    [140741783372544] = "Tổng Sát Thương: <HighLight>200%</> Tấn Công",
    [140741783382016] = "<img id=\"03\" width=\"40\" height=\"40\"/>Sát Thương: <HighLight>130%</>*Tấn Công",
    [140809429059072] = "Áp chế kẻ địch bằng các đòn chém cận chiến và sát thương phạm vi nhỏ.",
    [140809429059584] = "Chịu sát thương và dùng đòn phạm vi quanh người để kìm chân kẻ địch.",
    [140809429060096] = "Bùng nổ đơn mục tiêu, dùng Phi Bài tấn công mục tiêu then chốt.",
    [140809429060352] = "Gọi Mưa Bánh Quy ở cự ly trung bình, gây Sát Thương lên khu vực mục tiêu.",
    [140809429060608] = "Dùng Sát Thương đơn mục tiêu và Dấu Ấn Tử Linh làm suy yếu mục tiêu then chốt.",
    [140809429061888] = "Liên tục cắn xé mục tiêu hiện tại ở cự ly gần.",
    [140809429062144] = "Dùng rìu nặng gây sát thương diện rộng lên kẻ địch phía trước.",
    [140809429063168] = "Liên tục bắn Đạn Năng Lượng Mị Ảnh ở cự ly trung bình vào mục tiêu.",
    [140809429063424] = "Tấn công cận chiến nhiều hit và gây sát thương bùng nổ lên kẻ địch xung quanh.",
    [140809429063680] = "Ném Nấm Kỳ Diệu ở cự ly trung bình, Áp Chế kẻ địch trong khu vực mục tiêu.",
    [140809429064192] = "Dùng Thiết Bị Bánh Răng gây sát thương phạm vi và nhận Khiên.",
    [140809429067008] = "Theo định vị của kỹ năng con/biểu hiện vùng của Cường Hóa Dây Leo Tập Kích, đây là Sát Thương Khu Vực.",
    [140809429068032] = "Rải Mưa Bài, gây sát thương phạm vi lên khu vực mục tiêu.",
    [140809429068544] = "Liên tục dùng Kiếm Khí tấn công mục tiêu hiện tại.",
    [140809429068800] = "Chịu sát thương và dùng đòn đập tấn công kẻ địch xung quanh.",
    [140809429069824] = "Tấn công nhiều lần từ xa và Phán Quyết mục tiêu.",
    [140809429070336] = "Triệu hồi Dây Gai tại khu vực đông kẻ địch để gây sát thương liên tục.",
    [140809429070848] = "Dùng Phi Đạn và Oanh Kích Linh Giới tấn công kẻ địch trong phạm vi nhỏ quanh mục tiêu.",
    [140809429071616] = "Tới gần chiến trường ngâm Vịnh Thi Nửa Đêm, gây sát thương lên kẻ địch xung quanh.",
    [140809429072384] = "Dùng Súng Ngắn và Pháo Không Khí tấn công kẻ địch phía trước.",
    [140877343229440] = "Quái Vật: Cung cấp <HighLight>5%</> Máu cho toàn bộ đồng minh; 【Quái Vật】 nhận thêm Máu Tối Đa.",
    [140877343229952] = "Thiết Vệ: Cung cấp <HighLight>15</> Phòng Thủ cho toàn bộ đồng minh; 【Thiết Vệ】 nhận thêm Phòng Thủ.",
    [140877343230208] = "Thầy Bói: 【Thầy Bói】 nhận Khuếch Thương; tùy khoảng cách với mục tiêu còn nhận thêm Tăng Thương.",
    [140877343230720] = "Thợ Săn: 【Thợ Săn】 nhận thêm Tỷ Lệ Bạo Kích; khi trúng kẻ địch, áp Chảy Máu <HighLight>3</> giây, liên tục gây Sát Thương.",
    [140877343230976] = "Học Phái Bí Ẩn: Cả đội hồi Pháp Lực mỗi giây; khi 【Học Phái Bí Ẩn】 gây sát thương, nhận tăng Tốc Độ Đánh và Cường Hóa Kỹ Năng trong thời gian ngắn.",
    [140877343231232] = "Bàn Thạch: 【Bàn Thạch】 Khi Sinh Mệnh dưới <HighLight>60%</>, nhận Khiên dựa trên Sinh Mệnh Tối Đa và <HighLight>10</> giây Súc Thương.",
    [140877343231488] = "Hội Tarot: Mỗi <HighLight>1</> Quân Cờ Hội Tarot ra trận sẽ cung cấp một thuộc tính độc nhất cho toàn đội; Hội Tarot nhận thêm Buff.",
    [140877343232000] = "Nữ Thần Đêm Tối: Khi bắt đầu chiến đấu, quân cờ 【Nữ Thần Đêm Tối】 trên bàn tương ứng khi gây sát thương lên địch sẽ trực tiếp kết liễu nếu Máu mục tiêu thấp hơn ngưỡng. Mốc kích hoạt: (<HighLight>2</>)<HighLight>12%</> / (<HighLight>4</>)<HighLight>18%</> / (<HighLight>6</>)<HighLight>25%</>.",
    [140877343232256] = "Khi khai chiến, giảm Phòng Thủ toàn bộ địch dựa trên số người kích hoạt Liên Kết; mỗi vòng ngẫu nhiên nhận <HighLight>1</> quân cờ <HighLight>1</> sao từ các quân cờ địch đã bị hạ ở trận trước.",
    [140877343233024] = "Giáo Phái Sinh Mệnh: Khi quân cờ địch tử trận, quân cờ 【Giáo Phái Sinh Mệnh】 nhận Máu vĩnh viễn.",
    [140877343233280] = "Nhà Hàng Hải: Sau khi dùng kỹ năng nhận Tấn Công và Súc Thương trong <HighLight>4</> giây; kỹ năng hạ gục hồi <HighLight>20</> Pháp Lực.",
    [140877343233536] = "Giáo Phái Tử Vong: tích lũy nhận Trang Bị Tử Thần theo số tầng Liên Kết.",
    [140877343233792] = "Ở Giai Đoạn Chuẩn Bị, đồng minh trong <HighLight>1</> ô quanh tượng nhận tăng Giới Hạn Sinh Mệnh và Sát Thương; rời phạm vi lập tức mất hiệu lực. Sau khi chiến đấu bắt đầu, rời phạm vi vẫn duy trì <HighLight>45</> giây. Quân cờ 【Vùng Đất Bị Thần Ruồng Bỏ】 nhận thêm <HighLight>50%</> hiệu ứng hào quang; hiệu ứng cùng loại từ nhiều tượng không cộng dồn.",
    [140877343234048] = "Di Trạch Của Rồng: Sau <HighLight>8</> giây kể từ khi bắt đầu chiến đấu, Long Tức quét toàn bàn cờ, gây Sát Thương Chuẩn lên địch và tăng Tốc Đánh cho toàn bộ đồng minh đến hết trận.",
    [140877343234304] = "Sinh Vật Siêu Phàm: Quân Cờ 【Sinh Vật Siêu Phàm】 gây thêm Sát Thương; sau khi mỗi Sinh Vật Siêu Phàm tham gia <HighLight>4</> vòng đối chiến người chơi, nhận thêm Súc Thương.",
    [140877343235840] = "Quyến Tộc Rừng Sương: Quân cờ 【Quyến Tộc Rừng Sương】 mỗi lần Đánh Thường nhận <HighLight>1</> tầng 【Rêu Bóng Hấp Thu】; mỗi tầng tăng Hút Máu và Máu Tối Đa, tối đa <HighLight>6</> tầng. Khi có <HighLight>3</> quân, hiệu quả mỗi tầng tăng; sau mỗi trận PvP nhận <HighLight>1</> quân cờ Quyến Tộc Rừng Sương ngẫu nhiên.",
    [140877343236096] = "Khi Trissy xuất trận, lúc bắt đầu chiến đấu giảm <HighLight>2</> điểm hồi Mana của toàn bộ địch trong <HighLight>10</> giây.",
    [140877343236608] = "Mỗi khi <HighLight>1</> Quân Cờ địch tử trận, Abaddon nhận <HighLight>3%</> Tấn Công và <HighLight>3%</> Tốc Độ Đánh, cộng dồn tối đa <HighLight>5</> tầng.",
    [140877343237632] = "Khi Klein ra trận, dựa theo số Liên Kết đang kích hoạt để tăng Tấn Công và Khuếch Thương cho cả đội.",
    [140946331141632] = "Đồng minh +<HighLight>5%</> Máu; Quái Vật tăng thêm <HighLight>20%</> Máu Tối Đa.",
