    [140946331150848] = "【Nữ Thần Đêm Tối】 kết liễu mục tiêu địch có Máu dưới <HighLight>25%</>.",
    [140946331151104] = "Khi khai chiến, giảm <HighLight>10%</> Phòng Thủ của toàn bộ địch trong <HighLight>10</> giây; mỗi vòng ngẫu nhiên nhận <HighLight>1</> quân cờ <HighLight>1</> sao từ các quân cờ địch đã bị hạ ở trận trước.",
    [140946331151360] = "Khi khai chiến, giảm <HighLight>15%</> Phòng Thủ của toàn bộ địch trong <HighLight>15</> giây; mỗi vòng ngẫu nhiên nhận <HighLight>1</> quân cờ <HighLight>1</> sao từ các quân cờ địch đã bị hạ ở trận trước.",
    [140946331151616] = "Khi khai chiến, giảm <HighLight>30%</> Phòng Thủ của toàn bộ địch trong <HighLight>30</> giây; mỗi vòng ngẫu nhiên nhận <HighLight>1</> quân cờ <HighLight>1</> sao từ các quân cờ địch đã bị hạ ở trận trước.",
