    [140946331153408] = "Khi bắt đầu mỗi trận chiến với người chơi, hồi <HighLight>2</> Máu; sau khi thắng trận chiến người chơi, nhận <HighLight>50</> Điểm May Mắn.",
    [140946331153920] = "Mỗi khi <HighLight>1</> quân cờ địch tử trận, quân cờ 【Giáo Phái Sinh Mệnh】 vĩnh viễn nhận <HighLight>4</> Máu Tối Đa.",
    [140946331154176] = "Mỗi khi <HighLight>1</> quân cờ địch tử trận, quân cờ 【Giáo Phái Sinh Mệnh】 vĩnh viễn nhận <HighLight>8</> Máu Tối Đa.",
    [140946331154432] = "Mỗi khi <HighLight>1</> quân cờ địch tử trận, quân cờ 【Giáo Phái Sinh Mệnh】 vĩnh viễn nhận <HighLight>12</> Máu Tối Đa.",
    [140946331154688] = "Sau khi dùng kỹ năng, trong <HighLight>4</> giây nhận <HighLight>15%</> Tấn Công và <HighLight>5%</> Súc Thương; kỹ năng hạ gục hồi <HighLight>20</> Pháp Lực.",
    [140946331154944] = "Sau khi dùng kỹ năng, trong <HighLight>4</> giây nhận <HighLight>30%</> Tấn Công và <HighLight>10%</> Súc Thương; kỹ năng hạ gục hồi <HighLight>20</> Pháp Lực.",
    [140946331155968] = "Triệu hồi <HighLight>1</> Tượng Thần; đồng minh trong <HighLight>1</> ô quanh tượng tăng <HighLight>10%</> Giới Hạn Sinh Mệnh và <HighLight>8%</> Sát Thương; quân cờ 【Vùng Đất Bị Thần Ruồng Bỏ】 nhận thêm <HighLight>50%</> hiệu ứng. Giai Đoạn Chuẩn Bị rời phạm vi sẽ mất ngay; sau khi chiến đấu bắt đầu, rời phạm vi vẫn kéo dài <HighLight>45</> giây. Hiệu ứng cùng loại không cộng dồn.",
    [140946331156224] = "Triệu hồi <HighLight>2</> Tượng Thần; đồng minh trong <HighLight>1</> ô quanh tượng tăng <HighLight>18%</> Giới Hạn Sinh Mệnh và <HighLight>14%</> Sát Thương; quân cờ 【Vùng Đất Bị Thần Ruồng Bỏ】 nhận thêm <HighLight>50%</> hiệu ứng. Giai Đoạn Chuẩn Bị rời phạm vi sẽ mất ngay; sau khi chiến đấu bắt đầu, rời phạm vi vẫn kéo dài <HighLight>45</> giây. Hiệu ứng cùng loại không cộng dồn.",
    [140946331156480] = "Triệu hồi <HighLight>2</> Tượng Thần; đồng minh trong <HighLight>1</> ô quanh tượng tăng <HighLight>30%</> Giới Hạn Sinh Mệnh và <HighLight>22%</> Sát Thương; quân cờ 【Vùng Đất Bị Thần Ruồng Bỏ】 nhận thêm <HighLight>50%</> hiệu ứng. Giai Đoạn Chuẩn Bị rời phạm vi sẽ mất ngay; sau khi chiến đấu bắt đầu, rời phạm vi vẫn kéo dài <HighLight>45</> giây. Hiệu ứng cùng loại không cộng dồn.",
    [140946331156992] = "Sau <HighLight>8</> giây kể từ khi bắt đầu chiến đấu: gây <HighLight>200</> Sát Thương Chuẩn toàn màn, Tốc Đánh toàn đội +<HighLight>20%</>.",
    [140946331157248] = "Sau <HighLight>8</> giây kể từ khi bắt đầu chiến đấu: gây <HighLight>350</> Sát Thương Chuẩn toàn màn, Tốc Đánh toàn đội +<HighLight>30%</>.",
    [140946331157504] = "Sau <HighLight>8</> giây kể từ khi bắt đầu chiến đấu: gây <HighLight>500</> Sát Thương Chuẩn toàn màn, Tốc Đánh toàn đội +<HighLight>40%</>.",
    [140946331157760] = "Sau <HighLight>8</> giây kể từ khi bắt đầu chiến đấu: gây <HighLight>700</> Sát Thương Chuẩn toàn màn, Tốc Đánh toàn đội +<HighLight>50%</>.",
    [140946331158016] = "Sát Thương của Quân Cờ 【Sinh Vật Siêu Phàm】 tăng <HighLight>10%</>; sau khi tham chiến <HighLight>4</> vòng PvP người chơi, nhận thêm <HighLight>5%</> Súc Thương.",
    [140946331158272] = "Sát thương của quân cờ 【Sinh Vật Siêu Phàm】 tăng <HighLight>20%</>; sau khi tham chiến <HighLight>4</> vòng PvP người chơi, nhận thêm <HighLight>10%</> Súc Thương.",
    [140946331158528] = "Sát Thương của Quân Cờ 【Sinh Vật Siêu Phàm】 tăng <HighLight>30%</>; sau khi tham chiến <HighLight>4</> vòng PvP người chơi, nhận thêm <HighLight>15%</> Súc Thương.",
    [140946331158784] = "Sát Thương của Quân Cờ 【Sinh Vật Siêu Phàm】 tăng <HighLight>50%</>; sau khi tham chiến <HighLight>4</> vòng PvP người chơi, nhận thêm <HighLight>25%</> Súc Thương.",
    [140946331160320] = "Quân Cờ 【Quyến Tộc Rừng Sương】 mỗi lần Đánh Thường nhận <HighLight>1</> tầng 【Hấp Thu Rêu Bóng】; mỗi tầng nhận <HighLight>2%</> Hút Máu và <HighLight>1%</> Máu Tối Đa, cộng dồn tối đa <HighLight>6</> tầng.",
    [140946331160576] = "Quân cờ 【Quyến Tộc Rừng Sương】 mỗi lần Đánh Thường nhận <HighLight>1</> tầng 【Rêu Bóng Hấp Thu】; mỗi tầng tăng <HighLight>3%</> Hút Máu và <HighLight>2%</> Máu Tối Đa, tối đa <HighLight>6</> tầng. Sau mỗi trận PvP nhận <HighLight>1</> quân cờ Quyến Tộc Rừng Sương ngẫu nhiên.",
