    [141082964792832] = "Khi chiến đấu bắt đầu: Quân Cờ có đồng minh ở ô kề bên nhận 130 Khiên trong 8 giây. Khiên này có thể cộng dồn.",
    [141082964793344] = "Quân Cờ của bạn nhận 6% Súc Thương.",
    [141082964797696] = "Khi chiến đấu bắt đầu: Quân Cờ có đồng minh ở ô kề bên nhận 210 Khiên trong 8 giây. Khiên này có thể cộng dồn.",
    [141082964798208] = "Mỗi Quân Cờ phe mình, lần đầu Máu giảm xuống dưới 35%, sẽ hồi 22% Máu Tối Đa.",
    [141082964798720] = "Quân Cờ của bạn nhận 10% Súc Thương.",
    [141082964798976] = "Các quân cờ phe bạn đang mang 1 trang bị nhận 120 Máu và hồi 2 Mana mỗi giây.",
    [141082964799232] = "Quân cờ phe ta nhận 10% Tỷ Lệ Bạo Kích và 25% Sát Thương Bạo Kích.",
    [141082964800768] = "Quân cờ của bạn tăng 15% Tốc Độ Đánh và 15% Máu.",
    [141082964801024] = "Quân cờ của bạn tăng 15% Phòng Thủ và 15% Máu.",
    [141082964804608] = "Sau mỗi vòng PVP, ngẫu nhiên nhận 1 Quân Cờ từ Liên Kết có nhiều quân nhất trong đội hình ra trận.",
    [141082964805120] = "Khi chiến đấu bắt đầu, cứ mỗi 1 Quân Cờ ở hàng trước của phe ta, toàn đội nhận 30 Sinh Mệnh Tối Đa.",
    [141082964805376] = "Khi bắt đầu chiến đấu, quân cờ địch cứ mỗi 2 giây giảm 4 Phòng Thủ đến hết trận.",
    [141082964805632] = "Các quân cờ phe bạn đang mang 1 trang bị nhận 180 Máu và hồi 3 Mana mỗi giây.",
    [141082964805888] = "Quân cờ bắt đầu chiến đấu ở 2 hàng sau phe mình nhận 30% Khuếch Thương và mất 20% Sinh Mệnh hiện tại khi trận bắt đầu.",
    [141082964806144] = "Quân cờ phe mình không mang trang bị nhận 50 Phòng Thủ.",
    [141082964806400] = "Quân Cờ phe ta nhận 8 Phòng Thủ. Lần đầu Sinh Mệnh giảm xuống dưới 50%, nhận thêm 32 Phòng Thủ đến hết chiến đấu.",
    [141082964807680] = "Quân cờ phe ta mỗi 4 giây hồi 5% Máu Tối Đa.",
    [141082964807936] = "Mỗi vòng chiến đấu người chơi nhận thêm 2 EXP. Quân Cờ 5 phí của bạn nhận 12% Sinh Mệnh Tối Đa và 12% Tốc Độ Đánh.",
    [141082964808704] = "Nhận 3 Quân Cờ 3 Vàng ngẫu nhiên và 3 Vàng. Quân Cờ phe ta +5% Tốc Độ Đánh; Quân Cờ 3 Vàng của bạn nhận thêm 300 Sinh Mệnh Tối Đa và 25% Tốc Độ Đánh.",
    [141082964809984] = "Mỗi khi kích hoạt 1 Liên Kết khác nhau, quân cờ của bạn nhận 1.5% Tấn Công và 0.75% Khuếch Thương, tối đa tính 20 Liên Kết.",
    [141082964814336] = "Khi bắt đầu chiến đấu, quân cờ có đúng 1 đồng minh trong phạm vi 1 ô xung quanh nhận 15% Tốc Đánh và 15% Phòng Thủ.",
    [141082964814592] = "Khi bắt đầu chiến đấu, quân cờ có đúng 1 đồng minh trong phạm vi 1 ô xung quanh nhận 25% Tốc Đánh và 25% Phòng Thủ.",
    [141082964814848] = "Khi chiến đấu bắt đầu, càng nhiều đồng minh trong phạm vi 1 ô, Quân Cờ càng nhận nhiều Phòng Thủ: có 1/2/3+ đồng minh lần lượt nhận 8%/16%/24% Phòng Thủ.",
    [141082964815104] = "Cường hóa toàn đội theo số quân cờ 3 sao bạn sở hữu: có 1/2/3+ quân cờ 3 sao, toàn đội lần lượt nhận 5%/10%/15% Khuếch Thương.",
    [141082964815360] = "Tạo 1 Ô Liệt Diễm ở bên phải hàng sau phe ta. Khi chiến đấu bắt đầu, Quân Cờ đứng trong ô nhận 25% Tấn Công đến hết trận.",
    [141082964815616] = "Tạo 1 Ô Hàn Băng ở bên trái hàng sau phe ta. Khi chiến đấu bắt đầu, Quân Cờ đứng trong ô nhận 5 Hồi Pháp Lực đến hết trận.",
    [141082964815872] = "Tạo 1 Ô Thánh Huy ở giữa hàng trước phe ta. Khi chiến đấu bắt đầu, Quân Cờ đứng trong ô nhận 30% Phòng Thủ đến hết trận.",
    [141082964816128] = "Tạo 1 Ô Sinh Cơ Tự Nhiên ở bên trái hàng trước phe ta. Khi mỗi trận bắt đầu, Quân Cờ đứng trong ô vĩnh viễn nhận 30 Sinh Mệnh Tối Đa; mỗi trận tối đa kích hoạt 1 lần.",
    [141082964816384] = "Khi bắt đầu chiến đấu, quân cờ không mang trang bị nhận 15% Súc Thương trong 12 giây.",
    [141082964816640] = "Khi bắt đầu chiến đấu, quân cờ mang đúng 1 trang bị nhận 15 Tấn Công và 15 Phòng Thủ trong toàn trận.",
    [141082964817408] = "Khi bắt đầu chiến đấu, quân cờ mang đúng 2 trang bị nhận 15% Tốc Độ Đánh và 2 điểm Hồi Mana trong toàn trận.",
    [141082964817664] = "Khi bắt đầu chiến đấu, quân cờ mang 3 trang bị nhận 10% Khuếch Thương và 10% Súc Thương trong toàn trận.",
    [141082964817920] = "Khi quân cờ đã tham gia tổng cộng 4 trận PvP và hiện đang mang ít nhất 1 trang bị, vĩnh viễn nhận 12 Tấn Công và 12 Phòng Thủ. Mỗi quân cờ chỉ kích hoạt 1 lần.",
    [141082964818944] = "Lần đầu quân cờ mang 3 trang bị giảm xuống dưới 40% Sinh Mệnh: Vô Địch và Không Thể Chỉ Định trong 2 giây, hồi 20% Giới Hạn Sinh Mệnh. Mỗi trận tối đa 1 lần.",
    [141082964819200] = "Nhận 1 Cự Lang. Khi kẻ địch đầu tiên trong mỗi trận tử trận, toàn bộ Thợ Săn hồi 12% Sinh Mệnh Tối Đa.",
    [141082964819968] = "Nhận 1 Fors. Với mỗi Pháp Sư, sau 2 lần thi triển kỹ năng đầu tiên của mỗi trận, nhận 10% Tốc Độ Đánh và 8% Khuếch Thương trong 4 giây.",
    [141082964820224] = "Nhận 1 Kỵ Sĩ Cự Phủ. Khi bắt đầu chiến đấu, Thiết Vệ nhận Khiên bằng 12% Giới Hạn Sinh Mệnh; nếu ra trận 4 Thiết Vệ, Khiên tăng lên 20%, kéo dài 8 giây.",
    [141082964820480] = "Trong 10 giây sau khi bắt đầu chiến đấu, quân cờ phe mình mỗi giây nhận 2% Tấn Công; đủ 10 tầng nhận thêm 12% Khuếch Thương cho tới khi kết thúc trận.",
    [141082964820736] = "Khi bắt đầu chiến đấu, quân cờ không có đồng minh ở ô kề nhận Khiên bằng 20% Máu tối đa trong 10 giây.",
    [141082964820992] = "Quân cờ bắt đầu chiến đấu ở 2 hàng sau phe mình nhận 17% Khuếch Thương và mất 20% Sinh Mệnh hiện tại khi trận bắt đầu.",
    [141082964821248] = "Khi bắt đầu chiến đấu, quân cờ ở ô giữa hàng đầu phe mình nhận 15% Khuếch Thương và 25% Máu tối đa.",
    [141082964821504] = "Khi bắt đầu chiến đấu, quân cờ có đồng minh ở ô kề nhận Khiên 330 trong 8 giây. Khiên này có thể cộng dồn.",
    [141082964821760] = "Quân cờ phe mình không mang trang bị nhận 30 Phòng Thủ.",
    [141082964822016] = "Khi bắt đầu chiến đấu, quân cờ không có đồng minh ở ô kề nhận Khiên bằng 30% Máu tối đa trong 10 giây.",
    [141082964822272] = "Sau 12 giây kể từ khi bắt đầu chiến đấu, quân cờ phe bạn nhận 8% Tấn Công và 4% Khuếch Thương đến hết trận.",
    [141082964822528] = "Sau 12 giây kể từ khi bắt đầu chiến đấu, quân cờ phe bạn nhận 15% Tấn Công và 8% Khuếch Thương đến hết trận.",
    [141082964822784] = "Sau 12 giây kể từ khi bắt đầu chiến đấu, quân cờ phe bạn nhận 25% Tấn Công và 12% Khuếch Thương đến hết trận.",
    [141082964823040] = "Sau đòn đánh thường thứ 6 của mỗi quân cờ trong mỗi trận, nhận 12% Tốc Đánh và 6% Khuếch Thương đến hết trận.",
    [141082964823296] = "Sau Đánh Thường lần thứ 6 của mỗi quân cờ trong mỗi trận, nhận 20% Tốc Độ Đánh và 10% Khuếch Thương cho tới khi trận đấu kết thúc.",
    [141082964823552] = "Sau Đánh Thường lần thứ 6 của mỗi quân cờ trong mỗi trận, nhận 32% Tốc Độ Đánh và 15% Khuếch Thương cho tới khi trận đấu kết thúc.",
