    [211107843167232] = "Không thể tung Kỹ Năng.",
    [211107843168000] = "Không thể hành động hoặc dùng Kỹ Năng.",
    [211107843174656] = "Buff thuộc tính test dùng cho Phó Bản CBT2.",
    [211107843182592] = "Buff thuộc tính test dùng cho Phó Bản Open Beta.",
    [211107843203840] = "Tăng *d** Tấn Công và Tấn Công Đặc Biệt.",
    [211107843204352] = "Chiến đấu giằng co, thắng bại khó phân; Áp Chế Con Đường của toàn bộ người chơi tăng.",
    [211107843204864] = "Hồi Máu Liên Tục",
    [211107843205120] = "Mất Máu Liên Tục",
    [211107843205376] = "Chiến đấu giằng co, thắng bại khó phân; Áp Chế Con Đường của toàn bộ người chơi tăng thêm.",
    [211107843206144] = "Chiến đấu giằng co, thắng bại khó phân; Áp Chế Con Đường của toàn bộ người chơi tăng mạnh.",
    [211107843211008] = "Không Thể Được Trị Liệu",
    [211107843211264] = "Mỗi tầng giảm 10% sát thương phải chịu.",
    [211107843211776] = "Tăng 2% Áp Chế và Kháng Con Đường.",
    [211107843214592] = "Tăng 15% Áp Chế Con Đường trong 20 giây.",
    [211107843214848] = "Khiên Tiễn Tháp Siêu Cấp",
    [211107843215360] = "Trong khu vực quanh Hộ Vệ Huyễn Ảnh, hiệu quả Trị Liệu gây ra và nhận vào giảm 50%.",
    [211107843222784] = "Mỗi giây hồi *d Sinh Mệnh, kéo dài 60 giây.",
    [211107843223552] = "Tấn Công +*d, Cường Hóa Kỹ Năng +*d, kéo dài 1800 giây (dùng lại sẽ làm mới thời gian).",
    [211107843225856] = "Miễn Nhiễm Sát Thương",
    [211107843226112] = "Mỗi giây hồi *d Sinh Mệnh, kéo dài 30 giây.",
    [211107843229696] = "Kéo dài *d; chủ động dùng kỹ năng hoặc vật phẩm sẽ xóa",
    [211107843233280] = "Tấn Công +*d, Cường Hóa Kỹ Năng +*d, kéo dài 1800 giây (Dược thử dùng tại Sân Tập).",
    [211107843234304] = "Lấy lời thề làm củi, lấy ràng buộc làm lửa. Khi trong đội hoặc đoàn có thành viên cùng Gia Tộc, nhận tăng thuộc tính; số người càng nhiều, hiệu quả càng mạnh. Sau khi rời Gia Tộc, hiệu ứng có hồi chiêu 24 giờ.",
    [211107843234560] = "Không cùng huyết thống, nhưng lấy máu làm khế ước. Từ đây mạch sống tương liên, sống chết có nhau. Trong đội hoặc đoàn, nếu có 3~8 người thuộc cùng Gia Tộc, nhận thêm 1 lần hồi sinh; từ 9 người trở lên thuộc cùng Gia Tộc, nhận thêm 2 lần hồi sinh. Sau khi rời Gia Tộc, hiệu ứng có hồi chiêu 24 giờ.",
    [211107843235328] = "<Highlight>Chiến thắng của người tiên phong hóa thành hồi âm bất diệt trong Linh Giới, Bảo Hộ cho người đến sau.</>\nSau lần đầu thông Phó Bản, Phi Phàm Giả vào Phó Bản sẽ nhận buff thuộc tính.\nTuần 1 sau First Clear: Sinh Mệnh +500, Chuyên Công Quái Vật +100.\nTuần 2: Sinh Mệnh +1000, Chuyên Công Quái Vật +200.\nTuần 3: Sinh Mệnh +2000, Chuyên Công Quái Vật +400.",
    [211107843235584] = "Chiến thắng của người tiên phong hóa thành tiếng vọng bất diệt trong Linh Giới, Bảo Hộ người đến sau.\nSau khi vượt Phó Bản lần đầu, Phi Phàm Giả vào Phó Bản sẽ nhận buff thuộc tính.\nSinh Mệnh +500, Chuyên Công Quái Vật +100.",
    [211107843235840] = "Chiến thắng của người tiên phong hóa thành tiếng vọng bất diệt trong Linh Giới, Bảo Hộ người đến sau.\nSau khi vượt Phó Bản lần đầu, Phi Phàm Giả vào Phó Bản sẽ nhận buff thuộc tính.\nSinh Mệnh +1000, Chuyên Công Quái Vật +200.",
    [211107843236096] = "Chiến thắng của người tiên phong hóa thành tiếng vọng bất diệt trong Linh Giới, Bảo Hộ người đến sau.\nSau khi vượt Phó Bản lần đầu, Phi Phàm Giả vào Phó Bản sẽ nhận buff thuộc tính.\nSinh Mệnh +2000, Chuyên Công Quái Vật +400.",
    [211107843236352] = "<Highlight>Chiến thắng của người tiên phong hóa thành tiếng vọng bất diệt trong Linh Giới, Bảo Hộ những người đến sau.</>\nSau khi phó bản được vượt lần đầu, Phi Phàm Giả vào phó bản sẽ nhận tăng thuộc tính.",
    [211107843239680] = "Hiệu ứng Tê Liệt do sét đánh gây ra; không thể hành động hoặc dùng kỹ năng.",
    [211107843259904] = "Tăng 5% Áp Chế Công Trình và 2% Tốc Độ Di Chuyển.",
