    [211107843308032] = "Phá Phòng tăng *d",
    [211107843309056] = "Bạo Kích tăng *d, Kháng Bạo tăng *d.",
    [211107843309568] = "Kháng Khống Chế +*d, Kháng Tính Khống Chế +*d",
    [211107843309824] = "Chuyên Công Con Đường tăng *d, Chuyên Phòng Con Đường tăng *d",
    [211107843310336] = "Giới Hạn Sinh Mệnh +*d\nTấn Công Vật Lý Tối Thiểu +*d\nTấn Công Vật Lý Tối Đa +*d\nTấn Công Ma Pháp Tối Thiểu +*d\nTấn Công Ma Pháp Tối Đa +*d\nPhá Khiên +*d\nKhiên Khí +*d\nPhòng Thủ +*d\nPhá Phòng +*d\nTấn Công Nguyên Tố +*d\nTấn Công Nguyên Tố % +*.1f**\nBỏ Qua Nguyên Tố +*d\nKháng Nguyên Tố +*d\nCường Hóa Kỹ Năng +*d\nKháng Kỹ Năng +*d\nChính Xác +*d\nChặn Đòn +*d\nBạo Kích +*d\nKháng Bạo Kích\nSát Thương Bạo Kích\nKháng Sát Thương Bạo Kích\nTăng Sát Thương\nSúc Thương\nSát Thương Cuối\nGiảm Sát Thương Cuối\nCường Hoá Trị Liệu %",
    [211107843313664] = "Giới Hạn Sinh Mệnh +*d\nTấn Công Vật Lý Tối Thiểu +*d\nTấn Công Vật Lý Tối Đa +*d\nTấn Công Ma Pháp Tối Thiểu +*d\nTấn Công Ma Pháp Tối Đa +*d\nPhá Khiên +*d\nKhiên Khí +*d\nPhòng Thủ +*d\nPhá Phòng +*d\nTấn Công Nguyên Tố +*d\nTấn Công Nguyên Tố % +*.1f**\nBỏ Qua Nguyên Tố +*d\nKháng Nguyên Tố +*d\nCường Hóa Kỹ Năng +*d\nKháng Kỹ Năng +*d\nChính Xác +*d\nChặn Đòn +*d\nBạo Kích +*d\nKháng Bạo Kích +*d\nSát Thương Bạo Kích +*.1f**\nKháng Sát Thương Bạo Kích +*.1f**\nTăng Sát Thương +*.2f**\nSúc Thương +*.2f**\nSát Thương Cuối +*d\nGiảm Sát Thương Cuối +*d\nCường Hoá Trị Liệu % +*.2f**",
    [211107843318016] = "Mỗi tầng giảm Hồi Phục gây ra *f**.",
    [211107843318528] = "Sau khi đòn đánh trúng mục tiêu, sát thương mục tiêu nhận vào tăng 20% trong 10 giây; CD nội bộ 20 giây.",
    [211107843318784] = "Đại Cát: Thiên Mệnh Sở Quy\nTấn Công +*f**",
    [211107843319040] = "Cát: May Mắn Liên Tiếp\nTấn Công +*f**",
    [211107843319296] = "Tiểu Cát: Thuận Thủy Hành Chu\nTấn Công +*f**",
    [211107843320576] = "Khuy Bí: Hồi Chiêu Linh Thị giảm 30%.",
    [211107843321344] = "Được Chiến Sĩ Bảo Hộ, Phòng Thủ +*f**, Kháng Nguyên Tố +*f**.",
    [211107843338240] = "Xích Phong Ấn của lĩnh vực “Cửa” quấn quanh trái tim để chống sát thương chí mạng. Mỗi lần chịu đòn, lượng Máu mất không thể vượt 25% Máu Tối Đa.",
    [211107843338752] = "Bạn nhận được một phần Ám Thị của Con Đường “Khán Giả”: lượng Trị Liệu gây ra và nhận vào tăng 30%, nhưng trong tiềm thức bạn không muốn làm hại người khác, Bạo Kích giảm 10%.",
    [211107843339008] = "Bạn chạm tới tri thức cấm kỵ của “Học Phái Bí Ẩn”: sát thương gây ra tăng 40%, nhưng cơ thể trở nên mong manh như thủy tinh, Máu Tối Đa giảm 15%.",
    [211107843339264] = "Khi chịu sát thương chí mạng, hồi 50% Máu; chỉ kích hoạt 1 lần.",
    [211107843339776] = "Mỗi khi vào tầng mới, nhận thêm 12% sát thương và hiệu quả trị liệu; Máu tối đa giảm 5%.",
    [211107843341312] = "Lần đầu bạn tấn công một mục tiêu chưa từng giao chiến, Linh Giới sẽ đáp lại khát vọng của bạn, hồi 15% Máu.",
    [211107843342080] = "Trong chiến đấu, tiêu hao Thể Lực khi nhảy tăng gấp đôi; nhưng khi tiếp đất sau nhảy ba lần sẽ gây lượng lớn sát thương phạm vi lên kẻ địch xung quanh.",
    [211107843342336] = "Trong chiến đấu, mỗi 20 giây khi di chuyển, hai chân bạn tạm hiện đặc tính nóng rực của Con Đường “Ca Tụng Giả”; mặt đất đi qua để lại vùng Liệt Dương tròn tồn tại 10 giây.",
    [211107843342592] = "Mỗi tầng cho bạn 1 lần cơ hội dùng Thú Cưỡi trong chiến đấu, kéo dài 30 giây; khi cưỡi, va vào kẻ địch sẽ gây sát thương lớn.",
    [211107843342848] = "Mỗi tầng cho bạn 1 cơ hội biến thành Liệt Diễm trong chiến đấu, kéo dài 15 giây. Bản thân nhận 90% Giảm Thương và gây sát thương lớn lên kẻ địch bị thiêu; trong thời gian này không thể tấn công, nhảy hoặc né.",
    [211107843343360] = "Kẻ địch bị bạn lướt xuyên qua sẽ chịu sát thương và Giảm Tốc.",
    [211107843343616] = "Bạn ký khế ước bí mật với Linh Giới: mọi tiêu hao Thể Lực giảm 50%, như nhận được sự hỗ trợ vô hạn từ “Cửa”.",
    [211107843343872] = "Một cụm Sương Mù Xám tách ra từ Nguyên Bảo bao phủ bạn. Đơn vị bên ngoài Sương Mù Xám tấn công mục tiêu bên trong sẽ bị triệt tiêu 100% sát thương; đơn vị bên trong tấn công mục tiêu bên ngoài cũng bị triệt tiêu 100% sát thương.",
    [211107843347712] = "Giảm 90% sát thương phải chịu và gây sát thương lớn lên kẻ địch bị thiêu đốt; trong thời gian này không thể tấn công, nhảy hoặc né.",
    [211107843350784] = "Đòn đánh của bạn có 5% xác suất gây Nhiễm Ma Nữ Thống Khổ lên mục tiêu, liên tục gây sát thương trong 8 giây.",
    [211107843351040] = "Đòn đánh của bạn có 10% xác suất kích hoạt pháp thuật của Chiêm Tinh Sư, triệu hồi một thiên thạch tấn công và gây sát thương lên kẻ địch trong bán kính 4m quanh mục tiêu. Hiệu ứng này tối đa kích hoạt 1 lần mỗi 2 giây.",
    [211107843351296] = "Khi đòn tấn công trực tiếp của bạn gây Bạo Kích, Chúa Tể Bão Tố sẽ đáp lại lời cầu nguyện: một tia sét đánh trúng mục tiêu và gây thêm sát thương. Hiệu ứng này với cùng một mục tiêu tối đa kích hoạt 1 lần mỗi giây.",
    [211107843351552] = "Cảm giác Mất Kiểm Soát của Người Sói bao phủ bạn. Khi di chuyển trong chiến đấu, cứ mỗi 20 giây sẽ phát ra một tiếng tru mất kiểm soát, ngắt di chuyển và kỹ năng hiện tại, đồng thời gây sát thương lớn lên kẻ địch trong bán kính 10m.",
    [211107843352064] = "Nhặt được mê dược gây ngủ của Bang Liệp Long. Khi tấn công có 5% xác suất tạo Sương Độc tồn tại 12 giây; Tăng Thương của kẻ địch trong phạm vi giảm 20%. Hiệu ứng này tối đa kích hoạt 1 lần mỗi 5 giây.",
    [211107843352320] = "Bạn nhận Hình Thể Cự Nhân: kích thước tăng 100%; trong chiến đấu, mỗi 8 giây đẩy lùi mọi kẻ địch đến gần trong phạm vi 2 m.",
    [211107843352576] = "Bạn nhận được trợ giúp từ Linh Giới. Khi tấn công, Cự Thú Thông Linh có 10% xác suất hỗ trợ tấn công; hiệu ứng này mỗi 5 giây tối đa kích hoạt 1 lần.",
    [211107843352832] = "Bạn nhận được năng lực xuyên không gian. Trong chiến đấu, mỗi 15 giây sẽ chuyển sang một vị diện khác, giảm mạnh sát thương phải chịu trong 3 giây.",
    [211107843353088] = "Gây sát thương lên kẻ địch có Máu dưới 10% sẽ kích hoạt Phán Quyết Cuối Cùng theo Luật của Trọng Tài Nhân, lập tức Xử Quyết mục tiêu.",
    [211107843353344] = "Mẫu Thân ban phúc lành cùng cái giá: Máu tối đa +35%, Kháng Đẩy Lùi tăng mạnh; nhưng trong chiến đấu, khi đứng yên sẽ liên tục cộng tầng Giảm Tốc. Di chuyển hoặc thoát chiến sẽ dần xóa tầng Giảm Tốc.",
    [211107843353600] = "Học kỹ năng Giam Cầm Bí Ngẫu, cho phép Bí Ngẫu Hóa kẻ địch trong phạm vi lớn: Định Thân toàn bộ kẻ địch thường trong 40m; mỗi tầng chỉ dùng được 1 lần.",
    [211107843353856] = "Sau khi Bệnh Tật Quấn Thân lây nhiễm mục tiêu, Tấn Công và Phòng Thủ của mục tiêu giảm 20%.",
    [211107843354112] = "Khi bạn tấn công Quái Thường bị nhiễm, có 10% xác suất làm Choáng 1 giây.",
    [211107843355392] = "Sao Băng tiếp tục gây Cộng Hưởng Nguyên Tố, tạo thêm đòn tấn công phạm vi Nguyên Tố Băng và làm Choáng Quái Thường 1 giây.",
    [211107843356672] = "Sau khi Sét đánh trúng quái thường, có 20% xác suất gây Choáng 2 giây.",
    [211107843358720] = "Khi Cự Thú Thông Linh tấn công quái thường, có 50% xác suất gây Choáng 2 giây.",
    [211107843359744] = "Giúp đồng đội gánh 50% sát thương phải chịu; không hiệu lực khi Máu của bạn dưới 20%.",
    [211107843360000] = "Liên kết bản thân với đồng đội; khi chịu sát thương hoặc được Trị Liệu sẽ chia sẻ phần trăm Máu. Khi Máu của cả hai dưới 15%, liên kết đứt và mỗi người hồi 30% Máu; chỉ kích hoạt 1 lần.",
    [211107843360256] = "Đòn tấn công của bạn gắn Dấu Ánh Sáng lên mục tiêu. Khi tấn công đơn vị có Dấu Ánh Sáng, hồi Sinh Mệnh bằng 0.2% Sinh Mệnh Tối Đa của bản thân; hiệu ứng hồi tối đa kích hoạt 1 lần mỗi 0.5 giây.",
    [211107843360512] = "Bạn nhận được năng lực của Bậc “Trọng Tài Nhân”. Khi tấn công sẽ tạo một lĩnh vực; trong lĩnh vực, phe ta tăng Bạo Kích và Khuếch Thương gây lên địch, còn phe địch giảm Phòng Thủ và Chặn Đòn.",
    [211107843360768] = "Khi chịu đòn chí tử, Vô Địch 6 giây; đồng thời xuất hiện Con Rối bên cạnh. Sau 6 giây, Con Rối tự nổ khiến đồng minh tử vong; nếu Con Rối bị tiêu diệt trước, đồng minh hồi 70% Máu. Chỉ hiệu lực 1 lần.",
    [211107843364096] = "Khi tấn công mục tiêu có Ấn Ký Quang Minh, người tấn công hồi Máu bằng 0.2% Máu tối đa.",
    [211107843368192] = "Bạn nhận được một phần cảm nhận Vận Mệnh của Bậc 7 “Kẻ May Mắn” thuộc Con Đường “Quái Vật”, Xuyên Thấu +40%. Bạn có thể mơ hồ thấy trước quỹ đạo tiếp theo của kẻ địch, như thể định mệnh dẫn đường để đánh trúng mục tiêu.",
    [211107843368704] = "Bạn nhận một phần quyền năng phòng thủ của Bậc 5 “Người Thủ Hộ” thuộc Con Đường “Chiến Sĩ”, Chặn Đòn tăng 40%. Cơ thể bạn như bức tường đúc bằng thép.",
    [211107843369216] = "Bạn nhận được một phần năng lực điều khiển Hắc Diễm của Bậc 7 “Nữ Phù Thủy” thuộc Con Đường “Thích Khách”, Khuếch Thương +30%. Sức nóng và băng giá của vực sâu quấn quanh vũ khí, thiêu rụi mọi vật cản.",
    [211107843369984] = "Phúc Lành từ Kẻ Khờ: ngoài chiến đấu, mỗi 2 giây hồi 10% Sinh Mệnh.",
    [211107843370752] = "Mỗi tầng Thẩm Phán (Thẩm Phán Chính Nghĩa) tăng 5% sát thương cho Trừng Phạt và Vô Ám Thương của bản thân.",
    [211107843371008] = "Mục tiêu có Dị Giáo chịu Sát Thương từ Ca Tụng Giả tăng.",
    [211107843371264] = "Khi đạt 12 tầng, tự động tiến vào trạng thái Liệt Dương trong 4 giây.",
    [211107843371520] = "Bạn đã được tịnh hóa và rơi vào trạng thái Suy Yếu, Tấn Công giảm *f**.",
    [211107843372544] = "Năng lượng vô hạn; sát thương bản thân tăng 10%. Mỗi thêm 1 kẻ địch xung quanh, sát thương tăng thêm 10%, tối đa tăng 100%.",
    [211107843373312] = "*f** Giảm Thương",
    [211107843375360] = "Kháng Thương Chuẩn +*d điểm.",
    [211107843379456] = "Sát Thương Kỹ Năng Trừng Phạt tăng 20%.",
    [211107843381504] = "Mỗi tầng tăng 2% Tăng Thương, tối đa 10%.",
    [211107843381760] = "Tăng Sát Thương 15% trong 4 giây; sau đó mỗi 2 giây giảm 3%, tổng thời gian 8 giây.",
    [211107843382784] = "Tăng Thương - Vật +15%; tăng Bạo Kích và Xuyên Thấu.",
    [211107843384576] = "Tăng Máu Tối Đa; khi chịu sát thương sẽ phản kích kẻ địch.",
    [211107843385856] = "Sát thương Thánh Diễm tăng 200%. Thánh Diễm cộng hưởng với Nhật Thệ; khi dùng Thánh Diễm, tâm Nhật Thệ đồng thời thi triển 3 lần. Năng lực này thay Kỹ Năng Tịnh Quang bằng Thánh Diễm.",
    [211107843386368] = "Trong thời gian Thần Giáp, bản thân nhận 40% Khuếch Thương; sau khi thi triển kỹ năng, vào trạng thái Liệt Dương trong 6 giây. Thời lượng Liệt Dương có thể cộng dồn với trạng thái Liệt Dương từ hiệu ứng khác.",
    [211107843386624] = "Trong thời gian Thần Giáp, Máu Tối Đa của bản thân tăng 50%. Mỗi khi chịu sát thương, Phản Kích kẻ địch xung quanh; hiệu ứng này mỗi 0.2 giây tối đa kích hoạt một lần.",
    [211107843387392] = "Trục Nhật hoặc Trục Quang đầu tiên bạn dùng lên mục tiêu sẽ vĩnh viễn giảm 20% Máu và Tấn Công của mục tiêu.",
    [211107843388160] = "Thánh Diễm giảm 5% Tấn Công và Phòng Thủ của địch, cộng dồn tối đa 10 tầng. Năng lực này thay kỹ năng Tịnh Quang bằng Thánh Diễm.",
    [211107843388672] = "Tự động nhận 1 điểm Nhật Năng mỗi 2 giây.",
    [211107843388928] = "Số lần tích năng của Trục Nhật và Trục Quang +3; khi dùng Kỹ Năng này, hồi 15% Máu Tối Đa của bản thân.",
    [211107843390720] = "Sau khi dùng Phán Xét, lập tức nhận 5 Nhật Năng; 5 lần dùng Vô Ám Thương tiếp theo cũng lập tức nhận 5 Nhật Năng. Sát thương Vô Ám Thương tăng 40%.",
    [211107843391232] = "Hiệu quả Hồn Liệt Dương tăng 100%, Hồi Chiêu của hiệu ứng đổi thành 20 giây. (Khi nhận năng lực sẽ xóa trạng thái Linh Hồn Suy Yếu.)",
    [211107843391744] = "Hiệu quả Tăng Thương của Tịnh Quang tăng gấp 2. Trong thời gian Tịnh Quang, gây sát thương có 10% xác suất Tịnh Hóa mục tiêu, gây thêm sát thương bằng 5% giới hạn Máu của mục tiêu.",
    [211107843392000] = "Kỹ năng mới - Thanh Toán: Sau khi bật, Khuếch Thương +30% trong 10 giây và ghi lại tổng Sát Thương gây ra trong thời gian này. Khi hiệu ứng kết thúc, kẻ địch trong phạm vi chịu Sát Thương bằng 50% tổng Sát Thương đã ghi.",
    [211107843392256] = "Vô Ám Thương nhận thêm 5% Hút Máu; lượng hồi phục mỗi lần Hút Máu có giới hạn.",
    [211107843392512] = "Sau khi Tịnh Trảm gây sát thương, sát thương của Vô Ám Thương kế tiếp tăng 150%.",
    [211107843393024] = "Vô Ám Thương có thể kích hoạt Vô Ám lên quái ít Máu; khi kích hoạt Vô Ám, có 25% xác suất gây sát thương gấp 5 lần.",
    [211107843393280] = "Vô Ám Thương có thể kích hoạt Vô Ám lên quái vật ít Máu; trong trạng thái Liệt Dương, Tăng Thương của bản thân tăng 50%.",
    [211107843394816] = "Thần Phạt tại nút Lưỡi Đao Ánh Sáng có thể có hiệu lực lên quái vật và hiệu quả tăng 300%. Nếu chưa mở nút Thiên Phú Lưỡi Đao Ánh Sáng, năng lực này sẽ nhận thêm hiệu ứng “Thần Phạt” của nút đó.",
    [211107843395584] = "Số tầng Vô Tận cần để tiến vào trạng thái Liệt Dương tại nút Nhật Ca giảm từ 12 xuống 8.",
    [211107843395840] = "Khuếch Thương và Súc Thương +*f**.",
    [211107843396352] = "Vô Ám Thương có thể kích hoạt Vô Ám lên quái vật ít Sinh Mệnh; khi kích hoạt Vô Ám có 10% xác suất trực tiếp hạ mục tiêu.",
    [211107843396608] = "Choáng, không thể hành động hoặc dùng kỹ năng.",
    [211107843397120] = "Khuếch Thương +*f**.",
    [211107843397376] = "Súc Thương +*f**.",
    [211107843398400] = "Sát thương tăng 30%; tăng Bạo Kích và Xuyên Thấu.",
    [211107843400704] = "Liệt Dương:\n  - Liệt Trảm, Vô Ám Thương và Trừng Phạt được cường hóa\n  - Trong thời gian hiệu lực, hiệu suất nhận Năng Lượng tăng\n  - Trong thời gian hiệu lực, Tốc Chạy tăng",
    [211107843402240] = "Tăng Thương +*f**, Tấn Công và Cường Hóa Kỹ Năng tăng.",
    [211107843404544] = "Nhận *d Khiên, giảm *f** sát thương bản thân phải chịu; mỗi lần bị tấn công sẽ hồi Sinh Mệnh.",
    [211107843407616] = "Mỗi *d giây chịu *d điểm Sát Thương Ma Pháp.",
    [211107843407872] = "Nhận *f** Giảm Thương.",
    [211107843411200] = "Khi Khán Giả Hồi Phục cho bất kỳ mục tiêu nào, đồng thời Hồi Phục mục tiêu Đọc Tâm.",
    [211107843411712] = "Khi Khán Giả Hồi Phục cho bất kỳ mục tiêu nào, đồng thời Hồi Phục mục tiêu Dưỡng Tâm.",
    [211107843412736] = "Khiên bằng *f** Giới Hạn Sinh Mệnh.",
    [211107843412992] = "Tăng tốc *f**, buffdisc(*id)",
    [211107843413248] = "*f** Giảm Thương, đồng thời tăng Hồi Phục Nhận Vào *f**.",
    [211107843413760] = "Sau khi cộng đủ 3 tầng, tiến vào trạng thái Thôi Miên trong 1.5 giây.",
    [211107843416064] = "Hồi Chiêu của Linh Hoả giảm 5 giây, sát thương tăng 80%.",
    [211107843417600] = "Khi tấn công mục tiêu Thần Ôn, đòn Hiệp Đồng trở thành sát thương phạm vi và giá trị cơ bản sát thương Hiệp Đồng tăng 150%.",
    [211107843419648] = "Sau khi gây sát thương, có 40% xác suất tung Linh Hoả 3 lần; hiệu ứng này mỗi 10 giây tối đa kích hoạt một lần.",
    [211107843419904] = "Khi tạo Hồi Phục, gây một lần Sát Thương lên kẻ địch trong phạm vi lớn xung quanh; hiệu ứng này có hồi chiêu nội tại 2 giây.",
    [211107843421184] = "Phòng Thủ - *f**, liên tục chịu sát thương.",
    [211107843443200] = "Mỗi giây mất 1% Máu Tối Đa của người thi triển, tối đa không vượt quá 60% Công Kích của người thi triển.",
    [211107843445504] = "Tăng *f** Tăng Thương - Vật và *d điểm Xuyên Thấu cho bản thân.",
    [211107843446016] = "Khiên hấp thụ tối đa *d điểm Sát Thương",
    [211107843448320] = "Có thể giải một hiệu ứng Khống Chế; sau khi kích hoạt, Tốc Độ Di Chuyển của bản thân tăng 25% trong 2 giây.",
    [211107843449344] = "Đánh Thường có xác suất nhất định gắn Dấu Ngu Lộng lên mục tiêu; Tốc Độ Đánh tăng 30%.",
    [211107843449600] = "Sát Thương Đánh Thường tăng 40%, Tốc Đánh Đánh Thường tăng 20%.",
    [211107843449856] = "Sát Thương gây ra giảm *f**.",
    [211107843454464] = "Không thể hành động hoặc dùng Kỹ Năng.",
    [211107843457024] = "Sát thương Đạn Khí tăng 25%, chuyển thành Kỹ Năng Tích Năng và có 3 lần tích năng.",
    [211107843457280] = "Xào Bài làm mới hồi chiêu Đạn Khí; nếu Đạn Khí là kỹ năng tích năng, hồi đầy số tầng tích năng. Sát thương Đạn Khí tăng 50%.",
    [211107843457792] = "Mỗi phát Đạn Khí trúng đích kéo dài Ngu Phúc thêm 2 giây, tối đa 30 giây. Ngu Phúc nhận thêm 15% Tăng Thương và chỉ số Xuyên Thấu tăng 50%.",
    [211107843458816] = "Khi Mưa Bài trúng mục tiêu, triệu hồi Lá Tarot Khổng Lồ từ trên trời rơi xuống, gây lượng lớn sát thương phạm vi và tồn tại trên sân 1 phút. Cùng lúc tối đa tồn tại 3 lá.",
    [211107843459072] = "Khi sát thương bùng nổ của Trận Tarot trúng mục tiêu, triệu hồi Lá Tarot Khổng Lồ từ trên trời rơi xuống, gây lượng lớn sát thương phạm vi và tồn tại trên sân 1 phút. Cùng lúc tối đa tồn tại 3 lá.",
    [211107843459584] = "Mỗi khi tạo 1 Lá Tarot Khổng Lồ, nhận thêm 2 Lá Linh Tính. Sát thương Bộc Phát Linh Tính tăng 100%.",
    [211107843460352] = "Quỷ Bí Chi Cảnh liên tục kéo kẻ địch trong phạm vi về trung tâm; hồi chiêu giảm 20 giây, Sát Thương tăng 200%.",
    [211107843461376] = "Mỗi lần Trận Tarot gây sát thương sẽ kích hoạt thêm vụ nổ ruy-băng, gây sát thương phạm vi. Đòn cuối của Trận Tarot làm Choáng kẻ địch.",
    [211107843462144] = "Khi dùng Xào Bài, mỗi đòn trúng hồi Máu bằng 7.5% sát thương bản thân gây ra.",
    [211107843462656] = "Khiên hấp thụ tối đa *f điểm Sát Thương",
    [211107843463680] = "Sát thương của Đánh Dấu Ngu Lộng tăng 50%, cộng dồn tối đa 4 tầng.",
    [211107843466496] = "Trong 10 giây, Hỏa Diễm Dược tăng 400% sát thương; cộng dồn tối đa 3 tầng.",
    [211107843467264] = "Mưa Bài có 80% xác suất được dùng lại; hiệu ứng này không thể kích hoạt lần hai trong 2 giây. Khả năng gây Choáng của Mưa Bài được cường hóa.",
    [211107843467776] = "Tốc Độ Tấn Công Kỹ Năng +7%.",
    [211107843468288] = "Giảm Tốc 50%",
    [211107843470848] = "Phòng Ngự giảm 5% trong 5 giây, cộng dồn tối đa 3 tầng.",
    [211107843472128] = "Tăng Phá Phòng",
    [211107843473664] = "Tốc Độ Di Chuyển +*f**, Giảm Thương +*f**.",
    [211107843478784] = "Chịu 5 lần, mỗi lần *d điểm Sát Thương Ma Pháp.",
    [211107843481600] = "Bá Thể, Giảm Thương *f**.",
    [211107843482368] = "Tăng Hiệu Quả Giảm Thương",
    [211107843483648] = "Khi bản thân ở trong Không Ngục, tiến vào Hình Thái Linh Thể, Chặn Đòn tăng mạnh.",
    [211107843483904] = "Khi Thiểm Kích hoặc Tái Hiện Dấu Chân trúng, có 33% xác suất nhận Tăng Thương trong 3 giây, ở mức 10%; Tái Hiện Dấu Chân chuyển sang dạng tung xong rời tay.",
    [211107843484160] = "Khi nhận Dấu Chân, hồi 2% Máu của bản thân.",
    [211107843484416] = "Sát thương Trùng Môn tăng 120%.",
    [211107843484672] = "Khi tung Thán Vân, nhận hiệu ứng Giảm Thương kéo dài 5 giây, ở mức 35%.",
    [211107843485696] = "Trong thời gian Nghiên Tập, mỗi lần Tái Hiện Dấu Chân (theo số tầng) có thể giảm 1 giây Hồi Chiêu của Không Ngục.",
    [211107843485952] = "Khi Thiểm Kích trúng, có xác suất làm mới Hồi Chiêu của 1 Kỹ Năng ngẫu nhiên; Tái Hiện Dấu Chân chuyển sang dạng tung xong rời tay.",
    [211107843486464] = "Hồi chiêu kỹ năng chiến đấu của Học Đồ giảm 20%.",
    [211107843486720] = "Khi tiêu hao từ 5 điểm Năng Lượng Tinh Không để dùng Trùng Môn, hoàn lại 2 giây Hồi Chiêu và 2 điểm Năng Lượng Tinh Không.",
    [211107843486976] = "Xóa giới hạn số tầng Dấu Chân. Khi dùng kỹ năng chiến đấu để nhận Dấu Chân, nhận thêm 2 tầng Dấu Chân.",
    [211107843487232] = "Thiểm Kích và Tái Hiện Dấu Chân có 33% xác suất gây 666% sát thương. Khi Thiểm Kích trúng, nhận 1 tầng Dấu Chân; Tái Hiện Dấu Chân chuyển sang dạng tung xong rời tay và luôn tiêu hao 3 tầng Dấu Chân.",
    [211107843487744] = "Trong thời gian Nghiên Tập, tấn công mục tiêu trong Không Ngục sẽ gây Hiệp Đồng Công Kích; nếu dùng lại Không Ngục trong lúc Nghiên Tập sẽ mở rộng Lĩnh Vực và tăng số lần Hiệp Đồng Công Kích (tối đa 2 lần).",
    [211107843489024] = "Trong thời gian Du Hành, tốc độ hồi tất cả hồi chiêu kỹ năng tăng 100%; mỗi giây hồi 10% Máu.",
    [211107843489280] = "Hồi Chiêu của Xuyên Giới giảm 3 giây, sát thương tăng 100%.",
    [211107843490560] = "Biến Ảo nhận thêm 3 lần tích năng và sát thương tăng 60%.",
    [211107843490816] = "Tái Hiện Dấu Chân (theo số tầng) có thể giảm 1 giây Hồi Chiêu của Biến Ảo; sát thương Biến Ảo tăng 60%.",
    [211107843491328] = "Cánh Cửa Chồng Tầng sẽ kích nổ Ấn Ký Cộng Dồn trên mục tiêu để gây thêm sát thương; mỗi 1 lần kích nổ nhận 3 tầng Khắc Ấn Lữ Khách.",
    [211107843491584] = "Mỗi khi tiêu hao 1 tầng Dấu Chân, nhận 1 tầng Khắc Ấn Lữ Khách, cường hóa Đánh Thường gây thêm 100% Sát Thương lên mục tiêu có Sinh Mệnh trên 50%.",
    [211107843491840] = "Khi Học Đồ dùng kỹ năng Dịch Chuyển, vào dạng Linh Thể, tăng Tốc Chạy và nhận Khiên; khi Khiên biến mất sẽ thoát dạng Linh Thể.",
    [211107843492096] = "Biến Ảo cũng hưởng hiệu quả Tăng Thương của Ấn Ký Cộng Dồn; khi trúng mục tiêu sẽ cộng 3 tầng Ấn Ký Cộng Dồn.",
    [211107843492608] = "Dùng Cánh Cửa Chồng Tầng hạ mục tiêu sẽ nhận 10 tầng Khắc Ấn Lữ Khách; gây thêm 100% sát thương lên mục tiêu có Sinh Mệnh dưới 50%.",
    [211107843492864] = "Nhiệm vụ: Nhận 100 tầng Khắc Ấn Lữ Khách.\nPhần thưởng: Nhân đôi số tầng Khắc Ấn Lữ Khách của bạn và tiêu hao hiệu ứng này.",
    [211107843493120] = "Sau khi dùng Tinh Định, làm mới Hồi Chiêu các Kỹ Năng Bậc còn lại.",
    [211107843493376] = "Sau khi Khắc Ấn Lữ Khách vượt 300 tầng, định kỳ giáng sét lên mục tiêu trong phạm vi và thêm 1 tầng Ấn Ký Cộng Dồn.",
    [211107843495936] = "Mỗi tầng tăng *f** Sát Thương.",
    [211107843496192] = "Mỗi tầng tăng *f** Giảm Thương.",
    [211107843498752] = "Choáng, không thể hành động hoặc dùng kỹ năng.",
    [211107843504128] = "Mỗi giây chịu *d điểm Sát Thương Vật Lý do người áp hiệu ứng gây ra.",
    [211107843508992] = "Sát Thương nhận vào giảm *f**, Tốc Độ Di Chuyển +*f**.",
    [211107843511040] = "Khiên có thể hấp thụ *d điểm Sát Thương",
    [211107843511808] = "Nhận *f** Giảm Thương trong *d giây",
    [211107843514112] = "Sát Thương nhận vào giảm *f**.",
    [211107843517696] = "Nhận *d điểm Kháng Thương Chuẩn.",
    [211107843518976] = "Sát Thương nhận vào giảm *f**.",
    [211107843519744] = "Duy trì <Highlight>Bá Thể</>, Tốc Độ Di Chuyển giảm *f**.",
    [211107843520000] = "Mỗi tầng gây *f** Giảm Tốc; số tầng càng cao, hiệu quả Giảm Tốc càng mạnh.",
    [211107843521536] = "Hệ số Thù Hận bản thân +*d, Giảm Thương +*f**, Sinh Mệnh Tối Đa +*f**, Chuyên Phòng Quái Vật +*d, nhưng Sát Thương gây ra giảm *f**.",
    [211107843521792] = "Giảm Thương +*f**.",
    [211107843522048] = "Hệ Số Thù Hận bản thân +10, tăng Giảm Thương, Sinh Mệnh Tối Đa +25%, tăng Chuyên Phòng Quái Vật nhưng giảm Sát Thương gây ra. Càng nhiều người chơi địch ở gần, Giảm Thương bản thân càng tăng, đồng thời Sát Thương gây ra càng giảm.",
    [211107843527424] = "Khi Quang Bạo kích nổ Suy Bại trên mục tiêu, không còn xóa Suy Bại và gây thêm một lần Sát Thương kích nổ.",
    [211107843528704] = "Mỗi lần đòn thứ ba của Song Kiếm Trảm, Cự Trảm, Liệp Ma Trảm hoặc Mộ Sắc Trảm trúng địch, thời gian Suy Bại kéo dài thêm 12 giây; kẻ địch có Suy Bại giảm 15% Công Kích.",
    [211107843529984] = "Bạo Kích +864, Sát Thương Bạo Kích +95%, Kháng Bạo Kích +370. Trong thời gian Thấu Chi, mức tăng Bạo Kích và Kháng Bạo Kích được nhân đôi.",
    [211107843530496] = "Ở trạng thái Kiệt Sức, sát thương của mọi kỹ năng chiến đấu tăng 65%.",
    [211107843530752] = "Mỗi lần Bạo Kích cộng 1 tầng Cơn Thịnh Nộ Cự Nhân. Đủ 15 tầng, Cự Nhân xuất hiện gây sát thương diện rộng và xóa toàn bộ tầng.",
    [211107843531008] = "Đủ 15 tầng, Cự Nhân xuất hiện gây sát thương diện rộng và xóa toàn bộ tầng.",
    [211107843532032] = "Hồi chiêu Quang Bạo giảm 5 giây. Khi thiếu Ấn Ký, Quang Bạo vẫn nhận hiệu quả đầy Ấn nhưng sẽ Thấu Chi (mỗi thiếu 1 Ấn +3 giây, tối đa 20 giây, hồi chiêu 5 giây); trong thời gian Thấu Chi không thể nhận Ấn Ký và Hồi Phục nhận vào giảm.",
    [211107843532288] = "Không thể nhận Đánh Dấu Hoàng Hôn; hiệu quả Trị Liệu nhận vào giảm 20%.",
    [211107843532800] = "Mỗi lần Bạo Kích sẽ giảm 2 giây hồi chiêu của một kỹ năng đang hồi chiêu ngẫu nhiên; nếu lần Bạo Kích đó hạ gục kẻ địch, giảm thêm 1 giây.",
    [211107843533056] = "Mỗi khi Chiến Sĩ tiêu hao một Dấu Ấn Hoàng Hôn, hồi 2.5% Máu Tối Đa của bản thân.",
    [211107843533824] = "Khi dùng Quang Bạo, miễn nhiễm mọi sát thương trong 4 giây; hiệu ứng này trong 20 giây chỉ kích hoạt một lần.",
    [211107843534336] = "Hồi Chiêu của Lưỡi Đao Điêu Linh giảm 4 giây, sát thương tăng 530%.",
    [211107843534592] = "Đòn chém xuống của Quang Trảm tạo thêm một vùng bán kính 5m tại chỗ, tồn tại 5 giây; liên tục gây sát thương lên kẻ địch trong vùng và cho đồng minh 30% Giảm Thương.",
    [211107843535616] = "Quang Bạo tiêu hao đầy Ấn Ký sẽ không vào hồi chiêu.",
    [211107843537920] = "Cường hóa 2 lần thi triển tiếp theo của Quang Khúc, Tinh Sa hoặc Lao Lung Tinh Quang; cùng một kỹ năng chỉ có thể được cường hóa một lần.",
    [211107843544832] = "Hóa thành Tinh Quang, nhận *f** Giảm Thương.",
    [211107843545600] = "Giảm Tốc *f** và mỗi giây chịu *d điểm Sát Thương Ma Pháp.",
    [211107843546368] = "Dùng kỹ năng hoặc Đánh Thường có thể giảm thời gian hồi chiêu của kỹ năng đang hồi.",
    [211107843547392] = "Sát Thương nhận vào giảm *f**.",
    [211107843548416] = "Dựa trên trạng thái hồi chiêu của kỹ năng Giải Khống Chế của mục tiêu để kích hoạt hồi chiêu bổ sung.",
    [211107843555584] = "Khi Kỹ Năng Tinh Sa Cường Hóa kết thúc, triệu hồi gai nhọn gây sát thương phạm vi và làm Choáng kẻ địch trong phạm vi.",
    [211107843556096] = "Trí Nhân cường hóa 2 đòn đánh thường tiếp theo thành Thương Longinus; sát thương Thương Longinus tăng 50%.",
    [211107843556608] = "Kỳ Nguyệt cũng cường hóa đòn đánh thường kế tiếp thành Thương Longinus; sát thương Thương Longinus tăng 100%.",
    [211107843556864] = "Quang Khúc bắn thêm 1 Thương Longinus vào mục tiêu trúng đòn; nếu chỉ trúng 1 mục tiêu sẽ bắn 3 cây. Sát thương của Thương Longinus tăng 100%.",
    [211107843557120] = "Sau khi chủ động dùng Thương Longinus 3 lần, mở Khe Nứt Chân Lý; nếu chỉ trúng 1 mục tiêu, sát thương tăng 50%.",
    [211107843557888] = "Trong chiến đấu, cứ mỗi 2 giây sẽ có một Ngọn Giáo Longinus rơi xuống ngẫu nhiên kẻ địch xung quanh; mục tiêu trúng bị Giảm Tốc 50%.",
    [211107843560192] = "Mục tiêu trúng Quang Khúc bị giảm 15% Tăng Thương; sát thương của Quang Khúc tăng 150%.",
