    [272818201750784] = "Song Trọng Khiên",
    [272818201752576] = "Tư Thế Đỡ Đòn",
    [272818470127616] = "Xích Phong Ấn của lĩnh vực “Cửa” quấn quanh trái tim để chống sát thương chí mạng. Mỗi lần chịu đòn, lượng Máu mất không thể vượt 10% Máu Tối Đa.",
    [272818470127872] = "Khi Máu dưới 30%, sát thương phải chịu giảm 50%, Tốc Độ Di Chuyển bản thân giảm 25%.",
    [272818470128128] = "Bạn nhận một phần Ám Thị của Con Đường “Khán Giả”: Hồi Phục nhận vào +40%, nhưng trong tiềm thức không muốn làm hại người khác nên Hồi Phục và Sát Thương gây ra giảm 20%.",
    [272818470128384] = "Bạn chạm vào tri thức cấm kỵ của Kẻ Dòm Ngó Bí Ẩn: sát thương gây ra tăng 30%, nhưng Máu Tối Đa giảm 15%.",
    [272818470128640] = "Khi chịu sát thương chí mạng, bạn hồi 50% Máu và tiêu hao hiệu ứng này.",
    [272818470128896] = "Cho bạn Khiên bằng 20% Máu Tối Đa. Khiên này làm mới mỗi 30 giây.",
    [272818470129152] = "Mỗi khi vào tầng mới, nhận thêm 10% sát thương và hiệu quả trị liệu; Máu tối đa giảm 5%.",
    [272818470129408] = "Nhặt lá bài này sẽ lập tức tiêu hao nó và biến bạn thành một sinh vật vô hại / lập tức vào trạng thái Giả Chết trong 30 giây. Mọi kẻ địch không thể thêm bạn vào danh sách Thù Hận, nhưng bất kỳ chủ động tấn công nào của bạn sẽ xóa trạng thái này.",
    [272818470129664] = "Lần đầu bạn tấn công một mục tiêu chưa từng giao chiến, Linh Giới sẽ đáp lại khát vọng và hồi Sinh Mệnh theo một tỷ lệ nhất định của Sinh Mệnh Tối Đa.",
    [272818470130176] = "Khi liên tục di chuyển trong chiến đấu, mỗi giây hồi 2% Máu tối đa.",
    [272818470130432] = "Tiêu hao Thể Lực khi nhảy tăng gấp đôi, nhưng khi tiếp đất sau cú nhảy thứ ba sẽ gây sát thương diện rộng lớn lên kẻ địch xung quanh.",
    [272818470130944] = "Mỗi tầng cho bạn 1 lần cơ hội dùng Thú Cưỡi trong chiến đấu (không thể tích lũy cộng dồn), kéo dài 15 giây; khi cưỡi, va vào kẻ địch sẽ gây sát thương lớn.",
    [272818470131200] = "Mỗi tầng cho bạn 1 lần cơ hội biến thành Liệt Diễm trong chiến đấu, kéo dài 15 giây; gây sát thương lớn lên kẻ địch bị thiêu đốt. Trong thời gian này không thể Nhảy hoặc Né.",
    [272818470131712] = "Kẻ địch bị bạn lướt xuyên qua sẽ chịu sát thương và Giảm Tốc.",
    [272818470131968] = "Bạn ký khế ước bí mật với Linh Giới: mọi tiêu hao Thể Lực giảm 50%, như nhận được sự hỗ trợ vô hạn từ Con Đường “Cửa”.",
    [272818470132224] = "Một cụm Sương Mù Xám tách ra từ Nguyên Bảo bao phủ bạn. Đơn vị bên ngoài Sương Mù Xám tấn công mục tiêu bên trong sẽ bị triệt tiêu 100% sát thương; đơn vị bên trong tấn công mục tiêu bên ngoài cũng bị triệt tiêu 100% sát thương.",
    [272818470132480] = "Đòn đánh của bạn có xác suất gây Nhiễm Ma Nữ Thống Khổ lên mục tiêu, liên tục gây sát thương trong 8 giây.",
    [272818470132736] = "Đòn đánh của bạn có xác suất kích hoạt pháp thuật của Chiêm Tinh Sư, triệu hồi một thiên thạch tấn công và gây sát thương lên kẻ địch trong bán kính 3m quanh mục tiêu.",
    [272818470132992] = "Khi đòn tấn công trực tiếp của bạn Bạo Kích, Chúa Tể Bão Táp sẽ đáp lại lời cầu nguyện: một tia sét đánh trúng mục tiêu và gây Sát Thương.",
    [272818470133248] = "Cảm giác Mất Kiểm Soát của Người Sói bao phủ bạn. Trong chiến đấu, sau mỗi khoảng thời gian sẽ ngẫu nhiên phát ra tiếng tru mất kiểm soát, ngắt kỹ năng hiện tại và gây sát thương lớn lên kẻ địch trong bán kính 10m.",
    [272818470133760] = "Bạn nhặt được mê dược gây ngủ của Bang Liệp Long. Đòn đánh có xác suất tạo một vùng Sương Độc Gây Ngủ gần mục tiêu, tồn tại 12 giây. Kẻ địch trong vùng Sương Độc gây ít hơn 40% sát thương.",
    [272818470134016] = "Bạn nhận Hình Thể Cự Nhân: kích thước tăng 100%, và trong chiến đấu tự động đẩy lùi mọi kẻ địch đến gần trong phạm vi 1 m.",
    [272818470134528] = "Bạn nhận được năng lực xuyên không gian của Bậc “Cánh Cửa”. Trong chiến đấu, sau mỗi khoảng thời gian sẽ ngẫu nhiên chuyển sang một vị diện khác, giảm 99% sát thương phải chịu trong 3 giây.",
    [272818470134784] = "Gây sát thương lên kẻ địch có Máu dưới 10% sẽ kích hoạt Phán Quyết Cuối Cùng theo Luật của Trọng Tài Nhân, lập tức Xử Quyết mục tiêu.",
    [272818470135040] = "Mẹ ban phúc lành kèm cái giá: Máu Tối Đa tăng 50%, Kháng Hất Lùi tăng mạnh; nhưng khi đứng yên sẽ liên tục cộng dồn Buff Giảm Tốc, còn khi di chuyển các tầng Giảm Tốc sẽ giảm dần.",
    [272818470135296] = "Học kỹ năng Giam Cầm Bí Ngẫu, cho phép Bí Ngẫu Hóa kẻ địch trong phạm vi lớn: vĩnh viễn Định Thân toàn bộ kẻ địch trong 40 yard; mỗi tầng chỉ dùng được 1 lần.",
    [272818470136064] = "Khi Thiểm Kích trúng, có 33% xác suất nhận trong 3 giây hiệu ứng Tăng Thương 5%; Tái Hiện Dấu Chân chuyển sang dạng tung xong rời tay.",
    [272818470136320] = "Khi nhận Dấu Chân, hồi 3% Máu của bản thân.",
    [272818470136576] = "Sát thương Trùng Môn tăng 30%.",
    [272818470136832] = "Khi dùng Thán Vân, nhận 80% Giảm Thương trong 3 giây.",
    [272818470138624] = "Hồi Chiêu của mọi Kỹ Năng giảm 3 giây.",
    [272818470139136] = "Bỏ giới hạn số tầng Dấu Chân. Khi dùng kỹ năng Con Đường, có 66.6% xác suất nhận thêm 2 tầng Dấu Chân; Tái Hiện Dấu Chân cố định tiêu hao 3 tầng Dấu Chân.",
    [272818470139392] = "Thiểm Kích và Tái Hiện Dấu Chân có 20% xác suất gây 2000% sát thương; khi trúng nhận 1 tầng Dấu Chân. Tái Hiện Dấu Chân chuyển sang dạng tung xong rời tay.",
    [272818470139904] = "Trong thời gian Nghiên Tập, tấn công mục tiêu trong Không Ngục sẽ gây Hiệp Đồng Trảm Kích; nếu dùng lại Không Ngục trong lúc Nghiên Tập, số lần Hiệp Đồng Trảm Kích tăng (tối đa tăng 3 lần).",
    [272818470140160] = "Lao Tù Không Gian liên tục bám theo bản thân, sát thương tăng lên 1000%.",
    [272818470141184] = "Trong thời gian Du Hành Tàng Hình, tốc độ hồi tất cả hồi chiêu kỹ năng tăng 100%; mỗi giây hồi 10% Máu.",
    [272818470142976] = "Tái Hiện Dấu Chân (theo số tầng) có thể giảm 1 giây Hồi Chiêu của Biến Ảo.",
    [272818470143488] = "Cánh Cửa Chồng Tầng sẽ kích nổ Ấn Ký Cộng Dồn trên mục tiêu để gây thêm sát thương; mỗi 1 lần kích nổ nhận 3 tầng Minh Khắc Kẻ Du Hành.",
    [272818470143744] = "Mỗi khi tiêu hao 1 tầng Dấu Chân, nhận 1 tầng Khắc Ấn Kẻ Lãng Du, cường hóa Đánh Thường gây thêm 100% Sát Thương lên mục tiêu có Sinh Mệnh trên 50%.",
    [272818470144256] = "Biến Ảo cũng hưởng hiệu quả Tăng Thương của Ấn Ký Cộng Dồn; khi trúng mục tiêu sẽ cộng 1 tầng Ấn Ký Cộng Dồn.",
    [272818470144768] = "Dùng Cánh Cửa Chồng Tầng hạ mục tiêu sẽ nhận 10 tầng Minh Khắc Kẻ Du Hành; gây thêm 100% sát thương lên mục tiêu có Sinh Mệnh dưới 50%.",
    [272818470145280] = "Tinh Định xóa combo đòn hai; sau khi dùng sẽ làm mới Hồi Chiêu các Kỹ Năng còn lại.",
    [272818470145536] = "Sau khi Minh Khắc Kẻ Du Hành vượt 200 tầng, định kỳ giáng sét lên mục tiêu trong phạm vi và thêm 1 tầng Ấn Ký Cộng Dồn.",
    [272818470146048] = "Trong phạm vi Nhật Thệ, khi Trừng Phạt trúng mục tiêu sẽ kích hoạt thêm 1 lần Thiêu Đốt; Thiêu Đốt bỏ giới hạn tối đa của mức tăng sát thương và tăng biên độ cộng dồn sát thương lên 75%.",
    [272818470146304] = "Sát thương Thánh Diễm tăng 200%. Thánh Diễm cộng hưởng với Nhật Thệ; khi dùng Thánh Diễm, tâm Nhật Thệ đồng thời thi triển 3 lần. Năng lực này thay Kỹ Năng Tịnh Quang bằng Thánh Diễm.",
    [272818470146560] = "Mỗi lần bạn gây sát thương có 50% xác suất triệu hồi Liệt Dương Pháo, gây thêm sát thương bằng 50% Giới Hạn Sinh Mệnh của bạn lên mục tiêu. Với cùng một mục tiêu, hiệu ứng này tối đa kích hoạt 1 lần mỗi 2 giây.",
    [272818470146816] = "Trong thời gian Thần Giáp, bản thân nhận 40% Khuếch Thương; sau khi thi triển kỹ năng, vào trạng thái Liệt Dương trong 6 giây. Thời lượng Liệt Dương có thể cộng dồn với trạng thái Liệt Dương từ hiệu ứng khác.",
    [272818470147072] = "Trong thời gian Thần Giáp, Máu Tối Đa của bản thân tăng 50%. Mỗi khi chịu sát thương, Phản Kích kẻ địch xung quanh; hiệu ứng này mỗi 0.2 giây tối đa kích hoạt một lần.",
    [272818470147584] = "Khi thi triển Nhật Thệ, gây thêm 1 lần Choáng lên mục tiêu trong phạm vi, kéo dài 4 giây.",
    [272818470147840] = "Trục Nhật/Trục Quang đầu tiên bạn dùng lên mục tiêu sẽ vĩnh viễn giảm 20% Máu và Tấn Công của mục tiêu.",
    [272818470148608] = "Thánh Diễm giảm 5% Tấn Công và Phòng Thủ của địch, cộng dồn tối đa 10 tầng. Năng lực này thay kỹ năng Tịnh Quang bằng Thánh Diễm.",
    [272818470149120] = "Trong chiến đấu, tự động nhận 1 điểm Nhật Năng mỗi 2 giây.",
    [272818470151168] = "Sau khi dùng Phán Xét, chặn 60% Sát Thương kẻ địch gây lên bạn. Khi trạng thái Liệt Dương lần này kết thúc, nếu toàn bộ kẻ địch đã gây Sát Thương lên bạn vẫn còn sống, bạn sẽ chịu một lần toàn bộ Sát Thương đã bị chặn.",
    [272818470151680] = "Khi có 5 điểm Nhật Năng, Khuếch Thương tăng 20% trong 10 giây; khi có 0 điểm Nhật Năng, Súc Thương tăng 20% trong 10 giây.",
    [272818470151936] = "Hiệu quả Tịnh Quang tăng gấp 2. Trong thời gian Tịnh Quang, khi gây sát thương có 10% xác suất Tịnh Hóa mục tiêu, gây thêm sát thương bằng 5% Giới Hạn Sinh Mệnh của mục tiêu.",
    [272818470152192] = "Kỹ năng mới - Thanh Toán: Sau khi bật, Khuếch Thương +30% trong 10 giây và ghi lại tổng Sát Thương gây ra. Khi hiệu ứng kết thúc, gây một lần Sát Thương bằng đúng tổng Sát Thương đã ghi.",
    [272818470152960] = "Tịnh Trảm nhận thêm 3 lần tích năng, sát thương tăng 100%.",
    [272818470153216] = "Khi Vô Ám Thương kích hoạt Vô Ám lên mục tiêu Máu thấp, có 25% xác suất gây sát thương gấp 5 lần.",
    [272818470153472] = "Trong trạng thái Liệt Dương, Vô Ám Thương chắc chắn kích hoạt Vô Ám lên kẻ địch; khi Vô Ám kích hoạt, mức tăng giá trị sát thương cơ bản tăng lên 50%.",
    [272818470153728] = "Cuồng Phủ có 35% xác suất gây Choáng mục tiêu 1 lần, kéo dài 3 giây.",
    [272818470154240] = "Hồi Chiêu của Cuồng Phủ giảm 4 giây, sát thương tăng 100%.",
    [272818470154496] = "Vô Ám Thương vẫn ném Tiểu Thương vào mục tiêu Dị Giáo gần đó ngay cả khi không ở trạng thái Phán Xét; sát thương Tiểu Thương tăng 100%.",
    [272818470154752] = "Trong trạng thái Liệt Dương, Khuếch Thương và Súc Thương của bản thân tăng 20%.",
    [272818470155776] = "Số tầng Vô Tận cần để vào trạng thái Liệt Dương tại nút Nhật Ca giảm từ 12 xuống 7. Nếu chưa mở nút Thiên Phú Nhật Ca, năng lực này sẽ nhận thêm hiệu ứng của nút đó.",
    [272818470157824] = "Kẻ địch trúng Quang Khúc nhận một tầng 【Đánh Dấu Chiết Xạ】, khiến Sát Thương Khúc Xạ phải chịu tăng 5%; cộng dồn tối đa 10 tầng.",
    [272818470159360] = "Khi Kỹ Năng Tinh Sa Cường Hóa kết thúc, triệu hồi gai nhọn gây sát thương phạm vi.",
    [272818470159616] = "Sau khi dùng Quang Khúc, hồi 30% Máu Tối Đa của bản thân.",
    [272818470160896] = "Quang Khúc sẽ bắn thêm một Ngọn Giáo Longinus vào mục tiêu trúng đòn; nếu chỉ trúng 1 mục tiêu sẽ bắn 3 ngọn.",
    [272818470161408] = "Xào Bài làm mới Hồi Chiêu Đạn Khí; nếu Đạn Khí là Kỹ Năng Tích Năng thì hồi đầy số lần tích năng.",
    [272818470161920] = "Mỗi phát Đạn Khí trúng đích kéo dài Ngu Phúc thêm 2 giây, tối đa 30 giây. Tăng Thương của Ngu Phúc tăng 15%, chỉ số Xuyên Thấu tăng 1.5 lần.",
    [272818470162688] = "Khi Mưa Bài trúng mục tiêu, triệu hồi Lá Tarot Khổng Lồ từ trên trời rơi xuống, gây lượng lớn sát thương phạm vi và tồn tại trên sân 2 phút. Cùng lúc tối đa tồn tại 3 lá.",
    [272818470162944] = "Khi sát thương bùng nổ của Trận Tarot trúng mục tiêu, triệu hồi Lá Tarot Khổng Lồ từ trên trời rơi xuống, gây lượng lớn sát thương phạm vi và tồn tại trên sân 2 phút. Cùng lúc tối đa tồn tại 3 lá.",
    [272818470163968] = "Khi Đạn Khí tấn công mục tiêu, tạo vụ nổ phạm vi 6m tại vị trí mục tiêu, tăng phạm vi sát thương của Xào Bài.",
    [272818470164224] = "Quỷ Bí Chi Cảnh liên tục kéo kẻ địch trong phạm vi về trung tâm; hồi chiêu giảm 50%.",
    [272818470164480] = "Khi dùng Ngu Phúc sẽ tung dải ruy-băng gây sát thương phạm vi, đồng thời giảm 25% Tấn Công của kẻ địch trúng đòn.",
    [272818470165504] = "Khi dùng Xào Bài, hồi Máu bằng 7.5% sát thương bản thân gây ra.",
    [272818470165760] = "Khi dùng Ngu Phúc, nhận Khiên bằng 20% Máu Tối Đa trong 10 giây.",
    [272818470166272] = "Khi Quang Bạo kích nổ Suy Bại trên mục tiêu, không còn xóa Suy Bại và gây thêm một lần Sát Thương kích nổ.",
    [272818470167040] = "Mỗi lần đòn thứ ba của Song Kiếm Trảm, Cự Trảm, Liệp Ma Trảm hoặc Mộ Sắc Trảm trúng địch, thời gian Suy Bại kéo dài thêm 12 giây; kẻ địch có Suy Bại giảm 15% Công Kích.",
    [272818470167552] = "Khi mục tiêu mang Suy Bại chết, gây một lần Sát Thương phạm vi; nếu kẻ địch trúng đòn cũng đang mang Suy Bại, dựa theo thời gian Suy Bại còn lại để tăng thêm Sát Thương Nhận Vào.",
    [272818470167808] = "Bạo Kích +864, Sát Thương Bạo Kích +95%, Kháng Bạo Kích +370. Trong trạng thái Thấu Chi, mức tăng Bạo Kích và Kháng Bạo Kích được nhân đôi.",
    [272818470168064] = "Trong trạng thái Thấu Chi, sát thương của toàn bộ kỹ năng tăng 65%.",
    [272818470168320] = "Mỗi lần Bạo Kích cộng 1 tầng Cơn Thịnh Nộ Cự Nhân. Đủ 15 tầng, Cự Nhân xuất hiện gây sát thương diện rộng và xóa toàn bộ tầng.",
    [272818470168576] = "Khi Máu dưới 50%, nhận 30% Giảm Thương; trong thời gian hiệu quả Trị Liệu nhận vào bị giảm, Giảm Thương này luôn duy trì và không bị giới hạn bởi lượng Máu hiện tại.",
    [272818470168832] = "Hồi chiêu Quang Bạo -5 giây. Khi thiếu Ấn Ký, Quang Bạo vẫn nhận hiệu quả đầy Ấn nhưng sẽ Thấu Chi (mỗi thiếu 1 Ấn +3 giây, tối đa 20 giây, hồi chiêu 5 giây); trong thời gian Thấu Chi không thể nhận Ấn Ký, Hồi Phục nhận vào giảm.",
    [272818470169088] = "Mỗi lần Bạo Kích giảm 2 giây hồi chiêu của một kỹ năng đang hồi ngẫu nhiên; nếu lần Bạo Kích đó hạ gục kẻ địch, giảm thêm 1 giây.",
    [272818470169344] = "Mỗi khi tiêu hao một Đánh Dấu, hồi 2.5% Máu Tối Đa.",
    [272818470170112] = "Hồi Chiêu của Lưỡi Đao Điêu Linh giảm 4 giây, sát thương tăng 540%.",
    [272818470170368] = "Đòn chém xuống của Quang Trảm tạo thêm một vùng bán kính 5m tại chỗ, tồn tại 5 giây; Trường Hấp Dẫn liên tục gây sát thương lên kẻ địch trong vùng và cho đồng minh Giảm Thương.",
    [272818470171392] = "Hiệu quả Tăng Thương Động Sát tăng thêm 20%. Nếu chưa mở nút Thiên Phú Người Đứng Ngoài, năng lực này còn nhận thêm hiệu ứng của nút đó.",
    [272818470171648] = "Trong Tư Thế Ác Mộng, khi gây sát thương, lượng hồi phục của bản thân tăng 100%.",
    [272818470171904] = "Hồi Chiêu của Long Tức giảm 5 giây, sát thương tăng 80%.",
    [272818470172416] = "Sát thương của Động Sát, Thần Ôn, Chấn Nhiếp và Dệt Mộng tăng 40%.",
    [272818470172672] = "Khi Chấn Nhiếp trúng mục tiêu đang có Ôn Dịch Tinh Thần, khiến mục tiêu Hôn Mê 3 giây và giảm 5 giây hồi chiêu của Chấn Nhiếp.",
    [272818470172928] = "Hiệu quả Súc Thương của Thao Túng Ý Thức tăng lên 60%.",
    [272818470173184] = "Dệt Mộng nhận thêm 1 lần tích năng, sát thương tăng 100%, đồng thời tối đa tồn tại 3 Dệt Mộng.",
    [272818470173440] = "Khi Khán Giả tấn công mục tiêu Thần Ôn, đòn Hiệp Đồng trở thành sát thương phạm vi và giá trị cơ bản sát thương Hiệp Đồng tăng 150%.",
    [272818470173696] = "Khi Khán Giả dùng kỹ năng nghề nghiệp ở Tư Thế Ác Mộng, cũng sẽ tự động kích hoạt Trị Liệu Tâm Lý.",
    [272818470173952] = "Khi Kỹ Năng Bậc gây sát thương lên mục tiêu, làm mới thời gian duy trì của Tăng Thương Động Sát và tăng hiệu quả Tăng Thương thêm 20%.",
    [272818470174208] = "Thần Ôn giờ cũng có thể áp hiệu ứng Tăng Thương Động Sát lên mục tiêu; Tăng Thương tăng 20%.",
    [272818470174464] = "Dệt Mộng mỗi 3 giây kéo quái thường quanh pháp trận về gần và Giảm Tốc 70% trong 3 giây.",
    [272818470174720] = "Tâm Dệt Mộng phát Xung Kích Ý Thức ra ngoài; mỗi lần trúng kẻ địch giảm 0.1 giây Hồi Chiêu của Dệt Mộng.",
    [272818470174976] = "Nhận kỹ năng Nhiếp Tâm: giảm Phòng Thủ và gây sát thương lên tối đa 6 mục tiêu trong 6 giây. Gây Định Thân lên quái thường nằm trong Dệt Mộng hoặc đang chịu Thần Ôn.",
    [272818470175232] = "Khiển Thức liên tục gây sát thương lên kẻ địch xung quanh và không còn cần duy trì dẫn phép.",
    [272818470175488] = "Sau khi gây sát thương, có 40% xác suất tung Long Tức 3 lần; hiệu ứng này mỗi 10 giây tối đa kích hoạt một lần.",
    [272818470175744] = "Khi Khán Giả tạo Hồi Phục, gây một lần Sát Thương lên kẻ địch trong phạm vi lớn xung quanh; hiệu ứng này có hồi chiêu nội tại 2 giây.",
    [272818470176000] = "Hiệu ứng Tái Sinh Mộng Cảnh (Tự Hồi Sinh) đổi thành: khi chịu đòn chí mạng, hồi Sinh Mệnh bản thân lên 30% và nhận 70% Súc Thương trong 3 giây. Hồi chiêu 45 giây.",
    [272818470176256] = "Chấn Nhiếp được thêm hiệu ứng Kết Liễu: khi Máu mục tiêu dưới 30%, giá trị Sát Thương cơ bản tăng 400%, đồng thời có 15% xác suất trực tiếp hạ mục tiêu.",
    [272818470176512] = "Khi Trận Tarot gây Sát Thương, gắn 1 tầng Dấu Ngu Lộng lên mục tiêu.",
    [272818470176768] = "Khi Dấu Ấn Ngu Lộng phát nổ, bản thân nhận 1 tầng Vận Mệnh. Vận Mệnh tăng 50% sát thương Dấu Ấn Ngu Lộng, tối đa 4 tầng. Nếu đã chọn Nổ Ngu Lộng, hiệu ứng cũng tăng sát thương phạm vi của Nổ Ngu Lộng.",
    [272818470177024] = "Mỗi đòn của Xào Bài gây thêm sát thương lên mục tiêu địch; sát thương liên quan tới số tầng hiệu ứng Vận Mệnh.",
    [272818470177280] = "Mỗi lần dùng kỹ năng tăng 7% Tốc Độ Đánh Kỹ Năng, tối đa cộng dồn 5 tầng.",
    [272818470178048] = "Sau khi dùng Hỏa Diễm Khiêu Dược, giảm 4 giây hồi chiêu Quỷ Bí Chi Cảnh; Sát Thương của kẻ địch trong Quỷ Bí Chi Cảnh giảm 20%.",
    [272818470178816] = "Sau khi dùng Nhảy Lửa, nhận hiệu ứng “Hỏa Diệu”: Trong 10 giây, kỹ năng Nhảy Lửa có thể tăng 400% sát thương, cộng dồn tối đa 3 tầng.",
    [272818470179328] = "Hồi chiêu của Hỏa Diễm Dược giảm 18 giây; có thể dùng lên mục tiêu đang khóa và không còn lần 2.",
    [272818470179840] = "Hồi chiêu Thế Thân giảm 10 giây và hồi 10% Máu bản thân. Khi thi triển gây sát thương phạm vi và Giảm Tốc kẻ địch trúng đòn.",
    [272818470180608] = "Khi dùng Xào Bài, hồi 25% Máu Tối Đa của bản thân.",
    [272818470182400] = "Mắt Chân Lý sẽ xuất hiện dưới chân mục tiêu bị Quang Khúc trúng.",
    [272818470184448] = "Khi bắt đầu và kết thúc Hoàng Y, phát Sóng Chân Lý từ bản thân và gây sát thương; Hồi Chiêu của Hoàng Y giảm 8 giây.",
    [272818470184704] = "Ván Cờ Tuế Nguyệt giảm thêm 3 giây Hồi Chiêu Kỹ Năng.",
    [272818470185216] = "Kẻ địch trúng Nhãn Dòm Bí giảm 20% Tấn Công; sát thương Nhãn Dòm Bí tăng 100%.",
    [272818470185472] = "Sau khi dùng Quang Khúc, hồi 10% Máu Tối Đa của bản thân.",
    [272818470185728] = "Ván Cờ Tuế Nguyệt sẽ hút kẻ địch trong phạm vi về phía nó; sát thương Ván Cờ Tuế Nguyệt tăng 100%.",
    [272818470185984] = "Trong trạng thái chiến đấu, mỗi giây hồi 20 điểm Tri Thức Thần Bí; sát thương của Tin Tuyến tăng 50%.",
    [272818470186240] = "Sau khi dùng Áo Mới của Hoàng Đế, nhận thêm Khiên và hồi 10% Máu Tối Đa.",
    [272818470186496] = "Sau khi dùng Ván Cờ Tuế Nguyệt, bản thân nhận 25% Giảm Thương trong 8 giây; sát thương Ván Cờ Tuế Nguyệt tăng 250%.",
    [272818470187264] = "Bạn nhận được một phần năng lực cảm nhận vận mệnh sau khi thăng cấp từ Bậc 7 “Kẻ May Mắn” của Con Đường “Quái Vật”, tăng *d điểm Chính Xác. Dòng sông vận mệnh trải ra trước mắt; bạn lờ mờ nhìn thấy quỹ tích bước tiếp theo của kẻ địch, đánh trúng mục tiêu chuẩn xác như thể đã được định sẵn.",
    [272818470187776] = "Bạn nhận được một phần quyền năng phòng thủ của Bậc 5 “Người Thủ Hộ” thuộc Con Đường “Chiến Sĩ”, Chặn Đòn tăng *d điểm. Cơ thể bạn như bức tường đúc bằng thép.",
    [272818470188288] = "Bạn nhận được một phần năng lực điều khiển Hắc Diễm của Bậc 7 “Nữ Phù Thủy” thuộc Con Đường “Ma Nữ”, Khuếch Thương +30%. Sức nóng và băng giá của vực sâu quấn quanh vũ khí, thiêu rụi mọi vật cản.",
    [272818470189824] = "Sát thương khi Anh Hùng xuất hiện tăng 100%.",
    [272818470190336] = "Khi va trúng kẻ địch, gây Chảy Máu liên tục, cộng dồn tối đa 5 tầng.",
    [272818470190848] = "Khi cưỡi, sát thương gây ra khi va trúng kẻ địch tăng 100%.",
    [272818470191104] = "Sau khi Bệnh Tật Quấn Thân lây nhiễm mục tiêu, Tấn Công và Phòng Thủ của mục tiêu giảm 20%.",
    [272818470191360] = "Khi bạn tấn công quái thường bị Nhiễm, có 10% xác suất gây Choáng 1.5 giây.",
    [272818470191616] = "Khi gây sát thương lên mục tiêu bị nhiễm, có 20% xác suất gây thêm sát thương bằng 1% Máu tối đa của mục tiêu.",
    [272818470192128] = "Sát thương của đòn tấn công Lưu Tinh tăng 100%.",
    [272818470193408] = "Khi sét đánh xuống sẽ tạo một vụ nổ phạm vi, gây sát thương lên mục tiêu xung quanh.",
    [272818470193664] = "Sét gây sát thương bằng 1% Máu tối đa của mục tiêu.",
    [272818470194944] = "Khi Gầm, hồi 8% Máu Tối Đa của bản thân.",
    [272818470195712] = "Mỗi đòn tấn công của Cự Thú Thông Linh hồi cho bạn 2% Máu Tối Đa.",
    [272818470196480] = "Khi tấn công kẻ địch có Máu dưới 40%, gây thêm sát thương bằng 0.5% Máu Tối Đa của mục tiêu.",
    [272818470196736] = "Sau khi Kết Liễu mục tiêu, hồi Sinh Mệnh bằng 5% Sinh Mệnh Tối Đa của bản thân.",
    [272818470196992] = "Giúp đồng đội gánh 40% sát thương phải chịu; không hiệu lực khi Máu của bạn dưới 20%.",
    [272818470197248] = "Liên kết bản thân với đồng đội, chia sẻ tỷ lệ phần trăm Máu. Khi Máu của cả hai xuống dưới 15%, liên kết bị ngắt và mỗi người hồi 30% Máu; chỉ kích hoạt 1 lần.",
    [272818470197504] = "Đòn tấn công của bạn gắn Dấu Ánh Sáng lên mục tiêu. Khi tấn công đơn vị có Dấu Ánh Sáng, hồi Sinh Mệnh bằng 0.3% Sinh Mệnh Tối Đa của bản thân; hiệu ứng hồi tối đa kích hoạt 1 lần mỗi 0.5 giây.",
    [272818470197760] = "Bạn nhận được năng lực của Bậc “Trọng Tài Nhân”. Khi tấn công sẽ tạo một lĩnh vực; trong lĩnh vực, phe ta tăng Bạo Kích và Khuếch Thương, còn phe địch giảm Phòng Thủ và Chặn Đòn.",
    [272818470198016] = "Khi chịu đòn chí tử, Vô Địch 6 giây và sát thương gây ra giảm 30%; đồng thời xuất hiện một Con Rối bên cạnh. Sau 6 giây Con Rối tự nổ giết đồng minh; nếu Con Rối bị hạ sớm, hồi cho bạn 70% Máu. Chỉ kích hoạt 1 lần.",
    [272818470198272] = "Khi tấn công, tạo Trái Ác Quỷ quanh bản thân; sau 3 giây tự nổ, gây Sát Thương lên đồng minh. Chủ động giẫm lên Trái Ác Quỷ sẽ kích nổ, gây Sát Thương lên kẻ địch gần đó và cường hóa đồng minh.",
    [272818470198784] = "Phúc lành từ Kẻ Khờ, liên tục hồi Máu khi ngoài chiến đấu.",
    [272819006998016] = "Linh Tính",
    [272819007006464] = "Bậc",
    [273369299682816] = "Hãy chứng kiến kỳ tích Ngài Kẻ Khờ trình diễn tại Utopia! Sau khi mua, lập tức nhận thêm 1 lần hồi sinh.",
    [273369299683328] = "Ma Dược thần bí đến từ phía trên Sương Xám, có thể hồi 50% Sinh Mệnh Tối Đa trong Nhà Hát Utopia. Sau khi mua, hãy vào tab 【Túi Lối Chơi】 trong túi đồ để xem và sử dụng; khuyến nghị trang bị vào phím tắt.",
    [277077735516416] = "Dối Trá",
    [277077735556096] = "(Dùng chung cho nhân vật) Bị động suy giảm Kháng Khống Chế.",
    [277077735559424] = "Khán Giả · Bậc 9 — Thiên Phú Sát Thương phiên bản affix Roguelike.",
    [277077735559936] = "Cắt Bài",
    [277078272380160] = "Khi Máu lớn hơn 70%, Công Kích tăng 7%.",
    [277078272380416] = "Sau khi Kỹ Năng Bậc trúng mục tiêu, sát thương tăng 2% trong 6 giây, cộng dồn tối đa 3 tầng. Hồi chiêu 25 giây.",
    [277078272392192] = "Mỗi 5 giây nhận 1 tầng Nợ, tối đa 4 tầng. Tiêu hao toàn bộ Nợ để gây sát thương lên mục tiêu; số tầng Nợ tiêu hao càng nhiều, sát thương càng cao.",
    [277078272402432] = "Khi gây sát thương có xác suất nhỏ gây thêm sát thương (Khán Giả ở hình thái Trị Liệu sẽ hồi thêm Máu).",
    [277078272419584] = "Trân Phẩm - Người Thủ Hộ - Đồng đội tăng Kháng Kỹ.",
    [277078272423168] = "Độc Trân - Kẻ Kỳ Vọng - Sau khi vào chiến đấu, Bạo Kích tăng dần.",
    [277078272423680] = "Trân Phẩm Độc Nhất - Khoảnh Khắc Gặp Gỡ: Khi bị tấn công, tăng Kháng Con Đường.",
    [277078272429568] = "Lượng trị liệu của Trị Liệu Tâm Lý tăng 10%. Khi Trị Liệu Tâm Lý khả dụng, dùng Kỹ Năng Bậc có hiệu ứng trị liệu sẽ tự động thi triển Trị Liệu Tâm Lý.",
    [277078272430592] = "Khi Trị Liệu Tâm Lý khả dụng, ở Tư Thế Ác Mộng dùng Kỹ Năng Bậc sẽ tự động thi triển Trị Liệu Tâm Lý — Roguelike.",
    [277078272430848] = "Buff bị động thường trực của Thầy Bói (Cường hóa Đánh Thường từ Quỷ Thuật Giá Tiếp, Tăng Thương từ Bộc Phát Linh Tính, Mở Bài mỗi 4 lần cho 1 lá bài).",
    [277078272431104] = "Sát Thương Đánh Thường tăng 20%, Tốc Đánh tăng 20%.",
    [277078272431616] = "Mỗi 45 giây nhận Cảnh Báo Linh Tính, có thể giải 1 hiệu ứng khống chế; sau khi kích hoạt, Tốc Độ Di Chuyển tăng 25% trong 2 giây.",
    [277078540816128] = "<Yellow>Nguyền Rủa Trăng Tròn</>: Khi chịu sát thương từ địch trong <Yellow>8</>m, kích hoạt Thâm Hồng Nguyệt Miện, tăng Giảm Thương của người mang <Yellow>*f**</>. Duy trì Nguyền Rủa Trăng Tròn lên tối đa <Yellow>3</> mục tiêu địch không phải Boss trong <Yellow>8</>m đã tấn công mình, khiến Tăng Thương của chúng giảm <Yellow>*f**</>; hiệu quả Thâm Hồng Nguyệt Miện kéo dài <Yellow>5</> giây, mỗi <Yellow>10</> giây tối đa kích hoạt <Yellow>1</> lần.\n<Yellow>Pháp Thuật Hắc Ám</>: Khi gây sát thương cho mục tiêu địch, nhận Vuốt Hủ Thực trong <Yellow>5</> giây: Tăng Thương tăng <Yellow>*f**</>, đồng thời giảm Tốc Độ Di Chuyển của đơn vị địch chịu sát thương <Yellow>*f**</> trong <Yellow>4</> giây (mỗi mục tiêu chỉ có hiệu lực 1 lần). Mỗi <Yellow>10</> giây tối đa kích hoạt <Yellow>1</> lần.",
    [277078540816384] = "<Red>Đông Cứng Máu</>: Sau khi vào chiến đấu, máu của người trang bị dần lạnh đi, giảm Tốc Độ Hồi Thể Lực cho tới khi hoàn toàn không thể hồi. Liên tục gây Sát Thương có thể làm nhẹ hoặc loại bỏ hiệu ứng này.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 2 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu trong 15 giây.",
    [277078540816640] = "<Yellow>Dòm Ngó Minh Giới</>: Người mang nhận kỹ năng <Yellow>Mặt Nạ Hoàng Hôn</>: Đeo mặt nạ, chìm vào ranh giới giữa hiện thực và Minh Giới. Dưới kích thích của tiếng thét bất tận, cường hóa toàn bộ kỹ năng chiến đấu, tăng Tốc Độ Đánh của chúng <Yellow>{CheckStar(Type=\"sealed\",ID=2085018)=1?36%}{CheckStar(Type=\"sealed\",ID=2085018)=2?45%}{CheckStar(Type=\"sealed\",ID=2085018)=3?54%}</>, mỗi giây hoàn lại <Yellow>{CheckStar(Type=\"sealed\",ID=2085018)=1?0.24 giây}{CheckStar(Type=\"sealed\",ID=2085018)=2?0.28 giây}{CheckStar(Type=\"sealed\",ID=2085018)=3?0.32 giây}</> hồi chiêu. Người mang chịu đựng được <Yellow>20 giây</>; nếu trong thời gian này hạ gục hoặc hỗ trợ, thời gian chịu đựng kéo dài thêm <Yellow>5 giây</>, tối đa kích hoạt kéo dài <Yellow>2 lần</>.\nHồi chiêu kỹ năng: 60 giây.",
    [277078540816896] = "<Red>Suy Nhược Tiếng Thét</>: Khi người mang rời kích thích tiếng thét mà vẫn đang chiến đấu, tiến vào Suy Nhược: Tấn Công -5%, Tốc Độ Di Chuyển -15%. Chỉ thoát khi rời chiến đấu hoặc đeo mặt nạ lại.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 1 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu.",
    [277078540817152] = "<Yellow>Chăn Thả Linh Hồn</>: Sau khi người trang bị liên tục tấn công mục tiêu chính một thời gian, có thể tách linh hồn của mục tiêu xuống dưới chân mình. Chạm vào linh hồn trong <Yellow>10 giây</> để nuốt nó, tạo hiệu ứng khác nhau tùy loại chủ nhân linh hồn:\nNuốt linh hồn Phi Phàm Giả: Gây <Yellow>{CheckStar(Type=\"sealed\",ID=2085019)=1?*d}{CheckStar(Type=\"sealed\",ID=2085019)=2?*d}{CheckStar(Type=\"sealed\",ID=2085019)=3?*d}</> Sát Thương lên mục tiêu, đồng thời giam giữ linh hồn để nhận 1 kỹ năng của Bậc tương ứng. Dùng kỹ năng đó sẽ giải phóng linh hồn:\n    Bậc “Chiến Sĩ”: <Yellow>Khải Giáp Bình Minh</>;\n    Bậc “Ca Tụng Giả”: <Yellow>Nhật Thệ</>;\n    Bậc “Học Đồ”: <Yellow>Thán Vân</>;\n    Bậc “Khán Giả”: <Yellow>Ám Thị</>;\n    Bậc “Thầy Bói”: <Yellow>Bí Cảnh</>;\n    Bậc “Kẻ Dòm Ngó Bí Ẩn”: <Yellow>Lao Lung Tinh Quang</>;\nKhi Cơn Đói Ngọ Nguậy tăng cấp độ nguy hiểm, cường độ kỹ năng tương ứng cũng tăng.\nNuốt linh hồn quái vật: Lập tức nghiền nát linh hồn, gây <Yellow>{CheckStar(Type=\"sealed\",ID=2085019)=1?*d}{CheckStar(Type=\"sealed\",ID=2085019)=2?*d}{CheckStar(Type=\"sealed\",ID=2085019)=3?*d}</> Sát Thương lên mục tiêu và <Yellow>5</> quái vật xung quanh, đồng thời áp <Yellow>Áp Chế Linh Hồn</> trong <Yellow>5 giây</> lên mục tiêu: buffdisc(*id)\nHiệu ứng Tách Linh Hồn tối đa kích hoạt 1 lần mỗi 20 giây. Trước khi linh hồn bị giam được giải phóng, không thể tiếp tục tách linh hồn khỏi chủ nhân đó. Có thể đồng thời giam tối đa <Yellow>{CheckStar(Type=\"sealed\",ID=2085019)=1?3}{CheckStar(Type=\"sealed\",ID=2085019)=2?4}{CheckStar(Type=\"sealed\",ID=2085019)=3?5}</> linh hồn.",
    [277078540817408] = "<Red>Gánh Nặng Linh Hồn</>: Mỗi linh hồn Phi Phàm Giả bị giam giữ khiến Giới Hạn Sinh Mệnh của người trang bị giảm *f** trong thời gian giam giữ.\n<Red>Tham Thực Huyết Nhục</>: Sau khi người trang bị nghiền nát linh hồn quái vật, Giảm Thương giảm *f** trong 10 giây.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 1 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu.",
    [277078540817664] = "<Yellow>Trăng Tròn</>: Cường hóa kỹ năng chiến đấu của bản thân và đồng đội, tăng cấp của chúng <Yellow>{CheckStar(Type=\"sealed\",ID=2085020)=1?+1}{CheckStar(Type=\"sealed\",ID=2085020)=2?+2}{CheckStar(Type=\"sealed\",ID=2085020)=3?+3}</>; hiệu ứng có thể cộng dồn;\n<Yellow>Cánh Cửa Triệu Hồi</>: Cường hóa Bí Ngẫu, tăng Sát Thương và hiệu quả Hồi Phục từ kỹ năng Bí Ngẫu thêm <Yellow>{CheckStar(Type=\"sealed\",ID=2085020)=1?50%}{CheckStar(Type=\"sealed\",ID=2085020)=2?60%}{CheckStar(Type=\"sealed\",ID=2085020)=3?70%}</>. Khi kỹ năng Bí Ngẫu đang hồi chiêu, dùng Đánh Thường hoặc kỹ năng chiến đấu lên mục tiêu có xác suất cưỡng chế triệu hồi Bí Ngẫu và thi triển 1 lần kỹ năng Bí Ngẫu. Trong mỗi chu kỳ hồi chiêu của kỹ năng Bí Ngẫu, hiệu ứng cưỡng chế triệu hồi tối đa kích hoạt <Yellow>1</> lần.",
    [277078540817920] = "<Red>Chứng Khát Máu</>: Cái giá của cưỡng chế triệu hồi Bí Ngẫu: nhẫn sẽ nuốt 5% Giới Hạn Sinh Mệnh của bản thân.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 1 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu.",
    [277078540818176] = "Sau khi trang bị quá 60 giây, Thần Đèn thức tỉnh khỏi ngủ say và bắt đầu đáp lại nguyện vọng của người mang theo cách hiểu của mình:\n<Yellow>Thanh Xuân Vĩnh Trú</>: Khi dùng kỹ năng Giải Khống, nếu Sinh Mệnh dưới <Yellow>50%</>, Thần Đèn sẽ thỏa mãn “nguyện vọng”, cho bạn Thanh Xuân Vĩnh Trú: trong <Yellow>30</> giây buffdisc(*id)\n<Yellow>Đồng Tâm Chi Viện</>: Khi dùng Kỹ Năng Kết Liễu, nếu trong <Yellow>30</>m có ít nhất 1 đồng đội, Thần Đèn sẽ thỏa mãn “nguyện vọng”, cho bạn Đồng Tâm Chi Viện: trong <Yellow>30</> giây buffdisc(*id)\n<Yellow>Bối Thủy Nhất Kích</>: Khi mọi kỹ năng trừ Giải Khống và Kết Liễu đều đang hồi chiêu, nếu trong <Yellow>30</>m không có đồng đội, Thần Đèn sẽ thỏa mãn “nguyện vọng”, cho bạn Bối Thủy Nhất Kích: trong <Yellow>30</> giây buffdisc(*id)\nMọi nguyện vọng đều kích hoạt hồi chiêu 60 giây; Đồng Tâm Chi Viện và Bối Thủy Nhất Kích dùng chung hồi chiêu.",
    [277078540818432] = "Đèn Thần không hề hào phóng vô tư; khi điều ước thành hiện thực, hắn cũng sẽ lấy đi cái giá tương ứng:\n<Red>Tuổi Xuân Chợt Tàn</>: Khi Trẻ Mãi Không Già kết thúc, trừ *f** Sinh Mệnh còn lại.\n<Red>Tình Nghĩa Thấu Chi</>: Kỹ năng thường được Đồng Tâm Chi Viện hoàn trả hồi chiêu, khi lại bước vào hồi chiêu sẽ phát sinh thêm 3 giây hồi chiêu.\n<Red>Sức Cùng Lực Kiệt</>: Trong 30 giây sau khi Bối Thủy Nhất Kích kết thúc, buffdisc(*id)\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 2 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu trong 15 giây.",
    [277078540818688] = "<Yellow>Vương Miện Olmir</>: Thay kỹ năng Giải Khống của người mang bằng <Yellow>Chứng Nhận Vinh Quang</> mạnh hơn:\nGiải trừ khống chế trên bản thân, vào trạng thái <Yellow>Lao Lung Quang Mang</> trong 4 giây; trong thời gian này nhận <Yellow>Bá Thể</> và <Yellow>50%</> Giảm Thương. Với mỗi lần chịu sát thương, phần không vượt quá 10% Giới Hạn Sinh Mệnh sẽ được phản lại kẻ tấn công theo hệ số <Yellow>{CheckStar(Type=\"sealed\",ID=2085010)=1?0.6}{CheckStar(Type=\"sealed\",ID=2085010)=2?0.75}{CheckStar(Type=\"sealed\",ID=2085010)=3?0.9}</> (với mục tiêu ngoài 8m, sát thương phản lại suy giảm thêm, tối đa giảm còn 20% so với trong 8m). Khi <Yellow>Lao Lung Quang Mang</> kết thúc, gây <Yellow>{CheckStar(Type=\"sealed\",ID=2085010)=1?*d}{CheckStar(Type=\"sealed\",ID=2085010)=2?*d}{CheckStar(Type=\"sealed\",ID=2085010)=3?*d}</> sát thương cho tối đa 6 mục tiêu địch trong 8m quanh người, đồng thời gây <Yellow>Chói Mắt</> trong <Yellow>10</> giây, khiến Tấn Công của chúng giảm <Yellow>*d</>.\nHồi chiêu: 30 giây.",
    [277078540818944] = "<Red>Tiêu Tán Ánh Sáng</>: Khi Lao Lung Ánh Sáng phản Sát Thương, kéo dài hồi chiêu Chứng Nhận Vinh Quang thêm 0.5 giây, tối đa kích hoạt 10 lần.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 1 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu.",
    [277078540819200] = "<Yellow>Chúc Phúc Dị Giới</>: Khi dùng Linh Thị trong trạng thái chiến đấu, thời gian Linh Thị rút còn <Yellow>5 giây</>, hồi chiêu Linh Thị kéo dài thành <Yellow>20 giây</>. Trong thời gian đó nhận Chúc Phúc của Sinh Vật Linh Thể, mỗi giây hồi <Yellow>{CheckStar(Type=\"sealed\",ID=2085022)=1?3%}{CheckStar(Type=\"sealed\",ID=2085022)=2?4%}{CheckStar(Type=\"sealed\",ID=2085022)=3?5%}</> Giới Hạn Sinh Mệnh và tăng Giảm Thương <Yellow>*f**</>.\nHiệu quả Trị Liệu này chịu ảnh hưởng bởi Giảm Trị Liệu và Trọng Thương.",
    [277078540819456] = "<Red>Tổn Thương Thị Lực</>: Trong 5 giây sau khi trạng thái Dị Giới kết thúc, tầm nhìn bị mờ; trong thời gian này, Chặn Đòn giảm *f**, Phòng Thủ giảm *f**.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 1 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu.",
    [277078540819712] = "<Yellow>Ách Vận</>: Con Rối thức tỉnh khi chủ nhân vào chiến đấu. Khi kỹ năng của chủ nhân trúng mục tiêu chính phe địch, Con Rối sẽ bám lên mục tiêu, khiến nó chịu <Yellow>Ách Vận Quấn Thân</>: buffdisc(*id), kéo dài 30 giây. Khi chủ nhân đổi mục tiêu tấn công, Con Rối cũng chuyển sang mục tiêu mới. Sau khi tổng thời gian bám bên ngoài đạt 30 giây, Con Rối tạm trở về bên chủ cho tới lần chuyển tiếp theo.",
    [277078540819968] = "<Red>Luyến Gia</>: Sau khi Búp Bê trở về chủ, cần nghỉ 10 giây mới có thể chuyển đi lần nữa.\n<Red>Họa Tâm</>: Khi Búp Bê đã thức tỉnh ở trên chủ, chính chủ cũng chịu Vận Rủi Quấn Thân.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 2 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu trong 15 giây.",
    [277078540820224] = "<Yellow>Ác Linh</>: Ác Linh thức tỉnh khi chủ vào chiến đấu. Từ giây thứ 5, cứ mỗi <Yellow>10 giây</>, Ác Linh xuất hiện trên sân, khóa ngẫu nhiên 1 mục tiêu địch và đuổi theo; khi chạm đơn vị địch sẽ Báo Thù rồi tạm ngủ. Báo Thù gây <Yellow>{CheckStar(Type=\"sealed\",ID=2085024)=1?*d}{CheckStar(Type=\"sealed\",ID=2085024)=2?*d}{CheckStar(Type=\"sealed\",ID=2085024)=3?*d}</> Sát Thương, có <Yellow>100%</> xác suất cơ bản Choáng <Yellow>{CheckStar(Type=\"sealed\",ID=2085024)=1?1.5}{CheckStar(Type=\"sealed\",ID=2085024)=2?2}{CheckStar(Type=\"sealed\",ID=2085024)=3?2.5}</> giây và khắc Dấu <Yellow>Kẻ Thù</> trong 10 giây, khiến Tốc Độ Di Chuyển -<Yellow>20%</>. Lần xuất hiện kế tiếp, Ác Linh <Yellow>ưu tiên khóa</> mục tiêu có Dấu Kẻ Thù.\nCùng lúc, Ác Linh chỉ có thể đánh dấu 1 mục tiêu là Kẻ Thù.",
    [277078540820480] = "<Red>Thí Chủ</>: Ác Linh coi chủ nhân là đơn vị địch; khi chủ vào chiến đấu, bị khắc Dấu Kẻ Thù trong 10 giây.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 2 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu trong 15 giây.",
    [277078540820736] = "<Yellow>Bảo Hộ Người Giấy</>: Khi chủ nhân chịu sát thương chí mạng, kích hoạt Bảo Hộ Người Giấy trong <Yellow>8</> giây. Trong thời gian này, Người Giấy chịu phần sát thương vượt quá thay chủ nhân, đồng thời tăng <Yellow>*d</> Né Khống Chế và <Yellow>*d</> Kháng Khống Chế cho chủ nhân, khiến chủ nhân miễn nhiễm hiệu ứng giảm Tốc Độ Di Chuyển. Tổng sát thương vượt quá mà Người Giấy có thể chịu không vượt <Yellow>{CheckStar(Type=\"sealed\",ID=2085026)=1?56%}{CheckStar(Type=\"sealed\",ID=2085026)=2?70%}{CheckStar(Type=\"sealed\",ID=2085026)=3?84%}</> Giới Hạn Sinh Mệnh của chủ nhân. Khi đạt giới hạn, Bảo Hộ kết thúc sớm.\nBảo Hộ tối đa kích hoạt 1 lần mỗi 120 giây.",
    [277078540820992] = "<Red>Mỏng Manh</>: Khi Bảo Hộ kết thúc, 15% Sát Thương tràn mà Người Giấy đã chịu sẽ tác dụng trở lại lên chủ, đồng thời khiến Giảm Thương của chủ giảm 15% trong 15 giây tiếp theo.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 1 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu.",
    [277078540821248] = "<Yellow>Trị Thương Nhẹ</>: Khi Sinh Mệnh người đeo chưa đầy nhưng cao hơn <Yellow>{CheckStar(Type=\"sealed\",ID=2085027)=1?50%}{CheckStar(Type=\"sealed\",ID=2085027)=2?48%}{CheckStar(Type=\"sealed\",ID=2085027)=3?46%}</>, Lục Hoa mỗi giây hồi cho người đeo <Yellow>{CheckStar(Type=\"sealed\",ID=2085027)=1?4.5%}{CheckStar(Type=\"sealed\",ID=2085027)=2?5%}{CheckStar(Type=\"sealed\",ID=2085027)=3?5.5%}</> lượng Sinh Mệnh đã mất (lượng hồi không thấp hơn <Yellow>0.5%</> Giới Hạn Sinh Mệnh). Nếu Sinh Mệnh người đeo đã đầy, Lục Hoa chuyển sang trị liệu đồng đội có Sinh Mệnh thấp nhất gần đó; cùng một đơn vị không thể nhận nhiều lần trị liệu từ Lục Hoa của người khác trong 1 giây.\nHiệu quả hồi phục của Lục Hoa chịu ảnh hưởng bởi Giảm Trị Liệu và Trọng Thương.",
    [277078540821504] = "<Red>Thu Hút Muỗi</>: Khi người trang bị có Khiên, mỗi giây giảm lượng Khiên bằng 2.5% Giới Hạn Sinh Mệnh.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 1 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu.",
    [277078540821760] = "<Yellow>Cuồng Phong</>: Trong chiến đấu, Tốc Độ Di Chuyển của người mang +<Yellow>10%</>, Tốc Độ Đánh Đánh Thường +<Yellow>{CheckStar(Type=\"sealed\",ID=2085025)=1?10%}{CheckStar(Type=\"sealed\",ID=2085025)=2?15%}{CheckStar(Type=\"sealed\",ID=2085025)=3?20%}</>;\n<Yellow>Sấm Sét</>: Khi Đánh Thường trúng mục tiêu địch, có <Yellow>15%</> xác suất tung Lôi Kích gây <Yellow>{CheckStar(Type=\"sealed\",ID=2085025)=1?*d}{CheckStar(Type=\"sealed\",ID=2085025)=2?*d}{CheckStar(Type=\"sealed\",ID=2085025)=3?*d}</> sát thương. Sấm Sét có <Yellow>{CheckStar(Type=\"sealed\",ID=2085025)=1?40%}{CheckStar(Type=\"sealed\",ID=2085025)=2?50%}{CheckStar(Type=\"sealed\",ID=2085025)=3?60%}</> xác suất cơ bản gây Trì Trệ trong <Yellow>3 giây</>.",
    [277078540822016] = "<Red>Dẫn Lôi</>: Khi người mang kích hoạt Lôi Điện lên mục tiêu, có 50% xác suất Lôi Điện cũng giáng lên bản thân gây Sát Thương; Lôi Điện có 50% xác suất gây Trì Trệ 3 giây.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 1 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu.",
    [277078540822272] = "<Yellow>Trấn Định Cảm Xúc</>: Kích hoạt trong chiến đấu, trấn an mục tiêu địch quanh người mang. Nếu mục tiêu địch ở trong phạm vi 8 m quá 3 giây, sẽ tiến vào <Yellow>Lạc Lối</> trong 4 giây. Nếu địch tấn công người mang, tiến trình tăng nhanh; khoảng cách kích hoạt tăng tốc là <Yellow>{CheckStar(Type=\"sealed\",ID=2085016)=1?1}{CheckStar(Type=\"sealed\",ID=2085016)=2?0.75}{CheckStar(Type=\"sealed\",ID=2085016)=3?0.5}</> giây. Khi địch chịu Sát Thương, tiến trình bị trì hoãn; khoảng cách kích hoạt trì hoãn là 2 giây.\nMỗi <Yellow>{CheckStar(Type=\"sealed\",ID=2085016)=1?10}{CheckStar(Type=\"sealed\",ID=2085016)=2?8}{CheckStar(Type=\"sealed\",ID=2085016)=3?7}</> giây tối đa khiến mục tiêu xung quanh vào Lạc Lối 1 lần.\n\n<Yellow>Lạc Lối</>: buffdisc(*id)",
    [277078540822528] = "<Red>Bóc Tách Dục Vọng</>: Trong chiến đấu, cứ mỗi 7 giây người mang cũng tiến vào Lạc Lối trong 1 giây. Chịu Sát Thương hoặc Hồi Phục đều làm chậm tiến trình này.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 1 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu.",
    [277078540822784] = "<Yellow>Chuyển Dời Sát Thương</>: Khi trong thời gian ngắn chịu sát thương vượt <Yellow>30%</> Giới Hạn Sinh Mệnh, nhận năng lực Giá Họa trong <Yellow>5 giây</>. Sau khi dùng Giá Họa lên mục tiêu địch đã chọn, trong <Yellow>8 giây</> tiếp theo, <Yellow>{CheckStar(Type=\"sealed\",ID=2085014)=1?70%}{CheckStar(Type=\"sealed\",ID=2085014)=2?80%}{CheckStar(Type=\"sealed\",ID=2085014)=3?90%}</> Sát Thương Trực Tiếp bạn chịu sẽ chuyển sang mục tiêu đó. Tổng sát thương chuyển không thể vượt <Yellow>2</> lần Giới Hạn Sinh Mệnh của bản thân và mất hiệu lực nếu mục tiêu ở quá xa. Mỗi <Yellow>30 giây</> tối đa nhận Giá Họa 1 lần.\n<Yellow>Trực Giác Nguy Hiểm</>: Khi sắp chịu khống chế, có <Yellow>100%</> xác suất cơ bản né lần khống chế đó. Nếu kích hoạt <Yellow>3 lần</> trong thời gian ngắn (3 giây), hiệu ứng vào hồi chiêu <Yellow>10 giây</>.",
    [277078540823040] = "<Red>Hậu Sợ</>: Trong 10 giây sau khi hiệu ứng Giá Họa kết thúc, Giảm Thương giảm 10%. Trong thời gian hồi chiêu sau khi liên tục kích hoạt Trực Giác Nguy Hiểm, Tỉ Lệ Trúng Khống Chế và Kháng Khống Chế giảm.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 1 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu.",
    [277078540823296] = "<Yellow>Công Chứng</>: Khi người mang dùng Kỹ Năng Thường hoặc Kỹ Năng Kết Liễu trong chiến đấu, tự động Công Chứng kỹ năng đó; lần lượt có xác suất <Yellow>{CheckStar(Type=\"sealed\",ID=2085029)=1?80%/10%}{CheckStar(Type=\"sealed\",ID=2085029)=2?65%/15%/10%}{CheckStar(Type=\"sealed\",ID=2085029)=3?50%/20%/20%}</> Công Chứng thành công, nhận <Yellow>{CheckStar(Type=\"sealed\",ID=2085029)=1?1/2}{CheckStar(Type=\"sealed\",ID=2085029)=2?1/2/3}{CheckStar(Type=\"sealed\",ID=2085029)=3?1/2/3}</> tầng Công Chứng. Có 10% xác suất thất bại, mất 1 tầng. Mỗi tầng tăng <Yellow>*f</> Tấn Công và <Yellow>*f</> Cường Hóa Kỹ Năng.\nCông Chứng tối đa <Yellow>{CheckStar(Type=\"sealed\",ID=2085029)=1?40}{CheckStar(Type=\"sealed\",ID=2085029)=2?50}{CheckStar(Type=\"sealed\",ID=2085029)=3?60}</> tầng. Khi số tầng do kỹ năng kích hoạt vượt giới hạn, phần vượt tự động bị tiêu hao; mỗi tầng làm lần thi triển đó tăng <Yellow>10%</> Tăng Thương và <Yellow>10%</> Tăng Trị Liệu.\nRời cảnh sẽ xóa toàn bộ tầng Công Chứng.",
    [277078540823552] = "<Red>Tội Ngụy Chứng</>: Khi Công Chứng kỹ năng của người mang thất bại, Tăng Thương của lần thi triển đó giảm 60%, Tăng Trị Liệu giảm 60%.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 1 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu.",
    [277078540823808] = "<Yellow>Tấn Công Điểm Yếu</>: Khi người mang tấn công mục tiêu chính, có thể gây <Yellow>Bộc Lộ Điểm Yếu</>, mỗi giây tối đa 1 tầng, tối đa <Yellow>30</> tầng. Mỗi khi tiêu hao <Yellow>15</> tầng, có thể bóp cò Chuông Tang, tấn công Linh Thể mục tiêu, gây <Yellow>{CheckStar(Type=\"sealed\",ID=2085001)=1?*d}{CheckStar(Type=\"sealed\",ID=2085001)=2?*d}{CheckStar(Type=\"sealed\",ID=2085001)=3?*d}</> sát thương, trong <Yellow>3 giây</> giảm <Yellow>70%</> Tăng Hồi Phục Nhận Vào và giảm Tốc Độ Di Chuyển <Yellow>*f**</>; ngoài ra có <Yellow>{CheckStar(Type=\"sealed\",ID=2085001)=1?60%}{CheckStar(Type=\"sealed\",ID=2085001)=2?80%}{CheckStar(Type=\"sealed\",ID=2085001)=3?100%}</> xác suất cơ bản làm mục tiêu Choáng <Yellow>1 giây</>. Nếu mục tiêu đang Bá Thể, áp lại <Yellow>3</> tầng Bộc Lộ Điểm Yếu.",
    [277078540824064] = "<Red>Quán Chú Linh Tính</>: Khi người trang bị bóp cò, tiêu hao 20 Thể Lực. Nếu Thể Lực dưới 20, Thể Lực bị xóa sạch và không thể hồi trong 2 giây tiếp theo.\n<Red>Phản Phệ Điểm Yếu</>: Trong 2 giây sau khi dùng Chuông Tang, người trang bị không thể tiếp tục Vạch Trần Điểm Yếu. Trong thời gian này, Giảm Thương giảm *f**.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 1 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu.",
    [277078540824320] = "<Yellow>Đạn Gỉ</>: Khi đòn đánh trúng mục tiêu chính, có xác suất bắn một viên độc hoàn xanh sẫm, khiến cơ thể mục tiêu bị ăn mòn lở loét, mỗi giây gây <Yellow>{CheckStar(Type=\"sealed\",ID=2085028)=1?#placeholder#}{CheckStar(Type=\"sealed\",ID=2085028)=2?#placeholder#}{CheckStar(Type=\"sealed\",ID=2085028)=3?#placeholder#)</> sát thương trong <Yellow>5</> giây; hồi chiêu 5 giây. Trong thời gian này, tấn công mục tiêu sẽ kích hoạt <Yellow>Độc Dịch Bắn Tóe</>, gây sát thương cho tối đa 6 mục tiêu địch khác trong phạm vi <Yellow>8</>m; mỗi 2 giây tối đa bắn tóe 1 lần.",
    [277078540824576] = "<Red>Ô Nhiễm Tinh Không</>: Bắn đạn khiến bản thân nhận hiệu ứng Dịch Tinh: mỗi 2 giây chịu Sát Thương bằng 1% Giới Hạn Sinh Mệnh trong 10 giây; hiệu ứng cộng tối đa 3 tầng;\n<Red>Tính Ăn Mòn</>: Hiệu ứng Bắn Tóe Độc Dịch cũng tác dụng lên bản thân;\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 1 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu.",
    [277078540824832] = "<Yellow>Sương Độc Lan Tràn</>: Khi người mang bị kẻ địch trong phạm vi 8 m tấn công, có <Yellow>100%</> xác suất cơ bản khiến kẻ đó ngẫu nhiên nhiễm 1 trong 3 loại độc tố trong <Yellow>8 giây</>; mỗi loại tối đa <Yellow>5 tầng</>. Hiệu ứng nhiễm độc tối đa kích hoạt 1 lần mỗi 0.5 giây, với cùng một mục tiêu tối đa 1 lần mỗi 2 giây.\n<Yellow>Độc Tố Xâm Nhiễm</>: Sau khi mang Vật Phong Ấn này 5 phút, tiến vào trạng thái <Yellow>Độc Nhập Cốt</>. Nếu người mang chết trong trạng thái này, để lại Vũng Độc tồn tại <Yellow>10 giây</>. Khi Vũng Độc xuất hiện, có <Yellow>100%</> xác suất cơ bản Trói Buộc kẻ địch trong phạm vi <Yellow>3 giây</>, đồng thời mỗi giây thử áp 1 tầng của cả 3 loại độc lên từng kẻ địch trong phạm vi. Khi đứng trong Vũng Độc, Tốc Độ Di Chuyển giảm <Yellow>50%</>; Vũng Độc ảnh hưởng tối đa <Yellow>10</> người.\nHiệu ứng cụ thể của 3 loại độc tố:\n\n<Yellow>Độc Tố Tê Liệt</>: Giảm <Yellow>*f**</> Tốc Độ Đánh, tối đa 5 tầng. Khi đã đủ 5 tầng mà tiếp tục bị áp thêm, có <Yellow>{CheckStar(Type=\"sealed\",ID=2085008)=1?40%}{CheckStar(Type=\"sealed\",ID=2085008)=2?55%}{CheckStar(Type=\"sealed\",ID=2085008)=3?70%}</> xác suất cố định tiến vào trạng thái Trì Trệ trong 1 giây;\n<Yellow>Độc Tố Suy Nhược</>: Giảm <Yellow>*f**</> Tấn Công, tối đa 5 tầng. Khi đã đủ 5 tầng mà tiếp tục bị áp thêm, có <Yellow>{CheckStar(Type=\"sealed\",ID=2085008)=1?40%}{CheckStar(Type=\"sealed\",ID=2085008)=2?55%}{CheckStar(Type=\"sealed\",ID=2085008)=3?70%}</> xác suất cố định tiến vào trạng thái Câm Lặng trong 1 giây;\n<Yellow>Độc Tố Mệt Mỏi</>: Giảm <Yellow>*f**</> Tốc Độ Di Chuyển, tối đa 5 tầng. Khi đã đủ 5 tầng mà tiếp tục bị áp thêm, có <Yellow>{CheckStar(Type=\"sealed\",ID=2085008)=1?40%}{CheckStar(Type=\"sealed\",ID=2085008)=2?55%}{CheckStar(Type=\"sealed\",ID=2085008)=3?70%}</> xác suất cố định bị Giảm Tốc 50% trong 1 giây.",
    [277078540825088] = "<Red>Dễ Bay Hơi</>: Trong chiến đấu, mỗi 1 giây người mang nhiễm ngẫu nhiên 1 trong 3 loại độc trong 8 giây. Khi người mang làm kẻ tấn công nhiễm độc, có 65% xác suất ưu tiên truyền loại độc bản thân đang chịu.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 1 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu.",
    [277078540825344] = "<Yellow>Vùng Cỏ Mặt Đen</>: Khiến người mang vào trạng thái Cận Kề Lời Nguyền; sau 5 phút chuyển thành <Yellow>Gánh Lời Nguyền</>. Nếu chết trong trạng thái này, mọc một vùng Đất Hoạt Hóa bán kính 8 m tại chỗ trong 10 giây, áp các hiệu ứng sau lên tối đa 10 đồng minh trong phạm vi:\nMỗi giây hồi Sinh Mệnh bằng <Yellow>{CheckStar(Type=\"sealed\",ID=2085030)=1?6%}{CheckStar(Type=\"sealed\",ID=2085030)=2?7.5%}{CheckStar(Type=\"sealed\",ID=2085030)=3?9%}</> Giới Hạn Sinh Mệnh của người mang, ưu tiên đồng minh có Sinh Mệnh còn lại thấp; vượt 5 người thì lượng hồi suy giảm;\nNhận Tăng Tấn Công bằng <Yellow>{CheckStar(Type=\"sealed\",ID=2085030)=1?15%}{CheckStar(Type=\"sealed\",ID=2085030)=2?20%}{CheckStar(Type=\"sealed\",ID=2085030)=3?25%}</> Tấn Công của người mang, tối đa 10 người;\nMiễn <Yellow>{CheckStar(Type=\"sealed\",ID=2085030)=1?30}{CheckStar(Type=\"sealed\",ID=2085030)=2?40}{CheckStar(Type=\"sealed\",ID=2085030)=3?50}</> lượt hiệu ứng Khống Chế.\nSau khi hiệu ứng kích hoạt hoặc đổi cảnh, Cận Kề Lời Nguyền bắt đầu lại.",
    [277078540825600] = "<Red>Hồi Âm Di Hận</>: Khi đang chiến đấu, người mang định kỳ giảm Lý Trí và không thể nhận hiệu ứng tăng Tốc Độ Di Chuyển.\n<Red>Lời Nguyền Hài Cốt</>: Khi Đất Hoạt Hóa tồn tại, người mang không thể chủ động hồi sinh hoặc được đồng đội hồi sinh. Nếu thi thể bị cưỡng chế thanh tẩy, Đất Hoạt Hóa chỉ giữ hiệu ứng hồi Sinh Mệnh.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 2 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu trong 15 giây.",
    [277078540825856] = "<Yellow>Sol Bảo Mệnh</>: Giảm Thương của người mang tăng <Yellow>*f**</>.\n<Yellow>Tài Sản Khổ Nạn</>: Khi người mang chịu sát thương, tăng Phòng Thủ theo tổng sát thương đã chịu trong <Yellow>30 giây</>; tối đa tăng <Yellow>*d</> Phòng Thủ.",
    [277078540826112] = "<Red>Tiền Nhiều Đè Nặng</>: Sau khi người mang giữ Tài Phú Khổ Nạn quá 20 giây, nếu vẫn đang chiến đấu, cứ mỗi 10 giây sẽ rơi vào trạng thái Quá Tải trong 5 giây: giảm *f** Tốc Độ Di Chuyển và *f** Tốc Độ Hồi Thể Lực.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 1 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu.",
    [277078540826368] = "<Yellow>Năng Lượng Sinh Mệnh</>: Người mang nhận 1 điểm Năng Lượng Sinh Mệnh mỗi <Yellow>20 giây</>, tối đa 3 điểm. Khi tổng Trị Liệu Hiệu Lực gây cho bản thân hoặc đồng minh vượt <Yellow>50%</> Giới Hạn Sinh Mệnh của bản thân, tiêu hao 1 điểm, thêm 3 tầng <Yellow>Sinh Trưởng Mạnh Mẽ</> lên mục tiêu trong 10 giây và nhận 1 <Yellow>Hạt Giống Sinh Mệnh</>, tối đa giữ 3.\n\n<Yellow>Sinh Trưởng Mạnh Mẽ</>: Khi Sinh Mệnh chưa đầy, mỗi giây tiêu hao 1 tầng và hồi <Yellow>{CheckStar(Type=\"sealed\",ID=2085006)=1?*d}{CheckStar(Type=\"sealed\",ID=2085006)=2?*d}{CheckStar(Type=\"sealed\",ID=2085006)=3?*d}</> Sinh Mệnh.\n<Yellow>Hạt Giống Sinh Mệnh</>: Khi người mang chịu sát thương và Sinh Mệnh dưới <Yellow>50%</>, tự động tiêu hao 1 Hạt Giống Sinh Mệnh, hồi cố định <Yellow>{CheckStar(Type=\"sealed\",ID=2085006)=1?32%}{CheckStar(Type=\"sealed\",ID=2085006)=2?40%}{CheckStar(Type=\"sealed\",ID=2085006)=3?48%}</> Giới Hạn Sinh Mệnh.",
    [277078540826624] = "<Red>Dị Biến</>: Mỗi 1 điểm Năng Lượng Sinh Mệnh người mang tiêu hao sẽ tích 1 tầng Dị Biến, giảm 5% Tốc Độ Di Chuyển và 5% Phòng Thủ. Tối đa 10 tầng. Sau khi rời chiến đấu hoặc khi đứng yên, Dị Biến dần tiêu tán theo thời gian.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 2 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu trong 15 giây.",
    [277078540826880] = "<Yellow>Quyến Cố</>: Khi người đeo dùng Đánh Thường hoặc kỹ năng không thuộc loại Giải Khống Chế, có xác suất kích hoạt <Yellow>May Mắn</> trong 10 giây: mỗi tầng tăng <Yellow>*f**</> Tốc Độ Di Chuyển, <Yellow>*d</> Bạo Kích và <Yellow>*d</> Cường Hóa Kỹ Năng. Nếu không kích hoạt May Mắn, xác suất sẽ được tích sang lần dùng kỹ năng tiếp theo cho tới khi kích hoạt. Xác suất kích hoạt giảm dần theo số tầng <Yellow>May Mắn</> đang có: ban đầu <Yellow>25%</>, ở 5 tầng giảm về 0.",
    [277078540827136] = "<Red>Kiệt Quệ</>: Khi May Mắn kết thúc, người trang bị rơi vào Khốn Đốn trong 4 giây: Tốc Độ Di Chuyển giảm *d**, Tốc Độ Hồi Thể Lực giảm *d**, đồng thời không thể kích hoạt May Mắn trong thời gian này.\n<Red>Bài Xích</>: Trong chiến đấu, cứ mỗi 30 giây, ngẫu nhiên 1 thuộc tính từ của Vật Chất Phi Phàm bị vô hiệu.",
    [277078540842752] = "Khi dùng kỹ năng, có xác suất tăng 200 Chuyên Công Quái Vật và 3% Tấn Công trong 8 giây. Hồi chiêu 20 giây.",
    [277078540843008] = "Khi dùng kỹ năng, có xác suất tăng 200 Chuyên Công Hệ và 3% Tấn Công trong 8 giây. Hồi chiêu 20 giây.",
    [277078540871168] = "Khi Máu dưới <HighLight>35%</> thì buffdisc(*id), hồi chiêu 1 phút.",
    [277078540873728] = "Sát thương của <HyperLink stylename=\"M_Link\" u=\"86011020\" color=\"#f4a067\">Cuồng Phủ</> tăng 15%, khoảng cách kích hoạt hiệu ứng giảm từ 0.8 giây xuống 0.6 giây, xác suất cơ bản gây Chậm tăng lên 90%.",
    [277078540873984] = "<HyperLink stylename=\"M_Link\" u=\"86011050\" color=\"#f4a067\">Tịnh Quang</> tăng thêm Bạo Kích và Xuyên Thấu, hiệu quả Tăng Thương tăng 5%.;\n<HyperLink stylename=\"M_Link\" u=\"86011010\" color=\"#f4a067\">Tịnh Trảm</> trở thành kỹ năng tích trữ 2 lần, đồng thời sát thương tăng 15%.",
    [277078540874240] = "<HyperLink stylename=\"M_Link\" u=\"86011080\" color=\"#f4a067\">Vô Ám Thương</> nhận hiệu ứng <HighLight>Thần Phạt</>: Dựa trên % Sinh Mệnh mục tiêu đã mất và Tấn Công Vật Lý bản thân để gây Sát Thương Vật Lý; Sinh Mệnh mục tiêu càng thấp, sát thương càng cao, tối đa bằng 100% giá trị cơ sở Tấn Công Vật Lý bản thân. <HighLight>Vô Ám</> có hiệu lực với mục tiêu địch dưới 40% Sinh Mệnh.;\nSát thương của <HyperLink stylename=\"M_Link\" u=\"86011040\" color=\"#f4a067\">Trục Nhật</> tăng 15%.",
    [277078540874496] = "<HyperLink stylename=\"M_Link\" u=\"86023020\" color=\"#f4a067\">Trị Liệu Tâm Lý</> tăng 10% lượng trị liệu. Khi <HyperLink stylename=\"M_Link\" u=\"86023020\" color=\"#f4a067\">Trị Liệu Tâm Lý</> khả dụng, dùng kỹ năng chiến đấu có hiệu ứng trị liệu sẽ tự động thi triển <HyperLink stylename=\"M_Link\" u=\"86023020\" color=\"#f4a067\">Trị Liệu Tâm Lý</>.;\n<HyperLink stylename=\"M_Link\" u=\"86023020\" color=\"#f4a067\">Khiển Thức</> tăng 10% lượng trị liệu.",
    [277078540874752] = "Trong thời gian <HyperLink stylename=\"M_Link\" u=\"86031030\" color=\"#f4a067\">Đạn Khí</>, Tốc Chạy tăng 25%; có thể tấn công thêm 2 kẻ địch trong phạm vi 3m quanh mục tiêu. Mỗi đòn khiến địch <HighLight>Trì Trệ</> 1 giây và có 50% xác suất cơ bản gây <HighLight>Giảm Tốc</> 50% trong 1 giây.",
    [277078540878592] = "Sát Thương Kỹ Năng tăng 45%.",
    [277078540878848] = "Khi trúng mục tiêu, gây Giảm Tốc 25% trong 3 giây.",
    [277078540879616] = "Sát thương Kỹ Năng giai đoạn hai tăng 85%.",
    [277078540880128] = "Sát thương vụ nổ của Kỹ Năng giai đoạn hai tăng 100%.",
    [277078540884224] = "Sát Thương Kỹ Năng tăng 100%.",
    [281613489407488] = "Đánh Thường",
    [281613489407744] = "Kỹ Năng Bậc",
    [281613489408000] = "Đặc Kỹ",
    [281613489408256] = "Kỹ Năng Nhập Vai",
    [281888635749888] = "Giới Hạn Thiết Lập",
    [282026343139328] = "Trị Liệu",
    [282094525746944] = "Mở Khóa Mua Vật Phẩm",
    [285943890209024] = "Áp dụng Ám Thị tích cực lên mục tiêu, lập tức hồi lượng lớn Máu và cho mục tiêu Giảm Thương ngắn.",
    [285943890237952] = "Dùng sức mạnh xóa bỏ không gian, liên tục gây sát thương lên kẻ địch trong phạm vi, sau đó tung đòn kết thúc gây lượng lớn sát thương. Với quái vật, gây thêm hiệu ứng gom lại và Hất Tung.",
    [285943890247936] = "Liên tục bắn nhiều Đạn Khí vào kẻ địch.",
    [285943890248960] = "Dùng trò ảo thuật ngẫu nhiên tấn công kẻ địch tại vị trí mục tiêu và thêm hiệu ứng tùy loại trò.",
    [285943890251008] = "Dùng tiếng gầm kinh người chấn nhiếp kẻ địch, sau đó triệu hồi phân thân Cự Nhân đập mạnh xuống đất, gây sát thương phạm vi và Giảm Tốc.",
    [285943890251520] = "Triệu hồi Lao Lung Tinh Quang tấn công mục tiêu trong phạm vi, gây Giam Cầm và Giảm Tốc; riêng mục tiêu khóa chịu thêm Choáng.",
    [285944427079936] = "Cấp Cứu",
    [286011804466944] = "Dạ Phạt",
    [286011804540928] = "Cắn Xé",
    [286011805520640] = "Làm Bữa Tối",
    [286011805520896] = "Chế Thuốc",
    [286012072991744] = "Rung Chuông để thu hút Linh Hồn Khuyển Đỏ Thẫm trong phạm vi 4m, khiến chúng lập tức đổi mục tiêu vồ lần này sang bản thân.",
    [286012073052416] = "Dẫn Leodero tấn công vị trí hiện tại của bản thân; sau 1 giây, gây sát thương Sét trong phạm vi 3m quanh vị trí cũ của bản thân, không phân biệt địch-ta.",
    [286012073161728] = "Tập trung Linh Tính của bảo thạch lá xanh vào vòng tay, kích hoạt Vật Phong Ấn để đỡ đòn chí mạng của Phu Nhân Tử Tước.",
    [286012073170944] = "1. Triệu hồi 3 vũ khí",
    [286012073171456] = "1. Dựa theo Buff Vũ Khí nhận được để dùng kỹ năng khác nhau.",
    [286012073181952] = "1. Gây sát thương lên mục tiêu.",
    [286012073188096] = "1. Chỉ định 2 mục tiêu và dùng AOE hình tròn cần chia sát thương; 3 người chia, kèm Khuếch Thương.",
    [286012073189120] = "1. Gây sát thương lên mục tiêu; 2. Gây thêm một lần sát thương trong vùng hình chữ nhật phía trước.",
    [286012073347072] = "Tay trái cầm kiếm, liên tục chém 2 lần.\nGây hai lần sát thương lên đơn vị mục tiêu kỹ năng.",
    [286012073347840] = "Chiến Hống\nGây một lần sát thương phạm vi tròn lấy bản thân làm tâm. Triển khai Lĩnh Vực Quyết Đấu, đồng thời phong bế khu vực chiến đấu.",
    [286012073348352] = "Tụ lực tại chỗ rồi húc mục tiêu một lần; sau cú húc sẽ nhảy lên, dùng đại khiên đập xuống đất tạo sóng chấn động.\nGây 1 lần sát thương húc; trước khi nhảy có cảnh báo, sau đó gây 1 lần sát thương phạm vi tròn.",
    [286012073349376] = "Cộng Hưởng Linh Tính: thông qua niệm chú, gây sát thương phạm vi lớn quanh vị trí trung tâm mục tiêu.",
    [286012073349632] = "Lĩnh Vực Mộng Cảnh: Sau khi niệm chú khiến mục tiêu nhập mộng, khống chế mục tiêu, gây Tăng Thương và liên tục gây sát thương.",
    [286012073371904] = "Nhanh chóng nhảy lùi để kéo giãn khoảng cách với kẻ địch. Nhấn lại trong 3 giây để dùng súng lục ổ quay, bắn liên tiếp 2 phát vào kẻ địch phía trước.\n\nMột khẩu súng lục ổ quay ánh đồng thau từ một người bạn cũ; uy lực của nó đẹp chẳng kém vẻ ngoài.",
    [286012073372672] = "Phóng nhiều lá Tarot thành phi đao về vùng hình quạt phía trước, gây Sát Thương cho kẻ địch trúng đòn. Có thể dùng liên tiếp 3 lần; lần thứ ba đẩy lùi kẻ địch. Nếu quá một khoảng thời gian không dùng tiếp, kỹ năng sẽ vào hồi chiêu.\n\nMột xấp bài Tarot bình thường — đạo cụ quen thuộc trong bói toán, cũng là vũ khí bất ngờ nhất.",
    [286012073379328] = "Ngắm kẻ địch trong 5 giây để gây sát thương bắn cao hơn.",
    [286012073382656] = "Thi triển Nghi Thức Ma Pháp tại vị trí mục tiêu, tổng cộng gây 3 lần Sát Thương.",
    [286012073382912] = "Loại đạn rèn để đối phó vật ô uế và sa đọa. Khi quái tung kỹ năng vòng xanh, bắn trúng sẽ xuyên thủng Phòng Ngự Linh Tính, ngắt kỹ năng, khiến quái Cứng Đờ và giảm mạnh Thanh Phá Phòng.",
    [286012073647104] = "Chuyển Sang Kỹ Năng Bậc",
    [286012073696256] = "Gây lượng lớn sát thương lên kẻ địch trong phạm vi khá rộng; khi trúng, giảm 1 giây hồi chiêu của toàn bộ kỹ năng.",
    [286012073699584] = "Sau khi thi triển, tạo Trường Pháp Thuật quanh nhân vật, liên tục gây sát thương lên kẻ địch xung quanh.",
    [286012073934848] = "Ném một Đồng Vàng vào mục tiêu để xử lý mục tiêu!\nKhi sở hữu trên 250 và 500 Đồng Vàng, sẽ được Cường Hóa.",
    [286012610850816] = "Tung trọng quyền vào kẻ địch, có thể phá Tư Thế Phòng Thủ của chúng.",
    [286012610851072] = "Có thể phòng thủ hiệu quả phần lớn đòn tấn công và giảm Sát Thương. Nếu tung Phòng Thủ đúng lúc đòn địch trúng, có thể phản chế và đẩy lùi kẻ địch.",
    [286013147031808] = "Ô Nhiễm",
