    [294670189998848] = "Kỹ Năng Quái Vật",
    [294670189999104] = "Kỹ Năng Nghề Nghiệp",
    [294670189999360] = "Kỹ Năng Hệ Thống",
    [294670189999616] = "Kỹ Năng Đồng Hành",
    [294670190001664] = "Kỹ Năng Chiến Đấu không phải Đánh Thường",
    [294670190006016] = "Kỹ Năng Dịch Chuyển",
    [294807628941568] = "Hiệu Ứng Khống Chế",
    [294807628943360] = "Trọng Thương",
    [294807628944128] = "Đóng Băng",
    [294807628944384] = "Thôi Miên",
    [294807897376512] = "Miễn nhiễm sát thương phải chịu. (Không thể miễn nhiễm một số sát thương cơ chế đặc biệt.)",
    [294807897376768] = "Bao gồm Ngắt Chiêu, Đẩy Lùi, Đánh Ngã, Hất Tung, Lơ Lửng, Cứng Đờ và Kéo. Đây là nhóm hiệu ứng Khống Chế có thời lượng cố định và biểu hiện riêng; trong thời gian này không thể di chuyển, Né, hoặc dùng kỹ năng. (Ngắt Chiêu chịu ảnh hưởng của thuộc tính Khống Chế Đẩy Lùi.)",
    [294807897377280] = "Ngoài hiệu ứng Khống Chế, các hiệu ứng khác làm suy giảm năng lực chiến đấu, bao gồm nhưng không giới hạn ở giảm giá trị thuộc tính.",
    [294807897378304] = "Không thể dùng Kỹ Năng.",
    [294807897378816] = "Trị Liệu nhận vào giảm theo tỷ lệ, không thể miễn nhiễm hoặc giải trừ. Khi áp dụng nhiều lần hiệu ứng không cộng dồn; lấy giá trị cao nhất với Giảm Trị Liệu.",
    [294807897379072] = "Miễn nhiễm hiệu ứng Khống Chế. (Không thể miễn nhiễm một số Khống Chế do cơ chế đặc biệt gây ra.)",
    [294807897379584] = "Choáng có hiệu ứng đặc biệt; không thể di chuyển, Né Tránh hoặc dùng kỹ năng.",
    [294807897380096] = "Loại Sát Thương không nhận tăng từ thuộc tính Tấn Công và cũng không bị giảm bởi thuộc tính Phòng Thủ. (Sát Thương này có giới hạn tối đa dựa trên thuộc tính Tấn Công của bên công.)",
    [294807897380352] = "Hồi Máu không chịu tăng/giảm từ thuộc tính của bên Trị Liệu, cũng không chịu tăng/giảm từ thuộc tính của bên được Trị Liệu.",
    [294807897380608] = "Hồi Sinh Mệnh không chịu tăng/giảm từ thuộc tính của bên Trị Liệu, cũng không chịu tăng/giảm từ thuộc tính của bên được Trị Liệu. (Lượng hồi này có giới hạn tối đa dựa trên thuộc tính của bên Trị Liệu.)",
    [294807897380864] = "Sát Thương không chịu ảnh hưởng của hai cặp đối kháng thuộc tính Tấn Công/Phòng Thủ và Cường Hóa Kỹ Năng/Kháng Kỹ Năng.",
    [294807897381376] = "Trị Liệu nhận vào giảm theo tỷ lệ, không thể miễn nhiễm hoặc giải trừ. Khi áp dụng nhiều lần có thể cộng dồn, tối đa 65%; lấy giá trị cao nhất với Trọng Thương.",
    [294807897381632] = "Khi Sinh Mệnh nhân vật về 0 sẽ rơi vào trạng thái Tiêu Tán. Một số hiệu ứng kỹ năng có thể Thanh Tẩy kẻ địch đang Tiêu Tán, cưỡng chế chúng Phục Tô tại điểm mặc định và áp Suy Nhược, giảm mạnh Tấn Công trong một thời gian.",
    [294807897383168] = "Ngưng tụ ba rìu ngắn từ ánh sáng bùng phát trong cơ thể; các rìu xoay quanh bản thân, liên tục đánh kẻ địch xung quanh, gây sát thương và Giảm Tốc.",
    [316660691100160] = "Khiên Linh Tính",
    [316660691100672] = "Đạn Bay Choáng",
    [316661764754688] = "Cổng Truyền Tống Kỹ Năng Chỉ Huy Công Hội",
    [316665791284224] = "Biến Thân",
    [330060720520704] = "An Hồn hoàn tất thuận lợi, Linh Tính của {Player1} đã trở về yên tĩnh, Lý Trí +{N}",
    [330129439992064] = "Nhận 1 Vật Chất Phi Phàm có Dòng Thuộc Tính {Giám Mục Chiến Tranh}.",
    [330129439992320] = "Nhận 1 Vật Chất Phi Phàm có Dòng Thuộc Tính {Giám Mục Sợ Hãi}.",
    [330129439992576] = "Nhận 1 Vật Chất Phi Phàm có Dòng Thuộc Tính {Hóa Thân Thiên Tai}.",
    [330129439992832] = "Nhận 1 Vật Chất Phi Phàm có Dòng Thuộc Tính {Mẫu Chủ Hoang Vu}.",
    [330129439993088] = "Nhận 1 Vật Chất Phi Phàm có Dòng Thuộc Tính {Đạo Sư Chính Nghĩa}.",
    [330129439993344] = "Nhận 1 Vật Chất Phi Phàm có Dòng Thuộc Tính {Đạo Sư Lừa Dối}.",
    [330129439993600] = "Nhận 1 Vật Chất Phi Phàm có dòng thuộc tính {Môn Đồ Trầm Mặc}.",
    [330129439993856] = "Nhận 1 Vật Chất Phi Phàm có Dòng Thuộc Tính {Lữ Khách Hỗn Loạn}.",
    [357273633293824] = "Thiết Lập Mặc Định",
    [357273633294080] = "Thiết Lập Mới",
    [360778595069440] = "Đúng là một Vật Phong Ấn hoàn toàn không có chút tính công kích nào.",
    [360778595082752] = "？？？: Tôi nghi cuốn bút ký này là một vật phẩm tà ác có mức độ sinh mệnh và trí tuệ nhất định.",
    [360778595194368] = "Sức Mạnh Phi Phàm được chia thành các Con Đường khác nhau; thông thường có tổng cộng 22 Con Đường Phi Phàm.",
    [360778595266560] = "<P_Yellow>Gợi ý: dùng phím hướng trái/phải để di chuyển và né đòn</>",
    [360778595280640] = "Klein: Ví dụ, nó có rất nhiều túi, có thể cất các vật phẩm khác nhau ở những chỗ khác nhau, tránh lúc gấp gáp lấy nhầm rồi chôn vùi sinh mạng trong một sai lầm nực cười.",
    [360778595436288] = "Tôi quấy nhiễu hắn, bạn tiếp tục khống chế.",
    [369437785982464] = "Hãy chọn cách hồi sinh.",
    [369437785984000] = "Hồi Sinh Giải Liên Đấu Công Hội",
    [369437785986816] = "Hồi Sinh sẽ tiêu hao số lần Hồi Sinh còn lại.",
    [369438054419968] = "Người chơi cùng Gia Tộc tham gia Phó Bản có thể nhận bù thuộc tính và thêm số lần hồi sinh.",
    [369505700154112] = "Mất Kiểm Soát",
    [369505700157440] = "Chọn Điểm Hồi Sinh",
    [382631120254464] = "Kiểm định thành công thì có thể nắm lấy vũ khí thần bí và khống chế nó.",
    [382768559162880] = "Thuộc Tính",
    [382768559164160] = "Thiên Phú",
    [395895589832448] = "Tiểu đội Kẻ Gác Đêm dùng Vật Phong Ấn 2-049 tìm đặc tính hậu duệ Antigonus, lái xe truy tìm tung tích Ray Bieber...\n\n<Notice>Trong chế độ tổ đội, khi vào Phó Bản cùng thành viên </><Highlight>Gia Tộc</><Notice>, nếu chưa đạt Chiến Lực đề nghị sẽ nhận bù buff thuộc tính. Hiệu quả bù phụ thuộc số thành viên cùng Gia Tộc trong đội và Cấp Gia Tộc.</>",
    [395895589833472] = "Trang viên May nằm ngoại ô Tingen, trồng đầy những cây táo cao lớn. Mỗi tháng Năm, hoa táo nở rộ, hương quả tươi mát luôn lan khắp nơi.\nNhưng từ năm 1354 đến nay, hương thơm ấy chưa từng trở lại. Thay vào đó là ánh trăng đỏ thẫm, cây cối cao bất thường, ô nhiễm quỷ dị… mọi dị tượng dường như đều liên quan mật thiết tới Vương Miện Tri Thức.\n\n<Notice>Ở chế độ tổ đội, khi vào Phó Bản cùng thành viên </><Highlight>Gia Tộc</><Notice>, nếu chưa đạt Điểm Phi Phàm khuyến nghị sẽ nhận bù thuộc tính. Hiệu quả bù phụ thuộc số thành viên cùng Gia Tộc trong đội và cấp Gia Tộc.</>",
    [395895589833728] = "Sự biến mất của Vương Miện Tri Thức không mang ô nhiễm khỏi trang viên; trái lại, một tồn tại sâu bên trong càng phát triển mạnh. Chỉ dẫn từ Thánh Đường càng kinh người: “Ô nhiễm sâu nhất đến từ Hồng Nguyệt… một hậu duệ mới sẽ được sinh ra tại đây…”\nĐội Kẻ Gác Đêm bảo vệ Tingen nhất định phải ngăn tất cả!\n\n<Notice>Ở chế độ tổ đội, khi vào Phó Bản cùng thành viên </><Highlight>Gia Tộc</><Notice>, nếu chưa đạt Điểm Phi Phàm khuyến nghị sẽ nhận bù thuộc tính. Hiệu quả bù phụ thuộc số thành viên cùng Gia Tộc trong đội và cấp Gia Tộc.</>",
    [395895589834496] = "Vụ cướp Chợ Đen dưới lòng Tingen đã phá vỡ thế cân bằng mong manh suốt vài tháng qua. Nếu nguyên liệu Linh Tính Mất Kiểm Soát chảy vào dân gian, chúng sẽ thai nghén thêm những cơn điên mới. Công Ty An Ninh Blackthorn đã phái một nhóm Phi Phàm Giả tham gia điều tra. Trước khi dấu vết bị mưa cuốn sạch, các bạn phải lần theo tàn dư Linh Tính nguy hiểm và bước lên con đường truy bắt thủ phạm.",
    [395895589836544] = "<Notice>Trong chế độ hai người, vào Phó Bản cùng </><Highlight>Đồng Hành Thệ Ước</><Notice> có thể nâng tới </><Highlight>Điểm Đạt Chuẩn</><Notice> của Phó Bản.</>\n\nNhà Hát Utopia gần đây xuất hiện dao động bất thường. Sức mạnh của một Tồn Tại Ngoại Tầng thẩm thấu vào hiện thực, làm ô nhiễm ý thức còn sót lại của một số Bí Ngẫu trong nhà hát. Những Bí Ngẫu bị ô nhiễm tìm cách thông qua các vật phẩm ký ức liên quan đến Klein để dựng một lối bí mật dẫn tới tinh thần của Kẻ Khờ. Nếu thành công, Mẫu Thần sẽ có khả năng ảnh hưởng tinh thần của Ngài, lan tới toàn Nam Đại Lục. Giáo Hội cần người tiến vào Thị Trấn Utopia năm xưa, thanh lý Bí Ngẫu mất kiểm soát, điều tra ký ức còn sót và cuối cùng cắt đứt nguồn ô nhiễm.\n\nCấp kẻ địch trong nhà hát sẽ tăng đồng bộ theo cấp Phi Phàm Giả; Điểm Phi Phàm đề nghị cũng thay đổi theo cấp Phi Phàm Giả.",
    [395895589836800] = "<Notice>Trong chế độ hai người, vào Phó Bản cùng </><Highlight>Đồng Hành Thệ Ước</><Notice> có thể nâng tới </><Highlight>Điểm Đạt Chuẩn</><Notice> của Phó Bản.</>\n\nNhà Hát Utopia gần đây xuất hiện dao động bất thường. Sức mạnh của một Tồn Tại Ngoại Tầng thẩm thấu vào hiện thực, làm ô nhiễm ý thức còn sót lại của một số Bí Ngẫu trong nhà hát. Những Bí Ngẫu bị ô nhiễm tìm cách thông qua các vật phẩm ký ức liên quan đến Klein để dựng một lối bí mật dẫn tới tinh thần của Kẻ Khờ. Nếu thành công, Mẫu Thần sẽ có khả năng ảnh hưởng tinh thần của Ngài, lan tới toàn Nam Đại Lục. Giáo Hội cần người tiến vào Thị Trấn Utopia năm xưa, thanh lý Bí Ngẫu mất kiểm soát, điều tra ký ức còn sót và cuối cùng cắt đứt nguồn ô nhiễm.\n\nCấp kẻ địch trong nhà hát sẽ tăng đồng bộ theo cấp Phi Phàm Giả; Điểm Phi Phàm đề nghị cũng thay đổi theo cấp Phi Phàm Giả.\nỞ độ khó này, hiệu suất nhận Dư Âm Sân Khấu gấp 1.5 lần độ khó Thường.",
    [395895589837056] = "<Notice>Trong chế độ hai người, vào Phó Bản cùng </><Highlight>Đồng Hành Thệ Ước</><Notice> có thể nâng tới </><Highlight>Điểm Đạt Chuẩn</><Notice> của Phó Bản.</>\n\nNhà Hát Utopia gần đây xuất hiện dao động bất thường. Sức mạnh của một Tồn Tại Ngoại Tầng thẩm thấu vào hiện thực, làm ô nhiễm ý thức còn sót lại của một số Bí Ngẫu trong nhà hát. Những Bí Ngẫu bị ô nhiễm tìm cách thông qua các vật phẩm ký ức liên quan đến Klein để dựng một lối bí mật dẫn tới tinh thần của Kẻ Khờ. Nếu thành công, Mẫu Thần sẽ có khả năng ảnh hưởng tinh thần của Ngài, lan tới toàn Nam Đại Lục. Giáo Hội cần người tiến vào Thị Trấn Utopia năm xưa, thanh lý Bí Ngẫu mất kiểm soát, điều tra ký ức còn sót và cuối cùng cắt đứt nguồn ô nhiễm.\n\nNgười chơi có thành tích vượt ải đua tốc độ nằm trong Top 100 của Con Đường mình mỗi tuần sẽ nhận danh hiệu riêng. Để bảo đảm công bằng, cấp kẻ địch trong nhà hát sẽ cập nhật lúc 08:00 sáng Thứ Hai hàng tuần.\nỞ độ khó này, hiệu suất nhận Dư Âm Sân Khấu gấp 2 lần độ khó Thường.",
    [395895589837312] = "Khi mở nghi thức “Truyền Thừa Ký Ức”, cánh cửa dẫn tới Thế Giới Ký Ức sẽ mở ra — nơi lưu giữ quá khứ và những trận chiến kinh tâm động phách bạn từng trải qua.\n\nNhững cường địch trong ký ức sẽ tái hiện với dáng vẻ năm xưa, chờ người thách thức mới. Khi bước vào Thế Giới Ký Ức, bạn có thể giao chiến với những đối thủ trong lịch sử và một lần nữa chứng minh bản thân.\n\nChinh phục họ là minh chứng cho sức mạnh của bạn. Nếu sát cánh cùng thành viên Gia Tộc, đó cũng là lời tri ân dành cho ký ức Gia Tộc. Khi các thành viên cùng tiến vào Thế Giới Ký Ức, Liên Kết Gia Tộc sẽ hóa thành sức mạnh thực chất, nhận hai Buff 【Thệ Hỏa Cộng Nhiên】 và 【Huyết Mạch Minh Ước】, để vinh quang khắc lên Gia Huy và trở thành truyền thừa vĩnh viễn của Gia Tộc.",
    [395895589838592] = "Khi mở nghi thức \"Truyền Thừa Ký Ức\", cánh cửa dẫn tới Thế Giới Ký Ức sẽ mở ra — nơi lưu giữ quá khứ và những trận chiến kinh tâm động phách bạn từng trải qua.\n\nNhững cường địch trong ký ức sẽ tái hiện với dáng vẻ năm xưa, chờ người thách thức mới. Khi bước vào Thế Giới Ký Ức, bạn có thể giao chiến với những đối thủ trong lịch sử và một lần nữa chứng minh bản thân.\n\nChinh phục họ là minh chứng cho sức mạnh của bạn. Nếu sát cánh cùng thành viên Gia Tộc, đó cũng là lời tri ân dành cho ký ức Gia Tộc. Khi các thành viên cùng tiến vào Thế Giới Ký Ức, Liên Kết Gia Tộc sẽ hóa thành sức mạnh thực chất, nhận hai Buff 【Thệ Hỏa Cộng Nhiên】 và 【Huyết Mạch Minh Ước】, để vinh quang khắc lên Gia Huy và trở thành truyền thừa vĩnh viễn của Gia Tộc.",
    [396306027644416] = "Phó Bản",
    [396306027644928] = "CLB",
    [409088118752768] = "Vũ Khí",
    [409225557824256] = "Trang Bị Roselle",
    [409232268644864] = "Vặn nó, Bản Đồ Sao Cơ Giới bắt đầu giải mã vũ trụ im lặng.",
    [409295619360256] = "Chuyên Công/Chuyên Phòng Quái Vật tăng {AllRaceHurtPlus_N}/{AllRaceHurtReduce_N}; Áp Chế/Kháng Quái Vật tăng {AllRaceHurtMulti_N}/{AllRaceHurtDivi_N}.",
    [409295619360512] = "Chuyên Công/Chuyên Phòng Con Đường tăng {AllProHurtPlus_N}/{AllProHurtReduce_N}; Áp Chế/Kháng Con Đường tăng {AllProHurtMulti_N}/{AllProHurtDivi_N}.",
    [409365949450240] = "<Mark>Thuộc tính cơ bản</> của trang bị tăng.",
    [409365949451008] = "Trong lối chơi <Mark>Chạy Đoàn</>, sau khi Kiểm Định ra <Mark>Đại Thành Công</>, Tấn Công tăng <Mark>125</>. <Mark>{1,1,（Đã có hiệu lực）}</>",
    [409365949451776] = "Khi lắp kỹ năng Bí Ngẫu <Mark>Ghi Chép · Mưa Bài</>, kỹ năng được cường hóa.",
    [409365949452032] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Tấn Công +<Mark>275</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Linh và Tri Hồi Hưởng</>.",
    [409365949452288] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Chuyên Công Hệ +<Mark>250</>. Sau hơn <Mark>2</> giây kể từ lần chịu sát thương gần nhất, Phá Phòng +<Mark>70</> trong <Mark>5</> giây.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Linh và Tri Hồi Hưởng</>.",
    [409365949452544] = "<Highlight>{1,2,（Ấn Ký đã mất hiệu lực）}</>Chuyên Công Con Đường tăng <Mark>310</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Hồi Hưởng Linh Và Tri Thức</>.",
    [409365949452800] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Chuyên Phòng Hệ +<Mark>250</>. Khi bị tấn công có xác suất kích hoạt Gặp Gỡ, Chuyên Phòng Hệ +<Mark>180</> trong <Mark>10</> giây; mỗi <Mark>30</> giây tối đa 1 lần.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Linh và Tri Hồi Hưởng</>.",
    [409365949453056] = "Cường Hóa Kỹ Năng +<Mark>50</>. Nhận thêm hiệu ứng dựa trên tổng Ô Nhiễm của thành viên tiểu đội gần đó.\nTổng Ô Nhiễm <Mark>30</>: Tấn Công +<Mark>30</>{1,2,（Đã kích hoạt）}\nTổng Ô Nhiễm <Mark>60</>: Bạo Kích +<Mark>30</>{1,3,（Đã kích hoạt）}\nTổng Ô Nhiễm <Mark>120</>: Khắc Chế Quái Vật +<Mark>30</>{1,4,（Đã kích hoạt）}",
    [409365949453312] = "<Highlight>{1,3,（Lạc Ấn đã mất hiệu lực）}</> Tấn Công +<Mark>345</>, Phòng Thủ -<Mark>10</>, Ô Nhiễm +<Mark>15</>.\nHiệu ứng Ô Nhiễm: Khi đạt <Mark>30</> Ô Nhiễm, Phòng Thủ -<Mark>10</>. <Mark>{1,4,（Đã tịnh hóa）}</>\nKhông có hiệu lực khi kích hoạt bộ <Mark>Linh và Tri Hồi Hưởng</>.",
    [409365949453568] = "<Highlight>{1,3,（Lạc Ấn đã mất hiệu lực）}</> Cường Hóa Kỹ Năng +<Mark>75</>, Kháng Kỹ Năng -<Mark>5</>, Ô Nhiễm +<Mark>15</>.\nHiệu ứng Ô Nhiễm: Khi đạt <Mark>30</> Ô Nhiễm, Kháng Kỹ Năng -<Mark>5</>. <Mark>{1,4,（Đã tịnh hóa）}</>\nKhông có hiệu lực khi kích hoạt bộ <Mark>Linh và Tri Hồi Hưởng</>.",
    [409365949453824] = "<Highlight>{1,3,（Lạc Ấn đã mất hiệu lực）}</> Bạo Kích +<Mark>325</>, Kháng Bạo Kích -<Mark>15</>, Ô Nhiễm +<Mark>15</>.\nHiệu ứng Ô Nhiễm: Khi đạt <Mark>30</> Ô Nhiễm, Kháng Bạo Kích -<Mark>15</>. <Mark>{1,4,（Đã tịnh hóa）}</>\nKhông có hiệu lực khi kích hoạt bộ <Mark>Linh và Tri Hồi Hưởng</>.",
    [409365949454080] = "<Highlight>{1,2,（Ấn Ký đã mất hiệu lực）}</>Chuyên Công Con Đường tăng <Mark>350</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Hồi Hưởng Linh Và Tri Thức</>.",
    [409365949454336] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Chuyên Phòng Hệ +<Mark>300</>. Khi bị tấn công có xác suất kích hoạt Gặp Gỡ, Chuyên Phòng Hệ +<Mark>180</> trong <Mark>10</> giây; mỗi <Mark>30</> giây tối đa 1 lần.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Linh và Tri Hồi Hưởng</>.",
    [409365949454592] = "Tấn Công +<Mark>300</>, Phòng Thủ -<Mark>25</>. Khi vào chiến đấu, nếu trong đội có đồng đội khác giới, Tấn Công tăng thêm <Mark>45</>.",
    [409365949455104] = "Bạo Kích +<Mark>40</>. Khi lắp kỹ năng Bí Ngẫu <Mark>Ghi Chép · Mưa Bài</>, kỹ năng được cường hóa.",
    [409365949455360] = "Tấn Công +<Mark>250</>, Phòng Thủ +<Mark>20</>. Thanh tẩy <Mark>hiệu ứng ô nhiễm</> của các trang bị khác.",
    [409365949455616] = "Chuyên Công Quái Vật tăng <Mark>360</>; khi đối đầu Đại Đế Roselle, Chuyên Công Quái Vật tăng thêm <Mark>60</>.",
    [409365949456896] = "Phá Phòng +<Mark>40</>. Dùng kỹ năng hoặc Đánh Thường sẽ thu hút ánh nhìn của 2-049; đủ ba tầng Ánh Nhìn sẽ gây thêm Sát Thương. Mỗi <Mark>4</> giây tối đa kích hoạt một lần.",
    [409365949457152] = "Xuyên Thấu +<Mark>60</>. Trong chiến đấu, toàn đội Bạo Kích +<Mark>30</>, Phòng Thủ -<Mark>15</>.",
    [409365949457408] = "Chuyên Công Quái Vật +<Mark>130</>. Trong chiến đấu, sau khi đứng yên <Mark>5</> giây, Chuyên Công Quái Vật giảm <Mark>25</> trong <Mark>5</> giây; sau khi Né, Chuyên Công Quái Vật tăng <Mark>25</> trong <Mark>15</> giây.",
    [409365949457664] = "Phá Phòng +<Mark>80</>. Dùng kỹ năng hoặc Đánh Thường sẽ thu hút ánh nhìn của 2-049; đủ ba tầng Ánh Nhìn sẽ gây thêm Sát Thương. Mỗi <Mark>4</> giây tối đa kích hoạt một lần.",
    [409365949457920] = "Xuyên Thấu +<Mark>90</>. Trong chiến đấu, toàn đội Bạo Kích +<Mark>30</>, Phòng Thủ -<Mark>15</>.",
    [409365949458176] = "Chuyên Công Quái Vật +<Mark>180</>. Trong chiến đấu, sau khi đứng yên <Mark>5</> giây, Chuyên Công Quái Vật giảm <Mark>25</> trong <Mark>5</> giây; sau khi Né, Chuyên Công Quái Vật tăng <Mark>25</> trong <Mark>15</> giây.",
    [409365949458432] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Xuyên Thấu +<Mark>120</>, Bạo Kích -<Mark>20</>. Cho người trang bị <Mark>Mỹ Đức</> của gia tộc Wiesel.\n<Mark>Mỹ Đức</>: Vũ khí <Mark>Quê Hương Tri Thức</> tăng thêm hiệu quả buff Tấn Công theo số thành viên tiểu đội sở hữu <Mark>Mỹ Đức</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949458688] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Phá Phòng +<Mark>110</>, Phòng Thủ -<Mark>15</>. Cho người trang bị <Mark>Mỹ Đức</> của gia tộc Wiesel.\n<Mark>Mỹ Đức</>: Vũ khí <Mark>Quê Hương Tri Thức</> tăng thêm hiệu quả buff Tấn Công theo số thành viên tiểu đội sở hữu <Mark>Mỹ Đức</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949458944] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Tấn Công +<Mark>180</>, Phòng Thủ -<Mark>15</>. Cho người trang bị <Mark>Mỹ Đức</> của gia tộc Wiesel. Khi vào chiến đấu, mỗi thành viên tiểu đội sở hữu <Mark>Mỹ Đức</> của gia tộc Wiesel khiến Tấn Công tăng thêm <Mark>10</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949459200] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Xuyên Thấu +<Mark>140</>, Bạo Kích -<Mark>20</>. Cho người trang bị <Mark>Mỹ Đức</> của gia tộc Wiesel.\n<Mark>Mỹ Đức</>: Vũ khí <Mark>Quê Hương Tri Thức</> tăng thêm hiệu quả buff Tấn Công theo số thành viên tiểu đội sở hữu <Mark>Mỹ Đức</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949459456] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Phá Phòng +<Mark>130</>, Phòng Thủ -<Mark>15</>. Cho người trang bị <Mark>Mỹ Đức</> của gia tộc Wiesel.\n<Mark>Mỹ Đức</>: Vũ khí <Mark>Quê Hương Tri Thức</> tăng thêm hiệu quả buff Tấn Công theo số thành viên tiểu đội sở hữu <Mark>Mỹ Đức</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949459712] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Tấn Công +<Mark>210</>, Phòng Thủ -<Mark>15</>. Cho người trang bị <Mark>Mỹ Đức</> của gia tộc Wiesel. Khi vào chiến đấu, mỗi thành viên tiểu đội sở hữu <Mark>Mỹ Đức</> của gia tộc Wiesel khiến Tấn Công tăng thêm <Mark>10</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949459968] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Cường Hóa Kỹ Năng +<Mark>35</>. Bảo vệ đồng đội lân cận, tăng <Mark>10</> Kháng Kỹ Năng cho thành viên tiểu đội gần đó.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949460224] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Bạo Kích +<Mark>80</>. Sau khi vào chiến đấu, Bạo Kích tiếp tục tăng: mỗi <Mark>5</> giây +<Mark>10</>, tối đa tăng thêm <Mark>80</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949460480] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Chuyên Công Quái Vật +<Mark>150</>. Khi bị tấn công, Chuyên Công Quái Vật tăng thêm <Mark>50</> trong 8 giây.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949460736] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Cường Hóa Kỹ Năng +<Mark>40</>. Bảo vệ đồng đội lân cận, tăng <Mark>10</> Kháng Kỹ Năng cho thành viên tiểu đội gần đó.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949460992] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Bạo Kích +<Mark>100</>. Sau khi vào chiến đấu, Bạo Kích tiếp tục tăng: mỗi <Mark>5</> giây +<Mark>10</>, tối đa tăng thêm <Mark>80</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949461248] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Chuyên Công Quái Vật +<Mark>180</>. Sau khi bị tấn công, Chuyên Công Quái Vật tăng thêm <Mark>50</> trong <Mark>8</> giây.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949461504] = "<Highlight>{1,3,（Lạc Ấn đã mất hiệu lực）}</> Tấn Công +<Mark>230</>, Cường Hóa Kỹ Năng -<Mark>10</>, Ô Nhiễm +<Mark>15</>.\nHiệu ứng Ô Nhiễm: Khi đạt <Mark>30</> Ô Nhiễm, Kháng Bạo Kích +<Mark>30</>, Tấn Công -<Mark>45</>.\nÔ Nhiễm hiện tại: {2,1,*d,F1690001,Corruption}\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949461760] = "<Highlight>{1,3,（Lạc Ấn đã mất hiệu lực）}</> Bạo Kích +<Mark>140</>, Kháng Bạo Kích -<Mark>15</>, Ô Nhiễm +<Mark>15</>. Sau khi dùng động tác xã giao <Mark>Hành Lễ</>, hiệu ứng tăng Bạo Kích đổi thành Tấn Công +<Mark>205</>.\nHiệu ứng Ô Nhiễm: Khi đạt <Mark>30</> Ô Nhiễm, Kháng Bạo Kích -<Mark>15</>. <Mark>{1,4,（Đã Tịnh Hóa）}</>\nÔ Nhiễm hiện tại: {2,1,*d,F1690001,Corruption}\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949462016] = "<Highlight>{1,3,（Lạc Ấn đã mất hiệu lực）}</> Chuyên Công Quái Vật +<Mark>240</>, Xuyên Thấu -<Mark>40</>, Ô Nhiễm +<Mark>15</>. Khi gây Sát Thương/Hồi Phục nhận 1 tầng Sức Mạnh Hoang Vu, tối đa 1 tầng mỗi <Mark>2</> giây; khi dùng <Mark>Tuyệt Kỹ</> gây Sát Thương/Hồi Phục, dựa theo Sức Mạnh Hoang Vu tích lũy để gây thêm Sát Thương/Hồi Phục.\nHiệu ứng Ô Nhiễm: Khi đạt <Mark>30</> Ô Nhiễm, Sức Mạnh Hoang Vu gây một lượng nhỏ Sát Thương lên bản thân. <Mark>{1,4,（Đã Thanh Tẩy）}</>\nÔ Nhiễm hiện tại: {2,1,*d,F1690001,Corruption}\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949462272] = "<Highlight>{1,3,（Lạc Ấn đã mất hiệu lực）}</> Tấn Công +<Mark>260</>, Cường Hóa Kỹ Năng -<Mark>10</>, Ô Nhiễm +<Mark>15</>.\nHiệu ứng Ô Nhiễm: Khi đạt <Mark>30</> Ô Nhiễm, Kháng Bạo Kích +<Mark>30</>, Tấn Công -<Mark>45</>. <Mark>{1,4,（Đã Thanh Tẩy）}</>\nÔ Nhiễm hiện tại: {2,1,*d,F1690001,Corruption}\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949462528] = "<Highlight>{1,3,（Lạc Ấn đã mất hiệu lực）}</> Bạo Kích +<Mark>160</>, Kháng Bạo Kích -<Mark>15</>, Ô Nhiễm +<Mark>15</>. Sau khi dùng động tác xã giao <Mark>Hành Lễ</>, hiệu ứng tăng Bạo Kích đổi thành Tấn Công +<Mark>235</>.\nHiệu ứng Ô Nhiễm: Khi đạt <Mark>30</> Ô Nhiễm, Kháng Bạo Kích -<Mark>15</>. <Mark>{1,4,（Đã Tịnh Hóa）}</>\nÔ Nhiễm hiện tại: {2,1,*d,F1690001,Corruption}\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949462784] = "<Highlight>{1,3,（Lạc Ấn đã mất hiệu lực）}</> Chuyên Công Quái Vật +<Mark>270</>, Xuyên Thấu -<Mark>40</>, Ô Nhiễm +<Mark>15</>. Khi gây Sát Thương/Hồi Phục nhận 1 tầng Sức Mạnh Hoang Vu, tối đa 1 tầng mỗi <Mark>2</> giây; khi dùng <Mark>Tuyệt Kỹ</>, dựa theo Sức Mạnh Hoang Vu tích lũy để gây thêm Sát Thương/Hồi Phục.\nHiệu ứng Ô Nhiễm: Khi đạt <Mark>30</> Ô Nhiễm, Sức Mạnh Hoang Vu gây một lượng nhỏ Sát Thương lên bản thân. <Mark>{1,4,（Đã Thanh Tẩy）}</>\nÔ Nhiễm hiện tại: {2,1,*d,F1690001,Corruption}\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949470464] = "Dùng kỹ năng để Lên Dây Đồng Hồ Bỏ Túi; mỗi lần lên dây khiến đồng hồ chạy <Mark>3</> giây, mỗi giây tối đa lên dây 1 lần. Khi đồng hồ đang chạy, Xuyên Thấu tăng <Mark>75</>.",
    [409365949470720] = "Sau khi dùng kỹ năng, Cường Hóa Kỹ Năng và Kháng Kỹ Năng của thành viên Tiểu Đội gần đó +<Mark>5</> trong <Mark>12</> giây; mỗi <Mark>10</> giây tối đa kích hoạt một lần.",
    [409365949470976] = "Tấn Công +<Mark>120</>, Phòng Thủ -<Mark>15</>. Khi vào chiến đấu, nếu trong đội có đồng đội khác giới, Tấn Công tăng thêm <Mark>20</>.",
    [409365949472512] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Phá Phòng +<Mark>110</>. Dùng kỹ năng hoặc Đánh Thường sẽ thu hút ánh nhìn của 2-049; đủ 3 tầng Ánh Nhìn gây thêm sát thương, mỗi <Mark>4</> giây tối đa kích hoạt 1 lần.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949472768] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Xuyên Thấu +<Mark>90</>. Khi đang chiến đấu, cả đội Bạo Kích +<Mark>30</>, Phòng Thủ -<Mark>15</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949473024] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Chuyên Công Quái Vật +<Mark>180</>. Trong chiến đấu, đứng yên <Mark>5</> giây khiến Chuyên Công Quái Vật -<Mark>25</> trong <Mark>5</> giây; sau khi Né, Chuyên Công Quái Vật +<Mark>25</> trong <Mark>15</> giây.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949473536] = "Sau hơn <Mark>2</> giây kể từ lần chịu sát thương gần nhất, Phá Phòng +<Mark>70</> trong <Mark>5</> giây.",
    [409365949474304] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Chuyên Công Quái Vật +<Mark>100</>. Sau hơn <Mark>2</> giây kể từ lần chịu sát thương gần nhất, Phá Phòng +<Mark>70</> trong <Mark>5</> giây.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt và Máu</>.",
    [409365949474560] = "<Highlight>{1,2,（Ấn Ký đã mất hiệu lực）}</>Chuyên Công Quái Vật tăng <Mark>220</>, Xuyên Thấu giảm <Mark>20</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Thệ Ước Sắt Và Máu</>.",
    [409365949475072] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Cường Hóa Kỹ Năng +<Mark>30</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Linh và Tri Hồi Hưởng</>.",
    [409365949475328] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Sau khi dùng kỹ năng Giải Khống, Kháng Kỹ Năng +<Mark>50</> trong <Mark>10</> giây; mỗi <Mark>30</> giây tối đa kích hoạt 1 lần.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Linh và Tri Hồi Hưởng</>.",
    [409365949475584] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Phá Phòng +<Mark>80</>. Khi chịu đòn có xác suất nhận <Mark>60</> Phòng Thủ trong <Mark>5</> giây; mỗi <Mark>10</> giây tối đa kích hoạt 1 lần.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Linh và Tri Hồi Hưởng</>.",
    [409365949476096] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Chặn Đòn +<Mark>120</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Linh và Tri Hồi Hưởng</>.",
    [409365949476352] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Sau khi gây sát thương, nhận <Mark>90</> Bạo Kích và <Mark>90</> Kháng Bạo Kích trong 3 giây; mỗi 5 giây tối đa kích hoạt 1 lần.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Linh và Tri Hồi Hưởng</>.",
    [409365949476608] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Tấn Công +<Mark>200</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Linh và Tri Hồi Hưởng</>.",
    [409365949476864] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Sau khi chịu khống chế, nhận <Mark>30</> Né Khống Chế và <Mark>50</> Kháng Khống Chế trong <Mark>3</> giây; mỗi <Mark>10</> giây tối đa kích hoạt 1 lần.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Linh và Tri Hồi Hưởng</>.",
    [409365949477120] = "<Highlight>{1,2,（Lạc Ấn đã mất hiệu lực）}</> Chuyên Công Con Đường +<Mark>100</>, Chuyên Phòng Con Đường +<Mark>100</>.\nKhông có hiệu lực khi kích hoạt bộ <Mark>Linh và Tri Hồi Hưởng</>.",
    [409368633825280] = "“Vù————” Chiếc Còi Bạc Dạ Oanh vang lên, dịu dàng như tiếng thì thầm của chim sơn ca, ấm áp như cơn gió đêm hè.\nKẻ Mất Kiểm Soát dừng động tác tấn công; trong đôi mắt điên loạn lại ngưng tụ chút lý trí.\nHắn nhìn thấy mọi tiếc nuối đều được bù đắp, mọi nhục nhã đều bị xóa đi, mọi bi thương còn chưa kịp trào dâng. Hắn nhìn thấy một kết cục hạnh phúc khác.\nHãy mơ một giấc mộng đẹp. Trong mộng, mọi thứ vẫn chưa sa đọa.\nHãy vĩnh viễn ngủ trong mộng đẹp, chôn vùi mọi đau khổ của kiếp này.\nĐạn Liệp Ma của Kẻ Gác Đêm xuyên qua gió, mang theo sinh mệnh của Kẻ Mất Kiểm Soát. Thân thể đáng sợ sau dị hóa lay động rồi đổ xuống, nhưng trên mặt vẫn là nụ cười.\n“Nguyện Nữ Thần Bảo Hộ cho anh.” Đồng đội cất súng cầu nguyện, rồi vuốt chú chim nhỏ thân mật đậu trên vai. “Vật Phong Ấn này đúng là vô hại. Dù sao, ai lại xem những chú chim này là tác dụng phụ chứ?”\nArnold lấy chiếc hộp chứa Vật Phong Ấn, nhẹ nhàng đặt Còi Bạc Dạ Oanh trở lại rồi cất kỹ bên mình.\nDáng người anh thẳng tắp, ánh mắt kiên định, tiếng cười sảng khoái, giống hệt một cố nhân.\n“Có lẽ là bởi từng có một linh hồn dịu dàng trú ngụ trong đó.”",
    [409433595184896] = "Tranh Đấu Sequence",
    [409433863620096] = "Khi dùng kỹ năng, có xác suất tăng <Mark>200</> Chuyên Công Quái Vật và <Mark>3%</> Tấn Công trong <Mark>8</> giây. Hồi chiêu <Mark>20</> giây.",
    [409433863620352] = "Khi dùng kỹ năng, có xác suất tăng <Mark>200</> Chuyên Công Hệ và <Mark>3%</> Tấn Công trong <Mark>8</> giây. Hồi chiêu <Mark>20</> giây.",
    [409433863621632] = "Khi dùng kỹ năng chiến đấu, gây lên mục tiêu sát thương duy trì <Mark>6</> giây; hồi chiêu <Mark>30</> giây.",
    [409433863626240] = "Khi thi triển kỹ năng chiến đấu, Sinh Vật Thần Thoại có xác suất tấn công mục tiêu. Mục tiêu bị đánh liên tục chịu Sát Thương Chuẩn trong <Mark>8</> giây và Sát Thương nhận vào tăng trong thời gian này. Hồi chiêu <Mark>20</> giây.\n\nDo ảnh hưởng Thần Tính, khi mặc trang bị này, <Mark>giới hạn số từ có thể xuất hiện khi Tái Tạo +1</>.",
    [409434937363456] = "Ở dạng Trị Liệu, khi dùng kỹ năng chiến đấu, gây trị liệu duy trì <Mark>6</> giây lên mục tiêu trị liệu; hồi chiêu <Mark>30</> giây.",
    [409434937368064] = "Khi thi triển kỹ năng chiến đấu ở dạng Trị Liệu, Sinh Vật Thần Thoại có xác suất liên tục chữa các mục tiêu xung quanh; trị liệu có thể lan tới nhiều mục tiêu, đồng thời hiệu quả Hồi Phục nhận vào tăng trong thời gian hiệu ứng. Kéo dài <Mark>8</> giây. Hồi chiêu <Mark>20</> giây.\n\nDo ảnh hưởng Thần Tính, khi mặc trang bị này, <Mark>giới hạn số từ có thể xuất hiện khi Tái Tạo +1</>.",
    [413762385349120] = "Sủng Nhi Vận Mệnh: Cường Hóa Kỹ Năng +<UpgradeNum>40</>, Kháng Kỹ Năng +<UpgradeNum>40</>.",
    [413762385349376] = "Sủng Nhi Vận Mệnh: Cường Hóa Kỹ Năng +<UpgradeNum>70</>, Kháng Kỹ Năng +<UpgradeNum>70</>.",
    [413762385349632] = "Sủng Nhi Vận Mệnh: Cường Hóa Kỹ Năng +<UpgradeNum>100</>, Kháng Kỹ Năng +<UpgradeNum>100</>.",
    [413762385349888] = "Sủng Nhi Vận Mệnh: Cường Hóa Kỹ Năng +<UpgradeNum>130</>, Kháng Kỹ Năng +<UpgradeNum>130</>.",
    [413898750559745] = "Có thể Kế Thừa Dòng; sau %s ngày mở khóa Tái Tạo.",
    [418367932467200] = "Tấn Công +600, Tấn Công Đặc Biệt +200. Khi gây sát thương, Tấn Công và Tấn Công Đặc Biệt tăng thêm 240 trong 10 giây, đồng thời cộng 1 tầng Khiêu Khích lên mục tiêu; tối đa kích hoạt 1 lần mỗi 15 giây.\nKhiêu Khích: sát thương nhận vào tăng 2.2% trong 10 giây.",
    [418367932467456] = "Tấn Công +100, Tấn Công Đặc Biệt +150. Khi gây sát thương, Tấn Công và Tấn Công Đặc Biệt tăng thêm 265, 350 trong 10 giây, đồng thời cộng 1 tầng Tăng Thương lên mục tiêu.",
    [418367932467712] = "Tấn Công +370. Khi đánh thường trúng địch, Tấn Công tăng thêm 3.0% trong 8 giây; đánh thường còn cộng cho mục tiêu 1 tầng Thiết Hỏa.\nThiết Hỏa: mỗi giây chịu sát thương, kéo dài 4 giây, tối đa 3 tầng.",
    [418367932467968] = "Cường Hóa Kỹ Năng +80. Khi kỹ năng trúng địch, Cường Hóa Kỹ Năng tăng thêm 110 trong 10 giây và gây thêm 1 lần sát thương tại vị trí mục tiêu; tối đa kích hoạt 1 lần mỗi 20 giây.",
    [418367932468224] = "Tấn Công +185, Cường Hóa Kỹ Năng +40. Khi gây Sát Thương, tăng thêm 300 Tấn Công và 60 Cường Hóa Kỹ Năng trong 10 giây; mỗi 15 giây tối đa kích hoạt 1 lần.",
    [418367932468480] = "Tấn Công +300. Khi Đánh Thường trúng địch, Tấn Công tăng thêm 2.0% trong 10 giây.",
    [418367932468992] = "Cường Hóa Kỹ Năng tăng 60. Khi kỹ năng trúng kẻ địch, Cường Hóa Kỹ Năng tăng thêm 50 trong 10 giây; tối đa kích hoạt 1 lần mỗi 15 giây.",
    [418367932470272] = "Phá Phòng +250. Khi dùng Kỹ Năng Kết Liễu, Phá Phòng tăng thêm 250 và gây một lần sát thương tại vị trí mục tiêu; mỗi 12 giây tối đa kích hoạt 1 lần.",
    [418367932470528] = "Xuyên Thấu +7.0%. Khi dùng kỹ năng dịch chuyển, Xuyên Thấu tăng thêm 550 trong 10 giây, đồng thời gây một lần sát thương tại vị trí mục tiêu; mỗi 12 giây tối đa kích hoạt 1 lần.",
    [418367932470784] = "Xuyên Thấu +450, Phá Phòng +200. Khi dùng Kỹ Năng Kết Liễu hoặc kỹ năng dịch chuyển, Xuyên Thấu tăng thêm 160 trong 10 giây, đồng thời gây một lần sát thương tại vị trí mục tiêu; mỗi 12 giây tối đa kích hoạt 1 lần.",
    [418367932471040] = "Phá Phòng tăng 120. Khi dùng Kỹ Năng Kết Liễu, Phá Phòng tăng thêm 280 trong 10 giây; tối đa kích hoạt 1 lần mỗi 10 giây.",
    [418367932471552] = "Xuyên Thấu +170. Khi dùng kỹ năng Di Chuyển, Xuyên Thấu tăng thêm 430 trong 10 giây; mỗi 8 giây tối đa kích hoạt 1 lần.",
    [418367932472064] = "Phá Phòng +70, Xuyên Thấu +75.",
    [418367932474624] = "Bạo Kích +510; cấp Kỹ Năng Bí Ngẫu và Kỹ Năng Nhân Mạch +3.",
    [418367932475136] = "Bạo Kích +440. Dùng kỹ năng khiến Chuyên Công Con Đường tăng thêm 170 trong 10 giây; mỗi 20 giây tối đa kích hoạt 1 lần.",
    [418367932476416] = "Máu Tối Đa +430. Khi được Trị Liệu, Máu Tối Đa tăng thêm 430 và hiệu quả Trị Liệu nhận vào tăng 2.0% trong 8 giây.",
    [418367932476672] = "Phòng Thủ +240. Khi nhận Khiên, Phòng Thủ tăng thêm 220 và hiệu quả Khiên nhận vào +1.5%. Khi Sinh Mệnh dưới 30%, nhận Khiên tạm thời trong 5 giây; hồi chiêu 300 giây.",
    [418367932476928] = "Phòng Thủ +180, Sinh Mệnh Tối Đa +650. Khi nhận Hồi Phục hoặc Khiên, Phòng Thủ và Sinh Mệnh Tối Đa tăng thêm 170; hiệu quả Hồi Phục/Khiên nhận được tăng 0.6%. Khi Sinh Mệnh dưới 30%, nhận một lượng nhỏ Khiên tạm thời trong 5 giây, hồi chiêu 300 giây.",
    [418367932477184] = "Máu Tối Đa +720. Khi nhận Trị Liệu, Máu Tối Đa tăng thêm 720 trong 20 giây.",
    [418367932477696] = "Phòng Thủ +110. Khi nhận Khiên, Phòng Thủ tăng thêm 330 trong 20 giây.",
    [418367932478208] = "Phòng Ngự +70, Kháng Bạo Kích +80.",
    [418367932479488] = "Kháng Kỹ Năng +420.",
    [418367932482560] = "Chặn Đòn +240. Khi chịu Khống Chế, Chặn Đòn tăng thêm 190 trong 10 giây. Khi chịu Khống Chế Mạnh, hồi chiêu kỹ năng Giải Khống Chế giảm 1.5 giây; mỗi 25 giây tối đa kích hoạt một lần.",
    [418367932482816] = "Kháng Kỹ Năng +80. Khi bị tấn công, tăng thêm 80 Kháng Kỹ Năng trong 6 giây.",
    [418367932483072] = "Chặn Đòn +120, Kháng Kỹ Năng +40. Khi bị tấn công hoặc Khống Chế, tăng thêm 90 Chặn Đòn và 30 Kháng Kỹ Năng trong 10 giây. Khi chịu Khống Chế Mạnh, hồi chiêu kỹ năng Giải Khống Chế giảm 0.8 giây; mỗi 25 giây tối đa kích hoạt một lần.",
    [418367932483328] = "Chặn Đòn +190. Khi chịu Khống Chế, Chặn Đòn tăng thêm 120 trong 10 giây.",
    [418367932483840] = "Kháng Kỹ Năng +60. Khi bị tấn công, tăng thêm 40 Kháng Kỹ Năng trong 10 giây.",
    [418367932484352] = "Chặn Đòn +75, Kháng Kỹ Năng +25.",
    [418367932484864] = "Kháng Kỹ Năng +50.",
    [418369006209024] = "Tấn Công +600, Tấn Công Đặc Biệt +200. Khi gây trị liệu, Tấn Công và Tấn Công Đặc Biệt tăng thêm 240 trong 10 giây, đồng thời cộng cho mục tiêu 1 tầng Cường Ngự; tối đa kích hoạt 1 lần mỗi 15 giây.\nCường Ngự: sát thương nhận vào giảm 2.2% trong 10 giây.",
    [418369006209280] = "Tấn Công +100, Tấn Công Đặc Biệt +150. Khi gây trị liệu, Tấn Công và Tấn Công Đặc Biệt tăng thêm 265, 350 trong 10 giây, đồng thời cộng 1 tầng Tăng Thương lên mục tiêu.",
    [418369006209536] = "Tấn Công +370. Khi đánh thường gây trị liệu, Tấn Công tăng thêm 3.0% trong 8 giây; đánh thường còn cộng cho mục tiêu 1 tầng Minh Ước.\nMinh Ước: mỗi giây nhận trị liệu, kéo dài 4 giây, tối đa 3 tầng.",
    [418369006209792] = "Cường Hóa Kỹ Năng +80. Khi kỹ năng gây Trị Liệu, Cường Hóa Kỹ Năng tăng thêm 110 trong 10 giây, đồng thời tạo một lần Trị Liệu bổ sung tại vị trí mục tiêu; mỗi 20 giây tối đa kích hoạt 1 lần.",
    [418369006210048] = "Tấn Công +185, Cường Hóa Kỹ Năng +40. Khi gây Hồi Phục, tăng thêm 300 Tấn Công và 60 Cường Hóa Kỹ Năng trong 10 giây; mỗi 15 giây tối đa kích hoạt 1 lần.",
    [418369006210304] = "Tấn Công +300. Khi Đánh Thường gây Trị Liệu, Tấn Công tăng thêm 2.0% trong 10 giây.",
    [418369006210816] = "Cường Hóa Kỹ Năng tăng 60. Khi kỹ năng gây Trị Liệu, Cường Hóa Kỹ Năng tăng thêm 50 trong 10 giây; tối đa kích hoạt 1 lần mỗi 15 giây.",
    [418369006212096] = "Phá Phòng +250. Khi dùng Kỹ Năng Kết Liễu, Phá Phòng tăng thêm 250 và tạo một lần Trị Liệu tại vị trí mục tiêu; mỗi 12 giây tối đa kích hoạt 1 lần.",
    [418369006212352] = "Xuyên Thấu +7.0%. Khi dùng kỹ năng dịch chuyển, Xuyên Thấu tăng thêm 550 trong 10 giây, đồng thời tạo một lần Trị Liệu tại vị trí mục tiêu; mỗi 12 giây tối đa kích hoạt 1 lần.",
    [418369006212608] = "Xuyên Thấu +450, Phá Phòng +200. Khi dùng Kỹ Năng Kết Liễu hoặc kỹ năng dịch chuyển, Xuyên Thấu tăng thêm 160 trong 10 giây, đồng thời tạo một lần Trị Liệu tại vị trí mục tiêu; mỗi 12 giây tối đa kích hoạt 1 lần.",
    [426612390627328] = "Tán dương Kẻ Khờ! {{player.name}} trong Tụ Hợp Phi Phàm đã từ {{item.name}} đánh thức Dòng Thuộc Tính <Chat_Highlight>{{relic_word.name}}</> ngủ quên trong lịch sử. Đây là món quà không thuộc thời đại này, cũng là kỳ tích ngẫu nhiên trào lên giữa dòng sông Vận Mệnh!",
    [426612390628608] = "{{player.name}} trong Tụ Hợp Phi Phàm đã ngưng tụ Dòng Thuộc Tính <Chat_Highlight>{{relic_word.name}}</> vào {{item.name}}, nhận được sự quyến cố của Vua Vàng Đen chấp chưởng vận may!",
    [431010168703744] = "Nguyên Liệu",
    [431010168705536] = "Vật Liệu Ma Dược",
    [431010168706560] = "Tất Cả Trang Bị",
    [431078619831808] = "Vật Chất Phi Phàm - Tấn Công",
    [431078619832576] = "Vật Chất Phi Phàm - Phòng Thủ",
    [435545117296640] = "Thành Săn Rồng",
    [435545117297664] = "Dãy Núi Hornacis",
    [435545117298176] = "Backlund",
    [435613836773888] = "Khu Nam",
    [439944505984768] = "Vật nhiễm Linh Tính hình thành do sự kiện Phi Phàm tại địa phương; chạm để thu thập.\nTích đủ số lượng có thể tới một Kẻ Gác Đêm trong CLB để đổi thưởng.",
    [439945042857472] = "Điều khiển các loài động vật khác nhau qua Sợi Tơ Linh Thể có thể làm những việc vốn không thể.\nVí dụ, điều khiển một chú chuột nhỏ giúp bạn tìm chìa khóa Rương Báu bị giấu.",
    [440151201287168] = "Câu Chuyện Nhập Vai",
    [440151738159360] = "Bạn có thể nhìn thấy và chạm vào Sợi Tơ Linh Thể nối liền vạn vật. Sau khi khóa mục tiêu, thiết lập kết nối và cuối cùng tiếp quản ý thức, biến nó thành Bí Ngẫu. Đơn vị bị bạn khống chế sẽ nghe theo mệnh lệnh; hãy thận trọng khi sử dụng sức mạnh chi phối Vận Mệnh này.",
    [440151738160896] = "Vật nhiễm Linh Tính hình thành do sự kiện Phi Phàm tại địa phương; chạm để thu thập. Tích đủ số lượng có thể tới một Kẻ Gác Đêm trong CLB để đổi thưởng.",
    [440565128760064] = "“Thông Đạo” giữa bạn và Linh Giới đã được mở rộng. Bạn có thể nhanh chóng làm dịu nhiễu động Linh Tính, từ đó mở Linh Thị thường xuyên hơn. <Talent>Hồi chiêu kỹ năng 【Linh Thị】 -1 giây</>.",
    [440565128762624] = "Ở thời khắc quyết định của chiến đấu hoặc đối kháng, bạn có thể dồn toàn bộ uy thế và sức mạnh vào một điểm, tung ra đòn đánh hoặc phòng thủ chính xác áp đảo. <Talent>Khi kiểm định dựa trên 【Vũ Lực】, nhận Ưu Thế</>.",
    [440565128763648] = "Mỗi cuốn điển tịch tích lũy trong Thư Viện CLB đều là kết tinh kinh nghiệm mà các Phi Phàm Giả tiền bối đổi bằng sinh mệnh; còn những đồng đạo đưa tay tương trợ tại bước ngoặt vận mệnh là chỗ dựa đáng tin hơn bất kỳ Ma Dược nào. Tri thức và đồng bạn là sự Bảo Hộ vững chắc nhất trong thế giới Quỷ Bí.\n<Talent>Khi khám phá bản đồ Thế Giới Trật Tự, Giới Hạn Thể Lực tăng 10%</>.\n<Talent>Khi Tung Xúc Xắc, xác suất được thành viên CLB hỗ trợ tung lại tăng 30%</>.",
    [440565128763904] = "Mỗi cuốn điển tịch tích lũy trong Thư Viện CLB đều là kết tinh kinh nghiệm mà các Phi Phàm Giả tiền bối đổi bằng sinh mệnh; còn những đồng đạo đưa tay tương trợ tại bước ngoặt vận mệnh là chỗ dựa đáng tin hơn bất kỳ Ma Dược nào. Tri thức và đồng bạn là sự Bảo Hộ vững chắc nhất trong thế giới Quỷ Bí.\n<Talent>Khi khám phá bản đồ Thế Giới Trật Tự, Giới Hạn Thể Lực tăng 10%</>.\n<Talent>Khi Tung Xúc Xắc, xác suất được thành viên CLB hỗ trợ tung lại tăng 10%</>.",
    [440565128764416] = "Mỗi cuốn điển tịch tích lũy trong Thư Viện CLB đều là kết tinh kinh nghiệm mà các Phi Phàm Giả tiền bối đổi bằng sinh mệnh; còn những đồng đạo đưa tay tương trợ tại bước ngoặt vận mệnh là chỗ dựa đáng tin hơn bất kỳ Ma Dược nào. Tri thức và đồng bạn là sự Bảo Hộ vững chắc nhất trong thế giới Quỷ Bí.\n<Talent>Khi khám phá bản đồ Thế Giới Trật Tự, Giới Hạn Thể Lực tăng 10%</>.",
    [453276084474625] = "Vị Trí",
    [453276084474626] = "Khu Vực",
    [453413523517184] = "<DecH>Chế Tác:</> Lót lưới ・ Trang sức xích Linh Chất ・ Váy cắt chéo bất quy tắc\n“Ta sẽ nhớ lại những giấc mơ chúng ta từng cùng nhau tìm kiếm, nhớ lại từng vụ án Phi Phàm hay Vật Phong Ấn từng khiến chúng ta trăn trở, nhớ hướng gió thổi, cùng hình dạng và màu sắc của mặt trăng.”",
    [453413523794432] = "Trong những chuyến đi và trận chiến có bạn đồng hành, sẽ không còn bị nấm độc làm hại.",
    [453413523798016] = "<DecH>Công Nghệ:</> Da Đen Trầm · Bao Tay Chắc Chắn · Giáp Nhẹ Tụ Lực\nLời thì thầm dịu nhẹ hay cú đấm cuồng nhiệt đều có thể mang tới một giấc ngủ dài khó cưỡng.",
    [453413523798784] = "<DecH>Công Nghệ:</> Da Đen Trầm · Giáp Nhẹ Tụ Lực\nLời thì thầm dịu nhẹ hay cú đấm cuồng nhiệt đều có thể mang tới một giấc ngủ dài khó cưỡng.",
