    [466743759737600] = "Trang Sức",
    [470599029753600] = "Sau khi Xung Kích Mộng Yểm trúng mục tiêu Truy Kích, gây Trọng Thương trong 3 giây; hiệu quả Trọng Thương 66%.",
    [470599029754112] = "Trong thời gian hiệu lực, lượng trị liệu mục tiêu nhận được tăng 5%.",
    [470599029754624] = "Khi thi triển, giải Khống Chế; trong thời gian cưỡi sóng, miễn nhiễm hiệu ứng Giảm Tốc.",
    [470599029755904] = "Trong thời gian Bóng Tối Huyết Nhục tồn tại, khi chịu sát thương sẽ áp hiệu ứng Giảm Tấn Công 2 giây lên kẻ tấn công. Với cùng một mục tiêu, hiệu ứng này chỉ có hiệu lực 1 lần mỗi 1 giây.",
    [470599029756416] = "Mỗi khi mục tiêu chịu thêm sát thương do Ấn Ký Tử Linh, người thi triển hồi Máu một lần.",
    [470599029756672] = "Kẻ địch trúng Nấm Đặc Chế của Frank bị nhiễm sợi nấm; với 100% xác suất cơ bản, bị Giảm Tốc 25% trong 4 giây.",
    [470599029757184] = "Kẻ địch trúng đòn bị Thiêu Đốt, liên tục chịu sát thương trong 4 giây.",
    [470599566624768] = "Lượng Trị Liệu của Nghi Thức Thông Linh tăng 10%, sát thương tăng 10%.",
    [470599566627328] = "Sát thương bổ sung và lượng hồi Máu của Ấn Ký Tử Linh tăng 10%.",
    [470599566627840] = "Tăng Thương +2%; lượng Bạo Kích tăng thêm được tăng 30% so với giá trị gốc.",
    [470600103495168] = "Khi triển khai Hào Quang Tĩnh Lặng, có 85% xác suất cơ bản khiến mục tiêu địch trong phạm vi 6m xung quanh bị Trì Trệ 1.5 giây.",
    [470600103495936] = "Người có hiệu ứng Thẩm Thị lập tức xóa Giảm Tốc và Trì Trệ trên bản thân; trong thời gian hiệu lực sẽ không bị Giảm Tốc hoặc Trì Trệ.",
    [470600103496192] = "Sau khi trúng mục tiêu, mục tiêu trở thành Cơ Thể Nhiễm Điện, truyền điện giật sang tối đa 4 mục tiêu xung quanh và gây sát thương. Nếu xung quanh không có mục tiêu để truyền, sát thương lần này tăng 35%. Nếu mục tiêu là quái vật, sát thương tăng 75%.",
    [470600103496448] = "Sóng biển khiến mục tiêu chính có 100% xác suất cơ bản nhận Trì Trệ trong 2.5 giây.",
    [470600103498240] = "Hồi Chiêu Kỹ Năng giảm 3 giây.",
    [470600103499008] = "Triệu hồi 2 thiết bị bánh răng tấn công mục tiêu. Kẻ địch bị cả hai tia cùng trúng chịu tổng sát thương bằng 1.4 lần một tia.",
    [470600640369664] = "Mức tăng Cường Hóa Kỹ Năng tăng thêm 25% giá trị gốc; mức tăng Bạo Kích tăng thêm 30% giá trị gốc.",
    [470600640369920] = "Kẻ địch trúng đòn có 60% xác suất nhận Trọng Thương 66% trong 3 giây.",
    [470601177236992] = "Khi Kỹ Năng kết thúc, có 50% xác suất khiến kẻ địch trong phạm vi 8m rơi vào trạng thái Dẫn Dắt Ác Mộng (Ngủ) trong 1 giây.",
    [470601177237248] = "Sau khi Năng Lượng Bóng Tối của Xung Kích Mộng Yểm trúng mục tiêu, phân tách thành 2 Bóng Tối thứ cấp truy kích các kẻ địch khác trong phạm vi 8m, gây sát thương tương đương (không thêm Dấu Ấn Mộng Yểm), đồng thời gây Trọng Thương 60% trong 4 giây.",
    [470601177237504] = "Khi Sinh Mệnh đồng minh trong phạm vi Nghi Thức Thông Linh dưới 50%, lượng Hồi Phục lên họ tăng thêm 30%; khi Sinh Mệnh kẻ địch trong phạm vi trên 50%, Sát Thương lên chúng tăng thêm 30%.",
    [470601177237760] = "60% lượng Trị Liệu vượt mức của hiệu ứng Thẩm Thị chuyển thành Khiên trong 5 giây; lượng Khiên không vượt quá 0.5 lần Máu của người thi triển.",
    [470601177238016] = "Khi hiệu ứng Cơ Thể Nhiễm Điện kết thúc, chắc chắn chịu một lần Sát Thương Lôi Điện. Nếu mục tiêu là quái vật, sát thương tăng 75%.",
    [470601177238272] = "Sóng biển tạo một Xoáy Biển bán kính 6 m tại khu vực mục tiêu. Xoáy kéo mục tiêu xung quanh về trung tâm và giảm 15% Tốc Độ Di Chuyển; tồn tại 3 giây.",
    [470601177239296] = "Sau khi nhặt 4 Bánh Quy Thú Cưng Backlund, nhận Khiên bằng 5% Giới Hạn Sinh Mệnh trong 8 giây.",
    [470601177239552] = "Khi dùng kỹ năng, nếu tỷ lệ Sinh Mệnh không dưới 50%, nhận thêm 8% Giảm Thương trong 5 giây; nếu dưới 50%, nhận một lượng Hồi Phục.",
    [470601177240064] = "Khi Ấn Ký Tử Linh kết thúc sẽ phát nổ, gây sát thương phạm vi nhỏ. Sát thương phụ thuộc số lần chịu sát thương bổ sung trong thời gian hiệu lực; số lần càng nhiều, sát thương càng cao. Với mục tiêu quái vật, sát thương tăng thêm 75%.",
    [470601177240320] = "Hồi Máu cho người thi triển dựa trên sát thương vụ nổ Nấm; vụ nổ trúng càng nhiều mục tiêu, lượng Máu hồi càng nhiều.",
    [470601177240832] = "Sau khi bắn xong tia sáng, Thiết Bị Bánh Răng sẽ tự bay tới mục tiêu và gây Sát Thương.",
    [470936453123840] = "Công Ty An Ninh Blackthorn",
    [470936453129984] = "Tingen",
    [471073086768640] = "Cường hóa sát thương, tăng hiệu ứng Sợ Hãi và Giảm Thuộc Tính.",
    [471073086769152] = "Cấp Khiên và trị liệu cho mục tiêu.",
    [471073086770432] = "Giảm Kháng Kỹ Năng và Trì Trệ của mục tiêu.",
    [471073892075008] = "【Phong Văn】 Sau khi Xung Kích Mộng Yểm trúng mục tiêu chính, năng lượng bóng tối bùng nổ, gây sát thương phạm vi.",
    [471073892075264] = "【Tin Đồn】Khi dùng Nghi Thức Thông Linh sẽ triệu hồi Linh Thể Dunn, tăng 10% Tốc Độ Di Chuyển cho đồng minh trong phạm vi và giảm 10% Tốc Độ Di Chuyển của địch trong phạm vi.",
    [471073892075520] = "【Phong Văn】 Khi hiệu ứng Quan Sát tồn tại, nếu Máu mục tiêu dưới 20%, lập tức hồi 15% Máu tối đa của mục tiêu, nhưng không vượt 20% Sinh Mệnh của người thi triển; chỉ có hiệu lực 1 lần. Nếu hiệu ứng không kích hoạt, trong 5 giây người thi triển có thể dùng kỹ năng lần 2 để lập tức Trị Liệu mục tiêu.",
    [471073892076032] = "【Phong Văn】 Gây hiệu ứng Dòng Điện lên mục tiêu bị khóa trong 3 giây, mỗi giây gây 1 lần sát thương.",
    [471073892076544] = "【Tin Đồn】Đồng minh và bản thân mỗi giây nhận hiệu ứng Thi Ý; Thi Ý tăng Chuyên Công Con Đường của bản thân và đồng minh. Bán kính Hào Quang Thi Ý là 6 mét.",
    [471073892076800] = "【Phong Văn】 Sau khi Mộng Yểm trúng mục tiêu, làm suy yếu Kháng Kỹ Năng của mục tiêu trong 5 giây.",
    [471073892077056] = "【Phong Văn】 Móng Vuốt Tử Vong tạo Ma Pháp Nghi Thức tại vị trí mục tiêu, gây 3 lần sát thương với mức sát thương tăng dần.",
    [471073892077312] = "【Phong Văn】 Sau khi Mộng Yểm trúng mục tiêu, tạo Ma Pháp Nghi Thức tại vị trí mục tiêu. Nghi thức tồn tại 6 giây và mỗi giây gây sát thương lên kẻ địch trong phạm vi.",
    [471073892077568] = "【Phong Văn】 Móng Vuốt Tử Vong được thêm kỹ năng giai đoạn hai — Nắm Giữ Tử Vong, gây một lượng nhỏ Sát Thương lên mục tiêu; nếu mục tiêu có Tử Vong Xâm Thực, Sát Thương tăng.",
    [471073892078080] = "【Phong Văn】 Sau khi hoàn thành Nghi Thức Chuyển Vận, thả Đèn Lịch Sử cho đồng minh xung quanh, giúp họ nhận một lượng nhỏ Khiên trong 10 giây và Dấu Đèn Lịch Sử.",
    [471074428945920] = "【Thiển Kiến】 Người chơi bị vụ nổ Năng Lượng Bóng Tối trúng có 30% xác suất bị Sợ Hãi trong 1.2 giây. Tỷ lệ trúng và thời gian thực tế của Sợ Hãi chịu ảnh hưởng bởi thuộc tính liên quan đến Choáng.",
    [471074428946432] = "【Thiển Kiến】 Khi kích hoạt hiệu ứng lập tức hồi Máu lúc dưới 20%, mục tiêu nhận thêm 20% Giảm Thương trong 5 giây.",
    [471074428946944] = "【Thiển Kiến】 Trong thời gian Dòng Điện, sát thương Dòng Điện mục tiêu phải chịu có xác suất dao động trong khoảng 100%–150%.",
    [471074428947200] = "【Thiển Kiến】 Sau khi dùng kỹ năng giai đoạn hai Gia Trì Sương Xám hoặc Áp Chế Sương Xám, tăng Kháng Khống Chế của bản thân trong 10 giây.",
    [471074428947456] = "【Thiển Kiến】 Mỗi lần bản thân hoặc đồng minh trong Hào Quang Tĩnh Lặng tấn công mục tiêu sẽ hồi một lượng nhỏ Sinh Mệnh; trong 1 giây tối đa kích hoạt 1 lần. Bán kính Hào Quang Thi Ý tăng 2 m.",
    [471074428947712] = "【Thiển Kiến】 Sau khi Ác Mộng Tập Kích trúng mục tiêu, giảm một lượng Khiên của mục tiêu; nếu mục tiêu không có Khiên, kỹ năng này giảm thêm Kháng Kỹ Năng của mục tiêu.",
    [471074428947968] = "【Thiển Kiến】 Ma Pháp Nghi Thức do Móng Vuốt Tử Vong tạo ra gây thêm 5% Giảm Tốc và 30% Trọng Thương trong 4 giây. Hiệu ứng Giảm Tốc có thể cộng dồn.",
    [471074428948224] = "【Thiển Kiến】 Sau khi Ác Mộng trúng mục tiêu, có 30% xác suất cơ bản áp Trì Trệ trong 3 giây; Nghi Thức Ma Pháp tạo ra kèm 5% Giảm Tốc.",
    [471074428948736] = "【Thiển Kiến】 Cờ Đế Quốc cộng 1 tầng Vặn Vẹo lên mục tiêu trong phạm vi mỗi 4 giây (Vặn Vẹo: giảm Kháng Khống Chế), tối đa 3 tầng.",
    [471074428948992] = "【Thiển Kiến】 Khi Khiên Minh Đăng kết thúc, gây một vụ nổ, gây sát thương lên tối đa 2 mục tiêu quanh Khiên.",
    [471074965817088] = "【Thực Chứng】Hiệu quả Tăng Tốc tăng lên 15%, hiệu quả Giảm Tốc tăng lên 15%.",
    [471074965817856] = "【Thực Chứng】Thời gian hiệu ứng Điện Lưu tăng 1 giây, sát thương tăng 5%.",
    [471074965818624] = "Với Liên Kết 【Thực Chứng】, mức giảm Kháng Kỹ Năng từ 【Tin Đồn】 được tăng thêm.",
    [471074965819648] = "【Thực Chứng】 Mỗi lần cộng dồn Vặn Vẹo đồng thời gây một lần sát thương; nếu mục tiêu đang có Khiên, sát thương tăng lên 1.5 lần.",
    [471074965819904] = "【Thực Chứng】Lượng Khiên của Minh Đăng tăng 10%, sát thương vụ nổ tăng 30%.",
    [471075502688000] = "【Ẩn Tích】Khi bản thân ở trong phạm vi Nghi Thức Thông Linh sẽ miễn nhiễm Giảm Tốc. Kẻ địch trong phạm vi Nghi Thức Thông Linh sẽ ở trạng thái Trì Trệ.",
    [471075502688256] = "【Ẩn Tích】 Khi kích hoạt hiệu ứng hồi Sinh Mệnh tức thì dưới 20%, mục tiêu nhận thêm Bá Thể trong 4 giây.",
    [471075502688768] = "【Ẩn Tích】Mỗi đòn tấn công có 10% xác suất tăng thời gian hiệu ứng Điện Lưu thêm 1 giây, tối đa thêm 5 giây; mỗi 0.5 giây tối đa kích hoạt 1 lần.",
    [471075502689024] = "【Ẩn Tích】Trong thời gian được Sương Xám gia trì, mỗi lần hồi Thể Lực bằng kỹ năng sẽ tăng thêm Giáp cho bản thân, cộng dồn tối đa 3 tầng trong 5 giây.",
    [471075502689536] = "【Ẩn Tích】 Sau khi Tập Kích Mộng Yểm trúng mục tiêu, gây Trì Trệ trong 3 giây.",
    [471075502689792] = "【Ẩn Tích】 Khi hiệu ứng Giảm Tốc từ Nghi Thức Ma Pháp do Móng Vuốt Tử Vong tạo ra cộng đủ 3 tầng, có 36% xác suất cơ bản khiến mục tiêu Sợ Hãi trong 1 giây.",
    [471075502690048] = "【Ẩn Tích】 Người chơi địch trong Nghi Thức Ma Pháp nhận hiệu ứng Sinh Mệnh Trôi Mất: giảm 8% Sinh Mệnh Tối Đa.",
    [471075502690304] = "【Ẩn Tích】 Bàn Tay Tử Vong gây cùng một lượng sát thương lên kẻ địch và mọi mục tiêu trong phạm vi 6m quanh nó.",
    [471075502690816] = "【Ẩn Tích】 Mục tiêu bị ảnh hưởng bởi vụ nổ Khiên của Minh Đăng chịu sát thương Thiêu Đốt mỗi giây trong 4 giây.",
    [471076039558912] = "【Bí Tân】Hiệu quả Tăng Tốc tăng lên 20%, hiệu quả Giảm Tốc tăng lên 20%.",
    [471076039560448] = "【Bí Tân】 Tăng thêm 1 giây thời lượng hiệu ứng giảm Kháng Kỹ Năng và Trì Trệ.",
    [471076039561472] = "【Bí Tân】Mỗi lần cộng một tầng hiệu ứng Vặn Vẹo, sát thương gây ra tăng 30%.",
    [471076039561728] = "【Bí Tân】Lượng Khiên của Minh Đăng tăng 10%, sát thương vụ nổ tăng 30%.",
    [471076576429568] = "【Bản Tướng】 Khi sát thương kích nổ của Xung Kích Ác Mộng trúng từ 3 kẻ địch trở lên, tạo một Lõi Ác Mộng; sau 1 giây Lõi Ác Mộng phát nổ, gây sát thương phạm vi.",
    [471076576429824] = "【Bản Tướng】Sau khi đồng minh rời phạm vi Nghi Thức Thông Linh, hiệu ứng Tăng Tốc được duy trì thêm 2 giây. Sau khi kẻ địch rời phạm vi Nghi Thức Thông Linh, hiệu ứng Giảm Tốc được duy trì thêm 2 giây.",
    [471076576430080] = "【Bản Tướng】 Nếu chưa kích hoạt hiệu ứng lập tức hồi Máu khi dưới 20%, giảm thêm 2 giây hồi chiêu của kỹ năng này.",
    [471076576430592] = "【Bản Tướng】 Trong thời gian Dòng Điện duy trì, một Trường Tĩnh Điện bám theo mục tiêu sẽ xuất hiện dưới chân mục tiêu, liên tục gây sát thương lên kẻ địch trong phạm vi trong 5 giây.",
    [471076576430848] = "【Bản Tướng】 Sau khi dùng kỹ năng giai đoạn hai Gia Trì Sương Xám hoặc Áp Chế Sương Xám, giảm 3 giây hồi chiêu kỹ năng Giải Khống của bản thân.",
    [471076576431104] = "【Bản Tướng】 thêm lần 2 — Thi Phẩm Hợp Tấu: Sau khi dùng, nhận hiệu ứng Hợp Tấu. Nếu bản thân và đồng minh đang có Hợp Tấu cùng gây sát thương lên một mục tiêu, gây thêm sát thương bằng 10% Sinh Mệnh mục tiêu đã mất (không vượt 23.7% Tấn Công bản thân). Cùng một mục tiêu chỉ kích hoạt 1 lần mỗi 2 giây; kéo dài 10 giây.",
    [471076576431360] = "【Bản Tướng】 Sau khi Mộng Yểm trúng mục tiêu địch, mục tiêu mang Hào Quang Tĩnh Lặng trong 6 giây; hào quang này làm giảm Kháng Kỹ Năng của các mục tiêu địch xung quanh.",
    [471076576431616] = "【Bản Tướng】 Ở lần gây Sát Thương thứ 3 của Nghi Thức Ma Pháp, Sát Thương lên mục tiêu có Tử Vong Xâm Thực tăng thêm 150%; với mục tiêu không có Tử Vong Xâm Thực, có 16% xác suất áp Tử Vong Xâm Thực.",
    [471076576432128] = "【Bản Tướng】 Mỗi mục tiêu Bàn Tay Tử Vong trúng sẽ giảm 1 giây hồi chiêu của bản thân, tối đa giảm 4 giây.\nMỗi mục tiêu Bàn Tay Tử Vong trúng còn bị rút 1 Mảnh Linh Hồn. Sau khi rút đủ 10 Mảnh Linh Hồn, tạo một Vong Linh tại vị trí mục tiêu; sau 3 giây, Vong Linh thực hiện Thu Hoạch Linh Hồn, gây sát thương lên mục tiêu xung quanh.\nNếu sát thương kết liễu mục tiêu, tính là rút 2 mảnh.",
    [471076576432384] = "【Bản Tướng】 Khi cắm Cờ Đế Quốc, lá cờ gây sát thương lên mục tiêu địch trong phạm vi; gây thêm 50% sát thương lên cờ khác hoặc mục tiêu có Khiên trong phạm vi.",
    [471076576432640] = "【Bản Tướng】 Khi dùng Gia Trì Sương Xám hoặc Áp Chế Sương Xám, đồng minh có Dấu Đèn Lịch Sử trên người nhận thêm Khiên, đồng thời xóa Dấu Đèn Lịch Sử; khi Khiên này kết thúc sẽ không gây Sát Thương lên mục tiêu xung quanh.",
    [475127267460608] = "Chưa Mở Khóa",
    [475127804333312] = "　　Leonard cười với vẻ bất cần đời: “Klein, giữa chúng ta không cần giả vờ. Tôi từng tận mắt thấy cậu thoát khỏi sự khống chế của Vật Phong Ấn ‘2-049’, biết cậu có chỗ đặc biệt; còn cậu hẳn cũng mơ hồ cảm nhận được tôi khác với Phi Phàm Giả bình thường.”\n　　Anh thu lại nụ cười, nhìn thẳng vào Klein:\n　　“Tôi từng nói với cậu rồi, trên thế giới này có rất nhiều người đặc biệt, luôn làm được những chuyện người khác không thể làm. Ví dụ như cậu, cũng ví dụ như tôi.”\n　　“Thế giới này có lịch sử rất dài, tồn tại đủ loại vật phẩm thần kỳ. Luôn sẽ có người có được chúng, nắm giữ chúng, trở thành nhân vật chính của những vở kịch khác nhau. Những người như vậy sẽ không quá nhiều, nhưng chắc chắn không thể chỉ có một hai người.”\n\n　　——Quyển 1 《Chú Hề》, Chương 121: “Suy Đoán” Của Leonard",
    [475127804333824] = "Leonard Mitchell — một cái tên rất giống thi nhân.\n——Dù bản thân anh chẳng biết làm thơ.\nMột thi nhân không biết làm thơ, nghe thôi đã đầy tính kịch; cũng rất hợp với kỳ vọng anh từng dành cho chính mình — nhân vật chính của câu chuyện, vận mệnh đặc biệt, cuộc đời truyền kỳ.\nBan đầu, mọi thứ quả thật phát triển theo hướng ấy: anh thuận lợi trở thành Phi Phàm Giả, nắm giữ vài “bí mật”, quen những đồng đội đáng tin, vô số lần bảo vệ Tingen. Bánh xe lịch sử cuồn cuộn tiến lên, chưa từng bạc đãi anh vì tính lười nhác. Có lẽ đó chính là cấu hình tiêu chuẩn của nhân vật chính: một chút thiên phú hơn người, một nhóm bằng hữu sống chết có nhau, một hành trình khác thường……\n\nNhững tháng ngày bình thản, tốt đẹp và nhàm chán biết bao.\nCho tới khi Tà Thần giáng lâm, vô tình nghiền nát tất cả.\n\nLeonard Mitchell không phải đứa con được vận mệnh ưu ái.\nChỉ là một phàm nhân yếu ớt mà không tự biết.\n\nNhưng dù là phàm nhân cũng sẽ không ngừng bước về phía trước, như ngôi sao tuy nhỏ bé nhưng vẫn luôn cố gắng phát sáng.\nAnh thu lại vẻ lười nhác, bước lên con đường trưởng thành lặng lẽ.\nAnh trở thành Găng Tay Đỏ.\nAnh trở thành “Ngôi Sao”.\nAnh hoàn thành báo thù.\n——Nhưng anh vẫn không biết làm thơ.\n\n“Thì có sao đâu? Tôi rất hài lòng với mình hiện tại.\n“Một Thi Nhân Nửa Đêm không biết làm thơ mới là phần quan trọng nhất trong linh hồn tôi.\n“Như vậy, dù tôi đi trên con đường Phi Phàm bao lâu, dù tới gần điên cuồng và Mất Kiểm Soát đến đâu……\n“Chỉ cần vẫn còn những thứ này, tôi sẽ luôn nhớ mình thuộc về đâu.\n“Điên cuồng và đau khổ sẽ vĩnh viễn không thể làm tổn thương tôi.”",
    [475127804336128] = "　　Daly khó nhọc nở nụ cười, vừa chống lại lớp lông trắng và vảy đen không ngừng mọc trên cơ thể vừa nói:\n　　“Thì ra là cậu……\n　　“Trước đây cậu chẳng phải đã hỏi tôi vì sao không chủ động, chủ động tỏ tình với Dunn rồi đẩy anh ấy lên giường sao?”\n　　Cô hít một hơi, cười cay đắng:\n　　“Trước kia tôi từng quá phóng túng. Anh ấy, anh ấy là người bảo thủ, tôi…… tôi rất tự ti.”\n　　Cô đã gần như không thể khống chế, sắp biến thành quái vật.\n　　Đúng lúc ấy, cô nghe Klein Moretti trả lời:\n　　“Đội trưởng thật ra rất thích cô, nhưng cô quá xuất sắc, quá trẻ, nên anh ấy cũng rất tự ti.”\n　　Daly mỉm cười. Trong tầm nhìn mơ hồ, cô bỗng thấy người đàn ông mặc áo khoác đen, đường chân tóc khá cao, đôi mắt xám sâu thẳm. Anh đặt tay trước ngực, cúi người đưa tay, mời cô khiêu vũ.\n　　Cô đưa tay ra; suy nghĩ theo đó dần trở nên Trì Trệ.\n　　Người đàn ông mắt xám áo đen kéo Daly, khi dị biến trên người cô dần rút đi, cùng nhảy một điệu nhẹ nhàng giữa ánh mắt Leonard, giữa quảng trường đổ nát với dòng nước đài phun hỗn loạn.\n　　Từng loại nguyên liệu bay ra: dây nho vàng, chiếc mặt nạ cao su khá xấu xí…… Dưới sự dẫn dắt của Linh Tính, chúng dần hòa quyện rồi rót vào một chiếc lọ kim loại nhỏ.\n　　Trong điệu nhảy tuyệt đẹp, Daly khẽ nghiêng người, tựa vào lòng Dunn.\n\n　　——Quyển 4 《Kẻ Bất Tử》, Chương 213: Khúc Vĩ Thanh Của Câu Chuyện",
    [475127804340224] = "Một chú chó Golden Retriever huyết thống không mấy thuần, món tặng kèm khi mua chó săn cáo. Thế giới của cô từng rất đơn giản: ánh nắng, sân vườn, bánh quy và cô bé luôn cười rồi ngồi xổm xuống xoa đầu cô.\nCho tới khi bình ma dược ấy vô tình bị đổ.\nVận mệnh chưa bao giờ hỏi xin sự đồng ý của ai. Khi Đặc Tính Phi Phàm thấm vào bộ lông, máu, xương và cả trái tim ngây thơ đang đập ấy, Susie có được tia “ý thức” đầu tiên. Cô hiểu được nhiều hơn — sự im lặng dưới những lời nói, mệt mỏi phía sau nụ cười, và cả nỗi cô đơn Audrey mang theo khi ở một mình giữa đêm khuya mà có lẽ chính cô ấy cũng chưa nhận ra.\nSusie chưa bao giờ che giấu mình là một con chó. Đó là niềm kiêu hãnh của cô. Chó có thể ngửi ra lời dối trá, còn con người chỉ nghe được ngôn từ; chó có thể dùng chiếc đuôi nói hết lòng thật, còn con người học cách xây tường bằng nụ cười. Khi nằm trên thảm nhà Hall, quan sát những vị khách qua lại, cô nhìn thấy nhiều hơn bất kỳ vị khách nào — những lời lấy lòng giả dối, ánh mắt tính toán, sự đố kỵ ẩn dưới lời ca tụng.\nCô từng nghĩ: là một con chó có trí tuệ, bạn thấy mình giống người hơn hay giống chó hơn?\nCô vẫy đuôi và tìm ra câu trả lời của mình.\n“Ta giống chính ta hơn. Một chú Golden Retriever đã học nói nhưng vẫn thích đuổi theo đuôi mình; một Sinh Vật Phi Phàm đã đọc hết nhân tính trong tâm lý học nhưng vẫn tin vào lòng tốt. Không cần trở thành người, ta vẫn có thể dùng một đôi mắt khác biệt để mang đến một khoảng bình yên ấm áp cho mọi tâm hồn cô độc.”\n\n“Dù sao, ta chỉ là một con chó. Và đó, vừa hay, lại là điều ta giỏi nhất.”",
    [475127804342784] = "Old Neil, một trong những tiền bối lâu năm nhất của Blackthorn. Ông dạy bạn Thiền Định, Linh Thị, thậm chí cả cách “điền số hợp lý” trên đơn hoàn phí. Nhưng khi bản thân đang nợ ba mươi bảng, ông vẫn không lấy một xu từ chiếc ví ba trăm bảng nhặt được.\n“Muốn làm gì thì làm, nhưng đừng gây tổn thương” là châm ngôn ông giữ suốt đời.\nÔng từng là Kẻ Gác Đêm chính thức, nhưng luôn thiếu một bước để thăng cấp. Tuổi cao dần, Giáo Hội đề nghị ông chuyển sang làm “Người Canh Giữ” hoặc về nhà dưỡng lão, nhưng ông từ chối. Ông chỉ muốn ở lại Blackthorn, trông coi những điển tịch ngả vàng và thắp một ngọn đèn cho mọi người.\nGiữa những ngày tháng vui vẻ, hài hước, không ai biết Old Neil vẫn luôn tiết kiệm tiền, cố dùng nghi thức “Luyện Thành Sinh Mệnh” cấm kỵ để hồi sinh người vợ đã mất. Bên cạnh công thức cần máu, ông viết: “Có thể cân nhắc rút máu của tôi.” — ông thà dùng máu mình còn hơn làm hại người khác.\nCho tới khi lời thì thầm của Hiền Giả Ẩn Nặc nuốt chửng ông, đồng đội phải tự tay tiễn ông đi… Khi Kẻ Gác Đêm mở nhật ký Old Neil và thấy trang cuối viết: “Nếu không thể cứu cô ấy, vậy thì đi cùng cô ấy.”, họ mới hiểu sự kiên trì cuối cùng của ông.\nÔng muốn dùng quãng đời còn lại để soi sáng một đoạn đường ngắn cho người trẻ, rồi dùng chính sinh mệnh thực hiện lời thề không ai biết.",
