    [527766923710720] = "Nhận Vật Chất Phi Phàm",
    [527766923712000] = "Chọn Giáo Đoàn và cộng điểm thuộc tính",
    [527767191948544] = "<Assistant_Title1>【Loạn Đấu CLB】</>\n<Assistant_Title2>Bối Cảnh:</><Assistant_System>Loạn Đấu CLB</> bắt nguồn từ một Vật Phong Ấn dạng đĩa gương có năng lực Học Giả Cổ Đại. Người chơi tạm thời dùng năng lực Học Giả Cổ Đại như <Assistant_Property1>Triệu Hồi Sư</>, triệu hồi <Assistant_Property1>Hình Chiếu Lịch Sử</> để đối chiến. Hình chiếu lấy trạng thái người chơi tại một thời điểm quá khứ và tạo hình tương ứng.\n<Assistant_Title2>Mở:</> Đăng ký lúc <Assistant_Red>12:00</> trưa Thứ Ba, Thứ Năm; chiến đấu <Assistant_Red>19:00~20:30</> (giải đầu tiên server đăng ký <Assistant_Red>12:00 trưa</> Thứ Bảy).\nSố vòng mở dựa trên <Assistant_Property2>số người tham gia</> kỳ trước (giải đầu tiên trong CLB dựa theo <Assistant_Property2>số thành viên</>).\n<Assistant_Title2>Điều Kiện:</> CLB trên <Assistant_Red>20</> thành viên, Độ Hoạt Động trên <Assistant_Red>100</>.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Loạn Đấu CLB-Luật Chơi]|9}，{SendAnswer:[Loạn Đấu CLB-Luật Tính Điểm]|10}",
    [527767191948800] = "<Assistant_Title1>【CLB Loạn Đấu - Quy Tắc】</>\nKhi mở đăng ký, lối chơi ngẫu nhiên chọn <Assistant_Red>16</> thành viên CLB làm <Assistant_Property1>Huyễn Tượng Chiếu Ảnh</> cho người tham gia sử dụng. Tất cả người tham gia có cùng tập loại Chiếu Ảnh.\nTrận đấu gồm nhiều vòng. Người chơi có thể chọn Chiếu Ảnh đưa vào <Assistant_Property1>bất kỳ vòng nào</>; Chiếu Ảnh đã dùng <Assistant_Property1>không thể dùng lại</>.\nKhi vòng chỉ định bắt đầu, các Chiếu Ảnh của vòng đó được triệu hồi và <Assistant_Property1>tự động chiến đấu</>. Người tham gia có thể tới Trụ Sở CLB để <Assistant_Property1>quan chiến</>.\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[CLB Loạn Đấu]|8}, {SendAnswer:[CLB Loạn Đấu - Quy Tắc Tính Điểm]|10}",
    [527767191949056] = "<Assistant_Title1>【Loạn Đấu CLB - Quy Tắc Tính Điểm】</>\nNgười chơi tích điểm theo biểu hiện của Hình Chiếu trên chiến trường:\nTheo thứ hạng sống sót, ba Hình Chiếu đứng đầu lần lượt nhận <Assistant_Red>60,40,30</> điểm;\nMỗi khi Hình Chiếu khác bị hạ, Hình Chiếu của bản thân nhận <Assistant_Red>3</> điểm;\nHạ Hình Chiếu khác nhận <Assistant_Red>5</> điểm.\nNgười chơi cần đưa vào ít nhất <Assistant_Red>8</> Hình Chiếu để nhận thưởng. Sau trận, người có tổng điểm cao và Hình Chiếu có dữ liệu nổi bật sẽ nhận thêm phần thưởng <Assistant_Property1>Danh Hiệu</>.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Loạn Đấu CLB]|8}，{SendAnswer:[Loạn Đấu CLB - Quy Tắc Lối Chơi]|9}",
    [527767191949312] = "<Assistant_Title1>【Hồ Sơ Blackthorn】</>\n<Assistant_Title2>Giải Thích Lối Chơi:</> Công việc chính của Công Ty An Ninh Blackthorn là xử lý các sự kiện Phi Phàm xảy ra ở Tingen. Sau khi gia nhập công ty, bạn cần xử lý đủ loại vụ án.\n<Assistant_Title2>Tham Gia:</> Sau khi Phi Phàm Giả đạt <Assistant_Property1>Cấp 19</>, nhấn <Assistant_System>Menu-Mạo Hiểm Thế Giới-Phó Bản-Hồ Sơ Blackthorn</>.\n<Assistant_Title2>Phần Thưởng:</> Rương Mạo Hiểm Thế Giới, Trang Bị Vàng, Vật Chất Phi Phàm, v.v. Mỗi ngày 1 lượt thưởng.",
    [527767191949568] = "<Assistant_Title1>【Chợ Đen Gào Thét】</>\n<Assistant_Title2>Loại Lối Chơi:</><Assistant_Property1>Hồ Sơ Blackthorn</>\n<Assistant_Title2>Tham Gia:</> Phi Phàm Giả từ <Assistant_Property1>Cấp 40</>, chọn <Assistant_System>Menu - Mạo Hiểm Thế Giới - Phó Bản - Hồ Sơ Blackthorn - Chợ Đen Gào Thét</>.\n<Assistant_Title2>Số Người:</> Tổ đội 5~6 người hoặc chọn chế độ Máy.\n<Assistant_Title2>Phần Thưởng:</> Trang bị Vàng Cấp Trang Bị 45, Vật Chất Phi Phàm, v.v. Mỗi ngày 1 lượt thưởng <Assistant_Red>(dùng chung lượt thưởng Hồ Sơ Blackthorn)</>.\n<Assistant_Title2>Hướng Dẫn Boss:</>{JumpToUI:[Lambert Thòng Lọng]|1302136}",
    [527767191949824] = "<Assistant_Title1>【Góc Dòm Bí】</>\n<Assistant_Title2>Loại Lối Chơi:</><Assistant_Property1>Hồ Sơ Blackthorn</>\n<Assistant_Title2>Tham Gia:</> Phi Phàm Giả từ <Assistant_Property1>Cấp 19</>, chọn <Assistant_System>Menu - Mạo Hiểm Thế Giới - Phó Bản - Hồ Sơ Blackthorn - Góc Dòm Bí</>.\n<Assistant_Title2>Số Người:</> Tổ đội 5~6 người hoặc chọn chế độ Máy.\n<Assistant_Title2>Phần Thưởng:</> Trang bị Vàng Cấp Trang Bị 35, Vật Chất Phi Phàm, v.v. Mỗi ngày 1 lượt thưởng <Assistant_Red>(dùng chung lượt thưởng Hồ Sơ Blackthorn)</>.\n<Assistant_Title2>Hướng Dẫn Boss:</>{JumpToUI:[Carl Edgar]|1302139}",
    [527767191950080] = "<Assistant_Title1>【Tội Vàng】</>\n<Assistant_Title2>Loại Lối Chơi:</><Assistant_Property1>Hồ Sơ Blackthorn</>\n<Assistant_Title2>Tham Gia:</> Phi Phàm Giả từ <Assistant_Property1>Cấp 47</>, chọn <Assistant_System>Menu - Mạo Hiểm Thế Giới - Phó Bản - Hồ Sơ Blackthorn - Tội Vàng</>.\n<Assistant_Title2>Số Người:</> Tổ đội 5~6 người hoặc chọn chế độ Máy.\n<Assistant_Title2>Phần Thưởng:</> Trang bị Vàng Cấp Trang Bị 55, Vật Chất Phi Phàm, v.v. Mỗi ngày 1 lượt thưởng <Assistant_Red>(dùng chung lượt thưởng Hồ Sơ Blackthorn)</>.\n<Assistant_Title2>Hướng Dẫn Boss:</>{JumpToUI:[Locke King]|1302137}",
    [527767191950336] = "<Assistant_Title1>【Dấu Vết Người Chết】</>\n<Assistant_Title2>Loại Lối Chơi:</><Assistant_Property1>Hồ Sơ Blackthorn</>\n<Assistant_Title2>Tham Gia:</> Phi Phàm Giả từ <Assistant_Property1>Cấp 53</>, chọn <Assistant_System>Menu - Mạo Hiểm Thế Giới - Phó Bản - Hồ Sơ Blackthorn - Dấu Vết Người Chết</>.\n<Assistant_Title2>Số Người:</> Tổ đội 5~6 người hoặc chọn chế độ Máy.\n<Assistant_Title2>Phần Thưởng:</> Trang bị Vàng Cấp Trang Bị 60, Vật Chất Phi Phàm, v.v. Mỗi ngày 1 lượt thưởng <Assistant_Red>(dùng chung lượt thưởng Hồ Sơ Blackthorn)</>.\n<Assistant_Title2>Hướng Dẫn Boss:</>{JumpToUI:[Abaddon]|1302138}",
    [527767191950592] = "<Assistant_Title1>【Chế Độ Gác Đêm】</>\n<Assistant_Title2>Loại Lối Chơi:</><Assistant_Property1>Hồ Sơ Blackthorn</>\n<Assistant_Title2>Tham Gia:</> Phi Phàm Giả từ <Assistant_Property1>Cấp 57</>, chọn <Assistant_System>Menu - Mạo Hiểm Thế Giới - Phó Bản - Hồ Sơ Blackthorn - Chế Độ Gác Đêm</>.\n<Assistant_Title2>Số Người:</> Tổ đội 5~6 người hoặc chọn chế độ Máy.\n<Assistant_Title2>Phần Thưởng:</> Trang bị Vàng Cấp Trang Bị 60, Vật Chất Phi Phàm, v.v. Mỗi ngày 1 lượt thưởng <Assistant_Red>(dùng chung lượt thưởng Hồ Sơ Blackthorn)</>.\n<Assistant_Title2>Hướng Dẫn Boss:</>{JumpToUI:[Chế Độ Gác Đêm]|1302142}",
    [527767191950848] = "<Assistant_Title1>【Thảm Họa Thế Giới】</>\n<Assistant_Title2>Giải Thích:</> Thảm Họa Thế Giới là Boss thế giới xuất hiện định kỳ <Assistant_System>Trái Tim Steam</>, có cơ chế và phần thưởng riêng.\n<Assistant_Title2>Tham Gia:</> Phi Phàm Giả từ <Assistant_Red>Cấp 20</> có thể vào qua <Assistant_System>Menu - Phiêu Lưu Thế Giới - Thảm Họa Thế Giới</>. Mở hằng ngày 12:00–24:00, khuyến nghị tổ đội. Tham gia lúc <Assistant_Red>20:00~21:00</> mỗi ngày nhận thêm thưởng điểm.\n<Assistant_Title2>Phần Thưởng:</> Điểm tiến độ tuần (reset hằng tuần); đạt mốc chỉ định có thể nhận <Assistant_System>Rương Phiêu Lưu Thế Giới, Soule khóa, Vật Chất Phi Phàm, Tinh Thạch Lam Sơn, Tinh Tệ</> và các phần thưởng khác.",
    [527767191951104] = "<Assistant_Title1>【Bút Ký Antigonus】</>\n<Assistant_Title2>Loại:</><Assistant_Property1> Phó Bản Tổ Đội</>\n<Assistant_Title2>Điều Kiện:</>\n    <Assistant_Property1>Thường:</> Cấp 52\n    <Assistant_Property1>Khó:</> Cấp 70, mở ngày 2026-10-16\n<Assistant_Title2>Tham Gia:</> Nhấn <Assistant_System>Menu-Mạo Hiểm Thế Giới-Phó Bản-</>{JumpToUI:[Bút Ký Antigonus]|1250161}.\n<Assistant_Title2>Số Người:</> Tổ đội 5~6 người hoặc chọn chế độ máy.\n<Assistant_Title2>Phần Thưởng:</> Rương Mạo Hiểm Thế Giới, Trang Bị Khắc Ấn, Ngoại Hình, Vật Chất Phi Phàm, nguyên liệu Ma Dược, v.v.\n    <Assistant_Property1>Thường:</> Trang Bị Cấp 55-60\n    <Assistant_Property1>Khó:</> Trang Bị Cấp 66\n<Assistant_Red>Mỗi Boss chỉ nhận thưởng 1 lần mỗi tuần; số lượt thưởng dùng chung giữa các Phó Bản Tổ Đội khác nhau.</>\n<Assistant_Title2>Hướng Dẫn Boss:</>\n    <Assistant_Property1>Thường:</>{JumpToUI:[Hộ Tống Xe Ngựa]|1302100}{JumpToUI:[Riel Bieber]|1302101}{JumpToUI:[Chú Hề]|1302102}\n    <Assistant_Property1>Khó:</>{JumpToUI:[Hộ Tống Xe Ngựa]|1302103}{JumpToUI:[Riel Bieber]|1302104}{JumpToUI:[Chú Hề]|1302105}\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Cốt Truyện · Bút Ký Antigonus]|604}",
    [527767191951360] = "<Assistant_Title1>【Cây Phong Nhiêu】</>\n<Assistant_Title2>Loại:</><Assistant_Property1> Phó Bản Tổ Đội</>\n<Assistant_Title2>Điều Kiện:</>\n    <Assistant_Property1>Thường:</> Cấp 70, mở ngày 2026-09-18\n    <Assistant_Property1>Khó:</> Cấp 70, mở ngày 2026-11-13\n<Assistant_Title2>Tham Gia:</> Nhấn <Assistant_System>Menu-Mạo Hiểm Thế Giới-Phó Bản-</>{JumpToUI:[Cây Phong Nhiêu]|1250302}.\n<Assistant_Title2>Số Người:</> Tổ đội 5~6 người hoặc chọn chế độ máy.\n<Assistant_Title2>Phần Thưởng:</> Rương Mạo Hiểm Thế Giới, Trang Bị Khắc Ấn, Ngoại Hình, Vật Chất Phi Phàm, nguyên liệu Ma Dược, v.v.\n    <Assistant_Property1>Thường:</> Trang Bị Cấp 64\n    <Assistant_Property1>Khó:</> Trang Bị Cấp 68\n<Assistant_Red>Mỗi Boss chỉ nhận thưởng 1 lần mỗi tuần; số lượt thưởng dùng chung giữa các Phó Bản Tổ Đội khác nhau.</>\n<Assistant_Title2>Hướng Dẫn Boss:</>\n    <Assistant_Property1>Thường:</>{JumpToUI:[Cự Quy Ách Thủy]|1302106}{JumpToUI:[Vua Nhảy Baboon]|1302107}{JumpToUI:[Sylvia]|1302108}\n    <Assistant_Property1>Khó:</>{JumpToUI:[Cự Quy Ách Thủy]|1302109}{JumpToUI:[Vua Nhảy Baboon]|1302110}{JumpToUI:[Sylvia]|1302111}",
    [527767191951616] = "<Assistant_Title1>【Trang Viên Tháng Năm · Vườn】</>\n<Assistant_Title2>Loại:</><Assistant_Property1> Phó Bản Raid</>\n<Assistant_Title2>Điều Kiện:</>\n    <Assistant_Property1>Thường:</> Cấp 62, mở ngày 2026-08-27\n    <Assistant_Property1>Khó:</> Cấp 70, mở ngày 2026-10-23\n<Assistant_Title2>Tham Gia:</> Nhấn <Assistant_System>Menu-Mạo Hiểm Thế Giới-Phó Bản-</>{JumpToUI:[Trang Viên Tháng Năm · Vườn]|1250308}.\n<Assistant_Title2>Số Người:</> Tổ đội 10~12 người hoặc chọn chế độ máy.\n<Assistant_Title2>Phần Thưởng:</> Trang Bị Khắc Ấn, Ngoại Hình, Vật Chất Phi Phàm, nguyên liệu Ma Dược, v.v.\n    <Assistant_Property1>Thường:</> Trang Bị Cấp 62\n    <Assistant_Property1>Khó:</> Trang Bị Cấp 66\n<Assistant_Red>Mỗi Boss chỉ nhận thưởng 1 lần mỗi tuần; số lượt thưởng dùng chung giữa các Phó Bản Raid khác nhau.</>\n<Assistant_Title2>Hướng Dẫn Boss:</>\n    <Assistant_Property1>Thường:</>{JumpToUI:[Liệp Khuyển Dị Hóa]|1302112}{JumpToUI:[Giáp Tổ Tiên]|1302113}{JumpToUI:[Nhà Chiêm Tinh]|1302114}\n    <Assistant_Property1>Khó:</>{JumpToUI:[Liệp Khuyển Dị Hóa]|1302115}{JumpToUI:[Giáp Tổ Tiên]|1302116}{JumpToUI:[Nhà Chiêm Tinh]|1302117}",
    [527767191951872] = "<Assistant_Title1>【Trang Viên Tháng Năm · Lâu Đài】</>\n<Assistant_Title2>Loại:</><Assistant_Property1> Phó Bản Raid</>\n<Assistant_Title2>Điều Kiện:</>\n    <Assistant_Property1>Thường:</> Cấp 69, mở ngày 2026-09-04\n    <Assistant_Property1>Khó:</> Cấp 70, mở ngày 2026-10-30\n<Assistant_Title2>Tham Gia:</> Nhấn <Assistant_System>Menu-Mạo Hiểm Thế Giới-Phó Bản-</>{JumpToUI:[Trang Viên Tháng Năm · Lâu Đài]|1250309}.\n<Assistant_Title2>Số Người:</> Tổ đội 10~12 người hoặc chọn chế độ máy.\n<Assistant_Title2>Phần Thưởng:</> Rương Mạo Hiểm Thế Giới, Trang Bị Khắc Ấn, Ngoại Hình, Vật Chất Phi Phàm, Mảnh Bí Ngẫu, nguyên liệu Ma Dược, v.v.\n    <Assistant_Property1>Thường:</> Trang Bị Cấp 64\n    <Assistant_Property1>Khó:</> Trang Bị Cấp 68\n<Assistant_Red>Mỗi Boss chỉ nhận thưởng 1 lần mỗi tuần; số lượt thưởng dùng chung giữa các Phó Bản Raid khác nhau.</>\n<Assistant_Title2>Hướng Dẫn Boss:</>\n    <Assistant_Property1>Thường:</>{JumpToUI:[Thủ Hộ Hậu Duệ]|1302118}{JumpToUI:[Tín Đồ Số 1]|1302119}{JumpToUI:[Phu Nhân Tử Tước]|1302120}\n    <Assistant_Property1>Khó:</>{JumpToUI:[Thủ Hộ Hậu Duệ]|1302121}{JumpToUI:[Tín Đồ Số 1]|1302122}{JumpToUI:[Phu Nhân Tử Tước]|1302123}",
    [527767191952384] = "<Assistant_Title1>【Nhà Hát Utopia】</>\n<Assistant_Title2>Loại Lối Chơi:</><Assistant_Property1>Phó Bản Solo/2 Người</>\n<Assistant_Title2>Đặc Điểm:</>\n  <Assistant_Property1>Mảnh Ký Ức:</> Trong trận, hạ Bí Ngẫu mất kiểm soát có xác suất nhận Ký Ức Tàn Dư rơi ra. Có thể chọn các Mảnh Ký Ức cường hóa năng lực bản thân, liên tục trưởng thành để đối mặt thử thách mạnh hơn ở mỗi tầng.\n  <Assistant_Property1>Tặng Mảnh Ký Ức:</> Trong chế độ 2 người, dùng Hồi Tưởng Ký Ức tại giao diện Mảnh Ký Ức để chuyển Mảnh Ký Ức của mình thành Hồi Tưởng đồng đội có thể nhặt, trao đổi mảnh để bổ khuyết và cùng phát triển.\n<Assistant_Title2>Điều Kiện:</>\n    <Assistant_Property1>Thường:</> Cấp 30\n    <Assistant_Property1>Khó:</> Cấp 30, mở sau khi vượt Thường\n    <Assistant_Property1>Ác Mộng:</> Cấp 61, mở sau khi vượt Thường\n<Assistant_Title2>Tham Gia:</> Nhấn <Assistant_System>Menu-Mạo Hiểm Thế Giới-Phó Bản-</>{JumpToUI:[Nhà Hát Utopia]|1302351}.\n<Assistant_Title2>Số Người:</> Solo hoặc tổ đội 2 người.\n<Assistant_Title2>Phần Thưởng:</> Rương Mạo Hiểm Thế Giới, Chỉ Dệt Vàng, Hộp Mảnh Bí Ngẫu Ngẫu Nhiên...\n    <Assistant_Property1>Thưởng vượt lần đầu từng độ khó:</> Bảng Vàng Khóa, Hộp Mảnh Bí Ngẫu Tím/Vàng Ngẫu Nhiên\n    <Assistant_Property1>Thưởng tiến độ tuần:</> Rương Mạo Hiểm Thế Giới, Chỉ Dệt Vàng, Hộp Mảnh Bí Ngẫu Tím/Vàng Ngẫu Nhiên\n<Assistant_Red>Mỗi độ khó có 1 thưởng vượt lần đầu; mỗi tuần nhận thưởng tiến độ tương ứng tối đa 1200 Dư Âm Sân Khấu</>\n<Assistant_Title2>Thệ Ước Bonus:</>\n    <Assistant_Property1>Người chơi có quan hệ Thệ Ước</> vào chế độ 2 người sẽ nhận thêm số lần hồi sinh và thêm Tinh Túy Bí Ngẫu trong trận (dùng đổi vật phẩm quan trọng trong trận).",
    [527767191952640] = "<Assistant_Title1>【Kế Thừa Ký Ức】</>\n<Assistant_Title2>Loại:</><Assistant_Property1>Phó Bản Gia Tộc 5~6 người</>\n<Assistant_Title2>Giới Thiệu:</> Sau khi mở nghi thức “Kế Thừa Ký Ức”, người chơi sẽ vào Thế Giới Ký Ức và tái chiến những cường địch từng gặp. Khi vào cùng thành viên Gia Tộc, nhận buff 【Lửa Thề Cùng Cháy】 và 【Minh Ước Huyết Mạch】.\n<Assistant_Title2>Tham Gia:</> Nhấn <Assistant_System>Menu - Phiêu Lưu Thế Giới - Phó Bản - Kế Thừa Ký Ức</>.\n<Assistant_Title2>Boss và Điều Kiện:</>\n    <Assistant_Property1>Johnny:</> Thường Cấp 39, đề xuất Điểm Phi Phàm 8779; Khó Cấp 61, đề xuất 39842.\n    <Assistant_Property1>Mũi Khoan:</> Thường Cấp 46, đề xuất 17855; Khó Cấp 63, đề xuất 49578.\n    <Assistant_Property1>Bonnie:</> Thường Cấp 56, đề xuất 28959; Khó Cấp 66, đề xuất 58189.\n    <Assistant_Property1>Cự Long Chiến Tranh:</> Thường Cấp 60, đề xuất 38619; Khó Cấp 68, đề xuất 69025; Ác Mộng Cấp 70, đề xuất 94338.\n<Assistant_Title2>Lịch Mở:</> Mũi Khoan Thường mở ngày 2 mùa, Bonnie Thường ngày 4, Cự Long Chiến Tranh Thường ngày 5; Johnny Khó ngày 6, Mũi Khoan Khó ngày 8, Bonnie Khó ngày 12, Cự Long Chiến Tranh Khó ngày 14; Cự Long Chiến Tranh Ác Mộng ngày 25.\n<Assistant_Title2>Thử Thách:</> Mỗi Boss hỗ trợ tổ đội 5~6 người và Chế Độ Máy. Boss và độ khó mở độc lập; hãy chọn mục tiêu theo Cấp nhân vật và Điểm Phi Phàm đề xuất.",
    [527767191953152] = "<Assistant_Title1>【Thư】</>\n<Assistant_Title2>Giải Thích:</>\n1. Bấm biểu tượng <Assistant_System>Xã Hội - Thư</> ở góc dưới trái giao diện chính, hoặc <Assistant_System>Menu - Thư</> ở thanh bên góc trên phải để mở hộp thư.\n2. Bấm biểu tượng ngôi sao để lưu thư vào Mục Yêu Thích. Thư trong Mục Yêu Thích tồn tại vĩnh viễn cho tới khi tự xóa khỏi mục này (không thể lưu thư có tệp đính kèm).\n3. Chỉ hệ thống hoặc CLB có thể gửi thư; trao đổi với bạn bè hãy dùng hệ thống <Assistant_System>Chat</>.\n<Assistant_Title2>Tệp Đính Kèm:</>\n1. Hộp thư có giới hạn; thư vượt giới hạn sẽ bị <Assistant_Red>tự động xóa</>, hãy nhận thư kịp thời.\n2. Một số thư có <Assistant_Red>thời hạn hiệu lực</>; quá hạn sẽ <Assistant_Red>không thể nhận</>, hãy kiểm tra kịp thời.\n3. Thư đã xóa <Assistant_Red>không thể khôi phục</> (thư đã lưu vẫn có thể xem trong Mục Yêu Thích sau khi xóa).\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Gửi Thư Hàng Loạt CLB]|501}",
    [527767191953664] = "<Assistant_Title1>【Điểm Phi Phàm】</>\n<Assistant_Title2>Giải Thích:</> Nhấn <Assistant_System>Menu - Nhân Vật - Điểm Phi Phàm</> để xem Điểm Phi Phàm hiện tại. Đây là chỉ số đánh giá tổng hợp mức bồi dưỡng và sức chiến đấu của nhân vật.\n<Assistant_Title2>Gợi Ý Tăng Điểm:</> Trong hệ thống Điểm Phi Phàm có thể xem <Assistant_Red>phần trăm bồi dưỡng</> của từng hệ thống; mục có tỷ lệ thấp sẽ được đề xuất ưu tiên nâng (tỷ lệ chỉ phản ánh đề xuất theo tình trạng hiện tại; một số nội dung vẫn có thể tiếp tục nâng sau 100%).\n<Assistant_Title2>Cách Nâng:</> Nhấn module muốn nâng để xem <Assistant_Red>nguyên liệu bồi dưỡng</> và <Assistant_Red>nguồn nhận</>; nhấn “Đi Tới” để mở hệ thống tương ứng, nhấn “Hướng Dẫn” để mở trang hướng dẫn.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Điểm Con Đường]|503}，{SendAnswer:[Điểm Trang Bị]|504}，{SendAnswer:[Điểm Vật Phong Ấn]|505}，{SendAnswer:[Điểm Nhân Vật Phi Phàm]|506}，{SendAnswer:[Phương Án Đề Xuất]|507}",
    [527767191953920] = "<Assistant_Title1>【Điểm Con Đường】</> <Assistant_Title2>Giải Thích:</> Nhấn <Assistant_System>Menu - Nhân Vật - Điểm Phi Phàm - Con Đường</> để xem Điểm Con Đường hiện tại; đây là đánh giá mức bồi dưỡng Năng Lực Phi Phàm của chính nhân vật. <Assistant_Title2>Gợi Ý Tăng Điểm:</> Liên tục nâng Cấp nhân vật và Bậc để tăng Điểm Con Đường. Khi nội dung bồi dưỡng Điểm Con Đường đạt 100%, nghĩa là đã đạt giới hạn bồi dưỡng ở thời điểm hiện tại.",
    [527767191954176] = "<Assistant_Title1>【Điểm Trang Bị】</>\n<Assistant_Title2>Giải Thích:</> Chọn <Assistant_System>Menu - Nhân Vật - Điểm Phi Phàm - Trang Bị</> để xem Điểm Trang Bị hiện tại; đây là đánh giá mức bồi dưỡng của các trang bị <Assistant_Red>đang lắp</> trên nhân vật.\n<Assistant_Title2>Cách Tăng Điểm:</> Tham gia <Assistant_System>Lấy Chiến Nuôi Chiến, Mạo Hiểm Thế Giới và lối chơi Giáo Đoàn</>, mở Quà Tặng Phi Phàm để nhận trang bị mới; mặc đủ trang bị tạo Bộ, Cường Hóa trang bị, <Assistant_Property1>Tái Tạo</> dòng ngẫu nhiên và nhận <Assistant_Property1>Ân Tứ</> độ hiếm cao đều có thể tăng Điểm Trang Bị của Phi Phàm Giả.",
    [527767191954432] = "<Assistant_Title1>【Điểm Vật Phong Ấn】</> <Assistant_Title2>Giải Thích Điểm:</> Nhấn <Assistant_System>Menu-Nhân Vật-Điểm Phi Phàm-Vật Phong Ấn</> để xem Điểm Vật Phong Ấn hiện tại. Điểm này đánh giá mức bồi dưỡng của <Assistant_Red>Vật Phong Ấn và Vật Chất Phi Phàm đang trang bị</>. <Assistant_Title2>Cách Tăng Điểm:</> Tham gia <Assistant_System>Lấy Chiến Nuôi Chiến, Mạo Hiểm Thế Giới và lối chơi Giáo Đoàn</>; nhận Vật Phong Ấn mới, vật liệu nâng cấp và Vật Chất Phi Phàm tại Bách Hóa và Cửa Hàng; nâng Cấp và Bậc để tăng <Assistant_Property1>Cấp Tri Thức Phi Phàm</>; tiến hành <Assistant_Property1>Tụ Hợp Vật Chất Phi Phàm</> để tạo Vật Chất Phi Phàm có điểm cao hơn và dòng hiếm. <Assistant_Title2>Lưu Ý:</> Dòng có loại Vật Lý/Ma Pháp không phù hợp với Con Đường hiện tại sẽ không tăng Điểm Phi Phàm sau khi trang bị.",
    [527767191954688] = "<Assistant_Title1>【Điểm Nhân Vật Phi Phàm】</> <Assistant_Title2>Giải thích điểm:</> Vào <Assistant_System>Menu-Nhân Vật-Điểm Phi Phàm-Nhân Vật Phi Phàm</> để xem Điểm Nhân Vật Phi Phàm hiện tại. Điểm này đánh giá quá trình bồi dưỡng dựa trên <Assistant_Red>các kỹ năng Bí Ngẫu và Nhân Mạch đã lắp</>, thuộc tính Bí Ngẫu và Nghiên Cứu Lịch Sử của nhân vật. <Assistant_Title2>Hướng dẫn tăng điểm:</> Trải nghiệm <Assistant_System>Lấy Chiến Nuôi Chiến, Phiêu Lưu Thế Giới và lối chơi Giáo Đoàn</> để nhận <Assistant_Property1>Kim Phưởng Tuyến</> và <Assistant_Property1>Minh Đăng Lịch Sử</>, bồi dưỡng Nhân Mạch và Bí Ngẫu; tăng Cấp và Bậc của bản thân để nâng cấp kỹ năng.",
    [527767191954944] = "<Assistant_Title1>【Phương Án Đề Xuất】</>\n<Assistant_Title2>Giải Thích:</> Trong các hệ thống bồi dưỡng, nhấn <Assistant_System>Phương Án Đề Xuất</> để mở hệ thống này. Có thể áp dụng bằng một nút các phương án do hệ thống và người chơi cao thủ đề xuất dựa trên tình trạng bồi dưỡng hiện tại.\n<Assistant_Title2>Cách Dùng:</> Sau khi vào hệ thống, có thể nhấn Dùng Một Nút hoặc nhấn nút Sao Chép ở góc phải từng module để áp dụng cả bộ hoặc từng cấu hình vào phương án hiện tại. Trong giao diện phương án, nhấn <Assistant_System>Chia Sẻ</> góc trái dưới để chia sẻ cấu hình đang dùng. Người khác có thể <Assistant_System>Nhập</> bằng mã hoặc liên kết chia sẻ.\n<Assistant_Title2>Ghi Đè:</> Phương án sau khi ghi đè là <Assistant_Red>phối hợp thông minh</> được tính từ phương án đề xuất và tình trạng bồi dưỡng hiện tại, đồng thời tự trang bị Vật Chất Phi Phàm phù hợp. Chỉ Phi Phàm Giả <Assistant_Red>cùng Con Đường</> mới có thể trực tiếp chia sẻ, nhập và ghi đè phương án.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Điểm Phi Phàm]|502}，{SendAnswer:[Phương Án Phi Phàm]|508}",
    [527767191955200] = "<Assistant_Title1>【Phương Án Phi Phàm】</>\n<Assistant_Title2>Giải Thích Hệ Thống:</> Nhấn <Assistant_System>Menu-Kỹ Năng-Phương Án Phi Phàm</> để cấu hình Kỹ Năng, Vật Phong Ấn và Thiên Phú; nhấn <Assistant_System>Menu-Kỹ Năng-Hỗ Trợ Một Chạm</> để cấu hình phương án Hỗ Trợ Một Chạm, tự động thi triển combo; nhấn <Assistant_System>Menu-Nhân Vật-góc trái dưới</> để cấu hình Phương Án Trang Bị, nhanh chóng đổi trang bị hiện tại.\n<Assistant_Title2>Đổi Phương Án:</> Nhấn nút <Assistant_System>Trang Bị Nhanh</> trên vòng kỹ năng hoặc danh sách kỹ năng phía dưới giao diện chính để nhanh chóng đổi build hiện tại giữa các phương án đã cấu hình, thích ứng môi trường chiến đấu khác nhau.\n<Assistant_Title2>Đổi Theo Nhóm:</> Nhấn <Assistant_System>Trang Bị Nhanh</> và bật Đổi Theo Nhóm để đổi toàn bộ phương án một chạm; đồng thời bật <Assistant_Property1>Tự Động Đổi</> để hệ thống tự chọn Phương Án Nhóm phù hợp theo cảnh Phi Phàm Giả tiến vào.\n<Assistant_Title2>Chia Sẻ:</> Nhấn nút <Assistant_System>Chia Sẻ</> ở góc trái dưới giao diện Phương Án Phi Phàm để chia sẻ build đang dùng. Phi Phàm Giả khác có thể <Assistant_System>Nhập</> qua mã hoặc liên kết chia sẻ.\n\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Phương Án Đề Xuất]|507}",
    [527767191956224] = "<Assistant_Title1>【Dâng Hiến Nghi Thức CLB】</>\n<Assistant_Title2>Giải Thích Lối Chơi:</> <Assistant_System>Dâng Hiến Nghi Thức</> có thể vào từ <Assistant_Property1>Menu-CLB-Hoạt Động</>; làm mới lúc <Assistant_Red>8:00 mỗi ngày</>.\n<Assistant_Title2>Điều Kiện:</> Phi Phàm Giả đạt <Assistant_Red>Cấp 20</> và gia nhập CLB sẽ mở khóa <Assistant_System>Dâng Hiến Nghi Thức</>.\n<Assistant_Title2>Nộp Vật Tư:</> Nộp vật tư yêu cầu để nhận <Assistant_System>Suli, Huy Hiệu Đồng Hành</> và phần thưởng khác; sau khi nộp <Assistant_Red>từ 3 hàng hóa trở lên</> trong ngày, có thể tiêu hao Thể Lực nhận thưởng thêm.\n<Assistant_Title2>Nhờ Giúp:</> Có thể nhờ người khác hỗ trợ nộp trong kênh CLB.\n<Assistant_Title2>Giúp Người Khác:</> Tại giao diện Giúp Người Khác có thể thêm vật phẩm không khóa; hoàn thành yêu cầu của người khác để nhận thưởng <Assistant_System>Suli</>.",
    [527767191956480] = "<Assistant_Title1>【Mẫu Lâu Đài】</>\n<Assistant_Title2>Hướng Dẫn:</>\nMở tab <Assistant_System>Menu - Lâu Đài - Mẫu - Đề Xuất</>, hoặc {JumpToUI:[Bấm Vào Đây]|1250327}, để xem và tải các mẫu đề xuất.\nMở tab <Assistant_System>Menu - Lâu Đài - Mẫu - Của Tôi</>, chọn mẫu đã lưu rồi bấm <Assistant_System>Áp Dụng Mẫu</> để áp dụng cho Lâu Đài hiện tại.\nTrong <Assistant_System>Lâu Đài - Trang Trí - Lưu/Áp Dụng</>, cũng có thể áp dụng mẫu đã lưu hoặc lưu bố trí Lâu Đài hiện tại thành mẫu.\n<Assistant_Title2>Mẹo:</>\nBạn cũng có thể tới <Assistant_System>Quảng Trường Trang Trí</> để xem mẫu người chơi khác đăng tải; thích mẫu nào có thể lưu rồi sử dụng.\n<Assistant_Title2>Xóa Mẫu:</>\nMuốn xóa mẫu đã lưu, vào <Assistant_System>Menu - Lâu Đài - Mẫu - Của Tôi</>, chọn mẫu cần xóa rồi bấm nút xóa ở <Assistant_System>góc trên phải</>.",
    [527767191956736] = "<Assistant_Title1>【Tọa Kỵ】</>\n<Assistant_Title2>Giới Thiệu:</> Một loại Ngoại Hình.\n<Assistant_Title2>Cách Nhận:</> Có thể nhận Tọa Kỵ từ nhiệm vụ, sự kiện, Cửa Hàng hoặc phần thưởng gameplay đặc biệt và nhiều nguồn khác.\n<Assistant_Title2>Xem/Đổi:</> Vào Menu - Ngoại Hình - Tọa Kỵ để xem trước, đổi Tọa Kỵ và thay Ngoại Hình Tọa Kỵ.\n<Assistant_Title2>Triệu Hồi:</> Bấm nút Tọa Kỵ ở góc dưới phải để triệu hồi; trên PC cũng có thể dùng phím T.",
    [527767191956992] = "<Assistant_Title1>【Giá Trị Lý Trí】</>\n<Assistant_Title2>Giới thiệu:</> Khi hành động trong thế giới Phi Phàm, nhiều loại sự kiện sẽ khiến Giá Trị Lý Trí của người chơi biến động. Khi Lý Trí liên tục giảm, trạng thái bất thường sẽ bắt đầu từ thân thể rồi dần lan sang Thể Dĩ Thái, Thể Tâm Trí, Thể Tinh Linh và Thể Tinh Thần, khiến nhân vật lần lượt rơi vào các trạng thái tinh thần khác nhau cùng hiệu ứng tương ứng. \n<Assistant_Title2>Các mốc Lý Trí:</> Giá Trị Lý Trí chia thành các mốc sau, mỗi mốc có hiệu ứng khác nhau:\nKhi Lý Trí dồi dào, nhân vật ở trạng thái <Assistant_System>「Neo Định Tâm Trí」(100-80)</>, giảm tiêu hao Thể Lực và tăng Giảm Thương; khi giảm về mức bình thường sẽ vào <Assistant_System>「Tỉnh Táo」(60-79)</>, trạng thái này không có hiệu ứng.\n\nKhi Lý Trí tiếp tục giảm, nhân vật lần lượt vào <Assistant_System>「Bất An」(45-59)「Tự Nghi Ngờ」(30-44)「Lời Thì Thầm Quấn Thân」(20-29)</>; Tốc Độ Di Chuyển và độ ổn định khi chạy nước rút bị suy giảm ở mức khác nhau, xung quanh xuất hiện tiếng lẩm bẩm gây nhiễu.\n\nKhi Lý Trí xuống vùng thấp, nhân vật vào <Assistant_System>「Rơi Vào Điên Cuồng」(10-19)</>; toàn bộ hạn chế hành động được gỡ bỏ, sát thương gây ra và sát thương nhận vào đều tăng.\n\nKhi Lý Trí thấp hơn nữa, nhân vật vào <Assistant_System>「Bờ Vực Mất Kiểm Soát」(1-9)</>, <Assistant_System>sát thương tăng</> nhưng sát thương nhận vào cũng tăng, hiệu quả trị liệu nhận được giảm, cơ thể phát ánh đỏ và tầm nhìn trở nên điên loạn.\n\nKhi Lý Trí bằng 0 và duy trì trong một khoảng thời gian, sẽ có chuyện <Assistant_Red>kinh khủng</> xảy ra!",
    [527767191957248] = "<Assistant_Title1>【Lý Trí】</>\n<Assistant_Title2>Giới Thiệu:</> Người chơi gia nhập <Assistant_System>Thi Xã An Hồn</> có thể thực hiện An Hồn cho người chơi khác để hồi Lý Trí của mục tiêu.\n\n<Assistant_Title2>Điều Kiện:</> Chỉ có thể An Hồn khi Lý Trí của mục tiêu <Assistant_System>thấp hơn một mức nhất định</>.\n\n<Assistant_Title2>Cơ Chế Thành Công:</> <Assistant_System>Tỷ lệ Trị Liệu thành công</> của An Hồn do hai yếu tố cùng quyết định — <Assistant_System>cấp Hội</> của người An Hồn và <Assistant_System>Lý Trí hiện tại</> của người được An Hồn. Cấp Hội càng cao, Lý Trí đối phương càng cao, xác suất thành công càng lớn.\n\n<Assistant_Title2>Rủi Ro Thất Bại:</> An Hồn không phải không có rủi ro — <Assistant_System>nếu An Hồn thất bại</>, Lý Trí của cả hai bên đều có xác suất dao động và bị hao hụt.",
    [527767191957504] = "<Assistant_Title1>【Trên Sương Xám】</>\n<Assistant_Title2>Loại Nhiệm Vụ:</><Assistant_Property2>Cốt Truyện Chính Nguyên Tác</>\n<Assistant_Title2>Mô Tả:</> Đồng tiền cổ quái này dường như còn cất giấu bí mật khác……\n<Assistant_Title2>Cách Nhận:</> Mở vào ngày đầu Mùa 1. Khi Cấp Nhập Vai đạt <Assistant_Red>20</>, tự động nhận nhiệm vụ.\n<Assistant_Title2>Phần Thưởng:</> Kinh Nghiệm Nhận Thức, Suli Khóa, Bảng Vàng Khóa, Đèn Lịch Sử, Trang Bị, Vật Phong Ấn.",
    [527767191957760] = "<Assistant_Title1>【Vị Khách Bất Ngờ】</>\n<Assistant_Title2>Loại Nhiệm Vụ:</><Assistant_Property2> Cốt Truyện Chính Nguyên Tác</>\n<Assistant_Title2>Mô Tả:</> Một vụ tự sát quỷ dị, một lần xuyên không bất ngờ, một thế giới vừa xa lạ vừa quen thuộc. Lúc này có người gõ cửa — bên ngoài là bạn hay thù?\n<Assistant_Title2>Cách Nhận:</> Mở vào ngày thứ 2 của Mùa 1. Hoàn thành cốt truyện nguyên tác 《Trên Sương Xám》 và đạt <Assistant_Red>Cấp Nhập Vai 41</> sẽ tự nhận.\n<Assistant_Title2>Phần Thưởng:</> EXP Nhận Thức, Suli Khóa, Bảng Vàng Khóa, Đèn Lịch Sử, Trang Bị",
    [527767191958272] = "<Assistant_Title1>【Thiện Cảm Nhân Mạch】</>\n<Assistant_Title2>Giải Thích:</> Tiêu hao <Assistant_Red>【Thiệp Hoài Niệm】</> để mời Nhân Mạch đã sở hữu thực hiện 4 loại tương tác: Dạo Bước, Hẹn Gặp, Khiêu Vũ hoặc Thư Từ, nhận Thiện Cảm tương ứng. Lần tương tác đầu mỗi ngày miễn Thiệp (riêng lần đầu Thư Từ vẫn cần Thiệp); mọi Nhân Mạch dùng chung lượt miễn phí này. Sau khi đã tiêu Thiệp cho cùng một loại tương tác với cùng Nhân Mạch, các lần cùng loại tiếp theo trong ngày không tiêu Thiệp nhưng cũng không nhận Thiện Cảm.\n<Assistant_Title2>Mở Khóa:</> Cấp Nhập Vai đạt <Assistant_Red>45</>.\n<Assistant_Title2>Xem:</> Nhấn F11 vào Nhân Mạch, chọn Nhân Mạch rồi nhấn Tăng Thiện Cảm góc phải trên.\n<Assistant_Title2>Phần Thưởng:</> Hộp Ký Ức, Biên Lai Hóa Đơn, Kinh Nghiệm Nhận Thức...",
    [527767191958528] = "<Assistant_Title1>【Thiện Cảm Nhân Mạch-Tương Tác】</>\n<Assistant_Title2>Dạo Bước:</> Tiêu hao <Assistant_Red>【Thiệp Hoài Niệm】</> để mời Nhân Mạch dạo bước trên <Assistant_Red>bản đồ thế giới</>. Trong thời gian này Nhân Mạch đi theo Phi Phàm Giả; có thể mời cùng cưỡi thú và thực hiện động tác xã giao.\n<Assistant_Title2>Hẹn Gặp:</> Tiêu hao <Assistant_Red>【Thiệp Hoài Niệm】</> để mời Nhân Mạch hẹn gặp. Hai bên được dịch chuyển tới cảnh riêng để trò chuyện theo chủ đề; Cấp Thiện Cảm càng cao, chủ đề đối thoại càng nhiều.\n<Assistant_Title2>Khiêu Vũ:</> Tiêu hao <Assistant_Red>【Thiệp Hoài Niệm】</> để mời Nhân Mạch khiêu vũ. Nhân Mạch vào Học Viện Nghệ Thuật và có thể thực hiện động tác dựa trên video Phi Phàm Giả tải lên.",
    [527767191958784] = "<Assistant_Title1>【Thiện Cảm Nhân Mạch - Thưởng Cấp】</> <Assistant_Title2>Cách Nhận:</> Khi nâng Cấp Thiện Cảm với Nhân Mạch, Phi Phàm Giả có thể nhận phần thưởng cấp tương ứng của Nhân Mạch đó. <Assistant_Title2>Phần Thưởng:</> Khi Cấp Thiện Cảm tăng, ngoài tiền tệ Hộp Ký Ức, còn có thể nhận <Assistant_Property1>Thẻ Nhân Vật của Nhân Mạch<>、<Assistant_Property1>Tranh Treo Lâu Đài Độc Quyền<>、<Assistant_Property1>Động Tác Xã Giao<>、<Assistant_Property1>Kiểu Tóc Đồng Bộ Nhân Mạch<>、<Assistant_Property1>Danh Hiệu Độc Quyền Nhân Mạch<>. <Assistant_Title2>Hộp Ký Ức:</> Có thể dùng Hộp Ký Ức tại Phòng Trưng Bày Chuyện Xưa để mua Ngoại Trang đặc biệt và nguyên liệu chính cần cho Thăng Bậc.",
    [527767191960832] = "<Assistant_Title1>【Tarot Thất Lạc】</>\n<Assistant_Title2>Loại Nhiệm Vụ:</><Assistant_Property2>Bách Thái Thời Đại</>\n<Assistant_Title2>Mô Tả:</> Trên giá sách của CLB Bói Toán dường như có dao động Linh Tính...\n<Assistant_Title2>Cách Nhận:</> Khi Cấp Nhập Vai đạt <Assistant_Red>51</>, tới {Location:[CLB Bói Toán(112,94)]|923;-505;152;2;5200009;0} để kích hoạt nhiệm vụ.\n<Assistant_Title2>Phần Thưởng:</> EXP Nhận Thức, Suli Khóa, Chứng Từ Hóa Đơn, Huân Chương Mạo Hiểm, tiến độ Bí Bảo Mạo Hiểm Thế Giới",
    [527767191961600] = "<Assistant_Title1>Bí Ngẫu</>\n<Assistant_Title2>Giải Thích Lối Chơi:</>\nVật Phong Ấn <Assistant_Property1>Nhà Hát Utopia</> do ngài “Kẻ Khờ” ban tặng giúp Phi Phàm Giả thu nhận và điều khiển Bí Ngẫu.\n1. Vào <Assistant_System>Menu-Bí Ngẫu-Nhận Bí Ngẫu</> để đến <Assistant_Property1>Nhà Hát Utopia</>, rút <Assistant_Property2>Bí Ngẫu</> và mở kỹ năng tương ứng.\n2. Bí Ngẫu trùng chuyển thành Mảnh Bí Ngẫu, dùng <Assistant_Property1>Bồi Dưỡng Bí Ngẫu</> để tăng thuộc tính nhân vật và cường hóa kỹ năng Bí Ngẫu.\n3. Có thể chọn Bí Ngẫu <Assistant_Property1>Ra Trận</>; sau khi ra trận, thuộc tính Bí Ngẫu nhận thêm bonus.\n4. Có thể phái Bí Ngẫu <Assistant_Property1>Du Lịch</> để tăng mạnh phần thưởng Du Lịch.\n5. Có thể phái Bí Ngẫu tới <Assistant_Property1>Lâu Đài</> làm việc, tăng hiệu suất sản xuất <Assistant_Property2>Xưởng</>.\n6. Bí Ngẫu loại <Assistant_Property1>Trùng Tinh Tú</> có thể <Assistant_Property2>Biến Hình</> thành ngoại hình Phi Phàm Giả khác; sau Biến Hình có thể tự do đổi trang phục Bí Ngẫu.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Nhận Bí Ngẫu]|536}，{SendAnswer:[Bồi Dưỡng Bí Ngẫu]|537}，{SendAnswer:[Bí Ngẫu Ra Trận]|538}，{SendAnswer:[Bí Ngẫu Du Lịch]|539}，{SendAnswer:[Bí Ngẫu Biến Hình]|540}",
    [527767191961856] = "<Assistant_Title1>Nhận Bí Ngẫu</>\n<Assistant_Title2>Giải Thích Lối Chơi:</>\nVật Phong Ấn <Assistant_Property1>Nhà Hát Utopia</> do ngài “Kẻ Khờ” ban tặng có thể giúp Phi Phàm Giả thu nhận và điều khiển Bí Ngẫu.\n1. Vào <Assistant_System>Menu-Bí Ngẫu-Nhận Bí Ngẫu</> để đến <Assistant_Property1>Nhà Hát Utopia</>, rút <Assistant_Property2>Bí Ngẫu</> và mở khóa kỹ năng tương ứng.\n2. Mỗi lần sân khấu Nhà Hát Utopia <Assistant_Property1>Làm Mới</> sẽ bày <Assistant_Red>3</> Bí Ngẫu để rút. Nếu sau khi rút chỉ còn Bí Ngẫu phẩm chất <Assistant_Red>Tím</>, sân khấu tự làm mới.\nRút Mở Màn: Tiêu hao <Assistant_Property1>Chỉ Dệt Vàng</>*3, ngẫu nhiên nhận 1 trong 3 Bí Ngẫu trên sân khấu.\nRút Giữa Màn: Tiêu hao <Assistant_Property1>Chỉ Dệt Vàng</>*6, ngẫu nhiên nhận 1 trong 2 Bí Ngẫu còn lại.\nRút Hạ Màn: Tiêu hao <Assistant_Property1>Chỉ Dệt Vàng</>*12, chắc chắn nhận 1 Bí Ngẫu cuối cùng còn lại.\n3. Sau Rút Mở Màn, cũng có thể chủ động <Assistant_Property1>Từ Bỏ</> Bí Ngẫu còn lại để làm mới.\n4. Dùng <Assistant_Property1>Cầu Nguyện Bí Ngẫu</> và chọn Bí Ngẫu chỉ định để tăng xác suất xuất hiện.\n5. Bí Ngẫu trùng sẽ chuyển thành Mảnh Bí Ngẫu, dùng để <Assistant_Property1>Bồi Dưỡng Bí Ngẫu</>, tăng thuộc tính nhân vật và cường hóa kỹ năng Bí Ngẫu.\n6. Khi Bồi Dưỡng Bí Ngẫu đạt giới hạn, <Assistant_Property1>Mảnh Bí Ngẫu</> dư sẽ chuyển thành <Assistant_Property1>Dây Cót Con Rối</>, có thể đổi vật phẩm khác tại <Assistant_Property1>Cửa Hàng Bí Ngẫu</>.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Bồi Dưỡng Bí Ngẫu]|537}，{SendAnswer:[Dây Cót Nhân Ngẫu]|543}，{SendAnswer:[Cửa Hàng Bí Ngẫu]|545}",
    [527767191962112] = "<Assistant_Title1>Bồi Dưỡng Bí Ngẫu</>\n<Assistant_Title2>Giải Thích Lối Chơi:</>\n1. Bí Ngẫu trùng chuyển thành <Assistant_Property1>Mảnh Bí Ngẫu</>; số mảnh phụ thuộc phẩm chất. Mảnh dùng <Assistant_Property1>Bồi Dưỡng Bí Ngẫu</>.\n2. Tăng mức Bồi Dưỡng sẽ tăng <Assistant_Property1>bonus thuộc tính</> của Bí Ngẫu.\n3. Khi đạt mốc Bồi Dưỡng, kỹ năng Bí Ngẫu cũng <Assistant_Property1>Thăng Bậc</>, nhận <Assistant_Red>hiệu ứng kỹ năng bổ sung</>.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Nhận Bí Ngẫu]|536}",
    [527767191962368] = "<Assistant_Title1>Bí Ngẫu Ra Trận</>\n<Assistant_Title2>Giải Thích Lối Chơi:</>\n1. Có thể chọn Bí Ngẫu đã sở hữu để <Assistant_Property1>Ra Trận</>; sau khi ra trận, thuộc tính Bí Ngẫu được cộng thêm.\n2. Số Bí Ngẫu có thể ra trận sẽ tăng dần theo <Assistant_Property1>tiến trình mùa giải</>.\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Nhận Bí Ngẫu]|536}",
    [527767191962624] = "<Assistant_Title1>Bí Ngẫu Du Lịch</>\n<Assistant_Title2>Giải Thích Lối Chơi:</>\n1. Du Lịch tích lũy phần thưởng theo thời gian, tối đa 24 giờ. Có thể nhận <Assistant_Property1>Suli Khóa, tiến độ Rương Mạo Hiểm Thế Giới, nguyên liệu Ma Dược</>, v.v.\n2. Phái <Assistant_Property1>Bí Ngẫu</> đi Du Lịch có thể tăng mạnh phần thưởng; số lượng có thể phái tăng dần theo <Assistant_Property1>tiến trình mùa giải</>.\n3. Dùng vật phẩm <Assistant_Property1>Dây Linh</> có thể tăng thưởng Du Lịch và khiến Bí Ngẫu đang Du Lịch tự động hoàn thành <Assistant_Property1>Thám Bí Thế Giới Trật Tự</> tại khu vực chỉ định.\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Dây Linh]|544}，{SendAnswer:[Thám Bí]|560}",
    [527767191962880] = "<Assistant_Title1>Biến Hình Bí Ngẫu</>\n<Assistant_Title2>Giải Thích:</>\n1. Bí Ngẫu loại <Assistant_Property1>Trùng Tinh Tú</> có thể <Assistant_Property1>xin Biến Hình</> thành Phi Phàm Giả khác sau khi được đồng ý, rồi <Assistant_Property1>Biến Hình</> thành ngoại hình của đối phương.\n2. Khi Biến Hình, nếu trong <Assistant_Property1>Ngoại Trang bản thân sở hữu</> có món <Assistant_Property1>giống Ngoại Trang của mục tiêu</>, Trùng Tinh Tú sẽ tự mặc.\n3. Sau khi Biến Hình, có thể tự do thay đồ cho Trùng Tinh Tú tại <Assistant_System>Bí Ngẫu - Cơ Bản - Ngoại Trang</>.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Bí Ngẫu]|535}",
    [527767191963136] = "<Assistant_Title1>Cầu Nguyện Bí Ngẫu</>\n<Assistant_Title2>Giải Thích Lối Chơi:</>\n1. Khi <Assistant_Property1>Rút Bí Ngẫu</> tại Nhà Hát Utopia, có thể đặt Bí Ngẫu Cầu Nguyện.\n2. Sau khi Cầu Nguyện, lúc sân khấu <Assistant_Property1>Làm Mới</> lứa Bí Ngẫu mới, nếu xuất hiện Bí Ngẫu <Assistant_Property1>cùng phẩm chất</> với Bí Ngẫu Cầu Nguyện thì có <Assistant_Red>80%</> xác suất là Bí Ngẫu đó. Nếu lần này không xuất hiện, lần kế tiếp <Assistant_Red>chắc chắn</> xuất hiện.\n3. Cầu Nguyện không giới hạn số lần có hiệu lực và có thể đổi bất cứ lúc nào.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Nhận Bí Ngẫu]|536}",
    [527767191963392] = "<Assistant_Title1>Chỉ Dệt Vàng</>\n<Assistant_Title2>Giới Thiệu Vật Phẩm:</>\n1. Dùng Chỉ Dệt Vàng tại <Assistant_System>Bí Ngẫu-Nhận Bí Ngẫu-Nhà Hát Utopia</> để rút Bí Ngẫu.\n2. Mỗi lần sân khấu Nhà Hát Utopia <Assistant_Property1>Làm Mới</> sẽ bày <Assistant_Red>3</> Bí Ngẫu. Nếu sau khi rút chỉ còn Bí Ngẫu phẩm chất <Assistant_Red>Tím</>, sân khấu tự làm mới.\nRút Mở Màn: tiêu hao <Assistant_Property1>Chỉ Dệt Vàng</>*3, ngẫu nhiên nhận 1 trong 3 Bí Ngẫu.\nRút Giữa Màn: tiêu hao <Assistant_Property1>Chỉ Dệt Vàng</>*6, ngẫu nhiên nhận 1 trong 2 Bí Ngẫu còn lại.\nRút Hạ Màn: tiêu hao <Assistant_Property1>Chỉ Dệt Vàng</>*12, chắc chắn nhận 1 Bí Ngẫu cuối.\n3. Có thể đổi tại các cửa hàng trong <Assistant_System>Thương Thành-Bách Hóa</>, mua tại <Assistant_System>Thương Thành-Sàn Giao Dịch</>, nhận qua <Assistant_System>Thưởng Xếp Hạng</>...\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Nhận Bí Ngẫu]|536}",
    [527767191963648] = "<Assistant_Title1>Dây Cót Con Rối</>\n<Assistant_Title2>Giới Thiệu Vật Phẩm:</>\n1. Khi Bồi Dưỡng Bí Ngẫu đạt giới hạn, <Assistant_Property1>Mảnh Bí Ngẫu</> dư sẽ chuyển thành <Assistant_Property1>Dây Cót Con Rối</>.\n2. Dùng Dây Cót Con Rối để đổi vật phẩm tại <Assistant_System>Bí Ngẫu-Đổi-Cửa Hàng Bí Ngẫu</>.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Nhận Bí Ngẫu]|536}，{SendAnswer:[Cửa Hàng Bí Ngẫu]|545}",
    [527767191963904] = "<Assistant_Title1>Linh Tuyến</>\n<Assistant_Title2>Giới Thiệu Vật Phẩm:</>\n1. Dùng vật phẩm <Assistant_Property1>Linh Tuyến</> để tăng phần thưởng Du Lịch.\n2. Một số Linh Tuyến cho phép Bí Ngẫu đang Du Lịch tự động hoàn thành <Assistant_Property1>Thám Bí Thế Giới Trật Tự</> tại khu vực chỉ định.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Bí Ngẫu Du Lịch]|539}",
    [527767191964160] = "<Assistant_Title1>Cửa Hàng Bí Ngẫu</>\n1. Khi Bồi Dưỡng Bí Ngẫu đạt giới hạn, <Assistant_Property1>Mảnh Bí Ngẫu</> dư sẽ chuyển thành <Assistant_Property1>Dây Cót Con Rối</>.\n2. Dùng Dây Cót Con Rối để đổi vật phẩm tại <Assistant_System>Bí Ngẫu-Đổi-Cửa Hàng Bí Ngẫu</>.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Nhận Bí Ngẫu]|536}，{SendAnswer:[Dây Cót Con Rối]|543}",
    [527767191964416] = "<Assistant_Title1>Nhân Mạch</>\n<Assistant_Title2>Giải Thích Lối Chơi:</>\nNhờ Vật Phong Ấn <Assistant_Property1>Hành Lang Lịch Sử</>, có thể tìm những nhân vật rải rác trong khe hở lịch sử, kết giao với họ và mượn sức mạnh từ quá khứ.\nKết giao nhiều lần tăng mức hiểu biết về mục tiêu, nhận năng lực chân thực và mạnh hơn của họ.\n1. Dùng <Assistant_Property1>Kết Giao</> để nhận <Assistant_Property2>Nhân Mạch</>, mở khóa kỹ năng tương ứng.\n2. Nhận trùng Nhân Mạch dùng để tăng tầng Nhân Mạch, cường hóa hiệu quả kỹ năng tương ứng.\n3. Kết giao thêm Nhân Mạch giúp hiểu hơn về {SendAnswer:Quan Hệ|551} của họ, tăng mức <Assistant_Property2>Nghiên Cứu Lịch Sử</> và nhận thêm thuộc tính.\n<Assistant_Title2>Cách Kết Giao:</>\nVào <Assistant_System>Menu-Nhân Mạch-Kết Giao Nhân Mạch</> để mở giao diện {SendAnswer:Kết Giao Nhân Mạch|554}, sau đó chọn Kết Giao 1 lần/5 lần.\n<Assistant_Title2>Tiêu Hao:</>\nMỗi lần Kết Giao tiêu hao 1 {SendAnswer:Đèn Lịch Sử|556}.\n<Assistant_Title2>Quy Tắc Kết Giao:</>\n1. Mỗi 5 lần Kết Giao chắc chắn nhận 1 Nhân Mạch Sử Thi trở lên.\n2. Nếu 24 lần liên tiếp không nhận Truyền Thuyết, xác suất sau đó tăng dần. Mỗi 40 lần chắc chắn nhận Truyền Thuyết. Nhận Truyền Thuyết sẽ reset bộ đếm và xác suất về cơ bản.\n3. Bảo hiểm của sự kiện thường trực và giới hạn thời gian được tích riêng, không ảnh hưởng nhau.\n4. Sự kiện thường trực có thể Cầu Nguyện Nhân Mạch chỉ định để tăng xác suất.\n5. Nhận trùng cùng Nhân Mạch sẽ nhận thêm {SendAnswer:Mảnh Phim|557}. Nếu Nhân Mạch đã đạt cực hạn hoặc nguyên liệu đủ lên cực hạn, số Mảnh Phim nhận được tăng. Mảnh Phim dùng đổi Đèn Lịch Sử và Nhân Mạch chỉ định tại Cửa Hàng Nhân Mạch.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Quan Hệ]|551}，{SendAnswer:[Kết Giao Nhân Mạch]|554}，{SendAnswer:[Cầu Nguyện Nhân Mạch]|555}",
    [527767191964672] = "<Assistant_Title1>Quan Hệ</>\n<Assistant_Title2>Giải Thích Lối Chơi:</>\nGiữa các Nhân Mạch cũng tồn tại những <Assistant_Property1>Quan Hệ</> đặc biệt. Thu thập đủ {SendAnswer:Nhân Mạch|550} tương ứng để mở khóa/nâng cấp Quan Hệ, đào sâu Nghiên Cứu Lịch Sử.\nDựa theo mức <Assistant_Property2>Nghiên Cứu Lịch Sử</>, nhận thêm một lượng thuộc tính.\nQuan Hệ chia thành <Assistant_Property1>Quan Hệ Hiệp Chiến</> và <Assistant_Property1>Quan Hệ Lịch Sử</>; cả hai đều tăng Nghiên Cứu Lịch Sử.\nVới Quan Hệ Hiệp Chiến, sau khi mở khóa còn có thể cường hóa năng lực cho một số Nhân Mạch. Mỗi Kỹ Năng Nhân Mạch chỉ nhận hiệu quả tăng từ một Quan Hệ Hiệp Chiến.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Nhân Mạch]|550}，{SendAnswer:[Kết Giao Nhân Mạch]|554}，{SendAnswer:[Cầu Nguyện Nhân Mạch]|555}",
    [527767191965440] = "<Assistant_Title1>Kết Giao Nhân Mạch</>\n<Assistant_Title2>Giải Thích Lối Chơi:</>\nNhờ Vật Phong Ấn <Assistant_Property1>Hành Lang Lịch Sử</>, có thể tìm những nhân vật ({SendAnswer:Nhân Mạch|550}) rải rác trong khe hở lịch sử, kết giao với họ và mượn sức mạnh từ quá khứ.\n<Assistant_Title2>Cách Kết Giao:</>\nVào <Assistant_System>Menu-Nhân Mạch-Kết Giao Nhân Mạch</>, rồi chọn Kết Giao 1 lần/5 lần.\n<Assistant_Title2>Tiêu Hao:</>\nMỗi lần Kết Giao tiêu hao 1 {SendAnswer:Đèn Lịch Sử|556}.\n<Assistant_Title2>Quy Tắc:</>\n1. Mỗi 5 lần Kết Giao chắc chắn nhận 1 Nhân Mạch Sử Thi trở lên.\n2. Nếu 24 lần liên tiếp không nhận Truyền Thuyết, xác suất tăng dần; mỗi 40 lần chắc chắn nhận Truyền Thuyết. Nhận Truyền Thuyết sẽ reset bộ đếm và xác suất.\n3. Bảo hiểm của sự kiện thường trực và giới hạn thời gian được tính độc lập.\n4. Sự kiện thường trực có thể Cầu Nguyện Nhân Mạch chỉ định để tăng xác suất.\n5. Nhận trùng Nhân Mạch sẽ nhận thêm {SendAnswer:Mảnh Phim|557}. Nếu đã cực hạn hoặc nguyên liệu đủ lên cực hạn, số Mảnh Phim tăng. Mảnh Phim dùng đổi Đèn Lịch Sử và Nhân Mạch chỉ định tại {SendAnswer:Cửa Hàng Nhân Mạch|558}.\n<Assistant_Title2>Lịch Sử Kết Giao:</>\nXem tại <Assistant_System>Nhân Mạch-Kết Giao Nhân Mạch-Sự kiện tương ứng-Lịch Sử</>.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Nhân Mạch]|550}，{SendAnswer:[Quan Hệ]|551}，{SendAnswer:[Cầu Nguyện Nhân Mạch]|555}",
    [527767191965696] = "<Assistant_Title1>Cầu Nguyện Nhân Mạch</>\n<Assistant_Title2>Giải Thích:</>\nTrong hoạt động Kết Giao thường trực tại <Assistant_System>Menu - Nhân Mạch - Kết Giao Nhân Mạch</>, nhấn nút Cầu Nguyện ở góc trái dưới video để vào giao diện Cầu Nguyện.\nSau khi <Assistant_Property2>Cầu Nguyện</> một Nhân Mạch chỉ định, xác suất nhận đúng Nhân Mạch đó khi Kết Giao sẽ tăng.\n<Assistant_Title2>Quy Tắc Cầu Nguyện:</>\nChỉ có thể Cầu Nguyện Nhân Mạch Truyền Thuyết có thể Kết Giao.\nSau khi Cầu Nguyện, khi nhận Nhân Mạch Truyền Thuyết, xác suất nhận mục tiêu Cầu Nguyện tăng lên <Assistant_Property1>80%</>. Nếu Nhân Mạch Truyền Thuyết nhận được không phải mục tiêu, lần nhận Nhân Mạch Truyền Thuyết kế tiếp chắc chắn là mục tiêu Cầu Nguyện.\nTrong Kết Giao thường trực, <Assistant_Property1>mỗi tuần</> hiệu ứng Cầu Nguyện có thể kích hoạt <Assistant_Property1>2 lần</>, reset vào thứ Hai. Mỗi khi Kết Giao Nhân Mạch <Assistant_Property1>110 lần</>, nhận thêm một lượt Cầu Nguyện. Lượt này không bị reset và được tiêu hao sau lượt tuần.\nNếu chọn nhầm mục tiêu sau khi Cầu Nguyện, có thể nhấn Hủy Cầu Nguyện để hủy.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Nhân Mạch]|550}，{SendAnswer:[Quan Hệ]|551}，{SendAnswer:[Kết Giao Nhân Mạch]|554}",
    [527767191965952] = "<Assistant_Title1>Đèn Lịch Sử</>\n<Assistant_Title2>Giới Thiệu Vật Phẩm:</>\nDùng Đèn Lịch Sử để Kết Giao Nhân Mạch.\n<Assistant_Title2>Cách Kết Giao:</>\nVào <Assistant_System>Menu-Nhân Mạch-Kết Giao Nhân Mạch</>, rồi chọn Kết Giao 1 lần/5 lần.\n<Assistant_Title2>Tiêu Hao:</>\nMỗi lần Kết Giao tiêu hao 1 Đèn Lịch Sử.\n<Assistant_Title2>Cách Nhận:</>\n1. Nhấn Kết Giao khi thiếu Đèn Lịch Sử để mở mua nhanh.\n2. Mua tại <Assistant_System>Thương Thành-Thương Thành-Trưng Bày Bí Tàng</>.\n3. Mua tại <Assistant_System>Thương Thành-Bách Hóa-Cửa Hàng Hoàn Phí/Cửa Hàng Mạo Hiểm</>.\n4. Vào <Assistant_System>Menu-Nhân Mạch-Đổi</> để mở Cửa Hàng Nhân Mạch.\n5. Nhận qua <Assistant_System>Quà Tặng Vận Mệnh</> hoặc <Assistant_System>Thang Xếp Hạng</>.\n6. Nhận qua một số lối chơi <Assistant_System>Chạy Đoàn</> hoặc <Assistant_System>Nhiệm Vụ</>.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Nhân Mạch]|550}，{SendAnswer:[Quan Hệ]|551}，{SendAnswer:[Kết Giao Nhân Mạch]|554}",
    [527767191966208] = "<Assistant_Title1>Mảnh Phim</>\n<Assistant_Title2>Giới Thiệu Vật Phẩm:</>\nLà điểm nhận trong {SendAnswer:Kết Giao Nhân Mạch|554} khi nhận trùng {SendAnswer:Nhân Mạch|550}; dùng đổi nhiều phần thưởng tại {SendAnswer:Cửa Hàng Nhân Mạch|558}.\n<Assistant_Title2>Cách Nhận:</>\nKhi Kết Giao nhận trùng Nhân Mạch sẽ nhận Mảnh Phim; phẩm chất Nhân Mạch trùng càng cao, số lượng càng nhiều.\n<Assistant_Title2>Cách Dùng:</>\nVào <Assistant_System>Menu-Nhân Mạch-Đổi</> để mở <Assistant_System>Cửa Hàng Nhân Mạch</> và đổi vật phẩm.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Nhân Mạch]|550}，{SendAnswer:[Cửa Hàng Nhân Mạch]|558}，{SendAnswer:[Kết Giao Nhân Mạch]|554}",
    [527767191966464] = "<Assistant_Title1>Cửa Hàng Nhân Mạch</>\n<Assistant_Title2>Xem:</>\nNhấn <Assistant_System>Menu - Nhân Mạch - Đổi</> để mở {SendAnswer:Cửa Hàng Nhân Mạch|558}.\n<Assistant_Title2>Đổi:</>\nCó thể dùng {SendAnswer:Mảnh Hình Chiếu|557} đổi vật phẩm tương ứng; sau khi nhận có thể dùng trong Túi.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Nhân Mạch]|550}，{SendAnswer:[Mảnh Hình Chiếu]|557}，{SendAnswer:[Kết Giao Nhân Mạch]|554}",
    [527767191966720] = "<Assistant_Title1>【Thám Bí】</>\n<Assistant_Title2>Giải Thích Lối Chơi:</> Trong thế giới Quỷ Bí, có thể khám phá 【Thế Giới Trật Tự】 trên các bản đồ và lối chơi 【Mặt Tối Thành Phố】 tại Tingen. Tham gia sẽ tăng Độ Hoàn Thành Thế Giới Trật Tự và Giá Trị Truy Nã của Mặt Tối Thành Phố, qua đó nhận nhiều phần thưởng tiến độ.\n<Assistant_Title2>Hướng Dẫn Vào:</>\n1. Lối Vào Chạy Đoàn\nMở menu vào 【Chạy Đoàn】, gia nhập bất kỳ Giáo Đoàn nào rồi vào 【Thế Giới Trật Tự】 hoặc 【Mặt Tối Thành Phố】. Chọn lối chơi/sự kiện tương ứng và nhấn 【Đi Đến】 để tự tìm đường.\n2. Lối Vào Bản Đồ\nMở bản đồ góc trên phải, chuyển sang tab 【Thám Bí】, chọn 【Thế Giới Trật Tự】 hoặc 【Mặt Tối Thành Phố】. Sau đó chọn lối chơi/sự kiện muốn trải nghiệm và nhấn 【Đi Đến】 để tự tìm đường.\n<Assistant_Title3>Đề Xuất:</>{JumpToUI:Tổng Hợp Khám Phá Tingen|1301900}, {JumpToUI:Tổng Hợp Khám Phá Hồ Kim Thu|1301901}, {JumpToUI:Tổng Hợp Khám Phá Thành Cổ Lamud|1301902}, {JumpToUI:Tổng Hợp Khám Phá Trấn Thụy Liên|1301903}, {JumpToUI:Tổng Hợp Khám Phá Dãy Hornacis|1301904}, {JumpToUI:Tổng Hợp Khám Phá Biển Hoa Hornacis|1301905}\n<Assistant_Title2>Mẹo Thám Bí:</>\n{SendAnswer:1.Nhảy Linh Tính|882}: Trong khi khám phá, giữ nút Nhảy để vào trạng thái Nhảy Linh Tính; nhấn Nhảy lần nữa để vọt cao hơn~\n{SendAnswer:2.Linh Thị|883}: Nhấn nút Linh Thị để vào trạng thái Linh Thị, có thể phát hiện rương, manh mối nhiệm vụ và điểm giải đố có thể tương tác gần đó.",
    [527767191968768] = "<Assistant_Title1>【Nhà Thơ Du Ca】</>\n<Assistant_Title2>Giới Thiệu:</> Khi khám phá nhiều nơi, đôi lúc bạn sẽ nghe tiếng thì thầm có phương hướng rõ ràng vang bên tai. Lần theo âm thanh tới nguồn để tìm Nhà Thơ Du Ca.\n<Assistant_Title2>Hướng Dẫn:</>\n<Assistant_Title3>1. Tìm Nhà Thơ Du Ca</>\nCó thể tới bằng một trong các cách:\n<Assistant_Property2>Lối Vào Chạy Bàn:</> Mở Menu vào 【Chạy Bàn】, gia nhập một Giáo Đoàn bất kỳ, chọn 【Nhà Thơ Du Ca】 trong 【Thế Giới Trật Tự】 rồi nhấn 【Đi Tới】.\n<Assistant_Property1>Lối Vào Bản Đồ:</> Mở bản đồ, chuyển sang tab 【Thám Bí】, nhấn biểu tượng Nhà Thơ Du Ca để theo dõi và tự tìm đường.\n<Assistant_Title3>2. Lắng Nghe Giai Điệu</>\nTới mục tiêu, theo sóng âm dưới chân tìm nguồn, đối thoại với Nhà Thơ Du Ca và chọn cách tương tác.\n<Assistant_Title3>3. Hoàn Thành Thử Thách</>\nTìm Giai Điệu: bật <Assistant_System>Linh Thị</>, tìm ba nốt nhạc rải quanh đó; thu đủ để mở Rương Thưởng.\nNgâm Giai Điệu hoặc Phân Tích Giai Điệu: theo gợi ý hoàn thành kiểm định xúc xắc; thành công sẽ hoàn tất thử thách và nhận thưởng.",
    [527767191969024] = "<Assistant_Title1>【Truy Đuổi Bão Tố】</>\n<Assistant_Title2>Giới thiệu:</> Đua tốc độ là hình ảnh thu nhỏ của bão tố. Lái xe hơi nước lao qua phố ngõ, cưỡi gió vượt ghềnh, dùng Cú Nhảy Linh Tính vọt lên không trung để đuổi theo bước chân Chúa Tể Bão Tố, giành lấy vinh quang và quà tặng chỉ thuộc về bạn.\n<Assistant_Title2>Hướng dẫn:</>\n<Assistant_Title3>1. Tìm Truy Đuổi Bão Tố</>\nCó thể tới chế độ bằng một trong các cách:\n<Assistant_Property2>Cổng Chạy Đoàn:</> Mở Menu vào 【Chạy Đoàn】, gia nhập bất kỳ Giáo Đoàn nào, chọn 【Truy Đuổi Bão Tố】 trong 【Thế Giới Trật Tự】 rồi nhấn 【Đi Đến】 để tự tìm đường.\n<Assistant_Property1>Cổng Bản Đồ:</> Mở Bản Đồ, chuyển sang tab 【Thám Bí】, xem biểu tượng 【Truy Đuổi Bão Tố】 trong 【Chi Tiết Thế Giới】; tìm dấu tương ứng trên bản đồ theo chỉ dẫn rồi nhấn 【Đi Đến】 để tự tìm đường.\n<Assistant_Title3>2. Bắt đầu thử thách</>\nTới địa điểm mục tiêu, nói chuyện với Người Đam Mê Đua Xe và chọn bắt đầu thử thách đua.\n<Assistant_Title3>3. Hoàn thành cuộc đua</>\nSau khi vào vị diện đua, đi theo chỉ dẫn tuyến đường và tới đích trước khi đếm ngược kết thúc để hoàn thành.\n<Assistant_Title1>【Gợi Ý Trợ Lý】</>\nChạm <Assistant_Property1>vòng sáng trắng</> để nhận hiệu ứng tăng tốc.\nChạm <Assistant_Red>vòng sáng đỏ</> sẽ bị Giảm Tốc, nên cố gắng tránh.\nThử thách thất bại có thể bắt đầu lại!",
    [527767191969280] = "<Assistant_Title1>【Vật Dị Tượng】</>\n<Assistant_Title2>Giới Thiệu:</> Vật nhiễm Linh Tính hình thành do các sự kiện Phi Phàm tại địa phương; chỉ cần <Assistant_Red>chạm vào</> là có thể thu thập. Tích đủ số lượng có thể đem tới một Kẻ Gác Đêm để đổi thưởng.\n<Assistant_Title2>Hướng Dẫn:</>\n<Assistant_Title3>1. Thu Thập Vật Dị Tượng</>\nTrong khi khám phá, hãy chú ý các vật kết tinh phát sáng; tới gần và chạm để thu thập.\nCũng có thể tìm Vật Dị Tượng theo các cách sau:\n<Assistant_Property2>Lối Vào Chạy Đoàn:</> Mở menu vào 【Chạy Đoàn】, gia nhập bất kỳ Giáo Đoàn nào, chọn 【Vật Dị Tượng】 trong 【Thế Giới Trật Tự】 rồi nhấn 【Đi Đến】 để tự tìm đường.\n<Assistant_Property1>Lối Vào Bản Đồ:</> Mở bản đồ, chuyển sang tab 【Thám Bí】, xem biểu tượng 【Vật Dị Tượng】 trong 【Chi Tiết Thế Giới】; theo chỉ dẫn trên bản đồ, tìm ký hiệu tương ứng và nhấn 【Đi Đến】 để tự tìm đường.\n<Assistant_Title3>2. Đổi Thưởng</>\nSau khi thu thập đủ Vật Dị Tượng, tới gần <Assistant_Red>Công Ty An Ninh Blackthorn</> và nói chuyện với <Assistant_Red>Leonard</> để đổi thưởng.",
    [527767191969536] = "<Assistant_Title1>【Kỳ Ngộ Tìm Mèo】</>\n<Assistant_Title2>Giới Thiệu:</> Trên đường phố Tingen, đôi lúc bạn sẽ gặp một Linh Miêu với đoạn đối thoại đầy “hài hước kiểu Loen”.\n<Assistant_Title2>Hướng Dẫn:</>\n<Assistant_Title3>1. Tìm Linh Miêu</>\nCó thể tới bằng một trong các cách:\n<Assistant_Property2>Lối Vào Chạy Bàn:</> Mở Menu vào 【Chạy Bàn】, gia nhập một Giáo Đoàn bất kỳ, chọn 【Kỳ Ngộ Tìm Mèo】 trong 【Thế Giới Trật Tự】 rồi nhấn 【Đi Tới】.\n<Assistant_Property1>Lối Vào Bản Đồ:</> Mở bản đồ, chuyển sang tab 【Thám Bí】, xem biểu tượng 【Kỳ Ngộ Tìm Mèo】 trong 【Chi Tiết Thế Giới】, tìm dấu tương ứng rồi nhấn 【Đi Tới】.\n<Assistant_Title3>2. Phát Hiện Linh Miêu</>\nTới khu vực mục tiêu, nghe lén đối thoại NPC gần đó để lấy manh mối và theo hướng camera tìm Linh Miêu.\n<Assistant_Title3>3. Hoàn Thành Tương Tác</>\nĐối thoại với Linh Miêu và hoàn thành kiểm định xúc xắc.\n<Assistant_Red>Kiểm Định Thành Công:</> Nhận Rương Thưởng ngay.\n<Assistant_Red>Kiểm Định Thất Bại:</> Tiếp tục theo Linh Miêu hoàn thành đối thoại, vẫn nhận phần thưởng tương ứng.",
    [527767191969792] = "<Assistant_Title1>【Sợi Tơ Linh Thể】</>\n<Assistant_Title2>Giới thiệu:</> Chạm vào Sợi Tơ Linh Thể nối liền vạn vật để thiết lập liên kết, tiếp quản ý thức và biến đơn vị đó thành Bí Ngẫu của bạn. Đơn vị bị khống chế sẽ nghe theo mệnh lệnh của bạn.\n<Assistant_Title2>Hướng dẫn:</>\n<Assistant_Title3>1. Tìm Sợi Tơ Linh Thể</>\nCó thể tới chế độ bằng một trong các cách:\n<Assistant_Property2>Cổng Chạy Đoàn:</> Mở Menu vào 【Chạy Đoàn】, gia nhập bất kỳ Giáo Đoàn nào, chọn 【Sợi Tơ Linh Thể】 trong 【Thế Giới Trật Tự】 rồi nhấn 【Đi Đến】 để tự tìm đường.\n<Assistant_Property1>Cổng Bản Đồ:</> Mở Bản Đồ, chuyển sang tab 【Thám Bí】, xem biểu tượng 【Sợi Tơ Linh Thể】 trong 【Chi Tiết Thế Giới】; tìm dấu tương ứng trên bản đồ theo chỉ dẫn rồi nhấn 【Đi Đến】 để tự tìm đường.\n<Assistant_Title3>2. Điều khiển Bí Ngẫu</>\nTới khu vực mục tiêu, dùng kỹ năng <Assistant_Red>【Nhập Thân】</> để khống chế đơn vị chỉ định, rồi dùng năng lực của Bí Ngẫu hoàn thành thử thách tương ứng.\n<Assistant_Title3>3. Hoàn thành thử thách</>\nSau khi hoàn thành thành công, mở Rương và nhận thưởng.\n<Assistant_Title1>【Gợi Ý Trợ Lý】</>\nSau khi bật 【Nhập Thân】, các đơn vị có thể nhập thân thường xuất hiện nhãn <Assistant_Red>【Có Thể Nhập Thân】</> phía trên. Hãy chú ý quan sát xung quanh~",
    [527767191970048] = "<Assistant_Title1>【Không Gian Bí Ẩn】</>\n<Assistant_Title2>Giới Thiệu:</> Tiểu thư Fors “Nhà Ảo Thuật” dùng năng lực ẩn giấu không gian để che khuất một số khu vực mất kiểm soát, để lại các đồ đằng đặc biệt. Phi Phàm Giả có thể mở chúng, nhưng hãy cẩn thận: có xác suất bị truyền tống tới khu vực chưa biết.\n<Assistant_Title2>Hướng Dẫn:</>\n<Assistant_Title3>1. Tìm Không Gian Bí Ẩn</>\nCó thể tới bằng một trong các cách:\n<Assistant_Property2>Lối Vào Chạy Bàn:</> Mở Menu vào 【Chạy Bàn】, gia nhập một Giáo Đoàn bất kỳ, chọn 【Không Gian Bí Ẩn】 trong 【Thế Giới Trật Tự】 rồi nhấn 【Đi Tới】.\n<Assistant_Property1>Lối Vào Bản Đồ:</> Mở bản đồ, chuyển sang tab 【Thám Bí】, xem biểu tượng 【Không Gian Bí Ẩn】 trong 【Chi Tiết Thế Giới】, tìm dấu tương ứng rồi nhấn 【Đi Tới】.\n<Assistant_Title3>2. Vào Không Gian Bí Ẩn</>\nTới lối vào, tương tác với Hình Chiếu để vào Không Gian Bí Ẩn tương ứng.\n<Assistant_Title3>3. Hoàn Thành Thử Thách</>\nHoàn thành thử thách bên trong để nhận Rương Thưởng và tăng Tiến Độ Khám Phá tương ứng.",
    [527767191970304] = "<Assistant_Title1>【Rương Quỷ Biến】</>\n<Assistant_Title2>Giới Thiệu:</> Không một nhà thám hiểm dày dạn nào dễ dàng tin vào của cải không rõ nguồn gốc. Có chiếc đã mất chủ, có chiếc vẫn được canh giữ, cũng có chiếc chỉ là dấu vết của thời gian. Với Phi Phàm Giả, mỗi lần thử đều là một lựa chọn; mọi câu đố đang chờ bạn giải đáp. Hãy dùng vũ lực hoặc lừa gạt để thắng chúng và cho chúng biết ai mới là con mồi.\n<Assistant_Title2>Hướng Dẫn:</>\n<Assistant_Title3>1. Tìm Rương Quỷ Biến</>\nCó thể tới lối chơi bằng một trong các cách:\n<Assistant_Property2>Lối Vào Chạy Đoàn:</> Mở menu vào 【Chạy Đoàn】, gia nhập bất kỳ Giáo Đoàn nào, chọn 【Rương Quỷ Biến】 trong 【Thế Giới Trật Tự】 rồi nhấn 【Đi Đến】 để tự tìm đường.\n<Assistant_Property1>Lối Vào Bản Đồ:</> Mở bản đồ, chuyển sang tab 【Thám Bí】, xem biểu tượng 【Rương Quỷ Biến】 trong 【Chi Tiết Thế Giới】; theo chỉ dẫn trên bản đồ, tìm ký hiệu tương ứng và nhấn 【Đi Đến】 để tự tìm đường.\n<Assistant_Title3>2. Tương Tác Với Rương</>\nTới địa điểm mục tiêu, tương tác với chiếc rương kỳ lạ và chọn mở rương; hành động này sẽ kinh động kẻ địch quanh rương.\n<Assistant_Title3>3. Chọn Cách Ứng Phó</>\nSau khi bị phát hiện, có thể chọn cách xử lý khác nhau:\n<Assistant_Red>Đối Đầu Trực Diện:</> Đánh bại kẻ địch để nhận phần thưởng trong rương.\n<Assistant_Red>Kiểm Định Thiên Phú:</> Vượt kiểm định tương ứng cũng nhận được phần thưởng; nếu thất bại, phải chiến đấu hoàn thành thử thách.",
    [527767191970560] = "<Assistant_Title1>【Kho Báu Trùng Thời Gian】</>\n<Assistant_Title2>Giới Thiệu:</> Kho báu Trùng Thời Gian do “Thần Trò Đùa” Amon cất giấu nằm rải rác khắp nơi. Chạm Khe Nứt Thời Gian để gọi ra câu đố của Amon.\n<Assistant_Title2>Hướng Dẫn:</>\n<Assistant_Title3>1. Tìm Kho Báu Trùng Thời Gian</>\nCó thể tới bằng một trong các cách:\n<Assistant_Property2>Lối Vào Chạy Bàn:</> Mở Menu vào 【Chạy Bàn】, gia nhập một Giáo Đoàn bất kỳ, chọn 【Kho Báu Trùng Thời Gian】 trong 【Thế Giới Trật Tự】 rồi nhấn 【Đi Tới】 để tự tìm đường.\n<Assistant_Property1>Lối Vào Bản Đồ:</> Mở bản đồ, chuyển sang tab 【Thám Bí】, xem biểu tượng 【Kho Báu Trùng Thời Gian】 trong 【Chi Tiết Thế Giới】, tìm dấu tương ứng rồi nhấn 【Đi Tới】.\n<Assistant_Title3>2. Bắt Đầu Tìm Kho Báu</>\nTương tác với Khe Nứt Thời Gian và hoàn thành đối thoại với bóng kính một mắt để mở thử thách.\n<Assistant_Title3>3. Thu Thập Kho Báu</>\nTheo chỉ dẫn tìm các rương rải rác; thu đủ để mở Rương Cuối và nhận thưởng.\n<Assistant_Title1>【Gợi Ý Trợ Lý】</>\n<Assistant_Red>Linh Thị</> giúp phát hiện Rương Ẩn, nên dùng trong quá trình tìm nhé~\nMột số Rương Ẩn cần hoàn thành thử thách mới mở được.",
    [527767191970816] = "<Assistant_Title1>【Salon Thời Thượng】</>\n<Assistant_Title2>Giới Thiệu:</> Trong giới thượng lưu Vương quốc Loen, khả năng thưởng thức thời trang là biểu tượng của thân phận và sự tu dưỡng. Quý ông, quý cô có yêu cầu khắt khe với trang phục; phối đồ phù hợp hoàn cảnh, địa vị và mùa mới có thể giành được sự tôn trọng trong giới xã giao. Hãy thể hiện gu thẩm mỹ qua thử thách đánh giá và gây dựng danh tiếng trong thượng lưu.\n<Assistant_Title2>Hướng Dẫn:</>\n<Assistant_Title3>1. Tìm Salon Thời Thượng</>\nCó thể tới bằng một trong các cách:\n<Assistant_Property2>Lối Vào Chạy Bàn:</> Mở Menu vào 【Chạy Bàn】, gia nhập một Giáo Đoàn bất kỳ, chọn 【Salon Thời Thượng】 trong 【Thế Giới Trật Tự】 rồi nhấn 【Đi Tới】.\n<Assistant_Property1>Lối Vào Bản Đồ:</> Mở bản đồ, chuyển sang tab 【Thám Bí】, xem biểu tượng 【Salon Thời Thượng】 trong 【Chi Tiết Thế Giới】, tìm dấu tương ứng rồi nhấn 【Đi Tới】.\n<Assistant_Title3>2. PK Phối Đồ</>\nĐối thoại NPC để mở thử thách; phối đồ theo phong cách và điểm số, thắng PK nhận phần thưởng tương ứng.\n<Assistant_Title1>【Gợi Ý Trợ Lý】</>\nSalon Thời Thượng không tính vào Tiến Độ Hoàn Thành Thế Giới Trật Tự nhé~",
    [527767191971072] = "<Assistant_Title1>【Nhập Vai Phi Phàm】</> <Assistant_Title2>Giới Thiệu:</> Những <Assistant_Red>quang cầu</> chứa năng lực của Con Đường khác. Chạm vào để sử dụng Năng Lực Phi Phàm của nhiều Con Đường và tìm Rương Ẩn. <Assistant_Title2>Hướng Dẫn:</> <Assistant_Title3>1. Tìm Nhập Vai Phi Phàm</> Có thể tới hoạt động bằng một trong các cách: <Assistant_Property2>Lối Vào Chạy Bàn:</> Mở Menu vào 【Chạy Bàn】, gia nhập một Giáo Đoàn bất kỳ, chọn 【Nhập Vai Phi Phàm】 trong 【Thế Giới Trật Tự】 rồi nhấn 【Đi Tới】 để tự tìm đường. <Assistant_Property1>Lối Vào Bản Đồ:</> Mở bản đồ, chuyển sang tab 【Thám Bí】, xem biểu tượng 【Nhập Vai Phi Phàm】 trong 【Chi Tiết Thế Giới】, tìm dấu tương ứng trên bản đồ rồi nhấn 【Đi Tới】 để tự tìm đường. <Assistant_Title3>2. Nhập Vai Bậc Tương Ứng</> Tương tác với quang cầu, hoàn thành kiểm định để vào Nhập Vai Phi Phàm của Con Đường tương ứng và trải nghiệm năng lực riêng. <Assistant_Title3>3. Nhận Thưởng</> Hoàn tất nhập vai để nhận Rương Ẩn và tăng Tiến Độ Hoàn Thành của bản đồ.",
    [527767191974144] = "<Assistant_Title1>【Công Ty An Ninh Blackthorn】</>\n<Assistant_Title2>Loại Nhiệm Vụ:</><Assistant_Property2> Cốt Truyện Chính Nguyên Tác</>\n<Assistant_Title2>Mô Tả:</> Lời mời của Dunn quả thật rất hấp dẫn. Hãy tới Công Ty An Ninh Blackthorn xem thử; con người rồi cũng phải làm việc.\n<Assistant_Title2>Cách Nhận:</> Mở vào ngày thứ 3 của Mùa 1. Hoàn thành cốt truyện nguyên tác 《Vị Khách Bất Ngờ》 và đạt <Assistant_Red>Cấp Nhập Vai 48</> sẽ tự nhận.\n<Assistant_Title2>Phần Thưởng:</> EXP Nhận Thức, Suli Khóa, Bảng Vàng Khóa, Đèn Lịch Sử, Trang Bị",
    [527767191974912] = "<Assistant_Title1>【Hương Vị Ma Nữ Thật Không Tệ】</>\n<Assistant_Title2>Loại Nhiệm Vụ:</><Assistant_Property2> Nhánh</>\n<Assistant_Title2>Mô Tả:</> Tingen gần đây chẳng yên bình. Là người mới của tiểu đội Kẻ Gác Đêm, bạn cũng được giao một vụ án kỳ lạ. Nó dẫn tới một salon ở khu bắc Tingen, cùng bóng dáng bí ẩn đang lưu lại nơi đó...\n<Assistant_Title2>Cách Nhận:</> Khi Cấp Nhập Vai đạt <Assistant_Red>50</>, có thể nhận thủ công trong bảng Nhiệm Vụ.\n<Assistant_Title2>Phần Thưởng:</> EXP Nhận Thức, Suli Khóa, Bảng Vàng Khóa, Đèn Lịch Sử, Trang Bị, Tranh Treo · Lời Mời Đêm Xuân, Cặp Đôi · Nắm Tay, Danh Hiệu",
    [527767191975168] = "<Assistant_Title1>Lâu Đài</>\n<Assistant_Title2>Giải Thích Lối Chơi:</>\nNgười chơi tự xây <Assistant_Property2>Lâu Đài</>, có thể <Assistant_Property1>Xây Dựng</>, <Assistant_Property1>Sản Xuất Xưởng</>, <Assistant_Property1>Thu Mua Thị Trường</>, <Assistant_Property1>Railway Tycoon</>...\n<Assistant_Title2>Mở Khóa:</>\nPhi Phàm Giả Cấp Nhập Vai >19 hoàn thành Nhiệm Vụ Lâu Đài Kỳ Tích để mở; nhấn <Assistant_System>Menu-Lâu Đài</> để trở về.\n<Assistant_Title2>Điều Kiện Nâng Cấp:</>\n1. Cấp Lâu Đài hiện tại có thể nâng (Cấp tối đa mở dần theo số ngày server).\n2. <Assistant_Property2>Tổng Điểm Lâu Đài</> (tổng điểm cấu kiện) đạt yêu cầu.\n3. <Assistant_Property2>Điểm Xây Dựng Lâu Đài</> (tổng điểm cấu kiện thực tế đã đặt) đạt yêu cầu.\n4. Đủ điều kiện trên, tiêu hao một lượng <Assistant_Property2>Tài Sản Lâu Đài</> để nâng.\n<Assistant_Title2>Công Dụng Tài Sản:</>\n<Assistant_Property2>Vật Tư Lâu Đài</> dùng mua nội thất và nâng Lâu Đài.\n<Assistant_Title2>Nhận Tài Sản:</>\n1. Thưởng Nhiệm Vụ — hoàn thành nhiệm vụ <Assistant_Property1>Railway Tycoon</>.\n2. Thu Mua Thị Trường — bán sản phẩm Xưởng Lâu Đài cho lâu đài người khác.\n<Assistant_Title2>Lưu Trữ Tài Sản:</>\n1. Tài sản có giới hạn nhận theo tuần; vượt giới hạn sẽ không tích lũy. Tương tự, vượt giới hạn lưu trữ cũng không tích lũy.\n2. Giới hạn nhận theo tuần và giới hạn lưu trữ tăng cùng Cấp Lâu Đài.",
    [527767191975424] = "<Assistant_Title2>Giải Thích Trang Trí:</>\n1. Nhấn <Assistant_Property1>Trang Trí</> góc phải trên để vào <Assistant_Property2>Chế Độ Trang Trí Lâu Đài</>.\n2. Chức năng Trang Trí: <Assistant_Property1>Trang Trí Nội Thất</> (đặt, lát liên tục, thu hồi), <Assistant_Property1>Camera Thông Minh</> (góc nhìn tự do, từ trên xuống, bám theo), <Assistant_Property1>Chức Năng Nhanh</> (mua nhanh, thu hồi nhanh, ẩn/hiện tầng cao...).\n3. Chức năng nhanh: <Assistant_Property1>Xây Dựng Kỳ Tích</> (khoanh vùng, tự sinh cụm kiến trúc), <Assistant_Property1>Mẫu Lâu Đài</> (tải mẫu chính thức, nhanh chóng tạo lâu đài).\n<Assistant_Title2>Giao Diện Trang Trí:</>\n1. <Assistant_Property2>Thư Viện Nội Thất</>: Phía dưới là thư viện, có thể chọn, tìm và lọc nội thất.\n2. <Assistant_Property2>Camera Xây Dựng</>: Góc phải trên đổi góc camera.\n3. <Assistant_Property2>Điểm & Tiêu Hao</>: Khu điểm góc phải trên hiển thị <Assistant_Property2>Tổng Điểm Lâu Đài</> và số <Assistant_Property2>Tài Sản Lâu Đài</>.\n4. <Assistant_Property2>Trạng Thái Chọn Nội Thất</>: Khi đặt nội thất, màu xanh = có thể đặt; màu đỏ = không thể đặt.",
    [527767191975680] = "<Assistant_Title1>Lâu Đài-Xưởng</>\n<Assistant_Title2>Giới Thiệu:</>\n1. Sau khi bố trí <Assistant_Property1>Bí Ngẫu</>, có thể chọn và sản xuất nhiều loại <Assistant_Property2>Hàng Hóa</>.\n2. Nâng <Assistant_Property2>Xưởng</> để mở thêm Hàng Hóa.\n3. Nâng Xưởng tiêu hao <Assistant_Property2>Tài Sản Lâu Đài</> và bị giới hạn bởi Cấp Lâu Đài.\n<Assistant_Title2>Sản Xuất:</>\n1. <Assistant_Property1>Bí Ngẫu Ra Trận</>: Xưởng phải bố trí Bí Ngẫu mới bắt đầu sản xuất.\n2. <Assistant_Property2>Hàng Hiếm</>: Khi sản xuất có xác suất tạo Hàng Hiếm (giá bán cao hơn).\n3. <Assistant_Property1>Mẹo Sản Xuất</>: Xem danh sách thu mua giá cao tại Lâu Đài người khác, ưu tiên sản xuất hàng giá cao.",
    [527767191976448] = "<Assistant_Title1>【Bút Ký Antigonus】</>\n<Assistant_Title2>Loại Nhiệm Vụ:</><Assistant_Property2>Cốt Truyện Chính Nguyên Tác</>\n<Assistant_Title2>Mô Tả:</> Linh hồn lạc lối say ngủ trong giấc mộng cũ vỡ nát.\n<Assistant_Title2>Cách Nhận:</> Mở vào ngày 9 của Mùa 1. Hoàn thành Chương 5 cốt truyện nguyên tác 《Ủy Thác Chính Thức Đầu Tiên》 và đạt <Assistant_Red>Cấp Nhập Vai 63</>, nhiệm vụ sẽ tự động nhận.\n<Assistant_Title2>Phần Thưởng</>：EXP Nhận Thức, Soles Khóa, Bảng Vàng Khóa, Đèn Sáng Lịch Sử\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Phó Bản · Bút Ký Antigonus]|18}",
    [527767191976704] = "<Assistant_Title1>【Mộng Đẹp Thành Thật】</>\n<Assistant_Title2>Loại Nhiệm Vụ:</><Assistant_Property2> Nhánh</>\n<Assistant_Title2>Mô Tả:</> Hộp quà phủ bụi trong góc phòng, không biết đang cất giữ tâm ý của ai...\n<Assistant_Title2>Cách Nhận:</> Khi Cấp Nhập Vai đạt <Assistant_Red>28</>, có thể nhận thủ công trong bảng Nhiệm Vụ.\n<Assistant_Title2>Phần Thưởng:</> EXP Nhận Thức, Suli Khóa, Bảng Vàng Khóa, Chỉ Dệt Vàng, Trang Bị",
    [527767191978240] = "<Assistant_Title1>【Mặt Trời Trong Lòng Bàn Tay】</> <Assistant_Title2>Loại Nhiệm Vụ:</><Assistant_Property2>Câu Chuyện Nhập Vai</> <Assistant_Title2>Mô Tả:</> Cô bé mù Emily Morrison dùng đầu ngón tay chạm vào thế giới, dùng những câu chuyện sưởi ấm bóng tối nhưng chưa từng chạm được hình dáng của “ánh sáng”. Với tư cách Thần Quan Mặt Trời, hãy dùng Thánh Quang Thùy Mộ triệu hồi ánh sáng cho cô, giúp cô cảm nhận hơi ấm của ánh sáng, lắng nghe câu chuyện và chứng kiến rằng “ý nghĩa của ánh sáng là soi sáng cho nhau”. <Assistant_Title2>Cách Nhận:</> Hoàn thành nhiệm vụ Thăng Cấp, thăng lên Bậc 7; tới {Location:[Tingen(776,692)]\\|-22380;-31065;-1409;2;5200002;0} để kích hoạt nhiệm vụ. <Assistant_Title2>Phần Thưởng:</> Kinh Nghiệm Nhận Thức, tiến độ Bí Bảo Mạo Hiểm Thế Giới, Huân Chương Mạo Hiểm, Hóa Đơn.",
    [527767191978496] = "<Assistant_Title1>【Vũ Khí Tốt Nhất】</> <Assistant_Title2>Loại Nhiệm Vụ:</><Assistant_Property2>Câu Chuyện Nhập Vai</> <Assistant_Title2>Mô Tả:</> Có người bán súng cũ han gỉ ở chợ, chủ sạp nói chỉ để trang trí. Bạn tinh mắt chọn một khẩu tưởng đã phế, sửa kim hỏa ngay tại chỗ rồi bắn trúng một phát, khiến mọi người kinh ngạc. <Assistant_Title2>Nhận:</> Hoàn thành Nhiệm Vụ Thăng Cấp, đạt Bậc 7, tới {Location:[Tingen(757,1118)]\\|-24012;11883;-2064;2;5200002;0} để kích hoạt nhiệm vụ <Assistant_Title2>Phần Thưởng</>: Kinh Nghiệm Nhận Thức, Suli Khóa, Hóa Đơn, Huân Chương Mạo Hiểm, tiến độ Bí Bảo Mạo Hiểm Thế Giới",
    [527767191991552] = "<Assistant_Title1>【Gia Nhập Blackthorn】</>\n<Assistant_Title2>Loại Nhiệm Vụ:</><Assistant_Property2>Chính Tuyến Hiện Thực</>\n<Assistant_Title2>Mô Tả:</> Tỉnh dậy trong quán cà phê sáng sủa, trước mặt là một thiếu nữ quý tộc và một... chú chó Golden?\n<Assistant_Title2>Nhận:</> Mở ngày đầu Mùa 1. Hoàn thành Prologue 《Khởi Đầu Của Mọi Thứ》 và Cấp Nhập Vai đạt <Assistant_Red>9</> sẽ tự nhận.\n<Assistant_Title2>Phần Thưởng</>: Kinh Nghiệm Nhận Thức, Suli Khóa, Bảng Vàng Khóa, Điển Bào Kẻ Gác Đêm, Xe Đạp · Hồ Đào, Xã Giao · Nghỉ Tan Làm, Trang Bị, Bí Tinh · Trở Về, Thuần Lộ Sinh Mệnh Sơ Cấp, Ví Tinh Xảo",
    [527767191991808] = "<Assistant_Title1>【Làn Sóng Thời Đại】</>\n<Assistant_Title2>Loại Nhiệm Vụ:</><Assistant_Property2>Chính Tuyến Hiện Thực</>\n<Assistant_Title2>Mô Tả:</> Làn sóng thời đại đang quét qua Tingen. Hãy cưỡi xe đạp của nhân viên mới Blackthorn và đi dạo khắp nơi.\n<Assistant_Title2>Nhận:</> Mở ngày thứ hai Mùa 1. Hoàn thành Chương 1 chính tuyến 《Gia Nhập Blackthorn》 và Cấp Nhập Vai đạt <Assistant_Red>39</> sẽ tự nhận.\n<Assistant_Title2>Phần Thưởng</>: Kinh Nghiệm Nhận Thức, Suli Khóa, Bảng Vàng Khóa, Thuần Lộ Sinh Mệnh Trung Cấp, Tinh Tệ, Hộp Vũ Khí",
    [527767191992064] = "<Assistant_Title1>【Gia Tộc】</>\n<Assistant_Title2>Cấp Mở:</> Cấp Nhận Thức <Assistant_Red>37</>\n<Assistant_Title2>Lối Vào:</><Assistant_System>Menu - Gia Tộc</>{JumpToUI:[【Đến Xem】]|1250091}\n<Assistant_Title2>Giới Thiệu:</> Nhân danh Gia Tộc, lấy lời thề làm khóa, trở thành mỏ neo của nhau bên bờ vực Vận Mệnh. Tìm những người bạn cùng mục tiêu để lập Khế Ước Gia Tộc, hoàn thành nhiệm vụ Gia Tộc tăng cấp và nhận <Assistant_Property1>Huy Chương Đồng Hành</> đổi <Assistant_Property1>phần thưởng quý</>.\n<Assistant_Title3>Quy Tắc Chi Tiết:</>{SendAnswer:[Gia Tộc - Cách Lập Khế Ước]|666}，{SendAnswer:[Gia Tộc - Giải Thích Phần Thưởng]|667}，{SendAnswer:[Gia Tộc - Quy Tắc Cấp]|668}，{SendAnswer:[Gia Tộc - Quy Tắc Kệ Trưng Bày]|669}",
    [527767191992576] = "<Assistant_Title1>【Gia Tộc - Giải Thích Phần Thưởng】</>\n<Assistant_Title2>Buff thuộc tính Gia Tộc:</> Trong Phó Bản, tổ đội với đủ số thành viên cùng Gia Tộc sẽ nhận thêm <Assistant_Property1>số lần hồi sinh</> và <Assistant_Property1>bù thuộc tính</>; sau khi rời Gia Tộc có <Assistant_Red>24 giờ</> chờ hiệu lực.\n<Assistant_Title2>Buff thưởng Phó Bản:</> Trong một số Phó Bản chỉ định, khi tổ đội đủ số thành viên cùng Gia Tộc và vượt ải sẽ nhận <Assistant_Property1>phần thưởng thêm</>; sau khi rời Gia Tộc có <Assistant_Red>24 giờ</> chờ hiệu lực.\n<Assistant_Title2>Thưởng Cửa Hàng Gia Tộc:</> Hoàn thành Nhiệm Vụ Gia Tộc nhận <Assistant_Property1>Điểm Ăn Ý</> và <Assistant_Property1>Huy Chương Đồng Hành</>. Khi đạt Cấp Gia Tộc và thời gian gia nhập yêu cầu, có thể tới <Assistant_System>Cửa Hàng Đồng Hành</> để đổi <Assistant_Property1>phần thưởng quý</>.\n<Assistant_Title2>Danh Hiệu Gia Tộc:</> Gia nhập Gia Tộc tự động nhận <Assistant_Property1>Danh Hiệu Gia Tộc</>. Thủ Lĩnh có thể đổi tên Gia Tộc trong Chi Tiết Gia Tộc; đổi tên có <Assistant_Red>30 ngày</> hồi chiêu, sau khi đổi thành công Danh Hiệu Gia Tộc cũng đổi theo.\n<Assistant_Title2>Sân Trưng Bày Gia Tộc:</> Khi Cấp Gia Tộc tăng sẽ mở khóa cảnh độc quyền dùng cho Sân Trưng Bày Gia Tộc; xem chi tiết tại <Assistant_Property1>Gia Tộc - Quy Tắc Sân Trưng Bày</>.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Gia Tộc]|665}，{SendAnswer:[Gia Tộc - Cách Khế Ước]|666}，{SendAnswer:[Gia Tộc - Quy Tắc Cấp]|668}，{SendAnswer:[Gia Tộc - Quy Tắc Sân Trưng Bày]|669}",
    [527767191992832] = "<Assistant_Title1>【Gia Tộc - Quy Tắc Cấp】</>\n<Assistant_Title2>Độ Ăn Ý và Cấp:</> Hoàn thành nhiệm vụ tuần của Gia Tộc để nhận Độ Ăn Ý và tăng cấp Gia Tộc; giới hạn Độ Ăn Ý mỗi tuần là <Assistant_Red>2000 điểm</>.\n<Assistant_Title2>Nhiệm Vụ Tuần:</> Thành viên Gia Tộc lập đội tham gia nội dung tương ứng để nhận Độ Ăn Ý.\n    <Assistant_Property1>Độ Ăn Ý Bội Cao:</> Một số lần hoàn thành đầu tiên của từng nhiệm vụ trong tuần nhận hệ số cao; vượt số lần này chỉ nhận hệ số thường.\n    <Assistant_Property1>Thời Gian Làm Mới:</> Nhiệm vụ làm mới mỗi tuần.\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Gia Tộc]|665}，{SendAnswer:[Gia Tộc - Cách Lập Khế Ước]|666}，{SendAnswer:[Gia Tộc - Giải Thích Phần Thưởng]|667}，{SendAnswer:[Gia Tộc - Quy Tắc Kệ Trưng Bày]|669}",
    [527767191993088] = "<Assistant_Title1>【Gia Tộc - Quy Tắc Kệ Trưng Bày】</>\n<Assistant_Title2>Lối Vào:</><Assistant_System>Menu - Gia Tộc - Chỉnh Sửa Kệ Trưng Bày</>\n<Assistant_Title2>Quyền Chỉnh Sửa:</> Thành viên Gia Tộc có thân phận khác nhau được chỉnh các nội dung khác nhau trên Kệ Trưng Bày.\n    <Assistant_Property1>Thành Viên Thường:</> Chỉ nhân vật của bản thân.\n    <Assistant_Property1>Thủ Lĩnh:</> Toàn bộ nhân vật thành viên (phạm vi động tác có thể cài theo nội dung người chơi tương ứng đã mở), <Assistant_Property1>Camera</>, <Assistant_Property1>Cảnh</> (phạm vi có thể cài theo nội dung Thủ Lĩnh đã mở), <Assistant_Property1>Trang Trí Cảnh</> (phạm vi có thể cài theo nội dung Thủ Lĩnh đã mở), <Assistant_Property1>Hướng Gió</>, <Assistant_Property1>Chỉnh Màu</>.\n<Assistant_Title2>Xóa Khỏi Kệ:</> Khi thành viên rời Gia Tộc, các nội dung sau của người đó trên Kệ Trưng Bày sẽ tự động bị xóa:\n    <Assistant_Property1>Nhân Vật Trưng Bày</>\n    <Assistant_Property1>Cảnh</> (nếu có dùng)\n    <Assistant_Property1>Trang Trí Cảnh</> (nếu có dùng)\n<Assistant_Title2>Mở Kệ Trưng Bày:</> Khi Gia Tộc tăng cấp, cảnh chuyên dụng cho Kệ Trưng Bày Gia Tộc lần lượt mở ở Cấp 2 và Cấp 6; các cảnh này chỉ dùng được trong Kệ Trưng Bày Gia Tộc.\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Gia Tộc]|665}，{SendAnswer:[Gia Tộc - Cách Lập Khế Ước]|666}，{SendAnswer:[Gia Tộc - Giải Thích Phần Thưởng]|667}，{SendAnswer:[Gia Tộc - Quy Tắc Cấp]|668}",
    [527767191994112] = "<Assistant_Title1>【Độc Đằng】</>\n<Assistant_Title2>Mô Tả:</> Trang Phục Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Độc Đằng; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Kỳ Trang Tinh Linh</>",
    [527767191996928] = "<Assistant_Title1>【Pháp Bào Tinh Huy】</>\n<Assistant_Title2>Mô Tả:</> Trang phục bán trực tiếp trong Cửa Hàng\n<Assistant_Title2>Sử Dụng:</> Mua trong Cửa Hàng để nhận bộ Pháp Bào Tinh Huy; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Nhận từ <Assistant_System>Cửa Hàng</>",
    [527767191999744] = "<Assistant_Title1>【Vịnh Thán và Tuyên Tự】</>\n<Assistant_Title2>Mô Tả:</> Trang Phục Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Vịnh Thán và Tuyên Tự; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Kỳ Trang Tinh Linh</>",
    [527767192002048] = "<Assistant_Title1>【Kim Chi Sâm Ảnh】</>\n<Assistant_Title2>Mô Tả:</> Trang Phục Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Kim Chi Sâm Ảnh; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng, hoặc đổi thành <Assistant_Red>2</> Thẻ Thần Quyến.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Hoán Nhan Linh Giới</>, hoặc tại <Assistant_System>Cửa Hàng Quà Tặng Mỹ Thần</> dùng <Assistant_Red>2</> Thẻ Thần Quyến để đổi",
    [527767192002304] = "<Assistant_Title1>【Lễ Phục Tụng Thi】</>\n<Assistant_Title2>Mô Tả:</> Trang Phục Hồ Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Lễ Phục Tụng Thi; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Hoán Nhan Linh Giới</>",
    [527767192002560] = "<Assistant_Title1>【Sa Mạc Liệt Nhật】</>\n<Assistant_Title2>Mô Tả:</> Trang Phục Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Sa Mạc Liệt Nhật; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Kỳ Trang Tinh Linh</>",
    [527767192003584] = "<Assistant_Title1>【Cắt Đặc Biệt · Liệt Nhật】</>\n<Assistant_Title2>Mô Tả:</> Kiểu tóc Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Cắt Đặc Biệt · Liệt Nhật; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</><Assistant_System>Triệu Hồi - Tinh Linh Kỳ Trang mở sau tổng 200 lần triệu hồi",
    [527767192006400] = "<Assistant_Title1>【Đọa Lạc Đồ Lục】</>\n<Assistant_Title2>Mô Tả:</> Ngoại Hình Vũ Khí Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Đọa Lạc Đồ Lục; vào <Assistant_System>Ngoại Hình-Vũ Khí</> để xem và dùng.\n<Assistant_Title2>Nhận:</> Tại <Assistant_System>Triệu Hồi-Hoán Nhan Linh Giới-Cửa Hàng Quà Tặng Mỹ Thần</> dùng <Assistant_Red>1</> Thẻ Thần Quyến để đổi",
    [527767192008448] = "<Assistant_Title1>【Xiếc Hoang Đường】</>\n<Assistant_Title2>Mô Tả:</> Trang phục rơi từ Phó Bản\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Xiếc Hoang Đường; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Nhận từ <Assistant_System>Phó Bản - Bút Ký Antigonus</>",
    [527767192008704] = "<Assistant_Title1>【Giáp Tổ Tiên】</>\n<Assistant_Title2>Mô Tả:</> Trang phục rơi từ Phó Bản\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Giáp Tổ Tiên; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Nhận từ <Assistant_System>Phó Bản - Trang Viên Tháng Năm · Khu Vườn</>",
    [527767192008960] = "<Assistant_Title1>【Phu Nhân Tử Tước】</>\n<Assistant_Title2>Mô Tả:</> Trang phục rơi từ Phó Bản\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Phu Nhân Tử Tước; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Nhận từ <Assistant_System>Phó Bản - Trang Viên Tháng Năm · Lâu Đài</>",
    [527767192009216] = "<Assistant_Title1>【Tín Đồ Số Một】</>\n<Assistant_Title2>Mô Tả:</> Kiểu tóc rơi từ Phó Bản\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Tín Đồ Số Một; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Nhận từ <Assistant_System>Phó Bản - Trang Viên Tháng Năm · Lâu Đài</>",
    [527767192009728] = "<Assistant_Title1>【Lụa Tàn Đêm Vĩnh Hằng】</>\n<Assistant_Title2>Mô Tả:</> Phụ kiện rơi từ Phó Bản\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Lụa Tàn Đêm Vĩnh Hằng; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Nhận từ <Assistant_Link>{SendAnswer:[Trang Viên Tháng Năm · Lâu Đài]|21}</>",
    [527767192009984] = "<Assistant_Title1>【Dư Huy Sương Mù】</>\n<Assistant_Title2>Mô Tả:</> Phụ kiện rơi từ Phó Bản\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Dư Huy Sương Mù; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Nhận từ <Assistant_System>Phó Bản - Trang Viên Tháng Năm · Lâu Đài</>",
    [527767192010240] = "<Assistant_Title1>【Vinh Quang Thất Lạc】</>\n<Assistant_Title2>Mô Tả:</> Phụ kiện rơi từ Phó Bản\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Vinh Quang Thất Lạc; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Nhận từ <Assistant_System>Phó Bản - Trang Viên Tháng Năm · Khu Vườn</>",
    [527767192010496] = "<Assistant_Title1>【Chuông Trang Viên】</>\n<Assistant_Title2>Mô Tả:</> Phụ kiện rơi từ Phó Bản\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Chuông Trang Viên; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Nhận từ <Assistant_System>Phó Bản - Trang Viên Tháng Năm · Khu Vườn</>",
    [527767192010752] = "<Assistant_Title1>【Thỏ Con Barney】</>\n<Assistant_Title2>Mô Tả:</> Phụ kiện rơi từ Phó Bản\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Thỏ Con Barney; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Nhận từ <Assistant_System>Phó Bản - Trang Viên Tháng Năm · Lâu Đài</>",
    [527767192011776] = "<Assistant_Title1>【Máy Hát Đồng Thau】</>\n<Assistant_Title2>Mô Tả:</> Vật Trưng Bày rơi từ Phó Bản\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Máy Hát Đồng Thau; có thể vào <Assistant_System>Ngoại Hình - Kệ Trưng Bày</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Nhận từ <Assistant_System>Phó Bản - Trang Viên Tháng Năm</>",
    [527767192012032] = "<Assistant_Title1>【Trang Phục Học Đồ】</>\n<Assistant_Title2>Mô Tả:</> Trang phục thưởng Thăng Bậc\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Trang Phục Học Đồ; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Đăng nhập nhận trang phục có thời hạn; sau đó có thể nhận bản vĩnh viễn qua <Assistant_System>Thăng Bậc</>.",
    [527767192012288] = "<Assistant_Title1>【Trang Phục Thầy Bói】</>\n<Assistant_Title2>Mô Tả:</> Trang phục thưởng Thăng Bậc\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ trang phục; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Đăng nhập nhận trang phục có thời hạn; sau đó có thể nhận bản vĩnh viễn qua <Assistant_System>Thăng Bậc</>.",
    [527767192012544] = "<Assistant_Title1>【Trang Phục Kẻ Dòm Ngó Bí Ẩn】</>\n<Assistant_Title2>Mô Tả:</> Trang phục thưởng Thăng Bậc\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Trang Phục Kẻ Dòm Ngó Bí Ẩn; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Đăng nhập nhận trang phục có thời hạn; sau đó có thể nhận bản vĩnh viễn qua <Assistant_System>Thăng Bậc</>.",
    [527767192012800] = "<Assistant_Title1>【Trang Phục Chiến Sĩ】</>\n<Assistant_Title2>Mô Tả:</> Trang phục thưởng Thăng Bậc\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Trang Phục Chiến Sĩ; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Đăng nhập nhận trang phục có thời hạn; sau đó có thể nhận bản vĩnh viễn qua <Assistant_System>Thăng Bậc</>.",
    [527767192013056] = "<Assistant_Title1>【Trang Phục Ca Tụng Giả】</>\n<Assistant_Title2>Mô Tả:</> Trang phục thưởng Thăng Bậc\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Trang Phục Ca Tụng Giả; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</><Assistant_Title2>Nguồn:</> Đăng nhập nhận trang phục có thời hạn; sau đó có thể nhận bản vĩnh viễn qua <Assistant_System>Thăng Bậc</>.",
    [527767192013312] = "<Assistant_Title1>【Trang Phục Khán Giả】</>\n<Assistant_Title2>Mô Tả:</> Trang phục thưởng Thăng Bậc\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Trang Phục Khán Giả; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</><Assistant_Title2>Nguồn:</> Đăng nhập nhận trang phục có thời hạn; sau đó có thể nhận bản vĩnh viễn qua <Assistant_System>Thăng Bậc</>.",
    [527767192015616] = "<Assistant_Title1>【Bục Trưng Bày · Chĩa Súng】</>\n<Assistant_Title2>Mô Tả:</> Động tác Bục Trưng Bày thưởng từ PvP\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Bục Trưng Bày · Chĩa Súng; có thể vào <Assistant_System>Ngoại Trang - Bục Trưng Bày</> để xem và sử dụng.\n<Assistant_Title2>Nguồn Nhận:</> Dùng Huy Chương Khải Hoàn đổi tại <Assistant_System>Shop - Bách Hóa - Cửa Hàng Khải Hoàn</>.",
    [527767192016384] = "<Assistant_Title1>【Khải Thị Tinh Bàn】</>\n<Assistant_Title2>Mô Tả:</> Trang phục thưởng Cấp Giáo Đoàn\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Khải Thị Tinh Bàn; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Mở theo Cấp Giáo Đoàn",
    [527767192016640] = "<Assistant_Title1>【Dư Vị Ma Nữ】</>\n<Assistant_Title2>Mô Tả:</> Trang phục thưởng Cấp Giáo Đoàn\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Dư Vị Ma Nữ; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Mở theo Cấp Giáo Đoàn",
    [527767192016896] = "<Assistant_Title1>【Tâm Tự Tỉnh】</>\n<Assistant_Title2>Mô Tả:</> Phụ kiện thưởng Cấp Giáo Đoàn\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Tâm Tự Tỉnh; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Mở theo Cấp Giáo Đoàn",
    [527767192017152] = "<Assistant_Title1>【Kính Gọng Tròn Lớn】</>\n<Assistant_Title2>Mô Tả:</> Phụ kiện thưởng Cấp Giáo Đoàn\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Kính Gọng Tròn Lớn; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Mở theo Cấp Giáo Đoàn",
    [527767192017408] = "<Assistant_Title1>【Tâm Xà】</>\n<Assistant_Title2>Mô Tả:</> Phụ kiện thưởng Cấp Giáo Đoàn\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Tâm Xà; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Mở theo Cấp Giáo Đoàn",
    [527767192017664] = "<Assistant_Title1>【Nhẫn Ngọc Lục Bảo】</>\n<Assistant_Title2>Mô Tả:</> Phụ kiện thưởng Cấp Giáo Đoàn\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Nhẫn Ngọc Lục Bảo; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Mở theo Cấp Giáo Đoàn",
    [527767192017920] = "<Assistant_Title1>【Tượng Ma Nữ】</>\n<Assistant_Title2>Mô Tả:</> Linh kiện Kệ Trưng Bày thưởng Cấp Giáo Đoàn\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Tượng Ma Nữ; có thể vào <Assistant_System>Ngoại Hình - Kệ Trưng Bày</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Mở theo Cấp Giáo Đoàn",
    [527767192018176] = "<Assistant_Title1>【Chân Nến Tinh Nguyệt】</>\n<Assistant_Title2>Mô Tả:</> Linh kiện Kệ Trưng Bày thưởng Cấp Giáo Đoàn\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Chân Nến Tinh Nguyệt; có thể vào <Assistant_System>Ngoại Hình - Kệ Trưng Bày</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Mở theo Cấp Giáo Đoàn",
    [527767192025344] = "<Assistant_Title1>【Hàm Vĩ】</>\n<Assistant_Title2>Mô Tả:</> Phụ kiện thưởng từ gameplay\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Hàm Vĩ; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Nhận từ <Assistant_System>Gameplay - Công Hội</>",
    [527767192046080] = "<Assistant_Title1>【Mặt Tối Thành Phố】</>\n<Assistant_Title2>Giới Thiệu:</> Theo chỉ dẫn của tiểu thư “Chính Nghĩa”, bạn bước vào thế giới hình thành từ vô thức tập thể của Tingen. Mọi thứ xảy ra tại đây không trực tiếp ảnh hưởng hiện thực, nhưng thanh trừ ác ý trong vô thức sẽ làm dao động nguồn gốc ngoài đời. Hãy đi sâu vào hiện trường, hoàn thành sự kiện Cốt Truyện, Thử Thách và Thi Đấu để cứu thành phố.\n<Assistant_Title2>Hướng Dẫn:</>\n1. Hoàn thành cốt truyện <Assistant_System>“Tingen Tội Ác”</> để mở hệ thống; mở bản đồ, chuyển sang tab Thám Bí rồi tab “Mặt Tối Thành Phố”, chọn biểu tượng sự kiện đã mở và nhấn Đi Tới để tự tìm đường.\n2. Tới khu vực chỉ định, đối thoại NPC liên quan hoặc dùng phương thức tương ứng để mở sự kiện.\n3. Hoàn thành {SendAnswer:Sự Kiện|877} để nhận thưởng.\n<Assistant_Title2>Đặc Điểm Khu Vực:</>\nTrong Tingen Tội Ác, điều khiển xe dùng chế độ lái thực tế.\n<Assistant_Title2>Gợi Ý Tân Thủ:</>\n1. Lần đầu vào nên ưu tiên hoàn thành Cốt Truyện Chính trong Tingen Tội Ác để mở thêm lối chơi.\n2. Sự kiện <Assistant_Red>Kịch Chiến · Bonnie</> yêu cầu đạt Điểm Phi Phàm và Cấp đề xuất.\n3. Mỗi ngày mở giới hạn giờ cho sự kiện PvP nhiều người; tranh tài với người chơi khác để giành thưởng xếp hạng.",
    [527767192046336] = "<Assistant_Title1>【Sự Kiện】</>\n<Assistant_Title2>Mục tiêu sự kiện:</> Mặt Tối Thành Phố liên tục xảy ra nhiều sự kiện đột phát. Tham gia và hoàn thành sự kiện để nhận thưởng Treo Thưởng và đẩy tiến độ chế độ.\n<Assistant_Title2>Mẹo:</> Ưu tiên hoàn thành {SendAnswer:Sự Kiện Cốt Truyện|879} để dần mở thêm {SendAnswer:Sự Kiện Thử Thách|880} và {SendAnswer:Sự Kiện Cạnh Tranh|881}, trải nghiệm đầy đủ nội dung Mặt Tối Thành Phố.\n<Assistant_Title2>1. Loại sự kiện (3 loại):</>\n<Assistant_Title3>①Sự Kiện Cốt Truyện:</> Đẩy cốt truyện, mở thêm nội dung chế độ.\n<Assistant_Title3>②Sự Kiện Thử Thách:</> Hoàn thành boss challenge, đua tốc độ và các chế độ khác để nhận nhiều phần thưởng. Lưu ý: Kịch Chiến · Bonnie sẽ chuyển đổi thuộc tính theo Lực Chiến của người chơi, ảnh hưởng độ khó.\n<Assistant_Title3>③Sự Kiện Cạnh Tranh:</> Tham gia tranh tài nguyên, truy đuổi và thi đấu cùng người chơi khác.\n<Assistant_Title2>2. Quy tắc làm mới:</> Chỉ hiển thị sự kiện đã mở khóa và đạt điều kiện hiện tại. Khi cốt truyện tiến triển, nhiều sự kiện hơn sẽ dần mở.\n<Assistant_Title3>Sự Kiện Cốt Truyện:</> Mở khi hoàn thành điều kiện trước, không làm mới ngẫu nhiên.\n<Assistant_Title3>Sự Kiện Thử Thách:</> Sau khi đạt điều kiện mở sẽ liên tục làm mới; hoàn thành xong khoảng 10 giây sẽ xuất hiện lại.\n<Assistant_Title3>Sự Kiện Cạnh Tranh:</> Mở ghép trận vào giờ chỉ định mỗi ngày; ghép thành công thì bắt đầu.\n<Assistant_Title2>3. Quy tắc phần thưởng:</>\n<Assistant_Title3>①Sự Kiện Cốt Truyện:</> Hoàn thành là nhận thưởng.\n<Assistant_Title3>②Sự Kiện Thử Thách:</> Đua tốc độ phát thưởng theo xếp hạng; Kịch Chiến · Bonnie có thưởng theo mốc biểu hiện; sự kiện Boss Khó không có mốc thưởng.\n<Assistant_Title3>③Sự Kiện Cạnh Tranh:</> Phát thưởng theo xếp hạng cuối.\n<Assistant_Title2>4. Giới hạn thưởng:</> Không giới hạn số lần nhận thưởng sự kiện, nhưng Điểm Treo Thưởng nhận mỗi tuần có giới hạn. Sau khi đạt giới hạn vẫn có thể tham gia sự kiện, nhưng không nhận thêm Điểm Treo Thưởng.\n<Assistant_Title2>5. Điều kiện thất bại:</>\nKhông hoàn thành mục tiêu trong thời gian quy định.\nTrong sự kiện rời khu vực quá xa sẽ được xem là chủ động từ bỏ.",
    [527767192046848] = "<Assistant_Title1>【Sự Kiện Cốt Truyện】</>\n<Assistant_Title2>Giới Thiệu:</> Sự Kiện Cốt Truyện ghi lại các vụ án xảy ra trong Tingen Tội Ác. Hoàn thành để thúc đẩy Chính Tuyến Tingen Tội Ác, dần mở Nhánh mới và vén màn bí mật ẩn trong mặt tối thành phố.\n<Assistant_Title2>Quy Tắc Mở:</>\n1. Hoàn thành Sự Kiện Cốt Truyện tiên quyết.\n2. Một số sự kiện yêu cầu đạt Cấp.\n<Assistant_Title2>Gợi Ý Trợ Lý:</>\n1. Lần đầu tham gia nên ưu tiên vượt Sự Kiện Cốt Truyện.\n2. Sự Kiện Cốt Truyện sẽ mở Sự Kiện Thử Thách, Sự Kiện Thi Đấu và thêm nội dung cốt truyện, thúc đẩy tiến độ hoạt động.",
    [527767192047104] = "<Assistant_Title1>【Sự Kiện Thử Thách】</>\n<Assistant_Title2>Giới Thiệu:</> Gồm nhiều loại như Thử Thách Boss, Thử Thách Tốc Độ và Kịch Chiến · Bonnie. Hoàn thành thử thách nhận phần thưởng tương ứng; một số thử thách chia hạng thưởng theo thành tích.\n<Assistant_Title2>Quy Tắc Mở:</>\n1. Hoàn thành Sự Kiện Cốt Truyện hoặc Sự Kiện Thử Thách tiên quyết.\n2. <Assistant_Red>Kịch Chiến · Bonnie</> yêu cầu đạt Cấp và Điểm Phi Phàm chỉ định.\n<Assistant_Title2>Gợi Ý:</>\n1. Có thể xem hướng dẫn Boss và thử lại nhiều lần!\n2. Một số thử thách có quy tắc đặc biệt, hãy xem mô tả chi tiết trước khi tham gia.",
    [527767192047360] = "<Assistant_Title1>【Sự Kiện Cạnh Tranh】</>\n<Assistant_Title2>Giới Thiệu:</> Bao gồm các gameplay như tranh tài nguyên và đua truy đuổi. Thi đấu cùng người chơi khác và nhận thưởng theo thứ hạng cuối cùng.\n<Assistant_Title2>Quy Tắc Mở:</>\n1. Hoàn thành sự kiện cốt truyện tiền đề chỉ định.\n2. Mở vào khung giờ cố định mỗi ngày.\n<Assistant_Title2>Gợi Ý:</>\n1. Nên chú ý trước thời gian mở.\n2. Thử thách cạnh tranh có thưởng xếp hạng; hạng càng cao, thưởng càng nhiều.",
    [527767192047616] = "<Assistant_Title1>【Bước Nhảy Linh Tính】</>\n<Assistant_Title2>1. Công Dụng:</> Bước Nhảy Linh Tính giúp bạn tới những vị trí cao mà nhảy thường không thể đạt.\n<Assistant_Title2>2. Thao Tác:</> Khi khám phá, nhấn giữ phím nhảy để vào trạng thái Bước Nhảy Linh Tính, sau đó nhấn phím nhảy lần nữa để nhảy cao hơn.\n<Assistant_Title2>3. Tình Huống:</> Thường dùng để khám phá đài cao, vượt chướng ngại hoặc tới khu vực ẩn.\n<Assistant_Title1>【Gợi Ý】</>\nMột số điểm khám phá cần kết hợp Bước Nhảy Linh Tính mới tới được~",
    [527767192048128] = "<Assistant_Title1>【Khoảnh Khắc Nguyên Tác】</>\n<Assistant_Title2>Giới Thiệu</>\nNgài “Kẻ Khờ” vĩ đại cũng từng sống nơi đây; ký ức và dấu chân năm xưa kết tinh thành những khoảnh khắc đáng ghi nhớ. Chào mừng trở lại chốn cũ, gặp người xưa và tìm lại giấc mộng trong nguyên tác.\n<Assistant_Title2>Hướng Dẫn</>\n<Assistant_Title3>1. Vào Hoạt Động</>\nCó thể tới 【Giấc Mộng Nguyên Tác】 bằng:\n<Assistant_Property2>Lối Vào Chạy Bàn:</> Mở Menu vào 【Chạy Bàn】, gia nhập một Giáo Đoàn bất kỳ, chọn 【Khoảnh Khắc Nguyên Tác】 trong 【Thế Giới Trật Tự】 rồi nhấn 【Đi Tới】.\n<Assistant_Property1>Lối Vào Bản Đồ: Mở bản đồ, chuyển sang tab 【Thám Bí】, xem biểu tượng 【Khoảnh Khắc Nguyên Tác】 trong 【Chi Tiết Thế Giới】, tìm dấu tương ứng rồi nhấn 【Đi Tới】.\n<Assistant_Title3>2. Hoàn Thành Tương Tác</>\nTới mục tiêu, nhấn tương tác 【Chạm】 để sống lại ký ức xưa.\n<Assistant_Title3>3. Nhận Thưởng</>\nSau khi 【Chạm】 sẽ nhận thưởng và tăng Tiến Độ Hoàn Thành Thế Giới Trật Tự của bản đồ tương ứng.",
    [527767192048640] = "<Assistant_Title1>【Săn Giết Tận Cùng】</>\n<Assistant_Title2>Giải Thích Lối Chơi:</><Assistant_System>Săn Giết Tận Cùng</> là lối chơi hỗn chiến ngoài trời tại <Assistant_Property1>Thành Săn Rồng</> với <Assistant_Red>500 người</>. Có thể đánh bại Sinh Vật Siêu Phàm hoặc người chơi địch để nhận <Assistant_Property1>Di Vật Tinh Hồng</> và Điểm Thắng Hạng.\n<Assistant_Title2>Mục Tiêu Chính:</> Nộp <Assistant_Property1>Di Vật Tinh Hồng</> cho <Assistant_System>Quản Gia Săn Giết</> để tăng Tiến Độ Săn Giết và mở thưởng giai đoạn. Di Vật Tinh Hồng chỉ có hiệu lực trong Thành Săn Rồng; rời khỏi sẽ tự mất hiệu lực và bị xóa.\n<Assistant_Title2>Thời Khắc Săn Giết:</> Lối chơi mở cả ngày; mỗi ngày <Assistant_Red>19:00—20:00</> là Thời Khắc Săn Giết, Thứ Bảy và Chủ Nhật mở thêm <Assistant_Red>14:00—15:00</>. Trong thời gian này, số Điểm Thắng Hạng liên quan khi hạ hoặc bị hạ được nhân đôi.\n<Assistant_Title2>Sự Kiện Vương Thành:</> Mỗi tối Thứ Sáu, sau 10 phút kể từ khi Thời Khắc Săn Giết bắt đầu, tức <Assistant_Red>19:10</>, Cự Long · Hình Chiếu xuất hiện ở trung tâm Vương Thành; ở các phiên khác, Vệ Binh Vương Thành xuất hiện sau 10 phút.\n<Assistant_Title2>Kết Toán Đoàn:</> Người hạ mục tiêu và tối đa 29 thành viên cùng đoàn đủ điều kiện hỗ trợ được tham gia kết toán thưởng. Di Vật Tinh Hồng chia đều theo số người tham gia; phần dư ưu tiên 1 vật cho người hạ, phần còn lại phân ngẫu nhiên cho những người khác.\n<Assistant_Title2>Quy Tắc Cướp Đoạt:</> Số mảnh hiển thị trên đầu người chơi càng nhiều, tỷ lệ cướp Di Vật Tinh Hồng càng cao; cứ tăng 500 mảnh, tỷ lệ cướp tăng tương ứng.\n<Assistant_Title2>Quy Tắc Bậc:</> Dưới <Assistant_Red>Bá Tước Bậc 1</>, bị hạ không mất Điểm Thắng Hạng. Trong 01:00—08:00 mỗi ngày hoặc khi liên tục hạ cùng một mục tiêu trong thời gian ngắn, Điểm Thắng Hạng nhận được sẽ suy giảm theo quy tắc.\n<Assistant_Title2>Tham Gia:</>{JumpToUI:[Đến Săn Giết Tận Cùng]|1250342}",
    [527767192048896] = "<Assistant_Title1>【Liên Đấu Tứ Phương】</>\n<Assistant_Title2>Giới thiệu lối chơi:</><Assistant_System>Liên Đấu Tứ Phương</> là chiến trường quy mô lớn giữa các CLB. Mỗi trận có <Assistant_Red>4 CLB</> cùng thi đấu, mỗi CLB tối đa <Assistant_Red>60 thành viên chính thức</>, tổng cộng <Assistant_Red>240 người chơi</>; mỗi Pathway của một CLB tối đa <Assistant_Red>16 người</>. Mỗi trận kéo dài <Assistant_Red>23 phút</>.\n<Assistant_Title2>Thể thức:</> Mỗi vòng gồm hai trận. Trước trận đầu, các hạng 1–2, 3–4, 5–6 và 7–8 của bảng lần lượt được xếp vào các bảng đấu khác nhau, sau đó phân ngẫu nhiên trong phạm vi quy tắc này. Hai đội đầu mỗi bảng ở trận 1 vào Nhánh Thắng, hai đội sau vào Nhánh Thua; trận 2 lần lượt đấu Nhánh Thắng và Nhánh Thua để xác định hạng 1–8 của vòng.\n<Assistant_Title2>Điều kiện thắng:</> CLB đầu tiên đạt <Assistant_Red>3000 điểm</> lập tức chốt chiến thắng; nếu hết trận không ai đạt 3000, xếp hạng theo điểm hiện tại. Nếu bằng điểm, lần lượt so <Assistant_Property1>tổng số mạng hạ gục</> và <Assistant_Property1>tổng Điểm Phi Phàm của CLB</>.\n<Assistant_Title2>Điểm trong trận:</> Điểm chỉ đến từ kết toán quyền sở hữu Hộ Vệ. Chiếm Hộ Vệ lần đầu nhận <Assistant_Red>50 điểm</>; mỗi <Assistant_Red>5 giây</> kết toán nhỏ, mỗi Hộ Vệ đã chiếm cho <Assistant_Red>1 điểm</>; mỗi <Assistant_Red>30 giây</> kết toán lớn, mỗi Hộ Vệ đã chiếm cho <Assistant_Red>18 điểm</>. Ở phút <Assistant_Red>4, 8, 12, 16, 20</> sẽ ngẫu nhiên xuất hiện kết toán điểm nhân cao quyền sở hữu Hộ Vệ; khi đó mỗi Hộ Vệ đã chiếm cho <Assistant_Red>72 hoặc 108 điểm</>.\n<Assistant_Title2>Điểm tuyển chọn Server Chiến Lược:</> Trong <Assistant_Property1>giai đoạn tuyển chọn Server Chiến Lược</>, hai vòng đầu áp dụng quy tắc điểm tuyển chọn. Hạng 1–4 mỗi trận lần lượt nhận <Assistant_Red>30, 15, 10, 5 điểm</>; kết thúc vòng 1, hạng 1–4 lần lượt nhận <Assistant_Red>60, 50, 45, 40 điểm</>, hạng 5–8 mỗi đội <Assistant_Red>10 điểm</>; kết thúc vòng 2, hạng 1–4 lần lượt nhận <Assistant_Red>200, 100, 70, 50 điểm</>, hạng 5–8 mỗi đội <Assistant_Red>15 điểm</>. Sau hai vòng đầu, 4 CLB có tổng điểm tuyển chọn cao nhất khu vực sẽ vào <Assistant_Property1>Nhóm Khải Huyền Liên Đấu Tứ Phương</> và nhận <Assistant_Property1>quyền tham gia Server Chiến Lược</>.\n<Assistant_Title2>Xếp hạng khi bằng điểm:</> Ưu tiên xếp theo <Assistant_Property1>tổng điểm tuyển chọn Server Chiến Lược</> từ cao xuống thấp. Nếu tổng điểm bằng nhau: sau vòng 1 hoặc vòng 2, xếp theo <Assistant_Property1>hạng chung cuộc</> của CLB trong vòng đó, hạng cao hơn ưu tiên; sau trận đầu của một vòng Liên Đấu Tứ Phương, do chưa có hạng chung cuộc nên các CLB bằng điểm tạm thời không phân thứ tự, thứ tự hiển thị hiện tại không đại diện hạng cuối vòng.\n<Assistant_Title2>Tranh đoạt Hộ Vệ:</> Chiến trường có <Assistant_Red>5 Hộ Vệ</>. CLB tung đòn kết liễu Hộ Vệ sẽ giành quyền kiểm soát; sau khi thuộc về một bên, Hộ Vệ lập tức hồi sinh và thuộc phe đó. Hộ Vệ không thể được trị liệu, nhưng sẽ chậm rãi tự hồi Máu khi xung quanh không có địch.\n<Assistant_Title2>Tài nguyên & Chỉ huy:</> Hạ người chơi địch hoặc chiếm Hộ Vệ nhận Điểm Tài Nguyên và tự tích lũy cấp Sĩ Khí. Hội Trưởng, Phó Hội Trưởng, Lý Sự có thể tiêu hao Điểm Tài Nguyên để dùng kỹ năng chỉ huy.\n<Assistant_Title2>Kỹ năng chỉ huy:</><Assistant_Property1>Tuyên Ngôn Khắc Địch</> tốn 1000 Điểm Tài Nguyên, tăng 15% Áp Chế toàn Pathway cho toàn bộ thành viên trong 20 giây, hồi 180 giây; <Assistant_Property1>Hành Quân Thần Tốc</> tốn 600, tăng 60% Tốc Chạy cho toàn bộ thành viên trong 10 giây, hồi 120 giây; <Assistant_Property1>Sắc Lệnh Quy Linh</> tốn 1500, xóa thời gian chờ hồi sinh hiện tại của toàn bộ thành viên và áp dụng cả với người chết trong 5 giây tiếp theo, hồi 240 giây; <Assistant_Property1>Triệu Tập Dịch Chuyển</> tốn 2400, triệu tập toàn bộ thành viên tới điểm tập kết chỉ định, hồi 240 giây; <Assistant_Property1>Thánh Vực Bảo Hộ</> tốn 1000, hồi 50% Máu tối đa cho toàn bộ Hộ Vệ phe mình, hồi 180 giây.\n<Assistant_Title2>Cách tham gia:</>{JumpToUI:[Đến Liên Đấu Tứ Phương]|1250063}",
    [527767192049152] = "<Assistant_Title1>【Chiến Thành】</>\n<Assistant_Title2>Giải Thích Lối Chơi:</><Assistant_System>Chiến Thành</> là đại chiến trường <Assistant_Red>1.000 người</> trong Đối Chiến Thế Lực. Tư cách chiến trường được phân phối lúc <Assistant_Red>21:20</> sau khi trận đầu mỗi vòng Giải Tứ Phương kết thúc. Hệ thống sẽ dựa trên tổng thực lực CLB để phân các CLB vào Chiến Thành hoặc Chiến Cao Nguyên. Thành viên CLB có tư cách có thể xem lịch đấu tại <Assistant_System>Lấy Chiến Nuôi Chiến - Thế Lực - Chiến Thành</>. Mỗi Con Đường trong cùng một CLB tối đa <Assistant_Red>16 người</> ra trận.\n<Assistant_Title2>Giai Đoạn 1:</> Xuất phát từ <Assistant_Property1>Pháo Đài</> phe mình, tiến qua <Assistant_Property1>Tiền Đồn</> và <Assistant_Property1>Doanh Trại</>. Sau khi chiếm Doanh Trại có thể tấn công <Assistant_Property1>Bia Chiến Tranh</> nối với nó. Phải chiếm hai Bia nối với Doanh Trại phe mình mới có thể tấn công <Assistant_Property1>Cổng Vương Thành</>; nếu Bia phe mình bị địch chiếm, sẽ mất quyền tấn công cổng.\n<Assistant_Title2>Giai Đoạn 2:</> Sau khi phá Cổng Vương Thành, có thể tới đài trung tâm chiếm Vương Thành. Thế lực có nhiều người nhất trên đài sẽ tích <Assistant_Property1>Giá Trị Chiếm Lĩnh</>; hạ Phi Phàm Giả phe địch tại đài trung tâm cũng tăng Giá Trị Chiếm Lĩnh cho phe mình. Đạt <Assistant_Red>100%</> sẽ chiếm Vương Thành. Chiếm Vương Thành trung tâm sẽ kết thúc chiến trường ngay và nhận thưởng người thắng cuối cùng.\n<Assistant_Title2>Đặc Sắc Chiến Trường:</> Có thể đi <Assistant_Property1>Tàu Hơi Nước</> từ Pháo Đài phe mình để nhanh tới Doanh Trại tiền tuyến; khi công cổng có thể dùng <Assistant_Property1>Xe Công Thành</>. <Assistant_Property1>Cự Long Chiến Tranh</> chiếm giữ Vương Thành trung tâm và sẽ xuất hiện trong chiến đấu.\n<Assistant_Title2>Tham Gia:</>{JumpToUI:[Đến Chiến Thành]|1250322}",
    [527767192049408] = "<Assistant_Title1>【Chiến Cao Nguyên】</>\n<Assistant_Title2>Giải Thích Lối Chơi:</><Assistant_System>Chiến Cao Nguyên</> là chiến trường <Assistant_Red>800 người</> trong Chiến Thế Lực. Tư cách được phân lúc <Assistant_Red>21:20</> sau trận đầu của mỗi vòng Giải Tứ Phương; thành viên CLB đủ tư cách xem lịch tại <Assistant_System>Lấy Chiến Nuôi Chiến-Thế Lực-Chiến Cao Nguyên</>.\n<Assistant_Title2>Mục Tiêu Chính:</> Các thế lực tranh giành <Assistant_Property1>Kỵ Sĩ Tử Vong</> trên bục trung tâm. Kỵ Sĩ Tử Vong đi theo thế lực có nhiều Phi Phàm Giả nhất trong phạm vi <Assistant_Red>20 m</>; ít nhất <Assistant_Red>5 người</> mới có thể giành quyền đi theo. Thế lực ở gần Kỵ Sĩ định kỳ nhận Điểm Thế Lực; thế lực được Kỵ Sĩ đi theo nhận nhiều hơn.\n<Assistant_Title2>Luật Thắng:</> Đưa Kỵ Sĩ Tử Vong tới quảng trường phe mình nhận thêm <Assistant_Red>1200 Điểm Thế Lực</>. Thế lực đạt <Assistant_Red>15000 Điểm</> thắng sớm; khi chiến đấu kết thúc, phát thưởng theo xếp hạng điểm của bốn thế lực Hoàng Đế.\n<Assistant_Title2>Cơ Chế Yếu Thế:</> Thế lực cách hạng nhất <Assistant_Red>3000 Điểm</> được coi là yếu thế. Mỗi <Assistant_Red>5 phút</> thả <Assistant_Property1>Dây Cản Ngựa</> trước quảng trường, chỉ phe mình nhặt được, dùng để Giảm Tốc Kỵ Sĩ Tử Vong; mỗi <Assistant_Red>8 phút</> mở Dịch Chuyển Tập Hợp tại quảng trường, cần <Assistant_Red>1</> Phi Phàm Giả kích hoạt, sau đó toàn phe có thể dịch chuyển tới quảng trường và nhận buff mạnh.\n<Assistant_Title2>Tham Gia:</>{JumpToUI:[Đến Chiến Cao Nguyên]|1250323}",
    [527767192049664] = "<Assistant_Title1>【Tranh Phong Chúa Tể】</>\n<Assistant_Title2>Giải Thích Lối Chơi:</><Assistant_System>Tranh Phong Chúa Tể</> là PvP <Assistant_Red>3v3 công bằng</>, tối đa lập <Assistant_Red>đội 3 người</> để ghép trận. Sau khi vào, mọi người chơi nhận điều chỉnh thuộc tính công bằng; Vật Phong Ấn thống nhất ở <Assistant_Red>Cấp 3</>.\n<Assistant_Title2>Điều Kiện Thắng:</> Trong trận, người chơi đã chết không thể được nghề Khán Giả hồi sinh. Hạ toàn bộ đội địch hoặc gây Sát Thương cao hơn khi hết thời gian để thắng.\n<Assistant_Title2>Mở & Phần Thưởng:</> Giao diện hiển thị thời gian mở <Assistant_Red>10:00-1:00</>. Mỗi ngày có 1 thưởng Thắng Đầu; lượt chưa dùng tích tối đa <Assistant_Red>3</>. Thắng sẽ tiêu hao 1 lượt và nhận gấp đôi Điểm Thắng.\n<Assistant_Title2>Tham Gia:</>{JumpToUI:[Đến Tranh Phong Chúa Tể]|1250094}",
    [527767192049920] = "<Assistant_Title1>【Khoảnh Khắc Vận Mệnh】</>\n<Assistant_Title2>Giải Thích Lối Chơi:</><Assistant_System>Khoảnh Khắc Vận Mệnh</> là chiến trường <Assistant_Red>12v12</>. Phi Phàm Giả chia thành hai phe, mỗi trận kéo dài <Assistant_Red>4 phút</>. Khi hết trận, phe nhiều điểm hơn thắng; nếu bằng điểm lần lượt so số hạ gục và lượng Sát Thương, nếu vẫn bằng nhau thì ngẫu nhiên một phe thắng.\n<Assistant_Title2>Nhận Điểm:</> Nhặt <Assistant_Property1>Điểm Sáng Cường Hóa</>, hạ gục, hỗ trợ hoặc tranh đoạt trong <Assistant_Property1>Xoáy Tranh Chấp</> để nhận điểm. Điểm Sáng cho điểm và buff thuộc tính; khi đếm ngược Xoáy Tranh Chấp kết thúc, Phi Phàm Giả còn trong xoáy chia đều điểm.\n<Assistant_Title2>Điểm Neo Tập Kết:</> Trong trận xuất hiện Điểm Neo Tập Kết trong <Assistant_Red>15 giây</>. Khi đủ số người yêu cầu vào điểm neo và duy trì <Assistant_Red>3 giây</>, Phi Phàm Giả phe mình được tập kết tới đây; người tham gia nhận buff thuộc tính có thời hạn.\n<Assistant_Title2>Ghép Trận:</> Giao diện hiển thị thời gian mở <Assistant_Red>10:00-1:00</>. Khoảnh Khắc Vận Mệnh cho phép tối đa <Assistant_Red>tổ đội 3 người</> ghép trận.\n<Assistant_Title2>Tham Gia:</>{JumpToUI:[Đến Khoảnh Khắc Vận Mệnh]|1250095}",
    [527767192050176] = "<Assistant_Title1>【Tranh Đoạt Thần Tọa】</>\n<Assistant_Title2>Giới thiệu lối chơi:</><Assistant_System>Tranh Đoạt Thần Tọa</> là chế độ <Assistant_Red>6v6</> đối chiến quyết liệt, có thể lập đội tối đa <Assistant_Red>6 người</> để ghép trận. Trong chế độ, toàn bộ người chơi chiến đấu bằng thuộc tính thật giống bên ngoài.\n<Assistant_Title2>Điều kiện thắng:</> Hạ toàn bộ người chơi đội địch trong thời gian giới hạn để thắng. Nếu hết giờ cả hai bên vẫn còn người sống, lần lượt so <Assistant_Property1>số người hạ gục</>, <Assistant_Property1>số người sống</>, <Assistant_Property1>tổng sát thương</>, <Assistant_Property1>tổng Máu còn lại</>; bên có giá trị cao hơn thắng.\n<Assistant_Title2>Quy tắc hồi sinh:</> Trong Tranh Đoạt Thần Tọa, mỗi đội có <Assistant_Red>2 lần</> hồi sinh đồng đội đã chết.\n<Assistant_Title2>Thời gian mở:</> Cổng chế độ hiển thị thời gian mở <Assistant_Red>10:00-1:00</>.\n<Assistant_Title2>Cách tham gia:</>{JumpToUI:[Đến Tranh Đoạt Thần Tọa]|1250123}",
    [527767192050432] = "<Assistant_Title1>【Đỉnh Chư Thần】</>\n<Assistant_Title2>Giải Thích Lối Chơi:</><Assistant_System>Đỉnh Chư Thần</> là giải đấu tổ đội <Assistant_Red>6v6</> theo Chiến Đội. Đấu trường dùng thuộc tính thật; <Assistant_Property1>Trang Bị</>, <Assistant_Property1>Vật Phong Ấn</>, <Assistant_Property1>Bí Ngẫu</>, <Assistant_Property1>Nhân Mạch</> và hiệu ứng <Assistant_Property1>Hệ Thống Thiên Phú</> đều có hiệu lực.\n<Assistant_Title2>Luật Chiến Đội:</> Tối đa <Assistant_Red>6 người</>, cùng nghề tối đa <Assistant_Red>2 người</>. Khi mở đăng ký, có thể lập/gia nhập Chiến Đội; đủ <Assistant_Red>5 người</> có thể đăng ký. Đội đã đăng ký nếu thay đổi khiến dưới 5 người sẽ tự hủy đăng ký.\n<Assistant_Title2>Luật Khóa:</> Trong giai đoạn khóa đăng ký, đội đã đăng ký có thể vào Khu Chuẩn Bị; đội chưa đăng ký vẫn có thể đăng ký và người chơi vẫn có thể gia nhập, nhưng không thể chủ động rời hoặc bị Đội Trưởng mời rời; đội đã đăng ký cũng không thể hủy. Khi giải chính thức bắt đầu, cần ở lại Khu Chuẩn Bị để vào trận bình thường.\n<Assistant_Title2>Thể Thức:</> Vòng bảng ghép ngẫu nhiên đấu 1 trận mỗi vòng, tổng <Assistant_Red>6 vòng</>; chọn <Assistant_Red>16 đội</> theo số trận thắng. Nếu bằng số thắng, phân định bằng Điểm Vinh Dự, tham khảo số hạ gục và thời lượng chiến đấu. Sau vòng bảng là giai đoạn Trợ Lực; trước vòng loại trực tiếp, thứ hạng dựa trên tổng Điểm Trợ Lực + Điểm Vinh Dự. Vòng loại trực tiếp <Assistant_Red>Bo3 thắng 2</>; Chung Kết <Assistant_Red>Bo5 thắng 3</>.\n<Assistant_Title2>Tham Gia:</>{JumpToUI:[Đến Đỉnh Chư Thần]|1250113}",
    [527767192050688] = "<Assistant_Title1>【Hệ Thống Thệ Ước】</>\n<Assistant_Title2>Giải Thích Lối Chơi:</><Assistant_System>Hệ Thống Thệ Ước</> là gameplay xã hội dành cho hai người chơi là bạn bè. Hai người lập đội tới chỗ bà Summer xin kết Thệ Ước, sau đó cùng tham gia hoạt động tổ đội để nhận Điểm Thệ Ước và Huy Chương Đồng Hành.\n<Assistant_Title2>Điều Kiện:</>① Cả hai phải đạt <Assistant_Red>Cấp 30</> để mở Hệ Thống Thệ Ước. ② Hai bên là bạn bè và <Assistant_Red>Độ Thân Thiện đạt 200</>.\n<Assistant_Title2>Quy Tắc:</>① Hai người đủ điều kiện lập đội tới <Assistant_Red>biển hoa Hornacis, chỗ bà Summer</>; đội trưởng gửi lời mời kết Thệ Ước. ② Bên được mời chấp nhận rồi hai người viết lời thề cho nhau. ③ Viết xong, hai bên trao đổi và nhận lời thề của nhau, sau đó vào bước chụp ảnh cưới. ④ Hai bên chọn mẫu chụp; xác nhận cuối cùng để hoàn tất chụp ảnh và kết thành quan hệ Thệ Ước.",
    [527767192050944] = "<Assistant_Title1>【Điểm Thệ Ước】</>\n<Assistant_Title2>Giải Thích:</><Assistant_System>Điểm Thệ Ước</> là kinh nghiệm dùng để nâng Cấp Thệ Ước của hai người có quan hệ Thệ Ước khi cùng tổ đội tham gia và hoàn thành hoạt động.\n<Assistant_Title2>Quy Tắc Nhận:</>① Mỗi ngày, Phi Phàm Giả và một đối tượng Thệ Ước tương ứng tối đa nhận <Assistant_Red>600</> Điểm Thệ Ước (phần giới hạn chưa nhận không cộng dồn). ② Mỗi tuần tối đa <Assistant_Red>2000</> Điểm Thệ Ước (phần chưa nhận không cộng dồn).\n<Assistant_Title2>Nguồn Nhận:</>① Cùng Thệ Ước hoàn thành <Assistant_System>Phó Bản Tiểu Đội</>. ② Hoàn thành <Assistant_System>Phó Bản Raid</>. ③ Hoàn thành <Assistant_System>Thảm Họa Thế Giới</>. ④ Hoàn thành <Assistant_System>Nhà Hát Utopia Chế Độ Đôi (nhận nhiều Điểm Thệ Ước hơn)</>. ⑤ Hoàn thành <Assistant_System>Tranh Đoạt Thần Tọa</>. ⑥ Hoàn thành <Assistant_System>Khoảnh Khắc Vận Mệnh</>. ⑦ Hoàn thành <Assistant_System>Tranh Phong Chúa Tể</>.\n<Assistant_Title2>Công Dụng:</> Dùng Điểm Thệ Ước để nâng Cấp Thệ Ước với đối tượng tương ứng; mỗi lần lên cấp có thể nhận phần thưởng cấp (mỗi cấp chỉ nhận một lần).",
    [527767192051200] = "<Assistant_Title1>【Phần Thưởng Thệ Ước】</>\n<Assistant_Title2>Giải Thích:</><Assistant_System>Phần thưởng Hệ Thống Thệ Ước</> gồm 2 loại: ① Thưởng Cấp Thệ Ước. ② Vật phẩm có thể mua tại Cửa Hàng Đồng Hành sau khi Thệ Ước đạt cấp chỉ định.\n<Assistant_Title2>Quy Tắc Thưởng Cấp:</>① Mỗi khi Cấp Thệ Ước với đối tượng tăng 1 cấp, Phi Phàm Giả có thể nhận 1 Thưởng Cấp. ② Phần thưởng mỗi cấp chỉ nhận một lần.\n<Assistant_Title2>Quy Tắc Cửa Hàng:</> Có thể dùng Huy Chương Đồng Hành tại Shop - Bách Hóa - Cửa Hàng Đồng Hành để mua Ngoại Trang liên quan Hệ Thống Thệ Ước; từng Ngoại Trang yêu cầu Cấp Thệ Ước tương ứng.",
    [527767192051456] = "<Assistant_Title1>【Nhận Súng】</>\n<Assistant_Title2>Quy Tắc Mở:</> Trong <Assistant_System>Nhiệm Vụ Cốt Truyện</> và <Assistant_System>Tingen Tội Ác</>, <Assistant_Property1>một số ải nhất định</> sẽ kích hoạt chức năng súng theo tiến trình ải.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Giới Thiệu Lối Chơi Súng]|898}，{SendAnswer:[Ngắm Bắn]|903}",
    [527767192051712] = "<Assistant_Title1>【Lối Chơi Bắn Súng】</>\n<Assistant_Title2>Quy Tắc Mở:</> Trong <Assistant_System>Nhiệm Vụ Cốt Truyện</> và <Assistant_System>Tingen Tội Lỗi</>, chức năng súng sẽ được kích hoạt theo tiến trình tại <Assistant_Property1>một số ải nhất định</>.\n<Assistant_Title2>Giới Thiệu:</> Sau khi kích hoạt súng, dùng nút Đánh Thường để bắn trực tiếp; dùng kỹ năng để đổi loại súng, ngắm qua ống ngắm, hỗ trợ đẩy lùi và các hiệu ứng khác.\nLoại súng được kích hoạt khác nhau tùy ải; hãy sử dụng hợp lý để đánh bại kẻ địch.\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Ngắm Bắn]|903},{SendAnswer:[Súng Ngắn]|899},{SendAnswer:[Shotgun]|900},{SendAnswer:[Súng Bắn Tỉa]|901}",
    [527767192051968] = "<Assistant_Title1>【Súng Ngắn】</>\n<Assistant_Title2>Đặc Tính:</> Súng Ngắn có sát thương mỗi phát và dung lượng băng đạn ở mức trung bình, là loại súng phổ biến nhất.\nSúng Ngắn có thể vào trạng thái Ngắm; khi đó <Assistant_Property1>bắn Điểm Yếu</> sẽ gây <Assistant_Property1>sát thương lớn</>.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Ngắm Bắn]|903},{SendAnswer:[Bắn Điểm Yếu]|902}",
    [527767192052224] = "<Assistant_Title1>【Shotgun】</>\n<Assistant_Title2>Đặc Điểm:</> Shotgun có phạm vi phán định trúng rộng; một phát có thể trúng nhiều kẻ địch và gây nhiều lần Sát Thương, rất thích hợp xử lý đám đông.\nShotgun <Assistant_Property1>không thể</> gây thêm Sát Thương vào Điểm Yếu của kẻ địch.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Súng Ngắn]|899},{SendAnswer:[Súng Bắn Tỉa]|901}",
    [527767192052480] = "<Assistant_Title1>【Súng Bắn Tỉa】</>\n<Assistant_Title2>Đặc Điểm:</> Súng Bắn Tỉa có tầm xa, sát thương mỗi phát cao nhưng khoảng cách giữa các phát dài, yêu cầu ngắm tương đối chính xác.\nSau khi bật Ngắm, có thể dùng ống ngắm nhiều mức phóng đại để quan sát từ xa; trong trạng thái này, <Assistant_Property1>bắn trúng điểm yếu</> sẽ gây <Assistant_Property1>sát thương lớn</>.\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Ngắm Bắn]|903},{SendAnswer:[Bắn Điểm Yếu]|902}",
    [527767192052736] = "<Assistant_Title1>【Bắn Điểm Yếu】</>\n<Assistant_Title2>Quy Tắc:</> Trong các ải kích hoạt năng lực súng, một số kẻ địch có bộ phận yếu điểm; thông tin ải sẽ có gợi ý liên quan. Đầu là yếu điểm của phần lớn kẻ địch hình người.\n<Assistant_Red>Lưu ý</>: Chỉ <Assistant_Red>Súng Ngắn</> và <Assistant_Red>Súng Bắn Tỉa</> mới có thể trúng yếu điểm khi ở <Assistant_Red>trạng thái Ngắm</>; <Assistant_Property1>đánh trúng yếu điểm</> sẽ gây <Assistant_Property1>sát thương lớn</> lên kẻ địch.\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Ngắm Bắn]|903}",
    [527767192052992] = "<Assistant_Title1>【Ngắm Bắn】</>\n<Assistant_Title2>Giới thiệu:</> Mọi loại súng đều có thể bật trạng thái Ngắm. Dùng kỹ năng tương ứng trên thanh kỹ năng để bật; dùng lại kỹ năng đó để thoát Ngắm.\n<Assistant_Red>Lưu ý</>: <Assistant_Red>Súng Lục</> và <Assistant_Red>Súng Bắn Tỉa</> có thể đánh trúng Điểm Yếu khi ở <Assistant_Red>trạng thái Ngắm</>, gây sát thương lớn; <Assistant_Property1>Súng Hoa Cải</> không có đặc tính này khi Ngắm.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Bắn Điểm Yếu]|902}",
    [527767192053248] = "<Assistant_Title1>【Railway Tycoon】</>\n<Assistant_Title2>Giải Thích Lối Chơi:</><Assistant_System>Railway Tycoon</> là lối chơi độc lập trong Lâu Đài. Tiêu hao <Assistant_Property1>Giấy Phép Kinh Tiêu</> để mở tuyến, mang sản phẩm Xưởng Lâu Đài làm vốn ban đầu, <Assistant_Property1>mua thấp bán cao</> giữa các ga, kiếm <Assistant_Property2>Phiếu Thương Hội</> và đổi thành tiền Lâu Đài khi kết toán.\n<Assistant_Title2>Quy Trình:</> Chọn độ khó và hàng mang theo → ký Hợp Đồng Kinh Tiêu → mua bán từng ga → chọn Thẻ Chiến Lược → hoàn thành mục tiêu Hợp Đồng → tới ga cuối kết toán xếp hạng và thưởng.\n<Assistant_Title2>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Railway Tycoon-Tham Gia & Chuẩn Bị]|905}，{SendAnswer:[Railway Tycoon-Mẹo Giao Dịch]|906}，{SendAnswer:[Railway Tycoon-Hợp Đồng Kinh Tiêu]|907}，{SendAnswer:[Railway Tycoon-Thẻ Chiến Lược & Tuyến Đường]|908}",
    [527767192053504] = "<Assistant_Title1>【Railway Tycoon - Tham Gia & Chuẩn Bị】</>\n<Assistant_Title2>Cách Vào:</> Sau khi hoàn thành nhiệm vụ hướng dẫn, tới khu tàu hỏa trong Lâu Đài nói chuyện với Sean, hoặc vào trang Railway Tycoon từ lối vào Lâu Đài/Gia Viên.\n<Assistant_Title2>Điều Kiện Xuất Phát:</> Cần tiêu hao <Assistant_Property1>Giấy Phép Kinh Tiêu</>. Nếu có sản vật Xưởng Lâu Đài, có thể tăng Vé ban đầu; sản vật mang theo lúc bắt đầu sẽ được quy đổi thành <Assistant_Property2>Vé Thương Hội</> theo giá cấu hình.\n<Assistant_Title2>Khuyến Nghị Chuẩn Bị:</> Ưu tiên mang sản vật thuộc loại được đề xuất trong tuần hoặc đúng cấp độ khó hiện tại; loại được đề xuất sẽ cho lợi nhuận cao hơn.",
    [527767192054016] = "<Assistant_Title1>【Railway Tycoon - Hợp Đồng Kinh Tiêu】</>\n<Assistant_Title2>Giải Thích Lối Chơi:</> Khi bắt đầu ván sẽ ký Hợp Đồng Kinh Tiêu khu vực và nhận mục tiêu doanh số theo giai đoạn. Sau mỗi số trạm cố định, Thương Hội sẽ kiểm tra thành tích.\n<Assistant_Title2>Khi Đạt Mục Tiêu:</> Có thể giữ hợp đồng hiện tại hoặc nâng cấp hợp đồng. Hợp đồng cấp cao có mục tiêu cao hơn nhưng cung cấp bonus số lượng hàng và giá bán mạnh hơn.\n<Assistant_Title2>Khi Không Đạt:</> Nếu lúc kiểm tra chưa đạt mục tiêu, ván sẽ kết toán sớm và thành tích cuối bị chiết khấu. Cấp hợp đồng chỉ có thể tăng, không thể giảm.",
    [527767192054528] = "<Assistant_Title1>【Bóng Ma Opera】</>\n<Assistant_Title2>Giải Thích:</><Assistant_System>Bóng Ma Opera</> là lối chơi giữa các CLB thi phối Ngoại Trang. Thể thức tổng thể tương tự Liên Đấu CLB, nhưng người chơi cần phối đồ và phân thắng bại tại Hành Lang Mị Ảnh. Hoạt động diễn ra theo mùa/vòng, cùng nhịp với Liên Đấu CLB.\n<Assistant_Title2>Quy Trình Chính:</> Đến giờ cố định mỗi tuần công bố chủ đề → thành viên phối đồ và xếp hạng điểm → trước trận khóa 5 người có điểm phối đồ cao nhất → quản lý CLB chỉnh thứ tự ra sân → buổi tối thi đấu 5 lượt đối kháng CLB → kết toán thắng thua và phần thưởng.\n<Assistant_Title2>Điều Kiện:</> CLB cần đáp ứng điều kiện khu thi đấu/cấp; thành viên phải là Hội Viên Chính Thức, Thành Viên Dự Bị không thể tham gia.\n<Assistant_Title2>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Bóng Ma Opera - Quy Tắc Phối Đồ]|910},{SendAnswer:[Bóng Ma Opera - Thi Đấu và Phần Thưởng]|911}",
    [527767192118784] = "<Assistant_Title1>Ân Quyến Môn Đồ Trầm Mặc</>\n<Assistant_Title2>Phân Loại Thành Tựu:</> Phát Triển-Vật Phong Ấn\n<Assistant_Title2>Điều Kiện:</> Nhận 1 Vật Chất Phi Phàm có từ 〈Môn Đồ Trầm Mặc〉",
    [527767192144896] = "<Assistant_Title1>【Thiện Cảm Nhân Mạch-Tương Tác Nhanh】</>\n<Assistant_Title2>Giải Thích:</> Đồng thời tiêu hao <Assistant_Red>【Thiệp Hoài Niệm】</> và <Assistant_Red>lượt Thư Từ</> để trực tiếp tăng Thiện Cảm với Nhân Mạch đã chọn.\n<Assistant_Title2>Lối Vào:</> Tại giao diện Thiện Cảm của Nhân Mạch tương ứng, nhấn <Assistant_Red>Tập Thiệp Mời</> để mở Tương Tác Nhanh.\n<Assistant_Title2>Số Lượt:</> Tương Tác Nhanh gồm lượt riêng của Nhân Mạch và lượt quyền lợi Thẻ Tháng, tính độc lập. Ưu tiên tiêu lượt riêng trước, rồi tới lượt Thẻ Tháng.\n<Assistant_Title2>Lượt Riêng:</> Khi Thiện Cảm với Nhân Mạch đạt Cấp 2, mỗi ngày nhận <Assistant_Red>2</> lượt riêng. Mỗi cấp Thiện Cảm tăng thêm 2 lượt/ngày, tối đa <Assistant_Red>10</> lượt/ngày.\n<Assistant_Title2>Quyền Lợi Thẻ Tháng:</> Mỗi ngày nhận thêm 5 lượt dùng chung cho toàn bộ Nhân Mạch, tích tối đa 15; chỉ dùng được trong thời gian Thẻ Tháng còn hiệu lực.",
    [527767192145152] = "<Assistant_Title1>Vật Phong Ấn</>\n<Assistant_Title2>Giải Thích Hệ Thống:</>\nVật Phong Ấn bạn đang sử dụng về bản chất là <Assistant_Property1>Hình Chiếu Lịch Sử</> do một “Kỳ Tích Sư” thần bí triệu hồi. So với bản gốc, hình chiếu này có năng lực yếu hơn nhưng tác dụng phụ cũng nhẹ hơn, mang lại nhiều cường hóa cho Phi Phàm Giả.\nTrong đó, <Assistant_Property1>Vật Phong Ấn Thường</> chia thành Tấn Công, Phòng Thủ và Đặc Hóa; mỗi loại tối đa mang 1 món. <Assistant_Property2>Vật Phong Ấn Đặc Biệt</> cung cấp các năng lực đặc thù, không trực tiếp tăng Chiến Lực.\n1. Vào <Assistant_System>Menu-Vật Phong Ấn</> hoặc nhấn <Assistant_Property1>F5</> để mở hệ thống và chọn <Assistant_Property2>Vật Phong Ấn</> mang theo.\n2. Vật Phong Ấn Thường ban đầu đều là Cấp “3”; có thể tiêu hao <Assistant_Property1>Hồi Âm Lịch Sử</> để nâng lên Cấp “2”, tiêu hao <Assistant_Property2>Kết Tinh Lịch Sử</> để nâng lên Cấp “1”. Cấp “3” tối đa kích hoạt 4 từ Vật Chất Phi Phàm; Cấp “2” tối đa 5 từ.\n3. Khi Cấp Nhập Vai đạt 42, mở khóa khảm <Assistant_Property1>Vật Chất Phi Phàm</>. Khảm các loại khác nhau sẽ thêm nhiều hiệu ứng cho Vật Phong Ấn.\n4. Khi khảm Vật Chất Phi Phàm, dựa theo số từ để kích hoạt thêm hiệu ứng <Assistant_Property2>Cộng Hưởng Phi Phàm</>; nâng cấp Vật Phong Ấn sẽ tăng số từ tối đa có thể kích hoạt Cộng Hưởng.\n5. Nâng cấp <Assistant_Property1>Tri Thức Phi Phàm</> giúp làm chủ sức mạnh Phi Phàm tốt hơn; hiệu quả năng lực Phi Phàm của Vật Phong Ấn, giá trị thuộc tính cố định của Vật Chất Phi Phàm và thuộc tính Cộng Hưởng đều tăng theo cấp Tri Thức Phi Phàm.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Nhận Vật Phong Ấn]|1266}，{SendAnswer:[Nâng Cấp Vật Phong Ấn]|1267}，{SendAnswer:[Vật Chất Phi Phàm]|1268}，{SendAnswer:[Nhận Vật Chất Phi Phàm]|1269}，{SendAnswer:[Tụ Hợp Vật Chất Phi Phàm]|1270}",
    [527767192145408] = "<Assistant_Title1>Nhận Vật Phong Ấn</>\n<Assistant_Title2>Giải Thích Lối Chơi:</>\nVào <Assistant_System>Menu-Vật Phong Ấn</> hoặc nhấn <Assistant_Property1>F5</>, chọn “Vật Phong Ấn Tấn Công”, “Vật Phong Ấn Phòng Thủ” hoặc “Vật Phong Ấn Đặc Hóa” để mở giao diện mang Vật Phong Ấn. Chọn Vật Phong Ấn muốn nhận; cách nhận được hiển thị ở cuối phần chi tiết.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Vật Phong Ấn]|1265}，{SendAnswer:[Nâng Cấp Vật Phong Ấn]|1267}",
    [527767192145664] = "<Assistant_Title1>Nâng Cấp Vật Phong Ấn</>\n<Assistant_Title2>Giải Thích Lối Chơi:</>\nVật Phong Ấn Thường ban đầu đều Cấp “3”; tiêu hao <Assistant_Property1>Hồi Âm Lịch Sử</> để nâng lên Cấp “2”, tiêu hao <Assistant_Property2>Kết Tinh Lịch Sử</> để nâng lên Cấp “1”. Vật Phong Ấn Cấp “3” tối đa kích hoạt 4 từ Vật Chất Phi Phàm; Cấp “2” tối đa 5 từ.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Vật Phong Ấn]|1265}，{SendAnswer:[Nhận Vật Phong Ấn]|1266}",
    [527767192145920] = "<Assistant_Title1>Vật Chất Phi Phàm</> <Assistant_Title2>Giải Thích Lối Chơi:</> 1. Vật chất mang sức mạnh Phi Phàm có thể khảm vào <Assistant_Property1>Vật Phong Ấn</> để ổn định Hình Chiếu Lịch Sử và mở thêm hiệu ứng <Assistant_Property2>Cộng Hưởng Phi Phàm</>. 2. Sức mạnh của Đặc Tính Phi Phàm được lượng hóa thành các dòng thuộc tính. Do trình tự và số lượng Đặc Tính Phi Phàm cấu thành khác nhau, Vật Chất Phi Phàm có số dòng, loại và cường độ khác nhau. Ít nhất 1 dòng, tối đa có thể đạt 6 dòng; Vật Chất Phi Phàm trên 6 dòng hiện chưa được phát hiện. 3. Dòng ngẫu nhiên của Vật Chất Phi Phàm có thể chịu ảnh hưởng hoặc ô nhiễm từ sức mạnh vị cách cao và phát sinh Dị Biến. <Assistant_Property2>Dòng Dị Biến</> mạnh hơn dòng thường; mỗi Vật Chất Phi Phàm tối đa có 1 Dòng Dị Biến. <Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Vật Phong Ấn]\\|1265}，{SendAnswer:[Nhận Vật Chất Phi Phàm]\\|1269}，{SendAnswer:[Tụ Hợp Vật Chất Phi Phàm]\\|1270}",
    [527767192146176] = "<Assistant_Title1>Nhận Vật Chất Phi Phàm</>\n<Assistant_Title2>Giải Thích Lối Chơi:</>\nCó thể nhận qua <Assistant_Property1>Mạo Hiểm Thế Giới-Phó Bản</>, <Assistant_Property1>Lấy Chiến Nuôi Chiến-Tranh Đấu</>, <Assistant_Property1>Nhiệm Vụ</>, <Assistant_Property1>Cửa Hàng Hoàn Trả</>, <Assistant_Property1>Cửa Hàng Khải Hoàn</>, <Assistant_Property1>Sàn Giao Dịch</>, v.v.\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Vật Phong Ấn]|1265}，{SendAnswer:[Vật Chất Phi Phàm]|1268}，{SendAnswer:[Tụ Hợp Vật Chất Phi Phàm]|1270}",
    [527767192146432] = "<Assistant_Title1>Tụ Hợp Vật Chất Phi Phàm</>\n<Assistant_Title2>Giải Thích Lối Chơi:</>\nMở khóa Tụ Hợp Vật Chất Phi Phàm khi Cấp Nhập Vai đạt 47; có thể tụ hợp hai Vật Chất Phi Phàm thành một Vật Chất Phi Phàm mới.\n1. Khi tụ hợp, <Assistant_Red>toàn bộ</> từ của sản phẩm được chọn ngẫu nhiên từ các từ của <Assistant_Red>Vật Chất Phi Phàm đưa vào</>.\n2. Khi tụ hợp có xác suất cực nhỏ phát sinh Dị Biến, tạo <Assistant_Property2>Từ Dị Biến</>. Tổng số và loại từ của vật liệu khác nhau sẽ cho tập Từ Dị Biến có thể xuất hiện khác nhau.\n3. Khi đang sở hữu ít nhất 2 Vật Chất Phi Phàm Tấn Công và 2 Vật Chất Phi Phàm Phòng Thủ có từ 4 từ trở lên, mở khóa đưa Vật Chất Phi Phàm Tấn Công 4 từ vào tụ hợp; khi đang sở hữu ít nhất 2 Vật Chất Phi Phàm Tấn Công và 2 Vật Chất Phi Phàm Phòng Thủ 5 từ, mở khóa đưa Vật Chất Phi Phàm 5 từ vào tụ hợp.\n4. Tụ Hợp Vật Chất Phi Phàm tăng <Assistant_Property1>Độ Thành Thạo Tụ Hợp</>. Độ thành thạo reset theo mùa; đạt mốc nhất định nhận thưởng.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Vật Phong Ấn]|1265}，{SendAnswer:[Vật Chất Phi Phàm]|1268}，{SendAnswer:[Nhận Vật Chất Phi Phàm]|1269}",
    [527767192146688] = "<Assistant_Title1>【Truy Tìm Dấu Chân】</>\n<Assistant_Title2>Giới Thiệu:</>\nTầm nhìn của bạn tạm thời tách khỏi lớp bề mặt của hiện thực. Linh Tính cộng hưởng thoáng qua với những khe hở lịch sử lắng đọng nơi đây. Trước mắt bạn sẽ hiện lên khoảnh khắc cuốn hút nhất của vùng đất này.\n<Assistant_Title2>Hướng Dẫn</>\n<Assistant_Title3>1. Vào Lối Chơi</>\nCó thể tới 【Truy Tìm Dấu Chân】 bằng các cách:\n<Assistant_Property2>Lối Vào Chạy Đoàn:</> Mở menu vào 【Chạy Đoàn】, gia nhập bất kỳ Giáo Đoàn nào, chọn 【Truy Tìm Dấu Chân】 trong 【Thế Giới Trật Tự】 rồi nhấn 【Đi Đến】 để tự tìm đường.\n<Assistant_Property1>Lối Vào Bản Đồ:</> Mở bản đồ, chuyển sang tab 【Thám Bí】, xem biểu tượng 【Truy Tìm Dấu Chân】 trong 【Chi Tiết Thế Giới】; theo chỉ dẫn trên bản đồ, tìm ký hiệu tương ứng và nhấn 【Đi Đến】 để tự tìm đường.\n<Assistant_Title3>2. Hoàn Thành Tương Tác</>\nTới địa điểm mục tiêu, theo gợi ý chọn 【Ngắm Cảnh】 để thưởng ngoạn một trong những cảnh đẹp nhất của vùng đất và chụp ảnh lưu niệm.\n<Assistant_Title3>3. Mở Khóa Ký Ức</>\nHoàn thành tương tác sẽ hoàn tất khám phá ký ức tương ứng và tăng Độ Hoàn Thành của bản đồ.",
    [527767192146944] = "<Assistant_Title1>【Giáo Đoàn / Chạy Đoàn】</>\n<Assistant_System>Giáo Đoàn</> là hệ thống trưởng thành và phe phái cốt lõi của Chạy Đoàn. Sau khi gia nhập Giáo Đoàn, bạn sẽ có <Assistant_Property1>Cấp Giáo Đoàn</>, <Assistant_Property1>Thuộc Tính Giáo Đoàn</> riêng cùng lối chơi độc quyền của Giáo Đoàn đó.\n\n<Assistant_Title2>Nội Dung Chính:</>\n1. Chọn Giáo Đoàn và hoàn tất phân bổ thuộc tính.\n2. Tham gia lối chơi Giáo Đoàn để nhận Điểm Hành Động Giáo Đoàn và nhiều phần thưởng.\n3. Nâng Cấp Giáo Đoàn để mở khóa động tác, ngoại hình, danh hiệu và các phần thưởng khác.\n4. Dùng các thuộc tính như Mị Lực, Trực Giác, Học Thức, Vũ Lực để kiểm định trong Thám Bí và lối chơi Giáo Đoàn.\n\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Cách Gia Nhập Giáo Đoàn]|1273}, {SendAnswer:[Giải Thích Thuộc Tính Giáo Đoàn]|1275}, {SendAnswer:[Điểm Hành Động Và Giới Hạn Tuần Giáo Đoàn]|1276}",
    [527767192147200] = "<Assistant_Title1>【Cách Gia Nhập Giáo Đoàn】</>\nSau khi mở Giáo Đoàn, có thể vào quy trình gia nhập từ <Assistant_System>Chạy Đoàn</> hoặc tìm NPC của Giáo Đoàn tương ứng.\n\n<Assistant_Title2>Quy Trình:</>\n1. Mở giao diện chọn Giáo Đoàn.\n2. Chọn Giáo Đoàn muốn gia nhập.\n3. Xem năng lực, Tín Ngưỡng và thuộc tính khuyến nghị của Giáo Đoàn.\n4. Hoàn tất phân điểm thuộc tính rồi xác nhận.\n\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Chọn Giáo Đoàn Và Phân Điểm]|1274}",
    [527767192147456] = "<Assistant_Title1>【Chọn Giáo Đoàn Và Phân Điểm】</>\nKhi gia nhập Giáo Đoàn, bạn sẽ vào quy trình tương tự tạo nhân vật Chạy Đoàn, gồm ba bước chính: <Assistant_Property1>Giáo Đoàn</>, <Assistant_Property1>Tín Ngưỡng</>, <Assistant_Property1>Thuộc Tính</>.\n\n<Assistant_Title2>Quy Tắc:</>\n1. Sau khi chọn Giáo Đoàn, năng lực và Tín Ngưỡng của Giáo Đoàn đó được xác định tự động.\n2. Mỗi Giáo Đoàn có phương án thuộc tính khuyến nghị, có thể dùng trực tiếp.\n3. Giá trị cơ bản mỗi thuộc tính tối thiểu 8, tối đa 16; tổng Điểm Thuộc Tính là 44.\n\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Giải Thích Thuộc Tính Giáo Đoàn]|1275}, {SendAnswer:[Cách Gia Nhập Giáo Đoàn]|1273}",
    [527767192147712] = "<Assistant_Title1>【Giải Thích Thuộc Tính Giáo Đoàn】</>\nThuộc tính Giáo Đoàn chủ yếu gồm <Assistant_Property1>Mị Lực</>, <Assistant_Property1>Trực Giác</>, <Assistant_Property1>Học Thức</>, <Assistant_Property1>Vũ Lực</>. Thiên Phú Chạy Đoàn có thể cộng vĩnh viễn các thuộc tính này; một số khu vực có thể cung cấp cộng thêm tạm thời.\n\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Chọn Giáo Đoàn Và Phân Điểm]|1274}",
    [527767192147968] = "<Assistant_Title1>【Điểm Hành Động Giáo Đoàn & Giới Hạn Tuần】</>\nĐiểm Hành Động Giáo Đoàn chủ yếu nhận từ các lối chơi của Giáo Đoàn tương ứng, dùng để nâng Cấp Giáo Đoàn hiện tại.\n\n<Assistant_Title2>Quy Tắc Giới Hạn Tuần:</>\nĐiểm Hành Động Giáo Đoàn có giới hạn nhận hằng tuần và có thể cộng dồn tối đa 2 tuần.\n\n<Assistant_Title2>Điểm Hành Động Chung:</>\nKhi Điểm Hành Động của một Giáo Đoàn vượt giới hạn, phần dư chuyển thành Điểm Hành Động Chung. Điểm Hành Động Chung có thể dùng để nâng các Giáo Đoàn khác.\n\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Cấp, Đột Phá & Phần Thưởng Giáo Đoàn]|1277}",
    [527767192148224] = "<Assistant_Title1>【Cấp Giáo Đoàn, Đột Phá và Phần Thưởng】</>\nSau khi gia nhập Giáo Đoàn, mặc định bắt đầu từ Cấp 1. Tham gia hoạt động Giáo Đoàn để nhận Điểm Hành Động; đủ điểm sẽ tăng cấp.\n\n<Assistant_Title2>Nhiệm Vụ Đột Phá:</>\nMột số cấp sau khi đầy Điểm Hành Động còn cần hoàn thành Nhiệm Vụ Đột Phá. Khi chưa hoàn thành, Điểm Hành Động vẫn tiếp tục tích lũy. Hoàn tất Đột Phá mới có thể tăng cấp tiếp.\n\n<Assistant_Title2>Nhận Thưởng:</>\nCó thể nhận trực tiếp tại giao diện Thưởng Cấp.\n\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Điểm Hành Động Giáo Đoàn và Giới Hạn Tuần]|1276}",
    [527767192148480] = "<Assistant_Title1>【Cách Đổi Giáo Đoàn】</>\nSau khi đã gia nhập Giáo Đoàn, có thể vào giao diện Giáo Đoàn để thực hiện đổi Giáo Đoàn.\n\n<Assistant_Title2>Quy tắc đổi:</>\n1. Điểm Hành Động, Cấp và Thuộc Tính của Giáo Đoàn cũ được giữ lại; khi đổi về có thể tiếp tục tiến độ cũ.\n2. Nếu tất cả Giáo Đoàn dưới Cấp 4, có thể đổi trực tiếp; khi bất kỳ Giáo Đoàn nào đạt từ Cấp 4 trở lên, đổi Giáo Đoàn có hồi chiêu 7×24 giờ.\n\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Chọn Giáo Đoàn & Phân Điểm Thuộc Tính]|1274}，{SendAnswer:[Cấp, Đột Phá & Phần Thưởng Giáo Đoàn]|1277}",
    [527767192148736] = "<Assistant_Title1>【Tôn Chỉ Giáo Đoàn & Gameplay Riêng】</>\nMỗi Giáo Đoàn có quy định riêng. Hãy tuân thủ quy định và hoàn thành nhiệm vụ tuần, nếu không sẽ bị phạt.\n\n<Assistant_Title2>Gameplay Riêng:</>\nMỗi Giáo Đoàn có gameplay và năng lực riêng; Phi Phàm Giả có thể đổi Giáo Đoàn để trải nghiệm các lối chơi khác nhau.\n\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Điểm Hành Động Giáo Đoàn & Giới Hạn Tuần]|1276}",
    [527767192150272] = "<Assistant_Title1>【Ba Lô Gấu Bí Ngẫu】</>\n<Assistant_Title2>Mô Tả:</> Phụ kiện rơi từ Phó Bản\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Ba Lô Gấu Bí Ngẫu; có thể vào <Assistant_System>Ngoại Trang - Thay Đồ</> để xem và sử dụng.\n</>Nhận từ <Assistant_System>Phó Bản - Nhà Hát Utopia</>",
    [527767192150528] = "<Assistant_Title1>【Miện Thương Bạch】</>\n<Assistant_Title2>Mô Tả:</> Trang Phục Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Miện Thương Bạch; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng, hoặc đổi thành <Assistant_Red>2</> Thẻ Thần Quyến.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Hoán Nhan Linh Giới</>, hoặc tại <Assistant_System>Cửa Hàng Quà Tặng Mỹ Thần</> dùng <Assistant_Red>2</> Thẻ Thần Quyến để đổi",
    [527767192150784] = "<Assistant_Title1>【Kinh Cức Vĩnh Dạ】</>\n<Assistant_Title2>Mô Tả:</> Trang Phục Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Kinh Cức Vĩnh Dạ; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng, hoặc đổi thành <Assistant_Red>2</> Thẻ Thần Quyến.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Hoán Nhan Linh Giới</>, hoặc tại <Assistant_System>Cửa Hàng Quà Tặng Mỹ Thần</> dùng <Assistant_Red>2</> Thẻ Thần Quyến để đổi",
    [527767192151040] = "<Assistant_Title1>【Linh Lan và Kỵ Sĩ】</>\n<Assistant_Title2>Mô Tả:</> Trang Phục Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Linh Lan và Kỵ Sĩ; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng, hoặc đổi thành <Assistant_Red>2</> Thẻ Thần Quyến.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Hoán Nhan Linh Giới</>, hoặc tại <Assistant_System>Cửa Hàng Quà Tặng Mỹ Thần</> dùng <Assistant_Red>2</> Thẻ Thần Quyến để đổi",
    [527767192153600] = "<Assistant_Title1>【Lữ Khách Đường Sắt】</>\n<Assistant_Title2>Mô Tả:</> Trang phục nhận từ gameplay\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Lữ Khách Đường Sắt; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Nhận từ <Assistant_System>Gameplay - Trùm Đường Sắt</>",
    [527767192153856] = "<Assistant_Title1>【Hồi Hưởng Thành Kính】</>\n<Assistant_Title2>Mô Tả:</> Trang phục thưởng từ gameplay\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Hồi Hưởng Thành Kính; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Nhận từ <Assistant_System>Gameplay - Công Hội</>",
    [527767192154368] = "<Assistant_Title1>【Cà Phê Buổi Chiều】</>\n<Assistant_Title2>Mô Tả:</> Trang phục thưởng từ gameplay\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Cà Phê Buổi Chiều; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Nhận từ <Assistant_System>Gameplay - Thệ Ước</>",
    [527767192159488] = "<Assistant_Title1>【Chế Độ Cốt Truyện】</>\n<Assistant_Title2>Cài Đặt:</> Menu - Cài Đặt - Góc Nhìn - Chế Độ Cốt Truyện{JumpToUI:[【Đến Xem】]|1302534}\n<Assistant_Title2>Giới Thiệu:</> Khi bật Chế Độ Cốt Truyện, trong vị diện cốt truyện camera sẽ kéo gần thành góc quay cốt truyện để tăng độ nhập vai. Có thể bấm công tắc dưới nút chụp ảnh ở góc dưới trái màn hình để bật/tắt thủ công; cũng có thể tắt vĩnh viễn tại <Highlight>Cài Đặt - Góc Nhìn - Chế Độ Cốt Truyện - Tự Động Bật Chế Độ Cốt Truyện</>. Sau khi tắt, lần sau vào vị diện cốt truyện sẽ không tự bật nữa (trừ một số cảnh chiến đấu).\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Ẩn Ngoại Hình Trong Chế Độ Cốt Truyện]|1324}",
    [527767192160000] = "<Assistant_Title1>【Cách An Hồn Người Chơi Khác】</>\n<Assistant_Title2>Thao Tác:</>\n1. Bật <Assistant_System>Linh Thị</> để xem trạng thái Lý Trí của người chơi xung quanh; Lý Trí khác nhau có màu hiển thị khác nhau.\n2. Trong Linh Thị, nhấn người chơi mục tiêu để xem Lý Trí hiện tại.\n3. Nếu mục tiêu có thể An Hồn, sẽ hiện <Assistant_System>nút An Hồn</>.\n4. Nhấn <Assistant_System>An Hồn</> để thực hiện.\n\n<Assistant_Title2>Hướng Dẫn Hình Ảnh:</> Chưa biết thao tác? {JumpToUI:[Nhấn đây xem hướng dẫn hình ảnh]|1302511}\n<Assistant_Title3>Liên Quan:</>{SendAnswer:[An Hồn]|516}，{SendAnswer:[Lý Trí]|515}",
    [527767192160512] = "<Assistant_Title1>【Mị Hoặc】</>\n<Assistant_Title2>Giới Thiệu:</> Người chơi tham gia <Assistant_System>Vũ Hội Đêm Xuân</> có thể gửi <Highlight>lời mời Đối Quyết Mị Hoặc</> cho người chơi khác để so tài Mị Lực.\n\n<Assistant_Title2>Cách Chơi:</> Người chơi Vũ Hội Đêm Xuân <Highlight>chọn người chơi mục tiêu</>, dùng <Highlight>kỹ năng Mị Hoặc (cùng vị trí nút với Tầm Đường Bằng Trượng Bói và Sợi Dây Linh Thể)</> để gửi lời mời. Nếu đối phương chấp nhận trong thời gian quy định, hai bên vào quy trình <Assistant_System>Đối Quyết Phong Cách</>.\n\n<Assistant_Title2>Kiểm Định Mị Lực:</> Trước khi so tài chính thức, hai bên tung xúc xắc. Vượt kiểm định sẽ nhận <Highlight>điểm cộng</> ở vòng so tài sau. <Assistant_System>Cấp Hội</> của bên mời càng cao, <Assistant_System>giá trị mục tiêu khi tung xúc xắc</> của cả hai bên sẽ thay đổi tương ứng.\n\n<Assistant_Title2>Phần Thưởng:</> Dù thắng hay thua, cả hai đều nhận một phần thưởng. Bên <Assistant_System>Mị Hoặc thất bại</> bị buộc đeo danh hiệu có <Highlight>tên người thắng</> trong <Highlight>15 phút</>.",
    [527767192163328] = "<Assistant_Title1>【Quang Huy Kết Xã】</>\n<Assistant_Title2>Hiệu Ứng:</> Khi ở <Assistant_System>cảnh CLB</>, kết quả tung xúc xắc kiểm định dựa trên <Assistant_Property1>Mị Lực, Trực Giác</> <Assistant_Red>+1</>.\n<Assistant_Title2>Thời Gian:</> Có hiệu lực thường trực; <Assistant_Red>19:30~21:00 Thứ Bảy và Chủ Nhật</> mỗi tuần, Quang Huy Kết Xã được cường hóa.\n<Assistant_Title2>Cường Hóa:</> Trong thời gian cường hóa, khi ở <Assistant_System>cảnh CLB</>, kết quả kiểm định dựa trên <Assistant_Property1>Mị Lực, Trực Giác</> <Assistant_Red>+3</>; sau khi tham gia <Assistant_System>lối chơi Giáo Đoàn</>, nhận <Assistant_Property1>buff thuộc tính chiến đấu</>.",
    [527767192163584] = "<Assistant_Title1>【Thâm Hồng Nguyệt Miện】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Đặc Hóa\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên dùng chung. Khi chịu đòn từ kẻ địch ở cự ly gần, nhận <Assistant_Red>Giảm Thương</>, đồng thời khiến tối đa 3 mục tiêu không phải Boss đang tấn công mình bị <Assistant_Red>Tăng Thương giảm</>. Tấn công kẻ địch sẽ <Assistant_Red>Giảm Tốc</> chúng và cho bản thân <Assistant_Red>Tăng Thương</>; nhưng sau khi vào chiến đấu, <Assistant_Red>Tốc Độ Hồi Thể Lực</> giảm. Gây Sát Thương có thể làm nhẹ tác dụng phụ này.\n<Assistant_Title2>Nhận:</> Mở khóa khi đạt Cấp 62.",
    [527767192163840] = "<Assistant_Title1>【Chuông Tang】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Tấn Công\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên PvP. Gây Sát Thương lên mục tiêu chính liên tục cộng dồn <Assistant_Red>Vạch Trần Điểm Yếu</>; đủ tầng sẽ kích hoạt Sát Thương Linh Thể, kèm <Assistant_Red>Trọng Thương</>, <Assistant_Red>Choáng</> và <Assistant_Red>Giảm Tốc mạnh</>. Bóp cò tiêu hao <Assistant_Red>Thể Lực</>; nếu không đủ sẽ xóa sạch Thể Lực và tạm thời không thể hồi. Sau khi dùng, trong một thời gian không thể tiếp tục Vạch Trần Điểm Yếu và Sát Thương nhận vào tăng.\n<Assistant_Title2>Nhận:</> Hoàn thành Nhiệm Vụ-Nguyên Tác-Trên Sương Xám.",
    [527767192164096] = "<Assistant_Title1>【Cơn Đói Ngọ Nguậy】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Tấn Công\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên dùng chung. Sau khi tấn công mục tiêu một thời gian sẽ tách linh hồn mục tiêu xuống dưới chân; chạm linh hồn trong <Assistant_Red>10</> giây sẽ nuốt linh hồn và nhận 1 kỹ năng của Bậc tương ứng; dùng kỹ năng sẽ giải phóng linh hồn. Nếu mục tiêu là quái vật, linh hồn quái vật bị nghiền nát, gây Sát Thương lên nó và kẻ địch xung quanh. Mỗi linh hồn Phi Phàm Giả bị giam khiến <Assistant_Red>Giới Hạn Sinh Mệnh</> của người trang bị giảm; sau khi nghiền nát linh hồn quái vật, <Assistant_Red>Giảm Thương</> của bản thân giảm.\n<Assistant_Title2>Nhận:</> Phần thưởng tự chọn Vật Phong Ấn tại Bá Tước Bậc I của Thang Xếp Hạng.",
    [527767192164352] = "<Assistant_Title1>【Cuồng Phủ】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Tấn Công\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên PvP. Trong chiến đấu tăng <Assistant_Red>Tốc Độ Di Chuyển</> và <Assistant_Red>Tốc Độ Đánh Thường</>; Đánh Thường trúng có xác suất gây <Assistant_Red>Trì Trệ</> và kích hoạt Sát Thương Lôi Điện. Khi kích hoạt Lôi Điện lên mục tiêu, có xác suất Lôi Điện đánh ngược vào bản thân.\n<Assistant_Title2>Nhận:</> Phó Bản-Truyền Thừa Ký Ức · Johnny (Thường), thưởng vượt lần đầu.",
    [527767192164608] = "<Assistant_Title1>【Công Chứng Thư】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Tấn Công\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên Phó Bản. Khi thi triển kỹ năng thường và Tuyệt Kỹ sẽ tiến hành Công Chứng; thành công tăng <Assistant_Red>Tầng Công Chứng/>. Nếu vượt giới hạn cấp, phần vượt chuyển thành bonus Sát Thương hoặc Hồi Phục cho lần kỹ năng này. Công Chứng thất bại sẽ giảm <Assistant_Red>Tầng Công Chứng</>, đồng thời giảm <Assistant_Red>Sát Thương</> và <Assistant_Red>Hồi Phục</> của lần thi triển đó.\n<Assistant_Title2>Nhận:</> Vật Phong Ấn mở khóa mặc định, không cần nhận thêm.",
    [527767192164864] = "<Assistant_Title1>【Cỏ May Mắn】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Tấn Công\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên dùng chung. Khi dùng Đánh Thường và kỹ năng không phải Giải Khống có xác suất nhận tầng May Mắn, tăng <Assistant_Red>Tốc Độ Di Chuyển</>, <Assistant_Red>Bạo Kích</> và <Assistant_Red>Cường Hóa Kỹ Năng</>; nếu không kích hoạt sẽ tích lũy xác suất. Khi May Mắn kết thúc, vào trạng thái Khốn Đốn, giảm <Assistant_Red>Tốc Độ Di Chuyển</> và <Assistant_Red>Tốc Độ Hồi Thể Lực</>, không thể kích hoạt May Mắn trong thời gian này.\n<Assistant_Title2>Nhận:</> Vật Phong Ấn mở khóa mặc định, không cần nhận thêm.",
    [527767192165376] = "<Assistant_Title1>【Mặt Nạ Hoàng Hôn】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Tấn Công\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên PvP. Chủ động vào <Assistant_Red>Trạng Thái Cường Hóa</> để tăng Tốc Độ Đánh của kỹ năng chiến đấu và Tuyệt Kỹ, đồng thời liên tục hoàn hồi chiêu. Hạ gục hoặc hỗ trợ có thể kéo dài thời gian cường hóa; nếu khi cường hóa kết thúc vẫn đang chiến đấu, tiến vào <Assistant_Red>Suy Nhược</>, giảm Tấn Công và Tốc Độ Di Chuyển.\n<Assistant_Title2>Nhận:</> Không Gian Bí Ẩn-Tàn Tro Song Sinh.",
    [527767192165888] = "<Assistant_Title1>【Chứng Nhận Vinh Quang】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Phòng Thủ\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên PvP. Thay kỹ năng <Assistant_Red>Giải Khống</> bằng hiệu ứng phòng hộ-phản chế mạnh hơn: sau khi giải khống nhận <Assistant_Red>Bá Thể</> và lượng lớn <Assistant_Red>Giảm Thương</>, đồng thời có thể <Assistant_Red>Phản Sát Thương</> lên kẻ tấn công. Khi kết thúc, gây Sát Thương lên kẻ địch xung quanh và áp <Assistant_Red>Giảm Tấn Công</>. Mỗi lần Phản Sát Thương sẽ kéo dài hồi chiêu Chứng Nhận Vinh Quang.\n<Assistant_Title2>Nhận:</> Vật Phong Ấn mở khóa mặc định, không cần nhận thêm.",
    [527767192166144] = "<Assistant_Title1>【Tóc Tĩnh Lặng】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Phòng Thủ\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên PvP. Kẻ địch ở gần người mang hoặc tấn công người mang sẽ dần tiến vào <Assistant_Red>Lạc Lối</>; chịu Sát Thương sẽ trì hoãn hoặc rút ngắn quá trình này. Trong chiến đấu, người mang cũng định kỳ tiến vào <Assistant_Red>Lạc Lối</> ngắn; chịu Sát Thương hoặc Hồi Phục sẽ trì hoãn tiến trình.\n<Assistant_Title2>Nhận:</> Phần thưởng Nhiệm Vụ-Nguyên Tác-Công Ty An Ninh Blackthorn.",
    [527767192166400] = "<Assistant_Title1>【Người Giấy Mặt Trăng】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Phòng Thủ\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên PvP. Khi chịu Sát Thương chí tử, kích hoạt <Assistant_Red>Bảo Hộ Người Giấy</>, tạm gánh Sát Thương tràn của lần này và một khoảng thời gian sau. Khi Bảo Hộ kết thúc, một phần Sát Thương tràn Người Giấy đã gánh tác dụng trở lại lên người mang, đồng thời khiến người mang <Assistant_Red>Tăng Sát Thương Nhận Vào</> trong thời gian ngắn.\n<Assistant_Title2>Nhận:</> Phần thưởng tự chọn Vật Phong Ấn tại Bá Tước Bậc I của Thang Xếp Hạng.",
    [527767192166656] = "<Assistant_Title1>【Lục Hoa】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Phòng Thủ\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên Phó Bản. Khi Sinh Mệnh chưa đầy nhưng vẫn trên ngưỡng an toàn, liên tục hồi một phần Sinh Mệnh đã mất; khi đầy Máu sẽ chuyển sang chữa cho đồng đội gần nhất có Máu thấp nhất. Khi có <Assistant_Red>Khiên</>, Khiên liên tục giảm; đồng thời thuộc tính từ ở vị trí Vật Chất Phi Phàm chỉ định không có hiệu lực.\n<Assistant_Title2>Nhận:</> Hoàn thành Nhiệm Vụ-Nguyên Tác-Vị Khách Bất Ngờ.",
    [527767192166912] = "<Assistant_Title1>【Ví Tiền Chính Nghĩa】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Phòng Thủ\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên dùng chung. Trực tiếp giảm Sát Thương nhận vào; khi chịu Sát Thương, dựa theo tổng Sát Thương tích lũy để tăng <Assistant_Red>Phòng Thủ</>. Nếu giữ hiệu ứng tăng Phòng Thủ quá một thời gian và vẫn đang chiến đấu, sẽ định kỳ vào <Assistant_Red>Quá Tải</>, giảm Tốc Độ Di Chuyển và Tốc Độ Hồi Thể Lực.\n<Assistant_Title2>Nhận:</> Vật Phong Ấn mở khóa mặc định, không cần nhận thêm.",
    [527767192167168] = "<Assistant_Title1>【Bình Độc Tố Sinh Học】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Phòng Thủ\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên dùng chung. Khi bị kẻ địch cự ly gần tấn công, có xác suất áp <Assistant_Red>Độc Tố Tê Liệt</>, <Assistant_Red>Độc Tố Suy Nhược</>, <Assistant_Red>Độc Tố Mệt Mỏi</> lên kẻ tấn công. Khi đủ tầng có thể kích hoạt <Assistant_Red>Trì Trệ</>, <Assistant_Red>Câm Lặng</> hoặc <Assistant_Red>Giảm Tốc</>. Sau khi mang đủ thời gian, khi chết sẽ để lại <Assistant_Red>Vũng Độc</>, <Assistant_Red>Trói Buộc</> và liên tục áp độc lên kẻ địch trong phạm vi. Trong chiến đấu, người mang định kỳ nhiễm ngẫu nhiên một loại độc; khi làm kẻ tấn công nhiễm độc, ưu tiên truyền loại độc bản thân đang chịu.\n<Assistant_Title2>Nhận:</> Phần thưởng tự chọn Vật Phong Ấn tại Bá Tước Bậc I của Thang Xếp Hạng.",
    [527767192167680] = "<Assistant_Title1>【Búp Bê Vận Rủi】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Đặc Hóa\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên PvP. Sau khi vào chiến đấu, kỹ năng trúng sẽ khiến Búp Bê nhập vào mục tiêu chính và áp <Assistant_Red>Vận Rủi Quấn Thân</>; đổi mục tiêu chính có thể chuyển hiệu ứng nhập. Khi Búp Bê trở về chủ cần nghỉ trước khi chuyển tiếp; trong lúc ở trên chủ, chính chủ cũng chịu <Assistant_Red>Vận Rủi Quấn Thân</>.\n<Assistant_Title2>Nhận:</> Không Gian Bí Ẩn-Thám Tử Thông Linh.",
    [527767192167936] = "<Assistant_Title1>【Ân Tứ Đại Địa】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Đặc Hóa\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên PvP. Sau khi liên tục mang trong cùng cảnh đủ thời gian, chết sẽ tạo Vùng Cỏ Mặt Đen tại chỗ, cung cấp cho đồng minh <Assistant_Red>Hồi Phục liên tục</>, <Assistant_Red>Tăng Tấn Công</> và số lần <Assistant_Red>Miễn Khống</>. Khi Vùng Cỏ Mặt Đen còn tồn tại, không thể chủ động hồi sinh hoặc được đồng đội hồi sinh; nếu thi thể bị cưỡng chế thanh tẩy, chỉ giữ lại hiệu ứng hồi Sinh Mệnh.\n<Assistant_Title2>Nhận:</> Phó Bản-Truyền Thừa Ký Ức · Bonnie (Khó), thưởng vượt lần đầu.",
    [527767192168192] = "<Assistant_Title1>【Vị Tướng Không Đồng Tử】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Đặc Hóa\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên PvP. Sau khi vào chiến đấu, định kỳ triệu hồi Ác Linh truy đuổi mục tiêu địch; trúng sẽ gây Sát Thương, <Assistant_Red>Choáng</> và gắn dấu <Assistant_Red>Kẻ Thù</>. Ác Linh ưu tiên khóa mục tiêu có dấu. Ác Linh cũng có thể gây Sát Thương cho người mang; khi người mang vào chiến đấu cũng bị đánh dấu <Assistant_Red>Kẻ Thù</>.\n<Assistant_Title2>Nhận:</> Phó Bản-Truyền Thừa Ký Ức · Mũi Khoan (Khó), thưởng vượt lần đầu.",
    [527767192168704] = "<Assistant_Title1>【Đèn Thần Cầu Nguyện】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Đặc Hóa\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên dùng chung. Dùng vật phẩm trong chiến đấu kích hoạt <Assistant_Red>Cầu Nguyện</>; tùy lượng Máu hiện tại cung cấp hiệu ứng khác nhau, gồm tăng Giới Hạn Sinh Mệnh, tăng tốc Đánh Thường hoặc hoàn hồi chiêu kỹ năng. Mỗi loại điều ước có cái giá tương ứng: giảm Sinh Mệnh hiện tại, <Assistant_Red>khóa Đánh Thường</> hoặc khiến kỹ năng phát sinh <Assistant_Red>gấp đôi hồi chiêu</>.\n<Assistant_Title2>Nhận:</> Phần thưởng nhiệm vụ toàn server Chương 2 cốt truyện mùa 《Văn Minh và Luật Lệnh》.",
    [527767192168960] = "<Assistant_Title1>【Trượng Sinh Mệnh】</>\n<Assistant_Title2>Loại:</> Vật Phong Ấn Đặc Hóa\n<Assistant_Title2>Mô Tả:</> Vật Phong Ấn thiên dùng chung. Người mang định kỳ nhận <Assistant_Red>Năng Lượng Sinh Mệnh</>. Sau khi chữa cho đồng minh đủ lượng Sinh Mệnh, tiêu hao <Assistant_Red>Năng Lượng Sinh Mệnh</> để áp hiệu ứng hồi Máu liên tục lên mục tiêu và nhận 1 <Assistant_Red>Hạt Giống Sinh Mệnh</>. Khi chịu Sát Thương và Máu thấp, tự tiêu hao <Assistant_Red>Hạt Giống Sinh Mệnh</> để hồi Sinh Mệnh. Tiêu hao Năng Lượng Sinh Mệnh tích lũy <Assistant_Red>Dị Biến</>, giảm Tốc Độ Di Chuyển và Phòng Thủ.\n<Assistant_Title2>Nhận:</> Mở khóa khi đạt Cấp 62.",
    [527767192169728] = "<Assistant_Title1>《Tôi Đã Trở Lại》</>\n<Assistant_Title2>Mô Tả Danh Hiệu:</> Người này từng sượt qua Tử Vong nhưng kỳ tích thay vẫn sống sót.\n<Assistant_Title2>Cách Nhận:</> Hoàn thành thành tựu {SendAnswer:[Chết Đi Sống Lại Chính Là Kỳ Tích]|1361}, sau đó dùng vật phẩm <Assistant_Property1>Danh Hiệu · Tôi Đã Trở Lại</> để trang bị.\n<Assistant_Title2>Độ Hiếm:</><Assistant_Property1> Thường (Độ Hiếm 1)</>",
    [527767192171776] = "<Assistant_Title1>【Lì Xì - Bảng Vàng】</>\n<Assistant_Title2>Cấp Mở:</> Cấp Nhận Thức <Assistant_Red>2</>\n<Assistant_Title2>Lối Vào:</> Có thể phát Lì Xì cho từng kênh tại <Assistant_System>Chat - Góc dưới phải kênh tương ứng - nút Lì Xì</>.\n<Assistant_Title2>Kênh Phát:</> Có thể phát Lì Xì Bảng Vàng tương ứng trong kênh Đội/Tổ Đội, kênh CLB và phòng thoại.\n<Assistant_Title2>Lì Xì Phát Sóng:</> Dùng phát sóng Tâm Vũ · Thần Dụ hoặc Tấn Điện · Thần Dụ để gửi marquee toàn server, kèm Lì Xì Bảng Vàng Khóa ở kênh Thế Giới trị giá bằng một nửa.\n<Assistant_Title2>Chi Phí:</> Tiêu Bảng Vàng không khóa để gửi Lì Xì Bảng Vàng Khóa; người nhận nhận lượng Bảng Vàng Khóa tương đương. Sau 24 giờ, phần chưa được nhận sẽ hoàn lại lượng Bảng Vàng Khóa tương ứng.\n<Assistant_Title2>Lì Xì Vận May:</> Không cần mật khẩu; người chơi khác có thể nhận trực tiếp và nhận ngẫu nhiên một lượng Bảng Vàng Khóa.\n<Assistant_Title2>Lì Xì Mật Ngữ:</> Cần nhập đúng mật ngữ bằng giọng nói mới nhận được; phần thưởng là lượng Bảng Vàng Khóa ngẫu nhiên.\n<Assistant_Title2>Lì Xì Mật Khẩu:</> Cần nhập đúng mật khẩu mới nhận được; phần thưởng là lượng Bảng Vàng Khóa ngẫu nhiên.",
    [527767192172032] = "<Assistant_Title1>【Phát Thanh】</>\n<Assistant_Title2>Cấp Mở:</> Cấp Nhận Thức <Assistant_Red>2</>\n<Assistant_Title2>Lối Vào:</><Assistant_System>Chat - Phát Thanh góc phải dưới</>{JumpToUI:[【Đi Xem】]|1250041}\n<Assistant_Title2>Cách Mua:</> Có thể mua nhanh trong bảng Phát Thanh hoặc tại <Assistant_System>Shop - Trưng Bày Bí Tàng</>.\n<Assistant_Title2>Vật Phẩm - Phát Thanh Toàn Vùng:</> Dùng để gửi thông báo chạy chữ toàn server.\n<Assistant_Title2>Vật Phẩm - Tâm Vũ · Phát Thanh Thần Dụ:</> Dùng để gửi thông báo chạy chữ toàn server, kèm Lễ Kim Bảng Vàng khóa ở Kênh Thế Giới trị giá bằng một nửa.\n<Assistant_Title2>Vật Phẩm - Tấn Điện · Phát Thanh Thần Dụ:</> Dùng để gửi thông báo chạy chữ toàn server, kèm Lễ Kim Bảng Vàng khóa ở Kênh Thế Giới trị giá bằng một nửa.",
    [527767192172288] = "<Assistant_Title1>【Động Tác Xã Giao】</>\n<Assistant_Title2>Hệ Thống:</><Assistant_System>HUD - Nút Động Tác</>{JumpToUI:[【Đến Xem】]|1250058}\n<Assistant_Title2>Sử Dụng:</> Nhấn biểu tượng Động Tác để mở giao diện; có thể chọn Động Tác Đơn, Động Tác Đôi hoặc Biểu Cảm.\n<Assistant_Title2>Cách Nhận:</> Có thể xem trước tại <Assistant_System>Ngoại Hình - Phụ Kiện - Động Tác</> và xem nguồn nhận. Cũng có thể nhấn động tác chưa mở khóa trong bảng Động Tác Xã Giao để xem nguồn.\n<Assistant_Title2>Ảnh Hưởng SAN:</> Phần lớn động tác sẽ ảnh hưởng SAN sau khi sử dụng.\n<Assistant_Title2>Động Tác Đôi:</> Chọn người chơi mục tiêu rồi nhấn Động Tác Đôi để gửi lời mời; khi đối phương chấp nhận, hai người cùng biểu diễn. <Assistant_Red>Lưu ý: hai bên phải ở trong phạm vi khoảng cách nhất định; quá xa sẽ không thể gửi lời mời.</>",
    [527767192172800] = "<Assistant_Title1>【Vòng Quỷ Bí - Bài Đăng】</>\n<Assistant_Title2>Đăng Bài:</> Trong giao diện Vòng Quỷ Bí, nhấn <Assistant_System>Đăng</> để soạn bài. Khi đăng có thể nhập văn bản, tải ảnh, đặt chủ đề, phạm vi hiển thị, quyền bình luận và chia sẻ.\n<Assistant_Title2>Chia Sẻ Vào Vòng Quỷ Bí:</> Trong giao diện Chia Sẻ, nhấn <Assistant_System>Chia Sẻ Vào Vòng Quỷ Bí</> để chụp nội dung và đăng vào Vòng Quỷ Bí.\n<Assistant_Title2>Xóa Bài Và Bình Luận:</> Tại bài đăng hoặc bình luận của mình, nhấn nút ··· để xóa.\n<Assistant_Title2>Lưu Ý:</><Assistant_Red>Nội dung hoặc hình ảnh không phù hợp trong bài đăng/bình luận Vòng Quỷ Bí sẽ bị gỡ.</> Nếu phát hiện hành vi vi phạm hoặc bất thường của người chơi khác, hãy báo cáo hoặc liên hệ CSKH.\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Vòng Quỷ Bí]|1390}，{SendAnswer:[Vòng Quỷ Bí-Quan Hệ]|1392}，{SendAnswer:[Vòng Quỷ Bí-Tab]|1393}，{SendAnswer:[Vòng Quỷ Bí-Chủ Đề]|1394}",
    [527767192174336] = "<Assistant_Title1>【Phòng Thoại - Phòng Gameplay】</>\n<Assistant_Title2>Cấp Mở:</> Cấp Nhận Thức <Assistant_Red>10</>\n<Assistant_Title2>Lối Vào:</><Assistant_System>Bảng Chat - Phòng Thoại</>{JumpToUI:[【Đến Xem】]|1250316}\n<Assistant_Title2>Giới Hạn Người:</> Tối đa 1000 người trong một Phòng Thoại.\n<Assistant_Title2>Chế Độ Phát Biểu Mặc Định:</> Phòng Gameplay mặc định dùng thứ tự phát biểu do chủ phòng cài. Bấm nút mở mic để xin lên mic; sau khi chủ phòng duyệt có thể phát biểu.\n<Assistant_Title2>Tín Hiệu Rung Động:</> Người chơi trong hàng mic tự động có thân phận Khách Mời; người ở mic số 1 là Thượng Khách. Mọi Khách Mời có thể bật/tắt trạng thái Đèn Sáng để biểu đạt cảm xúc. Giao diện trực tiếp ở góc trên phải cho phép xem rõ tình trạng phát biểu và Đèn Sáng của tất cả Khách Mời.\n<Assistant_Title2>Thao Tác Chủ Phòng:</> Chủ phòng có thể chỉnh thứ tự phát biểu, cấm tiếng và blacklist tại Quyền Thành Viên; cũng có thể chỉnh thông tin phòng, gia hạn Phòng Thường Trực và chuyển quyền chủ phòng ở bảng cài đặt bên phải.\n<Assistant_Title2>Thao Tác Khác:</> Thanh bên phải cho phép chia sẻ liên kết Phòng Thoại và phát Lì Xì Phòng Thoại.\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Phòng Thoại - Quyền Chủ Phòng]|1395}，{SendAnswer:[Phòng Thoại - Phòng Thường]|1396}，{SendAnswer:[Phòng Thoại - Phòng Thường Trực]|1398}",
    [527767192174592] = "<Assistant_Title1>【Phòng Voice - Phòng Thường Trực】</>\n<Assistant_Title2>Lối Vào:</><Assistant_System>Phòng Voice Lối Chơi - Cài Đặt góc phải dưới - nút Thường Trực góc phải trên</>{JumpToUI:[【Đến Xem】]|1250316}\n<Assistant_Title2>Vật Phẩm Thường Trực:</> Có thể mua Khế Ước Thường Trực tại <Assistant_System>Cửa Hàng - Trưng Bày Bí Tàng</>. Sau khi dùng, có thể chuyển Phòng Voice Lối Chơi thành Phòng Thường Trực và tăng 30 ngày thời hạn. Mỗi vật phẩm gia hạn 30 ngày, tổng thời hạn liên tục tối đa 90 ngày.\n<Assistant_Title2>Chức Năng:</> Sau khi chuyển thành Phòng Thường Trực, <Assistant_Red>rời phòng voice hoặc offline</> vẫn giữ phòng và chủ phòng vẫn giữ quyền chủ. <Assistant_Red>Phòng Voice Thường Trực không thể chuyển chủ.</>\n<Assistant_Title2>Giới Hạn Số Lượng:</> Mỗi nhân vật tối đa sở hữu <Assistant_Red>1 Phòng Voice Thường Trực</>.\n<Assistant_Title2>Giải Tán:</> Chủ phòng có thể chủ động giải tán; sau khi giải tán <Assistant_Red>không thể khôi phục</>.\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[Phòng Voice-Quyền Chủ Phòng]|1395}，{SendAnswer:[Phòng Voice-Phòng Thường]|1396}，{SendAnswer:[Phòng Voice-Phòng Lối Chơi]|1397}",
    [527767192174848] = "<Assistant_Title1>【Câu Lạc Bộ】</>\n<Assistant_Title2>Cấp Mở:</> Cấp Nhận Thức <Assistant_Red>20</>\n<Assistant_Title2>Lối Vào:</><Assistant_System>Menu - CLB</>{JumpToUI:[【Đi Xem】]|1250052}\n<Assistant_Title2>Giới Thiệu:</> Khi nhân vật đạt Cấp 20, có thể gia nhập hoặc tự tạo CLB. Tham gia các hoạt động CLB để nhận nhiều phần thưởng và Huy Chương Đồng Hành; Huy Chương Đồng Hành có thể đổi vật phẩm tại Cửa Hàng CLB.\n<Assistant_Title2>Tạo CLB:</> Tạo CLB cần trả phí. Trong 24 giờ sau khi tạo, nếu đủ 4 người hưởng ứng thì thành công; quá hạn sẽ thất bại. <Assistant_Red>Tạo thất bại hoặc chủ động hủy đều không hoàn lại phí tạo.</>\n<Assistant_Title2>Loại CLB:</> Gồm CLB Nhàn Nhã và CLB Chiến Đấu, có thể đổi trong thông tin CLB. CLB Nhàn Nhã không hiển thị Điểm Phi Phàm trong danh sách thành viên.\n<Assistant_Title2>Vật Phẩm Đổi Tên:</> Có thể mua Thông Báo Đổi Tên tại <Assistant_System>Shop - Trưng Bày Bí Tàng</> để đổi tên CLB và chữ trên huy hiệu.\n<Assistant_Title2>Giới Hạn Hoạt Động:</> 1. Khóa thành viên CLB: trong các hoạt động lấy CLB làm đơn vị (như <Assistant_System>Liên Đấu Tứ Phương, Bóng Ma Opera, Chiến Thành, Chiến Cao Nguyên</>), CLB <Assistant_Red>không cho phép thành viên gia nhập hoặc rời đi.</>\n2. Giới hạn số người theo Con Đường: một số hoạt động CLB giới hạn <Assistant_Red>số người của từng Con Đường</>; xem chi tiết trong mô tả hoạt động.\n3. Trước khi tham gia, hãy kiểm tra phân công chức vụ. <Assistant_Red>Một số hoạt động chỉ cho Hội Viên Chính Thức thi đấu</>; Hội Viên Chính Thức là lực lượng nòng cốt, có thể tham gia hoạt động CLB. Thành Viên Dự Bị là lực lượng dự trữ, không thể tham gia một số hoạt động; hãy duy trì hoạt động và liên hệ quản lý để được chuyển chính thức.\n<Assistant_Title3>Chi Tiết Chức Năng Cơ Bản:</>{SendAnswer:[CLB - Công Trình và Quỹ CLB]|1401}，{SendAnswer:[CLB - Chức Vụ CLB]|1402}，{SendAnswer:[CLB - Hoạt Động CLB]|1403}，{SendAnswer:[Khu Vực - CLB]|567}",
    [527767192175104] = "<Assistant_Title1>【CLB-Kiến Trúc & Quỹ】</>\n<Assistant_Title2>Lối Vào:</><Assistant_System>Menu-CLB-Nâng Cấp Kiến Trúc</>{JumpToUI:[【Đến Xem】]|1250318}\n<Assistant_Title2>Nguồn Quỹ:</> Trợ Cấp Hoạt Động CLB và hoạt động CLB.\n<Assistant_Title2>Công Dụng:</> Dùng nâng kiến trúc CLB, tăng thực lực, phúc lợi và quy mô.\n<Assistant_Title2>Tiêu Hao Quỹ:</> Nâng kiến trúc tiêu hao Quỹ CLB và cần chờ một thời gian. Mỗi kiến trúc có hiệu quả theo cấp; cấp kiến trúc khác không thể vượt Cấp Phòng Nghị Sự.\n<Assistant_Title2>Giới hạn nâng mở dần theo thời gian server</>Cấp 3: sau 8:00 ngày 7 mở server\nCấp 4: sau 8:00 ngày 14\nCấp 5: sau 8:00 ngày 21\nCấp 6: sau 8:00 ngày 30\nCấp 7: sau 8:00 ngày 45\nCấp 8: sau 8:00 ngày 60\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[CLB]|1400}，{SendAnswer:[CLB-Chức Vụ CLB]|1402}，{SendAnswer:[CLB-Hoạt Động CLB]|1403}，{SendAnswer:[CLB-Trợ Cấp Hoạt Động]|1404}，",
    [527767192175616] = "<Assistant_Title1>【CLB - Hoạt Động CLB】</>\n<Assistant_Title2>Cấp Hoạt Động:</> Cấp Hoạt Động CLB từ cao xuống thấp gồm:\nHội Vụ Vắng Vẻ (＜720)\nVận Hành Thường (720~2400)\nHội Vụ Phồn Vinh (＞2400)\n<Assistant_Title2>Nguồn Hoạt Động:</> Trợ Cấp Hoạt Động\n<Assistant_Title2>Giải Thích:</> Hoạt Động CLB càng cao, thưởng Chia Lợi Nhuận CLB hàng tuần càng lớn.\n<Assistant_Title2>Tiêu Hao Hoạt Động:</> Bảo trì CLB mỗi ngày trừ 5% Hoạt Động hiện tại. Nếu liên tục 7 ngày ở mức Hội Vụ Vắng Vẻ, Cấp Phòng Nghị Sự giảm 1. <Assistant_Red>Nếu Cấp Phòng Nghị Sự dưới Cấp 1, CLB sẽ tự động giải tán.</>\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[CLB]|1400}，{SendAnswer:[CLB-Trợ Cấp Hoạt Động]|1404}，{SendAnswer:[CLB-Chia Lợi Nhuận]|1405}",
    [527767192176128] = "<Assistant_Title1>【CLB - Cổ Tức CLB】</>\n<Assistant_Title2>Lối Vào:</><Assistant_System>Menu - CLB - Phúc Lợi - Cổ Tức</>{JumpToUI:[【Đến Xem】]|1250319}\n<Assistant_Title2>Giải Thích:</> Mỗi tuần có thể nhận thưởng Cổ Tức CLB một lần.\nThưởng Cổ Tức CLB chịu ảnh hưởng bởi Cấp Hoạt Động của CLB và mức hoạt động cá nhân tại CLB hiện tại trong tuần trước.\nThưởng Cổ Tức CLB làm mới vào 8:00 sáng thứ Hai hằng tuần; hãy nhận kịp thời.\n<Assistant_Title3>Gợi Ý Tìm Kiếm:</>{SendAnswer:[CLB]|1400}，{SendAnswer:[CLB - Trợ Cấp Hoạt Động]|1404}，{SendAnswer:[CLB - Hoạt Động]|1403}",
    [527767192178176] = "<Assistant_Title1>【Chat】</>\n<Assistant_Title2>Lối Vào:</><Assistant_System>HUD góc trái dưới - Chat</>{JumpToUI:[【Đến Xem】]|1250050}\n<Assistant_Title2>Kênh Chat:</> Có thể chuyển giữa các kênh ở danh sách bên trái.\n<Assistant_Title2>Cài Đặt Chat:</> Vào <Assistant_System>Bảng Chat - nút Cài Đặt phía dưới</> để thiết lập kênh. Trong <Assistant_System>Cài Đặt Chung - Hiển Thị Kênh Chat</> có thể chọn kênh cần hiển thị; trong <Assistant_System>Cài Đặt Kênh</> có thể điều khiển kênh hiển thị ở HUD góc trái dưới.\n<Assistant_Title2>Kênh Tổng Hợp:</> Tổng hợp tin nhắn từ nhiều kênh để xem nhanh. Có thể chọn các kênh được gộp trong <Assistant_System>Cài Đặt Kênh</>.\n<Assistant_Title2>Cửa Sổ Chat Nhỏ:</> Nhấn nút cửa sổ nhỏ ở góc phải dưới giao diện Chat để mở chế độ cửa sổ nhỏ; có thể tự do kéo vị trí.\n<Assistant_Title3>Quy Tắc Chức Năng Cơ Bản:</>{SendAnswer:[Chat-Sticker]|1414}",
    [527767192178688] = "<Assistant_Title1>【Quà Tặng Xã Giao】</>\n<Assistant_Title2>Lối Vào:</> Tại <Assistant_System>Thương Thành - Khắc Dấu Hình Tượng - Nhân Khí Xã Giao</>, tiêu hao Bảng Vàng Khóa hoặc Bảng Vàng không khóa để mua quà xã giao tặng bạn bè/người chơi khác.\n<Assistant_Title2>Tặng Bạn:</> Tại <Assistant_System>Chat Riêng Bạn Bè - Tặng Quà góc phải dưới</>, tặng quà Độ Thân Thiện; sau khi tặng, tăng Độ Thân Thiện hai bên.\n<Assistant_Title2>Tặng Trang Cá Nhân:</> Tại <Assistant_System>Trang Cá Nhân - Tặng Quà góc phải dưới</>, tặng quà trang cá nhân; tăng Danh Vọng Trang Cá Nhân của đối phương. Nếu là bạn bè, tăng thêm Độ Thân Thiện.\n<Assistant_Title2>Tặng Phòng Voice:</> Tại <Assistant_System>Phòng Voice - nhấn avatar người chơi - Tặng Quà Phòng Voice</>, tăng Nhiệt Độ phòng hiện tại và Danh Vọng Trang Cá Nhân của đối phương.\n<Assistant_Title3>Tìm Kiếm Đề Xuất:</>{SendAnswer:[Bạn Bè-Độ Thân Thiện]|1410}",
    [527767192178944] = "<Assistant_Title1>Trang Bị</>\n\n<Assistant_Title2>Phẩm Chất:</> Tím, Vàng, Cam, Đỏ (Thần Thoại).\n\n<Assistant_Title2>Vị Trí:</> Mùa hiện tại mở các vị trí: Vũ Khí, Trâm Ngực, Nhẫn, Hộ Phù, Mũ, Áo Choàng, Giày, Giáp.\n\n<Assistant_Title2>Cách Nhận:</> Có thể nhận Trang Bị từ Bí Bảo Mạo Hiểm Thế Giới/Lấy Chiến Nuôi Chiến/Quà Tặng Xã Giao, thách đấu các Phó Bản và tham gia các lối chơi cạnh tranh lớn.",
    [527767192179200] = "<Assistant_Title1>Trang Bị Lạc Ấn</>\n\n<Assistant_Title2>Giải Thích Trang Bị:</> Trang Bị Lạc Ấn có hiệu ứng dòng Lạc Ấn riêng nhưng không có hiệu ứng Bộ.\n\n<Assistant_Title2>Cách Nhận:</>\n\n1. Tham gia Phó Bản để nhận Trang Bị Lạc Ấn thiên Mạo Hiểm.\n\n2. Mở Bí Bảo Lấy Chiến Nuôi Chiến hoặc đổi tại Cửa Hàng Hoàn Trả để nhận Trang Bị Lạc Ấn thiên Thi Đấu.\n\n3. Ngoài ra, có thể nhận Trang Bị Lạc Ấn qua nhiệm vụ và khám phá.",
    [527767192179456] = "<Assistant_Title1>Trang Bị Thần Thoại</>\n\n<Assistant_Title2>Giải Thích Lối Chơi:</>\n\n1. Sau khi nhận Kén Dệt Thần Thoại, có thể nhận nhiệm vụ 【Ẩn Bí Chi Ủng】 để mở khóa phương pháp rèn Vũ Khí Thần Thoại.\n\n2. Có thể dùng Tơ Kén trước để chế tạo vũ khí phẩm chất Đỏ (Thần Thoại) 【Dạ Mạc Chi Tụng】; sau khi nhận Kén Dệt Thần Thoại, bổ sung vật liệu để hoàn tất rèn 【Ẩn Bí Chi Ủng】.",
    [527767192179712] = "<Assistant_Title1>Cường Hóa Trang Bị</>\n\n<Assistant_Title2>Giải Thích Lối Chơi:</>\n\n1. Mỗi bộ phận có thể tiêu hao nguyên liệu cường hóa để tăng cường, tối đa Bậc 8.\n\n2. Mỗi bậc tăng thuộc tính nhân vật; thuộc tính tăng hiển thị trong phần Thuộc Tính Cơ Bản của trang bị.\n\n3. Khi đổi trang bị, hiệu quả cường hóa chuyển nguyên vẹn; nếu không mặc trang bị ở bộ phận tương ứng thì hiệu quả không có hiệu lực.\n\n4. Khi bậc cường hóa của mọi bộ phận cùng đạt yêu cầu, kích hoạt Bộ Cường Hóa để tăng thêm năng lực nhân vật.\n\n<Assistant_Title2>Nhận Vật Phẩm:</> Nguyên liệu cường hóa có thể đổi tại Cửa Hàng Hoàn Phí, hoặc nhận khi mở Bí Bảo Mạo Hiểm Thế Giới/Lấy Chiến Nuôi Chiến/Quà Tặng Xã Giao",
    [527767192179968] = "<Assistant_Title1>Dòng Thuộc Tính Trang Bị</>\n\n<Assistant_Title2>Giải Thích Lối Chơi:</>\n\n1. Khi Trang Bị được tạo ra sẽ mang các dòng thuộc tính ngẫu nhiên.\n\n2. Khi nhận Trang Bị có Dòng Thuộc Tính Phi Phàm, tổ hợp dòng sẽ được lưu lại; có thể áp dụng tổ hợp đã lưu tại mục “Ân Tứ” bên phải giao diện Tái Tạo.\nVí dụ: nhận một Nhẫn có 2 Dòng Thuộc Tính Phi Phàm thì tổ hợp trên Nhẫn sẽ tự lưu; có thể tìm phương án đã lưu trong “Ân Tứ” bên phải giao diện Tái Tạo và áp dụng cho bất kỳ Nhẫn nào.",
    [527767192180224] = "<Assistant_Title1>Tái Tạo Trang Bị</>\n\n<Assistant_Title2>Giải Thích Lối Chơi:</>\n\n1. Trong mùa hiện tại, Vũ Khí, Giáp, Trâm Cài và Mũ lần lượt mở chức năng Tái Tạo Từ. Sau khi mở, tiêu hao Tinh Thạch Núi Lam để Tái Tạo trang bị và nhận từ trang bị ngẫu nhiên.\n\n2. Bộ phận chưa mở Tái Tạo vẫn có thể Lưu và Áp Dụng từ. Ví dụ: khi nhận Nhẫn có 2 Từ Phi Phàm từ lối chơi, tổ hợp từ đó tự động được lưu và có thể áp dụng cho bất kỳ Nhẫn nào trong mục “Ân Tứ” bên phải giao diện Tái Tạo.\n\n<Assistant_Title2>Nhận Vật Phẩm:</> Có thể nhận Tinh Thạch Núi Lam qua phân giải trang bị, đổi tại Cửa Hàng Hoàn Phí...",
    [527767192185856] = "<Assistant_Title1>【Ánh Nhìn Vực Sâu】</>\n<Assistant_Title2>Mô Tả:</> Phụ kiện thưởng từ gameplay\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Ánh Nhìn Vực Sâu; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Nhận từ <Assistant_System>Gameplay - Công Hội</>",
    [527767192187136] = "<Assistant_Title1>【“Ngôi Sao”】</>\n<Assistant_Title2>Mô Tả:</> Trang Phục Hồ Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ “Ngôi Sao”; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Hoán Nhan Linh Giới</>",
    [527767192187392] = "<Assistant_Title1>【Minh Vu Lục Dạ】</>\n<Assistant_Title2>Mô Tả:</> Trang Phục Hồ Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Minh Vu Lục Dạ; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Hoán Nhan Linh Giới</>",
    [527767192187648] = "<Assistant_Title1>【Thơ Không Vần】</>\n<Assistant_Title2>Mô Tả:</> Trang Phục Hồ Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Thơ Không Vần; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Hoán Nhan Linh Giới</>",
    [527767192187904] = "<Assistant_Title1>【Truyền Kỳ Thời Đại】</>\n<Assistant_Title2>Mô Tả:</> Kiểu Tóc Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Truyền Kỳ Thời Đại; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng, hoặc đổi thành <Assistant_Red>1</> Thẻ Thần Quyến.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Hoán Nhan Linh Giới</>, hoặc tại <Assistant_System>Cửa Hàng Quà Tặng Mỹ Thần</> dùng <Assistant_Red>1</> Thẻ Thần Quyến để mua",
    [527767192188160] = "<Assistant_Title1>【Lời Thề Im Lặng】</>\n<Assistant_Title2>Mô Tả:</> Kiểu Tóc Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Lời Thề Im Lặng; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng, hoặc đổi thành <Assistant_Red>1</> Thẻ Thần Quyến.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Hoán Nhan Linh Giới</>, hoặc tại <Assistant_System>Cửa Hàng Quà Tặng Mỹ Thần</> dùng <Assistant_Red>1</> Thẻ Thần Quyến để mua",
    [527767192188416] = "<Assistant_Title1>【Đại Arcana】</>\n<Assistant_Title2>Mô Tả:</> Kiểu Tóc Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Đại Arcana; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng, hoặc đổi thành <Assistant_Red>1</> Thẻ Thần Quyến.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Hoán Nhan Linh Giới</>, hoặc tại <Assistant_System>Cửa Hàng Quà Tặng Mỹ Thần</> dùng <Assistant_Red>1</> Thẻ Thần Quyến để mua",
    [527767192188672] = "<Assistant_Title1>【Vũ Trụ Trong Vỏ】</>\n<Assistant_Title2>Mô Tả:</> Kiểu Tóc Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Vũ Trụ Trong Vỏ; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng, hoặc đổi thành <Assistant_Red>1</> Thẻ Thần Quyến.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Hoán Nhan Linh Giới</>, hoặc tại <Assistant_System>Cửa Hàng Quà Tặng Mỹ Thần</> dùng <Assistant_Red>1</> Thẻ Thần Quyến để mua",
    [527767192188928] = "<Assistant_Title1>【Tiểu Dạ Khúc】</>\n<Assistant_Title2>Mô Tả:</> Kiểu Tóc Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Tiểu Dạ Khúc; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng, hoặc đổi thành <Assistant_Red>1</> Thẻ Thần Quyến.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Hoán Nhan Linh Giới</>, hoặc tại <Assistant_System>Cửa Hàng Quà Tặng Mỹ Thần</> dùng <Assistant_Red>1</> Thẻ Thần Quyến để mua",
    [527767192189184] = "<Assistant_Title1>【Tụng Ca Cờ Xí】</>\n<Assistant_Title2>Mô Tả:</> Kiểu Tóc Thần Quyến\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận Tụng Ca Cờ Xí; vào <Assistant_System>Ngoại Hình-Thay Đồ</> để xem và dùng, hoặc đổi thành <Assistant_Red>1</> Thẻ Thần Quyến.\n<Assistant_Title2>Nhận:</> Qua <Assistant_System>Triệu Hồi-Hoán Nhan Linh Giới</>, hoặc tại <Assistant_System>Cửa Hàng Quà Tặng Mỹ Thần</> dùng <Assistant_Red>1</> Thẻ Thần Quyến để mua",
    [527767192190976] = "<Assistant_Title1>【Phán Quyết Tinh Bàn】</>\n<Assistant_Title2>Mô Tả:</> Trang phục thưởng Cấp Giáo Đoàn\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Phán Quyết Tinh Bàn; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Mở theo Cấp Giáo Đoàn",
    [527767192191232] = "<Assistant_Title1>【Dư Vị Ma Nữ】</>\n<Assistant_Title2>Mô Tả:</> Trang phục thưởng Cấp Giáo Đoàn\n<Assistant_Title2>Sử Dụng:</> Dùng để nhận bộ Dư Vị Ma Nữ; có thể vào <Assistant_System>Ngoại Hình - Thay Đồ</> để xem và sử dụng.\n<Assistant_Title2>Nguồn:</> Mở theo Cấp Giáo Đoàn",
