    [637718623203840] = "Cộng Minh Linh Tính",
    [637718623225344] = "Nhà Thờ Thánh Selena",
    [637787342679040] = "Đại Học Tingen",
    [637787342717952] = "Trang Viên Blackwood",
    [637787342721536] = "Núi Tuyết",
    [664107975969792] = "Phi Phàm Giả thân mến:\nMùa mới đã bắt đầu. Trong Túi của bạn còn %s tiền tệ chưa dùng; hệ thống đã tự động đổi theo tỷ lệ 1:%s sang %s tiền tệ.",
    [664107975974656] = "CLB <M_Orange>%s </> đã hoàn tất hưởng ứng và thành lập thành công!\n· Sau khi gia nhập CLB, mỗi ngày có thể tham gia gameplay đặc sắc.\n· Nhận lãnh địa CLB riêng.\n· Có thể dẫn thành viên tham gia giải đấu, tranh vinh dự cao nhất.\n· Trước khi tham gia hoạt động, hãy kiểm tra phân công chức vụ. Thành Viên Chính Thức là lực lượng nòng cốt và có thể tham gia gameplay CLB; Thành Viên Dự Bị là lực lượng dự trữ, không thể tham gia một số hoạt động CLB. Hãy duy trì hoạt động và liên hệ quản lý để được chuyển thành Thành Viên Chính Thức.",
    [664107975975424] = "CLB <M_Orange>%s </> chào mừng bạn gia nhập!\n· Sau khi gia nhập CLB, mỗi ngày có thể tham gia gameplay đặc sắc.\n· Nhận lãnh địa CLB riêng.\n· Có thể dẫn thành viên tham gia giải đấu, tranh vinh dự cao nhất.\n· Trước khi tham gia hoạt động, hãy kiểm tra phân công chức vụ và giới hạn số người theo Con Đường. Thành Viên Chính Thức là lực lượng nòng cốt và có thể tham gia gameplay CLB; Thành Viên Dự Bị là lực lượng dự trữ, không thể tham gia một số hoạt động CLB. Hãy duy trì hoạt động và liên hệ quản lý để được chuyển thành Thành Viên Chính Thức.",
    [664107975976704] = "Trong mùa giải %s, CLB đã trải qua %s trận, đạt thành tích %s thắng %s thua, xếp hạng %s trong các CLB máy chủ này. Nay phát thưởng như sau; mong các thành viên tiếp tục giữ phong độ và tái lập huy hoàng trong mùa giải mới!",
    [664107975985920] = "%s đã quá hạn chưa nhận vật phẩm %s bạn tặng; tiền tệ đã tiêu hao khi mua đã được hoàn trả cho bạn.",
    [664107975987968] = "Phi Phàm Giả thân mến:\nBạn đã mua nhanh đạo cụ <M_Link>%s</> thành công. Hãy nhận đạo cụ tương ứng.",
    [664107975988736] = "Kính gửi Phi Phàm Giả:\nHệ thống phát hiện giao dịch gần đây của bạn có dấu hiệu giao dịch ngoài luồng (vật phẩm <M_Link>%s</>, tổng giá trị giao dịch <M_Link>%s</>). Để bảo vệ quyền lợi của bạn, vui lòng không tham gia giao dịch ngoài luồng. Nếu tiếp tục phát sinh hành vi tương tự, tài khoản sẽ chịu hình phạt nặng hơn, bao gồm nhưng không giới hạn ở đóng băng tiền tệ hoặc khóa Sàn Giao Dịch.",
    [664107975999232] = "Gửi Phi Phàm Giả:\nMột số Phi Phàm Giả đã nhận thêm vật phẩm Tinh Thạch Lam Sơn trong sự kiện 「Tăng Tốc Trang Bị」. Để đảm bảo giới hạn vật phẩm tối đa mà mọi Phi Phàm Giả nhận được từ sự kiện là như nhau, Kẻ Gác Đêm đã khấu trừ phần %s nhận dư. Chúng tôi chân thành xin lỗi vì bất tiện trong thời gian xảy ra bất thường.",
    [664107975999488] = "Gửi Phi Phàm Giả:\nMột số Phi Phàm Giả đã nhận thêm vật phẩm Tinh Thạch Lam Sơn trong sự kiện 「Tăng Tốc Trang Bị」. Để đảm bảo giới hạn vật phẩm tối đa mà mọi Phi Phàm Giả nhận được từ sự kiện là như nhau, Kẻ Gác Đêm đã khấu trừ phần %s nhận dư; phần còn phải khấu trừ (%s) sẽ được trừ khi bạn nhận vật phẩm này trong tương lai. Chúng tôi chân thành xin lỗi vì bất tiện trong thời gian xảy ra bất thường.",
    [664107976000768] = "Kính gửi Phi Phàm Giả:\n    “Đối Chiến Thế Lực” đã bắt đầu. CLB của bạn nằm trong top 4 điểm ở vòng sàng lọc chiến khu và giành quyền vào chiến trường quyết thắng Chiến Thành.\n    Hãy kiểm tra lịch và thể thức tại Lấy Chiến Nuôi Chiến - Thế Lực - Chiến Thành. Lưu ý: trong cùng một CLB, thành viên chính thức của mỗi Con Đường tối đa <M_Orange>16 người</> ra trận; hãy bố trí đội hình hợp lý.\n    Chiến trường quyết thắng sẽ định đoạt kết quả Đối Chiến Thế Lực. Tham gia có thể nhận Nhân Mạch, vật phẩm rút Bí Ngẫu, cổ tức Soles cao hơn, danh hiệu chiến trường và nhiều phần thưởng khác.\n    Chúc bạn làm chủ chiến trường dưới ánh nhìn của Tứ Hoàng. Hẹn gặp lại!",
    [664107976001024] = "Kính gửi Phi Phàm Giả:\n    “Đối Chiến Thế Lực” đã bắt đầu. Sau khi đánh giá tổng hợp CLB của bạn, chiến trường diễn binh Thành Liệp Long đang chờ bạn.\n    Hãy kiểm tra lịch và thể thức tại Lấy Chiến Nuôi Chiến - Thế Lực - Chiến Thành. Lưu ý: trong cùng một CLB, thành viên chính thức của mỗi Con Đường tối đa <M_Orange>16 người</> ra trận; hãy bố trí đội hình hợp lý.\n    Tham gia Chiến Thành có thể nhận Nhân Mạch, vật phẩm rút Bí Ngẫu, cổ tức Soles, danh hiệu chiến trường và nhiều phần thưởng khác.\n    Chúc bạn làm chủ chiến trường dưới ánh nhìn của Tứ Hoàng. Hẹn gặp lại!",
    [664107976002304] = "<M_Red>「Hoàn thành đầy đủ khảo sát để nhận 300 Bảng Vàng Khóa!」</> <HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Test Sương Xám 2</> Phi Phàm Giả thân mến:     Chúc con đường Phi Phàm của bạn bình ổn thuận lợi.     Hai ngày đã lặng lẽ trôi qua từ khi vận mệnh triệu hồi bạn đến thế giới này. Trên những con phố Tingen, nơi nào khiến bạn lần đầu dừng chân và cảm nhận thế giới trở nên chân thực? Trong chiến đấu, khoảnh khắc nào khiến tim bạn đập nhanh, thật sự “nhập vai” thân phận tương ứng với Bậc của mình? Trong cốt truyện, lựa chọn hay câu thoại nào chạm tới bạn?     Dù câu trả lời là gì, chúng tôi đều vô cùng trân trọng. Mời bạn đi qua lối bí ẩn trong thư để gửi lại những điều đã chứng kiến và cảm nhận. Mỗi góc nhìn của bạn sẽ giúp chúng tôi gọt giũa thế giới chân thực hơn.     Cảm ơn bạn đã góp phần thay đổi thế giới này. Chúc bạn sớm tiêu hóa Ma Dược và làm chủ Phi Phàm.",
    [664107976003072] = "<M_Red>「Hoàn thành đầy đủ khảo sát để nhận 300 Bảng Vàng Khóa!」</>\n<HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Test Sương Xám - Chuyên Đề PvP</>\nPhi Phàm Giả thân mến:\n    Nguyện Linh Tính dẫn đường.\n    Chúng tôi muốn tìm hiểu trải nghiệm và đánh giá thực tế của bạn về PvP hiện tại. Chiến đấu có đủ căng thẳng, kích thích? Cân bằng giữa các chế độ, cơ chế ghép trận hay nhịp độ chiến đấu có điểm nào chưa hài lòng hoặc cần tối ưu?\n    Mời bạn nhấn lối đi bí ẩn trong thư và chia sẻ cảm nhận, góp ý quý báu từ các trận đối chiến.\n    Phản hồi của bạn sẽ trực tiếp giúp tối ưu cân bằng, hoàn thiện trải nghiệm ghép trận và xây dựng môi trường PvP công bằng, quyết liệt hơn.\n    Cảm ơn bạn đã góp phần thay đổi thế giới này. Chúc bạn sớm tiêu hóa Ma Dược và làm chủ Phi Phàm.",
    [664107976003584] = "Phi Phàm Giả thân mến:\n    Chúng tôi nhận thấy khảo sát về trải nghiệm ngày đầu đã được bạn gửi góp ý quý báu qua một thân phận khác. Theo thỏa thuận, quà cảm ơn lần này sẽ được Sứ Giả Linh Giới gửi thẳng tới Hòm Thư, vui lòng kiểm tra.\n<HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Test Sương Xám 1</>\n    Nếu vẫn muốn để lại ý kiến bằng thân phận hiện tại, bạn có thể tiếp tục gửi suy nghĩ qua lối bí ẩn trong thư; chúng tôi luôn hoan nghênh góp ý.\n    Cảm ơn bạn đã chứng kiến hành trình này; nguyện Linh Tính dẫn đường.",
    [664107976003840] = "Phi Phàm Giả thân mến:\n    Chúng tôi nhận thấy khảo sát về trải nghiệm hai ngày đã được bạn gửi góp ý quý báu qua một thân phận khác. Theo thỏa thuận, quà cảm ơn lần này sẽ được Sứ Giả Linh Giới gửi thẳng tới Hòm Thư, vui lòng kiểm tra.\n<HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Test Sương Xám 2</>\n    Nếu vẫn muốn để lại ý kiến bằng thân phận hiện tại, bạn có thể tiếp tục gửi suy nghĩ qua lối bí ẩn trong thư; chúng tôi luôn hoan nghênh góp ý.\n    Cảm ơn bạn đã chứng kiến hành trình này; nguyện Linh Tính dẫn đường.",
    [664107976004096] = "Phi Phàm Giả thân mến:\n    Chúng tôi nhận thấy khảo sát về trải nghiệm ba ngày đã được bạn gửi góp ý quý báu qua một thân phận khác. Theo thỏa thuận, quà cảm ơn lần này sẽ được Sứ Giả Linh Giới gửi thẳng tới Hòm Thư, vui lòng kiểm tra.\n<HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Test Sương Xám 3</>\n    Nếu vẫn muốn để lại ý kiến bằng thân phận hiện tại, bạn có thể tiếp tục gửi suy nghĩ qua lối bí ẩn trong thư; chúng tôi luôn hoan nghênh góp ý.\n    Cảm ơn bạn đã chứng kiến hành trình này; nguyện Linh Tính dẫn đường.",
    [664107976004352] = "Phi Phàm Giả thân mến:\n    Chúng tôi nhận thấy khảo sát về chuyên đề PvE đã được bạn gửi góp ý quý báu qua một thân phận khác. Theo thỏa thuận, quà cảm ơn lần này sẽ được Sứ Giả Linh Giới gửi thẳng tới Hòm Thư, vui lòng kiểm tra.\n<HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Test Sương Xám - Chuyên Đề PvE</>\n    Nếu vẫn muốn để lại ý kiến bằng thân phận hiện tại, bạn có thể tiếp tục gửi suy nghĩ qua lối bí ẩn trong thư; chúng tôi luôn hoan nghênh góp ý.\n    Cảm ơn bạn đã chứng kiến hành trình này; nguyện Linh Tính dẫn đường.",
    [664107976004608] = "Phi Phàm Giả thân mến:\n    Chúng tôi nhận thấy khảo sát về chuyên đề PvP đã được bạn gửi góp ý quý báu qua một thân phận khác. Theo thỏa thuận, quà cảm ơn lần này sẽ được Sứ Giả Linh Giới gửi thẳng tới Hòm Thư, vui lòng kiểm tra.\n<HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Test Sương Xám - Chuyên Đề PvP</>\n    Nếu vẫn muốn để lại ý kiến bằng thân phận hiện tại, bạn có thể tiếp tục gửi suy nghĩ qua lối bí ẩn trong thư; chúng tôi luôn hoan nghênh góp ý.\n    Cảm ơn bạn đã chứng kiến hành trình này; nguyện Linh Tính dẫn đường.",
    [664107976004864] = "Phi Phàm Giả thân mến:\n    Chúng tôi nhận thấy khảo sát về lối chơi thư giãn đã được bạn gửi góp ý quý báu qua một thân phận khác. Theo thỏa thuận, quà cảm ơn lần này sẽ được Sứ Giả Linh Giới gửi thẳng tới Hòm Thư, vui lòng kiểm tra.\n<HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Test Sương Xám - Chuyên Đề Lối Chơi Thư Giãn</>\n    Nếu vẫn muốn để lại ý kiến bằng thân phận hiện tại, bạn có thể tiếp tục gửi suy nghĩ qua lối bí ẩn trong thư; chúng tôi luôn hoan nghênh góp ý.\n    Cảm ơn bạn đã chứng kiến hành trình này; nguyện Linh Tính dẫn đường.",
    [664107976005120] = "Chào mừng gia nhập CLB!\n<M_Default>Liên Đấu Tứ Phương đầu tiên</> sẽ chính thức khai chiến vào <M_Default>20:00 Chủ Nhật tuần này</> — <M_Default>240 người</> cùng đối kháng, bốn phe kiềm chế lẫn nhau, là sân chơi thử thách phối hợp đội và ứng biến tại trận. Chuẩn bị sau sẽ giúp CLB đạt thành tích tốt hơn:\n    1. <M_Default>Thời Gian Phân Khu</>: <M_Default>12:00 trưa</> Chủ Nhật tuần này, hệ thống phân khu và xác định tư cách theo độ hoạt động CLB cùng các điều kiện khác.\n    2. <M_Default>Thời Gian Công Bố</>: <M_Default>18:00</> tối Chủ Nhật sẽ công bố khu thi đấu và chia bảng.\n    3. <M_Default>Yêu Cầu Hoạt Động</>: CLB cần ít nhất <M_Default>5</> người chơi hoạt động để đủ tư cách phân khu.\n    4. <M_Default>Tư Cách Thi Đấu</>: chỉ <M_Default>Hội Viên Chính Thức</> được tham gia; Hội Trưởng/Quản Lý hãy điều chỉnh chức vụ kịp thời.\n    5. <M_Default>Yêu Cầu Số Người</>: mỗi trận tối đa <M_Default>60 người</>; hãy tổ chức đủ thành viên, đồng thời mỗi Con Đường tối đa <M_Default>16 người</>. Phân bổ hợp lý để tạo đội hình mạnh nhất!\n    Hãy chiêu mộ thành viên, điều chỉnh chức vụ ngay và đảm bảo toàn đội có mặt lúc <M_Default>20:00 Chủ Nhật</>, chiến đấu vì vinh quang CLB!",
    [664107976005376] = "Các thành viên CLB chú ý:\n      <M_Default>Liên Đấu Tứ Phương đầu tiên</> sẽ chính thức khai chiến vào ngày mai (Chủ Nhật) lúc <M_Default>20:00</>! <M_Default>240 người</> cùng chiến đấu, bốn phe hợp tung liên hoành — đây là cuộc so tài tối thượng giữa trí tuệ và vũ lực, cũng là chiến trường đỉnh cao để giành vinh quang cho CLB!\n     Việc phân khu sẽ diễn ra vào <M_Default>12:00</> trưa mai. Hãy hoàn tất chuẩn bị trước thời điểm này:\n【Chuẩn Bị Trước Trận】\n    1. <M_Default>Xác Nhận Hoạt Động</>: CLB cần ít nhất <M_Default>5</> người chơi hoạt động, nếu không sẽ không đủ tư cách phân khu.\n    2. <M_Default>Điều Chỉnh Hội Viên Chính Thức</>: chỉ <M_Default>Hội Viên Chính Thức</> được tham gia giải; Hội Trưởng/Quản Lý hãy kiểm tra chức vụ và chuyển toàn bộ người dự chiến thành Hội Viên Chính Thức.\n    3. <M_Default>Xác Nhận Số Người</>: mỗi trận tối đa <M_Default>60 người</>, mỗi Con Đường tối đa <M_Default>16 người</>. Hãy phân bổ hợp lý để tạo đội hình mạnh nhất!\n 【Quy Tắc Giải】\n      Vào 【CLB】-【Hoạt Động】-【Liên Đấu Tứ Phương】 để xem chi tiết quy tắc chiến trường.",
    [664107976007168] = "<M_Default>Phi Phàm Giả thân mến:</>\n<M_Default>Một Khế Ước Thức Tỉnh đã được gửi tới — yêu cầu liên kết từ Quỷ Bí.</>\nHãy nhấn <HyperLink stylename=\"M_Link\" u=\"web=%s\">Xác Nhận Liên Kết</> để hoàn tất ký kết.\n Nếu không phải thao tác của bạn, hãy bỏ qua thư này.\nCảm ơn bạn đã chứng kiến hành trình này; nguyện Linh Tính dẫn đường.",
    [664107976008960] = "<M_Default>Kính gửi thành viên Giáo Đoàn:</>\n\n       Quyến Cố của Hắc Dạ không phải vĩnh hằng.\n       Qua kiểm tra, tuần trước bạn chưa hoàn thành thành công 3 Nghi Thức An Hồn. Theo quy tắc Giáo Đoàn, từ tuần này Trực Giác của bạn tạm thời bị áp chế (Thuộc Tính Trực Giác -5), cho tới khi trong tuần bạn lại hoàn thành thành công 3 Nghi Thức An Hồn.\n       Nguyện Hắc Dạ dẫn lối bạn trở về tĩnh lặng.",
    [664107976010240] = "Phi Phàm Giả thân mến:\n    Chúng tôi nhận thấy khảo sát về trải nghiệm game đã được bạn gửi góp ý quý báu qua một thân phận khác. Theo thỏa thuận, quà cảm ơn lần này sẽ được Sứ Giả Linh Giới gửi thẳng tới Hòm Thư, vui lòng kiểm tra.\n<HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Test Sương Xám 4</>\n    Nếu vẫn muốn để lại ý kiến bằng thân phận hiện tại, bạn có thể tiếp tục gửi suy nghĩ qua lối bí ẩn trong thư; chúng tôi luôn hoan nghênh góp ý.\n    Cảm ơn bạn đã chứng kiến hành trình này; nguyện Linh Tính dẫn đường.",
    [664107976011008] = "Phi Phàm Giả thân mến:\nHệ thống phát hiện nhân vật của bạn có hành vi vi phạm quy tắc Voice và hiện đã bị cấm phát biểu Voice.\nMôi trường game lành mạnh cần mọi người cùng bảo vệ; mong bạn tự giác tuân thủ quy tắc. Nếu tiếp tục vi phạm, hình phạt sẽ tăng, bao gồm nhưng không giới hạn kéo dài thời gian cấm mic / cấm mic vĩnh viễn. Nếu có thắc mắc hoặc khiếu nại, vui lòng liên hệ CSKH.",
    [664107976014080] = "<M_Default>Kính gửi Phi Phàm Giả:</>\n<M_Default>Hệ thống phát hiện tài khoản của bạn có nguy cơ hoàn tiền ác ý. Hiện đã thu hồi lượng Bảng Vàng/Bảng Vàng Khóa tương đương khoản hoàn tiền và hạn chế Thương Thành, Sàn Giao Dịch cùng các chức năng Triệu Hồi Linh Giới. Sau khi bù đủ Bảng Vàng/Bảng Vàng Khóa, hạn chế sẽ được gỡ.</>\n<M_Default>Nếu tiếp tục hoàn tiền ác ý, tài khoản có thể bị xử phạt, bao gồm nhưng không giới hạn ở khóa vĩnh viễn. Vì an toàn tài khoản, hãy kiểm tra kỹ thông tin vật phẩm trước khi mua. Cảm ơn sự hợp tác và thông cảm!</>\n<M_Default>Nếu có thắc mắc, vui lòng liên hệ CSKH trong game.</>",
    [664107976029696] = "<M_Default>Kính gửi Phi Phàm Giả:</>\n<M_Default>Giải Tứ Phương trận này đã kết thúc. CLB nhận được %s Điểm Vòng Loại Máy Chủ Chiến Lược. Cảm ơn mọi thành viên đã sát cánh chiến đấu; mong chúng ta tiếp tục đồng hành và tái lập thành tích trong hành trình tới!</>\n<M_Default>Có thể tới </><HyperLink stylename=\"M_Link\" u=\"jump=1302324\">【Máy Chủ Chiến Lược】</><M_Default> để xem.</>",
    [664107976029952] = "<M_Orange> [%s]</> đã chấp nhận lời tuyên chiến của CLB ta. Trận quyết đấu sẽ bắt đầu vào <M_Orange>[hôm nay %s]</>. Chiến hỏa đã tới, thắng bại sắp phân — dãy Hornacis sẽ chứng kiến kết cục trận này. Vì vinh quang chung, toàn bộ thành viên vào vị trí.\nBấm <HyperLink stylename=\"M_Link\" u=\"tipsId=6427619\">【Hướng Dẫn Tuyên Chiến CLB】</> để xem hướng dẫn!",
    [664107976030208] = "<M_Orange> [%s]</> đã chấp nhận lời tuyên chiến của CLB ta. Trận quyết đấu sẽ bắt đầu vào <M_Orange>[ngày mai %s]</>. Chiến hỏa đã tới, thắng bại sắp phân — dãy Hornacis sẽ chứng kiến kết cục trận này. Vì vinh quang chung, toàn bộ thành viên vào vị trí.\nBấm <HyperLink stylename=\"M_Link\" u=\"tipsId=6427619\">【Hướng Dẫn Tuyên Chiến CLB】</> để xem hướng dẫn!",
    [664107976033536] = "　　Bạn mở mắt, nhìn thấy Hồ Tingen quen thuộc — nơi mọi thứ bắt đầu.\n　　Nhưng bạn nhớ rất rõ, <M_Red>mình đã mất điểm Lý Trí cuối cùng. Ký ức vỡ vụn trong điên cuồng, ý thức bị bóng tối nuốt chửng, một sức mạnh lạnh lẽo thậm chí bắt đầu xóa đi dấu vết cho thấy bạn từng là “con người”.</>\n　　Ngay trước khi rơi xuống vực sâu điên loạn, bạn nhìn thấy Sương Xám vô biên. Sương Xám xuyên qua Minh Giới, tới trước Dòng Sông Vĩnh Ám và kéo bạn trở lại từ tận cùng giấc ngủ vĩnh hằng.\n\n　　Lý Trí hiện tại của bạn là <M_Orange>30</>, giới hạn Lý Trí tạm giảm xuống <M_Orange>70</>. Vết nứt tinh thần không thể tự biến mất, nhưng <M_Orange>An Hồn do Phi Phàm Giả khác thực hiện</> có thể giúp bạn khôi phục giới hạn Lý Trí.\n　　Trong <M_Orange>một tháng</> tiếp theo, sức mạnh đến từ Sương Xám vẫn sẽ đi theo bạn, bảo hộ sự tỉnh táo và khiến Lý Trí không giảm dưới <M_Orange>1</>.\n\n　　<M_Link>Đây là kỳ tích do chính Kẻ Khờ ban tặng.</>\n　　　<M_Link>Ca ngợi Kẻ Khờ!</>",
    [664107976034304] = "<M_Red>「Hoàn thành đầy đủ khảo sát để nhận 300 Bảng Vàng Khóa!」</> <HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Open Beta 2</> Phi Phàm Giả thân mến:       Chúc con đường Phi Phàm của bạn bình ổn thuận lợi.       Từ khi được vận mệnh triệu hồi tới thế giới này, hẳn bạn đã phần nào cảm nhận Tingen. Nơi nào trên phố khiến bạn lần đầu dừng chân và cảm nhận thế giới chân thực? Khoảnh khắc chiến đấu nào khiến tim đập nhanh, thật sự “nhập vai” thân phận tương ứng với Bậc của mình? Trong cốt truyện, lựa chọn hay câu thoại nào chạm tới bạn?       Dù câu trả lời là gì, chúng tôi đều vô cùng trân trọng. Mời bạn qua lối bí ẩn trong thư để gửi lại điều đã chứng kiến và cảm nhận. Mỗi góc nhìn sẽ giúp chúng tôi gọt giũa một thế giới Quỷ Bí chân thực hơn.       Cảm ơn bạn đã góp phần thay đổi thế giới này. Chúc bạn sớm tiêu hóa Ma Dược và làm chủ Phi Phàm.",
    [664107976034560] = "<M_Red>「Hoàn thành đầy đủ khảo sát để nhận 400 Bảng Vàng Khóa!」</>\n<HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Open Beta 3</>\nPhi Phàm Giả thân mến:\n      Những ngày qua, bạn đã để lại không ít dấu chân tại Tingen. Mỗi trận chiến, mỗi lựa chọn và mỗi lần tò mò về thế giới này đều soi sáng con đường phía trước cho chúng tôi.\n      Khi trải nghiệm và Nhập Vai sâu hơn, bạn đã hiểu thế giới này rõ hơn chưa? Nội dung nào để lại ấn tượng, nơi nào khiến bạn bối rối hoặc thấy chưa hoàn thiện? Đây không chỉ là một khảo sát, mà còn là lá phiếu quan trọng bạn gửi để thế giới tiếp tục hoàn thiện.\n      Mọi tiếng nói bạn truyền tới sẽ trở thành ngọn đèn dẫn đường.\n      Cảm ơn bạn đã góp phần thay đổi thế giới này. Chúc bạn sớm tiêu hóa Ma Dược và làm chủ Phi Phàm.",
    [664107976034816] = "<M_Red>「Điền đầy đủ khảo sát để nhận 400 Bảng Vàng Khóa!」</>\n<HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Open Beta 4</>\nKính gửi Phi Phàm Giả:\n      Trong quãng thời gian này, bạn đã đi xuyên ngày đêm ở Tingen, trải qua những trận chiến căng thẳng và cốt truyện thăng trầm, đồng thời để lại dấu ấn của riêng mình trong thế giới này. Từ lần đầu đặt chân tới nay, bạn đã có cái nhìn toàn diện và sâu sắc hơn về nơi đây.\n      Lúc này, chúng tôi muốn lắng nghe đầy đủ hơn tiếng nói của bạn. Nhìn lại hành trình, trải nghiệm nào khiến bạn hài lòng nhất? Thiết kế nào mang tới bất ngờ? Điều gì vẫn còn có thể cải thiện? Đây không chỉ là một bảng khảo sát, mà còn là lá phiếu quan trọng của bạn cho việc tiếp tục hoàn thiện thế giới này.\n      Mọi ý kiến bạn gửi đều sẽ trở thành ngọn đèn dẫn đường cho chúng tôi.\n      Cảm ơn những thay đổi bạn đã mang đến cho thế giới này. Chúc bạn sớm tiêu hóa Ma Dược, làm chủ sức mạnh Phi Phàm.",
    [664107976035072] = "Phi Phàm Giả thân mến:\n      Chúng tôi nhận thấy Khảo Sát 1 đã được bạn gửi góp ý quý báu qua một thân phận khác. Theo thỏa thuận, quà cảm ơn lần này sẽ được Sứ Giả Linh Giới gửi thẳng tới Hòm Thư, vui lòng kiểm tra.\n      Nếu vẫn muốn để lại ý kiến bằng thân phận hiện tại, bạn có thể tiếp tục gửi suy nghĩ qua lối bí ẩn trong thư; chúng tôi luôn hoan nghênh góp ý.\n<HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Open Beta 1</>\n      Cảm ơn bạn đã chứng kiến hành trình này; nguyện Linh Tính dẫn đường.",
    [664107976035328] = "Phi Phàm Giả thân mến:\n      Chúng tôi nhận thấy Khảo Sát 2 đã được bạn gửi góp ý quý báu qua một thân phận khác. Theo thỏa thuận, quà cảm ơn lần này sẽ được Sứ Giả Linh Giới gửi thẳng tới Hòm Thư, vui lòng kiểm tra.\n      Nếu vẫn muốn để lại ý kiến bằng thân phận hiện tại, bạn có thể tiếp tục gửi suy nghĩ qua lối bí ẩn trong thư; chúng tôi luôn hoan nghênh góp ý.\n<HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Open Beta 2</>\n      Cảm ơn bạn đã chứng kiến hành trình này; nguyện Linh Tính dẫn đường.",
    [664107976035584] = "Phi Phàm Giả thân mến:\n      Chúng tôi nhận thấy Khảo Sát 3 đã được bạn gửi góp ý quý báu qua một thân phận khác. Theo thỏa thuận, quà cảm ơn lần này sẽ được Sứ Giả Linh Giới gửi thẳng tới Hòm Thư, vui lòng kiểm tra.\n      Nếu vẫn muốn để lại ý kiến bằng thân phận hiện tại, bạn có thể tiếp tục gửi suy nghĩ qua lối bí ẩn trong thư; chúng tôi luôn hoan nghênh góp ý.\n<HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Open Beta 3</>\n      Cảm ơn bạn đã chứng kiến hành trình này; nguyện Linh Tính dẫn đường.",
    [664107976035840] = "Phi Phàm Giả thân mến:\n      Chúng tôi nhận thấy Khảo Sát 4 đã được bạn gửi góp ý quý báu qua một thân phận khác. Theo thỏa thuận, quà cảm ơn lần này sẽ được Sứ Giả Linh Giới gửi thẳng tới Hòm Thư, vui lòng kiểm tra.\n      Nếu vẫn muốn để lại ý kiến bằng thân phận hiện tại, bạn có thể tiếp tục gửi suy nghĩ qua lối bí ẩn trong thư; chúng tôi luôn hoan nghênh góp ý.\n<HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Open Beta 4</>\n      Cảm ơn bạn đã chứng kiến hành trình này; nguyện Linh Tính dẫn đường.",
    [664107976036352] = "Phi Phàm Giả thân mến:\n      Chúng tôi nhận thấy Khảo Sát 5 đã được bạn gửi góp ý quý báu qua một thân phận khác. Theo thỏa thuận, quà cảm ơn lần này sẽ được Sứ Giả Linh Giới gửi thẳng tới Hòm Thư, vui lòng kiểm tra.\n      Nếu vẫn muốn để lại ý kiến bằng thân phận hiện tại, bạn có thể tiếp tục gửi suy nghĩ qua lối bí ẩn trong thư; chúng tôi luôn hoan nghênh góp ý.\n<HyperLink stylename=\"M_Link\" u=\"web=%s\">Khảo Sát Open Beta 5</>\n      Cảm ơn bạn đã chứng kiến hành trình này; nguyện Linh Tính dẫn đường.",
    [664107976055296] = "<M_Orange>[%s]</> đã tuyên chiến với CLB của bạn và đang chờ phản hồi. Hãy trong <M_Orange>1 giờ</> tới <HyperLink stylename=\"M_Link\" u=\"jump=1302473\">【Tuyên Chiến CLB】</> để đưa ra phán quyết — quá hạn không phản hồi sẽ bị xem là tự động nhận thua, <M_Orange>đồng thời bị trừ Quỹ CLB tương ứng</>.\nCó thể nhấn <HyperLink stylename=\"M_Link\" u=\"tipsId=6427619\">【Hướng Dẫn Tuyên Chiến CLB】</> để xem hướng dẫn!",
    [664107976062208] = "Phi Phàm Giả thân mến:\nHệ thống phát hiện phiên đấu giá bạn tham gia gần đây trong Phó Bản %s có dấu hiệu giao dịch ngoài game hoặc chuyển Soli (đạo cụ <M_Link>%s</>, tổng giá trị giao dịch <M_Link>%s</>). Để bảo vệ quyền lợi của bạn, vui lòng không tham gia giao dịch ngoài game. Nếu tiếp tục xuất hiện hành vi tương tự, tài khoản sẽ chịu xử phạt thêm (bao gồm nhưng không giới hạn: đóng băng tiền tệ, khóa đấu giá Phó Bản, v.v.).",
    [664107976062720] = "Kính gửi Phi Phàm Giả:\nHệ thống phát hiện giao dịch gần đây của bạn có dấu hiệu giao dịch ngoài luồng hoặc chuyển Suli (vật phẩm <M_Link>%s</>, tổng giá trị giao dịch <M_Link>%s</>) và không vượt kiểm duyệt. Sàn Giao Dịch đã bị khóa tới %s, đồng thời đóng băng %s Suli. Bạn có thể nộp tiền bảo chứng %s Bảng Vàng tại giao diện Sàn Giao Dịch để mở đóng băng sớm. Nếu có thắc mắc, vui lòng vào Trung Tâm Người Dùng - Liên Hệ CSKH để phản hồi chi tiết.",
    [664107976062976] = "Kính gửi Phi Phàm Giả:\nHệ thống phát hiện phiên đấu giá bạn tham gia gần đây trong Phó Bản %s có dấu hiệu giao dịch ngoài luồng hoặc chuyển Suli (vật phẩm <M_Link>%s</>, tổng giá trị giao dịch <M_Link>%s</>) và không vượt kiểm duyệt. Suli của đơn này đã bị khấu trừ vĩnh viễn. Nếu có thắc mắc, vui lòng vào Trung Tâm Người Dùng - Liên Hệ CSKH để phản hồi chi tiết.",
    [664107976063232] = "Phi Phàm Giả thân mến:\nHệ thống phát hiện phiên đấu giá bạn tham gia gần đây trong Phó Bản %s có dấu hiệu giao dịch ngoài game hoặc chuyển Soli (đạo cụ <M_Link>%s</>, tổng giá trị giao dịch <M_Link>%s</>) và không vượt qua kiểm duyệt. Đấu giá Phó Bản hiện đã bị khóa đến %s. Bạn có thể nộp tiền bảo chứng %s Bảng Vàng trong giao diện Đấu Giá Phó Bản để mở khóa sớm. Nếu có thắc mắc, hãy vào Trung Tâm Người Dùng - Liên Hệ CSKH để phản hồi chi tiết.",
