    [695031203654912] = "Kho Vũ Khí",
    [695033351120384] = "Quảng Trường Trung Tâm",
    [695033619555584] = "Một Kẻ Gác Đêm đang thu thập Linh Tính tràn; có thể dùng Vật Dị Tượng thu thập được để đổi thưởng.",
    [695033619578880] = "Vật nhiễm Linh Tính rải rác khắp nơi do sự kiện Phi Phàm địa phương.\nThu thập rồi tới một Kẻ Gác Đêm trong CLB để đổi thưởng.",
    [695033619580672] = "Sau khi khóa mục tiêu, thiết lập kết nối và cuối cùng tiếp quản ý thức, biến nó thành Bí Ngẫu. Đơn vị bị bạn khống chế sẽ nghe theo mệnh lệnh.",
    [695033619585536] = "Một Rương Báu bị sức mạnh quỷ dị xâm thực đang chờ được thanh tẩy. Hoàn thành nghi thức, xua tan ô nhiễm và xem bên trong cất giấu thứ gì.",
    [695510897788416] = "Nhiệm Vụ",
    [695510897788928] = "Thám Bí",
    [712484608542720] = "Túi",
    [730076526173184] = "Chia Sẻ",
    [730076526173440] = "Kênh Thế Giới",
    [730076526173952] = "Kênh Lân Cận",
    [743274692217344] = "Thoát Trói",
    [743274692217856] = "Quán Chú Linh Tính",
    [743274692219136] = "Ám Sát",
    [752067564449280] = "Khu Vực Chiến Đấu",
    [752090918076928] = "Riel Bieber, hậu duệ Gia Tộc Antigonus. Hắn tình cờ có được một cuốn bút ký của gia tộc và bị sức mạnh thần bí trong đó xâm thực. Trong trạng thái nửa tỉnh táo, hắn đã tự tay kết liễu mẹ mình. Ô nhiễm từ cuốn bút ký ngày càng nghiêm trọng, cuối cùng hắn hoàn toàn Mất Kiểm Soát và biến thành quái vật.\n“Mẹ……”",
    [765264924772355] = "Có thể trực tiếp ảnh hưởng mục tiêu, chữa trị sự Cuồng Loạn và các vấn đề khác của đối phương, hoặc khiến đối phương Cuồng Loạn, mất Lý Trí.",
    [774126247609856] = "Kỹ Năng",
    [774126247610880] = "Trang Bị",
    [774126516045312] = "Kỹ Năng & Thiên Phú",
