    [862028122315521] = "Đối Quyết bắt đầu! Dùng kỹ năng mới nhận 【Đối Quyết Kỵ Binh】!",
    [862028122383617] = "Ở đây còn dấu vết Linh Tính. Vật Phong Ấn bị Giáo Hội thất lạc hẳn vẫn còn ở đây!",
    [866622663296512] = "Ám Thành",
    [866622663296768] = "Thế Giới Trật Tự",
    [866762786605056] = "Hằng Ngày",
    [870883807726080] = "Xóa Bạn",
    [870883807727104] = "Xin Vào Đội",
    [879890085710336] = "Klein hoàn thành thuận lợi nhiệm vụ ủy thác đầu tiên, cùng Leonard giải cứu bé Elliott bị bắt cóc. Nhưng ngay trong giấc mơ đêm đó, Klein nhận được cảnh báo Linh Tính: căn phòng đối diện vụ bắt cóc đang che giấu manh mối liên quan tới Bút Ký. Ngày hôm sau, Kẻ Gác Đêm tiến vào căn phòng đối diện điều tra và bất ngờ phát hiện người mẹ đã chết của Riel Bieber.",
    [879891427887617] = "Trọng Kích",
