    [906479691369728] = "Sát Thương Cao Nhất",
    [906479691369984] = "Trị Liệu Cao Nhất",
    [914795016495619] = "Thử Thách",
    [914865883449344] = "<Highlight>Trong thời gian kích hoạt</>, hạ <HyperLink stylename=\"Clickable\" u=\"\">Tiên Phong Tai Dị</> được triệu hồi. | Đánh bại Tiên Phong Tai Dị: <Highlight>%d</>/1",
    [914865883449600] = "Dùng máu chứng minh thực lực, hạ mọi mục tiêu thù địch.\nTích lũy Điểm Thắng Xếp Hạng: <Green>%s</>/<Highlight>200</>",
    [919197089545729] = "Áp Chế",
    [919197089551873] = "Chống Đỡ",
