    [999182265485569] = "Tím",
    [999182265485570] = "Vàng",
    [999182265485571] = "Cam",
    [999182265485572] = "Đỏ",
    [1002757020452352] = "<Highlight>Quyền Bính Theo Bậc:</> Thần Thánh, Ánh Sáng, Trật Tự  <Highlight>Năng Lực Cốt Lõi</>: Làm chủ Thánh Hỏa và Ánh Sáng Trật Tự của lĩnh vực Mặt Trời, lập nên những khế ước thần thánh không thể vi phạm, thanh tẩy mọi tà ác và ô nhiễm. Là hóa thân của ánh sáng, khắc tinh vĩnh hằng của tà ác, nhân danh Mặt Trời phán quyết mọi bất công trên thế gian.",
    [1002757020452608] = "<Highlight>Quyền Bính Theo Bậc:</> Không Tưởng, Tâm Linh, Động Sát  <Highlight>Năng Lực Cốt Lõi:</> Thống trị đảo tâm linh và biển tiềm thức tập thể, xâm nhập lĩnh vực tinh thần của mọi sinh linh. Quyền bính cốt lõi 「Không Tưởng」— điều được tưởng tượng có thể hóa thành hiện thực: dệt mộng, cấy Ám Thị, trấn an và chữa lành. Là kẻ thống trị thế giới tâm linh, người phán xét tinh thần, đồng thời có thể khiến những điều Không Tưởng hư ảo giáng xuống thế giới chân thực.",
    [1002757020452864] = "<Highlight>Quyền Bính Theo Bậc:</> Kỳ Tích, Quỷ Bí, Ngu Lộng, Lịch Sử  <Highlight>Năng Lực Cốt Lõi:</> Ngu lộng vận mệnh, thời gian và lịch sử; truy ngược quá khứ trong sương mù lịch sử, dòm ngó tương lai. Làm chủ những biến hóa Quỷ Bí, du hành nơi sâu thẳm Linh Giới, tạo ra kỳ tích giữa tuyệt cảnh. Là kẻ đùa cợt vận mệnh, kẻ ngu lộng thời gian; dùng sức mạnh Quỷ Bí đánh lừa quy tắc hiện thực, tạo nên khả năng giữa điều bất khả.",
    [1002757020453376] = "<Highlight>Quyền Bính Theo Bậc:</> Cánh Cửa, Không Gian, Phong Ấn  <Highlight>Năng Lực Cốt Lõi:</> Làm chủ khái niệm 「Cánh Cửa」 và quy luật không gian, bỏ qua giới hạn khoảng cách, mở khe nứt thông tới bất kỳ nơi nào. Du hành Tinh Giới và Linh Giới, phong ấn và ngăn cách vạn vật. Nơi nào có khe hở đều có thể đi qua; là kẻ gấp xếp không gian, lữ khách của thế giới, đồng thời làm chủ phong ấn và trục xuất.",
    [1002757020453632] = "<Highlight>Quyền Bính Theo Bậc:</> Hoàng Hôn, Chiến Đấu  <Highlight>Năng Lực Cốt Lõi:</> Mang sức mạnh chung kết của lĩnh vực Hoàng Hôn, làm chủ sức mạnh kinh hoàng và sinh mệnh bền bỉ. Dùng thể phách như người khổng lồ cùng ý chí sắt thép nghiền nát chướng ngại, càng chiến càng mạnh. Hoàng Hôn tượng trưng cho sự suy tàn của vạn vật và dòng chảy thời gian; là kẻ làm chủ sức mạnh, hóa thân của Hoàng Hôn, tiến tới thời khắc đình trệ vĩnh hằng.",
    [1002757020453888] = "<Highlight>Quyền Bính Theo Bậc:</> Thông Tin, Tri Thức  <Highlight>Năng Lực Cốt Lõi:</> Dòm ngó chân tướng thần bí học phía sau thế giới, phân tích những quy luật bí ẩn vận hành vạn vật, nhìn vào những bí mật bị che giấu. Có thể ẩn mình trong sương mù tri thức, nhưng bản thân tri thức cũng là lời nguyền—biết càng nhiều, càng gần điên loạn. Là người thám hiểm miền chưa biết, kẻ bảo hộ tri thức bí ẩn, cũng là người gánh lấy cái giá của nó.",
    [1002825739948288] = "Hoàng Đế Tri Thức",
