    [1002826813688320] = "Đã thăng tiến thành Học Giả Cách Đấu.",
    [1002826813688576] = "Đã thăng tiến thành Vu Sư.",
    [1002826813688832] = "Đã thăng tiến thành Giáo Sư Quyển Trục.",
    [1002826813689088] = "Đã thăng tiến thành Chiêm Tinh Sư.",
    [1002826813689344] = "Đã thăng tiến thành Thần Bí Học Gia.",
    [1002826813689600] = "Đã thăng tiến thành Đại Sư Tiên Tri.",
    [1002826813689856] = "Đã thăng tiến thành Hiền Giả.",
    [1002826813690112] = "Đã thăng tiến thành Hoàng Đế Tri Thức.",
    [1002826813690368] = "Đã thăng tiến thành Ẩn Giả.",
    [1002827350542080] = "Dùng tiếng ca du dương ca tụng Mặt Trời, truyền dũng khí và sức mạnh cho đồng đội, xua tan sợ hãi cùng u ám, khơi dậy lòng thành kính và ý phục tùng, để giai điệu ấm áp vang vọng trên chiến trường.",
    [1002827350542336] = "Thông qua nghi thức thần thánh để giao cảm với Mặt Trời, thành kính cầu xin ánh sáng giáng xuống, chế tạo Nước Thánh thanh tẩy; dùng quang minh xua tan bóng tối và tử linh, ôm lấy nắng ấm, gìn giữ ngọn lửa hy vọng.",
    [1002827350542592] = "Thể chất cường kiện, có sức đề kháng cực mạnh với bệnh tật và môi trường khắc nghiệt; nắm giữ thần thuật thuộc lĩnh vực Mặt Trời, triệu hồi Thánh Quang thanh tẩy tà uế, là người kiên định bảo hộ ánh sáng ấm áp.",
    [1002827350542848] = "Thể chất được tăng cường mạnh, nắm giữ sức mạnh Công Chứng để phân biệt thật giả của khế ước, ban ánh sáng thần thánh cho điều có hiệu lực và khiến kẻ vi ước trả giá nặng nề; là người bảo vệ trật tự thương mại.",
    [1002827350543104] = "Nắm giữ ánh sáng thần thánh và sức mạnh Mặt Trời, thanh tẩy tà uế và tử linh trên phạm vi lớn. Khi bóng tối giáng xuống, hóa thân thành người phát ngôn của ánh sáng, nhân danh Mặt Trời phán xét tà ác và xua tan mọi bóng đen.",
    [1002827350543360] = "Có thể đọc những thông tin bí ẩn từ ánh nắng, sở hữu trực giác nhạy bén với bóng tối và dị thường. Nơi bước chân đi qua, bóng tối lui tán, chân tướng bị che giấu không còn chỗ ẩn mình.",
    [1002827350543616] = "Xác lập chuẩn tắc chính nghĩa trong lòng, lập khế ước thần thánh với bản thân, thần linh và thế giới; nhân danh trật tự dẫn dắt quang minh, phán xét tà ác thế gian và dựng nên trật tự chính nghĩa phù hợp Con Đường Mặt Trời.",
    [1002827350543872] = "Bước đầu nắm giữ quyền bính Mặt Trời và Ánh Sáng; có thể hóa thành ánh sáng bay xuyên trời cao, cũng có thể phân tán thành quang mang rồi tái cấu trúc cơ thể sau khi chịu thương tổn, truy đuổi quỹ tích ánh sáng và trở thành hóa thân cùng sứ giả của quang minh.",
    [1002827350544128] = "Dần gánh vác quyền bính Thần Thánh và Trật Tự, rải quang huy thuần khiết để thanh tẩy vạn vật, khiến sinh linh tắm trong ánh sáng tinh khiết và xua tan mọi ô uế, bóng tối; là biểu hiện hoàn mỹ của thần tính Mặt Trời.",
    [1002827350544384] = "Ánh sáng còn, ta còn; soi sáng vạn vật, phá hủy bóng tối, lập khế ước thần thánh không thể trái nghịch, khiến mọi điều bất hài đều bị thanh tẩy và xua tan, mang đến hy vọng cùng trật tự vĩnh hằng.",
    [1002827350544896] = "Sở hữu tinh thần nổi trội và khả năng quan sát nhạy bén, như một khán giả đứng ngoài nhìn những “diễn viên” của xã hội thế tục; từ biểu cảm, cử chỉ mà nhìn thấu suy nghĩ thật, khéo léo tác động và âm thầm dẫn dắt sự việc theo hướng mong muốn.",
    [1002827350545152] = "Khả năng quan sát đi sâu vào Khí Trường, Thể Ether và các lĩnh vực thần bí khác, có thể nắm bắt lòng người với độ chính xác bất thường, gần như đọc được ý nghĩ đối phương. Trước mặt Độc Tâm Giả, rất khó che giấu bí mật.",
    [1002827350545408] = "Còn gọi là Nhà Phân Tích Tâm Lý, có thể chữa trị hoặc gây Cuồng Loạn; thông qua “Chấn Nhiếp”, “Ám Thị”, “An Phủ” để trực tiếp ảnh hưởng mục tiêu, nắm bắt cảm xúc và suy nghĩ chân thực nhất.",
    [1002827350545664] = "Thể chất tăng mạnh, sức mạnh và nhanh nhẹn vượt người thường. Có thể mở cánh cửa “Tâm Trí Thể” của mục tiêu để sửa đổi ý thức; trong chiến đấu cưỡng ép thôi miên kẻ địch, khiến chúng thực hiện hành vi bất thường.",
    [1002827350545920] = "Có thể dẫn dắt và sửa đổi giấc mơ, âm thầm ảnh hưởng mục tiêu theo thời gian. Có thể hư hóa cơ thể để ẩn vào giấc mơ và nhảy giữa các giấc mơ, nhờ đó thực hiện dịch chuyển tức thời theo nghĩa vật lý.",
    [1002827350546176] = "Sở hữu sức mạnh cực lớn, phòng ngự Long Lân kinh người và tốc độ cực nhanh. Có thể đưa Tâm Trí Thể vào Đảo Tâm Linh của người khác, trực tiếp sửa đổi Tiềm Thức và âm thầm điều khiển mục tiêu.",
    [1002827350546432] = "Có thể dệt giấc mơ rồi kéo mục tiêu vào trong, đồng thời kiểm soát chính xác tâm lý bản thân khiến kẻ địch khó phán đoán. Có thể tách thân phận thành một con người chân thực, nắm sâu “ẩn thân tâm lý” và “bão ôn dịch”.",
    [1002827350546688] = "Năng lực Ám Thị tâm lý đạt biến đổi về chất, gần tới cấp độ quyền bính: tin rằng bản thân mạnh thì sẽ thực sự mạnh. Có thể nhìn thấu lỗ hổng tâm linh, nhân quả vận mệnh và tạo ra “Mê Cung Giấc Mơ”.",
    [1002827350546944] = "Cổ xưng “Tác Gia Đồng Thoại”, nắm giữ một phần quyền bính “Không Tưởng”. Có thể tạm thời kéo khái niệm vào hiện thực; câu chuyện được viết ra sẽ trở thành hiện thực, đồng thời sở hữu đặc tính “phàm có lời, ắt bị biết”.",
    [1002827350547200] = "Vật được tưởng tượng nhất định sẽ cụ hiện, quốc độ được huyễn tưởng nhất định sẽ giáng lâm, tương lai được tuyên bố nhất định sẽ diễn ra. Nắm giữ hoàn chỉnh quyền bính “Không Tưởng”, khiến hư ảo và hiện thực đan xen.",
    [1002827350547712] = "Bước đầu có khả năng giao tiếp với Linh Giới, Linh Cảm tăng lên; nắm giữ Chiêm Tinh, Bài, Con Lắc và các năng lực Bói Toán khác. Có thể “nhìn” thấy vật bị che khuất, “nghe” thấy tiếng bước chân rất khẽ, nhưng thiếu thủ đoạn đối địch trực tiếp.",
    [1002827350547968] = "Khả năng kiểm soát cơ thể xuất sắc, có thể tạo những biểu cảm khoa trương và động tác hài hước. Cơ thể như tờ giấy trắng, có thể biến hóa; nắm giữ Người Giấy Thế Thân, Hỏa Diễm Khiêu Dược và nhiều năng lực khác, ung dung thoát hiểm.",
    [1002827350548224] = "Động tác nhanh nhẹn, Linh Tính mạnh, nắm giữ Chuyển Dời Thương Tổn, Hỏa Diễm Khiêu Dược, Người Giấy Thế Thân, Đạn Khí và nhiều trò ảo thuật. Khiến người khác cảm thấy không thể tin nổi mới là chân lý nghề nghiệp; sáng tạo kỳ tích giữa tuyệt cảnh.",
    [1002827350548480] = "Năng lực Bói Toán và cận chiến tăng mạnh, khả năng quan sát và mô phỏng rất cao, có thể biến thành diện mạo của bất kỳ ai. Nhưng qua vô số lần biến hóa, rất dễ đánh mất bản thân và quên đi khuôn mặt vốn có.",
    [1002827350548736] = "Có thể nhìn thấy Sợi Tơ Linh Thể và thao túng chúng để trực tiếp ảnh hưởng, khống chế mục tiêu, biến mục tiêu thành Bí Ngẫu. Một Bí Ngẫu Sư khiến người ta khiếp sợ, đứng sau màn điều khiển tất cả.",
    [1002827350548992] = "Năng lực Dây Linh Thể mạnh hơn, sở hữu nhiều Bí Ngẫu hơn. Kết hợp với năng lực ảo thuật khó tin của bản thân, có thể khiến người khác rơi vào một vở kịch quỷ bí khó lường; là tồn tại đứng trên đỉnh cao của Ảo Thuật Gia.",
    [1002827350549248] = "Có thể mượn sức mạnh từ chính mình trong quá khứ và triệu hồi hình chiếu từ khe hở lịch sử. Đối với Học Giả Cổ Đại, thứ từng sở hữu sẽ không thực sự mất đi; lịch sử chính là kho báu vô tận.",
    [1002827350549504] = "Quyền bính “Lịch Sử” được đào sâu, khả năng vận dụng sương mù lịch sử tiến thêm một bước. Sở hữu năng lực “Nguyện Vọng”, là biểu hiện của một phần quyền bính “Kỳ Tích”, tạo nên điều có thể giữa bất khả.",
    [1002827350549760] = "Thiên Sứ phụng sự Quỷ Bí, bước đầu nắm giữ quyền bính trong lĩnh vực tương ứng. Linh thể và thân xác không còn ranh giới rõ ràng, vừa thống nhất vừa phân tán, ở trạng thái cực kỳ vi diệu và khó bị khóa định.",
    [1002827350550016] = "Là hóa thân của quyền bính tương ứng, bao hàm một phần quyền bính về Lịch Sử, Thời Gian, Vận Mệnh, Biến Hóa và Bí Ẩn; đồng thời là biểu tượng của “Mù Quáng Ngu Muội” trong lĩnh vực tâm linh. Giỏi ngu lộng vạn vật và phô bày thần tích khó tin.",
    [1002827350553344] = "Bước đầu nắm giữ năng lực “Mở Cửa”, có thể xuyên tường, lấy vật từ xa và định vị. Rất khó bị giam giữ; có thể mở lối đi không thuộc hiện thực để thoát khỏi khốn cảnh, gần như không thể bị ngăn cách.",
    [1002827350553600] = "Nắm giữ đủ loại pháp thuật kỳ quái nhưng không quá mạnh như Tia Chớp, Hắc Mạc, Đóng Băng, Điện Kích, Tạo Sương, Gọi Gió, Châm Lửa, Thuật Vấp Ngã... thiên về biểu diễn trò ảo thuật hơn là đánh bại kẻ địch.",
    [1002827350553856] = "Có Linh Tính trực giác và dự cảm nguy hiểm khá mạnh, có thể hỏi Linh Tính để Bói Toán, đồng thời có năng lực quấy nhiễu Bói Toán; nhìn thấu quỹ tích vận mệnh và dự báo cát hung họa phúc.",
    [1002827350554112] = "Có được năng lực “Ghi Chép”: lấy tinh thần làm bút, linh thể làm giấy để tái hiện Năng Lực Phi Phàm mà mục tiêu đã sử dụng; điều khiển tế bào hoạt hóa tạo thành ký hiệu, hoa văn để lưu trữ — “Ta đến, ta thấy, ta ghi chép”.",
    [1002827350554368] = "Có thể liên tục dịch chuyển chớp quanh mục tiêu; kết hợp nhiều năng lực “Ghi Chép” cùng sự cảnh giác rời đi ngay khi thấy không ổn, sở hữu năng lực chiến đấu và cơ động mạnh, đến không bóng đi không hình.",
    [1002827350554624] = "Sở hữu năng lực “Giữ Bí Mật” để che chắn cảm ứng, có thể ẩn giấu không gian, dùng Cánh Cửa Hư Ảo trục xuất mục tiêu, dịch chuyển chớp và sử dụng nhiều Năng Lực Phi Phàm liên quan tới Cánh Cửa, Không Gian; thao túng pháp tắc không gian.",
    [1002827350554880] = "Không bị Linh Giới trói buộc, có thể tiến vào tinh không, du hành Tinh Giới và tới những tinh cầu khác nhau, tự do xuyên qua vũ trụ, khám phá những ngân hà và thế giới chưa biết.",
    [1002827350555136] = "Có thể chuyển hóa bản thân thành ký hiệu tượng trưng, lợi dụng Tinh Giới để tới các tinh cầu và thế giới khác nhau, tự do du hành giữa các chiều không gian; là hành giả xuyên qua các giới.",
    [1002827350555392] = "Nắm giữ quyền bính “Định Vị”, bản thân vĩnh viễn không lạc mất vị trí còn kẻ địch không thể định vị; là chìa khóa mở mọi Phong Ấn, cũng là ổ khóa đóng mọi cánh cửa.",
    [1002827350555648] = "Có thể mở hoặc đóng mọi sự vật liên quan tới khái niệm “Cánh Cửa”, khiến Phong Ấn bị phá bỏ hoặc được gia cường trong một khoảng thời gian; nắm giữ hoàn chỉnh quyền bính Không Gian và Phong Ấn.",
    [1002827350556160] = "Cổ xưng “Chiến Sĩ Phi Phàm”, sở hữu sức mạnh và độ nhanh nhẹn vượt xa người thường; tinh thông đủ loại vũ khí, phòng cụ và thuật cận chiến, không có vũ khí nào không dùng được hay lưu phái chiến đấu nào không thể nắm giữ.",
    [1002827350556416] = "Cổ xưng “Giác Đấu Sĩ”, là chuyên gia cận chiến; có thể dùng thân thể làm suy yếu ảnh hưởng của một số sức mạnh siêu tự nhiên, cận chiến gần như không ai sánh bằng, thuần túy dựa vào thể chất để giảm hiệu quả Năng Lực Phi Phàm.",
    [1002827350556672] = "Sở hữu sức mạnh, thể chất và nhanh nhẹn cực cao; chỉ cần là vũ khí đều có thể sử dụng ở trình độ bậc thầy, gồm cả Vũ Khí Phi Phàm và Vật Phẩm Thần Kỳ, đồng thời giảm hiệu quả sát thương do tác dụng phụ gây ra.",
    [1002827350556928] = "Sở hữu sức mạnh như Cự Nhân, có thể triệu hồi Thần Hi Bình Minh trong sạch bao phủ xung quanh, phá ảo giác, xua oán hồn, ngưng tụ Kiếm Bình Minh và Giáp Bình Minh, thi triển Bão Ánh Sáng phá hủy tà ác.",
    [1002827350557184] = "Có thể gây Sát Thương lên mọi loại quái vật và không bị Ảo Giác mê hoặc. Quỳ một gối có thể dựng bức tường vô hình kiên cố để gánh Sát Thương cho đồng đội; nếu chưa đạt Bậc Cao thì rất khó phá vỡ phòng thủ.",
    [1002827350557440] = "Còn gọi là “Thợ Săn Ma”, có sức mạnh khoa trương và tinh thần ở giữa Thần với người. Có thể chế tạo dược tề ứng phó tình huống phức tạp, che giấu hành động và quấy nhiễu Bói Toán; là khắc tinh của Ác Ma và quái vật.",
    [1002827350557696] = "Sức mạnh Thủ Hộ hóa thành bộ giáp bạc toàn thân kiên cố, hoa lệ nhưng không có trọng lượng, có thể chống đỡ công kích mạnh; là cực hạn của con đường Thủ Hộ, trên chiến trường như một bức tường không thể vượt qua.",
    [1002827350557952] = "Thiên Sứ Bậc 2 giỏi chiến đấu chính diện nhất, nắm quyền năng giản hóa của “Hoàng Hôn”, “Chiến Đấu” và “Thần Thánh”; là biểu tượng vinh quang của Con Đường Chiến Sĩ, uy năng kinh thiên động địa.",
    [1002827350558208] = "Có thể nắm giữ quyền bính “Đại Hành” giản hóa, trong thời gian ngắn và có tiết chế thay mặt Thần Minh hoặc Cựu Nhật mà mình phụng sự để thể hiện uy năng, giáng Thần Phạt và thay Thần thi hành ý chí.",
    [1002827350558464] = "Có thể khiến vật chất, ý chí thậm chí hư không suy bại, sụp đổ và tiêu vong, tỏa ra khí tức Hoàng Hôn khiến vạn vật suy tàn; chỉ riêng sự tồn tại của bản thân cũng khiến sự vật xung quanh bắt đầu mục rữa.",
    [1002827350558976] = "Nắm giữ Ma Pháp, Vu Thuật, Chiêm Tinh và nhiều Tri Thức Thần Bí, hiểu không ít Nghi Thức Ma Pháp. Sở hữu “Khuy Bí Nhãn”, có thể thấy những thứ vốn không nên thấy, vì vậy phải luôn kính sợ sức mạnh Phi Phàm.",
    [1002827350559232] = "Truy tìm bí mật sau sự vật, mà cận chiến cũng là một loại sự vật. Nắm giữ nhiều lưu phái kỹ thuật cận chiến, thể chất tăng lên, có thể dựa vào thân thể làm suy yếu ảnh hưởng của một số sức mạnh siêu tự nhiên.",
    [1002827350559488] = "Có khả năng dùng trí óc và tri thức để phân tích, nghiên cứu, học hỏi thậm chí sáng tạo pháp thuật; có thể dùng nhiều pháp thuật như Chiếu Minh Thuật, Trừ Tà Thuật, Thiểm Điện Thuật... tri thức càng toàn diện thì càng mạnh.",
    [1002827350559744] = "Có thể chế tạo cuộn phép; đọc chú ngữ khiến cuộn cháy và giải phóng năng lực bên trong, tiết kiệm đáng kể thời gian niệm phép và tăng năng lực chiến đấu của Phù Thủy. Làm chủ các pháp thuật cuộn như Đóng Băng, Chớp Sáng...",
    [1002827350560000] = "Bước đầu nắm giữ Tri Thức Thần Bí về tinh tượng, chòm sao và tinh thần; có thể sử dụng Cự Trụ Tinh Tú, Xuyên Hành Tinh Hải, Lao Lung Tinh Quang cùng nhiều năng lực khác, nhìn thấu bản chất của nhiều sự vật Phi Phàm.",
    [1002827350560256] = "Bậc đại sư hàng đầu về thần bí học, năng lực cốt lõi là “Tái Hiện Thần Bí”: rút sức mạnh từ tri thức thần bí học đã nắm giữ để tạo ra ma pháp; tri thức càng ít người biết, pháp thuật càng mạnh.",
    [1002827350560512] = "Thực sự chạm tới quyền bính “Khuy Bí”, có thể dòm ngó bí mật, tri thức và vận mệnh bị che giấu. Có thể tiên đoán hậu quả của lựa chọn và nhìn thấy tương lai, nhưng càng liên quan tồn tại cấp cao thì phản phệ càng lớn.",
    [1002827350560768] = "Năng lực cốt lõi là làm chủ và vận dụng thông tin: có thể hư hóa cơ thể thành sinh vật dòng thông tin, cũng có thể tái cấu trúc thân thể. Có thể tạo thông tin giả để đánh lừa quy tắc, đồng thời cụ hiện tri thức thành đòn tấn công.",
    [1002827350561024] = "Có thể trao sức mạnh thực chất cho tri thức trừu tượng, đưa sức mạnh được ban cho tri thức vào Dòng Thông Tin để có được năng lực của Bậc khác. Có thể lợi dụng thông tin Linh Giới, ảnh hưởng Thất Quang và dòm ngó bí mật của Chư Thần.",
    [1002827350561280] = "Sở hữu quyền bính liên quan tới Ẩn Nặc, có thể che giấu thông tin bản thân khiến Thần Linh khác không thể truy tung, định vị. Nắm giữ quyền bính “Tri Thức Thần Bí”, có thể ban sức mạnh cho con số và khiến thế giới quy về hư vô.",
    [1002827618977280] = "Bạn vẫn là thân phàm tục nhưng ẩn chứa vô hạn khả năng, chưa nhìn thấy cánh cửa Phi Phàm.",
    [1002827618977536] = "Bạn đã bước lên Con Đường Phi Phàm, có được Đặc Tính ban đầu. Sức mạnh tuy nhỏ bé nhưng đã vượt qua người thường.",
    [1002827618977792] = "Điểm Phi Phàm của bạn bắt đầu ổn định thành hình; bạn học cách dùng năng lực ứng phó nguy hiểm, cũng học cách cùng rủi ro khiêu vũ.",
    [1002827618978048] = "Bạn đã có thể linh hoạt vận dụng sức mạnh tương ứng với Bậc, bước đầu sở hữu thủ đoạn tự bảo vệ và chế địch khi đối mặt sự kiện Phi Phàm.",
    [1002827618978304] = "Năng lực của bạn đã lộ ra mũi nhọn riêng, Phi Phàm ăn sâu vào huyết nhục, bắt đầu từ “người có năng lực” tiến gần tới “siêu phàm giả”.",
    [1002827618978560] = "Bạn đã nhìn thấy diện mạo thực sự của Con Đường; cái giá của sức mạnh và lý trí cùng tồn tại, bạn đã trở thành một thực thể có thể ảnh hưởng cục diện.",
    [1002827618978816] = "Bạn nắm giữ “bản chất” của siêu phàm giả, năng lực đã hoàn chỉnh và bắt đầu chạm tới rìa của quy tắc thần bí.",
    [1002827618979072] = "Bạn đã trở thành ranh giới giữa phàm tục và thần bí; tư duy, cảm nhận và sức mạnh đều đang thoát khỏi phạm trù con người.",
    [1002827618979328] = "Sự tồn tại của bạn đang tiến gần tới “khái niệm”; năng lực đã chạm tới Nhân Quả, Vận Mệnh hoặc Pháp Tắc, vật phàm khó lòng lý giải.",
    [1002827618979584] = "Bạn gần như chính là biểu tượng của Con Đường; mỗi hành động đều lay động cấu trúc nền tảng của thế giới, sở hữu quyền năng Bán Thần.",
    [1002827618979840] = "Bạn đã thành Thần; lấy Con Đường làm danh, lấy quyền năng làm thân, chi phối pháp tắc thần tính của một lĩnh vực.",
