    [1003168263601152] = "Trong PvP, <Highlight>hạ gục</> %s/%s Thần Quan Mặt Trời.",
    [1003168263601920] = "Đánh bại Phu Nhân Tử Tước độ khó Khó, nhặt <Highlight>Đặc Tính Phi Phàm Ô Nhiễm</> (%s/%s)",
    [1003168263602176] = "Hoàn thành Câu Chuyện Nhập Vai: <Highlight>Điều Tri Thức Nhập Vai</> (%s/%s).",
    [1003168263602432] = "Dùng kỹ năng <Highlight>Nghi Thức Khuy Bí</> %s/%s lần.",
    [1003168263602944] = "Trong PvP, <Highlight>hạ gục</> %s/%s Vu Sư.",
    [1003168263603712] = "Đánh bại Tín Đồ Số Một độ khó Khó, nhặt <Highlight>Sách Cổ Tích</> (%s/%s).",
    [1003168263603968] = "Hoàn thành Câu Chuyện Nhập Vai: <Highlight>Sáu Con Bồ Câu</> (%s/%s).",
    [1003168263604224] = "Dùng kỹ năng <Highlight>Hạ Màn Buổi Diễn</> %s/%s lần.",
    [1003168263604736] = "Trong PvP, <Highlight>hạ gục</> %s/%s Ảo Thuật Gia.",
    [1003168263605504] = "Đánh bại Thủ Hộ Hậu Duệ độ khó Khó, nhặt <Highlight>Mảnh Đặc Tính Phi Phàm</> (%s/%s).",
    [1003168263605760] = "Hoàn thành Câu Chuyện Nhập Vai: <Highlight>Vũ Khí Tốt Nhất</> (%s/%s).",
    [1003168263606016] = "Dùng kỹ năng <Highlight>Bậc Thầy Kiếm Thuật</> %s/%s lần.",
    [1003168263606528] = "Trong PvP, <Highlight>hạ gục</> %s/%s Bậc Thầy Vũ Khí.",
    [1003168263607296] = "Đánh bại Giáp Tổ Tiên độ khó Khó, nhặt <Highlight>Vũ Khí Tàn Phá</> (%s/%s).",
    [1003168263607552] = "Hoàn thành Câu Chuyện Nhập Vai: <Highlight>Đêm Nay Ngủ Ngon</> (%s/%s).",
    [1003168263607808] = "Dùng kỹ năng <Highlight>An Ủi Tâm Linh</> %s/%s lần.",
    [1003168263608320] = "Trong PvP, <Highlight>hỗ trợ hạ gục</> %s/%s Bác Sĩ Tâm Lý.",
    [1003168263609088] = "Đánh bại Chó Săn Dị Hóa độ khó Khó, nhặt <Highlight>Vuốt Chó Săn</> (%s/%s).",
    [1003237519918592] = "Chất lỏng đỏ thẫm không ngừng cuộn trào.",
    [1003237519918848] = "Dung nham trắng rực.",
    [1003237519919104] = "Sắc vàng óng, tự mang nhiệt độ nóng bỏng.",
    [1003237519919360] = "Sắc vàng sẫm lưu chuyển, trong veo và óng ánh, như có thể soi thấu lòng người.",
    [1003237519921152] = "Chất lỏng bạc trắng sền sệt.",
    [1003237519921408] = "Chất lỏng có ánh sáng không ngừng biến đổi, dường như có thể soi tới tận đáy lòng mỗi người.",
    [1003237519921664] = "Chất lỏng hơi ánh vàng khẽ lay động, tựa một con ngươi khổng lồ đang biến hình.",
    [1003237519921920] = "Chất lỏng sền sệt trong suốt không màu; khi tĩnh lặng có thể phản chiếu trọn vẹn mọi vật trong phạm vi.",
    [1003237519923712] = "Chất lỏng xanh lam đậm sền sệt.",
    [1003237519923968] = "Nhuộm ba màu vàng kim, vàng và đỏ, đan xen nhau nhưng trong sạch lạ thường.",
    [1003237519924224] = "Như có pháo hoa nở rộ bên trong, các sắc đỏ, cam, vàng, lục... không ngừng tỏa ra ngoài.",
    [1003237519924480] = "Toàn thân đen lục, thỉnh thoảng nổi lên một bọt khí lớn bằng con mắt.",
    [1003237519928832] = "Đen sẫm, sền sệt, trông như loại thảo dược truyền thống nhất.",
    [1003237519929088] = "Chất lỏng rực rỡ đa sắc, tựa nấm độc.",
    [1003237519929344] = "Trong veo tinh khiết, gần như đã đông đặc.",
    [1003237519931392] = "Chất lỏng màu máu với mùi tanh nồng.",
    [1003237519931648] = "Mủ trắng tinh vương những sợi vết máu.",
    [1003237519931904] = "Chất lỏng đen có gỉ sắt nổi chìm.",
    [1003237519932160] = "Chất lỏng trong suốt như được Thần Hi chiếu sáng.",
    [1003237519933952] = "Chất lỏng chuyển sắc, càng gần tâm càng sâu thẳm và u ám.",
    [1003237519934208] = "Chất lỏng xám như ẩn chứa cuồng phong sóng dữ.",
    [1003237519934464] = "Mủ xanh lục đậm có những sợi bông xám trôi nổi.",
    [1003237519934720] = "Chất lỏng tím nhạt mang cảm giác gỗ mục rữa.",
    [1003306239395328] = "Đừng tiếc lời khen ngợi người khác, đặc biệt hãy khích lệ những đồng đội bên cạnh.",
    [1003306239395584] = "Khi người khác cần giúp đỡ, nhất định phải hào phóng đưa tay tương trợ.",
    [1003306239395840] = "Tiếng ca phải phục vụ tín ngưỡng và mục tiêu, tuyệt đối không được rỗng tuếch, phù phiếm.",
    [1003306239396096] = "Khi ca tụng phải tập trung tinh thần, tránh bị người nghe tác động ngược.",
    [1003306239396352] = "Giữ tâm linh thành kính và khiêm nhường, không để kiêu ngạo xâm thực.",
    [1003306239396608] = "Trước khi truyền đi quang huy, phải thanh tẩy tư tưởng của chính mình.",
    [1003306239396864] = "Dù rơi vào bóng tối, vẫn phải trông chờ hy vọng của Thần Hi.",
    [1003306239397120] = "Ánh sáng vừa là vũ khí vừa là phán xét, không được biến thành công cụ của tư dục.",
    [1003306239397376] = "Dùng quang huy của bản thân soi sáng người khác, mang đến cho họ sự ấm áp.",
    [1003306239397632] = "Không sợ bóng tối bao phủ; nơi đặt chân tới nhất định phải có quang huy tỏa sáng.",
    [1003306239397888] = "Khi thanh tẩy người và vật bị bóng tối xâm nhiễu, phải giữ lòng thương xót.",
    [1003306239398144] = "Khi giao tiếp với tín đồ, nhất định phải chân thành và ấm áp.",
    [1003306239398400] = "Khán Giả cuối cùng vẫn chỉ là Khán Giả, không được để cảm xúc chi phối.",
    [1003306239398656] = "Thông qua quan sát mục tiêu, nhìn thấu và nắm bắt suy nghĩ chân thực của đối phương.",
    [1003306239398912] = "Dùng manh mối dẫn dắt hành vi, khiến sự việc phát triển theo dự tính.",
    [1003306239399168] = "Những gì nhìn thấy không phải toàn bộ; bình tĩnh phân tích mới là then chốt.",
    [1003306239399424] = "Dẫn dắt không được đột ngột, cũng không được đánh mất nguyên tắc.",
    [1003306239399680] = "Chỉ khi mọi chi tiết đều mềm mại và hợp lý, sự dẫn dắt mới không để lại dấu vết.",
    [1003306239399936] = "Đọc hiểu điều mục tiêu khao khát, thấu hiểu dục cầu chân thực nhất của đối phương.",
    [1003306239400192] = "Duy trì phòng hộ tâm niệm, tránh bị phản phệ tinh thần.",
    [1003306239400448] = "Giúp người khác chữa lành tổn thương trong tâm linh.",
    [1003306239400704] = "Lắng nghe họ giãi bày phiền não, dẫn dắt họ chiến thắng trạng thái tinh thần tiêu cực.",
    [1003306239400960] = "Dám vận dụng kỹ xảo, trở thành một bác sĩ tâm lý thực thụ.",
    [1003306239401216] = "Giữ bình tĩnh và chuyên nghiệp, tránh thiên lệch do cảm xúc.",
    [1003306239401472] = "Giải đọc khải thị và dẫn dắt người khác tiến về hướng tốt đẹp.",
    [1003306239401728] = "Giữ lòng kính sợ và thận trọng trước Vận Mệnh.",
    [1003306239401984] = "Bói Toán không phải vạn năng, nó chỉ có thể đưa ra một phương hướng và khải thị nhất định.",
    [1003306239402240] = "Không được tự mãn, không được mù quáng tin vào cách giải Bói Toán của bản thân.",
    [1003306239402496] = "Dùng mặt nạ che giấu ý đồ thực sự của bản thân.",
    [1003306239402752] = "Giữa trêu đùa và bỡn cợt, vẫn phải nắm quyền kiểm soát cục diện.",
    [1003306239403008] = "Có thể dự kiến đôi chút Vận Mệnh, nhưng vẫn cảm thấy bất lực trước Vận Mệnh.",
    [1003306239403264] = "Dùng khuôn mặt tươi cười che giấu mọi buồn đau, thống khổ, mê mang và chán nản.",
    [1003306239403520] = "Chủ động biểu diễn nhiều hơn, không thực hiện màn diễn nào khi chưa chuẩn bị.",
    [1003306239403776] = "Trong lúc biểu diễn, phải nắm giữ sự chú ý của mục tiêu.",
    [1003306239404032] = "Cố gắng giành lấy tiếng vỗ tay và tán thưởng của khán giả.",
    [1003306239404288] = "Thách thức điều bất khả thi, cho dù kết quả cuối cùng chỉ là giả tạo.",
    [1003306239407616] = "Theo thầy học nghề, làm một Học Đồ trung thành.",
    [1003306239407872] = "Giữ lòng hiếu kỳ khi khám phá Tri Thức Phi Phàm.",
    [1003306239408128] = "Tri thức có được không được tùy ý truyền ra ngoài.",
    [1003306239408384] = "Với lòng khiêm nhường, tiếp nhận lời chỉ dạy của tiền bối.",
    [1003306239408640] = "Dùng trò ảo thuật hoa lệ che giấu thực lực, qua đó đùa bỡn đối thủ.",
    [1003306239408896] = "Trò ảo thuật phải được dùng đúng thời cơ mới phát huy tác dụng.",
    [1003306239409152] = "Mỗi trò ảo thuật đều phải luyện tập trước, thuần thục tới mức hoàn mỹ.",
    [1003306239409408] = "Tận hưởng màn biểu diễn của chính mình, để khán giả cảm nhận được niềm vui của bạn.",
    [1003306239409664] = "Đọc tinh tượng để quan sát Vận Mệnh của bản thân và người khác tốt hơn.",
    [1003306239409920] = "Khi quan sát tinh tượng, phải giữ yên tĩnh và tập trung.",
    [1003306239410176] = "Giải đọc tinh tượng phải thận trọng, tránh dẫn dắt sai lệch.",
    [1003306239410432] = "Chiêm Tinh chỉ là công cụ, không phải phương pháp giải quyết vấn đề.",
    [1003306239410688] = "Học và tinh thông càng nhiều kỹ thuật của các lưu phái cận chiến càng tốt.",
    [1003306239410944] = "Giữ bình tĩnh, tuyệt đối không để cơn giận làm mất phán đoán chiến thuật.",
    [1003306239411200] = "Trên chiến trường tuyệt đối không dễ dàng rút lui, dũng cảm đối mặt đối thủ.",
    [1003306239411456] = "Tôn trọng mọi cường giả và đối thủ.",
    [1003306239411712] = "Không ngừng rèn luyện, tôi luyện thể phách vượt khỏi người thường.",
    [1003306239411968] = "Khi đối mặt cường địch, vẫn phải giữ quyết tâm tất thắng.",
    [1003306239412224] = "Chiêu thức phải dung hợp thân thể và tâm linh, đạt tới cảnh giới hài hòa.",
    [1003306239412480] = "Trở thành chuyên gia trong lĩnh vực cận chiến, dung hội quán thông các kỹ thuật chiến đấu.",
    [1003306239412736] = "Rèn thân tâm hợp nhất với vũ khí, có kiến giải độc đáo về vũ khí.",
    [1003306239412992] = "Không ngừng nâng cao bản thân, tinh thông mọi loại vũ khí mình nắm giữ.",
    [1003306239413248] = "Xem vũ khí là người bạn đồng hành đáng tin cậy nhất.",
    [1003306239413504] = "Trong chiến đấu hợp nhất với vũ khí, khiến công thủ tự nhiên như hô hấp.",
    [1003306239413760] = "Tùy tâm sở dục, nhưng tuyệt đối không được mang lòng gây hại.",
    [1003306239414016] = "Kẻ nhìn chăm vào bí mật cũng sẽ bị bí mật nhìn chăm lại.",
    [1003306239414272] = "Lắng nghe lời thì thầm của thế giới, đồng thời giữ tâm cảnh trầm mặc.",
    [1003306239414528] = "Biết quá nhiều chưa chắc là trí tuệ; khi cần phải biết từ bỏ một phần chân tướng.",
    [1003306239414784] = "Thân thể tuy là vũ khí, đầu óc mới là cò súng thực sự.",
    [1003306239415040] = "Bạo lực có thể là một trong những phương pháp của lý tính.",
    [1003306239415296] = "Hãy kiểm soát sức mạnh của mình, đừng để sức mạnh kiểm soát bạn.",
    [1003306239415552] = "Không nhân danh học thuật mà thực hiện sát lục.",
    [1003306239415808] = "Phải làm chủ pháp thuật, tuyệt đối không để pháp thuật khống chế ngược bản thân.",
    [1003306239416064] = "Thi triển pháp thuật không phải không có bất kỳ cái giá nào.",
    [1003306239416320] = "Ma Pháp phải tuân theo con đường Nghi Thức, không được vượt giới hạn.",
    [1003306239416576] = "Pháp thuật như lời thì thầm không tiếng, còn ký hiệu là vật chứa sức mạnh.",
