    [1046736680280576] = "Cự Long Chiến Tranh",
    [1046736948692480] = "Phạm tội cướp bóc Chợ Đen Tingen, mưu toan Thăng Bậc thông qua nghi thức.",
    [1046736948692736] = "Ngẫu nhiên ôn lại một Sự Kiện Blackthorn đã được lưu hồ sơ.",
    [1046736948692992] = "Kẻ Dòm Ngó Bí Ẩn mất kiểm soát; sự chấp niệm điên cuồng với tri thức đã biến hắn thành một quái vật đáng sợ.",
    [1046736948693248] = "Một nhà tư bản tà ác không ngừng bóc lột tầng lớp dưới; trong cám dỗ truy đuổi lợi ích và tiền bạc, cuối cùng hắn phát điên và mất kiểm soát.",
    [1046736948693504] = "Phi Phàm Giả mất kiểm soát thuộc Bậc “Kẻ Bị Trói Buộc”; hắn mưu toan triệu hồi đại quân vong linh để phá hủy Tingen.",
    [1046736948693760] = "Một người đàn ông gầy nhưng cường tráng, tóc cắt rất ngắn, từng sợi dựng đứng như gai nhọn. Móng tay đen dài như dao găm, trên người mọc đầy lông đen cứng và dài.",
    [1046736948694016] = "Gương mặt tái nhợt với vài vết đen mờ, như dấu tích còn lại sau khi vết thương thối rữa lành lại. Ác ý trong mắt hoàn toàn không che giấu hay kìm nén; hắn giống một xác sống khát thịt tươi hơn là con người.",
    [1046736948694272] = "Áo đuôi tôm đen, áo choàng đỏ sẫm, tóc vuốt ngược bằng dầu, ánh mắt xanh âm u; gương mặt tái nhợt của một người khoảng bốn mươi tuổi.",
    [1046736948694528] = "Phó Bản Chính Tuyến: Hồ Tingen.",
    [1046736948694784] = "Phó Bản Chính Tuyến: Amon.",
    [1046736948695040] = "Là hậu duệ gia tộc Antigonus, hắn không được hưởng vinh quang mà dòng họ từng mang lại, trái lại vì thân phận hậu duệ mà nhiễm phải vận rủi khó lòng chống lại.",
    [1046736948695296] = "Vụ nổ do Ray Bieber tử vong khiến các Kẻ Gác Đêm bị thương và hôn mê. Hề Áo Đuôi Tôm quay lại, dùng Ma Dược Hề làm mồi nhử, ép Klein giao ra Bút Ký Antigonus.",
    [1046736948695552] = "Phó Bản Chính Tuyến: Mặt Trăng Nguyên Thủy.",
    [1046736948695808] = "Đội Kẻ Gác Đêm dùng Vật Phong Ấn 2-049 để tìm đặc tính của hậu duệ Antigonus, rồi lái xe truy tìm tung tích Ray Bieber.",
    [1046736948697344] = "Sức mạnh âm tính đến từ tinh không, đủ để đồng hóa và nuốt chửng mọi sinh mệnh yếu ớt. Hãy nhìn những gương mặt đáng ghét ấy chìm vào nỗi sợ vô tận.",
    [1046736948697600] = "Sau trận chiến dữ dội với đám tay sai, kẻ giật dây phía sau cuối cùng lộ diện — là nó! Chính là nó! Những tay sai ngã xuống méo mó lặp đi lặp lại hai chữ “Mẹ”.",
    [1046736948697856] = "Kẻ Báng Bổ tạm hoàn tất tu hành và trở về từ bên ngoài thời gian lẫn không gian xa xôi vô tận. Có lẽ đây là điềm báo cho một đại họa khác?",
    [1046736948698112] = "Việc đầu tiên học viên làm khi đến Học Phái Tarot là tới phòng họp diện kiến cô Audrey, “Chức Mộng Nhân”. Có lẽ vị tài trợ kinh phí hoạt động này sẽ không tiếc cho học viên một khoản sinh hoạt phí?",
    [1046736948698368] = "“Vô Ám Giả” Derrick đúng như tên gọi, nhiệt tình rực lửa như mặt trời. Anh nóng lòng muốn giao lưu thân thiện với học viên và giúp họ nâng cao khả năng tự bảo vệ trong thời loạn.",
    [1046736948698624] = "Merlin và Hugh đang chờ học viên tại phòng huấn luyện. Dày dạn chiến trận và kinh nghiệm, họ sẽ mở bài học nhập môn đầu tiên tại đây — thực chiến.",
    [1046736948698880] = "Whitebox test của phó bản leo tháp, tạm dùng sân Đấu Trường 3v3; kích thước vừa đủ phù hợp.",
    [1046736948699648] = "Hề Áo Đuôi Tôm đột nhiên xuất hiện cướp Bút Ký Gia Tộc Antigonus. Khi hắn sắp thoát đi, Dunn kéo cả đội Kẻ Gác Đêm vào giấc mơ của tên hề...",
    [1046736948699904] = "Một Kẻ Mất Kiểm Soát lang thang trên hoang dã Vùng Đất Bị Thần Bỏ Rơi; cơn đói của hắn cứ tăng mãi, cũng như sự điên cuồng...",
    [1046736948700160] = "Phân thân này giống hệt bản thể, luôn thích ma thuật lừa gạt và trò thao túng thời gian. Nếu không nhìn thấu những trò ấy, e rằng bạn sẽ vĩnh viễn không thể rời đi...",
    [1046736948700416] = "Một tồn tại Bậc Cao cực kỳ nguy hiểm. Đối mặt Ma Lang tám chân đã sống hàng nghìn năm, nếu không có Vật Phong Ấn đặc biệt hỗ trợ, e rằng không thể trực diện chống lại hắn...",
    [1046736948700672] = "Khoảnh khắc họ âm mưu phản bội đã quanh quẩn trong Đại Sảnh Hoa Hồng suốt nghìn năm, không sao tan biến; vận mệnh dưới sự thao túng của Ouroboros cứ lặp lại hết lần này đến lần khác.",
    [1046736948700928] = "Thợ Săn của Vương Đình năm xưa đã trói linh hồn mình với tượng sống trong cung điện Cự Nhân Vương; đến nay vẫn trung thành canh giữ trước cửa.",
    [1046736948701184] = "Ám Thiên Sứ bị phản bội sẽ không ngủ say mãi. Khi mạo hiểm giả tiến tới nơi sâu nhất của Vương Đình, ác ý và điên cuồng từ nghìn năm trước lại thức tỉnh...",
    [1046736948702208] = "BOSS 1 Trang Viên Tháng Năm",
    [1046736948702464] = "BOSS 2 Trang Viên Tháng Năm",
    [1046736948702720] = "BOSS 3 Trang Viên Tháng Năm",
