    [1046804594480896] = "Liệp Khuyển Vồ Giết",
    [1046804594481152] = "Xé Rách Linh Hồn",
    [1046805399733760] = "Trong lúc hộ tống sẽ xuất hiện <Disable>kẻ địch cầm dao găm ngắn</>.",
    [1046805399734016] = "Trên đường hộ tống sẽ xuất hiện <Disable>Quái Tự Nổ</>; mục tiêu của chúng <Disable>chỉ là Xe Ngựa</>, đồng thời để lại <Disable>lửa cháy liên tục</> trên mặt đất.",
    [1046805399734272] = "Ray Bieber giải phóng 2-049, khiến người chơi xung quanh rơi vào <Disable>Trì Trệ trong 10 giây</>.",
    [1046805399734528] = "Riel Bieber sau khi <Disable>tụ lực 3 giây</> sẽ nhảy lên rồi lao xuống đất, gây <Disable>sát thương lớn</> cho người chơi xung quanh.",
    [1046805399734784] = "Ray Bieber chọn người chơi <Disable>gần nhất</> làm mục tiêu, tóm lấy rồi tiến hành Thôn Phệ.",
    [1046805399735040] = "Để kịp phát hiện đồng đội bị 2-049 khống chế, đội Kẻ Gác Đêm đồng loạt làm động tác co duỗi tay, tạo nên cảnh tượng cả đội nhảy múa gượng gạo rất sống động.",
    [1046805399735296] = "Hề dùng <Disable>Vòng Quay</> nhốt người chơi.",
    [1046805399735552] = "Người chơi chịu sát thương từ Người Sói sẽ bị cộng dồn <Disable>hiệu ứng Xé Rách</>.",
    [1046805399735808] = "Người Sói khóa mục tiêu một người chơi rồi xung phong, gây sát thương lên người chơi trên đường đi và <Disable>cộng dồn hiệu ứng Xé Rách</>.",
    [1046805399736064] = "Thâm Hồng Nguyệt Miện dâng lên, <Disable>Người Sói được cường hóa!</> Người chơi có quá nhiều tầng Xé Rách sẽ <Disable>rơi vào Hỗn Loạn và tấn công đồng đội</>.",
    [1046805399736320] = "Xác Sống triệu hồi <Disable>tay sai</> xung quanh.",
    [1046805399736576] = "Hoạt Thi nháy tới giữa chiến trường và liên tục chỉ định <Disable>toàn bộ người chơi</>. Khi chỉ định kết thúc, <Disable>cột băng</> sẽ rơi từ trên đầu mỗi người chơi.",
    [1046805399736832] = "Oán Hồn dịch chuyển tới giữa sân rồi phóng <Disable>Bình Độc Tố</> trên phạm vi lớn ra bốn phía.",
    [1046805399737088] = "Sau khi hiệu ứng Bình Độc kết thúc, Oán Hồn nguyền rủa toàn bộ người chơi; vài giây sau <Disable>gây sát thương phạm vi.</>",
    [1046805399737344] = "Oán Hồn triệu hồi Quả Cầu Năng Lượng di chuyển về phía nó. Khi Oán Hồn hấp thụ bất kỳ Quả Cầu Năng Lượng nào, <Disable>lập tức gây sát thương cực lớn lên toàn bộ người chơi</>.",
    [1046805399737600] = "Người Hầu Mặt Trăng sẽ hai lần liên tiếp tung <Disable>Con Đường Kinh Cức</> sang trái và phải, gây đòn đánh mạnh lên người chơi.",
    [1046805399737856] = "Người Hầu Mặt Trăng có thể triệu hồi bụi hoa mang sức mạnh âm tính, khiến người chơi bên trong <Disable>rơi vào Ngủ Say</>.",
    [1046805399738112] = "Ý Chí Đỏ Thẫm tiến hành nghi thức bí ẩn, gây nhiều lần <Disable>đòn hủy diệt</> lên toàn sân.",
    [1046805399738368] = "Ánh sáng che chở từ tinh không xa xôi giáng xuống; trong phạm vi đó, Ý Chí Đỏ Thẫm <Disable>rất khó bị gây sát thương</>.",
    [1046805399738624] = "Phân Thân Amon cố chiếm lấy cơ thể người chơi, khiến người chơi <Disable>dần mất quyền kiểm soát</>.",
    [1046805399738880] = "Bản thể Phân Thân Amon rời khỏi chiến trường, hóa thành vô số phân thân Amon và <Disable>đồng loạt tấn công</> người chơi.",
    [1046805399739136] = "Tưởng tượng ra sức mạnh của Cự Long, gây <Disable>sát thương lớn</> cho người chơi trong phạm vi rộng.",
    [1046805399739392] = "Cự Long Tưởng Tượng tồn tại liên tục trên chiến trường, gây <Disable>sát thương liên tục</> lên người chơi.",
    [1046805399739648] = "Hút kẻ địch trong phạm vi cực lớn và đồng thời nhận <Disable>Buff Phòng Thủ</>.",
    [1046805399739904] = "Cưỡng ép hút kẻ địch trong vùng chữ nhật phía trước <Disable>về trước mặt</>, sau đó tung đòn chí mạng.",
    [1046805399740160] = "Triệu hồi một sân khấu biểu diễn Lá Bài Ma Thuật lớn tại vị trí chỉ định, <Disable>liên tục tấn công kẻ địch bên trong</>.",
    [1046805399740416] = "Di chuyển với tốc độ cao, hóa thành tàn ảnh và <Disable>liên tục tung đòn chí mạng</> lên kẻ địch.",
    [1046805399740672] = "Trong lúc hộ tống sẽ xuất hiện lẻ tẻ <Disable>kẻ địch Bang Săn Rồng</> tấn công xe ngựa.",
    [1046805399740928] = "Khi tới cửa kho sẽ gặp <Disable>một lượng lớn kẻ địch Bang Săn Rồng</>; chúng sẽ <Disable>cố phá hủy xe ngựa</>.",
    [1046805399741184] = "Khi xe ngựa ở trước cửa kho, bên rìa sân sẽ <Disable>định kỳ xuất hiện Quả Cầu Năng Lượng di chuyển về phía xe ngựa</>.",
    [1046805399741440] = "Ray Bieber sẽ <Disable>đột ngột nhắm một người chơi ngẫu nhiên rồi xung phong</>; nếu bị hắn đâm trúng, người chơi sẽ bị <Disable>ôm quật mạnh</>.",
    [1046805399741696] = "Riel Bieber bắt đầu đọc Bút Ký Gia Tộc Antigonus và <Disable>tạo cho bản thân lượng Khiên rất lớn; sau một khoảng thời gian</> sẽ gây lượng sát thương cực lớn lên toàn sân.",
    [1046805399741952] = "Riel Bieber <Disable>triệu hồi Thành Phố Đêm trong ký ức, nhốt người chơi và biến họ thành con rối</>, sau đó bắt đầu dùng kỹ năng <Disable>Khiên Mất Kiểm Soát</>.",
    [1046805399742208] = "Dưới chân toàn bộ người chơi xuất hiện <Disable>dải ma pháp hình chữ nhật di chuyển theo người chơi</>; sau một khoảng trễ ngắn, Năng Lượng Áo Thuật bùng nổ, gây sát thương lên mọi người chơi trong phạm vi.",
    [1046805399742464] = "Chú Hề Buồn mơ thấy <Disable>một Quả Bom Lớn, sẽ ngẫu nhiên khóa một người chơi</>; sau một khoảng thời gian bom nổ tại vị trí người đó, gây sát thương cực lớn nhưng có thể chia cho đồng đội trong phạm vi.",
    [1046805399742720] = "Hề Vui Vẻ mơ thấy <Disable>một Vòng Quay lớn, ngẫu nhiên gán chất bài cho người chơi</>. Sau một thời gian, ai không đứng trong vùng đúng chất bài trên Vòng Quay sẽ bị tên hề trừng phạt.",
    [1046805399742976] = "Tên hề trong mơ bắt đầu nghiên cứu Vật Phong Ấn 2-049 để đối phó người chơi. Các phân thân ảo ảnh xung quanh nạp năng lượng vào Khiên Vô Địch của hắn; <Disable>sau khi nghiên cứu xong</>, hắn sẽ hiểu nguyên lý 2-049, kích nổ phân thân và <Disable>biến toàn bộ người chơi thành con rối giống 2-049</>.",
    [1046805399743232] = "Gulu liên tục dùng đôi tay khổng lồ đập đất, gây nhiều đợt sát thương phạm vi <Disable>hình tròn hoặc vành khuyên ngẫu nhiên</> quanh thân.",
    [1046805399743488] = "Gulu khóa <Disable>hướng của mục tiêu Cừu Hận hiện tại</> và liên tục phun Dịch Dạ Dày, gây sát thương phạm vi lớn.",
    [1046805399743744] = "Gulu nhảy cao rồi rơi xuống đất, gây sát thương phạm vi tại điểm rơi và tạo <Disable>sóng chấn động mặt đất</> liên tục lan rộng, gây sát thương lên kẻ địch trúng phải.",
    [1046805399744000] = "Gulu liên tục giải phóng <Disable>Sương Độc</> tích trữ, gây nhiều đợt sát thương toàn sân; đồng thời Giá Trị Đói của bản thân tăng một lượng cố định.",
    [1046805399744256] = "Trên chiến trường liên tục xuất hiện <Disable>Ấu Thú Ô Uế</>; khi sinh ra chúng sẽ lang thang ngẫu nhiên. Sau khi đánh cạn Máu của Ấu Thú, người chơi có thể dùng kỹ năng <Disable>Đẩy</> để đẩy chúng về phía trước. Nếu bị đẩy tới dưới chân Gulu, Ấu Thú sẽ bị Gulu <Disable>nuốt</>; mỗi lần nuốt thành công làm giảm Độ Đói của Gulu.",
    [1046805399744512] = "Sau khi vào chiến đấu, <Disable>Giá Trị Đói</> của Gulu tăng dần theo thời gian, tối đa 100. Khi đạt <Disable>100</>, Gulu tung <Disable>Thôn Phệ Đói Khát</>, kéo ngẫu nhiên 3 người chơi tới trước mặt để nuốt chửng.",
    [1046805399744768] = "Phân thân Amon có thể thao túng sức mạnh thời gian, liên tục tạo vùng bóng tối trên sân; phân thân Amon <Disable>miễn nhiễm sát thương trong vùng bóng tối</>, còn người chơi ở trong vùng sẽ <Disable>chịu sát thương</>.",
    [1046805399745024] = "Phân Thân Amon triệu hồi nhiều Dòng Chảy Thời Gian bám theo và gây sát thương lên người chơi; cần <Disable>dẫn chúng vào vùng bóng tối</> mới có thể tiêu diệt.",
    [1046805399745280] = "Phân Thân Amon truyền Tri Thức Cấm Kỵ vào một số người chơi. Tri thức phát nổ trong <Disable>Vùng Bóng Tối</> sẽ đẩy kim đồng hồ tiến lên và tạo <Disable>Vùng Bóng Tối mới</>; nếu phát nổ trong <Disable>Vùng Không Bóng Tối</>, toàn bộ người chơi sẽ chịu <Disable>sát thương cực lớn</>.",
    [1046805399745536] = "Phân Thân Amon nhận Khiên và Ký Sinh lên hai người chơi, liên tục gây Sát Thương và Khống Chế. Người chơi chết khi đang bị Ký Sinh sẽ phát nổ, gây Sát Thương cực lớn lên toàn bộ người chơi. <Disable>Phá Khiên của Phân Thân Amon để giải Ký Sinh trên người chơi</>.",
    [1046805399745792] = "Phân Thân Amon triệu hồi 6 phân thân rồi hóa thành Quả Cầu Ánh Sáng luân chuyển giữa chúng. <Disable>Phân thân tại điểm dừng cuối của Quả Cầu Ánh Sáng</> chính là bản thể; <Disable>tìm và phá bản thể trong thời gian giới hạn</> sẽ khiến Phân Thân Amon rơi vào Suy Yếu. Nếu hết giờ mà bản thể vẫn sống, Phân Thân Amon sẽ tái xuất và <Disable>quét sạch toàn đội</>.",
    [1046805399746048] = "Phân Thân Amon triệu hồi 5 Xoáy Lịch Sử; cần <Disable>chuyển mục tiêu để hạ</>, nếu không sẽ gây <Disable>Sát Thương cực lớn lên toàn Raid</>. Xoáy trong vùng bóng tối nhận <Disable>Giảm Thương cực lớn</>, nên ưu tiên hạ Xoáy ngoài vùng bóng tối. Ngoài ra, trong thời gian kỹ năng, Phân Thân Amon sẽ hai lần đảo ngược thời không, <Disable>hoán đổi vùng bóng tối và vùng không bóng tối</>; cần nhanh chóng tới vùng không bóng tối mới để hạ Xoáy.",
    [1046805399746304] = "Ma Lang U Ám ẩn vào bóng tối và triệu hồi nhiều <Disable>Tượng Ma Lang</>. Bóng tối dần phủ chiến trường và nuốt chửng mọi người chơi bên trong; trong bóng tối, Ma Lang U Ám liên tục xung phong tấn công người chơi.",
    [1046805399746560] = "Ma Lang U Ám triệu hồi nhiều hàng <Disable>Bóng U Ám</> lang thang. Sau khi xuất hiện, <Disable>Bóng U Ám</> vào trạng thái <Disable>Tàng Hình</> và liên tục di chuyển về phía trước, gây Hất Tung và sát thương lên người chơi trên đường.",
    [1046805399746816] = "Ô Ám Ma Lang triệu hồi 2 <Disable>Quyến Tộc Ma Lang</>. Sau khi sinh ra, <Disable>Quyến Tộc Ma Lang</> vào trạng thái Ẩn Thân, liên tục di chuyển dọc rìa sân và định kỳ gây sát thương toàn sân ngày càng cao. Trong thời gian <Disable>Quyến Tộc Ma Lang</> tồn tại, chúng bảo vệ <Disable>Ô Ám Ma Lang</>, khiến nó ở trạng thái Vô Địch.",
    [1046805399747072] = "Ma Lang U Ám kéo Dây Linh Thể của toàn bộ người chơi và kéo họ về bên mình. Dây Linh Thể bị nhiễu sẽ nối từng cặp người chơi với nhau, liên tục gây sát thương cho đối phương.",
    [1046805399747328] = "Ma Lang U Ám cầu nguyện cho chính mình, gây <Disable>Ám Quang</> lên toàn bộ người chơi. Ám Quang liên tục gây sát thương và dần cướp đi ánh sáng của họ.",
    [1046805399747584] = "Văn bản mô tả lối chơi thông thường <Disable>văn bản trọng điểm</> văn bản mô tả lối chơi thông thường.",
    [1046805399747840] = "Vận mệnh của Medici và Aucuses bị liên kết. Nếu người chơi không thể hạ cả hai cùng lúc, sức mạnh hồi tưởng của Ouroboros sẽ khiến họ <Disable>hồi sinh hết lần này đến lần khác</>.",
    [1046805399748096] = "Ouroboros đồng thời ngẫu nhiên gán một hiệu ứng Vận Mệnh cho toàn bộ người chơi, Medici và Aucuses trên sân: <Disable>Thuận Lợi</> hoặc <Disable>Thất Bại</>. Nếu người chơi tấn công mục tiêu có hiệu ứng Vận Mệnh giống mình, sẽ chịu lượng <Disable>Sát Thương Phản Lại</> cực lớn.",
    [1046805399748352] = "Ouroboros phát động sức mạnh, tiêu diệt mọi kẻ địch <Disable>đang chịu hiệu ứng Vận Mệnh</>. Người chơi cần ghép thành từng cặp và tiếp xúc với người có <Disable>Vận Mệnh đối lập</> để xóa hiệu ứng Vận Mệnh.",
    [1046805399748608] = "Ouroboros dùng Vòng Xoáy Vận Mệnh triệu hồi Ghế Lưng Cao từ quá khứ, <Disable>cưỡng ép một người chơi ngồi lên và không thể cử động</>; đồng đội cần nhanh chóng phá Ghế Lưng Cao để cứu người.",
    [1046805399748864] = "Aucuses tập trung sức mạnh Liệt Dương, triệu hồi hai Pháp Trận trên sân để tích Quang Năng. Nếu để Pháp Trận tích đủ năng lượng, chúng sẽ <Disable>gây Sát Thương cực lớn lên toàn Raid</>; nếu có người đứng trong Pháp Trận ngăn tích năng lượng, <Disable>Sát Thương diệt đội sẽ bị giảm thành Sát Thương Chia Sẻ</>.",
    [1046805399749120] = "Medici triệu hồi các Binh Sĩ Quân Đoàn được mình ban phúc. Chúng <Disable>không chịu sát thương từ người chơi</>; cần <Disable>dẫn các Binh Sĩ Quân Đoàn va vào nhau</> để chúng tự tổn thương lẫn nhau.",
    [1046805399749376] = "Đòn phối hợp của Medici và Aucuses: Aucuses triệu hồi nhiều Hỏa Cầu Dương Viêm trên sân, <Disable>liên tục thiêu đốt mặt đất</>; Medici tụ lực phóng Trường Mâu vào người chơi, <Disable>xuyên qua kẻ địch trên đường</>. Người chơi cần <Disable>dẫn Trường Mâu bắn trúng Hỏa Cầu Dương Viêm</>.",
    [1046805399749632] = "Kỹ năng phối hợp của Medici và Aucuses: cả hai đồng thời nhảy vào giữa sân, phô bày uy thế Thiên Sứ và bắt đầu giằng co; các xung kích liên tục lan ra, hủy diệt mọi thứ. Người chơi có thể <Disable>Nhảy</> để né sát thương từ xung kích.",
    [1046805399749888] = "Trên chiến trường có sáu <Disable>Tượng Hộ Vệ</>, ban đầu ở trạng thái Vô Địch. Ở giai đoạn hai, khi Milgongen dùng Tứ Tượng Hộ Vệ, các tượng sẽ lần lượt mất Vô Địch. Mỗi tượng còn tồn tại giúp Milgongen nhận một mức <Disable>Khóa Máu</>; phải phá hủy toàn bộ tượng mới có thể hạ Milgongen.",
    [1046805399750144] = "Khi Tượng kích hoạt <Disable>trạng thái Laser</>, nó sẽ bắn <Disable>Tia Laser Cường Hóa</> về phía Milgongen. Khi tia chạm Milgongen, nó sẽ định kỳ thêm <Disable>hiệu ứng Cường Hóa</> cho Milgongen; người chơi có thể chặn tia Laser.",
    [1046805399750400] = "Khi Tượng kích hoạt <Disable>trạng thái Pháp Trận</>, quanh nó sẽ tạo một Trường Pháp Thuật; người chơi trong trường liên tục chịu sát thương phạm vi.",
    [1046805399750656] = "Khi Máu Mirgongen trên 75% sẽ ở <Disable>Giai Đoạn 1</>. Trong giai đoạn này tối đa 2 tượng cùng lúc vào trạng thái Laser; người chơi vừa phải xử lý cơ chế Mirgongen vừa phải chống đỡ <Disable>tia từ tượng</>.",
    [1046805399750912] = "Khi Máu của Milgongan dưới 75% sẽ vào <Disable>Giai Đoạn 2</>. Trong Giai Đoạn 2, Milgongan nhận hiệu ứng Giảm Thương thường trực; nhưng khi Milgongan bị <Disable>Phá Phòng</>, hiệu ứng Giảm Thương bị xóa và thời gian trạng thái Phá Phòng kéo dài hơn. Ở Giai Đoạn 2, trên sân có 2 tượng vào trạng thái Laser và 1 tượng vào trạng thái Ma Trận.",
    [1046805399751168] = "Ở giai đoạn 2, khi Máu Mirgongen giảm tới <Disable>55%, 35%, 15%</>, hắn dùng kỹ năng Tứ Tượng Thủ Hộ: sát thương phạm vi tròn xuất hiện ngẫu nhiên trên sân, đồng thời cả bốn tượng kích hoạt trạng thái laser. Hai tượng sẽ <Disable>mất bảo hộ Vô Địch</>; cần phá hủy chúng trong thời gian nhất định. Thành công sẽ đưa Mirgongen vào trạng thái Phá Phòng.",
    [1046805399751424] = "Sasrir dẫn dòng nước từ Biển Hỗn Độn, tạo 3 dòng sông đen trên chiến trường. <Disable>Các dòng sông định kỳ phun trào, hất tung toàn bộ người chơi phía trên</> và gây sát thương trung bình.",
    [1046805399751680] = "Sasrir đánh dấu nhiều người chơi; <Disable>sau 6 giây tạo một vũng nước đen hủ thực dưới chân người bị đánh dấu</>, liên tục gây Sát Thương và Giảm Tốc người đứng trên đó.",
    [1046805399751936] = "Sasrir triệu hồi nhiều phân thân truyền hai loại Năng Lượng Hỗn Độn đen/trắng về bản thể. <Disable>Mọi Năng Lượng Hỗn Độn chạm Sasrir đều cho hắn 1 tầng Cường Hóa</>. Sau một thời gian, Sasrir tung Cái Chết Của Kẻ Báng Bổ, gây sát thương toàn sân liên tục; mỗi tầng Cường Hóa Năng Lượng Hỗn Độn tăng 20% sát thương này.",
    [1046805399752192] = "Sasrir triệu hồi 2 Huyễn Ảnh Hiến Tế liên tục tiến về phía mình. <Disable>Mỗi Huyễn Ảnh chạm Sasrir sẽ gây sát thương lớn lên toàn chiến trường và cộng 1 tầng Thiêu Đốt Hiến Tế kéo dài 30 giây cho toàn bộ người chơi</>.",
    [1046805399752448] = "Sasrir ẩn mình rời chiến trường và điều khiển dòng nước hủy diệt của Biển Hỗn Độn hội tụ; <Disable>sau 30 giây chúng sẽ tràn qua chiến trường và hủy diệt mọi sinh vật</>.",
    [1046805399752704] = "Sasrir phóng <Disable>3 tia sát thương cao xếp cách nhau góc 120 độ</> rồi xoay trọn một vòng.",
    [1046805399752960] = "【Đang Thi Công】Mô tả gợi ý giai đoạn.",
    [1046805399753216] = "Trong chiến đấu, 2-049 liên tục ngẫu nhiên gây Trì Trệ lên đồng minh xung quanh, giảm Tốc Độ Di Chuyển và sau một khoảng thời gian <Disable>đồng hóa họ thành Con Rối</>.",
    [1046805399753472] = "Ray Bieber sẽ <Disable>triệu hồi 2-049</>. Xung quanh 2-049 hình thành Vùng Trì Trệ; ở trong vùng quá lâu sẽ rơi vào <Disable>Trì Trệ</>.",
    [1046805399753728] = "2-049 nhìn về <Disable>phía trước</>, liên tục xoay và nhắm mở mắt. Người chơi bị nhìn thấy khi 2-049 ở <Disable>trạng thái mở mắt</> sẽ bị <Disable>Choáng 5 giây</>.",
    [1046805399753984] = "Hề Vui Vẻ mơ thấy <Disable>một Vòng Quay lớn, ngẫu nhiên gán nhiều chất bài cho người chơi</>. Sau một thời gian, ai không đứng trong vùng đúng chất bài trên Vòng Quay sẽ bị trừng phạt. Cần chú ý, <Disable>Hề Khóc</> sẽ lừa người chơi!",
    [1046805399754240] = "Lambert trước tiên kéo người chơi về trước mặt, triệu hồi một <Disable>Lao Tù Băng</>, đồng thời tụ lực chuẩn bị một <Disable>đòn chí tử</>.",
    [1046805399754496] = "Trong Chế Độ Kẻ Gác Đêm, mỗi ngày sẽ mở các Sự Kiện Blackthorn khác nhau:",
    [1046805399754752] = "Thủ Hộ Hậu Duệ <Disable>khóa 2 người chơi</> rồi <Disable>lần lượt</> tung Trảm Kích Nhảy.",
    [1046805399755008] = "Khi Hộ Vệ Hậu Duệ dùng <Disable>tia nhìn Linh Tính màu tím khóa người chơi</>, nó tụ lực chém bằng đại kiếm, gây sát thương <Disable>phạm vi hình chữ nhật</>.",
    [1046805399755264] = "Nhà Chiêm Tinh dùng <Disable>Cấm Chế Tri Thức</> giam một người chơi và gây sát thương lan ra xung quanh. Nếu không <Disable>phá</> Cấm Chế trong thời gian giới hạn, người chơi đó sẽ <Disable>tử vong</>.",
    [1046805399755520] = "Nhà Chiêm Tinh triệu hồi 1 Phi Đạn phía sau <Disable>mỗi người chơi</>, gây Sát Thương lên nhân vật trên đường bay.",
    [1046805399755776] = "Nhà Thiên Văn triệu hồi Thiên Thạch; <Disable>mỗi người chơi</> sẽ hút một Thiên Thạch, khi rơi xuống sẽ gây sát thương nổ.",
    [1046805399756032] = "Sau khi vào <Disable>Giai Đoạn 2</>, Nhà Chiêm Tinh liên tục hút Vệ Binh Tinh Quang rơi xuống. Nếu Vệ Binh Tinh Quang ở <Disable>quá gần</> Nhà Chiêm Tinh, chúng tạo sát thương bức xạ phạm vi. Khi Vệ Binh Tinh Quang <Disable>chết</>, Tinh Quang Chi Lực phát nổ và <Disable>gây sát thương</> lên Nhà Chiêm Tinh.",
    [1046805399756288] = "Nhà Chiêm Tinh dùng <Disable>Cấm Chế Tri Thức</> giam hai người chơi. Nếu không <Disable>phá</> Cấm Chế trong thời gian giới hạn, người chơi đó sẽ <Disable>tử vong</>.",
    [1046805399756800] = "Nhà Thiên Văn cưỡng ép kéo tất cả người chơi về trước mặt rồi triệu hồi Thiên Thạch; <Disable>mỗi người chơi</> sẽ hút một Thiên Thạch, khi rơi xuống sẽ gây sát thương nổ.",
    [1046805399757056] = "Khi Máu Nhà Chiêm Tinh dưới 60%, bước vào <Disable>Giai Đoạn 2</>. Nhà Chiêm Tinh liên tục hút Vệ Binh Tinh Quang rơi xuống. Hạ Vệ Binh sẽ <Disable>rơi Tinh Quang</>; <Disable>chạm vào</> để tạm hấp thu Tinh Quang, trong thời gian này không thể dùng kỹ năng. Có thể vận chuyển tới Chân Nến Tinh Quang để <Disable>lưu giữ</>; hoàn tất vận chuyển nhận Tăng Sát Thương. Nếu trong <Disable>thời gian giới hạn</> Tinh Quang chưa được Chân Nến lưu giữ, nó sẽ <Disable>bị Nhà Chiêm Tinh hấp thu</> và tăng Sát Thương của Boss.",
    [1046805399757312] = "Chân Nến Tinh Quang có thể lưu trữ Tinh Quang. Sau khi hấp thụ Tinh Quang, người chơi <Disable>di chuyển tới</> gần Chân Nến để hoàn tất lưu trữ.",
    [1046805399757568] = "Khi Sinh Mệnh Nhà Chiêm Tinh giảm xuống <Disable>10%</>, nếu <Disable>chưa thu đủ 9</> Tinh Quang Chi Lực, sẽ không thể ngắt quá trình Nhà Chiêm Tinh hội tụ sức mạnh quần tinh; hoàn tất dẫn dắt sẽ gây sát thương cực lớn toàn sân. <Disable>Khi Cuồng Bạo</> không thể ngắt.",
    [1046805399757824] = "Khi Ngài Barney và Ancia <Disable>ở quá gần nhau</>, cả hai sẽ nhận <Disable>Tăng Sát Thương</>.",
    [1046805399758080] = "Khi Ngài Barney có mặt, Ancia nhận <Disable>Giảm Thương</>.",
    [1046805399758336] = "Ngài Barney sẽ lao tới người chơi <Disable>xa nhất</> so với mình.",
    [1046805399758592] = "Ancia triệu hồi Bướm Xanh; <Disable>Bướm Xanh</> liên tục gây sát thương xung quanh.",
    [1046805399758848] = "Ancia khóa người chơi bằng đường nối; khi đường nối tồn tại sẽ liên tục gây sát thương.",
    [1046805399759104] = "Anxia biến toàn bộ người chơi thành búp bê để chơi Người Gỗ. Người chơi phải di chuyển tới cạnh Anxia mới giải trừ biến thân. Trong thời gian đó, Anxia quay lưng đếm ngược; hết đếm sẽ quay lại nhìn người chơi và hóa đá những ai vẫn đang di chuyển. Sau vài vòng, nếu không ai tới được nơi, toàn sân sẽ chịu sát thương lớn.",
    [1046805399760128] = "Ngài Barney nhận Khiên; trước khi <Disable>Khiên</> bị phá, ông ta sẽ <Disable>liên tục di chuyển về phía Ancia</> và gây sát thương liên tục quanh mình khi di chuyển.",
    [1046805399760384] = "Anxia triệu hồi bướm: <Disable>Bướm Xanh</> liên tục gây Sát Thương xung quanh; <Disable>Bướm Vàng</> có thể hấp thụ. Sau khi hấp thụ, nhận buff <Disable>Sát Thương bản thân và Tốc Độ Di Chuyển</>, nhưng <Disable>Sát Thương nhận vào</> cũng tăng.",
    [1046805399760640] = "Anxia biến toàn bộ người chơi thành búp bê để chơi Người Gỗ. Người chơi phải di chuyển tới cạnh Anxia mới giải trừ biến thân. Trong thời gian đó, Anxia quay lưng đếm ngược và triệu hồi búp bê lao qua sân; hết đếm sẽ quay lại nhìn người chơi và hóa đá những ai vẫn đang di chuyển. Sau vài vòng, nếu không ai tới được nơi, toàn sân sẽ chịu sát thương lớn.",
    [1046805399760896] = "Chó Săn cuộn người, văng Hạt Quả Ký Sinh ra mọi hướng phủ toàn chiến trường. Các hạt sẽ <Disable>đồng loạt phát nổ sau một khoảng thời gian</>, gây sát thương cực lớn.",
    [1046805399761152] = "Liệp Khuyển lắc đuôi và liên tục <Disable>khóa chặt kẻ địch</>, sau đó quăng Bẫy Thú từ phía đuôi. Người chơi trúng phạm vi Bẫy Thú sẽ <Disable>không thể hành động và liên tục mất Máu theo phần trăm</>.",
    [1046805399761408] = "Chó Săn tích lực rồi phát <Disable>luồng gầm gây sát thương cực lớn</> ra toàn bộ chiến trường.",
    [1046805399761664] = "Liệp Khuyển phân tán sức mạnh, triệu hồi vài <Disable>Liệp Khuyển Đỏ Thẫm</> quanh chiến trường; sau một thời gian, chúng sẽ <Disable>liên tục xung phong vào người chơi</>.",
    [1046805399761920] = "Chó Săn liên tục ngắm 1 người chơi, sau đó nhảy lên không và lao xuống uy áp mục tiêu. <Disable>Sát Thương cú lao cực cao, có thể hạ gục tức thì</>, nhưng nhiều người chơi có thể <Disable>cùng chia sẻ để hóa giải</>.",
    [1046805399763456] = "Giáp Tổ Tiên đồng thời đánh dấu tối đa 2 người chơi, sau đó <Disable>lần lượt tung Ưng Dương Kích vào 2 người này</>. Sát thương rất cao nên cần <Disable>nhiều người cùng chia sát thương</>, nhưng người đã trúng Ưng Dương Kích trong thời gian ngắn không thể tiếp tục chịu lần thứ hai.",
    [1046805399763712] = "Giáp Tổ Tiên triệu hồi binh sĩ, liên tục xung phong ra bốn phía theo nhiều đội hình.",
    [1046805399763968] = "Khôi Giáp Tổ Tiên triệu hồi nhiều Thể Tinh Thần bị ô nhiễm trên sân. Sau khi được tấn công giải cứu, mỗi Thể Tinh Thần thả <Disable>2 Đặc Tính Thần Bí</>; người nhặt Đặc Tính Thần Bí sẽ <Disable>biến thành Kỵ Binh</> trong giai đoạn đối quyết tiếp theo.",
    [1046805399764224] = "Giáp Tổ Tiên tung <Disable>Ô Nhiễm Hủ Thực</> quanh sân, đồng thời liên tục triệu hồi Binh Sĩ Trường Kích từ mép sân xung phong vào trong; vùng Ô Nhiễm gây sát thương rất cao. Người chơi nhặt Đặc Tính Thần Bí lúc này sẽ <Disable>biến thành Kỵ Binh miễn nhiễm sát thương</>; tham gia hạ Binh Sĩ Trường Kích nhận <Disable>Chứng Nhận Vinh Quang</>, tối đa cấp 3. Sau một thời gian, Giáp Tổ Tiên thách đấu người giữ Chứng Nhận Vinh Quang; thua khiến toàn đội chịu trừng phạt và Giáp Tổ Tiên nhận Giảm Thương, thắng cho người chơi buff Tăng Thương.",
    [1046805399764480] = "Giáp Tổ Tiên triệu hồi nhiều Linh Thể chờ Hồi Sinh trên chiến trường. Có thể Trị Liệu để giải cứu Linh Thể; nếu giải cứu thất bại sẽ khiến Kỵ Sĩ Mất Khống Chế và Cuồng Bạo!",
    [1046805399765248] = "Khôi Giáp Tổ Tiên triệu hồi nhiều Thể Tinh Thần bị ô nhiễm trên sân. Sau khi được tấn công giải cứu, mỗi Thể Tinh Thần thả <Disable>1 Đặc Tính Thần Bí</>; người nhặt Đặc Tính Thần Bí sẽ <Disable>biến thành Kỵ Binh</> trong giai đoạn đối quyết tiếp theo.",
    [1046805399766016] = "Phu Nhân Tử Tước triệu hồi 2 <Disable>Chấp Niệm Quản Gia</> và 1 <Disable>Chấp Niệm Tiểu Tử Tước</>. Người chơi chạm Chấp Niệm Quản Gia sẽ bị trói và <Disable>liên tục mất Máu</>. Nếu không ai chạm Chấp Niệm hoặc Quản Gia chưa bị hạ, Phu Nhân Tử Tước sẽ nhận Buff Tăng Thương.",
    [1046805399766272] = "Phu Nhân Tử Tước mở <Disable>Cảnh Tối</>, khiến toàn bộ người chơi chìm vào bóng tối và liên tục chịu sát thương. Đồng thời, Phu Nhân Tử Tước thi triển kết liễu phạm vi lớn lên người chơi đang có Dấu Ấn Trung Thành và xóa 1 tầng Dấu Ấn Trung Thành. Nếu tổng số lần kết liễu của Phu Nhân Tử Tước <Disable>vượt quá 3 lần</> mà vẫn chưa xóa hết Dấu Ấn Trung Thành, bà ta sẽ mất kiên nhẫn và kết liễu toàn bộ người chơi. Trong bóng tối sẽ xuất hiện <Disable>chỉ dẫn của Tiểu Tử Tước</>; đi theo chỉ dẫn và tìm thấy Tiểu Tử Tước để giải trừ bóng tối.",
    [1046805399766528] = "Sau khi tụ lực một khoảng thời gian, Phu Nhân Tử Tước gây sát thương không thể né lên toàn chiến trường. Người chơi có thể tập hợp sức mạnh của Vòng Tay Cỏ Bốn Lá vỡ để ngăn Phán Quyết Tử Vong của Phu Nhân Tử Tước.",
    [1046805399766784] = "Phu Nhân Tử Tước chia sân thành 4 khu vực, mỗi khu có 3 tấm gương màu khác nhau. Sau mỗi khoảng thời gian, ngẫu nhiên 3 khu vực bị Ô Nhiễm bao phủ. Người chơi cần tìm <Disable>đúng tấm gương</> và dùng Xuyên Toa Linh Tính để tới khu an toàn. Đi vào sai gương sẽ nhiễm Ô Nhiễm Linh Tính và liên tục mất Máu.",
    [1046805399767040] = "Phu Nhân Tử Tước bắt đầu tụ lực, đồng thời Tiểu Tử Tước và các Tàn Niệm Quản Gia xuất hiện. Tiểu Tử Tước cố thuyết phục Phu Nhân từ bỏ chấp niệm nhưng bị các Tàn Niệm Quản Gia cản trở. Người chơi cần <Disable>tiêu diệt toàn bộ Tàn Niệm Quản Gia và hỗ trợ Tiểu Tử Tước</>, để cậu giúp chặn đòn tất sát của Phu Nhân.",
    [1046805399767296] = "Phu Nhân Tử Tước triệu hồi 1 <Disable>Chấp Niệm Quản Gia</> và 1 <Disable>Chấp Niệm Tiểu Tử Tước</>. Người chơi chạm Chấp Niệm Quản Gia sẽ bị trói và <Disable>liên tục mất Máu</>. Nếu không ai chạm Chấp Niệm hoặc Quản Gia chưa bị hạ, Phu Nhân Tử Tước sẽ nhận Buff Tăng Thương.",
    [1046805399767808] = "Cự Quy Ách Thủy dùng kỹ năng sát thương phạm vi 3 đoạn. Sau đoạn thứ 3, đồng thời xuất hiện 6 <Disable>Đạn Cầu Nước</> tấn công từng người chơi. Khi kỹ năng bắt đầu, Cự Quy triệu hồi trước mặt một <Disable>Nấm Độc liên tục lớn lên</>; khi lớn tới mức nhất định, Nấm Độc sẽ <Disable>tự nổ</>.",
    [1046805399768064] = "Cự Quy Ách Thủy lần lượt triệu hồi <Disable>nhiều đợt sóng</>; người chơi trúng sóng sẽ chịu sát thương lớn.",
    [1046805399768320] = "Rùa Khổng Lồ Ác Thủy ném mai ra rồi bắt đầu tụ lực, gây <Disable>Sát Thương toàn sân</>. Người chơi có thể nhặt mai và dùng nó chặn cú xung kích của Rùa Khổng Lồ.",
    [1046805399768576] = "Cự Quy Ách Thủy triệu hồi 3 <Disable>Vùng Độc Nấm</>. Sau một khoảng thời gian, nó đặt <Disable>Ấn Ký Ách Thủy</> lên 3 người chơi ngẫu nhiên; sau đó <Disable>Ách Thủy</> xuất hiện dưới chân họ. Tiếp đó, nó đặt <Disable>Ấn Ký Côi Bảo</> lên 3 người chơi ngẫu nhiên; sau đó <Disable>Côi Bảo</> xuất hiện dưới chân. Vùng Độc Nấm định kỳ gây sát thương <Disable>toàn chiến trường</>. Vùng Ách Thủy định kỳ sinh ra một <Disable>Bồ Nông Miệng Rộng hoặc Cá Heo Bong Bóng</> để tấn công người chơi.",
    [1046805399768832] = "Cự Quy Ách Thủy chọn <Disable>mục tiêu xa nhất</>, tụ lực ngắn rồi lao vào mục tiêu và khi kết thúc gây <Disable>sát thương lớn toàn sân</>. Nếu <Disable>đâm vào Côi Bảo</>, nó sẽ bị <Disable>đâm choáng</> và lần xung phong này bị ngắt.",
    [1046805399769088] = "Cự Quy Ách Thủy triệu hồi 1 <Disable>Vùng Độc Nấm</>. Sau một khoảng thời gian, nó đặt <Disable>Ấn Ký Ách Thủy</> lên 1 người chơi ngẫu nhiên; sau đó <Disable>Ách Thủy</> xuất hiện dưới chân. Tiếp đó, nó đặt <Disable>Ấn Ký Côi Bảo</> lên 1 người chơi ngẫu nhiên; sau đó <Disable>Côi Bảo</> xuất hiện dưới chân. Vùng Độc Nấm định kỳ gây sát thương <Disable>toàn chiến trường</>. Vùng Ách Thủy định kỳ sinh ra một <Disable>Bồ Nông Miệng Rộng hoặc Cá Heo Bong Bóng</> để tấn công người chơi.",
    [1046805399769344] = "Sylvia triệu hồi Tín Phong thổi qua mặt đất, gây sát thương trung bình lên kẻ địch trong vùng Tín Phong.",
    [1046805399769600] = "Sylvia triệu hồi Ý Chí Hoang Vu từ Cây Vàng, gây sát thương lớn lên kẻ địch trong vùng tròn hoặc vùng chữ nhật.",
    [1046805399769856] = "Sylvia phóng Tín Phong quy mô lớn, hất lùi hoặc hút người chơi trên chiến trường và gây sát thương.",
    [1046805399770112] = "Sylvia triệu hồi sức mạnh của Cuốn Sách Vàng, tạo thành Lưu Tinh oanh kích mặt đất.",
    [1046805399770368] = "Sylvia triệu hồi thực vật bị ô nhiễm. Nấm Hủ để lại vùng Ô Nhiễm tồn tại 120 giây trên mặt đất; Dây Khô khóa người chơi có Thù Hận cao nhất để tấn công.",
    [1046805399770624] = "Sylvia triệu hồi 6 <Disable>Dũng Sĩ Nấm</>. Sau một thời gian, Dũng Sĩ Nấm biến thành vùng Ô Nhiễm; khi vào vùng, cứ sau một khoảng thời gian nhận 1 tầng <Disable>Khô Mục</> và liên tục mất Sinh Mệnh theo Giới Hạn Sinh Mệnh.",
    [1046805399770880] = "Sylvia triệu hồi 6 <Disable>Dây Leo Phong Nhiêu</>, liên tục tấn công người chơi có Sinh Mệnh thấp nhất trong khu chiến đấu. Sau đó Sylvia triệu hồi vùng Ô Nhiễm ở vòng ngoài và dùng <Disable>Ân Tứ Phong Nhiêu</> đẩy người chơi vào vùng Ô Nhiễm.",
    [1046805399771136] = "Sylvia xoay 4 lần, mỗi lần gây sát thương lên mục tiêu trong vùng hình quạt 90° theo hướng hiện tại, bán kính 27m. Mỗi lần xoay sẽ chọn ngẫu nhiên 2 người chơi và áp <Disable>Thời Khắc Thu Hoạch</>. Khi hiệu ứng kết thúc, dựa theo hướng hiện tại của người bị chọn, gây sát thương lớn tỷ lệ theo Giới Hạn Sinh Mệnh lên <Disable>mục tiêu đồng minh</> trong vùng hình quạt 90°, bán kính 27m.",
    [1046805399771392] = "Sylvia sẽ chỉ định toàn bộ người chơi và gắn hiệu ứng Nguyền Rủa <Disable>Nấm Nở Rộ</>. Rời xa Sylvia để kéo đứt liên kết có thể xóa Nguyền Rủa; nếu không, tại vị trí hiện tại sẽ sinh <Disable>Nấm Nở Rộ</> và tung một đòn phạm vi giảm sát thương theo khoảng cách. Sylvia tạo vùng Khiên có hiệu quả bảo hộ khác nhau dựa trên số <Disable>Nấm Nở Rộ</> xuất hiện, sau đó dùng kỹ năng <Disable>Sinh Cơ Giáng Lâm</>.",
    [1046805399771648] = "Sylvia triệu hồi <Disable>Nấm Hoang Vu</> và làm ô nhiễm vùng di chuyển; dưới chân Sylvia sẽ ngẫu nhiên xuất hiện một vùng an toàn. Khi vào vùng Ô Nhiễm, cứ sau một khoảng thời gian nhận 1 tầng <Disable>Khô Mục</>; trong thời gian đó liên tục mất Sinh Mệnh theo Giới Hạn Sinh Mệnh.",
    [1046805399771904] = "Sylvia vào trạng thái Sụp Đổ và liên tục triệu hồi <Disable>Dây Leo Hoang Vu</> trong khu chiến đấu; người chơi tạm thời nhận kỹ năng <Disable>Dùng Nấm Trị Dây Leo</>. Dùng <Disable>Dùng Nấm Trị Dây Leo</> lên <Disable>Dây Leo Hoang Vu</> để thanh tẩy chúng. Nếu xử lý đủ số <Disable>Dây Leo Hoang Vu</> quy định trong cơ chế, Sylvia sẽ vào trạng thái Suy Yếu; nếu không, cô ta dùng <Disable>Vạn Vật Điêu Tàn</> tiêu diệt toàn bộ người chơi. <Disable>Dây Leo Hoang Vu</> không được thanh tẩy trong 15 giây sau khi sinh ra sẽ biến thành vùng Ô Nhiễm và tồn tại đến hết trận.",
    [1046805399772160] = "Hộ Vệ Hậu Duệ hấp thụ sức mạnh địa mạch Vườn Quả; khi phát nổ gây sát thương <Disable>vùng tròn</> hoặc <Disable>vùng vòng khuyên</>.",
    [1046805399772416] = "Bảo Hộ Hậu Duệ luyện thành Ma Tượng Đất; Ma Tượng sẽ tái hiện <Disable>Đại Địa Chấn Động</> hoặc <Disable>Địa Mạch Cộng Hưởng</>.",
    [1046805399772672] = "Khi còn <Disable>50% Máu</>, Bảo Hộ Hậu Duệ rơi vào trạng thái Mất Kiểm Soát, khiến Ma Tượng cuồng bạo và liên tục thi triển <Disable>Đại Địa Chấn Động cùng Địa Mạch Cộng Hưởng</>.",
    [1046805399772928] = "Bảo Hộ Hậu Duệ dùng Pháp Trận Luyện Kim dẫn sức mạnh Địa Mạch, trong lúc liên tục luyện Ma Tượng Đất và phát động <Disable>Đại Địa Chấn Động</>.",
    [1046805399773184] = "Khi kỹ năng bắt đầu, Vượn Vua Khiêu Vũ dịch chuyển tới giữa sân và nhảy múa, sau đó dùng 3 lần <Disable>kỹ năng sát thương phạm vi lớn</> tấn công từng người chơi.",
    [1046805399773440] = "Vượn Đầu Chó Vua Nhảy dần trở nên hưng phấn, liên tục chỉ định những người chơi khác nhau rồi xung phong. Mỗi lần xung phong gây <Disable>sát thương khống chế</> lên người chơi trên đường đi và để lại <Disable>đường lửa</> gây sát thương liên tục phía sau.",
    [1046805399773696] = "Vua Nhảy Baboon truyền tống tới giữa sàn nhảy và khiêu vũ, gắn Năng Lượng Nốt Nhạc <Disable>màu khác nhau</> lên từng người chơi, đồng thời triệu hồi <Disable>3 sàn nhảy màu khác nhau</>. <Disable>Khi hết thời gian</>, nó phóng Năng Lượng Sét tấn công toàn bộ người chơi và gây Sát Thương cực lớn cho người đứng sai màu.",
    [1046805399773952] = "Vượn Vua Khiêu Vũ dịch chuyển tới giữa sàn nhảy, giơ tay hô lớn đòi âm nhạc mạnh hơn và triệu hồi Đoàn Vũ Công Khỉ Đầu Chó. Người chơi cần <Disable>hạ khỉ nhỏ</> để nhận <Disable>vật phẩm Nốt Nhạc rơi</>, rồi nhặt Nốt Nhạc theo <Disable>thứ tự bản nhạc</>.",
    [1046805399774208] = "Mưa Nốt Nhạc Vàng bắt đầu rơi xuống sân. Chạm Nốt Nhạc Vàng sau khi rơi xuống đất để tích Giá Trị Vũ Lực; nếu tích đầy <Disable>trước khi hết đếm ngược</>, nhận <Disable>Lá Chắn Âm Nhạc</>; nếu không, Baboon sẽ gây <Disable>sát thương cực lớn</> lên người chơi.",
    [1046805399774464] = "Vua Nhảy Baboon dịch chuyển người chơi vào giữa sàn nhảy và <Disable>thực hiện các động tác khác nhau</> khi đang nhảy. Người chơi phải dựa vào gợi ý động tác để chọn điệu nhảy tương ứng. Trong toàn giai đoạn, nếu <Disable>cả đội cộng dồn nhảy sai 3 lần</>, Baboon sẽ nổi giận và gây <Disable>sát thương cực lớn</> lên người chơi.",
    [1046805399774720] = "Carl Edgar biến Tri Thức Cấm Kỵ vô tận mình đã nhìn trộm thành năng lượng hữu hình, triệu hồi bên cạnh mỗi người chơi một giá sách ngưng tụ từ Tri Thức Cấm Kỵ. Người chơi <Disable>chỉ cần tới gần giá sách sẽ bị Nguyền Rủa</> và rất khó thoát thân.",
    [1046805399774976] = "Carl Edgar dùng Linh Tính huyễn hóa Con Mắt Dòm Bí. Người chơi bị Con Mắt Dòm Bí nhìn chằm chằm không thể ẩn nấp và sau một khoảng trễ ngắn sẽ bị tia laser khóa mục tiêu của Carl Edgar tấn công.\n<Disable>Giá sách có thể chắn tia laser</> nhưng sẽ bị phá hủy ngay và biến thành <Disable>“Bẫy Tà Nhãn”</>.",
    [1046805399775232] = "Carl Edgar lật giở điển tịch và liên tục hấp thụ sức mạnh. Trong thời gian này, hắn <Disable>liên tục truy đuổi một người chơi</>; khi hấp thụ xong sẽ <Disable>kết liễu ngay</> người đó. Trong lúc hấp thụ, sát thương hắn phải chịu giảm mạnh và hắn còn liên tục gây sát thương toàn chiến trường.\n<Disable>Quá trình hấp thụ có thể bị “Bẫy Tà Nhãn” ngắt</>.",
    [1046805399775488] = "Abaddon niệm chú cấm kỵ, triệu hồi lượng lớn thiên thạch mang năng lượng tà ác rơi xuống sân. Nếu thiên thạch chạm đất sẽ phát nổ, gây sát thương lên toàn bộ người chơi và gắn <Disable>Ấn Ký Tà Ác</>; nếu người chơi đỡ được trước khi chạm đất, chỉ người đó chịu sát thương và nhận <Disable>Ấn Ký Tà Ác</>.",
    [1046805399775744] = "Khi mức ăn mòn của <Disable>Ấn Ký Tà Ác</> trên người chơi cộng dồn đến 100%, nó chuyển thành trạng thái <Disable>Xâm Thực Hắc Ám</>; người chơi biến thành <Disable>U Hồn</> trong một khoảng thời gian, không thể nhảy hoặc dùng kỹ năng.",
    [1046805399776256] = "Kỵ Sĩ Táo chọn 2 người chơi; sau một khoảng trễ ngắn gây sát thương phạm vi rồi <Disable>nảy theo hình chữ thập để gây thêm sát thương phạm vi</>. Hai người bị chọn sẽ biến thành <Disable>Táo Sắp Nổ</>; khi đếm ngược kết thúc sẽ làm nổ toàn chiến trường.",
    [1046805399776512] = "Kỵ Sĩ Táo rải độc dược khắp sân; hết đếm ngược sẽ <Disable>tất sát toàn bộ người chơi</>. Đồng thời mỗi người chơi bị gieo Hạt Độc, khi hết đếm sẽ gây <Disable>vụ nổ phạm vi nhỏ</>.",
    [1046805399776768] = "Kỵ Sĩ Táo triệu hồi rất nhiều Bom Táo, chuẩn bị <Disable>oanh tạc toàn sân</>. Các Người Lùn sẽ chạy tới hỗ trợ từ bốn phía, tạo <Disable>Vùng An Toàn Người Lùn ở nhiều vị trí</>.",
    [1046805399777024] = "Kỵ Sĩ Táo dùng Toàn Phong Trảm và <Disable>liên tục truy sát người chơi</>. Trên sân xuất hiện nhiều Bẫy Thú; dụ Kỵ Sĩ Táo <Disable>giẫm trúng 3 Bẫy Thú sẽ khiến nó ngã</>, sau đó dùng <Disable>Đại Chùy của Kỵ Sĩ Táo gây đòn chí mạng</>.",
    [1046805399777280] = "Kỵ Sĩ Táo <Disable>lần lượt xung phong vào 2 người chơi</>, gây <Disable>sát thương cực lớn có thể chia sẻ</> cho mọi người trên đường đi.",
    [1046805399777536] = "Người chơi sẽ bị Ma Lực Cổ Tích nối <Disable>theo từng cặp</> và trở thành bạn nhảy của nhau. Nếu hai bạn nhảy <Disable>cách nhau quá 8m</>, Ma Lực Cổ Tích sẽ <Disable>cưỡng ép kéo họ lại gần và gây sát thương lớn</>.",
    [1046805399777792] = "Hoàng Tử Ếch vào trạng thái Không Thể Chỉ Định, liên tục đuổi Cinderella để cưỡng hôn; khi hết kiên nhẫn sẽ cuồng bạo tấn công mọi người. Ở rìa sân xuất hiện Phục Vụ và Xe Đẩy. Sau khi <Disable>đuổi Phục Vụ</>, người chơi có thể dùng <Disable>đạo cụ trên sân</> tấn công Hoàng Tử Ếch, phá phòng khiến hắn ngã.",
    [1046805399778048] = "Thời khắc định mệnh đã tới, tất cả phải phối hợp tham gia Đại Vũ Hội. Người chơi cần <Disable>tới khu sân khấu của mình</> và theo <Disable>chỉ dẫn hướng di chuyển của bạn nhảy</> để cùng khiêu vũ; <Disable>di chuyển sai hướng sẽ bị trừng phạt tương ứng</>.",
    [1046805399778304] = "Locke King rải Đồng Vàng Tội Lỗi mê hoặc nhiều <Disable>Người Nghèo</>. Sau khi bị mê hoặc, họ <Disable>tăng mạnh Tốc Độ Di Chuyển và Tấn Công</>, điên cuồng truy đuổi người chơi.",
    [1046805399778560] = "Locke King dựng <Disable>Hộ Thuẫn Nợ Nần</>; nếu không phá kịp sẽ gây <Disable>vụ nổ toàn sân</>, đồng thời bên rìa sân xuất hiện <Disable>Pháo Đài Tiền</>.",
    [1046805399778816] = "Sân được chia thành <Disable>9 khu vực</>, mỗi khu xuất hiện hình chiếu thật và giả, bong bóng trên đầu ẩn chứa manh mối. <Disable>Chỉ một hình chiếu là tuyên truyền chống lừa đảo thiện ý</>.",
    [1046805399779072] = "Riel Bieber triệu hồi sức mạnh trong Bút Ký, bắn về phía trước một tia năng lượng gây sát thương liên tục. Tia sẽ gây sát thương lên <Disable>người chơi đầu tiên trúng phải</> rồi bị chặn.",
    [1046805399779328] = "Ray Bieber triệu hồi sức mạnh trong cuốn bút ký, bắn tia năng lượng về phía trước gây sát thương liên tục. Tia gây sát thương lên <Disable>người chơi đầu tiên trúng phải</> rồi bị chặn; kỹ năng càng duy trì lâu, <Disable>sát thương của tia càng tăng</>.",
    [1046805399779584] = "Ancia triệu hồi Ngài Barney giáng xuống nhiều người chơi, gây <Disable>sát thương cần chia sẻ</>.",
    [1046805399779840] = "Anxia triệu hồi Ngài Barney, tung đòn nện xuống nhiều người chơi cần <Disable>chia sát thương</>. Sau khi chia, <Disable>ngẫu nhiên chọn 1 người chơi</> và <Disable>nối dây</> với một người đã chia sát thương; nếu <Disable>dây nối bị kéo đứt</>, cả hai sẽ chịu lượng lớn sát thương.",
    [1046805399780096] = "Johnny triệu hồi 6 Vật Hiến Tế vô tội và sai khiến Ác Ma tấn công họ để tiến hành Nghi Thức Hiến Tế.",
    [1046805399780352] = "Johnny triệu hồi những vật hiến tế vô tội và bắt đầu Trò Chơi Tàn Sát; đồng thời trên sân xuất hiện Vùng An Toàn có thể cứu rỗi vật hiến tế.",
    [1046805399780608] = "Các Vật Hiến Tế Vô Tội sẽ định kỳ được Johnny triệu hồi vào cảnh. Khi bị Johnny giết, chúng sẽ phát ra sóng xung kích toàn phạm vi.",
    [1046805399780864] = "Chiến Long khóa <Disable>1 Phi Phàm Giả</> và phun Hỏa Cầu. Hỏa Cầu chạm đất sẽ phát nổ, để lại vùng lửa <Disable>cháy trong thời gian ngắn</>.",
    [1046805399781120] = "Chiến Long khóa <Disable>3 Phi Phàm Giả</> và phun Hỏa Cầu. Hỏa Cầu chạm đất sẽ phát nổ, để lại vùng lửa <Disable>cháy liên tục</> trên mặt đất.",
    [1046805399781376] = "Chiến Long khóa <Disable>1 Phi Phàm Giả</> và lao tới. Trong lúc xung phong, Chiến Sĩ có thể dùng <Disable>Kỹ Năng Kết Liễu</> để chặn thành công và ngắt cú lao của Chiến Long.",
    [1046805399781632] = "Sau khi Cự Long Chiến Tranh bay lên, nó sẽ vòng quanh sân, để lại Liệt Diễm và liên tục tụ lực. Phi Phàm Giả cần dùng <Disable>6 Phù Văn</> trong sân để hoàn thành nghi thức cầu nguyện trong thời gian giới hạn và đánh rơi Cự Long Chiến Tranh.",
    [1046805399781888] = "Sau khi Cự Long Chiến Tranh bay lên, nó sẽ vòng quanh sân, để lại lửa và liên tục tụ lực. Phi Phàm Giả cần dùng <Disable> 6 Phù Văn</> trong sân để hoàn thành nghi thức cầu nguyện trong thời gian giới hạn và đánh rơi Cự Long Chiến Tranh.\nĐi vào phạm vi Phù Văn để kích hoạt Phù Văn tương ứng. Từ vòng nghi thức thứ hai, Phù Văn phải được kích hoạt <Disable> theo đúng thứ tự chỉ định</>, nếu không nghi thức sẽ không có hiệu lực.",
    [1046805399782144] = "Bonnie triệu hồi 6 <Disable>Phân Thân Vũ Công</>; 6 Vũ Công sẽ nhảy 3 loại Điệu Nhảy. Sau một khoảng trễ ngắn, Bonnie gây sát thương lớn lên toàn chiến trường.",
    [1046805399782400] = "Bonnie triệu hồi 3 <Disable>Vũ Trận</>; mỗi Vũ Trận hiển thị một <Disable>tên điệu nhảy</>. Phi Phàm Giả sở hữu điệu nhảy tương ứng phải vào Vũ Trận và nhảy. Nếu không, Bonnie sẽ gây sát thương toàn sân để trừng phạt những kẻ phá rối trật tự sàn nhảy.",
    [1046805399782656] = "Bonnie triệu hồi 10 Phân Thân Vũ Công cùng nhảy với mình, nhưng <Disable>4 Vũ Công</> sẽ nhảy Điệu Nhảy <Disable>khác</> những người còn lại. Sau một khoảng thời gian, Bonnie kiểm tra điệu nhảy toàn chiến trường và gây sát thương toàn trường.",
    [1046805399783424] = "Sau khi Cự Long Chiến Tranh bay lên và bắt đầu tụ lực, Phi Phàm Giả phải trong thời gian giới hạn <Disable>phá Mảnh Tàn Chiến Hỏa, thu thập Năng Lượng Chinh Phục và tương tác với Phù Văn tương ứng để hoàn thành cầu nguyện</>. Khi <Disable>cả 6 Phi Phàm Giả</> hoàn tất cầu nguyện, Năng Lượng Chinh Phục hội tụ thành sức mạnh lớn, đánh rơi Cự Long Chiến Tranh khỏi không trung.",
    [1046805399784192] = "Bonnie triệu hồi 3 <Disable>Phân Thân Vũ Công</>. Trên <Disable>đầu</> mỗi Vũ Công sẽ hiện một <Disable>tên Điệu Nhảy</>; Vũ Công khóa một Phi Phàm Giả, sau một khoảng thời gian sẽ <Disable>xung phong</> vào người đó.",
    [1046805399784448] = "Bonnie triệu hồi 10 phân thân Vũ Công cùng nhảy, nhưng có <Disable>4 Vũ Công</> nhảy <Disable>khác</> những người còn lại. Đồng thời Bonnie triệu hồi <Disable>2 Vũ Trận</> quanh mình; sau khi hạ một Vũ Công nhảy sai, Vũ Trận sẽ hiển thị <Disable>tên điệu nhảy</>. Sau một khoảng thời gian, Bonnie kiểm tra điệu nhảy toàn sân và gây sát thương toàn sân.",
    [1046805399785472] = "“Mũi Khoan” triệu hồi tia sáng, xoay một thời gian rồi đảo chiều. Đồng thời trên sân xuất hiện nhiều <Highlight>Điện Trường</> cản đường. Bị tia sáng đánh trúng sẽ cộng dồn tầng <Highlight>Quá Tải</>.",
    [1046805399785728] = "Sau khi “Mũi Khoan” bay lên, sân xuất hiện 6 <Highlight>Lôi Trì</>. Dụ “Mũi Khoan” xung phong giẫm vào <Highlight>Lôi Trì</> để cộng tầng <Highlight>Quá Tải</>; đủ 4 tầng sẽ vào trạng thái <Highlight>Choáng</>.",
    [1046805399785984] = "Sau khi “Mũi Khoan” bay lên, nó triệu hồi <Highlight>Màn Chắn Cách Điện</>; sân xuất hiện nhiều <Highlight>Thánh Tiêu Dẫn Điện</>, trong đó một cái ở trạng thái kích hoạt. Toàn bộ Phi Phàm Giả dẫn sét từ Thánh Tiêu đang kích hoạt để nạp điện cho các Thánh Tiêu khác; nạp đủ sẽ phá <Highlight>Màn Chắn Cách Điện</>. Nếu không hoàn thành trong thời gian nhất định, cả đội bị tiêu diệt.",
    [1046805399786496] = "Sau khi “Mũi Khoan” bay lên, sân xuất hiện 6 <Highlight>Vũng Nước</>. Bên cạnh mỗi Phi Phàm Giả xuất hiện <Highlight>Cầu Điện</> tự động đuổi theo; cần dẫn <Highlight>Cầu Điện</> vào <Highlight>Vũng Nước</> để biến thành <Highlight>Lôi Trì</>. Sau đó “Mũi Khoan” đáp xuống và liên tục lao ngẫu nhiên! Hãy né <Highlight>Lôi Trì</>, dụ “Mũi Khoan” giẫm lên <Highlight>Lôi Trì</> để cộng tầng <Highlight>Quá Tải</>; đủ 4 tầng sẽ vào <Highlight>Choáng</>.",
    [1046805399787008] = "Triệu hồi 2 <Disable>Linh Hồn Khuyển Đỏ Thẫm không thể chọn làm mục tiêu</>; mỗi con khóa và liên tục truy đuổi một người chơi. Khi bị Linh Hồn Khuyển Đỏ Thẫm đuổi kịp, người chơi chịu một lần <Disable>sát thương cắn cực lớn</>.",
    [1046805399787264] = "Chỉ định một Phi Phàm Giả, khiến họ nhận 【Truy Liệp】, đồng thời triệu hồi 2 Liệp Khuyển Đỏ Thẫm Không Thể Chỉ Định và 1 Nam Bộc Dị Biến. Sau vài giây, Liệp Khuyển Đỏ Thẫm sẽ dùng 【Vồ Giết】 lên mục tiêu.",
    [1046805399787520] = "Đại Kiếm Luyện Kim do Hậu Duệ Bảo Hộ mang sức mạnh tà ác. Khi nó <Highlight>cầm kiếm tung tấn công phạm vi</> và trúng <Highlight>ít nhất 3</> Phi Phàm Giả cùng lúc, sẽ áp 1 tầng Linh Tính Xâm Thực lên những người trúng đòn. Khi Linh Tính Xâm Thực đạt 3 tầng, nó tung thêm một đòn <Highlight>Áp Chế</>, làm giảm năng lực gây sát thương của mục tiêu và khiến mục tiêu liên tục mất Sinh Mệnh.",
    [1046805668169216] = "<Highlight>Người chơi Tank</> cần kịp thời giữ Cừu Hận.",
    [1046805668169472] = "<Highlight>Người chơi DPS</> cần tiêu diệt nó càng nhanh càng tốt.",
    [1046805668169728] = "Người chơi ở trạng thái Trì Trệ không thể di chuyển hoặc dùng kỹ năng; <Highlight>có thể thao tác phím để tăng tốc thoát trạng thái</>.",
    [1046805668169984] = "Trong lúc tụ lực, người chơi cần <Highlight>tránh xa Riel Bieber</>.",
    [1046805668170240] = "<Highlight>Người chơi Tank</> cần đỡ kỹ năng này.",
    [1046805668170496] = "Quan sát kỹ và bắt chước <Highlight>động tác của Hề</>.",
    [1046805668170752] = "Khi Vòng Quay dừng, <Highlight>đi tới vùng đúng chất bài</>.",
    [1046805668171008] = "Khi <Highlight>Người Sói bị Choáng</>, tới gần có thể <Highlight>chuyển thương thế</>.",
    [1046805668171264] = "Có thể dụ Người Sói <Highlight>đâm vào bom</>.",
    [1046805668171520] = "Cần kịp thời <Highlight>chuyển thương thế</>; người chơi Hồi Phục <Highlight>chú ý Máu đồng đội</>.",
    [1046805668171776] = "<Highlight>Người chơi DPS</> cần nhanh chóng tiêu diệt tay sai.",
    [1046805668172032] = "Người chơi cần <Highlight>di chuyển linh hoạt</> để né Cột Băng.",
    [1046805668172288] = "Người chơi cần nhanh chóng <Highlight>tiêu diệt U Ảnh</>; U Ảnh bị tiêu diệt sẽ tạo <Highlight>Vùng An Toàn.</>",
    [1046805668172544] = "Người chơi cần nhanh chóng <Highlight>tản vị trí</> để tránh chịu <Highlight>nhiều lần sát thương Nguyền Rủa</>.",
    [1046805668172800] = "Người chơi cần nhanh chóng <Highlight>phá hủy Cầu Năng Lượng</>.",
    [1046805668173056] = "Người chơi cần <Highlight>quan sát cảnh báo kỹ năng</> và né tránh từ sớm.",
    [1046805668173312] = "Sau khi bụi hoa hình thành, <Highlight>nhanh chóng rời xa khu vực gần bụi hoa</>.",
    [1046805668173568] = "Arrodes sẽ kịp thời triệu hồi Màn Chắn Sương Xám; <Highlight>nhanh chóng vào bên trong để né tránh</>.",
    [1046805668173824] = "Người chơi cần <Highlight>dẫn Ý Chí Đỏ Thẫm rời xa Nguyệt Hoa</>.",
    [1046805668174080] = "Làm theo chỉ dẫn trên màn hình, phản ứng nhanh để <Highlight>thoát khỏi khống chế của Phân Thân Amon</>.",
    [1046805668174336] = "<Highlight>Chú ý quan sát quỹ đạo di chuyển của các Phân Thân Amon</> và né tránh từ sớm.",
    [1046805668174592] = "<Highlight>Chú ý tránh xa Audrey</>.",
    [1046805668174848] = "<Highlight>Rời xa phạm vi ảnh hưởng của Rồng Không Tưởng</>.",
    [1046805668175104] = "Dùng <Highlight>Kỹ Năng Giải Khống Chế</> và kịp thời kéo giãn khoảng cách.",
    [1046805668175616] = "Dùng <Highlight>kỹ năng Giải Khống hoặc Di Chuyển</> để rời khỏi tâm kỹ năng.",
    [1046805668176128] = "<Highlight>Nghề DPS</> cần kịp thời tiêu diệt nó.",
    [1046805668176384] = "<Highlight>Nghề DPS</> cần tiêu diệt nó càng nhanh càng tốt.",
    [1046805668176640] = "Quả Cầu Năng Lượng chạm xe ngựa sẽ gây sát thương rất lớn; toàn đội phải cố gắng <Highlight>chặn Quả Cầu Năng Lượng</>.",
    [1046805668176896] = "Chú ý cảnh báo dưới đất và kịp thời <Highlight>né cú xung phong của Ray Bieber</>.",
    [1046805668177152] = "Người chơi cần <Highlight>phá Khiên</> càng nhanh càng tốt trước khi Real Bieber đọc xong.",
    [1046805668177408] = "Tất cả người chơi cần vượt mê cung tới bên Ray Bieber để <Highlight>giải trừ hóa búp bê</>.",
    [1046805668177664] = "Di chuyển cẩn thận, <Highlight>tránh để các vùng sát thương chồng lên nhau</>.",
    [1046805668177920] = "Quan sát vị trí đồng đội bị đánh dấu, <Highlight>kịp thời vào vòng chia sát thương</>.",
    [1046805668178176] = "Quan sát <Highlight>chất bài</> trên đầu mình rồi nhanh chóng đứng vào vùng tương ứng.",
    [1046805668178432] = "<Highlight>Nhanh chóng phá toàn bộ phân thân,</> chấm dứt nghiên cứu của Hề.",
    [1046805668178688] = "Tất cả chú ý <Highlight>di chuyển linh hoạt</> để né.",
    [1046805668178944] = "Mục tiêu bị khóa cần kịp thời <Highlight>bật Giảm Thương</>; những người khác chú ý <Highlight>tránh xa</> hướng của mục tiêu bị khóa.",
    [1046805668179200] = "Tất cả kịp thời <Highlight>nhảy</> để né sóng chấn động.",
    [1046805668179456] = "<Highlight>Người chơi Trị Liệu</> hãy kịp thời dùng kỹ năng Trị Liệu diện rộng.",
    [1046805668179712] = "Kịp thời chuyển mục tiêu sang <Highlight>Ấu Thú Ô Uế</>, sau đó đẩy Ấu Thú tới <Highlight>bên dưới Gulu</> cho Gulu nuốt, qua đó kiểm soát tốc độ tăng Giá Trị Đói.",
    [1046805668180224] = "Người chơi Tank cần <Highlight>kéo Phân Thân Amon ra khỏi Vùng Bóng Tối</>; những người khác thận trọng khi đi vào Vùng Bóng Tối.",
    [1046805668180480] = "Người chơi bị Dòng Trào truy đuổi cần nhanh chóng <Highlight>dẫn Dòng Trào vào Vùng Bóng Tối</>.",
    [1046805668180736] = "Hai người chơi bị chỉ định khi đếm ngược nổ kết thúc cần <Highlight>chỉ định một người vào Vùng Bóng Tối</>, tránh hai lần sát thương khiến cả đội bị quét sạch.",
    [1046805668180992] = "Người chơi Trị Liệu <Highlight>liên tục hồi Máu cho người chơi bị Ký Sinh</>; những người khác tập trung tấn công Boss.",
    [1046805668181248] = "Quan sát hướng luân chuyển của Quả Cầu Ánh Sáng, kịp thời tìm và tập trung hỏa lực vào <Highlight>Phân Thân Amon tại điểm dừng cuối</>.",
    [1046805668181504] = "Dồn toàn lực tấn công <Highlight>Vòng Xoáy Lịch Sử ở Vùng Không Bóng Tối</>, rồi sau khi thời không đảo ngược phải kịp thời tới Vùng Không Bóng Tối mới.",
    [1046805668181760] = "Dùng <Highlight>Cảm Tri Sương Xám</> để dò vị trí Tượng Ma Lang và phá hủy toàn bộ trước khi bóng tối nuốt chửng chiến trường. <Highlight>Lời Cầu Nguyện Bão Táp</> cũng có thể phá Tượng; đồng thời cần dùng <Highlight>Tử Thần Nhân Tạo</> để xua tan hiệu ứng Ám Quang do Ma Lang U Ám gây ra.",
    [1046805668182016] = "Dùng <Highlight>Cảm Tri Sương Xám</> để dò vị trí <Highlight>Bóng Tối U Ám</> và tìm khoảng trống né đòn.",
    [1046805668182272] = "Dùng <Highlight>Cảm Tri Sương Xám</> dò vị trí <Highlight>Quyến Tộc Ma Lang</> rồi chuyển mục tiêu tấn công. <Highlight>Lời Cầu Nguyện Bão Táp</> có thể làm Choáng <Highlight>Quyến Tộc Ma Lang</>, khiến chúng tạm hiện hình và mất khả năng tấn công, di chuyển.",
    [1046805668182528] = "<Highlight>Sợi Tơ Linh Thể</> sẽ đứt khi <Highlight>khoảng cách giữa hai người được nối vượt quá một mức nhất định</>; hai người chơi được nối cần chạy ngược hướng nhau.",
    [1046805668182784] = "Dùng <Highlight>Tử Thần Nhân Tạo</> có thể xua tan hiệu ứng <Highlight>Ám Quang</> của mọi người chơi gần đó.",
    [1046805668183040] = "<Highlight>Văn bản trọng điểm</> văn bản thường văn bản thường văn bản thường.",
    [1046805668183296] = "Người chơi cần <Highlight>đánh bại đồng thời Medici và Ouroboros trong vòng 10 giây</>.",
    [1046805668183552] = "Dùng <Highlight>Hào Quang Vận Mệnh</> để nhận biết và <Highlight>tấn công kẻ địch có Vận Mệnh đối lập với bản thân</>.",
    [1046805668183808] = "Trong thời gian giới hạn, hãy <Highlight>tiếp xúc với đồng đội mang Vận Mệnh đối lập</>.",
    [1046805668184064] = "<Highlight>Tập trung tấn công Ghế Lưng Cao</> để giải cứu đồng đội bị trói buộc.",
    [1046805668184320] = "Chủ động <Highlight>tập trung trong Pháp Trận để chia sát thương</>, có thể ngăn Osecu gây sát thương diệt đội.",
    [1046805668184576] = "<Highlight>Dẫn Binh Sĩ Quân Đoàn va vào nhau</>.",
    [1046805668184832] = "Hỏa Cầu Dương Viêm gây nguy hiểm chí mạng cho người chơi; phải <Highlight>dẫn Trường Mâu bắn trúng</> chúng mới kịp giảm áp lực Máu.",
    [1046805668185088] = "Sát thương của sóng xung kích có thể né bằng cách <Highlight>nhảy</>.",
    [1046805668185344] = "Khi hiệu ứng Vô Địch của tượng biến mất, kịp thời <Highlight>phá hủy</> tượng.",
    [1046805668185600] = "Phân công người chơi linh hoạt để <Highlight>chặn</> tia Laser.",
    [1046805668185856] = "Tránh đi vào <Highlight>Pháp Trận Tượng</> để không chịu sát thương phạm vi.",
    [1046805668186112] = "Phân công người chơi linh hoạt để <Highlight>chắn tia</>, tránh để Mirgongen nhận Cường Hóa.",
    [1046805668186368] = "Hãy giữ lại <Highlight>kỹ năng Bùng Nổ</> và tung khi Mirgongen bị Phá Phòng để gây nhiều Sát Thương hơn.",
    [1046805668186624] = "Mọi người <Highlight>linh hoạt di chuyển</> để né, đồng thời bố trí người chơi chỉ định <Highlight>chặn đường</>. Những người còn lại kịp thời <Highlight>chuyển mục tiêu dồn sát thương</> vào tượng đã mất Vô Địch để đưa Mirgongen vào trạng thái Phá Phòng.",
    [1046805668186880] = "<Highlight>Quan sát nhịp chuyển động của dòng sông</>; đi qua khi nước yên và tránh lúc dòng sông sắp phun trào.",
    [1046805668187136] = "Người chơi bị đánh dấu <Highlight>rời xa nhóm, đặt Nước Đen ở rìa sân</> rồi nhanh chóng rời đi.",
    [1046805668187392] = "<Highlight>Chủ động chặn Năng Lượng Hỗn Độn; chú ý màu Vận Mệnh của bản thân. Va vào năng lượng cùng màu Vận Mệnh sẽ bị Choáng.</> Đừng để năng lượng chạm Sasrir.",
    [1046805668187648] = "<Highlight>Nhanh chóng chuyển mục tiêu sang Ảo Ảnh Hiến Tế</>; đừng để bất kỳ Ảo Ảnh nào chạm vào Sasrir.",
    [1046805668187904] = "<Highlight>Thu thập Mảnh Linh Năng rải rác ở Thành Bạch Ngân và mang tới vùng nạp năng lượng để nạp cho Nơi Trú Ẩn Bạch Ngân.</> Trong vùng đã nạp đầy có thể miễn nhiễm một lần sát thương hủy diệt.",
    [1046805668188160] = "<Highlight>Quan sát vị trí ban đầu và hướng xoay của tia rồi tránh chạm vào</>; trong lúc né tia đừng quên chặn Năng Lượng Hỗn Độn.",
    [1046805668188416] = "【Đang Thi Công】Gợi ý xử lý giai đoạn.",
    [1046805668188672] = "Trên người chơi bị <Highlight>Trì Trệ</> sẽ xuất hiện nút đẩy; <Highlight>nhấn nút</> để giải trừ <Highlight>Trì Trệ</> cho người đó.",
    [1046805668188928] = "<Highlight>Nghề Phòng Hộ</> cần kịp thời kéo Ray Bieber <Highlight>ra xa 2-049</>.",
    [1046805668189184] = "Cần đi qua Tường Tầm Nhìn trong lúc 2-049 <Highlight>nhắm mắt</>, hoặc tránh để nó quét trúng.",
    [1046805668189440] = "Quan sát <Highlight>biểu cảm của Hề</>, sau đó kết hợp với <Highlight>chất bài</> trên đầu mình và nhanh chóng đứng vào vùng tương ứng.",
    [1046805668189696] = "Tập trung hỏa lực <Highlight>phá một góc Nhà Tù Băng</> để phá giam giữ và thoát khỏi phạm vi đòn chí tử.",
    [1046805668189952] = "<Highlight>Góc Dòm Ngó Bí Ẩn: mở Thứ Hai</>\n<Highlight>Chợ Đen Ai Hào: mở Thứ Ba/Thứ Sáu</>\n<Highlight>Tội Vàng: mở Thứ Tư/Thứ Bảy</>\n<Highlight>Dấu Vết Người Chết: mở Thứ Năm/Chủ Nhật</>",
    [1046805668190208] = "Mỗi lần Nhảy Chém cần <Highlight>ít nhất 4 người tập trung</> để chia sát thương; người đã chia sát thương lần 1 trong thời gian ngắn <Highlight>không thể tham gia chia lần 2</>.",
    [1046805668190464] = "Người chơi bị khóa dùng <Highlight>di chuyển để dẫn hướng đòn Chấn Động Đại Địa</>, tránh lan sang quá nhiều đồng đội.",
    [1046805668190720] = "Người chơi bị đánh dấu tiến lại gần Nhà Chiêm Tinh; những người khác nhanh chóng chuyển mục tiêu khi <Highlight>Cấm Chế</> xuất hiện và chú ý Máu toàn đội.",
    [1046805668190976] = "<Highlight>Tập trung vị trí</>, tránh đứng quá phân tán khiến phạm vi ảnh hưởng của Phi Đạn quá lớn và khó né.",
    [1046805668191232] = "Khi Vẫn Thạch xuất hiện, nhanh chóng <Highlight>rời xa</> vị trí hiện tại.",
    [1046805668191488] = "<Highlight>Sóng nổ</> khi Hộ Vệ Tinh Quang đáp xuống có thể né bằng <Highlight>nhảy</>; đồng thời kịp thời <Highlight>kéo Cừu Hận</> ra xa Nhà Chiêm Tinh.",
    [1046805668191744] = "Người chơi bị đánh dấu tiến lại gần Nhà Chiêm Tinh; những người khác nhanh chóng chuyển mục tiêu khi <Highlight>Cấm Chế</> xuất hiện.",
    [1046805668192256] = "Khi bị kéo tới trước mặt Nhà Chiêm Tinh, nhanh chóng <Highlight>rời xa</> hắn.",
    [1046805668192512] = "<Highlight>Sóng nổ</> khi Hộ Vệ Tinh Quang đáp xuống có thể né bằng <Highlight>nhảy</>. Kịp thời chuyển mục tiêu, để <Highlight>Chiến Sĩ</> thu hút Cừu Hận của Hộ Vệ Tinh Quang. Sau khi đánh bại, nhanh chóng vận chuyển Tinh Quang tới Chân Nến Tinh Quang để lưu trữ.",
    [1046805668192768] = "Thời gian người chơi có thể tạm lưu <Highlight>Tinh Quang</> là có hạn; cần hoàn tất vận chuyển càng sớm càng tốt.",
    [1046805668193024] = "Ưu tiên bảo đảm thu thập Tinh Quang; cố gắng <Highlight>đồng thời tấn công</> Chiêm Tinh Nghi Giả và Hộ Vệ Tinh Quang, đồng thời bảo đảm vận chuyển Tinh Quang hoàn tất.",
    [1046805668193280] = "Cần <Highlight>hai người chơi</> ở hai phía sân lần lượt thu hút Cừu Hận của Ngài Barney và Anxia, cố gắng <Highlight>giữ họ cách xa nhau</>.",
    [1046805668193536] = "Cần <Highlight>ưu tiên đánh bại</> Ngài Barney.",
    [1046805668193792] = "Nếu hướng xung phong <Highlight>tiến gần</> Anxia, cần dẫn Anxia <Highlight>rời xa</> vị trí đó.",
    [1046805668194048] = "Tránh xa Bướm Xanh.",
    [1046805668194304] = "Sau khi xuất hiện, hãy nhanh chóng tách xa để cắt đường nối.",
    [1046805668194560] = "Chú ý <Highlight>đếm ngược</> của Anxia, kịp thời dừng di chuyển và né Bướm Xanh trên sân.",
    [1046805668195584] = "Trong lúc di chuyển cần dẫn Anxia <Highlight>liên tục rời xa</> Ngài Barney.",
    [1046805668195840] = "Tránh xa Bướm Xanh và sử dụng hợp lý chức năng của Bướm Vàng.",
    [1046805668196096] = "Chú ý <Highlight>đếm ngược</> của Anxia, kịp thời dừng di chuyển; đồng thời né Bướm Xanh và đường lao của búp bê, tận dụng Bướm Vàng để tăng tốc.",
    [1046805668196352] = "Cần <Highlight>tập trung phá một phần Hạt Quả</> và ở trong Vùng An Toàn cho tới khi toàn bộ Hạt Quả phát nổ rồi biến mất.",
    [1046805668196608] = "Người chơi bị Liệp Khuyển nhắm cần <Highlight>chủ động rời xa đám đông</>; những người khác kịp thời chuyển mục tiêu giải cứu sau khi người đó bị đánh trúng.",
    [1046805668196864] = "Người chơi Trị Liệu <Highlight>chú ý hồi toàn đội</>; tất cả bật kỹ năng <Highlight>Giảm Thương</>.",
    [1046805668197120] = "Chú ý liên tục né sát thương.",
    [1046805668197376] = "Người chơi không bị ngắm tới <Highlight>chủ động tập trung về phía người chơi đang bị ngắm</> để hỗ trợ chia sẻ sát thương Uy Áp.",
    [1046805668198912] = "Chia tổ chức thành hai đội nhỏ, <Highlight>mỗi đội giúp một người bị đánh dấu chia sát thương</>; người đã tham gia chia lần đầu tránh tham gia lần thứ hai.",
    [1046805668199424] = "Sau khi Linh Thể Bị Ô Nhiễm xuất hiện, toàn bộ người chơi phải <Highlight>ưu tiên hạ Linh Thể Bị Ô Nhiễm</>; sau đó một số người nhặt Đặc Tính Thần Bí để tham gia đối đầu tiếp theo.",
    [1046805668199680] = "Giai đoạn đầu, người nhặt Đặc Tính Thần Bí cần ra rìa sân <Highlight>dọn Binh Sĩ Trường Kích</> để nhận Chứng Nhận Vinh Quang; những người khác cẩn thận gây Sát Thương ở vòng trong. Khi Đối Quyết bắt đầu, người có <Highlight>Chứng Nhận Vinh Quang Cấp 1 trở lên</> tới Điểm Đối Quyết để <Highlight>mở Kỹ Năng Đối Quyết</>, rồi dùng kỹ năng phát động Đối Quyết! Những người còn lại <Highlight>hợp lực phá</> Khiên của Khải Giáp Tổ Tiên để giúp Đối Quyết thành công!",
    [1046805668199936] = "Sau khi Linh Thể Chờ Phục Tô xuất hiện, người chơi Trị Liệu phải <Highlight>ưu tiên Trị Liệu Linh Thể Chờ Phục Tô</>; những người khác tiếp tục gây sát thương.",
    [1046805668200960] = "Giai đoạn đầu, người nhặt Đặc Tính Thần Bí cần ra rìa sân <Highlight>dọn Binh Sĩ Trường Kích</> để nhận Chứng Nhận Vinh Quang; những người khác cẩn thận gây Sát Thương ở vòng trong. Khi Đối Quyết bắt đầu, người có <Highlight>Chứng Nhận Vinh Quang Cấp 3</> tới Điểm Đối Quyết để <Highlight>mở Kỹ Năng Đối Quyết</>, rồi dùng kỹ năng phát động Đối Quyết! Những người còn lại <Highlight>hợp lực phá</> Khiên của Khải Giáp Tổ Tiên để giúp Đối Quyết thành công!",
    [1046805668201472] = "Người chơi chạm Tàn Niệm Quản Gia sẽ bị trói; đồng đội cần kịp thời <Highlight>chuyển mục tiêu sang Quản Gia</>. Sau khi được cứu, người đó nhận <Highlight>Dấu Ấn Trung Thành</>, tối đa 3 tầng; đạt 3 tầng sẽ phát nổ. Sau đó Phu Nhân Tử Tước sẽ dùng <Highlight>U Linh Săn Giết</> lên người mang dấu. Người chơi chạm Tàn Niệm Tiểu Tử Tước nhận <Highlight>Nhớ Nhung Của Tiểu Tử Tước</>; đạt 2 tầng sẽ tạo chút ánh sáng trong cảnh tối và nghe được tiếng gọi của Tiểu Tử Tước, giúp xua tan bóng tối.",
    [1046805668201728] = "Người chơi có Dấu Ấn Trung Thành <Highlight>tập trung lại</> và rời xa người khác, chờ đòn chém của Phu Nhân Tử Tước. Người có <Highlight>2 tầng Nhớ Nhung Của Tiểu Tử Tước</> sẽ mở một vùng sáng quanh mình; những người khác đi cùng người có buff 2 tầng này để <Highlight>tìm Tàn Niệm Tiểu Tử Tước</> và giải trừ bóng tối.",
    [1046805668201984] = "Người chơi giữ <Highlight>Bảo Thạch Lá Xanh</> dùng kỹ năng tạm thời truyền năng lượng trong bảo thạch cho người giữ Vòng Tay Cỏ Bốn Lá. Khi năng lượng đạt 3 tầng, người giữ <Highlight>Vòng Tay Cỏ Bốn Lá</> mở <Highlight>Khiên May Mắn</> lúc Phu Nhân Tử Tước sắp hoàn tất tụ lực, ngăn Phán Quyết Tử Vong.",
    [1046805668202240] = "Quan sát gương trong Vùng An Toàn; <Highlight>gương có cột sáng vọt lên trời</> là gương đúng. Tất cả người chơi chạm gương cùng màu với khu vực hiện tại sẽ kích hoạt Linh Tính Xuyên Thoi để tới Vùng An Toàn.",
    [1046805668202496] = "Người chơi hạ toàn bộ Quản Gia; chờ nút <Highlight>Quán Chú Linh Tính</> xuất hiện trên Tiểu Tử Tước rồi tập trung hỗ trợ Tiểu Tử Tước mở Khiên, ngăn Phu Nhân Tử Tước.",
    [1046805668203008] = "Người chơi giữ <Highlight>Vòng Tay Cỏ Bốn Lá</>, khi Phu Nhân Tử Tước sắp kết thúc tụ lực, hãy bật <Highlight>Khiên May Mắn</> để chặn Tài Quyết Tử Vong của Phu Nhân.",
    [1046805668203264] = "Người chơi đứng cùng Nấm Độc, tận dụng khả năng <Highlight>Quả Cầu Nước có thể tiêu diệt Nấm Độc</> để xử lý chúng.",
    [1046805668203520] = "Quan sát vị trí sóng biển và né theo <Highlight>thứ tự nhất định</> để tránh bị sóng đánh trúng.",
    [1046805668203776] = "Người chơi nhặt Mai Rùa, dùng năng lực tạm thời để <Highlight>kích hoạt Giáp Đá</>, chống lại cú va của Cự Quy.",
    [1046805668204032] = "Người chơi có thể lợi dụng Nấm Độc tan trong nước, khiến <Highlight>Ách Thủy rơi lên Nấm Độc để loại bỏ Nấm Độc</>. Khi Côi Bảo rơi xuống có thể lấp Ách Thủy; <Highlight>dùng Côi Bảo để loại bỏ Ách Thủy</>.",
    [1046805668204288] = "Dẫn Cự Quy <Highlight>lao vào Côi Bảo</> để khiến nó bị Choáng.",
    [1046805668204800] = "Chú ý tốc độ và khu vực Tín Phong thổi qua.",
    [1046805668205056] = "Chú ý hướng nhìn của Hóa Thân Linh Thể và hiệu ứng cảnh báo.",
    [1046805668205312] = "Phán đoán hướng Thổ Tức, điều chỉnh vị trí để né Pháp Trường Ô Nhiễm trên đường đi. Chạm Quả Cầu Xanh có thể miễn nhiễm hiệu ứng Đẩy Lùi.",
    [1046805668205568] = "Cần phán đoán khu vực Lưu Tinh sẽ oanh tạc tiếp theo và di chuyển né trong khoảng trống giữa các đợt oanh tạc.",
    [1046805668205824] = "Nấm Mục có thể bị dụ di chuyển; khi Dây Leo Khô xuất hiện cần nhanh chóng tập trung hỏa lực xử lý.",
    [1046805668206080] = "Cần 6 người chơi tới gần <Disable>Dũng Sĩ Nấm</> và dẫn chúng rời xa đám đông để vùng Ô Nhiễm cách xa khu chiến đấu. Khi toàn bộ <Disable>Dũng Sĩ Nấm</> đều được dẫn đi thành công, cả đội nhận buff tăng 200% sát thương trong 2 phút.",
    [1046805668206336] = "Điều chỉnh hướng vùng chữ nhật bị đánh dấu để va vào <Disable>Dây Leo Phong Nhiêu</>, làm nó suy yếu thành Dây Leo Xanh. Tới gần Dây Leo Xanh sẽ bị trói; cần né hiệu ứng Đẩy Lùi của <Disable>Ân Huệ Phong Nhiêu</>.",
    [1046805668206592] = "Né đòn của Sylvia và chú ý đếm ngược hiệu ứng <Disable>Thời Khắc Thu Hoạch</> trên người; khi sắp hết, điều chỉnh hướng để tránh phun trúng đồng đội.",
    [1046805668206848] = "Mục tiêu bị chỉ định nhanh chóng rời xa Sylvia và xóa hiệu ứng Nguyền Rủa <Disable>Nấm Nở Rộ</>, sau đó vào trong Khiên để phòng <Disable>Sinh Cơ Giáng Lâm</>. Trong Khiên không phải cấp cao nhất, người trị liệu cần chú ý duy trì hồi phục; vai trò chịu sát thương cũng cần bật kỹ năng Giảm Thương nhóm và Khiên đúng lúc.",
    [1046805668207104] = "Quan sát vị trí <Disable>Nấm Hoang Vu</> xuất hiện và xác định Vùng An Toàn; đồng thời xử lý cơ chế tản và tập trung trong vùng an toàn.",
    [1046805668207360] = "Tất cả tản ra và dùng <Disable>Dùng Nấm Trị Dây Leo</> để thanh tẩy <Disable>Dây Leo Hoang Vu</> gần mình nhất. Trong thời gian này không thể nhận Trị Liệu; hãy tránh vùng ô nhiễm.",
    [1046805668207616] = "Phạm vi của hai đòn đánh chắc chắn khác nhau; <Highlight>quan sát cảnh báo phạm vi của đòn đầu</> rồi di chuyển né tránh.",
    [1046805668207872] = "Quan sát vị trí và động tác ra đòn của Thổ Ma Tượng. Phán đoán <Highlight>phạm vi tấn công</> kế tiếp rồi di chuyển né tránh.",
    [1046805668208128] = "Quan sát <Highlight>cảnh báo chuyển hướng</> và <Highlight>cảnh báo vị trí ban đầu</>; khuyến nghị ngừng tấn công, tập trung di chuyển né tránh.",
    [1046805668208640] = "Quan sát vị trí cảnh báo Sóng Âm, né theo <Highlight>thứ tự nhất định</> để tránh bị Năng Lượng xung kích.",
    [1046805668208896] = "Người chơi bị đánh dấu hãy nấp sau cột đá trên sân, dẫn Vua Khiêu Vũ <Disable>đâm vào cột đá</> để khiến hắn bị Choáng.",
    [1046805668209152] = "Quan sát màu Nốt Nhạc của bản thân; trước khi hết giờ, đi tới <Disable>Sàn Nhảy đúng màu tương ứng</> để giảm lượng sát thương chịu vào.",
    [1046805668209408] = "Trong giai đoạn này, trước khi hết đếm ngược cần chuyển mục tiêu và hạ <Disable>ít nhất 2 Khỉ Đầu Chó Nhỏ</> để lấy đủ Nốt Nhạc, rồi theo gợi ý Bản Nhạc <Disable>nhặt theo thứ tự</> để hoàn thành cơ chế.",
    [1046805668209664] = "Người chơi vừa né đòn của Vượn Vua Khiêu Vũ vừa nhặt Nốt Nhạc để nhận Điểm Vũ Lực.",
    [1046805668209920] = "Dựa theo động tác của Vua Nhảy Baboon, chọn kỹ năng vũ đạo tương ứng để bắt kịp nhịp của Vua Nhảy.",
    [1046805668210176] = "Khi cảnh báo xuất hiện, người chơi nên <Highlight>rời xa nhau</> và <Highlight>quy hoạch hợp lý vị trí xuất hiện của giá sách</>.",
    [1046805668210432] = "Sau khi bị chọn làm mục tiêu Ngưng Thị, người chơi cần tìm giá sách gần nhất và nấp sau đó, <Highlight>dùng giá sách chặn đòn laser khóa mục tiêu</>.",
    [1046805668210688] = "Khi Carl Edgar giẫm lên “Bẫy Tà Nhãn”, quá trình hấp thụ sức mạnh sẽ bị gián đoạn; người chơi bị truy đuổi nên <Highlight>dẫn quái vật giẫm bẫy</>.",
    [1046805668210944] = "Trước khi Vẫn Tinh chạm đất, người chơi nên <Highlight>nhảy</> để <Highlight>chạm</> nó từ sớm, ngăn nó rơi xuống mặt đất.",
    [1046805668211200] = "Chú ý <Highlight>mức Xâm Thực</> của Dấu Ấn Tà Ác trên người, tránh tích lũy tới 100%.",
    [1046805668211712] = "Sau khi người chơi biến thành Táo sắp nổ, trên sân sẽ tạo hai <Highlight>Vùng An Toàn Người Lùn</>. Người biến thành Táo cần nhanh chóng <Highlight>núp vào Vùng An Toàn</> để tránh làm bị thương đồng đội.",
    [1046805668211968] = "Người Lùn sẽ dựng Lá Chắn rộng lớn; tất cả người chơi nhanh chóng vào trong và <Highlight>tản vị trí trong Lá Chắn</>.",
    [1046805668212224] = "Mỗi Vùng An Toàn Người Lùn <Highlight>chỉ bảo hộ được một người</>; cần <Highlight>lên kế hoạch vị trí từ trước</> và lần lượt vào vòng.",
    [1046805668212480] = "Người chơi bị truy sát <Highlight>dụ Kỵ Sĩ Táo giẫm Bẫy Thú</>; những người khác <Highlight>tập trung hỏa lực vào Bẫy Thú trên sân</> để biến chúng thành trạng thái có thể kích hoạt. Sau khi Kỵ Sĩ Táo ngã, đừng quên <Highlight>nhặt Đại Chùy để đột kích</>.",
    [1046805668212736] = "Khi đồng đội bị xung phong, người chơi cần <Highlight>chủ động tiến vào đường lao</> để chia Sát Thương.",
    [1046805668212992] = "Người chơi cần <Highlight>kiểm soát khoảng cách với nhau</>, né các đòn Sát Thương phạm vi khi ở trạng thái Nối Cặp.",
    [1046805668213248] = "Người chơi cần nhanh chóng <Highlight>tập trung hỏa lực vào Phục Vụ</>, sau đó <Highlight>tới gần xe đồ ăn</>, nhặt bánh rồi <Highlight>ném bánh tấn công</> Hoàng Tử Ếch, hoặc <Highlight>đẩy xe đâm</> Hoàng Tử Ếch.",
    [1046805668213504] = "Nhanh chóng <Highlight>tới khu sân khấu của mình</>, <Highlight>quan sát hướng di chuyển của bạn nhảy</> rồi đi theo <Highlight>đúng hướng</>, đồng thời né vụ nổ dưới chân. <Highlight>Đứng yên hoặc đi sai hướng đều rất nguy hiểm</>!",
    [1046805668213760] = "Dùng <Highlight>Ném Đồng Vàng</> để cho người nghèo đủ Đồng Vàng Lý Trí; khi hồi phục Lý Trí, họ sẽ <Highlight>chuyển sang phe ta hỗ trợ chiến đấu</>.",
    [1046805668214016] = "Dùng Pháo Đài Tiền Tệ <Highlight>Ba Điểm Một Đường bắn đạn cường hóa</> để phá khiên hiệu quả.",
    [1046805668214272] = "Quan sát kỹ bong bóng khẩu hiệu tuyên truyền trên đầu rồi nhanh chóng đứng vào <Highlight>Khu Chống Lừa Đảo</>. Hết đếm ngược, vùng nguy hiểm sẽ <Disable>phát nổ và giảm mạnh Sinh Mệnh</>.",
    [1046805668214528] = "<Highlight>Nghề Phòng Hộ</> cần đứng <Highlight>phía trước</> Ray Bieber để chặn sát thương tia cho những người khác.",
    [1046805668214784] = "<Highlight>Nghề Phòng Hộ</> cần đứng <Highlight>phía trước</> Riel Bieber, bật kỹ năng Giảm Thương để chặn Sát Thương tia sáng thay người khác; <Highlight>Nghề Hồi Phục</> cũng cần chú ý lượng Máu của Nghề Phòng Hộ.",
    [1046805668215040] = "Nhanh chóng <Highlight>tập trung chia sát thương</>.",
    [1046805668215296] = "Nhanh chóng <Highlight>tập trung chia sát thương</>; sau khi chia, <Highlight>quan sát đường nối</> và <Highlight>tránh xung phong làm đứt</> đường nối.",
    [1046805668215552] = "Dẫn Vật Hiến Tế rời khỏi nguy hiểm và kịp thời <Highlight>tiêu diệt Ác Ma</> mới có thể ngắt nghi thức!",
    [1046805668215808] = "Dẫn Vật Hiến Tế vào <Highlight>Vùng An Toàn</>; sau khi đủ số Vật Hiến Tế được cứu rỗi, Johnny sẽ rơi vào Suy Yếu.",
    [1046805668216064] = "Dùng <Highlight>kỹ năng Dẫn Dắt Cừu Non</> giúp Vật Hiến Tế <Highlight>rời khỏi vùng nguy hiểm</>, đồng thời kịp thời <Highlight>Trị Liệu</> Vật Hiến Tế còn ít Máu!",
    [1046805668216320] = "Phi Phàm Giả bị khóa mục tiêu hãy <Highlight>di chuyển ra rìa chiến trường</>, tránh ảnh hưởng khu vực trung tâm.",
    [1046805668216832] = "<Highlight>Chiến Sĩ</> cần chú ý thời điểm Kỹ Năng Kết Liễu đánh trúng Cự Long; các Phi Phàm Giả khác hãy <Highlight>tránh xa</> đường di chuyển của Cự Long.",
    [1046805668217088] = "Phi Phàm Giả cần <Highlight>đi vào Vùng Phù Văn</> để kích hoạt; chú ý <Highlight>thứ tự Phù Văn</> và kích hoạt theo đúng trình tự.",
    [1046805668217344] = "Phi Phàm Giả cần <Highlight>đi vào Vùng Phù Văn</> để kích hoạt.",
    [1046805668217600] = "Phi Phàm Giả cần tương tác với 6 <Highlight>Vũ Công</> để nhận <Highlight>Kỹ Năng Khiêu Vũ tạm thời</> và né Sát Thương.",
    [1046805668217856] = "Phi Phàm Giả <Highlight>có điệu nhảy</> cần vào <Highlight>Vũ Trận tương ứng để nhảy</>.",
    [1046805668218112] = "Phi Phàm Giả cần <Highlight>tìm và đánh bại 4 Vũ Công này</>, sau đó <Highlight>nhảy</> tại vị trí ban đầu của 4 Vũ Công để tiếp nối điệu nhảy.",
    [1046805668218880] = "Tập trung phá <Highlight>toàn bộ Mảnh Tàn Chiến Hỏa</>; mỗi Phi Phàm Giả đều cần <Highlight>hoàn thành thu thập Năng Lượng Chinh Phục</>, rồi tương tác với Phù Văn để bắt đầu cầu nguyện.",
    [1046805668219648] = "Cần một Phi Phàm Giả khác có <Highlight>điệu nhảy tương ứng</> đứng <Highlight>trước mặt vũ công và nhảy</> để <Highlight>chặn</> đòn xung phong của vũ công.",
    [1046805668219904] = "Phi Phàm Giả cần <Highlight>tìm và đánh bại 4 Vũ Công này</>, sau đó <Highlight>nhảy tại vị trí ban đầu của 4 Vũ Công</> để tiếp nối điệu nhảy. Phi Phàm Giả sở hữu kỹ năng <Highlight>cùng điệu nhảy</> cần vào <Highlight>Vũ Trận để nhảy</>.",
    [1046805668220928] = "Chú ý hướng xoay của tia và kịp thời nhảy né.",
    [1046805668221184] = "Dụ “Mũi Khoan” giẫm vào Lôi Trì, cộng đủ 4 tầng Quá Tải để khiến nó bị Choáng.",
    [1046805668221440] = "Truyền Lôi Điện từ Thánh Tiêu Dẫn Điện đã kích hoạt, nạp năng lượng cho toàn bộ Thánh Tiêu và phá Màn Chắn Cách Điện.",
    [1046805668221952] = "Dẫn Cầu Điện vào Vũng Nước tạo Lôi Trì; dụ “Mũi Khoan” giẫm lên Lôi Trì để cộng đủ 4 tầng Quá Tải, khiến nó Choáng.",
    [1046805668222464] = "Dẫn Hồn Liệp Khuyển Đỏ Thẫm vào Bẫy Thú rồi đánh bại; nó sẽ rơi vật phẩm có thể nhặt <Highlight>【Chuông】</>.",
    [1046805668222720] = "Phi Phàm Giả bị <Highlight>【Truy Liệp】</> chỉ định cần liên tục dùng <Highlight>【Phấn Chấn Lại】</> để thoát khống chế. Nhanh chóng <Highlight>chuyển mục tiêu sang Nam Bộc Dị Biến</>. Người giữ 【Chuông】 cần áp sát Linh Hồn Khuyển Đỏ Thẫm và dùng <Highlight>【Lắc Chuông】</> để chuyển mục tiêu vồ giết của nó sang Liệp Khuyển Dị Hóa. Khi 2 Linh Hồn Khuyển Đỏ Thẫm vồ giết Liệp Khuyển Dị Hóa thành công, Liệp Khuyển Dị Hóa sẽ <Highlight>tê liệt 10 giây</>.",
    [1046805668222976] = "Khi chiến đấu, cố gắng <Highlight>né đòn đánh phạm vi</>; nếu có người bị Áp Chế, cần <Highlight>Trị Liệu liên tục</>.",
