    [1073124154636032] = "Đi tới Mở Khóa Thiên Phú",
    [1073124154637568] = "Thảo Phạt Cự Long",
    [1073124154637824] = "Đánh Lui Cự Long · Hình Chiếu",
    [1073124154638080] = "Trống chinh phạt đã vang lên, Cự Long · Hình Chiếu chiếm giữ trung tâm Vương Thành của Thành Săn Rồng. Sống sót và gây sát thương trong phạm vi 40m quanh Cự Long sẽ cộng Sát Thương Quyền Sở Hữu cho đoàn của bạn. Khi Cự Long bị đánh lui, đoàn có Sát Thương Quyền Sở Hữu hợp lệ cao nhất nhận thưởng đấu giá.",
    [1073124154638336] = "Đến Thảo Phạt",
    [1073124154638592] = "Cự Long sau %M:%S",
    [1073124154645760] = "Thuộc tính có hiệu lực <HighLight>%d%%</>.",
    [1073124154646272] = "Thuộc tính Bí Ngẫu có hiệu lực <Dominate>%d%%</>.",
    [1073124154654208] = "Số lần mở chia sẻ còn lại hôm nay: <Remaining>%d/%d lần</>",
    [1073124154660608] = "Số lượt chinh phạt còn lại của từng Boss. Hạ bất kỳ Boss nào dưới đây: Tiến Độ Chinh Phạt +1.",
    [1073124154667264] = "%s giờ sáng mở khóa nâng cấp.",
    [1073124154678272] = "Sau <Highlight>%d</> lần Tái Tạo, chắc chắn xuất hiện Ân Tứ có <Highlight>3 Dòng Thuộc Tính Phi Phàm</>.",
    [1073124154681088] = "Thảo Phạt Cự Long <Highlight>[Đấu Giá Đoàn Đội]</>: 19:10, %d/%d",
    [1077523542708736] = "Một “Ma Nữ” chết tiệt sắp Mất Kiểm Soát. Cầm lấy chiếc còng Vật Phong Ấn này! Bạn có thể dùng Linh Tính thông qua nó để tạm thời áp chế tiến độ Mất Kiểm Soát.",
    [1077523542710528] = "Sự kiện giới hạn thời gian có thể nhận giải may mắn <Highlight>Phiếu Mua 0 Đồng</>, dùng để <Highlight>đổi miễn phí bất kỳ Ngoại Trang bán trực tiếp nào trong Thương Thành</>. Tham gia sự kiện Đêm Cuồng Mua có xác suất nhận Rương Bất Ngờ Mặt Tối Thành Phố. Ở đây không có quy tắc, chỉ có Linh Tính đầy đất và những kẻ còn điên hơn bạn.",
    [1090717413804032] = "Trấn An",
    [1090717413804288] = "Long Uy",
    [1090717413806336] = "Thần Hy",
    [1090717682239488] = "Cường Hóa Trị Liệu",
    [1090717682239744] = "Cường Hóa Sát Thương",
    [1090717682240256] = "Cường Kỹ",
    [1090717950675456] = "Dùng Lá Bài Vàng Vận Mệnh để cường hóa khả năng gây sát thương bằng Đánh Thường của Thầy Bói.",
    [1090717950675712] = "Dùng Lá Bài Xanh Linh Tính để cường hóa khả năng gây sát thương bằng Kỹ Năng Kết Liễu của Thầy Bói.",
    [1090717950677248] = "Cường hóa năng lực gây sát thương của Chiến Sĩ.",
    [1090785059539968] = "Thanh Tẩy",
    [1090785059540224] = "Thần Danh",
    [1090785059542528] = "Thần Tứ",
    [1090785059544576] = "Trị Liệu",
    [1090785059554816] = "Tàn Ảnh",
    [1090785059562752] = "Suy Bại",
    [1090786670151168] = "Tăng Xuyên Thấu, Chặn Đòn và Phòng Thủ.",
    [1090786670151424] = "Tăng Tấn Công, Phòng Thủ và Chặn Đòn.",
    [1090786670151680] = "Tăng Xuyên Thấu, Tấn Công và Chặn Đòn.",
    [1090786670151936] = "Tăng Tấn Công, Xuyên Thấu và Phòng Thủ.",
    [1090786670152448] = "Sau khi dùng <HyperLink stylename=\"M_Link\" u=\"86011040\" color=\"#f4a067\">Trục Nhật</> hoặc kỹ năng nhánh của nó, 3 lần <HyperLink stylename=\"M_Link\" u=\"86011070\" color=\"#f4a067\">Trừng Phạt</> tiếp theo trong 10 giây gây thêm 20% sát thương.;\nTrong phạm vi <HyperLink stylename=\"M_Link\" u=\"86011030\" color=\"#f4a067\">Nhật Thệ</>, dùng <HyperLink stylename=\"M_Link\" u=\"86011070\" color=\"#f4a067\">Trừng Phạt</> sẽ giảm 1.5 giây hồi chiêu của <HyperLink stylename=\"M_Link\" u=\"86011030\" color=\"#f4a067\">Nhật Thệ</>.",
    [1090786670152704] = "Hiệu quả và giới hạn buff lên thành viên đội của <HyperLink stylename=\"M_Link\" u=\"86015020\" color=\"#f4a067\">Tài Quyết</> tăng 66.7%. (Cần kích hoạt nút Vùng Đất Vô Ám trước);\nKhi <HyperLink stylename=\"M_Link\" u=\"86011020\" color=\"#f4a067\">Cuồng Phủ</> gây sát thương, có 65% xác suất gây Chậm 25% trong 2 giây.",
    [1090786670152960] = "<HyperLink stylename=\"M_Link\" u=\"86011040\" color=\"#f4a067\">Trục Nhật</> nhận kỹ năng nhánh <HighLight>Trục Quang</>: nhanh chóng đột kích mục tiêu, Hất Ngã mục tiêu và kẻ địch xung quanh, đồng thời gây Giảm Trị Liệu và Trì Trệ. Kỹ năng nhánh có 2 lần tích năng, thời gian tích năng 10 giây.;\nKỹ năng giai đoạn hai của <HyperLink stylename=\"M_Link\" u=\"86011060\" color=\"#f4a067\">Thần Giáp</> nhận thêm <Orange>Bá Thể</> ngắn.",
    [1090786670153216] = "<HyperLink stylename=\"M_Link\" u=\"86011050\" color=\"#f4a067\">Tịnh Quang</> nhận kỹ năng nhánh <HighLight>Thánh Diễm</>:\nTịnh hóa người chơi địch bị tiêu tán trong phạm vi, gây nổ và sát thương các mục tiêu còn sống. Kỹ năng nhánh hồi chiêu 8 giây.;\nHiệu ứng <HyperLink stylename=\"M_Link\" u=\"86015020\" color=\"#f4a067\">Tài Quyết</> thay đổi: Trong trạng thái <HighLight>Liệt Dương</>, thành viên tiểu đội trong bán kính 70m tăng 3% Tăng Thương; Tấn Công/Cường Hóa Kỹ Năng tăng 15/2.16 điểm mỗi cấp kỹ năng, tổng tăng không vượt 10% Tấn Công/Cường Hóa Kỹ Năng của Ca Tụng Giả.",
    [1090786670154752] = "<HyperLink stylename=\"M_Link\" u=\"86013010\" color=\"#f4a067\">Phán Xét</> nhận hiệu ứng bị động:\n    Mỗi lần <HyperLink stylename=\"M_Link\" u=\"86011020\" color=\"#f4a067\">Cuồng Phủ</>, <HyperLink stylename=\"M_Link\" u=\"86011010\" color=\"#f4a067\">Tịnh Trảm</>, <HyperLink stylename=\"M_Link\" u=\"86011040\" color=\"#f4a067\">Trục Nhật</> trúng mục tiêu, bản thân nhận 1 tầng Vô Tận. Đủ 12 tầng sẽ vào trạng thái Liệt Dương trong 4 giây.\n    Thời gian Liệt Dương này cộng dồn với thời gian hiệu ứng chủ động của <HyperLink stylename=\"M_Link\" u=\"86013010\" color=\"#f4a067\">Phán Xét</>.;\nHiệu ứng <HyperLink stylename=\"M_Link\" u=\"86015020\" color=\"#f4a067\">Tài Quyết</> được cường hóa: Mục tiêu <HighLight>Dị Giáo</> chịu thêm 10% sát thương từ Ca Tụng Giả.",
    [1090786670155008] = "Sát thương của <HyperLink stylename=\"M_Link\" u=\"86011020\" color=\"#f4a067\">Cuồng Phủ</> tăng 15%, khoảng cách kích hoạt hiệu ứng giảm từ 0.8 giây xuống 0.6 giây, xác suất cơ bản gây Trì Trệ tăng lên 90%.;\n<HyperLink stylename=\"M_Link\" u=\"86011010\" color=\"#f4a067\">Tịnh Trảm</> trở thành kỹ năng tích trữ 2 lần, đồng thời sát thương tăng 15%.",
    [1090786670155264] = "<HyperLink stylename=\"M_Link\" u=\"86011050\" color=\"#f4a067\">Tịnh Quang</> tăng thêm Bạo Kích và Xuyên Thấu, hiệu quả Tăng Thương tăng 5%.;\nSát thương của <HyperLink stylename=\"M_Link\" u=\"86011040\" color=\"#f4a067\">Trục Nhật</> tăng 15%.",
    [1090786670155520] = "<HyperLink stylename=\"M_Link\" u=\"86011080\" color=\"#f4a067\">Vô Ám Thương</> nhận hiệu ứng <HighLight>Thần Phạt</>: Dựa trên % Sinh Mệnh đã mất của mục tiêu hoặc bản thân cùng Tấn Công Vật Lý của bản thân để gây Sát Thương Vật Lý lên người chơi địch. Sinh Mệnh mục tiêu hoặc bản thân càng thấp, sát thương càng cao, tối đa gây Sát Thương Vật Lý với giá trị cơ sở bằng 100% Tấn Công Vật Lý bản thân. <HighLight>Vô Ám</> có hiệu lực với người chơi địch dưới 40% Sinh Mệnh.;\nHồi chiêu nội tại của <HyperLink stylename=\"M_Link\" u=\"86013010\" color=\"#f4a067\">Liệt Linh</> giảm 30 giây; trong trạng thái, hiệu ứng Trọng Thương giảm từ 80% xuống 75%.;",
    [1090786670156288] = "<HyperLink stylename=\"M_Link\" u=\"86021110\" color=\"#f4a067\">Đọc Tâm</> nhận kỹ năng nhánh mới <HighLight>Trị Tâm</>:\n<HyperLink stylename=\"M_Link\" u=\"86021111\" color=\"#f4a067\">Trị Tâm</> khiến toàn bộ thành viên đội trong phạm vi 25m nhận <HighLight>Dấu Ấn Trị Tâm</> trong 5 giây; có hồi chiêu chung của đội là 20 giây.\n<HighLight>Dấu Ấn Trị Tâm</>: Nhận 20% Giảm Thương. Khi người thi triển dấu gây Trị Liệu, người giữ dấu hồi cố định Sinh Mệnh bằng 80% lượng Trị Liệu đó.",
    [1090786670157312] = "<HyperLink stylename=\"M_Link\" u=\"86023020\" color=\"#f4a067\">Trị Liệu Tâm Lý</> và <HyperLink stylename=\"M_Link\" u=\"86023020\" color=\"#f4a067\">Khiển Thức</> tăng 10% lượng trị liệu. Khi <HyperLink stylename=\"M_Link\" u=\"86023020\" color=\"#f4a067\">Trị Liệu Tâm Lý</> khả dụng, dùng kỹ năng chiến đấu có hiệu ứng trị liệu sẽ tự động thi triển <HyperLink stylename=\"M_Link\" u=\"86023020\" color=\"#f4a067\">Trị Liệu Tâm Lý</>.",
    [1090786670157824] = "<HyperLink stylename=\"M_Link\" u=\"86021080\" color=\"#f4a067\">Ám Thị</> khiến Đỡ Đòn của mục tiêu tăng mạnh trong 5 giây.",
    [1090786670158848] = "Trong vùng <HyperLink stylename=\"M_Link\" u=\"86021030\" color=\"#f4a067\">Mộng Giải</>, đồng minh tăng 5% Giảm Thương. Nếu mỗi lần trị liệu ít hơn 4 mục tiêu, hoàn lại 1 giây hồi chiêu.\nMức suy giảm Trị Liệu mỗi lần nảy của <HyperLink stylename=\"M_Link\" u=\"86021060\" color=\"#f4a067\">Linh Dẫn</> giảm 5%.",
    [1090786670159616] = "Giá trị cơ sở sát thương của <HyperLink stylename=\"M_Link\" u=\"86021010\" color=\"#f4a067\">Động Sát</> tăng 40%, thời gian Tăng Thương giảm còn 8 giây, hiệu quả Tăng Thương tăng 5%.",
    [1090786670160640] = "<HyperLink stylename=\"M_Link\" u=\"86023010\" color=\"#f4a067\">Linh Hoả</> có xác suất cơ bản gây <Orange>Trói Buộc</> tăng lên 75%; thời gian Thôi Miên tăng lên 2.5 giây.",
    [1090786670161152] = "<HyperLink stylename=\"M_Link\" u=\"86021070\" color=\"#f4a067\">Dệt Mộng</> tăng 30% sát thương gây lên mục tiêu đang <HighLight>Dịch Bệnh</>.\nSau khi <HyperLink stylename=\"M_Link\" u=\"86021050\" color=\"#f4a067\">Chấn Nhiếp</> trúng địch, gây Trì Trệ 4 giây.",
    [1090786670162176] = "Sau khi <HyperLink stylename=\"M_Link\" u=\"86020010\" color=\"#f4a067\">Xung Kích Ý Thức</> trúng, thêm 1 tầng <HyperLink stylename=\"M_Link\" u=\"86020010\" color=\"#f4a067\">Ác Mộng</> trong 7 giây. Đủ 3 tầng, Mộng Yểm bùng nổ, gây Sát Thương Ma Pháp bằng 85% hiệu quả cơ sở cho mục tiêu và kẻ địch trong 3m quanh đó.\nKhi gây sát thương lên mục tiêu chịu ảnh hưởng của <HyperLink stylename=\"M_Link\" u=\"86021020\" color=\"#f4a067\">Thần Ôn</>, thêm 1 đòn Hiệp Đồng, gây Sát Thương Ma Pháp bằng 85% hiệu quả cơ sở.",
    [1090786670162944] = "Hồi chiêu của <HyperLink stylename=\"M_Link\" u=\"86033010\" color=\"#f4a067\">Số Mệnh</> giảm 3 giây. Sau khi dùng <HighLight>Số Mệnh</>, xác suất Đánh Thường áp <HighLight>Dấu Ấn Ngu Lộng</> tăng lên 100%.",
    [1090786670163456] = "Khi dùng lần 1 của <HyperLink stylename=\"M_Link\" u=\"86031070\" color=\"#f4a067\">Hỏa Diễm Dược</>, Tốc Độ Di Chuyển tăng 50% trong 4 giây.\nTrước mỗi lần chịu sát thương, nhận <HighLight>Khiên</> trong 8 giây và tăng 50% Tốc Độ Di Chuyển trong 4 giây. Hiệu ứng này hồi chiêu 20 giây.",
    [1090786670163968] = "Đòn thứ ba của <HyperLink stylename=\"M_Link\" u=\"86031010\" color=\"#f4a067\">Phi Bài</> gây <HighLight>Chảy Máu</> trong 6 giây, mỗi giây mất 2% Giới Hạn Sinh Mệnh của người thi triển (không vượt 60% Tấn Công của người thi triển).\nKhi dùng đòn hai của <HyperLink stylename=\"M_Link\" u=\"86031070\" color=\"#f4a067\">Hỏa Diễm Khiêu Dược</>, giải <HighLight>hiệu ứng khống chế</> trên bản thân.",
    [1090786670164480] = "Sau khi dùng <HyperLink stylename=\"M_Link\" u=\"86033010\" color=\"#f4a067\">Số Mệnh</>, trong 16 giây Tốc Độ Đánh Đánh Thường +20%, giá trị cơ sở Sát Thương Đánh Thường +20%, và trong 10 giây Bạo Kích bản thân tăng.\nGiá trị cơ sở sát thương của <HyperLink stylename=\"M_Link\" u=\"86031020\" color=\"#f4a067\">Trận Tarot</> +10%, có 85% xác suất làm mục tiêu chính <HighLight>Chậm</> 50% trong 2.5 giây.",
    [1090786670165248] = "Hồi chiêu của <HyperLink stylename=\"M_Link\" u=\"86033020\" color=\"#f4a067\">Bộc Phát Linh Tính</> giảm 3 giây; sau khi thi triển, Tấn Công bản thân tăng trong 10 giây.",
    [1090786670165760] = "Trong thời gian <HyperLink stylename=\"M_Link\" u=\"86031030\" color=\"#f4a067\">Đạn Khí</>, Tốc Độ Di Chuyển +25%; có thể tấn công thêm 2 kẻ địch trong 3m quanh mục tiêu. Mỗi đòn có 50% xác suất cơ bản gây <HighLight>Trì Trệ</> và <HighLight>Chậm</> 50% trong 1 giây.\nMỗi lần <HyperLink stylename=\"M_Link\" u=\"86030010\" color=\"#f4a067\">Mở Bài</> gây sát thương sẽ giảm 0.5 giây hồi chiêu <HighLight>Đạn Khí</>.",
    [1090786670166272] = "Khi <HighLight>Năng Lượng Lá Bài</> đầy 5 điểm, <HighLight>Xuyên Thấu</> bản thân tăng trong 5 giây;\nnếu đồng thời kích hoạt node <HighLight>Thứ Tự Bài Hỗn Độn</>, khi đầy 4 điểm <HighLight>Xuyên Thấu</> bản thân cũng tăng trong 5 giây.\nHiệu quả <HyperLink stylename=\"M_Link\" u=\"86033020\" color=\"#f4a067\">Bộc Phát Linh Tính</> <HighLight>Tăng Thương</> tăng 5%.",
    [1090786670166784] = "<HyperLink stylename=\"M_Link\" u=\"86033030\" color=\"#f4a067\">Xào Bài</> cần ít hơn 1 điểm <HighLight>Năng Lượng Lá Bài</>, giá trị cơ sở sát thương +20%; đòn đầu có 90% xác suất <HighLight>Cấm Cố</> mục tiêu trong 0.8 giây.\n<HyperLink stylename=\"M_Link\" u=\"86030010\" color=\"#f4a067\">Mở Bài</> cứ 45 giây nhận <HighLight>Cảnh Báo Linh Tính</>, có thể giải 1 hiệu ứng khống chế; sau khi kích hoạt, Tốc Độ Di Chuyển bản thân +25% trong 2 giây.",
    [1090786670172160] = "Ở dạng Phòng Thủ, hiệu ứng Giảm Thương bị động của <HyperLink stylename=\"M_Link\" u=\"86065010\" color=\"#f4a067\">Bậc Thầy Vũ Khí</> tăng lên 30%.\n<HyperLink stylename=\"M_Link\" u=\"86061060\" color=\"#f4a067\">Tường Thành Hộ Vệ</> nhận nhánh mới <HyperLink stylename=\"M_Link\" u=\"86061063\" color=\"#f4a067\">Bích Lũy Hộ Vệ</>: Triển khai lĩnh vực, tạo Khiên lớn và 15% Giảm Thương cho 2 đồng minh có Máu thấp nhất trong phạm vi 30 m. Giá trị Khiên tăng theo số <HighLight>Khắc Ấn Hoàng Hôn</> tiêu hao.",
    [1090786670173184] = "Ở Hình Thái Phòng Thủ, mỗi đoạn của <HyperLink stylename=\"M_Link\" u=\"86061080\" color=\"#f4a067\">Nộ Ý Kích</> đều tăng Chuyên Phòng Quái Vật và hồi Sinh Mệnh. Khi dùng kỹ năng, mỗi 1/2 <HighLight>Dấu Ấn Hoàng Hôn</> tiêu hao sẽ tăng thêm 15%/30% Chuyên Phòng Quái Vật và 20%/50% lượng hồi phục.\n<HyperLink stylename=\"M_Link\" u=\"86061023\" color=\"#f4a067\">Hiệu Lệnh Vương Đình</> khiến mục tiêu địch trúng kỹ năng giảm 15% Tấn Công trong 5 giây.",
    [1090786670173696] = "Sau khi chịu sát thương, nếu Sinh Mệnh hiện tại dưới 50% và <HyperLink stylename=\"M_Link\" u=\"86061040\" color=\"#f4a067\">Giáp Bình Minh</> không đang hồi chiêu, tự động dùng <HyperLink stylename=\"M_Link\" u=\"86061040\" color=\"#f4a067\">Giáp Bình Minh</>; vẫn có hiệu lực ngay cả khi không mang <HyperLink stylename=\"M_Link\" u=\"86061040\" color=\"#f4a067\">Giáp Bình Minh</>.\n<HyperLink stylename=\"M_Link\" u=\"86061020\" color=\"#f4a067\">Liệp Ma Trảm</> nhận nhánh mới <HyperLink stylename=\"M_Link\" u=\"86061060\" color=\"#f4a067\">Khu Ma Vệ Trảm</>: Ở Hình Thái Phòng Thủ, dùng lên địch có hiệu quả như Liệp Ma Trảm gốc; dùng lên đồng minh sẽ giải Khống Chế Nhẹ và Chậm, đồng thời cho 20% Giảm Thương và 25% Tốc Độ Di Chuyển trong 5 giây.",
    [1090786670174720] = "Đòn đầu của <HyperLink stylename=\"M_Link\" u=\"86061030\" color=\"#f4a067\">Cuồng Phong</> gây <HighLight>Trì Trệ</> 2 giây lên người chơi trúng đòn. Trong thời gian Cuồng Phong duy trì, bản thân nhận 15% Giảm Thương và tăng 15% Tốc Độ Di Chuyển.\nSau khi kiếm trận của <HyperLink stylename=\"M_Link\" u=\"86061110\" color=\"#f4a067\">Cự Trảm</> phát nổ, Sức Mạnh Hoàng Hôn còn lưu lại, liên tục hút kẻ địch trong phạm vi trong 2 giây.",
    [1090786670175488] = "Thời lượng tối đa của <HighLight>Suy Bại</> tăng 15 giây.\nThời gian Cấm Cố của <HyperLink stylename=\"M_Link\" u=\"86061020\" color=\"#f4a067\">Săn Ma Thuấn Trảm</> kéo dài lên 3 giây.",
    [1090786670176512] = "Ở Hình Thái Công Kích, khi <HyperLink stylename=\"M_Link\" u=\"86061080\" color=\"#f4a067\">Nộ Ý Kích</> trúng kẻ địch đang có <HighLight>Suy Bại</>, gây thêm sát thương truy kích phạm vi nhỏ và kéo dài <HighLight>Suy Bại</> thêm 5 giây.\nỞ Hình Thái Công Kích, dùng <HyperLink stylename=\"M_Link\" u=\"86061023\" color=\"#f4a067\">Hiệu Lệnh Vương Đình</> sau Liệp Ma Trảm cũng có thể đánh ngã kẻ địch phía trước và vào <HighLight>Cuồng Bạo</> trong 6 giây. Trong <HighLight>Cuồng Bạo</>, tấn công trúng địch hồi Sinh Mệnh cho bản thân; hiệu ứng này có hồi chiêu nội tại <Highlight>1</> giây.",
    [1090786670177024] = "<HyperLink stylename=\"M_Link\" u=\"86061100\" color=\"#f4a067\">Mộ Sắc Trảm</> kéo dài thời gian Hất Tung người chơi địch lên 3 giây. Khi dùng <HyperLink stylename=\"M_Link\" u=\"86061100\" color=\"#f4a067\">Mộ Sắc Trảm</>, nếu <HyperLink stylename=\"M_Link\" u=\"86061050\" color=\"#f4a067\">Tế Kiếm Ngân Bạch</> không trong hồi chiêu thì tự động thi triển <HyperLink stylename=\"M_Link\" u=\"86061050\" color=\"#f4a067\">Tế Kiếm Ngân Bạch</>; vẫn có hiệu lực ngay cả khi không mang <HyperLink stylename=\"M_Link\" u=\"86061050\" color=\"#f4a067\">Tế Kiếm Ngân Bạch</>.",
    [1090786670178048] = "Mỗi lần <HyperLink stylename=\"M_Link\" u=\"86063020\" color=\"#f4a067\">Lưỡi Đao Điêu Tàn</> trúng sẽ gây <HighLight>Chậm</> và sau khi dùng, cứ <HighLight>2</> giây nhận <HighLight>1</> <HighLight>Dấu Ấn Hoàng Hôn</>, kéo dài 6 giây.\n<HyperLink stylename=\"M_Link\" u=\"86061110\" color=\"#f4a067\">Cự Trảm</> ngắt mục tiêu trúng đòn 0.5 giây; ở Hình Thái Công Kích gây thêm Câm Lặng 2 giây và <HighLight>Suy Bại</> 6 giây, đồng thời tăng <HighLight>10%</> sát thương gây lên kẻ địch đang <HighLight>Suy Bại</>.",
    [1090786670179072] = "<HyperLink stylename=\"M_Link\" u=\"86071010\" color=\"#f4a067\">Trí Nhân</> nhận thêm 10 điểm <HighLight>Tri Thức Thần Bí</>;\nSát thương của <HyperLink stylename=\"M_Link\" u=\"86071030\" color=\"#f4a067\">Tinh Sa</> tăng 50%, nhận thêm 10 điểm <HighLight>Tri Thức Thần Bí</>, đồng thời tăng lượng giảm Xuyên Thấu.",
    [1090786670179840] = "Xác suất kích hoạt <HyperLink stylename=\"M_Link\" u=\"86075010\" color=\"#f4a067\">Vòng Xoáy Tri Thức</> tăng 10%; khi kích hoạt <HyperLink stylename=\"M_Link\" u=\"86075010\" color=\"#f4a067\">Vòng Xoáy Tri Thức</> nhận thêm 5 <HighLight>Tri Thức Thần Bí</>; sau khi dùng Đánh Thường Cường Hóa <HyperLink stylename=\"M_Link\" u=\"86070040\" color=\"#f4a067\">Thương Longinus</> nhận <Orange>Bá Thể</> trong 2.5 giây.",
    [1090786670180608] = "Sát thương của <HyperLink stylename=\"M_Link\" u=\"86071020\" color=\"#f4a067\">Quang Khúc</> tăng 50%, nhận thêm 10 điểm <HighLight>Tri Thức Thần Bí</>;\nThời gian Bá Thể của <HyperLink stylename=\"M_Link\" u=\"86072010\" color=\"#f4a067\">Xuyên Toa Tinh Hải</> tăng lên 4.5 giây.",
    [1090786670182400] = "<HyperLink stylename=\"M_Link\" u=\"86073010\" color=\"#f4a067\">Tin Tuyến</> đổi thành xoay quanh bản thân và di chuyển theo bản thân. Trong thời gian kỹ năng, bản thân nhận 10% Giảm Thương và tăng 25% Tốc Độ Di Chuyển; hiệu ứng tối đa kéo dài 7 giây; hiệu ứng Đẩy Lùi của <HyperLink stylename=\"M_Link\" u=\"86071060\" color=\"#f4a067\">Con Mắt Dòm Bí</> đổi thành Hất Tung với xác suất cơ bản 100%.",
    [1090786670183168] = "Lượng hấp thụ sát thương của <HyperLink stylename=\"M_Link\" u=\"86071050\" color=\"#f4a067\">Hoàng Y</> tăng 25%; mỗi đòn tấn công của Huyễn Tượng Thần Bí do <HyperLink stylename=\"M_Link\" u=\"86071070\" color=\"#f4a067\">Tái Hiện Thần Bí</> triệu hồi hồi 5 điểm <HighLight>Tri Thức Thần Bí</>; trong thời gian dùng <HyperLink stylename=\"M_Link\" u=\"86073010\" color=\"#f4a067\">Tin Tuyến</>, bản thân nhận thêm 10% Giảm Thương, hiệu ứng tối đa kéo dài 7 giây.",
    [1090786670183936] = "Sau khi dùng <HyperLink stylename=\"M_Link\" u=\"86071080\" color=\"#f4a067\">Kỳ Nguyệt</>, nhận <HighLight>Vượt Ngưỡng Giới Hạn</> trong 10 giây.\n<FaintYellow>Vượt Ngưỡng Giới Hạn</>: Mỗi lần dùng kỹ năng hoặc Đánh Thường, giảm 0.5 giây hồi chiêu của các kỹ năng đang hồi; mỗi 1 giây tối đa giảm 0.5 giây.",
    [1090786670184704] = "<HyperLink stylename=\"M_Link\" u=\"86073010\" color=\"#f4a067\">Tin Tuyến</>: <HighLight>Tri Thức Thần Bí</> tiêu hao ban đầu và <HighLight>Tri Thức Thần Bí</> tiêu hao tăng dần về sau đều giảm 3 điểm; sát thương của <HyperLink stylename=\"M_Link\" u=\"86071060\" color=\"#f4a067\">Con Mắt Dòm Bí</> tăng 30%.",
    [1090789622942465] = "Sau khi dùng <HyperLink stylename=\"M_Link\" u=\"86011040\" color=\"#f4a067\">Trục Nhật</> hoặc kỹ năng nhánh của nó, 3 lần <HyperLink stylename=\"M_Link\" u=\"86011070\" color=\"#f4a067\">Trừng Phạt</> tiếp theo trong 10 giây gây thêm 20% sát thương.",
    [1090789622942466] = "Trong phạm vi <HyperLink stylename=\"M_Link\" u=\"86011030\" color=\"#f4a067\">Nhật Thệ</>, dùng <HyperLink stylename=\"M_Link\" u=\"86011070\" color=\"#f4a067\">Trừng Phạt</> sẽ giảm 1.5 giây hồi chiêu của <HyperLink stylename=\"M_Link\" u=\"86011030\" color=\"#f4a067\">Nhật Thệ</>.",
    [1090789622942722] = "Khi <HyperLink stylename=\"M_Link\" u=\"86011020\" color=\"#f4a067\">Cuồng Phủ</> gây sát thương, có 65% xác suất gây Chậm 25% trong 2 giây.",
    [1090789622942723] = "<HyperLink stylename=\"M_Link\" u=\"86011050\" color=\"#f4a067\">Tịnh Quang</> nhận kỹ năng nhánh <HighLight>Thánh Diễm</>:\nTịnh hóa người chơi địch bị tiêu tán trong phạm vi, gây nổ và sát thương các mục tiêu còn sống. Kỹ năng nhánh hồi chiêu 8 giây.",
    [1090789622942977] = "<HyperLink stylename=\"M_Link\" u=\"86011040\" color=\"#f4a067\">Trục Nhật</> nhận kỹ năng nhánh <HighLight>Trục Quang</>: nhanh chóng đột kích mục tiêu, Hất Ngã mục tiêu và kẻ địch xung quanh, đồng thời gây Giảm Trị Liệu và Trì Trệ. Kỹ năng nhánh có 2 lần tích năng, thời gian tích năng 10 giây.",
    [1090789622943233] = "Hiệu ứng <HyperLink stylename=\"M_Link\" u=\"86015020\" color=\"#f4a067\">Tài Quyết</> thay đổi: Trong trạng thái <HighLight>Liệt Dương</>, toàn bộ thành viên tiểu đội cùng khu vực tăng 4.5% Tăng Thương; Tấn Công/Cường Hóa Kỹ Năng tăng lần lượt 19.2/2.7 điểm cho mỗi cấp kỹ năng, tổng mức tăng không vượt quá 12% Tấn Công/Cường Hóa Kỹ Năng của Ca Tụng Giả.",
    [1090789622944769] = "<HyperLink stylename=\"M_Link\" u=\"86013010\" color=\"#f4a067\">Phán Xét</> nhận hiệu ứng bị động:\n    Mỗi lần <HyperLink stylename=\"M_Link\" u=\"86011020\" color=\"#f4a067\">Cuồng Phủ</>, <HyperLink stylename=\"M_Link\" u=\"86011010\" color=\"#f4a067\">Tịnh Trảm</>, <HyperLink stylename=\"M_Link\" u=\"86011040\" color=\"#f4a067\">Trục Nhật</> trúng mục tiêu, bản thân nhận 1 tầng Vô Tận. Đủ 12 tầng sẽ vào trạng thái Liệt Dương trong 4 giây.\n    Thời gian Liệt Dương này cộng dồn với thời gian hiệu ứng chủ động của <HyperLink stylename=\"M_Link\" u=\"86013010\" color=\"#f4a067\">Phán Xét</>.",
    [1090789622944770] = "Hiệu ứng <HyperLink stylename=\"M_Link\" u=\"86015020\" color=\"#f4a067\">Tài Quyết</> tăng: mục tiêu <HighLight>Dị Giáo</> chịu thêm 10% sát thương từ Ca Tụng Giả.",
    [1090789622945025] = "Sát thương của <HyperLink stylename=\"M_Link\" u=\"86011020\" color=\"#f4a067\">Cuồng Phủ</> tăng 15%, khoảng cách kích hoạt hiệu ứng giảm từ 0.8 giây xuống 0.6 giây, xác suất cơ bản gây Trì Trệ tăng lên 90%.",
    [1090789622945026] = "<HyperLink stylename=\"M_Link\" u=\"86011010\" color=\"#f4a067\">Tịnh Trảm</> trở thành kỹ năng tích trữ 2 lần, đồng thời sát thương tăng 15%.",
    [1090789622945281] = "<HyperLink stylename=\"M_Link\" u=\"86011050\" color=\"#f4a067\">Tịnh Quang</> tăng thêm Bạo Kích và Xuyên Thấu; hiệu quả Tăng Thương tăng 5%.",
    [1090789622945282] = "Sát Thương do <HyperLink stylename=\"M_Link\" u=\"86011040\" color=\"#f4a067\">Trục Nhật</> gây ra tăng 15%.",
    [1090789622945537] = "<HyperLink stylename=\"M_Link\" u=\"86011080\" color=\"#f4a067\">Vô Ám Thương</> nhận hiệu ứng <HighLight>Thần Phạt</>: gây Sát Thương Vật Lý lên người chơi địch dựa trên % Máu đã mất của mục tiêu hoặc bản thân và Tấn Công Vật Lý của bản thân; Máu mục tiêu hoặc bản thân càng thấp, sát thương càng cao, tối đa gây Sát Thương Vật Lý bằng 100% giá trị cơ bản Tấn Công Vật Lý của bản thân. <HighLight>Vô Ám</> có hiệu lực với người chơi địch dưới 40% Máu.",
    [1090789622945538] = "Hồi chiêu nội tại của <HyperLink stylename=\"M_Link\" u=\"86013010\" color=\"#f4a067\">Hồn Liệt Dương</> giảm 30 giây; trong thời gian trạng thái, hiệu ứng Trọng Thương giảm từ 80% xuống 75%.",
    [1090789622947329] = "<HyperLink stylename=\"M_Link\" u=\"86023020\" color=\"#f4a067\">Trị Liệu Tâm Lý</> tăng 10% lượng trị liệu. Khi <HyperLink stylename=\"M_Link\" u=\"86023020\" color=\"#f4a067\">Trị Liệu Tâm Lý</> khả dụng, dùng kỹ năng chiến đấu có hiệu ứng trị liệu sẽ tự động thi triển <HyperLink stylename=\"M_Link\" u=\"86023020\" color=\"#f4a067\">Trị Liệu Tâm Lý</>.",
    [1090789622947330] = "Lượng Hồi Phục do <HyperLink stylename=\"M_Link\" u=\"86023020\" color=\"#f4a067\">Thao Túng Ý Thức</> tạo ra tăng 10%.",
    [1090789622948865] = "Trong vùng <HyperLink stylename=\"M_Link\" u=\"86021030\" color=\"#f4a067\">Mộng Giải</>, đồng minh tăng 5% Giảm Thương; nếu mỗi lần trị liệu dưới 4 mục tiêu, hoàn lại 1 giây hồi chiêu.",
    [1090789622948866] = "Mức suy giảm Hồi Phục sau mỗi lần nảy của <HyperLink stylename=\"M_Link\" u=\"86021060\" color=\"#f4a067\">Linh Dẫn</> giảm 5%.",
    [1090789622951169] = "<HyperLink stylename=\"M_Link\" u=\"86021070\" color=\"#f4a067\">Dệt Mộng</> tăng 30% sát thương gây lên mục tiêu đang <HighLight>Dịch Bệnh</>.",
    [1090789622951170] = "Sau khi <HyperLink stylename=\"M_Link\" u=\"86021050\" color=\"#f4a067\">Chấn Nhiếp</> trúng kẻ địch, áp Trì Trệ trong 4 giây.",
    [1090789622952193] = "Sau khi <HyperLink stylename=\"M_Link\" u=\"86020010\" color=\"#f4a067\">Xung Kích Ý Thức</> trúng mục tiêu, cộng 1 tầng <HyperLink stylename=\"M_Link\" u=\"86020010\" color=\"#f4a067\">Ác Mộng</> kéo dài 7 giây. Đủ 3 tầng, Ác Mộng bùng nổ, gây Sát Thương Ma Pháp bằng 85% hiệu ứng cơ bản lên mục tiêu và kẻ địch trong phạm vi 3m.",
    [1090789622952194] = "Khi bản thân gây sát thương lên mục tiêu chịu ảnh hưởng của <HyperLink stylename=\"M_Link\" u=\"86021020\" color=\"#f4a067\">Thần Ôn</>, gây thêm một đòn Hiệp Đồng với Sát Thương Ma Pháp bằng 85% hiệu ứng cơ bản.",
    [1090789622953474] = "Trước mỗi lần chịu Sát Thương, nhận <HighLight>Khiên</> tồn tại 8 giây và tăng 50% Tốc Độ Di Chuyển trong 4 giây; hồi chiêu hiệu ứng 20 giây.",
    [1090789622953985] = "Giai đoạn ba của <HyperLink stylename=\"M_Link\" u=\"86031010\" color=\"#f4a067\">Phi Bài</> gây <HighLight>Chảy Máu</> 6 giây lên mục tiêu, mỗi giây mất 2% Máu tối đa của người thi triển (không vượt quá 60% Tấn Công của người thi triển).",
    [1090789622953986] = "Khi dùng lần 2 của <HyperLink stylename=\"M_Link\" u=\"86031070\" color=\"#f4a067\">Hỏa Diễm Dược</>, giải trừ <HighLight>hiệu ứng Khống Chế</> đang chịu.",
    [1090789622954497] = "Sau khi dùng <HyperLink stylename=\"M_Link\" u=\"86033010\" color=\"#f4a067\">Số Mệnh</>, trong 16 giây Tốc Độ Đánh của Đánh Thường tăng 20%, giá trị cơ sở sát thương Đánh Thường tăng 20%; Bạo Kích bản thân tăng trong 10 giây.",
    [1090789622954498] = "Giá trị sát thương cơ bản của <HyperLink stylename=\"M_Link\" u=\"86031020\" color=\"#f4a067\">Trận Tarot</> tăng 10%; có 85% xác suất khiến mục tiêu chính <HighLight>Giảm Tốc</> 50% trong 2.5 giây.",
    [1090789622955777] = "Trong thời gian <HyperLink stylename=\"M_Link\" u=\"86031030\" color=\"#f4a067\">Đạn Khí</>, Tốc Chạy tăng 25%; có thể tấn công thêm 2 kẻ địch trong phạm vi 3m quanh mục tiêu. Mỗi đòn có 50% xác suất cơ bản khiến địch <HighLight>Trì Trệ</> và <HighLight>Giảm Tốc</> 50% trong 1 giây.",
    [1090789622955778] = "Mỗi lần <HyperLink stylename=\"M_Link\" u=\"86030010\" color=\"#f4a067\">Mở Bài</> gây sát thương, giảm hồi chiêu của <HighLight>Đạn Khí</> 0.5 giây.",
    [1090789622956801] = "<HyperLink stylename=\"M_Link\" u=\"86033030\" color=\"#f4a067\">Xào Bài</> giảm 1 điểm <HighLight>Năng Lượng Lá Bài</> cần thiết và tăng 20% giá trị sát thương cơ bản; đòn đầu có 90% xác suất <HighLight>Giam Cầm</> mục tiêu trong 0.8 giây.",
    [1090789622956802] = "<HyperLink stylename=\"M_Link\" u=\"86030010\" color=\"#f4a067\">Mở Bài</> nhận <HighLight>Cảnh Báo Linh Tính</> mỗi 45 giây, có thể giải 1 hiệu ứng khống chế; sau khi kích hoạt, Tốc Độ Di Chuyển bản thân tăng 25% trong 2 giây.",
    [1090789622957569] = "Trong thời gian <HighLight>Nghiên Tập</>, mỗi lần dùng <HyperLink stylename=\"M_Link\" u=\"86050050\" color=\"#f4a067\">Tái Hiện Dấu Chân</> (tùy số tầng) có thể hoàn lại <HighLight>1 giây</> hồi chiêu của <HyperLink stylename=\"M_Link\" u=\"86051050\" color=\"#f4a067\">Tinh Vân Vịnh Thán</>, <HyperLink stylename=\"M_Link\" u=\"86051010\" color=\"#f4a067\">Diễn Dịch Trò Ảo</>, <HyperLink stylename=\"M_Link\" u=\"86051060\" color=\"#f4a067\">Phóng Trục</>, <HyperLink stylename=\"M_Link\" u=\"86051090\" color=\"#f4a067\">Ghi Chép</>.\nSát thương Hiệp Đồng Tấn Công của <HyperLink stylename=\"M_Link\" u=\"86051080\" color=\"#f4a067\">Không Ngục</> tăng <HighLight>100%</>.",
    [1090789622957570] = "Mỗi điểm <HighLight>Năng Lượng Tinh Không</> tăng <HighLight>1.5%</> Tăng Thương của bản thân (sau khi dùng <HyperLink stylename=\"M_Link\" u=\"86053010\" color=\"#f4a067\">Cổng Chồng Tầng</>, hiệu ứng vẫn duy trì 2 giây).",
    [1090789622958081] = "Sát thương của <HyperLink stylename=\"M_Link\" u=\"86050050\" color=\"#f4a067\">Tái Hiện Dấu Chân</> tăng <HighLight>50%</>.",
    [1090789622958082] = "Trong thời gian <HighLight>Nghiên Tu</>, nhận thêm <HighLight>Tấn Công</> và <HighLight>Cường Hóa Kỹ Năng</>.",
    [1090789622958593] = "Giới hạn cộng dồn <HighLight>Chiết Mạc</> tăng lên <HighLight>10</> tầng. Khi đạt <HighLight>10</> tầng, hoàn lại <HighLight>3 giây</> hồi chiêu của <HyperLink stylename=\"M_Link\" u=\"86051080\" color=\"#f4a067\">Không Ngục</> và <HighLight>5 giây</> hồi chiêu của <HyperLink stylename=\"M_Link\" u=\"86052010\" color=\"#f4a067\">Du Hành</>.\nSát thương Hiệp Đồng Tấn Công của <HyperLink stylename=\"M_Link\" u=\"86051080\" color=\"#f4a067\">Không Ngục</> tăng <HighLight>100%</>.",
    [1090789622959873] = "<HyperLink stylename=\"M_Link\" u=\"86050050\" color=\"#f4a067\">Tái Hiện Dấu Chân</> giờ sẽ lao một đoạn ngắn về phía mục tiêu. Khi tiêu hao <HighLight>3</> tầng <HighLight>Dấu Chân</>, còn cộng cho mục tiêu <HighLight>1</> tầng <HighLight>Ấn Ký Cộng Dồn</>, tối đa <HighLight>2</> tầng.\n\n<FaintYellow>Ấn Ký Cộng Dồn</>:\n<HyperLink stylename=\"M_Link\" u=\"86053010\" color=\"#f4a067\">Trùng Môn</> sẽ kích nổ toàn bộ <HighLight>Ấn Ký Cộng Dồn</> trên mục tiêu; mỗi tầng tăng <HighLight>60%</> sát thương lần này.",
    [1090789622960385] = "Dùng <HyperLink stylename=\"M_Link\" u=\"86051020\" color=\"#f4a067\">Xuyên Giới</> sẽ làm mới hồi chiêu của <HyperLink stylename=\"M_Link\" u=\"86051030\" color=\"#f4a067\">Ảo Thuật Thoát Thân</>.",
    [1090789622960386] = "Trạng thái <HyperLink stylename=\"M_Link\" u=\"86052010\" color=\"#f4a067\">Du Hành</> nhận thêm <HighLight>Tàng Hình</>. Dùng kỹ năng, chịu tấn công hoặc dùng vật phẩm sẽ hủy <HighLight>Tàng Hình</>.",
    [1090789622960897] = "Khi dùng <HyperLink stylename=\"M_Link\" u=\"86051040\" color=\"#f4a067\">Tinh Định</>, vào trạng thái <HighLight>Quá Tải</> trong <HighLight>8</> giây.\nTrong <HighLight>Quá Tải</>, dùng <HyperLink stylename=\"M_Link\" u=\"86053010\" color=\"#f4a067\">Cánh Cửa Chồng Lớp</> sẽ kết thúc <HighLight>Quá Tải</> sớm; dùng combo đòn hai của <HyperLink stylename=\"M_Link\" u=\"86051040\" color=\"#f4a067\">Tinh Định</> sẽ hoàn lại hồi chiêu dựa trên số tầng <HighLight>Dấu Ấn Chồng Lớp</> cao nhất của mục tiêu lân cận và kết thúc <HighLight>Quá Tải</> sớm.\n\n<FaintYellow>Quá Tải</>:\nTăng Thương +<HighLight>10%</>. Giới hạn cộng dồn <HighLight>Dấu Ấn Chồng Lớp</> tăng lên <HighLight>3</> tầng; số <HighLight>Dấu Chân</> cần để gắn Dấu Ấn giảm còn <HighLight>2</> tầng.",
    [1090789622961409] = "Mỗi điểm <HighLight>Năng Lượng Tinh Không</> tăng <HighLight>1.5%</> Tăng Thương của bản thân (sau khi dùng <HyperLink stylename=\"M_Link\" u=\"86053010\" color=\"#f4a067\">Cổng Chồng Tầng</>, hiệu ứng vẫn duy trì 2 giây).",
    [1090789622961410] = "Sát thương của <HyperLink stylename=\"M_Link\" u=\"86051020\" color=\"#f4a067\">Xuyên Giới</> tăng <HighLight>10%</>.",
    [1090789622962177] = "Ở Hình Thái Phòng Thủ, hiệu quả Giảm Thương bị động của <HyperLink stylename=\"M_Link\" u=\"86065010\" color=\"#f4a067\">Bậc Thầy Vũ Khí</> tăng lên 30%.",
    [1090789622962178] = "<HyperLink stylename=\"M_Link\" u=\"86061060\" color=\"#f4a067\">Kiên Bích Bảo Hộ</> nhận nhánh mới <HyperLink stylename=\"M_Link\" u=\"86061063\" color=\"#f4a067\">Bích Lũy Bảo Hộ</>: Triển khai lĩnh vực, cấp khiên lớn và 15% Giảm Thương cho 2 đồng minh có Sinh Mệnh thấp nhất trong phạm vi 30m. Lượng khiên tăng theo số <HighLight>Dấu Ấn Hoàng Hôn</> tiêu hao.",
    [1090789622963201] = "Ở Hình Thái Phòng Thủ, mỗi đoạn của <HyperLink stylename=\"M_Link\" u=\"86061080\" color=\"#f4a067\">Nộ Ý Kích</> đều tăng Chuyên Phòng Quái Vật và hồi Sinh Mệnh. Khi dùng kỹ năng, mỗi khi tiêu hao 1/2 <HighLight>Dấu Ấn Hoàng Hôn</>, Chuyên Phòng Quái Vật tăng thêm 15%/30%, lượng Hồi Phục tăng thêm 20%/50%.",
    [1090789622963202] = "<HyperLink stylename=\"M_Link\" u=\"86061023\" color=\"#f4a067\">Hiệu Lệnh Vương Đình</> khiến mục tiêu địch trúng kỹ năng giảm 15% Tấn Công trong 5 giây.",
    [1090789622963713] = "Sau khi chịu sát thương, nếu Sinh Mệnh hiện tại dưới 50% và <HyperLink stylename=\"M_Link\" u=\"86061040\" color=\"#f4a067\">Giáp Bình Minh</> không đang hồi chiêu, tự động dùng <HyperLink stylename=\"M_Link\" u=\"86061040\" color=\"#f4a067\">Giáp Bình Minh</>; vẫn có hiệu lực ngay cả khi không mang <HyperLink stylename=\"M_Link\" u=\"86061040\" color=\"#f4a067\">Giáp Bình Minh</>.",
    [1090789622963714] = "<HyperLink stylename=\"M_Link\" u=\"86061020\" color=\"#f4a067\">Săn Ma Thuấn Trảm</> nhận nhánh mới <HyperLink stylename=\"M_Link\" u=\"86061025\" color=\"#f4a067\">Trảm Vệ Trừ Ma</>: Ở Hình Thái Phòng Thủ, dùng lên kẻ địch có hiệu quả như Săn Ma Thuấn Trảm gốc; dùng lên đồng minh sẽ giải Khống Chế Nhẹ và Chậm, đồng thời cho 20% Giảm Thương và tăng 25% Tốc Độ Di Chuyển trong 5 giây.",
    [1090789622964737] = "Đòn đầu của <HyperLink stylename=\"M_Link\" u=\"86061030\" color=\"#f4a067\">Cuồng Phong</> gây <HighLight>Trì Trệ</> 2 giây lên người chơi trúng đòn. Trong thời gian Cuồng Phong duy trì, bản thân nhận 15% Giảm Thương và tăng 15% Tốc Độ Di Chuyển.",
    [1090789622964738] = "Sau khi kiếm trận của <HyperLink stylename=\"M_Link\" u=\"86061110\" color=\"#f4a067\">Cự Trảm</> phát nổ, Sức Mạnh Hoàng Hôn còn lưu lại, liên tục hút kẻ địch trong phạm vi trong 2 giây.",
    [1090789622966529] = "Ở Hình Thái Công Kích, khi <HyperLink stylename=\"M_Link\" u=\"86061080\" color=\"#f4a067\">Nộ Ý Kích</> trúng kẻ địch đang có <HighLight>Suy Bại</>, gây thêm sát thương truy kích phạm vi nhỏ và kéo dài <HighLight>Suy Bại</> thêm 5 giây.",
    [1090789622966530] = "Ở Hình Thái Công Kích, dùng <HyperLink stylename=\"M_Link\" u=\"86061023\" color=\"#f4a067\">Hiệu Lệnh Vương Đình</> sau Liệp Ma Trảm cũng có thể đánh ngã kẻ địch phía trước và vào <HighLight>Cuồng Bạo</> trong 6 giây. Trong <HighLight>Cuồng Bạo</>, tấn công trúng địch hồi Sinh Mệnh cho bản thân; hiệu ứng này có hồi chiêu nội tại <Highlight>1</> giây.",
    [1090789622968065] = "Mỗi lần <HyperLink stylename=\"M_Link\" u=\"86063020\" color=\"#f4a067\">Lưỡi Đao Điêu Linh</> trúng mục tiêu sẽ gây <HighLight>Giảm Tốc</>; sau khi dùng, mỗi <HighLight>2</> giây nhận <HighLight>1</> <HighLight>Ấn Ký Hoàng Hôn</>, kéo dài 6 giây.",
    [1090789622968066] = "<HyperLink stylename=\"M_Link\" u=\"86061110\" color=\"#f4a067\">Cự Trảm</> ngắt mục tiêu trúng đòn 0.5 giây; ở dạng Sát Thương gây thêm Câm Lặng 2 giây và <HighLight>Suy Bại</> 6 giây. Sát thương gây lên kẻ địch đang <HighLight>Suy Bại</> tăng <HighLight>10%</>.",
    [1090789622969090] = "Sát thương của <HyperLink stylename=\"M_Link\" u=\"86071030\" color=\"#f4a067\">Tinh Sa</> tăng 50%, nhận thêm 10 điểm <HighLight>Tri Thức Thần Bí</>, đồng thời tăng giá trị giảm Xuyên Thấu.",
    [1090789622970625] = "Sát thương của <HyperLink stylename=\"M_Link\" u=\"86071020\" color=\"#f4a067\">Quang Khúc</> tăng 50%, nhận thêm 10 điểm <HighLight>Tri Thức Thần Bí</>.",
    [1090789622972417] = "<HyperLink stylename=\"M_Link\" u=\"86073010\" color=\"#f4a067\">Tin Tuyến</> đổi thành xoay quanh bản thân và di chuyển theo bản thân. Trong thời gian kỹ năng, bản thân nhận 10% Giảm Thương và tăng 25% Tốc Độ Di Chuyển; hiệu ứng tối đa kéo dài 7 giây.",
    [1090789622972418] = "<HyperLink stylename=\"M_Link\" u=\"86071060\" color=\"#f4a067\">Con Mắt Dòm Bí</> đổi hiệu ứng Đẩy Lùi thành Hất Tung với 100% xác suất cơ bản.",
    [1090789622973185] = "Lượng Sát Thương hấp thụ của <HyperLink stylename=\"M_Link\" u=\"86071050\" color=\"#f4a067\">Áo Mới Của Hoàng Đế</> tăng 25%.",
    [1090789622973186] = "Mỗi lần Huyễn Tượng Thần Bí do <HyperLink stylename=\"M_Link\" u=\"86071070\" color=\"#f4a067\">Thần Bí Tái Hiện</> triệu hồi tấn công, hồi 5 điểm <HighLight>Tri Thức Thần Bí</>.",
    [1090789622973187] = "Trong thời gian dùng <HyperLink stylename=\"M_Link\" u=\"86073010\" color=\"#f4a067\">Tin Tuyến</>, bản thân nhận thêm 10% Giảm Thương; hiệu ứng tối đa kéo dài 7 giây.",
    [1090789622974722] = "Sát Thương của <HyperLink stylename=\"M_Link\" u=\"86071060\" color=\"#f4a067\">Mắt Dòm Ngó Bí Ẩn</> tăng 30%.",
    [1099514043755264] = "Dẫn 2-049 vào Pháp Trận Phong Ấn do Dunn triệu hồi.",
    [1099514043770112] = "Thử Lại",
    [1099514043785984] = "Xử Quyết Thiên Tai Mê Hồn (sau khi kẻ địch Suy Yếu, chọn mục tiêu và dùng kỹ năng “Xử Quyết”).",
    [1099514043786752] = "Đã vào phạm vi tìm kiếm. Hãy tự tìm mục tiêu trong khu vực.",
    [1099514043799040] = "Tiến vào trong Khiên",
    [1099514043811072] = "Quét sạch Zombie, chờ tin từ Trevor. (Gợi ý: dùng Shotgun có thể gây Sát Thương diện rộng rất cao)",
    [1099514043834624] = "Dùng kỹ năng “Ngắm Súng Ngắn”, bắn Trụ Linh Tính để kích hoạt cơ quan.",
    [1099514043840768] = "Điều tra thi thể Nam Tước. (Gợi ý: có thể dùng Linh Thị để tìm dấu vết Linh Tính)",
    [1099514043866112] = "Lại gần Phong Ấn Ký Ức và dùng kỹ năng “Cộng Hưởng” để mở khóa!",
    [1099514043868160] = "Dùng kỹ năng “Lumi Đại Hành” để trao đổi ý thức với Lumi; sau khi thu nhỏ, chui vào lối vào.",
    [1099582763174144] = "Tìm mục tiêu và dùng kỹ năng “Nhập Thân”.",
