    [1161087500159744] = "Thăng Tiến",
    [1161155682800896] = "Cấp Nhập Vai đạt 39 sẽ mở cốt truyện tiếp theo. Có thể tham gia các hoạt động tại <HyperLink stylename=\"h\" u=\"1250015\">Cốt Truyện</>, <HyperLink stylename=\"h\" u=\"1250008\">Phó Bản</>, <HyperLink stylename=\"h\" u=\"1250331\">Thám Bí</>, <HyperLink stylename=\"h\" u=\"1250093\">Đấu Trường</> và <HyperLink stylename=\"h\" u=\"1250163\">Nằm Thắng</> để nhận EXP Nhận Thức.",
    [1161155682823680] = "Cấp Nhập Vai đạt 46 sẽ mở cốt truyện tiếp theo. Có thể tham gia các hoạt động tại <HyperLink stylename=\"h\" u=\"1250015\">Cốt Truyện</>, <HyperLink stylename=\"h\" u=\"1250008\">Phó Bản</>, <HyperLink stylename=\"h\" u=\"1250331\">Thám Bí</>, <HyperLink stylename=\"h\" u=\"1250093\">Đấu Trường</> và <HyperLink stylename=\"h\" u=\"1250163\">Nằm Thắng</> để nhận EXP Nhận Thức.",
