    [1240250995242752] = "Áp Chế Boss",
    [1240250995243008] = "Kháng Boss",
    [1240250995247104] = "Mua Hàng Loạt",
    [1240250995250432] = "Mô tả đánh thường thay thế khi kỹ năng đang hồi chiêu.",
    [1240250995251200] = "Mô tả chọn mục tiêu kỹ năng khi rê chuột.",
    [1240250995256832] = "Thiêu Đốt",
    [1240250995261952] = "Mô Tả Nhập Vai",
    [1240250995262208] = "Thân Phận Nhập Vai",
    [1240250995330048] = "Có thể nhấn 【Triệu Hồi Quái Vật】 và tới khu vực chỉ định để triệu hồi.",
    [1240251532051969] = "Giao diện này hiển thị toàn bộ thuộc tính người chơi, đồng thời có thể mặc, tháo và thay trang bị.",
    [1240251532052225] = "Ngài “Kẻ Khờ” đã ghép cho bạn một Vận Mệnh từ tương lai, cho phép sử dụng sức mạnh của Bậc cao hơn. Khi thực lực tăng lên, số loại kỹ năng và sức mạnh kỹ năng bạn học được cũng tăng theo. Kỹ năng chia thành ba loại: Kỹ Năng Thường, Kỹ Năng Đặc Biệt và Kỹ Năng Nhập Vai; tối đa trang bị đồng thời bốn Kỹ Năng Thường hoặc Kỹ Năng Nhập Vai. Kỹ Năng Đặc Biệt không cần trang bị, gồm Tấn Công Thường, kỹ năng Giải Khống Chế và Kỹ Năng Kết Liễu.",
    [1240251532052481] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Giới Thiệu Lối Chơi</>\nTranh Phong Chúa Tể là PvP tổ đội, tối đa lập đội 3 người để ghép trận. Sau khi vào chế độ, mọi người nhận điều chỉnh thuộc tính <Highlight>cân bằng</>.\nHạ toàn bộ đội địch hoặc gây tổng sát thương cao hơn khi hết giờ để thắng trận.",
    [1240251532053249] = "Khi nhận trang bị <Highlight>Đã Khóa</>, toàn bộ loại và giá trị thuộc tính Linh Chất cố định của nó sẽ <Highlight>tự động ghi lại</> vào không gian.\nĐồng thời, giá trị từ Linh Chất cố định trên trang bị đang mặc sẽ luôn <Highlight>tự động cập nhật theo giá trị cao nhất</> đã ghi trong không gian.",
    [1240251532054019] = "Kỹ Năng: %s",
    [1240251532054785] = "1. Lập Tiểu Đội 6 người và đăng ký Phó Bản bằng chế độ tổ đội. Đội hình thường cần Chiến Sĩ, Khán Giả và 4 Phi Phàm Giả có khả năng gây sát thương. 2. Người chơi đơn có thể đăng ký Chế Độ Máy; Công Ty An Ninh Blackthorn sẽ cử Phi Phàm Giả tham gia. Sức mạnh đồng đội máy liên quan tới Điểm Phi Phàm của người chơi; nếu điểm thấp hơn nhiều so với đề xuất, tổng lực đội có thể không đủ vượt thử thách. 3. Chế độ tổ đội và Chế Độ Máy dùng chung giới hạn số lần nhận thưởng.",
    [1240251532055297] = "1. Lập Raid 12 người và đăng ký Phó Bản bằng chế độ tổ đội. Cần 2 đội, mỗi đội khuyến nghị có Chiến Sĩ, Khán Giả và 4 Phi Phàm Giả có khả năng gây sát thương. 2. Người chơi đơn có thể đăng ký Chế Độ Máy; Công Ty An Ninh Blackthorn sẽ cử Phi Phàm Giả tham gia. Sức mạnh đồng đội máy liên quan tới Điểm Phi Phàm của người chơi; nếu điểm thấp hơn nhiều so với đề xuất, tổng lực đội có thể không đủ vượt thử thách. 3. Chế độ tổ đội và Chế Độ Máy dùng chung giới hạn số lần nhận thưởng.",
    [1240251532055553] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy Tắc Tích Lũy Lượt Thưởng:</>\nVượt bất kỳ Phó Bản Hằng Ngày nào nhận <Highlight>1</> lượt thưởng. Mỗi ngày tăng <Highlight>1</> lượt, tích tối đa <Highlight>3</>; lượt tăng mỗi ngày của các Phó Bản khác nhau <Highlight>dùng chung giới hạn</>.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Lượt Thưởng Còn Lại:</>\nPhó Bản Hằng Ngày hiện tại: Thưởng Cá Nhân <Highlight>%s</> lượt, Thưởng Chung <Highlight>%s</> lượt\nChế độ Máy chỉ tiêu hao Thưởng Cá Nhân; chế độ Tổ Đội tiêu hao cả Thưởng Cá Nhân và Thưởng Chung.",
    [1240251532055809] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy Tắc Tích Lũy Lượt Thưởng:</>\nSau mỗi giai đoạn Phó Bản Tổ Đội có thể nhận <Highlight>1</> lượt thưởng, tổng <Highlight>3</> giai đoạn. Mỗi giai đoạn mỗi tuần tăng <Highlight>1</> lượt, tích tối đa <Highlight>2</>.\nCác độ khó và loại Phó Bản khác nhau <Highlight>dùng chung giới hạn</> lượt tăng theo tuần, tức mỗi tuần nhận tối đa <Highlight>3</> lượt. Khi mở Phó Bản mới, lượt còn lại trước đó không chuyển sang Phó Bản mới.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Lượt Thưởng Ban Đầu:</>\nKhi mở Phó Bản mới nhận thêm <Highlight>1</> lượt thưởng ban đầu; <Highlight>ưu tiên tiêu lượt ban đầu, không tính vào giới hạn tích lũy và không chịu giới hạn dùng chung</>.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Lượt Thưởng Còn Lại:</>\n<Highlight>%s</>: Thưởng Cá Nhân <Highlight>%s</> lượt, Thưởng Chung <Highlight>%s</> lượt\n<Highlight>%s</>: Thưởng Cá Nhân <Highlight>%s</> lượt, Thưởng Chung <Highlight>%s</> lượt\n<Highlight>%s</>: Thưởng Cá Nhân <Highlight>%s</> lượt, Thưởng Chung <Highlight>%s</> lượt\nChế độ Máy chỉ tiêu hao Thưởng Cá Nhân; chế độ Tổ Đội tiêu hao cả Thưởng Cá Nhân và Thưởng Chung.",
    [1240251532056065] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy Tắc Tích Lũy Lượt Thưởng:</>\nSau mỗi giai đoạn Phó Bản Đoàn Đội có thể nhận <Highlight>1</> lượt thưởng, tổng <Highlight>3</> giai đoạn. Mỗi giai đoạn mỗi tuần tăng <Highlight>1</> lượt, tích tối đa <Highlight>2</>.\nCác độ khó và loại Phó Bản khác nhau <Highlight>dùng chung giới hạn</> lượt tăng theo tuần, tức mỗi tuần nhận tối đa <Highlight>6</> lượt. Khi mở Phó Bản mới, lượt còn lại trước đó không chuyển sang Phó Bản mới.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Lượt Thưởng Ban Đầu:</>\nKhi mở Phó Bản mới nhận thêm <Highlight>1</> lượt thưởng ban đầu; <Highlight>ưu tiên tiêu lượt ban đầu, không tính vào giới hạn tích lũy và không chịu giới hạn dùng chung</>.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Lượt Thưởng Còn Lại:</>\n<Highlight>%s</>: Thưởng Cá Nhân <Highlight>%s</> lượt, Thưởng Chung <Highlight>%s</> lượt\n<Highlight>%s</>: Thưởng Cá Nhân <Highlight>%s</> lượt, Thưởng Chung <Highlight>%s</> lượt\n<Highlight>%s</>: Thưởng Cá Nhân <Highlight>%s</> lượt, Thưởng Chung <Highlight>%s</> lượt\nChế độ Máy chỉ tiêu hao Thưởng Cá Nhân; chế độ Tổ Đội tiêu hao cả Thưởng Cá Nhân và Thưởng Chung.",
    [1240251532058625] = "Mỗi Bậc Phi Phàm đều có năng lực thần kỳ riêng; trong chiến đấu sẽ ngẫu nhiên kích hoạt hiệu ứng Lĩnh Vực để tăng cường năng lực chiến đấu cho Phi Phàm Giả.",
    [1240251532058881] = "Trang bị Vật Phong Ấn để tăng Cộng Hưởng của Lĩnh Vực và giải phóng sức mạnh cao hơn. Tăng Cấp Nguy Hiểm của Vật Phong Ấn đang mặc hoặc Cải Tạo Đặc Tính Vật Phong Ấn đều tăng Điểm Cộng Hưởng. Khi đạt yêu cầu Cộng Hưởng của Cấp Lĩnh Vực, Lĩnh Vực tự tăng cấp; Cấp Lĩnh Vực càng cao, xác suất kích hoạt và hiệu quả năng lực tương ứng càng mạnh.",
    [1240251532059137] = "Mang Vật Phong Ấn cung cấp đặc tính mạnh trong chiến đấu nhưng cũng phải gánh lời nguyền tương ứng. Ngoài ra, Vật Phong Ấn có thể được cải tạo để cung cấp thêm thuộc tính Nguyên Tố.",
    [1240251532059393] = "Điểm Phi Phàm của hệ thống này là tổng Điểm Phi Phàm từ Cải Tạo Vật Phong Ấn và nâng cấp Lĩnh Vực. Điểm từ Cải Tạo Vật Phong Ấn chủ yếu đến từ phẩm chất và cấp của Khí Tức Phi Phàm; Cấp Lĩnh Vực được tính theo tổng Cộng Hưởng của các Vật Phong Ấn đang trang bị, mỗi lần tăng cấp sẽ cho một lần tăng Điểm Phi Phàm.",
    [1240251532059649] = "Cộng Hưởng Khí Tức giúp Vật Phong Ấn nhận thêm Điểm Cộng Hưởng; Cấp Khí Tức càng cao, Điểm Cộng Hưởng cung cấp càng nhiều. Tuy nhiên, khi Cấp Khí Tức cao nhất vượt Cấp Khí Tức thấp nhất sẽ xuất hiện Rối Loạn Khí Tức, khiến độ cộng hưởng từ việc cường hóa Khí Tức cấp cao giảm dần. Khi Cấp Khí Tức thấp nhất tăng lên, mức suy giảm do Rối Loạn cũng yếu đi; khi chênh lệch Cường Độ Khí Tức dưới 5 cấp, Rối Loạn dừng.",
    [1240251532060417] = "Điều chỉnh Khí Tức sẽ cung cấp các loại Khí Tức thuộc tính khác nhau. Ở cùng phẩm chất, Khí Tức dạng Lĩnh Vực mạnh hơn Khí Tức thuộc tính cơ bản. Cộng Hưởng cơ bản của Khí Tức càng cao, khi chịu ảnh hưởng Cộng Hưởng cũng nhận thêm nhiều Cộng Hưởng hơn.",
    [1240251532060929] = "Mở Kỹ Năng Chiến Đấu mới hoặc bồi dưỡng kỹ năng đã mở, đồng thời trang bị Bí Ngẫu và Kỹ Năng Nhân Mạch mạnh hơn sẽ tăng Điểm Phi Phàm.",
    [1240251532061185] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Phương Án Phi Phàm</>\nPhương Án Phi Phàm là build gồm Kỹ Năng, Thiên Phú và Vật Phong Ấn; phương án hiện tại thay đổi theo build người chơi theo thời gian thực.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Đổi Phương Án</>\nSau khi lưu một build thành phương án, có thể đổi một chạm sang build đó. Không thể đổi khi đang chiến đấu.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Phương Án Đề Xuất</>\nCó nhiều build đề xuất cho Con Đường hiện tại; có thể áp dụng một chạm build đề xuất vào phương án của bản thân.",
    [1240251532062209] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Cường Hóa Bộ Phận</>\nMỗi bộ phận có thể tiêu hao <Highlight>Nguyên Liệu Cường Hóa</> để cường hóa, tối đa đến <Highlight>Bậc 8</>.\nMỗi bậc đều tăng thuộc tính nhân vật; thuộc tính tăng được hiển thị trong phần <Highlight>Thuộc Tính Cơ Bản</> của trang bị.\nKhi đổi trang bị, hiệu quả cường hóa được <Highlight>chuyển nguyên vẹn</> (không có hiệu lực nếu không trang bị món ở bộ phận tương ứng).\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Bộ Cường Hóa</>\nKhi bậc cường hóa của từng bộ phận đồng thời đạt yêu cầu tương ứng, kích hoạt Bộ Cường Hóa để tiếp tục tăng năng lực nhân vật.",
    [1240251532062465] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Lưu Từ</>\nTrang bị khi rơi ra sẽ có từ ngẫu nhiên.\nKhi nhận trang bị <Highlight>có Từ Phi Phàm</>, tổ hợp từ <Highlight>sẽ được lưu</> và có thể <Highlight>áp dụng</> trong mục “Ân Tứ” bên phải giao diện Tái Tạo.\nBộ phận chưa mở chức năng Tái Tạo <Highlight>vẫn có thể dùng</> chức năng lưu và áp dụng này.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Tái Tạo Ngẫu Nhiên</>\nBộ phận đã mở Tái Tạo có thể tái tạo các từ ngẫu nhiên trên trang bị đang mặc, cần tiêu hao <Highlight>Nguyên Liệu Tái Tạo</>. Sau Tái Tạo, số lượng từ cùng <Highlight>loại thuộc tính và giá trị</> của toàn bộ từ sẽ được ngẫu nhiên lại.\nKhi xuất hiện nhiều Từ Phi Phàm, nhận thêm hiệu ứng Ân Tứ; các Từ Phi Phàm và số lượng từ khác nhau cho hiệu ứng Ân Tứ khác nhau.\nKhi đổi trang bị, từ Tái Tạo được <Highlight>chuyển nguyên vẹn</> (không có hiệu lực nếu không trang bị món ở bộ phận tương ứng).",
    [1240251532062721] = "Thánh Cao là vật phẩm đặc biệt dùng để <Highlight>ghi lại Dòng Thuộc Tính</>; dòng được ghi không trực tiếp có hiệu lực, chỉ có thể <Highlight>dùng để bôi lên Dòng Ngẫu Nhiên của Trang Bị</>.\nThánh Cao cũng có phẩm cấp. Thánh Cao phẩm cao có thể dùng cho Trang Bị phẩm thấp, nhưng sau khi bôi giá trị dòng chỉ có hiệu lực một phần; Thánh Cao phẩm thấp không thể dùng cho Trang Bị phẩm cao.",
    [1240251532062977] = "Khi liên tục Đột Phá, trang bị Phòng Thủ sẽ mở khóa ngày càng nhiều Linh Chất để lựa chọn.\nKích hoạt các Điểm Vận Mệnh khác nhau để nhận loại thuộc tính khác nhau. Nếu muốn loại thuộc tính khác, có thể chọn Con Đường để Tẩy Luyện.\nNếu không hài lòng với phương án Điểm Vận Mệnh hiện tại, có thể hoàn tác tiến độ và kích hoạt lại các điểm khác.",
    [1240251532063489] = "Tổng Điểm Phi Phàm do hệ thống Vật Phong Ấn cung cấp bằng tổng Điểm Phi Phàm của từng Vật Phong Ấn cộng với Điểm Phi Phàm từ hiệu ứng kích hoạt Lĩnh Vực.\nĐiểm Phi Phàm của Vật Phong Ấn gồm Điểm Phi Phàm cố hữu, phần tăng từ Nâng Cấp Vật Phong Ấn và phần tăng từ Đột Phá Vật Phong Ấn.\nĐiểm Phi Phàm của Lĩnh Vực đến từ Điểm Phi Phàm của các bonus được mở theo từng giai đoạn Cộng Hưởng Hạch Tâm.",
    [1240251532064513] = "Mỗi trang bị đều có Linh Chất cơ bản. Do vị trí và loại trang bị khác nhau, loại Linh Chất cơ bản cũng khác nhau.\nLinh Chất cơ bản của từng trang bị là giá trị cố định; với cùng loại trang bị, cấp càng cao thì Linh Chất cơ bản càng nhiều. Số lượng Linh Chất ngẫu nhiên trên trang bị cũng làm tăng lượng Linh Chất cơ bản.",
    [1240251532065793] = "Khi Máu nhân vật về 0 sẽ rơi vào trạng thái Tiêu Tán; cần bản thân hoặc người khác hỗ trợ Phục Tô mới có thể tiếp tục chiến đấu.",
    [1240251532066049] = "Tăng tốc độ hồi Máu, mỗi giây hồi {*.2f,F1690001,HpReg} Máu.",
    [1240251532066561] = "Tốc độ hồi Thể Lực bằng {*.1f**,F1690001,StaminaRecoverRate} lần tốc độ hồi cơ bản.",
    [1240251532067073] = "Biểu thị Tốc Độ Di Chuyển của nhân vật trong trạng thái hiện tại, gồm đi bộ, chạy và tốc độ né.",
    [1240251532067329] = "5 chỉ số cốt lõi của nhân vật sẽ chuyển đổi theo tỷ lệ thành Máu, Hồi Máu, Phòng Thủ, Bạo Kích, Kháng Bạo Kích, Xuyên Thấu, Đỡ Đòn, Cường Hóa Kỹ Năng, Kháng Kỹ Năng và Phá Phòng.",
    [1240251532067585] = "Phòng Thủ +{*d,Ini,pDef_N}, Kháng Kỹ Năng +{*d,Ini,BeSkilledReduce_N}.",
    [1240251532067841] = "Tăng {*d,Ini,MaxHp_N} Giới Hạn Sinh Mệnh, {*d,Ini,HpReg_N} Hồi Sinh Mệnh, {*d,Ini,pCrit_N} Bạo Kích và {*d,Ini,pCritAnti_N} Kháng Bạo Kích.",
    [1240251532068097] = "Tăng {*d,Ini,pDefReduce_N} Phá Phòng Vật Lý; Con Đường Vật Lý tăng thêm {*d,Ini,SkillPlus_N} Cường Hóa Kỹ Năng.\nCon Đường Vật Lý gồm: Thầy Bói, Ca Tụng Giả, Chiến Sĩ.",
    [1240251532068353] = "Tăng {*d,Ini,mDefReduce_N} Phá Phòng Ma Pháp; Con Đường Ma Pháp tăng thêm {*d,Ini,SkillPlus_N} Cường Hóa Kỹ Năng.\nCon Đường Ma Pháp gồm: Học Đồ, Khán Giả, Kẻ Dòm Ngó Bí Ẩn.",
    [1240251532068609] = "Xuyên Thấu +{*d,Ini,pPierce_N}, Chặn Đòn +{*d,Ini,pBlock_N}.",
    [1240251532068865] = "Tăng giá trị Trị Liệu cơ bản của kỹ năng Trị Liệu; mức tăng phụ thuộc vào hệ số kỹ năng.",
    [1240251532069377] = "Biểu thị Cường Hoá Trị Liệu mà Khán Giả Hình Thái Không Tưởng nhận từ chuyển đổi thuộc tính khác. Các thuộc tính sau được chuyển đổi theo tỷ lệ: Phá Phòng Ma Pháp, Bỏ Qua Phòng Thủ Ma Pháp, Phá Giáp, Cường Hóa Kỹ Năng, Xuyên Thấu Ma Pháp, Bạo Kích Ma Pháp, Sát Thương Bạo Kích Ma Pháp, Khuếch Thương, Cường Hóa Sát Thương Cuối, Chuyên Công Hệ, Áp Chế Hệ, Chuyên Công Boss, Áp Chế Boss, Chính Xác Khống Chế, Cường Hóa Khống Chế. (Tấn Công Ma Pháp tăng lượng Hồi Phục nhưng không chuyển thành Cường Hoá Trị Liệu.)",
    [1240251532070145] = "Tăng giá trị cơ bản Tấn Công của kỹ năng sát thương và giá trị cơ bản Trị Liệu của kỹ năng trị liệu. Hiệu quả thực tế chịu ảnh hưởng bởi hệ số kỹ năng và không liên quan Cấp Kỹ Năng. Tấn Công tối thiểu của nhân vật không vượt Tấn Công tối đa.",
    [1240251532070401] = "Tăng giá trị cơ sở Tấn Công gây Sát Thương Vật Lý thêm {*d,F1690008,pAtkMin}-{*d,F1690010,pAtkMax} và giá trị cơ sở Trị Liệu của Hệ Vật Lý thêm {*d,F1690033,pAtkMin}-{*d,F1690035,pAtkMax}; hiệu quả thực tế chịu ảnh hưởng bởi hệ số kỹ năng và không phụ thuộc cấp kỹ năng.\nTấn Công thực tế dao động trong khoảng Tấn Công Vật Lý Tối Thiểu {*d,F1690008,pAtkMin}~Tấn Công Vật Lý Tối Đa {*d,F1690010,pAtkMax}; Tấn Công Vật Lý Tối Thiểu không vượt Tối Đa.\nHệ Vật Lý gồm: Thầy Bói, Ca Tụng Giả, Chiến Sĩ.",
    [1240251532070657] = "Tăng giá trị cơ sở Tấn Công gây Sát Thương Ma Pháp thêm {*d,F1690009,pAtkMin}-{*d,F1690011,pAtkMax} và giá trị cơ sở Trị Liệu của Hệ Ma Pháp thêm {*d,F1690034,pAtkMin}-{*d,F1690036,pAtkMax}; hiệu quả thực tế chịu ảnh hưởng bởi hệ số kỹ năng và không phụ thuộc cấp kỹ năng.\nTấn Công thực tế dao động trong khoảng Tấn Công Ma Pháp Tối Thiểu {*d,F1690009,mAtkMin}~Tấn Công Ma Pháp Tối Đa {*d,F1690011,mAtkMax}; Tấn Công Ma Pháp Tối Thiểu không vượt Tối Đa.\nHệ Ma Pháp gồm: Học Đồ, Khán Giả, Kẻ Dòm Ngó Bí Ẩn.",
    [1240251532070913] = "Tấn Công của bên tấn công được hiệu chỉnh theo đối kháng Phá Giáp - Giáp giữa hai bên.\nKhi Phá Giáp bản thân thấp hơn ¼ Giáp mục tiêu, mỗi 1 điểm Phá Giáp tăng 2 điểm Tấn Công.\nKhi Phá Giáp bản thân vượt ¼ Giáp mục tiêu nhưng thấp hơn Giáp mục tiêu, mỗi 3 điểm Phá Giáp tăng 2 điểm Tấn Công.\nKhi Phá Giáp bản thân vượt Giáp mục tiêu, mỗi 3 điểm Phá Giáp tăng 1 điểm Tấn Công.",
    [1240251532071169] = "Tăng giá trị cơ sở của kỹ năng sát thương, bị Kháng Kỹ Năng của mục tiêu triệt tiêu.\nGiá trị cơ sở kỹ năng không chịu ảnh hưởng bởi <Highlight>Tấn Công</> và <Highlight>Phòng Thủ</>, mà phụ thuộc <Highlight>hệ số kỹ năng</> và <Highlight>cấp kỹ năng</>.\nGiá trị cơ sở kỹ năng sau hiệu chỉnh có trần <Highlight>250%</> và sàn <Highlight>5%</>; phần Cường Hóa Kỹ Năng vượt trần hoặc chưa đạt sàn không thể tăng năng lực Tăng Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>cấp</> hai bên và kết toán đối kháng với <Highlight>Kháng Kỹ Năng</> của đối phương.",
    [1240251532071425] = "Bỏ qua Chặn Đòn của mục tiêu, qua đó giảm xác suất sát thương bị mục tiêu Chặn Đòn. Khi Xuyên Thấu vượt Chặn Đòn của mục tiêu, tiếp tục giảm xác suất sát thương bản thân bị Chặn Đòn, tối đa giảm về 0.",
    [1240251532071681] = "Bỏ qua Chặn Đòn Vật Lý của mục tiêu; trên Tỷ Lệ Xuyên Thấu cơ bản <Highlight>75%</>, tăng xác suất Sát Thương Vật Lý Xuyên Thấu (không bị Chặn Đòn).\nTỷ Lệ Xuyên Thấu có trần <Highlight>100%</> và sàn <Highlight>25%</>; phần Xuyên Thấu vượt trần hoặc chưa đạt sàn không thể tăng năng lực Tăng Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>cấp</> hai bên và kết toán đối kháng với <Highlight>Chặn Đòn Vật Lý</> của đối phương.",
    [1240251532071937] = "Bỏ qua Chặn Đòn Ma Pháp của mục tiêu; trên Tỷ Lệ Xuyên Thấu cơ bản <Highlight>75%</>, tăng xác suất Sát Thương Ma Pháp Xuyên Thấu (không bị Chặn Đòn).\nTỷ Lệ Xuyên Thấu có trần <Highlight>100%</> và sàn <Highlight>25%</>; phần Xuyên Thấu vượt trần hoặc chưa đạt sàn không thể tăng năng lực Tăng Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>cấp</> hai bên và kết toán đối kháng với <Highlight>Chặn Đòn Ma Pháp</> của đối phương.",
    [1240251532072193] = "Tăng xác suất Sát Thương Bạo Kích (Tỷ Lệ Bạo Kích không vượt quá 75%). Khi Bạo Kích, Sát Thương được nhân theo Sát Thương Bạo Kích.",
    [1240251532072449] = "Trên Tỷ Lệ Bạo Kích cơ bản <Highlight>25%</>, tăng xác suất Sát Thương Vật Lý Bạo Kích; khi Bạo Kích, sát thương tăng theo Bạo Thương. Bị Kháng Bạo Kích Vật Lý của mục tiêu triệt tiêu.\nTỷ Lệ Bạo Kích có trần <Highlight>75%</> và sàn <Highlight>5%</>; phần Bạo Kích vượt trần hoặc chưa đạt sàn không thể tăng năng lực Tăng Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>cấp</> hai bên và kết toán đối kháng với <Highlight>Kháng Bạo Kích Vật Lý</> của đối phương.",
    [1240251532072705] = "Trên Tỷ Lệ Bạo Kích cơ bản <Highlight>25%</>, tăng xác suất Sát Thương Ma Pháp Bạo Kích; khi Bạo Kích, sát thương tăng theo Bạo Thương. Bị Kháng Bạo Kích Ma Pháp của mục tiêu triệt tiêu.\nTỷ Lệ Bạo Kích có trần <Highlight>75%</> và sàn <Highlight>5%</>; phần Bạo Kích vượt trần hoặc chưa đạt sàn không thể tăng năng lực Tăng Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>cấp</> hai bên và kết toán đối kháng với <Highlight>Kháng Bạo Kích Ma Pháp</> của đối phương.",
    [1240251532072961] = "Biểu thị hệ số sát thương khi sát thương gây Bạo Kích, bị Kháng Sát Thương Bạo Kích của mục tiêu triệt tiêu. Hệ số Sát Thương Bạo Kích cuối cùng không vượt 250% và không thấp hơn 125%.",
    [1240251532073217] = "Khi Sát Thương Vật Lý gây Bạo Kích, hệ số sát thương là {*.1f**,F1690001,pCritHurt}, bị đối kháng bởi Giảm Bạo Thương - Vật của mục tiêu. Hệ số Bạo Kích cuối không vượt 250% và không thấp hơn 125%.\nPhần Sát Thương Bạo Kích tăng vượt ngưỡng trên hoặc chưa đạt ngưỡng dưới không thể tiếp tục tăng sát thương.",
    [1240251532073473] = "Khi Sát Thương Ma Pháp gây Bạo Kích, hệ số sát thương là {*.1f**,F1690001,mCritHurt}, bị đối kháng bởi Giảm Bạo Thương - Ma của mục tiêu. Hệ số Bạo Kích cuối không vượt 250% và không thấp hơn 125%.\nPhần Sát Thương Bạo Kích tăng vượt ngưỡng trên hoặc chưa đạt ngưỡng dưới không thể tiếp tục tăng sát thương.",
    [1240251532073729] = "Sát thương gây ra tăng, bị Giảm Thương của mục tiêu đối kháng.",
    [1240251532073985] = "Sát Thương Vật Lý gây ra tăng {*.1f**,F1690001,pHurtMulti}. Bị Giảm Thương Vật Lý của mục tiêu triệt tiêu.",
    [1240251532074241] = "Sát Thương Ma Pháp gây ra tăng {*.1f**,F1690001,mHurtMulti}. Bị Giảm Thương Ma Pháp của mục tiêu triệt tiêu.",
    [1240251532074497] = "Sát Thương gây ra tăng {*.2f**,F1690001,SkillMulti}, bị Súc Thương của mục tiêu triệt tiêu.",
    [1240251532074753] = "Sát Thương Cuối gây ra tăng {*d,F1690001,DeltaHurt}.",
    [1240251532075009] = "Bỏ qua Phòng Thủ của mục tiêu (hiệu ứng % có hiệu lực sau hiệu ứng giá trị cố định), giảm mức Phòng Thủ của mục tiêu làm giảm giá trị cơ bản Tấn Công.",
    [1240251532075265] = "Bỏ qua {*d,F1690001,pDefReduce} điểm Phòng Thủ Vật Lý của mục tiêu, giảm mức Phòng Thủ Vật Lý khấu trừ khỏi Giá Trị Cơ Bản Tấn Công Vật Lý. (Hiệu ứng % có hiệu lực sau hiệu ứng giá trị cố định)\nGiá Trị Cơ Bản Tấn Công sau giảm trừ có trần <Highlight>75%</> và sàn <Highlight>20%</>. Phá Phòng vượt trần hoặc chưa chạm sàn sẽ không tiếp tục tăng khả năng Tăng Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>Cấp</> hai bên và kết toán đối kháng với thuộc tính <Highlight>Phòng Thủ Vật Lý</> của đối phương.",
    [1240251532075521] = "Bỏ qua {*.1f**,F1690001,pDefDivi} Phòng Thủ Vật Lý của mục tiêu (hiệu ứng phần trăm có hiệu lực sau hiệu ứng cố định), giảm mức Phòng Thủ Vật Lý làm giảm giá trị cơ sở Tấn Công Vật Lý.\nGiá trị cơ sở Tấn Công sau giảm có trần <Highlight>75%</> và sàn <Highlight>20%</>; phần Bỏ Qua Phòng Thủ vượt trần hoặc chưa đạt sàn không thể tăng năng lực Tăng Thương.",
    [1240251532075777] = "Bỏ qua {*d,F1690001,mDefReduce} điểm Phòng Thủ Ma Pháp của mục tiêu, giảm mức Phòng Thủ Ma Pháp khấu trừ khỏi Giá Trị Cơ Bản Tấn Công Ma Pháp. (Hiệu ứng % có hiệu lực sau hiệu ứng giá trị cố định)\nGiá Trị Cơ Bản Tấn Công sau giảm trừ có trần <Highlight>75%</> và sàn <Highlight>20%</>. Phá Phòng vượt trần hoặc chưa chạm sàn sẽ không tiếp tục tăng khả năng Tăng Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>Cấp</> hai bên và kết toán đối kháng với thuộc tính <Highlight>Phòng Thủ Ma Pháp</> của đối phương.",
    [1240251532076033] = "Bỏ qua {*.1f**,F1690001,mDefDivi} Phòng Thủ Ma Pháp của mục tiêu (hiệu ứng phần trăm có hiệu lực sau hiệu ứng cố định), giảm mức Phòng Thủ Ma Pháp làm giảm giá trị cơ sở Tấn Công Ma Pháp.\nGiá trị cơ sở Tấn Công sau giảm có trần <Highlight>75%</> và sàn <Highlight>20%</>; phần Bỏ Qua Phòng Thủ vượt trần hoặc chưa đạt sàn không thể tăng năng lực Tăng Thương.",
    [1240251532076289] = "Khi tấn công mục tiêu không phải người chơi, tăng Tấn Công bản thân (không áp dụng với kẻ địch loại Công Trình).",
    [1240251532076545] = "Khi tấn công Boss, Tấn Công bản thân tăng {*d,F1690001,BossHurtPlus}.",
    [1240251532076801] = "Khi tấn công Quái Tinh Anh, Tấn Công bản thân tăng {*d,F1690001,EliteHurtPlus} điểm.",
    [1240251532077057] = "Khi tấn công Quái Thường, Tấn Công bản thân tăng {*d,F1690001,CreepHurtPlus} điểm.",
    [1240251532077313] = "Khi tấn công Triệu Hồi Vật, Tấn Công bản thân tăng {*d,F1690001,CreateHurtPlus} điểm.",
    [1240251532077569] = "Khi tấn công mục tiêu không phải người chơi, tăng sát thương bản thân (không áp dụng với kẻ địch loại Công Trình).",
    [1240251532077825] = "Khi tấn công Boss, sát thương tăng {*.1f**,F1690001,BossHurtMulti}.",
    [1240251532078593] = "Khi tấn công Vật Triệu Hồi, sát thương tăng {*.1f**,F1690001,CreateHurtMulti}.",
    [1240251532078849] = "Tăng xác suất khống chế trúng mục tiêu, tối đa khiến tỷ lệ trúng cơ bản tăng thành 2 lần; bị đối kháng bởi Né Khống Chế của mục tiêu.",
    [1240251532079105] = "Tăng xác suất Đẩy Lùi trúng mục tiêu, tối đa khiến tỷ lệ trúng cơ bản tăng thành 2 lần; bị đối kháng bởi Né Đẩy Lùi của mục tiêu.",
    [1240251532079361] = "Tăng xác suất Kéo trúng mục tiêu, tối đa khiến tỷ lệ trúng cơ bản tăng thành 2 lần; bị đối kháng bởi Né Kéo của mục tiêu.",
    [1240251532079617] = "Tăng xác suất Hất Tung trúng mục tiêu, tối đa khiến tỷ lệ trúng cơ bản tăng thành 2 lần; bị đối kháng bởi Né Hất Tung của mục tiêu.",
    [1240251532079873] = "Tăng xác suất Hất Văng trúng mục tiêu, tối đa khiến tỷ lệ trúng cơ bản tăng thành 2 lần; bị đối kháng bởi Né Hất Văng của mục tiêu.",
    [1240251532080129] = "Tăng xác suất Hất Ngã trúng mục tiêu, tối đa khiến tỷ lệ trúng cơ bản tăng thành 2 lần; bị đối kháng bởi Né Hất Ngã của mục tiêu.",
    [1240251532080385] = "Tăng xác suất Cứng Đờ trúng mục tiêu, tối đa khiến tỷ lệ trúng cơ bản tăng thành 2 lần; bị đối kháng bởi Né Cứng Đờ của mục tiêu.",
    [1240251532080641] = "Tăng xác suất khống chế Choáng trúng mục tiêu, tối đa khiến tỷ lệ trúng cơ bản tăng thành 2 lần; bị đối kháng bởi Né Choáng của mục tiêu.",
    [1240251532080897] = "Tăng xác suất Ngủ trúng mục tiêu, tối đa khiến tỷ lệ trúng cơ bản tăng thành 2 lần; bị đối kháng bởi Né Ngủ của mục tiêu.",
    [1240251532081153] = "Tăng xác suất khống chế Câm Lặng trúng mục tiêu, tối đa khiến tỷ lệ trúng cơ bản tăng thành 2 lần; bị đối kháng bởi Né Câm Lặng của mục tiêu.",
    [1240251532081409] = "Tăng xác suất Trói Buộc trúng mục tiêu, tối đa khiến tỷ lệ trúng cơ bản tăng thành 2 lần; bị đối kháng bởi Né Trói Buộc của mục tiêu.",
    [1240251532081665] = "Tăng xác suất Trì Trệ trúng mục tiêu, tối đa khiến tỷ lệ trúng cơ bản tăng thành 2 lần; bị đối kháng bởi Né Trì Trệ của mục tiêu.",
    [1240251532081921] = "Tăng xác suất khống chế Giảm Tốc trúng mục tiêu, tối đa khiến tỷ lệ trúng cơ bản tăng thành 2 lần; bị đối kháng bởi Né Giảm Tốc của mục tiêu.",
    [1240251532082177] = "Tăng thời gian duy trì của hiệu ứng Khống Chế sau khi trúng, tối đa tăng thời gian cơ bản lên 2 lần; bị Kháng Khống Chế của mục tiêu triệt tiêu.",
    [1240251532082433] = "Tăng thời gian duy trì sau khi Choáng trúng mục tiêu, tối đa khiến thời gian cơ bản tăng thành 2 lần; bị đối kháng bởi Kháng Choáng của mục tiêu.",
    [1240251532082689] = "Tăng thời gian duy trì của hiệu ứng Ngủ sau khi trúng, tối đa tăng thời gian cơ bản lên 2 lần; bị Kháng Ngủ của mục tiêu triệt tiêu.",
    [1240251532082945] = "Tăng thời gian duy trì sau khi Câm Lặng trúng mục tiêu, tối đa khiến thời gian cơ bản tăng thành 2 lần; bị đối kháng bởi Kháng Câm Lặng của mục tiêu.",
    [1240251532083201] = "Tăng thời gian duy trì của hiệu ứng Cấm Cố sau khi trúng, tối đa tăng thời gian cơ bản lên 2 lần; bị Kháng Cấm Cố của mục tiêu triệt tiêu.",
    [1240251532083457] = "Tăng thời gian duy trì của hiệu ứng Trì Trệ sau khi trúng, tối đa tăng thời gian cơ bản lên 2 lần; bị Kháng Trì Trệ của mục tiêu triệt tiêu.",
    [1240251532083713] = "Tăng thời gian duy trì sau khi Giảm Tốc trúng mục tiêu, tối đa khiến thời gian cơ bản tăng thành 2 lần; bị đối kháng bởi Kháng Giảm Tốc của mục tiêu.",
    [1240251532083969] = "Giảm giá trị cơ sở Tấn Công của sát thương phải chịu; không thể giảm giá trị cơ sở kỹ năng.\nGiá trị cơ sở Tấn Công sau giảm có trần <Highlight>75%</> và sàn <Highlight>20%</>; phần Phòng Thủ vượt trần hoặc chưa đạt sàn không thể tăng năng lực Giảm Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>cấp</> hai bên và kết toán đối kháng với <Highlight>Phá Phòng</>, <Highlight>Bỏ Qua Phòng Thủ</> của đối phương.",
    [1240251532084225] = "Giảm giá trị cơ sở Tấn Công của Sát Thương Vật Lý phải chịu; không thể giảm giá trị cơ sở kỹ năng của Sát Thương Vật Lý.\nGiá trị cơ sở Tấn Công sau giảm có trần <Highlight>75%</> và sàn <Highlight>20%</>; phần Phòng Thủ vượt trần hoặc chưa đạt sàn không thể tăng năng lực Giảm Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>cấp</> hai bên và kết toán đối kháng với <Highlight>Phá Phòng Vật Lý</>, <Highlight>Bỏ Qua Phòng Thủ Vật Lý</> của đối phương.",
    [1240251532084481] = "Giảm giá trị cơ sở Tấn Công của Sát Thương Ma Pháp phải chịu; không thể giảm giá trị cơ sở kỹ năng của Sát Thương Ma Pháp.\nGiá trị cơ sở Tấn Công sau giảm có trần <Highlight>75%</> và sàn <Highlight>20%</>; phần Phòng Thủ vượt trần hoặc chưa đạt sàn không thể tăng năng lực Giảm Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>cấp</> hai bên và kết toán đối kháng với <Highlight>Phá Phòng Ma Pháp</>, <Highlight>Bỏ Qua Phòng Thủ Ma Pháp</> của đối phương.",
    [1240251532084737] = "Tấn Công của bên công sẽ được điều chỉnh theo đối kháng Phá Giáp - Giáp của hai bên.\nKhi Giáp bản thân cao hơn 4 lần Phá Giáp của nguồn sát thương, mỗi 1 Giáp giảm 1 Tấn Công của nguồn sát thương.\nKhi Giáp bản thân cao hơn Phá Giáp của nguồn sát thương nhưng thấp hơn 4 lần, mỗi 3 Giáp giảm 2 Tấn Công của nguồn sát thương.\nKhi Giáp bản thân thấp hơn Phá Giáp của nguồn sát thương, mỗi 3 Giáp giảm 1 Tấn Công của nguồn sát thương.",
    [1240251532084993] = "Giảm giá trị cơ sở kỹ năng của sát thương phải chịu, triệt tiêu Cường Hóa Kỹ Năng từ nguồn sát thương.\nGiá trị cơ sở kỹ năng không chịu ảnh hưởng bởi <Highlight>Tấn Công</> và <Highlight>Phòng Thủ</>, mà phụ thuộc <Highlight>hệ số kỹ năng</> và <Highlight>cấp kỹ năng</>.\nGiá trị cơ sở kỹ năng sau hiệu chỉnh có trần <Highlight>250%</> và sàn <Highlight>5%</>; phần Kháng Kỹ Năng vượt trần hoặc chưa đạt sàn không thể tăng năng lực Giảm Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>cấp</> hai bên và kết toán đối kháng với <Highlight>Cường Hóa Kỹ Năng</> của đối phương.",
    [1240251532085249] = "Triệt tiêu Xuyên Thấu từ nguồn sát thương; trên Tỷ Lệ Chặn Đòn cơ bản <Highlight>25%</>, tăng xác suất Chặn Đòn sát thương phải chịu. Khi Chặn Đòn, chỉ chịu 30% sát thương và không kích hoạt Bạo Kích.\nTỷ Lệ Chặn Đòn có trần <Highlight>75%</> và sàn <Highlight>0%</>; phần Chặn Đòn vượt trần hoặc chưa đạt sàn không thể tăng năng lực Giảm Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>cấp</> hai bên và kết toán đối kháng với <Highlight>Xuyên Thấu</> của đối phương.",
    [1240251532085505] = "Triệt tiêu Xuyên Thấu Vật Lý từ nguồn sát thương; trên Tỷ Lệ Chặn Đòn cơ bản <Highlight>25%</>, tăng xác suất Chặn Đòn sát thương phải chịu. Khi Chặn Đòn, chỉ chịu 30% sát thương và không kích hoạt Bạo Kích.\nTỷ Lệ Chặn Đòn có trần <Highlight>75%</> và sàn <Highlight>0%</>; phần Chặn Đòn vượt trần hoặc chưa đạt sàn không thể tăng năng lực Giảm Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>cấp</> hai bên và kết toán đối kháng với <Highlight>Xuyên Thấu Vật Lý</> của đối phương.",
    [1240251532085761] = "Triệt tiêu Xuyên Thấu Ma Pháp từ nguồn sát thương; trên Tỷ Lệ Chặn Đòn cơ bản <Highlight>25%</>, tăng xác suất Chặn Đòn sát thương phải chịu. Khi Chặn Đòn, chỉ chịu 30% sát thương và không kích hoạt Bạo Kích.\nTỷ Lệ Chặn Đòn có trần <Highlight>75%</> và sàn <Highlight>0%</>; phần Chặn Đòn vượt trần hoặc chưa đạt sàn không thể tăng năng lực Giảm Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>cấp</> hai bên và kết toán đối kháng với <Highlight>Xuyên Thấu Ma Pháp</> của đối phương.",
    [1240251532086017] = "Triệt tiêu Bạo Kích từ nguồn sát thương; trên Tỷ Lệ Bạo Kích cơ bản <Highlight>25%</>, giảm xác suất sát thương phải chịu gây Bạo Kích.\nTỷ Lệ Bạo Kích có trần <Highlight>75%</> và sàn <Highlight>5%</>; phần Kháng Bạo Kích vượt trần hoặc chưa đạt sàn không thể tăng năng lực Giảm Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>cấp</> hai bên và kết toán đối kháng với <Highlight>Bạo Kích</> của đối phương.",
    [1240251532086273] = "Triệt tiêu Bạo Kích Vật Lý từ nguồn sát thương; trên Tỷ Lệ Bạo Kích cơ bản <Highlight>25%</>, giảm xác suất sát thương phải chịu gây Bạo Kích.\nTỷ Lệ Bạo Kích có trần <Highlight>75%</> và sàn <Highlight>5%</>; phần Kháng Bạo Kích vượt trần hoặc chưa đạt sàn không thể tăng năng lực Giảm Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>cấp</> hai bên và kết toán đối kháng với <Highlight>Bạo Kích Vật Lý</> của đối phương.",
    [1240251532086529] = "Triệt tiêu Bạo Kích Ma Pháp từ nguồn sát thương; trên Tỷ Lệ Bạo Kích cơ bản <Highlight>25%</>, giảm xác suất sát thương phải chịu gây Bạo Kích.\nTỷ Lệ Bạo Kích có trần <Highlight>75%</> và sàn <Highlight>5%</>; phần Kháng Bạo Kích vượt trần hoặc chưa đạt sàn không thể tăng năng lực Giảm Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>cấp</> hai bên và kết toán đối kháng với <Highlight>Bạo Kích Ma Pháp</> của đối phương.",
    [1240251532086785] = "Giảm hệ số Sát Thương Bạo Kích nhận vào, triệt tiêu Sát Thương Bạo Kích của nguồn gây sát thương. Hệ số cuối của Sát Thương Bạo Kích không vượt quá 250% và không thấp hơn 125%.",
    [1240251532087041] = "Hệ số Sát Thương Bạo Kích Vật Lý nhận vào giảm {*.1f**,F1690001,pCritDef}, triệt tiêu Sát Thương Bạo Kích Vật Lý từ nguồn gây Sát Thương. Hệ số Sát Thương Bạo Kích cuối cùng không vượt quá 250% hoặc thấp hơn 125%.\nNếu mức Giảm Bạo Thương - Vật tăng thêm vượt giới hạn trên hoặc chưa chạm giới hạn dưới, sẽ không thể tăng khả năng Giảm Thương.",
    [1240251532087297] = "Hệ số Sát Thương Bạo Kích Ma Pháp nhận vào giảm {*.1f**,F1690001,mCritDef}, triệt tiêu Sát Thương Bạo Kích Ma Pháp từ nguồn gây Sát Thương. Hệ số Sát Thương Bạo Kích cuối cùng không vượt quá 250% hoặc thấp hơn 125%.\nNếu mức Giảm Bạo Thương - Ma tăng thêm vượt giới hạn trên hoặc chưa chạm giới hạn dưới, sẽ không thể tăng khả năng Giảm Thương.",
    [1240251532087553] = "Giảm sát thương phải chịu, triệt tiêu Tăng Thương của nguồn gây sát thương.",
    [1240251532087809] = "Sát Thương Vật Lý nhận vào giảm {*.1f**,F1690001,pHurtReduce}, triệt tiêu Tăng Thương - Vật của nguồn gây sát thương.",
    [1240251532088065] = "Sát Thương Ma Pháp nhận vào giảm {*.1f**,F1690001,mHurtReduce}, triệt tiêu Tăng Thương - Ma của nguồn gây sát thương.",
    [1240251532088321] = "Sát thương phải chịu giảm {*.2f**,F1690001,BeSkilledDivi}, triệt tiêu Khuếch Thương của nguồn gây sát thương.",
    [1240251532088577] = "Sát Thương Cuối phải chịu giảm {*d,F1690001,DeltaBeHurted}.",
    [1240251532089089] = "Khi bị kẻ địch không phải người chơi và không phải công trình tấn công, triệt tiêu Chuyên Công của nó. (Tối đa giảm Chuyên Công của bên tấn công về 0)",
    [1240251532089345] = "Khi chịu đòn từ Boss, triệt tiêu {*d,F1690001,BossHurtReduce} Chuyên Công của Boss. (Tối đa giảm Chuyên Công của bên tấn công về 0)",
    [1240251532089601] = "Khi chịu Quái Tinh Anh tấn công, triệt tiêu {*d,F1690001,EliteHurtReduce} điểm Chuyên Công của nó. (Tối đa giảm Chuyên Công bên tấn công về 0)",
    [1240251532089857] = "Khi chịu Quái Thường tấn công, triệt tiêu {*d,F1690001,CreepHurtReduce} điểm Chuyên Công của nó. (Tối đa giảm Chuyên Công bên tấn công về 0)",
    [1240251532090113] = "Khi chịu đòn từ Triệu Hồi Vật, triệt tiêu {*d,F1690001,CreateHurtReduce} điểm Chuyên Công của nó. (Tối đa giảm Chuyên Công của bên tấn công về 0)",
    [1240251532090369] = "Khi bị kẻ địch không phải người chơi và không phải công trình tấn công, triệt tiêu Áp Chế của nó. (Tối đa giảm Áp Chế của bên tấn công về 0)",
    [1240251532090625] = "Khi chịu Tấn Công từ Boss, triệt tiêu {*.1f**,F1690001,BossHurtDivi} Áp Chế của Boss. (Tối đa giảm Áp Chế của bên tấn công xuống 0)",
    [1240251532090881] = "Khi bị Quái Tinh Anh tấn công, triệt tiêu {*.1f**,F1690001,EliteHurtDivi} Áp Chế của nó. (Tối đa giảm Áp Chế của bên tấn công về 0)",
    [1240251532091137] = "Khi bị Quái Thường tấn công, triệt tiêu {*.1f**,F1690001,CreepHurtDivi} Áp Chế của nó. (Tối đa giảm Áp Chế của bên tấn công về 0)",
    [1240251532091393] = "Khi bị vật triệu hồi tấn công, triệt tiêu {*.1f**,F1690001,CreateHurtDivi} Áp Chế của nó. (Tối đa giảm Áp Chế của bên tấn công về 0)",
    [1240251532091649] = "Giảm xác suất bị Khống Chế đánh trúng, tối đa giảm một nửa Tỷ Lệ Trúng cơ bản; triệt tiêu Chính Xác Khống Chế của nguồn khống chế.",
    [1240251532091905] = "Giảm xác suất bị Hất Lùi khống chế đánh trúng, tối đa giảm một nửa Tỷ Lệ Trúng cơ bản; triệt tiêu Chính Xác Hất Lùi của nguồn khống chế.",
    [1240251532092161] = "Giảm xác suất bị Kéo khống chế đánh trúng, tối đa giảm một nửa Tỷ Lệ Trúng cơ bản; triệt tiêu Chính Xác Kéo của nguồn khống chế.",
    [1240251532092417] = "Giảm xác suất bị Hất Bổng khống chế đánh trúng, tối đa giảm một nửa Tỷ Lệ Trúng cơ bản; triệt tiêu Chính Xác Hất Bổng của nguồn khống chế.",
    [1240251532092673] = "Giảm xác suất bị Đánh Bay khống chế đánh trúng, tối đa giảm một nửa Tỷ Lệ Trúng cơ bản; triệt tiêu Chính Xác Đánh Bay của nguồn khống chế.",
    [1240251532092929] = "Giảm xác suất bị Quật Ngã khống chế đánh trúng, tối đa giảm một nửa Tỷ Lệ Trúng cơ bản; triệt tiêu Chính Xác Quật Ngã của nguồn khống chế.",
    [1240251532093185] = "Giảm xác suất bị Cứng Người khống chế đánh trúng, tối đa giảm một nửa Tỷ Lệ Trúng cơ bản; triệt tiêu Chính Xác Cứng Người của nguồn khống chế.",
    [1240251532093441] = "Giảm xác suất bị hiệu ứng Choáng đánh trúng, tối đa giảm một nửa Tỷ Lệ Trúng cơ bản; triệt tiêu Chính Xác Choáng của nguồn khống chế.",
    [1240251532093697] = "Giảm xác suất bị Ngủ khống chế đánh trúng, tối đa giảm một nửa Tỷ Lệ Trúng cơ bản; triệt tiêu Chính Xác Ngủ của nguồn khống chế.",
    [1240251532093953] = "Giảm xác suất bị Câm Lặng khống chế đánh trúng, tối đa giảm một nửa Tỷ Lệ Trúng cơ bản; triệt tiêu Chính Xác Câm Lặng của nguồn khống chế.",
