    [1240251532095489] = "Giảm thời gian Ngủ sau khi nhân vật bị hiệu ứng Ngủ trúng, tối đa giảm một nửa thời gian cơ bản; triệt tiêu Cường Hóa Ngủ từ nguồn gây hiệu ứng.",
    [1240251532095745] = "Giảm thời gian duy trì sau khi nhân vật bị Câm Lặng trúng, tối đa giảm thời gian cơ bản còn một nửa; đối kháng Cường Hóa Câm Lặng của nguồn khống chế.",
    [1240251532096001] = "Giảm thời gian Cấm Cố sau khi nhân vật bị hiệu ứng Cấm Cố trúng, tối đa giảm một nửa thời gian cơ bản; triệt tiêu Cường Hóa Cấm Cố từ nguồn gây hiệu ứng.",
