    [1240251532097537] = "Khi chịu tấn công từ Phi Phàm Giả Con Đường Thầy Bói, triệt tiêu {*d,F1690001,FeatherwitHurtReduce} điểm Chuyên Công của họ. (Tối đa giảm Chuyên Công bên tấn công về 0)",
    [1240251532097793] = "Khi chịu tấn công từ Phi Phàm Giả Con Đường Học Đồ, triệt tiêu {*d,F1690001,ApprenticeHurtReduce} điểm Chuyên Công của họ. (Tối đa giảm Chuyên Công bên tấn công về 0)",
    [1240251532098049] = "Khi chịu tấn công từ Phi Phàm Giả Con Đường Chiến Sĩ, triệt tiêu {*d,F1690001,WarriorHurtReduce} điểm Chuyên Công của họ. (Tối đa giảm Chuyên Công bên tấn công về 0)",
    [1240251532098305] = "Khi chịu tấn công từ Phi Phàm Giả Con Đường Kẻ Dòm Ngó Bí Ẩn, triệt tiêu {*d,F1690001,MysteryPryerHurtReduce} điểm Chuyên Công của họ. (Tối đa giảm Chuyên Công bên tấn công về 0)",
    [1240251532098561] = "Khi chịu Công Trình tấn công, triệt tiêu {*d,F1690001,BuildingHurtReduce} điểm Chuyên Công của nó. (Tối đa giảm Chuyên Công bên tấn công về 0)",
    [1240251532098817] = "Khi bị kẻ địch là người chơi hoặc công trình tấn công, triệt tiêu Áp Chế của nó. (Tối đa giảm Áp Chế của bên tấn công về 0)",
