    [1240251532099585] = "Khi bị Phi Phàm Giả Con Đường Thầy Bói tấn công, triệt tiêu {*.1f**,F1690001,FeatherwitHurtDivi} Áp Chế của họ. (Tối đa giảm Áp Chế của bên tấn công xuống 0)",
    [1240251532099841] = "Khi bị Phi Phàm Giả Con Đường Học Đồ tấn công, triệt tiêu {*.1f**,F1690001,ApprenticeHurtDivi} Áp Chế của họ. (Tối đa giảm Áp Chế của bên tấn công xuống 0)",
    [1240251532100097] = "Khi bị Phi Phàm Giả Con Đường Chiến Sĩ tấn công, triệt tiêu {*.1f**,F1690001,WarriorHurtDivi} Áp Chế của họ. (Tối đa giảm Áp Chế của bên tấn công xuống 0)",
    [1240251532100353] = "Khi bị Phi Phàm Giả Con Đường Kẻ Dòm Ngó Bí Ẩn tấn công, triệt tiêu {*.1f**,F1690001,MysteryPryerHurtDivi} Áp Chế của họ. (Tối đa giảm Áp Chế của bên tấn công xuống 0)",
    [1240251532100609] = "Khi bị công trình tấn công, triệt tiêu {*.1f**,F1690001,BuildingHurtDivi} Áp Chế của nó. (Tối đa giảm Áp Chế của bên tấn công về 0)",
    [1240251532101121] = "Khi tấn công Phi Phàm Giả Con Đường Ca Tụng Giả, Tấn Công bản thân tăng {*d,F1690001,SunHurtPlus} điểm.",
    [1240251532101377] = "Khi tấn công Phi Phàm Giả Con Đường Khán Giả, Tấn Công bản thân tăng {*d,F1690001,VisionaryHurtPlus} điểm.",
    [1240251532101633] = "Khi tấn công Phi Phàm Giả Con Đường Thầy Bói, Tấn Công bản thân tăng {*d,F1690001,FeatherwitHurtPlus} điểm.",
    [1240251532101889] = "Khi tấn công Phi Phàm Giả Con Đường Học Đồ, Tấn Công bản thân tăng {*d,F1690001,ApprenticeHurtPlus} điểm.",
    [1240251532102145] = "Khi tấn công Phi Phàm Giả Con Đường Chiến Sĩ, Tấn Công bản thân tăng {*d,F1690001,WarriorHurtPlus} điểm.",
    [1240251532102401] = "Khi tấn công Phi Phàm Giả Con Đường Kẻ Dòm Ngó Bí Ẩn, Tấn Công bản thân tăng {*d,F1690001,MysteryPryerHurtPlus} điểm.",
    [1240251532102657] = "Khi tấn công Công Trình, Tấn Công bản thân tăng {*d,F1690001,BuildingHurtPlus} điểm.",
    [1240251532103169] = "Khi tấn công Phi Phàm Giả thuộc Con Đường Ca Tụng Giả, sát thương tăng {*.1f**,F1690001,SunHurtMulti}.",
    [1240251532103425] = "Khi tấn công Phi Phàm Giả thuộc Con Đường Khán Giả, sát thương tăng {*.1f**,F1690001,VisionaryHurtMulti}.",
    [1240251532103681] = "Khi tấn công Phi Phàm Giả thuộc Con Đường Thầy Bói, sát thương tăng {*.1f**,F1690001,FeatherwitHurtMulti}.",
    [1240251532103937] = "Khi tấn công Phi Phàm Giả thuộc Con Đường Học Đồ, sát thương tăng {*.1f**,F1690001,ApprenticeHurtMulti}.",
    [1240251532104193] = "Khi tấn công Phi Phàm Giả thuộc Con Đường Chiến Sĩ, sát thương tăng {*.1f**,F1690001,WarriorHurtMulti}.",
    [1240251532104449] = "Khi tấn công Phi Phàm Giả thuộc Con Đường Kẻ Dòm Ngó Bí Ẩn, sát thương tăng {*.1f**,F1690001,MysteryPryerHurtMulti}.",
    [1240251532105217] = "Khi chịu sát thương, Khiên sẽ chặn sát thương trước khi nhân vật bị trừ Máu.",
    [1240251532105729] = "Khi Sinh Mệnh nhân vật về 0 sẽ rơi vào trạng thái Tiêu Tán; cần bản thân hoặc người khác hỗ trợ Phục Tô mới trở lại bình thường.",
    [1240251532105985] = "Phòng Thủ Vật Lý: {*d,F1690001,pDef}\nPhòng Thủ Ma Pháp: {*d,F1690001,mDef}\nGiảm giá trị cơ bản Tấn Công của nguồn sát thương, không thể giảm giá trị cơ bản Kỹ Năng.\nMức giảm đối với giá trị cơ bản Tấn Công có <Highlight>trần 75%</> và <Highlight>sàn 20%</>; Phòng Thủ tăng vượt ngưỡng trên hoặc chưa đạt ngưỡng dưới sẽ không tiếp tục cải thiện năng lực Giảm Thương.\nHiệu quả thực tế và ngưỡng phụ thuộc <Highlight>Cấp</> của hai bên công-thủ, đồng thời đối kháng với <Highlight>Phá Phòng</> và <Highlight>Bỏ Qua Phòng Thủ</> của đối phương.",
    [1240251532106241] = "Tấn Công của bên công sẽ được điều chỉnh theo đối kháng Phá Giáp - Giáp giữa bên công và bên thủ.\nKhi Giáp bản thân cao hơn 4 lần Phá Giáp của nguồn sát thương, mỗi 1 Giáp giảm 1 Tấn Công của nguồn sát thương.\nKhi Giáp bản thân cao hơn Phá Giáp của nguồn sát thương nhưng thấp hơn 4 lần, mỗi 3 Giáp giảm 2 Tấn Công của nguồn sát thương.\nKhi Giáp bản thân thấp hơn Phá Giáp của nguồn sát thương, mỗi 3 Giáp giảm 1 Tấn Công của nguồn sát thương.",
    [1240251532106497] = "Đỡ Đòn Vật Lý: {*d,F1690001,pBlock}\nĐỡ Đòn Ma Pháp: {*d,F1690001,mBlock}\nĐối kháng Xuyên Thấu của nguồn sát thương; trên nền tỷ lệ Đỡ Đòn cơ bản <Highlight>25%</>, tăng xác suất Đỡ Đòn sát thương nhận vào. Khi Đỡ Đòn, chỉ chịu 30% sát thương và không kích hoạt Bạo Kích.\nTỷ lệ Đỡ Đòn có <Highlight>trần 75%</> và <Highlight>sàn 0%</>; phần Đỡ Đòn vượt ngưỡng trên hoặc chưa đạt ngưỡng dưới không thể tiếp tục cải thiện năng lực Giảm Thương.\nHiệu quả thực tế và ngưỡng phụ thuộc <Highlight>Cấp</> của hai bên công-thủ và kết toán đối kháng với <Highlight>Xuyên Thấu</> của đối phương.",
    [1240251532106753] = "Kháng Bạo Kích Vật Lý: {*d,F1690001,pCritAnti}\nKháng Bạo Kích Ma Pháp: {*d,F1690001,mCritAnti}\nĐối kháng Bạo Kích của nguồn sát thương; trên nền tỷ lệ Bạo Kích cơ bản <Highlight>25%</>, giảm xác suất sát thương nhận vào gây Bạo Kích.\nTỷ lệ Bạo Kích có <Highlight>trần 75%</> và <Highlight>sàn 5%</>; phần Kháng Bạo Kích vượt ngưỡng trên hoặc chưa đạt ngưỡng dưới không thể tiếp tục cải thiện năng lực Giảm Thương.\nHiệu quả thực tế và ngưỡng phụ thuộc <Highlight>Cấp</> của hai bên công-thủ và kết toán đối kháng với <Highlight>Bạo Kích</> của đối phương.",
    [1240251532107265] = "Tấn Công của bên tấn công được hiệu chỉnh theo đối kháng Phá Giáp - Giáp giữa hai bên.\nKhi Phá Giáp bản thân thấp hơn ¼ Giáp mục tiêu, mỗi 1 điểm Phá Giáp tăng 2 điểm Tấn Công.\nKhi Phá Giáp bản thân vượt ¼ Giáp mục tiêu nhưng thấp hơn Giáp mục tiêu, mỗi 3 điểm Phá Giáp tăng 2 điểm Tấn Công.\nKhi Phá Giáp bản thân vượt Giáp mục tiêu, mỗi 3 điểm Phá Giáp tăng 1 điểm Tấn Công.",
    [1240251532107777] = "Tấn Công Vật Lý Tối Thiểu: {*d,F1690008,pAtkMin}\nTấn Công Vật Lý Tối Đa: {*d,F1690010,pAtkMax}\nTăng {*d,F1690008,pAtkMin}-{*d,F1690010,pAtkMax} điểm giá trị cơ sở Tấn Công của Sát Thương Vật Lý và {*d,F1690033,pAtkMin}-{*d,F1690035,pAtkMax} điểm giá trị cơ sở Trị Liệu của Con Đường Vật Lý. Hiệu quả thực tế chịu ảnh hưởng bởi hệ số kỹ năng, không liên quan cấp kỹ năng.\nCon Đường Vật Lý gồm: Thầy Bói, Ca Tụng Giả, Chiến Sĩ.",
    [1240251532108033] = "Bỏ qua {*d,F1690001,pDefReduce}+{*.1f**,F1690001,pDefDivi} Phòng Thủ Vật Lý của mục tiêu, giảm mức Phòng Thủ Vật Lý khấu trừ khỏi Giá Trị Cơ Bản Tấn Công Vật Lý. (Hiệu ứng % có hiệu lực sau hiệu ứng giá trị cố định)\nGiá Trị Cơ Bản Tấn Công sau giảm trừ có trần <Highlight>75%</> và sàn <Highlight>20%</>. Phá Phòng vượt trần hoặc chưa chạm sàn sẽ không tiếp tục tăng khả năng Tăng Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>Cấp</> hai bên và kết toán đối kháng với thuộc tính <Highlight>Phòng Thủ Vật Lý</> của đối phương.",
    [1240251532108801] = "Tấn Công Ma Pháp Tối Thiểu: {*d,F1690009,mAtkMin}\nTấn Công Ma Pháp Tối Đa: {*d,F1690011,mAtkMax}\nTăng {*d,F1690009,pAtkMin}-{*d,F1690011,pAtkMax} điểm giá trị cơ sở Tấn Công của Sát Thương Ma Pháp và {*d,F1690034,pAtkMin}-{*d,F1690036,pAtkMax} điểm giá trị cơ sở Trị Liệu của Con Đường Ma Pháp. Hiệu quả thực tế chịu ảnh hưởng bởi hệ số kỹ năng, không liên quan cấp kỹ năng.\nCon Đường Ma Pháp gồm: Học Đồ, Khán Giả, Kẻ Dòm Ngó Bí Ẩn.",
    [1240251532109057] = "Bỏ qua {*d,F1690001,mDefReduce}+{*.1f**,F1690001,mDefDivi} Phòng Thủ Ma Pháp của mục tiêu, giảm mức Phòng Thủ Ma Pháp khấu trừ khỏi Giá Trị Cơ Bản Tấn Công Ma Pháp. (Hiệu ứng % có hiệu lực sau hiệu ứng giá trị cố định)\nGiá Trị Cơ Bản Tấn Công sau giảm trừ có trần <Highlight>75%</> và sàn <Highlight>20%</>. Phá Phòng vượt trần hoặc chưa chạm sàn sẽ không tiếp tục tăng khả năng Tăng Thương.\nHiệu quả và ngưỡng thực tế phụ thuộc <Highlight>Cấp</> hai bên và kết toán đối kháng với thuộc tính <Highlight>Phòng Thủ Ma Pháp</> của đối phương.",
    [1240251532109825] = "Thuộc tính Tấn Công Ma Pháp của Khán Giả Hình Thái Không Tưởng sẽ chuyển thành Cường Hoá Trị Liệu theo tỷ lệ tùy loại thuộc tính. (Có thể chuyển đổi: Phá Phòng Ma Pháp, Bỏ Qua Phòng Thủ Ma Pháp, Phá Giáp, Xuyên Thấu Ma Pháp, Bạo Kích Ma Pháp, Sát Thương Bạo Kích Ma Pháp, Cường Hóa Kỹ Năng, Khuếch Thương, Cường Hóa Sát Thương Cuối, Áp Chế Hệ, Áp Chế Boss, Chuyên Công Hệ, Chuyên Công Boss, Chính Xác Khống Chế, Cường Hóa Khống Chế.)",
    [1240251532110081] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Đề Xuất Bồi Dưỡng</>\n1. Dựa trên <Highlight>cảnh mục tiêu</> Phi Phàm Giả chọn, <Highlight>thuộc tính hiện tại</> và <Highlight>thuộc tính của mục tiêu đối kháng</>, tự động đề xuất các thuộc tính bồi dưỡng có <Highlight>Lợi Ích Kỳ Vọng</> cao;\n2. Chỉ tính các <Highlight>thuộc tính bồi dưỡng</> phổ biến; một số thuộc tính không hiển thị (như Tăng Tốc Độ Đánh, Tăng Khiên Nhận Được) không nằm trong phạm vi tính;\n3. <Highlight>Lợi Ích Kỳ Vọng</> đồng thời chịu ảnh hưởng bởi <Highlight>mức tăng năng lực</> của thuộc tính đó trong <Highlight>cảnh mục tiêu</> và <Highlight>độ khó bồi dưỡng</>;\n4. <Highlight>Lợi Ích Kỳ Vọng</> chỉ xét trường hợp thuộc tính hiện tại tăng một lượng nhỏ. Khi một số thuộc tính tăng nhiều (hoặc chênh lệch lớn với thuộc tính đối kháng của mục tiêu), lợi ích có thể <Highlight>tăng mạnh</> hoặc <Highlight>giảm mạnh</>; đề xuất chỉ để tham khảo.",
    [1240251532110337] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Đánh Giá Mức Tăng</>\n1. Hiển thị mức tăng năng lực do <Highlight>thuộc tính từ</> của vật phẩm này mang lại, không tính ảnh hưởng của hiệu ứng đặc biệt (như Lạc Ấn, bộ trang bị, hiệu ứng Ân Tứ của trang bị; từ Kẻ Khờ của Vật Phong Ấn);\n2. Chỉ tính các <Highlight>thuộc tính công-thủ</> phổ biến; một số thuộc tính đặc biệt (như tăng Tốc Độ Đánh, tăng Khiên nhận được) không nằm trong phạm vi tính toán;\n3. Mức tăng sẽ thay đổi theo <Highlight>cảnh mục tiêu</>, <Highlight>thuộc tính hiện tại</> của Phi Phàm Giả và <Highlight>thuộc tính mục tiêu đối kháng</>. Kết quả không hoàn toàn chính xác, chỉ dùng tham khảo.\n4. Khi <Highlight>thuộc tính hiện tại</> của Phi Phàm Giả chênh lệch quá lớn so với <Highlight>thuộc tính mục tiêu đối kháng</>, một số hiệu ứng đã chạm giới hạn trên hoặc dưới, khiến mức tăng suy giảm nhanh hoặc về 0; lúc này đánh giá sẽ sai lệch nghiêm trọng.",
    [1240251532110593] = "Khi Sinh Mệnh nhân vật về 0 sẽ rơi vào trạng thái Tiêu Tán,\ncần bản thân hoặc người khác hỗ trợ Phục Tô mới trở lại bình thường.\n\nGiới Hạn Sinh Mệnh của nhân vật: {*d,F1690001,MaxHp}",
    [1240251532110849] = "Tấn Công tăng Sát Thương nhân vật gây ra; mức tăng phụ thuộc hệ số kỹ năng và loại Sát Thương, đồng thời chịu ảnh hưởng bởi Phòng Thủ Vật Lý hoặc Phòng Thủ Ma Pháp của mục tiêu.\n\nTấn Công Vật Lý nhân vật: {*d,F1690001,pAtkMin}-{*d,F1690001,pAtkMax}\nTấn Công Ma Pháp nhân vật: {*d,F1690001,mAtkMin}-{*d,F1690001,mAtkMax}",
    [1240251532111105] = "Triệt tiêu Tấn Công Vật Lý hoặc Ma Pháp từ nguồn tấn công; mỗi 3 điểm Giáp triệt tiêu 2 điểm Tấn Công. Khi Giáp vượt 4 lần Phá Giáp của nguồn tấn công, mỗi 1 điểm vượt triệt tiêu 1 điểm Tấn Công.\n\nGiáp của nhân vật: {*d,F1690001,AirShield}",
    [1240251532111361] = "Giảm Sát Thương Vật Lý và Sát Thương Ma Pháp phải chịu.\n\nPhòng Thủ Vật Lý của nhân vật: {*d,F1690001,pDef}\nPhòng Thủ Ma Pháp của nhân vật: {*d,F1690001,mDef}",
    [1240251532111617] = "Bỏ qua Phòng Thủ Vật Lý hoặc Phòng Thủ Ma Pháp của mục tiêu dựa trên loại sát thương tấn công (hiệu ứng phần trăm có hiệu lực sau hiệu ứng giá trị cố định).\n\nPhá Phòng Vật Lý của nhân vật: {*d,F1690001,pDefReduce}+{*.1f**,F1690001,pDefDivi}\nPhá Phòng Ma Pháp của nhân vật: {*d,F1690001,mDefReduce}+{*.1f**,F1690001,mDefDivi}",
    [1240251532111873] = "Tăng sát thương do nhân vật gây ra; mức tăng phụ thuộc hệ số kỹ năng và chịu ảnh hưởng bởi Phòng Thủ Đặc Biệt của mục tiêu.\n\nTấn Công Đặc Biệt của nhân vật: {*d,F1690001,AdditionalAtk}",
    [1240251532112129] = "Bỏ qua {*d,F1690001,AdditionalIgnore} Phòng Thủ Đặc Biệt của mục tiêu, giảm khả năng mục tiêu kháng Tấn Công Đặc Biệt. Khi Phá Phòng Đặc Biệt vượt Phòng Thủ Đặc Biệt của mục tiêu, có thể tiếp tục tăng hiệu quả tăng sát thương của Tấn Công Đặc Biệt.\n\nPhá Phòng Đặc Biệt của nhân vật: {*d,F1690001,AdditionalIgnore}",
    [1240251532112385] = "Phòng Thủ Đặc Biệt tăng khả năng kháng Tấn Công Đặc Biệt của nhân vật, giảm mức tăng sát thương mà nguồn tấn công nhận được từ Tấn Công Đặc Biệt.\n\nPhòng Thủ Đặc Biệt của nhân vật: {*d,F1690001,AdditionalAnti}",
    [1240251532112641] = "Dựa trên loại sát thương, bỏ qua Chặn Đòn Vật Lý hoặc Chặn Đòn Ma Pháp của mục tiêu, qua đó giảm xác suất đòn đánh bị chặn. Khi Xuyên Thấu vượt Chặn Đòn cùng loại của mục tiêu, trong một phạm vi nhất định sẽ tiếp tục giảm xác suất bị chặn, cho tới khi chắc chắn không kích hoạt Chặn Đòn.\n\nXuyên Thấu Vật Lý của nhân vật: {*d,F1690001,pPierce}\nXuyên Thấu Ma Pháp của nhân vật: {*d,F1690001,mPierce}",
    [1240251532112897] = "Tăng xác suất nhân vật Chặn Đòn Sát Thương Vật Lý hoặc Ma Pháp. Sau khi Chặn Đòn, nhân vật chỉ chịu 50% sát thương và lần sát thương đó không thể Bạo Kích (Tỷ Lệ Chặn Đòn không vượt 75%).\n\nChặn Đòn Vật Lý của nhân vật: {*d,F1690001,pBlock}\nChặn Đòn Ma Pháp của nhân vật: {*d,F1690001,mBlock}",
    [1240251532113153] = "Tăng xác suất Bạo Kích sau khi kỹ năng sát thương trúng mục tiêu (Tỷ Lệ Bạo Kích sau khi trúng không vượt 75%). Khi Bạo Kích, sát thương tăng theo một hệ số nhất định.\nTrị Liệu không thể Bạo Kích.\n\nBạo Kích Vật Lý của nhân vật: {*d,F1690001,pCrit}\nBạo Kích Ma Pháp của nhân vật: {*d,F1690001,mCrit}",
    [1240251532113409] = "Dựa trên loại sát thương, triệt tiêu Bạo Kích Vật Lý hoặc Bạo Kích Ma Pháp của nguồn tấn công, giảm xác suất nhân vật chịu sát thương Bạo Kích tương ứng (Tỷ Lệ Bạo Kích sau khi trúng không thấp hơn 5%).\n\nKháng Bạo Kích Vật Lý của nhân vật: {*d,F1690001,pCritAnti}\nKháng Bạo Kích Ma Pháp của nhân vật: {*d,F1690001,mCritAnti}",
    [1240251532113665] = "Khi tấn công Boss, tăng Tấn Công bản thân.\n\nÁp Chế · Boss của nhân vật: {*.1f**,F1690001,BossHurtMulti_N}",
    [1240251532113921] = "Khi chịu đòn từ Boss, triệt tiêu lượng Áp Chế tương đương (tối đa giảm Áp Chế của bên tấn công về 0).\n\nKháng · Boss của nhân vật: {*.1f**,F1690001,BossHurtDivi_N}",
    [1240251532114177] = "Tăng toàn bộ Kháng Khống Chế, giảm xác suất trúng hoặc thời gian duy trì của hiệu ứng khống chế tương ứng.\nKháng Đẩy Lùi: {*d,F1690001,HitBackEva}  Kháng Kéo: {*d,F1690001,HitDragEva}\nKháng Hất Tung: {*d,F1690001,HitFloatEva}  Kháng Hất Văng: {*d,F1690001,HitFlyEva}\nKháng Đánh Ngã: {*d,F1690001,HitDownEva}  Kháng Cứng Đờ: {*d,F1690001,HitStiffEva}\nKháng Chậm: {*d,F1690001,SlowEva}  Kháng Ngủ: {*d,F1690001,SleepEva}\nKháng Cấm Cố: {*d,F1690001,StuckEva}  Kháng Choáng: {*d,F1690001,DizzyEva}\nKháng Câm Lặng: {*d,F1690001,SilentEva}  Kháng Trì Trệ: {*d,F1690001,DodgeLockEva}",
    [1240251532114433] = "Tăng hiệu quả Trị Liệu do nhân vật gây ra; mức tăng phụ thuộc hệ số kỹ năng.\n\nCường Hoá Trị Liệu của nhân vật: {*d,F1690001,HealPlus}",
    [1240251532114689] = "Bỏ qua Giáp của mục tiêu, giảm khả năng kháng Tấn Công Vật Lý hoặc Ma Pháp. Khi Phá Giáp vượt Giáp của mục tiêu, mỗi 3 điểm vượt chuyển thành 1 điểm Tấn Công.\n\nPhá Giáp của nhân vật: {*d,F1690001,ShieldBreak}",
    [1240251532114945] = "Tăng giá trị cơ sở của kỹ năng sát thương, bị Kháng Kỹ Năng của mục tiêu triệt tiêu. Giá trị cơ sở kỹ năng không chịu ảnh hưởng bởi Phòng Thủ.\n\nCường Hóa Kỹ Năng của nhân vật: {*d,F1690001,SkillPlus}",
    [1240251532115201] = "Giảm giá trị cơ sở của kỹ năng sát thương từ nguồn tấn công, triệt tiêu Cường Hóa Kỹ Năng của nguồn tấn công. Giá trị cơ sở kỹ năng không chịu ảnh hưởng bởi Phòng Thủ.\n\nKháng Kỹ Năng của nhân vật: {*d,F1690001,BeSkilledReduce}",
    [1240251532115457] = "Giảm Sát Thương Vật Lý phải chịu.\n\nPhòng Thủ Vật Lý của nhân vật: {*d,F1690001,pDef}",
    [1240251532115713] = "Giảm Sát Thương Ma Pháp phải chịu.\n\nPhòng Thủ Ma Pháp của nhân vật: {*d,F1690001,mDef}",
    [1240251532115969] = "Tăng sát thương gây lên nhân vật thuộc Pathway Vật Lý. Mức tăng phụ thuộc hệ số kỹ năng và loại sát thương, chịu ảnh hưởng bởi Phòng Thủ Vật Lý hoặc Phòng Thủ Ma Pháp của mục tiêu.\nPathway Vật Lý gồm Ca Tụng Giả, Thầy Bói, Chiến Sĩ.",
    [1240251532116225] = "Tăng sát thương gây lên nhân vật thuộc Pathway Ma Pháp. Mức tăng phụ thuộc hệ số kỹ năng và loại sát thương, chịu ảnh hưởng bởi Phòng Thủ Vật Lý hoặc Phòng Thủ Ma Pháp của mục tiêu.\nPathway Ma Pháp gồm Khán Giả, Học Đồ, Kẻ Dòm Ngó Bí Ẩn.",
    [1240251532119297] = "Không thể chủ động tấn công Phi Phàm Giả có cấp ≤ mức đã đặt (tối thiểu Cấp 25).",
    [1240251532119553] = "Sau khi bật, không thể chủ động tấn công Phi Phàm Giả tên xanh.",
    [1240251532119809] = "Sau khi bật, không thể chủ động tấn công Phi Phàm Giả thuộc CLB không thù địch.",
    [1240251532120065] = "Sau khi bật, không thể chủ động tấn công Phi Phàm Giả cùng CLB.",
    [1240251532121089] = "Khi dùng kỹ năng, nhân vật sẽ tự động di chuyển vào phạm vi thi triển rồi mới dùng.",
    [1240251532121345] = "Khi kỹ năng đang hồi chiêu, nhấn kỹ năng sẽ tung đánh thường.",
    [1240251532121601] = "Trên thanh kỹ năng giao diện chính, giữ con trỏ trên biểu tượng kỹ năng một lúc sẽ hiển thị mô tả tương ứng.",
    [1240251532121857] = "Trên thanh kỹ năng giao diện chính, nhấn giữ kỹ năng một lúc để xem mô tả tương ứng.",
    [1240251532122113] = "Sau khi bật, di chuột lên mục tiêu sẽ làm nổi bật mục tiêu đó; kỹ năng sẽ ưu tiên chọn mục tiêu này để thi triển.",
    [1240251532122369] = "Sau khi bật, kỹ năng sẽ ưu tiên thi triển tại vị trí con trỏ chuột.",
    [1240251532123137] = "Tiêu hao đạo cụ để gửi tin nhắn mà toàn bộ người chơi trong server đều có thể thấy; tin sẽ hiển thị ở chữ chạy và kênh phát sóng.",
    [1240251532123649] = "Gia nhập hoặc tạo CLB để tham gia nhiều hoạt động CLB, nhận phần thưởng phong phú và Huy Chương Đồng Hành; Huy Chương Đồng Hành có thể đổi vật phẩm tại Cửa Hàng CLB.\nCLB gồm CLB Nhàn Nhã và CLB Chiến Đấu, có thể đổi trong thông tin CLB. CLB Nhàn Nhã không hiển thị Điểm Phi Phàm trong danh sách thành viên.",
    [1240251532125187] = "Thời gian mở Cấp Nhập Vai tiếp theo: <Yellow>%s</>\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nhận Kinh Nghiệm Nhận Thức</>\nNhận thức đầy đủ giúp thúc đẩy quá trình Nhập Vai. Hoàn thành Chính Tuyến, Nhánh, nhiệm vụ Thời Đại và Du Hành, cùng các hoạt động hằng ngày như <Yellow>Nằm Thắng Nhẹ Nhàng, Lấy Chiến Nuôi Chiến, Phiêu Lưu Thế Giới</> đều cho nhiều Kinh Nghiệm Nhận Thức. Khi tái trải nghiệm lịch sử của ngài “Kẻ Khờ”, dưới ảnh hưởng của sức mạnh “Ghép Nối”, bạn cũng nhận được phần Kinh Nghiệm Nhận Thức của riêng mình.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy Tắc Giới Hạn Cấp</>\nKhi Cấp Nhập Vai đạt giới hạn hiện tại và Kinh Nghiệm Nhận Thức đã đầy, bạn không thể tiếp tục nhận Kinh Nghiệm Nhận Thức cho đến khi mở giới hạn Cấp Nhập Vai mới. Khi Cấp Nhập Vai đạt giới hạn cuối, Kinh Nghiệm Nhận Thức tiếp tục tích lũy sẽ dùng để mở Cấp Thần Tính — nhận thức vượt quá giới hạn khiến Nhân Tính ngày càng phai nhạt, tiến gần Thần hơn.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nhân Tính và Thần Tính Trong Nhập Vai</>\n“Vạn vật đều có Thần Tính; khi Nhập Vai vượt quá giới hạn, bạn sẽ dần tiến về Thần Tính nguyên sơ.”\nThông qua trải nghiệm, nhiệm vụ và khám phá hằng ngày, Phi Phàm Giả không ngừng tiếp nhận nhận thức về thế giới và chuyển hóa thành <Yellow>Kinh Nghiệm Nhận Thức</>. Tích lũy kinh nghiệm để nâng dần <Yellow>Cấp Nhập Vai</>, củng cố sự ổn định của tinh thần và tồn tại thông qua Nhập Vai.\nTuy nhiên, nhận thức và Nhập Vai đều ẩn chứa rủi ro; mỗi bước Nhập Vai cũng phải trả giá. Sau khi Cấp Nhập Vai đạt giới hạn cuối, Nhân Tính không còn đủ sức duy trì ảnh hưởng của Nhập Vai — phần Nhập Vai tiếp theo sẽ bắt đầu định hình Thần Tính. Phi Phàm Giả sẽ dần tiến tới Thần Tính, từ đó nâng <Yellow>Cấp Thần Tính</>.\nĐể tránh tiếp nhận quá nhiều nhận thức trong thời gian ngắn khiến tinh thần sụp đổ, ngài “Kẻ Khờ” đã ban phúc bảo hộ giới hạn cấp. Ở Cấp Nhập Vai hoặc Cấp Thần Tính hiện tại, thân thể và tinh thần phải trải qua đủ thời gian thích nghi, lắng đọng mới có thể phá giới hạn, chịu được nhận thức tầng cao hơn và tiến sang giai đoạn tiếp theo.",
    [1240251532125443] = "Thời gian mở Cấp Thần Tính tiếp theo: <Yellow>%s</>\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nhận Kinh Nghiệm Nhận Thức</>\nNhận thức đầy đủ giúp thúc đẩy Nhập Vai. Hoàn thành Chính Tuyến, Nhánh, nhiệm vụ Thời Đại và Du Hành, cùng các hoạt động hằng ngày như <Yellow>Nằm Thắng Nhẹ Nhàng, Lấy Chiến Nuôi Chiến, Phiêu Lưu Thế Giới</> đều cho nhiều Kinh Nghiệm Nhận Thức. Khi tái trải nghiệm lịch sử của ngài “Kẻ Khờ”, dưới ảnh hưởng của sức mạnh “Ghép Nối”, bạn cũng nhận được phần Kinh Nghiệm Nhận Thức của riêng mình. Sau khi đạt giới hạn Cấp Nhập Vai, Kinh Nghiệm Nhận Thức nhận được sẽ được chuyển hóa để tiếp tục nâng Cấp Thần Tính.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy Tắc Giới Hạn Cấp</>\nSau khi Cấp Nhập Vai đạt giới hạn cuối, Kinh Nghiệm Nhận Thức tiếp tục tích lũy sẽ được chuyển đổi theo tỷ lệ để nâng Cấp Thần Tính. Khi Cấp Thần Tính đạt giới hạn hiện tại, không thể tiếp tục nhận Kinh Nghiệm Nhận Thức cho đến khi mở Cấp Thần Tính mới.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nhân Tính và Thần Tính Trong Nhập Vai</>\n“Vạn vật đều có Thần Tính; khi Nhập Vai vượt quá giới hạn, bạn sẽ dần tiến về Thần Tính nguyên sơ.”\nPhi Phàm Giả thông qua trải nghiệm, nhiệm vụ và khám phá hằng ngày để tiếp nhận nhận thức về thế giới, chuyển thành <Yellow>Kinh Nghiệm Nhận Thức</>. Tích lũy kinh nghiệm để nâng <Yellow>Cấp Nhập Vai</>, củng cố sự ổn định của tinh thần và tồn tại.\nNhưng nhận thức và Nhập Vai đều có rủi ro; mỗi bước đều phải trả giá. Khi Cấp Nhập Vai đạt giới hạn cuối, Nhân Tính không còn đủ sức duy trì ảnh hưởng của Nhập Vai — phần tiếp theo sẽ bắt đầu định hình Thần Tính. Phi Phàm Giả dần tiến tới Thần Tính và nâng <Yellow>Cấp Thần Tính</>.\nĐể tránh tiếp nhận quá nhiều nhận thức trong thời gian ngắn khiến tinh thần sụp đổ, ngài “Kẻ Khờ” đã ban phúc bảo hộ giới hạn cấp. Ở Cấp Nhập Vai hoặc Cấp Thần Tính hiện tại, thân thể và tinh thần phải trải qua đủ thời gian thích nghi, lắng đọng mới có thể phá giới hạn, chịu được nhận thức tầng cao hơn và tiến sang giai đoạn tiếp theo.",
    [1240251532125698] = "Hiệu suất nhận Kinh Nghiệm Nhận Thức hiện tại: <Yellow>%d%%</>\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nhận Kinh Nghiệm Nhận Thức</>\nNhận thức đầy đủ giúp thúc đẩy Nhập Vai. Hoàn thành Chính Tuyến, Nhánh, nhiệm vụ Thời Đại và Du Hành, cùng các hoạt động hằng ngày như <Yellow>Nằm Thắng Nhẹ Nhàng, Lấy Chiến Nuôi Chiến, Phiêu Lưu Thế Giới</> đều cho nhiều Kinh Nghiệm Nhận Thức. Khi tái trải nghiệm lịch sử của ngài “Kẻ Khờ”, dưới ảnh hưởng của sức mạnh “Ghép Nối”, bạn cũng nhận được phần Kinh Nghiệm Nhận Thức của riêng mình.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy Tắc Giới Hạn Cấp</>\nKhi Cấp Nhập Vai đạt giới hạn cuối, Kinh Nghiệm Nhận Thức tiếp tục tích lũy sẽ dùng để mở Cấp Thần Tính — nhận thức vượt quá giới hạn khiến Nhân Tính ngày càng phai nhạt, tiến gần Thần hơn.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nhân Tính và Thần Tính Trong Nhập Vai</>\n“Vạn vật đều có Thần Tính; khi Nhập Vai vượt quá giới hạn, bạn sẽ dần tiến về Thần Tính nguyên sơ.”\nPhi Phàm Giả thông qua trải nghiệm, nhiệm vụ và khám phá hằng ngày để tiếp nhận nhận thức về thế giới, chuyển thành <Yellow>Kinh Nghiệm Nhận Thức</>. Tích lũy kinh nghiệm để nâng <Yellow>Cấp Nhập Vai</>, củng cố sự ổn định của tinh thần và tồn tại.\nNhưng nhận thức và Nhập Vai đều có rủi ro; mỗi bước đều phải trả giá. Khi Cấp Nhập Vai đạt giới hạn cuối, Nhân Tính không còn đủ sức duy trì ảnh hưởng của Nhập Vai — phần tiếp theo sẽ bắt đầu định hình Thần Tính. Phi Phàm Giả dần tiến tới Thần Tính và nâng <Yellow>Cấp Thần Tính</>.\nĐể tránh tiếp nhận quá nhiều nhận thức trong thời gian ngắn khiến tinh thần sụp đổ, ngài “Kẻ Khờ” đã ban phúc bảo hộ giới hạn cấp. Ở Cấp Nhập Vai hoặc Cấp Thần Tính hiện tại, thân thể và tinh thần phải trải qua đủ thời gian thích nghi, lắng đọng mới có thể phá giới hạn, chịu được nhận thức tầng cao hơn và tiến sang giai đoạn tiếp theo.",
    [1240251532125954] = "Hiệu suất nhận Kinh Nghiệm Nhận Thức hiện tại: <Yellow>%d%%</>\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nhận Kinh Nghiệm Nhận Thức</>\nNhận thức đầy đủ giúp thúc đẩy Nhập Vai. Hoàn thành Chính Tuyến, Nhánh, nhiệm vụ Thời Đại và Du Hành, cùng các hoạt động hằng ngày như <Yellow>Nằm Thắng Nhẹ Nhàng, Lấy Chiến Nuôi Chiến, Phiêu Lưu Thế Giới</> đều cho nhiều Kinh Nghiệm Nhận Thức. Khi tái trải nghiệm lịch sử của ngài “Kẻ Khờ”, dưới ảnh hưởng của sức mạnh “Ghép Nối”, bạn cũng nhận được phần Kinh Nghiệm Nhận Thức của riêng mình.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy Tắc Giới Hạn Cấp</>\nKhi Cấp Thần Tính của Phi Phàm Giả đạt giới hạn mùa, không thể tiếp tục nhận Kinh Nghiệm Nhận Thức.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nhân Tính và Thần Tính Trong Nhập Vai</>\n“Vạn vật đều có Thần Tính; khi Nhập Vai vượt quá giới hạn, bạn sẽ dần tiến về Thần Tính nguyên sơ.”\nPhi Phàm Giả thông qua trải nghiệm, nhiệm vụ và khám phá hằng ngày để tiếp nhận nhận thức về thế giới, chuyển thành <Yellow>Kinh Nghiệm Nhận Thức</>. Tích lũy kinh nghiệm để nâng <Yellow>Cấp Nhập Vai</>, củng cố sự ổn định của tinh thần và tồn tại.\nNhưng nhận thức và Nhập Vai đều có rủi ro; mỗi bước đều phải trả giá. Khi Cấp Nhập Vai đạt giới hạn cuối, Nhân Tính không còn đủ sức duy trì ảnh hưởng của Nhập Vai — phần tiếp theo sẽ bắt đầu định hình Thần Tính. Phi Phàm Giả dần tiến tới Thần Tính và nâng <Yellow>Cấp Thần Tính</>.\nĐể tránh tiếp nhận quá nhiều nhận thức trong thời gian ngắn khiến tinh thần sụp đổ, ngài “Kẻ Khờ” đã ban phúc bảo hộ giới hạn cấp. Ở Cấp Nhập Vai hoặc Cấp Thần Tính hiện tại, thân thể và tinh thần phải trải qua đủ thời gian thích nghi, lắng đọng mới có thể phá giới hạn, chịu được nhận thức tầng cao hơn và tiến sang giai đoạn tiếp theo.",
    [1240251532126209] = "Kỹ năng mang hiệu ứng này sẽ hồi Quang Năng cho Ca Tụng Giả khi đáp ứng điều kiện sử dụng.\nCác kỹ năng hồi Quang Năng: Mộc Quang Chi Kích, Phán Quyết Tụ Năng, Khúc Ca Quang Minh, Trục Quang Huy Kích, Huy Quang Phù Hộ, Xung Phong Quang Năng.",
    [1240251532126465] = "Một số kỹ năng của Ca Tụng Giả tiêu hao Quang Năng để tạo hiệu ứng bổ sung.\nKỹ năng tiêu hao Quang Năng: Mang Kiếm Đột Kích, Triệu Hồi Thánh Quang, Ánh Sáng Thần Thánh, Tịnh Trảm",
    [1240251532126977] = "Tiêu hao toàn bộ Quang Năng hiện tại của nhân vật; mỗi điểm Quang Năng cho nhân vật 0.5% Tấn Công.\nNhân vật nhận 20% Giảm Thương.",
    [1240251532127233] = "Khi nhận buff này, lập tức nhận Khiên bằng 15% Giới Hạn Sinh Mệnh.\nTăng 20% Phòng Thủ Vật Lý và Phòng Thủ Ma Pháp. Giá trị Khiên không cộng dồn nhưng có thể được hồi phục, đồng thời thời gian duy trì có thể làm mới.",
    [1240251532127489] = "Khi Thầy Bói thi triển, hiệu ứng bổ sung phụ thuộc số tầng Lá Bài.\nKỹ năng có thể cộng tầng Lá Bài: Không Phải Hư Cấu, Tarot Vận Mệnh, Phi Bài Hoa Thức.\nKỹ năng nhận hiệu ứng bổ sung theo số tầng Lá Bài: Mưa Bài, Hỏa Diễm Khiêu Dược, Biểu Diễn Hạ Màn, Phi Bài, Sợi Tơ Linh Thể, Người Khiển Rối.",
    [1240251532129793] = "1. Dữ liệu BXH tự cập nhật mỗi phút để đảm bảo kịp thời.\n2. Một số BXH hỗ trợ lọc theo Con Đường; nhấn “Tất Cả Con Đường” phía trên để chuyển.\n3. Một số BXH hỗ trợ xem xếp hạng khu vực; nhấn tab khu vực tương ứng phía trên để chuyển.\n4. Nhấn dòng thông tin bản thân ở cuối BXH để nhanh chóng định vị thứ hạng hiện tại.\n5. Nhấn dòng thông tin Phi Phàm Giả khác để xem ngoại hình; nhấn ảnh đại diện để xem Danh Thiếp cá nhân.\n6. Khi Bậc của từng chế độ đạt Vua Thiên Sứ, đồng thời đứng Top 30 BXH Tổng hoặc Top 5 Con Đường, sẽ nhận Bậc Chủ Tể Tinh Tú trong 14 ngày. Nếu Điểm Bậc thay đổi và vẫn đủ điều kiện, thời hạn được làm mới thành 14 ngày.\n7. Trong BXH Phó Bản, chỉ tổ đội người chơi cùng server vượt Phó Bản mới được tính.",
    [1240251532130561] = "Theo chỉ thị của ngài “Kẻ Khờ”, Hội Trưởng Bernadette thiết kế Sổ Tay Nhập Vai — cẩm nang trưởng thành trong thế giới Phi Phàm do Học Phái Tarot cấp cho thành viên, giúp Phi Phàm Giả lĩnh ngộ Nhập Vai, hiểu thế giới Phi Phàm và học Tri Thức Phi Phàm, từ đó chống lại khuynh hướng Mất Khống Chế và điên cuồng, tăng tốc Thăng Bậc; đồng thời xây dựng các mối liên hệ với thế giới này, sớm tạo “Mỏ Neo” nhân tính cho bản thân để chuẩn bị thăng lên Bậc cao hơn.",
    [1240251532132865] = "Phi Phàm Giả có thể “Nhập Vai Trước”, tức nhập vai các nghề nghiệp và thân phận khác nhau trong thế giới thực để bản thân phù hợp với Đặc Tính Phi Phàm tương ứng với các năng lực khác nhau trên Phiến Đá, từ đó nhận và sử dụng nhiều năng lực an toàn hơn. Ngoài ra, “Nhập Vai Thân Phận” giúp Phi Phàm Giả xây dựng quan hệ xã hội sâu hơn trong thế giới thực, tích lũy “Mỏ Neo Nhân Tính” cho việc thăng lên Bậc cao hơn; đồng thời, thành viên Học Phái Tarot càng có nhiều Mỏ Neo trong thế giới thì sự tồn tại của Học Phái Tarot trong Linh Giới càng ổn định.",
    [1240251532134145] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Luật Sự Kiện</>\nTrong thời gian mở sự kiện, mỗi ngày 12:00–24:00 có thể tới Cổng Thời Gian ở Biển Hoa Honachis để đăng ký. Sau khi vào, người chơi chiến đấu với Tai Ách Thế Giới. Có thể đăng ký solo hoặc theo đội; khuyến nghị <Highlight>lập đội xong rồi đăng ký</>.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Thưởng Sự Kiện</>\nKhi Tai Ách Thế Giới chết, người tham chiến nhận Di Tích Tai Ách theo Điểm Cống Hiến, tối đa <Highlight>1200</> mỗi tuần. Khi Di Tích đạt các mốc, có thể nhận thưởng mốc tại trang giới thiệu Tai Ách Thế Giới.\nKhi Tai Ách Thế Giới chết, xếp hạng theo điểm quy đổi từ sát thương đầu ra của đội. Người chơi Top 1000 mỗi tuần nhận thưởng xếp hạng.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Giải Thích BXH</>\nNếu theo đội, lấy <Highlight>tổng sát thương đầu ra của 5 thành viên cao nhất</> làm điểm xếp hạng.\nNếu thành viên đội thay đổi trong trận, tự mất tư cách xếp hạng điểm.",
    [1240251532134657] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Giới Thiệu Lối Chơi</>\nTranh Phong Chúa Tể là PvP tổ đội, tối đa lập đội 3 người để ghép trận. Sau khi vào, mọi người chơi nhận điều chỉnh thuộc tính <Highlight>công bằng</>, <Highlight>Vật Phong Ấn thống nhất ở “Cấp 3”</>.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Điều Kiện Thắng</>\nSau khi vào trận, người chơi đã chết <Highlight>không thể</> được Con Đường Khán Giả <Highlight>hồi sinh</>. Cần hạ toàn bộ đội địch hoặc gây Sát Thương cao hơn khi hết thời gian để giành chiến thắng.",
    [1240251532135169] = "1. Khám phá Đại Thế Giới, mở khóa và thu thập Linh Hồn Cống Hiến hoặc hoàn thành các câu đố Ân Tứ Ẩn Giấu để tăng Độ Hoàn Thành;\n2. Khi Độ Hoàn Thành đạt mốc tương ứng, người chơi có thể nhận thưởng của mốc đó.",
    [1240251532135425] = "Phi Phàm Giả có thể học kiến thức và kỹ xảo của “Trị An Quan”, nhập vai thân phận “Trị An Quan” và thông qua “Nhập Vai Sớm” để dần nhận các năng lực Phi Phàm trên “Phiến Đá Chúc Phúc”.\n1. Mỗi Phi Phàm Giả đồng thời nhận tối đa 3 Truy Nã.\n2. Lệnh Truy Nã sẽ làm mới khi Phi Phàm Giả hoàn thành Truy Nã.\n3. Sau khi một Truy Nã hoàn tất, cùng Truy Nã đó sẽ không xuất hiện lại trong 6 phút.\n4. Có thể chủ động làm mới toàn bộ Truy Nã, tối đa 3 lần mỗi ngày.\n5. Hoàn thành Truy Nã nhận Kinh Nghiệm Trị An và Suli Khóa; Kinh Nghiệm Trị An dùng tăng Cấp Trị An Quan.\n6. Tại Cây Kỹ Năng Trị An có thể nâng và phát triển Kỹ Năng Trị An, cường hóa sáu thuộc tính cơ bản.\n7. Lệnh Truy Nã có ba cấp A/B/C, lần lượt mở ở Cấp Trị An 1/2/4.\n8. Sau khi nhận Lệnh Truy Nã, danh sách nhiệm vụ đồng thời nhận Nhiệm Vụ Truy Nã; nhấn nhiệm vụ để tự tìm đường tới vị trí.",
    [1240251532136193] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Thế Giới Quỷ Bí</>\nTrong tab Thế Giới Quỷ Bí, có thể xem tiến độ <Highlight>Thế Giới Trật Tự</> và <Highlight>Mặt Tối Thành Phố</> của từng bản đồ, đồng thời nhận <Highlight>Thưởng Tiến Độ</>.\n<Highlight>Salon Phong Cách, Nhiệm Vụ Thời Đại</> không tính vào độ hoàn thành Thế Giới Trật Tự.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Thiên Phú Chạy Bàn</>\nTrong tab Thiên Phú Chạy Bàn, nhận <Highlight>buff Thiên Phú</> liên quan dựa trên độ hoàn thành Thế Giới Trật Tự.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Lối Chơi Thú Vị</>\nTập hợp hướng dẫn các sự kiện/lối chơi gặp trong quá trình phiêu lưu.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Khoảnh Khắc Trân Quý</>\nTập hợp các khoảnh khắc quý giá thu thập trong hành trình.",
    [1240251532136449] = "1. Tiêu hao Bảng Vàng để gửi Lì Xì Bảng Khóa; người nhận nhận lượng Bảng Vàng Khóa tương đương;\n2. Sau 24 giờ, phần Lì Xì Bảng Khóa chưa nhận sẽ hoàn lượng Bảng Khóa tương đương;\n3. Với Quà Ngoại Hình, nếu sau 24 giờ vẫn còn trang phục chưa được nhận, sẽ hoàn lượng Bảng Vàng đã tiêu hao khi mua trang phục đó cùng Hạn Mức Tặng Quà tương ứng;\n4. Vật phẩm nhận từ Quà Ngoại Hình là vật phẩm khóa.",
    [1240251532137729] = "1. Tiêu hao Bảng Vàng để gửi Lì Xì Bảng Khóa; người nhận nhận lượng Bảng Vàng Khóa tương đương;\n2. Sau 24 giờ, phần Lì Xì Bảng Khóa chưa nhận sẽ hoàn lượng Bảng Khóa tương đương;\n3. Với Quà Ngoại Hình, nếu sau 24 giờ vẫn còn trang phục chưa được nhận, sẽ hoàn lượng Bảng Vàng đã tiêu hao khi mua trang phục đó cùng Hạn Mức Tặng Quà tương ứng;\n4. Vật phẩm nhận từ Quà Ngoại Hình là vật phẩm khóa",
    [1240251532138241] = "1. Chọn phạm vi bạn muốn đặt <Highlight>hiển thị một phần</> và <Highlight>ẩn thân với ai</>\n2. Nếu trong chat nhóm có người chơi không phải bạn bè, thiết lập phạm vi sẽ không có hiệu lực.",
    [1240251532139521] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Bối Cảnh Chiến Trường</>\n<Highlight>Tận Thế cận kề</>, ô nhiễm từ Tinh Không ngày càng áp sát, <Highlight>sự kiện Phi Phàm</> liên tục xảy ra. Các CLB Phi Phàm lớn tự tổ chức diễn tập liên hợp, mô phỏng đối kháng trong sa bàn lịch sử để ứng phó khủng hoảng sắp tới. <Highlight>Giải Tứ Phương</> là sân huấn luyện lớn nhất và gần thực chiến nhất trong số đó. Các <Highlight>CLB</> cùng tranh tài, không chỉ vì vinh dự mà còn để rèn năng lực bảo vệ nhân loại khi <Highlight>Tận Thế giáng xuống</>.",
    [1240251532140289] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Cấp Hoạt Động</>\nCấp Hoạt Động CLB từ cao xuống thấp:\nHội Vụ Quạnh Quẽ (dưới 720)\nVận Hành Thường (720~2400)\nHội Vụ Phồn Vinh (trên 2400)\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nguồn Hoạt Động</>\nTrợ Cấp Hoạt Động\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Mô Tả Hoạt Động</>\nHoạt Động CLB càng cao, thưởng Chia Lợi Nhuận CLB hàng tuần càng cao.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Tiêu Hao Hoạt Động</>\nBảo trì CLB mỗi ngày trừ %d%% Hoạt Động hiện tại. Nếu Hoạt Động liên tục %d ngày ở mức Hội Vụ Quạnh Quẽ, cấp Phòng Nghị Sự giảm %d. Nếu Phòng Nghị Sự dưới cấp %d, CLB tự giải tán.",
    [1240251532140545] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Tiêu Hao Quỹ CLB</>\nNâng cấp công trình cần tiêu hao Quỹ CLB và chờ một khoảng thời gian. Mỗi công trình có hiệu quả tăng cấp riêng; cấp của các công trình khác không thể vượt cấp Phòng Nghị Sự.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Giới hạn thời gian</>\nGiới hạn nâng cấp công trình được mở dần theo thời gian server. Mốc ngày cho từng cấp:\nCấp 3: sau 8:00 sáng ngày thứ 7 mở server\nCấp 4: sau 8:00 sáng ngày thứ 14\nCấp 5: sau 8:00 sáng ngày thứ 21\nCấp 6: sau 8:00 sáng ngày thứ 30\nCấp 7: sau 8:00 sáng ngày thứ 45\nCấp 8: sau 8:00 sáng ngày thứ 60",
    [1240251532140801] = "1. Trong một số Phó Bản, khi đội chưa đủ người có thể phát Cầu Viện.\n2. Hoàn thành hỗ trợ Cầu Viện của người khác sẽ nhận một lượng Soli Khóa nhất định.\n3. Hỗ trợ thất bại vẫn nhận một ít Soli Khóa.",
    [1240251532141057] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Cơ Chế Thắng Đầu</>\nMỗi ngày Tranh Phong Chúa Tể có 1 lần thưởng Thắng Đầu; lượt chưa dùng có thể cộng dồn, tối đa 3 lần. Sau khi thắng trong Tranh Phong Chúa Tể, tiêu hao 1 lượt Thắng Đầu và nhận gấp đôi Điểm Thắng.",
    [1240251532141569] = "Trong Phân Tuyến Chiến Đấu trên bản đồ, người chơi không thể tấn công đồng đội Tiểu Đội/Raid hoặc thành viên cùng CLB; người chơi khác được xem là địch.",
    [1240251532141825] = "1. Mặc định tắt. Khi tắt, hệ thống lọc tiếng môi trường và tăng cường giọng nói, phù hợp hơn cho voice chat.\n2. Khi bật, tiếng môi trường được tăng cường; nếu phát nhạc bằng thiết bị khác, khả năng thu âm sẽ tốt hơn.\n3. Sau khi rời phòng chat hiện tại, công tắc này sẽ tự đặt lại về Tắt.",
    [1240251532143105] = "“Mảnh Bình Chướng” trong Học Phái Tarot được Ngài “Kẻ Khờ” phong ấn bằng Sương Xám, chứa sức mạnh còn sót lại của Đấng Sáng Tạo “Nguyên Sơ” — chín loại sức mạnh Phi Phàm thuộc các lĩnh vực khác nhau.\n\nThành viên Học Phái Tarot có thể thông qua “Nghi Thức Mật Khế” điều chỉnh trạng thái thân, tâm và linh, tăng độ tương hợp với năng lực của từng lĩnh vực trong “Mảnh Bình Chướng”, hình thành “Thức Tỉnh Phi Phàm Mật Khế” riêng và cường hóa các Năng Lực Phi Phàm.\n\nTuy nhiên cách này cũng mang ô nhiễm và rủi ro. Ngoài một “Lĩnh Vực Mật Khế” vốn tương hợp với Con Đường Phi Phàm của bản thân, mỗi Phi Phàm Giả tối đa có thể Mật Khế thêm một lĩnh vực. Phát triển các “Thiên Phú Mật Khế” khác nhau sẽ tạo mức độ làm chủ năng lực tương ứng khác nhau.",
    [1240251532144385] = "1. Mất kết nối trong <Highlight>%d</> phút vẫn giữ trạng thái xếp hàng; kết nối lại có thể tiếp tục xếp hàng.\n2. Mất kết nối quá <Highlight>%d</> phút sẽ tự động hủy xếp hàng.\n3. Nếu đến lượt khi đang mất kết nối, có thể <Highlight>bỏ qua xếp hàng</> để vào game trực tiếp; hết hiệu lực vào ngày hôm sau.",
    [1240251532145665] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Giới Thiệu Lối Chơi</>\nTrong chiến trường Khoảnh Khắc Vận Mệnh, Phi Phàm Giả chia thành hai phe. Mỗi trận kéo dài <Highlight>4 phút</>; khi kết thúc, phe có điểm cao hơn thắng. Nếu bằng điểm, lần lượt so số mạng hạ gục rồi tổng Sát Thương; bên cao hơn thắng. Nếu vẫn bằng nhau, ngẫu nhiên một phe thắng.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Giải Thích Cơ Chế</>\n<Highlight>Nhận Điểm:</> Có thể nhận qua nhặt Điểm Sáng Cường Hóa, hạ gục, hỗ trợ và tranh đoạt trong Xoáy Tranh Chấp.\n<Highlight>Điểm Neo Tập Kết:</> Trong trận sẽ xuất hiện Điểm Neo Tập Kết trong <Highlight>15 giây</>. Hãy vào điểm neo theo <Highlight>số người yêu cầu</>; khi đủ người và duy trì <Highlight>3 giây</>, Phi Phàm Giả phe mình sẽ được tập kết tại đây, đồng thời người tham gia tập kết nhận buff thuộc tính có thời hạn.\n<Highlight>Xoáy Tranh Chấp:</> Xoáy Tranh Chấp xuất hiện ở giữa chiến trường; khi <Highlight>đếm ngược kết thúc</>, Phi Phàm Giả còn ở trong xoáy sẽ chia đều điểm.\n<Highlight>Điểm Sáng Cường Hóa:</> Điểm Sáng Cường Hóa xuất hiện trên chiến trường; nhặt sẽ nhận <Highlight>điểm và buff thuộc tính</>.\n<Highlight>Nấm Vận Mệnh:</> Trong chiến trường Khoảnh Khắc Vận Mệnh, sau khi Phi Phàm Giả tử trận liên tiếp 3 lần sẽ rơi Nấm Vận Mệnh: đồng minh tử trận rơi Nấm Vận Mệnh xanh mang sức mạnh Phong Nhiêu, nhặt sẽ hồi Sinh Mệnh; kẻ địch tử trận rơi Nấm Vận Mệnh đỏ mang sức mạnh Hủy Diệt, nhặt sẽ bị trừ Sinh Mệnh. Hãy phân biệt trước khi nhặt.",
    [1240251532146177] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Luật Thi Đấu</>\nĐấu trường sử dụng <Highlight>thuộc tính thật của người chơi</>; <Highlight>Trang Bị, Vật Phong Ấn, Bí Ngẫu, Nhân Mạch và hiệu ứng Hệ Thống Thiên Phú</> đều có hiệu lực. Người chơi thi đấu theo Chiến Đội; mỗi đội tối đa có 2 người cùng Con Đường.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Luật Đăng Ký</>\nSau khi mở đăng ký, người chơi có thể lập hoặc gia nhập Chiến Đội. Khi đủ <Highlight>5 thành viên</> có thể đăng ký.\nTừ lúc mở đăng ký đến giai đoạn khóa đăng ký, Đội Trưởng có thể tự do điều chỉnh thành viên, thành viên cũng có thể rời đội. Nếu đội đã đăng ký thay đổi thành viên khiến số người dưới 5, đăng ký tự động bị hủy.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Luật Khóa</>\nTrong giai đoạn khóa đăng ký, đội đã đăng ký có thể vào Khu Chuẩn Bị; đội chưa đăng ký vẫn có thể đăng ký và người chơi vẫn có thể gia nhập đội, nhưng không thể chủ động rời đội hoặc bị Đội Trưởng mời rời. Đội đã đăng ký không thể hủy đăng ký.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Luật Đối Chiến</>\nSau khi giải chính thức bắt đầu, người chơi cần <Highlight>ở lại Khu Chuẩn Bị</> để bảo đảm vào trận bình thường; tự ý rời đi có thể khiến không thể tham gia trận.\nVòng bảng: mỗi vòng ghép ngẫu nhiên đối thủ và đấu 1 trận, tổng cộng 6 vòng. Chọn 16 đội vào vòng trong theo số trận thắng; nếu bằng số thắng, dùng <Highlight>Điểm Vinh Dự để phân định (tham khảo số mạng hạ gục và thời lượng chiến đấu)</>.\nSau vòng bảng là giai đoạn Trợ Lực. Trước vòng loại trực tiếp, thứ hạng được xác định theo <Highlight>tổng Điểm Trợ Lực và Điểm Vinh Dự</>. Sau khi vòng loại bắt đầu vẫn có thể Trợ Lực nhưng không còn ảnh hưởng thứ hạng.\nVòng loại trực tiếp đấu <Highlight>Bo3 thắng 2</>; Chung Kết đấu <Highlight>Bo5 thắng 3</> để xác định quán quân!",
    [1240251532150017] = "Tài Sản Lâu Đài có thể dùng để mua nội thất, bộ phận Lâu Đài và chi trả nâng cấp Lâu Đài;\nCó thể nhận Tài Sản Lâu Đài bằng các cách sau:\n1. Nhận từ lối chơi Đại Gia Đường Sắt;\n2. Chế tạo sản vật tại Xưởng rồi bán trên Thị Trường;",
    [1240251532150529] = "Phân Bố Cấp Sĩ Khí:\n\nSĩ Khí Cấp 1: cần <Highlight>725 Điểm Tài Nguyên</>, toàn bộ thành viên phe nhận <Highlight>2% Áp Chế Hệ và Kháng Hệ</>.\n\nSĩ Khí Cấp 2: cần <Highlight>1450 Điểm Tài Nguyên</>, toàn bộ thành viên phe nhận <Highlight>4% Áp Chế Hệ và Kháng Hệ</>.\n\nSĩ Khí Cấp 3: cần <Highlight>2175 Điểm Tài Nguyên</>, toàn bộ thành viên phe nhận <Highlight>6% Áp Chế Hệ và Kháng Hệ</>.\n\nSĩ Khí Cấp 4: cần <Highlight>2900 Điểm Tài Nguyên</>, toàn bộ thành viên phe nhận <Highlight>8% Áp Chế Hệ và Kháng Hệ</>.\n\nSĩ Khí Cấp 5: cần <Highlight>3625 Điểm Tài Nguyên</>, toàn bộ thành viên phe nhận <Highlight>10% Áp Chế Hệ và Kháng Hệ</>.\n\nSĩ Khí Cấp 6: cần <Highlight>4350 Điểm Tài Nguyên</>, toàn bộ thành viên phe nhận <Highlight>12% Áp Chế Hệ và Kháng Hệ</>.\n\nSĩ Khí Cấp 7: cần <Highlight>5075 Điểm Tài Nguyên</>, toàn bộ thành viên phe nhận <Highlight>14% Áp Chế Hệ và Kháng Hệ</>.\n\nSĩ Khí Cấp 8: cần <Highlight>5800 Điểm Tài Nguyên</>, toàn bộ thành viên phe nhận <Highlight>16% Áp Chế Hệ và Kháng Hệ</>.\n\nSĩ Khí Cấp 9: cần <Highlight>6525 Điểm Tài Nguyên</>, toàn bộ thành viên phe nhận <Highlight>18% Áp Chế Hệ và Kháng Hệ</>.\n\nSĩ Khí Cấp 10: cần <Highlight>7250 Điểm Tài Nguyên</>, toàn bộ thành viên phe nhận <Highlight>20% Áp Chế Hệ và Kháng Hệ</>.\n",
    [1240251532151041] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Hệ Thống Thiên Phú</> 1. Mỗi Phi Phàm Giả có hai hướng Thiên Phú khác nhau; mỗi hướng gồm <Highlight>Nút Thiên Phú Cơ Bản</> và <Highlight>Nút Thiên Phú Đặc Biệt</>. 2. Dùng <Highlight>Điểm Thiên Phú</> nâng Nút Thiên Phú; <Highlight>Điểm Thiên Phú</> nhận qua <Highlight>Thăng Bậc</>. 3. Nâng <Highlight>Nút Thiên Phú Cơ Bản</> để nhận sức mạnh cao hơn. Một số <Highlight>Nút Thiên Phú Cơ Bản</> sau khi nâng sẽ mở <Highlight>Nút Thiên Phú Đặc Biệt</>. 4. <Highlight>Nút Thiên Phú Đặc Biệt</> thường chứa năng lực Phi Phàm đặc thù; nâng cấp sẽ cường hóa hoặc thay đổi một số năng lực. 5. <Highlight>Điểm Thiên Phú</> có thể đồng thời phân cho cả hai hướng, cho phép cường hóa các <Highlight>Nút Thiên Phú</> khác nhau ở hai hướng; nhưng cùng lúc chỉ kích hoạt được một hướng để có hiệu lực. 6. Nâng một số <Highlight>Nút Thiên Phú Cơ Bản</> bị giới hạn bởi <Highlight>Bậc</>. Tuy nhiên, có thể reset bất kỳ Nút Thiên Phú nào bất cứ lúc nào để thử hiệu ứng cường hóa khác.",
    [1240251532152065] = "<Highlight>Vật Phong Ấn</>: Vật Phong Ấn bạn đang sử dụng về bản chất là hình chiếu lịch sử do một “Kỳ Tích Sư” thần bí triệu hồi. So với Vật Phong Ấn nguyên bản, hình chiếu lịch sử này có năng lực suy yếu nhưng tác dụng phụ cũng nhẹ hơn, có thể mang lại nhiều cường hóa cho Phi Phàm Giả.\nVật Phong Ấn thường chia thành ba loại: Tấn Công, Phòng Thủ và Đặc Hóa; mỗi loại tối đa mang 1 món. Vật Phong Ấn đặc biệt cung cấp nhiều năng lực đặc thù, không trực tiếp tăng Chiến Lực của Phi Phàm Giả.\n<Highlight>Cấp Vật Phong Ấn</>: Vật Phong Ấn thường ban đầu đều là Cấp “3”. Sau khi Cấp Nhập Vai đạt 46, có thể tiêu hao “Hồi Âm Lịch Sử” để nâng Vật Phong Ấn lên Cấp “2”. Vật Phong Ấn Cấp “3” tối đa kích hoạt hiệu ứng của 4 từ Vật Chất Phi Phàm; Cấp “2” tối đa 5 từ.\n<Highlight>Vật Chất Phi Phàm</>: Khi Cấp Nhập Vai đạt 42, mở khóa khảm Vật Chất Phi Phàm. Khảm các Vật Chất Phi Phàm khác nhau sẽ thêm nhiều hiệu ứng cho Vật Phong Ấn.\n<Highlight>Cộng Hưởng Phi Phàm</>: Khi Vật Phong Ấn được khảm Vật Chất Phi Phàm, dựa theo số lượng từ của Vật Chất Phi Phàm để kích hoạt thêm hiệu ứng Phi Phàm. Nâng cấp Vật Phong Ấn sẽ tăng số từ tối đa có thể kích hoạt Cộng Hưởng Phi Phàm.\n<Highlight>Tri Thức Phi Phàm</>: Nâng cấp Tri Thức Phi Phàm giúp bạn làm chủ sức mạnh Phi Phàm tốt hơn; hiệu quả năng lực Phi Phàm của Vật Phong Ấn, giá trị thuộc tính cố định của Vật Chất Phi Phàm và thuộc tính Cộng Hưởng Phi Phàm đều tăng theo cấp Tri Thức Phi Phàm.\n<Highlight>Tụ Hợp</>: Khi Cấp Nhập Vai đạt 47, mở khóa Tụ Hợp Vật Chất Phi Phàm. Tụ hợp hai Vật Chất Phi Phàm phẩm chất vàng thành một Vật Chất Phi Phàm mới, có thể nhận Vật Chất Phi Phàm với nhiều từ hơn.",
    [1240251532152321] = "<Highlight>Tụ Hợp Phi Phàm</>: Có thể tụ hợp hai Vật Chất Phi Phàm thành một Vật Chất Phi Phàm mới.\n<Highlight>Kế Thừa Từ</>: Khi Tụ Hợp Phi Phàm, <Highlight>toàn bộ</> từ của sản phẩm sẽ được chọn ngẫu nhiên từ các từ của <Highlight>Vật Chất Phi Phàm đã đưa vào</>.\n<Highlight>Dị Biến Từ</>: Khi tổng số từ của Vật Chất Phi Phàm đưa vào tụ hợp ≥6, sau tụ hợp có xác suất cực nhỏ phát sinh Dị Biến, tạo Từ Dị Biến. Tổng số và loại từ khác nhau sẽ mở ra các Từ Dị Biến có thể xuất hiện khác nhau. Mỗi lần tụ hợp không ra Dị Biến sẽ tăng xác suất Dị Biến cho những lần sau.\n<Highlight>Nâng Cấp Từ</>: Khi tổng số từ đưa vào tụ hợp ≥6, sau tụ hợp có xác suất Nâng Cấp Từ, tăng giá trị thuộc tính của một số từ.\n<Highlight>Tụ Hợp Cao Cấp</>: Khi đang sở hữu ít nhất 2 Vật Chất Phi Phàm Tấn Công và 2 Vật Chất Phi Phàm Phòng Thủ có từ 4 từ trở lên, mở khóa đưa Vật Chất Phi Phàm Tấn Công 4 từ vào tụ hợp; khi đang sở hữu ít nhất 2 Vật Chất Phi Phàm Tấn Công và 2 Vật Chất Phi Phàm Phòng Thủ 5 từ, mở khóa đưa Vật Chất Phi Phàm 5 từ vào tụ hợp.\n<Highlight>Độ Thành Thạo Tụ Hợp</>: Tụ Hợp Vật Chất Phi Phàm sẽ tăng <Highlight>Độ Thành Thạo Tụ Hợp</>. Độ thành thạo reset theo mùa; đạt mốc nhất định sẽ nhận thưởng.",
    [1240251532152577] = "<Highlight>Vật Chất Phi Phàm</>: Vật chất mang sức mạnh Phi Phàm, có thể khảm vào Vật Phong Ấn để ổn định Hình Chiếu Lịch Sử và mở thêm hiệu ứng Phi Phàm (Cộng Hưởng Phi Phàm). <Highlight>Dòng Ngẫu Nhiên</>: Sức mạnh Đặc Tính Phi Phàm được lượng hóa thành dòng thuộc tính. Do trình tự và số lượng Đặc Tính cấu thành khác nhau, số dòng, loại và cường độ của từng Vật Chất Phi Phàm cũng khác nhau. Ít nhất 1 dòng, tối đa 6 dòng; Vật Chất Phi Phàm trên 6 dòng hiện chưa được phát hiện. <Highlight>Dòng Dị Biến</>: Dòng ngẫu nhiên có thể chịu ảnh hưởng hoặc ô nhiễm của sức mạnh vị cách cao và phát sinh Dị Biến; Dòng Dị Biến mạnh hơn dòng thường.",
    [1240251532152833] = "Nhận tăng thuộc tính theo số từ của Vật Chất Phi Phàm:\n1 từ: Tấn Công +200, Tấn Công Đặc Biệt +70\n2 từ: Tấn Công +400, Tấn Công Đặc Biệt +140\n3 từ: Tấn Công +600, Tấn Công Đặc Biệt +210\n4 từ: Tấn Công +800, Tấn Công Đặc Biệt +280\n<Highlight>Nâng Cấp Vật Phong Ấn có thể mở khóa thêm hiệu ứng Cộng Hưởng Phi Phàm.</>\n<Highlight>Nâng Cấp Tri Thức Phi Phàm có thể tăng hiệu quả Cộng Hưởng Phi Phàm.</>",
    [1240251532153089] = "Nhận tăng thuộc tính theo số từ của Vật Chất Phi Phàm:\n1 từ: Tấn Công +200, Tấn Công Đặc Biệt +70\n2 từ: Tấn Công +400, Tấn Công Đặc Biệt +140\n3 từ: Tấn Công +600, Tấn Công Đặc Biệt +210\n4 từ: Tấn Công +800, Tấn Công Đặc Biệt +280\n5 từ: Tấn Công +1000, Tấn Công Đặc Biệt +350\n<Highlight>Nâng Cấp Vật Phong Ấn có thể mở khóa thêm hiệu ứng Cộng Hưởng Phi Phàm.</>\n<Highlight>Nâng Cấp Tri Thức Phi Phàm có thể tăng hiệu quả Cộng Hưởng Phi Phàm.</>",
    [1240251532153345] = "Nhận tăng thuộc tính theo số từ của Vật Chất Phi Phàm:\n1 từ: Tấn Công +200, Tấn Công Đặc Biệt +70\n2 từ: Tấn Công +400, Tấn Công Đặc Biệt +140\n3 từ: Tấn Công +600, Tấn Công Đặc Biệt +210\n4 từ: Tấn Công +800, Tấn Công Đặc Biệt +280\n5 từ: Tấn Công +1000, Tấn Công Đặc Biệt +350\n6 từ: Tấn Công +1200, Tấn Công Đặc Biệt +420\n<Highlight>Tăng cấp Tri Thức Phi Phàm có thể cường hóa hiệu quả Cộng Hưởng Phi Phàm.</>",
    [1240251532153601] = "1. Mục Tiêu Sự Kiện: Tham gia và hoàn thành Sự Kiện Đột Phát xuất hiện trong khu vực chỉ định để nhận thưởng lớn.\n2. Loại Sự Kiện: Gồm <Highlight>“Cốt Truyện”, “Thử Thách”, “Thi Đấu”</>.\n3. Làm Mới: Khi vào “Tingen Tội Ác”, mọi sự kiện đủ điều kiện sẽ xuất hiện ngay; <Highlight>Sự kiện “Thi Đấu” có 2 phút đăng ký</>. Thời gian làm mới Sự Kiện Đột Phát lấy thời điểm người chơi vào cảnh; <Highlight>Sự kiện “Thử Thách” làm mới khoảng mỗi 10 giây</>, nếu đã kết thúc sẽ xuất hiện lại.\n4. Thưởng: Mỗi loại có luật thưởng khác nhau: <Highlight>“Cốt Truyện” thành công được nhận thưởng; “Thử Thách” có nhiều mốc; “Khó · Thử Thách” không chia mốc; “Thi Đấu” phát thưởng theo xếp hạng.</>\n5. Giới Hạn Thưởng: Số lần nhận thưởng từ sự kiện mỗi tuần không giới hạn, nhưng <Highlight>Giá Trị Truy Nã mỗi tuần có trần</>.\n6. Thất Bại: Không hoàn thành mục tiêu (nếu có) trong thời hạn thì thất bại.\n7. Rời Khu: Nếu đi quá xa khỏi khu sự kiện trước khi hoàn thành, bị xem là bỏ sự kiện và không nhận thưởng.\n8. Chiến Lực: Vào vị diện “Tingen Tội Ác” sẽ cân bằng thuộc tính. “Cốt Truyện”, “Khó · Thử Thách”, “Thi Đấu” đều là lối chơi cân bằng; <Highlight>“Kịch Chiến · Bonnie” chịu ảnh hưởng Chiến Lực người chơi và cân bằng thuộc tính theo bậc chuyển đổi Chiến Lực</>.",
    [1240251532153857] = "Vật Phong Ấn 【Nhà Hát Utopia】 do ngài “Kẻ Khờ” ban tặng giúp Phi Phàm Giả nắm giữ và điều khiển Bí Ngẫu.\nSau khi nhận Bí Ngẫu, có thể dùng 1 kỹ năng của Bí Ngẫu và nhận hiệu quả tăng thuộc tính nhân vật từ Bí Ngẫu.\nBí Ngẫu trùng dùng để Bồi Dưỡng Bí Ngẫu, tăng năng lực.\nBí Ngẫu loại Trùng Tinh Tú có thể Biến Hình thành ngoại hình Phi Phàm Giả khác; sau Biến Hình có thể tự do thay trang phục.",
    [1240251532154625] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Điểm Phi Phàm</>\nĐiểm Phi Phàm là đánh giá tổng hợp năng lực chiến đấu và mức bồi dưỡng của Phi Phàm Giả, có thể dùng làm tham khảo để đánh giá tiến độ phát triển.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Chi Tiết Bồi Dưỡng</>\nNhấn Điểm Phi Phàm ở góc phải dưới giao diện Nhân Vật để xem chi tiết bồi dưỡng từng module (một số giới hạn bồi dưỡng mở theo tiến độ mùa).\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Tăng Điểm</>\nTrong hệ thống Điểm Phi Phàm, nhấn module muốn nâng để xem nguyên liệu cần thiết và nguồn nhận.",
    [1240251532154881] = "Khi Bí Ngẫu tại Nhà Hát Utopia làm mới, nếu xuất hiện Bí Ngẫu cùng phẩm chất với Bí Ngẫu Ước Nguyện thì có 80% xác suất đó là Bí Ngẫu Ước Nguyện. Nếu lần này không xuất hiện, lần sau chắc chắn là Bí Ngẫu Ước Nguyện.",
    [1240251532155137] = "Nhờ Vật Phong Ấn <Highlight>Hành Lang Lịch Sử</>, có thể tìm những nhân vật rải rác trong khe hở lịch sử, kết giao với họ và mượn sức mạnh từ quá khứ.\nKết giao nhiều lần tăng mức hiểu biết về mục tiêu, nhận năng lực chân thực và mạnh hơn của họ.\n1. Dùng <Highlight>Kết Giao</> để nhận <Highlight>Nhân Mạch</>, mở khóa kỹ năng tương ứng.\n2. Nhận trùng Nhân Mạch dùng để tăng tầng Nhân Mạch, cường hóa hiệu quả kỹ năng tương ứng.",
    [1240251532155393] = "Giữa các Nhân Mạch còn tồn tại những <Highlight>mối quan hệ</> đặc biệt. Thu thập đủ Nhân Mạch tương ứng để mở khóa/nâng cấp quan hệ, tăng mức Nghiên Cứu Lịch Sử.\nDựa trên mức Nghiên Cứu Lịch Sử, nhận một lượng cộng thuộc tính nhất định.\nQuan hệ chia thành hai loại: <Highlight>Quan Hệ Hiệp Chiến</> và <Highlight>Quan Hệ Lịch Sử</>; cả hai đều tăng Nghiên Cứu Lịch Sử.\nVới Quan Hệ Hiệp Chiến, sau khi mở khóa còn có thể tăng năng lực cho một số Nhân Mạch; tuy nhiên mỗi Nhân Mạch chỉ có thể nhận hiệu quả tăng từ một Quan Hệ Hiệp Chiến.",
    [1240251532155649] = "<Highlight>【Lịch Sử Phi Phàm】</> là sự kiện Kết Giao Nhân Mạch thường trực.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Thông Tin Xác Suất</>\nNhân Mạch phẩm chất <Highlight>[Truyền Thuyết]</>: xác suất cơ bản 1.5%, xác suất tổng hợp (gồm bảo hiểm) 3.74%\nBao gồm: Audrey Hall, Leonard Mitchell, Fors Wall, Dunn Smith, Daly Simone, Alger Wilson\n\nNhân Mạch phẩm chất <Highlight>[Sử Thi]</>: xác suất cơ bản 10%, xác suất tổng hợp (gồm bảo hiểm) 22.56%\nBao gồm: Susie, Lovia Tiffany, Old Neil, Frye, Frank Lee, Benson Moretti, Melissa Moretti\n\n<Highlight>[Vật Phẩm Thường]</>: xác suất cơ bản 88.5%, xác suất tổng hợp (gồm bảo hiểm) 73.70%\nBao gồm: Vật Chất Cơ Bản, Nhân Tố Tụ Hợp\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy Tắc Kết Giao</>\n1. Mỗi 5 lần Kết Giao chắc chắn nhận 1 Nhân Mạch Sử Thi trở lên.\n\n2. Nếu 24 lần Kết Giao liên tiếp không nhận Nhân Mạch Truyền Thuyết, xác suất sau đó tăng dần.\nMỗi 40 lần Kết Giao chắc chắn nhận Nhân Mạch Truyền Thuyết.\nSau khi nhận Nhân Mạch Truyền Thuyết, bộ đếm reset và xác suất trở về mức cơ bản.\n\n3. Số lần bảo hiểm của 【Lịch Sử Phi Phàm】 được tính riêng với các sự kiện khác, không ảnh hưởng nhau.\n\n4. Có thể Cầu Nguyện để tăng xác suất nhận Nhân Mạch chỉ định.\nSau khi Cầu Nguyện, khi nhận Nhân Mạch Truyền Thuyết, xác suất trúng mục tiêu tăng lên 80%.\nNếu Nhân Mạch Truyền Thuyết nhận được không phải mục tiêu, lần nhận Truyền Thuyết kế tiếp chắc chắn là mục tiêu Cầu Nguyện.\nCầu Nguyện có hiệu lực 2 lần mỗi tuần, reset Thứ Hai.\nMỗi 110 lần Kết Giao Nhân Mạch, nhận thêm 1 lượt Cầu Nguyện. Lượt này không bị reset và có ưu tiên tiêu hao thấp hơn lượt reset hàng tuần.\n\n5. Mỗi ngày sự kiện cho 100 lượt Kết Giao, tối đa tích lũy 700 lượt.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nhận Trùng Nhân Mạch</>\nNhận trùng cùng Nhân Mạch Truyền Thuyết sẽ chuyển thành 1 nguyên liệu nâng cấp Nhân Mạch tương ứng và 10 Mảnh Phim. Nếu Nhân Mạch đã đạt cực hạn hoặc nguyên liệu đủ nâng tới cực hạn, nguyên liệu nâng cấp dư sẽ chuyển thành 40 Mảnh Phim.\nNhận trùng cùng Nhân Mạch Sử Thi sẽ chuyển thành 1 nguyên liệu nâng cấp Nhân Mạch tương ứng và 2 Mảnh Phim. Nếu Nhân Mạch đã đạt cực hạn hoặc nguyên liệu đủ nâng tới cực hạn, nguyên liệu nâng cấp dư sẽ chuyển thành 2 Mảnh Phim.\nMảnh Phim dùng đổi vật phẩm tại Cửa Hàng Nhân Mạch.",
    [1240251532155905] = "<Highlight>【Giấc Mộng Xưa Tingen】</> là sự kiện Kết Giao Nhân Mạch giới hạn thời gian.\nTrong sự kiện, xác suất Kết Giao <Highlight>Klein Moretti</> tăng mạnh. Khi nhận Nhân Mạch Truyền Thuyết, có 80% xác suất là Klein Moretti. Nếu Nhân Mạch Truyền Thuyết lần này không phải Klein Moretti, lần nhận Truyền Thuyết kế tiếp chắc chắn là Klein Moretti.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Thông Tin Xác Suất</>\n<Highlight>[Truyền Thuyết]</> Nhân Mạch: xác suất cơ bản 1.5%, xác suất tổng hợp (gồm bảo hiểm) 3.74%\nBao gồm: Klein Moretti, Audrey Hall, Leonard Mitchell, Fors Wall, Dunn Smith, Daly Simone, Alger Wilson\n\n<Highlight>[Sử Thi]</> Nhân Mạch: xác suất cơ bản 10%, xác suất tổng hợp (gồm bảo hiểm) 22.56%\nBao gồm: Susie, Lovia Tiffany, Old Neil, Frye, Frank Lee, Benson Moretti, Melissa Moretti\n\n<Highlight>[Vật Phẩm Thường]</> liên quan: xác suất cơ bản 88.5%, xác suất tổng hợp (gồm bảo hiểm) 73.70%\nBao gồm: Vật Chất Cơ Bản, Nhân Tố Tụ Hợp\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Chi Tiết Kết Giao</>\n1. Mỗi 5 lần Kết Giao chắc chắn nhận một Nhân Mạch Sử Thi trở lên.\n\n2. Nếu 24 lần Kết Giao liên tiếp không nhận Nhân Mạch Truyền Thuyết, xác suất sau đó tăng dần.\nMỗi 40 lần Kết Giao chắc chắn nhận Nhân Mạch Truyền Thuyết.\nNhận Nhân Mạch Truyền Thuyết sẽ reset bộ đếm và đưa xác suất về mức cơ bản.\n\n3. Số lần bảo hiểm của 【Giấc Mộng Xưa Tingen】 luôn được tích lũy trong sự kiện Kết Giao giới hạn thời gian, tính độc lập với sự kiện Kết Giao thường trực và không ảnh hưởng lẫn nhau.\n\n4. Mỗi ngày sự kiện Kết Giao giới hạn thời gian nhận 100 lượt Kết Giao, tích lũy tối đa 700 lượt.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nhận Trùng Nhân Mạch</>\nNhận trùng cùng Nhân Mạch Truyền Thuyết sẽ chuyển thành 1 nguyên liệu nâng cấp Nhân Mạch tương ứng và 10 Mảnh Phim. Nếu Nhân Mạch đó đã đạt cực hạn hoặc nguyên liệu đủ để lên cực hạn, nguyên liệu nâng cấp dư sẽ chuyển thành 40 Mảnh Phim.\nNhận trùng cùng Nhân Mạch Sử Thi sẽ chuyển thành 1 nguyên liệu nâng cấp Nhân Mạch tương ứng và 2 Mảnh Phim. Nếu Nhân Mạch đó đã đạt cực hạn hoặc nguyên liệu đủ để lên cực hạn, nguyên liệu nâng cấp dư sẽ chuyển thành 2 Mảnh Phim.\nMảnh Phim có thể dùng đổi vật phẩm tại Cửa Hàng Nhân Mạch.",
    [1240251532156161] = "<Highlight>【Vĩnh Độ Tử Vong】</> là sự kiện Kết Giao Nhân Mạch giới hạn thời gian.\nTrong sự kiện, xác suất Kết Giao <Highlight>Azik Eggers</> tăng mạnh. Khi nhận Nhân Mạch Truyền Thuyết, có 80% xác suất là Azik Eggers. Nếu Nhân Mạch Truyền Thuyết lần này không phải Azik Eggers, lần nhận Truyền Thuyết kế tiếp chắc chắn là Azik Eggers.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Thông Tin Xác Suất</>\n<Highlight>[Truyền Thuyết]</> Nhân Mạch: xác suất cơ bản 1.5%, xác suất tổng hợp (gồm bảo hiểm) 3.74%\nBao gồm: Azik Eggers, Klein Moretti, Audrey Hall, Leonard Mitchell, Fors Wall, Dunn Smith, Daly Simone, Alger Wilson\n\n<Highlight>[Sử Thi]</> Nhân Mạch: xác suất cơ bản 10%, xác suất tổng hợp (gồm bảo hiểm) 22.56%\nBao gồm: Susie, Lovia Tiffany, Old Neil, Frye, Frank Lee, Benson Moretti, Melissa Moretti\n\n<Highlight>[Vật Phẩm Thường]</> liên quan: xác suất cơ bản 88.5%, xác suất tổng hợp (gồm bảo hiểm) 73.70%\nBao gồm: Vật Chất Cơ Bản, Nhân Tố Tụ Hợp\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Chi Tiết Kết Giao</>\n1. Mỗi 5 lần Kết Giao chắc chắn nhận một Nhân Mạch Sử Thi trở lên.\n\n2. Nếu 24 lần Kết Giao liên tiếp không nhận Nhân Mạch Truyền Thuyết, xác suất sau đó tăng dần.\nMỗi 40 lần Kết Giao chắc chắn nhận Nhân Mạch Truyền Thuyết.\nNhận Nhân Mạch Truyền Thuyết sẽ reset bộ đếm và đưa xác suất về mức cơ bản.\n\n3. Số lần bảo hiểm của 【Vĩnh Độ Tử Vong】 luôn được tích lũy trong sự kiện Kết Giao giới hạn thời gian, tính độc lập với sự kiện Kết Giao thường trực và không ảnh hưởng lẫn nhau.\n\n4. Mỗi ngày sự kiện Kết Giao giới hạn thời gian nhận 100 lượt Kết Giao, tích lũy tối đa 700 lượt.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nhận Trùng Nhân Mạch</>\nNhận trùng cùng Nhân Mạch Truyền Thuyết sẽ chuyển thành 1 nguyên liệu nâng cấp Nhân Mạch tương ứng và 10 Mảnh Phim. Nếu Nhân Mạch đó đã đạt cực hạn hoặc nguyên liệu đủ để lên cực hạn, nguyên liệu nâng cấp dư sẽ chuyển thành 40 Mảnh Phim.\nNhận trùng cùng Nhân Mạch Sử Thi sẽ chuyển thành 1 nguyên liệu nâng cấp Nhân Mạch tương ứng và 2 Mảnh Phim. Nếu Nhân Mạch đó đã đạt cực hạn hoặc nguyên liệu đủ để lên cực hạn, nguyên liệu nâng cấp dư sẽ chuyển thành 2 Mảnh Phim.\nMảnh Phim có thể dùng đổi vật phẩm tại Cửa Hàng Nhân Mạch.",
    [1240251532156929] = "Chế độ phúc lợi do tín đồ Giáo Hội Kẻ Khờ lập nên. Cảm ơn sự ủng hộ của mọi người dành cho Giáo Hội Kẻ Khờ.\nLắng nghe 《Thánh Điển Kẻ Khờ》, ca ngợi Kẻ Khờ! Nguyện ân điển của Ngài luôn bên bạn ngày đêm, trở thành ngọn đèn không bao giờ tắt trên con đường phía trước!\nMua nhận ngay <Highlight>300</> Bảng Vàng cùng <Highlight>2</> Khối Đường Thể Lực, nhận <Highlight>30</> ngày Giải Đọc Vận Thế Phiếu Phúc Âm và mở các đặc quyền sau:\n<Highlight>※Tăng lượt Tương Tác Nhanh Nhân Mạch:</> Mỗi ngày nhận thêm <Highlight>5 lượt Tương Tác Nhanh</>; tiêu hao vật phẩm có thể trực tiếp tăng Thiện Cảm với Nhân Mạch tương ứng.\n<Highlight>※Tăng hiệu suất nhận tiền tệ lối chơi:</> Khi nhận <Highlight>Huân Chương Mạo Hiểm</>, <Highlight>Huy Hiệu Khải Hoàn</> và <Highlight>Huy Chương Đồng Hành</>, hiệu suất tăng <Highlight>20%</>.\n<Highlight>※Mốc Dịch Chuyển Tùy Chỉnh:</> Có thể ghi lại <Highlight>tọa độ Bia Phúc Âm</> trên bản đồ cảnh công cộng; sau khi ghi có thể dịch chuyển tới <Highlight>Bia Phúc Âm</> tương ứng bất cứ lúc nào.\n<Highlight>※Tăng Giới Hạn Thể Lực:</> Giới hạn tích lũy Thể Lực tăng <Highlight>1000</>.\nNgoài ra, mỗi ngày đăng nhập nhận <Highlight>100</> Bảng Vàng Khóa; tích lũy đăng nhập còn nhận thêm <Highlight>Khối Đường Thể Lực</>.\nPhúc Âm Kẻ Khờ tối đa kéo dài <Highlight>180</> ngày. Khi đã đạt giới hạn, nhận thêm Phúc Âm Kẻ Khờ sẽ chuyển thành lượng Bảng Vàng tương đương.",
    [1240251532157441] = "Mỗi lần sân khấu Nhà Hát Utopia làm mới sẽ xuất hiện 3 Bí Ngẫu để rút. Nếu sau khi rút chỉ còn Bí Ngẫu phẩm chất Tím, sân khấu tự làm mới.\nRút Mở Màn: tiêu hao 【Chỉ Dệt Vàng】*3, ngẫu nhiên nhận 1 trong 3 Bí Ngẫu.\nRút Giữa Màn: tiêu hao 【Chỉ Dệt Vàng】*6, ngẫu nhiên nhận 1 trong 2 Bí Ngẫu còn lại.\nRút Hạ Màn: tiêu hao 【Chỉ Dệt Vàng】*12, chắc chắn nhận 1 Bí Ngẫu cuối cùng.",
    [1240251532163329] = "Sau khi <Highlight>Cầu Nguyện</> một Nhân Mạch chỉ định, xác suất nhận Nhân Mạch đó khi Kết Giao sẽ tăng.\nCó thể Cầu Nguyện các Nhân Mạch Truyền Thuyết đang có thể Kết Giao.\nSau khi Cầu Nguyện, khi nhận Nhân Mạch Truyền Thuyết, xác suất nhận đúng mục tiêu Cầu Nguyện tăng lên <Highlight>80%</>. Nếu lần đó không nhận mục tiêu, Nhân Mạch Truyền Thuyết nhận ở lần kế tiếp chắc chắn là mục tiêu Cầu Nguyện.\n\nTrong Kết Giao thường trực, <Highlight>mỗi tuần</> hiệu ứng Cầu Nguyện có thể kích hoạt <Highlight>2 lần</>, reset vào Thứ Hai.\nMỗi khi Kết Giao Nhân Mạch <Highlight>110 lần</>, nhận thêm 1 lượt Cầu Nguyện. Lượt này không bị reset và có ưu tiên tiêu hao thấp hơn lượt reset hằng tuần.",
    [1240251532163585] = "Phi Phàm Giả tiêu hao Tài Sản Lâu Đài để đặt cấu kiện tại <Highlight>Sân Trong Lâu Đài</> và <Highlight>Xưởng Thợ</>.\n(Khu chức năng nhanh góc phải trên) — Mở Xây Dựng Kỳ Tích, tháo dỡ một chạm, <Highlight>đổi góc nhìn</> và các chức năng tiện lợi khác.\n(Thư viện cấu kiện phía dưới) — Mở khóa, mua, tìm kiếm cấu kiện; khi <Highlight>thu hồi cấu kiện</>, cấu kiện <Highlight>trở về Thư Viện Cấu Kiện</>.\n(Khu thông tin phía trên) — Hiển thị tên cấu kiện hiện tại và các thao tác có thể thực hiện.\n(Thanh trên cùng góc phải) Điểm Lâu Đài — Hiển thị Điểm Bố Trí hiện tại, Tổng Điểm, số Tài Sản Lâu Đài và thông tin khác.",
    [1240251532165377] = "Sách Đồng Thau Trunsoest, một quyển sách tạo từ những lá đồng thau mỏng. Tham gia và hoàn thành Phó Bản, thi đấu và nhiệm vụ Thử Thách Mạo Hiểm để nhận Điểm Thử Thách và token tương ứng, từ đó nhận/đổi nhiều phần thưởng và Ngoại Hình giới hạn. Thử thách Phó Bản Sách Đồng Thau cần tương tác đối thoại với NPC trong Phó Bản chế độ tổ đội để mở.",
    [1240251532166401] = "Phân Bố Cấp Sĩ Khí:\n\nSĩ Khí Cấp 1: cần <Highlight>720 Điểm Tài Nguyên</>, toàn bộ thành viên phe nhận <Highlight>5% Áp Chế Công Trình, 2% Tốc Độ Di Chuyển</>.\n\nSĩ Khí Cấp 2: cần <Highlight>1440 Điểm Tài Nguyên</>, nhận <Highlight>10% Áp Chế Công Trình, 4% Tốc Độ Di Chuyển</>.\n\nSĩ Khí Cấp 3: cần <Highlight>2160 Điểm Tài Nguyên</>, nhận <Highlight>15% Áp Chế Công Trình, 6% Tốc Độ Di Chuyển</>.\n\nSĩ Khí Cấp 4: cần <Highlight>2880 Điểm Tài Nguyên</>, nhận <Highlight>20% Áp Chế Công Trình, 8% Tốc Độ Di Chuyển</>.\n\nSĩ Khí Cấp 5: cần <Highlight>3600 Điểm Tài Nguyên</>, nhận <Highlight>25% Áp Chế Công Trình, 10% Tốc Độ Di Chuyển, 1.5% Áp Chế Hệ và Kháng Hệ</>.\n\nSĩ Khí Cấp 6: cần <Highlight>5280 Điểm Tài Nguyên</>, nhận <Highlight>30% Áp Chế Công Trình, 12% Tốc Độ Di Chuyển, 3% Áp Chế Hệ và Kháng Hệ</>.\n\nSĩ Khí Cấp 7: cần <Highlight>6960 Điểm Tài Nguyên</>, nhận <Highlight>35% Áp Chế Công Trình, 14% Tốc Độ Di Chuyển, 4.5% Áp Chế Hệ và Kháng Hệ</>.\n\nSĩ Khí Cấp 8: cần <Highlight>8640 Điểm Tài Nguyên</>, nhận <Highlight>40% Áp Chế Công Trình, 16% Tốc Độ Di Chuyển, 6% Áp Chế Hệ và Kháng Hệ</>.\n\nSĩ Khí Cấp 9: cần <Highlight>10320 Điểm Tài Nguyên</>, nhận <Highlight>45% Áp Chế Công Trình, 18% Tốc Độ Di Chuyển, 7.5% Áp Chế Hệ và Kháng Hệ</>.\n\nSĩ Khí Cấp 10: cần <Highlight>12000 Điểm Tài Nguyên</>, nhận <Highlight>50% Áp Chế Công Trình, 20% Tốc Độ Di Chuyển, 9% Áp Chế Hệ và Kháng Hệ</>.\n",
    [1240251532167169] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Giới Thiệu Lối Chơi</>\nTranh Đoạt Thần Tọa là PvP tổ đội, tối đa lập đội 6 người để ghép trận. Trong chế độ này, mọi người dùng thuộc tính <Highlight>thực</> giống ngoài chế độ.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Điều Kiện Thắng</>\nTrong thời gian giới hạn, hạ toàn bộ đội địch để thắng. Nếu hết giờ cả hai bên vẫn còn người sống, lần lượt so số người hạ gục, số người sống, tổng sát thương và tổng Sinh Mệnh còn lại; bên cao hơn thắng. Mỗi đội có <Highlight>2 lần hồi sinh</> đồng đội đã chết.",
    [1240251532167425] = "<Highlight>【Hoán Nhan Linh Giới】</>\nChạm tới vẻ đẹp, đánh thức vẻ đẹp, trở thành bản ngã của cái đẹp — kỳ tích mỹ lệ giữa thế gian.\n\n<Highlight>【Quy Tắc Triệu Hồi】</>\nDùng Thánh Bôi để Triệu Hồi Linh Giới, có xác suất nhận phần thưởng bảo vật quý.\nPhần thưởng chia thành <Highlight>Thần Quyến</>, <Highlight>Linh Huyễn</>, <Highlight>Phi Phàm</>. Sau khi tích lũy dùng <Highlight>60</> Thánh Bôi mà chưa nhận Thần Quyến, xác suất Thần Quyến tăng dần; mỗi <Highlight>140</> Thánh Bôi chắc chắn nhận <Highlight>Thần Quyến</>; mỗi <Highlight>10</> Thánh Bôi chắc chắn nhận phần thưởng phẩm chất <Highlight>Linh Huyễn trở lên</>.\nSố lần dùng Thánh Bôi · Khóa được tính riêng; phần thưởng triệu hồi bằng Thánh Bôi · Khóa không thể giao dịch hoặc tặng.\n\n<Highlight>【Quy Tắc Khác】</>\nDùng <Highlight>Thẻ Thần Quyến</> đổi phần thưởng <Highlight>Thần Quyến</> tại Cửa Hàng Quà Tặng Mỹ Thần.\nDùng <Highlight>Thẻ Linh Huyễn</> đổi thưởng tại Cửa Hàng Tế Đàn Linh Huyễn. Ngoại hình Linh Huyễn vượt giới hạn sở hữu sẽ phân giải thành số lượng <Highlight>Thẻ Linh Huyễn</> nhất định.\nSau khi chọn dùng <Highlight>Thánh Bôi</> bù <Highlight>Thánh Bôi · Khóa</> để triệu hồi, phần thưởng nhận bằng Thánh Bôi sẽ <Highlight>không thể giao dịch hoặc tặng</> và được tính vào tiến độ bảo hiểm Thánh Bôi · Khóa.\n\n<Highlight>【Công Bố Xác Suất】</>\nXác suất thưởng Thần Quyến (gồm bảo hiểm): 0.873%\n<Highlight>Thẻ Thần Quyến</>: 0.793%\n<Highlight>Miện Thương Bạch</>: 0.080%\n\nXác suất thưởng Linh Huyễn (gồm bảo hiểm): 10.928%\nTinh Ánh Lục Dạ · Áo, Tinh Ánh Lục Dạ · Quần, Tinh Ánh Lục Dạ · Trang Sức, Tinh Ánh Lục Dạ · Phụ Kiện, Lễ Phục Tụng Thi · Tóc, Lễ Phục Tụng Thi · Áo, Lễ Phục Tụng Thi · Quần, Lễ Phục Tụng Thi · Trang Sức, Hoa Nở Nửa Má, Bánh Lái Tàu Ma, Đồng Hồ Thời Gian, Thẻ Linh Huyễn*10, Thẻ Linh Huyễn*5\n\nXác suất thưởng Phi Phàm (gồm bảo hiểm): 88.199%\nThẻ Linh Huyễn, Nhân Tố Tụ Hợp, Thuốc Nhuộm Bọt, Thuốc Nhuộm San Hô, Pháo Nổ Bùm, Pháo Dây Màu, Pháo Tiệc, Dược Tề Kỳ Quái, Đuốc Đơn Giản, Đàn Lute Thuần Tình, Búp Bê Voi Con, Vải Quấn Lạnh, Truyền Thừa Vinh Quang, Lông Khỉ Đầu Chó Xoăn, Vòng Quay May Mắn, Dây Chuyền Vỏ Sò, Hoa Cài Ngọc Trai",
    [1240251532167681] = "<Highlight>【Hoán Nhan Linh Giới】</>\nChạm tới vẻ đẹp, đánh thức vẻ đẹp, trở thành bản ngã của cái đẹp — kỳ tích mỹ lệ giữa thế gian.\n\n<Highlight>【Quy Tắc Triệu Hồi】</>\nDùng Thánh Bôi để Triệu Hồi Linh Giới, có xác suất nhận phần thưởng bảo vật quý.\nPhần thưởng chia thành <Highlight>Thần Quyến</>, <Highlight>Linh Huyễn</>, <Highlight>Phi Phàm</>. Sau khi tích lũy dùng <Highlight>60</> Thánh Bôi mà chưa nhận Thần Quyến, xác suất Thần Quyến tăng dần; mỗi <Highlight>140</> Thánh Bôi chắc chắn nhận <Highlight>Thần Quyến</>; mỗi <Highlight>10</> Thánh Bôi chắc chắn nhận phần thưởng phẩm chất <Highlight>Linh Huyễn trở lên</>.\nSố lần dùng Thánh Bôi · Khóa được tính riêng; phần thưởng triệu hồi bằng Thánh Bôi · Khóa không thể giao dịch hoặc tặng.\n\n<Highlight>【Quy Tắc Khác】</>\nDùng <Highlight>Thẻ Thần Quyến</> đổi phần thưởng <Highlight>Thần Quyến</> tại Cửa Hàng Quà Tặng Mỹ Thần.\nDùng <Highlight>Thẻ Linh Huyễn</> đổi thưởng tại Cửa Hàng Tế Đàn Linh Huyễn. Ngoại hình Linh Huyễn vượt giới hạn sở hữu sẽ phân giải thành số lượng <Highlight>Thẻ Linh Huyễn</> nhất định.\nSau khi chọn dùng <Highlight>Thánh Bôi</> bù <Highlight>Thánh Bôi · Khóa</> để triệu hồi, phần thưởng nhận bằng Thánh Bôi sẽ <Highlight>không thể giao dịch hoặc tặng</> và được tính vào tiến độ bảo hiểm Thánh Bôi · Khóa.\n\n<Highlight>【Công Bố Xác Suất】</>\nXác suất thưởng Thần Quyến (gồm bảo hiểm): 0.873%\n<Highlight>Thẻ Thần Quyến</>: 0.793%\n<Highlight>Kim Chi Sâm Ảnh</>: 0.080%\n\nXác suất thưởng Linh Huyễn (gồm bảo hiểm): 10.928%\nTinh Ánh Lục Dạ · Áo, Tinh Ánh Lục Dạ · Quần, Tinh Ánh Lục Dạ · Trang Sức, Tinh Ánh Lục Dạ · Phụ Kiện, Lễ Phục Tụng Thi · Tóc, Lễ Phục Tụng Thi · Áo, Lễ Phục Tụng Thi · Quần, Lễ Phục Tụng Thi · Trang Sức, Hoa Nở Nửa Má, Bánh Lái Tàu Ma, Đồng Hồ Thời Gian, Thẻ Linh Huyễn*10, Thẻ Linh Huyễn*5\n\nXác suất thưởng Phi Phàm (gồm bảo hiểm): 88.199%\nThẻ Linh Huyễn, Nhân Tố Tụ Hợp, Thuốc Nhuộm Bọt, Thuốc Nhuộm San Hô, Pháo Nổ Bùm, Pháo Dây Màu, Pháo Tiệc, Dược Tề Kỳ Quái, Đuốc Đơn Giản, Đàn Lute Thuần Tình, Búp Bê Voi Con, Vải Quấn Lạnh, Truyền Thừa Vinh Quang, Lông Khỉ Đầu Chó Xoăn, Vòng Quay May Mắn, Dây Chuyền Vỏ Sò, Hoa Cài Ngọc Trai",
    [1240251532167937] = "<Highlight>【Kỳ Trang Tinh Linh】</>\nKhi quần tinh rực rỡ, khoảnh khắc tinh quang khoác lên thân, vẻ đẹp sẽ tái hiện nơi đây.\n\n<Highlight>【Quy Tắc Triệu Hồi】</>\nDùng Tinh Tệ để Triệu Hồi Linh Giới, có xác suất nhận phần thưởng bảo vật quý.\nPhần thưởng chia thành <Highlight>Thần Quyến</>, <Highlight>Linh Huyễn</>, <Highlight>Phi Phàm</>. Sau khi tích lũy dùng <Highlight>10</> Tinh Tệ mà chưa nhận Thần Quyến, xác suất Thần Quyến tăng dần; mỗi <Highlight>40</> Tinh Tệ chắc chắn nhận <Highlight>Thần Quyến</>, mỗi <Highlight>10</> Tinh Tệ chắc chắn nhận <Highlight>Linh Huyễn</>.\nMọi phần thưởng Triệu Hồi đều không thể giao dịch hoặc tặng.\n\n<Highlight>【Quy Tắc Khác】</>\nCó thể dùng <Highlight>Dao Cắt</> đổi thưởng tại Cửa Hàng Bí Khố Tinh Linh. Nếu nhận ngoại hình Linh Huyễn hoặc Thần Quyến vượt giới hạn sở hữu, phần dư sẽ phân giải thành số lượng <Highlight>Dao Cắt</> nhất định.\nKhi nhận phần thưởng Thần Quyến, sẽ <Highlight>ưu tiên ngoại hình chưa sở hữu</> (tóc Thần Quyến và mảnh trang phục tính riêng). Xem chi tiết tại tiến độ sưu tầm ngoại hình.\n\n<Highlight>【Công Bố Xác Suất】</>\nXác suất thưởng Thần Quyến (gồm bảo hiểm): 5.230%\n<Highlight>Tóc Thần Quyến</>: 0.596%\n<Highlight>Mảnh Trang Phục Thần Quyến</>: 4.634%\n\nXác suất thưởng Linh Huyễn (gồm bảo hiểm): 12.222%\nLệ Bão Tố, Trượng Dây Leo Hồng, Áo Choàng Điệp Đậu, Trói Buộc Tường Vi, Tường Vi Bạc\n\nXác suất thưởng Phi Phàm (gồm bảo hiểm): 82.548%\nNhân Tố Tụ Hợp, Thuốc Nhuộm Bọt, Thuốc Nhuộm San Hô, Pháo Nổ Bùm, Pháo Dây Màu, Pháo Tiệc, Dược Tề Kỳ Quái, Đuốc Đơn Giản, Đàn Lute Thuần Tình, Búp Bê Voi Con, Vải Quấn Lạnh, Truyền Thừa Vinh Quang, Lông Khỉ Đầu Chó Xoăn, Vòng Quay May Mắn, Dây Chuyền Vỏ Sò, Hoa Cài Ngọc Trai",
    [1240251532168961] = "Mở Railway Tycoon cần tiêu hao một số Giấy Phép Kinh Tiêu; Cấp Tuyến Đường càng cao, tiêu hao càng nhiều.\nGiấy Phép Kinh Tiêu tự hồi 2 tờ mỗi ngày, tối đa tích trữ 6. Khi số lượng đang giữ vượt giới hạn, sẽ không tự hồi.\nCó thể bổ sung Giấy Phép Kinh Tiêu tại Cửa Hàng CLB; mỗi tuần hồi 4 lượt mua.\nThời gian hồi Giấy Phép Kinh Tiêu: %d giờ mỗi ngày theo giờ server.",
    [1240251532169473] = "Tổng Điểm = (Phiếu Thương Hội đang giữ khi kết thúc + Phiếu Thương Hội quy đổi từ Hàng Hóa còn lại) x Hệ Số Phạt Thất Bại\nTài Sản Lâu Đài kiếm được = Tổng Điểm × Hệ Số Chuyển Đổi theo Xếp Hạng\n\nPhiếu Thương Hội đang giữ khi kết thúc: Số Phiếu Thương Hội hiện có khi kết toán.\nPhiếu Thương Hội quy đổi từ Hàng Hóa còn lại: Khi kết toán, Hàng Hóa chưa bán được đổi thành Phiếu Thương Hội theo 100% Giá Mua Chuẩn (giá trị này tăng thêm khi nâng Bánh Xe); hàng đề xuất nhận thêm khoảng 20% bonus. Vì Giá Bán Chuẩn cao hơn Giá Mua, cố gắng bán Hàng Hóa sẽ có lợi hơn.\nXếp Hạng: Tổng Điểm quyết định xếp hạng; xếp càng cao nhận càng nhiều Tài Sản Lâu Đài.\nTổn Thất Thất Bại: Nếu không hoàn thành hoặc từ bỏ Hợp Đồng, Thương Hội khấu trừ 20% tổng thành tích. Chọn Hợp Đồng phù hợp cũng là kỹ năng bắt buộc của Tycoon.",
    [1240251532169729] = "Tiêu hao Tài Sản Lâu Đài và tài nguyên khác để nâng Tàu Hỏa, nhận bonus trong Railway Tycoon.\n\nNâng Toa Hàng: Tăng giới hạn số Hàng Hóa khởi đầu có thể chở.\n\nNâng Buồng Lái: Tăng số lượt Làm Mới Thẻ Chiến Lược được hồi khi vào khu vực mới.\n\nNâng Bánh Xe: Tăng hệ số quy đổi Hàng Hóa chưa bán thành Phiếu Thương Hội khi tính Tổng Điểm.",
    [1240251532169985] = "Nhận tăng thuộc tính theo số từ của Vật Chất Phi Phàm:\n1 từ: Sinh Mệnh +160, Phòng Thủ +100\n2 từ: Sinh Mệnh +320, Phòng Thủ +200\n3 từ: Sinh Mệnh +480, Phòng Thủ +300\n4 từ: Sinh Mệnh +640, Phòng Thủ +400\n<Highlight>Nâng Cấp Vật Phong Ấn có thể mở khóa thêm hiệu ứng Cộng Hưởng Phi Phàm.</>\n<Highlight>Nâng Cấp Tri Thức Phi Phàm có thể tăng hiệu quả Cộng Hưởng Phi Phàm.</>",
    [1240251532170241] = "Nhận tăng thuộc tính theo số từ của Vật Chất Phi Phàm:\n1 từ: Sinh Mệnh +160, Phòng Thủ +100\n2 từ: Sinh Mệnh +320, Phòng Thủ +200\n3 từ: Sinh Mệnh +480, Phòng Thủ +300\n4 từ: Sinh Mệnh +640, Phòng Thủ +400\n5 từ: Sinh Mệnh +800, Phòng Thủ +500\n<Highlight>Nâng Cấp Vật Phong Ấn có thể mở khóa thêm hiệu ứng Cộng Hưởng Phi Phàm.</>\n<Highlight>Nâng Cấp Tri Thức Phi Phàm có thể tăng hiệu quả Cộng Hưởng Phi Phàm.</>",
    [1240251532170497] = "Nhận tăng thuộc tính theo số từ của Vật Chất Phi Phàm:\n1 từ: Sinh Mệnh +160, Phòng Thủ +100\n2 từ: Sinh Mệnh +320, Phòng Thủ +200\n3 từ: Sinh Mệnh +480, Phòng Thủ +300\n4 từ: Sinh Mệnh +640, Phòng Thủ +400\n5 từ: Sinh Mệnh +800, Phòng Thủ +500\n6 từ: Sinh Mệnh +960, Phòng Thủ +600\n<Highlight>Tăng cấp Tri Thức Phi Phàm có thể cường hóa hiệu quả Cộng Hưởng Phi Phàm.</>",
    [1240251532170753] = "Nhận tăng thuộc tính theo số từ của Vật Chất Phi Phàm:\n1 từ: Sinh Mệnh +160, Phá Phòng Vật Lý +100\n2 từ: Sinh Mệnh +320, Phá Phòng Vật Lý +200\n3 từ: Sinh Mệnh +480, Phá Phòng Vật Lý +300\n4 từ: Sinh Mệnh +640, Phá Phòng Vật Lý +400\n<Highlight>Nâng Cấp Vật Phong Ấn có thể mở khóa thêm hiệu ứng Cộng Hưởng Phi Phàm.</>\n<Highlight>Nâng Cấp Tri Thức Phi Phàm có thể tăng hiệu quả Cộng Hưởng Phi Phàm.</>",
    [1240251532171009] = "Nhận tăng thuộc tính theo số từ của Vật Chất Phi Phàm:\n1 từ: Sinh Mệnh +160, Phá Phòng Vật Lý +100\n2 từ: Sinh Mệnh +320, Phá Phòng Vật Lý +200\n3 từ: Sinh Mệnh +480, Phá Phòng Vật Lý +300\n4 từ: Sinh Mệnh +640, Phá Phòng Vật Lý +400\n5 từ: Sinh Mệnh +800, Phá Phòng Vật Lý +500\n<Highlight>Nâng Cấp Vật Phong Ấn có thể mở khóa thêm hiệu ứng Cộng Hưởng Phi Phàm.</>\n<Highlight>Nâng Cấp Tri Thức Phi Phàm có thể tăng hiệu quả Cộng Hưởng Phi Phàm.</>",
    [1240251532171265] = "Nhận tăng thuộc tính theo số từ của Vật Chất Phi Phàm:\n1 từ: Sinh Mệnh +160, Phá Phòng Vật Lý +100\n2 từ: Sinh Mệnh +320, Phá Phòng Vật Lý +200\n3 từ: Sinh Mệnh +480, Phá Phòng Vật Lý +300\n4 từ: Sinh Mệnh +640, Phá Phòng Vật Lý +400\n5 từ: Sinh Mệnh +800, Phá Phòng Vật Lý +500\n6 từ: Sinh Mệnh +960, Phá Phòng Vật Lý +600\n<Highlight>Tăng cấp Tri Thức Phi Phàm có thể cường hóa hiệu quả Cộng Hưởng Phi Phàm.</>",
    [1240251532171521] = "Sau khi bật, các thao tác vật phẩm sau cần xác nhận lần hai bằng Khóa Mật Khẩu: mở khóa vật phẩm đã khóa, tiêu hao/phân giải/đổi/vứt vật phẩm phẩm chất cao...",
    [1240251532171777] = "Sau khi bật, các thao tác giao dịch sau cần xác nhận lần hai bằng Khóa Mật Khẩu: đăng/hủy bán/mua vật phẩm tại Sàn Giao Dịch, trả giá đấu giá, tiêu hao vật phẩm có thể giao dịch, mọi tiêu hao Bảng Vàng/Suli khác...",
    [1240251532173057] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nguyên Tắc Đối Đẳng</>\nArrodes tuân theo nguyên tắc đối đẳng một hỏi một đáp. Câu hỏi của Arrodes có thể bị từ chối hoặc để dành, nhưng cuối cùng nhất định phải được giải quyết.\nNếu từ chối trả lời, trả lời sai hoặc nói dối, bạn sẽ chịu hình phạt của Arrodes.\nChỉ sau khi Arrodes trả lời xong và câu hỏi nó đưa ra đã được giải quyết mới có thể hỏi tiếp.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Giải Thích NPC</>\nPhạm vi nhận thức của NPC Arrodes bị giới hạn trong thế giới quan Quỷ Bí Chi Chủ. Khi trao đổi về chủ đề vượt thời đại hoặc quá nhảy cóc về tư duy, Arrodes có thể không trả lời được, mong bạn thông cảm.\nCâu trả lời của NPC Arrodes do mô hình AI tạo ra và có thể mơ hồ hoặc sai lệch. Có thể dùng nút Báo Cáo trong khung hội thoại để phản hồi, giúp chúng tôi hoàn thiện trải nghiệm Arrodes.\nNếu có quá nhiều người chơi tương tác cùng lúc, Arrodes có thể phản hồi chậm; chờ một lúc sẽ trở lại bình thường.",
    [1240251532173313] = "Bí Ngẫu loại Trùng Tinh Tú có thể xin Biến Hình thành Phi Phàm Giả khác sau khi được đồng ý.\nKhi Biến Hình, nếu Phi Phàm Giả sở hữu Ngoại Trang giống mục tiêu, Trùng Tinh Tú sẽ tự mặc.\nSau khi Biến Hình, có thể tự do thay đồ cho Trùng Tinh Tú trong chức năng Thay Đồ của Bí Ngẫu.\nCó thể mua Chứng Nhận Điều Khiển tại “Shop - Trưng Bày Bí Tàng”; sau khi dùng, Trùng Tinh Tú nhận khả năng cưỡi và khi đi theo có thể cưỡi Tọa Kỵ mà Phi Phàm Giả sở hữu.\nMỗi Trùng Tinh Tú sau khi Biến Hình thành công sẽ không thể đổi mục tiêu Biến Hình trong 24 giờ.",
    [1240251532173569] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Phương Án</>\nPhương Án gồm Phương Án Phi Phàm và Phương Án Trang Bị. Phương Án Phi Phàm là tổ hợp Kỹ Năng, Thiên Phú, Vật Phong Ấn; Phương Án Trang Bị là tổ hợp Trang Bị, Ân Tứ và Hiệu Ứng Bộ. Phương án hiện tại thay đổi theo build đang dùng theo thời gian thực.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Đổi Phương Án</>\nSau khi lưu một build thành phương án tại Kỹ Năng-Phương Án Phi Phàm hoặc Trang Bị-Phương Án Trang Bị, có thể đổi một chạm sang build đó. Không thể đổi phương án khi đang chiến đấu.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Đổi Theo Nhóm</>\nCó thể đóng gói một Phương Án Phi Phàm và một Phương Án Trang Bị thành Phương Án Nhóm để đổi cả trang bị và phương án Phi Phàm cùng lúc. Có thể đặt tự động đổi Phương Án Nhóm khi tới cảnh chỉ định.",
    [1240251532173825] = "Sau khi bật, người chơi trong cảnh sẽ hiển thị cùng một mô hình để tăng độ mượt chiến đấu. Hiện hiệu ứng Đồng Mô Hình chỉ áp dụng trong các gameplay nhiều người quy mô lớn như <Highlight>Chiến Thành</>, <Highlight>Chiến Cao Nguyên</> và <Highlight>Giải Tứ Phương</>.",
    [1240251532174337] = "Sau khi bật, <Highlight>tóc</> và <Highlight>trang phục</> của nhân vật sẽ có hiệu ứng vật lý mô phỏng chân thực.",
    [1240251532174593] = "Trong gameplay Chiến Bóng Ma Nhà Hát có bốn loại phần thưởng:\nThưởng Phối Đồ: Hoàn thành phối đồ và đạt Tổng Điểm Phối Đồ nhất định; khi vào giai đoạn điều chỉnh sẽ nhận thưởng theo mức Tổng Điểm tương ứng, gửi qua thư.\nThưởng Thi Đấu: Tham gia trận (xem hoặc được chọn vào đội hình) và vẫn ở trong CLB khi quyết toán để nhận thưởng; số lượng phụ thuộc số trận thắng tích lũy của vòng và kết quả trận hiện tại.\nThưởng Xem: Trong thời gian thi đấu, mỗi 1 phút người chơi ở Hành Lang Bóng Ma sẽ nhận một lượng Huy Chương Đồng Hành và vật phẩm khác.\nThưởng Mùa: Cuối mỗi mùa, 5 người có số trận tham gia nhiều nhất trong CLB nhận thưởng danh hiệu.",
    [1240251532175105] = "<Highlight>【Giải Thích Thưởng Bậc】</>\n\n1. Các chế độ có Bậc gồm: Phiêu Lưu, Đồng Hành, Phó Bản, Vui Đấu, Tranh Phong Chúa Tể, Tranh Đoạt Thần Tọa, Khoảnh Khắc Vận Mệnh, Săn Giết Chung Kết.\n\n2. Mỗi chế độ tích Điểm Thắng riêng để tăng Bậc và nhận Thưởng Bậc.\n\n3. Phần thưởng của mỗi Bậc <Highlight>tối đa nhận ba lần</>; có thể tự chọn 3 chế độ yêu thích, <Highlight>không cần chơi tất cả</>.\n\n4. Hệ thống tự đưa ba chế độ có Bậc hiện tại cao nhất lên vị trí chính; nhấn từng module để đi nhanh tới giao diện tương ứng.\n\n5. Khi Bậc reset, Thưởng Bậc cũng reset.",
    [1240251532175361] = "<Highlight>Hỗ Trợ Một Nút:</>\n· Bật để dùng Hỗ Trợ Một Nút. Nhấn nút Đánh Thường (mặc định E) sẽ lần lượt dùng kỹ năng; giữ nút Đánh Thường 2 giây để vào trạng thái tự dùng kỹ năng.\n· Sau khi vào trạng thái tự dùng kỹ năng, rời chiến đấu hoặc tự nhấn kỹ năng sẽ ngắt tự động.\n· Có thể vào Cài Đặt - Chiến Đấu - Thao Tác - Chế Độ Tự Chiến để chọn Ưu Tiên Di Chuyển hoặc Ưu Tiên Kỹ Năng; thiết lập này quyết định Hỗ Trợ Một Nút có thử dùng kỹ năng khi nhân vật đang di chuyển hay không.\n<Highlight>Phương Án Tân Thủ:</>\n· Đây là phương án Hỗ Trợ Một Nút mặc định.\n· Trong Phương Án Tân Thủ, ở bảng Lắp Kỹ Năng Nhanh có thể nhấn vùng góc phải trên biểu tượng kỹ năng để thêm/bỏ kỹ năng khỏi chuỗi Hỗ Trợ Một Nút; chỉ kỹ năng có dấu tick sáng mới được tự dùng.\n<Highlight>Phương Án Nâng Cao:</>\n· Cho phép tùy chỉnh Hỗ Trợ Một Nút, vào Kỹ Năng - Hỗ Trợ Một Nút để chỉnh.\n· Có thể tạo 10 phương án nâng cao, tùy chỉnh thứ tự ưu tiên và điều kiện dùng kỹ năng.",
    [1240251532175617] = "Hình chiếu lịch sử <Highlight>Thành Liệp Long</> bắt nguồn từ chiến trường cổ Kỷ Đệ Tứ.\nKhi <Highlight>Hắc Hoàng Đế</> lần nữa trở về, <Highlight>Dạ Hoàng</> nhờ thần linh trợ giúp chuyển sang Thẩm Phán Giả; <Highlight>Huyết Hoàng Đế</> cưỡng ép chuyển sang Hồng Tế Tư với cái giá nửa điên; <Highlight>Minh Hoàng</>, người tích lũy lực lượng ở tận Nam Đại Lục, cũng thổi lên tiếng kèn của Tử Thần. Tứ Hoàng hội tụ, chỉ một người có thể trở thành kẻ thắng cuối cùng; một cuộc chiến đủ sức thay đổi cục diện thế giới bắt đầu.\nDù Chiến Tranh Tứ Hoàng của Kỷ Đệ Tứ đã chìm trong lịch sử, năng lượng mạnh mẽ vẫn lưu lại trên chiến trường cổ. Vào thời điểm nhất định, toàn bộ chiến trường sẽ tạm thời được kích hoạt. Mỗi lần kích hoạt sẽ là một lần xáo lại hoàn toàn; các CLB được phân ngẫu nhiên vào một trong bốn thế lực của Tứ Hoàng để tham gia trận chiến từ Kỷ Đệ Tứ xa xưa.",
    [1240251532175873] = "Một khu vực trên <Highlight>Cao Nguyên Tinh Tinh</> ở Nam Đại Lục, là hình chiếu lịch sử của chiến trường cổ Kỷ Nguyên Thứ Tư. Sau Cuộc Chiến Tứ Hoàng, Minh Hoàng — kẻ thu lợi lớn nhất — mang kho báu về Cao Nguyên Tinh Tinh. Kỵ Sĩ Tử Vong luôn bảo vệ kho báu mang cấm chế này; bí bảo ấy thu hút vô số thế lực tranh đoạt, khiến xung đột kéo dài từ cổ chí kim.\nMỗi lần chiến trường kích hoạt, các CLB lớn sẽ ngẫu nhiên được phân vào một trong bốn thế lực <Highlight>Huyết Hoàng Đế, Hắc Hoàng Đế, Dạ Hoàng, Minh Hoàng</>, hóa thân thành chiến sĩ dưới trướng Tứ Hoàng và khiến cao nguyên lại dậy binh đao. Các chiến sĩ sẽ tranh đoạt <Highlight>Kỵ Sĩ Tử Vong</> — chìa khóa mở kho báu Minh Hoàng — để giành vinh quang cho thế lực mình.",
    [1240251532176641] = "Nhận tăng thuộc tính theo số từ của Vật Chất Phi Phàm:\n1 từ: Sinh Mệnh +160, Phá Phòng Ma Pháp +100\n2 từ: Sinh Mệnh +320, Phá Phòng Ma Pháp +200\n3 từ: Sinh Mệnh +480, Phá Phòng Ma Pháp +300\n4 từ: Sinh Mệnh +640, Phá Phòng Ma Pháp +400\n<Highlight>Nâng Cấp Vật Phong Ấn có thể mở khóa thêm hiệu ứng Cộng Hưởng Phi Phàm.</>\n<Highlight>Nâng Cấp Tri Thức Phi Phàm có thể tăng hiệu quả Cộng Hưởng Phi Phàm.</>",
    [1240251532176897] = "Nhận tăng thuộc tính theo số từ của Vật Chất Phi Phàm:\n1 từ: Sinh Mệnh +160, Phá Phòng Ma Pháp +100\n2 từ: Sinh Mệnh +320, Phá Phòng Ma Pháp +200\n3 từ: Sinh Mệnh +480, Phá Phòng Ma Pháp +300\n4 từ: Sinh Mệnh +640, Phá Phòng Ma Pháp +400\n5 từ: Sinh Mệnh +800, Phá Phòng Ma Pháp +500\n<Highlight>Nâng Cấp Vật Phong Ấn có thể mở khóa thêm hiệu ứng Cộng Hưởng Phi Phàm.</>\n<Highlight>Nâng Cấp Tri Thức Phi Phàm có thể tăng hiệu quả Cộng Hưởng Phi Phàm.</>",
    [1240251532177409] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Hiệu Quả Cải Tạo</>\nThông qua Cải Tạo Thần Chú, có thể thay đổi ngoại hình và hiệu năng của xe. Hiệu quả từng bộ phận:\n<Highlight>Sơn:</> Thay đổi hiệu ứng sơn xe\n<Highlight>Thân Xe:</> Thay đổi kiểu dáng thân xe\n<Highlight>Lốp:</> Thay đổi kiểu dáng lốp\n<Highlight>Biển Số:</> Thay đổi kiểu dáng và số biển\n<Highlight>Động Cơ:</> Thay đổi hiệu năng, cảm giác lái, âm thanh động cơ và lửa phụt đuôi xe\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Mở Khóa Bộ Phận</>\nBí Ấn Ngự Cơ có thể mua tại <Highlight>Thương Thành-Khắc Dấu Hình Tượng</>. Mỗi lần cải tạo tiêu hao <Highlight>1</> Bí Ấn Ngự Cơ sẽ tăng <Highlight>10~12 điểm</> Cải Tạo. Khi tích lũy đủ điểm Cải Tạo sẽ mở khóa bộ phận mới.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Khóa Bộ Phận</>\nKhi cải tạo có thể khóa bộ phận; bộ phận đã khóa sẽ không thay đổi trong lần cải tạo. Đồng thời, khi cải tạo với bộ phận bị khóa, lượng Bí Ấn Ngự Cơ tiêu hao sẽ tăng.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Phẩm Chất Phương Án</>\nPhương án cải tạo của mỗi bộ phận được chia theo phẩm chất: <Quality_3>Thường</>/<Quality_4>Hiếm</>/<Quality_5>Phi Phàm</>/<Quality_6>Thần Quyến</>/<Quality_7>Thần Chú</>. Quy tắc mở:\nMở khóa <Highlight>1</> bộ phận: tối đa xuất hiện phương án <Quality_3>Thường</>\nMở khóa <Highlight>2</> bộ phận: tối đa xuất hiện phương án <Quality_4>Hiếm</>\nMở khóa <Highlight>3</> bộ phận: tối đa xuất hiện phương án <Quality_5>Phi Phàm</>\nMở khóa <Highlight>4</> bộ phận: tối đa xuất hiện phương án <Quality_6>Thần Quyến</>\nMở khóa <Highlight>5</> bộ phận: tối đa xuất hiện phương án <Quality_7>Thần Chú</>\nPhạm vi ngẫu nhiên Phong Cách tăng theo phẩm chất phương án; ngoài ra, tiêu hao càng nhiều Bí Ấn Ngự Cơ, phạm vi ngẫu nhiên Giá Trị Phong Cách càng cao.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Công Bố Xác Suất</>\nPhương án <Quality_3>Thường</>: 55%\nPhương án <Quality_4>Hiếm</>: 29.7%\nPhương án <Quality_5>Phi Phàm</>: 11.4%, mỗi 20 lần cải tạo chắc chắn xuất hiện phương án <Quality_5>Phi Phàm</> trở lên\nPhương án <Quality_6>Thần Quyến</>: 2.9%, mỗi 60 lần cải tạo chắc chắn xuất hiện phương án <Quality_6>Thần Quyến</> trở lên\nPhương án <Quality_7>Thần Chú</>: 1%, mỗi 200 lần cải tạo chắc chắn xuất hiện phương án <Quality_7>Thần Chú</>\nSau khi khóa 4 bộ phận, xác suất phương án <Quality_7>Thần Chú</> tăng lên 3.7%, mỗi 30 lần cải tạo chắc chắn xuất hiện phương án <Quality_7>Thần Chú</>\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Giao Dịch Xe Cũ</>\nDo hạn chế chính sách giao dịch xe cũ, xe Cải Tạo Thần Chú đã có biển số (Điểm Cải Tạo từ <Highlight>1600 trở lên</>) có thể đóng gói thành vật phẩm để bán tại Sàn Giao Dịch. Sau khi kích hoạt ngoại hình của mỗi xe cũ, phải chờ 30 ngày mới có thể đóng gói lại.",
    [1240251532177665] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Con Đường Phi Phàm và Bậc</> Con Đường Phi Phàm, còn gọi là Con Đường Thần, là hệ thống thăng tiến hoàn chỉnh lấy Ma Dược làm cốt lõi. Mỗi Con Đường gồm 10 Bậc, từ 9 đến 0; số Bậc càng thấp, phẩm cấp càng cao và năng lực càng mạnh. Phi Phàm Giả có thể thu thập Công Thức Ma Dược, uống Ma Dược của Bậc tương ứng để nâng Bậc, đồng thời tăng tiến độ Tiêu Hóa Ma Dược nhằm nâng cao thực lực. <img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Thăng Tiến</> Sau khi hoàn thành toàn bộ điều kiện tiên quyết, có thể nhận Nhiệm Vụ Thăng Tiến, chế tạo và uống Ma Dược của Bậc tiếp theo để nâng Bậc.",
    [1240251532178177] = "Mượn vĩ lực của <Highlight>Kẻ Khờ</>, cho người chơi tạm thời có khả năng xây dựng <Highlight>Utopia</>.\n\nQuy trình xây dựng:\n\n· Khoanh phạm vi — chọn diện tích muốn sinh công trình (nếu đã có công trình trên sân, có thể nhấn Xóa để đặt lại khu xây dựng)\n\n· Chỉnh tham số — chỉnh chiều cao công trình; nhấn nút Tỷ Lệ Công Trình góc trên phải để chỉnh chi tiết hơn\n\n· Xem hiệu quả sinh — nhấn Sinh để tạo bản xem trước cụm công trình; nếu chưa hài lòng có thể nhấn Làm Mới\n\n· Tiêu hao Tài Sản Lâu Đài và sinh — sau khi chốt kiểu, nhấn Sinh, tiêu hao Tài Sản Lâu Đài và tạo công trình.\n",
    [1240251532178689] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Công Thức Ma Dược</> Vật bắt buộc để thăng lên Bậc cao hơn, gồm nguyên liệu chính và phụ. Chỉ sau khi thu thập đủ toàn bộ nguyên liệu trong Công Thức Ma Dược của Bậc kế tiếp mới có thể chế tác Ma Dược tương ứng và hoàn thành thăng tiến. <img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nhận Nguyên Liệu Ma Dược</> Khi đạt tiến độ Tiêu Hóa tương ứng, Phi Phàm Giả sẽ nhận Chỉ Dẫn Linh Tính, dẫn tới nhiệm vụ tương ứng để lấy Nguyên Liệu Ma Dược.",
    [1240251532179969] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Bối Cảnh Chiến Trường</>\nHình chiếu lịch sử từ chiến trường cổ Kỷ Nguyên Thứ Tư, chỉ kích hoạt vào <Highlight>khung giờ nhất định</>. Khi chưa mở, chiến trường bị sức mạnh còn sót lại của Huyết Hoàng Đế Alista Tudor chi phối, tràn ngập <Highlight>vặn vẹo và giết chóc</>. Phi Phàm Giả ở trong đó đều chịu ảnh hưởng, khao khát được tôi luyện bằng sắt và máu, tận hưởng <Highlight>khoái cảm chém giết</>.",
    [1240251532180481] = "Sau khi bật, hệ thống sẽ tự động tối ưu trải nghiệm trong <Highlight>chiến đấu nhiều người quy mô lớn</>, ưu tiên độ mượt hình ảnh.\nCác điều chỉnh chỉ có hiệu lực khi vào những gameplay như <Highlight>Chiến Thành</>, <Highlight>Chiến Cao Nguyên</> và <Highlight>Giải Tứ Phương</>; sau khi rời gameplay, các tùy chọn cài đặt khác sẽ không bị thay đổi.",
    [1240251532180737] = "Người chơi có thể chọn số lượng giới hạn Bí Ngẫu để Ra Trận. Bí Ngẫu đã Ra Trận có 100% thuộc tính nhân vật có hiệu lực; Bí Ngẫu chưa Ra Trận chỉ có 35% thuộc tính có hiệu lực.",
    [1240251532181249] = "1. Loại kiểm định: gồm Mị Lực, Trực Giác, Vũ Lực và Học Thức, tương ứng với các hành động và tình huống khác nhau.\n2. Buff kiểm định (thuộc tính): khi kiểm định, thuộc tính Thám Hiểm tương ứng sẽ cho bonus. Thuộc tính cơ bản là 10; cứ vượt 2 điểm, kết quả kiểm định nhận +1 bonus.\n3. Buff kiểm định (bonus trực tiếp): một số Thiên Phú Thám Hiểm ngoài tăng thuộc tính còn trực tiếp cho bonus kiểm định cố định.\n4. Ưu/nhược thế: trong một lần kiểm định, nếu có Ưu Thế, tung 2 xúc xắc và lấy kết quả cao hơn; nếu có Nhược Thế, lấy kết quả thấp hơn.\n5. Cơ hội tung lại: một số Thiên Phú hoặc tình huống cho cơ hội tung lại. Dù kiểm định đầu thất bại, có thể tiêu hao cơ hội để tung lại.\n6. Cộng nhiều xúc xắc: trong một số tình huống, cần tung nhiều xúc xắc và dùng tổng điểm của tất cả làm giá trị cơ bản để kiểm định.",
    [1240251532182273] = "Mở khóa khi nhận 1 Vật Phong Ấn Tấn Công Cấp “1”",
    [1240251532182529] = "Mở khóa khi nhận 1 Vật Phong Ấn Phòng Thủ Cấp “1”",
    [1240251532182785] = "Trước khi tham gia Chạy Đoàn, Phi Phàm Giả phải chọn một Giáo Đoàn để gia nhập.\nCó thể tự do chọn Giáo Đoàn theo sở thích. Trước khi bất kỳ Giáo Đoàn nào đạt cấp 4, có thể đổi Giáo Đoàn tùy ý; sau khi Cấp Giáo Đoàn đạt 4, mỗi lần đổi Giáo Đoàn sẽ có hồi chiêu 7 ngày.\nSau khi chọn Giáo Đoàn còn có thể tự phân bổ Thuộc Tính Thám Bí: mỗi thuộc tính tối thiểu 8, tối đa 16; tổng cộng có 12 Điểm Thuộc Tính để phân cho 4 chiều. Nên dùng phương án khuyến nghị để việc Thám Bí sau đó dễ dàng hơn.",
    [1240251532185089] = "Khi Tai Ách Thế Giới chết, Phi Phàm Giả tham gia chiến đấu có thể nhận thưởng. Mỗi tuần chỉ nhận được <Highlight>1 lần</>.",
    [1240251532185345] = "· Sau khi kích hoạt Hỗ Trợ Một Phím, <Yellow>nhấn nút Đánh Thường</> (mặc định E) sẽ <Yellow>lần lượt dùng kỹ năng</>; <Yellow>giữ nút Đánh Thường</> (mặc định E) trong 2 giây sẽ vào trạng thái <Yellow>Tự Động Dùng Kỹ Năng</>.\n· Khi đang Tự Động Dùng Kỹ Năng, rời chiến đấu hoặc tự nhấn kỹ năng sẽ ngắt trạng thái tự động.\n· Có thể đổi giữa chế độ Ưu Tiên Di Chuyển và Ưu Tiên Kỹ Năng tại Cài Đặt - Chiến Đấu - Điều Khiển - Chế Độ Tự Động Chiến Đấu. Thiết lập này quyết định Hỗ Trợ Một Phím có thử dùng kỹ năng khi nhân vật đang di chuyển hay không.",
    [1240251532185601] = "Nhấn để bật Trang Bị Kỹ Năng Nhanh.",
    [1240251532185857] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy Tắc Tăng Tiến Độ</>\nNộp <Highlight>Mảnh Di Vật Đỏ Thẫm tại Quản Gia Săn Bắt để tăng Tiến Độ Săn Bắt</>. Khi đạt <Highlight>mốc tiến độ tương ứng sẽ mở phần thưởng của mốc đó</>. Trong thời gian sự kiện Săn Bắt, hiệu suất tăng tiến độ khi nộp Mảnh Đỏ Thẫm sẽ <Highlight>tăng rõ rệt</>!\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy Tắc Reset</>\nReset vào <Highlight>8:00 sáng thứ Hai</> hằng tuần.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy Tắc Bảo Đảm Điểm Hạng</>\nKhi đạt hạng <Highlight>Thân Vương Huyết Sắc</>, phần thưởng Tiến Độ Săn Bắt sẽ <Highlight>không còn cung cấp Điểm Thắng Hạng</>.\n",
    [1240251532186881] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Giới Thiệu CLB</>\nGia nhập hoặc tạo CLB để tham gia nhiều hoạt động CLB, nhận phần thưởng phong phú và Huy Chương Đồng Hành; Huy Chương Đồng Hành có thể đổi vật phẩm tại Cửa Hàng CLB.\nCLB gồm CLB Nhàn Nhã và CLB Chiến Đấu, có thể đổi trong thông tin CLB. CLB Nhàn Nhã không hiển thị Điểm Phi Phàm trong danh sách thành viên.\nQuy tắc khóa thành viên: trong các hoạt động lấy CLB làm đơn vị như Liên Đấu Tứ Phương, Bóng Ma Opera, Chiến Thành, Chiến Cao Nguyên, CLB không cho phép thành viên gia nhập hoặc rời đi.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Tạo CLB Hưởng Ứng</>\nKhi nhân vật đạt Cấp 20, có thể gia nhập hoặc tự tạo CLB.\nTạo CLB cần trả phí; trong 24 giờ sau khi tạo, đủ 4 người hưởng ứng thì thành công, quá hạn sẽ thất bại.\nTạo thất bại hoặc chủ động hủy đều không hoàn lại phí tạo.",
    [1240251532187137] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Cách nhận lượt triệu hồi</>\nCó thể nhận lượt triệu hồi bằng các cách sau:\n<Highlight>Làm mới hằng ngày</>: mỗi ngày nhận 1 lượt triệu hồi 【Tiên Phong Tai Dị】 và 1 lượt 【Nhân Ngẫu Vận Mệnh】;\n<Highlight>Nhận thưởng Tiến Độ Săn</>: mở khóa mốc Tiến Độ Săn và nhận thưởng để nhận thêm lượt triệu hồi.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy tắc đặt lại</>\nLượt triệu hồi <Highlight>có thể tích lũy trong tuần</> và được đặt lại đồng loạt vào <Highlight>8:00 sáng thứ Hai</> hằng tuần.\n",
    [1240251532187649] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Tuyên Lệnh Chinh Phục</>\n1. Khi Server Chiến Lược mở, mỗi Chủ Nhật 12:00-19:30 mở Tuyên Chiến;\n2. Trong thời gian Tuyên Chiến, có thể tuyên chiến CLB có xếp hạng Điểm Thần Tuyển chênh không quá 3 bậc so với CLB mình;\n3. Hai khung chiến đấu là Chủ Nhật 20:00-20:25 và 20:30-20:55; bên tuyên chiến tự chọn một khung khi tuyên chiến;\n4. Một CLB có thể bị nhiều CLB tuyên chiến cùng lúc; nếu bị nhiều bên tuyên chiến, các bên tấn công cũng là phe địch của nhau;\n5. CLB có thể vừa tuyên chiến vừa bị tuyên chiến, cũng có thể tuyên chiến nhiều CLB; trong giao diện Tuyên Lệnh Chinh Phục có thể tự do truyền tống giữa các khu CLB Chiến Đấu;\n6. Trong trận, bên công phải chiếm hai Bia Chinh Phục trên và dưới (bất kỳ bên công nào chiếm đều được, không cần cùng một bên) để mở Cổng Chiến Tranh và tấn công Cờ Chinh Phục;\n7. Nếu Cờ Chinh Phục bị chiếm, toàn bộ bên công thắng và cướp Điểm Thần Tuyển của bên thủ; bên tung đòn kết liễu nhận nhiều Điểm Thần Tuyển hơn;\n8. Nếu hết giờ mà Cờ Chinh Phục chưa bị chiếm, toàn bộ bên công thua và mất Điểm Thần Tuyển CLB; bên thủ nhận Điểm Thần Tuyển.",
    [1240251532188929] = "<Highlight>Độ Cao Tầng</> quyết định <Highlight>chiều cao tối đa</> của công trình do Xây Dựng Kỳ Tích tạo ra.\nNâng cấp Lâu Đài sẽ mở khóa Độ Cao Tầng mới.\nMỗi phong cách xây dựng có phạm vi Độ Cao Tầng có thể chọn khác nhau.",
    [1240251532189185] = "Mua vật phẩm tại Cửa Hàng CLB để dùng trong biểu diễn, cổ vũ đồng đội!\nQuy tắc:\n• Mỗi trận, mỗi loại vật phẩm dùng tối đa X lần\n• Sau khi dùng hồi chiêu 3 giây\n• Điểm hiệu ứng đặc biệt tính riêng, không chịu bonus Like\n\nTips: Vật phẩm giới hạn mua theo tuần, nhớ tích trước!",
    [1240251532190209] = "Quy tắc tính trong phần Dữ Liệu Thêm:\n<Highlight>Tỷ Lệ Bạo Kích (Gây Sát Thương)</>: số đoạn Sát Thương Bạo Kích / tổng số đoạn sát thương\n<Highlight>Tỷ Lệ Xuyên Thấu</>: số đoạn sát thương không bị Chặn Đòn / tổng số đoạn sát thương\n<Highlight>Tỷ Lệ Đơn Mục Tiêu</>: tỷ trọng sát thương của kỹ năng có tag “Đơn Mục Tiêu”\n<Highlight>Tỷ Lệ Quần Thể</>: tỷ trọng sát thương của kỹ năng có tag “Quần Thể”\n<Highlight>Tỷ Lệ Bộc Phát</>: tỷ trọng sát thương của kỹ năng có tag “Bộc Phát”\n<Highlight>Tỷ Lệ Duy Trì</>: tỷ trọng sát thương của kỹ năng có tag “Duy Trì”\n<Highlight>Thời Gian Khống Chế Mạnh (Gây Ra)</>: thời lượng Khống Chế Mạnh thực tế gây ra (khống chế nhiều mục tiêu cùng lúc sẽ cộng nhiều thời gian)\n<Highlight>Thời Gian Khống Chế Nhẹ (Gây Ra)</>: thời lượng Khống Chế Nhẹ thực tế gây ra (khống chế nhiều mục tiêu cùng lúc sẽ cộng nhiều thời gian)\n<Highlight>Tỷ Lệ Bạo Kích (Chịu Sát Thương)</>: số đoạn Sát Thương Bạo Kích phải chịu / tổng số đoạn sát thương phải chịu\n<Highlight>Tỷ Lệ Chặn Đòn</>: số đoạn sát thương Chặn Đòn / tổng số đoạn sát thương phải chịu\n<Highlight>Thời Gian Khống Chế Mạnh (Phải Chịu)</>: thời lượng Khống Chế Mạnh thực tế phải chịu\n<Highlight>Thời Gian Khống Chế Nhẹ (Phải Chịu)</>: thời lượng Khống Chế Nhẹ thực tế phải chịu",
    [1240251532190721] = "· Liên Kết Bí Ẩn tối đa Cấp 7. Khi đầy cấp, Thiện Cảm dư tự động quy đổi thành 【Hộp Ký Ức】 theo tỷ lệ 10:1, dùng tại cửa hàng 【Phòng Trưng Bày Chuyện Xưa】 để đổi ngoại trang.\n· Khi Phi Phàm Giả cùng Nhân Mạch tham gia các tương tác như Dạo Bước, Hẹn Gặp, Cùng Nhảy có thể tiêu hao 【Thiệp Hoài Niệm】 và nhận Thiện Cảm. Lần tương tác đầu tiên mỗi ngày không tốn thiệp; tất cả Nhân Mạch dùng chung lượt miễn phí này.\n· Sau khi thực hiện một loại tương tác với cùng Nhân Mạch và tiêu hao thiệp, tiếp tục cùng loại trong ngày sẽ không tốn thêm thiệp và cũng không nhận thêm Thiện Cảm.\n· Dạo Bước: chỉ dùng ở Đại Thế Giới; khi vào Phó Bản hoặc khu vực không thuộc Đại Thế Giới sẽ tự hủy.\n· Khi Thiện Cảm với Nhân Mạch đạt Cấp 2, mỗi ngày nhận 2 lượt Tập Thư Mời với Nhân Mạch đó (số lượt tăng theo Cấp Thiện Cảm). Tiêu hao lượt Tập Thư Mời và số 【Thiệp Hoài Niệm】 tương ứng để hoàn thành nhanh số lượt tương tác, trực tiếp nhận Thiện Cảm và phần thưởng.\n· Mỗi ngày còn nhận 5 lượt Tập Thư Mời dùng chung cho mọi Nhân Mạch, tích tối đa 15 lượt, nhưng chỉ dùng được sau khi mở 【Phúc Âm Kẻ Khờ】.\n· Khi tương tác nhanh với Nhân Mạch, ưu tiên tiêu hao lượt riêng của Nhân Mạch trước, sau đó mới dùng lượt chung.",
    [1240251532190977] = "Trong một lần Phó Bản độ khó “Thường”, hạ toàn bộ Boss và mỗi trận số lần hồi sinh toàn đội sử dụng không quá 1.",
    [1240251532192001] = "Sau mỗi khoảng thời gian, Giáp Tổ Tiên triệu hồi nhiều “Thương Ô Uế” liên tục gây sát thương xung quanh; cần phân người dọn các cây Thương.",
    [1240251532192513] = "Trong một lần Phó Bản độ khó “Khó”, hạ toàn bộ Boss và mỗi trận số lần hồi sinh toàn đội sử dụng không quá 1.",
    [1240251532193537] = "Giáp Tổ Tiên chỉ định 6 người chơi và áp Ô Nhiễm Ý Chí, tạo Pháp Trường liên tục bám theo và định kỳ mở rộng, gây Sát Thương cho bản thân cùng đồng đội trong phạm vi. Đồng thời tạo 6 Mảnh Ý Chí; 6 người bị ô nhiễm mỗi người chạm 1 mảnh để giải trừ Ô Nhiễm.",
    [1240251532193793] = "Khi vào Giai Đoạn 2, Nhà Chiêm Tinh triệu hồi thiên thạch khổng lồ đập xuống giữa sân, tạo Áp Lực Gió liên tục và Sóng Khuếch Tán. Chạm Sóng Khuếch Tán sẽ bị Đẩy Lùi; nếu chạm mép sân sẽ tử vong ngay.",
    [1240251532194817] = "Sau khi Hộ Vệ Hậu Duệ vào chiến đấu sẽ nhận Năng Lượng Luyện Kim. Năng lượng tăng theo thời gian hoặc khi một số kỹ năng nhất định trúng người chơi. Khi năng lượng đạt 100%, Hộ Vệ Hậu Duệ vào trạng thái Mất Kiểm Soát và dùng “Nghi Thức Giác Đấu”; trong trạng thái này, chịu tấn công sẽ làm giảm năng lượng. Khi năng lượng về 0, Hộ Vệ Hậu Duệ vào trạng thái Phá Phòng.",
    [1240251532195329] = "Toàn bộ gương do Phu Nhân Tử Tước triệu hồi ở Giai Đoạn 2 đều phát sáng; người chơi không thể nhìn trực tiếp để biết gương nào đúng, chỉ có thể chủ động đi vào thử để tìm đúng gương.",
    [1240251532196353] = "Sau khi Hộ Vệ Hậu Duệ vào chiến đấu sẽ nhận Năng Lượng Luyện Kim. Năng lượng tăng theo thời gian hoặc khi một số kỹ năng nhất định trúng người chơi. Khi năng lượng đạt 100%, Hộ Vệ Hậu Duệ vào trạng thái Mất Kiểm Soát và dùng “Vũ Trang Luyện Kim”; trong trạng thái này, chịu tấn công sẽ làm giảm năng lượng. Khi năng lượng về 0, Hộ Vệ Hậu Duệ vào trạng thái Phá Phòng.",
    [1240251532197121] = "<Highlight>【Giải Thích Quy Tắc】</>\n\n<Title>Sức Mạnh Linh Tính</>\n1. Bonnie rải Mảnh Linh Tính khắp nơi — tranh đoạt thật mạnh!\n2. Một Đặc Tính Lôi Điện sẽ giáng xuống giữa sân; chạm vào để tạm thời làm chủ Sức Mạnh Lôi Điện.\n3. Dùng Sức Mạnh Lôi Điện hạ kẻ địch sẽ nhận lượng lớn Linh Tính, nhưng trong thời gian đó không thể nhặt bất kỳ Sức Mạnh Linh Tính nào khác.\n<Title>Thu Thập Linh Tính</>\n1. Các Quang Cầu Linh Tính khác cũng trôi khắp sân; chạm vào để nhận năng lực khác nhau.\n2. Khéo léo dùng kỹ năng đã nhận để quần thảo với kẻ địch, đồng thời thu thập càng nhiều Mảnh Linh Tính càng tốt.\n3. Đôi khi nắm đấm còn hữu dụng hơn Linh Tính.\n<Title>Quy Tắc Ngẫu Nhiên</>\n1. Trò chơi gồm 3 vòng; nghi thức mỗi vòng có quy tắc khác nhau.\n2. Điều chỉnh chiến thuật theo biến đổi môi trường để trở thành người thắng cuối cùng!\n3. Không cố gắng thì không nhận được phần thưởng của Bonnie đâu.",
    [1240251532197377] = "Mọi món quà của Vận Mệnh đều đã âm thầm được định giá từ trước.\n<Highlight>1. Thời Gian Sự Kiện</>\nSự kiện kỳ này diễn ra từ <Quality_5>08:00 ngày 2026-08-21 đến 08:00 ngày 2026-10-15</>.\n<Highlight>2. Quy Tắc</>\nHoàn thành nhiệm vụ sự kiện để nhận EXP, tích lũy EXP nâng cấp và nhận thưởng theo cấp. Mua <Quality_5>Ân Điển Thời Đại (Battle Pass Cao Cấp)</> để mở thêm phần thưởng và đặc quyền. Mua <Quality_5>Quà Tặng Vận Mệnh (Battle Pass Sưu Tầm)</>, ngoài toàn bộ thưởng và đặc quyền của <Quality_5>Battle Pass Cao Cấp</>, còn nhận ngay nhiều phần thưởng hiếm cùng quyền lợi <Quality_5>tăng thẳng 15 cấp</> và các quyền lợi sưu tầm khác.\n<Highlight>3. Nhiệm Vụ Sự Kiện</>\nNhiệm vụ gồm Nhiệm Vụ Tuần và Nhiệm Vụ Mùa. Nhiệm Vụ Tuần có thể hoàn thành nhiều vòng mỗi tuần; EXP nhận được tính vào giới hạn EXP tuần và giới hạn này có thể cộng dồn theo từng tuần trong thời gian sự kiện. Nhiệm Vụ Mùa chỉ hoàn thành một lần; EXP nhận được không tính vào giới hạn tuần.",
    [1240251532197889] = "Sau khi dùng Tụ Hợp Một Chạm, sẽ tiêu hao Vật Chất Phi Phàm, Nhân Tố Tụ Hợp và Suli Khóa đang sở hữu; lần lượt tụ hợp Vật Chất Phi Phàm 1 từ với 1 từ, 2 từ với 2 từ, 3 từ với 3 từ. Sản phẩm được tự động giữ theo ưu tiên: có Từ Kẻ Khờ > có Từ Dị Biến khác > Điểm cao.\nLưu ý: Không tụ hợp hai Vật Chất Phi Phàm đều có Từ Dị Biến. Khi số Vật Chất Phi Phàm còn lại quá ít sẽ không Tụ Hợp Một Chạm. Vật Chất Phi Phàm có thể giao dịch không được dùng trong Tụ Hợp Một Chạm hoặc Tụ Hợp Tùy Chỉnh. Vật Chất Phi Phàm có Từ Dị Biến có thể bị dùng trong Tụ Hợp Một Chạm, nhưng không bị dùng trong Tụ Hợp Tùy Chỉnh.",
    [1240251532198657] = "Sau khi gia nhập Giáo Đoàn, Phi Phàm Giả cần tuân thủ quy định, hoàn thành yêu cầu mỗi tuần đúng hạn; người không hoàn thành sẽ bị trừng phạt.\nTham gia hoạt động Giáo Đoàn để nhận Điểm Hành Động Giáo Đoàn và tiến độ Rương Quà Xã Giao. Điểm Hành Động dùng nâng Cấp Giáo Đoàn và nhận thưởng cấp; tiến độ Rương dùng tăng tiến độ rương, tiêu hao Thể Lực để mở và nhận Trang Bị, Vật Chất Phi Phàm, Suli Khóa...",
    [1240251532198913] = "2 Phó Bản này dùng chung số lượt thưởng. Sau khi hạ Boss và nhặt thưởng ở bất kỳ Phó Bản nào, lượt thưởng của Phó Bản còn lại cũng bị tiêu hao.",
    [1240251532200961] = "Trong khu vực chỉ định, <Highlight>triệu hồi Sinh Vật Siêu Phàm</>; cuộc săn bắt đầu.",
    [1240251532201217] = "<Title>Buff Số Lần Hồi Sinh</>\nTrong đội hoặc tổ đội lớn, nếu có 3~8 người cùng Gia Tộc, nhận thêm 1 lần hồi sinh; từ 9 người cùng Gia Tộc trở lên, nhận thêm 2 lần hồi sinh. Sau khi rời Gia Tộc có 24 giờ chờ hiệu lực.\n<Title>Buff Bù Thuộc Tính</>\nTrong đội hoặc tổ đội lớn, khi có thành viên cùng Gia Tộc sẽ nhận buff thuộc tính. Số thành viên cùng Gia Tộc trong tổ đội lớn càng nhiều, hiệu quả buff càng cao. Sau khi rời Gia Tộc có 24 giờ chờ hiệu lực.",
    [1240251532201473] = "Trước khi tham gia Chạy Đoàn, Phi Phàm Giả phải chọn một Giáo Đoàn để gia nhập.\nPhi Phàm Giả có thể tăng Tổng Độ Khám Phá bằng cách Thám Bí trong Thế Giới Trật Tự và Mặt Tối Thành Phố; đồng thời dùng Thiên Phú Chạy Đoàn để tăng Thuộc Tính Thám Bí. Thuộc Tính Thám Bí càng cao, tỷ lệ thành công của lối chơi Tung Xúc Xắc càng lớn.",
    [1240251532201729] = "Lần 「Thử Nghiệm Sương Xám」 này là thử nghiệm có nạp phí và xóa dữ liệu. Tổng số tiền Phi Phàm Giả đã nạp trong thời gian thử nghiệm sẽ được hoàn lại sau khi Open Beta theo các quy tắc dưới đây. Vui lòng đọc kỹ.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Bảng Vàng/Bảng Vàng Khóa</>\nTổng số tiền nạp trong thời gian thử nghiệm (bao gồm mua Bảng Vàng, Phúc Âm Kẻ Khờ, Ân Điển Thời Đại, Quà Tặng Vận Mệnh và các sản phẩm trả tiền mặt khác) sẽ được hoàn theo tỷ lệ sau khi Open Beta, với chuẩn 【1 NDT = 10 Bảng Vàng】. Quy tắc cụ thể:\n● Nếu tổng tiền nạp trong thử nghiệm là <Highlight>0-4000 NDT (gồm 4000)</>: nhận hoàn <Highlight>120% Bảng Vàng</> và <Highlight>50% Bảng Vàng Khóa</>.\n● Nếu tổng tiền nạp <Highlight>trên 4000 NDT</>: phần 0~4000 NDT (gồm 4000) được hoàn <Highlight>120% Bảng Vàng</> và <Highlight>50% Bảng Vàng Khóa</>; phần vượt 4000 NDT được hoàn <Highlight>120% Bảng Vàng</>, không tặng thêm Bảng Vàng Khóa.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Phúc Âm Kẻ Khờ</>\nSố tiền dùng mua 【Phúc Âm Kẻ Khờ】 trong thử nghiệm đều được tính vào tổng tiền nạp. Sau Open Beta, số tiền mua 【Phúc Âm Kẻ Khờ】 <Highlight>không chỉ được hoàn theo quy tắc 【Bảng Vàng】 mà còn nhận hoàn lại 【Phúc Âm Kẻ Khờ】</>. Quy tắc cụ thể:\n● Phi Phàm Giả đã mua 【Phúc Âm Kẻ Khờ】 sẽ nhận số <Highlight>đạo cụ 【Phúc Âm Kẻ Khờ】 hoàn lại</> tương ứng với số đã mua, tối đa <Highlight>2 phần</>.\n● Phần vượt 2 vẫn được tính vào tổng tiền nạp nhưng không hoàn thêm đạo cụ 【Phúc Âm Kẻ Khờ】.\n● Sau khi nhận, Phúc Âm Kẻ Khờ được lưu trong Túi Đồ; Phi Phàm Giả phải chủ động dùng để kích hoạt, trước khi dùng sẽ không hết hạn.\nLưu ý: số tiền trả khi mua 【Phúc Âm Kẻ Khờ】 được tính vào tổng hoàn theo quy tắc 【Bảng Vàng】 nêu trên. Dùng đạo cụ Phúc Âm Kẻ Khờ <Highlight>chỉ nhận quyền lợi 30 ngày</>, không nhận lại 【Bảng Vàng】 tặng kèm lúc mua. Quy tắc sử dụng, cộng dồn hoặc gia hạn nhiều đạo cụ 【Phúc Âm Kẻ Khờ】 lấy quy tắc thực tế trong game Open Beta làm chuẩn.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Ân Điển Thời Đại/Quà Tặng Vận Mệnh</>\nSố tiền mua 【Ân Điển Thời Đại】 hoặc 【Quà Tặng Vận Mệnh】 trong thử nghiệm đều được tính vào tổng tiền nạp. Khi Open Beta, số tiền mua 【Ân Điển Thời Đại】 hoặc 【Quà Tặng Vận Mệnh】 <Highlight>không chỉ được hoàn theo quy tắc 【Bảng Vàng】 mà còn nhận hoàn lại 【Ân Điển Thời Đại】 hoặc 【Quà Tặng Vận Mệnh】</>. Quy tắc cụ thể:\n● Phi Phàm Giả đã mua 【Ân Điển Thời Đại】 sẽ nhận <Highlight>đạo cụ 【Ân Điển Thời Đại】 hoàn lại</> khi Open Beta; dùng để mở khóa Battle Pass 【Ân Điển Thời Đại】 kỳ hiện tại.\n● Phi Phàm Giả đã mua 【Quà Tặng Vận Mệnh】 hoặc nâng cấp lên 【Quà Tặng Vận Mệnh】 qua 【Quà Nâng Cấp Quà Tặng Vận Mệnh】 sẽ nhận <Highlight>đạo cụ 【Quà Tặng Vận Mệnh】 hoàn lại</> khi Open Beta; dùng để mở khóa Battle Pass 【Quà Tặng Vận Mệnh】 kỳ hiện tại.\n● Nếu tạo nhiều nhân vật và mua nhiều Battle Pass, <Highlight>tối đa hoàn 1 đạo cụ Battle Pass</>; nếu mua các bậc khác nhau, ưu tiên hoàn đạo cụ <Highlight>【Quà Tặng Vận Mệnh】</> bậc cao hơn.\n● Số tiền mua các Battle Pass còn lại vẫn được tính vào tổng tiền nạp nhưng không hoàn thêm đạo cụ Battle Pass tương ứng.\n● Sau khi nhận, đạo cụ tương ứng được lưu trong Túi Đồ; Phi Phàm Giả phải chủ động dùng để kích hoạt, trước khi dùng sẽ không hết hạn.\nLưu ý: tiền trả khi mua Battle Pass được tính vào tổng hoàn theo quy tắc 【Bảng Vàng】 nêu trên.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Ví dụ</>\nĐể Phi Phàm Giả dễ hiểu, ví dụ như sau ▼\nNếu trong thời gian thử nghiệm bạn đã nạp tổng cộng <Highlight>5218 NDT</>, trong đó 5000 NDT mua Bảng Vàng và sản phẩm trả tiền mặt khác, 90 NDT mua 3 Phúc Âm Kẻ Khờ, 128 NDT mua 1 Quà Tặng Vận Mệnh, thì sau khi Open Beta sẽ nhận:\n\nTổng Bảng Vàng hoàn lại:\n● Phần 4000 NDT: 4000 × 10 × 120% = <Highlight>48000</>\n● Phần 1218 NDT: 1218 × 10 × 120% = <Highlight>14616</>\n● Tổng Bảng Vàng: <Highlight>62616</>\n\nTổng Bảng Vàng Khóa được tặng:\n● Phần 4000 NDT: 4000 × 10 × 50% = <Highlight>20000</>\n● Tổng Bảng Vàng Khóa: <Highlight>20000</>\n\nĐạo cụ hoàn lại:\n● <Highlight>【Phúc Âm Kẻ Khờ】× 2</>\n● <Highlight>【Quà Tặng Vận Mệnh】× 1</>\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Cách nhận</>\nSau khi Open Beta, Phi Phàm Giả dùng tài khoản đã nạp trong 「Thử Nghiệm Sương Xám」 đăng nhập game ở đúng kênh tương ứng, chọn bất kỳ server nào tạo nhân vật. <Highlight>Sau khi hoàn thành nhiệm vụ chính Chương 1</>, bạn sẽ nhận thư thông báo mở khóa hoàn nạp; tới địa điểm chỉ định và nói chuyện với NPC nhận hoàn để lấy phần hoàn nạp tương ứng.\nSự kiện có hiệu lực <Highlight>6 tháng sau Open Beta</>; quá hạn sẽ không hỗ trợ nhận. Đạo cụ hoàn lại đã nhận thành công trong thời hạn sẽ được lưu vào Túi Đồ và không hết hạn trước khi dùng.\n※Mỗi tài khoản chỉ có <Highlight>một nhân vật được nhận một lần</>; vui lòng xác nhận kỹ nhân vật trước khi nhận.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Cách tra cứu</>\nMini-app tra cứu hoàn nạp 「Thử Nghiệm Sương Xám」 sẽ ra mắt sau khi thử nghiệm kết thúc. Khi mở, Phi Phàm Giả có thể tra cứu tổng tiền đã nạp trong thử nghiệm và nội dung hoàn lại.\nTrong thời gian thử nghiệm, có thể xem tổng tiền nạp hiện tại của tài khoản tại trang <Highlight>【Cửa Hàng】-【Nạp】</>.\n※Thời gian ra mắt cụ thể của mini-app theo thông báo chính thức sau này. Mini-app chỉ hỗ trợ tra dữ liệu nạp của server chính thức; người tham gia qua kênh khác có thể liên hệ CSKH của kênh tương ứng.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Lưu ý</>\nTrong 「Thử Nghiệm Sương Xám」, tiền nạp của mọi nhân vật cùng kênh và cùng tài khoản được cộng chung. Tiền thanh toán qua PC, mobile, trung tâm nạp và các hình thức nạp khác đều được tính vào tổng tiền nạp. Tiền nạp ở các kênh khác nhau được cộng riêng, không gộp.\nTiền nạp trên <Highlight>server chính thức</> trong thử nghiệm chỉ có thể nhận hoàn trên <Highlight>server chính thức</> sau Open Beta; tiền nạp trên <Highlight>server kênh</> chỉ có thể nhận hoàn trên <Highlight>server kênh</> khi Open Beta.\nNội dung hoàn của 「Thử Nghiệm Sương Xám」 chỉ tính số tiền thanh toán bằng tiền mặt. Các tài nguyên được tặng qua sự kiện hoặc đạo cụ nhận thêm sau khi dùng sản phẩm (bao gồm nhưng không giới hạn: Bảng Vàng tặng thêm khi nạp, Bảng Vàng tặng từ Thẻ Tháng, đạo cụ tặng từ Battle Pass bản cao cấp, đạo cụ trong Battle Pass/Thẻ Tháng, quà hệ thống, thư vận hành, v.v.) <Highlight>không tính vào nội dung hoàn</>.\nNội dung hoàn chỉ có thể nhận sau khi 《Quỷ Bí Chi Chủ》 chính thức Open Beta bằng đúng tài khoản đã nạp trong 「Thử Nghiệm Sương Xám」, <Highlight>không thể nhận chéo tài khoản</> hoặc chuyển nội dung hoàn sang tài khoản khác.\nPhần thưởng cuối cùng chỉ có thể được <Highlight>một nhân vật nhận một lần</>; hãy chọn nhân vật cẩn thận. Sau khi nhận, các nhân vật khác trên tài khoản sẽ không thể nhận lại.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Q&A</>\nQ1 「Thử Nghiệm Sương Xám」 hỗ trợ những phương thức nạp nào?\nLần thử nghiệm này hỗ trợ các phương thức thanh toán phổ biến như <Highlight>Alipay, WeChat Pay</>.\n\nQ2 Sau khi nạp, tôi không nhận được sản phẩm (Bảng Vàng, Phúc Âm Kẻ Khờ, v.v.) thì làm sao?\nNếu nạp lâu mà chưa nhận được, hãy phản hồi qua <Highlight>Trung Tâm CSKH trong game</>.\n\nQ3 Tiền nạp có dùng chung giữa các thiết bị khác nền tảng (như PC và điện thoại) không?\nTrong thời gian thử nghiệm, dưới cùng một tài khoản, số tiền của mọi phương thức nạp (PC, mobile, trung tâm nạp) <Highlight>sẽ được cộng chung</>.\n\nQ4 Hoàn nạp có hỗ trợ nhận chéo tài khoản không?\n<Highlight>Không</>. Sau khi Open Beta, Phi Phàm Giả phải đăng nhập đúng tài khoản từng nạp trong 「Thử Nghiệm Sương Xám」 để nhận hoàn nạp; không thể thao tác chéo tài khoản.\n\nQ5 Tôi đã nạp tiền trong 「Thử Nghiệm Sương Xám」, khi nào có thể nhận hoàn nạp?\nPhi Phàm Giả có thể <Highlight>sau khi game Open Beta</>, nói chuyện với NPC chỉ định trong game để nhận phần hoàn tương ứng. Hãy dùng đúng tài khoản đã tham gia 「Thử Nghiệm Sương Xám」.\n\nQ6 Nội dung hoàn có thời hạn nhận không?\nCó. Cần nhận trong <Highlight>6 tháng sau Open Beta</>; quá hạn sẽ không còn hỗ trợ.\n\nQ7 Tôi tham gia thử nghiệm qua taptap hoặc bilibili và đã nạp tiền, hoàn như thế nào?\n● Phi Phàm Giả tham gia qua <Highlight>taptap</> có thể sau Open Beta dùng <Highlight>tài khoản Hộ Chiếu Dan Zhi Universe</> từng tham gia 「Thử Nghiệm Sương Xám」 để đăng nhập game và nhận phần hoàn tương ứng.\n● Phi Phàm Giả tham gia qua <Highlight>bilibili</> cần sau Open Beta tải client tương ứng từ <Highlight>Trung Tâm Game bilibili</>, đăng nhập tài khoản bilibili đã nạp và nhận phần hoàn tương ứng.",
    [1240251532203265] = "1. Dựa theo xếp hạng Điểm Thần Tuyển CLB, có thể phong một số thành viên CLB làm Tiên Phong Chinh Phục;\n2. Người được phong Tiên Phong Chinh Phục nhận vật phẩm “Chứng Nhận Chinh Phục”;\n3. Khi nâng Quân Hàm cá nhân từ Cấp 4 lên Cấp 3, cần tiêu hao 1 “Chứng Nhận Chinh Phục”.",
    [1240251532203521] = "Khi đổi Bộ Trang Bị, hệ thống sẽ đồng thời đổi trang bị và Phương Án Ân Tứ áp dụng cho trang bị tương ứng. Hãy thiết lập các Bộ Trang Bị khác nhau để ứng phó nhiều tình huống chiến đấu.\nCùng một trang bị có thể được đặt trong nhiều Bộ Trang Bị và áp dụng các Phương Án Ân Tứ khác nhau.",
    [1240251532205313] = "<Highlight>Loạn Đấu CLB</> bắt nguồn từ một Vật Phong Ấn hình đĩa gương sở hữu năng lực Học Giả Cổ Đại. Người chơi có thể tạm thời dùng năng lực Học Giả Cổ Đại như một Triệu Hồi Sư, triệu hồi <Highlight>Hình Chiếu Lịch Sử</> bên trong để đối chiến. Hình Chiếu Lịch Sử lấy trạng thái của người chơi tại một thời điểm trong quá khứ và tạo thành hình chiếu tương ứng.\nLối chơi mở đăng ký lúc <Highlight>12:00</> trưa Thứ Ba, Thứ Năm hàng tuần và chiến đấu lúc <Highlight>19:00~20:30</> (giải đầu tiên của server mở đăng ký <Highlight>12:00 trưa</> Thứ Bảy).\nSố vòng mở dựa theo <Highlight>số người tham gia</> kỳ trước (CLB cần trên 20 thành viên và Độ Hoạt Động trên 100; số vòng giải đầu tiên trong CLB dựa theo số thành viên CLB).",
    [1240251532206081] = "Khi Sinh Mệnh Sylvia giảm xuống 75%/50%/25%, cô ta triệu hồi Hành Quân Nấm Hủ trên sân, để lại vùng Ô Nhiễm, đồng thời tụ lực triệu hồi Cuồng Phong; khoảng cách Đẩy Lùi thay đổi theo số tầng tụ lực.",
    [1240251532206849] = "Khi Máu của Sylvia giảm xuống 75%/50%/25%, cô ta sẽ triệu hồi Hành Quân Nấm Thối trên sân, để lại vùng ô nhiễm; đồng thời triệu hồi Gió Mùa, liên tiếp hất lùi người chơi 3 lần.",
    [1240251532207873] = "Máu ban đầu của Xe Ngựa giảm. Trong chiến đấu, vật phẩm Sửa Chữa liên tục rơi trên sân; dùng lên Xe Ngựa để hồi Máu. Bị Bí Pháp Cầu đánh trúng sẽ mất 1 vật phẩm Sửa Chữa.",
    [1240251532208641] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Giới Thiệu Bí Bảo</>\n1. Bí Bảo chia thành <Highlight>Bí Bảo Mạo Hiểm Thế Giới</>, <Highlight>Bí Bảo Lấy Chiến Nuôi Chiến</>, <Highlight>Bí Bảo Quà Tặng Xã Giao</>; tiến độ và phần thưởng từng loại độc lập.\n2. Mở Bí Bảo có thể nhận trang bị theo Cấp Trang Bị tương ứng. <Highlight>Bí Bảo Mạo Hiểm Thế Giới và Lấy Chiến Nuôi Chiến</> cho <Highlight>nhiều tài nguyên phát triển</>; <Highlight>Bí Bảo Quà Tặng Xã Giao</> cho <Highlight>tài nguyên có thể giao dịch</>.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nhận Bí Bảo</>\n1. Tham gia lối chơi tương ứng sẽ <Highlight>tích lũy tiến độ Bí Bảo</>; khi đầy, tiến độ tự động chuyển thành Bí Bảo tương ứng.\n2. Chuyển tiến độ thành Bí Bảo Cấp Trang Bị 35/45/55 có giới hạn, tối đa <Highlight>10</> lần. Tiến độ vượt giới hạn sẽ <Highlight>tự lưu</>; khi mở Bí Bảo Cấp Trang Bị mới sẽ <Highlight>chuyển thành Bí Bảo mới</>.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Tích Lũy Lượt Mở</>\nTừ Thứ Hai, mỗi ngày thêm và tích lũy Lượt Mở Dùng Chung đến khi reset vào Thứ Hai kế tiếp. Lượt chưa dùng trong tuần sẽ bị xóa. Quy tắc:\n1. Thứ Hai–Thứ Sáu mỗi ngày thêm và tích lũy <Highlight>10</> lượt;\n2. Từ tuần thứ hai sau mở server, Thứ Bảy–Chủ Nhật <Highlight>không giới hạn lượt</>;\n3. Tuần đầu mở server, Thứ Sáu–Chủ Nhật vẫn mỗi ngày thêm và tích lũy <Highlight>10</> lượt.\n4. Bí Bảo đã nhận nhưng chưa mở có thể chủ động vứt sau khi mở khóa Bí Bảo mới.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy Tắc Tiêu Hao Thể Lực</>\nThể Lực tiêu hao cho Lượt Mở Dùng Chung tăng theo số lần Phi Phàm Giả đã mở:\nLần 1-5: <Highlight>20</> Thể Lực;\nLần 6-10: <Highlight>50</> Thể Lực;\nLần 11-20: <Highlight>100</> Thể Lực;\nLần 21-30: <Highlight>150</> Thể Lực;\nSau 30 lần: <Highlight>200</> Thể Lực.",
    [1240251532208897] = "1. Camera Thường cung cấp góc quay tiêu chuẩn, thuận tiện hiển thị nhân vật và chỉnh bố cục.\n2. Camera Tự Do cho phép tự do điều khiển vị trí và góc quay để tạo nhiều kiểu khung hình sáng tạo hơn.",
    [1240251532209665] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Lý Trí</>\nKhi hoạt động trong thế giới Phi Phàm, nhiều sự kiện sẽ khiến Lý Trí dao động. Khi Lý Trí liên tục giảm, trạng thái dị thường bắt đầu từ thể xác, rồi dần xâm thực Thể Dĩ Thái, Thể Tâm Trí, Thể Tinh Linh và Thể Tinh Thần; nhân vật lần lượt bước vào các mức trạng thái tinh thần khác nhau và chịu hiệu ứng tương ứng.\n\nKhi Lý Trí dồi dào, nhân vật ở trạng thái <Highlight>「Tâm Trí Neo Định」</>, giảm tiêu hao Thể Lực và tăng Giảm Thương; trở về mức bình thường sẽ vào <Highlight>「Tỉnh Táo」</>, không có hiệu ứng.\n\nKhi Lý Trí tiếp tục giảm, nhân vật lần lượt vào <Highlight>「Bất An」「Tự Ngã Hoài Nghi」「Thì Thầm Quấn Thân」</>; Thể Lực và độ ổn định khi chạy nước rút bị suy yếu ở các mức khác nhau, xung quanh xuất hiện lời thì thầm gây nhiễu.\n\nKhi Lý Trí xuống thấp, nhân vật vào <Highlight>「Rơi Vào Điên Cuồng」</>, mọi hạn chế hành động được gỡ bỏ, đồng thời sát thương gây ra và sát thương phải chịu đều tăng.\n\nKhi Lý Trí chạm mức thấp nhất, nhân vật vào <Highlight>「Bờ Vực Mất Kiểm Soát」</>: <Highlight>Tăng Sát Thương</>, nhưng sát thương phải chịu cũng tăng, hiệu quả Trị Liệu nhận được giảm, cơ thể phát sáng đỏ và tầm nhìn trở nên điên loạn.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Khôi Phục Lý Trí</>\nKhi Lý Trí giảm tới mức nhất định, người chơi có thể nhờ thành viên Hội Requiem hỗ trợ hồi Lý Trí.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Mất Kiểm Soát</>\nNếu nhân vật ở trạng thái 「Mất Kiểm Soát」 quá lâu mà không được tịnh hóa, sự xâm thực lên Ngũ Thể sẽ tiếp tục sâu hơn và có thể dẫn tới hậu quả nghiêm trọng khó lường.",
    [1240251532209921] = "<Highlight>Con Đường An Hồn</>\nNgười chơi có thể dùng <Highlight>An Hồn</> để tăng Lý Trí, giảm ảnh hưởng tiêu cực do Xâm Thực Tinh Thần.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>1、Người Tiếp Dẫn Thi Xã An Hồn</>\nCó thể tìm Người Tiếp Dẫn của Thi Xã An Hồn trong thế giới để tiến hành An Hồn và lập tức tăng Lý Trí. <Highlight>Cần trả một khoản phí</>.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>2、Nhờ Người Chơi Thi Xã An Hồn Giúp 【Khuyên Dùng】</>\nCó thể gửi yêu cầu trợ giúp ở các kênh, nhờ thành viên Giáo Đoàn thuộc Thi Xã An Hồn hỗ trợ An Hồn; <Highlight>hoàn toàn miễn phí, không tốn chi phí</>.",
    [1240251532210177] = "Khi Lý Trí của người chơi mục tiêu <Highlight>thấp hơn một mức nhất định</>, có thể bắt đầu An Hồn.\n\n<Highlight>Tỷ lệ Trị Liệu thành công</> của An Hồn phụ thuộc hai yếu tố: <Highlight>cấp Hội</> của người An Hồn và <Highlight>Lý Trí hiện tại</> của người được An Hồn. Cấp Hội càng cao, Lý Trí đối phương càng cao, xác suất thành công càng lớn.\n\nCần lưu ý, An Hồn không phải không có rủi ro — <Highlight>nếu An Hồn thất bại</>, Lý Trí của cả hai bên đều có xác suất dao động và bị hao hụt.",
    [1240251532210433] = "Dùng kỹ năng “Ngắm Bắn” để chuyển trạng thái bắn; bắn trúng Đuốc có thể tác động đến cơ quan gần đó.",
    [1240251532210689] = "Giữa các Nhân Mạch còn tồn tại những <Highlight>mối quan hệ</> đặc biệt. Thu thập đủ Nhân Mạch tương ứng để mở khóa/nâng cấp quan hệ, tăng mức Nghiên Cứu Lịch Sử.\nDựa trên mức Nghiên Cứu Lịch Sử, nhận một lượng cộng thuộc tính nhất định.\nQuan hệ chia thành hai loại: <Highlight>Quan Hệ Hiệp Chiến</> và <Highlight>Quan Hệ Lịch Sử</>; cả hai đều tăng Nghiên Cứu Lịch Sử.\nVới Quan Hệ Hiệp Chiến, sau khi mở khóa còn có thể tăng năng lực cho một số Nhân Mạch; tuy nhiên mỗi Nhân Mạch chỉ có thể nhận hiệu quả tăng từ một Quan Hệ Hiệp Chiến.\n\nTrong Server Chiến Lược, khi Quan Hệ Hiệp Chiến đạt tầng 【Bản Tướng】, có thể kết nối sức mạnh của nhánh dòng Vận Mệnh. Dùng <Highlight>Kết Tinh Nhánh Dòng</> để <Highlight>Khơi Mở</>, tăng Khắc Độ Nhánh Dòng, từ đó nhận Dư Hưởng Vận Mệnh và tăng Âm Giai Dư Hưởng, giúp nhận thêm cộng thuộc tính trong Server Chiến Lược. (Thuộc tính này chỉ có hiệu lực tại Server Chiến Lược)",
    [1240251532211201] = "<Highlight>【Ta Đến, Ta Thấy, Ta Chinh Phục】</> là sự kiện Kết Giao Nhân Mạch giới hạn thời gian.\nTrong sự kiện, xác suất Kết Giao <Highlight>Roselle Gustav</> tăng mạnh. Khi nhận Nhân Mạch Truyền Thuyết, có 80% xác suất là Roselle Gustav. Nếu Nhân Mạch Truyền Thuyết lần này không phải Roselle Gustav, lần nhận Truyền Thuyết kế tiếp chắc chắn là Roselle Gustav.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Thông Tin Xác Suất</>\n<Highlight>[Truyền Thuyết]</> Nhân Mạch: xác suất cơ bản 1.5%, xác suất tổng hợp (gồm bảo hiểm) 3.74%\nBao gồm: Roselle Gustav, Azik Eggers, Klein Moretti, Audrey Hall, Leonard Mitchell, Fors Wall, Dunn Smith, Daly Simone, Alger Wilson\n\n<Highlight>[Sử Thi]</> Nhân Mạch: xác suất cơ bản 10%, xác suất tổng hợp (gồm bảo hiểm) 22.56%\nBao gồm: Susie, Lovia Tiffany, Old Neil, Frye, Frank Lee, Benson Moretti, Melissa Moretti\n\n<Highlight>[Vật Phẩm Thường]</> liên quan: xác suất cơ bản 88.5%, xác suất tổng hợp (gồm bảo hiểm) 73.70%\nBao gồm: Vật Chất Cơ Bản, Nhân Tố Tụ Hợp\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Chi Tiết Kết Giao</>\n1. Mỗi 5 lần Kết Giao chắc chắn nhận một Nhân Mạch Sử Thi trở lên.\n\n2. Nếu 24 lần Kết Giao liên tiếp không nhận Nhân Mạch Truyền Thuyết, xác suất sau đó tăng dần.\nMỗi 40 lần Kết Giao chắc chắn nhận Nhân Mạch Truyền Thuyết.\nNhận Nhân Mạch Truyền Thuyết sẽ reset bộ đếm và đưa xác suất về mức cơ bản.\n\n3. Số lần bảo hiểm của 【Ta Đến, Ta Thấy, Ta Chinh Phục】 luôn được tích lũy trong sự kiện Kết Giao giới hạn thời gian, tính độc lập với sự kiện Kết Giao thường trực và không ảnh hưởng lẫn nhau.\n\n4. Mỗi ngày sự kiện Kết Giao giới hạn thời gian nhận 100 lượt Kết Giao, tích lũy tối đa 700 lượt.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nhận Trùng Nhân Mạch</>\nNhận trùng cùng Nhân Mạch Truyền Thuyết sẽ chuyển thành 1 nguyên liệu nâng cấp Nhân Mạch tương ứng và 10 Mảnh Phim. Nếu Nhân Mạch đó đã đạt cực hạn hoặc nguyên liệu đủ để lên cực hạn, nguyên liệu nâng cấp dư sẽ chuyển thành 40 Mảnh Phim.\nNhận trùng cùng Nhân Mạch Sử Thi sẽ chuyển thành 1 nguyên liệu nâng cấp Nhân Mạch tương ứng và 2 Mảnh Phim. Nếu Nhân Mạch đó đã đạt cực hạn hoặc nguyên liệu đủ để lên cực hạn, nguyên liệu nâng cấp dư sẽ chuyển thành 2 Mảnh Phim.\nMảnh Phim có thể dùng đổi vật phẩm tại Cửa Hàng Nhân Mạch.",
    [1240251532211457] = "<Highlight>Hình Chiếu Lịch Sử của chiến trường cổ từ Kỷ Đệ Tứ</>, chia thành hai chiến trường lớn: <Highlight>Chiến Thành</> và <Highlight>Chiến Cao Nguyên</>. Dù Chiến Tranh Bốn Hoàng Đế Kỷ Đệ Tứ đã chìm vào lịch sử, năng lượng khổng lồ vẫn lưu lại trên chiến trường cổ; vào thời điểm nhất định, toàn chiến trường sẽ tạm thời được hoạt hóa.\n\n<Highlight>Tư Cách Chiến Trường</> được phân phối lúc <Highlight>21:20 sau trận đầu mỗi vòng Giải Tứ Phương kết thúc</>. Hệ thống dựa trên tổng thực lực CLB để phân CLB vào Chiến Thành hoặc Chiến Cao Nguyên; hãy chú ý thư.\n\n<Highlight>Chiến Thành:</> CLB đủ tư cách vào 「Lấy Chiến Nuôi Chiến-Thế Lực-Chiến Thành」 để xem phân phe và chuẩn bị trước. Tham gia nhận đạo cụ rút Nhân Mạch/Bí Ngẫu, chia Suli và danh hiệu chiến trường.\n\n<Highlight>Chiến Cao Nguyên:</> CLB đủ tư cách cần chú ý thời gian đăng ký chiến trường và tham gia kịp lúc. Cũng nhận đạo cụ rút Nhân Mạch/Bí Ngẫu, chia Suli và danh hiệu chiến trường.\n\nQuy tắc chi tiết xem tại 「Lấy Chiến Nuôi Chiến-Thế Lực」.",
    [1240251532211969] = "· Sau khi bật công tắc này, nếu hiệu ứng kích hoạt của Vật Phong Ấn cần bấm thêm nút để thi triển thủ công, khi bật Trợ Giúp Một Nút hệ thống sẽ tự dùng hiệu ứng đó.\n· Chỉ bật công tắc này mới chỉ mở quyền tự dùng hiệu ứng kích hoạt của Vật Phong Ấn; vẫn cần bật Trợ Giúp Một Nút để có hiệu lực bình thường.",
    [1240251532212737] = "Điều kiện nhận:\nTrong Giải Tứ Phương, trực tiếp tham chiến (cần đạt thời gian tham gia yêu cầu);\nhoặc xem Chiến Bóng Ma Nhà Hát / được chọn vào đội hình thi đấu, chỉ cần thỏa một trong hai là có thể nhận thưởng.\nQuy tắc phát thưởng:\nTuần 1: Phát thưởng theo kết quả thắng/thua;\nTuần 2: Phát thưởng theo xếp hạng tổng hợp của hai vòng; hạng càng cao, thưởng càng nhiều.\n<Highlight>Quy tắc loại trừ: Thưởng xem Chiến Bóng Ma Nhà Hát và thưởng tham gia giải chỉ được chọn một, không thể nhận đồng thời</>.",
    [1240251532213761] = "<Highlight>Sản Xuất Xưởng</>\nNgười chơi có thể <Highlight>phân công nhân viên</> vào Xưởng để sản xuất sản vật.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>1. Tốc Độ Sản Xuất Của Nhân Viên</>\nPhân công <Highlight>càng nhiều nhân viên</>, tốc độ sản xuất càng nhanh; nhân viên có <Highlight>độ hiếm càng cao</>, tốc độ sản xuất càng nhanh.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>2. Tăng Tốc Độ Sản Xuất</>\n<Highlight>Nâng cấp Bí Ngẫu</> sẽ <Highlight>tăng tốc độ sản xuất</>.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>3. Giới Hạn Tốc Độ Sản Xuất</>\nMỗi Xưởng có <Highlight>giới hạn tốc độ sản xuất</>; sau khi đạt giới hạn, tiếp tục phân công nhân viên sẽ không tăng tốc độ nữa.",
    [1240251532214017] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Giới Thiệu Lối Chơi</>\nBàn Cờ Kẻ Khờ là PvP tổ đội, tối đa 8 người cùng ghép trận. Sau khi vào Bàn Cờ Kẻ Khờ, mọi Phi Phàm Giả sẽ <Highlight>chọn Quân Cờ ra trận</> và tăng sức mạnh bằng cách <Highlight>kích hoạt Liên Kết, nâng Sao Quân Cờ</>, cuối cùng đánh bại mọi đối thủ.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Điều Kiện Thắng</>\nSau khi vào trận, Phi Phàm Giả bị loại vẫn có thể ở lại <Highlight>quan sát</> người khác. Cần dùng đội hình Quân Cờ đánh bại đội hình của tất cả Phi Phàm Giả khác để chiến thắng.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy Tắc Tổ Đội</>\nKhi tổ đội nhiều người, hệ thống ghép trận theo <Highlight>Phi Phàm Giả có Bậc cao nhất trong đội</>. Nếu đội có từ 6 người trở lên, Phi Phàm Giả không nhận Điểm Thắng.",
    [1240251532215041] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy Tắc Nhận Thưởng Xã Hội:</>\nKhi vượt Phó Bản, nếu đội thỏa một trong các điều kiện sau, thành viên tương ứng có thể nhận thưởng xã hội:\nNếu trong đội có từ 3 người cùng Gia Tộc trở lên, các thành viên đội thuộc Gia Tộc đó nhận thưởng.\nNếu trong đội có từ 3 người cùng CLB trở lên, các thành viên đội thuộc CLB đó nhận thưởng.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy Tắc Tiêu Hao Lượt Thưởng:</>\nLượt thưởng xã hội chỉ bị tiêu hao khi vừa thỏa điều kiện nhận vừa vượt Phó Bản.",
    [1240251532215809] = "Phi Phàm Giả có thể mời bạn bè đạt Độ Thân Thiện <Highlight>Cấp 2 · Chạm Linh Tính</> tới Biển Hoa Hornacis-chỗ bà Summer để đăng ký Nghi Thức Thệ Ước.\nThệ Ước không giới hạn giới tính hai bên; bạn đồng giới hoặc khác giới đủ điều kiện đều có thể lập ước.\nSau khi Phi Phàm Giả tổ đội cùng bạn tới bà Summer đăng ký, hoàn thành viết lời thề, trao đổi nhận lời thề và chụp ảnh Thệ Ước, quan hệ Thệ Ước chính thức được lập. Sau đó nhận vật phẩm <Highlight>Chứng Nhận Thệ Ước</>; nhấp phải để xem lời thề đối phương viết cho mình bất cứ lúc nào.\nMỗi Phi Phàm Giả tối đa lập <Highlight>1 Thệ Ước mỗi ngày</> (bị gián đoạn giữa chừng không tính lượt).",
    [1240251532216065] = "Cùng đối tượng Thệ Ước tổ đội hoàn thành các hoạt động hằng ngày để nhận Điểm Thệ Ước và Huy Chương Đồng Hành; Điểm Thệ Ước tự động dùng để nâng Cấp Thệ Ước.\nThệ Ước có nhiều cấp; đạt cấp chỉ định có thể nhận Thưởng Cấp.\nMỗi ngày, Phi Phàm Giả tối đa nhận 600 Điểm Thệ Ước với một đối tượng; mỗi tuần tối đa 2000. Cùng đối tượng tham gia hoạt động chỉ định còn nhận thêm Huy Chương Đồng Hành.\nCùng bạn Thệ Ước vào Nhà Hát Utopia Chế Độ Đôi có thể nâng tới điểm đạt chuẩn Phó Bản, đồng thời nhận nhiều Điểm Thệ Ước và Huy Chương Đồng Hành hơn.\nHuy Chương Đồng Hành dùng để mua vật phẩm tại Cửa Hàng Đồng Hành; phần thưởng liên quan Thệ Ước yêu cầu Cấp Thệ Ước đạt mức chỉ định.\nPhi Phàm Giả có thể nhấn Đổi Bục Trưng Bày để vào chỉnh sửa trang cá nhân với đối tượng Thệ Ước: đổi động tác của nhân vật mình (không chỉnh được đối phương), đổi bục trưng bày trang đôi và đặt vật trang trí.\nCó thể tới chỗ phu nhân Summer xin đơn phương Giải Thệ Ước. Sau khi đăng ký bắt đầu thời gian bình tĩnh 24 giờ; hết thời gian có thể trả Soule để chính thức giải trừ. Trong thời gian bình tĩnh, người đăng ký có thể hủy.\nHai người cũng có thể tổ đội tới phu nhân Summer xin giải trừ song phương; sau 24 giờ bình tĩnh, trả một ít Soule để giải trừ. Trong thời gian này cả hai bên đều có thể hủy.",
    [1240251532216321] = "Phi Phàm Giả có thể mời bạn bè đạt Độ Thân Thiện <Highlight>Cấp 2 · Chạm Linh Tính</> tới Biển Hoa Hornacis-chỗ bà Summer để đăng ký Nghi Thức Thệ Ước.\nMỗi lần, Phi Phàm Giả chỉ có thể đồng thời mời tối đa một người bạn để bắt đầu quy trình Thệ Ước.",
    [1240251532216577] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Lưu Thủ Công</>\nCó thể lưu phương án cải tạo hiện tại vào bản ghi Lưu Thủ Công.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Lưu Tự Động</>\nMỗi lần cải tạo, phương án trước khi cải tạo sẽ được lưu theo quy tắc:\nNếu bản ghi Lưu Tự Động chưa đầy, phương án được lưu thẳng vào ô trống;\nNếu đã đầy và Độ Thời Thượng của phương án <Highlight>cao hơn</> mức thấp nhất trong bản ghi, phương án có Độ Thời Thượng thấp nhất sẽ tự bị thay.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Bản Ghi Tạm</> \nMỗi bản ghi lưu một bộ <Highlight>dữ liệu cải tạo</> của xe; có thể xem trước, chuyển đổi bất cứ lúc nào và tiếp tục cải tạo trên bản ghi đã chọn.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Xóa Bản Ghi</> \nSau khi <Highlight>Trang Bị Phương Án</> hoặc <Highlight>Đóng Gói Xe</>, toàn bộ bản ghi tạm của xe sẽ bị xóa.",
    [1240251532216833] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Tuyên Chiến</>\n1. Thời gian có thể tuyên chiến: <Highlight>Thứ Hai–Thứ Sáu 17:00-23:00; Thứ Bảy–Chủ Nhật 11:00-23:00</>.\n2. Khung giờ chiến đấu có thể chọn: <Highlight>Thứ Hai–Thứ Năm 12:00-14:00, 20:00-23:00; Thứ Sáu 12:00-14:00, 21:00-23:00; Thứ Bảy–Chủ Nhật 12:00-18:00, 22:00-23:00</>.\n3. Tuyên chiến tiêu hao Quỹ CLB; lượng tiêu hao phụ thuộc Cấp CLB, chênh lệch thực lực và Giá Trị Huyết Cừu.\n4. Nếu phe tuyên chiến thắng, hoàn <Highlight>30%</> Quỹ CLB; thua không hoàn. Nếu phe bị tuyên chiến thua, bị trừ quỹ theo Cấp CLB; thắng không bị trừ.\n5. Nếu liên tục tuyên chiến cùng một CLB và thắng, chi phí quỹ cho lần tuyên chiến tiếp theo sẽ tăng <Highlight>(reset 8:00 mỗi Thứ Hai)</>.\n6. Nếu liên tục bị cùng một CLB tuyên chiến và thua, chi phí quỹ của lần đối phương tuyên chiến tiếp theo sẽ giảm <Highlight>(reset 8:00 mỗi Thứ Hai)</>.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Giới Thiệu Lối Chơi</>\n1. Tuyên Chiến CLB diễn ra dưới dạng tự do chiến đấu trên bản đồ thế giới Dãy Hornacis. Sau khi bắt đầu, chỉ hai CLB tuyên chiến với nhau bước vào trạng thái đối đầu.\n2. Cắm Cờ: Phe phát động có quyền cắm cờ trước. Sau khi bất kỳ <Highlight>(Hội Trưởng, Phó Hội Trưởng, Lý Sự)</> nào cắm cờ, kỹ năng cắm cờ CLB sẽ biến mất. Sau khi cắm, CLB nhận điểm dựa theo thời gian sống sót quanh cờ.\n3. Luân Chuyển Cờ: Khi thời gian sở hữu cờ kết thúc, quyền cắm cờ chuyển sang CLB đối phương; hoặc có thể chuyển quyền bằng cách <Highlight>Cướp Cờ thành công</>.\n4. Hạ gục hoặc tham gia hạ gục đối thủ cũng nhận điểm.\n5. Toàn bộ trận tuyên chiến kéo dài <Highlight>30 phút</>. Khi kết toán, phe nhiều điểm hơn thắng; nếu bằng điểm, phe bị tuyên chiến thắng.\n6. Trong thời gian tuyên chiến, có thể dùng vật phẩm <Highlight>“Tập Kết · Tuyên Chiến CLB”</> tại Dãy Hornacis để <Highlight>phát động tập kết</>; vật phẩm có tại Đồng Hành Thương Điếm-CLB.",
    [1240251532217857] = "1. Sau khi vào khu vực, <Highlight>Hội Trưởng, Phó Hội Trưởng, Lý Sự</> của CLB nhận kỹ năng Cắm Cờ; có thể cắm cờ một lần tại bất kỳ phân tuyến và vị trí nào trên bản đồ Dãy Núi Hornacis.\n2. Sau khi bất kỳ ai cắm cờ, kỹ năng Cắm Cờ sẽ biến mất.",
    [1240251532218625] = "Khi Phi Phàm Giả mở Nghi Thức Thần Giáng tại quảng trường trước Nhà Thờ Thánh Selena ở Tingen, những Phi Phàm Giả khác có thể tới hỗ trợ.\nHỗ trợ sẽ tăng tốc tiến độ hoàn thành Nghi Thức Thần Giáng.\nPhi Phàm Giả hỗ trợ cho tới khi nghi thức thành công có thể nhận phần thưởng hỗ trợ.",
    [1240251532219137] = "<Highlight>【Giải Thích Luật】</>\n\n<Title>Thoát Khỏi Nhà Tù</>\n1. Bạn bị nhốt trong nhà tù đầy nguy hiểm; vượt qua cơ quan và tìm điểm thoát.\n2. Vượt các bạn tù khác, kiếm nhiều điểm hơn để nhận thưởng lớn.\n3. Hết 10 phút mà chưa thoát sẽ thất bại.\n<Title>Né Ánh Sáng</>\n1. Ánh đèn tuần tra liên tục quét nhà tù; bị phát hiện sẽ bị xiềng trói.\n2. Không rơi vào Ao Độc, đồng thời né đòn của Hoa Độc.\n<Title>Câu Đố Rune</>\n1. Cần phá Bình Chướng Rune để mở lối thoát; hãy tìm Rune rải trên mặt đất.\n2. Tìm đủ 16 Rune, Bình Chướng sẽ bị phá.",
    [1240251532222721] = "Dùng kỹ năng “Ngắm Súng Ngắn” để chuyển trạng thái bắn; bắn trúng Trụ Linh Tính có thể tác động đến cơ quan gần đó.",
    [1240251532223745] = "· Mở một góc nhìn khác của đôi mắt, nhìn thấy chân tướng ẩn dưới hiện thực.\n· <Yellow>Làm nổi bật</> manh mối quan trọng trong cảnh: bạn có thể thấy tàn ảnh người chết lang thang ở góc phố, bắt được ánh Linh Tính mờ từ Vật Phẩm Phi Phàm.\n· Dùng <Yellow>màu khác nhau</> để biểu thị trạng thái Khí Trường của sinh linh: Khí Trường không thể ẩn trước mắt bạn; sắc độ Thể Dĩ Thái cho biết sức khỏe và tâm trạng của họ.\n· Khi <Yellow>Thiên Phú Chạy Bàn</> tăng, có thể giải đọc thông tin sâu hơn, thậm chí nhìn thấy sự thịnh suy của Hỏa Quang Sinh Mệnh.",
    [1240251532224001] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quyền Chỉnh Sửa Sân Trưng Bày</>\n<Highlight>Thành Viên Thường:</> Chỉ chỉnh nhân vật của mình.\n<Highlight>Thủ Lĩnh:</> Có thể chỉnh nhân vật mọi thành viên, camera, cảnh, bố cảnh, hướng gió và màu sắc.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quyền Dùng Khi Chỉnh</>\n<Highlight>Khi chỉnh nhân vật:</> Chỉ dùng động tác và biểu cảm <Highlight>người được chỉnh</> đã mở khóa.\n<Highlight>Khi chỉnh cảnh/bố cảnh:</> Chỉ dùng nội dung <Highlight>người chỉnh</> đã mở khóa.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Luật Xóa Nội Dung</>\nKhi thành viên rời Gia Tộc, <Highlight>nhân vật trưng bày</>, <Highlight>cảnh</> và <Highlight>bố cảnh</> do họ chỉnh sẽ tự bị xóa khỏi sân.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Cảnh Độc Quyền Gia Tộc</>\nKhi Gia Tộc đạt <Highlight>cấp 2 và 6</>, mở quyền dùng cảnh độc quyền Sân Trưng Bày Gia Tộc. Loại cảnh này chỉ dùng tại Sân Trưng Bày Gia Tộc.",
    [1240251532224257] = "Hoàn thành Nhiệm Vụ Gia Tộc để nhận Điểm Ăn Ý, tăng Cấp Gia Tộc và nhận các buff:\n<Highlight>Tăng Buff Phó Bản:</> Cấp Gia Tộc càng cao, buff thuộc tính khi tổ đội tham gia Phó Bản càng mạnh.\n<Highlight>Mở Quyền Mua:</> Gia Tộc đạt cấp nhất định sẽ mở quyền mua vật phẩm cấp tương ứng trong Đồng Hành Thương Điếm.\n<Highlight>Quyền Dùng Cảnh:</> Khi Gia Tộc đạt <Highlight>Cấp 2, Cấp 6</>, mở quyền dùng cảnh độc quyền của quầy trưng bày tương ứng trong Khu Trưng Bày Gia Tộc.",
    [1240251532226049] = "Khi ở cảnh CLB, nhận buff 【Quang Huy Kết Xã】: khi tham gia lối chơi Giáo Đoàn (An Hồn, Mê Hoặc), kết quả tung xúc xắc +1.\nTrong 19:30~21:00 Thứ Bảy, Chủ Nhật mỗi tuần, 【Quang Huy Kết Xã】 được cường hóa: kết quả tung +3. Sau khi tham gia lối chơi Giáo Đoàn, cả hai bên nhận buff thuộc tính chiến đấu (dùng chung giới hạn với Dược Phẩm).",
    [1240251532226561] = "Các Phi Phàm Giả có thể lập đội với bạn Thệ Ước để tham gia các hoạt động sau, nhận Điểm Thệ Ước và Huy Chương Đồng Hành.\n① Lập đội tham gia <Highlight>Tranh Đoạt Thần Tọa</>.\n② Lập đội tham gia <Highlight>Khoảnh Khắc Vận Mệnh</>.\n③ Lập đội tham gia <Highlight>Tranh Phong Chúa Tể</>.\n④ Lập đội tham gia <Highlight>Phó Bản Hằng Ngày</>.\n⑤ Lập đội tham gia <Highlight>Phó Bản Đội</>.\n⑥ Lập đội tham gia <Highlight>Phó Bản Đoàn</>.\n⑦ Lập đội tham gia <Highlight>Tai Ách Thế Giới</>.\n⑧ Lập đội tham gia <Highlight>Nhà Hát Utopia Chế Độ Hai Người</>. Ở Chế Độ Hai Người, vào Phó Bản cùng bạn Thệ Ước có thể nâng Điểm Phi Phàm lên mức đạt chuẩn của Phó Bản.",
    [1240251532226817] = "1. Thuộc Tính Thám Hiểm gồm Mị Lực, Trực Giác, Võ Lực và Học Thức, tương ứng với các hành động và tình huống khác nhau. Thuộc tính có biểu tượng ngón cái là thuộc tính cần Kiểm Định trong lối chơi Giáo Đoàn này.\n2. Khi Kiểm Định, Thuộc Tính Thám Hiểm tương ứng sẽ cung cấp cộng thêm. Thuộc tính cơ bản là 10 điểm; mỗi vượt 2 điểm, kết quả Kiểm Định nhận +1.",
    [1240251532227329] = "<Title>Cự Long Xuất Hiện</>\nCự Long · Hình Chiếu xuất hiện tại <Highlight>trung tâm Vương Thành Liệp Long</> vào <Highlight>19:10</>, tức <Highlight>10 phút sau</> khi Giờ Săn Giết tối thứ Sáu bắt đầu. Nếu chưa bị đánh lui trước 20:00, Cự Long sẽ rời đi và không kích hoạt kết toán hạ gục.\n\n<Title>Sát Thương Quyền Sở Hữu</>\nChỉ khi còn sống trong phạm vi <Highlight>40m</> quanh Cự Long và gây sát thương cho nó, sát thương mới được tính vào đội hiện tại. Khi Cự Long bị đánh lui, <Highlight>đội có Sát Thương Quyền Sở Hữu hiệu lực cao nhất</> nhận quyền sở hữu cuối và thưởng đấu giá. Khi tới gần Cự Long có thể xem sát thương quyền sở hữu hiện tại theo thời gian thực.\n\n<Title>Suy Giảm Sát Thương</>\nKhi người chơi chết, rời phạm vi thảo phạt Cự Long, đổi Phân Tuyến hoặc rời đội, Sát Thương Quyền Sở Hữu đã tích cho đội sẽ bắt đầu suy giảm và đồng thời ảnh hưởng tổng sát thương quyền sở hữu hiệu lực của đội.\n\nTrong <Highlight>5 giây đầu</> sau khi kích hoạt suy giảm, sát thương không đổi; từ giây thứ 6, <Highlight>mỗi 6 giây giảm 5% tổng Sát Thương Quyền Sở Hữu gốc</>, về 0 sau 120 giây.\n\nKhi quay lại <Highlight>phạm vi thảo phạt Cự Long</> và tái tham chiến, suy giảm dừng; lượng còn lại được giữ và tiếp tục cộng sát thương mới.\n\n<Title>Thưởng Đấu Giá</>\nSau khi đánh lui Cự Long, mở cấp đấu giá tương ứng theo Điểm Kịch Chiến. <Highlight>Điểm Kịch Chiến càng cao, cấp thưởng đấu giá mở được càng cao</>.\n\n<Title>Giới Hạn Tư Cách</>\nTrong mỗi sự kiện Giờ Săn Giết, mỗi người chơi tối đa nhận <Highlight>1 lần</> tư cách đấu giá Chung Kết Săn Giết Cự Long · Hình Chiếu; đã nhận thì không thể nhận lại trong sự kiện đó.",
    [1240251532227841] = "Bấm mở <Highlight>Linh Thị</> để xem trạng thái Lý Trí của người chơi xung quanh; người chơi và NPC ở mức Lý Trí khác nhau sẽ hiển thị màu khác nhau.",
    [1240251532230401] = "Mỗi ngoại hình có Điểm Phong Cách cơ bản. Người chơi tiêu hao nguyên liệu nhuộm, nhuộm và lưu phương án để nhận thêm Điểm Phong Cách: mỗi <Highlight>1</> Thuốc Nhuộm San Hô = <Highlight>10</> điểm, mỗi <Highlight>1</> Thuốc Nhuộm Hồng Quang = <Highlight>40</> điểm, mỗi <Highlight>1</> Thuốc Nhuộm Bọt = <Highlight>20</> điểm, mỗi Thẻ Thần Quyến = <Highlight>4000</> điểm. Hệ thống chọn <Highlight>3</> phương án đã lưu có Điểm Phong Cách cộng thêm cao nhất, cộng vào Điểm Phong Cách cơ bản để tính Điểm Phong Cách cuối của ngoại hình.\n\nVí dụ:\nMột ngoại hình có Điểm Phong Cách cơ bản <Highlight>800</>. Người chơi lưu <Highlight>4</> phương án nhuộm, cho lần lượt <Highlight>150、280、420、360</> điểm.\nHệ thống từ <Highlight>4</> phương án chọn <Highlight>3</> phương án cao nhất (420, 360, 280); phương án còn lại không tính.\nVậy tổng cộng thêm từ nhuộm là 420 + 360 + 280 = 1060; Điểm Phong Cách cuối = 800 + 1060 = 1860.\n\nBổ sung:\n1. Khi thêm hoặc sửa phương án nhuộm, hệ thống tự chọn <Highlight> 3 </> phương án cao nhất để tính và cập nhật Điểm Phong Cách.\n2. Xóa phương án nhuộm sẽ đồng thời loại khỏi hàng tính; nếu phương án đó đang được tính, phương án cao tiếp theo sẽ thế chỗ.\n3. Nếu chưa lưu phương án nhuộm nào, ngoại hình chỉ hiển thị Điểm Phong Cách cơ bản.",
    [1240251532230913] = "<Highlight>Chia Sẻ Số Lần Mở Bí Bảo:</> Bí Bảo Phiêu Lưu Thế Giới, Bí Bảo Lấy Chiến Nuôi Chiến và Rương Quà Xã Hội dùng chung số lần mở.\n<Highlight>Tích Lũy Số Lần:</> Từ đầu thứ Hai, mỗi ngày cộng và tích lũy số lần mở chung, đặt lại vào thứ Hai tuần sau:\n1. Thứ Hai–thứ Sáu mỗi ngày cộng <Highlight>10</> lần;\n2. Từ tuần thứ hai sau mở server, thứ Bảy–Chủ Nhật không giới hạn;\n3. Tuần đầu mở server, thứ Sáu–Chủ Nhật vẫn mỗi ngày cộng <Highlight>10</> lần.\n4. Bí Bảo đã nhận nhưng chưa mở có thể tự vứt sau khi mở khóa Bí Bảo mới.\n\n<Highlight>Tiêu Hao Hoạt Lực:</> Hoạt Lực tiêu hao cho số lần mở chung tăng theo số lần Phi Phàm Giả đã mở:\n1–5: <Highlight>20</> Hoạt Lực;\n6–10: <Highlight>50</>;\n11–20: <Highlight>100</>;\n21–30: <Highlight>150</>;\nSau 30 lần: <Highlight>200</>.",
    [1240251532231425] = "Trong giao diện xem Mảnh Ký Ức, chọn mảnh chỉ định để <Highlight>Hồi Tưởng Ký Ức</>; có thể đặt Mảnh Ký Ức xuống đất và mọi người trong Phó Bản đều có thể nhặt.",
    [1240251532233473] = "1. Mỗi tuần, mỗi Phó Bản có một số <Highlight>lượt Thưởng Thảo Phạt</>. Khi người chơi hạ Boss Phó Bản, <Highlight>Tiến Độ Thưởng Thảo Phạt</> tăng.\n2. Khi Tiến Độ Thưởng Thảo Phạt <Highlight>đầy</>, có thể nhận 1 Trang Bị Khắc Ấn hoặc Ngoại Hình <Highlight>chưa sở hữu</> của Phó Bản hiện tại.\n3. Sau khi nhận, tiến độ tương ứng sẽ trừ số lượt cần để lĩnh thưởng.\n4. Quy tắc tăng lượt Thưởng Thảo Phạt Trang Bị Khắc Ấn: các Phó Bản dùng chung lượt sẽ chia sẻ lượt Thảo Phạt; mỗi Boss mỗi tuần tăng 1 lượt.\n5. Quy tắc tăng lượt Thưởng Thảo Phạt Ngoại Hình: mỗi Phó Bản, mỗi Boss mỗi tuần tăng 2 lượt; độ khó Thường và Khó dùng chung lượt.",
    [1240251532234241] = "<Highlight>Nhấn giữ nút Nhảy</> để vào trạng thái Nhảy Linh Tính.\nTrong trạng thái này có thể tiêu hao Thể Lực để tiếp tục nhảy lên hoặc lướt, nhanh chóng tới chỗ cao tìm mục tiêu.",
    [1240251532234497] = "· Mỗi ngày Phi Phàm Giả nhận 5 lượt Thư Mời dùng chung cho toàn bộ Nhân Mạch, tích lũy tối đa 15 lượt (chia sẻ giữa mọi nhân vật Nhân Mạch), nhưng cần mở khóa 【Phúc Âm Kẻ Khờ】 mới có thể dùng số lượt này.\n· Khi tương tác nhanh với nhân vật Nhân Mạch, ưu tiên tiêu hao lượt Thư Mời của chính Nhân Mạch đó, sau đó mới dùng lượt chung.",
    [1240251800487680] = "Kỹ Năng Nhân Mạch",
    [1240251800494592] = "Cộng Hưởng",
    [1240252337358593] = "Thông qua Vật Phong Ấn “Hành Lang Lịch Sử” tương ứng Bậc 3 “Học Giả Cổ Đại” của Con Đường “Kẻ Khờ”, tiến vào khe hở lịch sử, tìm hình chiếu nhân vật từng tồn tại trong lịch sử, kết giao với họ và mượn sức mạnh từ quá khứ. Tối đa trang bị 1 Kỹ Năng Nhân Mạch.",
    [1240252337359617] = "Có thể bất cứ lúc nào <Highlight>hoán đổi</> các từ đã ghi trong Không Gian Linh Chất Cố Định với từ Linh Chất Cố Định trên trang bị đang mặc; thao tác này <Highlight>không tốn gì</>.\nTừ Linh Chất Cố Định trên trang bị có <Highlight>loại duy nhất</>, tức không thể đồng thời có 2 từ trở lên cùng loại thuộc tính.\nKhi phẩm cấp trang bị quá thấp, giá trị thuộc tính Linh Chất Cố Định có thể <Highlight>không phát huy toàn bộ (không ảnh hưởng giá trị đã ghi trong không gian)</>.",
    [1240252337364737] = "Tấn Công <Tips_TWhite>%s</>\nHP <Tips_TWhite>%s</>\nVật Phòng<Tips_TWhite>%s</>\nMa Phòng<Tips_TWhite>%s</>\n",
    [1240252337364993] = "Nhận Vật Phong Ấn có năng lực Phi Phàm từ Hình Chiếu Lịch Sử; mang theo sẽ cung cấp đặc tính mạnh trong chiến đấu nhưng cũng phải chịu lời nguyền tương ứng. Ngoài ra, Vật Phong Ấn có thể được cải tạo để cung cấp thêm thuộc tính Lĩnh Vực.",
    [1240252337365249] = "Mỗi Bậc đồng thời chỉ có đúng 2 loại Lĩnh Vực có thể tự do chuyển đổi. Khi kích hoạt các Lĩnh Vực khác nhau, hiệu ứng riêng của Lĩnh Vực cũng khác nhau; sau khi chuyển Lĩnh Vực, loại sát thương của toàn bộ kỹ năng sẽ đồng nhất với loại Lĩnh Vực. Khi chiến đấu với quái vật Phi Phàm, sát thương người chơi gây ra được kết toán dựa trên kháng tính của quái vật đối với từng loại Lĩnh Vực.",
    [1240252337365505] = "Vật Phong Ấn lưu lại một lượng Khí Tức Phi Phàm. Có thể dùng Cộng Hưởng để nâng cấp các khí tức này, cuối cùng khuếch đại cường độ khí tức gốc theo tỷ lệ. Các Khí Tức Phi Phàm gây nhiễu lẫn nhau; khi cấp một khí tức cao hơn khí tức thấp nhất quá một mức nhất định, khí tức cấp cao sẽ bị ảnh hưởng và suy giảm. Số lượng khí tức do Cấp Nguy Hiểm quyết định: Vật Phong Ấn Cấp Nguy Hiểm 1 có 4 Khí Tức Phi Phàm; mỗi khi Cấp Nguy Hiểm thay đổi 1 cấp, giới hạn khí tức giảm 1.",
    [1240252337369089] = "Bôi Thánh Cao lên Trang Bị để <Highlight>thay một Dòng Ngẫu Nhiên đã chọn bằng một Dòng Ngẫu Nhiên được ghi trên Thánh Cao</>; thao tác này <Highlight>không thể hoàn tác</>.\nMỗi Trang Bị <Highlight>chỉ có thể có 1 dòng</> đã được bôi; dòng này có thể bôi lại nhiều lần nhưng <Highlight>không chịu ảnh hưởng của Tái Tạo</>.",
    [1240252337372161] = "Tăng Cấp Nhân Vật, Bồi Dưỡng Trang Bị, Bồi Dưỡng Vật Phong Ấn, Bồi Dưỡng Bí Ngẫu, dùng Dược Phẩm, v.v.",
    [1240252337372673] = "Trang Bị và Vật Phong Ấn nhất định.",
    [1240252337376513] = "Phát triển Trang Bị, phát triển Vật Phong Ấn, Kết Giao Nhân Mạch, mở Thiên Phú, dùng Dược Phẩm...",
    [1240252337377537] = "Cường Hóa Trang Bị, Cường Hóa Vật Phong Ấn, v.v.",
    [1240252337377793] = "Phát triển Trang Bị, Kết Giao Nhân Mạch, mở Thiên Phú...",
    [1240252337382657] = "Bồi Dưỡng Trang Bị, Bồi Dưỡng Vật Phong Ấn, Bồi Dưỡng Bí Ngẫu, v.v.",
    [1240252337390337] = "Phát triển Trang Bị, phát triển Vật Phong Ấn, mở Thiên Phú...",
    [1240252337411585] = "Dùng để nâng kỹ năng, bồi dưỡng Vật Phong Ấn, v.v.",
    [1240252337430017] = "1. Quy tắc khóa thành viên CLB: Trong các hoạt động lấy CLB làm đơn vị (như Giải Tứ Phương, Chiến Bóng Ma Nhà Hát, Chiến Thành, Chiến Cao Nguyên), CLB không cho phép thành viên gia nhập hoặc rời đi.\n2. Giới hạn số người theo Con Đường trong hoạt động CLB: Một số hoạt động CLB giới hạn số người tham gia theo Con Đường; xem mô tả hoạt động CLB để biết chi tiết.",
    [1240252337430529] = "Làm mới lúc 5:00 sáng thứ Hai hằng tuần. Thành viên hoàn thành mục tiêu cá nhân và CLB hoàn thành mục tiêu CLB đều tích Huy Chương cho CLB; tích đủ số lượng nhất định sẽ mở phần thưởng giai đoạn.",
    [1240252337445889] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Lịch Thi Đấu</>\n<Highlight>Giải Tứ Phương đầu tiên</> sẽ chia Khu/nhóm vào <Highlight>12:00 Chủ Nhật tuần đầu mở server</> dựa trên đánh giá tổng hợp CLB, công bố lúc <Highlight>18:00 cùng ngày</>. Giải tính <Highlight>mỗi hai trận là một vòng</>, mỗi vòng kéo dài <Highlight>hai tuần</>. Vòng đầu đặc biệt mở lúc <Highlight>20:00 Chủ Nhật tuần đầu</>; sau đó Giải Tứ Phương mở <Highlight>20:00 thứ Bảy</> hằng tuần.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Thể Thức</>\nMỗi vòng gồm hai trận. Trước trận đầu, hạng 1–2, 3–4, 5–6, 7–8 của nhóm lần lượt vào các bảng khác nhau và được <Highlight>chia ngẫu nhiên</> trong điều kiện đó. Sau trận đầu, <Highlight>Top 2 mỗi bảng vào Nhánh Thắng</>, hai đội sau vào Nhánh Thua. Trận hai thi đấu theo Nhánh Thắng/Nhánh Thua, xác định <Highlight>hạng 1–8</> của vòng.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Thăng/Hạ Hạng</>\nSau trận hai, 21:20 thứ Bảy sẽ thăng/hạ hạng: ở <Highlight>Nhóm Thánh Danh trở lên</>, Top 2 lên một nhóm, Bottom 2 xuống một nhóm; ở <Highlight>Nhóm Anh Kiệt trở xuống</>, hạng 1 lên hai nhóm, hạng 2 lên một, hạng 7 xuống một, hạng 8 xuống hai. <Highlight>Nhóm Truyền Kỳ, Sử Thi, Lữ Giả</> có luật riêng: Truyền Kỳ hạng 1–2 lên một, hạng 6–7 xuống một, hạng 8 xuống hai; Sử Thi hạng 1–2 lên một, hạng 7 xuống một, hạng 8 xuống hai; Lữ Giả hạng 1 lên hai, hạng 2 lên một, hạng 7–8 xuống hai; Khiêu Chiến Giả hạng 1 lên hai, hạng 2–3 lên một.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Luật Nhóm Liên Minh</>\nCác CLB sau Nhóm Lữ Giả được chia theo <Highlight>tổng Điểm Phi Phàm CLB</> vào <Highlight>Nhóm Khiêu Chiến Giả</> (Top 8) và các <Highlight>Nhóm Liên Minh</> sau đó (<Highlight>Nhóm Liên Minh không thăng/hạ hạng</>). Trước mỗi trận, CLB Nhóm Liên Minh <Highlight>tự ghép</> với CLB khác thành liên minh; <Highlight>mọi thành viên CLB</> trong liên minh đều có thể vào trận, và <Highlight>Hội Trưởng CLB xếp hạng cao nhất</> trong liên minh tự nhận <Highlight>Quyền Chỉ Huy Giải Đấu</>.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Reset Mùa</>\nMỗi mùa mới, giải đấu sẽ <Highlight>chia lại Khu</>, ghép đối thủ mới dựa trên <Highlight>thành tích mùa trước</>.\n",
    [1240252337449217] = "1. <Highlight>Buff Thuộc Tính Gia Tộc:</> Trong Phó Bản, lập đội với đủ số thành viên cùng Gia Tộc sẽ nhận thêm <Highlight>số lần hồi sinh</> và <Highlight>bù thuộc tính</>. Sau khi rời Gia Tộc có <Highlight>24 giờ</> hồi chờ hiệu lực.\n2. <Highlight>Danh Hiệu Gia Tộc:</> Gia nhập Gia Tộc tự động nhận <Highlight>Danh Hiệu Gia Tộc</>. Thủ Lĩnh có thể đổi tên Gia Tộc trong Chi Tiết Gia Tộc; đổi tên có hồi chiêu <Highlight>30 ngày</>, sau khi đổi thành công Danh Hiệu Gia Tộc cũng đổi theo.",
    [1240252337457921] = "1. Tại <Highlight>Chợ</> hoặc <Highlight>giao diện Sản Xuất Xưởng</>, có thể xem giá bán và hệ số của từng sản vật.\n2. Ưu tiên tìm và chế tạo <Highlight>sản vật hệ số cao</> để tăng mạnh tốc độ nhận Tài Sản Lâu Đài.\n3. Sản vật chế tạo bán tại Lâu Đài của mình không giới hạn số lượng; bán tại Lâu Đài bạn bè/người lạ có giới hạn.",
    [1240252337481985] = "CLB được phân bổ dựa trên số Phi Phàm Giả, độ hoạt động và Điểm Phi Phàm đạt yêu cầu. Phi Phàm Giả thuộc CLB đủ tư cách có thể xem lịch đấu tại Lấy Chiến Nuôi Chiến - Thế Lực - Chiến Thành.\nMỗi Con Đường trong cùng một CLB tối đa <Highlight>16 người</> ra trận; hãy bố trí đội hình hợp lý.\nKhi chiến dịch kết thúc, phần thưởng được chia theo xếp hạng Tiến Độ Chiếm Vương Thành; nếu tiến độ bằng nhau sẽ xếp theo Điểm Thế Lực. <Highlight>Chiếm Vương Thành trung tâm</> sẽ lập tức kết thúc chiến trường và nhận phần thưởng người thắng cuối cùng.",
    [1240252337482241] = "Để chiến thắng, các thế lực cần tranh giành <Highlight>Kỵ Sĩ Tử Vong</> trên đài trung tâm. Khi trận kết thúc, phần thưởng chia theo xếp hạng Điểm Thế Lực của Tứ Hoàng. Dẫn <Highlight>Kỵ Sĩ Tử Vong</> nhiều lần về <Highlight>Quảng Trường</> phe mình sẽ nhận lượng lớn Điểm Thế Lực, có thể kết thúc chiến trường sớm và nhận thưởng Toàn Thắng.\nHệ thống phân bổ theo CLB, sàng lọc CLB đạt yêu cầu về số Phi Phàm Giả, độ hoạt động và Điểm Phi Phàm. Thành viên CLB đủ tư cách có thể xem lịch đấu tại Lấy Chiến Nuôi Chiến - Thế Lực - Chiến Cao Nguyên.",
    [1240252337484545] = "Chọn Phong Cách — mỗi phong cách tạo cụm kiến trúc có hình dáng, chiều cao và ngoại quan hoàn toàn khác nhau.\n\nCách Mở Phong Cách — sau khi <Highlight>mở toàn bộ nội thất thuộc phong cách</>, phong cách đó tự động được mở.\n\nPhong Cách Tùy Chỉnh — chọn Tùy Chỉnh để tự thiết kế hình thức kiến trúc mong muốn.\n",
    [1240252337505025] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Lý Trí</>\nKhi hoạt động trong thế giới Phi Phàm, nhiều sự kiện sẽ khiến Lý Trí dao động. Khi Lý Trí liên tục giảm, trạng thái dị thường bắt đầu từ thể xác rồi dần xâm thực Thể Dĩ Thái, Thể Tâm Trí, Thể Tinh Linh và Thể Tinh Thần; nhân vật lần lượt vào các mức trạng thái tinh thần khác nhau và chịu hiệu ứng tương ứng.\n\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>An Hồn</>\nNgười chơi gia nhập Hội Requiem có thể An Hồn cho người chơi khác để <Highlight>hồi</> Lý Trí của họ.\n\nSau khi mở Linh Thị, nhấn người chơi khác để xem trạng thái Lý Trí. Khi Lý Trí mục tiêu <Highlight>thấp hơn một mức nhất định</>, có thể bắt đầu An Hồn.\n<Highlight>Tỷ lệ Trị Liệu thành công</> của An Hồn phụ thuộc hai yếu tố: <Highlight>cấp Hội</> của người An Hồn và <Highlight>Lý Trí hiện tại</> của người được An Hồn. Cấp Hội càng cao, Lý Trí đối phương càng cao, xác suất thành công càng lớn.\nCần lưu ý, An Hồn không phải không có rủi ro — <Highlight>nếu An Hồn thất bại</>, Lý Trí của cả hai bên đều có xác suất dao động và bị hao hụt.",
    [1240252337507329] = "Đánh bại Sinh Vật Phi Phàm được triệu hồi, đoạt <Highlight>Nguyên Liệu Di Vật Đỏ Thẫm</> chúng để lại — đây là tài nguyên duy nhất để tăng <Highlight>Tiến Độ Săn Giết</>.",
    [1240252337511681] = "Khi mở đăng ký, lối chơi sẽ ngẫu nhiên chọn <Highlight>16</> người chơi từ thành viên CLB làm <Highlight>Hình Chiếu Ảo Tượng</> cho người tham gia sử dụng. Tất cả người tham gia có <Highlight>cùng loại</> hình chiếu.\nTrận đấu chia nhiều vòng; người chơi có thể chọn hình chiếu đưa vào <Highlight>bất kỳ vòng nào</>, hình chiếu đã dùng không thể <Highlight>dùng lại</>.\nKhi vòng chỉ định bắt đầu, hình chiếu của vòng đó sẽ được triệu hồi và <Highlight>tự động chiến đấu</>; người tham gia có thể tới Trụ Sở CLB để <Highlight>quan chiến</>.",
    [1240252337524225] = "1. Sau khi cắm cờ, tiến độ phe ta bắt đầu đầy; thành viên phe ta đứng trong <Highlight>phạm vi cờ</> liên tục nhận điểm theo thời gian sống sót.\n2. Ngoài ra, <Highlight>hạ gục hoặc hỗ trợ hạ Phi Phàm Giả</> cũng nhận điểm.\n3. Khi hết thời gian tuyên chiến, <Highlight>phe nhiều điểm hơn thắng</>. Nếu bằng điểm, <Highlight>phe bị tuyên chiến</> thắng. Khi chênh lệch điểm vượt 5000, phe nhiều điểm hơn thắng ngay.\n4. Khi địch vào phạm vi cờ và <Highlight>số địch nhiều hơn phe ta</>, thanh tiến độ sẽ dần chuyển sang tiến độ phe địch.",
    [1240252337533441] = "Quy tắc Mê Hoặc:\n1. Thành viên Vũ Hội Đêm Xuân có thể gửi lời mời Mê Hoặc tới Phi Phàm Giả khác. Khi đối phương chấp nhận, hai bên vào Đối Đấu Mê Hoặc; không thao tác trong thời hạn hoặc ở quá xa sẽ tính là từ chối.\n2. Sau khi vào Đối Đấu Mê Hoặc, hai bên chọn Ngoại Trang để phối; thắng thua do Điểm cuối quyết định.\n2.1 Điểm đối đấu chịu ảnh hưởng của Giá Trị Thời Thượng Ngoại Trang và phong cách chủ đề. Chủ đề do hệ thống chỉ định và thay định kỳ; hãy chọn Ngoại Trang phù hợp chủ đề.\n2.2 Sau khi chốt phối đồ sẽ vào bước tung xúc xắc. Mị Lực đối phương càng cao, số cần đạt để kiểm định càng cao; Mị Lực bản thân cộng thêm vào kết quả. Tung thành công tăng thêm 5% Điểm đối đấu cuối.\n2.3 Nếu Điểm cuối bằng nhau, người phát động Mê Hoặc bị tính là thua (không Mê Hoặc thành công đối thủ).\n3. Sau Đối Đấu Mê Hoặc, bên thua nhận Danh Hiệu kéo dài 15 phút, cho biết vừa bị Mị Lực của Phi Phàm Giả chỉ định chinh phục.\n4. Thành viên Vũ Hội Đêm Xuân mỗi ngày tối đa 20 lần Mê Hoặc (không vào quy trình đối đấu thì không tính lượt); hoàn thành Mê Hoặc nhận thưởng.\n5. Thua Đối Đấu Mê Hoặc có thể giảm SAN; khi SAN quá thấp có thể tìm thành viên Thi Xã An Hồn để An Hồn.",
    [1240252337535233] = "Nhấn <Highlight>CLB</> trong menu chính để gia nhập và vào cảnh CLB. Dùng trực tiếp vật phẩm <Highlight>Vật Dị Tượng</> trong túi cũng có thể theo chỉ dẫn Linh Tính để tự tìm đường tới vị trí Leonard.",
    [1240252605794048] = "Kỹ Năng Bí Ngẫu",
    [1240253142664961] = "Dùng Vật Phong Ấn “Nhà Hát Utopia” do Ngài “Kẻ Khờ” ban tặng để mời Bí Ngẫu từ thị trấn Bí Ngẫu nằm trong Sương Mù Lịch Sử lên diễn và sử dụng sức mạnh của họ. Tối đa lắp 1 kỹ năng Bí Ngẫu.",
    [1240253142670081] = "Trong giao diện phát triển Đồng Hành, dùng nguyên liệu Đột Phá để tăng Bậc Đồng Hành. Sau Đột Phá, thuộc tính kỹ năng tương ứng của Đồng Hành cũng tăng.",
    [1240253142752257] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Phe và Luật Cơ Bản</>\n<Highlight>4 CLB</> cùng tranh tài; mỗi CLB có thể đưa <Highlight>60 thành viên chính thức</> ra trận, tổng cộng 240 người mỗi trận. Mỗi Hệ của cùng một CLB tối đa <Highlight>16 người</>, hãy bố trí đội hình hợp lý. Mỗi trận kéo dài <Highlight>23 phút</>.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Luật Thắng Thua</>\nCLB <Highlight>đạt 3000 điểm đầu tiên</> lập tức thắng. Nếu hết trận chưa ai đạt 3000, xếp hạng theo điểm hiện tại. Nếu bằng điểm, lần lượt so <Highlight>Tổng Hạ Gục</> và <Highlight>Tổng Điểm Phi Phàm của CLB</>.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nhận Điểm Trong Trận</>\nNguồn điểm duy nhất là <Highlight>chiếm Thủ Vệ và kết toán quyền sở hữu Thủ Vệ</>: lần đầu chiếm một Thủ Vệ nhận <Highlight>50 điểm</>; cứ 5 giây kết toán nhỏ, mỗi Thủ Vệ đã chiếm cho <Highlight>1 điểm</>; cứ 30 giây kết toán lớn, mỗi Thủ Vệ đã chiếm cho <Highlight>18 điểm</>. <Highlight>Kết toán điểm hệ số cao theo quyền sở hữu Thủ Vệ</> xuất hiện ngẫu nhiên ở phút 4, 8, 12, 16, 20 và báo trước 90 giây. Trong thời gian này, mỗi Thủ Vệ đã chiếm cho <Highlight>72 hoặc 108 điểm</> ở kỳ kết toán lớn, tương ứng x4 hoặc x6; hệ số cụ thể tùy vị trí Thủ Vệ được chọn.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Tranh Đoạt Thủ Vệ</>\nBản đồ có <Highlight>5 Thủ Vệ</>. CLB tung đòn kết liễu lên Thủ Vệ sẽ giành quyền kiểm soát. Sau khi chiếm, Thủ Vệ lập tức hồi sinh và thuộc phe đó. Thủ Vệ <Highlight>không thể được Trị Liệu</>, nhưng khi xung quanh không có địch sẽ từ từ tự hồi Sinh Mệnh.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Tài Nguyên và Quyền Chỉ Huy</>\n<Highlight>Hạ gục người chơi địch</> hoặc <Highlight>chiếm Thủ Vệ</> đều cho Điểm Tài Nguyên và tự tích lũy <Highlight>Cấp Sĩ Khí</>. <Highlight>Hội Trưởng, Phó Hội Trưởng, Lý Sự</> có thể tiêu hao Điểm Tài Nguyên để dùng Kỹ Năng Chỉ Huy.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Kỹ Năng Chỉ Huy</>\n<Highlight>Tuyên Ngôn Khắc Địch</>: tốn 1000 Điểm Tài Nguyên, tăng 15% Áp Chế Toàn Hệ cho toàn bộ thành viên phe mình trong 20 giây. Hồi chiêu 180 giây. <Highlight>Tiến Quân Thần Tốc</>: tốn 600, tăng 60% Tốc Độ Di Chuyển cho toàn bộ phe mình trong 10 giây. Hồi chiêu 120 giây. <Highlight>Sắc Lệnh Quy Linh</>: tốn 1500, lập tức xóa thời gian chờ hồi sinh hiện tại của toàn phe; thành viên phe mình tử trận trong 5 giây sau cũng có thể hồi sinh ngay. Hồi chiêu 240 giây. <Highlight>Triệu Tập Dịch Chuyển</>: tốn 2400, triệu tập toàn bộ thành viên phe mình tới điểm tập kết chỉ định. Hồi chiêu 240 giây. <Highlight>Thánh Vực Bảo Hộ</>: tốn 1000, hồi cho mọi Thủ Vệ phe mình 50% Giới Hạn Sinh Mệnh. Hồi chiêu 180 giây.\n",
    [1240253142755585] = "1. <Highlight>Độ Ăn Ý và Cấp:</> Hoàn thành nhiệm vụ tuần của Gia Tộc để nhận Độ Ăn Ý và tăng cấp Gia Tộc; giới hạn nhận mỗi tuần là <Highlight>2000 điểm</>.\n2. <Highlight>Nhiệm Vụ Tuần:</> Thành viên Gia Tộc lập đội tham gia gameplay tương ứng để nhận Độ Ăn Ý. <Highlight>một số lần</> hoàn thành đầu tiên của từng nhiệm vụ trong tuần nhận <Highlight>Độ Ăn Ý bội cao</>; vượt số lần bội cao chỉ nhận cộng thêm Độ Ăn Ý thường. Nhiệm vụ <Highlight>làm mới mỗi tuần</>.",
    [1240253142764289] = "1. Mỗi Lâu Đài có <Highlight>loại sản vật thu mua giá cao</> khác nhau theo tuần; có thể tới Lâu Đài bạn bè để bán sản vật.\n2. Kết thêm nhiều bạn giúp <Highlight>dễ tìm và bán sản vật giá cao hơn</>.\n3. Khi <Highlight>bán sản vật tại Lâu Đài</>, giá bán còn có thể <Highlight>tăng theo các cách sau</>: tăng Độ Thân Mật giữa bạn bè, tăng Tổng Điểm Lâu Đài, tăng Phong Thượng, v.v.",
    [1240253142776321] = "Mở khóa Nội Thất — 3 cách: mở sẵn, tự mở khi đạt cấp, hoặc tiêu hao Tài Sản Lâu Đài/Bảng Vàng Khóa để mở.\nĐiểm & Giá — mỗi Nội Thất có điểm khác nhau; loại cần tiêu hao tiền tệ để mở thường có điểm cao hơn.\nTrạng Thái Nội Thất — chọn Nội Thất để xem trạng thái (đỏ: không thể thu hồi; xanh: có thể xây; vàng: có thể thu hồi).",
    [1240253142788353] = "Ở giai đoạn 1 Chiến Thành, các Phi Phàm Giả cần xuất phát từ <Highlight>Pháo Đài</> phe mình, lần lượt tiến qua <Highlight>Tiền Đồn, Doanh Trại</>. Sau khi chiếm Doanh Trại có thể tấn công <Highlight>Bia Đá Chiến Tranh</> nối với nó; cần chiếm 2 Bia Đá nối với Doanh Trại phe mình mới được tấn công <Highlight>Cổng Vương Thành</>. Nếu Bia Đá phe mình bị địch chiếm, sẽ mất quyền tấn công cổng.\nỞ giai đoạn 2 Chiến Thành, sau khi phá Cổng Vương Thành có thể tới đài trung tâm để <Highlight>chiếm Vương Thành</>. Thế lực có đông người nhất trên đài sẽ tích lũy <Highlight>Điểm Chiếm Lĩnh</>; đồng thời hạ Phi Phàm Giả phe địch trên đài trung tâm cũng tăng <Highlight>Điểm Chiếm Lĩnh</> cho phe mình. Đạt 100% sẽ chiếm Vương Thành.",
    [1240253142788609] = "<Highlight>Kỵ Sĩ Tử Vong</> sẽ đi theo Thế Lực có nhiều Phi Phàm Giả nhất trong phạm vi <Highlight>20 mét</> quanh nó (cần ít nhất <Highlight>5</> người để được đi theo).\nThế Lực ở gần <Highlight>Kỵ Sĩ Tử Vong</> sẽ định kỳ nhận Điểm Thế Lực; Thế Lực được <Highlight>Kỵ Sĩ Tử Vong</> đi theo nhận nhiều điểm hơn. Đưa thành công <Highlight>Kỵ Sĩ Tử Vong</> tới Quảng Trường phe mình sẽ nhận thêm <Highlight>1200</> Điểm Thế Lực; Thế Lực đạt <Highlight>15000</> điểm sẽ thắng sớm.",
    [1240253142790913] = "Chọn Cấu Kiện — chỉ định cấu kiện yêu thích (sàn, tường...). Sau khi xác nhận, cụm công trình được tạo <Highlight>chỉ dùng cấu kiện đã chọn</>.\n\nQuy Tắc Tạo — nếu cùng một loại (sàn, tường...) chọn nhiều cấu kiện, mỗi công trình được tạo sẽ ngẫu nhiên dùng một trong số đó.\n\nXem Kết Quả — nhấn Tạo để sinh bản xem trước cụm công trình; nếu chưa hài lòng có thể nhấn Làm Mới.\n\nMẹo: muốn tạo cụm công trình lớn, hãy chia thành nhiều lần và mỗi lần khoanh một vùng nhỏ; kết quả cuối sẽ dễ kiểm soát hơn.",
    [1240253142792705] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Thời Gian Săn Giết</>\nMở <Highlight>19:00—20:00 mỗi ngày</>; Thứ Bảy và Chủ Nhật mở thêm <Highlight>14:00—15:00</>.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Sự Kiện Giới Hạn Khu Vực Vương Thành</>\nTrong Săn Giết, có thể triệu hồi giới hạn thời gian <Highlight>Nhân Ngẫu Vận Mệnh</> tại 【Doanh Trại Dị Biến】 ở trung tâm Vương Thành; đánh bại sẽ nhận nguyên liệu Di Vật Tinh Hồng.\nVào tối Thứ Sáu, sau khi Săn Giết mở <Highlight>10 phút</>, tức <Highlight>19:10</>, trung tâm Vương Thành xuất hiện <Highlight>Cự Long · Hình Chiếu</>. Khi đẩy lui Cự Long, đội có Sát Thương quy thuộc hợp lệ cao nhất nhận phần thưởng đấu giá. Trong mỗi sự kiện Săn Giết, mỗi người chơi tối đa nhận <Highlight>1 lần</> tư cách đấu giá Chung Kết Săn Giết từ Cự Long · Hình Chiếu; đã có tư cách thì không thể nhận lại trong sự kiện đó.\nNgoài tối Thứ Sáu, sau khi các phiên Săn Giết khác bắt đầu <Highlight>10 phút</>, trung tâm Vương Thành xuất hiện <Highlight>Người Bảo Vệ Vương Thành</>. Sau khi đánh bại, thành viên đội tung đòn kết liễu chia sẻ phần thưởng tương ứng.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Nhân Đôi Điểm Thắng Xếp Hạng</>\nTrong Săn Giết, hạ người chơi phe địch cướp <Highlight>gấp đôi Điểm Thắng Xếp Hạng</>; khi bị hạ, Điểm Thắng Xếp Hạng mất đi cũng gấp đôi.",
    [1240253142800641] = "<Title>Phân Bổ Thế Lực Sơ Bộ</>\nSau khi sàng lọc chiến khu hoàn tất, việc phân bổ thế lực sơ bộ sẽ hoàn thành lúc <Highlight>12:00 ngày 13/9</>.\n\n<Title>Điều Chỉnh Thế Lực</>\nSau phân bổ sơ bộ, có thể tự điều chỉnh thế lực theo quy tắc; <Highlight>18:00 ngày 13/9</> kết thúc điều chỉnh và chốt thế lực cuối cùng. Trong thời gian điều chỉnh, <Highlight>CLB hạng 1 của mỗi chiến khu sẽ bị khóa, không thể đổi thế lực</>. Sau đó sẽ dùng thế lực cố định đã phân để hoàn thành một tháng Đối Chiến Thế Lực.",
    [1240253142813697] = "<Highlight>Vừa là thợ săn, vừa là con mồi</> — bạn có thể hạ người khác để <Highlight>cướp Nguyên Liệu Di Vật và Điểm Thắng Xếp Hạng</>, nhưng cũng có thể trở thành mục tiêu của Phi Phàm Giả khác bất cứ lúc nào. <Highlight>Khuyến nghị tổ đội trước khi săn</>!",
    [1240253142818049] = "Người chơi tích điểm theo thành tích của Hình Chiếu trên chiến trường:\nTheo thứ hạng sống sót, ba Hình Chiếu đứng đầu lần lượt nhận <Highlight>60,40,30</> điểm;\nmỗi khi Hình Chiếu khác tử trận, Hình Chiếu của bản thân nhận <Highlight>3</> điểm;\nhạ Hình Chiếu khác nhận <Highlight>5</> điểm.\nNgười chơi cần đưa vào ít nhất <Highlight>8</> Hình Chiếu để đủ điều kiện nhận thưởng. Sau trận, người có tổng điểm cao và Hình Chiếu có dữ liệu nổi bật sẽ nhận thêm thưởng <Highlight>Danh Hiệu</>.",
    [1240253142830593] = "1. <Highlight>Bản Đồ Lớn</> hiển thị vị trí cờ theo thời gian thực.\n2. <Highlight>Mini-map góc phải trên</> cũng liên tục hiển thị hướng của cờ; có thể theo chỉ dẫn để tìm.\n3. <Highlight>Tập Kết · Tuyên Chiến CLB</>: Trong thời gian Tuyên Chiến CLB, <Highlight>Hội Trưởng, Phó Hội Trưởng, Lý Sự</> có thể dùng vật phẩm này tại Dãy Hornacis để phát động Tập Kết tới <Highlight>thành viên CLB mình đang ở trên bản đồ</>. Sau khi dùng, toàn bộ vật phẩm này của CLB bước vào hồi chiêu <Highlight>360</> giây. Có thể nhận tại <Highlight>Bách Hóa-Đồng Hành Thương Điếm-CLB</>.",
    [1240253947976449] = "Trong giao diện Ra Trận Đồng Hành, Đồng Hành được đặt Tham Chiến sẽ cung cấp kỹ năng chủ động và bonus Thuộc Tính Chiến Đấu cho người chơi. Người chơi có thể dùng Kỹ Năng Tham Chiến tương ứng để chiến đấu.",
    [1240253947978241] = "Tiêu hao Vật Phong Ấn cùng tên để gia cố Hình Chiếu Lịch Sử của Vật Phong Ấn, giúp nó nhận Đặc Tính Phi Phàm mạnh hơn và giảm cái giá tác dụng phụ.",
    [1240253948082689] = "Quy Tắc Trang Trí 1: Dùng tường và sàn <Highlight>tạo thành khu vực khép kín</> sẽ tự sinh mái.\nQuy Tắc Trang Trí 2: Có thể đổi <Highlight>Góc Nhìn Bám Theo</> ở góc trên phải sang <Highlight>Góc Nhìn Tự Do</> hoặc <Highlight>Góc Nhìn Từ Trên</>.\nQuy Tắc Trang Trí 3: Áp dụng <Highlight>Xây Dựng Kỳ Tích</> và <Highlight>Mẫu Lâu Đài</>, sau đó chỉnh thêm một chút để có hiệu quả tốt hơn.\nQuy Tắc Trang Trí 4: Hãy tận dụng <Highlight>Sàn Trong Suốt</>.\nQuy Tắc Trang Trí 5: Sau khi đặt sàn/tường, <Highlight>nhấn giữ sàn/tường rồi kéo</> để lát liên tục nhanh chóng.",
    [1240253948094721] = "Tại cứ điểm phe mình có thể đi <Highlight>Tàu Hơi Nước</> để nhanh chóng tới doanh trại phía trước; khi công cổng thành có thể dùng <Highlight>Xe Công Thành</>.\n<Highlight>Cự Long Chiến Tranh</> chịu ảnh hưởng của Định Luật Hội Tụ Đặc Tính Phi Phàm, bị tàn lực của Huyết Hoàng Đế Alista Tudor thu hút tới chiến trường này, chiếm cứ “Vương Thành Trung Ương” ở lõi chiến tranh và sẽ xuất hiện trong trận để kích động chiến hỏa.\nMỗi thế lực đều có kỹ năng chỉ huy mạnh mẽ, có thể tung ra đúng thời cơ để ảnh hưởng cục diện.",
    [1240253948094977] = "Phe có Điểm Thế Lực thấp hơn phe hạng nhất <Highlight>3000</> điểm sẽ được coi là phe yếu thế và nhận các cơ chế hỗ trợ sau:\n<Highlight>Dây Cản Ngựa</>: Cứ mỗi <Highlight>5 phút</>, trước quảng trường phe yếu thế sẽ thả vật phẩm Dây Cản Ngựa; chỉ Phi Phàm Giả phe đó có thể nhặt. Sau khi nhặt nhận kỹ năng đặc biệt, dùng lên Kỵ Sĩ để Giảm Tốc Kỵ Sĩ.\n<Highlight>Dịch Chuyển Tập Hợp</>: Cứ mỗi <Highlight>8 phút</>, quảng trường phe yếu thế mở cơ chế Tập Hợp; cần <Highlight>1</> Phi Phàm Giả tới khu vực quảng trường kích hoạt. Khi kích hoạt thành công, toàn bộ Phi Phàm Giả phe đó có thể dịch chuyển tới quảng trường và nhận buff mạnh.",
    [1240253948099073] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quan hệ bạn-địch</>\nThành viên cùng đội, tổ đội lớn hoặc CLB được xem là đồng minh; <Highlight>mọi người chơi còn lại đều là địch</> và có thể tự do tấn công.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Kết toán theo đội</>\nKhi hạ người chơi địch, người kết liễu và tối đa <Highlight>29 thành viên</> cùng đội đủ điều kiện hỗ trợ sẽ tham gia kết toán Di Vật Đỏ Thẫm và Điểm Thắng Hạng lần này.\nSố Di Vật Đỏ Thẫm được phân phối chia đều theo số người tham gia và làm tròn xuống. Nếu có dư, người kết liễu ưu tiên nhận thêm 1; phần còn lại phân ngẫu nhiên cho những người khác, mỗi người tối đa nhận thêm 1.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Quy tắc cướp đoạt</>\nSau khi hạ người chơi địch, có thể cướp <Highlight>Điểm Thắng Hạng</> và <Highlight>Di Vật Đỏ Thẫm</> họ đang giữ. Số mảnh hiển thị trên đầu người chơi càng nhiều, tỷ lệ cướp Di Vật Đỏ Thẫm càng cao; cứ tăng <Highlight>500 mảnh</>, tỷ lệ cướp tăng tương ứng.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Bảo hộ Hạng</>\nNgười chơi có Hạng thấp hơn <Highlight>Bá Tước Bậc 1</> không bị trừ Điểm Thắng Hạng khi bị hạ.\n<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Suy giảm Điểm Thắng Hạng</>\nMỗi ngày <Highlight>01:00—08:00</>, Điểm Thắng Hạng nhận khi hạ người chơi giảm còn <Highlight>10%</> giá trị bình thường; Điểm Thắng Hạng từ Tiến Độ Săn không bị ảnh hưởng.\nKhi cùng một người chơi liên tục hạ cùng một mục tiêu trong 10 phút, lần 1–3 nhận 100% Điểm Thắng Hạng, lần 4 nhận 50%, lần 5 nhận 20%, từ lần 6 trở đi không còn nhận. Khi hai quy tắc suy giảm cùng có hiệu lực, kết quả cuối được nhân theo tỷ lệ.",
    [1240253948107009] = "<Title>Đối Chiến Thế Lực</>\nCác CLB tham gia Server Chiến Lược sẽ chiến đấu theo thế lực cuối cùng đã xác định trong 1 tháng. Tham gia <Highlight>Lãnh Chúa Sương Rơi, Chiến Thành Server Chiến Lược, Tuyên Lệnh Chinh Phục CLB, Chung Kết Săn Giết Server Chiến Lược</> để nhận Điểm Thần Tuyển CLB và tranh Suất Thần Tuyển theo xếp hạng tuần cùng xếp hạng cuối. Suất Thần Tuyển CLB nhận được sẽ do quản lý CLB phân phối nội bộ.\n\n<Title>Chiến Bị Chiến Lược</>\nServer Chiến Lược lần này mở ba loại chiến bị riêng:\n<Highlight>Kỹ Năng Chiến Lược:</> Mỗi Con Đường có kỹ năng chiến lược riêng; dùng hợp lý sẽ ảnh hưởng lớn đến cục diện.\n<Highlight>Kết Tinh Lịch Sử:</> Dùng Kết Tinh Lịch Sử nâng Vật Phong Ấn lên Cấp 1 và dần mở thêm ô khảm Vật Chất Phi Phàm.\n<Highlight>Chinh Đồ Đại Đế:</> Tham gia các lối chơi Server Chiến Lược để nhận Danh Vọng Chinh Phục, dùng tăng Cấp Quân Hàm tại Server Chiến Lược.\n<Highlight>Các chiến bị trên chỉ có hiệu lực trong Server Chiến Lược</>.\n\n<Title>Vinh Quang Thần Tuyển</>\nSau khi Đối Chiến Thế Lực kết thúc, mở <Highlight>Đại Hội Tuyên Ngôn Kẻ Thắng</>. Khi đại hội kết thúc, đồng loạt phát thưởng Suất Thần Tuyển và Thần Giáng giới hạn thời gian. Sau đó, dựa theo Điểm Thần Tuyển của các CLB, server sẽ mở <Highlight>Chiến Tranh Thương Mại</>. Hãy đón chờ.",
    [1240253948120065] = "<Highlight>Nộp Vật Liệu Di Vật Tinh Hồng cho Quản Gia Săn Giết</> để tăng <Highlight>Tiến Độ Săn Giết</> và mở khóa <Highlight>phần thưởng lớn theo giai đoạn</>. Lưu ý: <Highlight>Di Vật Tinh Hồng chỉ có hiệu lực trong Thành Săn Rồng</>; rời khỏi sẽ <Highlight>tự mất hiệu lực và bị xóa</>.",
    [1240253948136961] = "1. Khi Cờ không ở Phân Tuyến hiện tại, có thể nhấn <Highlight>Đổi Phân Tuyến</> phía trên Bản Đồ Nhỏ góc phải để tìm.\n2. Chọn Điểm Dịch Chuyển để tới <Highlight>Phân Tuyến có Cờ</>, nhanh chóng tham chiến.",
    [1240319446222592] = "Rời Phó Bản sẽ rời Đội. Tiếp tục?\nCó thể chọn Tạm Rời.",
    [1240319446223360] = "Rời Đội cũng sẽ rời Phó Bản. Xác nhận?",
    [1240319446224384] = "Có vật phẩm phẩm chất cao. Xác nhận phân giải? %s",
    [1240319446224640] = "Hiện Tại: %s\nCập Nhật: %s\nMới Nhất: %s\nCập nhật?",
    [1240319446225152] = "Đã Có Bản Mới · Hãy Cập Nhật",
    [1240319446225408] = "Cần Cập Nhật · %s",
    [1240319446225664] = "Dữ Liệu Di Động · Tiếp Tục?",
    [1240319446228992] = "Sau khi xác nhận, Nhân Cách Thay Thế sẽ chết thay bạn một lần; bạn có thể tự chọn cách hồi sinh. Dùng Ân Tứ Kẻ Khờ này để thoát khỏi hiểm cảnh?",
    [1240319446231296] = "Chiến Lực mới thấp hơn cũ. Dùng kết quả mới?",
    [1240319446231552] = "Trang bị cũ có Dòng Thuộc Tính Hiếm; sau khi thay sẽ bị ghi đè và biến mất. Vẫn xác nhận dùng kết quả mới thay kết quả cũ?",
    [1240319446231808] = "Dòng đã chọn là Dòng Thuộc Tính Hiếm; sau khi bôi sẽ bị ghi đè và biến mất. Vẫn xác nhận bôi?",
    [1240319446232832] = "Trang bị có Dòng Thuộc Tính Hiếm; thao tác hiện tại có thể ghi đè dòng này và không thể hoàn tác. Tiếp tục?",
    [1240319446233088] = "Xác nhận chọn %s để thay %s?",
    [1240319446235392] = "%s hiện không đủ. Tiêu hao %d Bảng Vàng Khóa để mua %s %s?",
    [1240319446236416] = "Lần reset này sẽ hoàn %i %s đã tiêu hao (reset chỉ hoàn vật phẩm), đồng thời toàn bộ Điểm Vận Mệnh đã kích hoạt trở về trạng thái chưa kích hoạt. Xác nhận reset?",
    [1240319446238208] = "Vật Phong Ấn này đã được cải tạo. Tiếp tục tiêu hao nó làm nguyên liệu Đột Phá? Vật Phong Ấn đã phát triển dùng làm nguyên liệu sẽ hoàn các nguyên liệu phát triển tương ứng theo tỷ lệ phân giải.",
    [1240319446238720] = "Độ Cộng Hưởng Đặc Tính mới thấp hơn. Vẫn thay?",
    [1240319446239232] = "Giá trị Linh Chất của trang bị nguyên liệu không cao hơn Linh Chất cùng loại trên trang bị hiện tại. Xác nhận hoán đổi?\n\nChi phí: <Img tex2d=\"%s\"/>%s",
    [1240319446239488] = "Sau khi hoán đổi, trang bị nguyên liệu sẽ bị Khóa. Xác nhận hoán đổi?\n\nChi phí: <Img tex2d=\"%s\"/>%s",
    [1240319446240000] = "Hoàn tác điều chỉnh Linh Chất hiện tại sẽ hoàn %d nguyên liệu (80%% tổng nguyên liệu đã tiêu hao). Xác nhận hoàn tác?",
    [1240319446240256] = "Hoàn tác toàn bộ điều chỉnh Linh Chất ở bộ phận hiện tại sẽ hoàn %d nguyên liệu (80%% tổng nguyên liệu đã tiêu hao). Xác nhận hoàn tác?",
    [1240319446241280] = "Sau khi cập nhật Mùa, <Highlight>giới hạn Cường Hóa Trang Bị đã tăng</>, đồng thời tự chuyển sang nguyên liệu Cường Hóa mùa mới.",
    [1240319446241536] = "Sau khi cập nhật Niên Mùa, Cường Hóa Trang Bị đã được đặt lại; <Highlight>toàn bộ tiến độ Cường Hóa về 0</> và tự chuyển sang nguyên liệu Cường Hóa của Niên Mùa mới.",
    [1240319446242304] = "%s và các trang bị khác khá quý hiếm. Vẫn phân giải?",
    [1240319446242560] = "%s và các trang bị khác đang ở trạng thái %s. Vẫn phân giải?",
    [1240319446243072] = "Vị trí <Highlight>%s</> đã mở khóa Tái Tạo; Phi Phàm Giả có thể Tái Tạo để nhận hiệu quả Ân Tứ mạnh hơn.",
    [1240319446243840] = "Thiếu dung lượng tải cập nhật. Dọn bớt rồi thử lại.",
    [1240319446247936] = "Lần mua này tiêu hao %s Bảng Vàng Khóa. Cả Bảng Vàng Khóa và Bảng Vàng đều không đủ, tới nạp?",
    [1240319446248192] = "Lần mua này tiêu hao Bảng Vàng Khóa; hiện không đủ,\ncó dùng Bảng Vàng thay thế không?\n\nTiêu hao: <Img tex2d=\"%s\"/>%s<Img tex2d=\"%s\"/>%s",
    [1240319446248960] = "Xác nhận đặt mục tiêu này và rời Đoàn Đội dưới dạng Đội?",
    [1240319446249472] = "Lần mua này cần tiêu hao %s Bảng Vàng. Bảng Vàng hiện không đủ, tới nạp?",
    [1240319446249728] = "Cần tiêu hao %s Soli; Soli hiện không đủ. Có đến đổi không?",
    [1240319446252032] = "Hoàn thành nhiệm vụ <Highlight>%s</> để mở khóa. Có đến đó không?",
    [1240319446252800] = "Mở khóa %s ô Túi Đồ cần tiêu hao\n<Img tex2d=\"%s\"/><Highlight>%s</>",
    [1240319446253568] = "Tiêu hao <Img tex2d=\"%s\"/><Highlight>%s</> để Cầu Phúc?",
    [1240319446253824] = "Đã nhận Chúc Phúc hiếm, có tiêu hao <Img tex2d=\"%s\"/><Highlight>%s</> để tiếp tục Cầu Phúc không?",
    [1240319446254080] = "Lần làm mới này cần tiêu hao %s Suli; hiện không đủ Suli, đi đổi?",
    [1240319446254336] = "Sau khi chuyển sang Chế Độ Điên Cuồng, có thể chủ động tấn công Phi Phàm Giả khác và có thể bị treo thưởng truy nã. Xác nhận chuyển?",
    [1240319446256640] = "Xác nhận tiêu hao <Img tex2d=\"%s\"/>%s để mua %s?",
    [1240319446256896] = "Xác nhận tiêu hao <Img tex2d=\"%s\"/>%s để đấu giá %s?",
    [1240319446257408] = "Bạn vẫn còn phiếu giảm giá có thể dùng. Tiếp tục mua mà <Highlight>không dùng phiếu nào</>?",
    [1240319446259200] = "Thăng cấp cần tiêu hao các đạo cụ sau",
    [1240319446260480] = "Sau Cộng Hưởng Khí Tức lần này, chênh lệch giữa Khí Tức đang chọn và Khí Tức cường độ thấp nhất đã vượt 5 cấp. Nếu tiếp tục cường hóa sẽ làm suy giảm Độ Cộng Hưởng và mức tăng thuộc tính của Khí Tức này. Tiếp tục?",
    [1240319446260992] = "Hiện không có Vật Phong Ấn nào có thể trang bị. Tới giao diện rút thẻ để nhận Vật Phong Ấn?",
    [1240319446264832] = "Lần mua này tổng cộng tốn %s. Xác nhận mua %s?",
    [1240319446271232] = "%s đang nằm trong Phương Án Trang Bị. Vẫn phân giải? %s",
    [1240319446271488] = "%s đang nằm trong Phương Án Trang Bị. Đưa vào Kho sẽ xóa khỏi Phương Án Trang Bị; vẫn tiếp tục?",
    [1240319446272256] = "Rời Thẩm Vấn sẽ bỏ lần Thẩm Vấn này và tiêu hao lượt. Xác nhận rời lối chơi?",
    [1240319446272768] = "Không tiêu hao Thể Lực sẽ không nhận được thưởng vượt ải. Tiếp tục?",
    [1240319446275072] = "Khu vực mục tiêu là Khu Chiến Đấu; chọn Phân Tuyến Chiến Đấu sẽ cho phép bật <Highlight>Chế Độ PvP</> giữa Phi Phàm Giả!",
    [1240319446276352] = "Xác nhận tiêu hao <Img tex2d=\"%s\"/>%s để tặng Ngoại Hình?",
    [1240319446289920] = "Có tiêu hao đạo cụ để gia hạn Phòng Voice thường trực hiện tại thêm 30 ngày?",
    [1240319446290176] = "Sau khi giải tán, toàn bộ thành viên trong Phòng Thoại sẽ bị đưa ra ngoài; phòng đã giải tán không thể khôi phục, vật phẩm Gia Hạn cũng không được hoàn lại. Xác nhận?",
    [1240319446292736] = "Lần mua này sẽ tiêu hao Bảng Vàng Khóa. Tiếp tục mua?",
    [1240319446296576] = "Sau khi đặt lại, toàn bộ điểm đã cộng trong Thiên Phú hiện tại sẽ bị xóa và hoàn trả toàn bộ Điểm Thiên Phú. Xác nhận?",
    [1240319446298112] = "Có Vật Chất Phi Phàm có Điểm cao hơn. Xác nhận vẫn chọn?",
    [1240319446299136] = "Có Vật Chất Phi Phàm mang Dòng Dị Biến chưa được chọn; dòng này cực kỳ hiếm. Xác nhận lựa chọn lần này? Thao tác không thể hoàn tác. Nếu xác nhận, hãy tự nhập “Tôi đồng ý” rồi nhấn Xác Nhận.",
    [1240319446299392] = "Có Vật Chất Phi Phàm mang Dòng Thuộc Tính Dị Biến. Dòng này rất hiếm, xác nhận phân giải? Thao tác này không thể hoàn tác. Nếu đồng ý, hãy nhập thủ công “Tôi đồng ý” rồi bấm Xác Nhận.",
    [1240319446299648] = "Có tiêu hao %d %s để mở ô không?",
    [1240319446302208] = "Trang bị hiện tại không phải phương án Ân Tứ tối ưu. Có thể áp dụng phương án Ân Tứ tối ưu đã lưu. Áp dụng ngay?\n<BrickRedLight>Sau khi áp dụng, các Dòng Thuộc Tính hiện có trên trang bị sẽ biến mất.</>",
    [1240319446305024] = "Có tiêu hao <Img tex2d=\"%s\" width=\"54\" height=\"54\"/>%s để mở khóa thêm phương án?",
    [1240319446305280] = "Có dùng <Highlight>Thánh Bôi</> bù <Highlight>Thánh Bôi · Khóa</> để triệu hồi không?\nSau khi bật, phần thưởng triệu hồi bằng Thánh Bôi sẽ <Highlight>không thể giao dịch hoặc tặng</>, đồng thời tính vào tiến độ bảo hiểm Thánh Bôi · Khóa.",
    [1240319446307584] = "Vật Chất Phi Phàm này đang được trang bị. Xác nhận tháo?",
    [1240319446308096] = "Xác nhận đặt %s làm Điểm Hồi Sinh?",
    [1240319446310400] = "Xác nhận tiêu hao %d %s để rút chọn?",
    [1240319446316544] = "Phương án Trợ Giúp Một Chạm hiện tại là phương án Tân Thủ nên không thể thay thế. Hãy vào giao diện Trợ Giúp Một Chạm, <Highlight>chuyển sang và lưu một phương án không phải Tân Thủ</>.",
    [1240319446317568] = "Hiện vẫn còn <Highlight>Sinh Vật Siêu Phàm</> chưa bị đánh bại. Triệu hồi <Highlight>nhiều Sinh Vật Siêu Phàm</> cùng lúc sẽ dễ thu hút những Thợ Săn khác nhòm ngó hơn. Tiếp tục triệu hồi?",
    [1240319446317824] = "Rời <Highlight>Thành Săn Rồng</> sẽ <Highlight>gián đoạn</> nhiệm vụ Hạt Giống Than Thở hiện tại và <Highlight>xóa toàn bộ Di Vật Đỏ Thẫm có thể bị cướp trong Túi</>. Xác nhận truyền tống rời đi?",
    [1240319446318080] = "Hạt Giống Than Thở phải dùng trong <Highlight>khu vực Thành Săn Rồng</>. Có dịch chuyển tới đó không?",
    [1240319446318336] = "Xác nhận dùng phương án phân phối Điểm Thuộc Tính này để bắt đầu Chạy Đoàn?",
    [1240319446320640] = "Có Vật Chất Phi Phàm Phẩm Chất Vàng. Xác nhận phân giải?",
    [1240319446322176] = "Điểm Phi Phàm trung bình của đội bạn chưa đạt mức đề xuất, tạm thời không thể Ghép Đội; nên chiến đấu với máy hoặc Ghép Trận đơn.",
    [1240319446322688] = "Lần mua này cần tiêu hao <Highlight>50</><img id=\"2000030\" width=\"48\" height=\"48\"/>. Vật phẩm hiện không đủ, tới cửa hàng mua?",
    [1240319446323200] = "Đổi Tên Thiết Lập",
    [1240319446324992] = "Xác nhận tiêu hao %s để giúp %s?",
    [1240319446329088] = "Không đủ <Highlight>【%s】</>. Có đến Cửa Hàng để mua không?",
    [1240319446330368] = "Có tiêu hao %d %s để mở ô không?",
    [1240319446330880] = "Sau khi mặc, trang bị <Highlight>%s</> sẽ bị khóa liên kết và không thể giao dịch cho người khác. Tiếp tục mặc?",
    [1240319446332672] = "Cần tiêu hao <Highlight>%s Điểm Xếp Hạng</> (tức Điểm Xếp Hạng) để mua %s. Xác nhận mua?",
    [1240319446332928] = "Hiện bạn có thể vào Phó Bản độ khó cao hơn. Vẫn vào Phó Bản độ khó hiện tại? (Số lượt thưởng được dùng chung giữa các độ khó.)",
    [1240319446336512] = "Không đủ vật phẩm %s. Có đến nơi nhận không?",
    [1240319446337536] = "Lưu sẽ tiêu hao 1 <Highlight>Ấn Chương Vô Diện Nhân</>. Xác nhận?",
    [1240319446338048] = "Trong lúc điều chỉnh <Highlight>chưa sửa tạo hình khuôn mặt</>, hiện đang lưu <Highlight>phương án tạo mặt</>, sẽ tiêu hao Ấn Chương Vô Diện Nhân. Xác nhận?",
    [1240319446338816] = "Đã chuyển sang mạng di động. Tiếp tục tải sẽ tiêu hao dữ liệu, tiếp tục?",
    [1240319446340352] = "Mở nhiệm vụ tấn thăng sẽ tạm cất Ma Dược cần thiết trong Túi. Xác nhận?",
    [1240319446341376] = "Tiêu hao <Img tex2d=\"%s\"/>%s và <Img tex2d=\"%s\"/>%s để mở khóa và mua Nội Thất cùng linh kiện tương ứng?",
    [1240319446344192] = "Hiện có Vật Chất Phi Phàm Tím *%d, Phân Giải Một Chạm?",
    [1240319446344960] = "Tiêu hao <Highlight>%s</> %s để mở chức năng Tọa Kỵ của \"%s\"?",
    [1240319446347776] = "Xác nhận Tụ Hợp Một Nút? Khi xác nhận, hệ thống sẽ dùng Vật Chất Phi Phàm, Nhân Tố Tụ Hợp và Soule khóa hiện có của Phi Phàm Giả để hoàn thành Tụ Hợp theo quy tắc mặc định.",
    [1240319446349824] = "Tiến độ Săn Giết của bạn đã đạt mốc nhận thưởng. Nhận thưởng ngay và nhận lượt triệu hồi?",
    [1240319446350336] = "Chỉ có thể chọn một nhân vật ở một server để nhận hoàn trả.\nPhi Phàm Giả hiện có thể nhận 【%s】\nXác nhận dùng nhân vật hiện tại để nhận?",
    [1240319446350848] = "Trong Tai Ách Thế Giới, nếu thành viên đội thay đổi, đội sẽ mất tư cách vào bảng xếp hạng trong ván này và phần thưởng chỉ được tính theo Sát Thương cá nhân. Vẫn đồng ý cho thành viên mới vào đội?",
    [1240319446351360] = "Xác nhận rời Tranh Đoạt Thần Tọa?\n<BrickRedLight>Rời khu vực khi chưa chết hoặc vẫn có thể được hồi sinh sẽ chịu Hình Phạt Rời Trận</>",
    [1240319446351616] = "Mẫu này cần Cấp <Highlight>%s</> để dùng. Nếu lưu bây giờ sẽ chưa thể dùng trực tiếp. Tiếp tục lưu?",
    [1240319446351872] = "Chỉ có thể nhận thưởng của một sự kiện. Sau khi nhận, không thể nhận thưởng các sự kiện khác trong tuần này. Xác nhận?",
    [1240319446352128] = "Không thể đổi Thiên Phú Con Đường trong lối chơi này.",
    [1240319446353408] = "Sắp triệu hồi hơn <Highlight>7</> Hình Chiếu trong vòng hiện tại. Tiếp tục? (Khuyến nghị số Hình Chiếu triệu hồi dưới <Highlight>6</>)",
    [1240319446354432] = "Mỗi tuần chỉ có thể nhận một trong hai phần thưởng sự kiện Giải Tứ Phương và Bóng Ma Nhà Hát. Sau khi nhận một bên, không thể nhận bên còn lại. Xác nhận?",
    [1240319446355712] = "Phát hiện bạn đang dùng mạng di động. Tiếp tục tải sẽ tiêu hao dữ liệu, tiếp tục?",
    [1240319446357504] = "Tiêu hao %s %s để đánh thức nhánh Vận Mệnh của Quan Hệ %s?\n(Số lượng hiện có: %s)",
    [1240319446357760] = "Có tiêu hao <Img tex2d=\"%s\" width=\"54\" height=\"54\"/>%s để mở khóa ô?",
    [1240319446368000] = "Không đủ Mảnh Bí Ngẫu. Có đến 【Nhận Bí Ngẫu】 không?",
    [1240319446368256] = "Bạn sắp tuyên chiến với <Highlight>[%s]</>, thời gian khai chiến <Highlight>%s</>. Tuyên chiến tiêu hao Quỹ CLB <Img tex2d=\"%s\"/>%s. Xác nhận?",
    [1240319446375680] = "Tích lũy Kết Giao đủ 110 lần sẽ nhận thêm 1 lượt <Highlight>Ước Nguyện</>.\nHiện chưa có mục tiêu Ước Nguyện. Có đến Ước Nguyện không?",
    [1240319446375936] = "Tích lũy Kết Giao đủ 110 lần sẽ nhận thêm 1 lượt <Highlight>Ước Nguyện</>.\nMục tiêu Ước Nguyện hiện tại là <Highlight>%s</>. Có đến chỉnh sửa không?",
    [1240319446378240] = "Xác nhận tiêu hao <Img tex2d=\"%s\"/>%s để phát Lễ Kim?",
    [1240319446380288] = "Xác nhận tăng Cấp Nguy Hiểm của Vật Phong Ấn <Highlight>%s</>?",
    [1240319446380544] = "Bí Ngẫu đã chọn đang Du Lịch. Có tới 【Du Lịch Bí Ngẫu】 để đổi trạng thái không?",
    [1240319446381824] = "Xác nhận 【Chọn Đầu Hàng】? Đầu hàng sẽ bị xử thua ngay và trừ Quỹ CLB <Img tex2d=\"%s\"/>%s!",
    [1240319446382592] = "Bật Tự Động Phân Giải Vật Chất Phi Phàm? Sau khi bật, Vật Chất Phi Phàm phẩm chất Tím nhận được sẽ tự động bị phân giải.",
    [1240319446382848] = "Xác nhận áp dụng bản ghi này? <BrickRedLight>Sau khi áp dụng, Dòng Thuộc Tính đang dùng sẽ biến mất.</>",
    [1240319714658560] = "Bỏ Nhiệm Vụ",
    [1240319714659840] = "Xác Nhận Phân Giải",
    [1240319714663424] = "Mở Khóa Ô Túi",
    [1240319714663680] = "Mở Khóa Ô Kho",
    [1240319714663936] = "Mở Khóa Trang Kho",
    [1240319714668544] = "Chọn Thuộc Tính Tái Rèn",
    [1240319714671872] = "Đặt Lại Trang Bị Phòng Thủ",
    [1240319714673920] = "Tẩy Luyện Vật Phong Ấn",
    [1240319714678272] = "Xác Nhận Sử Dụng",
    [1240319714678784] = "Chuyển Lĩnh Vực",
    [1240319714679296] = "Không Đủ Chỗ",
    [1240319714683648] = "Xác Nhận Mua",
    [1240319714688256] = "Mở Khóa Túi",
    [1240319714688512] = "Mở Khóa Kho",
    [1240319714692096] = "Xác Nhận Giao Dịch",
    [1240319714693376] = "Hướng Dẫn Nhập Vai",
