    [1240389776402432] = "Liên tục nhấn nút để xóa trạng thái Trì Trệ của đồng đội.",
    [1240389776402688] = "<Reminder_Red>Nhanh chóng phá Khiên</> để ngắt kỹ năng sát thương toàn màn hình.",
    [1240389776402944] = "Sát thương đầu ra không đạt yêu cầu, Boss tung kỹ năng toàn màn hình.",
    [1240389776404224] = "Có thành viên chưa xác nhận, mở Phó Bản thất bại.",
    [1240389776404480] = "Thành viên Đội đã thay đổi, mở Phó Bản thất bại.",
    [1240389776406528] = "<Reminder_Red>%s</> bị Chú Hề gài bom hẹn giờ, mau lại gần để chia sẻ sát thương.",
    [1240389776408832] = "Chú Hề đặt bom lên một Phi Phàm Giả; đến gần nhau để chia Sát Thương.",
    [1240389776413952] = "Oán Hồn đặt bom lên một Phi Phàm Giả; đến gần nhau để chia Sát Thương.",
    [1240389776422912] = "Nếu không phá Ma Kính mục tiêu trong thời gian giới hạn, Sharon sẽ gây Sát Thương toàn màn hình.",
    [1240389776425984] = "Giữ cảnh giác trong <Dungeon_Highlight>phạm vi gần xe ngựa</>, hộ tống Vật Phong Ấn 2-049.",
    [1240389776426496] = "Đã tiêu diệt toàn bộ kẻ địch, <Dungeon_Highlight>quay lại gần xe ngựa</> để tiếp tục hộ tống Vật Phong Ấn 2-049.",
    [1240389776428544] = "Trận Boss sắp bắt đầu; toàn bộ Phi Phàm Giả sẽ được dịch chuyển vào khu vực chiến đấu.",
    [1240389776429568] = "Real Bieber đã triệu hồi Vật Phong Ấn 2-049! Cẩn thận Khu Vực Trì Trệ do nó tạo ra!",
    [1240389776433408] = "Triệu Hồi Vật Phong Ấn",
    [1240389776435456] = "Chiến đấu thất bại, Boss đã đặt lại. Hãy hồi sinh rồi thử lại.",
    [1240389776442624] = "Giam Cầm",
    [1240389776448256] = "Cùng chịu đòn tấn công của Boss; sát thương phải chịu sẽ giảm mạnh.",
    [1240389776449024] = "Boss liên tục phun dịch vị về phía mục tiêu bị khóa. Nhớ bật Giảm Thương!!",
    [1240389776454656] = "<Dungeon_Disable>Tượng Hộ Vệ</> sắp kích hoạt Pháp Trận Sát Thương; Pháp Trận định kỳ gây sát thương phạm vi!",
    [1240389776455424] = "Hãy dùng Trị Liệu Nhóm hoặc kỹ năng Giảm Thương kịp thời!!",
    [1240389776458496] = "Tia Mất Khống Chế gây sát thương liên tục; Tank hãy chắn sát thương giúp các Phi Phàm Giả khác!",
    [1240389776465664] = "Thủ Lĩnh ẩn mình và triệu hồi Năng Lượng Hỗn Độn để tiêu diệt Phi Phàm Giả!",
    [1240389776467712] = "Sát thương liên tục không thể Chặn Đòn; chú ý lượng Máu của bản thân!",
    [1240389776468224] = "Năng Lượng Hỗn Độn quá tải, Boss vào Suy Yếu!",
    [1240389776470016] = "Quạ Tập Kích",
    [1240389776471552] = "Sát Thương Tri Thức Cấm Kỵ cực cao; vào vùng bóng tối có thể triệt tiêu nhưng sẽ khiến kim đồng hồ tiến lên.",
    [1240389776471808] = "Phi Phàm Giả bị Ký Sinh liên tục chịu sát thương; phá Khiên của Amon để giải cứu.",
    [1240389776472576] = "Boss miễn nhiễm sát thương trong Vùng Bóng Tối; hãy chú ý vị trí của Boss!",
    [1240389776473600] = "Phi Phàm Giả bị Bom Thời Gian ảnh hưởng có thể bỏ qua sát thương vùng bóng tối; hãy phân phối hợp lý đồng đội chịu sát thương bom.",
    [1240389776476160] = "Tán Hoa",
    [1240389776509696] = "Tập trung phá Khiên! Phi Phàm Giả bị Ký Sinh hãy tới gần Hư Ảnh Vàng để làm yếu Khiên.",
    [1240389776519936] = "Phi Cước",
    [1240389776539904] = "Đã phá hủy toàn bộ Tượng Ma Lang. Ma Lang U Ám vào trạng thái Phá Phòng!",
    [1240389776544768] = "Boss đã phát hiện các bạn, chiến đấu sắp bùng nổ; toàn bộ Phi Phàm Giả sẽ được dịch chuyển vào khu vực chiến đấu.",
    [1240389776557312] = "Hồi Máu thông qua tấn công và kỹ năng!",
