    [1240389777552128] = "Linh Tính bị áp chế, không thể dùng kỹ năng và Tốc Độ Di Chuyển giảm. Hãy rời khỏi vùng Cấm Lệnh càng sớm càng tốt!",
    [1240389777552384] = "Lần Tụ Hợp Một Chạm này đã Tụ Hợp tổng cộng %d lần, tiêu hao tổng %d Nhân Tố Tụ Hợp và %d Suli Khóa.",
    [1240389777569792] = "Giữ lại ít nhất %s đồng đội “Hình Chiếu” loại Phòng Thủ/Hồi Phục.",
    [1240389777570816] = "Có thể nạp sau khi Vật Phong Ấn đạt Cấp “%d”.",
    [1240389777584384] = "Trạng thái hiện tại không thể Hồi Sinh.",
    [1240389777585408] = "Nhấn nút để tạo Khiên Hắc Diễm duy trì theo hướng tương ứng, thiêu đốt Linh Thể của con rối.",
    [1240389777593856] = "Chuyển Tạm Thành Công",
    [1240389777601536] = "Đang hồi chiêu Đóng Gói, có thể đóng gói lại sau %s.",
    [1240389777614080] = "Hãy dùng vật phẩm <Highlight_L>%s</> trước; sau khi nhận nhiệm vụ hãy Theo Dõi.",
    [1240389777615360] = "Linh Tính của <PVPHighlight>Cự Long · Hình Chiếu</> đang tiêu tán; <PVPHighlight>5 phút nữa</> sẽ rời <PVPHighlight>trung tâm Vương Thành Thành Săn Rồng</>. Hãy nhanh chóng hoàn tất thảo phạt.",
    [1240389777625856] = "Khi Giá Trị Phá Phòng của quái vật về 0, nó sẽ tạm thời rơi vào trạng thái Suy Yếu!",
    [1240389777633024] = "Linh Tính của <PVPHighlight>Cự Long · Hình Chiếu</> đang tiêu tán; <PVPHighlight>10 phút nữa</> sẽ rời <PVPHighlight>trung tâm Vương Thành Thành Săn Rồng</>. Hãy nhanh chóng hoàn tất thảo phạt.",
    [1240389777635328] = "Buff CLB <PVPHighlight>【Quang Huy Kết Xã】</> đang được cường hóa giới hạn thời gian! Tham gia lối chơi Giáo Đoàn trong cảnh CLB sẽ nhận cường hóa <PVPHighlight>kết quả tung xúc xắc</> và buff <PVPHighlight>thuộc tính chiến đấu</>!",
    [1240389777638144] = "Mở khóa vào ngày thứ 7 của Mùa 1 khi Cấp Nhập Vai ≥61 và đã hoàn thành nhiệm vụ tiền đề 《Trở Thành Phi Phàm Giả》.",
    [1240389777644544] = "Hiện đang ở trạng thái đổi kỹ năng, không thể dùng đạo cụ này.",
    [1240389777645056] = "Hạ Phi Phàm Giả địch <PVPHighlight>%s</>, nhận <PVPHighlight>%s</> Điểm Chiến Công.",
    [1240389777648640] = "Hạ Phi Phàm Giả địch <PVPHighlight>%s</>, nhận <PVPHighlight>%s</><img id=\"2000502\"/> và <PVPHighlight>%s</> Điểm Chiến Công.",
    [1240389777657088] = "Mục tiêu không thể hồi sinh.",
    [1240389777666304] = "Tập Kết do CLB phe ta phát động đang hồi chiêu, thử lại sau %s giây!",
    [1240389777671168] = "Có thể nhấn phím Chuyển Đổi để gọi Linh Tính và chuyển lại Năng Lực Bậc.",
    [1240389777671936] = "Tải động tác thất bại, ô lưu đã đầy. Hãy tới <Highlight_L>Động Tác Xã Hội - Motion Capture</> để xóa hoặc điều chỉnh rồi lưu lại.",
    [1240389777677056] = "Cấp không đạt yêu cầu Phó Bản, không thể quay lại Phó Bản.",
    [1240389777678592] = "<HyperLink stylename=\"Our_Name\" u=\"role=%s\">[%s]</> của CLB phe ta đã cắm cờ tại <HyperLink stylename=\"Chat_Hyperlink\" u=\"pvlhpos=%s,%s,%s,%s\">[Dãy Honachis (%d,%d) Phân Tuyến %s]</>. Nhấn để tới bảo vệ! Khi cờ hết thời gian hoặc bị chiếm, quyền cắm cờ sẽ luân phiên!",
    [1240389777678848] = "CLB [%s] đã để <HyperLink stylename=\"Enemy_Name\" u=\"role=%s\">[%s]</> cắm cờ tại <HyperLink stylename=\"Chat_Hyperlink\" u=\"pvlhpos=%s,%s,%s,%s\">[Dãy Honachis (%d,%d) Phân Tuyến %s]</>. Nhấn để tới tranh đoạt! Khi cờ hết thời gian hoặc bị chiếm, quyền cắm cờ sẽ luân phiên!",
    [1240389777688064] = "Lý Trí hiện đã đạt giới hạn; nên tìm Phi Phàm Giả khác An Hồn để hồi giới hạn Lý Trí.",
    [1240389777688320] = "Không thể xuống Tọa Kỵ khi Kỹ Năng Tọa Kỵ đang thi triển.",
    [1240389777691136] = "Linh Hồn Khuyển Đỏ Thẫm rơi Chuông sau khi chết; nhặt lên có thể học kỹ năng Lắc Chuông!",
    [1240389777695232] = "Chưa thiết lập tiêu hao Suli Khóa, không thể Tụ Hợp Một Chạm.",
    [1240389777695488] = "Thiếu Nhân Tố Tụ Hợp, không thể tăng giới hạn Soli Khóa.",
    [1240389777695744] = "Đã đạt giới hạn tiêu hao cho một lần Tụ Hợp Một Chạm, không thể tăng thêm.",
    [1240389777697024] = "Có đồng đội đang ở trong Phó Bản. Hãy để họ thoát Phó Bản trước rồi nhấn lại nút <Highlight_L>Tai Ách Thế Giới</>.",
    [1240391924163840] = "Phó Bản đã mở khóa, giờ có thể tham gia.",
    [1240391924675328] = "Mở khóa Cánh Cửa Linh Tính mới.",
    [1240662775174912] = "Số Tầng Quá Tải",
    [1240799677253120] = "Quay Lại",
    [1240799677253632] = "Con Đường Thần",
    [1240799677254656] = "Nút Quay Lại",
    [1253512780450048] = "Sợ Hãi",
    [1271036247019520] = "Vào Phi Phàm Giới",
    [1271036247030528] = "Đã Nhận",
    [1271036247032320] = "Vật Liệu Nâng Cấp",
    [1271036247034624] = "Cấp Tri Thức Phi Phàm",
    [1271036247037696] = "Tri Thức Phi Phàm",
    [1271036247043584] = "Đặt Lại",
    [1271036247046400] = "Nếu đang có hiệu ứng tăng Phòng Thủ sẽ nhận Khiên, hấp thụ Sát Thương bằng <HighLight>20.0%</> giới hạn Thể Lực trong <HighLight>15</> giây.",
    [1271036247048448] = "Hiệu Ứng Thiên Phú",
    [1271036247052800] = "Thiết Lập Đề Xuất",
    [1271036247069184] = "Tiêu Hao Nguyên Liệu",
    [1271036247076352] = "Tiêu Hao",
    [1271036247081472] = "Hạng",
    [1271036247082752] = "Hình Chiếu",
    [1271036247084288] = "Đã Đầy",
    [1271036247092736] = "Thưởng Mùa Giải: Khi mùa giải kết thúc, <Highlight>Top 5</> CLB <Highlight>Nhóm Thần Thoại/Thánh Danh/Truyền Kỳ</> có số trận tham gia nhiều nhất sẽ nhận <Highlight>Danh Hiệu giới hạn thời gian</>.",
    [1271036247095552] = "Thưởng",
    [1271036247117056] = "Thưởng Nhiệm Vụ",
    [1271036247125504] = "Mua Nhanh",
    [1271036247157760] = "Thăng Tiến Thành Công",
    [1271036247172096] = "Thành Phố",
    [1271036247172352] = "Quốc Gia",
    [1271036247177216] = "Đến Thiết Lập Sẵn",
    [1271036247202560] = "Nhận qua nhiệm vụ Nằm Thắng Nhẹ Nhàng hoặc hồi tự nhiên; cũng có thể dùng Dược Tề Hồi Thể Lực để hồi nhanh. Tiêu hao Thể Lực để mở Bí Bảo và nhận thưởng tương ứng.",
    [1271036247217152] = "Chọn Quái Vật Triệu Hồi",
    [1271036247218176] = "Chọn Khu Vực Triệu Hồi",
    [1271036247220224] = "Có thể tự chọn 1 điểm trong các Điểm Truyền Tống hoặc Điểm Hồi Sinh hiện tại để hồi sinh.",
    [1271036247222016] = "Số Lượng Sở Hữu",
    [1271036247228160] = "Con Đường Hiện Tại",
    [1271036247234816] = "Chuyển Con Đường",
    [1271036247235584] = "Thiết Lập Trang Bị",
    [1271036247241728] = "Độ Hảo Cảm chưa đạt 「Tiếp Xúc Linh Tính」, không thể chụp chung khung với bạn bè.",
    [1271036247242752] = "Có thứ gì đó đang thiêu cháy dưới da, nhuộm bạn từ trong ra ngoài thành sắc trăng đỏ thẫm. Sức mạnh của bạn vượt xa người thường; những xiềng xích muốn trói buộc bạn giờ chỉ là trò cười. Nhưng nhân tính cũng dần trôi mất, nhận thức bắt đầu rối loạn, không còn phân biệt được địch-ta. Sức mạnh Phi Phàm cuộn trào nhưng không nghe lệnh. Cơ thể phát ánh đỏ sẫm như một dây cháy sắp đứt. Bạn đã đứng bên bờ nguy hiểm; bước tiếp theo là vực sâu.\n——Sát thương tăng mức vừa; miễn nhiễm phần lớn khống chế; sát thương nhận vào tăng; khi dùng kỹ năng có xác suất đánh nhầm đồng đội; xác suất hình ảnh rối loạn tăng; bản thân phát hiệu ứng ánh đỏ.",
    [1271036247255296] = "Tên Kỹ Năng",
    [1271036247257088] = "Quân Cờ Giáo Phái Sinh Mệnh ngoài nhận <HighLight>Tấn Công</> và <HighLight>Tốc Độ Đánh</> cơ bản, Quân Cờ không thuộc Giáo Phái Sinh Mệnh có <HighLight>Hút Máu cao nhất</> cũng nhận cùng bonus. Khi được Nghi Thức Giáo Phái gia trì, toàn đội tăng Sát Thương Pháp Thuật và Tỷ Lệ Bạo Kích, nhận Tầm Nhìn Bóng Tối, đồng thời giảm nhẹ hồi chiêu kỹ năng.",
    [1271036247276288] = "Tổng Sát Thương",
    [1271036247277568] = "Thống Kê Sát Thương",
    [1271036247285248] = "Chọn Để Bán",
    [1271036247291136] = "Nhận Thiên Phú",
    [1271036247297280] = "Vật Phong Ấn <Rank1>“Cấp 1”</> chỉ có hiệu lực ở server Chiến Lược; server này áp dụng hiệu ứng <Rank2>“Cấp 2”</>.",
    [1271036247329024] = "Điểm Đề Xuất",
    [1271036247334144] = "Chọn vật phẩm gửi trước; chỉ <Highlight>vật phẩm không khóa</> mới có thể gửi trước.",
    [1271036247334912] = "Mùa",
    [1271036247344384] = "Thưởng Sự Kiện",
    [1271036247345152] = "Đã Sở Hữu",
    [1271036247346176] = "Mục Tiêu",
    [1271036247352320] = "Thưởng Thêm",
  },
