      [787323340014592] = "Cuối mỗi ga, có thể dùng Thẻ Chiến Lược để tăng lợi nhuận",
      [787323340014848] = "Lưu ý: mỗi Thẻ Chiến Lược thường có điều kiện; phải đáp ứng mới kích hoạt hiệu ứng",
      [787323340015104] = "Để suy đoán điều kiện, quan trọng nhất là tham khảo thông tin ga; dùng suy luận để tăng tỷ lệ thành công",
      [787323340015360] = "Sản phẩm Xưởng có thể mang vào Đại Gia Đường Sắt để bổ sung Phiếu Thương Hội",
      [787323340015616] = "Vật phẩm được đề xuất có giá trị cao hơn; điều chỉnh đồ mang theo theo đề xuất tuần sẽ hiệu quả hơn",
      [787323340015872] = "Khi Lâu Đài nâng cấp, Đại Gia Đường Sắt có thể chọn tuyến khó hơn, rủi ro và lợi nhuận đều cao hơn",
      [787323340016128] = "Tuyến khó về sau tốn nhiều Giấy Phép hơn, nhưng phần thưởng khi hoàn thành hoàn hảo cũng cao hơn",
      [787323340016384] = "Nhấn để đến <Highlight>Nâng Cấp Lâu Đài</>.",
      [787323340016640] = "Khi đạt <Highlight>điều kiện nâng cấp Lâu Đài</>, <Highlight>tiêu hao</> đủ Tài Sản Lâu Đài để nâng cấp.",
      [787323340016896] = "Khi đủ mọi điều kiện, nhấn đây để nâng cấp Lâu Đài.",
      [787323340017152] = "Cũng có thể xây Lâu Đài bằng chức năng <Highlight>Mẫu</>; nhấn đây để vào.",
      [787323340017408] = "Đã mở chức năng Mẫu; nhấn để xem.",
      [787323340017664] = "Tại đây có thể <Highlight>xem, tham quan</> Mẫu; lưu xong có thể <Highlight>Áp Dụng</>.",
      [787323340017920] = "Nhấn đây để đến <Highlight>Quảng Trường Trang Trí</> và xem Mẫu do Phi Phàm Giả khác tải lên.",
      [787323340018176] = "Dùng nút Bắt Lấy để bắt chữ.",
      [787323340018688] = "Chuyển sang <Orange>Bản Đồ Thám Bí</>.",
      [787323340018944] = "Chuyển sang <Orange>Mặt Tối Thành Phố</>.",
      [787323340019200] = "<Orange>Mặt Tối Thành Phố</> sẽ xuất hiện nhiều sự kiện và thử thách.",
      [787323340019456] = "Chọn điểm dịch chuyển để đến <Orange>Tingen Tội Ác</>.",
      [787323340019712] = "Nhấn để đi.",
      [787323340019968] = "Đã mở <Orange>Cốt Truyện Thế Giới</>; nhấn để xem.",
      [787323340020480] = "Đã mở Cấp Thần Tính; nhấn để xem",
      [787323340020736] = "Nhấn nút để xem giải thích về cấp",
      [787323340020992] = "Tại đây xem quy tắc Cấp Thần Tính, gồm ngày mở khóa, hiệu suất nhận kinh nghiệm...",
      [787323340021248] = "Chọn chữ rồi dùng <Highlight>“Bắt Lấy”</>.",
      [787323340021504] = "Chọn câu rồi dùng <Highlight>“Ném Ra”</>.",
      [787323340022272] = "Dùng shotgun để nhanh chóng dọn kẻ địch",
      [787323340022784] = "Shotgun gây sát thương diện rộng lớn",
      [787323340023296] = "Nhấn <Highlight>nút Lật Trang</> đến <Highlight>trang thứ hai</>",
      [787323340023552] = "Liên tục nhấn <Highlight>nút Lật Trang</> đến <Highlight>trang cuối</>",
      [787323340024320] = "Dựng khiên để bảo vệ bản thân và đồng đội",
      [787323340024832] = "Đã mở Trợ Lý Hướng Dẫn; nhấn để xem.",
      [787323340025088] = "Nhấn đây để mở giao diện Trợ Lý Hướng Dẫn.",
      [787323340025344] = "Tại đây hiển thị các câu hỏi phổ biến của phiên bản hiện tại.",
      [787323340025600] = "Tại đây có thể chủ động hỏi Trợ Lý Hướng Dẫn.",
      [787323340025856] = "Đã mở hệ thống Gia Tộc; nhấn để xem.",
      [787323340026112] = "Nhấn đây để mở giao diện Gia Tộc.",
      [787323340026368] = "Nhấn đây để xem hiệu ứng cộng thêm xã hội; đội đủ điều kiện sẽ tự kích hoạt.",
      [787323340026624] = "Nhấn đây để <Orange>xem sự kiện có thể nhận</>.",
      [787323340026880] = "Đến <Orange>Đạn Nhuốm Máu · Ủy Thác</>.",
      [787323340027136] = "Mở menu.",
      [787323340027392] = "Mở <Highlight>Mặt Tối Thành Phố</>.",
      [787323340027648] = "Tại đây xem các sự kiện có thể tham gia trong <Highlight>Mặt Tối Thành Phố</>.",
      [787323340027904] = "Đóng giao diện.",
      [787323340028160] = "Nhấn đây để thoát Mặt Tối Thành Phố.",
      [787323340028416] = "Dùng súng ngắn có thể gây sát thương đơn mục tiêu lớn",
      [787323340028928] = "Mở giao diện cài đặt Cọc Tập.",
      [787323340029184] = "Nhấn để đổi tên Cọc Tập.",
      [787323340029440] = "Nhấn để chuyển mẫu thuộc tính quái của các Phó Bản khác nhau.",
      [787323340029696] = "Tại đây mở giao diện dùng thử dược phẩm trong Sân Tập.",
      [787323340029952] = "Tại đây chọn dược phẩm muốn dùng.",
      [787323340030208] = "Nhấn đây để lưu và áp dụng.",
      [787323340030464] = "Nhấn đây để lưu thiết lập tùy chỉnh Cọc Tập vừa chỉnh.",
      [787323340030720] = "Nhấn thẻ Giáo Đoàn để đổi Giáo Đoàn và xem lối chơi cùng thiên hướng thuộc tính tương ứng.",
      [787323340030976] = "Nhấn “Thuộc Tính” để xem và tùy chỉnh thuộc tính Khám Phá.",
      [787323340031232] = "Tại đây xem thuộc tính, Vật Phong Ấn và hiệu ứng Chúc Phúc của Giáo Đoàn hiện tại.",
      [787323340031488] = "Sau khi xác nhận lựa chọn, nhấn đây để gia nhập Giáo Đoàn.",
      [787323340031744] = "Mỗi tuần cần tuân thủ quy tắc Giáo Đoàn, hoàn thành nhiệm vụ chỉ định để chứng minh hành tích.",
      [787323340032000] = "Tham gia các lối chơi để nhận Điểm Hành Động, nâng cấp Giáo Đoàn và nhận thưởng.",
      [787323340033024] = "Nhấn để xem Ghi Chú.",
      [787323340033536] = "Ghi Chú đã cập nhật; nhấn để xem.",
      [787323340034560] = "Dùng năng lực Linh Tính để đổi góc quan sát.",
      [787323340035072] = "Nhấn nút này để tắt <Highlight>Chế Độ Cốt Truyện</>; cũng có thể tắt vĩnh viễn tại <Highlight>Cài Đặt - Góc Nhìn - Chế Độ Cốt Truyện Động</>",
      [787323340035328] = "Thông qua cải tạo Thần Chú, có thể thay đổi <Highlight>sơn xe, thân xe, lốp, biển số, động cơ</>.",
      [787323340035584] = "Mỗi lần cải tạo tăng <Highlight>Điểm Cải Tạo</>; khi <Highlight>Điểm Cải Tạo</> tích đủ, sẽ mở khóa bộ phận mới.",
      [787323340035840] = "Nhấn để xem trước phương án cải tạo cao cấp.",
      [787323340036096] = "Xem Hướng Dẫn để biết thêm quy tắc cải tạo.",
      [787323340036352] = "<Orange>Kỹ Năng Tạm Thời</> sẽ hiện tại đây; nhấn để kích hoạt",
      [787323340036608] = "Dùng kỹ năng <Highlight>Lumi Đại Hành</> để tạm thời giành quyền điều khiển cơ thể Lumi",
      [787323340037120] = "Dùng kỹ năng <Highlight>Cộng Hưởng</> để giải phong tỏa mảnh vỡ",
      [787323608371200] = "Nhấn <img id=\"KeyPrompt_W\" width=\"33\" height=\"38\"/> để tiến lên",
      [787323608371712] = "Nhấn <img id=\"KeyPrompt_W\" width=\"33\" height=\"38\"/><img id=\"KeyPrompt_A\" width=\"33\" height=\"38\"/><img id=\"KeyPrompt_S\" width=\"33\" height=\"38\"/><img id=\"KeyPrompt_D\" width=\"33\" height=\"38\"/> để di chuyển",
      [787323608372224] = "Nhấn đây hoặc <img id=\"KeyPrompt_V\" width=\"33\" height=\"38\"/> để hiện <Highlight>đường chỉ dẫn</>.",
      [787323608372480] = "Tại đây có thể bật/tắt <Orange>Chế Độ Cốt Truyện</> và đổi khoảng cách camera",
      [787323608372736] = "Dùng <img id=\"KeyPrompt_Tab\" width=\"51\" height=\"38\"/> để khóa mục tiêu!",
      [787323608373504] = "Nhấn đây hoặc <img id=\"KeyPrompt_LeftMouseButton\" width=\"33\" height=\"38\"/> để <Orange>tấn công</>.",
      [787323608373760] = "Nhấn đây hoặc <img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> để <Orange>dùng kỹ năng</>.",
      [787323608374016] = "Nhấn lại đây hoặc <img id=\"KeyPrompt_LeftMouseButton\" width=\"33\" height=\"38\"/> để <Orange>tấn công</>.",
      [787323608374272] = "Nhấn đây hoặc <img id=\"KeyPrompt_E\" width=\"33\" height=\"38\"/> để <Orange>tấn công</>.",
      [787323608374784] = "Nhấn lại đây hoặc <img id=\"KeyPrompt_E\" width=\"33\" height=\"38\"/> để <Orange>tấn công</>.",
      [787323608375808] = "Dùng <img id=\"KeyPrompt_Shift\" width=\"66\" height=\"38\"/> để né tránh",
      [787323608376064] = "Nhấn để <Orange>né tránh</>!",
      [787323608376320] = "Nhấn <img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>Phán Xét</>, <img id=\"KeyPrompt_4\" width=\"33\" height=\"38\"/> <Orange>Nhật Thệ</>, <img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>Cuồng Phủ</>, <img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>Tịnh Trảm</>, <img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>Trừng Phạt</> để hoàn thành combo",
      [787323608376576] = "Nhấn <img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>Động Sát</>, <img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>Linh Hoả</>, <img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>Dệt Mộng</>, <img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>Cuồng Loạn</> để hoàn thành combo",
      [787323608376832] = "Nhấn <img id=\"KeyPrompt_4\" width=\"33\" height=\"38\"/> <Orange>Ngu Phúc</>, <img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>Đạn Khí</>, <img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>Trận Tarot</>, <img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>Mưa Bài</>, <img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>Linh Bạo</> để hoàn thành combo",
      [787323608377088] = "Nhấn <img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>Phóng Trục</>, <img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>Thán Vân</>, <img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>Ảo Thuật</>, <img id=\"KeyPrompt_4\" width=\"33\" height=\"38\"/> <Orange>Xuyên Giới</>, <img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>Trùng Môn</> để hoàn thành combo",
      [787323608377344] = "Nhấn <img id=\"KeyPrompt_4\" width=\"33\" height=\"38\"/> <Orange>Quang Trảm</>, <img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>Liệp Ma Trảm</>, <img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>Nộ Ý Kích</>, <img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>Cuồng Phong</>, <img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>Quang Bạo</> để hoàn thành combo",
      [787323608377600] = "Nhấn <img id=\"KeyPrompt_4\" width=\"33\" height=\"38\"/> <Orange>Hoàng Y</>, <img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>Trí Nhân</>, <img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>Quang Khúc</>, <img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>Tinh Sa</>, <img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>Tin Tuyến</> để hoàn thành combo",
      [787323608380416] = "Nhấn hoặc <img id=\"KeyPrompt_MiddleMouseButton\" width=\"33\" height=\"41\"/> để mở <Orange>Linh Thị</>, tìm mục tiêu phát sáng.",
