      [787323608385024] = "Nhấn dòng Ân Tứ để xem các dòng có thể thay thế.",
      [787323608386816] = "Nhấn <Highlight>Tịnh Hóa</> để tịnh hóa",
      [787323608387072] = "Nhấn để xem các hiệu ứng Tụ Hợp có thể chuyển.",
      [787323608399104] = "Nhấn đây để mở giao diện <Highlight>Kiến Tạo Kỳ Tích</>.",
