      [787323608436480] = "Tốn xu vàng để dùng Phi Ném, gây sát thương lớn lên quái thường",
      [787323608437248] = "Khi <Highlight>vòng xanh</> xuất hiện, nhấn <Highlight>Z</> hoặc nhấn đây dùng <Orange>Đạn Liệp Ma</> để phản kích!",
      [787323608437760] = "Khi <Highlight>vòng xanh</> xuất hiện, nhấn đây dùng <Orange>Đạn Liệp Ma</> để phản kích!",
      [787323608442368] = "Tại đây xem thêm chi tiết lối chơi",
      [787323608445184] = "Nhấn đây để <Highlight>Hưởng Ứng</> việc tạo Câu Lạc Bộ.",
      [787323608445440] = "Nhấn đây hoặc <img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> để <Orange>vào chế độ ngắm</>.",
      [787323608445696] = "Ngắm kẻ địch trước, rồi nhấn đây để <Orange>bắn</>.",
      [787323608446976] = "Nhấn <Highlight>Tiến Độ Hoàn Thành</> để xem chi tiết danh sách lối chơi trên bản đồ và tiến độ",
