      [787323608447488] = "Nhấn để dùng <Orange>Bắn Chỉ Thiên</>.",
      [787323608448256] = "Nhấn <Highlight>Thế Giới Trật Tự</> để xem nội dung có thể chơi; tăng Tiến Độ Hoàn Thành để mở Thiên Phú Thám Bí.",
      [787323608452864] = "Nhấn để xem <Highlight>Mẫu</>.",
      [787323608457728] = "Nhấn đây hoặc <img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> để dùng <Orange>Shotgun</>.",
      [787323608457984] = "Nhấn để dùng <Orange>Shotgun</>.",
