      [611536234087936] = "Xem thử.",
      [611536234088192] = "Nhận từ phó bản; có thể nhận trang bị tương ứng với khoảng cấp.",
      [611536234088960] = "Nhận từ phó bản; có thể nhận trang bị khoảng cấp 30.",
      [611536234089728] = "Xấp này có 10000 Soli Khóa.",
      [611536234089984] = "Thùng này có 60000 Soli.",
      [611536234090240] = "Mỗi ngày cung cấp một ít vật liệu.",
      [611536234090752] = "Chiếc rương đồng chẳng ai không thích. Dùng xong nhận trang bị phù hợp cho Ca Tụng Giả, đủ để ứng phó những tình huống có chút độ khó.",
      [611536234091008] = "Chiếc rương đồng chẳng ai không thích. Dùng xong nhận trang bị phù hợp cho Khán Giả, đủ để ứng phó những tình huống có chút độ khó.",
      [611536234091264] = "Chiếc rương đồng chẳng ai không thích. Dùng xong nhận trang bị phù hợp cho Thầy Bói, đủ để ứng phó những tình huống có chút độ khó.",
      [611536234091520] = "Chiếc rương đồng chẳng ai không thích. Dùng xong nhận trang bị phù hợp cho Học Đồ, đủ để ứng phó những tình huống có chút độ khó.",
      [611536234091776] = "Chiếc rương đồng chẳng ai không thích. Dùng xong nhận trang bị phù hợp cho Chiến Sĩ, đủ để ứng phó những tình huống có chút độ khó.",
      [611536234092032] = "Chiếc rương đồng chẳng ai không thích. Dùng xong nhận trang bị phù hợp cho Kẻ Dòm Ngó Bí Ẩn, đủ để ứng phó những tình huống có chút độ khó.",
      [611536234092288] = "Chiếc rương bạc chẳng ai không thích. Dùng xong nhận trang bị thích hợp mang vào phó bản, đủ để ứng phó những tình huống khá khó... chắc vậy.",
      [611536234093824] = "Chiếc rương do Arrodes ban tặng, bên trong có một số vật liệu chế dược.",
      [611536234094080] = "Sau khi dùng, có thể chọn nhận một trong các Hình Chiếu Lịch Sử Nhân Mạch sau.",
      [611536234096128] = "Mở ra nhận 30000 Soli Khóa và tăng 100 Linh Tính; có thể cộng dồn vượt giới hạn. Khi vượt giới hạn, Sức Sống sẽ không còn tự hồi theo thời gian.",
      [611536234097408] = "Ngẫu nhiên nhận vật chất Phi Phàm phẩm chất Vàng có 1–2 dòng thuộc tính; xác suất xuất hiện dòng Quý Phẩm tăng mạnh.",
      [611536234097664] = "Ngẫu nhiên nhận vật chất Phi Phàm phẩm chất Vàng có 1–2 dòng thuộc tính; chắc chắn là dòng Quý Phẩm.",
      [611536234097920] = "Ngẫu nhiên nhận vật chất Phi Phàm phẩm chất Tím có 1–2 dòng thuộc tính.",
      [611536234098176] = "Ngẫu nhiên nhận vật chất Phi Phàm phẩm chất Vàng có 1–2 dòng thuộc tính.",
      [611536234098688] = "Mua là nhận ngay <Highlight>300</> Bảng Vàng và <Highlight>2</> Khối Đường Sức Sống, đồng thời nhận <Highlight>30</> ngày giải đọc vận thế bằng Phiếu Phúc Âm cùng các đặc quyền như <Highlight>tăng số lần tương tác nhanh Nhân Mạch</>, <Highlight>tăng hiệu suất nhận tiền tệ lối chơi</>, <Highlight>tùy chỉnh mốc dịch chuyển</>, <Highlight>tăng giới hạn Sức Sống</>.\nĐăng nhập mỗi ngày nhận <Highlight>100</> Bảng Vàng Khóa; tích lũy đăng nhập còn nhận thêm nhiều <Highlight>Khối Đường Sức Sống</>.",
      [611536234098944] = "Sau khi mua sẽ mở khóa bản Cao Cấp của <Highlight>Quà Tặng Vận Mệnh</>, nhận các đặc quyền như tăng hiệu suất nhận chứng từ hóa đơn, tăng giới hạn số ô túi, cùng nhiều phần thưởng theo cấp như thời trang giới hạn, phụ kiện giới hạn, Chén Thánh · Khóa và vật liệu nhuộm.",
      [611536234099200] = "Sau khi mua sẽ mở khóa bản Sưu Tầm của <Highlight>Quà Tặng Vận Mệnh</>, nhận toàn bộ phần thưởng bản Cao Cấp, đồng thời tăng thẳng 15 cấp và nhận ngay thêm Chén Thánh · Khóa, Bảng Vàng Khóa, Tinh Thạch Chuyển Vận cùng nhiều phần thưởng khác.",
      [611536234099456] = "Sau khi dùng có xác suất nhận trang bị Vàng Cấp Trang Bị 35.",
      [611536234102528] = "Sau khi mua nhận các vật phẩm: <Highlight>Ba Lô Khỉ Đầu Chó Bạc</>, <Highlight>Xã Giao · Dẫn Bóng</>, <Highlight>Danh Hiệu · Bạn Của Khỉ Đầu Chó</> và 1 <Highlight>Khối Đường Sức Sống</>.",
      [611536234102784] = "Sau khi mua nhận: thời trang · <Highlight>Trong Gió Chiều</> và 1 <Highlight>Khối Đường Sức Sống</>.",
      [611536234103040] = "Sau khi mua nhận: kiểu tóc · <Highlight>Tự Nhiên Mềm Mượt</>, phụ kiện · <Highlight>Sổ Tay Da Cứng Thần Bí</>, động tác chờ · <Highlight>Ca Ngợi Kẻ Khờ</> và 1 <Highlight>Khối Đường Sức Sống</>.",
      [611536234103296] = "Nhận các vật phẩm sau.",
      [611536234105600] = "Sau khi mua có thể nâng bản Cao Cấp của <Highlight>Quà Tặng Vận Mệnh</> lên bản Sưu Tầm; nhận toàn bộ phần thưởng bản Cao Cấp, tăng thẳng 15 cấp và nhận ngay thêm Chén Thánh · Khóa, Bảng Vàng Khóa, Tinh Thạch Chuyển Vận cùng nhiều phần thưởng khác.",
      [611536234105856] = "Sau khi dùng nhận 2 <Highlight>Tinh Thạch Chuyển Vận</>, đồng thời có xác suất nhận thêm 1 <Highlight>Chén Thánh · Khóa</>.",
      [611536234106112] = "Sau khi dùng nhận trang phục Bậc của Con Đường tương ứng (30 ngày); sau khi thăng lên Bậc 8 có thể nâng thành trang phục vĩnh viễn.",
      [611536234106368] = "Tham gia phó bản <Highlight>Bút Ký Antigonus (Thường)</>, có xác suất nhận các ngoại hình sau.",
      [611536234106624] = "Tham gia phó bản <Highlight>Bút Ký Antigonus (Thường)</>, có xác suất nhận <Highlight>Cấp Trang Bị 55~60</> <Highlight>Trang Bị Khắc Ấn Phẩm Chất Vàng</>.",
      [611536234106880] = "Tham gia phó bản một mình <Highlight>Bút Ký Antigonus (Thường)</>, có xác suất nhận <Highlight>Cấp Trang Bị 55~60</> <Highlight>Trang Bị Khắc Ấn bị ô nhiễm Phẩm Chất Vàng</>.",
      [611536234107136] = "Tham gia phó bản <Highlight>Bút Ký Antigonus (Thường)</>, có xác suất nhận <Highlight>Cấp Trang Bị 55~60</> <Highlight>Trang Bị Phẩm Chất Vàng~Cam</>.",
