      [611536234173184] = "<Highlight>Chưa hoàn thiện, giữ chỗ</>. Tham gia phó bản <Highlight>Đại Đế Roselle (Thường)</>, có xác suất nhận các ngoại hình sau.",
      [611536234173440] = "Tham gia phó bản <Highlight>Đại Đế Roselle (Thường)</>, có xác suất nhận các trang bị sau.",
      [611536234173696] = "Tham gia phó bản <Highlight>Đại Đế Roselle (Thường)</>, có xác suất nhận các vật phẩm sau.",
      [611536234173952] = "<Highlight>Chưa hoàn thiện, giữ chỗ</>. Tham gia phó bản ở chế độ tổ đội <Highlight>Đại Đế Roselle (Thường)</>, có thể tham gia phân phối và đấu giá vật phẩm rơi chung. Có xác suất nhận các ngoại hình sau.",
      [611536234174208] = "Tham gia phó bản ở chế độ tổ đội <Highlight>Đại Đế Roselle (Thường)</>, có thể tham gia phân phối và đấu giá vật phẩm rơi chung. Có xác suất nhận trang bị có thể giao dịch.",
      [611536234174464] = "Tham gia phó bản ở chế độ tổ đội <Highlight>Đại Đế Roselle (Thường)</>, có thể tham gia phân phối và đấu giá vật phẩm rơi chung. Có xác suất nhận vật phẩm có thể giao dịch.",
      [611536234174720] = "<Highlight>Chưa hoàn thiện, giữ chỗ</>. Tham gia phó bản <Highlight>Đại Đế Roselle (Anh Hùng)</>, có xác suất nhận các ngoại hình sau.",
      [611536234174976] = "Tham gia phó bản <Highlight>Đại Đế Roselle (Anh Hùng)</>, có xác suất nhận các trang bị sau.",
      [611536234175232] = "Tham gia phó bản <Highlight>Đại Đế Roselle (Anh Hùng)</>, có xác suất nhận các vật phẩm sau.",
      [611536234175488] = "<Highlight>Chưa hoàn thiện, giữ chỗ</>. Tham gia phó bản ở chế độ tổ đội <Highlight>Đại Đế Roselle (Anh Hùng)</>, có thể tham gia phân phối và đấu giá vật phẩm rơi chung. Có xác suất nhận các ngoại hình sau.",
      [611536234175744] = "Tham gia phó bản ở chế độ tổ đội <Highlight>Đại Đế Roselle (Anh Hùng)</>, có thể tham gia phân phối và đấu giá vật phẩm rơi chung. Có xác suất nhận trang bị có thể giao dịch.",
      [611536234176000] = "Tham gia phó bản ở chế độ tổ đội <Highlight>Đại Đế Roselle (Anh Hùng)</>, có thể tham gia phân phối và đấu giá vật phẩm rơi chung. Có xác suất nhận vật phẩm có thể giao dịch.",
      [611536234176256] = "Có xác suất nhận các vật phẩm sau.",
      [611536234177792] = "Sau khi dùng, tự động nhận các bộ phận ngoại hình sau theo giới tính.",
      [611536234178816] = "Trải nghiệm phó bản, thi đấu, khám phá và các lối chơi khác để nhận trang bị.",
      [611536234179072] = "Sau khi dùng, nhận điểm dùng để tăng cấp Kỹ Năng Chiến Đấu, Kỹ Năng Bí Ngẫu và Kỹ Năng Nhân Mạch.",
      [611536234179328] = "Lời cảm ơn nhận được sau khi hoàn thành cống hiến.\nNhững gì bạn bỏ ra đã được ghi nhớ; đây là quà tặng tất yếu mà vận mệnh trao lại.",
      [611536234179584] = "Sau khi dùng, nhận 1 trang bị Vàng Cấp Trang Bị 35; hệ thống dựa trên trang bị đang mặc để cấp món có mức tăng cao nhất.",
      [611536234180864] = "Sau khi dùng, nhận 5 Nhân Tố Tụ Hợp, có thể dùng để tụ hợp vật liệu Phi Phàm.",
      [611536234181120] = "Ngẫu nhiên nhận vật chất Phi Phàm Vàng <Highlight>có thể giao dịch</> với 1–2 dòng thuộc tính; xác suất xuất hiện dòng Quý Phẩm tăng mạnh.",
      [611536234181376] = "Ngẫu nhiên nhận vật chất Phi Phàm Vàng <Highlight>có thể giao dịch</> với 1–2 dòng thuộc tính; chắc chắn là dòng Quý Phẩm.",
      [611536234181632] = "Ngẫu nhiên nhận vật chất Phi Phàm phẩm chất Vàng <Highlight>có thể giao dịch</> với 1–2 dòng thuộc tính.",
      [611536234181888] = "Nhận 10000 Soli Khóa. Tờ tiền xanh sẫm bạc màu, một loại tiền khá phổ biến trong hệ thống tiền tệ của Vương quốc Loen.",
      [611536234182144] = "Nhận 500 Soli Khóa. Tờ tiền xanh sẫm bạc màu, một loại tiền khá phổ biến trong hệ thống tiền tệ của Vương quốc Loen.",
      [611536234182400] = "Sau khi dùng, ngẫu nhiên nhận một trang bị bậc cao.",
      [611536234183680] = "Trải nghiệm các lối chơi để nhận Vật Phong Ấn.",
      [611536234184704] = "Sau khi dùng, nhận Danh Hiệu · Nhân Chứng Tingen.",
      [611536234185216] = "Sau khi dùng, mở khóa <Highlight>Động Tác Đơn · Vui Mừng</>; nếu nhận trùng rồi sử dụng, tự động phân giải thành Soli Khóa.",
      [611536234185472] = "Sau khi dùng, mở khóa <Highlight>Động Tác Đơn · Cổ Vũ</>; nếu nhận trùng rồi sử dụng, tự động phân giải thành Soli Khóa.",
      [611536234185728] = "Sau khi dùng, mở khóa <Highlight>Động Tác Đơn · Sợ Hãi</>; nếu nhận trùng rồi sử dụng, tự động phân giải thành Soli Khóa.",
      [611536234185984] = "Sau khi dùng, mở khóa <Highlight>Động Tác Đơn · Cầu Nguyện</>; nếu nhận trùng rồi sử dụng, tự động phân giải thành Soli Khóa.",
