      [611536234293248] = "Mở ra có thể tự chọn nhận trang bị Lạc Ấn Cam <Highlight>Cấp Trang Bị 66</> với <Highlight>Thiên Hướng Thi Đấu</>.",
      [611536234293504] = "Mở ra có thể tự chọn nhận trang bị Lạc Ấn Cam <Highlight>Cấp Trang Bị 68</> với <Highlight>Thiên Hướng Thi Đấu</>.",
      [611536234293760] = "Ngẫu nhiên nhận Vật Chất Tấn Công hoặc Vật Chất Phòng Thủ phẩm chất Vàng <Highlight>có thể giao dịch</> với 1–2 dòng thuộc tính; xác suất xuất hiện dòng Trân Phẩm tăng mạnh.",
      [611536234294016] = "Mở ra ngẫu nhiên nhận 1 Vật Chất Phi Phàm phẩm chất Vàng <Highlight>không thể giao dịch</> với 1–2 dòng thuộc tính; chắc chắn có dòng Trân Phẩm.",
      [611536234294272] = "Ngẫu nhiên nhận Vật Chất Tấn Công hoặc Vật Chất Phòng Thủ phẩm chất Vàng <Highlight>có thể giao dịch</> với 1–2 dòng thuộc tính; chắc chắn có dòng Trân Phẩm.",
      [611536234294528] = "Mở ra có thể tự chọn nhận <Highlight>Vật Chất Dị Biến</> mang một trong các dòng <Highlight>〈Hộ Vệ Giả〉</>, <Highlight>〈Vô Ám Giả〉</>, <Highlight>〈Kẻ Xúi Giục〉</>, <Highlight>〈Võ Đấu Gia〉</>.",
      [611536234294784] = "Mở ra có thể tự chọn nhận <Highlight>Vật Chất Dị Biến</> mang một trong các dòng <Highlight>〈Kẻ Thu Hoạch〉</>, <Highlight>〈Phong Quyến Giả〉</>, <Highlight>〈Nhà Thôi Miên〉</>, <Highlight>〈Thông Linh Giả〉</>.",
      [611536234295040] = "Mở ra có thể tự chọn nhận <Highlight>Vật Chất Dị Biến</> mang một trong các dòng <Highlight>〈Hoang Vu Chủ Mẫu〉</>, <Highlight>〈Kẻ Hầu Bí Ẩn〉</>, <Highlight>〈Hành Giả Hỗn Loạn〉</>, <Highlight>〈Môn Đồ Trầm Mặc〉</>.",
      [611536234295296] = "Mở ra có thể tự chọn nhận <Highlight>Vật Chất Dị Biến</> mang một trong các dòng <Highlight>〈Giám Mục Chiến Tranh〉</>, <Highlight>〈Giám Mục Sợ Hãi〉</>, <Highlight>〈Bàn Tay Thần Minh〉</>, <Highlight>〈Hóa Thân Thiên Tai〉</>.",
      [611536234295552] = "Mở ra nhận <Highlight>Vật Chất Dị Biến</> Phòng Thủ mang dòng <Highlight>〈Kẻ Khờ〉</>.",
      [611536234295808] = "Mở ra nhận <Highlight>Vật Chất Dị Biến</> Tấn Công mang dòng <Highlight>〈Kẻ Khờ〉</>.",
      [611536234296064] = "<Highlight>Vật Chất Dị Biến</> Tấn Công mang dòng <Highlight>〈Kẻ Khờ〉</>: “Vô hiệu hiệu ứng tiêu cực của Vật Phong Ấn, cấp mọi kỹ năng +1, tăng Khuếch Thương.”",
      [611536234296320] = "<Highlight>Vật Chất Dị Biến</> Tấn Công mang dòng <Highlight>〈Giám Mục Chiến Tranh〉</>: “Cấp mọi kỹ năng +1, tăng Tấn Công.”",
      [611536234296576] = "<Highlight>Vật Chất Dị Biến</> Tấn Công mang dòng <Highlight>〈Giám Mục Sợ Hãi〉</>: “Cấp mọi kỹ năng +1, tăng Cường Hóa Kỹ Năng.”",
      [611536234296832] = "<Highlight>Vật Chất Dị Biến</> Tấn Công mang dòng <Highlight>〈Bàn Tay Thần Minh〉</>: “Cấp mọi kỹ năng +1, tăng Phá Phòng.”",
      [611536234297088] = "<Highlight>Vật Chất Dị Biến</> Tấn Công mang dòng <Highlight>〈Hóa Thân Thiên Tai〉</>: “Cấp mọi kỹ năng +1, tăng Bạo Kích.”",
      [611536234297344] = "<Highlight>Vật Chất Dị Biến</> Tấn Công mang dòng <Highlight>〈Kẻ Thu Hoạch〉</>: “Tăng Sức Mạnh/Trí Tuệ.”",
      [611536234297600] = "<Highlight>Vật Chất Dị Biến</> Tấn Công mang dòng <Highlight>〈Phong Quyến Giả〉</>: “Tăng Nhanh Nhẹn.”",
      [611536234297856] = "<Highlight>Vật Chất Dị Biến</> Tấn Công mang dòng <Highlight>〈Nhà Thôi Miên〉</>: “Tăng Chính Xác Khống Chế.”",
      [611536234298112] = "<Highlight>Vật Chất Dị Biến</> Tấn Công mang dòng <Highlight>〈Thông Linh Giả〉</>: “Tăng Xuyên Thấu.”",
      [611536234298368] = "<Highlight>Vật Chất Dị Biến</> Phòng Thủ mang dòng <Highlight>〈Kẻ Khờ〉</>: “Vô hiệu hiệu ứng tiêu cực của Vật Phong Ấn, cấp mọi kỹ năng +1, tăng hiệu quả Súc Thương.”",
      [611536234298624] = "<Highlight>Vật Chất Dị Biến</> Phòng Thủ mang dòng <Highlight>〈Hoang Vu Chủ Mẫu〉</>: “Cấp mọi kỹ năng +1, tăng Phòng Thủ.”",
      [611536234298880] = "<Highlight>Vật Chất Dị Biến</> Phòng Thủ mang dòng <Highlight>〈Kẻ Hầu Bí Ẩn〉</>: “Cấp mọi kỹ năng +1, tăng Đỡ Kỹ Năng.”",
      [611536234299136] = "<Highlight>Vật Chất Dị Biến</> Phòng Thủ mang dòng <Highlight>〈Hành Giả Hỗn Loạn〉</>: “Cấp mọi kỹ năng +1, tăng Sinh Mệnh.”",
      [611536234299392] = "<Highlight>Vật Chất Dị Biến</> Phòng Thủ mang dòng <Highlight>〈Môn Đồ Trầm Mặc〉</>: “Cấp mọi kỹ năng +1, tăng Kháng Bạo Kích.”",
      [611536234299648] = "<Highlight>Vật Chất Dị Biến</> Phòng Thủ mang dòng <Highlight>〈Hộ Vệ Giả〉</>: “Tăng Thể Chất.”",
      [611536234299904] = "<Highlight>Vật Chất Dị Biến</> Phòng Thủ mang dòng <Highlight>〈Vô Ám Giả〉</>: “Tăng Ý Chí.”",
      [611536234300160] = "<Highlight>Vật Chất Dị Biến</> Phòng Thủ mang dòng <Highlight>〈Kẻ Xúi Giục〉</>: “Tăng Né Khống Chế.”",
      [611536234300416] = "<Highlight>Vật Chất Dị Biến</> Phòng Thủ mang dòng <Highlight>〈Võ Đấu Gia〉</>: “Tăng Đỡ Đòn.”",
      [611536234300672] = "Mở ra ngẫu nhiên nhận 1 trang bị Vàng <Highlight>Cấp Trang Bị 35</> với <Highlight>Thiên Hướng Thi Đấu</>.",
      [611536234300928] = "Mở ra ngẫu nhiên nhận 1 trang bị Vàng <Highlight>Cấp Trang Bị 45</> với <Highlight>Thiên Hướng Thi Đấu</>.",
      [611536234301184] = "Mở ra ngẫu nhiên nhận 1 trang bị Vàng <Highlight>Cấp Trang Bị 55</> với <Highlight>Thiên Hướng Thi Đấu</>.",
      [611536234301440] = "Khi trong tuần chưa đạt giới hạn nhận, mở ra nhận 1 Sỏi Tinh Sương Xám.\nSỏi Tinh Sương Xám là vật liệu then chốt để rèn Trâm Ngực phẩm chất Thần Thoại <Highlight>(Thiên Hướng Thi Đấu)</>.\n\nRèn cần tiêu hao <Highlight>15</> Sỏi Tinh Sương Xám, nhận Trâm Ngực Thần Thoại Cấp Trang Bị 64 <Highlight>Thiên Hướng Thi Đấu</>.\nTheo tiến trình mùa giải sẽ mở nâng Cấp Trang Bị cho Trâm Ngực Thần Thoại Thi Đấu; khi nâng tiêu hao một lượng <Highlight>Sỏi Tinh Sương Xám</>.\n\nMỗi tuần có thể <Highlight>nhận trực tiếp</> tối đa <Highlight>3</> Sỏi Tinh Sương Xám từ Săn Giết Tận Cùng, Giải Liên Đấu Tứ Phương, Chiến Thành/Chiến Cao Nguyên và Bí Bảo Lấy Chiến Nuôi Chiến. Số chưa nhận được cộng dồn sang tuần sau, tối đa <Highlight>15</>.",
      [611536502525440] = "Loại tiền tệ mới được phát hành sau khi Govington II kế vị. Sau cuộc cải cách, thu nhập bình quân của người dân Loen nghe có vẻ đã tăng lên không ít.",
      [611536502526208] = "Rương báu, tương truyền ẩn chứa sức mạnh kỳ diệu.",
      [611536502529280] = "Tên gọi dược phẩm qua thời gian đã được chuyển dịch, từ lâu không còn giống thuở ban đầu. Quan trọng hơn là thử tái hiện “biểu tượng cốt lõi” của dược phẩm thông qua tổ hợp nguyên liệu.",
      [611536502531584] = "Quà tặng từ Kẻ Khờ.",
      [611536502534144] = "Chế độ phúc lợi do tín đồ Giáo Hội Kẻ Khờ lập ra. Cảm ơn mọi giới đã ủng hộ Giáo Hội Kẻ Khờ.\nHãy lắng nghe «Thánh Điển Kẻ Khờ», ca ngợi Kẻ Khờ! Nguyện ân điển của Ngài ngày đêm ở bên bạn, trở thành ngọn đèn không bao giờ tắt trên con đường phía trước!",
      [611536502592512] = "Trông vuông vuông, nếm ngọt ngọt, ăn xong tràn đầy động lực!",
      [611536502635776] = "Phần lớn lời cầu xin chỉ chìm vào im lặng. Nhưng nếu Ngài thật sự đáp lại, vật tầm thường cũng sẽ có giá trị gần như thần tích.",
      [611536502703616] = "Khi quản lý mở kho tiền, bạn lịch sự hỏi: “Có thể nhét được bao nhiêu thì lấy bấy nhiêu, đúng không?”",
      [611536502704128] = "Máy tính tiền “hỏng” rồi; két tiền tự mọc chân chạy vào tay bạn. Thật kỳ lạ.",
      [611536502705408] = "Tay nghề nhập môn của Đêm Cuồng Hoan — vốn nằm trong túi quần sau, trông đủ để uống vài ly.",
      [611536502706688] = "Đường phố Đêm Cuồng Hoan chẳng bao giờ thiếu bất ngờ. Đêm nay, cả thành phố là giỏ hàng của bạn.",
      [611606832703744] = "Chiếc ví do tiểu thư “Chính Nghĩa” tặng, nặng trĩu, bên trong chứa một khoản tiền không nhỏ.",
    },
    ["itemlife"] = {
      [273369299683328] = "Ma Dược thần bí đến từ phía trên Sương Xám, có thể hồi 50% Sinh Mệnh Tối Đa trong Nhà Hát Utopia. Sau khi mua, hãy vào tab 【Túi Lối Chơi】 trong túi đồ để xem và sử dụng; khuyến nghị trang bị vào phím tắt.",
      [611536234244096] = "Nhận 100.000 Tài Sản Lâu Đài, có thể dùng nâng cấp Lâu Đài và mua nội thất.",
      [611606832705536] = "Bày hoa ra rồi cầu cô ấy đồng ý đi!",
      [611606832718080] = "Rượu nâu cháy cuộn bọt thô, hương mạch nha lẫn mùi hun khói; nuốt xuống còn để lại hậu vị ngọt.",
      [611673673041408] = "Sau khi dùng, tại cảnh 5209996 biến thành Cảnh Sát hoặc Chổi; ở Tingen chỉ biến thành Cảnh Sát.",
      [611673673041664] = "Sau khi dùng, lập tức hồi 30% Máu cho người Phi Phàm.",
      [611673673041920] = "Dược liệu thường gặp, có thể dùng để chế tạo dược phẩm.",
      [611673673045248] = "Nước suối từ đảo Sonia, từng là thứ các Tinh Linh yêu thích; tính chất ôn hòa, thường dùng pha chế nhiều loại dược phẩm.",
      [611673673045504] = "Tăng nhẹ Tấn Công.",
      [611673673045760] = "Sau khi dùng, người chơi nhận hiệu ứng di chuyển Hương Thơm đặc biệt, kéo dài 120 giây.",
      [611673673047296] = "Có thể dùng khi Cấp Nhập Vai đạt 19; hồi 5 Sinh Mệnh mỗi giây trong 60 giây.",
      [611673673047552] = "Có thể dùng khi Cấp Nhập Vai đạt 40; hồi 10 Sinh Mệnh mỗi giây trong 60 giây.",
      [611673673047808] = "Có thể dùng khi Cấp Nhập Vai đạt 60; hồi 15 Sinh Mệnh mỗi giây trong 60 giây.",
      [611673673048064] = "Có thể dùng khi Cấp Nhập Vai đạt 19; dùng xong lập tức hồi 100 Sinh Mệnh.",
      [611673673048320] = "Có thể dùng khi Cấp Nhập Vai đạt 40; dùng xong lập tức hồi 300 Sinh Mệnh.",
      [611673673048576] = "Có thể dùng khi Cấp Nhập Vai đạt 60; dùng xong lập tức hồi 700 Sinh Mệnh.",
      [611673673048832] = "Có thể dùng khi Cấp Nhập Vai đạt 40; tăng 2 điểm toàn bộ Năm Thuộc Tính trong 1800 giây. (Tối đa 2 loại Dược Thuộc Tính cùng có hiệu lực)",
      [611673673049088] = "Có thể dùng khi Cấp Nhập Vai đạt 50; tăng 3 điểm toàn bộ Năm Thuộc Tính trong 1800 giây. (Tối đa 2 loại Dược Thuộc Tính cùng có hiệu lực)",
      [611673673049344] = "Có thể dùng khi Cấp Nhập Vai đạt 60; tăng 4 điểm toàn bộ Năm Thuộc Tính trong 1800 giây. (Tối đa 2 loại Dược Thuộc Tính cùng có hiệu lực)",
      [611673673049600] = "Có thể dùng khi Cấp Nhập Vai đạt 40; tăng 10 Tấn Công và 2 Tăng Cường Kỹ Năng trong 1800 giây. (Tối đa 2 loại Dược Thuộc Tính cùng có hiệu lực)",
      [611673673049856] = "Có thể dùng khi Cấp Nhập Vai đạt 50; tăng 15 Tấn Công và 3 Tăng Cường Kỹ Năng trong 1800 giây. (Tối đa 2 loại Dược Thuộc Tính cùng có hiệu lực)",
      [611673673050112] = "Có thể dùng khi Cấp Nhập Vai đạt 60; tăng 25 Tấn Công và 5 Tăng Cường Kỹ Năng trong 1800 giây. (Tối đa 2 loại Dược Thuộc Tính cùng có hiệu lực)",
      [611673673050368] = "Nguyện Nữ Thần phù hộ bạn.",
      [611673673051392] = "Có thể dùng khi Cấp Nhập Vai đạt 19; dùng xong lập tức hồi 50 Sinh Mệnh.",
      [611673673052160] = "Lập tức hồi 30% Máu cho người chơi.",
      [611673673052416] = "Có thể dùng khi Cấp Nhập Vai đạt 70; hồi 20 Sinh Mệnh mỗi giây trong 60 giây.",
      [611673673052672] = "Có thể dùng khi Cấp Thần Tính đạt 20; hồi 30 Sinh Mệnh mỗi giây trong 60 giây.",
      [611673673052928] = "Có thể dùng khi Cấp Nhập Vai đạt 70; dùng xong lập tức hồi 1400 Sinh Mệnh.",
      [611673673053184] = "Có thể dùng khi Cấp Thần Tính đạt 20; dùng xong lập tức hồi 2500 Sinh Mệnh.",
      [611673673053440] = "Có thể dùng khi Cấp Nhập Vai đạt 70; tăng 5 điểm toàn bộ Năm Thuộc Tính trong 1800 giây. (Tối đa 2 loại Dược Thuộc Tính cùng có hiệu lực)",
      [611673673053696] = "Có thể dùng khi Cấp Thần Tính đạt 20; tăng 8 điểm toàn bộ Năm Thuộc Tính trong 1800 giây. (Tối đa 2 loại Dược Thuộc Tính cùng có hiệu lực)",
      [611673673053952] = "Có thể dùng khi Cấp Nhập Vai đạt 70; tăng 40 Tấn Công và 8 Tăng Cường Kỹ Năng trong 1800 giây. (Tối đa 2 loại Dược Thuộc Tính cùng có hiệu lực)",
      [611673673054208] = "Có thể dùng khi Cấp Thần Tính đạt 20; tăng 60 Tấn Công và 12 Tăng Cường Kỹ Năng trong 1800 giây. (Tối đa 2 loại Dược Thuộc Tính cùng có hiệu lực)",
      [611673673054720] = "Sau khi dùng nhận nội thất.",
      [611673673062912] = "Sau khi dùng nhận Sàn · Xây Đá ×10.",
      [611673673063168] = "Nhận 30.000 Tài Sản Lâu Đài, có thể dùng nâng cấp Lâu Đài và mua nội thất.",
      [611673673072896] = "Chỗ giữ đạo cụ.",
      [611673673075200] = "Đến gần sẽ rơi ra.",
      [611673673080832] = "Dược Thủy.",
      [611673941476864] = "Vị ngọt thanh sảng khoái như nước có ga; trong thời gian hiệu lực có thể tạm thời thay đổi ngoại hình. Người phát minh từng cảnh báo: đây là một giấc mộng đẹp rồi sẽ tỉnh, đừng quá chìm đắm.",
      [611673941477120] = "Nguyện Nữ Thần Đêm Tối phù hộ bạn.",
      [611673941480960] = "“Nếu nhà máy tinh dầu là thảo nguyên của tôi, thì một cốc cà phê mỗi sáng chính là chiếc roi thúc tôi tiến lên.”",
      [611673941481216] = "Một loại nước hoa hương gỗ ít người biết, chất lỏng đen tuyền nhưng mùi hương độc đáo.",
      [611673941481472] = "Đúng như tên gọi, hương đầu, giữa và cuối đều là hương trà xanh thuần túy. Vì được nhiều phụ nữ khéo léo lấy lòng đôi bên sử dụng nên bị một số người khinh miệt.",
      [611673941481728] = "Lấy cảm hứng từ phu nhân Sharon nổi danh giới giao tế; sau khi bà hương tiêu ngọc vẫn, người tình đã thiết kế nó để tưởng niệm.",
      [611673941482752] = "Một miếng bánh mì nhỏ bổ dưỡng và ngon miệng, vừa no bụng vừa chữa lành vết thương.",
      [611673941483008] = "Một phần bánh mì đầy đủ, bổ dưỡng và ngon miệng; ngọt thơm dễ ăn, no bụng mới có tinh thần!",
      [611673941483264] = "Phần bánh mì lớn thịnh soạn, bổ dưỡng, được nướng bằng nghi thức đặc biệt, mang tới sinh lực dồi dào!",
      [611673941483520] = "Dược Trị Liệu do Dược Sư pha chế, giá không cao, hiệu quả tốt, rất được người Phi Phàm ưa chuộng.",
      [611673941483776] = "Dược này vào miệng ngọt thanh, hơi chát như nhựa cây. Ngoài hiệu quả chữa trị xuất sắc, nó còn là một thức uống ngon.",
      [611673941484032] = "Dược Trị Liệu do Giáo Sư Ma Dược pha chế, giúp xoa dịu mọi vết thương và mệt mỏi.",
      [611673941484288] = "Dược đặc biệt do Dược Sư pha chế, nghe nói ẩn chứa sức mạnh thần bí.",
      [611673941484544] = "Dược này có thể đánh thức Linh Tính đang ngủ yên và bồi bổ tinh thần cạn kiệt — thuốc bổ tốt nhất cho Linh Tính.",
      [611673941484800] = "Dược đặc biệt do Giáo Sư Ma Dược pha chế, giúp đánh thức Linh Tính và độ nhạy bén tiềm ẩn.",
      [611673941485056] = "Dược Cuồng Bạo do Dược Sư pha chế, đốt cháy tiềm năng trong thời gian ngắn và tăng Tấn Công.",
      [611673941485312] = "Dược này có thể lập tức đốt cháy tiềm năng toàn thân. Ngoài tăng mạnh Tấn Công trong thời gian ngắn, nó còn khiến bạn quên mất đau đớn là gì.",
      [611673941485568] = "Dược Cuồng Bạo do Giáo Sư Ma Dược pha chế, giúp bạn phá hủy mọi trở ngại và hư vọng.",
      [611673941485824] = "Loài cây trang nghiêm, thanh u được Nữ Thần Đêm Tối yêu thích, có thể mua từ thương nhân Nghĩa Trang.",
      [611673941486592] = "Cốt bánh vàng óng xốp như mây, vị chua thơm hòa cùng ngọt sữa; cắn một miếng là mở ra ngày mới hạnh phúc.",
      [611673941486848] = "Tách sứ xương đựng trà màu hổ phách, vị ấm dịu của hồng trà quyện hương ngọt của đường phủ.",
      [611673941487104] = "Súp bí đỏ vàng sánh bốc hơi, hương sữa đan cùng quế; vào miệng mềm mịn ngọt dịu, hơi ấm đi thẳng vào lòng.",
      [611673941487360] = "Một lát bánh mì nướng cắt dày mang sắc vàng ấm. Vị béo của bơ và dịu của sữa hòa trong miệng, càng nhai càng thơm.",
      [611673941487872] = "Bánh mì kẹp rau, phô mai, giăm bông và nhiều nguyên liệu hảo hạng; ngon gấp bội, tinh lực trở lại!",
      [611673941488128] = "Sandwich đặc cấp làm từ nguyên liệu quý hiếm vùng núi rừng, nhiều tầng thỏa mãn; mỗi miếng đều chứa phúc lành.",
      [611673941488384] = "Dược Trị Liệu chế bằng ma pháp nghi thức đặc biệt, có thể kích phát giới hạn tự chữa lành của cơ thể.",
      [611673941488640] = "Dược Trị Liệu chứa lòng từ bi của thần linh, quà tặng từ bản nguyên Sinh Mệnh.",
      [611673941488896] = "Dược đặc biệt chế bằng ma pháp nghi thức, có thể lấp đầy khoảng trống Linh Tính và cảm nhận điều bí ẩn, chưa biết.",
      [611673941489152] = "Dược đặc biệt chứa sự khai sáng của thần linh, quà tặng từ bản nguyên Linh Tính.",
      [611673941489408] = "Dược Cuồng Bạo chế bằng ma pháp nghi thức đặc biệt, tách con người khỏi đau đớn và sợ hãi, tạm thời hóa thành binh khí chiến đấu.",
      [611673941489664] = "Dược Cuồng Bạo chứa cơn giận của thần linh, quà tặng từ bản nguyên Sức Mạnh.",
      [611673941492736] = "Ánh sao và ánh trăng được đúc vào cùng một nhánh kim loại; khi nến cháy lên, dường như có thể nghe tiếng hòa âm từ nơi cực xa.",
      [611673941492992] = "Sắc hồng đỏ và lửa đen đan quanh hình bóng người phụ nữ; nhà điêu khắc cố ý để những đầu ngón tay chưa hoàn thiện — phần còn lại giao cho người xem.",
      [611673941493248] = "Đá được tạc thành những đường nét mềm mại. Bức tượng im lặng đang mang tâm sự gì?",
      [611673941493504] = "Ghế dài bằng gỗ thường dùng để nghỉ chân, từng chở theo những khoảng thời gian ngắn ngủi của rất nhiều người qua đường.",
      [611673941494016] = "Khi ánh bình minh xuyên qua rèm cửa, người đẹp thấp thoáng đổi hình.\nLưu luyến dư vị, hương thơm thấm lòng. Kinh hồn chưa định, hóa ra một giấc đại mộng.",
      [611673941495296] = "Bức chân dung này vẽ một nhà văn đang mắc chứng trì hoãn.",
      [611673941496576] = "Bức chân dung này vẽ một Người Thu Xác nhợt nhạt và im lặng.",
      [611673941499136] = "Bánh mì cứng ngắc, mang vị chát của cám lúa mì; lựa chọn hàng đầu để lấp bụng.",
      [611673941499392] = "Một cốc trà lạnh ngọt đậm, thức uống mùa hè hòa bằng đá và đường. Có thể thử thêm lát chanh!",
      [611673941499648] = "Bánh pudding chanh hoàng gia do chủ quán mô phỏng lại, bớt vị ngọt gắt của đường công nghiệp, thêm nét tinh tế thủ công.",
      [611673941499904] = "Hộp đầy các loại quả mọng, giữ nguyên vị chua ngọt. Có thể mở ăn trực tiếp hoặc làm mứt phết bánh mì.",
      [611673941500160] = "Món trứng sữa ấm mềm mượt; nhấp một ngụm là tinh thần hồi lại.",
      [611673941500416] = "Miếng thịt cắt dày bóng nâu cháy, than lửa nướng bật hương mỡ; ăn no là bổ sung Thể Lực thật đã.",
      [611673941500672] = "Dược Thủy bình thường; uống vào cảm giác cơ thể lại được rót thêm sức mạnh. Nhìn và nếm đều hơi giống sữa...?",
      [611673941500928] = "Dược chứa đầy sương sớm trong rừng và tinh hoa dây leo, hội tụ sinh cơ cỏ cây.",
      [611673941501184] = "Dược chứa năng lượng đại địa; khẽ lắc, tựa địa mạch cuộn chảy trong chai.",
      [611673941501696] = "Khoảnh khắc này, chúng ta cùng chia sẻ hoàng hôn.",
      [611673941501952] = "Rượu màu hổ phách nổi bọt gừng mịn, vị cay hòa hương rượu xộc xuống cổ; hơi ấm trong ngực đánh thức thần kinh.",
      [611673941507584] = "Hương rang trầm ổn, dư vị mạch nha kéo dài, hơi ấm đi thẳng vào lòng.",
      [611673941507840] = "Sự kết hợp hoàn hảo giữa hạt cà phê rang đậm chất lượng cao và vị nho ngọt; tỉnh táo mà vẫn ngon miệng.",
      [611673941508096] = "Trong nước vàng đục nổi gừng vụn, vị cay xộc thẳng khoang mũi; uống cạn, từ cổ họng tới dạ dày đều nóng rực.",
      [611673941510656] = "Nếu bạn nhìn thấy đoạn mô tả này thì chứng tỏ có BUG, hãy báo cáo.",
      [611673941516544] = "Suất ăn công việc do cô Rozanne đặt trước: đùi cừu nướng, nước thịt đầy đặn thấm sâu vào thớ thịt dai mềm.",
      [611673941516800] = "Suất ăn công việc do cô Rozanne đặt trước, nấu từ kem sữa đậm đà và hàu tươi ngon.",
      [668921023714304] = "Đèn chiều lần lượt sáng lên, phản chiếu trên sông Tussock chảy qua Tingen.",
      [668921023718912] = "Bức chân dung này vẽ một nhà thơ không giỏi thơ.",
      [668921023719168] = "Bức chân dung này vẽ một Người Bảo Hộ có đôi mắt xám sâu thẳm.",
      [668921023719424] = "Bức chân dung này vẽ một Thông Linh Giả luôn giao thiệp với cái chết.",
      [668921023719680] = "Bức chân dung này vẽ một thiếu nữ quý tộc mỉm cười điềm tĩnh.",
      [668921023720192] = "Bức chân dung này vẽ một thuyền trưởng đối diện trực tiếp với Bão Táp.",
      [668921023720448] = "Bức chân dung này vẽ một... một chú chó Golden Retriever lớn với vẻ mặt ôn hòa.",
      [668921023720704] = "Bức chân dung này vẽ một người hướng về ánh sáng, chưa từng phản bội.",
      [668921023720960] = "Bức chân dung này vẽ một ông lão nghiêm giữ tín điều.",
      [668921023721472] = "Bức chân dung này vẽ một kẻ cuồng sinh vật mê nấm.",
      [668921023721728] = "Bức chân dung này vẽ một nhân viên văn phòng thông minh ở Backlund.",
      [668921023721984] = "Bức chân dung này vẽ một thiếu nữ tinh thông kỹ thuật máy móc.",
      [668921023722240] = "Bức chân dung này vẽ một Thủ Tịch mãi mãi canh gác.",
      [668921023722496] = "Bức chân dung này vẽ một Người Truy Quang thẳng thắn và kiên định.",
      [668921023737344] = "Trong mũ lễ giấu gì? Hoa giấy, khăn tay, bài lá, hay một màn ảo thuật hoành tráng mà nguy hiểm.",
      [668921023737600] = "Chế nhạo niềm vui và nỗi buồn, cũng chế nhạo thất bại và chiến thắng.\nChủ nhân của nó đã rời đi; đây là dấu ấn vinh dự của bạn.",
      [668921023737856] = "Dù từng nghiền nát thứ gì, giờ tất cả cũng chỉ còn là tiếng vọng xa xưa.",
      [668921023738112] = "Trang giấy không nên lật mở — là vận rủi, hay hủy diệt?",
      [668921023738368] = "Ý chí bị điều khiển đã rời đi, tiếng sủa uy nghiêm vẫn vang vọng.\nĐôi mắt trung thành vẫn canh giữ; táo năm nay có thơm không?",
      [668921023738624] = "Chỉ còn ký ức rách nát, lặng lẽ thực hiện lời hứa bảo hộ.",
      [668921023738880] = "Ai đã lấy trộm căn nhà nhỏ của một chú rùa?\nỒ, Phong Nhiêu, sức mạnh của Phong Nhiêu!",
      [668921023739136] = "Hí hí hí, ha ha ha... sao mẹ bỏ con lại?\nNgủ dài đi, ngủ yên đi. Cánh bướm yếu mềm, đừng lang thang nữa.",
      [668921023739392] = "Tiếng kèn nơi xa vẫn vang cao, vinh quang của Wessel vẫn chảy ở đây. Linh hồn bất khuất cúi đầu, nhưng ánh giáp vẫn như xưa.",
    },
    ["itemnormal"] = {
      [127888019949056] = "Sợi Tóc An Hồn",
      [141426025305344] = "Trâm Cài Mặt Trời",
      [141426025305856] = "Khuy Măng-sét Người Cá",
      [141426025306368] = "Quyền Trượng Sinh Mệnh",
      [141426025306624] = "Áo Choàng Bóng Tối",
      [141426025307904] = "Công Chứng Thư",
      [141426025309440] = "Hoa Máu",
      [141426025310720] = "Lưỡi Dao Kịch Độc",
      [141426025311232] = "Ánh Ngoái Nhìn của Ornia",
      [277077735510272] = "Mặt Nạ Hoàng Hôn",
      [277077735510784] = "Đói Khát Ngọ Nguậy",
      [277077735511296] = "Nhẫn Lilith",
      [277077735512832] = "Thủy Tinh Chi Nhãn",
      [277077735513344] = "Búp Bê Xui Xẻo",
      [277077735513856] = "Tướng Quân Vô Đồng",
      [277077735516416] = "Dối Trá",
      [277077735517952] = "Sao Băng Thối Rữa",
      [277077735518976] = "Ân Tứ Đại Địa",
      [277077735519488] = "Ví Tiền Chính Nghĩa",
      [580680652163328] = "Bút Ký Antigonus",
      [602739872630784] = "Xúc Xắc Xác Suất",
      [611398258361088] = "Tử Vong Nhợt Nhạt",
      [611398258363648] = "Lời Biển Cả",
      [611398258382336] = "Trượng Tinh Tú",
      [611399063569920] = "Tờ tiền xanh sẫm ngả trắng, một loại tiền khá phổ biến trong hệ thống tiền tệ của Vương quốc Loen.",
      [611399063570432] = "Đồng tiền màu vàng óng; mặt trước khắc chân dung George III đội vương miện, để ria mép hai bên, nghiêm nghị và cổ hủ. Đây là loại tiền có mệnh giá cao nhất trong hệ thống tiền tệ của Vương quốc Loen.",
      [611399063570944] = "Sau khi dùng có thể đốt Pháo Hoa Bùm Bùm.",
      [611399063571200] = "Sau khi dùng có thể đốt Pháo Hoa Ruy Băng.",
      [611399063571456] = "Có thể dùng trong Triệu Hồi - Hoán Dung Linh Giới để nhận ngoại hình giới hạn.",
      [611399063571968] = "Nhận được qua Triệu Hồi - Hoán Dung Linh Giới; dùng để đổi phần thưởng tại Cửa Hàng Quà Tặng Mỹ Thần.",
      [611399063572224] = "Nhận được qua Triệu Hồi - Hoán Dung Linh Giới; dùng để đổi phần thưởng tại Cửa Hàng Tế Đàn Linh Huyễn.",
      [611399063572480] = "Có thể dùng trong Triệu Hồi - Kỳ Trang Tinh Linh để nhận ngoại hình giới hạn.",
      [611399063572736] = "Nhận được qua Triệu Hồi - Kỳ Trang Tinh Linh; dùng để đổi phần thưởng tại Cửa Hàng Bí Khố Tinh Linh.",
      [611399063572992] = "Vật Phẩm Mở Khóa Phương Án Nhuộm (Placeholder)",
      [611399063573248] = "Nguyên liệu nhuộm cơ bản, dùng để nhuộm thời trang và mở khóa ô nhuộm.",
      [611399063573504] = "Có thể dùng để nhuộm tóc.",
      [611399063573760] = "Có thể dùng để nhuộm thời trang hoặc phụ kiện.",
      [611399063574272] = "Thu thập Điểm Phẩm Vị để tăng Cấp Phẩm Vị; đạt cấp tương ứng có thể nhận phần thưởng.",
      [611399063574528] = "Sau khi dùng có thể tái tạo dung mạo.",
      [611399063574784] = "Sau khi dùng, có thể chuyển ngoại hình giới hạn thời gian: 【Tên Ngoại Hình】 thành sở hữu vĩnh viễn.",
      [611399063575296] = "Đồng vàng tỏa ánh kim nhạt, là sự công nhận và phần thưởng của câu lạc bộ dành cho đóng góp của mỗi thành viên; có thể đổi nhiều loại hàng hóa tại Cửa Hàng Câu Lạc Bộ.",
      [611399063575552] = "Điểm Thiên Phú cần để nâng cấp nút Thiên Phú, nhận được qua Thăng Bậc.",
      [611399063575808] = "Điểm Thiên Phú - Điểm Đặc Biệt",
      [611399063576064] = "Tài Sản Lâu Đài dùng cho nâng cấp lâu đài, mua bán nội thất và các nội dung bên trong lâu đài.",
      [611399063576320] = "Tiền Vàng dùng để tăng cấp và mua quân cờ.",
      [611399063576576] = "Đồng bạc sáng bóng, dùng để nâng cấp công trình Câu Lạc Bộ; có thể nhận qua hoạt động Câu Lạc Bộ.",
      [611399063576832] = "Có thể dùng tại Cửa Hàng Chuyển Vận để đổi các phần thưởng như <Highlight>Chén Thánh · Khóa, Tinh Tệ, Thuốc Nhuộm Hồng Quang</>.",
      [611399063577088] = "Sau khi thu thập có thể đổi nhiều loại vật phẩm tại Cửa Hàng Đổi Nhân Mạch.",
      [611399063577344] = "Bắt nguồn từ nhận thức về thế giới; kinh nghiệm ấy sẽ hóa thành sức mạnh của bản thân. Khi đạt một mức nhất định, Kinh Nghiệm Nhận Thức sẽ chuyển thành Kinh Nghiệm Thần Tính.",
      [611399063577600] = "Nhận được qua Hoán Dung Linh Giới; dùng để đổi phần thưởng tại Cửa Hàng Quà Tặng Mỹ Thần.",
      [611399063578368] = "Sau khi dùng, mở nhiệm vụ “【Thần Giáng】Dệt Vinh Quang · Bộ Trang Phục”.",
      [611399063578624] = "Vật liệu nghi thức cần để hoàn thành nhiệm vụ “【Thần Giáng】Dệt Vinh Quang · Bộ Trang Phục”.",
      [611399063578880] = "Sau khi dùng, mở nhiệm vụ “【Thần Giáng】Dệt Vinh Quang · Cánh”.",
      [611399063579136] = "Vật liệu nghi thức cần để hoàn thành nhiệm vụ “【Thần Giáng】Dệt Vinh Quang · Cánh”.",
      [611399063579392] = "Sau khi dùng, mở nhiệm vụ “<Highlight>【Thần Giáng】Dệt Vinh Quang · Linh Kỵ</>”; mở nhiệm vụ không tiêu hao vật phẩm này.\nKhi đăng vật phẩm có thể giao dịch này lên <Highlight>Thương Thành - Sàn Giao Dịch</>, giá đề xuất là <Highlight>40000 vạn Soli</>.",
      [611399063579648] = "Vật liệu nghi thức cần để hoàn thành nhiệm vụ “<Highlight>【Thần Giáng】Dệt Vinh Quang · Linh Kỵ</>”.\nKhi đăng vật phẩm có thể giao dịch này lên <Highlight>Thương Thành - Sàn Giao Dịch</>, giá đề xuất là <Highlight>1500 vạn Soli</>.",
      [611399063579904] = "Vật phẩm Điểm Tiến Độ nhận từ Thử Thách Sách Đồng Thau · Phó Bản.",
      [611399063580160] = "Vật phẩm Điểm Tiến Độ nhận từ Thử Thách Sách Đồng Thau · Thi Đấu.",
      [611399063580416] = "Vật phẩm Điểm Tiến Độ nhận từ Thử Thách Sách Đồng Thau · Phiêu Lưu.",
      [611399063580672] = "Chứng từ đổi thưởng nhận từ Thử Thách Sách Đồng Thau · Phó Bản.",
      [611399063580928] = "Chứng từ đổi thưởng nhận từ Thử Thách Sách Đồng Thau · Thi Đấu.",
      [611399063581184] = "Chứng từ đổi thưởng nhận từ Thử Thách Sách Đồng Thau · Phiêu Lưu.",
      [611399063581440] = "Có thể dùng phiếu giảm 60 Bảng Vàng khi thanh toán một số ngoại hình trong Thương Thành; mỗi món tối đa dùng 2 phiếu.",
      [611399063581696] = "Chứng từ nhận được sau khi đánh bại Tai Ương Thế Giới; giới hạn nhận mỗi tuần là 1200.",
      [611399063581952] = "Có thể dùng phiếu giảm 500 Bảng Vàng khi thanh toán một số ngoại hình trong Thương Thành; mỗi món tối đa dùng 2 phiếu.",
      [611399063582208] = "Có thể dùng phiếu giảm 1000 Bảng Vàng khi thanh toán một số ngoại hình trong Thương Thành; mỗi món tối đa dùng 2 phiếu.",
      [611399063582464] = "Vật liệu cần để Cường Hóa Trang Bị; dùng vật liệu này có thể cường hóa trang bị tối đa tới giới hạn Tinh Luyện của mùa “Đại Đế Trở Về”.",
      [611399063582720] = "Có thể dùng để mở khóa thêm ô lưu phương án Ân Tứ.",
      [611399063582976] = "Vật liệu cần để Tái Tạo Trang Bị. Sau khi tái tạo, số lượng dòng thuộc tính ngẫu nhiên cùng loại thuộc tính và giá trị của toàn bộ dòng thuộc tính trên trang bị sẽ được ngẫu nhiên lại.",
      [611399063583232] = "Vật liệu cần để Tịnh Hóa dòng thuộc tính Ô Nhiễm. Sau khi tịnh hóa, dòng Ô Nhiễm có thể chuyển thành dòng Phi Phàm hoặc dòng thường.",
      [611399063583488] = "Dùng để cấu hình vật phẩm rơi của niên mùa.",
      [611399063583744] = "Cấu hình không chính thức, vui lòng không sử dụng. Trong niên mùa không phải “Tán Mỹ Kẻ Khờ”, đây là vật liệu cần để Tái Tạo Trang Bị.",
      [611399063584000] = "Vật liệu cốt lõi để chế tạo vũ khí Thần Thoại. <Highlight>Dùng</> vật phẩm để nhận nhiệm vụ “Vòng Ôm Ẩn Bí”, tìm hiểu phương pháp rèn vũ khí Thần Thoại.\n\nKhi mở Nghi Thức Rèn Thần Thoại, cần tiêu hao 1 <Highlight>Kén Dệt Thần Thoại</> và 60 <Highlight>Tơ Kén</>. Hoàn tất nghi thức nhận vũ khí Thần Thoại <Highlight>【Vòng Ôm Ẩn Bí】</>.",
      [611399063584256] = "Vật liệu then chốt để chế tạo vũ khí Thần Thoại.\n\nKhi mở Nghi Thức Rèn Thần Thoại, cần tiêu hao 1 <Highlight>Kén Dệt Thần Thoại</> và 60 <Highlight>Tơ Kén</>. Hoàn tất nghi thức nhận vũ khí Thần Thoại <Highlight>【Vòng Ôm Ẩn Bí】</>.\nNếu thiếu <Highlight>Kén Dệt Thần Thoại</>, cũng có thể tiêu hao 30 <Highlight>Tơ Kén</> để rèn vũ khí <Highlight>【Tụng Ca Màn Đêm】</>. <Highlight>【Tụng Ca Màn Đêm】</> có thể bổ sung đủ vật liệu để rèn tiếp thành <Highlight>【Vòng Ôm Ẩn Bí】</>.\nTheo tiến trình mùa giải, cấp trang bị của 【Vòng Ôm Ẩn Bí】 và 【Tụng Ca Màn Đêm】 sẽ được mở nâng; khi nâng cần tiêu hao một lượng <Highlight>Tơ Kén</>.",
      [611399063584512] = "Vật liệu then chốt để rèn trâm ngực phẩm chất Thần Thoại <Highlight>(thiên hướng Phiêu Lưu)</>.\n\nRèn cần tiêu hao <Highlight>15</> Bụi Sương Xám, nhận trâm ngực Thần Thoại cấp trang bị 64 <Highlight>thiên hướng Phiêu Lưu</>.\nTheo tiến trình mùa giải sẽ mở nâng cấp trang bị cho trâm ngực Thần Thoại thiên hướng tương ứng; khi nâng tiêu hao một lượng <Highlight>Bụi Sương Xám</>.\n\nMỗi tuần có thể <Highlight>nhận trực tiếp</> tối đa <Highlight>3</> Bụi Sương Xám từ Phó Bản Tổ Đội, Phó Bản Đoàn Đội và Bí Bảo Phiêu Lưu Thế Giới. Số chưa nhận được cộng dồn sang tuần sau, tối đa <Highlight>15</>.",
      [611399063584768] = "Vật liệu then chốt để rèn trâm ngực phẩm chất Thần Thoại <Highlight>(thiên hướng Thi Đấu)</>.\n\nRèn cần tiêu hao <Highlight>15</> Sỏi Tinh Sương Xám, nhận trâm ngực Thần Thoại cấp trang bị 64 <Highlight>thiên hướng Thi Đấu</>.\nTheo tiến trình mùa giải sẽ mở nâng cấp trang bị cho trâm ngực Thần Thoại thiên hướng Thi Đấu; khi nâng tiêu hao một lượng <Highlight>Sỏi Tinh Sương Xám</>.\n\nMỗi tuần có thể <Highlight>nhận trực tiếp</> tối đa <Highlight>3</> Sỏi Tinh Sương Xám từ Săn Giết Tận Cùng, Giải Liên Đấu Tứ Phương, Chiến Thành/Chiến Cao Nguyên và Bí Bảo Lấy Chiến Nuôi Chiến. Số chưa nhận được cộng dồn sang tuần sau, tối đa <Highlight>15</>.",
      [611399063585024] = "Mở để nhận 1 Tơ Kén <Highlight>khóa</>. Mỗi tuần có thể mở <Highlight>6</> lần; số lần chưa mở cộng dồn sang tuần sau, tối đa <Highlight>30</> lần.\n\n<Highlight>Tơ Kén</>: vật liệu then chốt để chế tạo vũ khí Thần Thoại.\n\nKhi mở Nghi Thức Rèn Thần Thoại, cần tiêu hao 1 <Highlight>Kén Dệt Thần Thoại</> và 60 <Highlight>Tơ Kén</>. Hoàn tất nghi thức nhận vũ khí Thần Thoại <Highlight>【Vòng Ôm Ẩn Bí】</>.\nNếu thiếu <Highlight>Kén Dệt Thần Thoại</>, cũng có thể tiêu hao 30 <Highlight>Tơ Kén</> để rèn vũ khí <Highlight>【Tụng Ca Màn Đêm】</>. <Highlight>【Tụng Ca Màn Đêm】</> có thể bổ sung đủ vật liệu để rèn tiếp thành <Highlight>【Vòng Ôm Ẩn Bí】</>.\nTheo tiến trình mùa giải, cấp trang bị của 【Vòng Ôm Ẩn Bí】 và 【Tụng Ca Màn Đêm】 sẽ được mở nâng; khi nâng cần tiêu hao một lượng <Highlight>Tơ Kén</>.",
      [611399063585280] = "Mở để nhận 1 Bụi Sương Xám <Highlight>khóa</>. Mỗi tuần có thể mở <Highlight>3</> lần; số lần chưa mở cộng dồn sang tuần sau, tối đa <Highlight>15</> lần.\n\n<Highlight>Bụi Sương Xám</>: vật liệu then chốt để rèn trâm ngực phẩm chất Thần Thoại <Highlight>(thiên hướng Phiêu Lưu)</>.\n\nRèn cần tiêu hao <Highlight>15</> Bụi Sương Xám, nhận trâm ngực Thần Thoại cấp trang bị 64 <Highlight>thiên hướng Phiêu Lưu</>.\nTheo tiến trình mùa giải sẽ mở nâng cấp trang bị cho trâm ngực Thần Thoại thiên hướng tương ứng; khi nâng tiêu hao một lượng <Highlight>Bụi Sương Xám</>.\n\nMỗi tuần có thể <Highlight>nhận trực tiếp</> tối đa <Highlight>3</> Bụi Sương Xám từ Phó Bản Tổ Đội, Phó Bản Đoàn Đội và Bí Bảo Phiêu Lưu Thế Giới. Số chưa nhận được cộng dồn sang tuần sau, tối đa <Highlight>15</>.",
      [611399063585536] = "Mở để nhận 1 Sỏi Tinh Sương Xám <Highlight>khóa</>. Mỗi tuần có thể mở <Highlight>3</> lần; số lần chưa mở cộng dồn sang tuần sau, tối đa <Highlight>15</> lần.\n\n<Highlight>Sỏi Tinh Sương Xám</>: vật liệu then chốt để rèn trâm ngực phẩm chất Thần Thoại <Highlight>(thiên hướng Thi Đấu)</>.\n\nRèn cần tiêu hao <Highlight>15</> Sỏi Tinh Sương Xám, nhận trâm ngực Thần Thoại cấp trang bị 64 <Highlight>thiên hướng Thi Đấu</>.\nTheo tiến trình mùa giải sẽ mở nâng cấp trang bị cho trâm ngực Thần Thoại thiên hướng Thi Đấu; khi nâng tiêu hao một lượng <Highlight>Sỏi Tinh Sương Xám</>.\n\nMỗi tuần có thể <Highlight>nhận trực tiếp</> tối đa <Highlight>3</> Sỏi Tinh Sương Xám từ Săn Giết Tận Cùng, Giải Liên Đấu Tứ Phương, Chiến Thành/Chiến Cao Nguyên và Bí Bảo Lấy Chiến Nuôi Chiến. Số chưa nhận được cộng dồn sang tuần sau, tối đa <Highlight>15</>.",
      [611399063585792] = "Quặng chứa một lượng Linh Chất nhất định, có thể dùng để thay thế dòng thuộc tính Lịch Sử của trang bị.",
      [611399063586048] = "Sau khi dùng vật phẩm này, số lượt riêng của Phó Bản Riel Bieber tăng 1 và số lượt dùng chung của Ngoại Đình Tháng Năm tăng 1.",
      [611399063586304] = "Có thể dùng để triệu hồi Hình Chiếu Lịch Sử, kết giao Nhân Mạch và học kỹ năng.",
      [611399063586560] = "Sản phẩm phân giải Vật Chất Phi Phàm, đồng thời là nguyên liệu bắt buộc khi Vật Chất Phi Phàm tụ hợp.",
      [611399063587072] = "Có thể dùng để đánh thức quan hệ Hiệp Chiến cấp 【Bản Tướng】, nhận Dư Âm Vận Mệnh và từ đó nâng Âm Giai Dư Âm.\n\nCó thể nhận bằng cách lặp lại việc kết giao Quan Hệ cấp Cực Hạn.",
      [611399063587328] = "Vật liệu dùng để Thần Rèn và cải tạo phương tiện.",
      [611399063587584] = "Vật phẩm Linh Tính rải rác khắp nơi.\nTrong Câu Lạc Bộ dường như có một Người Gác Đêm đang thu thập chúng.\nSau khi dùng có thể chỉ dẫn đến vị trí giao nộp để đổi thưởng.",
      [611399063588096] = "Dự Phòng",
      [611399063588352] = "Dùng để nhận Bí Ngẫu tại Nhà Hát Utopia.",
      [611399063588864] = "Vật phẩm chuyển hóa từ Bí Ngẫu trùng bị dư, có thể đổi hàng tại Cửa Hàng Bí Ngẫu.",
      [611399063589120] = "Dùng để tăng Cấp Mùa Du Lịch Bí Ngẫu.",
      [611399063589376] = "Sau khi dùng Bí Ngẫu Trùng Tinh Tú Huyễn Hình, có thể điều khiển tọa kỵ khi đang ở trạng thái đi theo.",
      [611399063589888] = "Một trong các sản vật của Xưởng Lâu Đài, có thể dùng cho: Thu Mua Chợ Lâu Đài, Đại Gia Đường Sắt.",
      [611399063604480] = "Sau khi dùng, có thể chuyển phòng thoại của hoạt động thành phòng thường trú và tăng thêm 30 ngày thời gian thường trú.",
      [611399063604736] = "Sau khi dùng có thể đốt Pháo Hoa Tiệc Tùng.",
      [611399063604992] = "Có thể dùng phiếu giảm 100 Bảng Vàng khi thanh toán một số ngoại hình trong Thương Thành; mỗi món tối đa dùng 2 phiếu.",
      [611399063605248] = "Có thể dùng phiếu giảm 300 Bảng Vàng khi thanh toán một số ngoại hình trong Thương Thành; mỗi món tối đa dùng 2 phiếu.",
      [611399063605504] = "Có thể dùng phiếu giảm 300 Bảng Vàng khi thanh toán một số ngoại hình trong Thương Thành; mỗi món tối đa dùng 2 phiếu. Chỉ có hiệu lực trong Mùa 1.",
      [611399063605760] = "Có thể dùng phiếu này để giảm 10% đơn giá khi thanh toán <Highlight>ngoại hình bán trực tiếp trong Thương Thành</>; mỗi món tối đa dùng 2 phiếu.",
      [611399063606016] = "Có thể dùng phiếu này để giảm 50% đơn giá khi thanh toán <Highlight>ngoại hình bán trực tiếp trong Thương Thành</>; mỗi món tối đa dùng 1 phiếu.",
      [611399063606272] = "Có thể mở khóa 1 lần sử dụng Phát Sóng Toàn Vùng.",
      [611399063606528] = "Có thể mở khóa 1 lần sử dụng phát sóng Tâm Vũ · Thần Dụ. <Highlight>Sau khi dùng tặng kèm Lễ Kim Bảng Vàng Khóa ở Kênh Thế Giới trị giá bằng một nửa.</>",
      [611399063606784] = "Có thể mở khóa 1 lần sử dụng phát sóng Tấn Điện · Thần Dụ. <Highlight>Sau khi dùng tặng kèm Lễ Kim Bảng Vàng Khóa ở Kênh Thế Giới trị giá bằng một nửa.</>",
