      [611399063655680] = "Có thể dùng để bồi dưỡng Bí Ngẫu Quái Hoa Ăn Mộng.",
      [611399063657472] = "Tiến độ săn giết chỉ có thể nhận bằng cách nộp <Highlight>Di Vật Tinh Hồng</> cho <Highlight>“Quản Gia Săn Giết”</> trong <Highlight>lối chơi Săn Giết Tận Cùng</> để đổi.",
      [611399063657728] = "Di Vật Tinh Hồng · Khóa có thể nhận khi tiêu diệt <Highlight>Sinh Vật Siêu Phàm trong Thành Săn Rồng</>; khi bị người chơi địch hạ gục, <Highlight>Di Vật Tinh Hồng · Khóa không rơi</>.\nCó thể nộp tại <Highlight>【Quản Gia Săn Giết】</> để tăng <Highlight>Tiến Độ Săn Giết</> và nhận thưởng.",
      [611399063657984] = "<Highlight>Sau khi nhận nhiệm vụ Hạt Giống Thở Dài</>, Di Vật Tinh Hồng có thể nhận bằng cách tiêu diệt <Highlight>Sinh Vật Siêu Phàm trong Thành Săn Rồng</> hoặc đánh bại người chơi địch để <Highlight>cướp đoạt</>. Khi bị người chơi địch hạ gục, <Highlight>Di Vật Tinh Hồng cũng sẽ rơi theo tỷ lệ</>.\nCó thể nộp tại <Highlight>【Quản Gia Săn Giết】</> để tăng <Highlight>Tiến Độ Săn Giết</> và nhận thưởng. <Highlight>Di Vật Tinh Hồng chỉ có hiệu lực trong Thành Săn Rồng</>; khi rời đi sẽ <Highlight>tự động mất hiệu lực và bị xóa</>.",
      [611399063658240] = "<Highlight>Số lần có thể nhận nhiệm vụ Hạt Giống Thở Dài · Săn Quái</>; mục tiêu nhiệm vụ là <Highlight>tìm và đánh bại các kỵ sĩ lang thang trong Thành Săn Rồng</>.",
      [611399063658752] = "<Highlight>Chỉ trong thời gian sự kiện Thời Khắc Săn Giết</>, có thể triệu hồi Nhân Ngẫu Vận Mệnh tại 【Tế Đàn Vận Mệnh】; đánh bại nó để nhận vật liệu Di Vật Tinh Hồng. Khu Vương Thành cực kỳ nguy hiểm, khuyến nghị <Highlight>đi theo đoàn đội để khiêu chiến</>.",
      [611399063659008] = "Triệu hồi Tiên Phong Tai Dị tại 【Sào Huyệt Tai Dị】; đánh bại nó để nhận vật liệu Di Vật Tinh Hồng. Tiên Phong Tai Dị rất mạnh, khuyến nghị <Highlight>lập tổ đội để khiêu chiến</>.",
      [611399063659264] = "Điểm Thắng bậc xếp hạng của lối chơi Săn Giết Tận Cùng, có thể nhận bằng cách <Highlight>nhận thưởng mốc Tiến Độ Săn Giết hằng tuần</> hoặc <Highlight>hạ người chơi địch để cướp đoạt</>.",
      [611399063659776] = "<Highlight>Số lần có thể nhận nhiệm vụ Hạt Giống Thở Dài · Tranh Quái</>; mục tiêu nhiệm vụ là <Highlight>đến khu Tranh Quái chỉ định, nhận nhiệm vụ và đánh bại quái thử luyện</>.",
      [611399063660288] = "Vật Phẩm Tạm Thời",
      [611399063660544] = "Có thể nhận khi tham gia mọi loại nội dung thi đấu; dùng tại Cửa Hàng Khải Hoàn.",
      [611399063661312] = "Điểm Hoạt Động Câu Lạc Bộ, có thể nhận khi tham gia nhiệm vụ Trợ Cấp Hoạt Động Câu Lạc Bộ.",
      [611399063661568] = "Có thể nhận khi tham gia nhiều loại nội dung, dùng đổi nhiều phần thưởng tại Cửa Hàng Hoàn Phí.\n\nGiới hạn Hóa Đơn Chứng Từ mỗi tuần là 10000, tối đa cộng dồn 2 tuần; 8 giờ sáng mỗi thứ Hai sẽ làm mới hạn mức nhận Hóa Đơn Chứng Từ.",
      [611399063661824] = "Tiêu hao Hoạt Lực để mở <Highlight>Bí Bảo Phiêu Lưu Thế Giới, Lấy Chiến Nuôi Chiến và Quà Tặng Xã Giao</>.\n\nHoạt Lực có thể nhận từ <Highlight>nhiệm vụ Nằm Không Cũng Thắng</> hoặc <Highlight>hồi phục tự nhiên</>; cũng có thể dùng <Highlight>Viên Đường Hoạt Lực</> để hồi nhanh.",
      [611399063662080] = "Hai Củ Khoai Tây",
      [611399063662336] = "Một lọ thuốc nhỏ bằng kim loại, bên trong còn nửa lọ dược thủy xanh đậm.",
      [611399063662592] = "Một tờ tiền 1 Soli màu xanh sẫm ngả trắng, in gương mặt nghiêm nghị của Vua George III của Loen.",
      [611399063662848] = "Một hộp cơ quan nhỏ vuông vức.",
      [611399063663104] = "Một chiếc bồn cầu sạch đẹp, kiêu hãnh đứng trong phòng vệ sinh sáng sủa.",
      [611399063663360] = "Một Cây Gậy",
      [611399063663616] = "Một Tập Thơ",
      [611399063663872] = "Báo",
      [611399063664384] = "Viên đạn trắng bạc, trên thân khắc hoa văn.",
      [611399063664640] = "Một que diêm đang cháy.",
      [611399063664896] = "Ảnh tham khảo là Bùa Hộ Mệnh Bão Tố; cần đổi sang chất liệu vàng, hoa văn ánh mặt trời.",
      [611399063665152] = "Có thể tái sử dụng kiểu dáng ở hình bên phải, nhưng mong bỏ viên đá quý phía trên.",
      [611399063667712] = "Sau khi dùng phát hiệu ứng cánh hoa (chỉ người chơi bản thân nhìn thấy).",
      [611399063667968] = "Dâng lên Nữ Thần đóa Hoa Ngủ Sâu trang nghiêm, thanh u, cầu mong Ngài bảo hộ.",
      [611399063671808] = "Sau khi dùng nhận 10000 điểm Kinh Nghiệm.",
      [611399063673344] = "Vật liệu tiêu hao để nâng cấp Kỹ Năng Chiến Đấu, nhận được qua Thăng Bậc.",
      [611399063673600] = "Vật liệu tiêu hao để nâng cấp Kỹ Năng Nhân Mạch, nhận được qua Thăng Bậc.",
      [611399063673856] = "Vật liệu tiêu hao để nâng cấp Kỹ Năng Bí Ngẫu, nhận được qua Thăng Bậc.",
      [611399063674112] = "Đại Gia Đường Sắt - Tiền Tệ Trong Hoạt Động",
      [611399063674368] = "Đại Gia Đường Sắt - Vé Tiêu Hao Khi Vào Hoạt Động",
      [611399063674624] = "Đại Gia Đường Sắt - Tiền Tệ Dùng Nâng Cấp Tàu Hỏa",
