      [611399063676672] = "Chứng nhận Công Dân Tốt do Cảnh Sát Trevor trao tặng, có thể đổi phần thưởng hậu hĩnh.",
      [611399063678208] = "Có thể nhận khi tham gia lối chơi “Mặt Tối Thành Phố”; tích lũy để đổi nhiều phần thưởng.",
      [611399063678464] = "Sau khi dùng nhận danh hiệu: <Highlight>Công Dân Tốt Năm Sao</>",
      [611399063678976] = "Khi tham gia Tranh Phong Chúa Tể và giành chiến thắng, tự động tiêu hao để <Highlight>nhân đôi Điểm Thắng</> nhận được trong trận này.",
      [611399063679232] = "Khi tham gia Tranh Phong Chúa Tể, giành chiến thắng và nhận danh hiệu, tự động tiêu hao để <Highlight>nhận thêm Điểm Thắng</>.",
