      [611399063679744] = "Khi tham gia Thời Khắc Vận Mệnh và giành chiến thắng, tự động tiêu hao để <Highlight>nhân đôi Điểm Thắng</> nhận được trong trận này.",
      [611399063680000] = "Khi tham gia Thời Khắc Vận Mệnh, giành chiến thắng và nhận danh hiệu, tự động tiêu hao để <Highlight>nhận thêm Điểm Thắng</>.",
      [611399063680256] = "Khi thua một trận Thời Khắc Vận Mệnh, vật phẩm này sẽ tự động bị tiêu hao để trận thua đó <Highlight>không bị trừ Điểm Thắng</>.\n<Highlight>Hiệu ứng này chỉ có tác dụng ở bậc dưới “Vua Thiên Sứ”</>.",
