      [611399063716352] = "Sau khi dùng mở khóa <Highlight>Động Tác Xã Giao Đôi · Nắm Tay</>; nếu nhận trùng, sau khi dùng sẽ tự động phân giải thành Soli Khóa.",
      [611399063716608] = "Sau khi dùng mở khóa <Highlight>Động Tác Xã Giao Đôi · Waltz</>; nếu nhận trùng, sau khi dùng sẽ tự động phân giải thành Soli Khóa.",
      [611399063716864] = "Sau khi dùng mở khóa <Highlight>Động Tác Xã Giao Đôi · Trên Vương Tọa</>; nếu nhận trùng, sau khi dùng sẽ tự động phân giải thành Soli Khóa.",
      [611399063717120] = "Sau khi dùng mở khóa <Highlight>Động Tác Xã Giao Đôi · Cầu Hôn</>; nếu nhận trùng, sau khi dùng sẽ tự động phân giải thành Soli Khóa.",
      [611399063717376] = "Trang Phục Mặc Định",
      [611399063717632] = "Sau khi dùng, mở khóa skin xúc xắc độc quyền <Highlight>【Hoàng Kim Hào Trịch】</>.\nCác cạnh được mài bằng kỹ nghệ cực hạn thành sắc vàng rực; mỗi lần tung đều lóe lên ánh sáng lộng lẫy, là minh chứng chói mắt nhất cho thực lực và phẩm vị.",
      [611399063717888] = "Sau khi dùng, mở khóa skin xúc xắc độc quyền <Highlight>【Xúc Xắc Đêm Tối】</>.\nMột viên xúc xắc nhuốm màu màn đêm. Tung nó ra, biết đâu sẽ có một tồn tại trong bóng tối thay bạn xoay chuyển vận mệnh.",
      [611399063718144] = "Sau khi dùng, mở khóa skin xúc xắc độc quyền <Highlight>【Xúc Xắc Bình Minh】</>.\nMột viên xúc xắc phủ ánh bình minh. Tung nó ra, biết đâu vận mệnh sẽ ưu ái hơn phần ánh sáng nơi bạn.",
      [611399063718400] = "Sau khi dùng mở khóa Kết Quả Tung Xúc Xắc · Vàng.",
      [611399063718656] = "Sau khi dùng mở khóa skin kết quả tung xúc xắc độc quyền <Highlight>【Chúa Tể Sương Xám】</>.\nTrên Sương Xám, vận mệnh đã sớm an bài.",
      [611399063718912] = "Sau khi dùng mở khóa skin kết quả tung xúc xắc độc quyền <Highlight>【Linh Quang Áo Bí】</>.\nNhìn thấu huyền bí, chính xác nắm lấy chiến thắng giữa muôn vàn khả năng.",
      [611399063719168] = "Sau khi dùng mở khóa skin kết quả tung xúc xắc độc quyền <Highlight>【Tung Hoành Tứ Hải】</>.\nKẻ chinh phục không sợ biến số, mà thu cả bốn biển vào trong tay.",
      [611399063719424] = "Sau khi dùng mở khóa skin kết quả tung xúc xắc độc quyền <Highlight>【Chạm Vận May】</>.\nKhoảnh khắc Linh Tính chạm tới luôn mang theo vận may. Hãy mạnh dạn cược tất cả đi.",
      [611399063719680] = "Sau khi dùng mở khóa skin kết quả tung xúc xắc độc quyền <Highlight>【An Ninh Vĩnh Dạ】</>.\nDù kết quả ra sao, cũng không thể phá vỡ sự an bình vĩnh hằng trong vận mệnh.",
      [611399063719936] = "Sau khi dùng mở khóa skin kết quả tung xúc xắc độc quyền <Highlight>【Phán Quyết Luật Pháp】</>.\nChỉ có luật lệnh mới là vĩnh hằng; thắng bại nhất thời chỉ tạo nên một gợn sóng nhỏ.",
      [611399063720192] = "Sau khi dùng mở khóa skin kết quả tung xúc xắc độc quyền <Highlight>【Vinh Quang Hoàng Gia】</>.\nKế thừa vận mệnh của vinh quang, tắm mình trong sự chiếu cố của may mắn.",
      [611399063720704] = "Sau khi dùng mở khóa skin nền tung xúc xắc độc quyền <Highlight>【Bàn Cược Vận Mệnh】</>.\nTrước khi mọi thứ ngã ngũ, không ai trên bàn cược biết được thắng thua.",
      [611399063720960] = "Sau khi dùng mở khóa skin nền tung xúc xắc độc quyền <Highlight>【Leonard Mitchell - Tử Đằng Thì Thầm】</>.\nCó lẽ vận mệnh cũng giống thi ca, đều không chịu nổi việc săm soi từng chữ.",
      [611399063721216] = "Chương một của câu chuyện cổ tích do Siga Teon viết dựa trên Dunn và Daly.",
      [611399063721472] = "Chương hai của câu chuyện cổ tích do Siga Teon viết dựa trên Dunn và Daly.",
      [611399063721728] = "Chương ba của câu chuyện cổ tích do Siga Teon viết dựa trên Dunn và Daly.",
      [611399063721984] = "Chương bốn của câu chuyện cổ tích do Siga Teon viết dựa trên Dunn và Daly.",
      [611399063722240] = "Chương năm của câu chuyện cổ tích do Siga Teon viết dựa trên Dunn và Daly.",
      [611399063722496] = "Câu chuyện cổ tích do Siga Teon viết dựa trên Dunn và Daly; trong truyện, họ có một kết thúc tốt đẹp và hạnh phúc.",
      [611399063723008] = "Sản vật hiếm do Xưởng Lâu Đài chế tạo, có thể dùng cho: Thu Mua Chợ Lâu Đài, Đại Gia Đường Sắt.",
      [611399063740672] = "Sau khi dùng nhận danh hiệu: <Highlight>Săn Giết Tận Cùng · Thân Vương Huyết Sắc</>",
