      [611399063742976] = "Sau khi dùng nhận danh hiệu: <Highlight>Đồng Hành · Hoàng Đế Chinh Phục</>",
      [611399063743232] = "Sau khi dùng nhận danh hiệu: <Highlight>Đồng Hành · Vua Thiên Sứ</>",
      [611399063743488] = "Sau khi dùng nhận danh hiệu: <Highlight>Đồng Hành · Chủ Tể Tinh Tú</>",
      [611399063743744] = "Sau khi dùng nhận danh hiệu: <Highlight>Phiêu Lưu · Thân Vương Huyết Sắc</>",
      [611399063744000] = "Sau khi dùng nhận danh hiệu: <Highlight>Phiêu Lưu · Hoàng Đế Chinh Phục</>",
      [611399063744256] = "Sau khi dùng nhận danh hiệu: <Highlight>Phiêu Lưu · Vua Thiên Sứ</>",
      [611399063744512] = "Sau khi dùng nhận danh hiệu: <Highlight>Phiêu Lưu · Chủ Tể Tinh Tú</>",
      [611399063744768] = "Cộng 500 điểm cho người đang biểu diễn.",
      [611399063745024] = "Cộng 100 điểm cho người đang biểu diễn.",
      [611399063745280] = "Trừ 100 điểm của người đang biểu diễn.",
      [611399063745536] = "Mời Nhân Mạch tương tác, tăng Độ Hảo Cảm và nâng Cấp Ràng Buộc.",
      [611399063745792] = "Vật phẩm mở khóa ô Động Tác Motion Capture.",
      [611399063746048] = "Tặng cho bạn bè để tăng 10 điểm Hữu Hảo.",
      [611399063746304] = "Tặng cho bạn bè để tăng 20 điểm Hữu Hảo.",
      [611399063746560] = "Tặng cho bạn bè để tăng 100 điểm Hữu Hảo.",
      [611399063746816] = "Tặng cho bạn bè để tăng 500 điểm Hữu Hảo.",
      [611399063747072] = "Tặng trên Trang Cá Nhân để tăng cho đối phương 10 Điểm Danh Vọng. Nếu hai bên là bạn bè, tăng thêm 10 điểm Hữu Hảo.",
      [611399063747328] = "Tặng trên Trang Cá Nhân để tăng cho đối phương 50 Điểm Danh Vọng. Nếu hai bên là bạn bè, tăng thêm 50 điểm Hữu Hảo.",
      [611399063747584] = "Tặng trên Trang Cá Nhân để tăng cho đối phương 300 Điểm Danh Vọng. Nếu hai bên là bạn bè, tăng thêm 300 điểm Hữu Hảo.",
      [611399063747840] = "Tặng trong bài đăng Vòng Quỷ Bí để tăng 20 Điểm Nhiệt cho bài đăng đó. Nếu hai bên là bạn bè, tăng thêm 10 điểm Hữu Hảo.",
      [611399063748096] = "Tặng trong bài đăng Vòng Quỷ Bí để tăng 100 Điểm Nhiệt cho bài đăng đó. Nếu hai bên là bạn bè, tăng thêm 50 điểm Hữu Hảo.",
      [611399063748352] = "Tặng trong bài đăng Vòng Quỷ Bí để tăng 666 Điểm Nhiệt cho bài đăng đó. Nếu hai bên là bạn bè, tăng thêm 300 điểm Hữu Hảo.",
      [611399063748608] = "Có thể tặng cho người chơi chỉ định trong phòng thoại, tăng cho đối phương 20 Điểm Danh Vọng và tăng 20 Điểm Nhiệt cho phòng thoại đó trong 15 phút.",
      [611399063748864] = "Có thể tặng cho người chơi chỉ định trong phòng thoại, tăng cho đối phương 60 Điểm Danh Vọng và tăng 50 Điểm Nhiệt cho phòng thoại đó trong 30 phút.",
      [611399063749120] = "Có thể tặng cho người chơi chỉ định trong phòng thoại, tăng cho đối phương 200 Điểm Danh Vọng và tăng 150 Điểm Nhiệt cho phòng thoại đó trong 60 phút.",
      [611399063749376] = "Dùng để đổi tên Câu Lạc Bộ và chữ trên huy hiệu.",
      [611399063749632] = "Truyền thuyết do bạn đúc nên, lệnh này làm chứng. Dùng để tuyên dương biểu hiện anh dũng của Người Phi Phàm trong Chiến Thế Lực tại %s.",
      [611399063749888] = "Sau khi dùng có thể đổi tên và ẩn danh.",
      [611399063750144] = "Nhận bằng cách hoàn thành nhiệm vụ Nằm Không Cũng Thắng hằng ngày; dùng để đổi vật liệu Ma Dược.",
      [611399063750400] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Thầy Bói”. Một sợi xích bạc, đầu cuối treo mảnh sắt thiên thạch đã được mài tròn; ở giữa khảm một viên thủy tinh lấy từ di tích cổ đại.",
      [611399063750656] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Hề”. Một chiếc giỏ tròn hình thù kỳ lạ ghép từ vải tím đậm và vàng, bề mặt thêu khuôn mặt cười méo mó cùng hoa văn xoắn ốc tượng trưng cho hỗn loạn.",
      [611399063750912] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Ảo Thuật Gia”. Một hình người gấp từ dải giấy dài mảnh, phần mắt vẽ ký hiệu xoáy bằng mực.",
      [611399063751168] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Ca Tụng Giả”. Một chiếc lông chim vàng, khi cầm trong tay sẽ tỏa ánh sáng ấm áp.",
      [611399063751424] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Người Cầu Ánh Sáng”. Một chiếc đèn tay cổ xưa, có thể phủ lên mục tiêu một tầng ánh vàng nhạt.",
      [611399063751680] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Thần Quan Mặt Trời”. Một miếng vàng khắc huy hiệu Mặt Trời, có thể giải phóng Thánh Diễm trong lúc cầu nguyện.",
      [611399063751936] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Khán Giả”. Một chiếc gương đồng nhỏ; thứ nó phản chiếu không phải dung mạo con người mà là màu sắc và quầng sáng tương ứng với tâm trạng của họ.",
      [611399063752192] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Độc Tâm Giả”. Một chiếc nhẫn màu tối; khi đeo có thể nghe được nội dung cảm xúc đang hiện lên trong tâm trí mục tiêu.",
      [611399063752448] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Bác Sĩ Tâm Lý”. Một cây bút kim loại dài mảnh; những ký hiệu viết trong không khí sẽ đi vào tinh thần mục tiêu và điều chỉnh trạng thái cảm xúc của họ.",
      [611399063752704] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Học Đồ”. Một chiếc chìa khóa đồng cổ; khi cắm vào bất kỳ ổ khóa cửa nào, phía bên kia cánh cửa sẽ dẫn tới một vị trí ngẫu nhiên.",
      [611399063752960] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Đại Sư Trò Ảo Thuật”. Một hộp gỗ đen vuông trông có vẻ bình thường nhưng mang ánh bóng bán trong suốt; mặt hộp khảm bảy viên đá quý nhỏ nhiều màu. Những vật lấy ra từ hộp luôn tạo cảm giác không thật, đôi khi còn hóa thành ảo ảnh giữa không trung. Cả chiếc hộp tỏa hương thơm nhè nhẹ, nhưng đôi lúc mùi hương lại biến thành mùi kim loại khó hiểu.",
      [611399063753216] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Nhà Chiêm Tinh”. Một quả cầu thủy tinh xanh đậm, bên trong trôi nổi ánh sao chuyển động không ngừng và sương mù mờ nhạt. Ngay cả khi nhắm mắt cũng có thể cảm nhận nhịp rung yếu ớt của nó, như thể đang hô hấp.",
      [611399063753472] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Kẻ Dòm Ngó Bí Ẩn”. Một mảnh giấy nhỏ gấp lại, khi cầm trong tay sẽ hiển thị thông tin bí mật.",
      [611399063753728] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Học Giả Cách Đấu”. Một cặp kính màu đồng cổ, tròng kính vàng nhạt, gọng khắc phù điêu chim ưng săn mồi và móng vuốt sắc bén. Khi đeo, tầm nhìn hơi thu hẹp nhưng bóng người dường như bị chia thành những mảng màu và đường nét chuyển động khác nhau.",
      [611399063753984] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Vu Sư”. Một đĩa tròn khắc phù văn phức tạp, có thể dùng để tiến hành nghi thức.",
      [611399063754240] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Chiến Sĩ”. Một đôi ủng sắt nặng; khi giẫm xuống đất có thể tạo chấn động và vết nứt.",
      [611399063754496] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Cách Đấu Gia”. Một đôi giáp cổ tay có thể tăng sức mạnh và khả năng bộc phát.",
      [611399063754752] = "Sau khi nhận Vật Phẩm Thần Kỳ này, sẽ nhận Kỹ Năng Nhập Vai của Bậc “Đại Sư Vũ Khí”. Trên thắt lưng có phù văn thu nhỏ, khi biểu diễn có thể huyễn hóa thành nhiều loại vũ khí.",
      [611399063755008] = "Tấm da dê ghi Công Thức Ma Dược để thăng lên Bậc 8; khi tiến độ tiêu hóa đạt mức nhất định, Công Ty An Ninh Blackthorn sẽ cung cấp cho thành viên tích cực đã tích đủ cống hiến.",
      [611399063755264] = "Tinh thể Hoa Mặt Trời hình thành dưới ánh nắng mạnh hoặc trong nghi thức tín ngưỡng Mặt Trời, chứa thuộc tính Ánh Sáng và Tịnh Hóa ổn định.",
      [611399063755520] = "Thực vật Siêu Phàm phát ra cộng hưởng tần số thấp trong gió, có thể tăng cộng hưởng tinh thần và độ ổn định của nghi thức.",
      [611399063755776] = "Rượu vang thường đã lên men, thường dùng làm môi giới nghi thức để làm dịu xung đột giữa sức mạnh Siêu Phàm và cơ thể người.",
      [611399063756032] = "Dược thảo chỉ sinh trưởng vào giữa mùa hè, chứa sinh lực dồi dào, thường dùng trong công thức tăng cường thể chất hoặc liên quan Sinh Mệnh.",
      [611399063756288] = "Nước quả tự rỉ ra từ trái chín vào tháng Bảy, mang chút men say và hiệu ứng khuếch tán Linh Tính.",
      [611399063756544] = "Lá sẫm màu mọc tại nơi tinh linh cư trú, có đặc tính che chắn, ẩn giấu và trấn an tinh thần.",
      [611399063756800] = "Khoáng thạch hình thành sau thời gian dài tiếp xúc với ánh sáng mạnh, bên trong chứa Linh Tính Quang Huy yếu nhưng ổn định.",
      [611399063757056] = "Cơ quan lõi của Cự Quái Dung Nham, chứa sức mạnh Lửa và Đại Địa cuồng bạo, cực kỳ bất ổn.",
      [611399063757312] = "Hoa Mặt Trời có viền cánh tự nhiên chuyển vàng, tượng trưng cho chúc phúc và sự bảo hộ của Con Đường Mặt Trời.",
      [611399063757568] = "Dịch chiết thực vật có độc tính rất cao, thường dùng để tăng độ mãnh liệt của công thức hoặc kích thích tiềm năng cơ thể.",
      [611399063757824] = "Vật phẩm được nghi thức tín ngưỡng Mặt Trời chúc thánh, mang biểu tượng rõ ràng của Quang Minh, Tịnh Hóa và Trật Tự.",
      [611399063758080] = "Mào đỏ trên đầu gà trống lúc bình minh, được xem là biểu tượng xua tan bóng tối và nghênh đón rạng đông.",
      [611399063758336] = "Quả đặc biệt mọc sau khi khế ước với Linh Giới, chứa liên kết ổn định giữa Ánh Sáng và Linh Giới.",
      [611399063758592] = "Máu Sinh Vật Siêu Phàm có hiệu quả yếu trong việc phá trừ bóng tối và sợ hãi.",
      [611399063758848] = "Tinh dầu chiết từ vật tượng trưng của Con Đường Mặt Trời, có thể tăng cường Ánh Sáng, Dũng Khí và Ý Chí Tinh Thần.",
      [611399063759104] = "Kim thủ cam được phơi khô rồi nghiền nhỏ, có tác dụng phấn chấn tinh thần và tăng độ tỉnh táo trong nghi thức.",
      [611399063759360] = "Hình thành do dung nham nhiệt độ cao tự nguội, vẫn giữ lại một phần thuộc tính Lửa và Đại Địa.",
      [611399063759616] = "Tinh thể hình thành ở rễ cây cổ thụ, chứa năm tháng lắng đọng và sinh lực của Đại Địa.",
      [611399063759872] = "Lông đuôi của loài chim Siêu Phàm giao tiếp với Linh Giới, có thể dùng làm vật dẫn Linh Tính hoặc môi giới nghi thức giao tiếp.",
      [611399063760128] = "Nhựa cây chứa sức mạnh Quang Huy và Linh Giới, dùng để Tịnh Hóa hoặc xây dựng thông đạo Linh Tính.",
      [611399063760384] = "Biến chủng hiếm của Hoa Mặt Trời, viền cánh màu trắng, chứa ánh trăng dịu nhẹ và lực Tịnh Hóa.",
      [611399063760640] = "Dịch của loài dương xỉ mọc ven nước, có tác dụng nuôi dưỡng và điều hòa thuộc tính nguyên tố Nước.",
      [611399063760896] = "Nhãn cầu được bảo quản nguyên vẹn của cá Manhal trưởng thành, thường dùng trong công thức Cảm Tri hoặc Dòm Ngó.",
      [611399063761152] = "Máu hỗn hợp mang đặc tính của cả cá và thú có sừng, sở hữu khả năng thích nghi khác thường.",
      [611399063761408] = "Nước đã được Tịnh Hóa, không chứa bất kỳ tạp chất nào; là môi chất cơ bản của phần lớn nghi thức và công thức.",
      [611399063761664] = "Tinh chất độc tính cao chiết từ hoa colchicum, thường dùng để ức chế hoặc bóp méo sinh lực.",
      [611399063761920] = "Thân rễ hình răng bò được nghiền nhỏ, dùng để tăng sức chịu đựng cơ thể hoặc khả năng chịu đau.",
      [611399063762176] = "Loài hoa mọc tại nơi tinh linh cư trú, mang thuộc tính hài hòa giữa Tự Nhiên và Tinh Thần.",
      [611399063762432] = "Vật liệu cực kỳ quý hiếm, chứa khả năng điều tiết nhiều thuộc tính cùng phản ứng Linh Tính mạnh.",
      [611399063762688] = "Dịch tủy sống có đặc tính phản ứng thần kinh cực nhanh, thường dùng trong công thức liên quan Nhanh Nhẹn.",
      [611399063762944] = "Bào tử cây dẻ vừa nảy mầm, tượng trưng cho sinh trưởng và tiếp nối.",
      [611399063763200] = "Bột nghiền từ loài thảo mộc có hình như răng rồng, tượng trưng cho sự cứng cỏi và sức kháng cự.",
      [611399063763456] = "Biến chủng của Hoa Tinh Linh, tượng trưng cho sức mạnh tự nhiên thuần khiết, chưa bị ô nhiễm.",
      [611399063763712] = "Cơ quan có khả năng phản chiếu và bóp méo hiện thực, mức độ nguy hiểm cực cao.",
      [611399063763968] = "Quả do cây cổ thụ kết thành, chứa ký ức lâu đời và hơi thở của thời gian.",
      [611399063764224] = "Máu Siêu Phàm cực kỳ bất ổn, có thể tạm thời ảnh hưởng Cảm Tri và cấu trúc hiện thực.",
      [611399063764480] = "Bột nghiền từ vỏ cây cổ thụ, tượng trưng cho sự bền bỉ, năm tháng và bảo hộ.",
      [611399063764736] = "Chiết xuất từ mao địa hoàng, có tác dụng cường hóa tim và nhịp điệu Sinh Mệnh.",
      [611399063764992] = "Vật tượng trưng cho sinh mệnh mới, thường dùng trong nghi thức liên quan Vận Mệnh, sinh ra hoặc huyết thống.",
      [611399063765248] = "Dịch tủy sống của loài săn mồi mạnh, chứa đặc tính truy dấu, ẩn nấp và Nhất Kích Chí Mạng.",
      [611399063765504] = "Loại quả gây ảo thanh và ảo giác mạnh sau khi ăn, thường dùng trong công thức can nhiễu Tinh Thần.",
      [611399063765760] = "Máu Siêu Phàm chứa bản năng máu lạnh và săn mồi, có thể tăng tính xâm lược và ẩn giấu của nghi thức.",
      [611399063766016] = "Sau khi nghiền sẽ phát tán bụi làm mê hoặc tâm trí, dùng để tạo bình chướng hoặc bẫy Tinh Thần.",
      [611399063766272] = "Quả mọng màu sẫm cực độc, thường dùng trong nghi thức Nguyền Rủa, suy yếu hoặc mở tầm nhìn u ám.",
      [611399063766528] = "Đặt trong phòng của bản thân hơn ba tháng, lâu ngày phản chiếu cùng một người nên sinh ra Linh Tính; có thể dùng trong nghi thức liên quan liên kết, thay thế hoặc dòm ngó.",
      [611399063766784] = "Máu của bạch tuộc Lava vùng biển sâu, mang thuộc tính biển sâu và áp bức rất mạnh.",
      [611399063767040] = "Thủy tinh hình thành dưới ảnh hưởng của bầu trời đêm hoặc tinh tượng, chứa sức mạnh Tinh Thần yếu ớt.",
      [611399063767296] = "Chiết xuất từ thảo dược tỏa hương vào ban đêm, có hiệu quả trấn an hoặc dẫn dụ.",
      [611399063767552] = "Phụ liệu nghi thức phổ biến dùng để giữ tinh thần tỉnh táo và tăng tập trung.",
      [611399063767808] = "Độc dịch thực vật có tính chí mạng cực cao, thường dùng trong công thức nguy hiểm hoặc nghi thức ức chế.",
      [611399063768064] = "Bột thảo mộc màu đỏ, tượng trưng cho sức mạnh và sinh lực cuồng bạo.",
      [611399063768320] = "Tinh thể hình thành từ sừng dê Siêu Phàm, chứa thuộc tính Sức Mạnh ổn định.",
      [611399063768576] = "Đóa hồng dị thường mọc ra cấu trúc gương mặt hoàn chỉnh, thường dùng trong nghi thức Tinh Thần hoặc Quỷ Bí.",
      [611399063768832] = "Dịch thực vật có hiệu ứng gây ảo giác mạnh, dễ khiến Tinh Thần lệch hướng.",
      [611399063769088] = "Bột Hoa Mặt Trời bị ô nhiễm hoặc dị hóa, trong Quang Minh lẫn theo Bóng Tối.",
      [611399063769344] = "Bột thảo mộc tượng trưng cho Phòng Hộ và Che Giấu.",
      [611399063769600] = "Phần rễ lõi bóc ra từ bản thể Thụ Nhân Sương Mù, có Linh Tính cực mạnh.",
      [611399063769856] = "Dịch tủy sống báo đen khắc hoa văn dị thường, tượng trưng cho Tốc Độ và tính xâm lược.",
      [611399063770112] = "Dịch chảy từ cơ thể Thụ Nhân Sương Mù, mang hiệu quả Che Giấu và Mê Hoặc.",
      [611399063770368] = "Bột nghiền từ bảo thạch có thể chuyển đổi giữa thể lỏng và thể rắn.",
      [611399063770624] = "Tinh dầu cường hóa ảo giác và lệch hướng Tinh Thần, rủi ro sử dụng cực cao.",
      [611399063770880] = "Cơ quan lõi điều khiển biến đổi hình thái, chứa sức mạnh ngụy trang và biến hình bất ổn nhưng cường đại.",
      [611399063771136] = "Đặc Tính Phi Phàm kết tinh sau khi U Ảnh chết, là vật liệu cốt lõi để chế tạo Ma Dược hoặc Vật Phẩm Thần Kỳ.",
      [611399063771392] = "Máu Siêu Phàm chứa nhiều lớp thông tin ngụy trang, có thể tạm thời thay đổi khí tức của bản thân hoặc vật phẩm.",
      [611399063771648] = "Biến chủng của cà độc dược, khả năng gây ảo giác và Ô Nhiễm Tinh Thần mạnh hơn, cực kỳ nguy hiểm.",
      [611399063771904] = "Tóc mang Linh Tính biển sâu và đặc tính Mị Hoặc, thường dùng để điều khiển dòng nước hoặc dẫn dắt Tinh Thần.",
      [611399063772160] = "Sinh vật dị thường lấy bảo thạch làm thức ăn, trong cơ thể lưu lại Linh Tính khoáng vật mạnh.",
      [611399063772416] = "Tinh thể có thể tự nhiên phóng chiếu ảo giác.",
      [611399063772672] = "Nước cất thực vật dùng để ổn định trạng thái biên của nghi thức.",
      [611399063772928] = "Nước giếng cổ lâu ngày thông với Linh Giới, mang rủi ro chưa rõ.",
      [611399063773184] = "Sản vật nơi Tử Vong và Sinh Mệnh đan xen, thường xuất hiện trong nghi thức Cấm Kỵ.",
      [611399063773440] = "Đất mang khí tức Linh Giới rõ rệt.",
      [611399063773696] = "Cơ quan dị thường có thể tiêu hóa tồn tại Linh Tính.",
      [611399063773952] = "Máu biển sâu tượng trưng cho Tốc Độ cao và khả năng Xuyên Thấu.",
      [611399063774208] = "Tinh dầu gỗ tăng cường Ý Chí và Phòng Ngự.",
      [611399063774464] = "Vật liệu thảo mộc tượng trưng cho Trói Buộc và Liên Kết.",
      [611399063774720] = "Đóa hoa chỉ nở trong thời gian ngắn, tượng trưng cho sinh lực bộc phát.",
      [611399063774976] = "Tinh thể Linh Tính cao hình thành cùng thiên thể rơi xuống.",
      [611399063775232] = "Dạng rắn sau khi cô đặc cao độ máu bạch tuộc Lava.",
      [611399063775488] = "Bột thực vật tăng cường sự cứng cỏi và Ý Chí.",
      [611399063775744] = "Dây leo đã mất sinh lực, thường dùng trong nghi thức Suy Bại hoặc Kết Thúc.",
      [611399063776000] = "Dùng trong công thức liên quan Cảm Tri và tầm nhìn đa hướng.",
      [611399063776256] = "Cồn nồng độ cao, dùng để kích thích hoặc làm vật dẫn cho phản ứng Siêu Phàm.",
      [611399063776512] = "Bộ não Siêu Phàm chứa lượng tri thức khổng lồ cùng tiếng lẩm bẩm điên cuồng, là sự kết hợp giữa trí tuệ và mất kiểm soát.",
      [611399063776768] = "Vật phẩm mang oán niệm và Nguyền Rủa mạnh, có thể bóp méo hiện thực hoặc Xâm Thực Sinh Mệnh.",
      [611399063777024] = "Vật có lịch sử hơn hai mươi hai năm, ghi lại lịch sử cá nhân dài lâu, chứa dấu vết của cảm xúc, ký ức và Vận Mệnh.",
      [611399063777280] = "Kim loại vừa có tính lưu động vừa cực độc, thường dùng làm môi giới Chuyển Hóa và Phân Tách trong Luyện Kim Thuật.",
      [611399063777536] = "Tinh dầu tượng trưng cho Quấn Quanh và Liên Kết, dùng để tăng Quan Hệ hoặc độ ổn định của Khế Ước.",
      [611399063777792] = "Nước tự nhiên mang nhiều đặc tính khác nhau, dùng làm nền nghi thức tương ứng với từng thuộc tính.",
      [611399063778048] = "Đến từ gấu đen bị Ô Nhiễm Siêu Phàm, tượng trưng cho Hoang Dã, Sức Mạnh và Tiến Hóa Dị Thường.",
      [611399063778304] = "Lấy từ đầu Tê Giác Khát Máu, vật tượng trưng cho tính công kích và phá hoại cực cao.",
      [611399063778560] = "Lấy từ cơ thể Gấu Đen Biến Dị, chứa thuộc tính Cuồng Bạo và Sức Bền.",
      [611399063778816] = "Đến từ lõi Sinh Mệnh của Tê Giác Khát Máu, vật liệu lõi Sinh Mệnh cực kỳ nguy hiểm.",
      [611399063779072] = "Chiết xuất từ cây húng quế, tinh dầu phổ biến dùng để ổn định Tinh Thần và nhịp điệu nghi thức.",
      [611399063779328] = "Khai thác từ mạch khoáng đen, loại quặng màu đen dùng cho Phong Ấn và Phòng Hộ.",
      [611399063779584] = "Đến từ cơ thể Cự Hùng Đen, tượng trưng cho Sức Mạnh áp đảo và Sinh Lực.",
      [611399063779840] = "Lấy từ sinh vật hình người dị thường, một loài vượn vàng nâu có dục vọng săn giết rất mạnh.",
      [611399063780096] = "Lấy từ cơ thể Kẻ Lang Thang Rừng Rậm, mang đặc tính Hoang Dã và Lý Trí bị bóp méo.",
      [611399063780352] = "Đến từ cơ thể Cự Hùng Đen, chứa mật Sinh Mệnh cô đặc cao.",
      [611399063780608] = "Khai thác từ cụm tinh thể tự nhiên, loại bảo thạch phổ biến dùng để ổn định Tinh Thần và Linh Tính.",
      [611399063780864] = "Lấy từ kẻ địch do chính tay mình đánh bại, thường dùng trong nghi thức Huyết Thệ hoặc định hướng Thù Hận.",
      [611399063781120] = "Lấy từ Cự Hùng Kim Loại Hóa, chi thể Siêu Phàm mang đặc tính Kim Loại Hóa.",
      [611399063781376] = "Lấy từ Khỉ Xám Sáu Tay, tượng trưng cho Cảm Tri đa hướng và bản năng chiến đấu.",
      [611399063781632] = "Đến từ cơ thể Cự Hùng Sắt Thép, dòng máu dị thường mang cả đặc tính Kim Loại và Sinh Mệnh.",
      [611399063781888] = "Lấy từ Khỉ Xám Sáu Tay, phụ liệu cường hóa Sức Mạnh và nghi thức Hoang Dã.",
      [611399063782144] = "Được khai quật từ chiến trường thật sự, vật phẩm mang Sát Ý và ký ức Tử Vong.",
      [611399063782400] = "Đến từ người bị chính bản thân đánh bại, vật liệu nghi thức dùng để xác nhận quan hệ Nhân Quả, Chiến Thắng và Chi Phối.",
      [611399063782656] = "Xương lõi chứa dũng khí nghênh đón Quang Minh, có thể dùng để xua tan Sợ Hãi hoặc cường hóa Ý Chí.",
      [611399063782912] = "Chi thể Siêu Phàm chứa sức mạnh Ánh Trăng cùng năng lực xé rách mạnh mẽ, đồng thời mang tính Thần Thánh và Cuồng Bạo.",
      [611399063783168] = "Mật Cự Hùng đã được Ánh Trăng Tịnh Hóa, có thể trung hòa một phần Nguyền Rủa và tăng khả năng Hồi Phục.",
      [611399063783424] = "Móng vuốt sắc bén có thể xé rách Bóng Tối và Hư Huyễn, tượng trưng cho quyết đoán và tính công kích lúc Phá Hiểu.",
      [611399063783680] = "Bảo thạch có màu sắc bên trong biến đổi bất định, có thể tăng hiệu quả Ảo Thuật hoặc gây nhiễu Cảm Tri Linh Tính.",
      [611399063783936] = "Vật phẩm đã được nghi thức đặc định loại bỏ ảnh hưởng tiêu cực, thường dùng làm vật dẫn nghi thức an toàn.",
      [611399063784192] = "Đến từ Tà Nhãn cư ngụ trong vực sâu Mộng Cảnh, có thể khúc xạ và ổn định dao động ảo giác của Sợ Hãi và Hỗn Loạn.",
      [611399063784448] = "Chậm rãi kết tinh trong môi trường Nguyền Rủa sâu, bên trong lưu chuyển Năng Lượng Âm liên tục hoạt hóa.",
      [611399063784704] = "Rỉ ra từ chỗ cơ quan Tà Thị bị vỡ, mang tính Xâm Thực cực mạnh và đặc tính Ô Nhiễm Mộng Cảnh.",
      [611399063784960] = "Cấu trúc vi tinh thể cộng sinh với Thủy Tinh Nguyền Rủa, có thể đồng bộ và khuếch đại tần số Linh Tính của nguồn Nguyền Rủa.",
      [611399063785216] = "Giấy dệt từ sợi Linh Giới, ghi lại ký ức bí mật của người khác.",
      [611399063785472] = "Chưng cất từ hoa và lá, hương thơm chứa hai dao động vừa An Thần vừa Phấn Chấn.",
      [611399063785728] = "Xương có mật độ cực cao, Linh Chất nội sinh chứa sức mạnh man dã nguyên thủy.",
      [611399063785984] = "Cơ quan lõi của loài rùa sống lâu, trong nhịp đập ngưng tụ Sức Bền và Cảm Tri đa góc.",
      [611399063786240] = "Linh Chất cơ bắp hoạt động mạnh, tần số nhịp đập cực cao.",
      [611399063786496] = "Nghiền từ vỏ cứng; cấu trúc tinh thể có thể chắn phần lớn dòng Linh Lực Xung Kích.",
      [611399063786752] = "Chất sừng sinh vật chứa Linh Tính sắc bén, có thể dễ dàng cắt rách cấu trúc vật chất.",
      [611399063787008] = "Mang hiệu quả tê liệt Linh Thể; chạm vào có thể nhanh chóng cản trở dòng chảy Tinh Thần.",
      [611399063787264] = "Trong sợi chất sừng tồn tại Linh Tính tự nhiên dùng để truy dấu và khóa mục tiêu.",
      [611399063787520] = "Phạm vi Linh Thị cực rộng, có thể bắt lấy gợn hình ảnh của ký ức và tương lai gần.",
      [611399063787776] = "Mang nhịp đập Hoang Dã phản ứng nhanh, Cảm Tri Linh Tính cực kỳ nhạy bén.",
      [611399063788032] = "Lông vũ nhẹ, tỏa Linh Tính yếu ớt.",
      [611399063788288] = "Có thể xuyên qua tàn ảnh Linh Hồn để bắt lấy những mảnh suy nghĩ chưa tan.",
      [611399063788544] = "Trong sợi giấy còn lưu dấu ấn Tinh Thần của Bí Thuật cổ xưa, có thể cộng hưởng với tần số Linh Cảm khi ấy.",
      [611399063788800] = "Lõi kết tinh Sinh Mệnh và trí tuệ của Tế Tư Thụ Nhân, chứa sức mạnh Tự Nhiên sâu dày cùng ký ức năm tháng.",
      [611399063789056] = "Cơ quan thị giác cấu thành từ giấy và Bí Pháp, có thể nhìn thấu ngụy trang hoặc tạo ảo giác khó phân biệt thật giả.",
      [611399063789312] = "Chất lỏng chứa Sinh Lực dồi dào và độ thân hòa Tự Nhiên, là môi giới tuyệt vời cho Trị Liệu và thúc sinh trưởng.",
      [611399063789568] = "Tàn dư sau khi Yêu Giấy bị thiêu đốt, chứa thông tin vỡ vụn và khái niệm tiêu vong, thường dùng để xóa bỏ hoặc làm nhiễu.",
      [611399063789824] = "Tạo vật do Phi Phàm Giả ở Bậc cao hơn “Giáo Sư Quyển Trục” chế tạo, Phong Ấn tri thức cao cấp và sức mạnh Phi Phàm; cấu trúc cùng nguyên lý vượt xa phạm vi hiểu biết của người thường.",
      [611399063790080] = "Chất lỏng chưng cất từ Cỏ Rễ Giấy, có thể ổn định Tinh Thần và tăng độ thân hòa với chữ viết, ký hiệu.",
      [611399063790336] = "Sau khi Độ Hảo Cảm Nhân Mạch đạt tối đa, phần Hảo Cảm dư từ các nội dung chơi sẽ chuyển hóa thành vật phẩm này; có thể đổi tại Cửa Hàng Phòng Trưng Bày Vãng Sự.",
      [611399063790592] = "Sau khi dùng nhận danh hiệu: <Highlight>Bạn Của Miêu Quỷ</>",
      [611399063790848] = "Nhận khi tham gia các độ khó của Nhà Hát Utopia; đạt mốc tiến độ nhất định sẽ nhận thưởng, làm mới mỗi tuần.",
      [611399063791104] = "Nhận thêm 1 lượt hồi sinh; có hiệu lực ngay khi mua.",
      [611399063791360] = "Tạo một Ký Ức Tàn Tồn có thể đánh thức ở gần; có hiệu lực ngay khi mua.",
      [611399063791616] = "Tấm da dê ghi Công Thức Ma Dược để thăng lên Bậc 7; khi tiến độ tiêu hóa đạt mức nhất định, Công Ty An Ninh Blackthorn sẽ cung cấp cho thành viên tích cực.",
      [611399063791872] = "Sau khi dùng, hồi 1 điểm Thể Lực Thương Đội trong lối chơi Chiến Tranh Thương Mại.",
      [611399063792128] = "Tiền tệ dùng trong Chiến Tranh Thương Mại, có thể dùng để mua bán hàng hóa.",
      [611399063792384] = "Sau khi dùng có thể biểu diễn <Highlight>Động Tác Mị Ảnh · Liên Xạ Ái Ý</> trong lối chơi Bóng Ma Opera.",
      [611399063792640] = "Sau khi dùng có thể biểu diễn <Highlight>Động Tác Mị Ảnh · Bàn Tay Mời Gọi</> trong lối chơi Bóng Ma Opera.",
