      [611399063856640] = "Sau khi dùng nhận danh hiệu: <Highlight>Người Bảo Hộ Tingen</>",
      [611399063856896] = "Người biểu diễn +750 điểm, đồng thời hiển thị bảng đèn.",
      [611399063857152] = "Sau khi dùng, lần gieo tiếp theo chắc chắn Đại Thành Công. Hiệu ứng này loại trừ lẫn nhau với 【Xúc Xắc Ách Số】, lấy vật phẩm được dùng sau cùng làm chuẩn. Hiệu ứng này không ảnh hưởng kết quả của gameplay gieo xúc xắc tùy chỉnh đặc biệt.",
      [611399063857408] = "Sau khi dùng, lần gieo tiếp theo chắc chắn Đại Thất Bại. Hiệu ứng này loại trừ lẫn nhau với 【Nụ Hôn Vận Mệnh】, lấy vật phẩm được dùng sau cùng làm chuẩn. Hiệu ứng này không ảnh hưởng kết quả của gameplay gieo xúc xắc tùy chỉnh đặc biệt.",
      [611399063857920] = "Sau khi dùng nhận danh hiệu: <Highlight>Đồng Hành Sequence</>",
      [611399063858176] = "Sau khi dùng nhận danh hiệu: <Highlight>Kẻ Si Tình Nhất Loen</>",
      [611399063858432] = "Phần thưởng phân chia ghế Thần Tuyển của server chiến lược.",
      [611399063858688] = "Sau khi dùng, lập tức hồi một phần Lý Trí cho người dùng.",
      [611399063858944] = "Sau khi dùng, lập tức giảm một phần Lý Trí của người dùng.",
      [611399063859200] = "Sau khi dùng, trừ một phần Lý Trí của tất cả người chơi xung quanh người dùng (bao gồm người dùng).",
      [611399063859456] = "Sau khi dùng nhận danh hiệu: <Highlight>Đồng Hành Giả Sương Xám</>",
      [611399063859712] = "Sau khi dùng nhận danh hiệu: <Highlight>Người Cầm Bài Tarot</>",
      [611399063859968] = "Sau khi dùng nhận danh hiệu: <Highlight>Chuyên Gia Thẩm Định Ma Dược</>",
      [611399063860224] = "Sau khi dùng nhận danh hiệu: <Highlight>Hội Viên VIP Bói Toán</>",
      [611399063860480] = "Sau khi dùng nhận danh hiệu: <Highlight>Thực Tập Sinh Phi Phàm</>",
      [611399063860736] = "Sau khi dùng nhận danh hiệu: <Highlight>Lãnh Chúa Tĩnh Lặng</>",
      [611399063860992] = "Sau khi dùng nhận danh hiệu: <Highlight>Thiên Sứ Sao Mai</>",
      [611399063861248] = "Sau khi dùng nhận danh hiệu: <Highlight>Thân Vương U Thâm</>",
      [611399063861504] = "Sau khi dùng nhận danh hiệu: <Highlight>Quân Chủ Vĩnh Dạ</>",
      [611399063861760] = "Sau khi dùng nhận danh hiệu: <Highlight>Chúa Tể Vô Tận</>",
      [611399063862016] = "Sau khi dùng nhận danh hiệu: <Highlight>Hoàng Đế Vĩnh Hằng</>",
      [611399063862272] = "Sau khi dùng nhận danh hiệu: <Highlight>Kẻ Nhìn Xuống Từ Tinh Không</>",
      [611399063862528] = "Sau khi dùng nhận danh hiệu: <Highlight>Cựu Nhật Chi Phối Giả</>",
      [611399063862784] = "Sau khi dùng có thể kích hoạt hiệu ứng phun Champagne. (Trong sự kiện toàn server “Dạ Tiệc Danh Lưu”, có thể tăng Điểm Nhiệt Cá Nhân.)",
      [611399063863040] = "Trong thời gian Câu Lạc Bộ tuyên chiến, <Highlight>Hội Trưởng, Phó Hội Trưởng, Thành Viên Hội Đồng</> có thể dùng vật phẩm này tại Dãy Núi Hornacis để phát lệnh tập kết tới <Highlight>thành viên Câu Lạc Bộ trên bản đồ</>. Sau khi dùng, toàn bộ vật phẩm này của Câu Lạc Bộ sẽ vào hồi chiêu <Highlight>360</> giây.",
      [611399063863296] = "Sau khi dùng nhận danh hiệu: <Highlight>Khoái Thủ Vô Ngân Kinh Chư Thần</>.",
      [611399063863552] = "Sau khi dùng nhận danh hiệu: <Highlight>Thợ Săn Sói Đầu Đàn</>.",
      [611399063863808] = "Sau khi dùng nhận danh hiệu: <Highlight>Cô Lang Độc Hành</>.",
      [611399063864064] = "Sau khi dùng nhận danh hiệu: <Highlight>Nhân Danh Lang Vương</>.",
      [611399063864320] = "Sau khi dùng nhận danh hiệu: <Highlight>Bác Diện Trục Ảnh</>.",
      [611399063864576] = "Sau khi dùng nhận danh hiệu: <Highlight>Tài Quyết Ngụy Diện</>.",
      [611399063864832] = "Sau khi dùng nhận danh hiệu: <Highlight>Chung Yên Vô Diện Giả</>.",
      [611399063865088] = "Sau khi dùng nhận danh hiệu: <Highlight>Tài Quyết Máy Khoan Điện</>.",
      [611399063865344] = "Sau khi dùng nhận danh hiệu: <Highlight>Khắc Tinh Mũi Khoan</>.",
      [611399063865600] = "Sau khi dùng nhận danh hiệu: <Highlight>Đệ Nhất Điện Trị</>.",
      [611399063865856] = "Sau khi dùng nhận danh hiệu: <Highlight>Giờ Khai Tòa</>.",
      [611399063866112] = "Sau khi dùng nhận danh hiệu: <Highlight>Đảo Ngược Phán Quyết</>.",
      [611399063866368] = "Sau khi dùng nhận danh hiệu: <Highlight>Người Thay Mặt Chung Thẩm</>.",
      [611399063866624] = "Sau khi dùng nhận danh hiệu: <Highlight>Khải Hoàn Thiết Huyết</>",
      [611399063866880] = "Sau khi dùng nhận danh hiệu: <Highlight>Cùng Lên Chinh Trình</>",
      [611399063867136] = "Sau khi dùng nhận danh hiệu: <Highlight>Người Hộ Vệ Chiến Thắng</>",
      [611399063867392] = "Sau khi dùng nhận danh hiệu: <Highlight>Kẻ Du Hành Thời Đại</>",
      [611399063867648] = "Chứng từ mua sắm đặc biệt, có thể <Highlight>đổi miễn phí bất kỳ ngoại hình bán trực tiếp nào trong Cửa Hàng</>.",
      [611399063867904] = "Sau khi dùng nhận danh hiệu: <Highlight>Người Của Thệ Minh</>",
      [611399063868160] = "Sau khi dùng nhận danh hiệu: <Highlight>Đồng Hành Huyết Minh</>",
      [611399063868416] = "Sau khi dùng nhận danh hiệu: <Highlight>Khách Quen Tiệc Tùng</>",
      [611399063868672] = "Sau khi dùng nhận danh hiệu: <Highlight>Thượng Khách Danh Lưu</>",
      [611399063869184] = "Sau khi dùng nhận <Highlight>Bộ Trang Phục Thầy Bói (Vĩnh Viễn)</>; nếu đang sở hữu trang phục giới hạn thời gian tương ứng, sẽ gỡ giới hạn thời gian.",
      [611399063869440] = "Sau khi dùng nhận <Highlight>Bộ Trang Phục Học Đồ</>; nếu đang sở hữu trang phục giới hạn thời gian tương ứng, sẽ gỡ giới hạn thời gian.",
      [611399063869696] = "Sau khi dùng nhận <Highlight>Bộ Trang Phục Thầy Bói</>; nếu đang sở hữu trang phục giới hạn thời gian tương ứng, sẽ gỡ giới hạn thời gian.",
      [611399063869952] = "Sau khi dùng nhận <Highlight>Bộ Trang Phục Kẻ Dòm Ngó Bí Ẩn</>; nếu đang sở hữu trang phục giới hạn thời gian tương ứng, sẽ gỡ giới hạn thời gian.",
      [611399063870208] = "Sau khi dùng nhận <Highlight>Bộ Trang Phục Chiến Sĩ</>; nếu đang sở hữu trang phục giới hạn thời gian tương ứng, sẽ gỡ giới hạn thời gian.",
      [611399063870464] = "Sau khi dùng nhận <Highlight>Bộ Trang Phục Ca Tụng Giả</>; nếu đang sở hữu trang phục giới hạn thời gian tương ứng, sẽ gỡ giới hạn thời gian.",
      [611399063870720] = "Sau khi dùng nhận <Highlight>Bộ Trang Phục Khán Giả</>; nếu đang sở hữu trang phục giới hạn thời gian tương ứng, sẽ gỡ giới hạn thời gian.",
      [611399063870976] = "Chứng vật tối cao chứng minh người chiến thắng từng bước lên Đỉnh Chư Thần. Có thể dùng chứng vật này để hiển hiện tượng cá nhân trong đại thế giới, cho mọi người chiêm ngưỡng.",
      [611399063871232] = "Sau khi dùng nhận danh hiệu: <Highlight>Quyến Giả Kẻ Khờ</>",
      [611399063871488] = "Nhận 1 <Highlight>Pháp Điển Khải Hoàn · Tranh Đoạt Thần Tọa</> và <Highlight>25 Huy Hiệu Khải Hoàn</>.",
      [611399063871744] = "Sau khi dùng nhận danh hiệu: <Highlight>Bạn Của Khỉ Đầu Chó</>",
      [611399063872000] = "Có thể dùng phiếu này khi thanh toán <Highlight>ngoại hình bán trực tiếp trong Cửa Hàng</> để giảm 25% đơn giá; mỗi sản phẩm tối đa dùng 2 phiếu.",
      [611399063872256] = "Sau khi dùng, có thể biểu diễn <Highlight>Động Tác Mị Ảnh · Ngọt Ngào Gấp Đôi</> trong gameplay Bóng Ma Ca Kịch.",
      [611399063872512] = "Sau khi dùng, có thể biểu diễn <Highlight>Động Tác Mị Ảnh · Ngoảnh Nhìn Thanh Nhã</> trong gameplay Bóng Ma Ca Kịch.",
      [611399063872768] = "Sau khi dùng, có thể biểu diễn <Highlight>Động Tác Mị Ảnh · Hiệu Triệu Cổ Vũ</> trong gameplay Bóng Ma Ca Kịch.",
      [611399063873024] = "Sau khi dùng, có thể biểu diễn <Highlight>Động Tác Mị Ảnh · Gửi Nụ Hôn Gió</> trong gameplay Bóng Ma Ca Kịch.",
      [611399063873280] = "Sau khi dùng nhận danh hiệu: <Highlight>Ta Đã Trở Lại</>",
      [611399063873536] = "Vật phẩm nâng cấp Trang Bị Lạc Ấn.\nCó thể nâng Nhẫn Lạc Ấn phẩm chất Vàng cấp trang bị 55 <Highlight>Nhẫn Trì Trệ</> lên <Highlight>phẩm chất Cam cấp trang bị 62</>; khi nâng tiêu hao <Highlight>3</> Linh Tính Minh Thạch.",
      [611399063873792] = "Vật phẩm nâng cấp Trang Bị Lạc Ấn.\nCó thể nâng Mũ Lạc Ấn phẩm chất Vàng cấp trang bị 60 <Highlight>Gai Xao Động</> lên <Highlight>phẩm chất Cam cấp trang bị 62</>; khi nâng tiêu hao <Highlight>3</> Neo Lịch Sử.",
      [611399063874048] = "Vật phẩm nâng cấp Trang Bị Lạc Ấn.\nCó thể nâng Áo Choàng Lạc Ấn phẩm chất Vàng cấp trang bị 60 <Highlight>Trò Đùa Của Hề</> lên <Highlight>phẩm chất Cam cấp trang bị 62</>; khi nâng tiêu hao <Highlight>3</> Lạc Ấn Phi Phàm.",
      [611399063874304] = "Vật phẩm nâng cấp Trang Bị Lạc Ấn.\nCó thể nâng Giày Lạc Ấn phẩm chất Vàng cấp trang bị 35 <Highlight>Ủng Da Ấm Áp</> lên <Highlight>phẩm chất Cam cấp trang bị 62</>; khi nâng tiêu hao <Highlight>1</> Mảnh Vỡ Quá Khứ.",
      [611399063874560] = "Vật phẩm nâng cấp Trang Bị Lạc Ấn.\nCó thể nâng Nhẫn Lạc Ấn phẩm chất Vàng cấp trang bị 45 <Highlight>Hạch Tâm Cơ Giới</> lên <Highlight>phẩm chất Cam cấp trang bị 62</>; khi nâng tiêu hao <Highlight>1</> Hạt Cát Thời Gian.",
      [611399063874816] = "Vật phẩm nâng cấp Trang Bị Lạc Ấn.\nCó thể nâng Bùa Hộ Mệnh Lạc Ấn phẩm chất Vàng cấp trang bị 60 <Highlight>Tàn Tro Đỏ Tươi</> lên <Highlight>phẩm chất Cam cấp trang bị 62</>; khi nâng tiêu hao <Highlight>1</> Kết Tinh Ký Ức.",
      [611399063875072] = "Placeholder vật phẩm nâng cấp.",
      [611399600442368] = "Chén Thánh đặc biệt có thể giao tiếp và kết nối Linh Giới.\nTừng là vật sưu tầm của Nữ Vương Huyết Nguyệt “Mỹ Thần” Auernia; có thể dùng làm môi giới để tạm thời lập khế ước với sinh vật Linh Giới trung thành với “Mỹ Thần”, sai khiến chúng mang vật phẩm Thần Quyến từ Linh Giới về.",
      [611399600442880] = "Một lá bài đặc biệt khảm đá quý quý giá, dung chứa khái niệm về “cái đẹp” trong Linh Giới. Sau khi được sinh vật Linh Giới mang về hiện thực, nó có thể hóa thành nhiều loại vật sưu tầm quý giá nhất của Mỹ Thần.",
      [611399600443136] = "Một lá bài chứa lượng Linh Tính khổng lồ. Người sở hữu có thể dùng làm môi giới để giao tiếp với Linh Giới, trao đổi vận may và vận mệnh, từ đó lấy bảo vật từ Linh Giới.",
      [611399600443392] = "Một đồng tiền cổ ánh sắc Tinh Không, có thể thông qua thể tinh thần để cộng hưởng với Linh Giới và Tinh Không. Trên đó khắc minh văn bí ẩn do Thiên Sứ của gia tộc Abraham vẽ; mỗi lần sử dụng như mở ra một chuyến du hành Tinh Không, đem lại cho người dùng kiến văn và thu hoạch trên hành trình.",
      [611399600443648] = "Một lưỡi dao sắc bén có thể cắt sợi tơ vận mệnh. Người nắm giữ vận mệnh cũng bị vận mệnh chi phối; mỗi nhát cắt đều mang đến biến đổi chưa biết. Mong vận may luôn đồng hành cùng bạn.",
      [611399600443904] = "Placeholder.",
      [611399600444160] = "Tinh lộ trong suốt rực rỡ, là vật liệu nhuộm được thợ may ưa chuộng nhất; nhưng công thức được nghiên cứu độc quyền, trên đời chỉ có rất ít người biết.",
      [611399600444416] = "Thuốc nhuộm sủi bọt, màu sắc rực rỡ và dễ lên màu.",
      [611399600444672] = "Thuốc nhuộm đặc biệt được nghiền và pha chế từ san hô, màu sắc bền và tươi.",
      [611399600444928] = "Thuốc nhuộm làm từ vật liệu bí ẩn, tỏa ánh bóng trong trẻo.",
      [611399600445184] = "Phong cách thời thượng được chứng minh từ đây.",
      [611399600445440] = "Lấy đây làm ấn, phong tồn một diện mạo khác.",
      [611399600445696] = "Ánh trăng rơi vào băng tinh, thời gian cũng dừng lại vì nó; chi bằng hóa khoảnh khắc này thành vĩnh hằng.",
      [611399600446208] = "Mỗi đồng vàng đều tượng trưng cho một lần hoàn thành ủy thác, một lần cùng nhau bảo hộ, một lần sẻ chia vinh dự; kết tinh lời thề chung và đóng góp tập thể của các thành viên Câu Lạc Bộ.",
      [611399600446464] = "Hãy nhớ, bạn chỉ đang nhập vai.",
      [611399600446720] = "Hãy nhớ bạn chỉ đang nhập vai.",
      [611399600446976] = "Dùng để mua nội thất và nâng cấp Lâu Đài.",
      [611399600447232] = "Dùng để tăng cấp và mua quân cờ.",
      [611399600447488] = "Không chỉ đại diện cho tài nguyên, đây còn là minh chứng cho nỗ lực chung của mọi thành viên trong việc xây dựng Câu Lạc Bộ. Câu Lạc Bộ sẽ cùng chung vận mệnh với tất cả thành viên.",
      [611399600447744] = "Thạch Anh Tím mang lại may mắn, có thể dùng để đổi vật phẩm trong cửa hàng.",
      [611399600448000] = "Mảnh hình ảnh trôi nổi giữa màn sương lịch sử.",
      [611399600448256] = "Tích lũy nhận thức, thúc đẩy nhập vai; nhưng biết quá nhiều sẽ dần nhiễm Thần Tính. Điều đó mang đến sức mạnh, đồng thời cũng kéo theo điên cuồng.",
      [611399600449280] = "Lớp da lột của sinh vật Linh Giới, dưới ánh trăng tỏa ra ánh sáng nhàn nhạt.",
      [611399600449536] = "Sợi Tơ Linh Tính rút ra từ “Khe Hở Lịch Sử”, quấn quanh vô số khả năng của vận mệnh.",
      [611399600449792] = "Một chiếc lông vũ phát sáng nhè nhẹ, nhẹ tựa hư vô; mơ hồ có thể cảm nhận phúc lành thần thánh ẩn chứa bên trong.",
      [611399600450048] = "Làn gió nhẹ thu thập từ khe nứt Linh Giới.",
      [611399600450304] = "Một tờ giấy da dê ố vàng, trên đó viết vài dòng chú văn mơ hồ bằng Cổ Hermes; thấp thoáng có thể cảm nhận sức mạnh Linh Tính hùng hậu nối tới phía bên kia khế ước.",
      [611399600450560] = "Tinh Trần thần bí trôi nổi sâu trong Linh Giới.",
      [611399600451072] = "Một trang của Sách Đồng, minh chứng cho vinh dự khiêu chiến.",
      [611399600451840] = "Con dấu sáp của nền văn minh hơi nước. Trong cải cách của Đại Đế Roselle, văn thư pháp luật và kỹ thuật hơi nước đều được coi trọng; con dấu này chính là bằng chứng tiêu biểu.",
      [611399600453376] = "Khai thác từ một mỏ ở thành phố Constant, quận Midseashire thuộc Vương quốc Loen. Dù cả thành phố bị chiến tranh tàn phá nghiêm trọng, nơi đây cũng vì thế mà có lượng lớn vật liệu chứa Linh Tính. Do quanh mỏ thường lưu truyền những lời đồn kỳ quái, công nhân chỉ dám khai thác đá lửa ở lớp ngoài cùng.",
      [611399600453632] = "Lần này, xoay chìa khóa không phải để mở ra, mà để khóa thứ gì đó lại.",
      [611399600453888] = "Khai thác từ đảo Blue Mountain, đảo lớn nhất quần đảo Rorsted. Nơi đây giàu khoáng sản, và Tinh Thạch Lam Sơn là một loại khá được ưa chuộng.",
      [611399600454144] = "Kết Tinh Linh Chất tinh khiết được tinh luyện từ trang bị, tỏa ánh sáng rực rỡ như một ngôi sao nhỏ bé nhưng mạnh mẽ.",
      [611399600454912] = "Ngài “Kẻ Khờ” định vị vô số Sinh Vật Thần Thoại trong lịch sử, dùng “Giá Tiếp” chuyển sức mạnh về Nguyên Bảo và tạo ra Kén Dệt Thần Thoại.",
      [611399600455168] = "Không phải toàn bộ sức mạnh thần thoại đều ngưng tụ thành kén hoàn chỉnh. Một số sức mạnh không đủ mạnh, chỉ có thể trở thành những sợi tơ rời rạc.",
      [611399600455424] = "Khi Kén Dệt Thần Thoại sinh ra trên Nguyên Bảo, Sương Xám cũng cuốn lên vô số bụi.",
      [611399600455680] = "Khi Kén Dệt Thần Thoại sinh ra trên Nguyên Bảo, Sương Xám cũng ngưng kết thành vô số hạt tinh thể.",
      [611399600456704] = "Tinh thạch mang quang huy nóng rực; sử dụng nó có thể khơi lại tiềm năng cao nhất mà trang bị từng sở hữu.",
      [611399600456960] = "Vật chất kỳ dị ở trạng thái tinh thể bán trong suốt, lóe ánh u quang yếu ớt, hình dạng thường biến đổi không ngừng.",
      [611399600457216] = "Ngọn đèn chứa sức mạnh thần bí; khi thắp lên có thể gõ mở cánh cửa Hành Lang Lịch Sử.",
      [611399600457472] = "Nhân tố nguyên thủy kết tủa sau khi vật chất Phi Phàm vỡ vụn, có thể dùng làm môi giới cho sự tụ hợp Phi Phàm.",
      [611399600457984] = "Một nhánh phụ của vận mệnh, tựa ráng chiều đông cứng, lại như bình minh không bao giờ tắt trong một thế giới song song nào đó.",
      [611399600458240] = "Có thể tinh chỉnh chính xác từng bánh răng và van của xe hơi nước, tái định hình trạng thái vận hành của phương tiện. Người nắm giữ ấn này mới xứng là bậc thầy điều khiển máy móc thực thụ.",
      [611399600459264] = "Sợi Chỉ Vàng nhiễm đậm khí tức Sương Xám; có thể dùng tại Nhà Hát Utopia để tìm Bí Ngẫu.",
      [611399600462592] = "Hương bia thanh nhẹ quyện cùng bơ đậm đà, ấm áp ngọt dịu, uống vào trơn mượt đầy miệng.",
      [611399600462848] = "Rượu trong óng ánh, vào miệng êm mượt; tỷ lệ hương vị hài hòa tạo nên mùi thơm dễ chịu.",
      [611399600463104] = "Rượu chưng cất đặc sản miền bắc Loen, độ rượu dữ dội đủ xua tan mọi cơn gió rét.",
      [611399600463360] = "Rượu màu đỏ vàng như mật ong loãng pha máu, ngọt dịu đậm đà; cẩn thận đừng quá chén.",
      [611399600463616] = "Làm từ gỗ cứng nâu sẫm, rẻ và chắc; dằm gỗ trên bề mặt cần tự xử lý trong quá trình sử dụng.",
      [611399600463872] = "Nồi súp gia dụng rèn bằng sắt đen; chất liệu dày nặng rất hợp để hầm chậm món súp mùa đông.",
      [611399600464128] = "Lắc một chút, ngâm một chút — hương cà phê nồng nàn chỉ có thể được tạo ra bằng cối xay cà phê quay tay!",
      [611399600464384] = "Kiểu dáng tinh xảo nhỏ gọn, phím bấm có độ nảy rõ ràng; công cụ được các nhà văn du ký ưa chuộng.",
      [611399600464640] = "Mô phỏng kiểu dáng đoàn tàu kinh điển “Thomas”; mua kèm tặng đường ray.",
      [611399600464896] = "Đồng hồ để bàn bằng gỗ gụ, tao nhã trang trọng; bên trong có chim báo giờ cơ khí. Mua dịch vụ bảo dưỡng sẽ được tới tận nhà chỉnh âm lượng.",
      [611399600465152] = "Nòng súng đen ánh lên sắc lạnh; những vết mòn trên tay cầm ghi lại nhiều cuộc giao tranh giữa đêm khuya.",
      [611399600465408] = "Sản phẩm của công nghệ hơi nước, uy lực cực lớn; mỗi lần khai hỏa hơi nước phun trào, là hiện thân của sức mạnh và công nghiệp.",
      [611399600465664] = "Bên trong dùng đồng thau chịu mài mòn, bảo đảm sau thời gian dài sử dụng kim vẫn vận hành chính xác.",
      [611399600465920] = "Hộp và búp bê chịu va đập tốt, dây cót vặn mạnh đến đâu cũng không đứt; thiết kế riêng cho trẻ hiếu động.",
      [611399600466176] = "Ngoại hình tham khảo ý kiến của những người sành búp bê lâu năm. Có thể dùng làm vật trang trí, đồ chơi, hoặc một người bạn.",
      [611399600468480] = "Chế biến sữa bò hảo hạng rồi lọc bỏ nước, tạo thành thực phẩm không thể thiếu trên bàn ăn.",
      [611399600468736] = "Chiết xuất từ cây phong đường, màu vàng óng, chất siro mượt, vị ngọt cỏ cây thanh nhẹ; bạn đồng hành hoàn hảo của bánh kếp nóng.",
      [611399600468992] = "Tôm biển được trải phẳng phơi khô giữ vị tươi, rồi nướng than đến màu hổ phách — hương vị biển cả, Tôm Khô Hổ Phách!",
      [611399600469248] = "Quý như ngọc trai, quà tặng từ đại dương; vị mặn tươi, giòn sần sật, phẩm vị thượng hạng.",
      [611399600469504] = "Đường may chắc, vạt áo rộng; khi giơ tay làm việc sẽ không cảm thấy bó.",
      [611399600469760] = "Như cái ôm của người bạn cũ, vẻ thô ráp bao bọc một tâm hồn tinh tế.",
      [611399600470016] = "Khi vạt áo lướt qua đèn đường, dường như luôn có bí mật khẽ xào xạc trong những nếp gấp.",
      [611399600470272] = "Đường cắt tựa cánh én, tà sau khẽ bay; ẩn trong đó là một yến tiệc chưa khai màn.",
      [611399600470528] = "Bạn đồng hành tuyệt nhất của giấc mơ, khiến cả giấc ngủ cũng mang vẻ hoa lệ.",
      [611399600470784] = "Như một bài sonnet dệt bằng ánh trăng; mỗi lần xoay người lại viết tiếp một chương hoa mỹ còn dang dở.",
      [611399600471040] = "Cashmere thượng hạng mềm như mây, diễn giải sự xa hoa kín đáo của đời sống quý tộc.",
      [611399600471296] = "Lụa óng ánh xà cừ; khoác lên người, bạn nhất định sẽ là viên ngọc sáng nhất buổi dạ hội.",
      [611399600471552] = "Khi tháo mũ khẽ cúi đầu — có mũ lễ, có lễ độ.",
      [611399600471808] = "Sự dịu dàng lướt qua đầu ngón tay, biến mỗi lần chạm thành khoảnh khắc khiến người ta say mê.",
      [611399600472064] = "Buộc một phép tu từ im lặng nơi cổ, gấp tâm sự thành đóa hoa không bao giờ tàn.",
      [611399600474368] = "Nung từ gốm thô, trang trí theo phong cách truyền thống của Vương quốc Loen; tao nhã mà hoa lệ.",
      [611399600474624] = "Chế tác bằng kỹ thuật thổi thủy tinh, kiểu dáng lộng lẫy. Phù hợp với mọi khoảnh khắc đáng để chúc mừng.",
      [611399600474880] = "Dao ngắn chuyên dùng rạch mở phong bì. Cán men khảm chỉ vàng, hoa mỹ và cầu kỳ.",
      [611399600475136] = "Tác phẩm truyền đời chế tác tinh xảo. Thân đàn làm từ gỗ gụ thượng hạng nhất Nam Đại Lục, âm sắc dày và êm.",
      [611399600475392] = "Một văn bản khế ước ố vàng, buộc bằng dây lanh xanh, tỏa ra sức mạnh của Trật Tự; không thể bóp méo, không thể phá hủy.",
      [611399600477184] = "Kỳ vật vô tuyến do thợ thủ công chế tạo, có thể truyền giọng nói của người dùng ra ngoài Ngũ Hải.",
      [611399600477440] = "Kỳ vật phát thanh được gia thêm sức mạnh Phi Phàm, biến tiếng lòng của người dùng thành những chiếc lông ấm áp, nhẹ nhàng truyền ra ngoài Ngũ Hải.",
      [611399600477696] = "Kỳ vật phát thanh được gia thêm sức mạnh Phi Phàm, biến lời tuyên cáo của người dùng thành tiếng sấm, nhanh chóng truyền ra ngoài Ngũ Hải.",
      [611399600480256] = "Hình Chiếu Lịch Sử của Leonard Mitchell, tái hiện hình thái và một phần năng lực của bản thể.",
      [611399600480512] = "Hình Chiếu Lịch Sử của Dunn Smith, tái hiện hình thái và một phần năng lực của bản thể.",
      [611399600480768] = "Hình Chiếu Lịch Sử của Daly Simone, tái hiện hình thái và một phần năng lực của bản thể.",
      [611399600481024] = "Hình Chiếu Lịch Sử của Audrey Hall, tái hiện hình thái và một phần năng lực của bản thể.",
      [611399600481280] = "Hình Chiếu Lịch Sử của Fors Wall, tái hiện hình thái và một phần năng lực của bản thể.",
      [611399600481536] = "Hình Chiếu Lịch Sử của Alger Wilson, tái hiện hình thái và một phần năng lực của bản thể.",
      [611399600482048] = "Hình Chiếu Lịch Sử của Susie, tái hiện hình thái và một phần năng lực của bản thể.",
      [611399600482304] = "Hình Chiếu Lịch Sử của Lovia Tiffany, tái hiện hình thái và một phần năng lực của bản thể.",
      [611399600482816] = "Hình Chiếu Lịch Sử của Old Neil, tái hiện hình thái và một phần năng lực của bản thể.",
      [611399600483072] = "Hình Chiếu Lịch Sử của Frye Oakon, tái hiện hình thái và một phần năng lực của bản thể.",
      [611399600483328] = "Hình Chiếu Lịch Sử của Frank Lee, tái hiện hình thái và một phần năng lực của bản thể.",
      [611399600483584] = "Hình Chiếu Lịch Sử của Benson Moretti, tái hiện hình thái và một phần năng lực của bản thể.",
      [611399600483840] = "Hình Chiếu Lịch Sử của Melissa Moretti, tái hiện hình thái và một phần năng lực của bản thể.",
      [611399600506368] = "Khi cư dân Tingen đều chìm vào giấc mơ, phải có người giữ tỉnh táo để chống lại điên cuồng.",
      [611399600528384] = "Máu của con mồi — đó chính là dấu ấn duy nhất của quyền bính.",
      [611399600528640] = "Một loại vật liệu đặc biệt có thể dùng làm nền pha chế Ma Dược. Đây là chiến lợi phẩm chỉ thuộc về bạn, không ai có thể cướp đoạt.",
      [611399600528896] = "Một loại vật liệu đặc biệt có thể dùng làm nền pha chế Ma Dược. Đây là của cải mà ai cũng thèm muốn, không ai không tranh giành.",
      [611399600529408] = "Đây là dư âm tiếng thở dài của chiến trường, cũng là hồi âm tất yếu của vận mệnh.",
      [611399600530176] = "Cuộc săn sinh tử dưới bóng Cấm Khu; mỗi nét đều là dấu ấn nặng nề về quyền sinh tồn của Thợ Săn.",
      [611399600531200] = "Dùng thử tạm thời.",
      [611399600531456] = "Hỡi dũng sĩ khải hoàn trở về, hãy đón lấy tiếng reo hò chiến thắng!",
      [611399600531712] = "Đầu đạn lõi thép mật độ cao do công nghiệp quân sự nặng luyện thành, đủ sức xuyên giáp hạng nặng và xoay chuyển chiến cuộc.",
      [611399600531968] = "Lông cáo mềm, dày xốp; đi chân trần qua cũng tận hưởng cảm giác êm mượt.",
      [611399600532224] = "Một quả cầu pha lê tỏa ánh tím, tượng trưng cho sức gắn kết của Câu Lạc Bộ cùng mức độ hoạt động và đóng góp của bạn.",
      [611399600532480] = "Mỗi lần thanh toán chi phí đều bắt đầu từ việc dán hóa đơn cho tử tế.",
      [611399600532736] = "Hãy bắt đầu một ngày tràn đầy sức sống!",
      [611399600533248] = "Mảnh thu thập cốt truyện dạng tự sự phân mảnh.",
      [611399600537088] = "“Khi Hình Chiếu Lịch Sử của Vật Phong Ấn tan biến, nó sẽ để lại một phần khí tức lịch sử chỉ thuộc về mình.” “Những thứ này dùng làm gì?” “Đương nhiên, Khí Tức Lịch Sử có thể nâng cấp và tăng năng lực của Vật Phong Ấn, tối đa lên cấp 1 — tức trạng thái Nguy Hiểm Cao.” “Có thể nâng lên cấp 0 không?” “Cấp 0? Mấy cái đầu nhỏ ngây thơ của các cậu cũng dám nghĩ thật đấy. Ít nhất đạt Bậc Trung rồi hãy tính chuyện đó!”",
      [611399600538624] = "Những cánh hoa đỏ sẫm khiến người ta khó quên.",
      [611399600538880] = "Hít sâu một hơi, bình tâm an tĩnh. (Mỗi lần chỉ có thể mang 3 đóa)",
      [611399600542720] = "Ma thủy năng lượng đặc biệt ghi lại kinh nghiệm trưởng thành của những người Phi Phàm khác. Sau khi dùng có thể nhanh chóng trải qua con đường trưởng thành của các Phi Phàm giả mạnh mẽ, giúp bản thân vượt qua thời kỳ yếu ớt và nhận 10000 EXP.",
      [611399600544256] = "Tri thức thần bí, nguồn gốc chưa rõ; thời gian như đông cứng trong đó, cô đọng sự thấu hiểu về cách vận dụng năng lực.",
      [611399600544512] = "Mượn sức mạnh từ quá khứ; hiểu lịch sử tương ứng càng chi tiết, tỷ lệ thành công càng cao.",
      [611399600544768] = "Khi chiếc mặt nạ ban cho con rối sinh mệnh mới, vạn vật đều có thể lên sân khấu và mở màn vì bạn.",
      [611399600545024] = "Một loại vật ngang giá được Thương Hội công nhận trong chế độ Đại Gia Đường Sắt, phát hành dưới dạng phiếu.",
      [611399600545280] = "Vài trang văn kiện thể hiện sự cho phép của Thương Hội đối với quyền lưu thông đường sắt — điểm khởi đầu cho giấc mơ của một đại gia thương giới.",
      [611399600545536] = "Hai bánh răng dày, một lớn một nhỏ, có thể dùng để nâng cấp tàu hỏa.",
      [611399600546304] = "Biểu tượng danh dự nhận được sau khi tham gia chế độ Đỉnh Chư Thần.",
      [611399600547584] = "Hãy nhớ, bạn tôi, ở Tingen... khi nhận được thứ này, cậu đã không còn là một “công dân tốt”, mà là người của chúng ta. Chào mừng đến với thế giới trật tự chân thực. Giờ thì nhận thưởng, hoặc biến.",
      [611399600549120] = "Tội ác trong bóng tối đều đã được định giá.",
      [611399600549376] = "Nhìn cho kỹ, đây mới là “Công Dân Năm Sao Tingen”. Đừng bận tâm đống rác mạ vàng do lũ ngu ở Tòa Thị Chính phát — chúng biết cái quái gì.",
      [611399600552192] = "Kiến thức và trải nghiệm tích lũy qua rèn luyện sẽ giúp bạn kiểm soát sức mạnh Phi Phàm tốt hơn.",
      [611399600552448] = "Huân chương danh dự cao nhất do Tòa Thị Chính trao tặng. Nó không chỉ là điểm cuối của hành trình khám phá, mà còn là một kỷ niệm — về tất cả những gì chính tay bạn đã cứu vãn, để Tingen một lần nữa trở nên vĩ đại. Theo cách của riêng bạn.",
      [611399600552704] = "Bạn đã thu thập đủ mọi chương thất lạc. Những tri thức này ghép lại hoàn chỉnh trong tâm trí, dựng nên một Roselle Gustav chân thực hơn bất kỳ sử sách nào.",
      [611399600557312] = "Khi Sương Xám cuộn trào, khi Quả Cầu Thạch Anh Vàng phản chiếu bóng hình dị hương, luôn có những người nhận ra trong mắt nhau tia sáng không thuộc về thời đại này — sự ăn ý đến từ cùng một quê hương.",
      [611399600560640] = "Phơi bày điểm yếu của kẻ địch, tích lũy từng tầng rồi bóp cò, gây sát thương, Trọng Thương và Choáng. Đổi lại, mỗi phát bắn đều phải rót Linh Tính, tiêu hao Thể Lực và khiến điểm yếu của bản thân lộ ra trong chốc lát.",
      [611399600560896] = "Ánh sáng tỏa ra sưởi ấm bạn và đồng đội gần đó, tăng Tấn Công và Tăng Cường Kỹ Năng. Nhưng nhiệt độ áp sát cũng thiêu đốt người sở hữu; sau khi dùng Kỹ Năng Bản Nguyên, bạn sẽ liên tục mất Sinh Mệnh.",
      [611399600561152] = "Quà tặng của tiểu thư “Chính Nghĩa”, mang lại cảm giác an tâm khó tả. Giảm sát thương bạn phải chịu và biến đau khổ thành tài sản: càng tích lũy nhiều sát thương đã chịu, Phòng Ngự càng tăng. Nhưng nếu gánh tài sản quá lâu, bạn sẽ kiệt sức vì sức nặng.",
      [611399600561408] = "Chiếc nhẫn vàng nạm ruby lấp lánh. Khi hấp hối, nó hút máu thịt từ kẻ địch gần đó, giúp bạn hết lần này tới lần khác trở về từ bờ vực cái chết. Cái giá của việc đánh mất Lý Trí là đôi lúc bạn trở nên trì độn trong chiến đấu và bị giảm Tốc Di Chuyển.",
      [611399600561664] = "Hoàn thành luyện thành sinh mệnh đến cực hạn, dùng sức sống tăng trưởng mạnh mẽ để hồi phục Sinh Mệnh vào thời khắc then chốt. Đổi lại, cơ thể dần dị biến, Tốc Di Chuyển và Phòng Ngự liên tục giảm.",
      [611399600561920] = "Tạo ra những vảy ảo ẩn dưới da, khiến bạn khó bị bắt giữ như cá. Khi bị thương, cộng dồn Súc Thương và Né Khống Chế. Nhưng sau khi lên bờ, bạn dễ mệt hơn người thường và tiêu hao Thể Lực nhanh hơn.",
      [611399600562176] = "Khi kẻ địch tấn công bạn, chúng ngẫu nhiên nhiễm các độc tố như Tê Liệt, Suy Yếu; đủ tầng sẽ chuyển biến xấu. Khi bạn chết, còn để lại một Vũng Độc. Nhưng là người sở hữu, bạn cũng không tránh khỏi độc tố bốc hơi ngược lên chính mình.",
      [611399600562432] = "Sau khi dùng Kỹ Năng Bản Nguyên, các đòn vung đánh được thêm hiệu ứng Phong Nhận, tăng Tốc Di Chuyển, Phá Phòng và Tăng Cường Kỹ Năng. Đồng thời, vì giọng hát tệ hại của vị ca sĩ này, bạn sẽ định kỳ nhận các hiệu ứng bất lợi như Giam Cầm, Câm Lặng và giảm thuộc tính.",
      [611399600562688] = "Sau khi đánh thường hoặc dùng kỹ năng, có xác suất nhận May Mắn, tăng Tốc Di Chuyển, Bạo Kích và Tăng Cường Kỹ Năng; có thể cộng dồn nhiều lần, nếu chưa kích hoạt thì xác suất tiếp tục tích lũy. Nhưng khi May Mắn kết thúc, bạn rơi vào Khô Kiệt, giảm Tốc Di Chuyển và hồi Thể Lực.",
      [611399600562944] = "Tạo một Trăng Tròn quanh người. Kẻ địch gần đó làm bạn bị thương sẽ bị giảm tốc, đồng thời tăng Giảm Thương của bạn; khi bạn gây sát thương lên địch, nhận Tăng Sát Thương. Nếu một thời gian không gây sát thương, máu dần lạnh đi và Thể Lực không thể hồi phục.",
      [611399600563200] = "Trong một số tình huống đặc biệt, có lẽ bạn có thể cầu nguyện Đèn Thần, đổi lấy Sinh Mệnh Tối Đa, Hoàn Trả Hồi Chiêu hoặc bùng nổ Đánh Thường. Nhưng mọi điều ước đều có giá và phải hoàn trả trong tương lai.",
      [611399600563456] = "Thay kỹ năng Giải Khống Chế của bạn bằng “Chứng Nhận Vinh Quang” mạnh hơn. Ánh sáng dày đặc bao phủ cơ thể, cho Bá Thể và Giảm Thương, đồng thời hoàn trả sát thương cho kẻ tấn công cận thân; khi kết thúc, phá vỡ lao tù khiến kẻ địch Chói Mắt. Phản Sát Thương sẽ kéo dài hồi chiêu của nó.",
      [611399600563712] = "Sở hữu vũ khí này sẽ ban cho bạn sức mạnh của gió và điện. Tăng Tốc Di Chuyển và Tốc Đánh của Đánh Thường; khi Đánh Thường trúng, có xác suất giáng sét lên mục tiêu, gây sát thương và Trì Trệ. Nhưng nếu bất cẩn, sét cũng có thể bổ vào chính bạn.",
      [611399600563968] = "Từ từ gây ảnh hưởng lên đơn vị địch ở gần, khiến chúng Mê Lạc, hành động chậm chạp và tay chân không thể cử động. Nếu chúng dám tấn công bạn, vận rủi này sẽ đến nhanh hơn. Là người sở hữu, chính bạn cũng định kỳ rơi vào Mê Lạc.",
      [611399600564224] = "Khi chịu đòn chí tử, Người Giấy sẽ xuất hiện trong chốc lát, thay bạn gánh phần sát thương vượt quá trong một khoảng thời gian. Nhưng khi nó biến mất, một phần sát thương đó vẫn quay lại tác dụng lên bạn và khiến bạn yếu hơn trong một thời gian.",
      [611399600564480] = "Chỉ cần thương thế chưa nghiêm trọng, chiếc nhẫn sẽ liên tục hồi Sinh Mệnh cho bạn. Nếu Sinh Mệnh đã đầy, nó sẽ chuyển sang chữa trị đồng đội có lượng máu thấp nhất. Nó cũng thu hút muỗi, khiến Khiên bạn sở hữu dần tan theo thời gian.",
      [611399600564736] = "Nắm giữ năng lực Chuyển Dời Sát Thương. Sau khi chịu trọng kích trong thời gian ngắn, bạn có thể Giá Họa phần lớn sát thương tiếp theo sang người khác; trực giác trước nguy hiểm giúp né Khống Chế. Nhưng hư vọng rồi sẽ tan, cảm xúc bị khuếch đại mang đến nhạy cảm và đau đớn, khiến bạn tạm thời rơi vào Tăng Thương.",
      [611399600564992] = "Nhìn qua nó, Linh Thể trở nên rõ ràng còn hiện thực mờ đi. Trong chiến đấu, khi bật Linh Thị, bạn nhận Phúc Lành Linh Thể, liên tục hồi Sinh Mệnh và giảm sát thương phải chịu; nhưng thời gian Linh Thị ngắn hơn và hồi chiêu dài hơn. Khi kết thúc, thị lực tổn thương, giảm Đỡ Đòn và Phòng Ngự.",
      [611399600565248] = "Ngay khi bước vào chiến đấu, Búp Bê Vận Rủi sẽ chờ cơ hội quấy phá. Khi kỹ năng trúng địch, búp bê nhập vào chúng, giảm Phòng Ngự và Kháng Bạo Kích, đồng thời chuyển theo khi bạn đổi mục tiêu. Khi nó trở về trên người bạn, vận rủi sẽ do bạn gánh chịu.",
      [611399600565504] = "Ngửi thấy mùi chiến đấu, Vị Tướng sẽ hóa Ác Linh định kỳ xuất hiện, truy theo hướng kẻ thù để tấn công, gây sát thương, Choáng và khắc Dấu Ấn Kẻ Thù. Nhưng nhớ tránh xa nó một chút — chủ nhân cũng là kẻ thù của nó.",
      [611399600565760] = "Trăng Tròn Vĩnh Hằng do Thủy Tổ Huyết Tộc đích thân rèn. Tăng cấp Kỹ Năng Chiến Đấu của bản thân và đồng đội, đồng thời cường hóa Bí Ngẫu; ngay cả khi kỹ năng đang hồi chiêu vẫn có xác suất cưỡng chế triệu hồi. Cái giá là mỗi lần cưỡng triệu đều nuốt Sinh Mệnh của bạn.",
      [611399600566016] = "Đeo nó lên, tiếng rít của Minh Giới sẽ xé bên tai, tăng mạnh Tốc Đánh và Hoàn Trả Hồi Chiêu của mọi Kỹ Năng Chiến Đấu; hạ gục còn kéo dài thời gian có thể chịu đựng. Nhưng nếu tháo mặt nạ mà vẫn đang chiến đấu, bạn sẽ rơi vào Suy Yếu.",
      [611399600566272] = "Chiếc găng tay này bóc linh hồn kẻ địch tới bên mình; sau khi nuốt có thể nhận năng lực lúc sinh thời hoặc cường hóa chuyên công của chúng. Nhưng nó mãi không biết no — mỗi linh hồn bị Chăn Thả đều làm giảm Sinh Mệnh Tối Đa của bạn.",
      [611399600566528] = "Từng là thiên thạch ngoài trời, nay tỏa khí tức mục nát. Tấn công có xác suất bắn Độc Hoàn Ăn Mòn, khiến mục tiêu liên tục lở loét; tấn công lần nữa sẽ làm độc dịch bắn tung tóe ra xung quanh. Ô nhiễm từ Tinh Không cũng quay lại trên người bạn, liên tục ăn mòn chính mình.",
      [611399600566784] = "Thu hoạch, phì nhiêu, sinh cơ dồi dào. Sau khi sở hữu một thời gian, bạn gánh lời nguyền; khi chết, tại chỗ mọc ra Đất Sống, liên tục hồi máu, tăng Tấn Công và cho đồng minh Miễn Khống Chế. Nhưng khi vùng đất còn tồn tại, bạn không thể hồi sinh.",
      [611399600567040] = "Trượng Dịch Chuyển do gia tộc Abraham để lại. Khắc Dấu Sao lên mục tiêu; khi ngoài tầm, tiêu hao dấu để dịch chuyển tới vị trí thích hợp rồi ra tay, sau khi Né còn có thể dịch chuyển thêm một lần. Càng kích hoạt nhiều, càng dễ mất khống chế và lạc đường.",
      [611399600567296] = "Nó mang đặc tính sống, nắm giữ xác suất của mọi sự việc. Khi phản phệ của Vật Phong Ấn ập tới, nó sẽ thay bạn gieo xúc xắc một lần; chỉ có một phần sáu khả năng phản phệ thực sự rơi lên bạn.",
      [611399600567552] = "Hiệu ứng bất lợi của nó có thể khiến người đeo chết dần. Nó áp chế Vật Phong Ấn của kẻ địch xung quanh, khiến hiệu ứng có lợi có xác suất mất tác dụng, đồng thời định kỳ gây Trọng Thương và Hóa Đá quái vật gần đó. Cái giá là Vật Phong Ấn của chính bạn cũng bị áp chế và Sinh Mệnh liên tục trôi đi.",
      [611399600567808] = "Khế ước đã viết thì nhất định phải thực hiện. Trong chiến đấu, khi dùng kỹ năng nghề nghiệp sẽ tự động Công Chứng; số tầng Công Chứng tích lũy liên tục tăng Tấn Công và Tăng Cường Kỹ Năng, đủ tầng chuyển thành sát thương bổ sung. Nhưng một khi Ngụy Chứng, uy lực kỹ năng đó giảm mạnh.",
      [611399600615680] = "Món quà hoa lệ như sao chiều lao vun vút, mang theo lời tán thưởng nồng nhiệt nhất của khán giả, rực sáng xuất hiện trong Hành Lang Mị Ảnh.",
      [611399600615936] = "Món quà tao nhã nở thành mưa hoa hồng, biến hương thơm và tiếng vỗ tay thành phúc lành, dâng tặng bóng hình rực rỡ nhất trên sân khấu.",
      [611399600616192] = "“Ý kiến khán giả” truyền thống của nhà hát opera, dùng cách hài hước để bày tỏ tiếng nói khác biệt — đây cũng là một phần của sân khấu.",
      [611399600616448] = "Khoảnh khắc viết tên đối phương xuống, một quãng thời gian chỉ thuộc về hai người từ đó ra đời.",
      [611399600616704] = "Một lăng kính trong suốt được cắt gọt tinh xảo, có thể khúc xạ ánh sáng, cũng có thể “khúc xạ” sức chứa ký ức, khiến động tác biểu diễn của bạn phong phú hơn.",
      [611399600616960] = "Dây chuyền làm từ vỏ sò tự nhiên, mang theo sự rộng lớn và tự do của đại dương.",
      [611399600617216] = "Ngọc trai lặng lẽ khảm trên hoa cài ngực, quang huy dịu dàng bao dung mọi tâm tư.",
      [611399600617472] = "Khuy măng-sét chế tác từ sapphire thượng hạng, ánh xanh sâu thẳm tựa sao trời đêm.",
      [611399600617728] = "Nhẫn làm từ ruby huyết bồ câu hiếm có, sắc đỏ đậm nồng nhiệt, khắc ghi lời hứa vĩnh hằng.",
      [611399600617984] = "Sinh trưởng ở Feynapotter đầy nhiệt tình, màu vàng óng tượng trưng cho niềm vui.",
      [611399600618240] = "Chiết xuất hương hoa hồng tự nhiên, nở rộ trong mọi mùa.",
      [611399600618496] = "Nước hoa độc đáo pha chế từ quà tặng của sinh linh đại dương, tỏa hương thần bí và dịu dàng.",
      [611399600618752] = "Chế tác tinh xảo bằng đồng thau, nhẹ nhàng cổ điển, người bạn tuyệt vời khi đọc sách.",
      [611399600619008] = "Kỹ thuật ép bạc tinh tế, tao nhã cao quý, vật mang hoàn hảo cho thư từ.",
      [611399600619264] = "Ngoại hình dát vàng rực rỡ, viết trơn mượt, thể hiện trí tuệ và phẩm vị.",
      [611399600619520] = "Bánh pudding caramel thơm ngậy, mềm mượt tinh tế, một tận hưởng ngọt ngào.",
      [611399600619776] = "Hồng trà thượng hạng được quý tộc yêu thích, vị đậm đà, hậu vị hơi ngọt.",
      [611399600620032] = "Bộ trà cụ làm từ sứ xương tinh khiết, chế tác tinh xảo, chạm vào ấm mịn; thưởng trà cũng truyền tải nét tao nhã.",
      [611399600620288] = "Mỗi lần đổi tên là một lần tái định hình âm thầm, đồng nghĩa Câu Lạc Bộ sẽ dùng diện mạo hoàn toàn mới để một lần nữa tuyên bố sự tồn tại.",
      [611399600620544] = "Một trang xé từ sách tiên tri cổ xưa, được viết lại bởi chiến tích của bạn.",
      [611399600620800] = "Ký khế thư này có thể thay đổi danh xưng dùng để lập thân trên đời.",
      [611399600621312] = "Vận mệnh không nói dối; bói toán là phương tiện để con người đọc hiểu nó.",
      [611399600621568] = "Mọi chuyện trên đời chẳng qua là một vở kịch; bạn và tôi đều là người trong kịch, không cần nghiêm túc đến vậy.",
      [611399600621824] = "Một mạng đổi một mạng, một tờ giấy thay một người.",
      [611399600622080] = "Bóng tối trước bình minh lạnh nhất, nhưng tia sáng đầu tiên luôn đáng để chờ đợi.",
      [611399600622336] = "Ánh sáng sẽ soi rõ chân tướng, cũng sẽ thiêu cháy dối trá.",
      [611399600622592] = "Nhân danh Mặt Trời, tịnh hóa mọi thứ ô uế.",
      [611399600622848] = "Lòng người khó dò, nhưng màu sắc không bao giờ nói dối.",
      [611399600623104] = "Lòng người là sự tĩnh lặng ồn ào nhất.",
      [611399600623360] = "Chữ viết có sức mạnh, nhất là những gì được viết vào lòng người.",
      [611399600623616] = "Phía sau cánh cửa là gì? Ngay cả chiếc chìa khóa cũng không biết.",
      [611399600623872] = "Chân thực và hư ảo chỉ cách nhau một niệm.",
      [611399600624128] = "Các vì sao đã viết sẵn đáp án, chỉ xem bạn có chịu lắng nghe hay không.",
      [611399600624384] = "Có những bí mật chỉ có thể viết ở nơi không nhìn thấy.",
      [611399600624640] = "Đấu võ không chỉ là so sức mạnh, mà còn là tranh giành tầm nhìn.",
      [611399600624896] = "Nghi thức là khế ước giữa con người và thần bí, mà khế ước cần người chứng kiến.",
      [611399600625152] = "Đại địa im lặng, nhưng sẽ đáp lại những bước chân đủ nặng.",
      [611399600625408] = "Trong khoảng nghỉ giữa trận chiến, tích lũy cho lần bùng nổ kế tiếp.",
      [611399600625664] = "Vũ khí biến hóa muôn vàn, chỉ có sát ý là không đổi.",
      [611399600625920] = "Tri thức chính là sức mạnh, còn công thức là chìa khóa mở sức mạnh.",
      [611399600626176] = "Trong lời cầu nguyện giữa trưa, cánh hoa hóa thành pha lê.",
      [611399600626432] = "Khi gió lướt qua, nó bắt chước tiếng thì thầm của gió.",
      [611399600626688] = "Sự lắng đọng của thời gian khiến vật bình thường cũng có thể gánh sức mạnh Phi Phàm.",
      [611399600626944] = "Ánh nắng của cả một mùa hè được cất giữ trong phiến lá.",
      [611399600627200] = "Quà tặng tháng Bảy khiến Linh Tính chảy như rượu.",
      [611399600627456] = "Bóng tối sâu trong rừng ẩn giấu bí mật của tự nhiên.",
      [611399600627712] = "Ánh mặt trời bị giam trong đá, vẫn cố vùng thoát.",
      [611399600627968] = "Một ngọn núi lửa còn đang đập, nóng đến xuyên thủng Lý Trí của người sở hữu.",
      [611399600628224] = "Giao điểm giữa ánh sáng và lên men, nơi thần thánh được thai nghén trong bình phàm.",
      [611399600628480] = "Vị ngọt chết người là cánh cửa hẹp dẫn tới Phi Phàm.",
      [611399600628736] = "Hơi ấm của tín ngưỡng vẫn còn lưu trên bề mặt vật dụng.",
      [611399600628992] = "Được hái sau tiếng gáy đầu tiên, mang theo khả năng Mặt Trời mọc.",
      [611399600629248] = "Nó sinh trưởng trong khe hở giữa hiện thực và Linh Giới.",
      [611399600629504] = "Trong bóng tối, giọt máu này vẫn cháy.",
      [611399600629760] = "Hương thơm tựa ánh sáng, có thể chiếu vào những nếp gấp của linh hồn.",
      [611399600630016] = "Bột vàng là sự tỉnh táo đã đông cứng.",
      [611399600630272] = "Cái ôm của lửa và đất trở thành vĩnh hằng trong lúc nguội đi.",
      [611399600630528] = "Rễ cây ghi nhớ lịch sử xa xưa hơn loài người.",
      [611399600630784] = "Chiếc lông này từng lướt qua ranh giới Linh Giới.",
      [611399600631040] = "Ánh sáng chảy trong chất lỏng, nối liền hai thế giới.",
      [611399600631296] = "Ánh sáng và bóng tối hòa giải ở mép cánh hoa.",
      [611399600631552] = "Lời thì thầm bên mép nước được phong kín trong sắc xanh.",
      [611399600631808] = "Nó từng nhìn thấy bí mật tăm tối nhất của biển sâu.",
      [611399600632064] = "Sự hòa trộn của hai sinh mệnh vật lộn trong dòng máu.",
      [611399600632320] = "Tinh khiết đến gần như hư vô mới có thể dung chứa tất cả.",
      [611399600632576] = "Chất độc đẹp đẽ khiến sinh mệnh đình trệ.",
      [611399600632832] = "Loại bột đắng có thể làm tê liệt cảm giác đau.",
      [611399600633088] = "Hơi thở của rừng ngưng tụ trong một đóa hoa.",
      [611399600633344] = "Bảy màu sắc xoay tròn trong tủy não, không bao giờ ngừng.",
      [611399600633600] = "Tốc độ bị đông cứng trong chất lỏng trong suốt.",
      [611399600633856] = "Khởi điểm của sinh mệnh ẩn trong lớp vỏ cứng.",
      [611399600634112] = "Ký ức của Nanh Rồng lắng lại trong lá cỏ.",
      [611399600634368] = "Màu trắng chưa vương bụi trần là bản tâm ban sơ của tự nhiên.",
      [611399600634624] = "Khi nó nhìn bạn, bạn nhìn thấy ai?",
      [611399600634880] = "Mỗi ngụm đều là trăm năm thời gian.",
      [611399600635136] = "Dòng máu trong ống nghiệm làm ánh sáng méo đi.",
      [611399600635392] = "Vân trên vỏ cây là dấu vân tay của năm tháng.",
      [611399600635648] = "Tiếng tim đập được phong kín trong hương thơm.",
      [611399600635904] = "Sự mềm mại cắt xuống lúc mới sinh là chiếc neo đầu tiên của vận mệnh.",
      [611399600636160] = "Cái lạnh sâu trong tủy xương ẩn chứa sự kiên nhẫn chí mạng.",
      [611399600636416] = "Khoảnh khắc cắn vỡ vỏ quả, tiếng chuông gió hư ảo vang vọng trong đầu.",
      [611399600636672] = "Trong dòng máu lạnh lẽo lắng đọng bản năng săn mồi nguyên thủy.",
      [611399600636928] = "Vỏ cây hóa thành bụi, trong không khí dần lan tiếng chuông hư ảo.",
      [611399600637184] = "Trong phần thịt quả sẫm màu, kịch độc và bóng tối cùng lắng đọng.",
      [611399600637440] = "Ba tháng nhìn chăm chú, trong gương đã lắng lại một bản thân hoàn chỉnh khác.",
      [611399600637696] = "Sức nặng của biển sâu lắng trong dòng máu.",
      [611399600637952] = "Trong cơ thể ẩn giấu một bầu Tinh Không đông cứng.",
      [611399600638208] = "Hương thơm chỉ nở trong bóng tối.",
      [611399600638464] = "Hương vị tỉnh táo có thể xua tan sương mù.",
      [611399600638720] = "Đẹp mà chí mạng; chỉ một giọt cũng đủ khiến linh hồn run rẩy.",
      [611399600638976] = "Bột đỏ bay trong gió, nóng rực như Long Tức.",
      [611399600639232] = "Quà tặng từ dãy Hornacis, nặng nề như vận mệnh.",
      [611399600639488] = "Gương mặt ngủ giữa những cánh hoa là hình phản chiếu của một linh hồn nào đó.",
      [611399600639744] = "Dịch gây ảo giác khiến người ta không phân biệt được hiện thực và giấc mơ.",
      [611399600640000] = "Ánh sáng bị ô nhiễm, bóng tối lan ra từ rìa.",
      [611399600640256] = "Sự Bảo Hộ màu vàng ẩn trong lớp bột mịn.",
      [611399600640512] = "Bén rễ từ màn sương, hút lấy hư ảo và chân thực.",
      [611399600640768] = "Những hoa văn thần bí phát sáng trong chất lỏng, tựa hình xăm sống.",
      [611399600641024] = "Chất lỏng trắng sữa, gặp không khí liền hóa thành sương mỏng.",
      [611399600641280] = "Lưỡng lự giữa thể rắn và lỏng, mãi không xác định.",
      [611399600641536] = "Hương thơm đậm đặc đến nghẹt thở, hiện thực bắt đầu méo mó.",
      [611399600641792] = "Khi chạm vào, da sẽ vô thức ngọ nguậy.",
      [611399600642048] = "Kết tinh của quỷ bí và biến hóa, vẫn đang cố biến đổi hình dạng.",
      [611399600642304] = "Dòng máu trong ống nghiệm liên tục đổi màu.",
      [611399600642560] = "Bóng tối sâu hơn cả Mạn Đà La thông thường.",
      [611399600642816] = "Mái tóc ướt sũng tỏa ra áp lực của biển sâu.",
      [611399600643072] = "Lòng tham được tiêu hóa trong bụng rồi hóa thành kết tinh.",
      [611399600643328] = "Nhìn quá lâu sẽ quên mất mình là ai.",
      [611399600643584] = "Tinh khiết và mềm như râu dê, có thể ổn định ranh giới.",
      [611399600643840] = "Mặt nước thỉnh thoảng phản chiếu những cảnh tượng vốn không nên tồn tại.",
      [611399600644096] = "Sự cộng sinh đẹp đến mức khiến người ta bất an.",
      [611399600644352] = "Có thể thay đổi cách thực vật xung quanh sinh trưởng.",
      [611399600644608] = "Mặt trong khắc những phù văn không thể lý giải.",
      [611399600644864] = "Tốc độ bị đông cứng trong chất lỏng mằn mặn.",
      [611399600645120] = "Hương gỗ ẩn chứa sự bền bỉ và che chở.",
      [611399600645376] = "Cuộn thành một quả cầu, nối với những sợi dây vô hình.",
      [611399600645632] = "Ngắn ngủi đến cực hạn chính là vĩnh hằng.",
      [611399600645888] = "Vị khách ngoài trời, di hài sau khi rơi xuống.",
      [611399600646144] = "Dưới trọng áp vẫn giữ nguyên vẹn.",
      [611399600646400] = "Sức dẻo dai của loài leo bám lắng trong lớp bột.",
      [611399600646656] = "Dây leo đã mất sinh lực vẫn cố quấn lấy.",
      [611399600646912] = "Nghe nói có thể đồng thời nhìn thấy từ nhiều góc độ.",
      [611399600647168] = "Ngọn lửa nồng độ cao có thể đánh thức Linh Tính đang ngủ.",
      [611399600647424] = "Trí tuệ và mất khống chế chỉ cách nhau một đường.",
      [611399600647680] = "Chấp niệm của người chết còn ngoan cố hơn người sống.",
      [611399600647936] = "Hai mươi hai năm đủ để vận mệnh lưu lại dấu vết.",
      [611399600648192] = "Màu bạc lưu động là dòng máu của luyện kim thuật.",
      [611399600648448] = "Đóa hoa sinh ra trong quấn quýt, cường hóa mối ràng buộc vô hình.",
      [611399600648704] = "Ba hình thái đại diện cho lưu động, tĩnh tại và ngưng kết.",
      [611399600648960] = "Trong đồng tử phản chiếu một thế giới méo mó.",
      [611399600649216] = "Dục vọng giết chóc nguyên thủy đông cứng trong lớp sừng.",
      [611399600649472] = "Dòng máu đen có nhiệt độ cao bất thường.",
      [611399600649728] = "Vẫn khẽ đập, tỏa ra ý chí bất khuất.",
      [611399600649984] = "Khí tức tìm kiếm cân bằng giữa cuồng bạo.",
      [611399600650240] = "Sự bảo hộ màu đen phong ấn thứ không nên được giải phóng.",
      [611399600650496] = "Mỗi nhịp đập đều như tiếng trống trận vang dội.",
      [611399600650752] = "Vẫn giữ ký ức bản năng săn giết.",
      [611399600651008] = "Dã tính và lý trí giao chiến trong dòng máu.",
      [611399600651264] = "Đắng đến mức khiến người ta tỉnh táo.",
      [611399600651520] = "Ánh tím có thể xoa dịu cảm xúc xao động.",
      [611399600651776] = "Mang sức nặng của chiến thắng và nhân quả.",
      [611399600652032] = "Cứng đến mức có thể đập vỡ đá.",
      [611399600652288] = "Có thể nghe thấy nguy hiểm đến từ nhiều hướng.",
      [611399600652544] = "Dòng máu bạc, vừa lạnh vừa ấm.",
      [611399600652800] = "Khi chạm vào có thể cảm nhận nhịp đập của dã tính.",
      [611399600653056] = "Vẫn sắc bén, sát ý chưa tan.",
      [611399600653312] = "Minh chứng của kẻ chiến thắng, quấn quanh nhân quả.",
      [611399600653568] = "Cứng rắn mà ấm áp, là vật chứa của dũng khí.",
      [611399600653824] = "Ánh trăng và cuồng bạo cùng tồn tại trong lòng bàn tay.",
      [611399600654080] = "Vị đắng được ánh trăng tịnh hóa có thể chữa lành vết thương.",
      [611399600654336] = "Có thể xé toạc bóng tối, tượng trưng cho quyết đoán của bình minh.",
      [611399600654592] = "Màu sắc biến đổi, gây rối cảm nhận.",
      [611399600654848] = "Loại bỏ ô uế để trở thành vật chứa an toàn.",
      [611399600655104] = "Mang nó đi ngủ, bạn sẽ nhìn thấy ác mộng của người khác.",
      [611399600655360] = "Chất lỏng màu đen chảy trong tinh thể, tựa oán hận đã đông cứng.",
      [611399600655616] = "Mang đặc tính ô nhiễm từ giấc mơ.",
      [611399600655872] = "Có thể khuếch đại tần số của nguồn nguyền rủa.",
      [611399600656128] = "Ghi lại những ký ức người khác không muốn bị biết.",
      [611399600656384] = "An thần và phấn chấn cân bằng trong một làn hương.",
      [611399600656640] = "Man lực nguyên thủy đông cứng trong xương.",
      [611399600656896] = "Trong nhịp đập ngưng tụ sự bền bỉ và cảm nhận đa góc.",
      [611399600657152] = "Nhịp đập có tần số cực cao, tràn đầy sức mạnh nguyên thủy.",
      [611399600657408] = "Những đường vân nghìn năm bị nghiền thành bột, bức tường thời gian tan ra nơi đầu ngón tay.",
      [611399600657664] = "Một đoạn sắc bén bong ra từ bóng tối, vẫn có thể rạch vỡ hiện thực.",
      [611399600657920] = "Chạm vào có thể nhanh chóng làm đình trệ dòng chảy tinh thần.",
      [611399600658176] = "Chứa Linh Tính có khả năng truy dấu và khóa mục tiêu.",
      [611399600658432] = "Có thể bắt giữ hình ảnh của ký ức và tương lai gần.",
      [611399600658688] = "Nhịp đập dã tính phản ứng cực nhanh.",
      [611399600658944] = "Tỏa ra dao động Linh Tính yếu ớt.",
      [611399600659200] = "Có thể bắt lấy những mảnh suy nghĩ chưa tan.",
      [611399600659456] = "Cộng hưởng với tần số Linh Cảm cổ xưa.",
      [611399600659712] = "Lời thì thầm của rừng được lưu trong vòng tuổi cây.",
      [611399600659968] = "Có thể nhìn thấu ngụy trang hoặc tạo ảo tượng.",
      [611399600660224] = "Sinh lực dồi dào và độ thân hòa cao với tự nhiên.",
      [611399600660480] = "Thông tin vỡ vụn và khái niệm đã tiêu vong.",
      [611399600660736] = "Thứ bị cuộn lại không chỉ là giấy, mà còn là thời không bị gấp và điều cấm kỵ.",
      [611399600660992] = "Hơi thở cỏ cây hóa thành sự tĩnh lặng dạng lỏng, chữ viết ngủ yên bên trong.",
      [611399600661248] = "Mối ràng buộc sâu sắc nhất bắt đầu từ một niềm tin nhỏ bé nhất. Và mọi niềm tin đều đáng được trân trọng lưu giữ.",
      [611399600662016] = "Đây là đạo cụ tạm thời.",
      [611399600662784] = "Món quà nhỏ Marmoth yêu thích nhất, có thể hồi phục hiệu quả tinh lực của chúng.",
      [611399600663040] = "Đồng tiền chung của Liên Hiệp Thương Nghiệp, có thể dùng để giao dịch hàng hóa.",
      [611399600663296] = "Các động tác trong Bóng Ma Nhà Hát; sau khi mua có thể dùng để biểu diễn trong Bóng Ma Nhà Hát.",
      [611399600665856] = "Hỡi lữ khách đã đi khắp miền vô danh, hãy nhận lấy vinh quang từ phương xa!",
      [611399600666112] = "Hỡi người bạn đồng hành sát cánh, hãy ghi nhớ lời thề cùng bước bên nhau!",
      [611399600673280] = "Một quả cầu pha lê trong suốt cỡ nắm tay, bên trong như phong kín ánh sáng và bóng hình đang chuyển động. Khẽ chạm vào, những bước múa tao nhã sẽ tái hiện trong tâm trí, như thể linh hồn từng tự mình trải qua buổi diễn ấy. Bản chất của nghệ thuật chính là biến khoảnh khắc thành vĩnh hằng.",
      [611399600697600] = "Tiếng vọng yếu ớt của Hình Chiếu Lịch Sử, ghi lại mảnh sức mạnh Vật Phong Ấn từng sở hữu. Dùng nó đánh thức hình chiếu đang ngủ, để nguy hiểm dần lộ nguyên hình.",
      [611399600697856] = "Mảnh chân thực đông cứng trong dòng sông lịch sử, chứa một phần bản chất của Vật Phong Ấn. Dùng nó sẽ khiến hình chiếu tiến gần vô hạn tới chân thực; cái giá là nguy hiểm cũng theo đó giáng xuống.",
      [611399600700672] = "Khi hai linh hồn sóng vai trên quỹ đạo vận mệnh, nơi sâu trong Sương Xám sẽ ngưng tụ ánh sáng yếu ớt này. Nó không ghi nội dung lời thề, chỉ khắc con đường đã cùng đi qua.",
      [611399600713728] = "Nhìn chăm chú vào mục tiêu rồi siết chặt tinh thể, khuôn mặt và thân hình đối phương sẽ hiện lên bên trong. Khi tinh thể tan chảy và thấm vào lòng bàn tay, bạn sẽ trở thành người đó. Nhưng khuôn mặt vay mượn cuối cùng vẫn tan đi; lớp ảo tượng này không thể theo bạn quá lâu.",
      [611399600714752] = "Một trong những lễ khí biểu tượng của Giáo Hội Mặt Trời Vĩnh Hằng, dùng kỹ thuật đặc biệt phong kín một lượng nhỏ Linh Tính thần thánh của Con Đường Mặt Trời trong huy chương mạ vàng. Dù ở trong bóng tối, tia quang huy truyền từ huy chương vẫn chân thực: người quanh kẻ đeo cảm nhận sự ấm áp và trật tự không lời, giúp dao động tinh thần dần ổn định, đưa thần trí từ hỗn loạn trở lại bình tĩnh.",
      [611399600722944] = "“Giao dịch chưa bao giờ miễn phí, nhưng khế ước bảo đảm nó sẽ không thất hứa.”",
      [611399600723200] = "Một chai chất lỏng thần bí đựng trong bình thủy tinh. Nghe nói người uống nó có thể tạm thời quên những năng lực mình đã học, từ đó đưa ra lựa chọn lại ở ngã rẽ của vận mệnh.",
      [611399600726016] = "Trang giấy trắng rơi xuống từ phía trên Sương Xám, được sức mạnh vận mệnh rót Linh Tính. Khi hai lời thề cộng hưởng, những dòng chữ ẩn sẽ hiện ra.",
      [611399600727808] = "Thiết bị bảng đèn kiểu mới của nhà hát opera, có thể tạo liên kết giữa người Phi Phàm và người biểu diễn.",
      [611399600728064] = "Một viên xúc xắc đa diện bất quy tắc tỏa ánh vàng, chạm vào ấm áp, như có ý thức đang chậm rãi lật mình bên trong. Khi nắm nó và gieo ra, tựa như vận mệnh trong khoảnh khắc ấy chủ động nghiêng người, ưu ái mặt sắp rơi xuống.",
      [611399600728320] = "Một viên xúc xắc đa diện bất quy tắc tỏa khí tức u ám, ánh tím sẫm chảy dọc các cạnh. Khi gieo ra, nó sẽ khựng giữa không trung nửa nhịp, như đang đưa ra quyết định, rồi rơi xuống mặt mà nó tự chọn.",
      [611399600729344] = "Dùng để phân phát phần thưởng suất Thần Tuyển của server chiến lược.",
      [611399600729600] = "Một phát minh của Đại Đế Roselle. Nghe nói cảm hứng đến từ công thức tỉnh táo ở quê hương. Lấy tinh dầu bạc hà làm nền, trộn bảy loại thảo mộc chống khí tức mục nát — tương truyền cái tên ứng với “Bảy Chính Thần”. Đựng trong lọ kim loại, tiện dùng mọi lúc; chỉ cần mở nắp đưa gần mũi, mùi hương mát lạnh sẽ lập tức xua tan sự choáng váng do mục nát gây ra.\n\nDù ở đâu, lúc nào, nó cũng hiệu quả như vậy. Giá không đắt, nhưng luôn cứu người vào lúc chật vật nhất.",
      [611399600729856] = "Phế liệu còn lại sau khi người Phi Phàm luyện chế Ma Dược, thường bị đổ bỏ ngay. Không rõ ai bắt đầu thu gom đóng chai rồi bán với giá cực thấp ở chợ đen. Mùi tanh hôi khó tả, chẳng kém cá sói đóng hộp — bạn có kẻ thù không? Có thể giới thiệu họ nếm thử.",
      [611399600730112] = "Một lọ nhỏ kín làm từ thủy tinh đen, mặt trong khắc phù văn phong ấn Cổ Feysac, nghe nói dùng để áp chế khí tức thực sự đến từ Vực Sâu bên trong. Khi đập vỡ lọ, tiếng vọng cô đọng lập tức khuếch tán và bao phủ khu vực xung quanh, khiến thần trí người tiếp xúc dao động dữ dội. Chỉ dùng được một lần, không thể phục hồi lọ.",
      [611399600733696] = "Rượu thơm dịu lặng lẽ chảy.",
      [611399600738304] = "Điểm cốt truyện đạt 800.",
      [611399600738560] = "Hóa đơn không biến mất, chỉ được chuyển cho một người thích hợp trả tiền hơn.",
      [611399600740352] = "<Highlight>Chế tác:</> Nỉ Tinh Trần · Họa Tiết Dấu Lữ Hành · Bộ Áo Choàng Ngắn\nTinh Không mênh mông, mọi cánh cửa đều có thể tới. Khoác bộ y phục này, nguyện ánh sao trên hành trình dẫn lối để các bạn không bao giờ lạc.",
      [611399600740608] = "<Highlight>Chế tác:</> Vải Dệt Mịn Xám Sương · Jacquard Hoa Văn Ẩn · Y Phục Bói Toán\nNgay cả khi biến động lớn của vận mệnh sắp đến, đừng quên nhếch khóe môi mà chế nhạo nó.",
      [611399600740864] = "<Highlight>Chế tác:</> Lanh Dệt Mịn · Dập Vân Trang Sách · Trường Bào Mở Vạt\nMang lòng kính sợ, dòm ngó thần bí, cho tới khi thân này hiểu rõ chân lý của vạn vật mới thôi.",
      [611399600741120] = "<Highlight>Chế tác:</> Da Dập Vân · Giáp Nhẹ Đinh Bạc · Chiến Giáp Gọn Nhẹ\nHoàng hôn không trôi dừng lại trên giáp vai; dù thân này tắm trong ánh tà dương, vẫn mang chí đánh thức bình minh.",
      [611399600741376] = "<Highlight>Chế tác:</> Vải Thánh Giả · Viền Nhật Quang · Thánh Giáp Rủ\nLinh hồn chí thành chí thuần sẽ thần thánh như ánh mặt trời; khi hết lòng ca tụng, Mặt Trời cũng gật đầu tán thành bạn.",
      [611399600741632] = "<Highlight>Chế tác:</> Nỉ Lông Lạc Đà · Cắt Ôm Dáng · Lễ Phục Nhà Hát\nKhán Giả luôn ở sau màn, lặng nhìn mọi tiếng reo hò của vở kịch, thấu rõ hướng đi của từng vai diễn.",
      [611399600741888] = "Chế tác từ giấy da dê cổ màu vàng nhạt. Mỗi khi một cái tên mới được khắc vào, trên vòm trời sẽ hiện một luồng sáng, ngưng tụ thành pho tượng tượng trưng cho vinh quang.",
      [611399600744448] = "Linh Tính được cất giữ cẩn thận trong khối đá, chờ khoảnh khắc ngân vang.",
      [611399600744704] = "Con người nghiên cứu lịch sử, dùng điểm neo để học chân lý. Nhưng chân lý duy nhất con người học được từ lịch sử là: lịch sử luôn lặp lại.",
      [611399600744960] = "Đây là dấu vết của Phi Phàm, cũng là dấu vết Thần Tính. Vạn vật đều có Thần Tính, vạn vật đều sinh ra từ Đấng Ban Sơ, và dấu ấn của Ngài cũng tồn tại giữa muôn vật.",
      [611399600745216] = "Thời gian lặng lẽ nhưng để lại dấu vết; ngay cả cái chết cũng không thể xóa chúng. Chỉ khi bị thế giới lãng quên mới là giấc ngủ vĩnh hằng thực sự.",
      [611399600745472] = "Khi thời gian chảy qua một số nơi, nó để lại trầm tích. Tĩnh tâm lắng nghe, có lẽ bạn sẽ nghe được một tiếng thở dài từ phía trên Sương Xám trong những hạt cát ấy.",
      [611399600745728] = "Những ký ức đủ sâu đôi khi được lưu lại theo cách không ngờ tới. Vào một thời khắc nhất định, chúng có thể cứu bạn, hoặc đẩy bạn xuống vực sâu.",
      [611536234211328] = "Hãy đón chờ!",
      [611536502534144] = "Chế độ phúc lợi do tín đồ Giáo Hội Kẻ Khờ thiết lập. Cảm ơn mọi giới đã ủng hộ Giáo Hội Kẻ Khờ.\nHãy lắng nghe 《Thánh Điển Kẻ Khờ》, ca ngợi Kẻ Khờ! Nguyện ân điển của Ngài ngày đêm ở bên, trở thành ngọn đèn không bao giờ tắt trên con đường bạn tiến bước!",
      [743274692231680] = "Chuông Tang",
      [949979120143616] = "Lọ Độc Tố Sinh Vật",
      [949979120144128] = "Chứng Nhận Vinh Quang",
      [949979120144640] = "Cỏ May Mắn",
      [949979120145664] = "Tóc Tĩnh Lặng",
      [949979120146944] = "Đèn Thần Ước Nguyện",
      [949979120147968] = "Rìu Cuồng Phong",
      [949979120148224] = "Người Giấy Mặt Trăng",
      [949979120148480] = "Lục Hoa",
      [950253998049280] = "Du Ký Groselle Không Tưởng",
      [950255340227584] = "Một Vật Phong Ấn kỳ diệu không có cấp đánh giá, vừa có thể hỗ trợ chiến đấu vừa có thể trả lời câu hỏi. Khi bạn hỏi nó một câu, xúc tu sẽ khẽ rung rồi đưa ra đáp án. Dù chỉ là một con mực, nó quả thật biết rất nhiều.\nKhông cấp, không số hiệu, không ai biết rốt cuộc nó làm được bằng cách nào.",
      [1046804594429696] = "Thâm Hồng Nguyệt Miện",
      [1200668845035008] = "Sinh ra vốn là một viên minh châu; dù rơi vào bụi trần cũng chưa từng mất đi nửa phần ánh sáng — lời dối trá hào phóng nhất trên đời là khiến nó ngỡ rằng mình có thể bị chôn vùi.",
      [1200668845035520] = "Cung Điện Stiem gầm vang. Sau khi một thành phố hơi nước thoát khỏi bản vẽ và có được sinh mệnh, lõi máy không ngừng nghỉ ấy đến nay vẫn đập vì giấc mơ đặt chân lên Mặt Trăng từ trăm năm trước.",
      [1200668845035776] = "Khi Đại Đế Roselle đặt chân lên Mặt Trăng, ông không hề đi bằng thành phố hơi nước này — nhưng Cung Điện Stiem sinh ra vì mục tiêu ấy rồi cũng vì thế mà lặng im. Có những ý tưởng vĩ đại, dù không được lựa chọn, vẫn đáng được ghi nhớ.",
      [1200668845036032] = "Dòng lũ tri thức cuốn qua từng bánh răng của Stiem, hòa thành giai điệu độc đáo giữa tiếng gầm vang — đó là khát vọng chạm tới Mặt Trăng, là khúc nhạc của chiến thắng.",
      [1200668845048832] = "Huân chương bạc do Tòa Thị Chính trao tặng. Nó chứng kiến từng nơi bạn đã đi qua — sự náo nhiệt của Phố Chữ Thập Sắt, tiếng còi nơi bến cảng ẩm ướt, những câu chuyện phía sau các ngôi nhà. Tingen, giờ đây, ở ngay dưới chân bạn.",
      [1200668845049088] = "Các bạn hội ngộ nơi thần quốc, nhất định giấc mơ đẹp sẽ thành hiện thực.",
      [1200668845049344] = "Ăn dưa, mua dưa đây! Dưa tươi, làm một miếng không? Dưa này chín thật chứ? Tất nhiên, không tin thì nếm thử đi... Ừm, vận may tốt thật, còn là một quả dưa lật kèo nữa!",
      [1200668845049600] = "Rượu độc ngọt ngào nhất, mật đường ăn mòn tận xương. Bạn chỉ nhấp một ngụm rồi thôi, hay sẽ chẳng thể dứt ra?",
      [1200668845049856] = "Tôi biết mình đang đồng hành cùng cái chết, và tôi biết mình cũng đang đồng hành cùng sự sống.",
      [1200668845050112] = "Tôi sẽ mãi mãi chờ đợi, chờ tuổi xuân qua đi, thân xác mục rữa, chờ mùa xuân được đoàn tụ cùng bạn.",
      [1200668845050368] = "Đội trưởng, anh xem, chúng ta lại một lần nữa cứu Tingen rồi.",
      [1200668845050624] = "Chúc mừng, kẻ may mắn. Được Ngài chiếu cố vừa là vinh hạnh, vừa là khởi đầu. Mong chuyến đi của bạn thuận lợi dưới ánh nhìn và sự bảo hộ của Kẻ Khờ.",
      [1200668845051648] = "Khi lá bài Trăng Đỏ hóa thành lá bài Kẻ Khờ, chúc mừng bạn cuối cùng đã thoát khỏi cơn ác mộng. Chào mừng đến với — Phi Phàm Giới.",
      [1200668845051904] = "Rượu thường trên đời đã nếm đủ, còn lần này trong chén là chính Phi Phàm. Đã nâng chén rồi thì hãy thưởng thức cho thật trọn vẹn.",
      [1200668845052160] = "Bói quá khứ, bói hiện tại, bói tương lai; chúng ta bói vận mệnh, chúng ta kính sợ vận mệnh.",
      [1200668845052416] = "Giữa làn sóng hơi nước và máy móc, ai có thể chạm tới Phi Phàm? Trong sương mù của lịch sử và bóng tối, lại là ai đang thì thầm?",
      [1200668845052672] = "Hỡi vị thần nhân từ cai quản giấc ngủ và tĩnh lặng, Ngài ban vinh dự này cho bạn — từ nay tên bạn nằm ngoài mọi ồn ào.",
      [1200668845052928] = "Là sao mai của bình minh, cũng là tia sáng đầu tiên nơi tận cùng đêm tối. Thiên sứ truyền rải thần ân của Ngài, giáng lâm nơi đây.",
      [1200668845053184] = "Nơi sâu nhất của đêm dài u tối, Ngài lấy màn đêm làm hoa bào vinh quang, ban cho bạn sự tỉnh táo và an bình tránh xa điên cuồng, để bạn đứng độc lập phía sau trường dạ sâu thẳm.",
      [1200668845053440] = "Thần minh rủ ân, Ngài đội vương miện Vĩnh Dạ lên đầu bạn. Từ đây đêm dài vô tận, chỉ vì bạn đứng ở tận cùng của nó.",
      [1200668845054976] = "Chiến thắng cúi đầu, cự long phủ phục; thế giới sẽ là chiến quả của hành trình chinh phục.",
      [1200668845060352] = "Khỉ đầu chó lông xoăn không biết nói, nhưng dường như chúng đã công nhận bạn.",
      [1200668845060608] = "Người này từng sượt qua cái chết, nhưng kỳ tích thay vẫn sống sót nơi đây.",
      [1214205776627200] = "Nguyên Liệu Luyện Kim Cơ Bản",
      [1214205776627456] = "Nhiên Liệu Cơ Bản",
      [1214205776627712] = "Gỗ Cơ Bản",
      [1214205776627968] = "Cá Đặc Sản Hồ Kim Thu",
      [1214205776628224] = "Nguyên Liệu Dệt",
      [1214205776628480] = "Đặc Sản Thị Trấn Hoa Súng",
      [1214205776628736] = "Vật Liệu Huyền Học Cơ Bản",
      [1214205776628992] = "Sản Phẩm Luyện Kim",
      [1214205776629248] = "Đặc Sản Chợ Cổ Bảo",
      [1214205776629504] = "Hàng Thủ Công Đặc Sản Hồ Kim Thu",
      [1214205776629760] = "Sản Phẩm Chế Biến Hồ Kim Thu",
      [1214205776630016] = "Hàng Dệt Đặc Sản Tingen",
      [1214205776630272] = "Da Lông Cao Cấp Đặc Sản Tuyết Sơn",
      [1214205776630528] = "Sản Phẩm Huyền Học Chế Biến",
      [1214205776630784] = "Đặc Sản Khu Công Xưởng Tingen",
      [1214205776631040] = "Gia Vị Cơ Bản",
      [1214205776631296] = "Kim Loại Hiếm Đặc Sản Tuyết Sơn",
      [1214205776631552] = "Rượu Cao Cấp Đặc Sản Ga Đông Tingen",
      [1214205776631808] = "Chế Phẩm Huyền Học Cao Cấp",
      [1214205776632064] = "Đặc Sản Phía Nam Tuyết Sơn",
      [1214205776632320] = "Thiết Bị Chính Xác Đặc Sản Ga Đông Tingen",
      [1214205776632576] = "Sản Phẩm Văn Hóa Đặc Sản Ga Đông Tingen",
      [1214205776632832] = "Đặc Sản Nhà Thờ Thánh Selena",
      [1214205776633088] = "Đặc Sản Đông Bắc Backlund",
      [1214205776633344] = "Đặc Sản Đỉnh Cấp Nhà Thờ Thánh Selena",
      [1218466384184832] = "Niềm vui đổi được bằng vài đồng xu, món khoái khẩu của công nhân sau một ngày lao động.",
      [1218466384185088] = "Bia vàng óng có vị mật ong, tỏa hương mạch nha.",
      [1218466384185344] = "Rượu thanh ngọt đem lại chút men say; từng bọt khí như nhảy múa nơi đầu lưỡi.",
      [1218466384185600] = "Vị đắng nhẹ của ca cao hòa cùng độ mịn béo của kem, giống một món tráng miệng hơn là rượu.",
      [1218466384185856] = "Bạn gần như có thể cảm thấy tuyết tùng nảy mầm ngay trong miệng; dư vị gỗ hơi đắng lưu lại trên môi lưỡi.",
      [1218466384186112] = "Trong veo như sương sớm giữa rừng bạch dương; rượu lạnh buốt lại thiêu đốt bằng kích thích nóng rực như lửa.",
      [1218466384186368] = "Rượu vang đỏ ủ hầm cổ điển, màu sắc sâu đậm, vị vào miệng mượt mà đầy đặn, càng để lâu càng đáng thưởng thức.",
      [1218466384186624] = "Rượu màu vàng nhạt với bọt mịn dày, hương thơm quyến rũ. Chỉ ly pha lê của những yến tiệc thượng lưu mới xứng với nó.",
      [1218466384190976] = "Đường tinh luyện được ép thành viên vuông, trở thành bạn đồng hành kinh điển của trà đen Loen.",
      [1218466384191232] = "Ngô cứng từ Nam Đại Lục được ép và nướng thành những lát vàng giòn, thơm ngon xốp giòn.",
      [1218466384191488] = "Sữa bò tươi sau khi lên men tạo nên kết cấu độc đáo và hương thơm hấp dẫn, rất được mèo lẫn chuột yêu thích.",
      [1218466384191744] = "Việt quất và dâu tây cùng khiêu vũ một điệu waltz, xoay thành vị chua ngọt. Nào, thử phết lên bánh mì đi!",
      [1218466384192000] = "Nhiều năm trước, một thủy thủ tên Jules đã nghĩ ra công thức ngâm hàu trong nước muối; đến nay vẫn được lưu truyền rộng rãi.",
      [1218466384192256] = "Mật ong đậm vị kết hợp cùng thịt heo hun khói, người bạn tuyệt vời của bữa sáng. Bacon với trứng, cộng sự của tôi.",
      [1218466384192512] = "Giăm bông huy chương vàng do nhà cung ứng đặc biệt của Hoàng gia sản xuất; hương hun khói lắng đọng thành vị ngon của thời gian.",
      [1218466384192768] = "Đá lạnh khóa lại vị ngọt tươi của thịt sò; từng lát mỏng trong veo như băng tuyết. Cảm ơn món quà từ nơi sâu thẳm của biển cả.",
      [1218466384197120] = "Bột đá thô được ép thành hình rồi chạm khắc tỉ mỉ, tạo nên đường nét đẹp mắt và có nhiều công dụng.",
      [1218466384197376] = "Ghép từ những tấm gỗ phong trắng rồi mài nhẵn, kiểu dáng mộc mạc, thích hợp để sắp xếp đồ dùng trên bàn viết hằng ngày.",
      [1218466384197632] = "Đúc bằng đồng thau, trang trí hoa văn giản dị mà thanh nhã. Phù hợp cho chiếu sáng và trưng bày hằng ngày.",
      [1218466384197888] = "Đĩa sứ trắng viền hoa nhỏ tinh tế, chạm vào ấm mịn. Một lựa chọn lịch sự để các gia đình bình thường tiếp khách.",
      [1218466384198144] = "Trang sức bạc nguyên chất chất lượng cao, phong cách cổ điển, thể hiện gu thẩm mỹ kín đáo mà tinh tế của người đeo.",
      [1218466384198400] = "Gương trang điểm treo tường được chạm khắc tinh xảo. Mặt gương rõ nét, đủ để soi từng chi tiết của lớp trang điểm.",
      [1218466384198656] = "Bản luyện tập sơn dầu do danh họa thực hiện; mỗi nét cọ đều như kể một câu chuyện.",
      [1218466384198912] = "Bộ trà cụ ánh bạc khắc huy chương hoa lệ, khiến giờ trà chiều càng thêm tao nhã.",
      [1240250726755328] = "Nhà Hát Utopia",
    },
    ["itemoutlook"] = {
      [26389889680896] = "Mẫu xe đạp kinh điển nhất, được sơn lại với phối màu xanh lam–trắng độc đáo rồi tái phát hành. Khi ánh đèn đường khí gas xuyên qua màn mưa chiếu lên thân xe, ai cũng có thể cảm nhận vẻ đẹp của kim loại từ nơi này.",
      [26389889681152] = "Mẫu xe mới do công ty xe đạp lớn nhất Loen ra mắt, phối màu độc đáo; bất kỳ người sành điệu nào theo đuổi trào lưu cũng sẽ phải ngoái nhìn. Đây là phối màu McGin.",
      [26389889681408] = "Mẫu xe mới do công ty xe đạp lớn nhất Loen ra mắt, phối màu độc đáo; bất kỳ người sành điệu nào theo đuổi trào lưu cũng sẽ phải ngoái nhìn. Đây là phối màu Đài Nguyên.",
      [26389889681664] = "Mẫu xe mới do công ty xe đạp lớn nhất Loen ra mắt, phối màu độc đáo; bất kỳ người sành điệu nào theo đuổi trào lưu cũng sẽ phải ngoái nhìn. Đây là phối màu Đồng Xanh.",
      [26389889681920] = "Mẫu xe mới do công ty xe đạp lớn nhất Loen ra mắt, phối màu độc đáo; bất kỳ người sành điệu nào theo đuổi trào lưu cũng sẽ phải ngoái nhìn. Đây là phối màu Óc Chó.",
      [26389889682432] = "Một chiến mã bình thường, khoác lượng giáp chiến giản dị vừa phải; là người bạn trung thành của mọi lữ hành.",
      [26389889682688] = "Một con ngựa Shire lông đen tuyền. Đây là giống ngựa lao dịch phổ biến nhất Vương quốc Loen: điềm tĩnh, đáng tin, khả năng chở nặng cực tốt; dù đi lại hay vận chuyển hàng hóa đều là lựa chọn hàng đầu.",
      [26389889682944] = "Một con ngựa Shire lông trắng tuyền. Đây là giống ngựa lao dịch phổ biến nhất Vương quốc Loen: điềm tĩnh, đáng tin, khả năng chở nặng cực tốt; dù đi lại hay vận chuyển hàng hóa đều là lựa chọn hàng đầu.",
      [26389889683200] = "Một con ngựa Shire lông màu hạt dẻ ánh vàng. Đây là giống ngựa lao dịch phổ biến nhất Vương quốc Loen: điềm tĩnh, đáng tin, khả năng chở nặng cực tốt; dù đi lại hay vận chuyển hàng hóa đều là lựa chọn hàng đầu.",
      [26389889683456] = "Chiến mã đỏ thẫm như Huyết Nguyệt, giáp bạc phủ trước ngực, tựa u linh đỏ giữa trời đêm.",
      [26389889683712] = "Chiến mã tím sâu như màn sao nửa đêm, điểm xuyết chút giáp bạc, tựa bóng tối lẩn trong màn đêm.",
      [26389889683968] = "Chiến mã mang ánh bạc như trăng, điểm giáp bạch kim; những đường sáng vàng như lưu quang chạy dọc bộ lông.",
      [26389889684224] = "Chiến mã đỏ sẫm như máu, phần lớn thân thể phủ trọng giáp bạc; hoa văn đan xen tựa những ký hiệu thần bí cổ xưa.",
      [26389889684480] = "Chiến mã tím sẫm như đêm sâu, khoác trọng giáp bạc nặng nề, tựa sứ giả u minh tuần hành nhân thế.",
      [26389889684736] = "Chiến mã trắng thánh khiết, khoác lượng lớn trọng giáp bạch kim; vệt sáng vàng khắc nên dấu ấn thần thánh.",
      [26389889685504] = "Ngọn lửa không cần đi theo tranh đấu. Khi Ngài giáng lâm, tranh đấu tự khắc theo tới. Từ đó, sắt và máu có tên.",
      [26389889685760] = "Kẻ nhìn vào vực sâu cuối cùng sẽ thấy chính mình trong vực sâu. Giao chiến với ác long quá lâu, long lân đã phủ lên thân thể.",
      [26389889686016] = "Hoàng hôn đã qua, thân này chính là vĩnh trú ban ngày. Ta đứng nơi đây, thế giới mới bắt đầu được nhìn thấy.",
      [26389889686272] = "Chỉ băng tuyết trường tồn từ cổ chí kim. Vạn vật ngưng đọng nơi đây, đến thời gian cũng phai màu.",
      [453069926041088] = "Mỗi bước chân nở một đóa hoa nhẹ tênh, mỗi dấu vuốt để lại một lời hứa mềm mại. Thế giới nhờ bạn mà trở nên bông xù.",
      [453069926041344] = "Ánh sáng tinh bàn từ từ trải ra dưới từng bước chân. Không ai biết con đường phía trước dẫn về đâu, nhưng tinh tú vẫn mãi đếm từng bước của bạn.",
      [453069926042368] = "Màu hồng không nhất thiết đồng nghĩa với dịu dàng. Trái tim xoay giữa ánh sao đôi khi mang một nét sắc bén khó gọi thành tên.",
      [453069926045184] = "Tia nắng đầu tiên của buổi sớm xuyên qua sương mỏng, rơi trên hoa hồng và linh lan vừa hé nở.",
      [453069926046720] = "Sợi nấm lan theo gân lá, bào tử trôi cùng những đốm sáng. Cánh rừng cổ xưa vô hình cứ thế lặng lẽ sinh trưởng quanh bạn.",
      [453069926048256] = "Bên bờ Minh Hà, cái chết và vĩnh hằng cùng khiêu vũ. Nàng khoác cốt sa màu sương bước tới.",
      [453069926049024] = "Cành lá vàng dệt thành vương miện; nơi sâu trong bóng rậm tự có bất hủ. Dây leo quấn lá vàng, đến rừng sâu cũng cúi đầu.",
      [453069926057472] = "Bên bờ Minh Hà, cái chết và vĩnh hằng cùng khiêu vũ. Vương miện đen xám đội lên đầu hắn giữa tịch diệt.",
      [453069926064384] = "Ngài nói bóng tối sẽ đến, thế là đêm đen dùng im lặng thu gom vạn vật vào giữa môi răng.\nNgài nói hãy an giấc nơi đây, thế là màn đêm dùng bình yên bọc chúng sinh vào vương quốc chưa tỉnh.\nBóng đêm thu hết mọi sắc bén, chỉ vì bạn đến mà lấp lánh, như tinh tú thức dậy trên thiên khung.",
      [453138108646912] = "Khởi điểm của Con Đường Phi Phàm. Bậc còn chưa hiển danh, nhưng sức mạnh đã âm thầm thức tỉnh, chờ vận mệnh triệu gọi.",
      [453138108648704] = "Hương thơm ngọt ngào tỏa ra từ cái đầu lông xù, khiến cả những người Phi Phàm đang nghiêm trận cũng không khỏi mềm lòng.",
      [453138108650496] = "Đỏ thẫm thấm qua bóng tối, lời điên cuồng thì thầm quanh lưỡi đao. Mỗi lần vung lên đều hóa thành huyết tế dâng cho Tà Thần.",
      [453138108652288] = "Dao nĩa khẽ chạm đĩa sứ, đồ bạc ánh lạnh dưới nến. Những quý tộc hai bên bàn dài buộc phải thu lại mọi ý nghĩ thất lễ.",
      [453413523432192] = "Nụ cười ngồi xổm trên đỉnh đầu, sưởi ấm từng sợi tóc của bạn.",
      [453413523437568] = "Đường ray kéo dài về phương xa, dụng cụ leng keng. Một chuyến hành trình đường sắt đan xen hơi nước và tiếng động cơ bắt đầu từ đây.",
      [453413523475968] = "Hoàng hôn không bao giờ trôi đọng lại nơi ngọn tóc. Dẫu thân mình tắm trong ánh chiều tà, ý chí đánh thức bình minh vẫn không đổi.",
      [453413523476736] = "Hoàng hôn không bao giờ trôi dừng lại trên giáp vai. Dẫu thân mình tắm trong ánh chiều tà, ý chí đánh thức bình minh vẫn không đổi.",
      [453413523482112] = "Nhân danh Tarot truyền đi mồi lửa, chỉ để sau ngày tận thế vẫn còn ngày mai.",
      [453413523497216] = "Ánh vàng rực đan cùng sắc ngọc lục trong trẻo; quang ảnh lay động, ngâm một khúc tụng ca không lời.",
      [453413523517440] = "“Tôi sẽ nhớ lại những giấc mơ chúng ta từng cùng nhau dò tìm, nhớ từng vụ án Phi Phàm hay Vật Phong Ấn từng làm chúng ta đau đầu, nhớ hướng gió thổi, cả hình dạng và màu sắc của mặt trăng.”",
      [453413523520000] = "Lời lẩm bẩm điên cuồng theo Hồng Nguyệt mà tới. Nữ tiểu thuyết gia tụng niệm tôn danh Kẻ Khờ; lúc ấy nàng còn chưa biết, đây sẽ là chuyến hành trình xuyên qua gia tộc và lịch sử.",
      [453413523564288] = "Sự tồn tại điên cuồng trên biển cả; dưới đôi găng da sinh ra đủ loại sinh mệnh kỳ quái. Mỗi cây cỏ đều là “đứa con” của hắn, bén rễ giữa những cuộc thí nghiệm.",
      [453413523624192] = "Kính gọng đen giản dị khiến người đeo trông uyên bác hơn.",
      [453413523625472] = "Nghe nói là phiên bản nâng cấp của kính gọng tròn nhỏ; đeo vào giúp khả năng tập trung tiến thêm một bậc.",
      [453413523630592] = "Sắc trắng của aria nở giữa tà váy, sắc vàng của recitative cuộn dưới áo choàng. Dưới màn sân khấu, họ viết nên khúc hoa chương không ngừng nghỉ.",
      [453413523644928] = "Cát vàng vùi lấp quá khứ. Ánh mắt của Ngài xuyên qua thời gian; giấc mộng liệt nhật chưa từng tan biến.",
      [453413523651584] = "Giữa sóng lúa vàng của thị trấn Morse, nhặt lại một đoạn thời gian dịu dàng đã qua.",
      [453413523668736] = "Màu đen là bí ẩn đêm tối ban tặng, màu đỏ là sự nghiêm khắc của giới luật. Những sứ giả của Nữ Thần lên đường vì bảo hộ.",
      [453413523693312] = "Dùng đôi vai non nớt chống lấy bầu trời của gia đình Moretti; giữa nghèo khó vẫn không đánh mất thể diện và tôn nghiêm.",
      [453413523712000] = "Có những điều thần bí ẩn trong tinh đồ, ẩn trong ánh sáng cuối đêm dài không chịu tắt.",
      [453413523712768] = "Trong tiên cảnh đêm giữa hạ, lướt qua bầu trời không chỉ có đôi cánh tinh linh, mà còn có trái tim thơ bay đầy trời.",
      [453413523735296] = "Nguyện bạn cũng như vị tồn tại ấy, có được quãng thời gian khởi đầu hành trình tuyệt vời nhất tại thành phố tri thức này.",
      [453413523744768] = "Đôi cánh dịu dàng bay ra từ Linh Giới. Dẫu không thể trở thành tín sứ, chúng vẫn đủ mang đến một phần an ủi.",
      [453413523745280] = "Đôi tai thỏ lông xù bất đối xứng, khẽ lay theo từng động tác.",
      [453413523745536] = "Đôi tai thỏ lông xù đối xứng, tất nhiên cũng sẽ khẽ lay theo từng động tác.",
      [453413523748096] = "Dù chỉ là hàng mô phỏng của một Vật Phong Ấn thần bí nào đó, cũng đừng tùy tiện ước nguyện nhé?",
      [453413523748352] = "Tóm lại, đội nó lên sẽ có cảm giác tri thức đang tràn vào đầu.",
      [453413523748864] = "Kem do “May Mắn” mang tới cũng là cây kem có thể mang lại may mắn!",
      [453413523749120] = "Hàng mô phỏng cao cấp không khiến Đặc Tính Phi Phàm tách ra. Cứ yên tâm đeo.",
      [453413523749376] = "Tương truyền chiếc bình báu này có thể trói buộc ma quỷ, nhưng lúc này bên trong trống không.",
      [453413523749632] = "Trái tim bị độc xà quấn quanh, dường như là vật dùng trong một nghi thức bí nghi nào đó.",
      [453413523752960] = "Đây không phải Thánh Huy Thái Dương thật, cũng không phải Thánh Huy Thái Dương Dị Biến thật. Xin hãy ngừng thử dùng nó để nhìn trộm Vĩnh Hằng Liệt Dương.",
      [453413523756032] = "Kề vai chiến đấu là lời thề còn kiên cố hơn sắt.",
      [453413523766784] = "Cát vàng vùi lấp quá khứ. Ánh mắt của Ngài xuyên qua thời gian; giấc mộng liệt nhật càng thêm bỏng rực.",
      [453413523781632] = "Xin chào! Có thể cho tôi xin một chút thời gian không! Tôi muốn kể cho bạn nghe về đạo tiêu và Đấng Cứu Thế của chúng tôi! Ngài Kẻ Khờ... ngài Kẻ Khờ Meo!",
      [453413523787776] = "Không thèm giải thích, cũng chẳng muốn thuận theo. Kẻ phản nghịch sẽ đúng giờ xuất hiện lúc nửa đêm. Khoảnh khắc kinh tình chính là lúc này.",
      [453413523791104] = "Khoác sương mù và bụi trần, tìm một khoảng trời trong cho riêng mình nơi góc khuất của đô thành vạn đô.",
      [453413523794432] = "Trong những chuyến đi và trận chiến có bạn đồng hành, sẽ không còn bị nấm độc làm hại.",
      [453413523795968] = "Vương đến, thời đại vì thế mở đường; vương đứng, quyền và lực vì thế cúi đầu.",
      [453413523798272] = "Lời thì thầm dịu nhẹ hay cú đấm cuồng nhiệt đều có thể hoàn thành một giấc ngủ dài khó lòng chống cự.",
      [453413523812096] = "Nắng chiều rót vào tách cà phê, tâm trạng thư thái cũng rực rỡ như lớp latte art.",
      [453413523817984] = "“Món quà thứ hai là gì?”\n\n“Là một con tàu ma mang tên ‘Kẻ Báo Thù Lam Thẫm’, đã neo ở cảng.”",
      [453413523818240] = "Lại một tiếng chuông vang. Trên mặt đồng hồ xám trắng xen xanh đen, xuất hiện thêm một kim giờ loang lổ.",
      [453413523821568] = "Tạo vật của Chấp Chính Quan Tử Vong, sự bảo hộ sinh ra từ tư tâm. Lời che chở Ngài đã hứa sẽ cháy sáng mãi trong ngọn nến này.",
      [453413523822080] = "Khoác áo mưa bước qua góc phố, để những hạt nước dày trượt khỏi bên người; bạn chính là ngọn đèn ấm áp giữa đêm.",
      [453413523825664] = "Ánh nắng đã chạm mặt ngay từ lúc bình minh; một ngày quang đãng bắt đầu từ bây giờ.",
      [453413523826944] = "Trong gió chiều, bước chân càng nhẹ nhờ bộ đồ thoải mái. Ngày mai cũng sẽ là một ngày mai tốt đẹp.",
      [453413523828480] = "Nàng đã rời đi, nhưng chiếc còi bạc sẽ mãi ngân khúc du dương, chúc cho mọi người ôm lý tưởng bảo hộ đều biến giấc mơ đẹp thành hiện thực.",
      [453413523834880] = "Tu hành vô cùng vô tận; quỹ đạo tinh tú và Tarot chẳng bao giờ dừng. Cứ tiến về phía huyền bí, bói ra thêm nhiều khải thị về tương lai.",
      [453413523837184] = "Một vị đế vương từng để lại một câu cảm khái chưa trọn trong nhật ký. Sau thời gian dài thưởng thức, hẳn hương vị ấy đã thấm sâu vào cả thân lẫn tâm bạn.",
      [453413523840768] = "Khi bạn nhìn vào vực sâu, vực sâu cũng nhìn lại bạn. Hoặc bạn có thể chọn trở thành vực sâu.",
      [453413523841536] = "Bước chân không dừng, lần theo quá khứ trong bảo tàng đồng thời nhìn về ngày mai. Có lẽ chính chúng ta cũng chỉ là bóng cắt giữa khe hở lịch sử.",
      [611466978023424] = "Cánh Tay Cánh Hoa Tự Chương",
