      [611468051555840] = "<Highlight>Công Nghệ:</> Trang Sức Ngọc Trai Lộng Lẫy\n“Chúng ta có một viên ngọc đủ sức soi sáng cả Backlund. Trí tuệ, dung mạo, phẩm cách và lễ nghi của cô ấy đều không thể chê trách.”",
      [611468051556352] = "“Chúng ta có một viên ngọc đủ sức soi sáng cả Backlund. Trí tuệ, dung mạo, phẩm cách và lễ nghi của cô ấy đều không thể chê trách.”",
      [611468051557376] = "Bình minh dâng lên dưới chân, soi sáng miền huy hoàng.",
      [611468051565824] = "<Highlight>Công Nghệ:</> Lót Lưới Voan · Trang Sức Xích Linh Chất\n“Tôi sẽ nhớ lại những giấc mơ chúng ta từng cùng nhau dò tìm, nhớ từng vụ án Phi Phàm hay Vật Phong Ấn từng làm chúng ta đau đầu, nhớ hướng gió thổi, cả hình dạng và màu sắc của mặt trăng.”",
      [611468051566080] = "<Highlight>Công Nghệ:</> Lót Lưới Voan · Trang Sức Xích Linh Chất · Váy Cắt Xéo Bất Đối Xứng\n“Tôi sẽ nhớ lại những giấc mơ chúng ta từng cùng nhau dò tìm, nhớ từng vụ án Phi Phàm hay Vật Phong Ấn từng làm chúng ta đau đầu, nhớ hướng gió thổi, cả hình dạng và màu sắc của mặt trăng.”",
      [611468051566592] = "<Highlight>Công Nghệ:</> Lót Lưới Voan\n“Tôi sẽ nhớ lại những giấc mơ chúng ta từng cùng nhau dò tìm, nhớ từng vụ án Phi Phàm hay Vật Phong Ấn từng làm chúng ta đau đầu, nhớ hướng gió thổi, cả hình dạng và màu sắc của mặt trăng.”",
      [611468051568640] = "<Highlight>Công Nghệ:</> Nhung Ô Liu · Gấm Dệt Hoa Văn Vàng · Váy Dài Thêu\nLời lẩm bẩm điên cuồng theo Hồng Nguyệt mà tới. Nữ tiểu thuyết gia tụng niệm tôn danh Kẻ Khờ; lúc ấy nàng còn chưa biết, đây sẽ là chuyến hành trình xuyên qua gia tộc và lịch sử.",
      [611468051583488] = "<Highlight>Công Nghệ:</> Voan Dệt Bạc Tối · Thêu Sắc Sương · Váy Lễ Trắng Bệch\nBên bờ Minh Hà, cái chết và vĩnh hằng cùng khiêu vũ. Nàng khoác cốt sa màu sương bước tới.",
      [611468051584000] = "<Highlight>Công Nghệ:</> Voan Dệt Bạc Tối · Thêu Sắc Sương\nBên bờ Minh Hà, cái chết và vĩnh hằng cùng khiêu vũ. Nàng khoác cốt sa màu sương bước tới.",
      [611468051585280] = "<Highlight>Công Nghệ:</> Thêu Sắc Sương\nBên bờ Minh Hà, cái chết và vĩnh hằng cùng khiêu vũ. Nàng khoác cốt sa màu sương bước tới.",
      [611468051591936] = "Lời thề không tiếng, nhưng kéo dài đến tận cùng sinh mệnh.",
      [611468051602432] = "<Highlight>Công Nghệ:</> Da Làm Cũ · Phối Lớp Lót Vàng · Áo Măng Tô Dài Trầm Tĩnh\n“Tôi sẽ nhớ lại những giấc mơ chúng ta từng cùng nhau dò tìm, nhớ từng vụ án Phi Phàm hay Vật Phong Ấn từng làm chúng ta đau đầu, nhớ hướng gió thổi, cả hình dạng và màu sắc của mặt trăng.”",
      [611468051602688] = "<Highlight>Công Nghệ:</> Da Làm Cũ\n“Tôi sẽ nhớ lại những giấc mơ chúng ta từng cùng nhau dò tìm, nhớ từng vụ án Phi Phàm hay Vật Phong Ấn từng làm chúng ta đau đầu, nhớ hướng gió thổi, cả hình dạng và màu sắc của mặt trăng.”",
      [611468051609088] = "<Highlight>Công Nghệ:</> Giáp Da Nâu Sẫm · Phụ Kiện Lưng Mạng Nấm · Trang Phục Học Giả Sinh Vật\nSự tồn tại điên cuồng trên biển cả; dưới đôi găng da sinh ra đủ loại sinh mệnh kỳ quái. Mỗi cây cỏ đều là “đứa con” của hắn, bén rễ giữa những cuộc thí nghiệm.",
      [611468051609600] = "<Highlight>Công Nghệ:</> Phụ Kiện Lưng Mạng Nấm\nSự tồn tại điên cuồng trên biển cả; dưới đôi găng da sinh ra đủ loại sinh mệnh kỳ quái. Mỗi cây cỏ đều là “đứa con” của hắn, bén rễ giữa những cuộc thí nghiệm.",
      [611468051615232] = "<Highlight>Công Nghệ:</> Vải Nỉ Đêm Tối · Cắt May Thi Vị · Áo Khoác Đuôi Tôm Dài\nDưới sự dẫn dắt của Đêm Tối, Găng Tay Đỏ đi xuyên qua những điều ẩn mật. Bảo hộ màn đêm này chính là ngôi sao sáng nhất trong số họ.",
      [611468051615488] = "Dưới sự dẫn dắt của Đêm Tối, Găng Tay Đỏ đi xuyên qua những điều ẩn mật. Bảo hộ màn đêm này chính là ngôi sao sáng nhất trong số họ.",
      [611468051616000] = "<Highlight>Công Nghệ:</> Vải Nỉ Đêm Tối · Cắt May Thi Vị\nDưới sự dẫn dắt của Đêm Tối, Găng Tay Đỏ đi xuyên qua những điều ẩn mật. Bảo hộ màn đêm này chính là ngôi sao sáng nhất trong số họ.",
      [611468051617536] = "<Highlight>Công Nghệ:</> Nỉ Nhung Đen Huyền · Khuy Vòng Trang Sức Bạc · Lễ Phục Học Giả Loen\nTri thức lắng đọng giữa những nếp gấp, năm tháng lưu luyến trên tà áo.\nĐây là nét thanh lịch thuộc về thời đại cũ, cũng là sự im lặng của người bảo hộ.",
      [611468051623936] = "Kiểu tóc uốn sóng cổ điển mang dư vị thanh lịch của một thời đại đã qua.",
      [611468051625216] = "<Highlight>Công Nghệ:</> Gấm Satin Sắc Sương · Điểm Sương Mai · Lễ Phục Thanh Nhã\nTrong màn sương sớm, tinh linh đã để lại dấu chân.",
      [611468051626240] = "<Highlight>Công Nghệ:</> Gấm Satin Sắc Sương · Điểm Sương Mai\nTrong màn sương sớm, tinh linh đã để lại dấu chân.",
      [611468051627520] = "<Highlight>Công Nghệ:</> Lễ Phục Đêm Tối\nĐêm tối và sắc đỏ thẫm là những gai nhọn quấn quanh sinh mệnh dài dằng dặc của Huyết Tộc: nguy hiểm, mỹ lệ và khiến người ta đau nhói.",
      [611468051627776] = "<Highlight>Công Nghệ:</> Gấm Đỏ Thẫm · Lễ Phục Đêm Tối\nĐêm tối và sắc đỏ thẫm là những gai nhọn quấn quanh sinh mệnh dài dằng dặc của Huyết Tộc: nguy hiểm, mỹ lệ và khiến người ta đau nhói.",
      [611468051637760] = "<Highlight>Công Nghệ:</> Vân Sóng Bọt Biển · Mặt Dây Chuyển Động · Đồ Bơi Năng Động\nGợn sóng cuộn lên, sắc cam vàng tươi sáng phá tan từng đợt nóng. Bọt nước tung nở — mùa hè xuất hiện!",
      [611468051638016] = "Gợn sóng cuộn lên, sắc cam vàng tươi sáng phá tan từng đợt nóng. Bọt nước tung nở — mùa hè xuất hiện!",
      [611468051639040] = "<Highlight>Công Nghệ:</> Mặt Dây Chuyển Động\nGợn sóng cuộn lên, sắc cam vàng tươi sáng phá tan từng đợt nóng. Bọt nước tung nở — mùa hè xuất hiện!",
      [611468051639808] = "<Highlight>Công Nghệ:</> Lưới Voan Mềm Nhẹ · Điểm Lông Vũ Trắng · Lễ Trang Quang - Ám\nCánh vươn trong huy quang, kim loại ngưng kết giữa bóng tối; đôi bên phản chiếu lẫn nhau, mỗi bên tự thành một thể hoàn chỉnh.",
      [611468051640064] = "Cánh vươn trong huy quang, kim loại ngưng kết giữa bóng tối; đôi bên phản chiếu lẫn nhau, mỗi bên tự thành một thể hoàn chỉnh.",
      [611468051640832] = "<Highlight>Công Nghệ:</> Lưới Voan Mềm Nhẹ · Điểm Lông Vũ Trắng\nCánh vươn trong huy quang, kim loại ngưng kết giữa bóng tối; đôi bên phản chiếu lẫn nhau, mỗi bên tự thành một thể hoàn chỉnh.",
      [611468051641600] = "<Highlight>Công Nghệ:</> Lông Quạ Hắc Ám · Da Chế Tác Nặng · Lễ Phục Dạ Hội Gothic\nSắc màu rực rỡ chảy trên nền đen sâu, quỷ quyệt mà thanh lịch, khiến mọi màu sắc tầm thường đều lu mờ.",
      [611468051641856] = "Sắc màu rực rỡ chảy trên nền đen sâu, quỷ quyệt mà thanh lịch, khiến mọi màu sắc tầm thường đều lu mờ.",
      [611468051642368] = "<Highlight>Công Nghệ:</> Lông Quạ Hắc Ám · Da Chế Tác Nặng\nSắc màu rực rỡ chảy trên nền đen sâu, quỷ quyệt mà thanh lịch, khiến mọi màu sắc tầm thường đều lu mờ.",
      [611468051643136] = "<Highlight>Công Nghệ:</> Lông Quạ Hắc Ám\nSắc màu rực rỡ chảy trên nền đen sâu, quỷ quyệt mà thanh lịch, khiến mọi màu sắc tầm thường đều lu mờ.",
      [611468051644160] = "<Highlight>Công Nghệ:</> Họa Tiết Quả Trám Xanh-Đen · Xích Bạc Tinh Chế · Lễ Phục Cổ Tích\nDẫu chỉ là vị khách lạc bước, xin hãy tuân theo lễ nghi phục sức. Thay bộ lễ phục quả trám xanh-đen tinh nghịch và gia nhập buổi tiệc trà quái đản kỳ diệu.",
      [611468051644416] = "Dẫu chỉ là vị khách lạc bước, xin hãy tuân theo lễ nghi phục sức. Thay bộ lễ phục quả trám xanh-đen tinh nghịch và gia nhập buổi tiệc trà quái đản kỳ diệu.",
      [611468051644928] = "<Highlight>Công Nghệ:</> Lễ Phục Cổ Tích\nDẫu chỉ là vị khách lạc bước, xin hãy tuân theo lễ nghi phục sức. Thay bộ lễ phục quả trám xanh-đen tinh nghịch và gia nhập buổi tiệc trà quái đản kỳ diệu.",
      [611468051645696] = "<Highlight>Công Nghệ:</> Xích Bạc Tinh Chế\nDẫu chỉ là vị khách lạc bước, xin hãy tuân theo lễ nghi phục sức. Thay bộ lễ phục quả trám xanh-đen tinh nghịch và gia nhập buổi tiệc trà quái đản kỳ diệu.",
      [611468051646208] = "<Highlight>Công Nghệ:</> Lụa Đen Bóng Tối · Giáp Tay Trang Bạc · Lễ Trang Quang - Ám\nCánh vươn trong huy quang, kim loại ngưng kết giữa bóng tối; đôi bên phản chiếu lẫn nhau, mỗi bên tự thành một thể hoàn chỉnh.",
      [611468051646976] = "<Highlight>Công Nghệ:</> Lụa Đen Bóng Tối · Lễ Trang Quang - Ám\nCánh vươn trong huy quang, kim loại ngưng kết giữa bóng tối; đôi bên phản chiếu lẫn nhau, mỗi bên tự thành một thể hoàn chỉnh.",
      [611468051651072] = "Tạo kiểu đơn giản, gọn gàng sạch sẽ — hiệu suất là trên hết.",
      [611468051651328] = "Sương chiều khẽ hôn mái tóc, lười biếng mà lưu luyến.",
      [611468051651584] = "Mái tóc dài mềm mượt lướt qua gương mặt, ánh lên vẻ óng như gấm satin trong ánh nến.",
      [611468051651840] = "Tình cảm tuổi trẻ ngây thơ thuần khiết, như mùa xuân, như mùa xuân ngọt ngào tràn đầy sức sống.",
      [611468051655680] = "Tóc mái mềm mượt rủ bên má, ánh lên vẻ óng như gấm satin trong ánh nến.",
      [611468051655936] = "Những công nhân bắt đầu làm việc cùng lúc mặt trời mọc thường chải tóc theo kiểu thuận tiện nhất cho vận động.",
      [611468051658240] = "Chải tóc thật chỉnh tề là bài học đầu tiên khi tới mái nhà mới. Tình yêu và đức tin che chở lũ trẻ, giữ linh hồn chúng thành kính và trong sạch.",
      [611468051659520] = "<Highlight>Công Nghệ:</> Fondant Công Nghiệp · Khuôn Trái Tim\nSản phẩm từ thí nghiệm fondant của Giáo Hội Hơi Nước. Tiếc là nếu xem như đồ ăn thì có vẻ hơi cứng quá.",
      [611468051660544] = "Kính tròn viền bạc dễ phối, một lựa chọn khó mà sai.",
      [611468051661056] = "Kính gọng mảnh viền vàng được các Nhà Phân Tích Tâm Lý ưa chuộng, để ánh mắt sắc bén nhìn thấu mọi điều ẩn giấu.",
      [611468051661312] = "Kính vuông viền vàng dày khiến người ta liên tưởng tới vị quản lý hồ sơ nghiêm túc, quy củ trong thư viện đại học.",
      [611468051661568] = "Chiếc kính tròn nhỏ không nổi bật khiến người đeo bất giác tập trung hơn.",
      [611468051662336] = "<Highlight>Công Nghệ:</> Ren Xanh-Trắng · Tai Thỏ Tinh Nghịch · Lễ Phục Cổ Tích\nDẫu chỉ là vị khách lạc bước, xin hãy tuân theo lễ nghi phục sức. Thay bộ lễ phục ren xanh-trắng tinh nghịch và gia nhập buổi tiệc trà quái đản kỳ diệu.",
      [611468051662592] = "Dẫu chỉ là vị khách lạc bước, xin hãy tuân theo lễ nghi phục sức. Thay bộ lễ phục ren xanh-trắng tinh nghịch và gia nhập buổi tiệc trà quái đản kỳ diệu.",
