      [611468051673856] = "<Highlight>Công Nghệ:</> Thường Phục Dã Ngoại\nLấy trời sao làm chăn, mặt đất làm giường; bên đống lửa cất giấu giấc mơ phiêu lưu.",
      [611468051674112] = "Lấy trời sao làm chăn, mặt đất làm giường; bên đống lửa cất giấu giấc mơ phiêu lưu.",
      [611468051676160] = "<Highlight>Công Nghệ:</> Satin Đỏ Thắm · Hoa Văn Chìm Bạc Xám · Đồ Săn Sắc Gọn\nTấm lòng son như trăng non vừa hé, lời thề không tiếng còn nóng bỏng hơn máu tươi.",
      [611468051676416] = "Tấm lòng son như trăng non vừa hé, lời thề không tiếng còn nóng bỏng hơn máu tươi.",
      [611468051677184] = "<Highlight>Công Nghệ:</> Hoa Văn Chìm Bạc Xám\nTấm lòng son như trăng non vừa hé, lời thề không tiếng còn nóng bỏng hơn máu tươi.",
      [611468051677440] = "<Highlight>Công Nghệ:</> Satin Đỏ Thắm · Hoa Văn Chìm Bạc Xám\nTấm lòng son như trăng non vừa hé, lời thề không tiếng còn nóng bỏng hơn máu tươi.",
      [611468051678208] = "<Highlight>Công Nghệ:</> Voan Dệt Liên Kết · Chuỗi Hạt Quấn Vòng · Trang Phục Phong Vị Nam Đại Lục\nCát vàng vùi lấp quá khứ. Ánh mắt của Ngài xuyên qua thời gian; giấc mộng liệt nhật chưa từng tan biến.",
      [611468051679232] = "<Highlight>Công Nghệ:</> Chuỗi Hạt Quấn Vòng\nCát vàng vùi lấp quá khứ. Ánh mắt của Ngài xuyên qua thời gian; giấc mộng liệt nhật chưa từng tan biến.",
      [611468051683840] = "<Highlight>Công Nghệ:</> Dệt Cotton-Lanh · Thêu Bông Lúa · Thường Phục Đồng Quê\nGiữa sóng lúa vàng của thị trấn Morse, nhặt lại một đoạn thời gian dịu dàng đã qua.",
      [611468051686144] = "<Highlight>Công Nghệ:</> Dệt Cotton-Lanh · Thường Phục Đồng Quê\nGiữa sóng lúa vàng của thị trấn Morse, nhặt lại một đoạn thời gian dịu dàng đã qua.",
      [611468051686656] = "<Highlight>Công Nghệ:</> Lụa Bạc Tối · Thêu Sắc Sương · Lễ Phục Trắng Bệch\nBên bờ Minh Hà, cái chết và vĩnh hằng cùng khiêu vũ. Vương miện đen xám đội lên đầu hắn giữa tịch diệt.",
      [611468051688960] = "<Highlight>Công Nghệ:</> Lụa Tinh Chế · Dệt Lưới Voan · Lễ Phục Dạ Hội Yến Tiệc\nKhúc dạo đầu vang lên, điệu nhảy mở màn kéo rèm yến tiệc. Làn gió tối đầu tiên khẽ vuốt tà áo, màn đêm thở thật nhẹ.",
      [611468051689216] = "Khúc dạo đầu vang lên, điệu nhảy mở màn kéo rèm yến tiệc. Làn gió tối đầu tiên khẽ vuốt tà áo, màn đêm thở thật nhẹ.",
      [611468051689728] = "<Highlight>Công Nghệ:</> Lụa Tinh Chế · Lễ Phục Dạ Hội Yến Tiệc\nKhúc dạo đầu vang lên, điệu nhảy mở màn kéo rèm yến tiệc. Làn gió tối đầu tiên khẽ vuốt tà áo, màn đêm thở thật nhẹ.",
      [611468051695872] = "<Highlight>Công Nghệ:</> Cotton-Linen Mộc · Tối Giản Thanh Nhã\nChất liệu tự nhiên không nhuộm không tô điểm, tượng trưng cho sự tinh khiết thuở ban sơ của linh hồn.",
      [611468051697152] = "<Highlight>Công Nghệ:</> Giáp Trụ Đồng Xanh · Gỉ Mòn Năm Tháng · Trọng Giáp Cổ\nVinh quang của gia tộc Avery rên xiết trong gỉ sét; bào tử ăn mòn tinh thần kỵ sĩ, chỉ còn lời thì thầm đổ nát.",
      [611468051697920] = "<Highlight>Công Nghệ:</> Hoa Văn Chìm Đỏ Nâu\nSự ăn mòn của sa đọa, tiếng mê sảng tà ác… nhưng tinh thần kỵ sĩ không cho phép bị vấy bẩn.",
      [611468051698176] = "<Highlight>Công Nghệ:</> Cắt May Gọn Sắc · Chỉnh Tề Không Trang Trí · Đồng Phục Nhẹ\nBộ đồng phục xanh đậm cổ điển, đường nét chiến trường thon gọn sắc sảo, tượng trưng cho khởi đầu của trật tự.",
      [611468051698432] = "Đường nét chiến trường thon gọn sắc sảo, tượng trưng cho khởi đầu của trật tự.",
      [611468051700480] = "<Highlight>Công Nghệ:</> Cắt May Gọn Sắc · Chỉnh Tề Không Trang Trí\nBộ đồng phục xanh đậm cổ điển, đường nét chiến trường thon gọn sắc sảo, tượng trưng cho khởi đầu của trật tự.",
      [611468051700736] = "<Highlight>Công Nghệ:</> Bề Mặt Da Tinh Chế · Ve Áo Đỏ Thắm · Ngoại Bào Kẻ Gác Đêm\nMàu đen là bí ẩn đêm tối ban tặng, màu đỏ là sự nghiêm khắc của giới luật. Những sứ giả của Nữ Thần lên đường vì bảo hộ.",
      [611468051702784] = "<Highlight>Công Nghệ:</> Bề Mặt Da Tinh Chế\nMàu đen là bí ẩn đêm tối ban tặng, màu đỏ là sự nghiêm khắc của giới luật. Những sứ giả của Nữ Thần lên đường vì bảo hộ.",
      [611468051703040] = "Voan mỏng màu mực che giấu bóng bí ẩn, nhưng không giấu nổi hương thơm nguy hiểm như đóa hồng tai ách.",
      [611468051703296] = "Suốt nhiều năm, chiếc chuông lắc bạc màu xanh trong tay quản gia vẫn trung thành làm tròn bổn phận, đưa tiếng chuông trong trẻo tới mọi góc trang viên.",
      [611468051703552] = "<Highlight>Công Nghệ:</> Voan Rủ Ánh Sương · Thêu Thanh Lịch\nVải vóc như mây như sương, cũng giống kết cục mà một quý cô bất lực nhưng cuối cùng vẫn phải đối mặt.",
      [611468051703808] = "Mẹ sẽ hóa thành cánh bướm xanh khẽ hôn ngọn tóc Anthea. Từ đó, Anthea không còn sợ bị mẹ bỏ lại nữa.",
      [611468051704064] = "Chú thỏ Barney cũ kỹ là người nhà quan trọng nhất, quan trọng nhất của Anthea. Đôi mắt cúc áo của nó lúc nào cũng như vật sống, chăm chăm nhìn vào điều gì đó.",
      [611468051704576] = "Kiểu tóc đoan trang là bài học đầu tiên khi tới mái nhà mới. Tình yêu và đức tin che chở lũ trẻ, giữ linh hồn chúng thành kính và trong sạch.",
      [611468051704832] = "Mái tóc bạc như ngọn lửa lạnh, tựa đang kể lại truyền thuyết từ thời đại trước.",
      [611468051710208] = "<Highlight>Công Nghệ:</> Voan Lanh Trắng Thánh Khiết · Thêu Hoa Văn Vàng · Tế Bào Tư Tế\nTiếng cầu nguyện xuyên mái vòm hóa thành quầng sáng; lòng thành kính vang mãi giữa những cột đá của thánh điện.",
      [611468051713024] = "<Highlight>Công Nghệ:</> Lụa Tinh Chế\nKhúc dạo đầu vang lên, điệu nhảy mở màn kéo rèm yến tiệc. Làn gió tối đầu tiên khẽ vuốt tà áo, màn đêm thở thật nhẹ.",
      [611468051713280] = "<Highlight>Công Nghệ:</> Dệt Lưới Voan\nKhúc dạo đầu vang lên, điệu nhảy mở màn kéo rèm yến tiệc. Làn gió tối đầu tiên khẽ vuốt tà áo, màn đêm thở thật nhẹ.",
      [611468051714048] = "<Highlight>Công Nghệ:</> Satin Vàng Nhạt Mềm Mại · Quả Trám Nhung Đỏ · Áo Ngủ An Miên\nNhư nền gạch đã nằm suốt một mùa đông trong hành lang ngôi nhà cũ: bước lên không tiếng động, nhưng ẩn một cảm giác yên ổn và ấm áp khó gọi thành lời.",
      [611468051714304] = "Như nền gạch đã nằm suốt một mùa đông trong hành lang ngôi nhà cũ: bước lên không tiếng động, nhưng ẩn một cảm giác yên ổn và ấm áp khó gọi thành lời.",
      [611468051719168] = "<Highlight>Công Nghệ:</> Quả Trám Nhung Đỏ\nNhư nền gạch đã nằm suốt một mùa đông trong hành lang ngôi nhà cũ: bước lên không tiếng động, nhưng ẩn một cảm giác yên ổn và ấm áp khó gọi thành lời.",
      [611468051720960] = "<Highlight>Công Nghệ:</> Đồ Săn Sắc Gọn\nTấm lòng son như trăng non vừa hé, lời thề không tiếng còn nóng bỏng hơn máu tươi.",
      [611468051721216] = "<Highlight>Công Nghệ:</> Satin Đỏ Thắm\nTấm lòng son như trăng non vừa hé, lời thề không tiếng còn nóng bỏng hơn máu tươi.",
      [611468051724544] = "<Highlight>Công Nghệ:</> Vải Lanh Trắng Mộc · Váy Xếp Ly Màu Trà · Nơ Cổ Tối Giản\nDùng đôi vai non nớt chống lấy bầu trời của gia đình Moretti; giữa nghèo khó vẫn không đánh mất thể diện và tôn nghiêm.",
      [611468051725312] = "<Highlight>Công Nghệ:</> Giáp Rèn Mithril · Áo Choàng Xanh Thẳm · Chiến Giáp Kỵ Sĩ\nTia nắng đầu tiên của buổi sớm xuyên qua sương mỏng, rơi trên hoa hồng và linh lan vừa hé nở.",
      [611468051726080] = "<Highlight>Công Nghệ:</> Giáp Rèn Mithril · Chiến Giáp Kỵ Sĩ\nTia nắng đầu tiên của buổi sớm xuyên qua sương mỏng, rơi trên hoa hồng và linh lan vừa hé nở.",
      [611468051726336] = "<Highlight>Công Nghệ:</> Áo Choàng Xanh Thẳm\nTia nắng đầu tiên của buổi sớm xuyên qua sương mỏng, rơi trên hoa hồng và linh lan vừa hé nở.",
      [611468051726592] = "<Highlight>Công Nghệ:</> Giáp Rèn Mithril\nTia nắng đầu tiên của buổi sớm xuyên qua sương mỏng, rơi trên hoa hồng và linh lan vừa hé nở.",
      [611468051726848] = "<Highlight>Công Nghệ:</> Gấm Chúc Thánh · Hoa Văn Ánh Liệt Dương · Chiến Giáp Ca Tụng\nLinh hồn chí thành chí thuần sẽ thần thánh như ánh mặt trời; khi tấm lòng son cất tiếng ca tụng, Thái Dương cũng gật đầu với bạn.",
      [611468051727104] = "Linh hồn chí thành chí thuần sẽ thần thánh như ánh mặt trời; khi tấm lòng son cất tiếng ca tụng, Thái Dương cũng gật đầu với bạn.",
      [611468051729920] = "<Highlight>Công Nghệ:</> Voan Mỏng Trắng Thánh Khiết · Thêu Chỉ Vàng · Lễ Phục Nghi Điển\nHuy quang của Liệt Dương rơi xuống; Kẻ Cầu Quang nhận lễ đăng quang thần thánh trong lời nguyện sớm.",
      [611468051730176] = "Huy quang của Liệt Dương rơi xuống; Kẻ Cầu Quang nhận lễ đăng quang thần thánh trong lời nguyện sớm.",
      [611468051734016] = "<Highlight>Công Nghệ:</> Voan Đen Gai Nhọn · U Quang Lam Bảo · Váy Lễ Rách Vỡ\nPhu nhân Tử tước cứ đứng ở đó, chờ cây táo nở hoa, chờ trái chín, chờ người mà bà vẫn luôn đợi.",
      [611468051734272] = "Phu nhân Tử tước cứ đứng ở đó, chờ cây táo nở hoa, chờ trái chín, chờ người mà bà vẫn luôn đợi.",
      [611468051736064] = "<Highlight>Công Nghệ:</> Lụa Mềm Ánh Dịu · Voan Ren Nhẹ · Váy Ngủ Ôm Dáng\nMột vị Đại Đế từng để lại trong nhật ký câu cảm thán chưa viết hết; giờ nếm thử quả thật có một phong vị khác thường.",
      [611468051736320] = "Một vị Đại Đế từng để lại trong nhật ký câu cảm thán chưa viết hết; giờ nếm thử quả thật có một phong vị khác thường.",
      [611468051736832] = "<Highlight>Công Nghệ:</> Voan Ren Nhẹ\nMột vị Đại Đế từng để lại trong nhật ký câu cảm thán chưa viết hết; giờ nếm thử quả thật có một phong vị khác thường.",
      [611468051737600] = "<Highlight>Công Nghệ:</> Lụa Mềm Ánh Dịu · Voan Ren Nhẹ\nMột vị Đại Đế từng để lại trong nhật ký câu cảm thán chưa viết hết; giờ nếm thử quả thật có một phong vị khác thường.",
      [611468051739136] = "Chư Thần nói rằng ngoài nơi sâu thẳm còn có vô biên.",
      [611468051739904] = "Nơi thánh quang chiếu xuống chính là lúc rạng đông. Nơi thần ý chạm tới, bình minh sẽ bắt đầu từ đó.",
      [611468051740160] = "<Highlight>Công Nghệ:</> Satin Dệt Xanh U Ám · Dây Leo Xanh Lan Tràn · Váy Lễ Quét Đất\nĐộc đằng quấn lấy im lặng; sâu trong sắc xanh tối ẩn nét thanh lịch chí mạng.",
      [611468051740416] = "Độc đằng quấn lấy im lặng; sâu trong sắc xanh tối ẩn nét thanh lịch chí mạng.",
      [611468051741184] = "<Highlight>Công Nghệ:</> Dây Leo Xanh Lan Tràn\nĐộc đằng quấn lấy im lặng; sâu trong sắc xanh tối ẩn nét thanh lịch chí mạng.",
      [611468051741696] = "<Highlight>Công Nghệ:</> Nhung Xanh Đêm · Áo Choàng Tinh Trần · Đồng Phục Ma Pháp\nCó những điều thần bí ẩn trong tinh đồ, ẩn trong ánh sáng cuối đêm dài không chịu tắt.",
      [611468051742464] = "<Highlight>Công Nghệ:</> Nhung Xanh Đêm · Đồng Phục Ma Pháp\nCó những điều thần bí ẩn trong tinh đồ, ẩn trong ánh sáng cuối đêm dài không chịu tắt.",
      [611468051742720] = "<Highlight>Công Nghệ:</> Đồng Phục Ma Pháp\nCó những điều thần bí ẩn trong tinh đồ, ẩn trong ánh sáng cuối đêm dài không chịu tắt.",
      [611468051743488] = "<Highlight>Công Nghệ:</> Nhung Đêm Tối · Hoa Trang Sức Bướm Múa · Váy Dạ Hội Tà Rộng\nTrong tiên cảnh đêm giữa hạ, lướt qua bầu trời không chỉ có đôi cánh tinh linh, mà còn có trái tim thơ bay đầy trời.",
      [611468051744000] = "<Highlight>Công Nghệ:</> Nhung Đêm Tối · Hoa Trang Sức Bướm Múa\nTrong tiên cảnh đêm giữa hạ, lướt qua bầu trời không chỉ có đôi cánh tinh linh, mà còn có trái tim thơ bay đầy trời.",
      [611468051744512] = "<Highlight>Công Nghệ:</> Nhung Đêm Tối\nTrong tiên cảnh đêm giữa hạ, lướt qua bầu trời không chỉ có đôi cánh tinh linh, mà còn có trái tim thơ bay đầy trời.",
      [611468051745024] = "<Highlight>Công Nghệ:</> Hoa Trang Sức Bướm Múa\nTrong tiên cảnh đêm giữa hạ, lướt qua bầu trời không chỉ có đôi cánh tinh linh, mà còn có trái tim thơ bay đầy trời.",
      [611468051753728] = "<Highlight>Công Nghệ:</> Lông Khỉ Đầu Chó · May Vá Tinh Xảo\nMột chiếc túi nhỏ lông mềm màu bạc. (Cực kỳ thích hợp để đựng chuối!)",
      [611468051754240] = "<Highlight>Công Nghệ:</> Khảm Bạch Kim · Đá Huy Quang Xanh Trong\nKhép mắt lại, nhưng một tầm nhìn mới mở ra. Chân lý được đôi mắt xanh soi sáng đang ở ngay phía trước.",
      [611468051754752] = "<Highlight>Công Nghệ:</> Khảm Bạch Kim · Ngọc Biển\nMón trang sức cổ được vớt lên từ biển. Những viên ngọc biển tinh xảo và đường vân tự nhiên dường như đều kể về thời đại cổ xưa, thần bí nơi “Tinh Linh” từng tồn tại…",
      [611468051755520] = "<Highlight>Công Nghệ:</> Khảm Đồng Thau · Huyết Thạch Đỏ Sẫm\nĐức tin phải hướng về đúng phương hướng. Hãy luôn soi xét nội tâm, đừng rơi vào con đường lạc lối vô tận.",
      [611468051755776] = "<Highlight>Công Nghệ:</> Satin Ngà · Điểm Chuỗi Ngọc · Kỵ Trang Cung Đình\nKhi cánh cổng trường đua cung đình lần nữa mở ra, cả bước chân lẫn dáng vẻ đều không được lơi lỏng dù chỉ nửa phần.",
      [611468051756032] = "Khi cánh cổng trường đua cung đình lần nữa mở ra, cả bước chân lẫn dáng vẻ đều không được lơi lỏng dù chỉ nửa phần.",
      [611468051756800] = "<Highlight>Công Nghệ:</> Lưu Quang Lá Khô · Vảy Giáp Xếp Lớp · Chiến Giáp Cổ Nhã\nTrong cảnh sắc thu vàng và di tích trù phú, héo tàn hóa thành tân sinh, lá khô phá kén thành bướm.",
      [611468051757824] = "<Highlight>Công Nghệ:</> Lưu Quang Lá Khô\nTrong cảnh sắc thu vàng và di tích trù phú, héo tàn hóa thành tân sinh, lá khô phá kén thành bướm.",
      [611468051758080] = "<Highlight>Công Nghệ:</> Voan Dệt Lông Trắng · Điểm Vàng Son · Lễ Trang Thánh Vịnh\nTà áo của người cầu nguyện sớm vương sương và ánh sáng; mỗi bước đặt lên dư âm của khúc tụng ca, ngâm sự tĩnh lặng của thánh điện thành một bài thơ biết bước đi.",
      [611468051758336] = "Tà áo của người cầu nguyện sớm vương sương và ánh sáng; mỗi bước đặt lên dư âm của khúc tụng ca, ngâm sự tĩnh lặng của thánh điện thành một bài thơ biết bước đi.",
      [611468051759360] = "<Highlight>Công Nghệ:</> Voan Dệt Lông Trắng · Điểm Vàng Son\nTà áo của người cầu nguyện sớm vương sương và ánh sáng; mỗi bước đặt lên dư âm của khúc tụng ca, ngâm sự tĩnh lặng của thánh điện thành một bài thơ biết bước đi.",
      [611468051760896] = "<Highlight>Công Nghệ:</> Satin Rủ Hoang Dã · Huy Chương Sư Tử Vàng · Trang Phục Biểu Diễn Vũ Kịch\nSắc trắng của aria nở giữa tà váy, sắc vàng của recitative cuộn dưới áo choàng. Dưới màn sân khấu, họ viết nên khúc hoa chương không ngừng nghỉ.",
      [611468051761664] = "<Highlight>Công Nghệ:</> Satin Rủ Hoang Dã · Trang Phục Biểu Diễn Vũ Kịch\nSắc trắng của aria nở giữa tà váy, sắc vàng của recitative cuộn dưới áo choàng. Dưới màn sân khấu, họ viết nên khúc hoa chương không ngừng nghỉ.",
      [611468051762176] = "<Highlight>Công Nghệ:</> Chế Tác Mạ Vàng · Trang Sức Sân Khấu Lộng Lẫy\n Váy trắng phủ đầy máu tươi, sư tử vàng bám theo từng bước. Dưới màn sân khấu là luật rừng đang được diễn lại; kịch hay chẳng bao giờ hạ màn.",
      [611468051763456] = "<Highlight>Công Nghệ:</> Da Chế Tác Nặng · Lễ Phục Dạ Hội Gothic\nSắc màu rực rỡ chảy trên nền đen sâu, quỷ quyệt mà thanh lịch, khiến mọi màu sắc tầm thường đều lu mờ.",
      [611468051765760] = "<Highlight>Công Nghệ:</> Đúc Từ Sức Mạnh Bất Diệt\nSức mạnh bất diệt nóng bỏng như máu thịt vừa được hoạt hóa.",
      [611468051766016] = "<Highlight>Công Nghệ:</> Áo Gile Caro Xanh · Nơ Cổ Lụa Đen · Đồng Phục Học Viện\nTrên tường học viện, rêu xanh và đất mọc xen nhau giữa khe gạch vuông: một ô xanh biếc, một ô nâu vàng.",
      [611468051766784] = "<Highlight>Công Nghệ:</> Đồng Phục Học Viện\nTrên tường học viện, rêu xanh và đất mọc xen nhau giữa khe gạch vuông: một ô xanh biếc, một ô nâu vàng.",
      [611468051767040] = "<Highlight>Công Nghệ:</> Vải Màu Dịu · Viền Hoa Tinh Xảo · Váy Ban Ngày Dịu Dàng\nNguyện bạn cũng như vị tồn tại ấy, có được quãng thời gian khởi đầu hành trình tuyệt vời nhất tại thành phố tri thức này.",
      [611468051768576] = "<Highlight>Công Nghệ:</> Voan Mỏng Xanh Sương · Thêu Linh Lan · Váy Dài Quý Cô\nTia nắng đầu tiên của buổi sớm xuyên qua sương mỏng, rơi trên hoa hồng và linh lan vừa hé nở.",
      [611468051769600] = "<Highlight>Công Nghệ:</> Voan Mỏng Xanh Sương\nTia nắng đầu tiên của buổi sớm xuyên qua sương mỏng, rơi trên hoa hồng và linh lan vừa hé nở.",
      [611468051769856] = "<Highlight>Công Nghệ:</> Voan Mỏng Xanh Sương · Thêu Linh Lan\nTia nắng đầu tiên của buổi sớm xuyên qua sương mỏng, rơi trên hoa hồng và linh lan vừa hé nở.",
      [611468051771136] = "<Highlight>Công Nghệ:</> Điểm Vàng Son · Lễ Trang Thánh Vịnh\nTà áo của người cầu nguyện sớm vương sương và ánh sáng; mỗi bước đặt lên dư âm của khúc tụng ca, ngâm sự tĩnh lặng của thánh điện thành một bài thơ biết bước đi.",
      [611468051771648] = "<Highlight>Công Nghệ:</> Điểm Vàng Son\nTà áo của người cầu nguyện sớm vương sương và ánh sáng; mỗi bước đặt lên dư âm của khúc tụng ca, ngâm sự tĩnh lặng của thánh điện thành một bài thơ biết bước đi.",
      [611468051773440] = "Trang phục tân binh giản dị nhưng thực dụng.",
      [611468051776000] = "<Highlight>Công Nghệ:</> Dệt Mithril · Hoa Văn Lông Đen\nCất khúc An Miên cho mọi cuộc chia ly.",
      [611468051776256] = "<Highlight>Công Nghệ:</> May Mithril · Hoa Bất Tử\nHương hoa sẽ xoa dịu mọi linh hồn chưa cam lòng chìm vào giấc ngủ sâu.",
      [611468051777280] = "Đội niềm vui và lòng trung thành lên đầu.",
      [611468051778304] = "<Highlight>Công Nghệ:</> Voan Mỏng Trắng Thánh Khiết\nHuy quang của Liệt Dương rơi xuống; Kẻ Cầu Quang nhận lễ đăng quang thần thánh trong lời nguyện sớm.",
      [611468051778816] = "<Highlight>Công Nghệ:</> Thêu Chỉ Vàng\nHuy quang của Liệt Dương rơi xuống; Kẻ Cầu Quang nhận lễ đăng quang thần thánh trong lời nguyện sớm.",
      [611468051781120] = "<Highlight>Công Nghệ:</> Linh Mộc Cổ · Hoa Trang Sức Thủ Công\nBên dưới hương thơm, hoa và gai là hai mặt của Vận Mệnh.",
      [611468051781376] = "<Highlight>Công Nghệ:</> Satin Dệt Xanh U Ám · Dây Leo Xanh Lan Tràn · Lễ Phục Tinh Chế\nĐộc đằng quấn lấy im lặng; sâu trong sắc xanh tối ẩn nét thanh lịch chí mạng.",
      [611468051782912] = "<Highlight>Công Nghệ:</> Đồng Thau Rèn Tinh · Hoa Hồng Quấn Buộc\nMột đóa hồng giả cực kỳ tinh xảo, được cho là món trang sức cổ còn lại từ Kỷ Thứ Tư, góp một phần vào vẻ đẹp bất đối xứng.",
      [611468051783936] = "<Highlight>Công Nghệ:</> Chạm Khắc Mithril · Khảm Tinh Chế\nMột làn mát lạnh nơi đầu ngón tay thu liễm Linh Tính, dường như khiến mỗi lần nghi thức đều thuận lợi hơn.",
      [611468051784448] = "Đội sự ung dung và sức mạnh lên đầu.",
      [611468051785216] = "<Highlight>Công Nghệ:</> Rèn Vàng Ròng · Khảm Ngọc Và Kim Cương Cầu Kỳ\nMón trang sức đỉnh cấp mà một công ty châu báu từng cố ra mắt, nhưng liên tiếp thất bại vì nguyên nhân không rõ. Thành phẩm còn tồn tại cũng cực ít. Có lẽ là vì Vận Mệnh.",
      [611468051786496] = "<Highlight>Công Nghệ:</> Satin Ngà\nKhi cánh cổng trường đua cung đình lần nữa mở ra, cả bước chân lẫn dáng vẻ đều không được lơi lỏng dù chỉ nửa phần.",
      [611468051787008] = "<Highlight>Công Nghệ:</> Dệt Bộ Lạc · Trang Sức Đá Quý Thô Mạnh\nChiếc áo choàng kỳ lạ mang phong vị hoang dã, được nói là một trong những chiến lợi phẩm từ chuyến hải hành mở tuyến đường biển của Đại Đế Roselle.",
      [611468051788032] = "<Highlight>Công Nghệ:</> Chạm Khắc Phi Phàm · Khảm Pha Lê\nVòng tay bí nghi có xúc cảm lạnh như băng tuyết, dường như có thể giúp Phi Phàm Giả thu liễm Linh Tính.",
      [611468051788288] = "<Highlight>Công Nghệ:</> Nhung Xanh Đêm · Áo Choàng Tinh Trần · Đồng Phục Ma Pháp\nCó những điều thần bí ẩn trong tinh đồ, ẩn trong ánh sáng cuối đêm dài không chịu tắt.",
      [611468051789056] = "<Highlight>Công Nghệ:</> Nhung Xanh Đêm · Đồng Phục Ma Pháp\nCó những điều thần bí ẩn trong tinh đồ, ẩn trong ánh sáng cuối đêm dài không chịu tắt.",
      [611468051789568] = "<Highlight>Công Nghệ:</> Đồng Phục Ma Pháp\n Có những điều thần bí ẩn trong tinh đồ, ẩn trong ánh sáng cuối đêm dài không chịu tắt.",
      [611468051791104] = "Trên tường học viện, rêu xanh và đất mọc xen nhau giữa khe gạch vuông: một ô xanh biếc, một ô nâu vàng.",
      [611468051791616] = "<Highlight>Công Nghệ:</> Cashmere Xanh Ngọc · Gấm Hoa Văn Chìm · Áo Len Giữ Ấm\nKhi sương mù tan đi, lữ khách sẽ nhận ra con đường dưới chân mềm hơn tưởng tượng. Hóa ra đồng xanh không chỉ tồn tại trong truyền thuyết.",
      [611468051792640] = "Khi sương mù tan đi, lữ khách sẽ nhận ra con đường dưới chân mềm hơn tưởng tượng. Hóa ra đồng xanh không chỉ tồn tại trong truyền thuyết.",
      [611468051795712] = "Vẻ đẹp vĩnh hằng hay cô độc vô tận, chỉ cách nhau một ý niệm của bạn.",
      [611468051795968] = " <Highlight>Công Nghệ:</> Gấm Cổ · Hoa Văn Mật Ước\nChiếc áo choàng trải qua sự gột rửa của năm tháng, dường như ghi lại một minh ước đã bị lãng quên.",
      [611468051796736] = " <Highlight>Công Nghệ:</> Tơ Tằm Lưu Quang · Nhuộm Điểm Phấn Vảy\nBướm đã rời đi trong hoàng hôn, nhưng ảo ảnh cánh bướm vẫn còn đậu trên áo choàng.",
      [611468051797248] = " <Highlight>Công Nghệ:</> Gấm Satin Thêu · Trang Trí Cụm Hoa Cầu Kỳ\nKhông ai có thể nói chắc phải chờ bao lâu mới nở rộ, nhưng vẻ đẹp khi hoa mới nở nửa chừng đã đủ khiến người ta trân quý.",
      [611468051799040] = "Những lọn tóc xoáy xếp lớp dường như truyền đạt bí mật thâm áo nhất trong Tarot.",
      [611468051800064] = "<Highlight>Công Nghệ:</> Giáp Vai Bạc · Khảm Kim Cương\nGai nhọn vươn ra, nở rộ trong đêm trăng tròn, nguy hiểm mà mỹ lệ.",
      [611468051800832] = "<Highlight>Công Nghệ:</> Gấm Satin Ánh Bạc · Lông Thú Hoa Mỹ\nKhoác gió lạnh lên vai; dung quang chiến thắng chẳng sợ bất kỳ băng tuyết rét buốt nào.",
      [611468051801088] = "Mái tóc đen dài như cơn mưa trong đêm lạnh.",
      [611468051801344] = "<Highlight>Công Nghệ:</> Gấm Bạch Kim · Thêu Cành Dây Leo · Trường Bào Tinh Linh\nCành lá vàng dệt thành vương miện; nơi sâu trong bóng rậm tự có bất hủ. Dây leo quấn lá vàng, đến rừng sâu cũng cúi đầu.",
      [611468051804928] = "<Highlight>Công Nghệ:</> Satin Nhung Đỏ · Ren Đen-Vàng · Váy Lễ Ma Nữ\nTiếng tà váy kéo lê nhẹ như một bí mật; chỉ người đứng đủ gần mới nghe thấy cám dỗ đang thì thầm.",
      [611468051805184] = "Tiếng tà váy kéo lê nhẹ như một bí mật; chỉ người đứng đủ gần mới nghe thấy cám dỗ đang thì thầm.",
      [611468051806208] = "Sức mạnh bất diệt ập tới như mây đỏ đè thành.",
      [611468051806464] = "Không phải “Gấu Bí Ngẫu”, mà là “Ba Lô Gấu” Bí Ngẫu. Cả chiếc ba lô đều là Bí Ngẫu, nên đừng vứt lung tung nhé!",
      [611468051806720] = "Vĩ lực chưa biết cuộn trào trong thân thể, còn ngọn lửa phản kháng mãi không tắt.",
      [611468051809024] = "<Highlight>Công Nghệ:</> Vải Mờ · Dệt Kim Mịn · Trang Phục Dạo Phố Thư Thả\nNguyện bạn cũng như vị tồn tại ấy, có được quãng thời gian khởi đầu hành trình tuyệt vời nhất tại thành phố tri thức này.",
      [611468051809792] = "<Highlight>Công Nghệ:</> Vải Mờ · Trang Phục Dạo Phố Thư Thả\nNguyện bạn cũng như vị tồn tại ấy, có được quãng thời gian khởi đầu hành trình tuyệt vời nhất tại thành phố tri thức này.",
      [611468051813632] = "<Highlight>Công Nghệ:</> Lụa Đêm Tối · Trang Sức Vai Bướm Múa · Lễ Phục Nhẹ Quyến Rũ\nTrong tiên cảnh đêm giữa hạ, lướt qua bầu trời không chỉ có đôi cánh tinh linh, mà còn có trái tim thơ bay đầy trời.",
      [611468051814400] = "<Highlight>Công Nghệ:</> Lễ Phục Nhẹ Quyến Rũ\nTrong tiên cảnh đêm giữa hạ, lướt qua bầu trời không chỉ có đôi cánh tinh linh, mà còn có trái tim thơ bay đầy trời.",
      [611468051819008] = "<Highlight>Công Nghệ:</> Satin Mềm Phối Ren · Bèo Nhún Đen-Tím · Đồ Phố Gothic\nKhông thèm giải thích, cũng chẳng muốn thuận theo. Kẻ phản nghịch sẽ đúng giờ xuất hiện lúc nửa đêm. Khoảnh khắc kinh tình chính là lúc này.",
      [611468051820032] = "<Highlight>Công Nghệ:</> Đồ Phố Gothic\nKhông thèm giải thích, cũng chẳng muốn thuận theo. Kẻ phản nghịch sẽ đúng giờ xuất hiện lúc nửa đêm. Khoảnh khắc kinh tình chính là lúc này.",
      [611468051820288] = "<Highlight>Công Nghệ:</> Bèo Nhún Đen-Tím\nKhông thèm giải thích, cũng chẳng muốn thuận theo. Kẻ phản nghịch sẽ đúng giờ xuất hiện lúc nửa đêm. Khoảnh khắc kinh tình chính là lúc này.",
      [611468051820800] = "<Highlight>Công Nghệ:</> Da Làm Cũ · Trang Sức Xích Đinh Bạc · Đồ Phố Punk\nKhông thèm giải thích, cũng chẳng muốn thuận theo. Kẻ phản nghịch sẽ đúng giờ xuất hiện lúc nửa đêm. Khoảnh khắc kinh tình chính là lúc này.",
      [611468051821568] = "<Highlight>Công Nghệ:</> Da Làm Cũ · Đồ Phố Punk\nKhông thèm giải thích, cũng chẳng muốn thuận theo. Kẻ phản nghịch sẽ đúng giờ xuất hiện lúc nửa đêm. Khoảnh khắc kinh tình chính là lúc này.",
      [611468051822336] = "<Highlight>Công Nghệ:</> Da Thuộc Tinh Chế · Cắt May Nhẹ Gọn · Trang Phục Dạo Phố Đô Thị\nKhoác sương mù và bụi trần, tìm một khoảng trời trong cho riêng mình nơi góc khuất của đô thành vạn đô.",
      [611468051824384] = "<Highlight>Công Nghệ:</> Da Thuộc Tinh Chế\nKhoác sương mù và bụi trần, tìm một khoảng trời trong cho riêng mình nơi góc khuất của đô thành vạn đô.",
      [611468051825664] = "<Highlight>Công Nghệ:</> Sắt Trắng Rèn Tinh · Chế Tác Thủ Công\nMặt sắt vô tình, Vận Mệnh không thể kháng cự.",
      [611468051825920] = "<Highlight>Công Nghệ:</> Bạch Kim Chạm Tinh · Trang Sức Ngọc Trai Rủ\nMón trang sức trán tinh mỹ đan từ bạch kim thuần khiết; hoa văn phức tạp dường như có thể thu hút sự che chở của Thần Minh.",
      [611468051826688] = "<Highlight>Công Nghệ:</> Satin Hoàng Gia Lộng Lẫy · Giáp Trụ Chí Tôn · Vương Phục Đỉnh Cao\nVương đến, thời đại vì thế mở đường; vương đứng, quyền và lực vì thế cúi đầu.",
      [611468051827712] = "<Highlight>Công Nghệ:</> Satin Hoàng Gia Lộng Lẫy · Vương Phục Đỉnh Cao\nVương đến, thời đại vì thế mở đường; vương đứng, quyền và lực vì thế cúi đầu.",
      [611468051827968] = "<Highlight>Công Nghệ:</> Giáp Trụ Chí Tôn · Vương Phục Đỉnh Cao\nVương đến, thời đại vì thế mở đường; vương đứng, quyền và lực vì thế cúi đầu.",
      [611468051828224] = "<Highlight>Công Nghệ:</> Giáp Trụ Chí Tôn\nVương đến, thời đại vì thế mở đường; vương đứng, quyền và lực vì thế cúi đầu.",
      [611468051828992] = "<Highlight>Công Nghệ:</> Da Đen Trầm · Hộ Uyển Chắc Chắn · Khinh Chiến Giáp Tụ Lực\nLời thì thầm dịu nhẹ hay cú đấm cuồng nhiệt đều có thể hoàn thành một giấc ngủ dài khó lòng chống cự.",
      [611468051829760] = "<Highlight>Công Nghệ:</> Da Đen Trầm · Khinh Chiến Giáp Tụ Lực\nLời thì thầm dịu nhẹ hay cú đấm cuồng nhiệt đều có thể hoàn thành một giấc ngủ dài khó lòng chống cự.",
      [611468051830784] = "<Highlight>Công Nghệ:</> Nỉ Mềm Màu Lạc Đà · Lót Trắng Tinh · Thường Phục Ra Ngoài\nTrong gió chiều, bước chân càng nhẹ nhờ bộ đồ thoải mái. Ngày mai cũng sẽ là một ngày mai tốt đẹp.",
      [611468051831552] = "<Highlight>Công Nghệ:</> Nỉ Mềm Màu Lạc Đà · Thường Phục Ra Ngoài\nTrong gió chiều, bước chân càng nhẹ nhờ bộ đồ thoải mái. Ngày mai cũng sẽ là một ngày mai tốt đẹp.",
      [611468051834624] = "<Highlight>Công Nghệ:</> Satin Dệt Màu Tối · Mặt Che Chỉ Bạc · Váy Quét Đất “Lời Dịu Dàng”\nLời thì thầm dịu nhẹ hay cú đấm cuồng nhiệt đều có thể hoàn thành một giấc ngủ dài khó lòng chống cự.",
      [611468051835136] = "<Highlight>Công Nghệ:</> Satin Dệt Màu Tối · Váy Quét Đất “Lời Dịu Dàng”\nLời thì thầm dịu nhẹ hay cú đấm cuồng nhiệt đều có thể hoàn thành một giấc ngủ dài khó lòng chống cự.",
      [611468051836672] = "<Highlight>Công Nghệ:</> Mặt Che Chỉ Bạc\nLời thì thầm dịu nhẹ hay cú đấm cuồng nhiệt đều có thể hoàn thành một giấc ngủ dài khó lòng chống cự.",
      [611468051841792] = "<Highlight>Công Nghệ:</> Satin Hoàng Gia Lộng Lẫy · Giáp Trụ Chí Tôn\nVương đến, thời đại vì thế mở đường; vương đứng, quyền và lực vì thế cúi đầu.",
      [611468051842816] = "<Highlight>Công Nghệ:</> Gấm Mocha · Thêu Hoa Lá · Khinh Trang Nhịp Điệu\nNắng chiều rót vào tách cà phê, tâm trạng thư thái cũng rực rỡ như lớp latte art.",
      [611468051843328] = "<Highlight>Công Nghệ:</> Gấm Mocha · Khinh Trang Nhịp Điệu\nNắng chiều rót vào tách cà phê, tâm trạng thư thái cũng rực rỡ như lớp latte art.",
      [611468051844096] = "<Highlight>Công Nghệ:</> Gấm Mocha · Thêu Hoa Lá · Váy Lễ Nhịp Điệu\nNắng chiều rót vào tách cà phê, tâm trạng thư thái cũng rực rỡ như lớp latte art.",
      [611468051844864] = "<Highlight>Công Nghệ:</> Gấm Mocha\nNắng chiều rót vào tách cà phê, tâm trạng thư thái cũng rực rỡ như lớp latte art.",
      [611468051845376] = "<Highlight>Công Nghệ:</> Gấm Mocha · Thêu Hoa Lá\nNắng chiều rót vào tách cà phê, tâm trạng thư thái cũng rực rỡ như lớp latte art.",
      [611468051851264] = "<Highlight>Công Nghệ:</> Kim Loại Champagne · Khảm Thủ Công\nMặt nạ dạ hội hóa trang do thợ kim hoàn hàng đầu Loen tung ra, nghe nói lấy cảm hứng từ tiểu thuyết kinh dị của cô Fors Wall về một bệnh nhân mọc hoa trên mặt. Dĩ nhiên họ đã làm đẹp đi khá nhiều.",
      [611468051852544] = "<Highlight>Công Nghệ:</> Da Chống Nước · Ve Áo Bóng Sơn · Trang Phục Ra Ngoài Đêm Mưa\nKhoác áo mưa bước qua góc phố, để những hạt nước dày trượt khỏi bên người; bạn chính là ngọn đèn ấm áp giữa đêm.",
      [611468051853312] = "<Highlight>Công Nghệ:</> Da Chống Nước · Trang Phục Ra Ngoài Đêm Mưa\nKhoác áo mưa bước qua góc phố, để những hạt nước dày trượt khỏi bên người; bạn chính là ngọn đèn ấm áp giữa đêm.",
      [611468051855872] = "<Highlight>Công Nghệ:</> Len Pha · Lót Trắng Tinh · Trang Phục Ngắn Ngoài Trời\nÁnh nắng đã chạm mặt ngay từ lúc bình minh; một ngày quang đãng bắt đầu từ bây giờ.",
      [611468051856128] = "<Highlight>Công Nghệ:</> Len Pha · Trang Phục Ngắn Ngoài Trời\nÁnh nắng đã chạm mặt ngay từ lúc bình minh; một ngày quang đãng bắt đầu từ bây giờ.",
      [611468051858176] = "Nhân vật chính của thời đại, truyền kỳ trưởng thành — cũng có thể là bạn và tôi.",
      [611468051858432] = "Dẫu thân ở trong vỏ hạt, vẫn tự cho mình là vua của không gian vô tận.",
      [611468051858944] = "Lọn tóc linh động nhảy múa trong gió, tựa một khúc tiểu dạ du dương.",
      [611468051859200] = "Nung chiến kỳ phần phật thành sắc đỏ bách chiến bách thắng; thế gian rồi sẽ thần phục và ca tụng.",
      [611468051860224] = "Sự mềm mượt tự nhiên thực sự không cần tô điểm thừa thãi; chỉ một đường nét cũng đủ động lòng người.",
      [611468051862016] = "Độc đằng quấn lấy im lặng; cái đẹp tuyệt mỹ nằm ở nơi còn chí mạng hơn.",
      [611468051862272] = "Ngọn tóc xoay bay như aria ngân đến cao trào cốt truyện, khiến mọi tràng pháo tay đều nghiêng ngả vì nó.",
      [611468051862528] = "Tóc tung bay như recitative diễn đến khoảnh khắc cảm xúc nhất, mọi ánh đèn đều hội tụ về đó.",
      [611468051863040] = "Tiếng cầu nguyện xuyên mái vòm hóa thành quầng sáng; lòng thành kính vang mãi giữa những cột đá của thánh điện.",
      [611468051863552] = "<Highlight>Công Nghệ:</> Voan Lanh Trắng Thánh Khiết · Thêu Hoa Văn Vàng\nTiếng cầu nguyện xuyên mái vòm hóa thành quầng sáng; lòng thành kính vang mãi giữa những cột đá của thánh điện.",
      [611468051866624] = "<Highlight>Công Nghệ:</> Tinh Nguyệt Giao Huy · Vận Mệnh Luân Chuyển · Phục Bói Toán Cao Cấp\nTu hành vô cùng vô tận; quỹ đạo tinh tú và Tarot chẳng bao giờ dừng. Cứ tiến về phía huyền bí, bói ra thêm nhiều khải thị về tương lai.",
      [611468051868928] = "<Highlight>Công Nghệ:</> Lụa Mềm Ánh Dịu · Voan Ren Nhẹ · Váy Ngủ Kiểu Mới\nMột vị đế vương từng để lại một câu cảm khái chưa trọn trong nhật ký. Sau thời gian dài thưởng thức, hẳn hương vị ấy đã thấm sâu vào cả thân lẫn tâm bạn.",
      [611468051869696] = "<Highlight>Công Nghệ:</> Voan Ren Nhẹ\nMột vị đế vương từng để lại một câu cảm khái chưa trọn trong nhật ký. Sau thời gian dài thưởng thức, hẳn hương vị ấy đã thấm sâu vào cả thân lẫn tâm bạn.",
      [611468051870464] = "<Highlight>Công Nghệ:</> Lụa Mềm Ánh Dịu · Voan Ren Nhẹ\nMột vị đế vương từng để lại một câu cảm khái chưa trọn trong nhật ký. Sau thời gian dài thưởng thức, hẳn hương vị ấy đã thấm sâu vào cả thân lẫn tâm bạn.",
      [611468051872512] = "<Highlight>Công Nghệ:</> Cotton Dệt Tinh · Hoa Trang Sức Trí Thức · Trang Phục Nhà Tự Nhiên Học\nBước chân không dừng, lần theo quá khứ trong bảo tàng đồng thời nhìn về ngày mai. Có lẽ chính chúng ta cũng chỉ là bóng cắt giữa khe hở lịch sử.",
      [611468051873280] = "<Highlight>Công Nghệ:</> Cotton Dệt Tinh · Trang Phục Nhà Tự Nhiên Học\nBước chân không dừng, lần theo quá khứ trong bảo tàng đồng thời nhìn về ngày mai. Có lẽ chính chúng ta cũng chỉ là bóng cắt giữa khe hở lịch sử.",
      [611468051875328] = "<Highlight>Công Nghệ:</> Hoa Trang Sức Trí Thức\nBước chân không dừng, lần theo quá khứ trong bảo tàng đồng thời nhìn về ngày mai. Có lẽ chính chúng ta cũng chỉ là bóng cắt giữa khe hở lịch sử.",
      [611468051876608] = "<Highlight>Công Nghệ:</> Gấm Đỏ Thẫm · Gai Xương Kinh Cức\nĐêm tối và sắc đỏ thẫm là những gai nhọn quấn quanh sinh mệnh dài dằng dặc của Huyết Tộc: nguy hiểm, mỹ lệ và khiến người ta đau nhói.",
      [611468051877120] = "Đăng quang cho người phản kháng; ngọn lửa bất hủ mãi cháy trên vương tọa.",
      [611468051878400] = "<Highlight>Công Nghệ:</> Gấm Chiến Kỳ · Giáp Vai Từng Trải\nDũng sĩ trải trăm trận trở về, vinh quang lấp lánh trên áo choàng.",
      [611468051878912] = "<Highlight>Công Nghệ:</> Gấm Chiến Kỳ · Giáp Vai Thường Thắng\nDũng sĩ thường thắng xuất chinh; huân chương dành cho người ấy chính là chiến thắng kế tiếp.",
      [611468051879680] = "Đuôi lông khẽ lay, trở thành tâm điểm của cả sảnh ở cao trào vũ hội. Giữa đám đông đang kinh diễm, cứ tùy ý chọn con mồi vừa ý.",
      [611468051879936] = "Bản mô phỏng bút ký gia tộc Antigonus. Ngoài việc khiến người cầm muốn viết “Mọi người đều sẽ không chết, bao gồm cả tôi”, nó không có hiệu quả Phi Phàm nào khác.",
      [611468051884800] = "Chiếc tọa kỵ hơi nước đầu tiên rời xưởng cơ khí Tingen, cũng là lần đầu thành phố này nghe tiếng máy móc thay cho vó ngựa. Nó không nhanh, cũng chẳng hoa lệ, nhưng mọi tọa kỵ tung hoành đường phố Tingen sau này đều là hậu bối của nó.",
      [611468051887360] = "Một thoáng dừng lại, như đang suy nghĩ. Còn nghĩ tới điều gì thì chỉ sự im lặng mới biết.",
      [611468051887616] = "Toàn thân tỏa ra khí chất “lúc này rất đáng tin” — ít nhất là ngay lúc này.",
      [611468051887872] = "Một lần cầu nguyện đầy đủ nghi thức. Có được lắng nghe hay không thuộc về lĩnh vực bất khả tri.",
      [611468051888128] = "Ra hiệu giữ im lặng. Lý do chưa rõ, nhưng trong thế giới này cẩn thận chưa bao giờ là thừa.",
      [611468051888384] = "Tư duy trì độn, ý thức bồng bềnh. Cơ thể rơi vào trạng thái mơ hồ như bị “ủy quản”, thuận theo sự dẫn dắt từ bên ngoài.",
      [611468051888640] = "Khoanh hai tay, chuyển sang chế độ đứng xem, chẳng vội tham gia.",
      [611468051888896] = "Một cái nhún vai tiêu chuẩn. Thường dùng để nói: “Giải thích phiền quá, cứ thế này đi.”",
      [611468051889152] = "Ngón trỏ và ngón cái khẽ chạm thành hình trái tim, như một cánh bướm dừng giữa không trung chờ bạn nhận lấy.",
      [611468051889408] = "Động tác tay gửi lời mời, còn ánh mắt lặng lẽ châm lên tia lửa thăm dò.",
      [611468051889664] = "Khoảnh khắc giơ máy ảnh lên, thời gian vấp một bước trong khung ngắm và thế là bị đóng băng thành vĩnh hằng.",
      [611468051889920] = "Khẽ xoay người chống hông, để vẻ đẹp của sức mạnh dừng lại trong khoảnh khắc này.",
      [611468051890176] = "Gom lại mọi xao động, tập trung vào khoảnh khắc này.",
      [611468051890432] = "Dùng tay làm súng ngắm về phía trước. Có lẽ chỉ là trò đùa, cũng có thể không.",
      [611468051890688] = "Khóe mắt khẽ hạ, thu cả thế giới vào tầm nhìn bên.",
      [611468051890944] = "Khoe cơ bắp — đây là lời cảnh cáo không tiếng của tôi.",
      [611468051891200] = "Đầu ngón tay khẽ nhấc, đã “vớt” được một người quen cũ giữa đám đông.",
      [611468051891456] = "Thay vì nhìn thẳng vào nắng gắt, chi bằng ngắm xa qua kẽ ngón tay.",
      [611468051891712] = "Mở cuốn sách ra cũng là bước vào biển tri thức.",
      [611468051891968] = "Ngôn ngữ cơ thể khoa trương, biểu cảm cảm xúc đầy kịch tính. Sự thật thường còn hoang đường hơn cả sân khấu.",
      [611468051892224] = "Lưng thẳng khiến một bạn đầy tự tin càng đáng tin cậy hơn.",
      [611468051892480] = "Khoảnh khắc ô mở ra, mưa chỉ còn là phông nền.",
      [611468051892736] = "Cổ tay khẽ xoay; phong thái ung dung là bộ giáp lễ nghi của bạn.",
      [611468051892992] = "Đầu ngón tay chạm trên đỉnh đầu, nhẹ nhàng nói lên tình ý.",
      [611468051893248] = "Cúi đầu trước thế giới, dâng lên bạn lời cầu nguyện thành kính.",
      [611468051893504] = "Vẫy tay linh động như mèo con — trêu chọc hay mời gọi đây?",
      [611468051893760] = "Đầu ngón tay khẽ chạm, trả lại gương mặt mộc không tô điểm.",
      [611468051894016] = "Niềm vui từ cả tay trái lẫn tay phải — tất cả đều khóa mục tiêu là bạn.",
      [611468051897088] = "Nụ cười ngọt ngào của nàng lại như lưỡi dao tẩm mật, nguy hiểm mà mỹ lệ.",
      [611468051897344] = "Sáp nến đông lại thành hình đêm trăng, sẽ ban cho bạn sự an bình.",
      [611468051897600] = "Bức tượng mang thần sắc trang nghiêm, đứng nơi đây đã lâu, im lặng và thần thánh.",
      [611468051897856] = "Đứa trẻ với vẻ mặt ngây thơ. Lại gần cậu bé, biết đâu bạn sẽ được chia một tia quyến cố của Vận Mệnh.",
      [611468051898112] = "Ông lão trùm mũ che mặt, khiêm nhường đặt tay lên ngực. Tốt nhất đừng nói chuyện thì thầm trước mặt ông ấy.",
      [611468051898368] = "Người phụ nữ mặc trường bào, quanh thân tỏa ánh sáng dịu. Nàng lặng lẽ đứng đó, như đang âm thầm che chở nơi này.",
      [611468051898624] = "Một cây bách im lặng, cành lá chẳng hề lay trong gió. Nó không hiểu mong ước của con người, chỉ biết biến những ước nguyện ấy thành hạt bách rồi thả xuống đất.",
      [611468051898880] = "Một cây phong vàng óng dáng thẳng tắp; nó sẽ nhuộm bóng của bạn thành màu vàng rồi lén giấu đi.",
      [611468051899136] = "Chạm khắc trang trọng, nội tâm lại “qua loa”, nghiêm túc làm công tác phủ xanh.",
      [611468051899392] = "Bình hoa chạm khắc tinh mỹ, cắm những đóa hoa hồng phấn mềm mại rực rỡ, lặng lẽ tỏa hương.",
      [611468051899648] = "Ghế sofa ba chỗ bằng gỗ óc chó đen với hoa văn nổi, thường được đặt trong phòng khách.",
      [611468051899904] = "Chiếc sofa cổ điển nhỏ dành cho một người. Cảm giác mềm mại khi chìm vào đó thường khiến người ta quên mất thời gian trôi.",
      [611468051900160] = "Một chiếc bàn dài rất chắc chắn làm từ gỗ óc chó đen, từng chứng kiến rất nhiều người sáng tác trên mặt bàn.",
      [611468051900416] = "Một chiếc bàn vuông chắc chắn, trông rất thích hợp để… đấu với tà ác.",
      [611468051900672] = "Một chiếc bàn tròn bình thường, chân bàn chạm hoa; bày thêm trà bánh là thành khung cảnh thường ngày.",
      [611468051900928] = "Tay quay chuyển động, giai điệu năm xưa liền chậm rãi chảy ra từ bên trong.",
      [611468051901184] = "Ngọn nến đứng yên như nốt nhạc đông cứng, mãi không tắt.",
      [611468051901440] = "Nó ôm ánh sáng vào lòng, chờ màn đêm gửi lời mời.",
      [611468051901696] = "Những phím đen trắng im lặng, chờ một đôi tay đánh thức các nốt nhạc đang ngủ.",
      [611468051901952] = "Một cây piano có thể chơi nhạc. Êm tai hay không còn tùy người đánh.",
      [611468051902208] = "Dây đàn rung trong gió, cất lên khúc ca không ai hiểu.",
      [611468051902464] = "Dù thế giới ngoài cửa sổ u tối đến đâu, chúng vẫn luôn hướng về phía ánh sáng. Ca tụng Thái Dương!",
      [611468051902720] = "Cánh hoa đã rụng, nhưng vẫn còn ngửi thấy hương thanh.",
      [611468051902976] = "Hoa đã phai màu, nhưng vẫn tồn tại trong giấc mơ của mỗi người từng thấy nó nở rộ.",
      [611468051903232] = "Một vũ trụ có thể đặt gọn trong lòng bàn tay, cũng chứa vô số câu hỏi dành cho Vận Mệnh.",
      [611468051903488] = "Mở nó ra, chữ viết sẽ nhảy múa theo suy nghĩ của bạn.",
      [611468051903744] = "Đóng băng thời gian vào khoảnh khắc đôi cánh khẽ vỗ; cánh bướm lúc này như đang chuẩn bị bay vào giấc mơ của ai đó.",
      [611468051904000] = "Quả cầu pha lê lóe ánh mờ, tựa có thể phản chiếu nội tâm chân thật nhất của con người.",
      [611468051904256] = "Đôi cánh hóa đá, nhưng mang một trái tim tự do bay lượn.",
      [611468051904768] = "Nơi tiếng đàn rơi xuống, thời gian dừng lại.",
      [611468051905024] = "Nó đứng trên quyền năng Mất Trật Tự, giễu cợt và lật đổ mọi trật tự vốn có.",
      [611468051905280] = "Cột sáng dát vàng rủ từ đỉnh tháp. Tại đây mọi thứ đều được định nghĩa bằng luật lệnh; trong tĩnh lặng chứa uy nghi phán quyết vạn vật.",
      [611468051905536] = "Quang diễm đỏ thẫm cháy không tiếng trên đỉnh tháp. Dưới ánh sáng bao phủ, mọi thứ ngập mùi tanh ngọt của sắt và máu; kẻ bước vào đều trở thành một phần của chiến tranh.",
      [611468051905792] = "Tinh mang xanh u lặng lẽ lưu chuyển trên đỉnh tháp; vạn vật nơi đây rơi vào giấc An Miên vĩnh hằng, tiến gần tới chung kết.",
      [611468051913472] = "Trước khi mọi thứ thành hình, thế giới trông như thế nào? Có lẽ… chính là nơi đây.",
      [611468051913728] = "Ánh trời dịu nhẹ khiến người ta thoáng ngỡ rằng: có lẽ mọi chuyện chưa tệ đến thế.",
      [611468051913984] = "Đêm tối chưa rời sân khấu, ánh trời đã lặng lẽ len vào. Lúc này bạn có thể tận mắt chứng kiến bình minh tới.",
      [611468051914240] = "Tầm nhìn biến mất, nhưng thế giới vẫn chuyển động trong bóng tối.",
      [611468051914496] = "Hồng Nguyệt treo cao, màn đêm sâu thẳm; tòa cổ bảo sừng sững lặng nhìn đại địa.",
      [611468051914752] = "Phòng khách cổ điển thanh nhã, trông có vẻ trống trải nhưng khắp nơi đều lộ dấu vết bài trí dụng tâm.",
      [611468051915264] = "Vĩnh Miên là một dạng khác của an bình; nơi quy tụ cuối cùng của mọi thứ là an bình!",
      [611468051916032] = "Một miền tinh khiết khiến người ta không nỡ quấy nhiễu. Cây vàng trong mộng lấp lánh, chỉ chờ người say ngủ tới hái.",
      [611468051916544] = "Có lẽ bạn cần chậm lại, ngồi bên hồ, lặng cảm nhận thời gian trôi và nhìn mây trời phản chiếu trên mặt nước.",
      [611468051917056] = "Phòng khách với ánh nến lay động đang chờ một bữa dạ tiệc long trọng.",
      [611468051917312] = "Muôn hoa chứng kiến lời thề, cũng mở một góc gặp gỡ cho những người hữu tình.",
      [611468051917568] = "Trong thánh đình rực đuốc, bình minh dần nuốt chửng u ám — ánh sáng chính là ý nghĩa của tất cả.",
      [611468051918080] = "Rõ ràng không vui; thanh kiên nhẫn có thể thấy bằng mắt thường đang tụt về đáy.",
      [611468051918336] = "Thần sắc sa sút, nhưng cảm xúc vẫn còn được giữ trong phạm vi kiểm soát.",
      [611468051918592] = "Một nụ cười tiêu chuẩn. Ý nghĩa cụ thể xin đọc kết hợp ngữ cảnh.",
      [611468051918848] = "Rõ ràng diễn biến sự việc đã vượt ngoài dự liệu.",
      [611468051919360] = "Văn tự đến từ thời đại cũ, ép nhũ bằng thứ á kim thần bí, hiện lên huy hiệu chỉ thuộc về Quỷ Bí Chi Chủ.",
      [611468051919616] = "Theo đuổi tự do, khám phá điều chưa biết.",
      [611468051919872] = "Kính sợ Vận Mệnh, bói đoán bi hoan.",
      [611468051920128] = "Ca tụng quang minh, tán dương Thái Dương.",
      [611468051920384] = "Dòm ngó thần bí, cầu tri không ngừng.",
      [611468051920640] = "Thấu suốt tâm linh, đứng ngoài quan sát vạn vật.",
      [611468051920896] = "Can đảm vô úy, chính trực anh dũng.",
      [611468051921152] = "Gảy kim thời gian, rong chơi trong bóng của Vận Mệnh, hóa thân của lừa gạt và trò quậy phá — những thứ này thì liên quan gì tới quạ?",
      [611468051921408] = "Âu phục và mũ lễ là vũ trang của quý ông, cũng là dấu ấn thế giới này khắc lên người hắn.",
      [611468051921664] = "Đôi tai mèo lông xù mang nét hoạt bát tinh nghịch khiến người ta bất giác hạ phòng bị.",
      [611468051921920] = "Đôi tai thỏ lông xù mang vẻ linh động đáng yêu khác biệt.",
      [611468051922176] = "Trang sức hình bướm lưu chuyển ánh mờ, tượng trưng cho vẻ đẹp vô thường và những lần dừng chân đã định sẵn là ngắn ngủi.",
      [611468051922432] = "Muôn hoa làm khung viền, dịu dàng bao quanh trong dáng nở rộ, lặng nghe gió nhẹ và hương hoa thì thầm nơi mép viền.",
      [611468051922688] = "Đừng thấy chỉ là một Soli; đồng tiền nhỏ bé cũng có thể bẩy lên một nguyện vọng thật lớn.",
      [611468051923200] = "Lướt trong bóng tối, dùng đôi cánh đánh dấu từng tấc lãnh địa nó bay qua.",
      [611468051923456] = "Trên mỗi sợi tơ đều dính một đoạn ký ức bị lãng quên.",
      [611468051923968] = "Dán nó lên, nỗi nhớ liền bắt đầu phiêu bạt.",
      [611468051924224] = "Từ đây, mọi chuyện đều có thể.",
      [611468051924480] = "Tiếng gào của con mồi đặt dấu chấm hết cho cuộc săn này.",
      [611468051924736] = "“Hương vị Ma Nữ thật không tệ chút nào!” — Roselle Gustav",
      [611468051925504] = "“May mắn, thuận lợi”",
      [611468051926016] = "Tem thư là một cánh cửa nhỏ, từ đó có thể thoáng nhìn những lát cắt trong cuộc đời vị nhân vật chính của thời đại ấy.",
      [611468051931136] = "Trên mảnh đất này, em là đóa hồng cuối cùng của anh.",
    },
    ["loading"] = {
      [74905840276736] = "Bạn có một giấc mơ kỳ lạ, trong mơ bạn trở thành một kỵ sĩ...",
      [74905840276992] = "Một rương báu bị sức mạnh quỷ dị xâm thực đang chờ được tịnh hóa.",
      [74905840277504] = "Cầm đồng hồ bỏ túi xuyên qua những trang hư-thực của tửu quán, hoàn tất nghi thức tịnh hóa còn dang dở.",
      [83769847450880] = "Ánh sáng chính là ý nghĩa của tất cả.",
      [83769847451136] = "Kẻ Khờ không thuộc về thời đại này; Chúa Tể Thần Bí trên Sương Xám; Vị Vua Hoàng-Đen nắm giữ vận may.",
      [83769847451392] = "Luôn có những điều cao hơn tất cả những điều khác.",
      [281546917428736] = "Mọi món quà của vận mệnh đều đã được âm thầm ghi sẵn cái giá.",
      [281546917429248] = "Giải đọc khải thị, luôn giữ lòng kính sợ trước vận mệnh.",
      [281546917429504] = "Kỳ tích chỉ là nhất thời, vận mệnh mới luôn dài lâu.",
      [281546917431040] = "Nhà Ảo Thuật không bao giờ biểu diễn khi chưa chuẩn bị.",
      [646721411483136] = "Ánh nhìn từ tinh không đổ xuống; đại địa sẽ vỡ làm bốn, vạn vật trên đời đều không còn tồn tại.",
      [646721411483392] = "Mẹ Của Ẩn Bí, Nữ Hoàng Tai Ách Và Kinh Hoàng, Chúa Tể An Miên Và Tĩnh Lặng.",
      [646721411483904] = "Nữ Thần Đêm Tối, cao cả hơn tinh không, lâu đời hơn vĩnh hằng.",
      [646721411484160] = "Cảm tạ Ngài, Nguồn Suối Sự Sống! Tán tụng Ngài, Mẹ Của Vạn Vật!",
      [646721411484416] = "Vua Của Bầu Trời, Hoàng Đế Của Biển Cả. Chúa Tể Thiên Tai, Thần Của Bão Tố!",
      [646721411484672] = "Mọi người đều sẽ chết, kể cả tôi.",
      [646721411484928] = "Đây là thời đại tốt đẹp nhất, cũng là thời đại tồi tệ nhất.",
      [646721411485184] = "Mỗi chuyến hành trình đều có điểm cuối.",
      [646721411485440] = "Một ân tứ, hoặc một lời nguyền.",
      [646721411485696] = "Người sắp chết đuối nào cũng sẽ vùng vẫy.",
      [646721411486208] = "Vạn vật đều có Thần Tính.",
      [646721411486464] = "Giáo Hội Đại Địa Mẫu Thần cho rằng mỗi sinh mệnh đều là một “thực vật”.",
      [646721411486720] = "Vương quốc Loen là cường quốc ở phía đông Bắc Đại Lục, thủ đô là Backlund.",
      [646721411486976] = "Vương quốc Loen chủ yếu tín ngưỡng Nữ Thần Đêm Tối, Chúa Tể Bão Tố và Đại Địa Mẫu Thần.",
      [646721411487232] = "Vương quốc Loen do gia tộc Augustus thống trị.",
      [646721411487488] = "Vương quốc Loen có kỳ thi thống nhất dành cho công chức chính phủ.",
      [646721411487744] = "Vương quốc Loen là quốc gia có quân lực mạnh nhất Nam-Bắc Đại Lục.",
      [646721411488000] = "Trong game có hai loại tiền tệ: Bảng và Soli.",
      [646721411488256] = "Ngành khí cầu đã phát triển nhiều năm, dùng cho cả quân sự lẫn dân sự.",
      [646721411488512] = "Giáo Hội Bão Tố bài xích Mặt Trời Vĩnh Hằng và Thần Tri Thức Và Trí Tuệ.",
      [646721411488768] = "Tín đồ Chúa Tể Bão Tố cho rằng con gái chỉ nên được giáo dục tại gia.",
      [646721411489024] = "Klein tốt nghiệp khoa Lịch Sử, Đại học Khoy.",
      [646721411489280] = "Con người muốn trở thành Phi Phàm Giả thường phải uống ma dược.",
      [646721411489536] = "Tên ma dược bắt nguồn từ “Phiến Đá Báng Bổ”.",
      [646721411489792] = "Trong “Kỷ Nguyên Hắc Ám”, loài người là phụ thuộc của Cự Nhân, Tinh Linh và Huyết Tộc.",
      [646721411490048] = "Trong “Kỷ Nguyên Chư Thần”, thần linh thường xuyên hiển hiện thần tích.",
      [646721411490304] = "Ngày nay, các thần không còn xuất hiện bằng hình tượng cụ thể mà dùng biểu tượng thay cho bản thân.",
      [646721411490560] = "Roselle Gustav phát minh máy hơi nước và cải tiến thuyền buồm.",
      [646721411490816] = "Roselle Gustav từng lật đổ sự thống trị của gia tộc Sauron đối với Vương quốc Intis.",
      [646721411491072] = "Roselle Gustav từng là Chấp Chính Quan đầu tiên của Cộng hòa Intis.",
      [646721411491328] = "Roselle từng chinh chiến bốn phương, biến Cộng hòa Intis thành đế quốc lần nữa và tự xưng “Caesar Đại Đế”.",
      [646721411491584] = "Trong thời Roselle cai trị, “Thần Thợ Thủ Công” đổi tên thành “Thần Hơi Nước Và Máy Móc”.",
      [646721411491840] = "Con Đường Kẻ Dòm Ngó Bí Ẩn: Làm điều mình muốn, nhưng đừng gây tổn hại.",
      [646721411492096] = "Con Đường Thầy Bói: Giải đọc khải thị, kính sợ vận mệnh.",
      [646721411492352] = "Con Đường Khán Giả: Hễ có lời nói, ắt sẽ bị biết.",
      [646721411492608] = "Con Đường Ca Tụng Giả: Lấy thân ta, tắm trong Liệt Dương.",
      [646721411492864] = "Con Đường Học Đồ: Ta đến, ta thấy, ta ghi lại.",
      [646721411493120] = "Con Đường Chiến Sĩ: Bình minh che lấp mọi ô uế.",
      [646721411493376] = "Đặt lọc hiệu ứng thành “Chỉ Hiện Kẻ Địch” để dễ nhìn phạm vi kỹ năng của địch hơn.",
      [646721411493632] = "Có thể đặt ưu tiên mục tiêu thành Máu Thấp Nhất để dễ khóa kẻ địch còn ít Máu.",
      [646721411493888] = "Nhấn nhanh TAB để đổi mục tiêu khóa; giữ TAB để hủy khóa mục tiêu.",
      [646721411494144] = "Roselle Đại Đế: Đợi ta thành cường giả Bậc Cao, gặp một “Thầy Bói” là đánh một!",
      [646721411494400] = "Roselle Đại Đế: Mùi vị Ma Nữ thật không tệ!",
      [646721411494656] = "Dù không có ý nghĩa, vẫn có những việc phải làm.",
      [646721411495168] = "Dùng Linh Thị có thể phát hiện vật phẩm đặc biệt gần đó.",
      [646721411495424] = "Vật Dị Tượng thu thập khắp bản đồ có thể đem đến Leonard tại Câu Lạc Bộ để đổi thưởng.",
      [646721411495680] = "Trong Chế Độ Máy, có thể dùng vòng điều khiển để chỉnh chế độ chiến đấu của bot.",
      [646721411495936] = "Chiến Sĩ có thể chuyển giữa hai hình thái: Sát Thương và Phòng Thủ.",
      [646721411496192] = "Khán Giả có thể chuyển giữa hai hình thái: Sát Thương và Trị Liệu.",
      [646721411496448] = "Trang bị Kỹ Năng Nhân Mạch hợp lý có thể tăng đáng kể sức mạnh nhân vật.",
      [646721411496704] = "Sau khi bật Hỗ Trợ Một Nút, khi đang chiến đấu giữ nút Đánh Thường để tự động tung kỹ năng.",
      [646721411496960] = "Kích hoạt Thiên Phú có thể tăng đáng kể năng lực chiến đấu.",
      [646721411497216] = "Lưu bộ Kỹ Năng, Vật Phong Ấn và Thiên Phú thành phương án trang bị để chuyển nhanh.",
      [646721411497728] = "Đừng ném Bí Ngẫu lung tung, sẽ bị truy dấu.",
      [646721411497984] = "Người Khiển Rối nên cố gắng ẩn mình sau màn.",
      [646721411498240] = "Bạn có thể ngụy trang thành bất kỳ ai, nhưng chỉ có thể là chính mình.",
      [646721411498752] = "Tán tụng Kẻ Khờ!",
      [646721411499264] = "Thân là nhà tù của tâm, thế giới là nhà tù của thân.",
      [646721411499776] = "Tingen nằm ở phía bắc Vương quốc Loen, thuộc quận Ahowa.",
      [646721411500032] = "Tingen được mệnh danh “Thành Phố Đại Học”; Đại học Tingen và Đại học Khoy đều là trường danh tiếng của Loen.",
      [646721411500288] = "Nhà Thờ Saint Selena nằm ở Bắc Khu, là nhà thờ chính của Giáo Hội Đêm Tối tại Tingen.",
      [646721411500544] = "Nhà Thờ Sông Và Biển nằm ở Bắc Khu, thuộc Giáo Hội Chúa Tể Bão Tố.",
      [646721411500800] = "Đại học Khoy là trường cũ của Klein Moretti, cũng là nơi Azik Eggers giảng dạy.",
      [646721411501056] = "Klein Moretti từng được giảng viên giới thiệu đến Đại học Tingen phỏng vấn vị trí giảng sư.",
      [646721411501312] = "Viện Tế Bần Tây Khu được cải tạo từ một nhà thờ cũ; mỗi ngày đều có rất nhiều người xếp hàng.",
      [646721411501568] = "Câu Lạc Bộ Bói Toán nằm ở tầng hai, số 13 phố Howes.",
      [646721411501824] = "Câu Lạc Bộ Bắn Súng Tingen nằm trên phố Zouteland; có một khu vực dành riêng cho Kẻ Gác Đêm.",
      [646721411502080] = "Hãy theo dõi “Báo Người Thật Thà Tingen”, “Tingen Morning Post”, “Ahowa Evening News” và “Tingen Daily”.",
      [646721411502336] = "Tiệm Bánh Slim không chỉ có Bánh Tingen và Bánh Chanh ngon, mà còn phục vụ trà đá ngọt tự làm.",
      [646721411502592] = "Phố Chữ Thập Sắt bán nhiều món bình dân như cá áp chảo, súp hàu, bánh pancake nhỏ, súp lươn và bia gừng.",
      [646721411502848] = "Nhà Hàng Silver Crown nằm trên phố Daffodil, nghe nói món ăn rất ngon.",
      [646721411503104] = "Nhà Hàng Old Will nằm gần Công Ty An Ninh Blackthorn, phục vụ các món kinh điển như xúc xích, khoai tây nghiền, pudding bò và custard.",
      [646721411503360] = "Nhà Hàng Bonaparte nằm ở khu Howes, chuyên món Intis; chi tiêu trung bình khoảng 1 bảng rưỡi/người.",
      [646721411503616] = "Nhà Hàng Coastline nằm ở khu Golden Indus, chuyên món miền nam và là nhà hàng nổi tiếng thường xuất hiện trên báo.",
      [646721411503872] = "Backlund là thủ đô Vương quốc Loen, được gọi là Thành Phố Của Vạn Đô, Miền Đất Hy Vọng và Thành Phố Bụi.",
      [646721411504128] = "Backlund có hơn năm triệu dân, là thành phố phồn hoa nhất Nam-Bắc Đại Lục.",
      [646721411504384] = "Backlund có nhiều tổ chức bí ẩn, cùng nền công nghiệp và kinh tế hùng mạnh.",
      [646721411504640] = "Sông Tussock chia Backlund thành hai phần, nối với nhau bằng Cầu Backlund.",
      [646721411504896] = "Backlund thường có mưa và sở hữu hệ thống cống ngầm tiên tiến.",
      [646721411505152] = "Công trình biểu tượng của Backlund là “Chuông Trật Tự” và Cung Điện Sodorak.",
      [646721411505408] = "Backlund từng là thủ đô của Đế quốc Liên hiệp Tudor–Trunsoest.",
      [646721411505664] = "Nhiệt độ cao trung bình tháng bảy ở Backlund là 28°C, còn thấp nhất mùa đông khoảng 2°C.",
      [646721411505920] = "Sau Đại Thảm Họa Sương Mù Backlund, vương quốc bắt đầu xử lý ô nhiễm không khí và nay đã cải thiện rõ rệt.",
      [646721411506176] = "Xe điện đường sắt chạy xuyên khu đô thị Backlund.",
      [646721411506432] = "Gần sáu vạn người đã chết vì Đại Thảm Họa Sương Mù Backlund, gồm cả trẻ nhỏ và thanh niên khỏe mạnh.",
      [646721411506688] = "Hồ Kim Thu là miền điền viên yên bình, quanh năm ở trong mùa thu hoạch dễ chịu.",
      [646721411506944] = "Hồ Kim Thu có lịch sử lâu đời, thường thu hút thợ săn tiền thưởng và nhà khảo cổ.",
      [646721411507200] = "Người Hồ Kim Thu yêu hòa bình, cần cù chất phác và không chủ động khám phá những điều thần bí xung quanh.",
      [646721411507456] = "Một tuyến đường sắt chạy từ tây sang đông xuyên Hồ Kim Thu, nối thẳng Tingen với Backlund.",
      [646721411507712] = "Trong Chiến Tranh Bội Thệ Kỷ Nguyên thứ năm, nơi đây từng xảy ra xung đột giữa hai giáo hội, dẫn tới tai họa hoang hóa.",
      [646721411507968] = "Hồ Kim Thu bị ô nhiễm đã gặp khủng hoảng mùa màng và động vật dị biến.",
      [646721411508224] = "Cự Quy Ách Thủy sống dưới đáy hồ; sau khi bị ô nhiễm trở nên hung bạo bất thường.",
      [646721411508480] = "Ở đây thậm chí có thể gặp Khỉ Đầu Chó Lông Xoăn biết nhảy múa.",
      [646721411508736] = "Luyện kim sinh mệnh của Con Đường Người Canh Tác có thể ban tuổi thọ dài lâu, nhưng không giúp người ta thấu hiểu sinh tử.",
      [646721411508992] = "Cây Phong Nhiêu vốn là Vật Phong Ấn của Giáo Hội Đại Địa Mẫu Thần; từ sau Chiến Tranh Bội Thệ vẫn luôn tồn tại tại đây.",
      [646721411509248] = "Hornacis... Flegrea... Hornacis... Flegrea...",
      [646721411509504] = "Đỉnh chính Hornacis từng cao hơn sáu nghìn mét, rồi một ngày sụp đổ.",
      [646721411509760] = "Dãy Hornacis từng ẩn giấu một dạng Sinh Vật Thần Thoại mất kiểm soát.",
      [646721411510016] = "Từng có một tồn tại cấp cao vượt biển, lập nên một quốc gia bí ẩn tại đây: Vương Quốc Đêm Tối.",
      [646721411510272] = "Tương truyền nơi đây cất giấu kho báu bí mật có thể phục hưng gia tộc Antigonus.",
      [646721411510528] = "“Vương Quốc Đêm Tối” do hậu duệ Cổ Thần lập nên, nay đã bị hủy diệt.",
      [646721411510784] = "Nền văn minh nơi đây vừa tôn kính vừa sợ hãi màn đêm.",
      [646721411511040] = "Trên đỉnh chính từng có dấu vết con người sinh sống; một ngày nọ, toàn bộ cư dân nơi đây bỗng biến mất.",
      [646721411511296] = "Đây là biên giới giữa Vương quốc Loen và Vương quốc Intis.",
      [646721411511552] = "Trong sâu thẳm dãy núi từng có một Thành Phố Người Chết cùng tồn tại với quốc độ của người sống.",
      [646721411511808] = "Chân dung Nam tước Lamud đời đầu được phát hiện tại đây.",
      [646721411512064] = "Cổ bảo này thuộc về lãnh chúa cai trị thị trấn Lamud vào cuối Kỷ Nguyên thứ tư.",
      [646721411512320] = "Cổ Bảo Lamud nằm trên ngọn đồi cỏ dại um tùm, xung quanh đầy bụi rậm.",
      [646721411512576] = "Nơi đây có nhà trọ và nhà thờ; phần lớn cư dân tín ngưỡng Nữ Thần Đêm Tối.",
      [646721411512832] = "Ngày nay, tường ngoài Cổ Bảo Lamud đã sụp đổ, cây xanh quấn kín.",
      [646721411513088] = "Kết cấu chính của cổ bảo vẫn giữ nét kiến trúc cuối Kỷ Nguyên thứ tư đến đầu Kỷ Nguyên thứ năm.",
      [646721411513344] = "Đại sảnh cổ bảo cao rộng nhưng thiếu sáng; cửa sổ nhỏ và cao, cột đá đỡ mái vòm, lối vào tầng hầm kín đáo.",
      [646721411513600] = "Trong tầng hầm cổ bảo chôn hậu duệ của một vị thần — cũng là con của Azik Eggers.",
      [646721411513856] = "Vì linh hồn bị chia cắt, Azik Eggers rơi vào vòng luân hồi chết và sống lại.",
      [646721411514112] = "Mỗi lần tỉnh dậy, Azik Eggers đều mất ký ức; theo thời gian ký ức dần trở lại, rồi ông lại chết một lần nữa.",
      [646721411514368] = "Azik Eggers là Chấp Chính Quan Tử Vong của Đế quốc Balam Kỷ Nguyên thứ tư, hiện là Thiên Sứ Bậc 2 của Con Đường Tử Thần.",
      [646721411514624] = "Trong thời gian Azik ngủ say, Klein vẫn luôn viết thư cho ông.",
      [646721411514880] = "Giờ đây, sau khi tỉnh lại, Azik bắt đầu du hành tìm kiếm quá khứ và cũng viết thư hồi âm cho Klein.",
      [646721411515136] = "Trước khi đêm xuống, mọi người sẽ trở về nhà. Nếu còn ở ngoài lúc này, rất có thể gặp sự kiện linh dị.",
      [646721411515392] = "Mỗi tháng năm, trang viên trồng đầy táo luôn ngập hương hoa.",
      [646721411515648] = "Gia đình Tử tước mở cửa trang viên vào mỗi tháng năm, mời cư dân trong lãnh địa cùng thưởng hương hoa.",
      [646721411515904] = "Một ngày nọ, sự trả thù từ giới quý tộc phá hủy tất cả; chỉ còn tiểu thư Helena sống sót.",
      [646721411516160] = "Tiểu Thư Bùn Đất và Tử Tước Gạch là trời sinh một đôi; họ xây mái nhà mới, Trang Viên Tháng Năm mới.",
      [646721411516416] = "Chủ nhân Bộ Giáp Tổ Tiên, Baldwin Wetherell, từng tham gia Chiến Tranh Bội Thệ và được ban vô số phần thưởng sau khi khải hoàn.",
      [646721411516672] = "Quản gia trung thành sẽ mãi bảo vệ gia tộc Wetherell, dù phải dùng tri thức hay cả sinh mệnh.",
      [646721411516928] = "Từ sâu trong trang viên vọng ra tiếng tim đập; những kẻ bảo vệ đỏ thẫm quỷ dị lang thang dưới tán cây.",
      [646721411517184] = "Cô bé mồ côi mù đưa quả táo cho người bạn đang bệnh nặng: Đừng sợ, trò chơi tiếp theo sắp bắt đầu rồi.",
      [646721411517440] = "Bệnh di truyền của gia tộc đã cướp chồng của phu nhân Tử tước, và rồi sẽ cướp cả đứa con của bà.",
      [646721411517696] = "Dưới trò đùa của vận mệnh, bóng đỏ như máu dần bao phủ Trang Viên Tháng Năm.",
      [646721411517952] = "Trang Viên Tháng Năm có chó dữ, xin đừng chạm vào; khi cần có thể cho chúng ăn táo.",
      [646721411518208] = "Gia sư tên Ted được mời tới trang viên, nhưng lại tuyên bố có cách chữa cho tiểu Tử tước.",
      [646721411518464] = "Thời gian đông cứng tại đây, thế giới vĩnh viễn chìm trong hoàng hôn. Chào mừng đến Vương Đình Cự Nhân!",
      [646721411518720] = "Trong tộc Cự Nhân, “kẻ phản bội” đồng nghĩa với Soniathrym.",
      [646721411518976] = "Hàng nghìn năm trôi qua, các Cự Nhân vẫn luôn tìm quê hương. Con đường này sẽ không dừng lại nếu chưa tới đích.",
      [646721411519232] = "Người Feysac chảy trong mình huyết mạch Cự Nhân và thường mơ thấy Vương Đình Cự Nhân.",
      [646721411519488] = "Đỉnh núi cao vút, tường thành khổng lồ, cung điện mãi tắm trong ánh hoàng hôn — đó chính là Vương Đình Cự Nhân.",
      [646721411519744] = "Nữ Vương Thần Bí Bernadette nói rằng “Chiến Thần” là một Cự Nhân sống sót từ thời đại cổ xưa.",
      [646721411520000] = "Mirgongen, danh hiệu “Kẻ Đồ Sát Ánh Sáng”, thủ lĩnh các Thợ Săn của Vương Đình, về sau đi theo Thiên Sứ Bóng Tối Sasrir.",
      [646721411520256] = "Sau khi Sasrir ngủ say, Mirgongen vẫn luôn bảo vệ Vương Đình Cự Nhân.",
      [646721411520512] = "Thành Bạch Ngân bắt nguồn từ Quốc Gia Bạch Ngân dưới quyền Vương Đình Cự Nhân, tín ngưỡng Nữ Vương Cự Nhân “Nữ Thần Thu Hoạch” Omebella.",
      [646721411520768] = "“Ta không phản bội Thành Bạch Ngân...” Lời nói năm xưa tan biến trong ánh hoàng hôn.",
      [646721411521024] = "Hoa Hồng Cứu Rỗi là tổ chức bí ẩn ra đời ở Kỷ Nguyên thứ ba; Thiên Sứ Chiến Tranh và Thiên Sứ Vận Mệnh từng là thành viên.",
      [646721411521280] = "Mục đích ban đầu của Hoa Hồng Cứu Rỗi là cứu rỗi Ngài bằng cách ám sát Ngài.",
      [646721411521536] = "Thân xác “Thiên Sứ Bóng Tối” Sasrir ngủ say tại Vương Đình Cự Nhân và đã bị Biển Hỗn Độn xâm thực.",
      [646721411521792] = "Thần để lại lời nguyền: mọi người sắp chết đều sẽ biến thành Ác Linh, trừ khi được chính tay người thân kết liễu.",
      [646721411522048] = "Bóng tối kéo dài suốt hai nghìn năm, cho đến khi Kẻ Khờ vĩ đại đáp lại lời cầu nguyện của cư dân Thành Bạch Ngân.",
      [646721411522304] = "“Thiên Sứ Vận Mệnh” Ouroboros là Vua Thiên Sứ của Con Đường Vận Mệnh, người đi theo Viễn Cổ Thái Dương Thần.",
      [646721411522560] = "Ma Lang U Ám rất giỏi ẩn nấp, tinh thông cách sinh tồn của Con Đường Thầy Bói — cho đến khi Ngài gặp Kẻ Khờ.",
      [646721411522816] = "Bầu trời nơi đây không có mặt trời, chỉ có bóng tối bất biến và sấm chớp xé nát mọi thứ.",
      [646721411523072] = "Thánh địa nơi Viễn Cổ Thái Dương Thần thức tỉnh còn có một tên khác là _______.",
      [646721411523328] = "Vùng Đất Bị Thần Ruồng Bỏ hình thành sau khi Viễn Cổ Thái Dương Thần ngã xuống, là vùng đất bị bóng tối bao phủ.",
      [646721411523584] = "Bút Ký Gia Tộc Antigonus từng do Mật Tu Hội nắm giữ, sau đó thất lạc vì một sự cố.",
      [646721411523840] = "Gia tộc Antigonus từng có địa vị hiển hách trong Đế quốc Solomon Kỷ Nguyên thứ tư, nhưng đoạn lịch sử ấy bị sương mù che phủ...",
      [646721411524096] = "Khi gặp hậu duệ gia tộc Antigonus, Vật Phong Ấn “2-049” sẽ trở nên cực kỳ kích động và năng lực tăng rõ rệt.",
      [646721411524352] = "Ryle Bieber là thợ kim hoàn ở Tingen, lương tuần khoảng 1 bảng 15 Soli.",
      [646721411524608] = "Vật Phong Ấn “2-049” khiến người xung quanh trở nên chậm chạp. Hãy để ý động tác đồng đội và giải cứu kịp thời!",
      [646721411524864] = "Mỗi lần Mật Tu Hội xuất hiện đều là để truy tìm di vật của gia tộc Antigonus.",
      [646721411525120] = "Vật Phong Ấn Cấp “2”: nguy hiểm, phải sử dụng thận trọng và có tiết chế...",
      [646721411525376] = "Hộp sắt chứa Vật Phong Ấn cần được truyền Linh Tính để kích hoạt.",
      [646721411525632] = "Phi Phàm Giả Con Đường Kẻ Không Ngủ cần ngâm xướng thi ca để tác động sinh linh xung quanh.",
      [646721411525888] = "Nơi đây nằm dưới chân Hornacis, có một biển hoa đẹp nở quanh năm.",
      [646721411526144] = "Đây là thắng cảnh được những người đang yêu yêu thích nhất.",
      [646721411526400] = "Nhìn thảo nguyên này từ trên cao, có thể thấy con đường hình trái tim.",
      [646721411526656] = "Nơi đây từng là chốn định tình của một đôi vua và hoàng hậu trong lịch sử Loen.",
      [646721411526912] = "Khi đài phun nước trên bản đồ Núi Tuyết phun trào, có thể nhặt quà rơi trên mặt đất để hồi Máu.",
      [646721411527168] = "Mỗi ván Tranh Phong Chúa Tể được dùng hai lần dược hồi phục đặc biệt.",
      [646721411527424] = "Trong Tranh Phong Chúa Tể, sức mạnh Phi Phàm Giả đã được cân bằng, rất công bằng.",
      [646721411527680] = "Nếu tập trung hỏa lực vẫn khó hạ địch, hãy bảo vệ đồng đội, hóa giải áp lực và thắng bằng tổng sát thương cũng là một cách tốt.",
      [646721411527936] = "Khi Tranh Phong Chúa Tể đạt phút thứ nhất và phút thứ hai, Tấn Công sẽ tăng; hãy tận dụng hiệu ứng này để kết thúc trận.",
      [646721411528192] = "Trên bản đồ Núi Tuyết, Phi Phàm Giả đến gần đài phun đang phun sẽ bị Hất Tung.",
      [646721411528448] = "Đầu Chiến Thế Lực, chiến thuật quan trọng nhất là chiếm và bảo vệ Bia Chiến Tranh của phe mình.",
      [646721411528704] = "Khi thấy mình đơn độc, hãy mở Bản Đồ tìm vị trí thành viên cùng phe.",
      [646721411528960] = "Đi tàu hơi nước giúp đến tiền tuyến nhanh hơn.",
      [646721411529216] = "Chiến Tranh Tứ Hoàng là cuộc chiến Kỷ Nguyên thứ tư làm thay đổi cục diện thế giới; các thần trực tiếp tham chiến.",
      [646721411529472] = "Tứ Hoàng gồm Hắc Hoàng Đế của Đế quốc Solomon, Huyết Hoàng Đế của Triều Tudor, Dạ Hoàng của Đế quốc Trunsoest và Minh Hoàng của Nam Đại Lục.",
      [646721411529728] = "Trong Tranh Đoạt Thần Tọa, mỗi đội có 2 cơ hội hồi sinh đồng đội đã chết.",
      [646721411529984] = "Trong Tranh Đoạt Thần Tọa, mọi Phi Phàm Giả chiến đấu bằng thuộc tính thật giống bên ngoài trận.",
      [646721411530240] = "Đội hình gồm các Con Đường khác nhau cần chiến thuật khác nhau; ví dụ Học Đồ Con Đường “Cánh Cửa” thích hợp lao vào tuyến sau hơn.",
      [646721411530496] = "Ma Nữ Mê Hoặc lấy sinh sôi làm mồi nhử, dụ vạn vật trở về nhịp thai động vĩnh hằng.",
      [646721411530752] = "Nghe nói mỗi thành phố đều lưu hồ sơ về sự kiện Phi Phàm Giả mất kiểm soát, và những hồ sơ này hiếm khi được công khai.",
      [646721411531264] = "Gần đây, một đoạn cống ngầm bỏ hoang ở Tingen thường phát ra âm thanh khiến người ta sởn tóc gáy...",
      [646721411531520] = "Nghe nói Tri Thức Cấm Kỵ mà Carl Edgar nhìn trộm được có thể nô dịch và điều khiển tâm trí sinh vật khác.",
      [646721411531776] = "Nếu thấy một con mắt đỏ điên cuồng đang nhìn chằm chằm vào bạn... hãy cực kỳ cẩn thận!",
      [646721411532032] = "Carl Edgar mê sưu tầm búp bê...",
      [646721411532288] = "Trước khi vòng loại trực tiếp Đỉnh Chư Thần bắt đầu, có thể bỏ phiếu cho đội mình yêu thích.",
      [646721411532544] = "Khi trận Đỉnh Chư Thần kéo dài quá một thời gian nhất định, Tấn Công sẽ tăng.",
      [646721411532800] = "Chào mừng đến Đỉnh Chư Thần. Dưới ánh nhìn của chư thần, bạn sẽ tuốt vũ khí, tranh đoạt vinh quang và chứng kiến sức mạnh.",
      [646721411533056] = "Trong khu Săn Giết Tận Cùng, thành viên cùng Đội, Đoàn Đội và Câu Lạc Bộ được bảo hộ chiến đấu; Liên Minh Đoàn Đội không được bảo hộ!",
      [646721411533312] = "Quản Gia Săn Giết xuất hiện ngẫu nhiên mỗi nửa giờ. Khi chiến sự ác liệt, một Quản Gia Săn Giết thứ hai cũng sẽ xuất hiện!",
      [646721411533568] = "Sự kiện 【Thời Khắc Săn Giết】 mở giới hạn mỗi ngày từ 19h–20h; cuối tuần mở thêm 14h–15h.",
      [646721411533824] = "Khi mang Di Vật Tinh Hồng, bạn có thể đã trở thành mục tiêu của thợ săn khác. Mau tìm Quản Gia Săn Giết để nộp!",
      [646721411534080] = "Trong sự kiện 【Thời Khắc Săn Giết】, khu trung tâm Vương Thành sẽ mở triệu hồi Nhân Ngẫu Vận Mệnh.",
      [646721411534336] = "Trong sự kiện 【Thời Khắc Săn Giết】, đánh bại Vệ Binh trong Vương Thành để nhận nhiều vật liệu Di Vật Tinh Hồng!",
      [646721411534592] = "Trong sự kiện 【Thời Khắc Săn Giết】, rủi ro đi cùng lợi nhuận! Hạ người chơi địch có thể cướp gấp đôi Điểm Thắng Hạng; bị hạ cũng mất tương ứng.",
      [646721411534848] = "Đầu trận hãy tranh điểm trước! Hạ Vệ Binh lần đầu để giành quyền sở hữu và nhận thêm điểm!",
      [646721411535104] = "Hội Trưởng, Phó Hội Trưởng và Lý Sự có thể dùng Kỹ Năng Chỉ Huy để xoay chuyển thế trận!",
      [646721411535360] = "Vệ Binh Ảo Ảnh không thể được trị liệu, nhưng sẽ từ từ hồi Máu khi quanh đó không có người chơi địch.",
      [646721411535616] = "Trong chiến trường Giải Liên Đấu Tứ Phương, khắc chế Con Đường cũng có hiệu lực với Vệ Binh Ảo Ảnh.",
      [646721411535872] = "Sau khi trận bắt đầu, cứ mỗi 4 phút sẽ xuất hiện Vệ Binh hệ số cao để tính điểm; giành quyền sở hữu nhận 4 hoặc 6 lần điểm.",
      [646721411537920] = "Cuộc tấn công của Zaratul ảnh hưởng Thị Trấn Bí Ngẫu; toàn bộ Bí Ngẫu mất kiểm soát đúng vào khoảnh khắc đó.",
      [646721411538176] = "Trong Chế Độ Hai Người, có thể dùng 【Hồi Tưởng Ký Ức】 tại giao diện Mảnh Ký Ức để đưa mảnh ra; người chơi trong Phó Bản có thể nhặt",
      [646721411538432] = "Nhà Hát Utopia là Vật Phong Ấn liên quan tới ký ức của ngài “Kẻ Khờ”; Mẫu Thần đang tìm cách ô nhiễm nó để ảnh hưởng tinh thần của Ngài...",
      [646721411538688] = "Các Bí Ngẫu mất kiểm soát vẫn lưu ký ức khi còn sống; nhặt Mảnh Ký Ức có thể giúp ích cho điều tra.",
      [646721411538944] = "Những hành lang tầng tầng lớp lớp trong nhà hát; mỗi tầng đều tái hiện một phần Thị Trấn Bí Ngẫu.",
      [646721411539200] = "Thử thách cùng bạn đồng hành đã lập thệ ước sẽ nhận thêm buff thuộc tính, số lần hồi sinh, Tinh Túy Bí Ngẫu...",
      [646721411539456] = "Quảng Trường Trung Tâm Tingen, tiền vàng rơi như mưa. Hứng quà, tránh bẫy — cám dỗ của tư bản chưa bao giờ miễn phí.",
      [646721411539712] = "Mỗi ngày phát lương của nhà máy, hóa đơn và đám đòi nợ dưới trướng Locke luôn tới đúng hẹn.",
      [646721411539968] = "Dưới mặt nạ giả nhân giả nghĩa của cán sự từ thiện là vực sâu bóc lột. Giải cứu lao công, chấm dứt ngưỡng hành quyết tại đây.",
      [646721411540224] = "Nghĩa địa khu nghèo đầy những phép thử nhân tính. Trước khi thời gian cạn, kéo vận mệnh sắp bị chặt đứt trở lại.",
      [646721411540480] = "Hóa thân của lòng tham cuối cùng lộ nguyên hình. Dùng tiền vàng phá khiên hắn, dùng khế ước kết thúc cơn điên.",
      [646721411540736] = "Trong di tích ngầm hoang phế, tà giáo đồ vẫn lang thang. Khi bạn bước vào bẫy, người chết đã mở mắt.",
      [646721411540992] = "Thi triều như thác đổ từ núi xuống. Cái chết bám theo như bóng; chỉ có một đường sống.",
      [646721411541248] = "Bộ hài cốt khổng lồ chặn đường, còn phía sau nó là kẻ giật dây thực sự.",
      [646721411541504] = "Tingen lại lâm nguy; Kẻ Gác Đêm sẽ dùng Vật Phong Ấn dựng nên phòng tuyến cuối cùng.",
      [646721411541760] = "Sào huyệt của Abaddon, nguồn gốc vong linh. Kết thúc tất cả, hoặc trở thành một món nữa trong bộ sưu tập của hắn.",
      [646721411542016] = "Một thành phố hơi nước hùng vĩ, một ý tưởng kỳ diệu về việc lên Mặt Trăng, một tàn ảnh tri thức quen thuộc...",
      [646721411542272] = "Roxanne khuyên nhân viên mới của Công Ty An Ninh Blackthorn sớm làm quen với Tingen; Sổ Tay Tân Nhân sẽ giúp ích nhiều.",
      [646721411542528] = "Tên tội phạm truy nã gây vụ cướp đang trốn trong một di tích ngầm đâu đó bên Hồ Kim Thu. Hãy nghênh chiến trận cuối!",
      [646721411543040] = "Khi người chơi cùng một Gia Tộc tham gia Phó Bản, có thể nhận buff thuộc tính và thêm số lần hồi sinh.",
      [646721411545856] = "Mẹo Bàn Cờ Kẻ Khờ 1 (placeholder, chờ bổ sung)",
      [646721411546112] = "Mẹo Bàn Cờ Kẻ Khờ 2 (placeholder, chờ bổ sung)",
      [646721411546368] = "Mẹo Bàn Cờ Kẻ Khờ 3 (placeholder, chờ bổ sung)",
      [646721411546624] = "Mẹo Bàn Cờ Kẻ Khờ 4 (placeholder, chờ bổ sung)",
      [646721411546880] = "Mẹo Bàn Cờ Kẻ Khờ 5 (placeholder, chờ bổ sung)",
      [646721411547136] = "Mẹo Bàn Cờ Kẻ Khờ 6 (placeholder, chờ bổ sung)",
      [646721411547392] = "Mẹo Bàn Cờ Kẻ Khờ 7 (placeholder, chờ bổ sung)",
      [646721411547648] = "Điểm đến của mọi cái chết, địa ngục ẩn sâu trong Linh Giới, chứng nhân vạn vật cuối cùng đều mục nát — quốc độ chỉ thuộc về Tử Thần.",
      [646721411547904] = "Sau khi bạn và ngài Azik cùng ngăn nghi thức hiến tế, kẻ chủ mưu đã chạy vào Minh Giới...",
      [646721411548160] = "Nến Vĩnh Ám vốn do Azik chế tạo, về sau bị kẻ khác lợi dụng thành công cụ thao túng dân làng hiến tế sinh mệnh.",
      [646721411548416] = "Minh Giới là vùng đặc biệt do Tử Thần Viễn Cổ khai mở trong Linh Giới.",
      [646721411548672] = "Màn quỷ kế sắp bắt đầu. Bạn có thể giải được câu đố của tên hề không?",
      [646721411549184] = "Khi cả hai Bia Chinh Phục đều bị bất kỳ phe tấn công nào chiếm, Cổng Chiến Tranh sẽ mở.",
      [646721411549440] = "Phe phòng thủ có thể dịch chuyển tới Hành Lang Chiến Tranh bất cứ lúc nào để giành lại Bia Chinh Phục.",
      [646721411549696] = "Nếu Cờ Chinh Phục bị chiếm, phe tung đòn kết liễu sẽ nhận nhiều Điểm Thần Tuyển hơn.",
      [646721411549952] = "Vua Nhảy mạnh nhất lịch sử VS Vua Nhảy mạnh nhất hiện đại — ai thắng?",
      [646721411550208] = "Một tấm vé ghi kín chữ “cứu mạng” chỉ tới một nhà hát quỷ dị; bạn quyết định vào khám phá...",
      [646721411550464] = "Giải mã ký hiệu, tận dụng quy tắc; mỗi ký hiệu đều chỉ về chân tướng cuối cùng.",
      [646721411550720] = "Có thể vào 【Cài Đặt】-【Hình Ảnh】-【Hiệu Ứng Hình Ảnh】 để chọn ẩn một số bộ phận ngoại hình khi vào Chế Độ Cốt Truyện.",
      [646721411550976] = "Tàn lửa Thần Chiến chưa tắt; chấp niệm của kẻ bị trục xuất vẫn quấn quanh Thánh Tượng Kẻ Khờ.",
      [646721411551744] = "Một cuốn sách da người quỷ dị đang chờ người được chọn tiếp theo.",
      [646721411552256] = "Bạn tìm thấy một căn nhà đầy bí thuật linh dị ở thị trấn Lamud; bên trong lại là hiện trường án mạng...",
      [646721411552512] = "Một cô gái đang chờ, chờ bạn trao lại tâm nguyện cuối cùng cho cô ấy.",
      [646721411552768] = "Ca Tụng Giả Thiên Phú Thánh Ca nên mang Trừng Phạt, Tịnh Trảm, Nhật Thệ và Tịnh Quang khi chiến đấu.",
      [646721411553024] = "Ca Tụng Giả Thiên Phú Thánh Phán nên mang Vô Ám Thương, Tịnh Trảm, Cuồng Phủ và Tịnh Quang khi chiến đấu.",
      [646721411553280] = "Khán Giả Thiên Phú Trấn An nên mang Mộng Giải, Linh Dẫn, Ám Thị và Khiển Thức khi chiến đấu.",
      [646721411553536] = "Khán Giả Thiên Phú Long Uy nên mang Động Sát, Dệt Mộng, Thần Ôn và Chấn Nhiếp khi chiến đấu.",
      [646721411553792] = "Thầy Bói Thiên Phú Vận Mệnh nên mang Phi Bài, Trận Tarot, Mưa Bài và Thần Bài khi chiến đấu.",
      [646721411554048] = "Thầy Bói Thiên Phú Linh Tính nên mang Đạn Khí, Trận Tarot, Mưa Bài và Ngu Phúc khi chiến đấu.",
      [646721411554304] = "Học Đồ Thiên Phú Tập Kích nên mang Thán Vân, Ảo Thuật, Phóng Trục và Không Ngục khi chiến đấu.",
      [646721411554560] = "Học Đồ Thiên Phú Tuần Tinh nên mang Thán Vân, Xuyên Giới, Tinh Định và Biến Ảo khi chiến đấu.",
      [646721411554816] = "Chiến Sĩ Thiên Phú Hoàng Hôn nên mang Liệp Ma Trảm, Quang Trảm, Cuồng Phong và Cự Trảm khi chiến đấu.",
      [646721411555072] = "Chiến Sĩ Thiên Phú Bình Minh nên mang Liệp Ma Trảm, Quang Trảm, Mộ Sắc Trảm và Cự Trảm khi chiến đấu.",
      [646721411555328] = "Kẻ Dòm Ngó Bí Ẩn Thiên Phú Học Giả nên mang Trí Nhân, Quang Khúc, Tinh Sa và Kỳ Nguyệt khi chiến đấu.",
      [646721411555584] = "Kẻ Dòm Ngó Bí Ẩn Thiên Phú Trí Giả nên mang Quang Khúc, Hoàng Y, Khuy Bí Nhãn và Kỳ Nguyệt khi chiến đấu.",
      [695033619583232] = "Một tên hề nào đó ở Tingen gửi lời mời — đây là ván poker lấy mạng làm cược.",
      [695033619583488] = "Những gì mắt thường thấy chưa chắc là chân tướng. Thám tử giỏi biết cách tìm câu trả lời từ người chết.",
      [695033619586304] = "Dục vọng không bao giờ nói dối, canh bạc kéo bạn nhập cuộc. Nhìn thấu chân tướng viên đạn, trở thành kẻ thắng của dục vọng.",
      [695033619586816] = "Trong cơn mơ màng, bạn lặn xuống đáy hồ giữa biển hoa; nơi đây lại ẩn giấu hai thế giới mang tên “Trật Tự” và “Hỗn Loạn”...",
    },
