    ["nocamera"] = {
      [519245976831488] = "…Cô ấy, anh ấy… bọn họ đều… ọe…",
      [519245976831744] = "Nếu em chỉ là một đứa trẻ bình thường, tôi sẽ che mắt em và để em quên hết mọi chuyện.",
      [519245976832000] = "Nhưng đã là Phi Phàm Giả, em phải mở mắt ra và theo kịp tôi.",
      [519245976832256] = "Tôi nguyện moi cả trái tim mình ra, chỉ để đổi lấy một nụ cười khẽ của ngài!",
      [519245976832512] = "Xin để tôi hóa thành bụi trần, mãi mãi theo sau dáng váy của ngài!",
      [519245976832768] = "Xin cho tôi được hôn lên đầu ngón tay ngài; đó sẽ là vinh dự lớn nhất đời tôi!",
      [519245976833024] = "Dẫu phải quỳ rạp dưới đất, tôi cũng nguyện làm một hạt cát dưới chân ngài!",
      [519245976833280] = "Trước mặt ngài, tôi chỉ là một tín đồ hèn mọn, chỉ cầu ngài ban cho chút thương xót!",
      [519245976833536] = "Ngài là mặt trời trong đời tôi; không có ngài, tôi chẳng còn nơi nào để sinh trưởng!",
      [519245976833792] = "Nụ cười của ngài là báu vật quý giá nhất của tôi; tôi nguyện dùng cả sinh mệnh để bảo vệ!",
      [519245976834048] = "Chính ngài đã thắp sáng thế giới của tôi, để tôi mãi sống trong tình yêu cháy bỏng!",
      [519245976834304] = "Tôi nguyện hóa thành một đóa hoa vì ngài, nở rộ trong mỗi sớm mai ngài đi qua!",
      [519245976834560] = "Dù chỉ đứng từ xa, tôi vẫn cảm thấy không khí quanh mình trở nên ấm áp.",
      [519245976834816] = "Bóng dáng ngài luôn khiến tôi bất giác nhìn thêm vài lần, nhưng lại chẳng dám để ánh mắt dừng quá lâu.",
      [519245976835072] = "Đôi khi tôi tự hỏi, ngài có thật sự biết sự hiện diện của mình khiến người ta an tâm đến mức nào không.",
      [519245976835328] = "Chỉ một thoáng dư quang từ nụ cười của ngài cũng đủ để tôi nhớ mãi cả ngày.",
      [519245976835584] = "Sự hiện diện của ngài khiến người ta không dám mơ trèo cao, nhưng lại chẳng thể ngăn lòng kính mộ.",
      [519245976835840] = "Tôi luôn muốn mở lời, nhưng lại sợ phá vỡ vẻ đẹp yên tĩnh này.",
      [519245976836096] = "8! Tôi chọn số 8!",
      [519245976836352] = "Vị trí đầu tiên là 8 — không, con số là 8.",
      [519245976836608] = "Tôi thấy giống 86, còn bạn?",
      [519245976836864] = "89, tôi chọn số 89! Nó nhất định là “trứng may mắn”!",
      [519245976837120] = "Mảnh đất phía đông ấy à? Bá tước Howard ra giá tám nghìn bảng vàng để mua làm khách sạn nghỉ dưỡng mà ông ấy còn không bán!",
      [519245976837376] = "Tặng không cho một lão quản gia? Dạo này Nam tước William bị sao vậy?",
      [519245976837632] = "Đầu tiên là từ chối hợp tác với công ty khai khoáng, giờ lại đem đất tặng… tinh thần ông ấy có vấn đề rồi sao?",
      [519245976837888] = "Nghe nói ông ấy mất ngủ suốt đêm, cả người trông rất không ổn.",
      [519245976838144] = "Đêm nay chúng ta tụ họp tại đây — vì một đêm không thể nào quên, cạn ly!",
    },
