      [285943085007104] = "Kết Toán Trúng Không Headshot",
      [285943085007360] = "Kết Toán Headshot",
      [285943085007616] = "Thay Đạn Súng Lục",
      [285943085008896] = "Thay Đạn Shotgun",
      [285943085010176] = "Thay Đạn Súng Bắn Tỉa",
      [285943353312768] = "Lấy kết quả tính công thức của kỹ năng này:*d Lấy tham số có tên CA của kỹ năng này:*.2f Lấy tham số không tên CA của kỹ năng này:*f** Lấy cấu hình kỹ năng khác trong bảng này:*s Lấy mô tả đại diện pháp thuật:spellagent(*id) Lấy tên kỹ năng:skillname(*id) Lấy mô tả kỹ năng:skilldisc(*id) Lấy tên Buff:buffname(*id) Lấy mô tả Buff:buffdisc(*id) Lấy tên trường pháp thuật:spellfieldname(*id) Lấy mô tả trường pháp thuật:spellfielddisc(*id) Lấy tên hào quang:auraname(*id) Lấy mô tả hào quang:auradisc(*id) Lấy tên bị động:passivename(*id) Lấy mô tả bị động:passivedisc(*id) Lấy tên bẫy:trapname(*id) Lấy mô tả bẫy:trapdisc(*id)",
      [285943353313024] = "Gây Sát Thương A lên mục tiêu khóa và thêm buff; gây Sát Thương B lên mục tiêu trong phạm vi 5m xung quanh.",
      [285943353313536] = "Gây Sát Thương A lên mục tiêu khóa và tạo trường pháp thuật tại vị trí của mục tiêu.",
      [285943353313792] = "【Chế Độ Cần Phải 7】Tấn công kẻ địch trong phạm vi tròn phía trước. Lưu ý: độ lệch và bán kính lọc mục tiêu liên quan đến tham số cảnh báo của Chế Độ Cần Phải.",
      [285943353314048] = "【Chế Độ Cần Phải 4】Tấn công kẻ địch trong phạm vi chữ nhật phía trước. Lưu ý: chiều dài/rộng lọc mục tiêu liên quan đến tham số cảnh báo của Chế Độ Cần Phải.",
      [285943353314304] = "【Chế Độ Cần Phải 3】Lấy bản thân làm tâm, gây hiệu ứng lên vùng hình quạt phía trước; có thể tung kỹ năng liên kích, hoàn tất liên kích sẽ vào hồi chiêu.",
      [285943353314560] = "【Chế Độ Cần Phải 3】Liên kích của kỹ năng Mẫu 7; lấy bản thân làm tâm, gây hiệu ứng lên vùng hình quạt phía trước và Đẩy Lùi.",
      [285943353314816] = "Nếu khoảng cách tới mục tiêu không quá 2000, bắn đạn vào mục tiêu; một số kỹ năng có thể hủy hậu diêu.",
      [285943353315072] = "【Chế Độ Cần Phải 1】Gây nhiều lần sát thương với các hiệu ứng khác nhau lên toàn bộ kẻ địch trong phạm vi chọn.",
      [285943353316608] = "Định Thân vĩnh viễn toàn bộ kẻ địch thường trong phạm vi 40 yard; mỗi tầng chỉ có thể thi triển một lần.",
      [285943353316864] = "Trong chiến đấu, biến thành liệt diễm trong 15 giây; bản thân được Giảm Thương 90% và gây sát thương lớn lên kẻ địch bị thiêu trúng. Trong thời gian này không thể tấn công, nhảy hoặc né tránh.",
      [285943353318144] = "Trong 30 giây, cho phép cưỡi tọa kỵ khi chiến đấu và gây sát thương lên mục tiêu va phải; khi dùng kỹ năng sẽ tự động lên tọa kỵ.",
      [285943353318400] = "Biến thành một sinh vật vô hại, lập tức vào trạng thái giả chết trong 30 giây. Mọi kẻ địch không thể thêm bạn vào danh sách thù hận, nhưng bất kỳ đòn tấn công chủ động nào của bạn cũng sẽ giải trừ trạng thái này.",
      [285943353319680] = "Thực hiện chuỗi 3 nhát chém lên kẻ địch trong phạm vi nhỏ phía trước, lần lượt gây *d, *d+*d và *d điểm Sát Thương Vật Lý, đồng thời <HyperLink stylename=\"M_Link\" u=\"2\">Đẩy Lùi</> nhẹ quái địch; nhát thứ ba trúng sẽ nhận 1 điểm <HighLight>Nhật Năng</>. skilldisc(*id) <FaintYellow>Nhật Năng</>: Tối đa 5 điểm; tích lũy Nhật Năng để mở khóa và cường hóa <HighLight>Trừng Phạt</> và <HighLight>Vô Ám Thương</>.",
      [285943353320448] = "Trong trạng thái <HighLight>Liệt Dương</>, bản thân nhảy tới trước mặt kẻ địch, sau đó toàn lực chém về phía trước, gây 1 lần *d điểm Sát Thương Vật Lý và <HyperLink stylename=\"M_Link\" u=\"2\">Đánh Ngã</> quái địch; khi trúng nhận 1 điểm <HighLight>Nhật Năng</>.",
      [285943353320704] = "Bước tới và chém, gây spellfielddisc(*id) điểm Sát Thương Vật Lý lên mục tiêu và kẻ địch trong phạm vi nhỏ xung quanh, đồng thời <HyperLink stylename=\"M_Link\" u=\"21\">Tịnh Hóa</> kẻ địch đang ở trạng thái tiêu tán; nhận 1 điểm <HighLight>Nhật Năng</> (trong trạng thái <HighLight>Liệt Dương</> nhận 2 điểm <HighLight>Nhật Năng</>). <FaintYellow>Nhật Năng</>: Tối đa 5 điểm; tích lũy Nhật Năng để mở khóa và cường hóa <HighLight>Trừng Phạt</> và <HighLight>Vô Ám Thương</>.",
      [285943353320960] = "Ngưng tụ rìu ngắn, liên tục tấn công kẻ địch xung quanh trong 6 giây; mỗi 0.8 giây gây *d điểm Sát Thương Vật Lý và *f giây mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</>, đồng thời có *f** xác suất cơ bản gây Trì Trệ trong *f giây; Khi thi triển nhận 1 điểm <HighLight>Nhật Năng</> (trong trạng thái <HighLight>Liệt Dương</> nhận 2 điểm <HighLight>Nhật Năng</>), sau đó mỗi 2 lần tấn công nhận 1 điểm <HighLight>Nhật Năng</>. <FaintYellow>Nhật Năng</>: Tối đa 5 điểm; tích lũy Nhật Năng để mở khóa và cường hóa <HighLight>Trừng Phạt</> và <HighLight>Vô Ám Thương</>.",
      [285943353322240] = "Làm Choáng kẻ địch xung quanh.",
      [285943353322496] = "Dựng Nhật Thệ tại vị trí chỉ định trong 8 giây, gây spellfielddisc(*id) điểm Sát Thương Vật Lý và <HyperLink stylename=\"M_Link\" u=\"9\">Trì Trệ</> liên tục lên kẻ địch trong phạm vi; sau đó mỗi 0.5 giây kích hoạt 1 lần <HighLight>Thiêu Nóng</>. Kẻ địch trong phạm vi thệ ước trapdisc(*id) (số lần kích hoạt có giới hạn). Khi thi triển nhận 2 điểm <HighLight>Nhật Năng</> (trong trạng thái <HighLight>Liệt Dương</> nhận 3 điểm <HighLight>Nhật Năng</>); sau đó khi ở trong phạm vi thệ ước, mỗi 2 giây nhận 1 điểm <HighLight>Nhật Năng</>. <FaintYellow>Thiêu Nóng</>: Kẻ địch trong phạm vi thệ ước chịu spellfielddisc(*id) điểm Sát Thương Vật Lý; sát thương <HighLight>Thiêu Nóng</> từ kỹ năng này mà chúng nhận sau đó tăng 15% (tối đa tăng 150%). <FaintYellow>Nhật Năng</>: Tối đa 5 điểm; tích lũy Nhật Năng để mở khóa và cường hóa <HighLight>Trừng Phạt</> và <HighLight>Vô Ám Thương</>.",
      [285943353322752] = "Xông vào kẻ địch chỉ định, liên tục <HyperLink stylename=\"M_Link\" u=\"2\">Đẩy Lùi</> mục tiêu và gây 5 lần *d điểm Sát Thương Vật Lý; hất văng các kẻ địch khác trên đường và gây *d điểm Sát Thương Vật Lý. Sau đó tung đòn kết liễu bằng trường kích, gây *d điểm Sát Thương Vật Lý phạm vi, <HyperLink stylename=\"M_Link\" u=\"2\">Đẩy Lùi</> mục tiêu và thêm *f giây mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</> cùng *f giây <HyperLink stylename=\"M_Link\" u=\"9\">Trì Trệ</>. Trong lúc xông tới, bản thân ở trạng thái <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>. Nếu mục tiêu xông tới đang Bá Thể, bản thân sẽ dừng xông, gây *d điểm Sát Thương Vật Lý và áp dụng hiệu ứng bổ sung của đòn kết liễu. Khi thi triển nhận 1 điểm <HighLight>Nhật Năng</> (trong trạng thái <HighLight>Liệt Dương</> nhận 2 điểm <HighLight>Nhật Năng</>). Kỹ năng này có thể tích 2 lần. <FaintYellow>Nhật Năng</>: Tối đa 5 điểm; tích lũy Nhật Năng để mở khóa và cường hóa <HighLight>Trừng Phạt</> và <HighLight>Vô Ám Thương</>.",
      [285943353324800] = "Nhanh chóng lao tới mục tiêu địch, với *f** xác suất cơ bản <HyperLink stylename=\"M_Link\" u=\"2\">Đánh Ngã</> mục tiêu và kẻ địch trong phạm vi nhỏ xung quanh, gây *d điểm Sát Thương Vật Lý, thêm *f giây mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</> và *f giây <HyperLink stylename=\"M_Link\" u=\"9\">Trì Trệ</>. Trong lúc lao tới, bản thân ở trạng thái <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>. Khi thi triển nhận 1 điểm <HighLight>Nhật Năng</> (trong trạng thái <HighLight>Liệt Dương</> nhận 2 điểm <HighLight>Nhật Năng</>). Kỹ năng này có thể tích 2 lần. <FaintYellow>Nhật Năng</>: Tối đa 5 điểm; tích lũy Nhật Năng để mở khóa và cường hóa <HighLight>Trừng Phạt</> và <HighLight>Vô Ám Thương</>.",
      [285943353325056] = "Chỉ có thể thi triển khi có ít nhất 2 điểm <HighLight>Nhật Năng</>. Tiêu hao toàn bộ <HighLight>Nhật Năng</>, gây *d điểm Sát Thương Vật Lý lên mục tiêu khóa và kích hoạt <HighLight>Vô Ám</>. Trong trạng thái <HighLight>Liệt Dương</> nhận thêm hiệu ứng: mất *f** Máu hiện tại của bản thân, gây lên mục tiêu <HyperLink stylename=\"M_Link\" u=\"15\">Sát Thương Cố Định</> bằng Máu hiện tại của bản thân hoặc Máu đã mất mul(*f**,*f) (lấy giá trị lớn hơn). Ném tiểu thương vào các kẻ địch khác trong 8m đang có hiệu ứng <HighLight>Dị Đoan</>, gây spellfielddisc(*id) điểm Sát Thương Vật Lý và kích hoạt <HighLight>Vô Ám</>. Khi hạ gục người chơi địch, đặt lại hồi chiêu kỹ năng này. <FaintYellow>Vô Ám</>: Khi tiêu hao 3/4/5 điểm Nhật Năng, sát thương cơ bản tăng *d**/mul(*d**,2)/mul(*d**,3). Nếu mục tiêu là người chơi và Máu dưới <HighLight>30%</>, giá trị cơ bản của sát thương lần này tăng <HighLight>15%</> (trong trạng thái <HighLight>Liệt Dương</> tăng <HighLight>30%</>). Nếu sát thương lần này hạ gục người chơi địch, sau một khoảng ngắn sẽ <HyperLink stylename=\"M_Link\" u=\"21\">Tịnh Hóa</> mục tiêu.",
      [285943353325312] = "Chỉ có thể thi triển khi có ít nhất 2 điểm <HighLight>Nhật Năng</>. Tiêu hao toàn bộ <HighLight>Nhật Năng</>, gây *d điểm Sát Thương Vật Lý lên mục tiêu khóa và kích hoạt <HighLight>Vô Ám</>. Trong trạng thái <HighLight>Liệt Dương</> nhận thêm hiệu ứng: mất *f** Máu hiện tại của bản thân, gây lên mục tiêu <HyperLink stylename=\"M_Link\" u=\"15\">Sát Thương Cố Định</> bằng Máu hiện tại của bản thân hoặc Máu đã mất mul(*f**,*f) (lấy giá trị lớn hơn). Ném tiểu thương vào các kẻ địch khác trong 8m đang có hiệu ứng <HighLight>Dị Đoan</>, gây spellfielddisc(*id) điểm Sát Thương Vật Lý và kích hoạt <HighLight>Vô Ám</>. Khi hạ gục người chơi địch, đặt lại hồi chiêu kỹ năng này. <FaintYellow>Vô Ám</>: Khi tiêu hao 3/4/5 điểm Nhật Năng, sát thương cơ bản tăng *d**/mul(*d**,2)/mul(*d**,3). Nếu mục tiêu là người chơi và Máu dưới *d**, giá trị cơ bản của sát thương lần này tăng 15% (trong trạng thái <HighLight>Liệt Dương</> tăng 30%). Nếu sát thương lần này hạ gục người chơi địch, sau một khoảng ngắn sẽ <HyperLink stylename=\"M_Link\" u=\"21\">Tịnh Hóa</> mục tiêu.",
      [285943353325824] = "Triệu hồi Thánh Quang cường hóa bản thân. Khi thi triển lập tức nhận 2 điểm <HighLight>Nhật Năng</> (trong trạng thái <HighLight>Liệt Dương</> lập tức nhận 3 điểm <HighLight>Nhật Năng</>), sau đó mỗi giây nhận 1 điểm <HighLight>Nhật Năng</> trong 5 giây; Tăng Thương - Vật của bản thân tăng *d**, kéo dài *f giây. <FaintYellow>Nhật Năng</>: Tối đa 5 điểm; tích lũy Nhật Năng để mở khóa và cường hóa <HighLight>Trừng Phạt</> và <HighLight>Vô Ám Thương</>.",
      [285943353326336] = "Thánh Diễm bao phủ. Khi thi triển lập tức kích hoạt hiệu ứng hồi <HighLight>Nhật Năng</> sau Tịnh Hóa; gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh, <HyperLink stylename=\"M_Link\" u=\"21\">Tịnh Hóa</> kẻ địch đang ở trạng thái tiêu tán trong phạm vi lớn quanh bản thân, đồng thời khi Tịnh Hóa gây nổ, gây spellfielddisc(*id) điểm Sát Thương Vật Lý lên kẻ địch. <FaintYellow>Nhật Năng</>: Tối đa 5 điểm; tích lũy Nhật Năng để mở khóa và cường hóa <HighLight>Trừng Phạt</> và <HighLight>Vô Ám Thương</>.",
      [285943353327104] = "Nhận 1 điểm <HighLight>Nhật Năng</> (trong trạng thái <HighLight>Liệt Dương</> nhận 2 điểm <HighLight>Nhật Năng</>); trong *f giây, bản thân buffdisc(*id). Trong 16 giây của lần thi triển thứ nhất có thể tung liên chiêu giai đoạn hai, giải trừ <HyperLink stylename=\"M_Link\" u=\"3\">Hiệu Ứng Khống Chế</> đang chịu. <FaintYellow>Nhật Năng</>: Tối đa 5 điểm; tích lũy Nhật Năng để mở khóa và cường hóa <HighLight>Trừng Phạt</> và <HighLight>Vô Ám Thương</>.",
      [285943353328384] = "Chỉ có thể thi triển khi có ít nhất 3 điểm <HighLight>Nhật Năng</>. Tiêu hao 3 điểm <HighLight>Nhật Năng</> (khi vào chiến đấu, nếu không trúng sẽ không tiêu hao năng lượng), gây *d điểm Sát Thương Vật Lý lên kẻ địch phía trước và <HyperLink stylename=\"M_Link\" u=\"2\">Đánh Ngã</> quái địch. Trong trạng thái <HighLight>Liệt Dương</>, kỹ năng nhận thêm hiệu ứng: tăng số mục tiêu tối đa, mở rộng phạm vi tấn công, sát thương cơ bản tăng thành *d điểm; nếu mục tiêu có hiệu ứng <HighLight>Dị Đoan</>, tăng thêm thành *d điểm.",
      [285943353329152] = "Giải trừ <HyperLink stylename=\"M_Link\" u=\"3\">Hiệu Ứng Khống Chế</> đang chịu. Hồi *f** Máu cho bản thân, nhận *f giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</> và trong *f giây buffdisc(*id), đồng thời gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh.",
      [285943353329664] = "Vào trạng thái <HighLight>Liệt Dương</> trong *f giây và nhận *f giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>. Nhận hiệu ứng bị động <HighLight>Liệt Linh</>. <FaintYellow>Liệt Dương</>: Tốc độ di chuyển của bản thân tăng *f**; hiệu suất nhận <HighLight>Nhật Năng</> từ kỹ năng chiến đấu tăng; giảm điều kiện kích hoạt <HighLight>Thẩm Phán (Thẩm Phán Chính Nghĩa)</> và <HighLight>Tài Quyết</>; cường hóa đòn đánh thường <HighLight>Liệt Trảm</>, <HighLight>Vô Ám Thương</> và <HighLight>Trừng Phạt</>. <FaintYellow>Liệt Linh</>: Khi chịu sát thương chí mạng, giữ lại 1 Máu và nhận *f giây <HyperLink stylename=\"M_Link\" u=\"1\">Vô Địch</>, đồng thời giải trừ <HyperLink stylename=\"M_Link\" u=\"3\">Hiệu Ứng Khống Chế</> đang chịu. Trong thời gian này, mỗi 0.25 giây nhận 5 điểm <HighLight>Nhật Năng</>; hồi chiêu <HighLight>Vô Ám Thương</> giảm về 0; nhận thêm *f** Tăng Thương (mỗi thêm 1 kẻ địch, nhận thêm *f** Tăng Thương, tối đa mul(*f**,*d)). Bản thân chịu <HighLight>80%</> <HyperLink stylename=\"M_Link\" u=\"10\">Trọng Thương</>; mỗi khi hạ gục 1 kẻ địch, <HyperLink stylename=\"M_Link\" u=\"16\">Hồi Phục Cố Định</> 20% Máu. <HighLight>Liệt Linh</> có hồi chiêu nội tại *f giây.",
      [285943353330176] = "Tung một loạt tia sáng thuần trắng vào mục tiêu, tổng cộng tấn công 5 lần; sát thương mỗi lần tăng dần. Sát thương này giảm theo số mục tiêu trúng trong phạm vi, tối đa 3 người cùng chia sẻ.",
      [285943353330688] = "Bản thân nhận hiệu ứng <HighLight>Năng Lượng Dâng Trào</>. Khi thi triển <HighLight>Trừng Phạt</> và <HighLight>Vô Ám Thương</>, nhận 1 tầng <HighLight>Thẩm Phán (Thẩm Phán Chính Nghĩa)</>, kéo dài 15 giây, tối đa 3 tầng. Trong trạng thái <HighLight>Liệt Dương</>, đòn đánh thường <HighLight>Liệt Trảm</> và kỹ năng chiến đấu cũng thêm 1 tầng <HighLight>Thẩm Phán</> cho bản thân. <HighLight>Năng Lượng Dâng Trào</>: Hạ gục người chơi địch nhận 5 điểm <HighLight>Nhật Năng</>; Tịnh Hóa người chơi địch nhận 5 điểm <HighLight>Nhật Năng</>; tham gia hỗ trợ hạ gục người chơi địch nhận 1 điểm <HighLight>Nhật Năng</>, tối đa kích hoạt 1 lần mỗi giây. <HighLight>Thẩm Phán</>: Mỗi tầng <HighLight>Thẩm Phán</> làm sát thương của <HighLight>Trừng Phạt</> và <HighLight>Vô Ám Thương</> tăng 5%.",
      [285943353330944] = "Khi <HighLight>Trừng Phạt</> và <HighLight>Vô Ám Thương</> trúng mục tiêu, áp dụng dấu ấn <HighLight>Dị Đoan</> trong 5 giây. Trong trạng thái <HighLight>Liệt Dương</>, đòn đánh thường <HighLight>Liệt Trảm</> và kỹ năng thường khi trúng cũng áp dụng dấu ấn <HighLight>Dị Đoan</>. <HighLight>Dị Đoan</>: Mục tiêu có dấu ấn <HighLight>Dị Đoan</> nhận thêm 10% mọi sát thương từ Ca Tụng Giả.",
      [285943353331200] = "Tán tụng Vĩnh Hằng Liệt Dương vĩ đại, khiến bản thân nhận Mị Lực +1. Trong thời gian này, các Phi Phàm Giả xung quanh có thể nhận kỹ năng tạm thời để cùng tán tụng Liệt Dương; Phi Phàm Giả tham gia cũng nhận Mị Lực +1.",
      [285943353331712] = "Đọc câu cầu nguyện ngắn liên quan đến Mặt Trời để chúc phúc đồng hành, dẫn Thánh Quang tạo thành chùm sáng lơ lửng liên tục, ban Bảo Hộ cho mục tiêu. Mục tiêu nhận Vũ Lực +3, Học Thức +1. Dùng liên tiếp lên cùng một mục tiêu có thể biến chùm sáng trên đầu mục tiêu thành 2 hoặc 3 chùm.",
      [285943353331968] = "Thông qua lời cầu nguyện thành kính, nhận ánh nhìn của thần linh, cầu xin Thánh Quang bao phủ bản thân, Tịnh Hóa ô uế bám vào linh tính và hồi phục hao tổn tinh thần do chiến đấu. Bản thân nhận Học Thức +4, Mị Lực +2.",
      [285943353332224] = "Ban cho đồng đội năng lực <HyperLink stylename=\"M_Link\" u=\"21\">Tịnh Hóa</> trong 6 giây. Trong thời gian này, khi đồng đội hạ gục người chơi địch, sau một khoảng ngắn sẽ <HyperLink stylename=\"M_Link\" u=\"21\">Tịnh Hóa</> mục tiêu; hiệu ứng này tối đa có hiệu lực 3 lần.",
      [285943353332480] = "Khi bật, Khuếch Thương tăng 30% trong 10 giây. Ghi lại tổng sát thương bạn gây lên kẻ địch trong thời gian hiệu ứng; khi kết thúc, gây một lần sát thương lên mục tiêu trong phạm vi bằng 50% tổng sát thương đã ghi.",
      [285943353332992] = "Liên chiêu 3 giai đoạn, phóng năng lượng tinh thần tấn công; mỗi giai đoạn lần lượt gây bulletdisc(*id)/bulletdisc(*id)/bulletdisc(*id) điểm Sát Thương Phép lên kẻ địch. Chỉ dùng được trong <HighLight>Tư Thế Ác Mộng</>; ở <HighLight>Tư Thế Không Tưởng</> sẽ đổi thành <HighLight>An Phủ</>.",
      [285943353333760] = "Liên chiêu 3 giai đoạn, xoa dịu tinh thần đồng minh; mỗi giai đoạn lần lượt hồi *d/*d/*d Máu cho mục tiêu đồng minh. Chỉ dùng được trong <HighLight>Tư Thế Không Tưởng</>; ở <HighLight>Tư Thế Ác Mộng</> sẽ đổi thành <HighLight>Xung Kích Ý Thức</>.",
      [285943353334528] = "Gây spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch trong phạm vi và thêm <HighLight>Tăng Thương</> trong *f giây. <FaintYellow>Tăng Thương</>: buffdisc(*id)5%.",
      [285943353334784] = "Gây *d điểm Sát Thương Phép lên kẻ địch trong phạm vi và thêm <HighLight>Ôn Dịch</> trong *f giây. <FaintYellow>Ôn Dịch</>: buffdisc(*id).",
      [285943353335552] = "Tạo lĩnh vực và lập tức hồi *d Máu cho đồng minh trong phạm vi; lĩnh vực tồn tại 6 giây, đồng minh bên trong mỗi giây hồi *d Máu và buffdisc(*id).",
      [285943353336576] = "Gây spellfielddisc(*id) điểm Sát Thương Phép lên mục tiêu khóa và kẻ địch xung quanh, đồng thời <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</> quái địch đang ở trạng thái <HighLight>Ôn Dịch</>.",
      [285943353337088] = "Bắn đạn trị liệu vào đồng minh, hồi bulletdisc(*id) Máu. Khi trúng mục tiêu, đạn trị liệu nảy sang đồng đội trong tiểu đội hoặc đoàn đội của mục tiêu và hồi Máu cho mục tiêu kế tiếp. Tối đa nảy 3 lần; mỗi lần nảy làm lượng trị liệu của viên đạn giảm 30%.",
      [285943353337344] = "Tạo lĩnh vực, mỗi giây gây spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch trong phạm vi, kéo dài 8 giây. Chỉ dùng được trong <HighLight>Tư Thế Ác Mộng</>; ở <HighLight>Tư Thế Không Tưởng</> sẽ đổi thành <HighLight>Ám Thị</>.",
      [285943353338112] = "Lập tức hồi cho mục tiêu đồng minh lượng Máu bằng *f** Máu tối đa của mục tiêu (không vượt quá *f** Máu tối đa của bản thân), đồng thời khiến mục tiêu buffdisc(*id) trong *f giây. Nếu kỹ năng tạo trị liệu dư, hồi Máu cho thành viên đoàn đội có phần trăm Máu thấp nhất trong phạm vi kỹ năng bằng lượng trị liệu dư (chịu ảnh hưởng Giảm Hồi Phục của mục tiêu). Kỹ năng này có thể tích 2 lần. Chỉ dùng được trong <HighLight>Tư Thế Không Tưởng</>; ở <HighLight>Tư Thế Ác Mộng</> sẽ đổi thành <HighLight>Dệt Mộng</>.",
      [285943353338368] = "Gây spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch phía trước, thêm *f giây mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</> và với *d** xác suất cơ bản thêm buffdisc(*id) trong *f giây. Chỉ dùng được trong <HighLight>Tư Thế Ác Mộng</>; ở <HighLight>Tư Thế Không Tưởng</> sẽ đổi thành <HighLight>Đọc Tâm</>.",
      [285943353338880] = "Vào trạng thái <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</> và buffdisc(*id), liên tục trị liệu đồng minh trong phạm vi xung quanh; mỗi giây hồi spellfielddisc(*id) Máu, kéo dài 6.5 giây. Trong lúc thi triển có thể di chuyển; sau 3 giây có thể dùng kỹ năng khác để ngắt thi triển, sau khi bị ngắt hiệu ứng trị liệu vẫn tiếp tục.",
      [285943353339392] = "Vào trạng thái <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</> và buffdisc(*id), liên tục trị liệu đồng minh xung quanh, mỗi giây hồi spellfielddisc(*id) Máu; đồng thời liên tục tấn công kẻ địch trong phạm vi, mỗi giây gây spellfielddisc(*id) sát thương, kéo dài <Highlight>6.5</> giây.",
      [285943353339648] = "Khiến một thành viên tiểu đội mục tiêu nhận <HighLight>Dấu Ấn Đọc Tâm</> trong *f giây. Mỗi Khán Giả chỉ có thể cho một mục tiêu giữ <HighLight>Dấu Ấn Đọc Tâm</> cùng lúc, và mỗi mục tiêu cùng lúc chỉ có thể nhận <HighLight>Dấu Ấn Đọc Tâm</> của một Khán Giả. Khi khoảng cách giữa người giữ <HighLight>Dấu Ấn Đọc Tâm</> và người thi triển vượt quá 70m, người giữ sẽ mất <HighLight>Dấu Ấn Đọc Tâm</>. Chỉ dùng được trong <HighLight>Tư Thế Không Tưởng</>; ở <HighLight>Tư Thế Ác Mộng</> sẽ đổi thành <HighLight>Cuồng Loạn</>. <FaintYellow>Dấu Ấn Đọc Tâm</>: Khi Máu của người giữ dưới 30%, nhận buffdisc(*id) trong *f giây; hiệu ứng này có hồi chiêu 20 giây. Khi người thi triển dấu ấn dùng kỹ năng chiến đấu tạo hiệu ứng trị liệu, người giữ dấu ấn hồi Máu bằng 30% lượng hiệu ứng (chịu ảnh hưởng Giảm Hồi Phục của mục tiêu).",
      [285943353339904] = "Khiến thành viên tiểu đội trong 25m nhận <HighLight>Dấu Ấn Trị Tâm</> trong *f giây. Khi khoảng cách giữa người giữ <HighLight>Dấu Ấn Trị Tâm</> và người thi triển vượt quá 70m, người giữ sẽ mất <HighLight>Dấu Ấn Trị Tâm</>. Kỹ năng này có hồi chiêu chung tiểu đội 20 giây. Chỉ dùng được trong <HighLight>Tư Thế Không Tưởng</>; ở <HighLight>Tư Thế Ác Mộng</> sẽ đổi thành <HighLight>Cuồng Loạn</>. <FaintYellow>Dấu Ấn Trị Tâm</>: Người giữ nhận *d** Giảm Thương. Khi người thi triển dấu ấn dùng kỹ năng chiến đấu tạo hiệu ứng trị liệu, người giữ dấu ấn hồi Máu bằng 80% lượng hiệu ứng (chịu ảnh hưởng Giảm Hồi Phục của mục tiêu).",
      [285943353340416] = "Có hiệu lực đồng thời lên tối đa 6 mục tiêu trong 6s. Trong thời gian hiệu lực, Phòng Thủ của mục tiêu giảm và mục tiêu chịu sát thương; Định Thân kẻ địch ở trong Dệt Mộng hoặc đang chịu Ôn Dịch Tinh Thần.",
      [285943353340672] = "Giải trừ <HyperLink stylename=\"M_Link\" u=\"3\">Hiệu Ứng Khống Chế</> đang chịu, vào trạng thái <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</> và nhận buffdisc(*id) trong *f giây.",
      [285943353340928] = "Phóng Linh Hoả, với *d** xác suất cơ bản <HyperLink stylename=\"M_Link\" u=\"7\">Trói Buộc</> kẻ địch phía trước trong *f giây và gây spellfielddisc(*id) điểm Sát Thương Phép; sau đó tiến lên phun trào, gây *d điểm Sát Thương Phép lên kẻ địch trong phạm vi lớn và thêm *f giây mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</>. Để lại vùng lửa trong 4 giây, mỗi 0.7 giây gây spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch trong phạm vi. Khi kỹ năng này gây sát thương, có *f** xác suất thêm 1 tầng <HighLight>Dấu Ấn Dẫn Dụ</>, kéo dài *f giây. Chỉ dùng được trong <HighLight>Tư Thế Ác Mộng</>; ở <HighLight>Tư Thế Không Tưởng</> sẽ đổi thành <HighLight>Trị Liệu Tâm Lý</>. <FaintYellow>Dấu Ấn Dẫn Dụ</>: Khi cộng đủ 3 tầng, với <Highlight>100%</> xác suất cơ bản, trong <Highlight>1.5</> giây rơi vào <HyperLink stylename=\"M_Link\" u=\"14\">Thôi Miên</>.",
      [285943353341696] = "Liên tục trị liệu đồng minh trong phạm vi xung quanh; mỗi 1.5 giây hồi *d Máu cho đồng minh trong phạm vi, tối đa 7 lần. Trong lúc kỹ năng có hiệu lực, bản thân có thể di chuyển và dùng kỹ năng khác. Chỉ dùng được trong <HighLight>Tư Thế Không Tưởng</>; ở <HighLight>Tư Thế Ác Mộng</> sẽ đổi thành <HighLight>Linh Hoả</>.",
      [285943353342208] = "Liên tục trị liệu đồng minh trong phạm vi xung quanh; mỗi 1.5 giây hồi *d Máu cho đồng minh, tối đa 7 lần. Trong lúc kỹ năng có hiệu lực, bản thân có thể di chuyển và dùng kỹ năng khác.",
      [285943353342464] = "Giải trừ một phần <HyperLink stylename=\"M_Link\" u=\"3\">Hiệu Ứng Khống Chế đang chịu, tạo lĩnh vực liên tục trị liệu đồng minh trong phạm vi; mỗi giây hồi spellfielddisc(*id) Máu, kéo dài <Highlight>9</> giây.",
      [285943353342720] = "<HighLight>Giai Đoạn 1</>: Khán Giả giải trừ trạng thái khống chế của bản thân, triển khai Hải Dương Tiềm Thức dưới chân để liên tục hồi Máu cho đồng minh trong phạm vi, tối đa 9 giây; đồng đội trong Hải Dương Tiềm Thức nhận hiệu ứng Giảm Thương. <HighLight>Giai Đoạn 2</>: Khán Giả giải tán Hải Dương Tiềm Thức và hồi Máu cho đồng minh trong phạm vi; Hải Dương Tiềm Thức tồn tại càng ngắn thì lượng hồi càng lớn.",
      [285943353343488] = "<HyperLink stylename=\"M_Link\" u=\"22\">Đánh Thức</> đồng đội tiểu đội hoặc đoàn đội đang ở trạng thái tiêu tán, khiến họ phục hồi tại vị trí Khán Giả thi triển và hồi 50% Máu.",
      [285943353344000] = "Khi đang ở trạng thái tiêu tán, có thể <HyperLink stylename=\"M_Link\" u=\"22\">Đánh Thức</> bản thân và hồi 50% Máu.",
      [285943353344256] = "Trong tư thế này, sát thương bản thân gây ra giảm mạnh, nhưng năng lực trị liệu tăng; các thuộc tính tấn công có thể tăng lượng trị liệu của bản thân (mức tăng phụ thuộc loại thuộc tính và hệ số kỹ năng). Trong tư thế này, khi bản thân chịu <HyperLink stylename=\"M_Link\" u=\"3\">Hiệu Ứng Khống Chế</>, buffdisc(*id) trong passivedisc(*id) giây; hiệu ứng này có hồi chiêu nội tại 15 giây.",
      [285943353344512] = "Trong tư thế này, các thuộc tính tấn công ngoài Tấn Công Phép không còn tăng lượng trị liệu, đồng thời lượng trị liệu giảm mạnh. Trong tư thế này, khi bản thân gây sát thương sẽ hồi passivedisc(*id) Máu cho bản thân.",
      [285943353344768] = "Khi Thiêu Đốt từ đòn đánh thường cộng đủ 3 tầng sẽ gây nổ phạm vi và xóa số tầng.",
      [285943353345024] = "Quan sát cảm xúc nội tâm phản ánh qua hành vi, cử chỉ của mục tiêu, ngưng tụ một điểm sáng màu quanh mục tiêu, phản ánh tâm trạng cốt lõi bề mặt của đối phương trong ngày. Mục tiêu nhận Mị Lực +1.",
      [285943353345280] = "Vận dụng Linh Thị, quan sát biểu hiện của Thể Dĩ Thái và Thể Tâm Trí dưới hành vi cử chỉ của mục tiêu; kết hợp phân tích để đọc suy nghĩ tầng nông của đối phương và áp dụng ám thị theo cách hợp lý. Mục tiêu nhận Trực Giác +3, Học Thức +1.",
      [285943353345536] = "Thông qua hành vi đặc định để thể hiện sức ảnh hưởng lên người khác, xoa dịu trạng thái tinh thần cuồng loạn, bất ổn của mục tiêu, giúp họ tránh xa điên cuồng và đạt được sự tĩnh lặng, bình hòa trong tâm trí. Mục tiêu nhận Học Thức +4, Mị Lực +2.",
      [285943353345792] = "Dùng lên một người chơi địch, nhìn thấu nội tâm và gieo <Highlight>Ám Thị</> gây hiểu lầm trong <Highlight>3</> giây. Khi mục tiêu bị ám thị dùng kỹ năng, sát thương họ gây ra sẽ chuyển sang đồng minh của họ; trị liệu họ tạo ra sẽ chuyển sang kẻ địch của họ. Sát thương gây lên đồng minh do Tinh Thần Rối Loạn không thể trực tiếp hạ gục đồng minh.",
      [285943353346048] = "Phóng lá bài tấn công mục tiêu theo chuỗi 4 giai đoạn, lần lượt gây bulletdisc(*id)/bulletdisc(*id)/bulletdisc(*id)/bulletdisc(*id) điểm Sát Thương Vật Lý và <HyperLink stylename=\"M_Link\" u=\"2\">Ngắt</> quái địch. Sau mỗi 4 lần dùng Mở Bài gây sát thương, nhận 1 <HighLight>Thẻ Vàng Vận Mệnh</>; nếu lần trước nhận <HighLight>Thẻ Lam Linh Tính</>, thay vào đó nhận 1 <HighLight>Thẻ Lam Linh Tính</>. <FaintYellow>Thẻ Vàng Vận Mệnh</>/<FaintYellow>Thẻ Lam Linh Tính</>: Khi có 3 <HighLight>Thẻ Vàng Vận Mệnh</>/<HighLight>Thẻ Lam Linh Tính</>, tiêu hao toàn bộ lá bài, khiến <HighLight>Kỹ Năng Kết Liễu-Xào Bài</> chuyển thành <HighLight>Số Mệnh</>/<HighLight>Linh Bạo</>.",
      [285943353347072] = "Tấn công kẻ địch trong vùng hình quạt phía trước theo chuỗi 3 giai đoạn; mỗi giai đoạn gây *d điểm Sát Thương Vật Lý và <HyperLink stylename=\"M_Link\" u=\"2\">Ngắt</> quái địch. Sau giai đoạn đầu, bản thân buffdisc(*id) trong 6 giây. Giai đoạn ba thêm 1 tầng <HighLight>Dấu Ấn Ngu Lộng</> và với *d** xác suất cơ bản <HyperLink stylename=\"M_Link\" u=\"2\">Đẩy Lùi</> kẻ địch, thêm *f giây mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</>, đồng thời bản thân nhận 1 <HighLight>Thẻ Vàng Vận Mệnh</>. <FaintYellow>Thẻ Vàng Vận Mệnh</>/<FaintYellow>Thẻ Lam Linh Tính</>: Khi có 3 <HighLight>Thẻ Vàng Vận Mệnh</>/<HighLight>Thẻ Lam Linh Tính</>, tiêu hao toàn bộ lá bài, khiến <HighLight>Kỹ Năng Kết Liễu-Xào Bài</> chuyển thành <HighLight>Số Mệnh</>/<HighLight>Linh Bạo</>. <FaintYellow>Dấu Ấn Ngu Lộng</>: Khi cộng đủ 3 tầng, kích nổ và xóa dấu ấn; chịu mul(*d,3) điểm Sát Thương Vật Lý do người áp dụng gây ra.",
      [285943353347328] = "Tấn công kẻ địch trong vùng hình quạt phía trước theo chuỗi 3 giai đoạn; mỗi giai đoạn gây *d điểm Sát Thương Vật Lý và <HyperLink stylename=\"M_Link\" u=\"2\">Ngắt</> quái địch. Giai đoạn ba thêm 1 tầng <HighLight>Dấu Ấn Ngu Lộng</> và với *d** xác suất cơ bản <HyperLink stylename=\"M_Link\" u=\"2\">Đẩy Lùi</> kẻ địch, thêm *f giây mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</>, đồng thời bản thân nhận 1 <HighLight>Thẻ Vàng Vận Mệnh</>. <FaintYellow>Thẻ Vàng Vận Mệnh</>/<FaintYellow>Thẻ Lam Linh Tính</>: Khi có 3 <HighLight>Thẻ Vàng Vận Mệnh</>/<HighLight>Thẻ Lam Linh Tính</>, tiêu hao toàn bộ lá bài, khiến <HighLight>Kỹ Năng Kết Liễu-Xào Bài</> chuyển thành <HighLight>Số Mệnh</>/<HighLight>Linh Bạo</>. <FaintYellow>Dấu Ấn Ngu Lộng</>: Khi cộng đủ 3 tầng, kích nổ và xóa dấu ấn; chịu mul(*d,3) điểm Sát Thương Vật Lý do người áp dụng gây ra.",
      [285943353347840] = "Ném bài Tarot vào mục tiêu và triển khai trận bài, gây 4 lần spellfielddisc(*id) điểm Sát Thương Vật Lý lên kẻ địch trong trận và <HyperLink stylename=\"M_Link\" u=\"2\">Ngắt</> quái địch. Sau đó trận bài phát nổ, gây spellfielddisc(*id) điểm Sát Thương Vật Lý và <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</> quái địch trong phạm vi, tối đa <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</> 2 mục tiêu. Sau khi thi triển nhận 1 <HighLight>Thẻ Vàng Vận Mệnh</> và thêm 1 tầng <HighLight>Dấu Ấn Ngu Lộng</> lên kẻ địch trúng vụ nổ; nếu lần trước nhận <HighLight>Thẻ Lam Linh Tính</>, thay vào đó nhận 1 <HighLight>Thẻ Lam Linh Tính</>, đồng thời khi vụ nổ trúng nhận 1 điểm <HighLight>Năng Lượng Lá Bài</>. <FaintYellow>Thẻ Vàng Vận Mệnh</>/<FaintYellow>Thẻ Lam Linh Tính</>: Khi có 3 <HighLight>Thẻ Vàng Vận Mệnh</>/<HighLight>Thẻ Lam Linh Tính</>, tiêu hao toàn bộ lá bài, khiến <HighLight>Kỹ Năng Kết Liễu-Xào Bài</> chuyển thành <HighLight>Số Mệnh</>/<HighLight>Linh Bạo</>. <FaintYellow>Năng Lượng Lá Bài</>: Tối đa 5 điểm; khi đạt 5 điểm, <HighLight>Kỹ Năng Kết Liễu</> chuyển thành và khóa ở <HighLight>Xào Bài</>. <FaintYellow>Dấu Ấn Ngu Lộng</>: Khi cộng đủ 3 tầng, kích nổ và xóa dấu ấn; chịu mul(*d,3) điểm Sát Thương Vật Lý do người áp dụng gây ra.",
      [285943353348352] = "Trong 2.7 giây, liên tục bắn Đạn Khí vào mục tiêu khóa, gây 5 lần bulletdisc(*id) điểm Sát Thương Vật Lý và <HyperLink stylename=\"M_Link\" u=\"2\">Ngắt</> quái địch. Trong lúc thi triển có thể di chuyển; khi bắt đầu thi triển nhận *f giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</> và tăng tốc *d**. Khi kết thúc thi triển, nhận 1 điểm <HighLight>Năng Lượng Lá Bài</> và 1 <HighLight>Thẻ Lam Linh Tính</>. <FaintYellow>Thẻ Vàng Vận Mệnh</>/<FaintYellow>Thẻ Lam Linh Tính</>: Khi có 3 <HighLight>Thẻ Vàng Vận Mệnh</>/<HighLight>Thẻ Lam Linh Tính</>, tiêu hao toàn bộ lá bài, khiến <HighLight>Kỹ Năng Kết Liễu-Xào Bài</> chuyển thành <HighLight>Số Mệnh</>/<HighLight>Linh Bạo</>. <FaintYellow>Năng Lượng Lá Bài</>: Tối đa 5 điểm; khi đạt 5 điểm, <HighLight>Kỹ Năng Kết Liễu</> chuyển thành và khóa ở <HighLight>Xào Bài</>.",
      [285943353348864] = "Gây *d điểm Sát Thương Vật Lý lên mục tiêu địch, đồng thời kèm hiệu ứng <HyperLink stylename=\"M_Link\" u=\"6\">Choáng</> trong *f giây và buffdisc(*id) trong *f giây.",
      [285943353349120] = "Bổ sung <HighLight>Năng Lượng Lá Bài</> của bản thân lên 5 điểm; khi thi triển, mỗi 1 điểm <HighLight>Năng Lượng Lá Bài</> hiện có giảm 5 giây hồi chiêu của kỹ năng này. Nhận 3 <HighLight>Thẻ Vàng Vận Mệnh</>; nếu số <HighLight>Thẻ Lam Linh Tính</> nhiều hơn, thay vào đó nhận 3 <HighLight>Thẻ Lam Linh Tính</>. <FaintYellow>Thẻ Vàng Vận Mệnh</>/<FaintYellow>Thẻ Lam Linh Tính</>: Khi có 3 <HighLight>Thẻ Vàng Vận Mệnh</>/<HighLight>Thẻ Lam Linh Tính</>, tiêu hao toàn bộ lá bài, khiến <HighLight>Kỹ Năng Kết Liễu-Xào Bài</> chuyển thành <HighLight>Số Mệnh</>/<HighLight>Linh Bạo</>. <FaintYellow>Năng Lượng Lá Bài</>: Tối đa 5 điểm; khi đạt 5 điểm, <HighLight>Kỹ Năng Kết Liễu</> chuyển thành và khóa ở <HighLight>Xào Bài</>.",
      [285943353349376] = "buffdisc(*id) trong *f giây, đồng thời nhận 1 điểm <HighLight>Năng Lượng Lá Bài</> và 1 <HighLight>Thẻ Lam Linh Tính</>. <FaintYellow>Thẻ Vàng Vận Mệnh</>/<FaintYellow>Thẻ Lam Linh Tính</>: Khi có 3 <HighLight>Thẻ Vàng Vận Mệnh</>/<HighLight>Thẻ Lam Linh Tính</>, tiêu hao toàn bộ lá bài, khiến <HighLight>Kỹ Năng Kết Liễu-Xào Bài</> chuyển thành <HighLight>Số Mệnh</>/<HighLight>Linh Bạo</>. <FaintYellow>Năng Lượng Lá Bài</>: Tối đa 5 điểm; khi đạt 5 điểm, <HighLight>Kỹ Năng Kết Liễu</> chuyển thành và khóa ở <HighLight>Xào Bài</>.",
      [285943353349632] = "Giải trừ <HyperLink stylename=\"M_Link\" u=\"3\">Hiệu Ứng Khống Chế</> đang chịu, nhận *f giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</> và *f giây <HighLight>Giảm Thương</> 15%; đặt một mốc lửa tại vị trí hiện tại rồi dịch chuyển tức thời đến vị trí mục tiêu. Gây *d điểm Sát Thương Vật Lý trong phạm vi nhỏ quanh vị trí biến mất và vị trí đích. Trong 3 giây sau khi thi triển có thể tung liên chiêu. Khi tung liên chiêu nhận *f giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>, dịch chuyển ngược về vị trí mốc lửa và lại gây *d điểm Sát Thương Vật Lý trong phạm vi nhỏ quanh vị trí biến mất và vị trí mốc lửa.",
      [285943353350144] = "Giải trừ <HyperLink stylename=\"M_Link\" u=\"3\">Hiệu Ứng Khống Chế</> đang chịu và nhận *f giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>; đặt một mốc lửa tại vị trí hiện tại rồi dịch chuyển tức thời đến vị trí mục tiêu. Gây *d điểm Sát Thương Vật Lý trong phạm vi nhỏ quanh vị trí biến mất và vị trí đích. Trong 3 giây sau khi thi triển có thể tung liên chiêu. Khi tung liên chiêu nhận *f giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>, dịch chuyển ngược về vị trí mốc lửa và lại gây *d điểm Sát Thương Vật Lý trong phạm vi nhỏ quanh vị trí biến mất và vị trí mốc lửa.",
      [285943353350400] = "Gây spellfielddisc(*id) điểm Sát Thương Vật Lý lên kẻ địch trong phạm vi và với *f** xác suất cơ bản thêm buffdisc(*id) trong *f giây; đồng thời với *f** xác suất cơ bản <HyperLink stylename=\"M_Link\" u=\"6\">Choáng</> kẻ địch ở tâm phạm vi trong 0.8 giây, tối đa <HyperLink stylename=\"M_Link\" u=\"6\">Choáng</> 2 mục tiêu. Khi trúng người chơi địch, thêm *f giây mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</>. Sau khi thi triển nhận 1 <HighLight>Thẻ Vàng Vận Mệnh</> và thêm 1 tầng <HighLight>Dấu Ấn Ngu Lộng</> lên kẻ địch trúng; nếu lần trước nhận <HighLight>Thẻ Lam Linh Tính</>, thay vào đó nhận 1 <HighLight>Thẻ Lam Linh Tính</>, đồng thời nhận 1 điểm <HighLight>Năng Lượng Lá Bài</>. <FaintYellow>Thẻ Vàng Vận Mệnh</>/<FaintYellow>Thẻ Lam Linh Tính</>: Khi có 3 <HighLight>Thẻ Vàng Vận Mệnh</>/<HighLight>Thẻ Lam Linh Tính</>, tiêu hao toàn bộ lá bài, khiến <HighLight>Kỹ Năng Kết Liễu-Xào Bài</> chuyển thành <HighLight>Số Mệnh</>/<HighLight>Linh Bạo</>. <FaintYellow>Năng Lượng Lá Bài</>: Tối đa 5 điểm; khi đạt 5 điểm, <HighLight>Kỹ Năng Kết Liễu</> chuyển thành và khóa ở <HighLight>Xào Bài</>. <FaintYellow>Dấu Ấn Ngu Lộng</>: Khi cộng đủ 3 tầng, kích nổ và xóa dấu ấn; chịu mul(*d,3) điểm Sát Thương Vật Lý do người áp dụng gây ra.",
      [285943353350912] = "Giải trừ <HyperLink stylename=\"M_Link\" u=\"3\">Hiệu Ứng Khống Chế</> đang chịu, để lại một Thế Thân tại vị trí hiện tại kế thừa dấu khóa mục tiêu của bản thân; đồng thời bản thân nhảy theo hướng cần điều khiển (nếu không nhập hướng, mặc định nhảy về sau nhân vật). Khi dùng nhận *f giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</> và buffdisc(*id) trong *f giây. Thế Thân tự đánh thường kẻ địch 3 lần, lần lượt gây bulletdisc(*id)/bulletdisc(*id)/bulletdisc(*id) điểm Sát Thương Vật Lý, sau đó phát nổ gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh.",
      [285943353351936] = "Thu thập đủ 3 <HighLight>Thẻ Vàng Vận Mệnh</> để mở khóa kỹ năng này. Gây spellfielddisc(*id) điểm Sát Thương Vật Lý lên kẻ địch trong phạm vi, thêm 1 tầng <HighLight>Dấu Ấn Ngu Lộng</> và <HyperLink stylename=\"M_Link\" u=\"2\">Ngắt</> quái địch. Sau đó trong *f giây, đòn đánh thường của bản thân có xác suất passivedisc(*id) thêm 1 tầng <HighLight>Dấu Ấn Ngu Lộng</> lên mục tiêu; bản thân buffdisc(*id). Sau khi thi triển nhận 1 điểm <HighLight>Năng Lượng Lá Bài</>. Khi dùng Số Mệnh sẽ xóa hiệu ứng <HighLight>Tăng Thương</> của Linh Bạo. <FaintYellow>Dấu Ấn Ngu Lộng</>: Khi cộng đủ 3 tầng, kích nổ và xóa dấu ấn; chịu mul(*d,3) điểm Sát Thương Vật Lý do người áp dụng gây ra. <FaintYellow>Năng Lượng Lá Bài</>: Tối đa 5 điểm; khi đạt 5 điểm, <HighLight>Kỹ Năng Kết Liễu</> chuyển thành và khóa ở <HighLight>Xào Bài</>.",
      [285943353352192] = "Thu thập đủ 3 <HighLight>Thẻ Lam Linh Tính</> để mở khóa kỹ năng này. Gây spellfielddisc(*id) điểm Sát Thương Vật Lý lên kẻ địch trong phạm vi, thêm <HighLight>Tăng Thương</> trong *f giây và <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</> quái địch. Sau khi thi triển nhận 1 điểm <HighLight>Năng Lượng Lá Bài</>. Khi dùng Linh Bạo sẽ xóa hiệu ứng tăng cường bản thân của Số Mệnh. <FaintYellow>Năng Lượng Lá Bài</>: Tối đa 5 điểm; khi đạt 5 điểm, <HighLight>Kỹ Năng Kết Liễu</> chuyển thành và khóa ở <HighLight>Xào Bài</>. <FaintYellow>Tăng Thương</>: Sát thương nhận từ người áp dụng tăng 10%.",
      [285943353352448] = "Chỉ có thể thi triển khi <HighLight>Năng Lượng Lá Bài</> đạt 5 điểm. Tiêu hao 5 điểm <HighLight>Năng Lượng Lá Bài</>, trong 2.7 giây liên tục bắn lá bài vào mục tiêu khóa, gây 12 lần spellfielddisc(*id) điểm Sát Thương Vật Lý lên mục tiêu và kẻ địch trong phạm vi nhỏ xung quanh, đồng thời <HyperLink stylename=\"M_Link\" u=\"2\">Ngắt</> quái địch. Trong lúc thi triển có thể dùng kỹ năng khác và di chuyển. Chỉ cần kỹ năng này đang ở trạng thái có thể thi triển, <HighLight>Kỹ Năng Kết Liễu</> sẽ không chuyển sang <HighLight>Số Mệnh</> hoặc <HighLight>Linh Bạo</>; tuy nhiên hai kỹ năng đó vẫn có thể được mở khóa bằng cách thu thập <HighLight>Thẻ Vàng Vận Mệnh</> hoặc <HighLight>Thẻ Lam Linh Tính</>, và sẽ lập tức khả dụng sau khi kỹ năng này được thi triển.",
      [285943353352704] = "Chỉ có thể thi triển khi <HighLight>Năng Lượng Lá Bài</> đạt 5 điểm. Tiêu hao 5 điểm <HighLight>Năng Lượng Lá Bài</>, trong 2.7 giây liên tục bắn lá bài vào mục tiêu khóa, gây 12 lần spellfielddisc(*id) điểm Sát Thương Vật Lý lên mục tiêu và kẻ địch trong phạm vi nhỏ xung quanh, đồng thời <HyperLink stylename=\"M_Link\" u=\"2\">Ngắt</> quái địch. Trong lúc thi triển có thể dùng kỹ năng khác và di chuyển. Chỉ cần kỹ năng này đang ở trạng thái có thể thi triển, <HighLight>Kỹ Năng Kết Liễu</> sẽ không chuyển sang <HighLight>Số Mệnh</> hoặc <HighLight>Linh Bạo</>; tuy nhiên hai kỹ năng đó vẫn có thể được mở khóa bằng cách thu thập <HighLight>Thẻ Vàng Vận Mệnh</> hoặc <HighLight>Thẻ Lam Linh Tính</>, và sẽ lập tức khả dụng sau khi kỹ năng này được thi triển.",
      [285943353353728] = "Điều khiển Sợi Tơ Linh Thể của mục tiêu khiến mục tiêu buffdisc(*id); đồng thời triển khai Bí Cảnh quanh mục tiêu, khiến kẻ địch trong phạm vi <HyperLink stylename=\"M_Link\" u=\"9\">Trì Trệ</> trong *f giây và chịu 6 lần spellfielddisc(*id) điểm Sát Thương Vật Lý. Sau đó đòn kết liễu gây spellfielddisc(*id) điểm Sát Thương Vật Lý; nếu mục tiêu là quái, <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</> mục tiêu; nếu là người chơi, <HyperLink stylename=\"M_Link\" u=\"6\">Choáng</> mục tiêu trong *f giây. Sau khi thi triển nhận 1 <HighLight>Thẻ Vàng Vận Mệnh</>; nếu lần trước nhận <HighLight>Thẻ Lam Linh Tính</>, thay vào đó nhận 1 <HighLight>Thẻ Lam Linh Tính</>. <FaintYellow>Thẻ Vàng Vận Mệnh</>/<FaintYellow>Thẻ Lam Linh Tính</>: Khi có 3 <HighLight>Thẻ Vàng Vận Mệnh</>/<HighLight>Thẻ Lam Linh Tính</>, tiêu hao toàn bộ lá bài, khiến <HighLight>Kỹ Năng Kết Liễu-Xào Bài</> chuyển thành <HighLight>Số Mệnh</>/<HighLight>Linh Bạo</>.",
      [285943353354240] = "Điều khiển Sợi Tơ Linh Thể của mục tiêu, khiến mục tiêu sau 10 giây rơi vào trạng thái Choáng Cưỡng Chế trong 3 giây; trạng thái Choáng Cưỡng Chế này không thể được giải bằng kỹ năng giải khống chế.",
      [285943353354496] = "Thầy Bói dùng kỹ xảo thu thập <HighLight>Thẻ Vàng Vận Mệnh</>, <HighLight>Thẻ Lam Linh Tính</> và <HighLight>Năng Lượng Lá Bài</>, chuyển <HighLight>Kỹ Năng Kết Liễu</> giữa <HighLight>Số Mệnh</>, <HighLight>Linh Bạo</> và <HighLight>Xào Bài</>; đồng thời có thể dùng kỹ năng để thêm <HighLight>Dấu Ấn Ngu Lộng</> kéo dài *f giây lên kẻ địch. <FaintYellow>Dấu Ấn Ngu Lộng</>: Khi cộng đủ 3 tầng, kích nổ và xóa dấu ấn; chịu mul(*d,3) điểm Sát Thương Vật Lý do người áp dụng gây ra.",
      [285943353354752] = "Dựa vào linh tính bản thân và lấy con lắc chứa linh tính tự nhiên làm môi giới, cảm nhận khải thị của vận mệnh. Bản thân nhận Trực Giác +1.",
      [285943353356288] = "Nhờ khả năng phối hợp cơ thể tăng lên từ năng lực Bậc, kiểm soát hành vi và thần thái để trình diễn một màn khoa trương, hài hước vượt xa khả năng người thường. Bản thân nhận Mị Lực +3, Học Thức +1.",
      [285943353356800] = "Dùng giấy linh tính đặc chế vẽ mẫu mang dấu ấn linh tính của bản thân, khiến mục tiêu theo dẫn dắt linh tính biến thành những mảnh giấy vụn bay đầy trời, dần tiêu tán trong ánh linh tính yếu ớt; đồng thời xóa khí tức và dấu vết tại vị trí hiện tại của mục tiêu. Mục tiêu nhận Học Thức +4, Trực Giác +2.",
      [285943353357056] = "Giải trừ <HyperLink stylename=\"M_Link\" u=\"3\">Hiệu Ứng Khống Chế</> đang chịu; khi dùng nhận <HighLight>0.5</> giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</> và <HighLight>4</> giây <HighLight>Giảm Thương</> 15%; đặt một mốc lửa tại vị trí hiện tại rồi dịch chuyển tức thời đến vị trí mục tiêu. Gây *d điểm Sát Thương Vật Lý trong phạm vi nhỏ quanh vị trí biến mất và vị trí đích.",
      [285943353357312] = "Giải trừ <HyperLink stylename=\"M_Link\" u=\"3\">Hiệu Ứng Khống Chế đang chịu; khi dùng nhận <HighLight>0.5</> giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>; đặt một mốc lửa tại vị trí hiện tại rồi dịch chuyển tức thời đến vị trí mục tiêu. Gây *d điểm Sát Thương Vật Lý trong phạm vi nhỏ quanh vị trí biến mất và vị trí đích.",
      [285943353357568] = "Triệu hồi Bí Cảnh tại khu vực chỉ định, cưỡng chế toàn bộ kẻ địch dịch chuyển về tâm, gây 6 lần spellfielddisc(*id) sát thương; sau đó gây spellfielddisc(*id) sát thương kết liễu, <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</> kẻ địch và khiến chúng <HyperLink stylename=\"M_Link\" u=\"2\">Trì Trệ</> trong 3.5 giây. Sau khi thi triển nhận 1 <HighLight>Vận Mệnh</>; nếu lần trước nhận <HighLight>Linh Tính</>, thay vào đó nhận 1 <HighLight>Linh Tính</>. <FaintYellow>Vận Mệnh</>/<FaintYellow>Linh Tính</>: Tức Thẻ Vàng Vận Mệnh và Thẻ Lam Linh Tính. Khi có 3 <HighLight>Vận Mệnh</>/<HighLight>Linh Tính</>, tiêu hao toàn bộ lá bài, khiến <HighLight>Kỹ Năng Kết Liễu-Xào Bài</> chuyển thành <HighLight>Số Mệnh</>/<HighLight>Linh Bạo</>.",
      [285943353361920] = "Tấn công kẻ địch trong phạm vi nhỏ phía trước theo chuỗi 4 giai đoạn, lần lượt gây *d/*d/sum(*d,*d,*d)/sum(*d,*d,*d,*d) điểm Sát Thương Phép. Giai đoạn bốn khi trúng <HyperLink stylename=\"M_Link\" u=\"2\">Đẩy Lùi</> quái địch và khiến bản thân nhận <HighLight>Hồi Ảnh</>. Khi có <HighLight>Dấu Chân</>, kỹ năng này đổi thành <HighLight>Tái Hiện Dấu Chân</>. <FaintYellow>Tái Hiện Dấu Chân</> skilldisc(*id)",
      [285943353363456] = "Đâm kẻ địch trong phạm vi phía trước, gây *d điểm Sát Thương Phép. Khi trúng, tiêu hao toàn bộ <HighLight>Dấu Chân</> để triệu hồi tàn ảnh truy kích (tối đa tăng lên *d điểm Sát Thương Phép), thêm <HighLight>Rơi Xuống</> lên kẻ địch và khiến bản thân nhận <HighLight>Hồi Ảnh</>. <FaintYellow>Rơi Xuống</> Khiến quái địch <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</>. Nếu tiêu hao từ 2 tầng <HighLight>Dấu Chân</> trở lên, có <HighLight>42%</> xác suất cơ bản thêm buffdisc(*id) trong *f giây; nếu tiêu hao 3 tầng <HighLight>Dấu Chân</>, có <HighLight>70%</> xác suất cơ bản khiến người chơi địch <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</>. Sau khi mục tiêu người chơi bị kỹ năng này <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</>, trong thời gian ngắn không thể tiếp tục bị kỹ năng này <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</>. <FaintYellow>Hồi Ảnh</> Giảm 1 giây hồi chiêu của <HighLight>Trục Xuất</>, <HighLight>Thán Vân</>, <HighLight>Ảo Thuật</>, <HighLight>Ghi Chép</>; nếu tiêu hao 3 tầng <HighLight>Dấu Chân</>, giảm thêm 2 giây hồi chiêu của <HighLight>skillname(*id)</>.",
      [285943353364736] = "Gây spellfielddisc(*id) điểm Sát Thương Phép và *f giây mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</> lên kẻ địch trong phạm vi, đồng thời ngẫu nhiên thêm một trong các hiệu ứng <HighLight>Đá Rơi</>, <HighLight>Băng Giá</>, <HighLight>Cuồng Phong</>. Khi có <HighLight>Nghiên Tập</> (dùng kỹ năng chiến đấu <HighLight>Không Ngục</> để vào trạng thái <HighLight>Nghiên Tập</>), nhận <HighLight>Cường Hóa</>: sau khi thi triển, triệu hồi tàn ảnh tấn công lại kẻ địch trong phạm vi, gây spellfielddisc(*id) điểm Sát Thương Phép và khi trúng nhận 1 điểm <HighLight>Năng Lượng Tinh Không</>. <FaintYellow>Đá Rơi</> Gây spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch trong phạm vi và thêm Thiêu Đốt khiến chúng buffdisc(*id), đồng thời <HyperLink stylename=\"M_Link\" u=\"2\">Đánh Ngã</> quái địch. <FaintYellow>Băng Giá</> Gây spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch trong phạm vi và có <HighLight>66%</> xác suất cơ bản thêm buffdisc(*id) trong *f giây, đồng thời <HyperLink stylename=\"M_Link\" u=\"13\">Đóng Băng</> quái địch. <FaintYellow>Cuồng Phong</> Triệu hồi cuồng phong liên tục <HyperLink stylename=\"M_Link\" u=\"2\">Kéo</> quái địch và gây 6 lần spellfielddisc(*id) điểm Sát Thương Phép; đòn cuối <HyperLink stylename=\"M_Link\" u=\"2\">Đánh Ngã</> quái địch.",
      [285943353365248] = "Dịch chuyển tới vị trí mục tiêu, nhận 0.8 giây <HyperLink stylename=\"M_Link\" u=\"1\">Vô Địch</> và 2 giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>, gây 4 lần *d điểm Sát Thương Phép lên kẻ địch trong khu vực; sau đó kích nổ gây thêm *d điểm Sát Thương Phép, <HyperLink stylename=\"M_Link\" u=\"2\">Đánh Ngã</> quái địch và thêm *f giây mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</>.",
      [285943353365760] = "Lao theo hướng nhân vật đang nhìn, nhận <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</> ngắn trong lúc lao; gây spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch trên đường và có <HighLight>60%</> xác suất cơ bản thêm 1.3 giây <HyperLink stylename=\"M_Link\" u=\"9\">Trì Trệ</>. Kỹ năng này có thể tích 2 lần.",
      [285943353366016] = "Lao tới mục tiêu khóa, nhận <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</> ngắn trong lúc lao, có <HighLight>80%</> xác suất cơ bản gây 2 giây <HyperLink stylename=\"M_Link\" u=\"6\">Choáng</> lên mục tiêu và gây *d điểm Sát Thương Phép lên mục tiêu cùng kẻ địch xung quanh. Trong *f giây sau khi thi triển có thể dùng liên chiêu giai đoạn hai để nhanh chóng lùi về vị trí ban đầu.",
      [285943353366784] = "Gây *d điểm Sát Thương Phép và *f giây mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</> lên kẻ địch trong phạm vi tròn phía trước. Khi có <HighLight>Nghiên Tập</> (dùng kỹ năng chiến đấu <HighLight>Không Ngục</> để vào trạng thái <HighLight>Nghiên Tập</>), nhận <HighLight>Cường Hóa</>: sau khi thi triển, triệu hồi tàn ảnh tấn công lại kẻ địch trong phạm vi, gây spellfielddisc(*id) điểm Sát Thương Phép và khi trúng nhận 1 điểm <HighLight>Năng Lượng Tinh Không</>.",
      [285943353367040] = "Gây <HyperLink stylename=\"M_Link\" u=\"9\">Trì Trệ</> và giảm 50% Tốc Độ Di Chuyển lên kẻ địch trong phạm vi, đồng thời gây 5 lần *d điểm Sát Thương Phép và <HyperLink stylename=\"M_Link\" u=\"2\">Kéo</> quái địch. Sau đó đòn kết liễu gây *d điểm Sát Thương Phép và <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</> quái địch. Khi có <HighLight>Nghiên Tập</> (dùng kỹ năng chiến đấu <HighLight>Không Ngục</> để vào trạng thái <HighLight>Nghiên Tập</>), nhận <HighLight>Cường Hóa</>: mỗi trong 5 lần sát thương lên kẻ địch trong phạm vi tăng thành *d điểm; sát thương đòn kết liễu tăng thành *d điểm.",
      [285943353368320] = "Bản thân nhận <HighLight>Nghiên Tập</> trong 6 giây; triệu hồi Không Ngục tại vị trí mục tiêu trong 5 giây, gây 3 lần *d điểm Sát Thương Phép lên kẻ địch trong phạm vi, sau đó lao lung sụp đổ gây *d điểm Sát Thương Phép. Khi kẻ địch trong lao lung bị kỹ năng chiến đấu của bản thân đánh trúng, bản thân nhận 1 tầng <HighLight>Chiết Mạc</> trong <HighLight>0.5</> giây và khiến lao lung phối hợp tấn công mục tiêu, gây *d điểm Sát Thương Phép phạm vi và thêm buffdisc(*id) trong *f giây. (Cùng một mục tiêu có hồi chiêu nội tại 1 giây.) <FaintYellow>Chiết Mạc</> Mỗi tầng <HighLight>Chiết Mạc</> cho bản thân <HighLight>Bá Thể</> và <HighLight>Giảm Thương 6%</>, tối đa <HighLight>5</> tầng; thời lượng cũng cộng dồn theo số tầng. <FaintYellow>Nghiên Tập</> Cường hóa hiệu ứng khi dùng <HighLight>Thán Vân</>, <HighLight>Ảo Thuật</>, <HighLight>Trục Xuất</>.",
      [285943353369344] = "Ghi lại <HighLight>Năng Lực Phi Phàm</> thuộc Con Đường của mục tiêu (nếu ghi lại mục tiêu không phải người chơi, nhận ngẫu nhiên một Năng Lực Phi Phàm của Con Đường này). Sau khi dùng kỹ năng có thể tung liên chiêu để triệu hồi hình chiếu sử dụng <HighLight>Năng Lực Phi Phàm</> đã ghi (Năng Lực Phi Phàm không thuộc Con Đường này chỉ giữ hiệu ứng cơ bản). <FaintYellow>Năng lực có thể ghi lại</>: Ca Tụng Giả: <HyperLink stylename=\"M_Link\" u=\"86054010\" color=\"#f4a067\">Cuồng Phủ</> Khán Giả: <HyperLink stylename=\"M_Link\" u=\"86054020\" color=\"#f4a067\">Ám Thị</> Thầy Bói: <HyperLink stylename=\"M_Link\" u=\"86054030\" color=\"#f4a067\">Đạn Khí</> Học Đồ: <HyperLink stylename=\"M_Link\" u=\"86054050\" color=\"#f4a067\">Thán Vân</>, <HyperLink stylename=\"M_Link\" u=\"86054052\" color=\"#f4a067\">Ảo Thuật</>, <HyperLink stylename=\"M_Link\" u=\"86054054\" color=\"#f4a067\">Trục Xuất</> Chiến Sĩ: <HyperLink stylename=\"M_Link\" u=\"86054060\" color=\"#f4a067\">Hiệu Lệnh Vương Đình</> Kẻ Dòm Ngó Bí Ẩn: <HyperLink stylename=\"M_Link\" u=\"86054070\" color=\"#f4a067\">Lao Lung Tinh Quang</>",
      [285943353369600] = "Giải trừ <HyperLink stylename=\"M_Link\" u=\"3\">Hiệu Ứng Khống Chế</> đang chịu, nhận <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</> và buffdisc(*id) trong *f giây; gây *d điểm Sát Thương Phép lên kẻ địch xung quanh, đồng thời có <HighLight>100%</> xác suất cơ bản thêm buffdisc(*id) trong *f giây. Sau khi dùng có thể tung liên chiêu, lao tới cạnh mục tiêu địch, gây *d điểm Sát Thương Phép và có <HighLight>100%</> xác suất cơ bản <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</> mục tiêu.",
      [285943353370112] = "Nhận *f giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>, <HyperLink stylename=\"M_Link\" u=\"7\">Trói Buộc</> kẻ địch trong khu vực mục tiêu trong *f giây và sau một khoảng trễ ngắn gây *d sát thương.",
      [285943353374720] = "Chỉ có thể thi triển khi có ít nhất 3 điểm <HighLight>Năng Lượng Tinh Không</>. Tiêu hao toàn bộ <HighLight>Năng Lượng Tinh Không</>, đâm kẻ địch trong khu vực gây 2 lần *d điểm Sát Thương Phép; sau đó triệu hồi nhiều tàn ảnh đánh kẻ địch gây 4 lần *d điểm Sát Thương Phép, cuối cùng kích nổ Năng Lượng Tinh Không gây *d điểm Sát Thương Phép. Khi tiêu hao hơn 3 điểm Năng Lượng Tinh Không, mỗi thêm 1 điểm tiêu hao làm sát thương kỹ năng này tăng *f**.",
      [285943353375744] = "Ngưng tụ rìu ngắn, liên tục tấn công kẻ địch xung quanh trong 6 giây; mỗi <HighLight>0.8</> giây gây *d điểm Sát Thương Phép và có *f** xác suất cơ bản gây <HighLight>Giảm Tốc 25%</> trong *f giây.",
      [285943353376512] = "Lập tức hồi cho mục tiêu lượng Máu bằng *f** Máu tối đa của mục tiêu và khiến mục tiêu buffdisc(*id) trong *f giây.",
      [285943353377024] = "Đồng thời liên tục bắn nhiều Đạn Khí vào kẻ địch, gây 5 lần bulletdisc(*id) điểm Sát Thương Phép và <HyperLink stylename=\"M_Link\" u=\"2\">Ngắt</> quái địch.",
      [285943353377536] = "Gây *d điểm Sát Thương Phép lên kẻ địch trong phạm vi tròn phía trước. Khi có <HighLight>Nghiên Tập</> (dùng kỹ năng chiến đấu <HighLight>Không Ngục</> để vào trạng thái <HighLight>Nghiên Tập</>), nhận <HighLight>Cường Hóa</>: sau khi thi triển, triệu hồi tàn ảnh tấn công lại kẻ địch trong phạm vi, gây spellfielddisc(*id) điểm Sát Thương Phép và khi trúng nhận 1 điểm <HighLight>Năng Lượng Tinh Không</>.",
      [285943353378048] = "Gây spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch trong phạm vi, đồng thời ngẫu nhiên thêm một trong các hiệu ứng <HighLight>Đá Rơi</>, <HighLight>Băng Giá</>, <HighLight>Cuồng Phong</>. Khi có <HighLight>Nghiên Tập</> (dùng kỹ năng chiến đấu <HighLight>Không Ngục</> để vào trạng thái <HighLight>Nghiên Tập</>), nhận <HighLight>Cường Hóa</>: sau khi thi triển, triệu hồi tàn ảnh tấn công lại kẻ địch trong phạm vi, gây spellfielddisc(*id) điểm Sát Thương Phép và khi trúng nhận 1 điểm <HighLight>Năng Lượng Tinh Không</>. <FaintYellow>Đá Rơi</> Gây spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch trong phạm vi và thêm Thiêu Đốt khiến chúng buffdisc(*id), đồng thời <HyperLink stylename=\"M_Link\" u=\"2\">Đánh Ngã</> quái địch. <FaintYellow>Băng Giá</> Gây spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch trong phạm vi và có <HighLight>66%</> xác suất cơ bản thêm buffdisc(*id) trong *f giây, đồng thời <HyperLink stylename=\"M_Link\" u=\"13\">Đóng Băng</> quái địch. <FaintYellow>Cuồng Phong</> Triệu hồi cuồng phong liên tục <HyperLink stylename=\"M_Link\" u=\"2\">Kéo</> quái địch và gây 6 lần spellfielddisc(*id) điểm Sát Thương Phép; đòn cuối <HyperLink stylename=\"M_Link\" u=\"2\">Đánh Ngã</> quái địch.",
      [285943353378560] = "Gây 5 lần *d điểm Sát Thương Phép lên kẻ địch trong phạm vi, đồng thời <HyperLink stylename=\"M_Link\" u=\"2\">Kéo</> quái địch; sau đó đòn kết liễu gây *d điểm Sát Thương Phép và <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</> quái địch. Khi có <HighLight>Nghiên Tập</> (dùng kỹ năng chiến đấu <HighLight>Không Ngục</> để vào trạng thái <HighLight>Nghiên Tập</>), nhận <HighLight>Cường Hóa</>: mỗi trong 5 lần sát thương lên kẻ địch trong phạm vi tăng thành *d điểm; sát thương đòn kết liễu tăng thành *d điểm.",
      [285943353380096] = "Gầm lên dữ dội, gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh và thêm buffdisc(*id) trong *f giây. Sau đó triệu hồi hư ảnh Cự Nhân đập mạnh xuống đất, gây spellfielddisc(*id) điểm Sát Thương Vật Lý.",
      [285943353380608] = "Triệu hồi Lao Lung Tinh Quang, gây spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch trong phạm vi quanh mục tiêu khóa, kèm <HighLight>44%</> xác suất cơ bản trong <HighLight>1.1</> giây <HyperLink stylename=\"M_Link\" u=\"7\">Trói Buộc</> và <HyperLink stylename=\"M_Link\" u=\"7\">Giảm Tốc</>; riêng mục tiêu khóa chịu thêm <HighLight>69%</> xác suất cơ bản trong <HighLight>1.71</> giây <HyperLink stylename=\"M_Link\" u=\"6\">Choáng</>.",
      [285943353381120] = "Sau khi dùng kỹ năng chiến đấu ngoài đánh thường, nhận 1 tầng <HighLight>Dấu Chân</> trong *f giây. Sau khi dùng kỹ năng chiến đấu ngoài đánh thường và Kỹ Năng Kết Liễu, nhận 1 điểm <HighLight>Năng Lượng Tinh Không</>. <FaintYellow>Năng Lượng Tinh Không</> <HighLight>Năng Lượng Tinh Không</> tối đa 5 điểm. Khi có 3 điểm <HighLight>Năng Lượng Tinh Không</>, mở khóa <HighLight>Kỹ Năng Kết Liễu-Trùng Môn</>. Dùng <HighLight>Trùng Môn</> sẽ tiêu hao <HighLight>Năng Lượng Tinh Không</> để cường hóa hiệu ứng. <FaintYellow>Dấu Chân</> <HighLight>Dấu Chân</> tối đa 3 tầng. Khi dùng đòn đánh thường <HighLight>Thiểm Kích</>, tiêu hao toàn bộ <HighLight>Dấu Chân</> để cường hóa hiệu ứng. (Nếu không trúng sẽ không tiêu hao <HighLight>Dấu Chân</>.)",
      [285943353381376] = "Cảm nhận Linh Giới và không gian, mở một cổng dịch chuyển để Học Đồ xuyên qua. Chỉ có thể dùng tại Tingen. Bản thân nhận Trực Giác +1.",
      [285943353381632] = "Nắm vững nhiều trò ảo thuật kỳ lạ nhưng ít nguy hiểm, dùng hộp đạo cụ đặc chế để trình diễn hoa mỹ, đánh lừa người xem và quay lại khoảnh khắc này. Bản thân nhận Học Thức +3, Vũ Lực +1.",
      [285943353382400] = "Cảm nhận Linh Giới, quan sát tinh không; thông qua biến động vận mệnh được vật phẩm linh tính khải thị, giải đọc dị động trong không gian hiện thực, xu hướng phát triển sự việc và nguy hiểm tiềm ẩn chưa biết. Trong thời gian Khải Thị Chiêm Tinh, người chơi xung quanh có thể nhận kỹ năng tạm thời để lấy chỉ dẫn chiêm tinh. Bản thân nhận Vũ Lực +4, Trực Giác +2. Người chơi dùng kỹ năng tạm thời nhận chỉ dẫn chiêm tinh cũng nhận Vũ Lực +4, Trực Giác +2.",
      [285943353383168] = "Tạo <HighLight>Cổng Lữ Hành Gia dùng cho tiểu đội</> trước mặt và tại vị trí mục tiêu. Thành viên tiểu đội có thể tương tác với <HighLight>Cổng Lữ Hành Gia</> để dịch chuyển tới vị trí mục tiêu và nhận <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</> cùng <HighLight>Giảm Thương</> (dịch chuyển một chiều, tối đa 1 lần).",
      [285943353383936] = "Tấn công liên tiếp 3 lần lên kẻ địch trong phạm vi nhỏ phía trước, mỗi lần lần lượt gây *d, *d và *d điểm Sát Thương Vật Lý. Giai đoạn ba trúng kẻ địch, bản thân nhận 1 <HighLight>Dấu Ấn Hoàng Hôn</>. <FaintYellow>Dấu Ấn Hoàng Hôn</> Cường hóa <HighLight>Kỹ Năng Kết Liễu</> và <HighLight>Nộ Ý Kích</>, tối đa giữ 6 dấu.",
      [285943353384704] = "Tấn công liên tiếp 3 lần lên kẻ địch trong phạm vi nhỏ phía trước, mỗi lần lần lượt gây sum(*d+*d), sum(*d+*d) và sum(*d+*d+*d) điểm Sát Thương Vật Lý. Giai đoạn ba trúng kẻ địch sẽ thêm <Highlight>6</> giây <HighLight>Suy Bại</>, đồng thời bản thân nhận 1 <HighLight>Dấu Ấn Hoàng Hôn</>. <FaintYellow>Dấu Ấn Hoàng Hôn</> Cường hóa <HighLight>Kỹ Năng Kết Liễu</> và <HighLight>Nộ Ý Kích</>, tối đa giữ 6 dấu. <FaintYellow>Suy Bại</> buffdisc(*id); khi áp dụng nhiều lần, thời lượng cộng dồn, tối đa 20 giây.",
      [285943353385728] = "Gây *d điểm Sát Thương Vật Lý lên kẻ địch trong phạm vi chữ nhật theo hướng mục tiêu khóa, đồng thời <HyperLink stylename=\"M_Link\" u=\"2\">Kéo</> chúng tới trước mặt và thêm <HighLight>2 giây</> <HyperLink stylename=\"M_Link\" u=\"9\">Trì Trệ</> lên người chơi địch. Sau đó chém bổ xuống, gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh; có *f** xác suất cơ bản thêm *f giây <HyperLink stylename=\"M_Link\" u=\"7\">Trói Buộc</> và *f giây mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</> lên người chơi địch. Khi trúng kẻ địch, bản thân nhận 1 <HighLight>Dấu Ấn Hoàng Hôn</>. Khi bản thân ở <HighLight>Tư Thế Phòng Thủ</>, nếu mục tiêu khóa là quái, thêm *f giây <HyperLink stylename=\"M_Link\" u=\"12\">Khiêu Khích</> lên mục tiêu. <FaintYellow>Dấu Ấn Hoàng Hôn</> Cường hóa <HighLight>Kỹ Năng Kết Liễu</> và <HighLight>Nộ Ý Kích</>, tối đa giữ 6 dấu.",
      [285943353386752] = "Nhanh chóng lao tới mục tiêu địch, gây *d điểm Sát Thương Vật Lý lên kẻ địch tại khu vực đích, với *f** xác suất cơ bản gây *f giây <HyperLink stylename=\"M_Link\" u=\"7\">Trói Buộc</> và thêm *f giây mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</> lên người chơi địch. Sau đó đập xuống, gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh, <HyperLink stylename=\"M_Link\" u=\"2\">Đánh Ngã</> quái địch và với *f** xác suất cơ bản <HyperLink stylename=\"M_Link\" u=\"2\">Ngắt</> người chơi địch; đồng thời bản thân nhận 1 <HighLight>Dấu Ấn Hoàng Hôn</>. Trong <HighLight>Tư Thế Tấn Công</>, mỗi lần trúng kẻ địch sẽ thêm <Highlight>6</> giây <HighLight>Suy Bại</>. Sau khi thi triển, nếu bản thân không ở trạng thái <HighLight>Chân Không Lực Lượng</>, trong <Highlight>3</> giây kỹ năng này đổi thành <HighLight>Hiệu Lệnh Vương Đình</>. <FaintYellow>Dấu Ấn Hoàng Hôn</> Cường hóa <HighLight>Kỹ Năng Kết Liễu</> và <HighLight>Nộ Ý Kích</>, tối đa giữ 6 dấu. <FaintYellow>Suy Bại</> buffdisc(*id); khi áp dụng nhiều lần, thời lượng cộng dồn, tối đa 20 giây. <FaintYellow>Chân Không Lực Lượng</> Trong thời gian hiệu lực không thể dùng <HighLight>Hiệu Lệnh Vương Đình</>.",
      [285943353387264] = "Gầm lên dữ dội, gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh và thêm buffdisc(*id) trong *f giây. Sau đó triệu hồi hư ảnh Cự Nhân đập mạnh xuống vùng đất phía trước, gây spellfielddisc(*id) điểm Sát Thương Vật Lý và <HighLight>Đánh Ngã</> quái ở vùng trung tâm. Trong <HighLight>Tư Thế Phòng Thủ</>, dùng sau Liệp Ma Trảm có thể <HighLight>Đánh Ngã</> người chơi địch ở vùng trung tâm; dùng sau Trảm Vệ Trừ Ma không có hiệu ứng <HighLight>Đánh Ngã</> người chơi. Sau khi dùng, vào trạng thái <HighLight>Chân Không Lực Lượng</>. <FaintYellow>Chân Không Lực Lượng</> Trong thời gian hiệu lực không thể dùng <HighLight>Hiệu Lệnh Vương Đình</>.",
      [285943353387520] = "Nhanh chóng lao tới mục tiêu đồng minh, giải trừ khống chế nhẹ và Giảm Tốc của đồng minh tại khu vực đích, đồng thời cho họ 15% Giảm Thương và 25% Tăng Tốc trong 5 giây. Sau khi thi triển, nếu bản thân không ở trạng thái <HighLight>Chân Không Lực Lượng</>, trong <Highlight>3</> giây kỹ năng này đổi thành <HighLight>Hiệu Lệnh Vương Đình</>. <FaintYellow>Dấu Ấn Hoàng Hôn</> Cường hóa <HighLight>Kỹ Năng Kết Liễu</> và <HighLight>Nộ Ý Kích</>, tối đa giữ 6 dấu. <FaintYellow>Chân Không Lực Lượng</> Trong thời gian hiệu lực không thể dùng <HighLight>Hiệu Lệnh Vương Đình</>.",
      [285943353387776] = "Nhanh chóng lao tới mục tiêu, tạo hiệu ứng khác nhau tùy phe mục tiêu. Nếu mục tiêu là kẻ địch, gây *d điểm Sát Thương Vật Lý lên đơn vị tại khu vực đích, với *f** xác suất cơ bản gây *f giây <HyperLink stylename=\"M_Link\" u=\"7\">Trói Buộc</> và thêm *f giây mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</> lên người chơi địch; sau đó đập xuống gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh, <HyperLink stylename=\"M_Link\" u=\"2\">Đánh Ngã</> quái địch và với *f** xác suất cơ bản <HyperLink stylename=\"M_Link\" u=\"2\">Ngắt</> người chơi địch; đồng thời bản thân nhận 1 <HighLight>Dấu Ấn Hoàng Hôn</>. Nếu mục tiêu là đồng minh và bản thân ở <HighLight>Tư Thế Phòng Thủ</>, giải trừ khống chế nhẹ và Giảm Tốc cho đồng minh, thêm <HighLight>Tiếp Viện Tức Thời</> khiến họ buffdisc(*id) trong 5 giây, đồng thời bản thân nhận 1 <HighLight>Dấu Ấn Hoàng Hôn</>. Trong <HighLight>Tư Thế Tấn Công</>, mỗi lần trúng kẻ địch sẽ thêm <Highlight>6</> giây <HighLight>Suy Bại</>. Sau khi thi triển, nếu bản thân không ở trạng thái <HighLight>Chân Không Lực Lượng</>, trong <Highlight>3</> giây kỹ năng này đổi thành <HighLight>Hiệu Lệnh Vương Đình</>; lúc này trong <HighLight>Tư Thế Phòng Thủ</>, Hiệu Lệnh Vương Đình không có hiệu ứng Đánh Ngã người chơi địch. <FaintYellow>Dấu Ấn Hoàng Hôn</> Cường hóa <HighLight>Kỹ Năng Kết Liễu</> và <HighLight>Nộ Ý Kích</>, tối đa giữ 6 dấu. <FaintYellow>Suy Bại</> buffdisc(*id); khi áp dụng nhiều lần, thời lượng cộng dồn, tối đa 20 giây. <FaintYellow>Chân Không Lực Lượng</> Trong thời gian hiệu lực không thể dùng <HighLight>Hiệu Lệnh Vương Đình</>.",
      [285943353388032] = "Gầm lên dữ dội, gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh và thêm buffdisc(*id) trong *f giây. Sau đó triệu hồi hư ảnh Cự Nhân đập mạnh xuống đất, gây spellfielddisc(*id) điểm Sát Thương Vật Lý. Sau khi dùng, vào trạng thái <HighLight>Chân Không Lực Lượng</>. <FaintYellow>Chân Không Lực Lượng</> Trong thời gian hiệu lực không thể dùng <HighLight>Hiệu Lệnh Vương Đình</>.",
      [285943353388288] = "Cầm cự kiếm xoay chém. Đòn đầu gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh; sau đó liên tục tấn công, mỗi <Highlight>0.4</> giây gây *d điểm Sát Thương Vật Lý, tổng thời gian <Highlight>5</> giây, đồng thời <HyperLink stylename=\"M_Link\" u=\"2\">Kéo</> quái địch về phía bản thân và khiến người chơi địch buffdisc(*id). Khi kết thúc xoay, gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh. Trong lúc thi triển, mỗi giây nhận 1 <HighLight>Dấu Ấn Hoàng Hôn</>. Trong thời gian kỹ năng Cuồng Phong, nhận <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</> và có thể di chuyển. Sau 1 giây có thể nhấn lại để ngắt sớm, gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh và hoàn trả một phần hồi chiêu. Nếu bản thân ở <HighLight>Tư Thế Phòng Thủ</>, các đòn đánh thêm *f giây <HyperLink stylename=\"M_Link\" u=\"12\">Khiêu Khích</> lên quái địch. <FaintYellow>Dấu Ấn Hoàng Hôn</> Cường hóa <HighLight>Kỹ Năng Kết Liễu</> và <HighLight>Nộ Ý Kích</>, tối đa giữ 6 dấu.",
      [285943353389056] = "Cầm cự kiếm xoay chém. Đòn đầu gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh; sau đó liên tục tấn công, mỗi <Highlight>0.4</> giây gây *d điểm Sát Thương Vật Lý, tổng thời gian <Highlight>5</> giây, đồng thời <HyperLink stylename=\"M_Link\" u=\"2\">Kéo</> quái địch về phía bản thân và khiến người chơi địch buffdisc(*id). Khi kết thúc xoay, gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh. Trong lúc thi triển, mỗi giây nhận 1 <HighLight>Dấu Ấn Hoàng Hôn</>. Trong thời gian kỹ năng Cuồng Phong, nhận <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</> và có thể di chuyển. Sau 1 giây có thể tung liên chiêu để ngắt, gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh và hoàn trả một phần hồi chiêu. Nếu bản thân ở <HighLight>Tư Thế Phòng Thủ</>, các đòn đánh thêm *f giây <HyperLink stylename=\"M_Link\" u=\"12\">Khiêu Khích</> lên quái địch. <FaintYellow>Dấu Ấn Hoàng Hôn</> Cường hóa <HighLight>Kỹ Năng Kết Liễu</> và <HighLight>Nộ Ý Kích</>, tối đa giữ 6 dấu.",
      [285943353389312] = "Nhận buffdisc(*id) trong *f giây (khiên này được cộng thêm từ Máu tối đa của bản thân). Khi khiên bị phá, bản thân nhận buffdisc(*id) giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>; hiệu ứng này có hồi chiêu nội tại buffdisc(*id) giây. Khi thi triển nhận 1 <HighLight>Dấu Ấn Hoàng Hôn</>. Nếu đang thi triển kỹ năng khác, nhấn kỹ năng này có thể nhận khiên ngay. Khi mang kỹ năng này: passivedisc(*id). <FaintYellow>Dấu Ấn Hoàng Hôn</> Cường hóa <HighLight>Kỹ Năng Kết Liễu</> và <HighLight>Nộ Ý Kích</>, tối đa giữ 6 dấu.",
      [285943353389824] = "Bản thân nhận <HighLight>Tế Kiếm Ngân Bạch</> trong <HighLight>20</> giây và nhận 4 tầng <HighLight>Thần Hi</>; mỗi <HighLight>5</> giây mất 1 tầng <HighLight>Thần Hi</>. Khi thi triển nhận 2 <HighLight>Dấu Ấn Hoàng Hôn</>. Nếu đang thi triển kỹ năng khác, nhấn kỹ năng này có thể nhận trực tiếp toàn bộ hiệu ứng tăng cường. <FaintYellow>Tế Kiếm Ngân Bạch</> Khi gây sát thương lên kẻ địch, phối hợp tấn công mục tiêu, gây bulletdisc(*id) điểm Sát Thương Vật Lý. Hiệu ứng này có hồi chiêu nội tại <HighLight>3</> giây. <FaintYellow>Thần Hi</> Mỗi tầng khiến buffdisc(*id). <FaintYellow>Dấu Ấn Hoàng Hôn</> Cường hóa <HighLight>Kỹ Năng Kết Liễu</> và <HighLight>Nộ Ý Kích</>, tối đa giữ 6 dấu.",
      [285943353390336] = "Triển khai lĩnh vực: bản thân buffdisc(*id), đồng đội trong phạm vi lớn buffdisc(*id); bản thân và đồng đội nhận <HighLight>10%</> Giảm Thương; gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh. Sau đó liên tục tụ lực và ở trạng thái <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>; khi kết thúc gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh. Sát thương và khiên này được cộng thêm từ Máu tối đa của bản thân. Khi thi triển, tiêu hao toàn bộ <HighLight>Dấu Ấn Hoàng Hôn</> để <HighLight>Cường Hóa</> kỹ năng. <FaintYellow>Cường Hóa</> Mỗi 1 Dấu Ấn Hoàng Hôn tiêu hao làm khiên cung cấp tăng <HighLight>25%</>.",
      [285943353391104] = "Triển khai lĩnh vực, cung cấp lượng khiên lớn và <HighLight>15%</> Giảm Thương cho 2 đồng đội có Máu thấp nhất trong lĩnh vực (nếu trong lĩnh vực chỉ có bản thân, lượng khiên tăng gấp đôi); gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh. Sau đó liên tục tụ lực và ở trạng thái <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>; khi kết thúc gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh. Sát thương và khiên này được cộng thêm từ Máu tối đa của bản thân. Khi thi triển, tiêu hao toàn bộ <HighLight>Dấu Ấn Hoàng Hôn</> để <HighLight>Cường Hóa</> kỹ năng. <FaintYellow>Cường Hóa</> Mỗi 1 Dấu Ấn Hoàng Hôn tiêu hao làm khiên cung cấp tăng <HighLight>25%</>.",
      [285943353391616] = "Liên tục ở trạng thái <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>, tụ lực và liên tục gây Sát Thương Vật Lý lên kẻ địch xung quanh, tổng cộng <Highlight>4</> lần, mỗi lần *d điểm; sau khi tụ lực kết thúc gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh. Đòn đầu kích nổ và xóa <HighLight>Suy Bại</> trên mục tiêu; mỗi 1 giây thời lượng Suy Bại còn lại làm sát thương tăng *d điểm. Khi thi triển, tiêu hao toàn bộ <HighLight>Dấu Ấn Hoàng Hôn</> để <HighLight>Cường Hóa</> kỹ năng. <FaintYellow>Cường Hóa</> Mỗi 1 <HighLight>Dấu Ấn Hoàng Hôn</> tiêu hao làm sát thương kỹ năng tăng <HighLight>10%</>.",
      [285943353392384] = "Kỹ năng có thể tích 3 lần và có 3 thế kiếm; sau mỗi lần thi triển, thế kiếm tự đổi, các thế có thể nối với nhau, lần lượt gây *d, sum(*d+*d), sum(*d+*d) điểm Sát Thương Vật Lý. Mỗi giai đoạn khi thi triển tiêu hao tối đa 2 <HighLight>Dấu Ấn Hoàng Hôn</> để <HighLight>Cường Hóa</> kỹ năng. <FaintYellow>Cường Hóa</> Tiêu hao 1/2 <HighLight>Dấu Ấn Hoàng Hôn</>, giá trị sát thương cơ bản mỗi lần của kỹ năng tăng *d/*d điểm.",
      [285943353394432] = "Lao theo hướng chỉ định, gây *d điểm Sát Thương Vật Lý lên kẻ địch trên đường. Khi trúng kẻ địch, nhận 1 <HighLight>Dấu Ấn Hoàng Hôn</>. Kỹ năng này có thể tích <HighLight>2</> lần. Nếu bản thân ở <HighLight>Tư Thế Phòng Thủ</>, khi trúng kẻ địch sẽ buffdisc(*id) trong *f giây. Nếu bản thân ở <HighLight>Tư Thế Tấn Công</>, khi trúng kẻ địch thêm <HighLight>Suy Bại</> trong <HighLight>6</> giây. <FaintYellow>Dấu Ấn Hoàng Hôn</> Cường hóa <HighLight>Kỹ Năng Kết Liễu</> và <HighLight>Nộ Ý Kích</>, tối đa giữ 6 dấu. <FaintYellow>Suy Bại</> buffdisc(*id); khi áp dụng nhiều lần, thời lượng cộng dồn, tối đa 20 giây.",
      [285943353395200] = "Nhận buffdisc(*id) và <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>, vung song kiếm liên tục <HyperLink stylename=\"M_Link\" u=\"2\">Ngắt</> mục tiêu địch và gây tổng cộng sum(*d,*d,*d,*d) điểm Sát Thương Vật Lý, cuối cùng với *f** xác suất cơ bản <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</> mục tiêu. Sau khi thi triển nhận 2 <HighLight>Dấu Ấn Hoàng Hôn</>. Nếu bản thân ở <HighLight>Tư Thế Tấn Công</>, mỗi lần trúng kẻ địch sẽ thêm <HighLight>Suy Bại</> trong <HighLight>6</> giây. <FaintYellow>Dấu Ấn Hoàng Hôn</> Cường hóa <HighLight>Kỹ Năng Kết Liễu</> và <HighLight>Nộ Ý Kích</>, tối đa giữ 6 dấu. <FaintYellow>Suy Bại</> buffdisc(*id); khi áp dụng nhiều lần, thời lượng cộng dồn, tối đa 20 giây.",
      [285943353396224] = "Triệu hồi kiếm trận cự kiếm tại vị trí mục tiêu khóa, gây spellfielddisc(*id) điểm Sát Thương Vật Lý. Khi thi triển nhận 1 <HighLight>Dấu Ấn Hoàng Hôn</>. Nếu bản thân ở <HighLight>Tư Thế Tấn Công</>, khi trúng kẻ địch thêm <HighLight>Suy Bại</> trong <HighLight>6</> giây. <FaintYellow>Dấu Ấn Hoàng Hôn</> Cường hóa <HighLight>Kỹ Năng Kết Liễu</> và <HighLight>Nộ Ý Kích</>, tối đa giữ 6 dấu. <FaintYellow>Suy Bại</> buffdisc(*id); khi áp dụng nhiều lần, thời lượng cộng dồn, tối đa 20 giây.",
      [285943353397248] = "Giải trừ <HyperLink stylename=\"M_Link\" u=\"3\">Hiệu Ứng Khống Chế</> đang chịu, <HyperLink stylename=\"M_Link\" u=\"16\">Hồi Phục Cố Định</> lượng Máu bằng *f** Máu đã mất của bản thân, gây *d điểm Sát Thương Vật Lý lên kẻ địch xung quanh; nhận *f giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>, 3 giây tăng <HighLight>20%</> Tốc Độ Di Chuyển và *f giây <HighLight>Phá Huyễn</>. <FaintYellow>Phá Huyễn</> buffdisc(*id).",
      [285943353397760] = "Triệu hồi hư ảnh Cự Nhân đập mạnh xuống đất, gây lượng lớn Sát Thương Vật Lý.",
      [285943353398272] = "Triệu hồi hư ảnh Cự Nhân phối hợp tấn công kẻ địch phía trước, lần lượt gây *d và *d điểm Sát Thương Vật Lý; kẻ địch người chơi trúng đòn của bản thân bị thêm *f giây mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</>. Sau khi thi triển, bản thân nhận 4 <HighLight>Dấu Ấn Hoàng Hôn</>, đồng thời mỗi <HighLight>2</> giây nhận <HighLight>1</> <HighLight>Dấu Ấn Hoàng Hôn</> trong 6 giây. <FaintYellow>Dấu Ấn Hoàng Hôn</> Cường hóa <HighLight>Kỹ Năng Kết Liễu</> và <HighLight>Nộ Ý Kích</>, tối đa giữ 6 dấu.",
      [285943353398784] = "Nhận buffdisc(*id) và <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>, vung song kiếm liên tục tấn công kẻ địch trong phạm vi nhỏ phía trước, gây tổng cộng sum(*d,*d,*d,*d,*d) điểm Sát Thương Vật Lý và liên tục <HyperLink stylename=\"M_Link\" u=\"2\">Ngắt</> quái địch. Đòn cuối gây *d điểm Sát Thương Vật Lý, <HyperLink stylename=\"M_Link\" u=\"2\">Đẩy Lùi</> quái địch, đồng thời triệu hồi hư ảnh Cự Nhân spellfielddisc(*id). Kỹ năng này gây thêm <HighLight>10%</> sát thương lên kẻ địch ở trạng thái <HighLight>Suy Bại</>. Sau khi thi triển nhận 4 <HighLight>Dấu Ấn Hoàng Hôn</>. <FaintYellow>Dấu Ấn Hoàng Hôn</> Cường hóa <HighLight>Kỹ Năng Kết Liễu</> và <HighLight>Nộ Ý Kích</>, tối đa giữ 6 dấu.",
      [285943353399296] = "Biến thành Cự Nhân và nhận <HyperLink stylename=\"M_Link\" u=\"1\">Vô Địch</> ngắn, xóa tối đa 3 <HyperLink stylename=\"M_Link\" u=\"4\">Trạng Thái Bất Lợi</>, triển khai <HighLight>Lĩnh Vực Hoàng Hôn</>; gây tổng cộng sum(*d,*d,*d,*d,*d) sát thương lên kẻ địch xung quanh và khi biến thân kết thúc gây *d sát thương lên kẻ địch trong phạm vi. Trong lúc thi triển có thể di chuyển; bản thân buffdisc(*id), buffdisc(*id). <FaintYellow>Lĩnh Vực Hoàng Hôn</> Liên tục áp dụng Giảm Tốc lên kẻ địch trong lĩnh vực.",
      [285943353399808] = "Triển khai Lĩnh Vực Hoàng Hôn di chuyển theo bản thân, khiến kẻ địch trong phạm vi liên tục chịu <HyperLink stylename=\"M_Link\" u=\"6\">Trì Trệ</>.",
      [285943353400064] = "Khi ở <HighLight>Tư Thế Tấn Công</>, buffdisc(*id). Khi ở <HighLight>Tư Thế Phòng Thủ</>, buffdisc(*id). Khi dùng Tư Thế Phòng Thủ trong <HyperLink stylename=\"M_Link\" u=\"26\">chế độ thi đấu chỉ định</>, hai thuộc tính Giảm Thương và Giảm Sát Thương được điều chỉnh động theo số người chơi địch xung quanh: Giảm Thương tối thiểu 2%, tối đa 15%; Giảm Sát Thương tối thiểu 15%, tối đa 25%. Càng nhiều người chơi địch, Giảm Thương và Giảm Sát Thương của bản thân càng cao; các thuộc tính bị động khác không đổi.",
      [285943353401344] = "Dựa vào căn nguyên huyết mạch Cự Nhân Hoàng Hôn, ngưng tụ sức mạnh, giậm mạnh xuống đất tạo chấn động, hất bụi quanh người tạo màn che thị giác ngắn. Bản thân nhận Vũ Lực +1.",
      [285943353401600] = "Sức mạnh hữu hình, ngưng hình thành ảnh. Mượn huyết mạch Cự Nhân Hoàng Hôn để tích lực cho tư thế tấn công sắp thi triển và cụ hiện quỹ đạo chiêu thức. Khi phát lực tấn công, quỹ đạo hình thành sẽ hóa thành tàn ảnh theo động tác. Bản thân nhận Mị Lực +3, Trực Giác +1.",
      [285943353402368] = "Dẫn huyết mạch Cự Nhân Hoàng Hôn làm lực, lấy thiên phú Bậc Thầy Vũ Khí làm kỹ, ngưng tụ sức mạnh Phi Phàm để triệu hồi hình thái thực thể của cự kiếm và song kiếm tương ứng. Bản thân nhận Trực Giác +4, Vũ Lực +2.",
      [285943353402624] = "Dùng Vu Thuật tấn công kẻ địch trong phạm vi nhỏ theo chuỗi 3 giai đoạn, lần lượt gây spellfielddisc(*id)/spellfielddisc(*id)/bulletdisc(*id) điểm Sát Thương Phép và <HyperLink stylename=\"M_Link\" u=\"2\">Ngắt</> quái địch; khi trúng nhận <HighLight>6</>/<HighLight>5</>/<HighLight>13</> điểm <HighLight>Tri Thức Thần Bí</>. Khi bản thân có <HighLight>Quán Chú Tri Thức</>, kỹ năng này nhận <HighLight>Cường Hóa</>. <FaintYellow>Cường Hóa</>: Ngưng tụ 3 Thương Longinus ném vào khu vực chỉ định, gây spellfielddisc(*id)+spellfielddisc(*id)+spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch trong phạm vi nhỏ, thêm mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</> trong *f giây và có <HighLight>50%</> xác suất cơ bản gây <HighLight>Giảm Tốc 50%</> trong <HighLight>3</> giây. Đồng thời nhận 20 điểm <HighLight>Tri Thức Thần Bí</>. <FaintYellow>Tri Thức Thần Bí</>: Tối đa 100 điểm. Khi đạt 100 điểm, mở khóa <HighLight>Kỹ Năng Kết Liễu-Tin Tuyến</>.",
      [285943353404160] = "Ngưng tụ Thương Longinus ném vào khu vực chỉ định, gây spellfielddisc(*id)+spellfielddisc(*id)+spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch trong phạm vi nhỏ, thêm mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</> trong *f giây và có <HighLight>50%</> xác suất cơ bản gây <HighLight>Giảm Tốc 50%</> trong <HighLight>3</> giây. Đồng thời nhận 20 điểm <HighLight>Tri Thức Thần Bí</>. <FaintYellow>Tri Thức Thần Bí</>: Tối đa 100 điểm. Khi đạt 100 điểm, mở khóa <HighLight>Kỹ Năng Kết Liễu-Tin Tuyến</>.",
      [285943353404416] = "Gây *d điểm Sát Thương Phép lên mục tiêu khóa; bản thân nhận <HighLight>Quán Chú Tri Thức</> và buffdisc(*id) trong *d giây. Sau khi thi triển nhận 20 điểm <HighLight>Tri Thức Thần Bí</>. <FaintYellow>Quán Chú Tri Thức</>: <HighLight>Cường Hóa</> lần <HighLight>Vu Thuật</> (đánh thường) kế tiếp. <HighLight>Cường Hóa</> 2 lần thi triển tiếp theo của <HighLight>Quang Khúc</>, <HighLight>Tinh Sa</> hoặc <HighLight>Lao Lung Tinh Quang</>; một lần <HighLight>Quán Chú Tri Thức</> chỉ có thể cường hóa cùng một kỹ năng tối đa 1 lần. <FaintYellow>Tri Thức Thần Bí</>: Tối đa 100 điểm. Khi đạt 100 điểm, mở khóa <HighLight>Kỹ Năng Kết Liễu-Tin Tuyến</>.",
      [285943353404672] = "Bắn tia sáng vào mục tiêu khóa, gây *d điểm Sát Thương Phép. Tia sáng khúc xạ sang mục tiêu địch xung quanh tối đa <HighLight>3</> lần; mỗi lần khúc xạ làm sát thương lên mục tiêu kế tiếp giảm <HighLight>5%</>. Tia sáng có <HighLight>60%</> xác suất cơ bản gây <HighLight>0.7</> giây <HyperLink stylename=\"M_Link\" u=\"6\">Trì Trệ</> lên mục tiêu trúng; nếu chỉ trúng một mục tiêu, sát thương tăng thành *d điểm. Sau khi thi triển nhận 20 điểm <HighLight>Tri Thức Thần Bí</>. Khi có <HighLight>Quán Chú Tri Thức</>, kỹ năng nhận <HighLight>Cường Hóa</>. <FaintYellow>Cường Hóa</>: Giá trị sát thương cơ bản tăng thành *d điểm; số lần khúc xạ +1 và sát thương không còn suy giảm khi khúc xạ; nếu chỉ trúng một mục tiêu, sát thương tăng thành *d điểm. Khiến tất cả mục tiêu trúng buffdisc(*id) điểm trong <HighLight>3.5</> giây; có <HighLight>70%</> xác suất cơ bản giảm <HighLight>50%</> Tốc Độ Di Chuyển trong <HighLight>2.5</> giây. Sau khi thi triển nhận thêm 5 điểm <HighLight>Tri Thức Thần Bí</>. Dùng <HighLight>Quang Khúc</> không cường hóa sẽ hoàn trả <HighLight>2</> giây hồi chiêu. <FaintYellow>Tri Thức Thần Bí</>: Tối đa 100 điểm. Khi đạt 100 điểm, mở khóa <HighLight>Kỹ Năng Kết Liễu-Tin Tuyến</>.",
      [285943353406208] = "Rải Tinh Sa xuống khu vực mục tiêu, gây spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch trong phạm vi và khiến chúng buffdisc(*id) trong 10 giây. Sau khi thi triển nhận 20 điểm <HighLight>Tri Thức Thần Bí</>. Khi có <HighLight>Quán Chú Tri Thức</>, kỹ năng nhận <HighLight>Cường Hóa</>. <FaintYellow>Cường Hóa</>: Sau hiệu ứng ban đầu, Tinh Sa tiếp tục tồn tại; mỗi <HighLight>0.7</> giây gây spellfielddisc(*id) điểm Sát Thương Phép và có <HighLight>90%</> xác suất cơ bản thêm 1 tầng <HighLight>buffname(*id)</> trong <HighLight>2</> giây, tổng cộng <HighLight>3</> lần; cuối cùng <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</> quái địch trong phạm vi và gây spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch. Mỗi tầng <HighLight>buffname(*id)</> trên kẻ địch làm sát thương này tăng <HighLight>10%</>. <FaintYellow>buffname(*id)</>: Tối đa <HighLight>3</> tầng, buffdisc(*id). <FaintYellow>Tri Thức Thần Bí</>: Tối đa 100 điểm. Khi đạt 100 điểm, mở khóa <HighLight>Kỹ Năng Kết Liễu-Tin Tuyến</>.",
      [285943353406720] = "Triệu hồi Lao Lung Tinh Quang, gây *d điểm Sát Thương Phép lên mục tiêu khóa và <HighLight>69%</> xác suất cơ bản trong <HighLight>1.71</> giây <HyperLink stylename=\"M_Link\" u=\"6\">Choáng</>. Sau khi thi triển nhận 20 điểm <HighLight>Tri Thức Thần Bí</>. Khi có <HighLight>Quán Chú Tri Thức</>, kỹ năng nhận <HighLight>Cường Hóa</>. <FaintYellow>Cường Hóa</>: Đổi thành gây spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch trong phạm vi quanh mục tiêu khóa, với <HighLight>86%</> xác suất cơ bản trong <HighLight>1.71</> giây <HyperLink stylename=\"M_Link\" u=\"7\">Trói Buộc</> và <HighLight>86%</> xác suất cơ bản giảm Tốc Độ Di Chuyển <HighLight>50%</>; riêng mục tiêu khóa chịu thêm <HighLight>69%</> xác suất cơ bản trong <HighLight>1.71</> giây <HyperLink stylename=\"M_Link\" u=\"6\">Choáng</>. <FaintYellow>Tri Thức Thần Bí</>: Tối đa 100 điểm. Khi đạt 100 điểm, mở khóa <HighLight>Kỹ Năng Kết Liễu-Tin Tuyến</>.",
      [285943353407488] = "Triển khai Hoàng Y, nhận <HighLight>2.5</> giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</> và buffdisc(*id) (khiên này được cộng thêm từ Máu tối đa của bản thân), kéo dài <HighLight>15</> giây. Khi khiên biến mất hoặc bị phá, gây Sát Thương Phép lên kẻ địch xung quanh với giá trị cơ bản bằng <HighLight>5</> lần lượng sát thương khiên đã hấp thụ, tối đa không quá spellfielddisc(*id) điểm; sát thương được chia cho kẻ địch trong phạm vi. Sau khi thi triển nhận 20 điểm <HighLight>Tri Thức Thần Bí</>. <FaintYellow>Tri Thức Thần Bí</>: Tối đa 100 điểm. Khi đạt 100 điểm, mở khóa <HighLight>Kỹ Năng Kết Liễu-Tin Tuyến</>.",
      [285943353407744] = "Gây spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch xung quanh và <HyperLink stylename=\"M_Link\" u=\"2\">Đẩy Lùi</> chúng; xóa spellfielddisc(*id) điểm khiên của kẻ địch và thêm mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</> trong *f giây. Trong <HighLight>5</> giây sau khi thi triển có thể tung liên chiêu, khiến bản thân nhanh chóng lùi về sau. Sau khi thi triển nhận 20 điểm <HighLight>Tri Thức Thần Bí</>. <FaintYellow>Tri Thức Thần Bí</>: Tối đa 100 điểm. Khi đạt 100 điểm, mở khóa <HighLight>Kỹ Năng Kết Liễu-Tin Tuyến</>.",
      [285943353408256] = "Triệu hồi một Ảo Tượng Thần Bí không thể bị khóa mục tiêu hoặc tấn công, kéo dài <HighLight>10</> giây. Sau khi thi triển nhận 20 điểm <HighLight>Tri Thức Thần Bí</>. Ảo tượng liên tục dùng <HighLight>Vu Thuật</> (đánh thường) tấn công kẻ địch; mỗi chuỗi lần lượt gây spellfielddisc(*id)/spellfielddisc(*id)/bulletdisc(*id) điểm Sát Thương Phép, lặp 3 lần. Trong thời gian Ảo Tượng Thần Bí tồn tại, có thể tung liên chiêu để đổi vị trí với ảo tượng; mỗi lần dùng kỹ năng tối đa đổi vị trí 1 lần. <FaintYellow>Tri Thức Thần Bí</>: Tối đa 100 điểm. Khi đạt 100 điểm, mở khóa <HighLight>Kỹ Năng Kết Liễu-Tin Tuyến</>.",
      [285943353409536] = "Triển khai Kỳ Nguyệt; bản thân nhận <HighLight>3</> giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>, sau *f giây gây *d điểm Sát Thương Phép lên kẻ địch xung quanh và với *f** xác suất cơ bản <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</> chúng; đồng thời giảm <HighLight>3</> giây hồi chiêu của toàn bộ <HighLight>Kỹ Năng Nghề Nghiệp</>. Trong thời gian này bản thân có thể di chuyển. Sau khi thi triển nhận 20 điểm <HighLight>Tri Thức Thần Bí</>. <FaintYellow>Tri Thức Thần Bí</>: Tối đa 100 điểm. Khi đạt 100 điểm, mở khóa <HighLight>Kỹ Năng Kết Liễu-Tin Tuyến</>.",
      [285943353409792] = "Giải trừ <HyperLink stylename=\"M_Link\" u=\"3\">Hiệu Ứng Khống Chế</> đang chịu, nhận buffdisc(*id) và hiệu ứng buffdisc(*id) trong <HighLight>4</> giây, đồng thời vào <HighLight>Trạng Thái Tinh Quang</> trong <HighLight>4</> giây. <FaintYellow>Trạng Thái Tinh Quang</>: buffdisc(*id); khi di chuyển để lại Con Đường Tinh Huy, kẻ địch đứng trên đó buffdisc(*id). Chủ động dùng kỹ năng sẽ thoát <HighLight>Trạng Thái Tinh Quang</>. Khi thoát <HighLight>Trạng Thái Tinh Quang</> do hết thời gian hoặc dùng kỹ năng, gây spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch xung quanh và <HyperLink stylename=\"M_Link\" u=\"2\">Đẩy Lùi</> chúng.",
      [285943353410048] = "Có thể dùng khi sở hữu 100 điểm <HighLight>Tri Thức Thần Bí</>. Khiến bản thân buffdisc(*id) trong *d giây và triệu hồi Tin Tuyến tại vị trí mục tiêu khóa. Tin Tuyến truy đuổi mục tiêu địch với tốc độ nhất định, mỗi giây tối đa gây *d điểm Sát Thương Phép lên 4 mục tiêu địch trong phạm vi; mỗi lần tấn công tiêu hao 20 điểm <HighLight>Tri Thức Thần Bí</>, tự dừng khi không đủ <HighLight>Tri Thức Thần Bí</>. Sau khi Tin Tuyến hoạt động 5 giây, mỗi lần tấn công tăng thêm 10 điểm tiêu hao <HighLight>Tri Thức Thần Bí</>; khi tiêu hao <HighLight>30</>/<HighLight>40</>/<HighLight>50</>/<HighLight>60</>/<HighLight>70</> điểm <HighLight>Tri Thức Thần Bí</>, sát thương tăng thành spellfielddisc(*id)/spellfielddisc(*id)/spellfielddisc(*id)/spellfielddisc(*id)/spellfielddisc(*id) điểm. Nếu số lần tấn công trước khi Tin Tuyến tự dừng là <HighLight>7</>/<HighLight>8</>/<HighLight>9</> lần, khi kết thúc gây spellfielddisc(*id)/spellfielddisc(*id)/spellfielddisc(*id) điểm Sát Thương Phép lên kẻ địch trong phạm vi và có <HighLight>91%</> xác suất cơ bản <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</> tối đa 2 kẻ địch trong phạm vi.",
      [285943353411072] = "Điều động sức mạnh Tinh Giới xung quanh để phác họa tinh đồ thần bí, thắp sáng bầu trời và triệu hồi cột sáng tinh tú tại vị trí mục tiêu, gây sát thương phạm vi. <FaintYellow>Lời Nguyền Tinh Thực</> Kẻ địch trúng bị giảm lượng trị liệu nhận được. <FaintYellow>Chỉ Dẫn Tinh Giới</> Sau khi dùng Tinh Khung Tài Quyết, bản thân nhận Chỉ Dẫn Tinh Giới, giảm sát thương nhận vào trong 15 giây.",
      [285943353411328] = "Dòm ngó bí mật của kẻ địch. Nếu kỹ năng giải khống chế của kẻ địch đang hồi chiêu, kéo dài hồi chiêu thêm 15 giây; nếu chưa hồi chiêu, khiến kỹ năng đó vào hồi chiêu 5 giây.",
      [285943353411584] = "Mỗi lần dùng đánh thường có <HighLight>5%</> xác suất, dùng kỹ năng chiến đấu có <HighLight>15%</> xác suất bắn Xoáy Tri Thức theo hướng bản thân đang nhìn, gây *d điểm Sát Thương Phép lên kẻ địch trên đường và thêm mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</> trong *f giây. Nếu sau khi dùng đánh thường hoặc kỹ năng không kích hoạt Xoáy Tri Thức, xác suất sẽ cộng dồn.",
      [285943353412352] = "Dùng Con Mắt Dòm Bí để bắt lấy tri thức vô hình trong môi trường xung quanh, ngưng tụ thành một tờ giấy thần bí mang thông tin. Khi mở ra, trên giấy hiện một ít thông tin; sau khi đọc, tờ giấy sẽ tiêu tán theo linh tính. Khi dòm ngó thần bí, cũng phải nhớ giữ bí mật. Bản thân nhận Học Thức +1.",
      [285943353412608] = "Điều động khả năng cảm nhận tri thức, phân giải và dung hợp kỹ xảo chiến đấu đã nghiên cứu; thông qua trải nghiệm thế khởi thủ để cảm nhận sâu tinh túy võ học. Khi tấn công lần nữa sẽ để lại một tàn ảnh chiến đấu bắt nguồn từ tri thức. Sau khi hấp thu tàn ảnh, nhận Vũ Lực +3, Trực Giác +1.",
      [285943353412864] = "Điều động khả năng cảm nhận tri thức, phân giải và dung hợp kỹ xảo chiến đấu đã nghiên cứu; thông qua trải nghiệm thế khởi thủ để đào sâu tinh túy võ học. Khi tấn công lần nữa sẽ để lại một tàn ảnh chiến đấu bắt nguồn từ tri thức. Sau khi hấp thu tàn ảnh, nhận Vũ Lực +3, Trực Giác +1.",
      [285943353413376] = "Dùng linh tính thăm dò thần bí, cảm nhận dòng thông tin vô hình xung quanh. Dựa vào trí óc và tri thức để phân tích, nghiên cứu, học tập; triển khai pháp trận với tư thái Phù Thủy, nhập vai sâu năng lực Bậc để tăng tốc tiêu hóa ma dược. Trong lúc thi triển, người chơi xung quanh đều có thể nhận kỹ năng tạm thời; dùng kỹ năng tạm thời để lấy một tờ giấy ghi tri thức bí ẩn. Bản thân nhận Trực Giác +4, Học Thức +2. Người dùng kỹ năng tạm thời cũng nhận Trực Giác +4, Học Thức +2.",
      [285943353415424] = "Trong 30 giây, kích thước cơ thể tăng 1.5 lần.",
      [285943353415680] = "Cầm đuốc trong 30 giây.",
      [285943353415936] = "Biểu diễn Hoa Nhài Nhỏ Quê Nhà.",
      [285943353416192] = "Kích hoạt Thánh Huy Mặt Trời, khiến người chơi xung quanh không nhịn được mà bước vào trạng thái tán tụng Mặt Trời.",
      [285943353416448] = "Kết Toán Hitbox Di Chuyển",
      [285943353416960] = "Dịch chuyển tới phòng nghỉ của Công Ty An Ninh Blackthorn.",
      [285943353417216] = "Chơi xích đu.",
      [285943353417472] = "Biến thành Voi Con.",
      [285943353417728] = "Giải trừ trạng thái biến hình hiện tại.",
      [285943353417984] = "Cầu Vồng!",
      [285943353418240] = "Biến thành U Ảnh.",
      [285943353418752] = "Cảm nhận luồng gió lạnh thấu xương.",
      [285943353419008] = "Biến thành Kỵ Binh.",
      [285943353419520] = "Vì vinh quang gia tộc, tiến lên!",
      [285943353419776] = "Biến thành Khỉ Đầu Chó Lông Xoăn.",
      [285943353420288] = "Ngồi xuống tại chỗ",
      [285943353420544] = "Vỗ ngực",
      [285943353420800] = "Hoan Hô",
      [285943353421056] = "Quay Vòng Quay Lớn.",
      [285943353421568] = "Vòng Quay Lớn-Kết Toán Vua.",
      [285943353421824] = "Vòng Quay Lớn-Kết Toán Bích.",
      [285943353422080] = "Vòng Quay Lớn-Kết Toán Rô.",
      [285943353422336] = "Vòng Quay Lớn-Kết Toán Tép.",
      [285943353422592] = "Vòng Quay Lớn-Kết Toán Cơ.",
      [285943353422848] = "Triệu hồi Thần Quốc Giáng Lâm.",
      [285943353423360] = "Hồi 100 điểm SAN cho đồng minh trong bán kính 30m quanh bản thân; ngẫu nhiên tăng Học Thức, Mị Lực, Vũ Lực, Trực Giác và thêm <HighLight>Thể Phách Rồng</> cùng <HighLight>Nộ Ý Rồng</> trong <HighLight>1800</> giây. <HighLight>Thể Phách Rồng</>: Tăng toàn bộ 5 thuộc tính, hiệu quả tương đương Tinh Túy Đỏ Thẫm cấp cao nhất hiện có, không cộng dồn. <HighLight>Nộ Ý Rồng</>: Tăng Tấn Công và Cường Hóa Kỹ Năng, hiệu quả tương đương Dược Tề Cuồng Bạo cấp cao nhất hiện có, không cộng dồn.",
      [285943353424128] = "Sương Lộ Thất Thần.",
      [285943353424384] = "Phế Dịch Luyện Dược.",
      [285943353424640] = "Hồi Âm Vực Sâu.",
      [285943353425152] = "Hát Nhảy Rap Bóng Rổ.",
      [285943353425408] = "Thiết Sơn Kháo.",
      [285943353425664] = "Khe nứt nuốt trọn tầm nhìn, cũng là khởi điểm để quân lâm thế giới. Thay đổi bầu trời của đại thế giới nơi bản thân đang ở trong 5 phút, đồng thời triệu hồi lối vào <HighLight>“Điện Danh Lưu”</> trong 30 phút.",
      [285943353434624] = "Ngắm kẻ địch rồi bắn, gây sát thương bắn cao hơn.",
      [285943353436928] = "Bắn chỉ thiên cảnh báo.",
      [285943890183936] = "Gây sát thương lên mục tiêu khóa.",
      [285943890184960] = "【Chế Độ Cần Phải 4】Tấn công kẻ địch trong phạm vi chữ nhật phía trước.",
      [285943890185216] = "【Chế Độ Cần Phải 3】Lấy bản thân làm tâm, gây hiệu ứng lên vùng hình quạt phía trước và tung kỹ năng liên kích; hoàn tất liên kích sẽ vào hồi chiêu.",
      [285943890185472] = "【Chế Độ Cần Phải 3】Liên kích của kỹ năng Mẫu 7; lấy bản thân làm tâm, gây hiệu ứng lên vùng hình quạt phía trước và Hất Tung.",
      [285943890185728] = "Khóa mục tiêu; nếu khoảng cách tới mục tiêu không quá 2000, bắn đạn vào mục tiêu; một số kỹ năng có thể hủy hậu diêu.",
      [285943890185984] = "Gây nhiều lần sát thương lên kẻ địch tại vị trí mục tiêu.",
      [285943890187520] = "Định Thân vĩnh viễn toàn bộ kẻ địch thường trong phạm vi 40 yard.",
      [285943890187776] = "Trong chiến đấu, biến thành liệt diễm và gây sát thương lớn lên kẻ địch bị thiêu trúng.",
      [285943890189056] = "Cho phép cưỡi tọa kỵ trong chiến đấu và gây sát thương lên mục tiêu va phải.",
      [285943890189312] = "Biến thành một sinh vật vô hại, lập tức vào trạng thái giả chết.",
      [285943890190592] = "Nắm chặt trường kích, xoay người liên tục chém phía trước rồi dốc sức đâm trường kích, gây sát thương và nhận Nhật Năng (dùng để mở khóa Trừng Phạt và Vô Ám Thương). Trong trạng thái Liệt Dương, nhảy tới trước mặt kẻ địch rồi toàn lực chém về trước, gây sát thương và nhận Nhật Năng (dùng để mở khóa Trừng Phạt và Vô Ám Thương).",
      [285943890191616] = "Nhấc gối bước tới, thuận thế vung trường kích chém phía trước, gây sát thương lên kẻ địch trước mặt, Tịnh Hóa kẻ địch đang ở trạng thái tiêu tán và nhận Nhật Năng (dùng để mở khóa Trừng Phạt và Vô Ám Thương).",
      [285943890191872] = "Dùng quang huy bùng phát trong cơ thể ngưng tụ 3 rìu ngắn; rìu xoay quanh bản thân liên tục tấn công kẻ địch xung quanh, gây sát thương, Giảm Hồi Phục và Trì Trệ; bản thân liên tục nhận Nhật Năng (dùng để mở khóa Trừng Phạt và Vô Ám Thương).",
      [285943890193408] = "Dựng Nhật Thệ tại vị trí chỉ định và nhận Nhật Năng (dùng để mở khóa Trừng Phạt và Vô Ám Thương); kẻ địch trong phạm vi thệ ước chịu sát thương, Trì Trệ và Trói Buộc.",
      [285943890193664] = "Cúi người cầm kích, lao thẳng vào kẻ địch không gì cản nổi, liên tục Đẩy Lùi mục tiêu và gây sát thương; sau đó tung đòn kết liễu đâm trường kích, Đẩy Lùi và gây sát thương, thêm Giảm Hồi Phục và Trì Trệ; bản thân nhận Nhật Năng (dùng để mở khóa Trừng Phạt và Vô Ám Thương). Nếu mục tiêu Bá Thể, xung phong sẽ dừng.",
      [285943890195712] = "Cúi người cầm kích, lao như lưu quang đâm vào kẻ địch, đâm ngã mục tiêu, thêm Giảm Hồi Phục và Trì Trệ; bản thân nhận Nhật Năng (dùng để mở khóa Trừng Phạt và Vô Ám Thương).",
      [285943890195968] = "Tiêu hao toàn bộ Nhật Năng, ngưng tụ Vô Ám Thương ném vào kẻ địch. Sát thương tăng mạnh theo lượng Nhật Năng tiêu hao, tăng thêm sát thương lên người chơi địch ít Máu và Tịnh Hóa người chơi địch bị hạ gục. Hạ gục người chơi sẽ đặt lại hồi chiêu. Trong trạng thái Liệt Dương, uy lực tăng; tiêu hao một tỷ lệ Máu hiện tại của bản thân để gây thêm sát thương.",
      [285943890196736] = "Triệu hồi Thánh Quang cường hóa bản thân, nhận lượng lớn Nhật Năng (dùng để mở khóa Trừng Phạt và Vô Ám Thương) cùng hiệu ứng Tăng Thương.",
      [285943890197248] = "Thánh Diễm bao phủ, nhận Nhật Năng (dùng để mở khóa Trừng Phạt và Vô Ám Thương), Tịnh Hóa kẻ địch đang tiêu tán quanh bản thân và gây sát thương.",
      [285943890198016] = "Ngưng tụ giáp bằng ánh vàng để bảo hộ bản thân, tăng Đỡ Đòn và nhận Nhật Năng (dùng để mở khóa Trừng Phạt và Vô Ám Thương); dùng liên chiêu giai đoạn hai để giải khống chế.",
      [285943890199296] = "Tiêu hao 3 điểm Nhật Năng ngưng tụ cự chùy, dốc sức nện về phía trước, gây lượng lớn sát thương lên kẻ địch trong phạm vi. Trong trạng thái Liệt Dương được cường hóa, tăng phạm vi và sát thương.",
      [285943890200064] = "Dùng Công Chứng Vô Hiệu để vô hiệu hóa khống chế đang chịu và nhận tăng cường; hồi Máu, nhận Bá Thể và Giảm Thương, đồng thời gây sát thương lên kẻ địch xung quanh.",
      [285943890200576] = "Vào trạng thái Liệt Dương, tăng Tốc Độ Di Chuyển và hiệu suất nhận Nhật Năng (dùng để mở khóa Trừng Phạt và Vô Ám Thương) trong 8 giây; đồng thời Bá Thể trong 6 giây. Hiệu ứng bị động Liệt Linh kích hoạt 1 lần mỗi 120 giây: sau khi chịu sát thương chí mạng, giải khống chế và nhận 4 giây Vô Địch, Tăng Thương cao cùng Nhật Năng; trong thời gian này hồi chiêu Vô Ám Thương bằng 0, lượng trị liệu nhận giảm và bản thân hồi Máu theo số kẻ địch hạ gục.",
      [285943890201088] = "Dùng ánh sáng thuần trắng hủy diệt cường địch; quang mang nóng rực giáng xuống như sét, đánh mục tiêu nhiều lần, sát thương mỗi lần tăng dần.",
      [285943890201600] = "Lập chuẩn tắc chính nghĩa và hành động theo chính nghĩa, mở thêm cách nhận năng lượng. Khi dùng Trừng Phạt và Vô Ám Thương, bản thân cộng dồn Thẩm Phán (Thẩm Phán Chính Nghĩa), tăng sát thương của hai kỹ năng. Trong trạng thái Liệt Dương, dùng kỹ năng chiến đấu cũng cộng dồn Thẩm Phán. Hạ gục, Tịnh Hóa hoặc hỗ trợ hạ gục người chơi địch đều nhận Nhật Năng.",
      [285943890201856] = "Lập chuẩn tắc chính nghĩa, trừng phạt Dị Đoan bội thệ. Khi Trừng Phạt và Vô Ám Thương trúng kẻ địch, áp dụng dấu ấn Dị Đoan khiến mục tiêu nhận thêm sát thương từ Ca Tụng Giả. Trong trạng thái Liệt Dương, kỹ năng chiến đấu trúng cũng áp dụng dấu ấn Dị Đoan.",
      [285943890202112] = "Tán tụng Vĩnh Hằng Liệt Dương vĩ đại, Thần Mặt Trời, đấng ban tặng ánh sáng và sinh mệnh.",
      [285943890202624] = "Đọc câu cầu nguyện ngắn liên quan đến Mặt Trời để chúc phúc đồng hành, dẫn Thánh Quang tạo thành chùm sáng lơ lửng liên tục, ban Bảo Hộ.",
      [285943890202880] = "Thông qua lời cầu nguyện hết lòng thành kính để thu hút ánh nhìn của thần linh, cầu xin một đạo Thánh Quang bao phủ bản thân, Tịnh Hóa ô uế bám vào linh tính và hồi phục hao tổn tinh thần do chiến đấu.",
      [285943890203136] = "Ban cho đồng đội năng lực Tịnh Hóa.",
      [285943890203392] = "Nhận trạng thái; khi kết thúc gây sát thương lên xung quanh.",
      [285943890203904] = "Phóng năng lượng tinh thần xung kích kẻ địch, gây sát thương đơn mục tiêu.",
      [285943890204672] = "Xoa dịu tâm linh của mục tiêu đồng minh, hồi một lượng Máu cho mục tiêu.",
      [285943890205440] = "Nhìn thấu và lợi dụng sơ hở tâm linh của kẻ địch, gây sát thương phạm vi và thêm trạng thái Tăng Thương.",
      [285943890205696] = "Phát tán Ôn Dịch Tinh Thần tại khu vực mục tiêu, gây sát thương và lây nhiễm đơn vị địch trong phạm vi.",
      [285943890206464] = "Tạo Lĩnh Vực Mộng Cảnh yên bình, liên tục hồi Máu cho đồng minh trong lĩnh vực và tăng Giảm Thương của đồng minh bên trong.",
      [285943890207488] = "Dùng Long Uy chấn nhiếp kẻ địch trong phạm vi, gây lượng lớn sát thương và Hất Tung quái đang ở trạng thái Ôn Dịch.",
      [285943890208000] = "Dẫn năng lượng tinh thần bình tĩnh, trầm ổn truyền giữa đồng đội, hồi Máu cho đồng đội mà năng lượng truyền tới.",
      [285943890208256] = "Dệt Lĩnh Vực Mộng Cảnh hỗn loạn tại khu vực mục tiêu, liên tục gây sát thương lên kẻ địch trong lĩnh vực.",
      [285943890209024] = "Áp dụng Ám Thị tích cực lên mục tiêu, lập tức hồi lượng lớn Máu và cho mục tiêu Giảm Thương ngắn.",
      [285943890209280] = "Phóng xung kích tâm linh mãnh liệt về phía trước, gây lượng lớn sát thương, Giảm Tốc và Giảm Hồi Phục.",
      [285943890209792] = "Liên tục ám thị tích cực tiềm thức của bản thân và đồng đội, nhận Giảm Thương, Bá Thể và liên tục trị liệu đồng minh xung quanh.",
      [285943890210560] = "Đọc, phân tích và liên tục bảo vệ tâm trí mục tiêu, trị liệu bổ sung và cung cấp khiên khi mục tiêu ít Máu.",
      [285943890210816] = "Trong thời gian ngắn, phân tích và bảo vệ tâm trí toàn bộ đồng đội, trị liệu bổ sung lượng lớn và cung cấp Súc Thương.",
      [285943890211328] = "Giảm Phòng Thủ của mục tiêu địch và gây sát thương lên mục tiêu.",
      [285943890211584] = "Khiến bản thân khó bị kẻ địch phát hiện, giải trừ khống chế đang chịu, vào Bá Thể, nhận Giảm Thương, tăng trị liệu nhận vào và Tăng Tốc.",
      [285943890211840] = "Phóng Linh Hoả về phía trước và để lại vùng lửa, gây sát thương phạm vi, Giảm Hồi Phục, Trói Buộc và Thôi Miên mục tiêu.",
      [285943890212608] = "Liên tục Trị Liệu Tâm Lý cho đồng minh xung quanh, hồi Máu cho họ.",
      [285943890213376] = "Ẩn vào Hải Dương Tiềm Thức, giải trừ khống chế của bản thân, triệu hồi Cự Long lượn quanh khu vực mục tiêu, hồi phục đồng minh trong phạm vi.",
      [285943890213632] = "Giải trừ lĩnh vực và lập tức hồi Máu.",
      [285943890214400] = "Đánh Thức đồng đội đang tiêu tán khỏi mộng cảnh và hồi 50% Máu cho họ.",
      [285943890214912] = "Đánh Thức bản thân khỏi mộng cảnh và hồi 50% Máu.",
      [285943890215168] = "Tư Thế Không Tưởng thiên về trị liệu: khi chịu khống chế, bản thân hồi Máu, nhưng sát thương bản thân gây ra giảm mạnh.",
      [285943890215424] = "Tư Thế Ác Mộng thiên về chiến đấu: khi kỹ năng chiến đấu gây sát thương, trị liệu bản thân, nhưng trị liệu bản thân áp dụng giảm mạnh.",
      [285943890215936] = "Quan sát cảm xúc tâm linh phản ánh qua hành vi, cử chỉ của mục tiêu, ngưng tụ một điểm sáng màu quanh mục tiêu, phản ánh tâm trạng cốt lõi bề mặt của đối phương trong ngày. ▸Đỏ: Nhiệt Tình ▸Vàng: Thư Giãn ▸Trắng: Bình Thản ▸Xám: U Sầu ▸Đen: Bi Thương",
      [285943890216192] = "Kết hợp sức mạnh thần bí học để đọc suy nghĩ nội tâm của mục tiêu và áp dụng ám thị mà không bị phát hiện.",
      [285943890216448] = "Thông qua sự an ủi của bác sĩ tâm lý, ngẫu nhiên chuyển cảm xúc tiêu cực hoặc trung tính của mục tiêu thành cảm xúc tích cực; cảm xúc mới hiển thị bằng điểm màu tương ứng trong một khoảng thời gian.",
      [285943890216704] = "Dùng ám thị gây hiểu lầm lên một người chơi địch, khiến họ Tinh Thần Rối Loạn.",
      [285943890216960] = "Phóng lá bài tấn công mục tiêu. Sau mỗi 4 lần kỹ năng này gây sát thương, nhận 1 lá bài cùng loại với lá bài trước đó bản thân nhận được (dùng để mở khóa Kỹ Năng Kết Liễu).",
      [285943890217984] = "Nhanh chóng ném nhiều lá bài về phía trước gây sát thương phạm vi; kỹ năng có 3 giai đoạn. Giai đoạn đầu cho bản thân hiệu ứng Xuyên Thứ; giai đoạn ba Đẩy Lùi kẻ địch, gây Giảm Hồi Phục và thêm Dấu Ấn Ngu Lộng gây sát thương bổ sung, đồng thời bản thân nhận 1 Thẻ Vàng Vận Mệnh (dùng để mở khóa Kỹ Năng Kết Liễu).",
      [285943890218752] = "Ném một lá Tarot vào kẻ địch, triển khai trận Tarot liên tục gây sát thương; khi kết thúc Hất Tung mục tiêu quái. Bản thân nhận 1 lá bài cùng loại với lá bài trước đó đã nhận (dùng để mở khóa Kỹ Năng Kết Liễu) và hiệu ứng bổ sung tương ứng.",
      [285943890219264] = "Duy trì di chuyển và liên tục bắn nhiều Đạn Khí vào kẻ địch; bản thân nhận 1 Thẻ Lam Linh Tính và 1 điểm Năng Lượng Lá Bài (dùng để mở khóa Kỹ Năng Kết Liễu).",
      [285943890219776] = "Điều khiển Sợi Tơ Linh Thể của kẻ địch, khống chế mục tiêu, gây sát thương và Giảm Tốc.",
      [285943890220032] = "Mượn sức mạnh từ lịch sử, lập tức nạp đầy Năng Lượng Lá Bài và nhận lá bài tùy theo số bài bản thân đang có (dùng để mở khóa Kỹ Năng Kết Liễu).",
      [285943890220288] = "Tán tụng Kẻ Khờ; trong 10 giây tăng sát thương bản thân, nhận 1 Thẻ Lam Linh Tính và 1 điểm Năng Lượng Lá Bài (dùng để mở khóa Kỹ Năng Kết Liễu).",
      [285943890220544] = "Đốt mốc lửa đã chuẩn bị, giải trừ khống chế đang chịu, nhận Bá Thể và Giảm Thương, dịch chuyển tức thời đến vị trí chỉ định và gây sát thương phạm vi; dùng lại trong 3 giây để trở về vị trí ban đầu.",
      [285943890221312] = "Kỳ tích giáng mưa bài tại vị trí mục tiêu, gây sát thương, Giảm Tốc và Choáng kẻ địch; người chơi chịu thêm Giảm Hồi Phục. Bản thân nhận 1 lá bài cùng loại với lá bài trước đó đã nhận (dùng để mở khóa Kỹ Năng Kết Liễu) và hiệu ứng bổ sung tương ứng.",
      [285943890221824] = "Giải trừ khống chế, để lại một Thế Thân đánh lừa kẻ địch, còn bản thân dịch chuyển tới vị trí mục tiêu.",
      [285943890222848] = "Thu thập Thẻ Vàng Vận Mệnh để mở khóa kỹ năng. Ngu lộng kẻ địch trong phạm vi, gây lượng lớn sát thương; sau đó trong một khoảng thời gian, đòn đánh thường thêm Dấu Ấn Ngu Lộng gây sát thương bổ sung và tăng Tốc Độ Đánh. Sau khi dùng nhận 1 điểm Năng Lượng Lá Bài.",
      [285943890223104] = "Thu thập Thẻ Lam Linh Tính để mở khóa kỹ năng. Giải phóng sức mạnh linh tính, gây lượng lớn sát thương lên kẻ địch trong phạm vi và thêm Tăng Thương; sau khi dùng nhận 1 điểm Năng Lượng Lá Bài.",
      [285943890223360] = "Thu thập Năng Lượng Lá Bài để mở khóa kỹ năng. Quán chú toàn bộ Năng Lượng Lá Bài đã thu thập vào lượng lớn lá bài, liên tục trút những lá bài đầy năng lượng vào kẻ địch, gây sát thương cao; trong lúc thi triển có thể dùng kỹ năng khác và di chuyển.",
      [285943890224640] = "Triệu hồi hình chiếu lịch sử của Bí Cảnh, điều khiển Sợi Tơ Linh Thể của mục tiêu địch, làm chậm mục tiêu và khiến kẻ địch trong phạm vi Trì Trệ, liên tục gây sát thương; sau đó đòn kết liễu gây lượng lớn sát thương, Hất Tung quái và Choáng người chơi. Bản thân nhận 1 lá bài cùng loại với lá bài trước đó đã nhận (dùng để mở khóa Kỹ Năng Kết Liễu).",
      [285943890225408] = "Điều khiển vận mệnh và linh tính, cụ tượng chúng thành lá bài để ngu lộng kẻ địch; thu thập Thẻ Vàng Vận Mệnh và Thẻ Lam Linh Tính để mở khóa Kỹ Năng Kết Liễu Số Mệnh và Linh Bạo; thu thập Năng Lượng Lá Bài để mở khóa Kỹ Năng Kết Liễu Xào Bài.",
      [285943890225664] = "Dựa vào linh tính bản thân và lấy con lắc chứa linh tính tự nhiên làm môi giới, cảm nhận khải thị của vận mệnh. Hướng và tốc độ quay của con lắc tương ứng cường độ chỉ dẫn khác nhau: ▸Quay nhanh theo chiều kim đồng hồ: khẳng định mạnh, phát triển thuận lợi ▸Quay chậm theo chiều kim đồng hồ: khẳng định nhẹ, phát triển bình ổn ▸Quay nhanh ngược chiều kim đồng hồ: phủ định mạnh, rủi ro lớn ▸Quay chậm ngược chiều kim đồng hồ: phủ định nhẹ, có ít trắc trở ▸Đứng yên: không có khải thị rõ ràng, hoặc vận mệnh đang bị can nhiễu",
      [285943890227200] = "Nhờ khả năng phối hợp cơ thể tăng lên từ năng lực Bậc, kiểm soát hành vi và thần thái để trình diễn một màn khoa trương, hài hước vượt xa khả năng người thường.",
      [285943890227712] = "Dựa vào Người Giấy mà Nhà Ảo Thuật chuẩn bị trước và Linh Tính của Bậc, khi điều kiện kích hoạt đặt trước được đáp ứng, khiến mục tiêu biến thành Thế Thân rồi dần tiêu tán, thực hiện màn rời sân không dấu vết. Bản chất là một “màn hạ màn hoàn mỹ” được chuẩn bị từ trước, phù hợp nguyên tắc cốt lõi “Nhà Ảo Thuật không biểu diễn khi chưa chuẩn bị”, dùng để né nguy hiểm hoặc hoàn tất vòng nhập vai.",
      [285943890228480] = "Triệu hồi hình chiếu lịch sử của Bí Cảnh, điều khiển Sợi Tơ Linh Thể của toàn bộ kẻ địch, kéo chúng về tâm và liên tục gây sát thương; sau đó đòn kết liễu gây lượng lớn sát thương và Hất Tung kẻ địch. Bản thân nhận 1 lá bài cùng loại với lá bài trước đó đã nhận (dùng để mở khóa Kỹ Năng Kết Liễu) và hiệu ứng bổ sung tương ứng.",
      [285943890232832] = "Hội tụ Năng Lượng Tinh Không để tung tối đa 4 giai đoạn tấn công. Thu thập Dấu Chân để dùng Tái Hiện Dấu Chân, cường hóa Thiểm Kích, giảm hồi chiêu kỹ năng và áp dụng xác suất Hất Tung cùng Giảm Tốc lên kẻ địch.",
      [285943890235648] = "Dùng trò ảo thuật ngẫu nhiên tấn công kẻ địch tại vị trí mục tiêu và thêm hiệu ứng theo loại trò. Sau khi dùng Không Ngục, kỹ năng này được cường hóa và nhận thêm Năng Lượng Tinh Không.",
      [285943890236160] = "Hóa thành hư ảnh xuyên tới khu vực mục tiêu, nhận Vô Địch và Bá Thể ngắn; sau đó kích nổ khu vực mục tiêu, gây sát thương và Giảm Hồi Phục.",
      [285943890236672] = "Trong chớp mắt vượt qua không gian, dịch chuyển theo hướng đang nhìn, gây sát thương và Trì Trệ lên kẻ địch trên đường. Có thể tích 2 lần.",
      [285943890236928] = "Ngưng tụ tinh quang đâm vào kẻ địch, gây sát thương và Choáng. Sau khi thi triển có thể tung liên chiêu để trở về vị trí ban đầu.",
      [285943890237696] = "Phát động sức mạnh Tinh Giới, xuyên toa vòng quanh và gây sát thương cùng Giảm Hồi Phục lên kẻ địch phía trước. Sau khi dùng Không Ngục, kỹ năng được cường hóa và nhận thêm Năng Lượng Tinh Không.",
      [285943890237952] = "Dùng sức mạnh xóa không gian, liên tục gây sát thương lên kẻ địch trong phạm vi rồi tung đòn kết liễu gây lượng lớn sát thương. Với quái, thêm hiệu ứng gom tụ và Hất Tung.",
      [285943890239232] = "Tạo Không Ngục, phối hợp tấn công kẻ địch trong phạm vi lao lung và liên tục gây sát thương, cung cấp Bá Thể cùng Giảm Thương cho bản thân; sau đó lao lung sụp đổ gây thêm sát thương. Không Ngục cho bản thân hiệu ứng Nghiên Tập, cường hóa một số kỹ năng chiến đấu.",
      [285943890240256] = "Ghi lại Năng Lực Phi Phàm thuộc Con Đường của mục tiêu. Sau khi dùng kỹ năng có thể tung liên chiêu, triệu hồi hình chiếu dùng Năng Lực Phi Phàm đã ghi.",
      [285943890240512] = "Ẩn vào Linh Giới du hành, lập tức giải trừ khống chế đang chịu và nhận Bá Thể, tăng Tốc Độ Di Chuyển và Giảm Thương; gây sát thương cùng Giảm Tốc lên kẻ địch xung quanh, sau đó có thể tung liên chiêu tập kích kẻ địch, gây sát thương, Giảm Tốc và Hất Tung.",
      [285943890241024] = "Triệu hồi tinh tú rơi xuống kẻ địch, gây lượng lớn sát thương lên kẻ địch trong khu vực mục tiêu.",
      [285943890245632] = "Có thể dùng khi Năng Lượng Tinh Không không dưới 3 điểm. Tiêu hao toàn bộ Năng Lượng Tinh Không, trước tiên chém kẻ địch, sau đó triệu hồi nhiều tàn ảnh đánh kẻ địch, cuối cùng kích nổ Năng Lượng Tinh Không gây lượng lớn sát thương; tiêu hao càng nhiều Năng Lượng Tinh Không, sát thương càng cao.",
      [285943890246656] = "Dùng quang huy bùng phát trong cơ thể ngưng tụ 3 rìu ngắn; rìu xoay quanh bản thân liên tục tấn công kẻ địch xung quanh, gây sát thương và Giảm Tốc.",
      [285943890247936] = "Liên tục bắn nhiều Đạn Khí vào kẻ địch.",
      [285943890248448] = "Phát động sức mạnh Tinh Giới, xuyên toa vòng quanh, gây sát thương và Giảm Hồi Phục lên kẻ địch phía trước.",
      [285943890248960] = "Dùng trò ảo thuật ngẫu nhiên tấn công kẻ địch tại vị trí mục tiêu và thêm hiệu ứng tùy loại trò.",
      [285943890251008] = "Dùng tiếng gầm kinh người chấn nhiếp kẻ địch, sau đó triệu hồi phân thân Cự Nhân đập mạnh xuống đất, gây sát thương phạm vi và Giảm Tốc.",
      [285943890251520] = "Triệu hồi Lao Lung Tinh Quang tấn công mục tiêu trong phạm vi, gây Trói Buộc và Giảm Tốc; riêng mục tiêu khóa chịu thêm Choáng.",
      [285943890252032] = "Học Đồ dùng kỹ năng chiến đấu sẽ tích Năng Lượng Tinh Không và Dấu Chân. Năng Lượng Tinh Không dùng để mở khóa và cường hóa Kỹ Năng Kết Liễu của Học Đồ; Dấu Chân dùng để cường hóa đòn đánh thường.",
      [285943890252288] = "Cảm nhận Linh Giới và không gian, mở một cổng dịch chuyển để Học Đồ xuyên qua.",
      [285943890252544] = "Dùng hộp đạo cụ đặc chế trình diễn trò ảo thuật hoa mỹ để đánh lừa người xem và quay lại khoảnh khắc này.",
      [285943890253312] = "Cảm nhận Linh Giới, quan sát tinh không; thông qua biến động vận mệnh được vật phẩm linh tính khải thị, giải đọc dị động trong không gian hiện thực, xu hướng phát triển sự việc và nguy hiểm tiềm ẩn chưa biết.",
      [285943890254080] = "Tạo Cổng Lữ Hành Gia; bản thân và đồng đội tiểu đội có thể dùng cổng để dịch chuyển, khoảng cách tối đa 30m.",
      [285943890254848] = "Vung cự kiếm như lôi đình liên tục chém trái phải, sau đó bổ mạnh về phía trước, gây sát thương và nhận 1 Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu).",
      [285943890255616] = "Xoay song kiếm, tung chuỗi kiếm kỹ nhanh như gió về phía trước, thêm Suy Bại (liên tục gây sát thương) lên kẻ địch; đồng thời bản thân nhận 1 Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu).",
      [285943890256640] = "Ngưng tụ kiếm khí bằng linh tính, kéo kẻ địch tới trước mặt và thêm Trì Trệ; sau đó toàn lực nhảy chém phía trước gây sát thương, bản thân nhận Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu); gây Trói Buộc và Giảm Hồi Phục lên người chơi. Tư Thế Phòng Thủ có thể Khiêu Khích quái.",
      [285943890257664] = "Xung phong khiên vào kẻ địch rồi thuận thế nhảy nện, thêm Suy Bại (liên tục gây sát thương), gây sát thương và khống chế; người chơi chịu thêm Giảm Hồi Phục. Bản thân nhận Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu). Sau khi dùng mở khóa Hiệu Lệnh Vương Đình.",
      [285943890258432] = "Xung phong chi viện đồng minh, giải trừ khống chế nhẹ và Giảm Tốc đang chịu, cung cấp Giảm Thương và Tăng Tốc; bản thân nhận Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu). Sau khi dùng mở khóa Hiệu Lệnh Vương Đình.",
      [285943890258688] = "Xung phong khiên rồi thuận thế nhảy nện; với kẻ địch, thêm Suy Bại (liên tục gây sát thương), gây sát thương và khống chế, người chơi địch chịu thêm Giảm Hồi Phục; với người chơi đồng minh, giải trừ khống chế nhẹ và thêm Giảm Thương. Bản thân nhận Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu). Sau khi dùng mở khóa Hiệu Lệnh Vương Đình.",
      [285943890259200] = "Cầm cự kiếm xoay chém không ngừng như cuồng phong, liên tục gây sát thương phạm vi và nhận Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu), đồng thời kéo quái và Giảm Tốc người chơi địch. Tư Thế Phòng Thủ có thể Khiêu Khích quái.",
      [285943890259968] = "Cầm cự kiếm xoay chém không ngừng như cuồng phong, liên tục gây sát thương phạm vi và nhận Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu), đồng thời kéo quái và Giảm Tốc người chơi. Tư Thế Phòng Thủ có thể Khiêu Khích quái.",
      [285943890260224] = "Ngưng tụ giáp bằng linh tính bao phủ toàn thân, nhận khiên hấp thụ sát thương và Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu); khi khiên bị phá, duy trì Bá Thể. Khi mang kỹ năng này, lúc ít Máu nhận Phòng Thủ và Giảm Thương.",
      [285943890260480] = "Ngưng tụ giáp bằng linh tính bao phủ toàn thân, nhận khiên hấp thụ sát thương và Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu); khi khiên bị phá, duy trì Bá Thể. Khi mang kỹ năng này, lúc ít Máu nhận Giảm Thương cao.",
      [285943890260736] = "Dùng linh tính ngưng tụ Tế Kiếm Ngân Bạch tung đòn bất ngờ, nhận Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu), tăng Tấn Công và khi tấn công sẽ truy kích gây thêm sát thương.",
      [285943890261248] = "Cắm cự kiếm xuống đất làm tan rã hiện thực xung quanh, liên tục Bá Thể, gây sát thương phạm vi quanh bản thân được cộng thêm từ Máu tối đa và cung cấp khiên cho đồng minh trong phạm vi lớn; được cường hóa khi có Dấu Ấn Hoàng Hôn.",
      [285943890262016] = "Cắm cự kiếm xuống đất làm tan rã hiện thực xung quanh, liên tục Bá Thể, gây sát thương phạm vi quanh bản thân được cộng thêm từ Máu tối đa và cung cấp khiên lớn cùng Giảm Thương cho đồng minh ít Máu; được cường hóa khi có Dấu Ấn Hoàng Hôn.",
      [285943890262528] = "Cắm cự kiếm xuống đất làm tan rã hiện thực xung quanh, duy trì Bá Thể và tụ lực, liên tục gây sát thương lên kẻ địch quanh bản thân; sau khi tụ lực kết thúc tung đòn kết liễu gây lượng lớn sát thương và kích nổ Suy Bại, thời lượng Suy Bại còn lại càng dài thì sát thương càng cao; được cường hóa khi có Dấu Ấn Hoàng Hôn.",
      [285943890263296] = "Phát huy võ nghệ tinh xảo, mỗi lần thi triển dùng một thế kiếm khác để đánh kẻ địch; có thể tích năng lượng rồi dùng liên tiếp để nối các thế kiếm. Được cường hóa khi có Dấu Ấn Hoàng Hôn.",
      [285943890265344] = "Cầm kiếm lao nhanh chém về phía trước, tấn công đơn vị trên đường và nhận Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu). Tư Thế Tấn Công thêm Suy Bại (liên tục gây sát thương); Tư Thế Phòng Thủ tăng Đỡ Đòn của bản thân.",
      [285943890266112] = "Vung song kiếm tung thế công như mưa bão, gây lượng lớn sát thương và dùng chuỗi chém liên tục khống chế kẻ địch; bản thân nhận Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu). Tư Thế Tấn Công thêm Suy Bại (liên tục gây sát thương).",
      [285943890267136] = "Giáng kiếm trận tại vị trí mục tiêu, gây sát thương lên kẻ địch. Tư Thế Tấn Công thêm Suy Bại (liên tục gây sát thương).",
      [285943890268160] = "Trừ tà diệt ma, giải trừ toàn bộ khống chế, vào Bá Thể, nhận Giảm Thương và Tăng Tốc, đồng thời hồi Máu.",
      [285943890268672] = "Triệu hồi phân thân Cự Nhân đập mạnh xuống đất, gây sát thương phạm vi.",
      [285943890269184] = "Ngưng tụ linh tính thành thực thể Cự Nhân, cùng tung đòn chém kết liễu, gây lượng lớn sát thương và thêm Giảm Hồi Phục lên người chơi địch. Sau khi dùng nhận 4 Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu).",
      [285943890269696] = "Dùng thế công liên tục không ngừng để Ngắt kẻ địch và gây nhiều lần sát thương; sau đó linh tính ngưng tụ thành thực thể Cự Nhân tung đòn kết liễu, tăng sát thương lên kẻ địch Suy Bại. Sau khi dùng nhận 4 Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu).",
      [285943890270208] = "Biến thành Cự Nhân, nhận Vô Địch ngắn và xóa Trạng Thái Bất Lợi; sau đó vừa di chuyển vừa liên tục tấn công kèm Giảm Tốc, trong thời gian này Bá Thể và Giảm Thương.",
      [285943890270976] = "Chiến Sĩ là bậc thầy vũ khí bẩm sinh, có thể thành thạo nhiều loại vũ khí. Trong Tư Thế Tấn Công dùng song kiếm để tăng sát thương; trong Tư Thế Phòng Thủ dùng cự kiếm, nhận Giảm Thương và dễ thu hút thù hận của quái hơn.",
      [285943890272256] = "Dựa vào căn nguyên huyết mạch Cự Nhân Hoàng Hôn, ngưng tụ sức mạnh, giậm mạnh xuống đất tạo chấn động, hất bụi quanh người tạo màn che thị giác ngắn.",
      [285943890272512] = "Sức mạnh hữu hình, ngưng hình thành ảnh. Mượn huyết mạch Cự Nhân Hoàng Hôn để tích lực cho tư thế tấn công sắp thi triển và cụ hiện quỹ đạo chiêu thức. Khi phát lực tấn công, quỹ đạo hình thành sẽ hóa thành tàn ảnh theo động tác.",
      [285943890273280] = "Dẫn huyết mạch Cự Nhân Hoàng Hôn làm lực, lấy thiên phú Bậc Thầy Vũ Khí làm kỹ, ngưng tụ sức mạnh Phi Phàm để triệu hồi hình thái thực thể của cự kiếm và song kiếm tương ứng.",
      [285943890273536] = "Dùng Vu Thuật tấn công mục tiêu và nhận Tri Thức Thần Bí (dùng để mở khóa Kỹ Năng Kết Liễu); sau khi dùng Trí Nhân, cường hóa thành Thương Longinus, tăng sát thương và lượng Tri Thức Thần Bí nhận được, đồng thời thêm Giảm Hồi Phục.",
      [285943890275072] = "Ngưng tụ Thương Longinus từ trời giáng xuống, đâm 3 lần vào kẻ địch trong phạm vi nhỏ, nhận Tri Thức Thần Bí (dùng để mở khóa Kỹ Năng Kết Liễu) và thêm Giảm Hồi Phục.",
      [285943890275328] = "Dùng quyển trục gây sát thương lên kẻ địch và nhận Quán Chú Tri Thức, cường hóa đòn đánh thường kế tiếp và 2 kỹ năng chiến đấu có thể được cường hóa tiếp theo. Sau khi dùng nhận Tri Thức Thần Bí (dùng để mở khóa Kỹ Năng Kết Liễu).",
      [285943890275584] = "Kích phát quang hoa khúc xạ giữa các kẻ địch, gây sát thương và Trì Trệ, đồng thời nhận Tri Thức Thần Bí (dùng để mở khóa Kỹ Năng Kết Liễu). Có thể được Trí Nhân cường hóa, tăng sát thương và thêm Giảm Tốc, Giảm Công Kích.",
      [285943890277120] = "Rải Tinh Sa xuống khu vực mục tiêu làm tan rã mục tiêu, gây sát thương phạm vi và nhận Tri Thức Thần Bí (dùng để mở khóa Kỹ Năng Kết Liễu). Có thể được Trí Nhân cường hóa, gây thêm sát thương liên tục, Giảm Tốc và Hất Tung.",
      [285943890277632] = "Triệu hồi Lao Lung Tinh Quang gây sát thương và Choáng mục tiêu, đồng thời nhận Tri Thức Thần Bí (dùng để mở khóa Kỹ Năng Kết Liễu). Có thể được Trí Nhân cường hóa, biến khống chế thành khống chế phạm vi.",
      [285943890277888] = "Ngưng tụ lao lung bằng tinh mang, gây sát thương và Choáng mục tiêu, đồng thời nhận Tri Thức Thần Bí (dùng để mở khóa Kỹ Năng Kết Liễu). Có thể được Trí Nhân cường hóa, biến khống chế thành khống chế phạm vi.",
      [285943890278400] = "Dùng ma pháp cổ tích, lấy sức mạnh thần bí bảo vệ bản thân, nhận khiên, Bá Thể và Tri Thức Thần Bí (dùng để mở khóa Kỹ Năng Kết Liễu).",
      [285943890278656] = "Mở Con Mắt Dòm Bí để nhìn thấu giả tượng, gây sát thương phạm vi quanh bản thân và Đẩy Lùi kẻ địch, xóa khiên địch và gây Giảm Hồi Phục; giai đoạn hai có thể nhanh chóng lùi về sau. Sau khi dùng nhận Tri Thức Thần Bí (dùng để mở khóa Kỹ Năng Kết Liễu).",
      [285943890279168] = "Rút sức mạnh từ tri thức, triệu hồi một Ảo Tượng Thần Bí Vô Địch cạnh mục tiêu để liên tục gây sát thương; giai đoạn hai có thể đổi vị trí với ảo tượng. Sau khi dùng nhận Tri Thức Thần Bí (dùng để mở khóa Kỹ Năng Kết Liễu).",
      [285943890280448] = "Dùng ma pháp cổ tích, triển khai Kỳ Nguyệt để tăng tốc dòng thời gian của bản thân, nhận Bá Thể; sau một khoảng trễ ngắn gây sát thương phạm vi và Hất Tung, đồng thời giảm hồi chiêu kỹ năng của bản thân. Sau khi dùng nhận Tri Thức Thần Bí (dùng để mở khóa Kỹ Năng Kết Liễu).",
      [285943890280704] = "Hóa thân thành Tinh Quang, giải trừ khống chế đang chịu, nhận Bá Thể, Giảm Thương và tăng Tốc Độ Di Chuyển.",
      [285943890280960] = "Dùng sức mạnh tri thức cuồn cuộn tạo Tin Tuyến liên tục xung kích kẻ địch, không ngừng tiêu hao Tri Thức Thần Bí để gây sát thương cao.",
      [285943890281984] = "Gây sát thương phạm vi và giảm sát thương bản thân nhận vào.",
      [285943890282496] = "Trong chiến đấu, thần bí tràn ra làm nhiễu kẻ địch; khi dùng đánh thường hoặc kỹ năng có xác suất dùng thêm Xoáy Tri Thức, gây sát thương và Giảm Hồi Phục.",
      [285943890283264] = "Dùng Con Mắt Dòm Bí thăm dò thông tin môi trường xung quanh, in tri thức vô hình lên mặt giấy dưới dạng văn tự.",
      [285943890283520] = "Với lòng cầu tri, điều động toàn bộ cảm giác để trải nghiệm sâu chiêu thức chiến đấu, để lại tàn ảnh khi tấn công.",
      [285943890284288] = "Dùng linh tính cảm nhận môi trường, thăm dò thần bí với tư thái Phù Thủy.",
      [285943890294272] = "Hồi SAN phạm vi, tăng Học Thức, Vũ Lực, Mị Lực, Trực Giác, đồng thời thêm <HighLight>Thể Phách Rồng</> và <HighLight>Nộ Ý Rồng</>.",
      [285943890296576] = "Thay đổi bầu trời và triệu hồi <HighLight>“Điện Danh Lưu”</>.",
