    ["skill1"] = {
      [140741246462464] = "Lá Bài Vận Rủi",
      [140741246464000] = "Ấn Ký Tử Linh",
      [140741246465536] = "Trọng Chùy Phẫn Nộ",
      [140741246466304] = "Barney Chấn Địa",
      [140741246467072] = "Sổ Sách Nhà Moretti",
      [140741246468608] = "Đoạn Nhạc Nhất Kích",
      [140741246469376] = "Tinh Giới Tái Hiện",
      [140741246470912] = "Huyết Hồng Nở Rộ",
      [140741246475520] = "Bão Kiếm",
      [140741246477056] = "Hồi Âm Thánh Quang",
      [140741246478592] = "Hiệu Lệnh Bầy Sói",
      [140741246479360] = "Liệt Địa",
      [140741246480128] = "Huyết Diễm Cuồng Vũ",
      [140741246487040] = "Lệnh Truy Bắt Thiết Huyết",
      [140741246487808] = "Kiếm Khí Đỏ Thẫm",
      [140741246491136] = "Tam Kích Nộ Triều",
      [140741246492672] = "Trụy Kích Tham Lam",
      [140741246501632] = "Nộ Hống Tử Linh",
      [140741514894848] = "Liên tục chém nhanh 3 lần, tổng cộng gây <HighLight>220%</> Sát Thương Tấn Công; sau đó nhận khiên bằng <HighLight>10%</> Máu tối đa trong <HighLight>3</> giây.",
      [140741514895616] = "Bắn mũi tên xuyên thấu, gây <HighLight>180%</> Sát Thương Tấn Công lên kẻ địch trên đường thẳng; tại điểm cuối mũi tên gây thêm <HighLight>60%</> sát thương phạm vi và Choáng <HighLight>1</> giây.",
      [140741514896384] = "Chấn kích kẻ địch xung quanh, gây <HighLight>120%</> Sát Thương Tấn Công; nhận khiên bằng <HighLight>18%</> Máu tối đa và <HighLight>8%</> Súc Thương trong <HighLight>3</> giây.",
      [140741514897152] = "Liên tục phun 9 lần, mỗi lần gây <HighLight>18%</> Sát Thương Tấn Công; khi trúng gây Thiêu Đốt trong <HighLight>4</> giây và giảm <HighLight>25%</> hồi Máu.",
      [140741514897920] = "Ném 2 Lá Bài Vận Rủi, mỗi lá gây <HighLight>90%</> Sát Thương Tấn Công; sau đó ngẫu nhiên nhận cường hóa Tốc Độ Đánh, Tấn Công hoặc Khiên trong <HighLight>4</> giây.",
      [140741514898688] = "Oanh kích khu vực mục tiêu, gây <HighLight>120%</> Sát Thương Tấn Công và giảm <HighLight>8%</> Tấn Công của kẻ địch trong <HighLight>3</> giây; đồng minh trong khu vực hồi <HighLight>4%</> Máu tối đa.",
      [140741514899456] = "Gây <HighLight>220%</> Sát Thương Tấn Công lên mục tiêu hiện tại và khiến sát thương mục tiêu nhận vào tăng <HighLight>10%</> trong <HighLight>4</> giây.",
      [140741514900224] = "Bắn 3 đạn Tinh Huy, lần lượt gây <HighLight>60%/60%/90%</> Sát Thương Tấn Công; viên thứ ba trúng sẽ hồi <HighLight>6</> Mana.",
      [140741514900992] = "Đập mạnh kẻ địch xung quanh, gây <HighLight>120%</> Sát Thương Tấn Công và nhận <HighLight>20%</> Hút Máu trong <HighLight>5</> giây; trong thời gian này, chịu đòn sẽ cộng dồn Tốc Độ Đánh.",
      [140741514901760] = "Ngài Barney liên tục chấn kích mặt đất và nhận lượng lớn <img id=\"09\" width=\"40\" height=\"40\"/>Súc Thương.",
      [140741514902528] = "Đối chiếu sổ sách, hồi <HighLight>4%</> Máu tối đa cho bản thân và đồng minh trong 1 ô, đồng thời tăng <HighLight>6</> Phòng Thủ trong <HighLight>4</> giây; sau đó bản thân ngẫu nhiên nhận 1 loại Kết Dư trong <HighLight>6</> giây: Tấn Công và Tốc Độ Đánh +<HighLight>12%</>; hoặc nhận khiên bằng <HighLight>10%</> Máu tối đa và +<HighLight>8</> Phòng Thủ; hoặc hồi <HighLight>6%</> Máu tối đa và <HighLight>8</> Mana, đồng thời nhận khiên bằng <HighLight>4%</> Máu tối đa.",
      [140741514903296] = "Lao vào kẻ địch có Máu thấp nhất, bình thường gây <HighLight>180%</> Sát Thương Tấn Công; nếu Máu mục tiêu không quá 35%, đổi thành <HighLight>260%</>, đồng thời hồi <HighLight>8%</> Máu tối đa.",
      [140741514904064] = "Vung rìu gây <HighLight>160%</> Sát Thương Tấn Công, giảm <HighLight>15</> Phòng Thủ của kẻ địch trong <HighLight>5</> giây; Tốc Độ Đánh bản thân tăng <HighLight>20%</> trong 4 giây.",
      [140741514904832] = "Gây <HighLight>160%</> Sát Thương Tấn Công về phía trước; sau <HighLight>1.2</> giây, Hồng Lưu Tinh Giới tái hiện tại cùng khu vực, gây thêm <HighLight>80%</> Sát Thương Tấn Công.",
      [140741514905600] = "Sóng âm gây <HighLight>170%</> Sát Thương Tấn Công lên kẻ địch phía trước và Đẩy Lùi; bản thân nhận khiên bằng <HighLight>12%</> Máu tối đa trong <HighLight>4</> giây.",
      [140741514906368] = "Gây <HighLight>160%</> Sát Thương Tấn Công lên kẻ địch xung quanh và nhận khiên bằng <HighLight>10%</> Máu tối đa trong <HighLight>4</> giây.",
      [140741514907136] = "Liên tục bắn 5 đạn năng lượng, lần lượt gây <HighLight>60%/55%/50%/45%/40%</> Sát Thương Tấn Công.",
      [140741514907904] = "Tập kích kẻ địch có Máu thấp nhất, 3 đòn tổng cộng gây <HighLight>200%</> Sát Thương Tấn Công; để lại Hắc Diễm, 3 lần tổng cộng gây <HighLight>100%</> Sát Thương Tấn Công.",
      [140741514908672] = "Nấm liên tục phát nổ 3 lần, gây <HighLight>35%/35%/120%</> Sát Thương Tấn Công; đồng minh trong khu vực hồi <HighLight>6%</> Máu tối đa.",
      [140741514909440] = "Gây <HighLight>120%</> Sát Thương Tấn Công lên kẻ địch xung quanh, sau đó ngẫu nhiên nhận Khiên, Tốc Độ Đánh hoặc Súc Thương trong <HighLight>3</> giây.",
      [140741514910208] = "Bắn 2 đạn Mắt Máy, mỗi viên gây <HighLight>80%</> Sát Thương Tấn Công; khi triển khai, đồng minh gần đó nhận khiên bằng <HighLight>8%</> Máu tối đa trong <HighLight>4</> giây.",
      [140741514910976] = "Bá Thể chém 6 lần, tổng cộng gây <HighLight>220%</> Sát Thương Tấn Công; bản thân nhận khiên bằng <HighLight>14%</> Máu tối đa trong <HighLight>4</> giây.",
      [140741514911744] = "Tăng <HighLight>35%</> Tốc Độ Đánh cho bản thân và đồng minh trong 2 ô trong <HighLight>6</> giây; bản thân hồi <HighLight>15%</> Máu tối đa.",
      [140741514912512] = "Nhận khiên bằng <HighLight>16%</> Máu tối đa; sau 1.2 giây gây <HighLight>120%</> Sát Thương Tấn Công lên kẻ địch xung quanh và khiến đồng minh gần đó hồi <HighLight>8%</> Máu tối đa.",
      [140741514913280] = "Tinh Quỹ thứ nhất gây <HighLight>180%</> Sát Thương Tấn Công, tinh quỹ thứ hai gây <HighLight>120%</>; điểm giao nhau gây thêm <HighLight>60%</>.",
      [140741514914048] = "Phát 4 xung, mỗi lần gây <HighLight>25%</> Sát Thương Tấn Công; Tốc Độ Đánh của bản thân và đồng minh trong 1 ô tăng <HighLight>25%</> trong 4 giây.",
      [140741514914816] = "Nhảy lên nện kẻ địch xung quanh, gây <HighLight>200%</> Sát Thương Tấn Công và Hất Tung.",
      [140741514915584] = "Quét Huyết Diễm về phía trước, gây <HighLight>180%</> Sát Thương Tấn Công; Tốc Độ Đánh bản thân tăng <HighLight>30%</> trong <HighLight>4</> giây.",
      [140741514916352] = "Tia sáng liên tục gây 6 lần <HighLight>30%</> Sát Thương Tấn Công; khi kết thúc gây thêm vụ nổ phạm vi <HighLight>80%</>.",
      [140741514917120] = "Tường Sóng gây <HighLight>160%</> Sát Thương Tấn Công về phía trước và Đẩy Lùi; sau <HighLight>1</> giây, sét đánh xuống cùng khu vực, gây thêm <HighLight>80%</> Sát Thương Tấn Công.",
      [140741514917888] = "Gây <HighLight>180%</> Sát Thương Tấn Công về phía trước; Tấn Công và Phòng Thủ của kẻ địch giảm <HighLight>15%</>, còn của bản thân tăng <HighLight>15%</>, kéo dài 4 giây.",
      [140741514918656] = "Ba vòng ngoài/giữa/trong lần lượt gây <HighLight>60%/70%/90%</> Sát Thương Tấn Công; vòng thứ ba Choáng kẻ địch <HighLight>1</> giây.",
      [140741514919424] = "Vung liềm gây <HighLight>180%</> Sát Thương Tấn Công; kẻ địch có Máu không quá 35% chịu thêm <HighLight>50%</> Sát Thương Tấn Công; bản thân nhận <HighLight>10%</> Khiên.",
      [140741514920192] = "Gây <HighLight>180%</> Sát Thương Tấn Công lên khu vực mục tiêu và khiến kẻ địch Ngủ <HighLight>1</> giây; sau khi tỉnh, Tấn Công giảm <HighLight>12%</> trong 4 giây.",
      [140741514920960] = "Gây <HighLight>220%</> Sát Thương Tấn Công lên kẻ địch xung quanh, Kéo và Choáng <HighLight>1</> giây; bản thân cùng đồng minh trong 1 ô nhận khiên bằng <HighLight>10%</> Máu tối đa trong 4 giây.",
      [140741514921728] = "Gây <HighLight>180%</> Sát Thương Tấn Công lên khu vực mục tiêu; đồng minh trong khu vực nhận khiên bằng <HighLight>8%</> Máu tối đa trong <HighLight>4</> giây.",
      [140741514922496] = "Khóa kẻ địch xa nhất, gây <HighLight>180%</> Sát Thương Tấn Công, kéo tới trước mặt và Khiêu Khích <HighLight>1.5</> giây.",
      [140741514923264] = "Ý chí Đỏ Thẫm ngưng tụ <HighLight>3</> đạo Kiếm Khí Đỏ Thẫm, tổng cộng gây <img id=\"03\" width=\"40\" height=\"40\"/> Sát Thương Tấn Công <HighLight>210%</>.",
      [140741514924288] = "Giậm mạnh phía trước, gây <HighLight>260%</> Sát Thương Tấn Công và Đẩy Lùi; bản thân nhận <HighLight>20%</> Súc Thương trong 4 giây.",
      [140741514925056] = "Liên tục xung kích 3 lần, mỗi lần gây <HighLight>60%</> Sát Thương Tấn Công; đòn đầu Kéo kẻ địch, bản thân hồi <HighLight>12%</> Máu tối đa.",
      [140741514925824] = "Gây <HighLight>220%</> Sát Thương Tấn Công lên xung quanh; kẻ địch có Máu không quá 35% chịu thêm <HighLight>80%</> Sát Thương Tấn Công và giảm 15% Tấn Công.",
      [140741514926592] = "Tung 3 trọng quyền cuốn theo Nộ Triều, lần lượt gây <HighLight>50%/50%/80%</> Sát Thương Tấn Công; đòn cuối kích nổ Lôi Triều và Hất Tung kẻ địch, bản thân nhận khiên bằng <HighLight>12%</> Máu tối đa trong <HighLight>4</> giây.",
      [140741514927360] = "Tuyên phán kẻ địch xa nhất, gây <HighLight>200%</> Sát Thương Tấn Công và Choáng <HighLight>1</> giây; giảm <HighLight>8</> điểm Hồi Mana của mục tiêu trong 3 giây.",
      [140741514928128] = "Gây <HighLight>220%</> Sát Thương Tấn Công lên khu vực mục tiêu, giảm <HighLight>12%</> Tấn Công của kẻ địch; Tấn Công bản thân tăng <HighLight>15%</>, đều kéo dài 4 giây.",
      [140741514928896] = "Tại vị trí mục tiêu lần lượt nở 3 vòng gai dây leo, mỗi vòng gây <HighLight>80%</> Sát Thương Tấn Công; vòng thứ ba Choáng kẻ địch <HighLight>1</> giây.",
      [140741514929664] = "Uy áp Cự Long Tâm Linh quét phía trước, gây <HighLight>180%</> Sát Thương Tấn Công và Đẩy Lùi, giảm <HighLight>12%</> Tấn Công của kẻ địch trong 4 giây.",
      [140741514930432] = "Ba đợt Oanh Kích Linh Giới lần lượt gây <HighLight>70%/70%/140%</> Sát Thương Tấn Công; đợt đầu Kéo, đợt hai giảm 15% Tấn Công.",
      [140741514931200] = "Gây <HighLight>180%</> Sát Thương Tấn Công lên toàn bộ kẻ địch; ngẫu nhiên nhận Tấn Công, Giảm Thương hoặc hồi <HighLight>15</> Mana trong 6 giây.",
      [140741514931968] = "Xung Oán Niệm 3 lần, mỗi lần gây <HighLight>60%</> Sát Thương Tấn Công; lần thứ ba giảm <HighLight>15%</> Tấn Công của kẻ địch trong 4 giây.",
      [140741514932736] = "Gây <HighLight>160%</> Sát Thương Tấn Công lên kẻ địch xung quanh và khiến chúng Ngủ <HighLight>1</> giây; sau khi tỉnh, Tốc Độ Đánh và Tấn Công giảm <HighLight>15%</> trong 4 giây.",
      [140741514933504] = "Siết chết kẻ địch phía trước, gây <HighLight>200%</> Sát Thương Tấn Công; để lại mạng nhện trong <HighLight>4</> giây, giảm 20% Tốc Độ Di Chuyển và Tốc Độ Đánh của kẻ địch.",
      [140741514935552] = "Pháo Khí xuyên thấu bắn 2 lần, mỗi lần gây <HighLight>135%</> Sát Thương Tấn Công; chuẩn bị sẵn Người Giấy, sau lần chịu đòn kế tiếp sẽ tạm thời Không Thể Chỉ Định, nhưng bản thân cũng không thể hành động.",
      [140741514936320] = "Gây <HighLight>200%</> Sát Thương Tấn Công lên xung quanh, giảm <HighLight>15%</> Tấn Công của kẻ địch; bản thân nhận <HighLight>12%</> Súc Thương, đều kéo dài 4 giây.",
      [140741514937088] = "Nộ Hống 3 lần, tổng cộng gây <HighLight>200%</> Sát Thương Tấn Công và Đẩy Lùi; bản thân nhận khiên bằng <HighLight>22%</> Máu tối đa trong 5 giây.",
