      [286080523902976] = "Giao Điểm Dự Ngôn",
      [286080523903488] = "Người Treo Ngược-Lôi Kích",
      [286080523903744] = "Xung Oán Niệm·Hai",
      [286080523904000] = "Xung Oán Niệm·Ba",
      [286080523904256] = "Lãng Quên",
      [286080523904512] = "Quy Tịch",
      [286080523904768] = "Ngân Sách Gia Đình",
      [286080523906048] = "Chỉ Dẫn Của Thế Giới",
      [286080792266752] = "Dùng gậy chống, tiến vào trạng thái bán thiền để cảm nhận biến đổi của cơ thể và tâm linh, từ đó xác định chính xác vị trí của vật thể hoặc người mục tiêu.",
      [286080792267264] = "Thông qua ngâm xướng kéo mục tiêu vào mộng cảnh, từ đó thu được thông tin và manh mối bí mật.",
      [286080792267520] = "Trực tiếp giao tiếp với linh tự nhiên và vong hồn lang thang trong thế giới hiện thực để thu thập thông tin chân thực.",
      [286080792267776] = "Có thể chuyển nhân vật chủ đạo giữa Dunn và Daly.",
      [286080792269568] = "Ném Quả Ô Uế vào Kẻ Mất Trí, dùng sức mạnh ô uế để triệt tiêu hiệu ứng Vô Địch của chúng.",
      [286080792269824] = "Vung mạnh Thiết Bích, dọn sạch chướng ngại phía trước.",
      [286080792271616] = "Bắn đạn pháo, gây lượng sát thương lớn lên công trình.",
      [286080792271872] = "Bắn liên hoàn đạn pháo, gây lượng sát thương lớn lên công trình.",
      [286080792273920] = "Tạo 6 bẫy xung quanh; sau 2 giây phát nổ, Hất Tung kẻ địch và gây sát thương bằng 20% Máu tối đa.",
      [286080792275200] = "Bẫy dây vấp bện từ vật liệu phi phàm. Khi Phi Phàm Giả ném dây vào Khôi Giáp Tổ Tiên, dây sẽ quấn chân thú cưỡi, dùng Linh Tính khóa nhịp hành động và giảm mạnh Tốc Độ Di Chuyển.",
      [286080792277760] = "Năng lực đồng hồ bỏ túi của Lão Victor, có thể chuyển không gian giữa “trạng thái ổn định” và “trạng thái xâm thực”.",
      [286080792279552] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để tung Mưa Bài, gây spellfielddisc(*id) sát thương lên kẻ địch trong phạm vi 4.5m quanh mục tiêu, đồng thời với xác suất cơ bản *f** <HyperLink stylename=\"M_Link\" u=\"6\">Choáng</> kẻ địch ở tâm phạm vi trong 0.8 giây, tối đa <HighLight>Choáng</> 2 mục tiêu.",
      [286080792281088] = "Bật/tắt đèn pha phía trước của phương tiện.",
      [286080792281344] = "Phát một tiếng còi ngắn.",
      [286080792281600] = "Bật/tắt đèn cảnh báo.",
      [286080792281856] = "Phát tiếng còi báo động chói tai.",
      [286080792282112] = "Phát tiếng chuông xe trong trẻo.",
      [286080792282368] = "Mời một Phi Phàm Giả khác ngồi ghế sau và cùng xuất hành.",
      [286080792282624] = "Mời một Phi Phàm Giả khác ngồi phía sau và cùng xuất hành.",
      [286080792282880] = "Mời một Phi Phàm Giả khác ngồi ghế phụ và cùng xuất hành.",
      [286080792283136] = "Mời một Phi Phàm Giả khác cùng lên xe.",
      [286080792283392] = "Có thể cưỡi lưng rồng, bay trong <HighLight>Đại Thế Giới và chiến trường GVG</>. Tung hoành trên chiến trường, nhìn xuống chúng sinh dưới chân.",
      [286080792283648] = "Radio trên xe, có thể nghe nhạc.",
      [286080792284672] = "Sát Thương Đơn Mục Tiêu",
      [286080792289536] = "Đánh Thường: Dunn cầm súng tay phải bắn; ở đòn thứ ba sẽ dùng tay trái cường hóa viên đạn.",
      [286080792299008] = "Gây <color=red>90% Sát Thương Công Kích</color> lên mục tiêu hiện tại.",
      [286080792300544] = "Liên tục tấn công mục tiêu hiện tại 2 lần, tổng cộng gây <color=red>90% Sát Thương Công Kích</color>.",
      [286080792301056] = "Liên tục cào mục tiêu hiện tại 2 lần, tổng cộng gây <color=red>90% Sát Thương Công Kích</color>.",
      [286080792301568] = "Bắn 3 Phi Đạn vào mục tiêu hiện tại, tổng cộng gây <color=red>90% Sát Thương Công Kích</color>.",
      [286080792303104] = "Gây <HighLight>90%</> Sát Thương Công Kích lên mục tiêu hiện tại.",
      [286080792304640] = "Liên tục tấn công mục tiêu hiện tại 3 lần, tổng cộng gây <color=red>90% Sát Thương Công Kích</color>.",
      [286080792305664] = "Gây <color=red>90% Sát Thương Công Kích</color> lên mục tiêu hiện tại và kẻ địch trong phạm vi 1 ô quanh đó.",
      [286080792306176] = "Gây <color=red>90% Sát Thương Công Kích</color> lên mục tiêu hiện tại trong phạm vi 2 ô.",
      [286080792307712] = "Gây <color=red>90% Sát Thương Công Kích</color> lên mục tiêu hiện tại trong phạm vi 1 ô.",
      [286080792309760] = "Phóng Đạn Bóng Tối vào mục tiêu hiện tại trong phạm vi 2 ô, gây <color=red>90% Sát Thương Công Kích</color>.",
      [286080792312832] = "Bắn Đạn Tinh Huy vào mục tiêu hiện tại trong phạm vi 4 ô, gây <color=red>90% Sát Thương Công Kích</color>.",
      [286080792313344] = "Dùng trọng quyền cuốn theo thủy triều đánh mục tiêu hiện tại trong phạm vi 1 ô, gây <color=red>90% Sát Thương Công Kích</color>.",
      [286080792313856] = "Dùng súng lục bắn mục tiêu hiện tại trong phạm vi 3 ô, gây <color=red>90% Sát Thương Công Kích</color>.",
      [286080792314368] = "Sát thương giai đoạn hai của Pháo Không Khí.",
      [286080792314624] = "Giao hóa đơn cho mục tiêu hiện tại trong phạm vi 2 ô, gây <color=red>90% Sát Thương Công Kích</color>.",
      [286080792315136] = "Bắn tia bánh răng vào mục tiêu hiện tại trong phạm vi 3 ô, gây <color=red>75% Sát Thương Công Kích</color>.",
      [286080792315648] = "Thi hài khổng lồ vung đánh kẻ địch cận thân, gây <color=red>90% Sát Thương Công Kích</color> lên mục tiêu hiện tại trong phạm vi 1 ô.",
      [286080792320768] = "Tạm thời tiến vào vùng giao giới giữa hiện thực và Linh Giới. Dưới kích thích của tiếng thét bất tận, cường hóa toàn bộ kỹ năng chiến đấu, tăng {CheckStar(Type=\"sealed\",ID=2085018)=1?36%}{CheckStar(Type=\"sealed\",ID=2085018)=2?45%}{CheckStar(Type=\"sealed\",ID=2085018)=3?54%} Tốc Độ Tấn Công và mỗi giây hoàn lại {CheckStar(Type=\"sealed\",ID=2085018)=1?0.24}{CheckStar(Type=\"sealed\",ID=2085018)=2?0.28}{CheckStar(Type=\"sealed\",ID=2085018)=3?0.32} giây Hồi Chiêu, kéo dài 20 giây. Trong thời gian cường hóa, nếu hạ gục hoặc hỗ trợ hạ gục bất kỳ mục tiêu nào, thời gian trạng thái kéo dài thêm 5 giây; tối đa kích hoạt kéo dài 2 lần.",
      [286080792321024] = "Xóa <HyperLink stylename=\"M_Link\" u=\"3\" color=\"#f4a067\">hiệu ứng khống chế</> trên bản thân và nhận <HyperLink stylename=\"M_Link\" u=\"3\" color=\"#f4a067\">Bá Thể</> cùng 50% Giảm Thương trong 4 giây. Với mỗi lần nhận sát thương, phần không vượt quá 10% Máu tối đa sẽ phản lại kẻ tấn công theo hệ số {CheckStar(Type=\"sealed\",ID=2085010)=1?0.6}{CheckStar(Type=\"sealed\",ID=2085010)=2?0.75}{CheckStar(Type=\"sealed\",ID=2085010)=3?0.9} (với mục tiêu ngoài 8m, sát thương phản lại suy giảm thêm, thấp nhất còn 20% so với trong 8m). Khi hiệu ứng kết thúc, phá vỡ lao lung, gây sát thương lên tối đa 6 mục tiêu địch trong phạm vi 8m quanh bản thân và gây hiệu ứng Chói Mắt 10 giây, làm giảm Công Kích của chúng.",
      [286080792325632] = "Triển khai Bí Cảnh quanh mục tiêu, khiến kẻ địch trong phạm vi <HyperLink stylename=\"M_Link\" u=\"9\">Trì Trệ</> *f giây và trong thời gian đó chịu 6 lần spellfielddisc(*id) Sát Thương Vật Lý; sau đó đòn kết liễu gây spellfielddisc(*id) Sát Thương Vật Lý. Nếu mục tiêu là quái vật thì <HyperLink stylename=\"M_Link\" u=\"2\">Hất Tung</>; nếu là người chơi thì có xác suất <HyperLink stylename=\"M_Link\" u=\"6\">Choáng</> mục tiêu *f giây.",
      [286080792325888] = "Nhận Khiên bằng <HighLight>{CheckStar(Type=\"sealed\",ID=2085019)=1?21%}{CheckStar(Type=\"sealed\",ID=2085019)=2?30%}{CheckStar(Type=\"sealed\",ID=2085019)=3?39%}</> Máu tối đa, kéo dài *f giây. Khi Khiên bị phá, bản thân nhận buffdisc(*id) giây <HyperLink stylename=\"M_Link\" u=\"11\">Bá Thể</>; hiệu ứng này có Hồi Chiêu Nội Bộ buffdisc(*id) giây.",
      [286080792326656] = "Gây {CheckStar(Type=\"sealed\",ID=2085019)=1?*d}{CheckStar(Type=\"sealed\",ID=2085019)=2?*d}{CheckStar(Type=\"sealed\",ID=2085019)=3?*d} Sát Thương Phép lên kẻ địch trong vùng tròn phía trước và gây mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">Giảm Hồi Phục</> trong *f giây.",
      [286080792327168] = "Lập tức hồi cho mục tiêu đồng minh lượng Máu bằng {CheckStar(Type=\"sealed\",ID=2085019)=1?*f**}{CheckStar(Type=\"sealed\",ID=2085019)=2?*f**}{CheckStar(Type=\"sealed\",ID=2085019)=3?*f**} Máu tối đa của họ (lượng hồi không vượt quá {CheckStar(Type=\"sealed\",ID=2085019)=1?*f**}{CheckStar(Type=\"sealed\",ID=2085019)=2?*f**}{CheckStar(Type=\"sealed\",ID=2085019)=3?*f**} Máu tối đa của bản thân), đồng thời khiến họ buffdisc(*id), kéo dài *f giây. Nếu kỹ năng tạo hồi phục dư, hồi cho thành viên đội có % Máu thấp nhất trong phạm vi kỹ năng một lượng bằng phần hồi dư (chịu ảnh hưởng Giảm Hồi Phục của mục tiêu).",
      [286080792327424] = "Triệu hồi Lao Lung Tinh Quang gây {CheckStar(Type=\"sealed\",ID=2085019)=1?*d}{CheckStar(Type=\"sealed\",ID=2085019)=2?*d}{CheckStar(Type=\"sealed\",ID=2085019)=3?*d} Sát Thương Phép lên mục tiêu khóa và với <HighLight>100%</> xác suất cơ bản, trong <HighLight>{CheckStar(Type=\"sealed\",ID=2085019)=1?1}{CheckStar(Type=\"sealed\",ID=2085019)=2?1.25}{CheckStar(Type=\"sealed\",ID=2085019)=3?1.5}</> giây gây <HyperLink stylename=\"M_Link\" u=\"6\">Choáng</>.",
      [286080792328192] = "Dựng Nhật Thệ tại vị trí chỉ định trong 8 giây, gây 8 lần {CheckStar(Type=\"sealed\",ID=2085019)=1?*d}{CheckStar(Type=\"sealed\",ID=2085019)=2?*d}{CheckStar(Type=\"sealed\",ID=2085019)=3?*d} Sát Thương Vật Lý lên kẻ địch trong phạm vi và liên tục khiến chúng <HyperLink stylename=\"M_Link\" u=\"9\">Trì Trệ</>. Kẻ địch trong phạm vi lời thệ trapdisc(*id) (số lần kích hoạt có giới hạn).",
      [286080792328448] = "Mở hồ sơ lời khai để xem toàn bộ lời khai thu được trong quá trình điều tra.",
      [286080792328704] = "Tạm thời giành quyền điều khiển cơ thể của Lumi.",
      [286080792328960] = "Hủy Hoán Đổi Thân Phận, trở về thân thể hiện thực.",
      [286080792329216] = "Nhận ma lực của Đại Kiếm Hỗn Loạn.",
      [286080792329472] = "Nhận ma lực của Đại Kiếm Trật Tự.",
      [286080792329728] = "Ghi lại và xem các phù văn đã xuất hiện.",
      [286080792329984] = "Chuyển góc nhìn để quan sát vị trí hiện tại.",
      [286080792330240] = "Dùng năng lực của bùa chú triển khai Khiên, Bảo Hộ bản thân và đồng đội.",
      [286080792341504] = "Nhận chỉ dẫn về cách xuyên toa giữa thế giới Hỗn Loạn và Trật Tự, cũng như cách khéo léo vận chuyển đại kiếm.",
      [286081329137920] = "Thoát trạng thái Biến Thân.",
