      [286081329173760] = "Sát Thương Khu Vực Mục Tiêu",
      [286081329174784] = "Sát Thương Phạm Vi Quanh Bản Thân & Hất Tung",
      [286081329175296] = "Sát Thương Duy Trì Khu Vực Mục Tiêu",
      [286081329175808] = "Sát Thương Lớn Đơn Mục Tiêu",
      [286081329176320] = "Sát Thương Toàn Màn Hình",
      [286081329176576] = "Đánh Thường Phạm Vi Nhỏ Quanh Mục Tiêu",
      [286081329177344] = "Sát Thương Vùng Tròn Quanh Mục Tiêu",
      [286081329182464] = "Vung chi nhện siết giết kẻ địch phía trước, gây <color=red>220% Sát Thương Công Kích</color> lên kẻ địch trong vùng quạt 2 ô.",
      [286081329182976] = "Phát tiếng thét kinh hoàng, gây <color=red>200% Sát Thương Công Kích</color> lên kẻ địch trong phạm vi 2 ô quanh bản thân.",
      [286081329183488] = "Phóng Xung Kích Âm Ba, gây <color=red>220% Sát Thương Công Kích</color> lên kẻ địch trong vùng quạt 3 ô phía trước.",
      [286081329184000] = "Liên tục bắn 3 Đạn Tinh Huy, mỗi viên gây <color=red>75% Sát Thương Công Kích</color> lên mục tiêu hiện tại trong phạm vi 4 ô.",
      [286081329184256] = "Dùng Triều Quyền gây 90% Sát Thương Công Kích lên mục tiêu hiện tại trong phạm vi 1 ô.",
      [286081329184512] = "Ba đòn trọng quyền tổng cộng gây 180% Sát Thương Công Kích; đòn cuối Hất Tung và nhận Khiên bằng 12% Máu tối đa.",
      [286081329184768] = "Dùng súng lục bắn mục tiêu hiện tại trong phạm vi 3 ô, gây 90% Sát Thương Công Kích.",
      [286081329185024] = "Sát Thương Hai Đoạn Hình Chữ Nhật Phía Trước",
      [286081329185536] = "Giao hóa đơn cho mục tiêu hiện tại trong phạm vi 2 ô, gây 90% Sát Thương Công Kích.",
      [286081329185792] = "Hồi Máu cho bản thân và đồng minh trong phạm vi 1 ô, đồng thời tăng Phòng Thủ; bản thân ngẫu nhiên nhận thêm một loại Kết Dư.",
      [286081329186048] = "Bắn tia bánh răng vào mục tiêu hiện tại trong phạm vi 3 ô, gây 75% Sát Thương Công Kích.",
      [286081329186304] = "Triệu hồi thiết bị bánh răng, gây Sát Thương Phạm Vi lên kẻ địch phía trước.",
      [286081329186560] = "Sát Thương Cận Chiến Đơn Mục Tiêu",
      [286081329186816] = "Sát Thương Phạm Vi Quanh Bản Thân & Đẩy Lùi",
      [286081329191680] = "Nhận hiệu ứng tăng cường, cường hóa toàn bộ kỹ năng chiến đấu và Tuyệt Kỹ, tăng Tốc Độ Tấn Công và hoàn lại Hồi Chiêu mỗi giây.",
      [286081329191936] = "Xóa trạng thái khống chế trên bản thân, đồng thời nhận Bá Thể, Giảm Thương và phản sát thương. Khi hiệu ứng kết thúc, gây sát thương lên mục tiêu địch gần đó và giảm Công Kích của chúng.",
      [286081329196544] = "Triệu hồi Hình Chiếu Lịch Sử của Bí Cảnh, thao túng Sợi Tơ Linh Thể của mục tiêu, khiến kẻ địch trong phạm vi Trì Trệ và liên tục chịu sát thương; sau đó đòn kết liễu gây lượng lớn sát thương, Hất Tung quái vật và Choáng người chơi.",
      [286081329197056] = "Ngưng tụ Linh Tính thành khôi giáp phủ toàn thân, nhận Khiên hấp thụ sát thương; khi Khiên bị phá, duy trì Bá Thể.",
      [286081329198592] = "Triệu hồi Lao Lung Tinh Quang gây sát thương và Choáng mục tiêu.",
      [286081329199104] = "Dựng Nhật Thệ tại vị trí chỉ định; kẻ địch trong phạm vi chịu sát thương, Trì Trệ và Giam Cầm.",
      [286081329200640] = "Mở Bút Ký",
      [286081866022656] = "Bấm Còi",
      [286081866022912] = "Đèn Xe",
      [286081866023424] = "Đèn Cảnh Báo",
