      [286149243319040] = "Mặc Cả",
      [286149243321088] = "Trả Nợ",
      [286149243326464] = "Lạc Ấn Tử Vong",
      [286149243326976] = "Bàn Tay Tử Vong",
      [286149243328512] = "Đế Quốc Kỳ Xí",
      [286149243329024] = "Chiến Kỳ Bất Bại",
      [286149243330048] = "Sương Xám Gia Trì",
      [286149243330304] = "Áp Chế Sương Xám",
      [286149511742976] = "Dẫn dắt Ma Pháp Đồng Thoại, khiến mục tiêu chìm sâu trong Ảo Cảnh Vương Quốc và liên tục rơi vào trạng thái Cứng Đờ. Tạo ảo cảnh Vương Quốc Đồng Thoại tại vị trí mục tiêu, gây skilldisc(*id) lên kẻ địch trong phạm vi. Trong khi dẫn dắt, bản thân nhận Bá Thể và có thể Né để ngắt sớm. Sau khi dẫn dắt hoàn chỉnh Ảo Cảnh Vương Quốc, kích nổ ảo cảnh gây skilldisc(*id).",
      [286149511743232] = "Gây 5 lần sát thương, mỗi lần *d điểm.",
      [286149511743488] = "Gây *d điểm sát thương; sát thương tại vùng trung tâm tăng thành *d điểm.",
      [286149511743744] = "skilldisc(*id), sau đó hóa thành tàn ảnh, nhanh chóng gây 6 lần sát thương *d điểm; trong thời gian này buffdisc(*id). Sau *f giây, Luật Lệnh bùng nổ spellfielddisc(*id).",
      [286149511744000] = "Dịch chuyển tức thời đến trước mục tiêu, áp Luật Lệnh lên kẻ địch xung quanh, khiến chúng buffdisc(*id) trong *f giây.",
      [286149511744256] = "Liên tiếp bắn 2 Pháo Khí về phía trước, gây 2 lần sát thương *d điểm; nếu chỉ trúng một mục tiêu, sát thương mỗi lần tăng thành *d điểm.",
      [286149511744768] = "Cưỡi sóng xung phong; có thể điều chỉnh hướng bằng phím di chuyển. Trong thời gian này nhận tối đa 4 giây Bá Thể và 5 giây Tăng Tốc. Khi xung phong kết thúc hoặc chủ động dùng lần hai, gây *d điểm sát thương. Trang bị kỹ năng nhận nội tại: trong đại thế giới, tốc độ lướt ván trên mặt nước và bơi tăng 5%.",
      [286149511745792] = "Leonard ngâm Thi Phẩm An Hồn, khiến mục tiêu trong bán kính 6m xung quanh nhận 70% Trọng Thương trong 4 giây; bản thân nhận Hào Quang Tinh Thần bán kính <Highlight>6</>m kéo dài <Highlight>6</> giây, khiến kẻ địch trong hào quang buffdisc(*id).",
      [286149511746304] = "Nếu bản thân và đồng đội có hiệu ứng Hợp Tấu cùng gây sát thương lên một mục tiêu, gây thêm sát thương bằng <Highlight>10%</> lượng HP mục tiêu đã mất; mỗi 2 giây chỉ kích hoạt 1 lần.",
      [286149511746816] = "Triển khai Lĩnh Vực Thánh Quang, xóa hiệu ứng khống chế trên bản thân và nhận Bá Thể, buffdisc(*id); sau một khoảng thời gian hoặc khi kích hoạt lại, skilldisc(*id).",
      [286149511747072] = "Bùng nổ năng lượng, gây *d điểm sát thương lên kẻ địch xung quanh và Đẩy Lùi chúng.",
      [286149511747584] = "Dòm ngó bí mật của vận mệnh, khiến bản thân và đồng minh xung quanh buffdisc(*id).",
      [286149511747840] = "Daly tiến hành Nghi Thức Thông Linh, spellfielddisc(*id), đồng thời spellfielddisc(*id).",
      [286149511748352] = "Dunn rót sức mạnh Mộng Yểm vào mặt đất, ngưng tụ thành Mộng Yểm lao vào mục tiêu địch, gây bulletdisc(*id) điểm sát thương khi trúng và để lại Ấn Ký Mộng Yểm; sau 1.5 giây gây thêm *d điểm sát thương.",
      [286149511749632] = "Frye gây *d điểm sát thương lên người chơi địch và *d điểm lên quái vật địch, đồng thời gắn <FaintYellow>Ấn Ký Tử Linh</> trong 10 giây, buffdisc(*id).",
      [286149511750400] = "Audrey hồi *d HP cho đồng minh mục tiêu và gắn hiệu ứng <FaintYellow>Thẩm Thị</> trong <HighLight>4</> giây, ghi lại sát thương nhận vào trong <HighLight>4</> giây; khi hiệu ứng kết thúc, hồi HP bằng <HighLight>40%</> lượng sát thương đã nhận trong thời gian hiệu ứng.",
      [286149511750656] = "Audrey gắn hiệu ứng <FaintYellow>Thẩm Thị</> lên đồng minh mục tiêu trong 4 giây, ghi lại sát thương nhận vào trong <HighLight>4</> giây; khi hiệu ứng kết thúc, hồi HP bằng <HighLight>40%</> lượng sát thương đã nhận trong thời gian hiệu ứng.",
      [286149511751168] = "Fors triệu hồi một tia sét đánh mục tiêu địch, gây *d sát thương; nếu mục tiêu là quái vật, sát thương tăng 75%.",
      [286149511752192] = "Audrey ném 3 chiếc bánh thú cưng Backlund Susie cất riêng và hồi *d HP cho 1 đồng minh có tỷ lệ HP thấp nhất xung quanh. Chạm vào bánh sẽ hồi *d HP cho 3 đồng minh có tỷ lệ HP thấp nhất xung quanh; nếu không ai chạm, khi bánh biến mất cũng hồi *d HP cho 3 đồng minh có tỷ lệ HP thấp nhất xung quanh. Bánh tồn tại tối đa <HighLight>6</> giây.",
      [286149511753472] = "Frank triệu hồi một cây nấm đặc chế tại vị trí mục tiêu địch; nấm phát nổ gây sát thương phạm vi spellfielddisc(*id).",
      [286149511753984] = "Lovia gia trì Bóng Tối Huyết Nhục cho người thi triển, trong 5.5 giây gây spellfielddisc(*id) điểm sát thương lên kẻ địch.",
      [286149511754496] = "Benson mặc cả, ngẫu nhiên tung <HighLight>1-5</> đồng xu; số xu quyết định mức chiết khấu, và mức chiết khấu quyết định hiệu ứng tăng cường bản thân trong <HighLight>9</> giây. <HighLight>1</> xu, cửu chiết: buffdisc(*id) <HighLight>2</> xu, bát chiết: buffdisc(*id) <HighLight>3</> xu, thất chiết: buffdisc(*id) <HighLight>4</> xu, lục chiết: buffdisc(*id) <HighLight>5</> xu, ngũ chiết: buffdisc(*id)",
      [286149511756544] = "Sau khi trang bị kỹ năng: mỗi <HighLight>5</> giây nhận 1 tầng Nợ, tối đa <HighLight>4</> tầng. Khi dùng kỹ năng: Lão Neil tiêu hao toàn bộ Nợ để gây <HighLight>3</> lần sát thương lên mục tiêu; tiêu hao càng nhiều Nợ, sát thương càng cao. Lần 1: skilldisc(*id), lần 2: skilldisc(*id), lần 3: skilldisc(*id). Tối đa 6 mục tiêu; sát thương lên quái vật tăng 100%.",
      [286149511756800] = "Gây *d sát thương phạm vi.",
      [286149511759872] = "Sau khi trang bị kỹ năng: mỗi <HighLight>5</> giây nhận 1 tầng Nợ, tối đa <HighLight>4</> tầng. Khi dùng kỹ năng: Lão Neil tiêu hao toàn bộ Nợ để gây <HighLight>3</> lần sát thương lên mục tiêu; tiêu hao càng nhiều Nợ, sát thương càng cao. Lần 1: skilldisc(*id), lần 2: skilldisc(*id), lần 3: skilldisc(*id).",
      [286149511760128] = "Melissa triệu hồi một thiết bị bánh răng trên đầu, quét một tia lửa về phía trước, skilldisc(*id); nếu mục tiêu có Khiên, trước tiên gây *d điểm sát thương lên Khiên.",
      [286149511760384] = "Gây *d sát thương lên mục tiêu địch trên đường đi.",
      [286149511760640] = "Melissa triệu hồi 2 thiết bị bánh răng bên cạnh, quét một tia lửa về phía trước, skilldisc(*id); nếu mục tiêu có Khiên, trước tiên gây *d điểm sát thương lên Khiên.",
      [286149511761920] = "Azik triệu hồi Móng Vuốt Tử Vong của Sứ Giả Bạch Cốt tấn công mục tiêu, gây *d điểm sát thương. Móng Vuốt Tử Vong gắn hiệu ứng <HighLight>Tử Vong Xâm Thực</> trong 4 giây, mỗi giây gây một lượng sát thương.",
      [286149511762432] = "Azik gây một lượng nhỏ sát thương lên mục tiêu; nếu mục tiêu đang có Tử Vong Xâm Thực, chuyển thành gây lượng lớn sát thương.",
      [286149511763968] = "Roselle dựng <HighLight>Đế Quốc Kỳ Xí</> tại vị trí mục tiêu. <HighLight>Cờ Xí</> kế thừa 250% HP; trong thời gian <HighLight>Đế Quốc Kỳ Xí</> tồn tại, ban bố <HighLight>Luật Lệnh</> trong bán kính 12m quanh <HighLight>Cờ Xí</>: thể lực tiêu hao mỗi lần Né của kẻ địch tăng gấp đôi, Tốc Độ Di Chuyển giảm 15%. <HighLight>Cờ Xí</> tồn tại 12 giây; hiệu ứng từ nhiều <HighLight>Cờ Xí</> cùng phe không cộng dồn. Hiệu ứng liên quan đến tiêu hao thể lực của kỹ năng này không bị ảnh hưởng bởi các hiệu ứng tốc độ tiêu hao thể lực khác.",
      [286149511764480] = "Trong thời gian <HighLight>Cờ Xí</> tồn tại, có thể tăng thời gian tồn tại của <HighLight>Cờ Xí</> thêm 5 giây, đồng thời Hồi Chiêu tăng 15 giây.",
      [286149511764992] = "Dẫn dắt nghi thức và bố trí Nghi Thức Chuyển Vận xung quanh bản thân; cần đi ngược 4 bước theo thứ tự 4→3→2→1 và hoàn thành trong 20 giây. Sau khi hoàn thành, Nghi Thức Chuyển Vận nhận kỹ năng lần hai — Sương Xám Gia Trì; chỉ khi kích hoạt lần hai mới phát động hiệu ứng nghi thức. Bản thân nhận Sương Xám Gia Trì trong 10 giây, Tăng Thương 20%. Nếu không hoàn thành trong thời gian quy định, hoàn lại 10 giây Hồi Chiêu.",
      [286149511766528] = "Nhận Sương Xám Gia Trì, buffdisc(*id), kéo dài *d giây.",
      [286149511766784] = "Dùng vị cách chí cao của Sương Xám áp chế mục tiêu — với 100% xác suất cơ bản khiến mục tiêu Câm Lặng trong *d giây. Khi ảnh hưởng kết thúc, mục tiêu chịu *d điểm sát thương; nếu trong thời gian đó mục tiêu Xóa Khống Chế, chịu *d điểm sát thương. (Trong lúc áp chế, bản thân đồng thời nhận Sương Xám Gia Trì.)",
      [286150048613888] = "Dẫn dắt Ma Pháp Đồng Thoại, khiến mục tiêu chìm sâu trong Ảo Cảnh Vương Quốc, liên tục chịu sát thương và rơi vào trạng thái Cứng Đờ.",
      [286150048614656] = "Dịch chuyển tức thời đến trước mục tiêu, Choáng kẻ địch xung quanh và tung nhiều nhát chém; trong thời gian đó bản thân nhận Giảm Thương.",
      [286150048615168] = "Nhanh chóng tung 2 đòn tấn công; nếu chỉ trúng một mục tiêu, sát thương tăng.",
      [286150048615680] = "Cưỡi sóng, nhận Bá Thể và Tăng Tốc; có thể điều chỉnh hướng xung phong bằng phím di chuyển. Khi xung phong kết thúc hoặc chủ động dùng lần hai, tấn công kẻ địch xung quanh. Trang bị kỹ năng sẽ tăng tốc độ lướt ván trên mặt nước và bơi.",
      [286150048616704] = "Leonard ngâm Thi Phẩm An Hồn, khiến kẻ địch chịu Trọng Thương và bản thân nhận một hào quang; hào quang làm giảm Tốc Độ Di Chuyển của mục tiêu địch xung quanh.",
      [286150048617216] = "Nếu bản thân và đồng đội có hiệu ứng Hợp Tấu cùng gây sát thương lên một mục tiêu, gây thêm sát thương.",
      [286150048617728] = "Triển khai Lĩnh Vực Thánh Quang, xóa hiệu ứng khống chế trên bản thân và nhận Bá Thể, Giảm Thương cùng Khiên. Sau một khoảng thời gian hoặc khi kích hoạt lại, bùng nổ năng lượng tấn công và Đẩy Lùi kẻ địch xung quanh.",
      [286150048618496] = "Dòm ngó bí mật của vận mệnh, trong một khoảng thời gian tăng sát thương của bản thân và đồng minh xung quanh.",
      [286150048618752] = "Daly tiến hành Nghi Thức Thông Linh, hồi HP cho đồng minh gần đó và gây sát thương lên kẻ địch.",
      [286150048619264] = "Dunn rót sức mạnh Mộng Yểm vào mặt đất, ngưng tụ thành Mộng Yểm gây sát thương lên mục tiêu địch và để lại Ấn Ký Mộng Yểm; khi dấu ấn kết thúc sẽ gây thêm sát thương.",
      [286150048620544] = "Frye gây sát thương lên mục tiêu địch và gắn <FaintYellow>Ấn Ký Tử Linh</>, khiến mục tiêu chịu thêm sát thương bằng một tỷ lệ Tấn Công của người thi triển mỗi khi bị người thi triển tấn công.",
      [286150048621312] = "Audrey trị liệu đồng minh mục tiêu và gắn hiệu ứng <FaintYellow>Thẩm Thị</>; trong một khoảng thời gian ghi lại sát thương nhận vào, khi hết thời gian sẽ hồi HP theo một tỷ lệ nhất định.",
      [286150048621568] = "Audrey gắn hiệu ứng <FaintYellow>Thẩm Thị</> lên đồng minh mục tiêu; trong một khoảng thời gian ghi lại sát thương nhận vào, khi hết thời gian sẽ hồi HP theo một tỷ lệ nhất định.",
      [286150048622080] = "Fors triệu hồi một tia sét đánh mục tiêu địch, gây một lượng sát thương; nếu mục tiêu là quái vật, sát thương tăng 75%.",
      [286150048623104] = "Audrey ném 3 chiếc bánh thú cưng Backlund Susie yêu thích để hồi HP cho đồng minh; chạm vào bánh cũng có thể hồi HP cho đồng minh.",
      [286150048624384] = "Frank triệu hồi một cây nấm đặc chế tại vị trí mục tiêu địch; nấm phát nổ gây sát thương trong một phạm vi nhất định.",
      [286150048624896] = "Lovia gia trì Bóng Tối Huyết Nhục cho người thi triển, liên tục gây sát thương lên kẻ địch.",
      [286150048625408] = "Benson mặc cả, ngẫu nhiên tung <FaintYellow>1-5</> đồng xu; số xu quyết định mức chiết khấu, và mức chiết khấu quyết định hiệu ứng tăng cường nhận được.",
      [286150048625664] = "Benson mặc cả, ngẫu nhiên tung 1-5 đồng xu; số xu quyết định mức chiết khấu, và mức chiết khấu quyết định hiệu ứng tăng cường nhận được.",
      [286150048627456] = "Sau khi trang bị kỹ năng: mỗi <FaintYellow>5</> giây nhận 1 tầng Nợ, tối đa <FaintYellow>4</> tầng. Khi dùng kỹ năng: Lão Neil tiêu hao toàn bộ Nợ để gây sát thương lên mục tiêu; tiêu hao càng nhiều Nợ, sát thương càng cao. Sát thương lên quái vật tăng 100%.",
      [286150048630784] = "Sau khi trang bị kỹ năng: mỗi <FaintYellow>5</> giây nhận 1 tầng Nợ, tối đa <FaintYellow>4</> tầng. Khi dùng kỹ năng: Lão Neil tiêu hao toàn bộ Nợ để gây sát thương lên mục tiêu; tiêu hao càng nhiều Nợ, sát thương càng cao.",
      [286150048631040] = "Melissa triệu hồi một thiết bị bánh răng trên đầu, quét một tia lửa về phía trước, gây sát thương lên mục tiêu địch trên đường đi; nếu mục tiêu có Khiên, gây hiệu ứng Phá Khiên.",
      [286150048631552] = "Melissa triệu hồi 2 thiết bị bánh răng bên cạnh, quét một tia lửa về phía trước, gây sát thương lên mục tiêu địch trên đường đi; nếu mục tiêu có Khiên, gây hiệu ứng Phá Khiên.",
      [286150048632832] = "Azik triệu hồi Móng Vuốt Tử Vong của Sứ Giả Bạch Cốt tấn công mục tiêu và gây sát thương. Móng Vuốt Tử Vong gắn hiệu ứng Tử Vong Xâm Thực, mỗi giây gây một lượng sát thương.",
      [286150048634880] = "Roselle dựng <HighLight>Đế Quốc Kỳ Xí</> tại vị trí mục tiêu. <HighLight>Cờ Xí</> có HP và có thể bị tấn công; trong thời gian <HighLight>Đế Quốc Kỳ Xí</> tồn tại, ban bố <HighLight>Luật Lệnh</>: thể lực tiêu hao mỗi lần Né của kẻ địch tăng gấp đôi, Tốc Độ Di Chuyển giảm. Hiệu ứng từ nhiều <HighLight>Cờ Xí</> cùng phe không cộng dồn. Hiệu ứng liên quan đến tiêu hao thể lực của kỹ năng này không bị ảnh hưởng bởi các hiệu ứng tốc độ tiêu hao thể lực khác.",
      [286150048635392] = "Trong thời gian Cờ Xí tồn tại, có thể tăng thời gian tồn tại của Cờ Xí, đồng thời tăng Hồi Chiêu của kỹ năng này.",
      [286150048635904] = "Dẫn dắt nghi thức và bố trí Nghi Thức Chuyển Vận xung quanh bản thân; cần đi ngược 4 bước theo thứ tự 4→3→2→1 và hoàn thành trong 20 giây. Sau khi hoàn thành, Nghi Thức Chuyển Vận nhận kỹ năng lần hai — Sương Xám Gia Trì; chỉ khi kích hoạt lần hai mới phát động hiệu ứng nghi thức và bản thân nhận Sương Xám Gia Trì. Nếu không hoàn thành trong thời gian quy định, hoàn lại một phần Hồi Chiêu.",
      [286150048637440] = "Bản thân nhận Sương Xám Gia Trì, tăng hiệu quả Tăng Thương.",
      [286150048637696] = "Dùng vị cách chí cao của Sương Xám áp chế mục tiêu; khi ảnh hưởng kết thúc, mục tiêu chịu một lượng sát thương. Nếu mục tiêu Xóa Khống Chế trong thời gian đó, sẽ chịu lượng lớn sát thương. (Trong lúc áp chế, bản thân đồng thời nhận Sương Xám Gia Trì.)",
      [611398258279936] = "Minh Đăng Lịch Sử",
    },
    ["skill3"] = {
      [286217962784256] = "Khuyển Hồn Dược Kích",
      [286217962784512] = "Cắn Xé Răng Cưa",
      [286217962785024] = "Dị Khuyển Xung Phong",
      [286217962786048] = "Ghi Chép·Dòm Bí",
      [286217962786560] = "Ghi Chép·Cuồng Phong",
      [286217962787840] = "Khỉ Đầu Chó Trợ Trận",
      [286217962791168] = "Thụ Linh Hoàng Kim",
      [286217962794240] = "Cá Nóc Bùm Bùm",
      [286217962795264] = "Loạn Lưu Vận Mệnh",
      [286217962795776] = "Hắc Sắc Loạn Lưu",
      [286217962796032] = "Bạch Sắc Loạn Lưu",
      [286217962796288] = "Tổ Tiên Bảo Hộ",
      [286217962797824] = "Ẩn Hình Thứ Kích",
      [286217962798848] = "Huyễn Hóa Hành Tung",
      [286217962799360] = "Ghi Chép·Mưa Bài",
      [286217962799872] = "Ghi Chép·Trừng Phạt",
      [286217962800384] = "Ghi Chép·Mộng Cảnh",
      [286217962801152] = "Ma Đạn Truy Dấu",
      [286217962802688] = "Ghi Chép·Trục Xuất",
      [286217962805504] = "Chưa Phát Hành-Hồi Toàn Trảm Kích",
      [286217962806016] = "Chưa Phát Hành-Tinh Ngân",
      [286217962808064] = "Thánh Quang Rủ Lòng",
      [286217962808576] = "Thi Hành Trọng Tài",
      [286217962809344] = "Hồi Toàn Lãng Giáp",
      [286217962810368] = "Barney Húc Đầu",
      [286217962811136] = "Màn Hề Hạ Màn",
      [286217962811904] = "Bình Minh Giáng Lâm",
      [286217962812416] = "Lạc Ấn Trọng Tài",
      [286217962813184] = "Khuy Bí Ngưng Thị",
      [286217962813696] = "Thủ Hộ Thần Hi",
      [286217962814208] = "Thệ Ước Kỵ Sĩ",
      [286217962814720] = "Điệp Linh Phụ Thân",
      [286217962815232] = "Bóng Hình Giáng Lâm",
      [286217962816000] = "Hồi Âm Chuông Tang",
      [286217962816512] = "Liên Trảo Sói Đầu Đàn",
      [286217962817024] = "Mũi Khoan Thủ Hộ",
      [286218231219712] = "Triệu hồi Dị Hóa Liệp Khuyển, lấy mục tiêu đã khóa làm điểm chuẩn để lao bổ, gây *d điểm sát thương và Hất Tung.",
      [286218231219968] = "Lập tức ngưng tụ ba bóng chó đỏ thẫm trong vùng hình quạt phía trước; cả ba cùng cắn một lần, gây *d điểm sát thương.",
      [286218231220480] = "Lập tức hóa thân thành Liệp Khuyển, xung phong 20 mét về phía trước; trong thời gian này gây *d điểm sát thương lên kẻ địch trên đường đi.",
      [286218231221504] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Con Mắt Dòm Bí, loại bỏ spellfielddisc(*id) điểm Hộ Thuẫn của kẻ địch quanh Bí Ngẫu và gây spellfielddisc(*id) điểm sát thương.",
      [286218231222016] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Cuồng Phong, liên tục tấn công kẻ địch trong phạm vi 4.5 mét quanh Bí Ngẫu. Mỗi <Highlight>0.4</> giây gây *d điểm sát thương và giảm <Highlight>25%</> Tốc Độ Di Chuyển trong 1.2 giây; kéo dài <Highlight>5</> giây.",
      [286218231223296] = "Triệu hồi một con khỉ đầu chó trước mặt bản thân trong 21 giây. Khi được triệu hồi và sau đó cứ mỗi <Highlight>6</> giây, khỉ đầu chó sẽ ban một buff ngẫu nhiên cho đồng đội trong phạm vi 30 mét.\nBuff ngẫu nhiên: buffdisc(*id), kéo dài <Highlight>6</> giây; buffdisc(*id), kéo dài <Highlight>6</> giây; buffdisc(*id), kéo dài <Highlight>6</> giây;\nKỹ năng này có hồi chiêu tổ đội <Highlight>30</> giây.",
      [286218231226624] = "Triệu hồi linh thể Sylvia nhập vào bản thân trong 30 giây. Trong thời gian nhập thân, buffdisc(*id) gây bulletdisc(*id) sát thương; mỗi giây có thể kích hoạt 1 lần, tối đa 7 lần.",
      [286218231227648] = "Khi Uy Năng Hoàng Kim tích đủ 5 tầng, có thể gây bulletdisc(*id) sát thương lên một mục tiêu.",
      [286218231228416] = "Khi Uy Năng Hoàng Kim tích đủ 5 tầng, có thể gây bulletdisc(*id) sát thương lên một mục tiêu và tạo vụ nổ, gây spellfielddisc(*id) điểm sát thương lên kẻ địch trong phạm vi 10 mét quanh mục tiêu.",
      [286218231228928] = "Triệu hồi Phu Nhân Tử Tước tấn công mục tiêu.\nNếu mục tiêu là người chơi: Phu Nhân Tử Tước gây bulletdisc(*id) sát thương và gắn U Hồn Phụ Thân trong 10 giây; khi bị phụ thân, sát thương bản thân gây lên mục tiêu tăng 6%. Nếu mục tiêu chết trong 10 giây, u hồn sẽ tìm ngẫu nhiên thêm 1 người chơi địch trong phạm vi 15 mét, gây bulletdisc(*id) sát thương rồi phụ thân; tối đa phụ thân thêm 1 lần.\nNếu mục tiêu là quái: u hồn gây bulletdisc(*id) sát thương 2 lần và phụ thân trong 15 giây; khi bị phụ thân, sát thương bản thân gây lên quái đó tăng 6%.",
      [286218231229696] = "Biến thành cá nóc; sau một khoảng trễ ngắn sẽ phát nổ và bắn <Highlight>4</> viên đạn ra xung quanh, mỗi viên gây *d điểm sát thương. Toàn bộ quá trình biến hình có <Highlight>Bá Thể</>.",
      [286218231230720] = "Triệu hồi tàn ảnh Ouroboros, phóng Hắc Sắc Loạn Lưu về phía trước 15 mét. Trong 6 giây sau đó có thể chủ động tung đoạn hai Bạch Sắc Loạn Lưu, hiệu ứng như sau.\nHắc Sắc Loạn Lưu: chỉ tác dụng lên kẻ địch; vừa Đẩy Lùi vừa gắn hiệu ứng Vận Mệnh Đen trong 8 giây, mỗi giây gây sát thương nhất định. Nếu kẻ địch chết trong thời gian này, tại chỗ sẽ phát nổ một lần, gây thêm sát thương phạm vi.\nBạch Sắc Loạn Lưu: chỉ tác dụng lên phe mình; lập tức hồi một lượng Máu nhất định và trong 8 giây tiếp theo tăng Tốc Độ Di Chuyển cùng hiệu quả Giảm Thương.",
      [286218231231744] = "Triệu hồi Giáp Tổ Tiên, tạo dưới chân bản thân một pháp trận bán kính 30 mét, kéo dài <Highlight>10</> giây, khiến đồng đội cùng tổ đội trong phạm vi buffdisc(*id).\nTổ Tiên Bảo Hộ: cứ mỗi 3 lần bản thân chủ động hồi phục cho đồng đội, tạo Tổ Tiên Bảo Hộ dưới chân bản thân, bán kính 5 mét, kéo dài 2.5 giây; tối đa kích hoạt 1 lần mỗi 4 giây, khiến đồng đội trong phạm vi buffdisc(*id).\nPháp trận và Tổ Tiên Bảo Hộ không thể đồng thời tồn tại; cùng lúc chỉ có tối đa một Tổ Tiên Bảo Hộ.\nKỹ năng này có hồi chiêu tổ đội <Highlight>30</> giây.",
      [286218231233280] = "Khi thi triển, bản thân vào trạng thái Ẩn Thân trong <Highlight>3</> giây, đồng thời triệu hồi 3 ảo ảnh Selina trong vùng vành khuyên bán kính 3.5 mét quanh bản thân để kích nổ Mặt Gương. Mỗi ảo ảnh gây *d điểm sát thương lên kẻ địch trong phạm vi 3.5 mét quanh nó; mỗi lần chịu thêm một đòn Thứ Kích trùng lặp, sát thương giảm 50%.",
      [286218231234304] = "Ngẫu nhiên huyễn hóa ngụy trang thành một vật thể trong cảnh trong 10 giây. Trong thời gian này không thể di chuyển hoặc dùng kỹ năng và không chịu bất kỳ sát thương nào; có thể dùng lại kỹ năng để hủy biến hình.",
      [286218231234816] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Mưa Bài, gây spellfielddisc(*id) điểm sát thương lên kẻ địch trong phạm vi 4.5 mét quanh mục tiêu, đồng thời có xác suất cơ bản *f** <HyperLink stylename=\"M_Link\" u=\"6\">Choáng</> kẻ địch ở tâm vùng trong 0.8 giây; tối đa <HighLight>Choáng</> 2 mục tiêu.",
      [286218231235328] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Trừng Phạt, gây *d điểm sát thương lên kẻ địch trong phạm vi 4 mét quanh Bí Ngẫu.",
      [286218231235840] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Mộng Giải, tạo lĩnh vực bán kính 6 mét; liên tục hồi phục đồng đội trong lĩnh vực, mỗi giây hồi *d Máu, kéo dài <HighLight>6</> giây.",
      [286218231236608] = "Triệu hồi Không Tưởng Tiểu Quái gần một mục tiêu địch trong phạm vi 15 mét. Sau khi bay lên, Không Tưởng Tiểu Quái liên tục bắn <HighLight>4</> viên đạn truy đuổi mục tiêu, mỗi viên gây bulletdisc(*id) sát thương.",
      [286218231238144] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Trục Xuất, gây <HighLight>5</> lần *d điểm sát thương lên kẻ địch trong phạm vi 5 mét quanh mục tiêu, sau đó <HighLight>đòn kết liễu</> gây *d điểm sát thương. Khi tấn công quái, bổ sung hiệu ứng <HyperLink stylename=\"M_Link\" u=\"2\" color=\"#f4a067\">Kéo</> về tâm.",
      [286218231238912] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành, ngẫu nhiên phun Hỏa Diễm Thổ Tức hoặc Băng Sương Thổ Tức vào vùng thẳng phía trước.\nHỏa Diễm Thổ Tức: gây *d điểm sát thương lên kẻ địch trên đường đi và gắn <HighLight>68%</> <HyperLink stylename=\"M_Link\" u=\"10\">Trọng Thương</> trong *d giây lên người chơi địch.\nBăng Sương Thổ Tức: gây *d điểm sát thương lên kẻ địch trên đường đi và có 70% xác suất khiến kẻ địch buffdisc(*id), kéo dài *f giây.",
      [286218231239936] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Tinh Vân Trảm Kích, gây *d điểm sát thương lên kẻ địch trong phạm vi 4 mét quanh mục tiêu.",
      [286218231240960] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Hồi Toàn Trảm Kích, gây sát thương lên kẻ địch trên đường đi và <HighLight>Đẩy Lùi</>.",
      [286218231241472] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển kỹ năng Tinh Ngân, mở Tinh Môn tấn công kẻ địch trong phạm vi phía trước bản thân. Khi thi triển, nếu bản thân chưa có <HighLight>Năng Lượng Bí Pháp</> thì nhận <HighLight>Năng Lượng Bí Pháp</> trong 70 giây. Nếu đã có <HighLight>Năng Lượng Bí Pháp</>, sẽ mở thêm một Tinh Môn và làm mới thời lượng <HighLight>Năng Lượng Bí Pháp</>.",
      [286218231241984] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Liệt Dương Tụng Ca, gây *d điểm sát thương lên kẻ địch trong phạm vi 12 mét quanh bản thân.",
      [286218231242752] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Nhật Miện Tài Quyết: vung kiếm khí gây *d điểm sát thương lên kẻ địch phía trước, sau đó đẩy kiếm khí về phía trước, gây *d điểm sát thương lên kẻ địch trên đường đi.",
      [286218231243520] = "Triệu hồi Tín Đồ Số 1 · Anxia, giải trừ trạng thái Khống Chế cho mục tiêu và hồi *d Máu. Có thể dùng ngay cả khi bản thân đang bị Khống Chế.",
      [286218231244032] = "Triệu hồi Nhà Chiêm Tinh tại vị trí mục tiêu, đá ngang gây *d sát thương, loại bỏ *d Hộ Thuẫn của mục tiêu và gây Cứng Đờ. Sau đó đá thẳng gây *d sát thương; nếu Máu mục tiêu dưới 20%, cú đá thẳng gây *d sát thương.",
      [286218231244800] = "Triệu hồi Cự Quy tại vùng mục tiêu; nó xoay tại chỗ và bắn nước ra xung quanh, gây 3 lần *d điểm sát thương, sau đó giậm đất gây *d điểm sát thương. Kẻ địch trúng nước liên tục bị gắn Suy Yếu và Trì Trệ.",
      [286218231245824] = "Triệu hồi thỏ bông phía trước để dùng đầu giậm đất, gây *d sát thương lên kẻ địch trong vùng hình quạt phía trước và có 50% xác suất cơ bản Đánh Ngã. Đồng thời tạo dư chấn, gây *d sát thương lên kẻ địch xung quanh.",
      [286218231246592] = "Triệu hồi Chú Hề tại vị trí mục tiêu. Màn ra mắt của Chú Hề liên tục kích nổ bom ruy-băng quanh mình trong 3 giây; mỗi 0.5 giây gây spellfielddisc(*id) sát thương lên mục tiêu trong phạm vi, đồng thời hồi lượng Máu bằng 50% sát thương gây ra (mỗi lần hồi không vượt quá 2% Máu tối đa của bản thân).",
      [286218231247360] = "Triệu hồi Kỵ Sĩ Trọng Phủ tại vị trí mục tiêu để bổ xuống, gây spellfielddisc(*id) sát thương lên kẻ địch trong phạm vi và có 70% xác suất gây <Highlight>Choáng</> lên kẻ địch ở vùng trung tâm.",
      [286218231247872] = "Triệu hồi Eudora tại vị trí mục tiêu. Eudora triệu hồi pháp trận; sau một khoảng ngắn, pháp trận bùng nổ gây *d sát thương lên mục tiêu 2 lần, sau đó bản thân nhận 6% Tăng Sát Thương khi đánh mục tiêu và mục tiêu nhận 6% Giảm Sát Thương, kéo dài 6 giây.",
      [286218231248640] = "Triệu hồi Con Mắt Dòm Bí tại vị trí mục tiêu để liên kết mục tiêu; mỗi 0.5 giây gây *d sát thương và giảm 25% Tốc Độ Di Chuyển. Liên kết kéo dài tối đa 4 giây; nếu mục tiêu cách Con Mắt Dòm Bí quá xa, liên kết sẽ ngắt sớm.",
      [286218231249152] = "Triệu hồi Kỵ Sĩ Thiết Bích, khiến đồng đội xung quanh buffdisc(*id), kéo dài 8 giây.",
      [286218231249664] = "Triệu hồi Kỵ Sĩ Ma Pháp ban phúc cho bản thân, buffdisc(*id), kéo dài 10 giây.",
      [286218231250176] = "Triệu hồi Không Tưởng Hồ Điệp nhập vào mục tiêu, buffdisc(*id), kéo dài 6 giây.",
      [286218231250688] = "Triệu hồi Bóng Hình Megose tại vị trí mục tiêu để tấn công kép về phía trước. Đòn thứ nhất gây *d sát thương và <Highlight>Trì Trệ</>; đòn thứ hai gây *d sát thương và <Highlight>Trọng Thương</>. Kẻ địch trúng đòn thứ nhất sẽ chịu thêm 50% sát thương từ đòn thứ hai; đòn thứ hai đồng thời tăng sát thương cho đơn vị phe mình xung quanh trong một khoảng thời gian.",
      [286218231251456] = "Triệu hồi Kẻ Lột Mặt, bắn đạn nảy vào kẻ địch trong phạm vi. Đạn nảy giữa đơn vị phe mình và phe địch ở gần; khi trúng địch gây bulletdisc(*id) sát thương, khi trúng đồng đội khiến họ buffdisc(*id).",
      [286218231251968] = "Triệu hồi \"Sói Đầu Đàn\" Ruper tung liên tiếp 3 đòn Trảo Kích, mỗi đòn gây *d điểm sát thương và có 50% xác suất khiến mục tiêu Cứng Đờ trong 0.3 giây. Trong 8 giây sau khi triệu hồi, khiến bản thân buffdisc(*id).",
      [286218231252480] = "Triệu hồi mũi khoan bảo vệ bản thân; trong thời gian này nhận Bá Thể và buffdisc(*id). Khi bị tấn công, khiến kẻ tấn công giảm 20% Tốc Độ Di Chuyển trong 1 giây; hiệu ứng kéo dài <Highlight>4</> giây.",
      [286218768090624] = "Triệu hồi Dị Hóa Liệp Khuyển, lao bổ vào mục tiêu gần đó, gây sát thương lớn và Hất Tung.",
      [286218768090880] = "Lập tức ngưng tụ ba bóng chó đỏ thẫm phía trước; cả ba cùng cắn một lần, gây lượng lớn sát thương.",
      [286218768091392] = "Lập tức hóa thân thành Liệp Khuyển và xung phong xa về phía trước; gây sát thương lên kẻ địch trên đường đi.",
      [286218768092416] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Con Mắt Dòm Bí, loại bỏ một phần Hộ Thuẫn của kẻ địch xung quanh Bí Ngẫu và gây sát thương.",
      [286218768092928] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Cuồng Phong, liên tục tấn công kẻ địch quanh Bí Ngẫu, gây sát thương và Giảm Tốc.",
      [286218768094208] = "Triệu hồi một con khỉ đầu chó trước mặt bản thân; sau mỗi khoảng thời gian, nó ban một buff ngẫu nhiên cho toàn bộ thành viên tổ đội.\nBuff ngẫu nhiên: tăng Công Kích, tăng Cường Hóa Kỹ Năng, tăng Chuyên Công Quái.",
      [286218768097536] = "Triệu hồi một linh thể nhập vào bản thân; khi người chơi dùng kỹ năng, linh thể gây sát thương lên mục tiêu.",
      [286218768098560] = "Tích đầy Uy Năng Hoàng Kim để gây sát thương lên một mục tiêu.",
      [286218768099328] = "Tích đầy Uy Năng Hoàng Kim để gây sát thương lên một mục tiêu và tạo vụ nổ, gây sát thương lên kẻ địch xung quanh.",
      [286218768099840] = "Triệu hồi Phu Nhân Tử Tước tấn công mục tiêu.\nNếu mục tiêu là người chơi: gây một lần sát thương và gắn U Hồn Phụ Thân, trong thời gian đó bản thân nhận Tăng Sát Thương khi đánh mục tiêu. Nếu mục tiêu chết trong một khoảng thời gian, u hồn sẽ tìm một người chơi địch khác ở gần để phụ thân.\nNếu mục tiêu là quái: u hồn gây thêm sát thương và phụ thân, trong thời gian đó tăng sát thương bản thân gây lên quái đó.",
      [286218768100608] = "Biến thành cá nóc; sau một khoảng trễ ngắn sẽ phát nổ và bắn nhiều viên đạn ra xung quanh. Toàn bộ quá trình biến hình có Bá Thể.",
      [286218768101632] = "Triệu hồi tàn ảnh Ouroboros, phóng Hắc Sắc Loạn Lưu về phía trước; trong 6 giây sau đó có thể chủ động tung đoạn hai Bạch Sắc Loạn Lưu.\nHắc Sắc Loạn Lưu: chỉ tác dụng lên kẻ địch; Đẩy Lùi và gây sát thương duy trì. Nếu kẻ địch chết trong thời gian này, tại chỗ sẽ phát nổ gây sát thương.\nBạch Sắc Loạn Lưu: chỉ tác dụng lên phe mình; lập tức hồi một lượng Máu nhất định và trong 8 giây tiếp theo tăng Tốc Độ Di Chuyển cùng hiệu quả Giảm Thương.",
      [286218768102656] = "Triệu hồi Giáp Tổ Tiên, tạo pháp trận cho bản thân; đồng đội trong phạm vi được cường hóa.",
      [286218768104192] = "Vào trạng thái Ẩn Thân, đồng thời triệu hồi ảo ảnh Selina theo vòng quanh bản thân để kích nổ Mặt Gương, gây lượng lớn sát thương.",
      [286218768105728] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để tung Mưa Bài, gây sát thương lên kẻ địch trong phạm vi mục tiêu, đồng thời Choáng kẻ địch ở tâm phạm vi.",
      [286218768106240] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Trừng Phạt, gây sát thương lên kẻ địch quanh Bí Ngẫu.",
      [286218768106752] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Mộng Giải, tạo một lĩnh vực mộng cảnh yên bình, liên tục hồi Máu cho đồng đội trong lĩnh vực.",
      [286218768107520] = "Triệu hồi Không Tưởng Tiểu Quái gần kẻ địch, sau đó bắn nhiều viên đạn truy đuổi gây sát thương lớn.",
      [286218768109056] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Trục Xuất, liên tục gây sát thương lên kẻ địch trong phạm vi mục tiêu. Khi đánh quái, bổ sung hiệu ứng gom mục tiêu.",
      [286218768109824] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành, ngẫu nhiên phun Hỏa Diễm Thổ Tức hoặc Băng Sương Thổ Tức.\nHỏa Diễm Thổ Tức: gây sát thương lên kẻ địch trên đường đi và gắn Trọng Thương.\nBăng Sương Thổ Tức: gây sát thương lên kẻ địch trên đường đi và gắn Giảm Tốc.",
      [286218768110848] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Tinh Vân Trảm Kích, gây sát thương lên kẻ địch trong phạm vi mục tiêu.",
      [286218768111872] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Hồi Toàn Trảm Kích, gây sát thương lên kẻ địch trên đường đi và Đẩy Lùi.",
      [286218768112384] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển kỹ năng Tinh Ngân, mở Tinh Môn tấn công kẻ địch trong phạm vi phía trước bản thân.",
      [286218768112896] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Liệt Dương Tụng Ca, gây sát thương phạm vi.",
      [286218768113664] = "Triệu hồi Bí Ngẫu do Trùng Tinh Tú hóa thành để thi triển Nhật Miện Tài Quyết: vung kiếm khí gây sát thương lên kẻ địch phía trước, sau đó đẩy kiếm khí về phía trước, gây sát thương lên kẻ địch trên đường đi.",
      [286218768114432] = "Triệu hồi Tín Đồ Số 1 · Anxia, giải trừ Khống Chế cho mục tiêu và hồi Máu.",
      [286218768114944] = "Triệu hồi Nhà Chiêm Tinh tại vị trí mục tiêu, tung 2 cú đá gây sát thương; nhận Tăng Sát Thương khi đánh mục tiêu thấp Máu.",
      [286218768115712] = "Triệu hồi Cự Quy tại vùng mục tiêu; nó xoay tại chỗ và bắn nước ra xung quanh, gây sát thương và khiến kẻ địch chịu hiệu ứng bất lợi.",
      [286218768116736] = "Triệu hồi thỏ bông phía trước để dùng đầu giậm đất; có xác suất Đánh Ngã kẻ địch trong vùng hình quạt phía trước, đồng thời tạo dư chấn.",
      [286218768117504] = "Triệu hồi Chú Hề tại vị trí mục tiêu, liên tục gây sát thương lên mục tiêu trong phạm vi và hồi Máu dựa trên lượng sát thương gây ra.",
      [286218768118272] = "Triệu hồi Kỵ Sĩ Trọng Phủ tại vị trí mục tiêu, gây sát thương lên kẻ địch trong phạm vi và gây Choáng lên kẻ địch ở trung tâm.",
      [286218768118784] = "Triệu hồi Eudora tại vị trí mục tiêu; sau một khoảng ngắn gây sát thương lên mục tiêu, đồng thời bản thân nhận Tăng Sát Thương khi đánh mục tiêu và mục tiêu nhận Giảm Sát Thương.",
      [286218768119552] = "Triệu hồi Con Mắt Dòm Bí tại vị trí mục tiêu, gây sát thương duy trì và Giảm Tốc mục tiêu.",
      [286218768120064] = "Triệu hồi Kỵ Sĩ Thiết Bích, thêm Hộ Thuẫn cho đồng đội xung quanh.",
      [286218768120576] = "Triệu hồi Kỵ Sĩ Ma Pháp, liên tục hồi Máu cho bản thân và nhận hiệu ứng tăng Công Kích cùng Xuyên Thấu.",
      [286218768121088] = "Triệu hồi Không Tưởng Hồ Điệp, liên tục hồi phục mục tiêu.",
      [286218768121600] = "Triệu hồi Bóng Hình Megose tại vị trí mục tiêu, tấn công hai lần về phía trước, gây Trì Trệ và Trọng Thương.",
      [286218768122368] = "Triệu hồi Kẻ Lột Mặt, bắn đạn nảy gây các hiệu ứng khác nhau lên phe mình và phe địch.",
      [286218768122880] = "Triệu hồi \"Sói Đầu Đàn\" Ruper, tấn công khiến kẻ địch Cứng Đờ và thêm buff Công Kích cho bản thân.",
      [286218768123392] = "Triệu hồi mũi khoan bảo vệ bản thân, nhận Bá Thể và Hộ Thuẫn, đồng thời khiến kẻ tấn công Giảm Tốc.",
      [998771022366208] = "U Hồn Đòi Mạng",
      [998771022396928] = "Băng Diễm Thổ Tức",
      [998771022398464] = "Liệt Dương Tụng Ca",
      [998771022400000] = "Nhật Miện Tài Quyết",
      [998771022409216] = "Tinh Vân Trảm Kích",
    },
