      [1218466115771904] = "Hiếm · Hàu Muối",
      [1218466115772160] = "Hiếm · Thịt Xông Khói Ngâm Mật",
      [1218466115772416] = "Hiếm · Giăm Bông Hoàng Gia",
      [1218466115772672] = "Hiếm · Lát Sò Tuyết",
      [1218466115773952] = "Hiếm · Áo Sơ Mi Lanh",
      [1218466115774208] = "Hiếm · Áo Gile Dạ Thô",
      [1218466115774464] = "Hiếm · Áo Khoác Dài Cài Trước",
      [1218466115774720] = "Hiếm · Lễ Phục Đuôi Tôm",
      [1218466115774976] = "Hiếm · Áo Ngủ Satin",
