      [1218466115775488] = "Hiếm · Bộ Cashmere",
      [1218466115775744] = "Hiếm · Lễ Phục Lụa",
      [1218466115777024] = "Hiếm · Tượng Thạch Cao",
      [1218466115777280] = "Hiếm · Ống Bút Phong Trắng",
      [1218466115777536] = "Hiếm · Chân Nến Đồng Chạm",
      [1218466115777792] = "Hiếm · Đĩa Sứ Khắc Hoa",
      [1218466115778048] = "Hiếm · Nhẫn Bạc Cổ",
      [1218466115778304] = "Hiếm · Gương Trang Điểm Mạ Vàng",
      [1218466115778560] = "Hiếm · Tiểu Phẩm Sơn Dầu",
      [1218466115778816] = "Hiếm · Bộ Trà Cung Đình",
      [1218466384184832] = "Niềm vui chỉ tốn vài đồng xu, món khoái khẩu của công nhân sau một ngày vất vả.",
      [1218466384185088] = "Bia vàng vị mật ong, tỏa hương mạch nha.",
      [1218466384185344] = "Rượu ngọt thanh đem lại chút men say; từng bọt khí nhảy múa trên đầu lưỡi.",
      [1218466384185600] = "Vị đắng nhẹ của ca cao hòa cùng độ béo mịn của kem; giống món tráng miệng hơn là rượu.",
      [1218466384185856] = "Gần như cảm được tuyết tùng nảy mầm trong miệng; hậu vị gỗ hơi đắng lưu trên môi lưỡi.",
      [1218466384186112] = "Trong veo như sương sớm giữa rừng bạch dương; rượu lạnh nhưng bùng lên cảm giác nóng rực như lửa.",
      [1218466384186368] = "Vang đỏ ủ hầm kinh điển, màu sâu, vị mượt và đầy đặn; càng cất lâu càng đáng thưởng thức.",
      [1218466384186624] = "Rượu vàng nhạt với bọt mịn dày, hương thơm quyến rũ. Chỉ ly pha lê của dạ tiệc cao cấp mới xứng với nó.",
      [1218466384190976] = "Đường tinh luyện ép thành viên vuông, người bạn kinh điển của trà đen Loen.",
      [1218466384191232] = "Ngô cứng từ Nam Đại Lục được ép và nướng thành lát vàng giòn, thơm ngon.",
      [1218466384191488] = "Sữa tươi lên men tạo kết cấu độc đáo và hương thơm hấp dẫn, rất được mèo lẫn chuột yêu thích.",
      [1218466384191744] = "Việt quất và dâu tây cùng khiêu vũ, xoay thành vị chua ngọt. Thử phết lên bánh mì đi!",
      [1218466384192000] = "Nhiều năm trước, một thủy thủ tên Yule nghĩ ra cách ngâm hàu bằng nước muối; công thức lưu truyền đến nay.",
      [1218466384192256] = "Mật ong đậm vị hòa với thịt heo hun khói, bạn đồng hành tuyệt hảo của bữa sáng. Bacon và trứng, chiến hữu của tôi.",
      [1218466384192512] = "Giăm bông huy chương vàng từ nhà cung ứng đặc biệt của hoàng gia; vị hun khói lắng đọng thành hương vị của thời gian.",
      [1218466384192768] = "Đá lạnh giữ trọn vị ngọt tươi của thịt sò; lát mỏng trong như băng tuyết. Cảm ơn món quà từ biển sâu.",
      [1218466384194048] = "Đường may chắc, gấu rộng; giơ tay làm việc cũng không gò bó.</>",
      [1218466384194304] = "Như cái ôm của bạn cũ, vẻ thô ráp bên ngoài ôm lấy một tâm hồn tinh tế.</>",
      [1218466384194560] = "Khi vạt áo lướt qua đèn đường, dường như có bí mật xào xạc trong từng nếp gấp.</>",
      [1218466384194816] = "Đường cắt tựa cánh én; tà sau khẽ bay, giấu một dạ tiệc chưa khai màn.</>",
      [1218466384195072] = "Người bạn lý tưởng của giấc mơ, khiến giấc ngủ cũng mang vẻ hoa lệ.</>",
      [1218466384195328] = "Như sonnet dệt bằng ánh trăng; mỗi lần xoay người lại viết tiếp bản nhạc hoa mỹ còn dang dở. </>",
      [1218466384195584] = "Cashmere cao cấp mềm như mây, diễn giải sự xa hoa kín đáo của đời sống quý tộc.</>",
      [1218466384195840] = "Lụa ánh ngọc trai; mặc nó vào, bạn nhất định là viên ngọc sáng nhất dạ tiệc.</>",
      [1218466384197120] = "Ép từ bột đá thô luyện rồi chạm khắc tinh xảo, tạo đường nét đẹp mắt và dùng được trong nhiều hoàn cảnh.",
      [1218466384197376] = "Ghép và đánh bóng từ gỗ phong trắng, kiểu dáng mộc mạc, hợp để sắp xếp bàn làm việc.",
      [1218466384197632] = "Đúc bằng đồng thau, chạm hoa văn giản dị mà thanh nhã; dùng chiếu sáng hoặc trang trí hằng ngày.",
      [1218466384197888] = "Đĩa sứ trắng viền hoa nhỏ, xúc cảm ấm mịn; lựa chọn lịch sự để gia đình bình thường đãi khách.",
      [1218466384198144] = "Trang sức bạc nguyên chất chất lượng cao, phong cách cổ điển, thể hiện gu kín đáo nhưng tinh tế.",
      [1218466384198400] = "Gương trang điểm treo tường chạm trổ tinh xảo; mặt gương rõ nét, đủ soi từng chi tiết trang điểm.",
      [1218466384198656] = "Tiểu phẩm sơn dầu của danh họa; mỗi nét cọ đều kể một câu chuyện.",
      [1218466384198912] = "Bộ trà ánh bạc chạm huy hiệu hoa lệ, khiến giờ trà chiều càng thêm tao nhã.",
